@visibleForTesting
bool shouldMidiClipLabelFollowInstrument({
  required String label,
  required String instrumentName,
}) {
  final normalizedLabel = label.trim();
  return normalizedLabel.isEmpty || normalizedLabel == instrumentName.trim();
}

