class _DecodedStereoPcm {
  const _DecodedStereoPcm({
    required this.sampleRate,
    required this.left,
    required this.right,
  });

  final int sampleRate;
  final Float32List left;
  final Float32List right;

  int get frameCount => math.min(left.length, right.length);
}

