class _ResolvedMixEffectParameter {
  const _ResolvedMixEffectParameter({
    required this.effectIndex,
    required this.effectId,
    required this.effectName,
    required this.parameter,
    this.effectInstanceId,
    this.effectOccurrence = 0,
  });

  final int effectIndex;
  final String effectId;
  final String effectName;
  final String? effectInstanceId;
  final int effectOccurrence;
  final Map<String, dynamic> parameter;
}

class _AssistantActionApplyException implements Exception {
  const _AssistantActionApplyException({
    required this.actionType,
    required this.cause,
    required this.stackTrace,
  });

  final String actionType;
  final Object cause;
  final StackTrace stackTrace;

  @override
  String toString() => 'Assistant action failed ($actionType): $cause';
}

class _ChatFlowCancelledException implements Exception {
  const _ChatFlowCancelledException();
}

List<Map<String, dynamic>> _cloneInstrumentCatalog(
  Iterable<Map<String, dynamic>> catalog,
) {
  return catalog.map(normalizeInstrumentPickerSpec).toList(growable: true);
}

List<Map<String, dynamic>> _mergeInstrumentCatalogs(
  Iterable<Iterable<Map<String, dynamic>>> catalogs,
) {
  final merged = <Map<String, dynamic>>[];
  final seen = <String>{};

  for (final catalog in catalogs) {
    for (final spec in catalog) {
      final next = normalizeInstrumentPickerSpec(spec);
      final id = (next['id'] as String? ?? '').trim().toLowerCase();
      final key = id.isNotEmpty
          ? id
          : '${(next['name'] as String? ?? '').trim().toLowerCase()}|'
                '${(next['sfzAssetPath'] as String? ?? '').trim().toLowerCase()}';
      if (!seen.add(key)) continue;
      merged.add(next);
    }
  }

  return merged;
}

enum _FallbackInstrumentFamily {
  basic,
  bass,
  pad,
  lead,
  pluck,
  keys,
  brass,
  wavetable,
  harmonic,
  drum,
}

class _FallbackInstrumentPreset {
  final _FallbackInstrumentFamily family;
  final int oscillator;
  final double cutoffHz;
  final double attackMs;
  final double decayMs;
  final double sustainLevel;
  final double releaseMs;
  final double drive;
  final double outputGain;
  final double detune;
  final double stereoWidth;
  final double tone;
  final double transient;
  final double pitchDropSemitones;
  final double noise;
  final double padDetuneOffset;

  const _FallbackInstrumentPreset({
    this.family = _FallbackInstrumentFamily.basic,
    this.oscillator = 1,
    this.cutoffHz = 3200.0,
    this.attackMs = 18.0,
    this.decayMs = 120.0,
    this.sustainLevel = 0.86,
    this.releaseMs = 180.0,
    this.drive = 0.08,
    this.outputGain = 0.36,
    this.detune = 0.0,
    this.stereoWidth = 0.12,
    this.tone = 0.55,
    this.transient = 0.08,
    this.pitchDropSemitones = 0.0,
    this.noise = 0.02,
    this.padDetuneOffset = 0.0008,
  });

  _FallbackInstrumentPreset copyWith({
    _FallbackInstrumentFamily? family,
    int? oscillator,
    double? cutoffHz,
    double? attackMs,
    double? decayMs,
    double? sustainLevel,
    double? releaseMs,
    double? drive,
    double? outputGain,
    double? detune,
    double? stereoWidth,
    double? tone,
    double? transient,
    double? pitchDropSemitones,
    double? noise,
    double? padDetuneOffset,
  }) {
    return _FallbackInstrumentPreset(
      family: family ?? this.family,
      oscillator: oscillator ?? this.oscillator,
      cutoffHz: cutoffHz ?? this.cutoffHz,
      attackMs: attackMs ?? this.attackMs,
      decayMs: decayMs ?? this.decayMs,
      sustainLevel: sustainLevel ?? this.sustainLevel,
      releaseMs: releaseMs ?? this.releaseMs,
      drive: drive ?? this.drive,
      outputGain: outputGain ?? this.outputGain,
      detune: detune ?? this.detune,
      stereoWidth: stereoWidth ?? this.stereoWidth,
      tone: tone ?? this.tone,
      transient: transient ?? this.transient,
      pitchDropSemitones: pitchDropSemitones ?? this.pitchDropSemitones,
      noise: noise ?? this.noise,
      padDetuneOffset: padDetuneOffset ?? this.padDetuneOffset,
    );
  }
}

class _FallbackNoteState {
  double phaseA;
  double phaseB;
  double low = 0.0;
  double aux = 0.0;
  final int seed;

  _FallbackNoteState({
    required this.phaseA,
    required this.phaseB,
    required this.seed,
  });
}

