double _clampDouble(num value, double min, double max) =>
    value.toDouble().clamp(min, max).toDouble();

double _wrapUnitPhase(double phase) {
  var wrapped = phase - phase.floorToDouble();
  if (wrapped < 0.0) wrapped += 1.0;
  return wrapped;
}

double _waveFromType(int type, double phase) {
  final p = _wrapUnitPhase(phase);
  switch (type) {
    case 0:
      return math.sin(2.0 * math.pi * p);
    case 1:
      return (2.0 * p) - 1.0;
    case 2:
      return p < 0.5 ? 1.0 : -1.0;
    default:
      return p < 0.5 ? (-1.0 + 4.0 * p) : (3.0 - 4.0 * p);
  }
}

double _hashNoise(int seed) {
  var x = (seed * 747796405 + 2891336453) & 0xFFFFFFFF;
  x ^= (x >> 16);
  x = (x * 2246822519) & 0xFFFFFFFF;
  x ^= (x >> 13);
  x = (x * 3266489917) & 0xFFFFFFFF;
  x ^= (x >> 16);
  final n01 = (x & 0x00ffffff) / 0x01000000;
  return (n01 * 2.0) - 1.0;
}

double _noiseForSample(int seed, int sampleIndex) {
  return _hashNoise(seed + sampleIndex * 17);
}

double _lowPassSample({
  required _FallbackNoteState state,
  required bool auxiliaryState,
  required double input,
  required double cutoffHz,
  required double sampleRate,
}) {
  final clampedCutoff = _clampDouble(cutoffHz, 50.0, sampleRate * 0.45);
  final alpha = 1.0 - math.exp((-2.0 * math.pi * clampedCutoff) / sampleRate);
  if (auxiliaryState) {
    state.aux += alpha * (input - state.aux);
    return state.aux;
  }
  state.low += alpha * (input - state.low);
  return state.low;
}

double _highPassSample({
  required _FallbackNoteState state,
  required double input,
  required double cutoffHz,
  required double sampleRate,
}) {
  final lp = _lowPassSample(
    state: state,
    auxiliaryState: true,
    input: input,
    cutoffHz: cutoffHz,
    sampleRate: sampleRate,
  );
  return input - lp;
}

void _advancePhase({
  required _FallbackNoteState state,
  required bool primary,
  required double frequencyHz,
  required double sampleRate,
}) {
  final next =
      (primary ? state.phaseA : state.phaseB) + (frequencyHz / sampleRate);
  final wrapped = _wrapUnitPhase(next);
  if (primary) {
    state.phaseA = wrapped;
  } else {
    state.phaseB = wrapped;
  }
}

_FallbackInstrumentPreset _fallbackPresetFromKeywords(String text) {
  if (text.contains('drum') || text.contains('kick') || text.contains('808')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.drum,
      oscillator: 0,
      cutoffHz: 2000.0,
      attackMs: 0.0,
      releaseMs: 120.0,
      drive: 0.30,
      outputGain: 0.42,
      detune: 0.0,
      stereoWidth: 0.0,
      tone: 0.58,
      transient: 0.30,
      pitchDropSemitones: 16.0,
      noise: 0.20,
    );
  }
  if (text.contains('bass')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.bass,
      oscillator: 2,
      cutoffHz: 1200.0,
      attackMs: 6.0,
      releaseMs: 220.0,
      drive: 0.24,
      outputGain: 0.34,
      detune: 0.004,
      stereoWidth: 0.06,
      tone: 0.52,
      transient: 0.16,
      pitchDropSemitones: 6.0,
      noise: 0.04,
    );
  }
  if (text.contains('pad') || text.contains('string')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.pad,
      oscillator: 3,
      cutoffHz: 2200.0,
      attackMs: 80.0,
      releaseMs: 620.0,
      drive: 0.05,
      outputGain: 0.30,
      detune: 0.012,
      stereoWidth: 0.24,
      tone: 0.48,
      transient: 0.06,
      pitchDropSemitones: 0.0,
      noise: 0.03,
    );
  }
  if (text.contains('pluck') || text.contains('bell')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.pluck,
      oscillator: 3,
      cutoffHz: 5100.0,
      attackMs: 2.0,
      releaseMs: 190.0,
      drive: 0.08,
      outputGain: 0.33,
      detune: 0.005,
      stereoWidth: 0.13,
      tone: 0.74,
      transient: 0.20,
      pitchDropSemitones: 0.0,
      noise: 0.03,
    );
  }
  if (text.contains('brass') || text.contains('horn')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.brass,
      oscillator: 1,
      cutoffHz: 2800.0,
      attackMs: 18.0,
      releaseMs: 290.0,
      drive: 0.14,
      outputGain: 0.33,
      detune: 0.004,
      stereoWidth: 0.13,
      tone: 0.56,
      transient: 0.08,
      pitchDropSemitones: 0.0,
      noise: 0.02,
    );
  }
  if (text.contains('key') ||
      text.contains('piano') ||
      text.contains('organ')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.keys,
      oscillator: 0,
      cutoffHz: 3300.0,
      attackMs: 10.0,
      releaseMs: 280.0,
      drive: 0.06,
      outputGain: 0.32,
      detune: 0.004,
      stereoWidth: 0.12,
      tone: 0.58,
      transient: 0.12,
      pitchDropSemitones: 0.0,
      noise: 0.02,
    );
  }
  if (text.contains('wave')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.wavetable,
      oscillator: 1,
      cutoffHz: 4800.0,
      attackMs: 6.0,
      releaseMs: 240.0,
      drive: 0.16,
      outputGain: 0.33,
      detune: 0.006,
      stereoWidth: 0.14,
      tone: 0.68,
      transient: 0.12,
      pitchDropSemitones: 0.0,
      noise: 0.03,
    );
  }
  if (text.contains('harmonic') || text.contains('fm')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.harmonic,
      oscillator: 0,
      cutoffHz: 3400.0,
      attackMs: 12.0,
      releaseMs: 360.0,
      drive: 0.09,
      outputGain: 0.32,
      detune: 0.005,
      stereoWidth: 0.15,
      tone: 0.62,
      transient: 0.12,
      pitchDropSemitones: 0.0,
      noise: 0.02,
    );
  }
  if (text.contains('lead') || text.contains('saw')) {
    return const _FallbackInstrumentPreset(
      family: _FallbackInstrumentFamily.lead,
      oscillator: 1,
      cutoffHz: 5600.0,
      attackMs: 4.0,
      releaseMs: 200.0,
      drive: 0.18,
      outputGain: 0.34,
      detune: 0.008,
      stereoWidth: 0.16,
      tone: 0.74,
      transient: 0.10,
      pitchDropSemitones: 0.0,
      noise: 0.03,
    );
  }
  return _kFallbackDefaultPreset;
}

_FallbackInstrumentPreset _fallbackPresetForInstrument({
  required String instrumentId,
  required String instrumentName,
  required Map<String, double> params,
}) {
  final id = instrumentId.trim().toLowerCase();
  final text = '$id ${instrumentName.toLowerCase()}';
  var preset =
      _kFallbackInstrumentPresets[id] ?? _fallbackPresetFromKeywords(text);

  double getParam(String key, double fallback, double min, double max) {
    final raw = params[key];
    if (raw == null || !raw.isFinite) return fallback;
    return _clampDouble(raw, min, max);
  }

  final oscillator = getParam(
    'oscillator',
    preset.oscillator.toDouble(),
    0.0,
    3.0,
  ).round().clamp(0, 3);

  preset = preset.copyWith(
    oscillator: oscillator,
    cutoffHz: getParam('cutoffHz', preset.cutoffHz, 200.0, 16000.0),
    attackMs: getParam('attackMs', preset.attackMs, 0.0, 1000.0),
    decayMs: getParam('decayMs', preset.decayMs, 0.0, 2000.0),
    sustainLevel: getParam('sustainLevel', preset.sustainLevel, 0.05, 1.0),
    releaseMs: getParam('releaseMs', preset.releaseMs, 20.0, 2400.0),
    drive: getParam('drive', preset.drive, 0.0, 1.0),
    outputGain: getParam('outputGain', preset.outputGain, 0.15, 0.75),
    detune: getParam('detune', preset.detune, 0.0, 0.03),
    stereoWidth: getParam('stereoWidth', preset.stereoWidth, 0.0, 0.45),
    tone: getParam('tone', preset.tone, 0.0, 1.0),
    transient: getParam('transient', preset.transient, 0.0, 1.0),
    pitchDropSemitones: getParam(
      'pitchDropSemitones',
      preset.pitchDropSemitones,
      0.0,
      36.0,
    ),
    noise: getParam('noise', preset.noise, 0.0, 0.45),
    padDetuneOffset: getParam(
      'padDetuneOffset',
      preset.padDetuneOffset,
      0.0,
      0.004,
    ),
  );

  return preset;
}

double _renderFallbackRawSample({
  required _FallbackInstrumentPreset preset,
  required _FallbackNoteState state,
  required int pitch,
  required int noteSampleIndex,
  required double frequencyHz,
  required double noteProgress,
  required double envelope,
  required double sampleRate,
}) {
  switch (preset.family) {
    case _FallbackInstrumentFamily.bass:
      {
        final toneShape = _clampDouble(preset.tone, 0.0, 1.0);
        final det = _clampDouble(preset.detune, 0.0, 0.012);
        final sub =
            _waveFromType(0, state.phaseA) *
            _clampDouble(0.94 - toneShape * 0.24, 0.64, 0.94);
        final body =
            _waveFromType(3, state.phaseB) *
            _clampDouble(0.10 + toneShape * 0.18, 0.08, 0.28);
        final growl =
            _waveFromType(1, state.phaseA * (1.15 + toneShape * 0.25)) *
            _clampDouble(toneShape * 0.18, 0.0, 0.18);
        final overtone =
            _waveFromType(
              0,
              state.phaseA * (1.8 + toneShape * 1.0 + det * 20.0),
            ) *
            _clampDouble(0.02 + toneShape * 0.10, 0.02, 0.12);
        final grit =
            (preset.noise * (0.01 + toneShape * 0.08)) *
            math.exp(-10.0 * noteProgress) *
            _noiseForSample(state.seed + 23, noteSampleIndex);
        final transient =
            (0.004 + preset.transient * 0.025) *
            math.exp(-36.0 * noteProgress) *
            _noiseForSample(state.seed, noteSampleIndex);
        final dynamicCutoff =
            preset.cutoffHz *
            _clampDouble(
              0.82 + toneShape * 0.08 - noteProgress * 0.22,
              0.30,
              0.96,
            );
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: sub + body + growl + overtone + grit + transient,
          cutoffHz: dynamicCutoff,
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * (1.0 + det * (1.2 + toneShape * 1.6)),
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.pad:
      {
        final det = _clampDouble(
          preset.detune + preset.padDetuneOffset,
          0.0,
          0.004,
        );
        final foundation = _waveFromType(0, state.phaseA) * 0.54;
        final bloom = _waveFromType(0, state.phaseB) * 0.26;
        final octave = _waveFromType(3, state.phaseA * 0.5 + 0.125) * 0.08;
        final air =
            preset.noise * 0.06 * _noiseForSample(state.seed, noteSampleIndex);
        final openAmount = _clampDouble(
          0.70 + (1.0 - noteProgress) * 0.14,
          0.58,
          0.92,
        );
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: foundation + bloom + octave + air,
          cutoffHz: preset.cutoffHz * openAmount,
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz * (1.0 - det),
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * (1.0 + det),
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.lead:
      {
        final vibrato =
            1.0 +
            math.sin(2.0 * math.pi * noteSampleIndex / sampleRate * 5.1) *
                (0.001 + 0.002 * envelope);
        final saw = _waveFromType(1, state.phaseA);
        final pulse = _waveFromType(2, state.phaseB) * 0.42;
        final edge = _waveFromType(3, state.phaseA * 1.99) * 0.18;
        final noise =
            preset.noise *
            0.35 *
            math.exp(-12.0 * noteProgress) *
            _noiseForSample(state.seed, noteSampleIndex);
        final cutoffOpen = _clampDouble(1.2 - noteProgress * 0.35, 0.8, 1.55);
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: saw * 0.68 + pulse + edge + noise,
          cutoffHz: preset.cutoffHz * cutoffOpen,
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz * vibrato,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * 1.01 * vibrato,
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.pluck:
      {
        final decay = math.exp(-6.5 * noteProgress);
        final tri = _waveFromType(3, state.phaseA) * 0.62;
        final tone = _waveFromType(0, state.phaseB) * 0.36;
        final pick =
            (preset.transient + 0.12) *
            math.exp(-28.0 * noteProgress) *
            _noiseForSample(state.seed, noteSampleIndex);
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: (tri + tone) * decay + pick,
          cutoffHz: preset.cutoffHz * (1.1 + (1.0 - noteProgress) * 0.25),
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * 2.0,
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.keys:
      {
        final style = preset.oscillator.clamp(0, 3).toInt();
        final keyOpen = _clampDouble(
          0.75 + preset.tone * 0.75 + (1.0 - noteProgress) * 0.2,
          0.6,
          1.7,
        );

        if (style == 2) {
          final fundamental = _waveFromType(2, state.phaseA) * 0.48;
          final octave = _waveFromType(2, state.phaseB) * 0.28;
          final twelfth = _waveFromType(2, state.phaseB * 1.5) * 0.16;
          final chorus = _waveFromType(1, state.phaseB + 0.13) * 0.11;
          final click =
              (0.04 + preset.transient * 0.18) *
              math.exp(-52.0 * noteProgress) *
              _noiseForSample(state.seed + 31, noteSampleIndex);
          final raw = _lowPassSample(
            state: state,
            auxiliaryState: false,
            input: fundamental + octave + twelfth + chorus + click,
            cutoffHz: preset.cutoffHz * keyOpen,
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: true,
            frequencyHz: frequencyHz,
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: false,
            frequencyHz: frequencyHz * 2.0,
            sampleRate: sampleRate,
          );
          return raw;
        }

        final inharmonic =
            1.0 + _clampDouble(frequencyHz * 0.0000005, 0.0, 0.005);
        final hammer =
            (0.09 + preset.transient * 0.30) *
            math.exp(-36.0 * noteProgress) *
            _noiseForSample(state.seed + 21, noteSampleIndex);
        final body = _waveFromType(0, state.phaseA) * 0.58;
        final second = _waveFromType(0, state.phaseB * inharmonic) * 0.26;
        final third =
            _waveFromType(style == 1 ? 1 : 0, state.phaseB * 1.5 * inharmonic) *
            0.15;
        final tine =
            _waveFromType(
              style == 3 ? 3 : 0,
              state.phaseB * (2.4 + style * 0.25),
            ) *
            0.11;
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: body + second + third + tine + hammer,
          cutoffHz: preset.cutoffHz * keyOpen,
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * 2.0,
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.brass:
      {
        final style = preset.oscillator.clamp(0, 3).toInt();
        final vibratoDepth = 0.0002 + envelope * (0.00025 + style * 0.00008);
        final vibratoRate = 4.2 + style * 0.35;
        final vibrato =
            1.0 +
            math.sin(
                  2.0 * math.pi * noteSampleIndex / sampleRate * vibratoRate,
                ) *
                vibratoDepth;
        final body = _waveFromType(0, state.phaseA) * 0.34;
        final saw = _waveFromType(1, state.phaseA) * 0.22;
        final pulse = _waveFromType(2, state.phaseB) * 0.10;
        final upper =
            _waveFromType(style >= 2 ? 0 : 3, state.phaseA * 2.0) *
            (0.08 + 0.02 * style);
        final breath =
            (0.01 + preset.noise * 0.22) *
            math.exp(-7.0 * noteProgress) *
            _noiseForSample(state.seed + 41, noteSampleIndex);
        final t = noteSampleIndex / sampleRate;
        final formantA =
            math.sin(2.0 * math.pi * (520.0 + style * 90.0) * t) * 0.11;
        final formantB =
            math.sin(2.0 * math.pi * (980.0 + style * 120.0) * t) * 0.08;
        final dynamicCutoff =
            preset.cutoffHz *
            _clampDouble(
              0.72 + envelope * 0.42 - noteProgress * 0.10,
              0.55,
              1.18,
            );
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: body + saw + pulse + upper + breath + formantA + formantB,
          cutoffHz: dynamicCutoff,
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz * vibrato,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * 0.994 * vibrato,
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.wavetable:
      {
        final modLfo = math.sin(
          2.0 * math.pi * noteSampleIndex / sampleRate * 0.35,
        );
        final pd = _wrapUnitPhase(
          state.phaseA + 0.18 * math.sin(2.0 * math.pi * state.phaseB + modLfo),
        );
        final main = math.sin(2.0 * math.pi * pd);
        final upper = math.sin(2.0 * math.pi * pd * 2.0) * 0.33;
        final sparkle = _waveFromType(1, pd * 1.5) * 0.22;
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: main + upper + sparkle,
          cutoffHz: preset.cutoffHz * (1.1 - noteProgress * 0.25),
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: 0.27,
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.harmonic:
      {
        final style = preset.oscillator.clamp(0, 3).toInt();
        final modRatio = style <= 1 ? 2.0 : 3.0;
        final modDepth = 0.05 + preset.tone * 0.13 + style * 0.02;
        final mod = math.sin(2.0 * math.pi * state.phaseB * modRatio);
        final carrier = _wrapUnitPhase(state.phaseA + mod * modDepth);
        final p = 2.0 * math.pi * carrier;
        final body = math.sin(p) * 0.50;
        final even = math.sin(2.0 * p) * 0.26;
        final odd = math.sin(3.0 * p) * 0.18;
        final air = math.sin(5.0 * p) * 0.10;
        final sheen = _waveFromType(style == 3 ? 1 : 3, state.phaseB) * 0.12;
        final transient =
            (0.02 + preset.transient * 0.12) *
            math.exp(-24.0 * noteProgress) *
            _noiseForSample(state.seed + 57, noteSampleIndex);
        final dynamicCutoff =
            preset.cutoffHz * (0.9 + (1.0 - noteProgress) * 0.35);
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: body + even + odd + air + sheen + transient,
          cutoffHz: dynamicCutoff,
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * 0.5,
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.drum:
      {
        final style = preset.oscillator.clamp(0, 3).toInt();
        final isKick = pitch == 35 || pitch == 36;
        final isSnare = pitch == 38 || pitch == 40;
        final isClap = pitch == 37 || pitch == 39;
        final isTom =
            pitch == 41 ||
            pitch == 43 ||
            pitch == 45 ||
            pitch == 47 ||
            pitch == 48 ||
            pitch == 50;
        final isHat =
            pitch == 42 ||
            pitch == 44 ||
            pitch == 46 ||
            pitch == 49 ||
            pitch == 51 ||
            pitch == 52 ||
            pitch == 53 ||
            pitch == 55 ||
            pitch == 57 ||
            pitch == 59;

        final treatAsKick = isKick || pitch < 35;
        final treatAsSnare =
            isSnare || (!isClap && !isTom && !isHat && pitch <= 44);
        final treatAsClap =
            isClap || (!isTom && !isHat && pitch > 44 && pitch <= 52);
        final treatAsTom = isTom || (!isHat && pitch > 52 && pitch <= 63);

        // Prefer GM-like drum note routing so common MIDI drum clips sound expected.
        if (treatAsKick) {
          final extraDrop = style == 0
              ? 22.0
              : style == 1
              ? 12.0
              : style == 2
              ? 16.0
              : 14.0;
          final curve = style == 0 ? 1.35 : 1.0;
          final dropSemis = _clampDouble(
            preset.pitchDropSemitones + extraDrop,
            0.0,
            36.0,
          );
          final dropProgress = math.pow(1.0 - noteProgress, curve).toDouble();
          final ratio = math.pow(2.0, -(dropSemis * dropProgress) / 12.0);
          final tunedFreq = _clampDouble(
            frequencyHz * ratio.toDouble(),
            24.0,
            1400.0,
          );
          final body =
              math.sin(2.0 * math.pi * state.phaseA) * (0.80 + 0.06 * style);
          final sub =
              math.sin(2.0 * math.pi * state.phaseB) *
              (style == 0 ? 0.36 : 0.22);
          final click =
              (0.07 + preset.transient * (0.34 + style * 0.07)) *
              math.exp(-40.0 * noteProgress) *
              _noiseForSample(state.seed + 7, noteSampleIndex);
          final beater =
              ((style == 1 || style == 2) ? 0.08 : 0.03) *
              math.exp(-58.0 * noteProgress) *
              math.sin(2.0 * math.pi * state.phaseB * 10.0);
          final raw = _lowPassSample(
            state: state,
            auxiliaryState: false,
            input: body + sub + click + beater,
            cutoffHz: preset.cutoffHz * (0.75 + (1.0 - noteProgress) * 0.9),
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: true,
            frequencyHz: tunedFreq,
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: false,
            frequencyHz: tunedFreq * 0.5,
            sampleRate: sampleRate,
          );
          return raw;
        }
        if (treatAsSnare) {
          final toneMult = style == 0
              ? 1.25
              : style == 1
              ? 1.6
              : style == 2
              ? 1.85
              : 1.45;
          final toneA =
              math.sin(2.0 * math.pi * state.phaseA) *
              math.exp(-8.0 * noteProgress) *
              0.36;
          final toneB =
              math.sin(2.0 * math.pi * state.phaseB) *
              math.exp(-10.0 * noteProgress) *
              0.20;
          final noise =
              _noiseForSample(state.seed + 17, noteSampleIndex) *
              math.exp(-(9.0 + style * 1.2) * noteProgress) *
              (0.55 + 0.16 * style + preset.noise * 0.55);
          final raw = _highPassSample(
            state: state,
            input: toneA + toneB + noise,
            cutoffHz: 780.0 + style * 140.0,
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: true,
            frequencyHz: frequencyHz * toneMult,
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: false,
            frequencyHz: frequencyHz * toneMult * 1.72,
            sampleRate: sampleRate,
          );
          return raw;
        }
        if (treatAsClap) {
          if (style == 1) {
            final rimTone =
                math.sin(2.0 * math.pi * state.phaseA) *
                math.exp(-22.0 * noteProgress) *
                0.34;
            final rimSnap =
                _noiseForSample(state.seed + 29, noteSampleIndex) *
                math.exp(-26.0 * noteProgress) *
                0.28;
            _advancePhase(
              state: state,
              primary: true,
              frequencyHz: frequencyHz * 3.2,
              sampleRate: sampleRate,
            );
            return rimTone + rimSnap;
          }

          final burst0 = math.exp(-95.0 * math.pow(noteProgress - 0.028, 2.0));
          final burst1 = math.exp(-125.0 * math.pow(noteProgress - 0.068, 2.0));
          final burst2 = math.exp(-165.0 * math.pow(noteProgress - 0.112, 2.0));
          final envelopeNoise = _clampDouble(
            burst0 + burst1 + burst2,
            0.0,
            1.0,
          );
          final tail = math.exp(-(10.0 + style * 1.5) * noteProgress);
          final noise = _noiseForSample(state.seed + 29, noteSampleIndex);
          return noise * (envelopeNoise * 0.78 + tail * 0.22);
        }
        if (treatAsTom) {
          final tomMul = style == 0
              ? 0.85
              : style == 1
              ? 1.0
              : style == 2
              ? 1.18
              : 0.95;
          final tomFreq = _clampDouble(frequencyHz * tomMul, 70.0, 900.0);
          final tone =
              math.sin(2.0 * math.pi * state.phaseA) *
              math.exp(-6.5 * noteProgress) *
              0.56;
          final ring =
              _waveFromType(3, state.phaseB) *
              math.exp(-8.5 * noteProgress) *
              0.24;
          final stick =
              (0.03 + preset.transient * 0.14) *
              math.exp(-42.0 * noteProgress) *
              _noiseForSample(state.seed + 37, noteSampleIndex);
          final raw = _lowPassSample(
            state: state,
            auxiliaryState: false,
            input: tone + ring + stick,
            cutoffHz: preset.cutoffHz * 1.1,
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: true,
            frequencyHz: tomFreq,
            sampleRate: sampleRate,
          );
          _advancePhase(
            state: state,
            primary: false,
            frequencyHz: tomFreq * 1.6,
            sampleRate: sampleRate,
          );
          return raw;
        }
        final hatDecay = style == 0
            ? 14.0
            : style == 1
            ? 18.0
            : style == 2
            ? 16.0
            : 11.0;
        final noise =
            _noiseForSample(state.seed + 47, noteSampleIndex) *
            math.exp(-hatDecay * noteProgress);
        final metallic =
            _waveFromType(2, state.phaseA) * 0.23 +
            _waveFromType(1, state.phaseB) * 0.16;
        final air = _waveFromType(0, state.phaseA * 1.7) * 0.06;
        final raw = _highPassSample(
          state: state,
          input: noise + metallic + air,
          cutoffHz: 4800.0 + style * 380.0,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: 6400.0 + style * 750.0,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: 8900.0 + style * 980.0,
          sampleRate: sampleRate,
        );
        return raw;
      }
    case _FallbackInstrumentFamily.basic:
      {
        final main = _waveFromType(preset.oscillator, state.phaseA);
        final sub = 0.30 * _waveFromType(0, state.phaseB);
        final second = _waveFromType(0, state.phaseA * 2.0) * 0.12;
        final noise =
            preset.noise * _noiseForSample(state.seed, noteSampleIndex);
        final raw = _lowPassSample(
          state: state,
          auxiliaryState: false,
          input: main * 0.72 + sub + second + noise,
          cutoffHz: preset.cutoffHz,
          sampleRate: sampleRate,
        );

        _advancePhase(
          state: state,
          primary: true,
          frequencyHz: frequencyHz,
          sampleRate: sampleRate,
        );
        _advancePhase(
          state: state,
          primary: false,
          frequencyHz: frequencyHz * 0.5,
          sampleRate: sampleRate,
        );
        return raw;
      }
  }
}

double _fallbackEnvelopeHoldLevel({
  required double ageSec,
  required double attackSec,
  required double decaySec,
  required double sustainLevel,
}) {
  final safeAttack = math.max(0.001, attackSec);
  final safeDecay = math.max(0.001, decaySec);
  final safeSustain = sustainLevel.clamp(0.05, 1.0).toDouble();
  if (ageSec < safeAttack) {
    return (ageSec / safeAttack).clamp(0.0, 1.0).toDouble();
  }
  final decayAge = ageSec - safeAttack;
  if (decayAge < safeDecay) {
    final t = decayAge / safeDecay;
    return 1.0 + ((safeSustain - 1.0) * t);
  }
  return safeSustain;
}

double _fallbackEnvelopeLevel({
  required double ageSec,
  required double holdSec,
  required double attackSec,
  required double decaySec,
  required double sustainLevel,
  required double releaseSec,
}) {
  if (ageSec < holdSec) {
    return _fallbackEnvelopeHoldLevel(
      ageSec: ageSec,
      attackSec: attackSec,
      decaySec: decaySec,
      sustainLevel: sustainLevel,
    );
  }
  final safeRelease = math.max(0.02, releaseSec);
  final releaseAge = ageSec - holdSec;
  final releaseStart = _fallbackEnvelopeHoldLevel(
    ageSec: holdSec,
    attackSec: attackSec,
    decaySec: decaySec,
    sustainLevel: sustainLevel,
  );
  return releaseStart * (1.0 - (releaseAge / safeRelease));
}

enum _ExportAudioFormat { wav, mp3, flac }

enum _ExportChannelMode { stereo, mono }

enum _ExportResampleQuality { draft, good, best }

enum _ExportMp3Mode { cbr, vbr }

class _AudioExportSettings {
  final _ExportAudioFormat format;
  final int sampleRate;
  final int wavBitDepth;
  final bool wavDithering;
  final int mp3BitrateKbps;
  final _ExportMp3Mode mp3Mode;
  final int mp3VbrQuality;
  final _ExportChannelMode channelMode;
  final bool normalize;
  final double normalizeTargetDb;
  final _ExportResampleQuality resampleQuality;

  const _AudioExportSettings({
    required this.format,
    required this.sampleRate,
    required this.wavBitDepth,
    required this.wavDithering,
    required this.mp3BitrateKbps,
    required this.mp3Mode,
    required this.mp3VbrQuality,
    required this.channelMode,
    required this.normalize,
    required this.normalizeTargetDb,
    required this.resampleQuality,
  });

  String get fileExtension {
    switch (format) {
      case _ExportAudioFormat.wav:
        return 'wav';
      case _ExportAudioFormat.mp3:
        return 'mp3';
      case _ExportAudioFormat.flac:
        return 'flac';
    }
  }
}

class _CopiedClipGroupEntry {
  final AudioTrack clip;
  final Duration trimStart;
  final Duration trimEnd;
  final double offsetDeltaMs;
  final int rowDelta;

  const _CopiedClipGroupEntry({
    required this.clip,
    required this.trimStart,
    required this.trimEnd,
    required this.offsetDeltaMs,
    required this.rowDelta,
  });
}

class _CopiedRowEffectsEntry {
  final RowEffectsSnapshot effects;
  final List<AutomationLaneSnapshot> automationLanes;
  final List<AutomationClipSnapshot> automationClips;
  final String? selectedAutomationTargetId;

  const _CopiedRowEffectsEntry({
    required this.effects,
    required this.automationLanes,
    required this.automationClips,
    this.selectedAutomationTargetId,
  });

  Map<String, dynamic> toJson() => <String, dynamic>{
    'effects': effects.toJson(),
    'automationLanes': automationLanes.map((lane) => lane.toJson()).toList(),
    'automationClips': automationClips.map((clip) => clip.toJson()).toList(),
    if ((selectedAutomationTargetId ?? '').trim().isNotEmpty)
      'selectedAutomationTargetId': selectedAutomationTargetId!.trim(),
  };
}

