class _AutomationTargetMeta {
  final String targetId;
  final String label;
  final int effectIndex; // -1 = row volume
  final String paramId;
  final String type; // float|bool|choice
  final String unit;
  final double min;
  final double max;
  final double initialNormalized;
  final double? defaultNormalized;
  final Map<double, String> displayLabels;
  final bool isOrphan;
  final bool uiVisible;

  const _AutomationTargetMeta({
    required this.targetId,
    required this.label,
    required this.effectIndex,
    required this.paramId,
    required this.type,
    this.unit = '',
    required this.min,
    required this.max,
    this.initialNormalized = 0.5,
    this.defaultNormalized,
    this.displayLabels = const <double, String>{},
    this.isOrphan = false,
    this.uiVisible = true,
  });

  bool get isVolume => targetId == 'volume';

  _AutomationTargetMeta copyWith({
    String? targetId,
    String? label,
    int? effectIndex,
    String? paramId,
    String? type,
    String? unit,
    double? min,
    double? max,
    double? initialNormalized,
    double? defaultNormalized,
    Map<double, String>? displayLabels,
    bool? isOrphan,
    bool? uiVisible,
  }) {
    return _AutomationTargetMeta(
      targetId: targetId ?? this.targetId,
      label: label ?? this.label,
      effectIndex: effectIndex ?? this.effectIndex,
      paramId: paramId ?? this.paramId,
      type: type ?? this.type,
      unit: unit ?? this.unit,
      min: min ?? this.min,
      max: max ?? this.max,
      initialNormalized: initialNormalized ?? this.initialNormalized,
      defaultNormalized: defaultNormalized ?? this.defaultNormalized,
      displayLabels: displayLabels ?? this.displayLabels,
      isOrphan: isOrphan ?? this.isOrphan,
      uiVisible: uiVisible ?? this.uiVisible,
    );
  }

  Map<String, dynamic> toUiMap() => <String, dynamic>{
    'id': targetId,
    'label': label,
    'fullLabel': label,
    'isVolume': isVolume,
    'isOrphan': isOrphan,
    'effectIndex': effectIndex,
    'paramId': paramId,
    'type': type,
    if (unit.trim().isNotEmpty) 'unit': unit.trim(),
    'min': min,
    'max': max,
    'initialNormalized': initialNormalized.clamp(0.0, 1.0),
    if (defaultNormalized != null)
      'defaultNormalized': defaultNormalized!.clamp(0.0, 1.0),
    if (displayLabels.isNotEmpty)
      'displayLabels': displayLabels.map(
        (key, value) => MapEntry(key.toStringAsFixed(6), value),
      ),
    'uiVisible': uiVisible,
  };

  AutomationLaneSnapshot toLaneSnapshot(List<AutomationPoint> points) {
    return AutomationLaneSnapshot(
      targetId: targetId,
      label: label,
      effectIndex: effectIndex,
      paramId: paramId,
      type: type,
      unit: unit,
      min: min,
      max: max,
      points: points.map((p) => p.copy()).toList(growable: false),
    );
  }

  static _AutomationTargetMeta fromLaneSnapshot(AutomationLaneSnapshot lane) {
    final laneInitial = lane.points.isNotEmpty
        ? lane.points.first.volume.clamp(0.0, 1.0).toDouble()
        : (lane.targetId == 'volume' ? 0.75 : 0.5);
    return _AutomationTargetMeta(
      targetId: lane.targetId,
      label: lane.label,
      effectIndex: lane.effectIndex,
      paramId: lane.paramId,
      type: lane.type,
      unit: lane.unit,
      min: lane.min,
      max: lane.max,
      initialNormalized: laneInitial,
      isOrphan: false,
    );
  }
}

