const double _kMacDawBackPillWidth = 69.0;
const double _kMacDawBackPillHeight = 26.0;
const double _kMacDawBackPillHorizontalNudge = 3.0;
const double _kMacDawBackPillDownNudgeFraction = 0.22;
const double _kDesktopTopBarExtraTopPadding = 2.0;
const double _kDesktopTimelineScrollbarReservedGap = 6.0;
const double _kDesktopTimelineRulerHeight =
    TabletDawPanelLayout.tabletRulerHeight + 6.0;

class _EditorLayoutSpec {
  final EdgeInsets topBarPadding;
  final double topBarBottomGap;
  final double topBarClusterGap;
  final double topBarActionButtonSize;

  const _EditorLayoutSpec({
    required this.topBarPadding,
    required this.topBarBottomGap,
    required this.topBarClusterGap,
    required this.topBarActionButtonSize,
  });

  factory _EditorLayoutSpec.fromSize(Size size) {
    final isDesktop = PlatformCapabilities.current.isDesktop;
    final width = size.width;
    final isMacDesktop = !kIsWeb && Platform.isMacOS && isDesktop;
    final scale = isDesktop
        ? (width >= 1900
              ? 1.26
              : width >= 1600
              ? 1.16
              : width >= 1360
              ? 1.08
              : 1.0)
        : 1.0;
    return _EditorLayoutSpec(
      topBarPadding: EdgeInsets.fromLTRB(
        (isMacDesktop ? 22.0 : 16.0) * scale,
        (isMacDesktop ? 10.0 : 12.0) * scale,
        16.0 * scale,
        8.0 * scale,
      ),
      topBarBottomGap: isDesktop ? 14.0 : 12.0,
      topBarClusterGap: (isDesktop ? 10.0 : 8.0) * scale,
      topBarActionButtonSize: (isDesktop ? 42.0 : 46.0) * scale,
    );
  }
}

