  bool _canUseSubscriptionCapability(
    String capability, {
    bool fallback = true,
  }) {
    try {
      return context.read<EntitlementService>().canUseCapability(capability);
    } catch (_) {
      return fallback;
    }
  }

  bool get _isProEntitled => _canUseSubscriptionCapability(
    SubscriptionCapability.allPlugins,
    fallback: widget.isProEntitled ?? true,
  );

  EntitlementSnapshot? get _currentEntitlementSnapshot {
    try {
      return context.read<EntitlementService>().entitlement;
    } catch (_) {
      return null;
    }
  }

  bool get _isSubscriptionEnforcementEnabled {
    try {
      return context.read<EntitlementService>().isEnforcementEnabled;
    } catch (_) {
      return widget.isProEntitled == false;
    }
  }

  bool get _isFreePlan {
    if (!_isSubscriptionEnforcementEnabled) return false;
    final entitlement = _currentEntitlementSnapshot;
    if (entitlement == null && widget.isProEntitled != false) return false;
    return SubscriptionLimits.isFreePlan(entitlement);
  }

  bool get _shouldShowChatUsageButton {
    if (!_isSubscriptionEnforcementEnabled) return true;
    final entitlement = _currentEntitlementSnapshot;
    if (entitlement == null) return widget.isProEntitled != false;
    if (!SubscriptionLimits.isFreePlan(entitlement)) return true;
    if (entitlement.hasCapability(SubscriptionCapability.studioFeatures) ||
        entitlement.hasCapability(SubscriptionCapability.educationSandbox) ||
        entitlement.hasCapability(
          SubscriptionCapability.educationVisibilityControls,
        ) ||
        entitlement.hasCapability(SubscriptionCapability.teamWorkspaces)) {
      return true;
    }
    if (entitlement.workspaceAccessSummary.organizationCount > 0 ||
        entitlement.workspaceAccessSummary.workspaceCount > 0 ||
        entitlement.organizations.isNotEmpty) {
      return true;
    }
    return entitlement.accessSources.any((source) {
      final status = source.status.trim().toLowerCase();
      final active =
          status.isEmpty ||
          status == 'active' ||
          status == 'trialing' ||
          status == 'grace_period';
      return active && source.planCode.trim().toLowerCase() != 'free';
    });
  }

  int get _effectiveMaxRows {
    if (!_isFreePlan) return kMaxRows;
    return math.min(kMaxRows, SubscriptionLimits.freeRowsPerProject);
  }

  bool _canUseEffectForCurrentPlan(String effectName) {
    if (!_isSubscriptionEnforcementEnabled) return true;
    return SubscriptionLimits.canUseBuiltInEffect(
      _currentEntitlementSnapshot,
      effectName,
    );
  }

  bool _canUseInstrumentForCurrentPlan(String instrumentId) {
    if (!_isSubscriptionEnforcementEnabled) return true;
    final normalizedId = instrumentId.trim().toLowerCase();
    if (normalizedId.isNotEmpty &&
        _desktopHostedInstrumentCatalog.any((spec) {
          final id = (spec['id'] as String? ?? '').trim().toLowerCase();
          return id == normalizedId;
        })) {
      return true;
    }
    return SubscriptionLimits.canUseInstrument(
      _currentEntitlementSnapshot,
      instrumentId,
    );
  }

  String _rowLimitReachedMessage() {
    final limit = _effectiveMaxRows;
    return '${L10n.translate(context, 'Maximum of')} $limit ${L10n.translate(context, 'rows reached.')}';
  }

  void _showRowLimitReachedNotice() {
    if (_isFreePlan) {
      if (_rowLimitUpgradeDialogOpen || !mounted) return;
      _rowLimitUpgradeDialogOpen = true;
      unawaited(
        showAppUpgradeDialog(
          context: context,
          title: 'Upgrade for more tracks',
          message: 'Free includes 5 tracks per project. Upgrade to add more.',
          icon: Icons.view_week_outlined,
          onUpgrade: widget.onUpgradeRequested,
        ).whenComplete(() {
          _rowLimitUpgradeDialogOpen = false;
        }),
      );
      return;
    }
    _showSmallNotice(_rowLimitReachedMessage());
  }

