  void _setGlobalAudioClock(Duration value, {bool forceNotify = false}) {
    if (_globalAudioClock == value && _transportClock.value == value) {
      return;
    }
    _globalAudioClock = value;
    final now = _transportUiStopwatch.elapsed;
    final elapsedSinceUiNotify = now - _lastTransportUiNotifyElapsed;
    final bool shouldNotify =
        forceNotify ||
        !_isPlaying ||
        elapsedSinceUiNotify >= _kTransportUiNotifyInterval;
    if (!shouldNotify) return;
    _lastTransportUiNotifyElapsed = now;
    if (_transportClock.value != value) _transportClock.value = value;
  }

  void _syncTransportClock(Duration value, {required bool playing}) {
    final now = _transportUiStopwatch.elapsed;
    _lastTransportSampleSeconds = value.inMilliseconds / 1000.0;
    _lastTransportSampleElapsed = now;
    _lastTransportPollElapsed = now;
    _transportRateSecPerSec = playing ? 1.0 : 0.0;
    _setGlobalAudioClock(value, forceNotify: true);
  }

  bool get _hasTimelineClips => _audioTracks.isNotEmpty;

  Duration _timelineEndPoint() {
    var endMs = 0.0;
    for (final track in _audioTracks) {
      final offsetMs = track.offset * 1000.0;
      if (!offsetMs.isFinite) continue;
      final durationMs = _clipTimelineDurationMs(track);
      if (!durationMs.isFinite || durationMs <= 0.0) continue;
      endMs = math.max(endMs, offsetMs + durationMs);
    }
    if (endMs <= 0.0) return Duration.zero;
    return Duration(milliseconds: endMs.ceil());
  }

  Duration _transportEndPoint() {
    return audioEditorTransportEndPoint(
      contentEnd: _timelineEndPoint(),
      bpm: _tempo,
    );
  }

  Duration _playbackStartFallbackPoint() {
    if (_loopEnabled && _loopEndMs > _loopStartMs) {
      return Duration(milliseconds: math.max(0, _loopStartMs));
    }
    return Duration.zero;
  }

  bool _playheadAtOrPastTransportEnd(Duration playhead) {
    return audioEditorPlayheadAtOrPastTransportEnd(
      hasTimelineClips: _hasTimelineClips,
      playhead: playhead,
      transportEnd: _transportEndPoint(),
    );
  }

