  double get _tabletTimelineRulerHeight {
    return PlatformCapabilities.current.isDesktop
        ? _kDesktopTimelineRulerHeight
        : TabletDawPanelLayout.tabletRulerHeight;
  }

  void _syncTabletRowFxSelectionAfterRemove(int row, int removedEffectIndex) {
    if (!mounted) return;
    if (_tabletSelectedRowFxRow != row ||
        _tabletSelectedRowFxIndex == null ||
        removedEffectIndex < 0) {
      return;
    }

    final selectedIndex = _tabletSelectedRowFxIndex!;
    if (selectedIndex == removedEffectIndex) {
      setState(() {
        _tabletSelectedRowFxRow = null;
        _tabletSelectedRowFxIndex = null;
      });
      return;
    }

    if (selectedIndex > removedEffectIndex) {
      setState(() {
        _tabletSelectedRowFxIndex = selectedIndex - 1;
      });
    }
  }

  void _clearTabletRowFxSelectionForRow(int row) {
    if (!mounted || _tabletSelectedRowFxRow != row) return;
    setState(() {
      _tabletSelectedRowFxRow = null;
      _tabletSelectedRowFxIndex = null;
    });
  }

  String _audioClipDisplayName(AudioTrack clip) {
    final label = clip.label.trim();
    if (label.isNotEmpty) return label;
    return L10n.translate(context, clip.isMidi ? 'MIDI Clip' : 'Audio Clip');
  }

  bool _isValidAudioClipOptionsIndex(int? clipIndex) {
    if (clipIndex == null ||
        clipIndex < 0 ||
        clipIndex >= _audioTracks.length) {
      return false;
    }
    return !_audioTracks[clipIndex].isMidi;
  }

  void _openTabletAudioClipOptions(int clipIndex) {
    if (!_isValidAudioClipOptionsIndex(clipIndex)) return;
    final clip = _audioTracks[clipIndex];
    setState(() {
      _selectedRow = clip.rowIndex.clamp(0, math.max(0, _rowCount - 1)).toInt();
      _tabletRightPanelTab = 'inspector';
      _tabletRightPanelCollapsed = false;
      _tabletAudioClipOptionsIndex = clipIndex;
      _tabletAudioClipOptionsNameDraft = _audioClipDisplayName(clip);
      _tabletAudioClipOptionsRenaming = false;
      _tabletAudioClipOptionsGainStart = null;
      _tabletAudioClipOptionsPitchStart = null;
    });
    _tabletAudioClipNameFocusNode.unfocus();
  }

  void _closeTabletAudioClipOptions() {
    if (_tabletAudioClipOptionsIndex == null) return;
    setState(() {
      _tabletAudioClipOptionsIndex = null;
      _tabletAudioClipOptionsNameDraft = '';
      _tabletAudioClipOptionsRenaming = false;
      _tabletAudioClipOptionsGainStart = null;
      _tabletAudioClipOptionsPitchStart = null;
    });
    _tabletAudioClipNameFocusNode.unfocus();
  }

  Future<void> _renameAudioClipFromPanel(int clipIndex, String rawName) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final oldLabel = _audioTracks[clipIndex].label;
    final nextLabel = rawName.trim();
    if (nextLabel.isEmpty || oldLabel == nextLabel) return;

    await _undoManager.execute(
      SetClipLabelAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldLabel: oldLabel,
        newLabel: nextLabel,
        applyToState: (clip, label) {
          clip.label = label;
          setState(() {});
        },
      ),
    );

    _recordProducerManualEdit('clip_rename', {
      'clip': clipIndex,
      'old_label': oldLabel,
      'new_label': nextLabel,
    });
  }

  void _beginTabletAudioClipRename() {
    if (_tabletAudioClipOptionsIndex == null) return;
    setState(() {
      _tabletAudioClipOptionsRenaming = true;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_tabletAudioClipOptionsRenaming) return;
      _tabletAudioClipNameFocusNode.requestFocus();
    });
  }

  Future<void> _finishTabletAudioClipRename(
    int clipIndex,
    String rawName,
  ) async {
    await _renameAudioClipFromPanel(clipIndex, rawName);
    if (!mounted) return;
    setState(() {
      _tabletAudioClipOptionsRenaming = false;
      if (_isValidAudioClipOptionsIndex(clipIndex)) {
        _tabletAudioClipOptionsNameDraft = _audioClipDisplayName(
          _audioTracks[clipIndex],
        );
      }
    });
    _tabletAudioClipNameFocusNode.unfocus();
  }

  Future<void> _commitTabletAudioClipGain(int clipIndex) async {
    final oldGain = _tabletAudioClipOptionsGainStart;
    _tabletAudioClipOptionsGainStart = null;
    if (oldGain == null || clipIndex < 0 || clipIndex >= _audioTracks.length) {
      return;
    }
    final newGain = _audioTracks[clipIndex].gain.clamp(0.0, 3.0).toDouble();
    if ((oldGain - newGain).abs() < 0.0001) return;
    await _undoManager.execute(
      SetClipGainAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldGain: oldGain,
        newGain: newGain,
        applyToState: (clip, gain) {
          clip.gain = gain;
          setState(() {});
        },
      ),
    );
    _recordProducerManualEdit('clip_gain', {
      'clip': clipIndex,
      'old_gain': oldGain,
      'new_gain': newGain,
    });
  }

  Future<void> _commitTabletAudioClipPitch(int clipIndex) async {
    final oldPitch = _tabletAudioClipOptionsPitchStart;
    _tabletAudioClipOptionsPitchStart = null;
    if (oldPitch == null || clipIndex < 0 || clipIndex >= _audioTracks.length) {
      return;
    }
    final newPitch = _audioTracks[clipIndex].pitchSemitones
        .clamp(_kClipPitchMinSemitones, _kClipPitchMaxSemitones)
        .toDouble();
    if ((oldPitch - newPitch).abs() < 0.0001) return;
    await _undoManager.execute(
      SetClipPitchAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldPitch: oldPitch,
        newPitch: newPitch,
        applyToState: (clip, pitch) {
          clip.pitchSemitones = pitch;
          setState(() {});
        },
      ),
    );
    _recordProducerManualEdit('clip_pitch', {
      'clip': clipIndex,
      'old_pitch': oldPitch,
      'new_pitch': newPitch,
    });
  }

  Future<void> _setAudioClipReversedFromPanel(
    int clipIndex,
    bool reversed,
  ) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi || clip.isReversed == reversed) return;
    await _undoManager.execute(
      SetClipReverseAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldReversed: clip.isReversed,
        newReversed: reversed,
        applyToState: (target, value) {
          target.isReversed = value;
          setState(() {});
        },
      ),
    );
    _recordProducerManualEdit('clip_reverse', {
      'clip': clipIndex,
      'reversed': reversed,
    });
  }

  double _tabletExpandedRightPanelWidthFor(double availableWidth) {
    return TabletDawPanelLayout.expandedRightPanelWidth(
      availableWidth: availableWidth,
      preferredRightPanelWidth: _tabletRightPanelWidthOverride,
    );
  }

  double _tabletReservedRightPanelWidthFor(
    double availableWidth, {
    required bool collapsed,
  }) {
    return TabletDawPanelLayout.reservedWidth(
      usesTabletDawLayout: true,
      collapsed: collapsed,
      availableWidth: availableWidth,
      preferredRightPanelWidth: _tabletRightPanelWidthOverride,
    );
  }

  void _resizeTabletRightPanelBy(double deltaDx, double availableWidth) {
    if (!mounted) return;
    final current = _tabletExpandedRightPanelWidthFor(availableWidth);
    final next = TabletDawPanelLayout.boundedPreferredRightPanelWidth(
      current - deltaDx,
    );
    setState(() {
      _tabletRightPanelWidthOverride = next;
      _tabletRightPanelCollapsed = false;
    });
  }

  bool _isLocalFilePath(String? path) {
    final trimmed = path?.trim();
    if (trimmed == null || trimmed.isEmpty) return false;
    return !trimmed.contains('://');
  }

  void _deleteContainedExportFileIfSafe(String? path) {
    if (!_isLocalFilePath(path)) return;
    try {
      final file = File(path!);
      if (file.existsSync()) {
        file.deleteSync();
      }
    } catch (_) {}
  }

  void _clearContainedExportPayload({bool deleteFiles = false}) {
    if (deleteFiles) {
      final previewPath = _containedExportPreviewFilePath;
      final exportPath = _containedExportFilePath;
      final savedPath = _containedExportSavedFilePath;
      if (previewPath != null &&
          previewPath != exportPath &&
          previewPath != savedPath) {
        _deleteContainedExportFileIfSafe(previewPath);
      }
      if (exportPath != null && exportPath != savedPath) {
        _deleteContainedExportFileIfSafe(exportPath);
      }
    }
    _containedExportFilePath = null;
    _containedExportPreviewFilePath = null;
    _containedExportSavedFilePath = null;
    _containedExportSavedFileName = null;
  }

  void _startContainedExportEllipsisTimer() {
    _containedExportEllipsisTimer?.cancel();
    _containedExportEllipsisTimer = Timer.periodic(
      const Duration(milliseconds: 500),
      (_) {
        if (!mounted ||
            _containedExportPanelStage !=
                _ContainedExportPanelStage.exporting) {
          return;
        }
        setState(() {
          _containedExportEllipsisStep = (_containedExportEllipsisStep + 1) % 3;
        });
      },
    );
  }

  void _stopContainedExportEllipsisTimer() {
    _containedExportEllipsisTimer?.cancel();
    _containedExportEllipsisTimer = null;
  }

  int _beginContainedExportProgress() {
    _clearContainedExportPayload(deleteFiles: true);
    final token = ++_containedExportRunToken;
    _cancelSignal = Completer();
    _containedExportCancelled = false;
    _containedExportEllipsisStep = 0;
    _startContainedExportEllipsisTimer();
    setState(() {
      _tabletRightPanelTab = 'export';
      _tabletRightPanelCollapsed = false;
      _containedExportPanelStage = _ContainedExportPanelStage.exporting;
      _containedExportProgress = 0.0;
    });
    return token;
  }

  Future<void> _letContainedExportProgressPaint() async {
    if (!mounted) return;
    await SchedulerBinding.instance.endOfFrame;
    if (!mounted) return;
    await Future<void>.delayed(const Duration(milliseconds: 80));
  }

  void _cancelContainedExportProgress() {
    _containedExportCancelled = true;
    if (!_cancelSignal.isCompleted) {
      _cancelSignal.complete();
    }
    _stopContainedExportEllipsisTimer();
    if (!mounted) return;
    setState(() {
      _containedExportPanelStage = _ContainedExportPanelStage.idle;
      _containedExportProgress = 0.0;
    });
  }

  void _scrubProjectTransport(double ms) {
    if (_isRecording) return;
    final clampedMs = math.max(0.0, ms);
    final newPosition = Duration(milliseconds: clampedMs.round());
    _syncTransportClock(newPosition, playing: _isPlaying);
    unawaited(JuceAudioEngine.seekTransport(clampedMs / 1000.0));
    JuceAudioEngine.setAutomationTransport(clampedMs / 1000.0);
    JuceAudioEngine.setMetronomeTransportMs(clampedMs);
  }

  void _selectTabletRightPanelTab(String tabId, {bool openPanel = true}) {
    if (!mounted) return;
    setState(() {
      _tabletRightPanelTab = tabId;
      if (tabId != 'fx') {
        _setMasterMeterExpandedState(false);
      }
      if (openPanel) {
        _tabletRightPanelCollapsed = false;
      }
    });
    if (_rowCount <= 0) return;
    final row = _selectedRow.clamp(0, _rowCount - 1).toInt();
    if (tabId == 'inspector') {
      _timelineController.ensureRowExpanded(row, tab: _tabletRowDetailTab);
    } else if (tabId == 'fx') {
      setState(() {
        _tabletRowDetailTab = 1;
      });
      _timelineController.ensureRowExpanded(row, tab: 1);
    }
  }

  void _openTabletExportPanel() {
    if (!mounted) return;
    setState(() {
      _tabletRightPanelTab = 'export';
      _tabletRightPanelCollapsed = false;
      _setMasterMeterExpandedState(false);
      if (_containedExportPanelStage != _ContainedExportPanelStage.success) {
        _containedExportPanelStage = _ContainedExportPanelStage.idle;
      }
    });
  }

  Duration _estimateTransportClockFromSample() {
    if (!_isPlaying) {
      return Duration(
        milliseconds: (_lastTransportSampleSeconds * 1000).round(),
      );
    }
    final elapsedSinceSample =
        _transportUiStopwatch.elapsed - _lastTransportSampleElapsed;
    final boundedElapsed = !_hasTimelineClips
        ? elapsedSinceSample
        : elapsedSinceSample > _kTransportMaxExtrapolation
        ? _kTransportMaxExtrapolation
        : elapsedSinceSample;
    final estimatedSeconds =
        _lastTransportSampleSeconds +
        (boundedElapsed.inMicroseconds / 1e6) * _transportRateSecPerSec;
    return Duration(milliseconds: (estimatedSeconds * 1000).round());
  }

  Future<void> _pollTransportFromJuceIfNeeded({
    bool force = false,
    int? commandSerial,
  }) async {
    if (_transportPollBusy) return;
    if (!force && _transportNativeCommandInFlight) return;
    final now = _transportUiStopwatch.elapsed;
    if (!force && now - _lastTransportPollElapsed < _kTransportPollInterval) {
      return;
    }
    if (_isPlaying && !_hasTimelineClips) {
      _lastTransportPollElapsed = now;
      _transportRateSecPerSec = 1.0;
      return;
    }
    _transportPollBusy = true;
    _lastTransportPollElapsed = now;
    final prevSampleSeconds = _lastTransportSampleSeconds;
    final prevSampleElapsed = _lastTransportSampleElapsed;
    final pollCommandSerial = commandSerial ?? _transportCommandSerial;
    try {
      final t = await JuceAudioEngine.getTransportSeconds();
      if (pollCommandSerial != _transportCommandSerial) return;
      final sampleElapsed = _transportUiStopwatch.elapsed;
      final wallDeltaUs = (sampleElapsed - prevSampleElapsed).inMicroseconds;
      if (wallDeltaUs > 0) {
        final measuredRate = ((t - prevSampleSeconds) / (wallDeltaUs / 1e6))
            .clamp(0.0, 2.0);
        if (_isPlaying) {
          if (measuredRate < 0.05) {
            _transportRateSecPerSec = 0.0;
          } else if (_transportRateSecPerSec <= 0.0) {
            _transportRateSecPerSec = measuredRate;
          } else {
            _transportRateSecPerSec =
                (_transportRateSecPerSec * 0.7) + (measuredRate * 0.3);
          }
        } else {
          _transportRateSecPerSec = 0.0;
        }
      }
      _lastTransportSampleSeconds = t;
      _lastTransportSampleElapsed = sampleElapsed;
      final suppressImmediateSnap =
          _isPlaying &&
          !force &&
          sampleElapsed < _transportPlayStartSyncGraceUntil;
      if (!suppressImmediateSnap) {
        _setGlobalAudioClock(Duration(milliseconds: (t * 1000.0).round()));
      }
    } catch (_) {
      // Ignore transient bridge errors; next poll will recover.
    } finally {
      _transportPollBusy = false;
    }
  }

  void _refreshFxUiForPlaybackTick() {
    if (!_isPlaying) return;
    final now = _transportUiStopwatch.elapsed;
    if (now - _lastFxPlaybackRefreshElapsed < _kFxPlaybackRefreshInterval) {
      return;
    }
    _lastFxPlaybackRefreshElapsed = now;
    _refreshMixAutomationUiForPlaybackTick(
      _globalAudioClock.inMilliseconds.toDouble(),
    );
    _refreshVisiblePluginAutomationUiForPlaybackTick(
      _globalAudioClock.inMilliseconds.toDouble(),
    );
    for (int row = 0; row < _rowCount; row++) {
      _refreshRowFxPlayback(row);
    }
    _tabletSelectedRowFxPlaybackRefresh?.call();
    _masterFxPlaybackRefresh?.call();
  }

  void _refreshRowFxUiForAutomatedEffectParameter({
    required int row,
    required int effectIndex,
  }) {
    _refreshRowFxPlayback(row);
    if (_tabletSelectedRowFxRow == row &&
        _tabletSelectedRowFxIndex == effectIndex) {
      _tabletSelectedRowFxPlaybackRefresh?.call();
    }
  }

  int _normalizedExpandedTab(int row) {
    if (row < 0 || row >= _rowExpandedTab.length) return 0;
    final tab = _rowExpandedTab[row];
    return (tab == 1 || tab == 2) ? tab : 0;
  }

  bool _isRowMixUiVisible(int row) {
    if (row < 0 || row >= _rowCount) return false;
    if (row >= _rowExpanded.length || !_rowExpanded[row]) return false;
    return _normalizedExpandedTab(row) == 0;
  }

  bool get _isMasterMixUiVisible =>
      _showMasterRack &&
      (_masterRackContentKey.currentState?.isVolumeTabVisible ?? true);

  void _refreshMixAutomationUiForPlaybackTick(double timeMs) {
    if (_rowCount <= 0) return;
    bool changed = false;

    for (int row = 0; row < _rowCount; row++) {
      if (!_isRowMixUiVisible(row)) continue;

      final rowGainTargetId = _rowMixAutomationTargetId('gain');
      if (_hasExplicitAutomationForTarget(row, rowGainTargetId)) {
        final target =
            _rowAutomationTargets[row]?[rowGainTargetId] ??
            _fallbackAutomationTargetMeta(rowGainTargetId);
        final normalized = _resolvedAutomationValueAtMs(
          row,
          rowGainTargetId,
          timeMs,
        ).clamp(0.0, 1.0);
        final value = _denormalizeAutomationValue(
          normalized,
          target,
        ).clamp(_kGainUiMin, _kGainUiMax).toDouble();
        if ((value - _rowGain[row]).abs() > 0.0005) {
          _rowGain[row] = value;
          changed = true;
        }
      }

      final rowPanTargetId = _rowMixAutomationTargetId('pan');
      if (_hasExplicitAutomationForTarget(row, rowPanTargetId)) {
        final target =
            _rowAutomationTargets[row]?[rowPanTargetId] ??
            _fallbackAutomationTargetMeta(rowPanTargetId);
        final normalized = _resolvedAutomationValueAtMs(
          row,
          rowPanTargetId,
          timeMs,
        ).clamp(0.0, 1.0);
        final value = _denormalizeAutomationValue(
          normalized,
          target,
        ).clamp(0.0, 1.0).toDouble();
        if ((value - _rowPan[row]).abs() > 0.0005) {
          _rowPan[row] = value;
          changed = true;
        }
      }
    }

    if (_isMasterMixUiVisible) {
      final masterGainTargetId = _masterMixAutomationTargetId('gain');
      if (_hasExplicitAutomationForTarget(0, masterGainTargetId)) {
        final target =
            _automationTargetMetaFromAnyRow(masterGainTargetId) ??
            _fallbackAutomationTargetMeta(masterGainTargetId);
        final normalized = _resolvedAutomationValueAtMs(
          0,
          masterGainTargetId,
          timeMs,
        ).clamp(0.0, 1.0);
        final value = _denormalizeAutomationValue(
          normalized,
          target,
        ).clamp(_kGainUiMin, _kGainUiMax).toDouble();
        if ((value - _masterGain).abs() > 0.0005) {
          _masterGain = value;
          changed = true;
        }
      }

      final masterPanTargetId = _masterMixAutomationTargetId('pan');
      if (_hasExplicitAutomationForTarget(0, masterPanTargetId)) {
        final target =
            _automationTargetMetaFromAnyRow(masterPanTargetId) ??
            _fallbackAutomationTargetMeta(masterPanTargetId);
        final normalized = _resolvedAutomationValueAtMs(
          0,
          masterPanTargetId,
          timeMs,
        ).clamp(0.0, 1.0);
        final value = _denormalizeAutomationValue(
          normalized,
          target,
        ).clamp(0.0, 1.0).toDouble();
        if ((value - _masterPan).abs() > 0.0005) {
          _masterPan = value;
          changed = true;
        }
      }
    }

    if (changed && mounted) {
      setState(() {});
    }
  }

  void _refreshVisiblePluginAutomationUiForPlaybackTick(double timeMs) {
    if (_visiblePluginAutomationUiSyncInFlight) return;
    final row = _tabletSelectedRowFxRow;
    final effectIndex = _tabletSelectedRowFxIndex;
    if (row == null ||
        effectIndex == null ||
        row < 0 ||
        row >= _rowCount ||
        effectIndex < 0) {
      return;
    }

    final targets =
        _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
    final visibleTargets = targets.entries
        .where((entry) {
          final target = entry.value;
          if (target.isOrphan || target.isVolume) return false;
          if (target.effectIndex != effectIndex) return false;
          if (target.paramId.trim().isEmpty) return false;
          final parsed = _parseAutomationTargetId(entry.key);
          return parsed.isEffectParameter &&
              !parsed.isMaster &&
              _hasExplicitAutomationForTarget(row, entry.key);
        })
        .toList(growable: false);
    if (visibleTargets.isEmpty) return;

    _visiblePluginAutomationUiSyncInFlight = true;
    unawaited(() async {
      var changed = false;
      try {
        for (final entry in visibleTargets) {
          final targetId = entry.key;
          final target = entry.value;
          final normalized = _resolvedAutomationValueAtMs(
            row,
            targetId,
            timeMs,
          ).clamp(0.0, 1.0).toDouble();
          final last = _lastAppliedAutomationNormalized['$row|$targetId'];
          if (last != null && (last - normalized).abs() < 0.0005) {
            continue;
          }
          final value = _denormalizeAutomationValue(normalized, target);
          await JuceAudioEngine.setTrackEffect(
            row,
            effectIndex,
            target.paramId,
            value,
          );
          _lastAppliedAutomationNormalized['$row|$targetId'] = normalized;
          changed = true;
        }
        if (changed) {
          _refreshRowFxUiForAutomatedEffectParameter(
            row: row,
            effectIndex: effectIndex,
          );
        }
      } catch (_) {
        // Playback UI mirroring is best-effort; native automation remains active.
      } finally {
        _visiblePluginAutomationUiSyncInFlight = false;
      }
    }());
  }

