  int get _rowCount => _rows.length;

  int _rowIdAt(int rowIndex) {
    if (rowIndex < 0 || rowIndex >= _rows.length) return -1;
    return _rows[rowIndex].rowId;
  }

  int _rowIndexForId(int rowId) {
    return _rows.indexWhere((r) => r.rowId == rowId);
  }

  String _automationDiscoverySignature(List<List<String>> parts) {
    final buffer = StringBuffer();
    for (final group in parts) {
      for (final item in group) {
        buffer
          ..write(item.trim())
          ..write('\u0001');
      }
      buffer.write('\u0002');
    }
    return buffer.toString();
  }

  List<_DiscoveredAutomationTarget> _cloneDiscoveredAutomationTargets(
    List<_DiscoveredAutomationTarget> source,
  ) {
    return source
        .map(
          (entry) => _DiscoveredAutomationTarget(
            meta: entry.meta.copyWith(),
            scope: entry.scope,
            effectKey: entry.effectKey,
          ),
        )
        .toList(growable: false);
  }

  void _pruneAutomationDiscoveryCaches() {
    final validRowIds = _rows.map((row) => row.rowId).toSet();
    _rowAutomationDiscoveryCache.removeWhere(
      (rowId, _) => !validRowIds.contains(rowId),
    );
  }

  void _invalidateRowAutomationDiscoveryCache(
    int row, {
    bool includeMaster = false,
  }) {
    final rowId = _rowIdAt(row);
    if (rowId >= 0) {
      _rowAutomationDiscoveryCache.remove(rowId);
    }
    if (includeMaster) {
      _masterAutomationDiscoveryCache = null;
    }
  }

  void _invalidateAllRowAutomationDiscoveryCaches({
    bool includeMaster = false,
  }) {
    _rowAutomationDiscoveryCache.clear();
    if (includeMaster) {
      _masterAutomationDiscoveryCache = null;
    }
  }

  String _rowDisplayName(int row) {
    final trackPrefix = L10n.translate(context, 'Track');
    if (row < 0 || row >= _rows.length) {
      return '$trackPrefix ${row + 1}';
    }
    final name = _rows[row].name.trim();
    return name.isEmpty ? '$trackPrefix ${row + 1}' : name;
  }

  String _mixerDisplayNameForRow(int row) {
    final group = _trackGroupForLeadRowIndex(row);
    if (group != null) {
      final name = group.name.trim();
      if (name.isNotEmpty) return name;
    }
    return _rowDisplayName(row);
  }

  int _allocateEngineClipId() {
    final usedIds = Set<int>.from(_reservedEngineClipIds);
    for (final track in _audioTracks) {
      if (track.engineClipId >= 0) {
        usedIds.add(track.engineClipId);
      }
    }
    for (int id = 0; id < kNumClips; id++) {
      if (!usedIds.contains(id)) {
        _reservedEngineClipIds.add(id);
        return id;
      }
    }
    return -1;
  }

  int _reserveEngineClipId() {
    return _allocateEngineClipId();
  }

  void _releaseReservedEngineClipId(int engineClipId) {
    if (engineClipId >= 0) {
      _reservedEngineClipIds.remove(engineClipId);
    }
  }

  Future<T> _enqueueClipPaste<T>(Future<T> Function() task) {
    final next = _clipPasteQueue.then((_) => task());
    _clipPasteQueue = next.then<void>((_) {}).catchError((_) {});
    return next;
  }

  void _handleChatTextChanged() {
    final hasText = _chatTextController.text.trim().isNotEmpty;
    if (_chatHasText == hasText || !mounted) return;
    setState(() {
      _chatHasText = hasText;
    });
  }

  void _handleChatFocusChanged() {
    if (!mounted) return;
    final hasFocus = _chatFocusNode.hasFocus;
    if (_chatInputActive == hasFocus) return;
    setState(() {
      _chatInputActive = hasFocus;
    });
    _setDawPanelVisible('chat_input', hasFocus);
  }

  String? _topPopupPanelId(_TopPopupType popupType) {
    switch (popupType) {
      case _TopPopupType.projectSettings:
        return 'project_settings';
      case _TopPopupType.tempo:
        return 'tempo_popup';
      case _TopPopupType.master:
        return 'master_rack';
      case _TopPopupType.none:
        return null;
    }
  }

  void _setActiveTopPopup(_TopPopupType popupType) {
    final previousPanelId = _topPopupPanelId(_activeTopPopup);
    final previousPopup = _activeTopPopup;
    final nextPanelId = _topPopupPanelId(popupType);
    if (previousPanelId != null && previousPanelId != nextPanelId) {
      _setDawPanelVisible(previousPanelId, false);
    }
    _activeTopPopup = popupType;
    if (previousPopup == _TopPopupType.master &&
        popupType != _TopPopupType.master) {
      _timelineController.closeMasterAutomationLane();
    }
    if (nextPanelId != null && nextPanelId != previousPanelId) {
      _setDawPanelVisible(nextPanelId, true);
    }
  }

  void _setDawPanelVisible(String panelId, bool visible) {
    final normalizedPanelId = panelId.trim();
    if (normalizedPanelId.isEmpty) return;
    final openedAt = _dawPanelOpenedAt[normalizedPanelId];
    if (visible) {
      if (openedAt != null) return;
      _dawPanelOpenedAt[normalizedPanelId] = DateTime.now().toUtc();
      unawaited(
        AnalyticsService.instance.track(
          AnalyticsEvents.dawPanelOpened(
            panelId: normalizedPanelId,
            projectId: _projectId,
          ),
        ),
      );
      return;
    }

    if (openedAt == null) return;
    _dawPanelOpenedAt.remove(normalizedPanelId);
    final durationMs = DateTime.now()
        .toUtc()
        .difference(openedAt)
        .inMilliseconds;
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.dawPanelClosed(
          panelId: normalizedPanelId,
          durationMs: math.max(durationMs, 0),
          projectId: _projectId,
        ),
      ),
    );
  }

  Object? _analyticsPropertyValue(Object? value) {
    if (value == null) return null;
    if (value is num) {
      return double.parse(value.toStringAsFixed(4));
    }
    if (value is bool) return value;
    final text = value.toString().trim();
    return text.isEmpty ? null : text;
  }

  void _trackUiClick({
    required String controlId,
    required String surface,
    String controlType = 'button',
    Object? value,
    Map<String, Object?> extra = const <String, Object?>{},
  }) {
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.uiClick(
          controlId: controlId,
          surface: surface,
          controlType: controlType,
          projectId: _projectId,
          value: _analyticsPropertyValue(value),
          extra: extra,
        ),
      ),
    );
  }

  String _aiToolFamily(String toolName) {
    final normalized = toolName.trim().toLowerCase();
    switch (normalized) {
      case 'mix_model_request':
        return 'mix_assistant';
      case 'daw_assistant_actions':
        return 'daw_assistant';
      case 'informational_response':
        return 'informational';
      default:
        return normalized.isEmpty ? 'unknown' : normalized;
    }
  }

  List<String> _uniqueSortedActionTypes(Iterable<String> actionTypes) {
    final normalized =
        actionTypes
            .map((type) => type.trim().toLowerCase())
            .where((type) => type.isNotEmpty)
            .toSet()
            .toList(growable: false)
          ..sort();
    return normalized;
  }

  String? _primaryActionType(List<String> actionTypes) {
    return actionTypes.isEmpty ? null : actionTypes.first;
  }

  String? _toolVariantForAnalytics(String toolName, List<String> actionTypes) {
    final normalizedTool = toolName.trim().toLowerCase();
    if (normalizedTool.isEmpty) return null;
    if (actionTypes.isEmpty) return normalizedTool;
    if (actionTypes.length == 1) return actionTypes.first;
    return 'multi_action';
  }

  String _newAssistantConversationSessionId() {
    final timestamp = DateTime.now().microsecondsSinceEpoch;
    final random = math.Random().nextInt(0x7fffffff).toRadixString(16);
    return 'assistant_chat_${timestamp}_$random';
  }

  String _ensureAssistantConversationSessionId() {
    final existing = _assistantConversationSessionId.trim();
    if (existing.isNotEmpty) return existing;
    _assistantConversationSessionId = _newAssistantConversationSessionId();
    return _assistantConversationSessionId;
  }

  void _rotateAssistantConversationSessionId() {
    _assistantConversationSessionId = _newAssistantConversationSessionId();
  }

  void _trackAiToolUsage({
    required String toolName,
    required String aiFeature,
    required String promptTraceId,
    List<String> actionTypes = const <String>[],
  }) {
    final normalizedToolName = toolName.trim();
    if (normalizedToolName.isEmpty) return;
    final normalizedActionTypes = _uniqueSortedActionTypes(actionTypes);
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.aiToolCalled(
          toolName: normalizedToolName,
          projectId: _projectId,
          aiFeature: aiFeature,
          toolFamily: _aiToolFamily(normalizedToolName),
          toolVariant: _toolVariantForAnalytics(
            normalizedToolName,
            normalizedActionTypes,
          ),
          primaryActionType: _primaryActionType(normalizedActionTypes),
          actionTypes: normalizedActionTypes.isEmpty
              ? null
              : normalizedActionTypes.join(','),
          actionCount: normalizedActionTypes.isEmpty
              ? null
              : normalizedActionTypes.length,
          producerCaptureEnabled: _producerDataMode,
          promptTraceId: promptTraceId,
        ),
      ),
    );
  }

  void _trackPluginInserted({
    required String pluginName,
    required String scope,
    int? rowIndex,
  }) {
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.pluginInserted(
          pluginName: pluginName,
          scope: scope,
          projectId: _projectId,
          rowIndex: rowIndex,
        ),
      ),
    );
  }

  void _trackPluginRemoved({
    required String pluginName,
    required String scope,
    int? rowIndex,
  }) {
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.pluginRemoved(
          pluginName: pluginName,
          scope: scope,
          projectId: _projectId,
          rowIndex: rowIndex,
        ),
      ),
    );
  }

  Future<void> _trackPluginParameterCommitted({
    required String scope,
    required String paramId,
    required Object? oldValue,
    required Object? newValue,
    int? rowIndex,
    int? effectIndex,
  }) async {
    try {
      String pluginName = '';
      if (scope == 'track' && rowIndex != null && effectIndex != null) {
        final names = await JuceAudioEngine.getTrackEffectsForRow(rowIndex);
        if (effectIndex >= 0 && effectIndex < names.length) {
          pluginName = names[effectIndex];
        }
      } else if (scope == 'master' && effectIndex != null) {
        final names = await JuceAudioEngine.getMasterEffects();
        if (effectIndex >= 0 && effectIndex < names.length) {
          pluginName = names[effectIndex];
        }
      }
      unawaited(
        AnalyticsService.instance.track(
          AnalyticsEvents.pluginParameterCommitted(
            pluginName: pluginName.isEmpty ? 'unknown_plugin' : pluginName,
            paramId: paramId,
            scope: scope,
            projectId: _projectId,
            rowIndex: rowIndex,
            oldValue: _analyticsPropertyValue(oldValue),
            newValue: _analyticsPropertyValue(newValue),
          ),
        ),
      );
    } catch (_) {}
  }

  Map<String, dynamic> _buildProjectTelemetrySnapshot(
    Map<String, dynamic> projectJson,
  ) {
    final tracks =
        (projectJson['tracks'] as List?)?.whereType<Map>().toList(
          growable: false,
        ) ??
        const <Map>[];
    final rowEffects =
        (projectJson['rowEffects'] as List?)?.whereType<Map>().toList(
          growable: false,
        ) ??
        const <Map>[];
    final master = projectJson['master'];
    final masterEffectsRaw = master is Map ? master['effects'] : null;
    final masterEffects = master is Map
        ? (masterEffectsRaw is List
              ? masterEffectsRaw.whereType<Map>().toList(growable: false)
              : masterEffectsRaw is Map
              ? (masterEffectsRaw['effects'] as List?)?.whereType<Map>().toList(
                      growable: false,
                    ) ??
                    const <Map>[]
              : const <Map>[])
        : const <Map>[];
    final assistantChat = projectJson['assistantChat'];

    final instrumentIds =
        tracks
            .map((track) => (track['instrumentId'] ?? '').toString().trim())
            .where((value) => value.isNotEmpty)
            .toSet()
            .toList(growable: false)
          ..sort();
    final trackEffectIds = rowEffects
        .expand(
          (row) => ((row['effects'] as List?) ?? const <Object?>[])
              .whereType<Map>()
              .map((fx) => (fx['effectId'] ?? '').toString().trim()),
        )
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    final masterEffectIds = masterEffects
        .map((fx) => (fx['effectId'] ?? '').toString().trim())
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    final chatMessages = assistantChat is List
        ? assistantChat.whereType<Map>().length
        : 0;

    return <String, dynamic>{
      'captured_at': DateTime.now().toUtc().toIso8601String(),
      'tempo_bpm': projectJson['tempoBpm'],
      'row_count': (projectJson['rows'] as List?)?.length ?? _rows.length,
      'track_count': tracks.length,
      'instrument_ids': instrumentIds,
      'track_effect_ids': trackEffectIds,
      'master_effect_ids': masterEffectIds,
      'has_assistant_chat': assistantChat != null,
      'assistant_message_count': chatMessages,
      'producer_capture_enabled': _showProducerCaptureUi,
    };
  }

  Map<String, dynamic> _buildFeedbackProjectSettings() {
    final selectedClip =
        (_timelinePrimarySelectedClipIndex >= 0 &&
            _timelinePrimarySelectedClipIndex < _audioTracks.length)
        ? _audioTracks[_timelinePrimarySelectedClipIndex]
        : null;
    final visibleRowNames = _rows
        .take(12)
        .map((row) => row.name.trim())
        .where((name) => name.isNotEmpty)
        .toList(growable: false);
    return <String, dynamic>{
      'project_id': _projectId,
      'project_name': _projectName,
      'mode': _resolvedMode,
      'tempo_bpm': _tempo,
      'metronome_enabled': _metronomeEnabled,
      'loop_enabled': _loopEnabled,
      if (_loopEnabled) 'loop_start_ms': _loopStartMs,
      if (_loopEnabled) 'loop_end_ms': _loopEndMs,
      'row_count': _rows.length,
      'track_count': _audioTracks.length,
      'selected_row_index': _selectedRow,
      if (selectedClip != null) 'selected_clip_label': selectedClip.label,
      if (_producerCaptureAllowlistUsername.isNotEmpty)
        'producer_capture_allowlist_username':
            _producerCaptureAllowlistUsername,
      'producer_capture_enabled':
          _isProducerCaptureUiVisible || _producerDataMode,
      'sample_browser_open': _sampleBrowserVisible,
      'master_rack_open': _showMasterRack,
      if (visibleRowNames.isNotEmpty) 'row_names': visibleRowNames,
    };
  }

  List<String> _visibleAiRowNames() {
    return _rows.map((row) => row.name.trim()).toList(growable: false);
  }

  List<TimelineRow> _visibleAiRows() {
    return _rows.map(_cloneTimelineRow).toList(growable: false);
  }

  TimelineRow _cloneTimelineRow(TimelineRow row) {
    return TimelineRow(
      rowId: row.rowId,
      name: row.name,
      iconId: row.iconId,
      kind: row.kind,
      instrumentId: row.instrumentId,
      instrumentName: row.instrumentName,
      instrumentParams: Map<String, double>.from(row.instrumentParams),
      hostedInstrumentStateBase64: row.hostedInstrumentStateBase64,
      roleOverride: row.roleOverride,
      groupId: row.groupId,
      color: row.color,
      inputDeviceName: row.inputDeviceName,
      inputChannelStart: row.inputChannelStart,
      inputChannelCount: row.inputChannelCount,
    );
  }

  TrackGroup _cloneTrackGroup(TrackGroup group) {
    return cloneTrackGroupForGroupReconcile(group);
  }

  int _deriveTrackGroupColorFromRows(
    Iterable<int> rowIds,
    List<TimelineRow> rows,
  ) {
    final rowIdSet = rowIds.toSet();
    for (final row in rows) {
      if (rowIdSet.contains(row.rowId) && row.color != 0) {
        return row.color;
      }
    }
    return 0;
  }

  TrackGroup _trackGroupWithColor(TrackGroup group, int color) {
    return TrackGroup(
      id: group.id,
      name: group.name,
      color: color,
      rowIds: group.rowIds,
      gain: group.gain,
      pan: group.pan,
      muted: group.muted,
      soloed: group.soloed,
      collapsed: group.collapsed,
      effects: group.effects,
    );
  }

  void _syncTrackGroupColorsFromRows(List<TimelineRow> rows) {
    if (_trackGroups.isEmpty) return;
    var changed = false;
    final nextGroups = _trackGroups
        .map((group) {
          final color = _deriveTrackGroupColorFromRows(group.rowIds, rows);
          if (group.color == color) return _cloneTrackGroup(group);
          changed = true;
          return _trackGroupWithColor(group, color);
        })
        .toList(growable: false);
    if (!changed) return;
    _trackGroups
      ..clear()
      ..addAll(nextGroups);
  }

  List<TimelineRow> _sanitizeTrackGroupsForRows(List<TimelineRow> rows) {
    final reconciled = reconcileTrackGroupsForRows(
      rows: rows,
      groups: _trackGroups,
    );
    _trackGroups
      ..clear()
      ..addAll(reconciled.groups);
    return reconciled.rows;
  }

  List<TrackGroup> _trackGroupsFromProjectJson(Map<String, dynamic> json) {
    final rawGroups = json["trackGroups"] ?? json["track_groups"];
    if (rawGroups is! List) return const <TrackGroup>[];
    return rawGroups
        .whereType<Map>()
        .map((e) => TrackGroupJson.fromJson(e.cast<String, dynamic>()))
        .where((group) => group.id.trim().isNotEmpty)
        .toList(growable: false);
  }

  List<TrackGroup> _deriveTrackGroupsFromRows(List<TimelineRow> rows) {
    final rowIdsByGroupId = <String, List<int>>{};
    for (final row in rows) {
      final groupId = row.groupId.trim();
      if (groupId.isEmpty || row.rowId < 0) continue;
      rowIdsByGroupId.putIfAbsent(groupId, () => <int>[]).add(row.rowId);
    }
    if (rowIdsByGroupId.isEmpty) return const <TrackGroup>[];
    final groups = <TrackGroup>[];
    for (final entry in rowIdsByGroupId.entries) {
      if (entry.value.length < 2) continue;
      groups.add(
        TrackGroup(
          id: entry.key,
          name: 'Group',
          rowIds: List<int>.from(entry.value, growable: false),
        ),
      );
    }
    return groups;
  }

  void _seedMissingTrackGroupsFromRows(List<TimelineRow> rows) {
    if (_trackGroups.isNotEmpty) return;
    final groups = _deriveTrackGroupsFromRows(rows);
    if (groups.isEmpty) return;
    _trackGroups
      ..clear()
      ..addAll(groups);
  }

  List<int> _trackGroupControlRowsFor(int row) {
    return resolveTrackGroupControlRowIndices(
      rows: _rows,
      groups: _trackGroups,
      sourceIndex: row,
    ).where((item) => item >= 0 && item < _rowCount).toList(growable: false);
  }

  int _trackGroupLeadRowIndex(TrackGroup group) {
    if (group.rowIds.isEmpty) return -1;
    final leadRowId = group.rowIds.first;
    return _rows.indexWhere((row) => row.rowId == leadRowId);
  }

  TrackGroup? _trackGroupForLeadRowIndex(int row) {
    if (!_isValidRowIndex(row)) return null;
    final rowId = _rows[row].rowId;
    for (final group in _trackGroups) {
      if (group.rowIds.isNotEmpty && group.rowIds.first == rowId) {
        return group;
      }
    }
    return null;
  }

  TrackGroup? _trackGroupById(String groupId) {
    final normalized = groupId.trim();
    if (normalized.isEmpty) return null;
    for (final group in _trackGroups) {
      if (group.id == normalized) return group;
    }
    return null;
  }

  int? _trackGroupLeadRowIndexForId(String groupId) {
    final group = _trackGroupById(groupId);
    if (group == null) return null;
    final leadIndex = _trackGroupLeadRowIndex(group);
    return _isValidRowIndex(leadIndex) ? leadIndex : null;
  }

  String _trackGroupDisplayName(String groupId) {
    final group = _trackGroupById(groupId);
    final name = group?.name.trim() ?? '';
    return name.isEmpty ? 'Group Bus' : '$name Group Bus';
  }

  Future<List<TrackGroup>> _trackGroupsForAiProjectState() async {
    final groups = <TrackGroup>[];
    for (final group in _trackGroups) {
      var effects = group.effects;
      final leadIndex = _trackGroupLeadRowIndex(group);
      if (_isValidRowIndex(leadIndex)) {
        try {
          final snapshot = await captureRowSnapshot(
            leadIndex,
            rowId: _rowIdAt(leadIndex),
          );
          effects = snapshot.effects;
        } catch (error) {
          debugPrint('AI group FX snapshot failed for ${group.id}: $error');
        }
      }
      groups.add(
        TrackGroup(
          id: group.id,
          name: group.name,
          color: group.color,
          rowIds: List<int>.from(group.rowIds),
          gain: group.gain,
          pan: group.pan,
          muted: group.muted,
          soloed: group.soloed,
          collapsed: group.collapsed,
          effects: effects,
        ),
      );
    }
    return groups;
  }

  void _applyTrackGroupMuteSoloState(
    String groupId, {
    bool? muted,
    bool? soloed,
  }) {
    final nextGroups = _trackGroups
        .map((group) {
          if (group.id != groupId) return _cloneTrackGroup(group);
          return TrackGroup(
            id: group.id,
            name: group.name,
            color: group.color,
            rowIds: List<int>.from(group.rowIds),
            gain: group.gain,
            pan: group.pan,
            muted: muted ?? group.muted,
            soloed: soloed ?? group.soloed,
            collapsed: group.collapsed,
            effects: group.effects,
          );
        })
        .toList(growable: false);
    setState(() {
      _trackGroups
        ..clear()
        ..addAll(nextGroups);
    });
  }

  Future<void> _setTrackGroupMuteSoloNative(
    String groupId, {
    bool? muted,
    bool? soloed,
  }) async {
    final group = _trackGroups.firstWhere(
      (item) => item.id == groupId,
      orElse: () => TrackGroup(id: groupId, name: groupId),
    );
    await JuceAudioEngine.setTrackGroupMixState(
      groupId: group.id,
      gain: group.gain,
      pan: group.pan,
      muted: muted ?? group.muted,
      soloed: soloed ?? group.soloed,
    );
  }

  void _applyTrackGroupGainState(String groupId, double gain) {
    final safeGain = gain.clamp(_kGainUiMin, _kGainUiMax).toDouble();
    final nextGroups = _trackGroups
        .map((group) {
          if (group.id != groupId) return _cloneTrackGroup(group);
          return TrackGroup(
            id: group.id,
            name: group.name,
            color: group.color,
            rowIds: List<int>.from(group.rowIds),
            gain: safeGain,
            pan: group.pan,
            muted: group.muted,
            soloed: group.soloed,
            collapsed: group.collapsed,
            effects: group.effects,
          );
        })
        .toList(growable: false);
    setState(() {
      _trackGroups
        ..clear()
        ..addAll(nextGroups);
      final group = _trackGroups.firstWhere(
        (item) => item.id == groupId,
        orElse: () => TrackGroup(id: groupId, name: groupId),
      );
      final leadIndex = _trackGroupLeadRowIndex(group);
      if (_isValidRowIndex(leadIndex)) _rowGain[leadIndex] = safeGain;
    });
  }

