  Future<void> _syncTrackGroupsToEngine() async {
    final groups = _trackGroups
        .map(
          (group) => <String, dynamic>{
            'id': group.id,
            'rowIds': group.rowIds,
            'gain': group.gain,
            'pan': group.pan,
            'muted': group.muted,
            'soloed': group.soloed,
          },
        )
        .toList(growable: false);
    final signature = jsonEncode(groups);
    if (signature == _lastNativeTrackGroupSignature) return;
    await JuceAudioEngine.configureTrackGroups(groups);
    _lastNativeTrackGroupSignature = signature;
  }

  TimelineRow _timelineRowFromJson(Map<String, dynamic> map) {
    final rawParams =
        (map['instrumentParams'] as Map?)?.cast<String, dynamic>() ??
        const <String, dynamic>{};
    final params = <String, double>{};
    for (final entry in rawParams.entries) {
      final value = entry.value;
      if (value is num) params[entry.key] = value.toDouble();
    }
    return TimelineRow(
      rowId: (map['rowId'] as num?)?.toInt() ?? -1,
      name: (map['name'] as String?) ?? '',
      iconId: (map['iconId'] as num?)?.toInt() ?? 0,
      kind: TimelineRowKind.fromWire(map['kind'] as String?),
      instrumentId: (map['instrumentId'] as String?)?.trim() ?? '',
      instrumentName: (map['instrumentName'] as String?)?.trim() ?? '',
      instrumentParams: params,
      hostedInstrumentStateBase64:
          ((map['hostedInstrumentStateB64'] as String?) ??
                  (map['hostedInstrumentStateBase64'] as String?) ??
                  '')
              .trim(),
      roleOverride: (map['roleOverride'] as String?)?.trim() ?? '',
      groupId: (map['groupId'] as String?)?.trim() ?? '',
      color: (map['color'] as num?)?.toInt() ?? 0,
      inputDeviceName: (map['inputDeviceName'] as String?)?.trim() ?? '',
      inputChannelStart: ((map['inputChannelStart'] as num?)?.toInt() ?? 0)
          .clamp(0, 999),
      inputChannelCount: ((map['inputChannelCount'] as num?)?.toInt() ?? 1)
          .clamp(1, 999),
    );
  }

  Map<String, dynamic> _timelineRowToJson(TimelineRow row) {
    return <String, dynamic>{
      'rowId': row.rowId,
      'name': row.name,
      'iconId': row.iconId,
      'kind': row.kind.wireName,
      if (row.isInstrumentLane) ...<String, dynamic>{
        'instrumentId': row.instrumentId,
        'instrumentName': row.instrumentName,
        'instrumentParams': row.instrumentParams,
        if (row.hostedInstrumentStateBase64.trim().isNotEmpty)
          'hostedInstrumentStateB64': row.hostedInstrumentStateBase64.trim(),
      },
      if (row.roleOverride.isNotEmpty) 'roleOverride': row.roleOverride,
      if (row.groupId.trim().isNotEmpty) 'groupId': row.groupId.trim(),
      if (row.color != 0) 'color': row.color,
      if (row.inputDeviceName.trim().isNotEmpty)
        'inputDeviceName': row.inputDeviceName.trim(),
      'inputChannelStart': row.inputChannelStart,
      'inputChannelCount': row.inputChannelCount,
    };
  }

  bool _rowAllowsClipKind(int row, ClipKind clipKind) {
    if (row < 0 || row >= _rows.length) return false;
    final timelineRow = _rows[row];
    if (timelineRow.isInstrumentLane) return clipKind == ClipKind.midi;
    return clipKind == ClipKind.audio;
  }

  Future<int> _ensureInstrumentLaneForMidiClip({
    required int row,
    required String instrumentId,
    required String instrumentName,
    required Map<String, double> instrumentParams,
  }) async {
    await _ensureRowIndexExists(row);
    await _ensureRowExistsForClipInsertion();
    if (_rowCount == 0) return 0;
    var safeRow = row.clamp(0, _rowCount - 1).toInt();
    final current = _rows[safeRow];
    if (current.isInstrumentLane) {
      final currentInstrumentId = current.instrumentId.trim();
      final nextInstrumentId = instrumentId.trim();
      final compatibleInstrument =
          currentInstrumentId.isEmpty ||
          nextInstrumentId.isEmpty ||
          currentInstrumentId == nextInstrumentId;
      final rowId = current.rowId;
      final hasLaneClips = _audioTracks.any((clip) {
        return (rowId >= 0 && clip.rowId == rowId) || clip.rowIndex == safeRow;
      });
      if (compatibleInstrument || !hasLaneClips) {
        final nextRows = List<TimelineRow>.from(_rows);
        final preserveHostedState =
            currentInstrumentId.isNotEmpty &&
            nextInstrumentId.isNotEmpty &&
            _liveMidiEngineInstrumentId(currentInstrumentId) ==
                _liveMidiEngineInstrumentId(nextInstrumentId);
        nextRows[safeRow] = current.copyWith(
          instrumentId: instrumentId,
          instrumentName: instrumentName,
          instrumentParams: instrumentParams,
          hostedInstrumentStateBase64: preserveHostedState
              ? current.hostedInstrumentStateBase64
              : '',
        );
        await _applyRowsToEditorState(
          nextRows,
          refreshAutomationTargets: false,
          syncClipRows: false,
        );
        return safeRow;
      }

      if (_rowCount >= _effectiveMaxRows) {
        _showRowLimitReachedNotice();
        return -1;
      }
      final lane = TimelineRow(
        rowId: -1,
        name: instrumentName.isEmpty ? 'Instrument' : instrumentName,
        iconId: 1,
        kind: TimelineRowKind.instrument,
        instrumentId: instrumentId,
        instrumentName: instrumentName,
        instrumentParams: instrumentParams,
      );
      final newRowId = await JuceAudioEngine.insertRowBelow(
        current.rowId,
        lane.name,
        iconId: lane.iconId,
      );
      if (newRowId < 0) return -1;
      final nextRows = List<TimelineRow>.from(_rows)
        ..insert(safeRow + 1, lane.copyWith(rowId: newRowId));
      await _applyRowsToEditorState(
        nextRows,
        refreshAutomationTargets: false,
        syncClipRows: true,
      );
      return safeRow + 1;
    }

    final rowId = current.rowId;
    final hasClips = _audioTracks.any((clip) {
      return (rowId >= 0 && clip.rowId == rowId) || clip.rowIndex == safeRow;
    });
    final lane = current.copyWith(
      name: instrumentName.isEmpty ? 'Instrument' : instrumentName,
      iconId: 1,
      kind: TimelineRowKind.instrument,
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      instrumentParams: instrumentParams,
      hostedInstrumentStateBase64: '',
    );
    if (!hasClips) {
      await JuceAudioEngine.renameRow(current.rowId, lane.name);
      await JuceAudioEngine.setRowIcon(current.rowId, lane.iconId);
      final nextRows = List<TimelineRow>.from(_rows);
      nextRows[safeRow] = lane;
      await _applyRowsToEditorState(
        nextRows,
        refreshAutomationTargets: false,
        syncClipRows: false,
      );
      return safeRow;
    }

    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return -1;
    }
    final newRowId = await JuceAudioEngine.insertRowBelow(
      current.rowId,
      lane.name,
      iconId: lane.iconId,
    );
    if (newRowId < 0) return -1;
    final nextRows = List<TimelineRow>.from(_rows)
      ..insert(safeRow + 1, lane.copyWith(rowId: newRowId));
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: false,
      syncClipRows: true,
    );
    return safeRow + 1;
  }

  bool _isLegacyProjectWithoutExplicitLaneKinds(
    List<Map<String, dynamic>> rowsJson,
  ) {
    return rowsJson.every((row) => !row.containsKey('kind'));
  }

  bool _migrateLegacyInstrumentRows(
    List<Map<String, dynamic>> rowsJson,
    List tracks,
  ) {
    if (!_isLegacyProjectWithoutExplicitLaneKinds(rowsJson)) return false;

    final tracksByOriginalRow = <int, List<Map<String, dynamic>>>{};
    for (final raw in tracks) {
      if (raw is! Map) continue;
      final track = raw.cast<String, dynamic>();
      final row = (track['rowIndex'] as num?)?.toInt() ?? 0;
      tracksByOriginalRow
          .putIfAbsent(row, () => <Map<String, dynamic>>[])
          .add(track);
    }

    final maxOriginalRow = tracksByOriginalRow.keys.isEmpty
        ? -1
        : tracksByOriginalRow.keys.fold<int>(
            -1,
            (maxRow, row) => math.max(maxRow, row),
          );
    final sourceRows = rowsJson.isEmpty
        ? List<Map<String, dynamic>>.generate(
            math.max(1, maxOriginalRow + 1),
            (index) => <String, dynamic>{
              'rowId': -1,
              'name': 'Track ${index + 1}',
              'iconId': 0,
            },
          )
        : rowsJson.map((row) => Map<String, dynamic>.from(row)).toList();

    final migratedRows = <Map<String, dynamic>>[];
    var changed = false;
    for (var sourceIndex = 0; sourceIndex < sourceRows.length; sourceIndex++) {
      final rowTracks =
          tracksByOriginalRow[sourceIndex] ?? const <Map<String, dynamic>>[];
      final audioTracks = rowTracks
          .where((track) {
            return ClipKindWire.fromWire(
                  (track['clipType'] as String?) ?? 'audio',
                ) !=
                ClipKind.midi;
          })
          .toList(growable: false);
      final midiTracks = rowTracks
          .where((track) {
            return ClipKindWire.fromWire(
                  (track['clipType'] as String?) ?? 'audio',
                ) ==
                ClipKind.midi;
          })
          .toList(growable: false);

      final sourceRow = Map<String, dynamic>.from(sourceRows[sourceIndex]);
      sourceRow['kind'] = 'audio';
      if (midiTracks.isNotEmpty && audioTracks.isEmpty) {
        final first = midiTracks.first;
        sourceRow['kind'] = 'instrument';
        sourceRow['instrumentId'] = (first['instrumentId'] ?? '').toString();
        sourceRow['instrumentName'] =
            ((first['instrumentName'] ?? '').toString().trim().isNotEmpty)
            ? first['instrumentName'].toString()
            : _instrumentNameFromId((first['instrumentId'] ?? '').toString());
        sourceRow['instrumentParams'] =
            (first['instrumentParams'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};
        final hostedState =
            ((first['hostedInstrumentStateB64'] as String?) ??
                    (first['hostedInstrumentStateBase64'] as String?) ??
                    '')
                .trim();
        if (hostedState.isNotEmpty) {
          sourceRow['hostedInstrumentStateB64'] = hostedState;
        }
      }
      migratedRows.add(sourceRow);

      if (midiTracks.isNotEmpty && audioTracks.isNotEmpty) {
        changed = true;
        for (final midiTrack in midiTracks) {
          final migratedRowIndex = migratedRows.length;
          final instrumentId = (midiTrack['instrumentId'] ?? '').toString();
          final instrumentName =
              ((midiTrack['instrumentName'] ?? '').toString().trim().isNotEmpty)
              ? midiTrack['instrumentName'].toString()
              : _instrumentNameFromId(instrumentId);
          migratedRows.add(<String, dynamic>{
            'rowId': -1,
            'name': instrumentName.isEmpty ? 'Instrument' : instrumentName,
            'iconId': 1,
            'kind': 'instrument',
            'instrumentId': instrumentId,
            'instrumentName': instrumentName,
            'instrumentParams':
                (midiTrack['instrumentParams'] as Map?)
                    ?.cast<String, dynamic>() ??
                const <String, dynamic>{},
            if ((((midiTrack['hostedInstrumentStateB64'] as String?) ??
                        (midiTrack['hostedInstrumentStateBase64'] as String?) ??
                        '')
                    .trim())
                .isNotEmpty)
              'hostedInstrumentStateB64':
                  ((midiTrack['hostedInstrumentStateB64'] as String?) ??
                          (midiTrack['hostedInstrumentStateBase64']
                              as String?) ??
                          '')
                      .trim(),
          });
          midiTrack['rowIndex'] = migratedRowIndex;
          midiTrack.remove('rowId');
        }
      }
    }

    rowsJson
      ..clear()
      ..addAll(migratedRows);
    return changed || migratedRows.isNotEmpty;
  }

  Future<FeedbackScreenshotAttachment> _captureFeedbackScreenshot() async {
    final previousChatExpanded = _chatExpanded;
    final previousChatInputActive = _chatInputActive;
    final pixelRatio =
        MediaQuery.maybeDevicePixelRatioOf(context)?.clamp(1.0, 2.0) ?? 1.0;

    if (mounted) {
      setState(() {
        _chatExpanded = false;
        _chatInputActive = false;
      });
    }
    _chatFocusNode.unfocus();

    await Future<void>.delayed(const Duration(milliseconds: 90));
    await WidgetsBinding.instance.endOfFrame;

    try {
      final boundaryContext = _feedbackScreenshotBoundaryKey.currentContext;
      final boundaryRenderObject = boundaryContext?.findRenderObject();
      if (boundaryRenderObject is! RenderRepaintBoundary) {
        throw StateError('Could not capture the editor screenshot.');
      }

      final capturedImage = await boundaryRenderObject.toImage(
        pixelRatio: pixelRatio,
      );
      final byteData = await capturedImage.toByteData(
        format: ui.ImageByteFormat.png,
      );
      capturedImage.dispose();
      if (byteData == null) {
        throw StateError('Could not capture the editor screenshot.');
      }

      final pngBytes = byteData.buffer.asUint8List();
      final decoded = img.decodeImage(pngBytes);
      if (decoded == null) {
        throw StateError('Could not capture the editor screenshot.');
      }

      img.Image workingImage = decoded;
      if (workingImage.width > 1280) {
        workingImage = img.copyResize(workingImage, width: 1280);
      }

      Uint8List encoded = Uint8List.fromList(
        img.encodeJpg(workingImage, quality: 74),
      );
      int quality = 74;
      while (encoded.lengthInBytes > 120 * 1024 && quality > 38) {
        quality -= 8;
        encoded = Uint8List.fromList(
          img.encodeJpg(workingImage, quality: quality),
        );
      }
      while (encoded.lengthInBytes > 120 * 1024 && workingImage.width > 720) {
        final nextWidth = (workingImage.width * 0.82).round();
        workingImage = img.copyResize(workingImage, width: nextWidth);
        encoded = Uint8List.fromList(
          img.encodeJpg(workingImage, quality: quality),
        );
      }

      if (encoded.lengthInBytes > 120 * 1024) {
        throw StateError('Screenshot is too large to attach.');
      }

      return FeedbackScreenshotAttachment(
        bytes: encoded,
        mimeType: 'image/jpeg',
        width: workingImage.width,
        height: workingImage.height,
      );
    } finally {
      if (mounted) {
        setState(() {
          _chatExpanded = previousChatExpanded;
          _chatInputActive = previousChatInputActive;
        });
      }
    }
  }

  Future<void> _openDawFeedbackComposer() async {
    if (_feedbackSubmissionInFlight) return;

    final authService = context.read<AuthService>();
    final draft = await showFeedbackSheet(
      context,
      source: FeedbackSource.dawChat,
    );
    if (draft == null || !mounted) return;

    setState(() => _feedbackSubmissionInFlight = true);
    try {
      FeedbackContextPayload? contextPayload;
      if (draft.includeDawContext) {
        contextPayload = FeedbackContextPayload(
          chatHistory: ProjectChatHistory.fromChatMessages(
            _chatController.messages,
          ).toConversation(),
          projectSettings: _buildFeedbackProjectSettings(),
        );
      }

      FeedbackScreenshotAttachment? screenshot;
      if (draft.includeDawScreenshot) {
        screenshot = await _captureFeedbackScreenshot();
      }

      await FeedbackService.instance.submit(
        auth: authService,
        request: FeedbackSubmissionRequest(
          category: draft.category,
          source: FeedbackSource.dawChat,
          message: draft.message,
          allowEmailContact: draft.allowEmailContact,
          context: contextPayload,
          screenshot: screenshot,
        ),
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            L10n.translate(context, 'Thank you for your submission!'),
          ),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString().replaceFirst('Bad state: ', ''))),
      );
    } finally {
      if (mounted) {
        setState(() => _feedbackSubmissionInFlight = false);
      }
    }
  }

  // This is needed in iOS so that hold actions (like track headers) are immediately responsive
  // without gesture gate issues. But the tradeoff is that swipe to go back/forward will not work.
  // Since those actions might be needed in other parts of app, make it toggleable like this.
  Future<void> _setIOSSystemGestureDeferral(bool enabled) async {
    if (!Platform.isIOS) return;
    try {
      await _edgeGesturesChannel.invokeMethod<void>('setDeferred', {
        'enabled': enabled,
      });
    } catch (_) {}
  }

  void _setStateAndRefreshProjectSettings(VoidCallback updater) {
    if (!mounted) return;
    final dialogSetState = _projectSettingsStateSetter;
    if (dialogSetState != null) {
      // While the settings dialog is open, avoid rebuilding the whole editor
      // tree for each control change. Refresh only the dialog subtree.
      updater();
      dialogSetState(() {});
      return;
    }
    setState(updater);
  }

  void _refreshAudioEditorView([VoidCallback? updater]) {
    if (!mounted) return;
    if (updater != null) {
      updater();
    }
    final localSetState = _audioEditorStateSetter;
    if (localSetState != null) {
      localSetState(() {});
      return;
    }
    setState(() {});
  }

  bool get _showMasterRack => _activeTopPopup == _TopPopupType.master;
  bool get _showTempoRollDown => _activeTopPopup == _TopPopupType.tempo;
  bool get _isProjectSettingsOpen =>
      _activeTopPopup == _TopPopupType.projectSettings;
  bool get _isMasterPopupOpen => _activeTopPopup == _TopPopupType.master;
  bool get _canShowProducerCaptureUiSetting => _producerCaptureUiAllowlisted;
  bool get _isProducerCaptureUiVisible =>
      _canShowProducerCaptureUiSetting && _showProducerCaptureUi;

  void _showMasterInRightPanel() {
    if (!_usesTabletDesktopDawShell(context)) return;
    setState(() {
      if (_showMasterRack || _isMasterPopupOpen) {
        _setActiveTopPopup(_TopPopupType.none);
      }
      _tabletRightPanelTab = 'fx';
      _tabletRightPanelCollapsed = false;
      _setMasterMeterExpandedState(true);
    });
    _handleDawOnboardingMasterOpened();
  }

  void _setMasterMeterExpandedState(bool expanded) {
    _masterMeterExpanded = expanded;
    if (!expanded) {
      _timelineController.closeMasterAutomationLane();
    }
  }

  void _toggleMasterRightPanelFromTopBar() {
    final willOpen = !_masterMeterExpanded;
    _trackUiClick(
      controlId: 'master_plugins_button',
      surface: 'top_bar',
      controlType: 'toggle',
      value: willOpen,
    );
    setState(() {
      if (_showMasterRack || _isMasterPopupOpen) {
        _setActiveTopPopup(_TopPopupType.none);
      }
      _tabletRightPanelTab = 'fx';
      _tabletRightPanelCollapsed = false;
      _setMasterMeterExpandedState(willOpen);
    });
    if (willOpen) {
      _handleDawOnboardingMasterOpened();
    }
  }

  bool _toggleTopPopup(_TopPopupType popupType) {
    if (popupType == _TopPopupType.master &&
        _usesTabletDesktopDawShell(context)) {
      final willOpen = !_masterMeterExpanded;
      setState(() {
        if (_showMasterRack || _isMasterPopupOpen) {
          _setActiveTopPopup(_TopPopupType.none);
        }
        _tabletRightPanelTab = 'fx';
        _tabletRightPanelCollapsed = false;
        _setMasterMeterExpandedState(willOpen);
      });
      if (willOpen) {
        _handleDawOnboardingMasterOpened();
      }
      return willOpen;
    }
    final bool willOpen = _activeTopPopup != popupType;
    setState(() {
      _setActiveTopPopup(willOpen ? popupType : _TopPopupType.none);
    });
    if (willOpen && popupType == _TopPopupType.tempo) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _syncTempoPickerSelection();
      });
    }
    return willOpen;
  }

  void _closeTopPopup([_TopPopupType popupType = _TopPopupType.none]) {
    if (_activeTopPopup == _TopPopupType.none) return;
    if (popupType != _TopPopupType.none && _activeTopPopup != popupType) return;
    setState(() {
      _setActiveTopPopup(_TopPopupType.none);
    });
  }

  void _onTopPopupTapAwayPointerDown(PointerDownEvent event) {
    _topPopupTapPointerId = event.pointer;
    _topPopupTapDownGlobalPos = event.position;
    _topPopupTapMoved = false;
  }

  void _onTopPopupTapAwayPointerMove(PointerMoveEvent event) {
    if (_topPopupTapPointerId != event.pointer ||
        _topPopupTapDownGlobalPos == null) {
      return;
    }
    if (_topPopupTapMoved) return;
    final movedDistance =
        (event.position - _topPopupTapDownGlobalPos!).distance;
    if (movedDistance > 10.0) {
      _topPopupTapMoved = true;
    }
  }

  void _onTopPopupTapAwayPointerCancel(PointerCancelEvent event) {
    if (_topPopupTapPointerId == event.pointer) {
      _topPopupTapPointerId = null;
      _topPopupTapDownGlobalPos = null;
      _topPopupTapMoved = false;
    }
  }

  bool _consumeTopPopupTapAwayPointerUp(PointerUpEvent event) {
    final pointerMatches = _topPopupTapPointerId == event.pointer;
    final down = _topPopupTapDownGlobalPos;
    final moved = _topPopupTapMoved;
    _topPopupTapPointerId = null;
    _topPopupTapDownGlobalPos = null;
    _topPopupTapMoved = false;
    if (!pointerMatches || down == null || moved) return false;
    return (event.position - down).distance <= 10.0;
  }

  bool _isGlobalPointInsideKeyRect(GlobalKey key, Offset globalPosition) {
    final context = key.currentContext;
    if (context == null) return false;
    final renderObject = context.findRenderObject();
    if (renderObject is! RenderBox || !renderObject.hasSize) return false;
    final origin = renderObject.localToGlobal(Offset.zero);
    final rect = origin & renderObject.size;
    return rect.contains(globalPosition);
  }

  Rect? _topPopupAnchorRect(GlobalKey key) {
    final BuildContext? anchorContext = key.currentContext;
    final BuildContext? stackContext = _editorContentStackKey.currentContext;
    if (anchorContext == null || stackContext == null) return null;

    final RenderObject? anchorObject = anchorContext.findRenderObject();
    final RenderObject? stackObject = stackContext.findRenderObject();
    if (anchorObject is! RenderBox ||
        stackObject is! RenderBox ||
        !anchorObject.hasSize ||
        !stackObject.hasSize) {
      return null;
    }

    final Offset topLeft = anchorObject.localToGlobal(
      Offset.zero,
      ancestor: stackObject,
    );
    final Offset topRight = anchorObject.localToGlobal(
      Offset(anchorObject.size.width, 0),
      ancestor: stackObject,
    );
    final Offset bottomLeft = anchorObject.localToGlobal(
      Offset(0, anchorObject.size.height),
      ancestor: stackObject,
    );
    final Offset bottomRight = anchorObject.localToGlobal(
      Offset(anchorObject.size.width, anchorObject.size.height),
      ancestor: stackObject,
    );

    final double left = math.min(
      math.min(topLeft.dx, topRight.dx),
      math.min(bottomLeft.dx, bottomRight.dx),
    );
    final double top = math.min(
      math.min(topLeft.dy, topRight.dy),
      math.min(bottomLeft.dy, bottomRight.dy),
    );
    final double right = math.max(
      math.max(topLeft.dx, topRight.dx),
      math.max(bottomLeft.dx, bottomRight.dx),
    );
    final double bottom = math.max(
      math.max(topLeft.dy, topRight.dy),
      math.max(bottomLeft.dy, bottomRight.dy),
    );
    return Rect.fromLTRB(left, top, right, bottom);
  }

  Rect? _globalAnchorRect(GlobalKey key) {
    final BuildContext? anchorContext = key.currentContext;
    if (anchorContext == null) return null;
    final RenderObject? anchorObject = anchorContext.findRenderObject();
    if (anchorObject is! RenderBox || !anchorObject.hasSize) return null;
    final Offset topLeft = anchorObject.localToGlobal(Offset.zero);
    return topLeft & anchorObject.size;
  }

  _TopPopupLayout _resolveTopPopupLayout({
    required GlobalKey anchorKey,
    required double desiredWidth,
    required double connectorWidth,
    bool centerOnToolbarPill = false,
    bool matchToolbarWidth = false,
    bool alignLeftToAnchor = false,
  }) {
    final BuildContext? stackContext = _editorContentStackKey.currentContext;
    final RenderObject? stackObject = stackContext?.findRenderObject();
    if (stackObject is! RenderBox || !stackObject.hasSize) {
      final fallbackWidth = desiredWidth;
      return _TopPopupLayout(
        top: 48,
        left: _kTopPopupHorizontalMargin,
        width: fallbackWidth,
        connectorLeft: (fallbackWidth - connectorWidth) / 2,
      );
    }

    final Rect? anchorRect = _topPopupAnchorRect(anchorKey);
    final Rect? toolbarRect = centerOnToolbarPill
        ? _topPopupAnchorRect(_toolbarPillKey)
        : null;
    final double targetWidth = matchToolbarWidth && toolbarRect != null
        ? toolbarRect.width
        : desiredWidth;
    final double maxWidth = math.max(
      0,
      stackObject.size.width - (_kTopPopupHorizontalMargin * 2),
    );
    final double resolvedWidth = math.min(targetWidth, maxWidth);
    final double centerX =
        toolbarRect?.center.dx ??
        anchorRect?.center.dx ??
        (stackObject.size.width / 2);
    final double requestedLeft = alignLeftToAnchor && anchorRect != null
        ? anchorRect.left
        : centerX - (resolvedWidth / 2);
    final double maxLeft = math.max(
      _kTopPopupHorizontalMargin,
      stackObject.size.width - resolvedWidth - _kTopPopupHorizontalMargin,
    );
    final double left = requestedLeft.clamp(
      _kTopPopupHorizontalMargin,
      maxLeft,
    );
    final Rect? topAnchorRect = toolbarRect ?? anchorRect;
    final double connectorLeft = anchorRect == null
        ? (resolvedWidth - connectorWidth) / 2
        : (anchorRect.center.dx - left - (connectorWidth / 2)).clamp(
            14.0,
            math.max(14.0, resolvedWidth - connectorWidth - 14.0),
          );

    return _TopPopupLayout(
      top: topAnchorRect == null
          ? 56
          : topAnchorRect.bottom + _kTopPopupVerticalGap,
      left: left,
      width: resolvedWidth,
      connectorLeft: connectorLeft,
    );
  }

  String _sanitizeInstrumentIdToken(String raw) {
    final lower = raw.toLowerCase();
    final collapsed = lower.replaceAll(RegExp(r'[^a-z0-9]+'), '_');
    return collapsed.replaceAll(RegExp(r'^_+|_+$'), '');
  }

  String _prettyInstrumentNameFromSfzPreset(String presetFileName) {
    var stem = presetFileName.trim();
    if (stem.toLowerCase().endsWith('.sfz')) {
      stem = stem.substring(0, stem.length - 4);
    }
    stem = stem.replaceAllMapped(
      RegExp(r'([a-z])([A-Z])'),
      (m) => '${m.group(1)} ${m.group(2)}',
    );
    stem = stem.replaceAll(RegExp(r'[_\-]+'), ' ');
    stem = stem.replaceAll(RegExp(r'\s+'), ' ').trim();
    if (stem.isEmpty) return 'Instrument';
    return stem
        .split(' ')
        .map(
          (w) => w.isEmpty
              ? w
              : '${w[0].toUpperCase()}${w.substring(1).toLowerCase()}',
        )
        .join(' ');
  }

  String _normalizePickerCategory(String raw) {
    return normalizeInstrumentPickerCategory(raw);
  }

  Map<String, dynamic> _defaultInstrumentSpec() {
    for (final spec in _instrumentCatalog) {
      if ((spec['id'] as String?)?.trim() == kPreferredPianoInstrumentId) {
        return _platformResolvedInstrumentSpec(spec);
      }
    }
    for (final spec in kBundledSfzFallbackCatalog) {
      if ((spec['id'] as String?)?.trim() == kPreferredPianoInstrumentId) {
        return _platformResolvedInstrumentSpec(spec);
      }
    }
    for (final spec in _instrumentCatalog) {
      if (!_isSampledInstrumentSpec(spec)) {
        return _platformResolvedInstrumentSpec(spec);
      }
    }
    if (kInstrumentCatalog.isNotEmpty) {
      return _platformResolvedInstrumentSpec(kInstrumentCatalog.first);
    }
    if (_instrumentCatalog.isNotEmpty) {
      return _platformResolvedInstrumentSpec(_instrumentCatalog.first);
    }
    if (kBundledSfzFallbackCatalog.isNotEmpty) {
      return _platformResolvedInstrumentSpec(kBundledSfzFallbackCatalog.first);
    }
    return <String, dynamic>{
      'id': 'mixroom.basic_synth',
      'name': 'Basic Synth',
      'category': 'instrument',
    };
  }

  bool _isSampledInstrumentSpec(Map<String, dynamic> spec) {
    if (spec['isSampled'] == true) return true;
    final id = (spec['id'] as String? ?? '').toLowerCase();
    return id.startsWith('sfz.');
  }

  bool _isGranularizerTemplateSpec(Map<String, dynamic> spec) {
    final id = (spec['id'] as String? ?? '').trim().toLowerCase();
    return id == 'mixroom.granularizer' ||
        spec['isGranularizerTemplate'] == true;
  }

  bool _isSamplerTemplateSpec(Map<String, dynamic> spec) {
    final id = (spec['id'] as String? ?? '').trim().toLowerCase();
    return id == 'mixroom.sampler' || spec['isSamplerTemplate'] == true;
  }

  bool _isPitchLabToolSpec(Map<String, dynamic> spec) {
    final id = (spec['id'] as String? ?? '').trim().toLowerCase();
    return id == kPitchLabToolInstrumentId || spec['isPitchLabTool'] == true;
  }

  bool _isGranularizerParams(Map<String, double> params) {
    return (params['granularMode'] ?? 0.0) >= 0.5;
  }

  bool _isExternalPluginInstrumentSpec(Map<String, dynamic> spec) {
    return spec['isExternalPlugin'] == true;
  }

  bool _looksLikeDesktopHostedPluginId(String pluginId) {
    final id = pluginId.trim().toLowerCase();
    if (id.isEmpty) return false;
    return id.startsWith('audiounit') ||
        id.endsWith('.vst3') ||
        id.contains('/audio/plug-ins/') ||
        id.contains(r'\');
  }

  bool _isSampledInstrumentId(String instrumentId) {
    final id = instrumentId.trim().toLowerCase();
    if (id.startsWith('sfz.') || id.startsWith('sfz_asset:')) return true;
    final spec = _findInstrumentSpecById(instrumentId);
    if (spec == null) return false;
    return _isSampledInstrumentSpec(spec);
  }

  Future<String?> _ensureAndroidBundledInstrumentRootPath() async {
    if (!Platform.isAndroid) return null;
    return _androidBundledInstrumentRootPathFuture ??= () async {
      final root = (await JuceAudioEngine.getBundledInstrumentRootPath())
          ?.trim();
      if (root == null || root.isEmpty) {
        _androidBundledInstrumentRootPath = null;
        return null;
      }
      _androidBundledInstrumentRootPath = p.normalize(root);
      return _androidBundledInstrumentRootPath;
    }();
  }

  String _resolveBundledInstrumentPathForCurrentPlatform(String rawPath) {
    final trimmed = rawPath.trim();
    if (trimmed.isEmpty) return trimmed;
    if (!Platform.isAndroid) return trimmed;
    if (p.isAbsolute(trimmed)) return p.normalize(trimmed);
    final root = _androidBundledInstrumentRootPath?.trim() ?? '';
    if (root.isEmpty) return trimmed;
    const prefix = 'assets/instruments/';
    if (!trimmed.startsWith(prefix)) return trimmed;
    final relative = trimmed.substring(prefix.length);
    return p.normalize(p.join(root, relative));
  }

  Map<String, dynamic> _platformResolvedInstrumentSpec(
    Map<String, dynamic> spec,
  ) {
    if (!Platform.isAndroid || spec['isSampled'] != true) {
      return Map<String, dynamic>.from(spec);
    }
    final resolved = Map<String, dynamic>.from(spec);
    final sfzAssetPath = (resolved['sfzAssetPath'] as String?)?.trim() ?? '';
    if (sfzAssetPath.isNotEmpty) {
      resolved['sfzAssetPath'] =
          _resolveBundledInstrumentPathForCurrentPlatform(sfzAssetPath);
    }
    return resolved;
  }

  List<Map<String, dynamic>> _platformResolvedInstrumentCatalog(
    List<Map<String, dynamic>> specs,
  ) {
    return specs
        .map((spec) => _platformResolvedInstrumentSpec(spec))
        .toList(growable: false);
  }

  Map<String, dynamic>? _desktopHostedInstrumentSpecFromPlugin(
    Map<String, dynamic> plugin,
  ) {
    final id = (plugin['id'] as String?)?.trim() ?? '';
    final name = (plugin['name'] as String?)?.trim() ?? id;
    if (id.isEmpty || name.isEmpty) return null;
    if (plugin['isInstrument'] != true) return null;
    return <String, dynamic>{
      'id': id,
      'name': name,
      'category': 'instrument',
      'pickerCategory': 'On Device',
      'format': (plugin['format'] as String?)?.trim() ?? '',
      'manufacturer': (plugin['manufacturer'] as String?)?.trim() ?? '',
      'isInstrument': true,
      'isExternalPlugin': true,
      'favorite': _desktopFavoritePluginIds.contains(id),
      'hidden': _desktopHiddenPluginIds.contains(id),
    };
  }

  Map<String, dynamic> _decorateDesktopPluginForUi(
    Map<String, dynamic> plugin,
  ) {
    final id = (plugin['id'] as String?)?.trim() ?? '';
    final next = Map<String, dynamic>.from(plugin);
    next['favorite'] = id.isNotEmpty && _desktopFavoritePluginIds.contains(id);
    next['hidden'] = id.isNotEmpty && _desktopHiddenPluginIds.contains(id);
    return next;
  }

  List<Map<String, dynamic>> _applyDesktopPluginPreferences(
    List<Map<String, dynamic>> plugins,
  ) {
    final decorated = plugins
        .map(_decorateDesktopPluginForUi)
        .toList(growable: false);
    decorated.sort((a, b) {
      final aHidden = a['hidden'] == true;
      final bHidden = b['hidden'] == true;
      if (aHidden != bHidden) return aHidden ? 1 : -1;
      final aFavorite = a['favorite'] == true;
      final bFavorite = b['favorite'] == true;
      if (aFavorite != bFavorite) return aFavorite ? -1 : 1;
      final aName = ((a['name'] as String?) ?? '').trim().toLowerCase();
      final bName = ((b['name'] as String?) ?? '').trim().toLowerCase();
      return aName.compareTo(bName);
    });
    return decorated;
  }

  bool _isKnownDesktopPluginId(String pluginId) {
    final trimmed = pluginId.trim();
    if (trimmed.isEmpty) return false;
    for (final plugin in _desktopScannedPlugins) {
      if ((plugin['id'] as String?)?.trim().toLowerCase() ==
          trimmed.toLowerCase()) {
        return true;
      }
    }
    if (trimmed.toLowerCase().endsWith('.vst3') ||
        trimmed.contains('/') ||
        trimmed.contains(r'\')) {
      return File(trimmed).existsSync();
    }
    return false;
  }

  Future<List<Map<String, dynamic>>> _scanDesktopPlugins({
    bool forceRescan = false,
    bool includeHidden = false,
  }) async {
    if (!PlatformCapabilities.current.isDesktop ||
        !_platformCapabilities.externalPluginHosting) {
      return const <Map<String, dynamic>>[];
    }
    if (_platformCapabilities.supportedPluginFormats.isEmpty) {
      return const <Map<String, dynamic>>[];
    }
    final raw = forceRescan
        ? await JuceAudioEngine.rescanPlugins(
            searchPaths: _desktopPluginSearchPaths,
          )
        : await JuceAudioEngine.scanPlugins(
            searchPaths: _desktopPluginSearchPaths,
          );
    final filtered = _applyDesktopPluginPreferences(raw);
    final visible = includeHidden
        ? filtered
        : filtered
              .where((plugin) => plugin['hidden'] != true)
              .toList(growable: false);
    if (!mounted) return visible;
    setState(() {
      _desktopScannedPlugins = filtered;
      _desktopPluginCatalogLoadAttempted = true;
      if (forceRescan) {
        _desktopLastPluginRescanAtMs = DateTime.now().millisecondsSinceEpoch;
      }
    });
    if (forceRescan) {
      unawaited(_persistDesktopPluginPrefs());
    }
    return visible;
  }

  List<Map<String, dynamic>> _cachedDesktopPlugins({
    bool includeHidden = false,
  }) {
    final filtered = _applyDesktopPluginPreferences(_desktopScannedPlugins);
    final visible = includeHidden
        ? filtered
        : filtered
              .where((plugin) => plugin['hidden'] != true)
              .toList(growable: false);
    return visible
        .map((plugin) => Map<String, dynamic>.from(plugin))
        .toList(growable: false);
  }

  Future<List<Map<String, dynamic>>> _cachedDesktopPluginsForPicker() async {
    return _cachedDesktopPlugins();
  }

  List<Map<String, dynamic>> _availableDesktopHostedInstrumentCatalog() {
    if (!PlatformCapabilities.current.isDesktop ||
        !_platformCapabilities.externalPluginHosting) {
      return const <Map<String, dynamic>>[];
    }
    return _desktopHostedInstrumentCatalog
        .map((spec) => Map<String, dynamic>.from(spec))
        .toList(growable: false);
  }

  List<Map<String, dynamic>> _uiInstrumentCatalog() {
    final base = _activeInstrumentCatalog();
    final hosted = _availableDesktopHostedInstrumentCatalog();
    final merged = hosted.isEmpty
        ? base
        : _mergeInstrumentCatalogs([base, hosted]);
    return merged
        .where((spec) => !_isPitchLabToolSpec(spec))
        .map((spec) => Map<String, dynamic>.from(spec))
        .toList(growable: false);
  }

  List<Map<String, dynamic>> _instrumentCatalogForCurrentPlan(
    List<Map<String, dynamic>> catalog,
  ) {
    if (!_isFreePlan) return catalog;
    return catalog
        .where((spec) {
          final id = (spec['id'] as String? ?? '').trim();
          return _canUseInstrumentForCurrentPlan(id);
        })
        .map((spec) => Map<String, dynamic>.from(spec))
        .toList(growable: false);
  }

  Future<void> _refreshDesktopHostedInstrumentCatalog() async {
    if (!PlatformCapabilities.current.isDesktop ||
        !_platformCapabilities.externalPluginHosting) {
      if (_desktopHostedInstrumentCatalogReady &&
          _desktopHostedInstrumentCatalog.isEmpty) {
        return;
      }
      if (!mounted) {
        _desktopHostedInstrumentCatalog = <Map<String, dynamic>>[];
        _desktopHostedInstrumentCatalogReady = true;
        return;
      }
      setState(() {
        _desktopHostedInstrumentCatalog = <Map<String, dynamic>>[];
        _desktopHostedInstrumentCatalogReady = true;
      });
      return;
    }

    final normalized = _cachedDesktopPlugins()
        .map(_desktopHostedInstrumentSpecFromPlugin)
        .whereType<Map<String, dynamic>>()
        .where((plugin) => plugin['hidden'] != true)
        .toList(growable: false);
    if (!mounted) {
      _desktopHostedInstrumentCatalog = normalized;
      _desktopHostedInstrumentCatalogReady = true;
      return;
    }
    setState(() {
      _desktopHostedInstrumentCatalog = normalized;
      _desktopHostedInstrumentCatalogReady = true;
    });
  }

  Future<void> _ensureDesktopHostedInstrumentCatalogLoaded() async {
    if (!PlatformCapabilities.current.isDesktop ||
        !_platformCapabilities.externalPluginHosting ||
        _desktopHostedInstrumentCatalogReady) {
      return;
    }
    await _refreshDesktopHostedInstrumentCatalog();
  }

  Future<void> _loadBundledInstrumentCatalog() async {
    try {
      String raw;
      if (Platform.isAndroid) {
        final root = await _ensureAndroidBundledInstrumentRootPath();
        if (root != null && root.isNotEmpty) {
          final indexFile = File(p.join(root, 'index.json'));
          raw = await indexFile.readAsString();
        } else {
          raw = await rootBundle.loadString('assets/instruments/index.json');
        }
      } else {
        raw = await rootBundle.loadString('assets/instruments/index.json');
      }
      final decoded = jsonDecode(raw);
      if (decoded is! Map<String, dynamic>) {
        return;
      }

      final pack = (decoded['pack'] as String?)?.trim();
      final presets = decoded['presets'];
      if (presets is! List) {
        return;
      }

      final loaded = <Map<String, dynamic>>[];
      for (final entry in presets) {
        if (entry is! Map) continue;
        final map = entry.cast<String, dynamic>();
        final presetFile = (map['preset'] as String?)?.trim() ?? '';
        if (presetFile.isEmpty) continue;
        final entryPack = (map['pack'] as String?)?.trim().isNotEmpty == true
            ? (map['pack'] as String).trim()
            : pack ?? '';
        final categoryRaw = (map['category'] as String?) ?? '';
        final pickerCategory = _normalizePickerCategory(categoryRaw);
        final displayName = (map['name'] as String?)?.trim().isNotEmpty == true
            ? (map['name'] as String).trim()
            : _prettyInstrumentNameFromSfzPreset(presetFile);
        final defaultOutputGain = pickerCategory == 'Drums' ? 0.84 : 0.72;
        final defaultAttackMs = pickerCategory == 'Drums' ? 2.0 : 6.0;
        final defaultReleaseMs = pickerCategory == 'Drums' ? 320.0 : 520.0;
        final explicitId = (map['id'] as String?)?.trim() ?? '';
        final idToken = _sanitizeInstrumentIdToken(
          '${entryPack.isEmpty ? 'sfz' : entryPack}_${presetFile.replaceAll('.sfz', '')}',
        );
        final sourceProject =
            (map['source_project'] as String?)?.trim().isNotEmpty == true
                ? (map['source_project'] as String).trim()
                : entryPack.isEmpty
                    ? 'Bundled SFZ'
                    : entryPack;
        final sourceLicense =
            (map['source_license'] as String?)?.trim().isNotEmpty == true
                ? (map['source_license'] as String).trim()
                : 'See bundled LICENSE';
        loaded.add(<String, dynamic>{
          'id': explicitId.isNotEmpty ? explicitId : 'sfz.$idToken',
          'name': displayName,
          'category': 'instrument',
          'pickerCategory': pickerCategory,
          'sourceProject': sourceProject,
          'sourceLicense': sourceLicense,
          'isSampled': true,
          'sfzAssetPath': 'assets/instruments/$entryPack/$presetFile',
          'outputGain':
              ((map['outputGain'] as num?)?.toDouble() ?? defaultOutputGain)
                  .clamp(0.2, 2.0),
          'attackMs': ((map['attackMs'] as num?)?.toDouble() ?? defaultAttackMs)
              .clamp(0.0, 2400.0),
          'releaseMs':
              ((map['releaseMs'] as num?)?.toDouble() ?? defaultReleaseMs)
                  .clamp(20.0, 3600.0),
        });
      }

      if (loaded.isEmpty) {
        return;
      }
      final merged = _platformResolvedInstrumentCatalog(
        _mergeInstrumentCatalogs([
          kInstrumentCatalog,
          loaded,
          kBundledSfzFallbackCatalog,
        ]),
      );
      if (!mounted) {
        _instrumentCatalog = merged;
        _instrumentCatalogReady = true;
        return;
      }
      setState(() {
        _instrumentCatalog = merged;
        _instrumentCatalogReady = true;
      });
    } catch (_) {
      if (_instrumentCatalogReady) return;
      final fallback = _platformResolvedInstrumentCatalog(
        _mergeInstrumentCatalogs([
          kInstrumentCatalog,
          kBundledSfzFallbackCatalog,
        ]),
      );
      if (!mounted) {
        _instrumentCatalog = fallback;
        _instrumentCatalogReady = true;
        return;
      }
      setState(() {
        _instrumentCatalog = fallback;
        _instrumentCatalogReady = true;
      });
    }
  }

  void _syncRowLocalStateToRowCount() {
    while (_rowPan.length < _rowCount) {
      final nextRow = _rowPan.length;
      _rowPan.add(0.5);
      _rowGain.add(_kGainUiUnity);
      _rowVolumeAutomation.add([AutomationPoint(x: 0.0, volume: 0.75)]);
      _rowPluginAutomation[nextRow] = <String, List<AutomationPoint>>{};
      _rowAutomationClips[nextRow] = <String, List<AutomationClipSnapshot>>{};
      _rowAutomationTargets[nextRow] = _defaultAutomationTargetsForRow(nextRow);
      _rowSelectedAutomationTarget[nextRow] = 'volume';
      _rowMuted.add(false);
      _rowSoloed.add(false);
      _rowMuteApplied.add(null);
      _rowExpanded.add(false);
      _rowExpandedTab.add(0);
      _rowGainSnapshot.add(_kGainUiUnity);
      _rowPanSnapshot.add(0.5);
      _rowAutomationSnapshot.add([]);
    }
    if (_rowPan.length > _rowCount) {
      _rowPan.removeRange(_rowCount, _rowPan.length);
      _rowGain.removeRange(_rowCount, _rowGain.length);
      _rowVolumeAutomation.removeRange(_rowCount, _rowVolumeAutomation.length);
      _rowMuted.removeRange(_rowCount, _rowMuted.length);
      _rowSoloed.removeRange(_rowCount, _rowSoloed.length);
      _rowMuteApplied.removeRange(_rowCount, _rowMuteApplied.length);
      _rowExpanded.removeRange(_rowCount, _rowExpanded.length);
      _rowExpandedTab.removeRange(_rowCount, _rowExpandedTab.length);
      _rowGainSnapshot.removeRange(_rowCount, _rowGainSnapshot.length);
      _rowPanSnapshot.removeRange(_rowCount, _rowPanSnapshot.length);
      _rowAutomationSnapshot.removeRange(
        _rowCount,
        _rowAutomationSnapshot.length,
      );
    }

    _rowPluginAutomation.removeWhere((row, _) => row < 0 || row >= _rowCount);
    _rowAutomationClips.removeWhere((row, _) => row < 0 || row >= _rowCount);
    _rowAutomationTargets.removeWhere((row, _) => row < 0 || row >= _rowCount);
    _rowSelectedAutomationTarget.removeWhere(
      (row, _) => row < 0 || row >= _rowCount,
    );

    for (int row = 0; row < _rowCount; row++) {
      _rowPluginAutomation.putIfAbsent(
        row,
        () => <String, List<AutomationPoint>>{},
      );
      _rowAutomationClips.putIfAbsent(
        row,
        () => <String, List<AutomationClipSnapshot>>{},
      );
      _rowAutomationTargets.putIfAbsent(
        row,
        () => <String, _AutomationTargetMeta>{
          'volume': _volumeAutomationTargetMeta(),
        },
      );
      _rowSelectedAutomationTarget.putIfAbsent(row, () => 'volume');
    }

    if (_selectedRow >= _rowCount) {
      _selectedRow = _rowCount == 0 ? 0 : _rowCount - 1;
    }
    if (_meters.rows.length != _rowCount) {
      _meters.dispose();
      _meters = MeterBus(numRows: _rowCount);
    }
    _rowPeakHoldDb.removeWhere(
      (row, _) => row != -1 && (row < 0 || row >= _rowCount),
    );
    _rowPeakHoldLastUpdate.removeWhere(
      (row, _) => row != -1 && (row < 0 || row >= _rowCount),
    );
    _rowPeakHoldFreezeUntil.removeWhere(
      (row, _) => row != -1 && (row < 0 || row >= _rowCount),
    );
  }

  Future<void> _refreshPlatformCapabilities() async {
    final capabilities = await PlatformCapabilities.refresh();
    if (!mounted) return;
    setState(() {
      _platformCapabilities = capabilities;
    });
  }

  bool _elementSubtreeContainsEditableText(
    Element element, {
    int depth = 0,
    int maxDepth = 18,
  }) {
    if (element.widget is EditableText) {
      return true;
    }
    if (depth >= maxDepth) return false;

    var found = false;
    element.visitChildElements((child) {
      if (found) return;
      if (child.widget is EditableText) {
        found = true;
        return;
      }
      found = _elementSubtreeContainsEditableText(
        child,
        depth: depth + 1,
        maxDepth: maxDepth,
      );
    });
    return found;
  }

  bool _isEditableTextFocused() {
    final focusedContext = FocusManager.instance.primaryFocus?.context;
    if (focusedContext == null) return false;
    if (focusedContext is! Element) return false;
    if (_elementSubtreeContainsEditableText(focusedContext)) return true;

    var found = false;
    var ancestorDepth = 0;
    focusedContext.visitAncestorElements((ancestor) {
      if (found) return false;
      if (ancestor.widget is EditableText) {
        found = true;
        return false;
      }
      if (_elementSubtreeContainsEditableText(ancestor, maxDepth: 3)) {
        found = true;
        return false;
      }
      ancestorDepth += 1;
      return ancestorDepth < 24;
    });
    return found;
  }

  bool _isEditorTextEntryActive() {
    return _isEditableTextFocused() || _isChatTypingActive;
  }

  AudioTrack? _desktopMidiTargetClipOrNull() {
    if (_activeMidiClipEngineId != null) {
      final index = _clipIndexForEngineId(_activeMidiClipEngineId!);
      if (index >= 0 && index < _audioTracks.length) {
        final clip = _audioTracks[index];
        if (clip.isMidi) return clip;
      }
    }
    return _armedMidiClipOrNull();
  }

  bool _desktopKeyboardMidiCanCapture() {
    if (!PlatformCapabilities.current.isDesktop ||
        !_desktopKeyboardMidiEnabled) {
      return false;
    }
    if (_isEditorTextEntryActive()) return false;
    return _desktopMidiTargetClipOrNull() != null;
  }

  static final Map<LogicalKeyboardKey, int> _kDesktopKeyboardMidiOffsets =
      <LogicalKeyboardKey, int>{
        LogicalKeyboardKey.keyA: 0,
        LogicalKeyboardKey.keyW: 1,
        LogicalKeyboardKey.keyS: 2,
        LogicalKeyboardKey.keyE: 3,
        LogicalKeyboardKey.keyD: 4,
        LogicalKeyboardKey.keyF: 5,
        LogicalKeyboardKey.keyT: 6,
        LogicalKeyboardKey.keyG: 7,
        LogicalKeyboardKey.keyY: 8,
        LogicalKeyboardKey.keyH: 9,
        LogicalKeyboardKey.keyU: 10,
        LogicalKeyboardKey.keyJ: 11,
        LogicalKeyboardKey.keyK: 12,
        LogicalKeyboardKey.keyO: 13,
        LogicalKeyboardKey.keyL: 14,
        LogicalKeyboardKey.keyP: 15,
        LogicalKeyboardKey.semicolon: 16,
        LogicalKeyboardKey.quote: 17,
      };

  int? _desktopMidiPitchForKey(LogicalKeyboardKey key) {
    final semitoneOffset = _kDesktopKeyboardMidiOffsets[key];
    if (semitoneOffset == null) return null;
    return 60 + semitoneOffset;
  }

  Set<int> _desktopMidiHeldPitchesForPianoRoll(AudioTrack clip) {
    if (_desktopMidiHeldKeys.isEmpty || !_desktopKeyboardMidiEnabled) {
      return const <int>{};
    }
    final targetClip = _desktopMidiTargetClipOrNull();
    if (targetClip == null) return const <int>{};
    final sameEngineClip =
        clip.engineClipId >= 0 &&
        targetClip.engineClipId >= 0 &&
        clip.engineClipId == targetClip.engineClipId;
    if (!sameEngineClip && !identical(clip, targetClip)) {
      return const <int>{};
    }
    return _desktopMidiHeldKeys
        .map(_desktopMidiPitchForKey)
        .whereType<int>()
        .toSet();
  }

  Future<void> _dispatchDesktopMidiNoteDown(LogicalKeyboardKey key) async {
    final pitch = _desktopMidiPitchForKey(key);
    final clip = _desktopMidiTargetClipOrNull();
    if (pitch == null || clip == null || !clip.isMidi) return;

    if (!_isMidiClipRecording &&
        (!_liveMidiEventPlaybackSupported || clip.engineClipId < 0)) {
      await _previewPianoRollNote(pitch, 0.92);
      return;
    }

    await _handlePianoRollKeyboardNoteDown(clip, pitch, 0.92);
  }

  Future<void> _dispatchDesktopMidiNoteUp(LogicalKeyboardKey key) async {
    final pitch = _desktopMidiPitchForKey(key);
    final clip = _desktopMidiTargetClipOrNull();
    if (pitch == null || clip == null || !clip.isMidi) return;

    await _handlePianoRollKeyboardNoteUp(clip, pitch);
  }

  Future<void> _releaseAllDesktopMidiNotes() async {
    if (_desktopMidiHeldKeys.isEmpty) return;
    final keys = _desktopMidiHeldKeys.toList(growable: false);
    _desktopMidiHeldKeys.clear();
    if (mounted && _showPianoRoll) {
      setState(() {});
    }
    for (final key in keys) {
      await _dispatchDesktopMidiNoteUp(key);
    }
  }

  Future<void> _performEditorUndo() async {
    if (_v3ExecutionInProgress) return;
    await _commitPendingProjectTempoUndo();
    final action = await _undoManager.undo();
    if (action != null) {
      _updateOverallDurationIfNeeded(forceRebuild: true);
    }
    if (!mounted || action == null) return;
    await _refreshEffectCachesForUndoAction(action);
    final message =
        '${L10n.translate(context, 'Undo')}: ${_localizedUndoHistoryDescription(action.description)}';
    await _persistUndoHistory();
    if (LlmConfig.aiLiveEvaluationEnabled) {
      await _performAutosaveWrite();
    }
    if (!mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    messenger.hideCurrentSnackBar();
    messenger.showSnackBar(
      SnackBar(
        content: Text(message),
        duration: const Duration(milliseconds: 1200),
      ),
    );
    setState(() {});
  }

  Future<void> _performEditorRedo() async {
    if (_v3ExecutionInProgress) return;
    await _commitPendingProjectTempoUndo();
    final action = await _undoManager.redo();
    if (action != null) {
      _updateOverallDurationIfNeeded(forceRebuild: true);
    }
    if (!mounted || action == null) return;
    await _refreshEffectCachesForUndoAction(action);
    final message =
        '${L10n.translate(context, 'Redo')}: ${_localizedUndoHistoryDescription(action.description)}';
    await _persistUndoHistory();
    if (LlmConfig.aiLiveEvaluationEnabled) {
      await _performAutosaveWrite();
    }
    if (!mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    messenger.hideCurrentSnackBar();
    messenger.showSnackBar(
      SnackBar(
        content: Text(message),
        duration: const Duration(milliseconds: 1200),
      ),
    );
    setState(() {});
  }

  void _showUndoHistorySheet() {
    _showUndoRedoHistorySheet(isUndo: true);
  }

  void _showRedoHistorySheet() {
    _showUndoRedoHistorySheet(isUndo: false);
  }

  void _showUndoRedoHistorySheet({required bool isUndo}) {
    final entries = isUndo
        ? _undoManager.undoHistoryNewestFirst
        : _undoManager.redoHistoryNewestFirst;
    if (entries.isEmpty) return;
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withValues(alpha: 0.38),
      isScrollControlled: true,
      builder: (sheetContext) {
        return SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(14, 0, 14, 14),
            child: Align(
              alignment: Alignment.bottomCenter,
              child: ConstrainedBox(
                constraints: const BoxConstraints(
                  maxWidth: 420,
                  maxHeight: 360,
                ),
                child: _buildDawConnectedSurface(
                  borderRadius: BorderRadius.circular(29),
                  padding: const EdgeInsets.fromLTRB(16, 14, 16, 10),
                  active: true,
                  showOverlay: false,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        L10n.translate(
                          context,
                          isUndo ? 'Undo History' : 'Redo History',
                        ),
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 15,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const SizedBox(height: 10),
                      Flexible(
                        child: ListView.separated(
                          shrinkWrap: true,
                          itemCount: entries.length,
                          separatorBuilder: (_, __) => Divider(
                            height: 1,
                            color: Colors.white.withValues(alpha: 0.08),
                          ),
                          itemBuilder: (context, index) {
                            final entry = entries[index];
                            return ListTile(
                              dense: true,
                              contentPadding: EdgeInsets.zero,
                              title: Text(
                                _localizedUndoHistoryDescription(
                                  entry.description,
                                ),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 13,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                              subtitle: Text(
                                _formatUndoHistorySubtitle(
                                  isUndo: isUndo,
                                  index: index,
                                  timestampMs: entry.timestampMs,
                                ),
                                style: TextStyle(
                                  color: Colors.white.withValues(alpha: 0.58),
                                  fontSize: 11.5,
                                  fontWeight: FontWeight.w500,
                                ),
                              ),
                              onTap: () {
                                Navigator.of(sheetContext).pop();
                                unawaited(
                                  isUndo
                                      ? _selectUndoHistoryEntry(entry)
                                      : _selectRedoHistoryEntry(entry),
                                );
                              },
                            );
                          },
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  Future<void> _selectUndoHistoryEntry(ProjectUndoSnapshotRecord entry) async {
    try {
      await _commitPendingProjectTempoUndo();
      await _undoManager.undoToRecord(entry);
      await _persistUndoHistory();
      if (mounted) setState(() {});
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('${L10n.translate(context, 'Undo failed')}: $error'),
        ),
      );
    }
  }

  Future<void> _selectRedoHistoryEntry(ProjectUndoSnapshotRecord entry) async {
    try {
      await _commitPendingProjectTempoUndo();
      await _undoManager.redoToRecord(entry);
      await _persistUndoHistory();
      if (mounted) setState(() {});
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('${L10n.translate(context, 'Redo failed')}: $error'),
        ),
      );
    }
  }

  String _formatUndoHistorySubtitle({
    required bool isUndo,
    required int index,
    required int timestampMs,
  }) {
    final sequence = index == 0
        ? L10n.translate(context, isUndo ? 'Next undo' : 'Next redo')
        : '${index + 1} ${L10n.translate(context, isUndo ? 'steps back' : 'steps forward')}';
    final time = TimeOfDay.fromDateTime(
      DateTime.fromMillisecondsSinceEpoch(timestampMs),
    );
    return '$sequence · ${time.format(context)}';
  }

  String _localizedUndoHistoryDescription(String description) {
    final trimmed = description.trim();
    if (trimmed.isEmpty) return trimmed;

    final exact = L10n.translate(context, trimmed);
    if (exact != trimmed) return exact;

    final projectTempoMatch = RegExp(
      r'^Project tempo set to ([0-9]+) BPM\.$',
    ).firstMatch(trimmed);
    if (projectTempoMatch != null) {
      return '${L10n.translate(context, 'Project tempo set to')} ${projectTempoMatch.group(1)} BPM.';
    }

    final addMatch = RegExp(r'^Add (.+)$').firstMatch(trimmed);
    if (addMatch != null) {
      return _localizedUndoVerbObjectPhrase(
        verbKey: 'Add',
        objectText: addMatch.group(1)!,
      );
    }

    return trimmed;
  }

  String _localizedUndoVerbObjectPhrase({
    required String verbKey,
    required String objectText,
  }) {
    final object = L10n.translate(context, objectText.trim());
    switch (Localizations.localeOf(context).languageCode) {
      case 'ko':
        return '$object ${L10n.translate(context, verbKey)}';
      case 'ja':
        return '$object${L10n.translate(context, verbKey)}';
      case 'zh':
        return '${L10n.translate(context, verbKey)}$object';
      default:
        return '${L10n.translate(context, verbKey)} $object';
    }
  }

