  Future<void> _handleMacSpacebarPlayPauseShortcut() async {
    if (!mounted) return;
    if (_isRecording) {
      await _stopRecordingJuce(keepPlaying: false);
      return;
    }
    if (_isPlaying && _desktopSpacebarStopReturnsToStart) {
      await _pauseAudio(_safeAudioEditorStateSetter);
      await JuceAudioEngine.setTransportSeconds(
        _desktopPlaybackStartPoint.inMilliseconds / 1000.0,
      );
      setState(() {
        _isPlaying = false;
        _syncTransportClock(_desktopPlaybackStartPoint, playing: false);
      });
      return;
    }
    await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
  }

  bool _handleDesktopTopPopupEscape(KeyEvent event) {
    if (event is! KeyDownEvent ||
        event.logicalKey != LogicalKeyboardKey.escape) {
      return false;
    }
    if (_showTempoRollDown) {
      _closeTopPopup(_TopPopupType.tempo);
      return true;
    }
    if (_isProjectSettingsOpen) {
      unawaited(_closeProjectSettings());
      return true;
    }
    return false;
  }

  bool _handleDesktopChatEscape(KeyEvent event) {
    if (!PlatformCapabilities.current.isDesktop ||
        event is! KeyDownEvent ||
        event.logicalKey != LogicalKeyboardKey.escape ||
        !_chatExpanded) {
      return false;
    }
    _collapseChatWindow();
    return true;
  }

  bool _handleDesktopRightPanelEscape(KeyEvent event) {
    if (!PlatformCapabilities.current.isDesktop ||
        event is! KeyDownEvent ||
        event.logicalKey != LogicalKeyboardKey.escape ||
        !_usesTabletDesktopDawShell(context) ||
        _tabletRightPanelCollapsed) {
      return false;
    }
    setState(() {
      _tabletRightPanelCollapsed = true;
      _setMasterMeterExpandedState(false);
      _tabletRightPanelHandleDragging = false;
      _tabletRightPanelHandleDownGlobalPosition = null;
      _tabletRightPanelHandleLastGlobalPosition = null;
      _tabletRightPanelHandleMovedPastTapSlop = false;
      _tabletRightPanelHandleResized = false;
    });
    return true;
  }

  KeyEventResult _handleChatSurfaceKeyEvent(FocusNode node, KeyEvent event) {
    return _handleDesktopChatEscape(event)
        ? KeyEventResult.handled
        : KeyEventResult.ignored;
  }

  Widget _wrapDesktopChatSurfaceKeyboardHandler({required Widget child}) {
    if (!PlatformCapabilities.current.isDesktop) return child;
    return Focus(
      canRequestFocus: false,
      onKeyEvent: _handleChatSurfaceKeyEvent,
      child: child,
    );
  }

  bool _handleMacEditorKeyEvent(KeyEvent event) {
    if (!PlatformCapabilities.current.isDesktop) return false;
    final isKeyDown = event is KeyDownEvent;
    final isKeyRepeat = event is KeyRepeatEvent;
    final isKeyUp = event is KeyUpEvent;
    if (!isKeyDown && !isKeyRepeat && !isKeyUp) return false;

    if (_desktopShortcutSettingsOpen) {
      return false;
    }

    if (_handleDesktopTopPopupEscape(event)) {
      return true;
    }

    if (_handleDesktopChatEscape(event)) {
      return true;
    }

    if (_v3ExecutionInProgress) {
      if (_desktopMidiHeldKeys.isNotEmpty) {
        unawaited(_releaseAllDesktopMidiNotes());
      }
      return true;
    }

    if (_isEditorTextEntryActive()) {
      if (_desktopMidiHeldKeys.isNotEmpty) {
        unawaited(_releaseAllDesktopMidiNotes());
      }
      return false;
    }

    if (isKeyDown &&
        _matchesDesktopShortcut(_kDesktopShortcutOpenChat, event)) {
      _handleDesktopOpenChatShortcut();
      return true;
    }

    if (isKeyDown && event.logicalKey == LogicalKeyboardKey.escape) {
      if (_sampleBrowserVisible) {
        unawaited(_closeSampleBrowser());
        return true;
      }
      if (_showPianoRoll) {
        _closeMidiClipEditor();
        return true;
      }
      if (_showAddActionsPanel) {
        setState(() {
          _showAddActionsPanel = false;
        });
        _setDawPanelVisible('add_actions', false);
        return true;
      }
      if (_handleDesktopRightPanelEscape(event)) {
        return true;
      }
    }

    if (isKeyDown &&
        _matchesDesktopShortcut(_kDesktopShortcutCloseChat, event) &&
        _chatExpanded) {
      _collapseChatWindow();
      return true;
    }

    if (isKeyDown && _matchesDesktopShortcut(_kDesktopShortcutUndo, event)) {
      unawaited(_performEditorUndo());
      return true;
    }

    if (isKeyDown && _matchesDesktopShortcut(_kDesktopShortcutRedo, event)) {
      unawaited(_performEditorRedo());
      return true;
    }

    if (isKeyDown &&
        _matchesDesktopShortcut(_kDesktopShortcutCopyClips, event)) {
      _handleDesktopCopySelectedClipsShortcut();
      return true;
    }

    if (isKeyDown &&
        _matchesDesktopShortcut(_kDesktopShortcutPasteClips, event)) {
      _handleDesktopPasteSelectedClipsShortcut();
      return true;
    }

    final keyboard = HardwareKeyboard.instance;
    final key = event.logicalKey;
    if (!keyboard.isMetaPressed &&
        !keyboard.isControlPressed &&
        !keyboard.isAltPressed &&
        _desktopKeyboardMidiCanCapture()) {
      final midiPitch = _desktopMidiPitchForKey(key);
      if (midiPitch != null) {
        if (isKeyDown || isKeyRepeat) {
          if (_desktopMidiHeldKeys.add(key)) {
            if (mounted && _showPianoRoll) {
              setState(() {});
            }
            unawaited(_dispatchDesktopMidiNoteDown(key));
          }
          return true;
        }
        if (isKeyUp) {
          if (_desktopMidiHeldKeys.remove(key)) {
            if (mounted && _showPianoRoll) {
              setState(() {});
            }
            unawaited(_dispatchDesktopMidiNoteUp(key));
          }
          return true;
        }
      }
    }

    if (!isKeyDown) return false;

    if (_matchesDesktopShortcut(
      _kDesktopShortcutToggleSoloSelectedRow,
      event,
    )) {
      unawaited(_toggleSelectedRowSoloFromShortcut());
      return true;
    }

    if (_matchesDesktopShortcut(
      _kDesktopShortcutToggleMuteSelectedRow,
      event,
    )) {
      unawaited(_toggleSelectedRowMuteFromShortcut());
      return true;
    }

    if (_matchesDesktopShortcut(_kDesktopShortcutPlayPause, event)) {
      unawaited(_handleMacSpacebarPlayPauseShortcut());
      return true;
    }

    if (_matchesDesktopShortcut(_kDesktopShortcutToggleRecord, event)) {
      unawaited(_onRecordPressed());
      return true;
    }

    if (_matchesDesktopShortcut(_kDesktopShortcutToggleMagnet, event)) {
      _timelineController.toggleMagnet();
      return true;
    }

    if (_matchesDesktopShortcut(_kDesktopShortcutRestart, event)) {
      unawaited(_restartAudio(_safeAudioEditorStateSetter));
      return true;
    }

    if (_matchesDesktopShortcut(_kDesktopShortcutOpenFileBrowser, event)) {
      unawaited(_openSampleBrowser(promptFolderIfEmpty: true));
      return true;
    }

    if (_matchesDesktopShortcut(_kDesktopShortcutAddAudio, event)) {
      unawaited(_handleAddActionSelection('audio'));
      return true;
    }

    if (_matchesDesktopShortcut(_kDesktopShortcutAddInstrument, event)) {
      unawaited(_handleAddActionSelection('instrument'));
      return true;
    }

    return false;
  }

  @override
  void initState() {
    super.initState();
    if (PlatformCapabilities.current.isDesktop) {
      HardwareKeyboard.instance.addHandler(_handleMacEditorKeyEvent);
    }
    unawaited(_setIOSSystemGestureDeferral(true));
    WidgetsBinding.instance.addObserver(this);
    unawaited(_refreshPlatformCapabilities());
    _sampleBrowserPreferencesFuture = _loadDesktopEditorPrefs();
    unawaited(_loadBluetoothRecordingPrefs());
    // prewarmFFT(); // so that AI sync first run is not heavy (this was for video/audio sync)

    _transportTicker = Ticker((_) {
      if (!_isPlaying) return;
      _setGlobalAudioClock(_estimateTransportClockFromSample());
      unawaited(_pollTransportFromJuceIfNeeded());
      _refreshFxUiForPlaybackTick();

      // ===== END / LOOP LOGIC (same as before) =====
      final endPoint = _transportEndPoint();
      final withinEndGuard =
          _transportUiStopwatch.elapsed < _transportEndCheckGraceUntil;

      final reachedEnd =
          _hasTimelineClips &&
          endPoint > Duration.zero &&
          _globalAudioClock >= endPoint;
      final reachedLoopEnd =
          _loopEnabled &&
          _globalAudioClock >= Duration(milliseconds: _loopEndMs);

      if (reachedLoopEnd && !withinEndGuard) {
        if (_isRecording) {
          _transportTicker?.stop();
          _stopRecordingJuce(keepPlaying: false);
          return;
        }
        if (!_loopWrapInFlight) {
          unawaited(_wrapPlaybackToLoopStart());
        }
        return;
      }

      if (reachedEnd && !withinEndGuard) {
        if (_isRecording) return;
        unawaited(_togglePlayPauseAudio(_safeAudioEditorStateSetter));
      }
    });

    _projectDir = widget.projectDir;
    _projectCreatedAtMs = DateTime.now().millisecondsSinceEpoch;
    _projectPersistence = JsonAudioProjectPersistence();
    _projectAutosaveCoordinator = AutosaveCoordinator(
      performSave: _performAutosaveWrite,
      onError: (error, _) {
        debugPrint('Project autosave failed: $error');
      },
    );
    unawaited(_loadCloudSyncMode());
    _undoManager.addListener(_handleUndoHistoryChanged);

    _classifier = InstrumentClassifier();
    _spleeterStemSeparator = SpleeterStemSeparator();
    // Warm model availability early so stem separation doesn't block on first tap.
    unawaited(_spleeterStemSeparator.prewarm(includeSession: false));
    // _classifier.debugLog = (msg) {
    //   print('msg: $msg');
    //   ScaffoldMessenger.of(context).showSnackBar(
    //     SnackBar(
    //       content: Text(msg),
    //       duration: const Duration(seconds: 3),
    //     ),
    //   );
    // };
    // Defer AI model loads until AI features are actually used.
    _producerCollector = ProducerDataCollector();
    _producerCollector.setEnabled(_producerDataMode);
    final authService = context.read<AuthService>();
    _magnitudePredictor = !kUseLearnedMagnitudePredictor
        ? const NoopMixingMagnitudePredictor()
        : kUseRemoteLearnedMagnitudePredictor
        ? RemoteMixingMagnitudePredictor(
            enabled: true,
            proxyApiBaseUrl: LlmConfig.effectiveProxyApiBaseUrl,
            proxyPath: LlmConfig.mixResolvePath,
            authTokenProvider: authService.getIdTokenOrNull,
            refreshAuthTokenProvider: authService.refreshIdTokenOrNull,
            requestTimeout: Duration(seconds: LlmConfig.requestTimeoutSeconds),
          )
        : OnnxMixingMagnitudePredictor(
            enabled: true,
            applyModelAsset: kMixApplyClassifierAsset,
            magnitudeModelAsset: kMixMagnitudeRegressorAsset,
          );
    unawaited(_magnitudePredictor.startBackgroundRefresh());

    _mixModel = LocalMixingModel();
    _chatPipeline = ChatPipeline(
      llm: CloudLlmService(
        apiKey: LlmConfig.canUseDirectOpenAi ? LlmConfig.openAiApiKey : '',
        model: LlmConfig.openAiModel,
        proxyApiBaseUrl: LlmConfig.effectiveProxyApiBaseUrl,
        proxyPath: LlmConfig.proxyPath,
        conversationStateMode: LlmConfig.normalizedConversationStateMode,
        requestTimeout: Duration(seconds: LlmConfig.requestTimeoutSeconds),
        authTokenProvider: authService.getIdTokenOrNull,
        refreshAuthTokenProvider: authService.refreshIdTokenOrNull,
      ), // LocalLlmService(),
      projectBuilder: ProjectStateBuilder(classifier: _classifier),
      mixModel: _mixModel,
      magnitudePredictor: _magnitudePredictor,
      aiV3Planner: LlmConfig.effectiveAiV3Enabled
          ? AiV3PlannerService(
              apiKey: LlmConfig.effectiveAiV3PrototypeEnabled
                  ? LlmConfig.openAiApiKey
                  : '',
              model: LlmConfig.aiV3Model,
              reasoningEffort: LlmConfig.aiV3ReasoningEffort,
              requestTimeout: Duration(
                seconds: LlmConfig.requestTimeoutSeconds,
              ),
              proxyApiBaseUrl:
                  LlmConfig.effectiveAiV3ProxyEnabled &&
                      !LlmConfig.effectiveAiV3PrototypeEnabled
                  ? LlmConfig.effectiveProxyApiBaseUrl
                  : '',
              proxyPath: LlmConfig.aiV3ProxyPath,
              authTokenProvider: authService.getIdTokenOrNull,
              refreshAuthTokenProvider: authService.refreshIdTokenOrNull,
              resourceRefsEnabled: LlmConfig.aiV3ResourceRefsEnabled,
            )
          : null,
      aiV3CompactShadowPlanner:
          LlmConfig.aiV3CompactShadowEvaluationEnabled &&
              LlmConfig.aiV3CaptureEnabled &&
              LlmConfig.aiV3DetachedComparisonsEnabled &&
              LlmConfig.canUseDirectOpenAi
          ? AiV3PlannerService(
              apiKey: LlmConfig.openAiApiKey,
              model: LlmConfig.aiV3Model,
              reasoningEffort: LlmConfig.aiV3ReasoningEffort,
              requestTimeout: Duration(
                seconds: LlmConfig.requestTimeoutSeconds,
              ),
              commandTypes: aiV3CommonCommandTypes,
              architecture: 'v3_compact_common_shadow',
              resourceRefsEnabled: LlmConfig.aiV3ResourceRefsEnabled,
            )
          : null,
      aiV3AdaptiveShadowPlanner:
          LlmConfig.aiV3AdaptiveShadowEnabled &&
              LlmConfig.aiV3CaptureEnabled &&
              LlmConfig.aiV3DetachedComparisonsEnabled &&
              LlmConfig.canUseDirectOpenAi
          ? AiV3AdaptivePlannerService(
              apiKey: LlmConfig.openAiApiKey,
              model: LlmConfig.aiV3Model,
              reasoningEffort: LlmConfig.aiV3ReasoningEffort,
              requestTimeout: Duration(
                seconds: LlmConfig.requestTimeoutSeconds,
              ),
              resourceRefsEnabled: LlmConfig.aiV3ResourceRefsEnabled,
            )
          : null,
      aiV3AdaptiveShadowComparisonPlanner:
          LlmConfig.aiV3AdaptiveShadowEnabled &&
              LlmConfig.aiV3CaptureEnabled &&
              LlmConfig.aiV3DetachedComparisonsEnabled &&
              LlmConfig.canUseDirectOpenAi &&
              LlmConfig.aiV3AdaptiveComparisonModel.trim().isNotEmpty &&
              LlmConfig.aiV3AdaptiveComparisonModel.trim() !=
                  LlmConfig.aiV3Model.trim()
          ? AiV3AdaptivePlannerService(
              apiKey: LlmConfig.openAiApiKey,
              model: LlmConfig.aiV3AdaptiveComparisonModel,
              reasoningEffort: LlmConfig.aiV3ReasoningEffort,
              requestTimeout: Duration(
                seconds: LlmConfig.requestTimeoutSeconds,
              ),
              resourceRefsEnabled: LlmConfig.aiV3ResourceRefsEnabled,
            )
          : null,
      aiV3Capture: AiV3Capture(
        enabled: LlmConfig.aiV3CaptureEnabled,
        directoryPath: LlmConfig.aiV3CaptureDirectory,
      ),
      aiV3DetachedComparisonsEnabled: LlmConfig.aiV3DetachedComparisonsEnabled,
      aiV3ContextProfile: parseAiV3ContextProfile(LlmConfig.aiV3ContextProfile),
      aiV3ClipTempoDetector: _detectClipTempoBpm,
      aiV3ClipBoundaryAnalyzer: _analyzeAiV3ClipBoundaries,
      onThinkingChanged: (isThinking) {
        if (!mounted) return;
        if (isThinking && _isThinking && !_chatScrollHintEnabled) {
          _scrollChatToLatest();
        }
      },
    );
    widget.evaluationController?._attach(
      submit: _submitChatPrompt,
      undo: _performEditorUndo,
      redo: _performEditorRedo,
      executeV3Handoff: _presentAiV3Handoff,
      effectChain: _aiV3NativeRowEffectChain,
      snapshot: _aiEvaluationSnapshot,
      stateDigest: _freshAiV3StateFingerprint,
      hasPendingPlan: _chatPipeline.hasActiveAiV3PendingPlan,
    );

    _tempoPickerController = FixedExtentScrollController(
      initialItem: _tempoPickerItemFor(_tempo),
    );
    _chatController = InMemoryChatController();
    _chatTextController.addListener(_handleChatTextChanged);
    _chatFocusNode.addListener(_handleChatFocusChanged);
    unawaited(_refreshPromptRateLimitStatus());

    _samplePreviewPlayer = ja.AudioPlayer(handleAudioSessionActivation: false);
    _samplePreviewStateSub = _samplePreviewPlayer.playerStateStream.listen((
      state,
    ) {
      if (!mounted) return;
      setState(() {
        _samplePreviewPlaying = state.playing;
        if (state.processingState == ja.ProcessingState.completed) {
          _auditioningSamplePath = null;
          _samplePreviewPlaying = false;
        }
      });
    });
    if (PlatformCapabilities.current.isDesktop) {
      _desktopFinderDropSub = DesktopFileIngressService.dragSession.listen((
        event,
      ) {
        if (_isProjectLoading || !_loadedOnce) {
          if (event.phase == DesktopFileDragPhase.dropped) {
            _pendingDesktopFinderDragEvents.add(event);
          }
          return;
        }
        unawaited(_handleDesktopFinderDragEvent(event));
      });
      _pendingDesktopFinderDragEvents.addAll(
        DesktopFileIngressService.consumePendingDragEvents(),
      );
      // Drops are also mirrored onto the legacy batch stream; discard them so
      // projects-screen pending consumption remains the only batch consumer.
      DesktopFileIngressService.consumePendingBatches();
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      setState(() {
        _chatWarm = true;
      });
    });

    _meters = MeterBus(numRows: 0);
    // _startMeterPolling();

    WidgetsBinding.instance.addPostFrameCallback((_) async {
      final bluetoothSession = await _bluetoothImplementationSessionResolverV2
          .loadSession();
      if (!mounted) return;
      setState(() {
        _bluetoothImplementationSessionV2 = bluetoothSession;
      });
      while (true) {
        final priorShutdown = _processAudioEngineShutdownFuture;
        if (priorShutdown == null) break;
        try {
          await priorShutdown;
        } catch (_) {
          if (!mounted) return;
          _showSmallNotice('Audio output is not available yet.');
          setState(() => _isLoadingNextScreen = false);
          return;
        }
        if (!mounted) return;
        final latestShutdown = _processAudioEngineShutdownFuture;
        if (latestShutdown == null ||
            identical(latestShutdown, priorShutdown)) {
          break;
        }
      }
      if (!mounted) return;
      final engineInitialised =
          await JuceAudioEngine.initialiseForImplementation(
            bluetoothSession.active,
          );
      if (!mounted) return;
      if (!engineInitialised) {
        _showSmallNotice('Audio output is not available yet.');
        setState(() => _isLoadingNextScreen = false);
        return;
      }
      if (Platform.isMacOS &&
          JuceAudioEngine.v2BluetoothCommunicationQualityReduced) {
        _macBluetoothCommunicationQualityNoticeShown = true;
        _showSmallNotice(
          'Bluetooth microphone selected. Playback quality is reduced. Select another microphone for stereo audio.',
        );
      }
      _juceEngineEventSubscription ??= JuceAudioEngine.eventsStream.listen(
        _handleJuceEngineEvent,
      );
      if (_isBluetoothV2Session &&
          _usesLiveAudioRouteCoordinatorV2 &&
          !Platform.isIOS) {
        final coordinator = AudioRouteCoordinatorV2(
          adapter: const MethodChannelAudioRouteAdapterV2(),
          allowRecoveryGenerationSupersession: Platform.isMacOS,
          onStateChanged: _handleAudioRouteCoordinatorStateV2,
          onTransition: _handleAudioRouteTransitionV2,
          onIntentInvalidated: _handleAudioRouteIntentInvalidatedV2,
        );
        _audioRouteCoordinatorV2 = coordinator;
        final initialRoute = await coordinator.start();
        if (!mounted) {
          await _shutdownAudioEngineV2Aware();
          return;
        }
        if (initialRoute.captureConsistency ==
            AudioRouteCaptureConsistencyV2.unavailable) {
          await _shutdownAudioEngineV2Aware();
          _showSmallNotice('Audio output monitoring is unavailable.');
          setState(() => _isLoadingNextScreen = false);
          return;
        }
        if (Platform.isMacOS) {
          await _loadMacV2AudioDevices();
        }
      }
      await _refreshPlatformCapabilities();
      if (!_isBluetoothV2Session) {
        await _refreshMicrophonePermissionState();
        await _maybePromptMicrophonePermissionOnDawEntry();
        await _loadInputDevicesFromJuce(scheduleRecordingPrewarm: true);
        await _refreshAudioRouteInfo();
      }
      await _loadBundledInstrumentCatalog();
      final engineSupportsLiveMidi =
          await JuceAudioEngine.supportsLiveMidiClipPlayback();
      _liveMidiEventPlaybackSupported =
          !_kForceRenderedMidiPlaybackForBeta && engineSupportsLiveMidi;
      if (_kForceRenderedMidiPlaybackForBeta && engineSupportsLiveMidi) {
        debugPrint(
          '🎹 Live MIDI clip playback disabled for beta quality; using rendered MIDI WAV playback.',
        );
      }
      if (_liveMidiEventPlaybackSupported) {
        _startMidiDeviceConnectionPolling();
      }
      await _reloadRowsFromEngine();
      await _refreshProducerCaptureUiAllowlistAccess();
      await _sampleBrowserPreferencesFuture;
      await _loadProjectIfAny();
      if (!mounted) {
        await _shutdownAudioEngineV2Aware();
        return;
      }
      if (_isBluetoothV2Session && Platform.isIOS) {
        final coordinator = AudioRouteCoordinatorV2(
          adapter: const MethodChannelAudioRouteAdapterV2(),
          onStateChanged: _handleAudioRouteCoordinatorStateV2,
          onTransition: _handleAudioRouteTransitionV2,
          onIntentInvalidated: _handleAudioRouteIntentInvalidatedV2,
        );
        _audioRouteCoordinatorV2 = coordinator;
        final initialRoute = await coordinator.start();
        if (!mounted) {
          await _shutdownAudioEngineV2Aware();
          return;
        }
        if (initialRoute.captureConsistency ==
            AudioRouteCaptureConsistencyV2.unavailable) {
          await _shutdownAudioEngineV2Aware();
          _showSmallNotice('Audio output monitoring is unavailable.');
          setState(() => _isLoadingNextScreen = false);
          return;
        }
        if (_v2HardwareSettingsApplicationPending) {
          _v2HardwareSettingsApplicationPending = false;
          await _applyAudioEngineSettingsToNative(
            reason: 'projectLoadDeferred',
            notifyOnFailure: false,
          );
        }
      }
      if (!_isBluetoothV2Session) {
        _scheduleRecordingInputPrewarm(reason: 'projectLoaded');
      }
      await _flushPendingDesktopFinderDrops();
      setState(() => _isLoadingNextScreen = false);
      unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
      await _runInitialActionIfNeeded();
      await _maybeShowDawOnboarding();
    });
  }

  Future<void> _runInitialActionIfNeeded() async {
    if (_handledInitialAction || !mounted) return;
    final action = widget.initialAction;
    if (action == null) return;
    _handledInitialAction = true;

    final nextFormat = action == AudioEditorInitialAction.exportMp3
        ? _ExportAudioFormat.mp3
        : _ExportAudioFormat.wav;
    final current = _audioExportSettings;
    setState(() {
      _audioExportSettings = _AudioExportSettings(
        format: nextFormat,
        sampleRate: current.sampleRate,
        wavBitDepth: current.wavBitDepth,
        wavDithering: current.wavDithering,
        mp3BitrateKbps: current.mp3BitrateKbps,
        mp3Mode: current.mp3Mode,
        mp3VbrQuality: current.mp3VbrQuality,
        channelMode: current.channelMode,
        normalize: current.normalize,
        normalizeTargetDb: current.normalizeTargetDb,
        resampleQuality: current.resampleQuality,
      );
    });

    await Future.delayed(const Duration(milliseconds: 120));
    if (!mounted) return;
    if (_usesContainedExportPanel) {
      await _exportAndNavigate(
        selectedSettingsOverride: _normalizeAudioExportSettings(
          _audioExportSettings,
        ),
      );
    } else {
      await _exportAndNavigate();
    }
  }

  String? _currentOnboardingUserId() {
    try {
      return context.read<AuthService>().signedInUser?.userId;
    } catch (_) {
      return null;
    }
  }

  DesktopShortcutBinding _defaultDesktopShortcutBinding(String actionId) {
    switch (actionId) {
      case _kDesktopShortcutUndo:
        return DesktopShortcutBinding(
          keyId: LogicalKeyboardKey.keyZ.keyId,
          meta: Platform.isMacOS,
          control: !Platform.isMacOS,
        );
      case _kDesktopShortcutRedo:
        return DesktopShortcutBinding(
          keyId: LogicalKeyboardKey.keyZ.keyId,
          meta: Platform.isMacOS,
          control: !Platform.isMacOS,
          shift: true,
        );
      case _kDesktopShortcutPlayPause:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.space.keyId);
      case _kDesktopShortcutToggleRecord:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyR.keyId);
      case _kDesktopShortcutToggleMagnet:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyQ.keyId);
      case _kDesktopShortcutRestart:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyA.keyId);
      case _kDesktopShortcutOpenFileBrowser:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyF.keyId);
      case _kDesktopShortcutAddInstrument:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyD.keyId);
      case _kDesktopShortcutToggleSoloSelectedRow:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyS.keyId);
      case _kDesktopShortcutToggleMuteSelectedRow:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyM.keyId);
      case _kDesktopShortcutOpenChat:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.keyC.keyId);
      case _kDesktopShortcutCloseChat:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.escape.keyId);
      case _kDesktopShortcutCopyClips:
        return DesktopShortcutBinding(
          keyId: LogicalKeyboardKey.keyC.keyId,
          meta: Platform.isMacOS,
          control: !Platform.isMacOS,
        );
      case _kDesktopShortcutPasteClips:
        return DesktopShortcutBinding(
          keyId: LogicalKeyboardKey.keyV.keyId,
          meta: Platform.isMacOS,
          control: !Platform.isMacOS,
        );
      case _kDesktopShortcutStepDuplicateClips:
        return DesktopShortcutBinding(
          keyId: LogicalKeyboardKey.keyB.keyId,
          meta: Platform.isMacOS,
          control: !Platform.isMacOS,
        );
      case _kDesktopShortcutSelectTool:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.digit1.keyId);
      case _kDesktopShortcutStretchTool:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.digit2.keyId);
      case _kDesktopShortcutPaintTool:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.digit3.keyId);
      case _kDesktopShortcutCutTool:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.digit4.keyId);
      case _kDesktopShortcutDeleteTool:
        return DesktopShortcutBinding(keyId: LogicalKeyboardKey.digit5.keyId);
    }
    return DesktopShortcutBinding(keyId: LogicalKeyboardKey.space.keyId);
  }

