  Future<void> _showDesktopShortcutSettingsDialog() async {
    if (!mounted || !PlatformCapabilities.current.isDesktop) return;
    final updatedBindings = Map<String, DesktopShortcutBinding>.from(
      _desktopShortcutBindings,
    );
    var updatedWheelSensitivity = _desktopSliderWheelSensitivity;
    String? capturingActionId;
    _desktopShortcutSettingsOpen = true;
    try {
      await showDialog<void>(
        context: context,
        barrierDismissible: true,
        requestFocus: true,
        builder: (dialogContext) {
          return StatefulBuilder(
            builder: (context, setModalState) {
              final primaryModifier = Platform.isMacOS ? 'Cmd' : 'Ctrl';
              final optionModifier = Platform.isMacOS ? 'Option' : 'Alt';
              final hasConflicts = _desktopShortcutEntries.any((entry) {
                final binding =
                    updatedBindings[entry.key] ??
                    _defaultDesktopShortcutBinding(entry.key);
                return _desktopShortcutConflictMessage(
                      entry.key,
                      binding,
                      updatedBindings,
                    ) !=
                    null;
              });
              return Focus(
                autofocus: true,
                onKeyEvent: (_, event) {
                  if (capturingActionId == null) {
                    if (event is KeyDownEvent &&
                        event.logicalKey == LogicalKeyboardKey.escape) {
                      Navigator.of(dialogContext).pop();
                    }
                    return KeyEventResult.handled;
                  }
                  if (event is! KeyDownEvent) {
                    return KeyEventResult.handled;
                  }
                  final key = event.logicalKey;
                  if (key == LogicalKeyboardKey.metaLeft ||
                      key == LogicalKeyboardKey.metaRight ||
                      key == LogicalKeyboardKey.controlLeft ||
                      key == LogicalKeyboardKey.controlRight ||
                      key == LogicalKeyboardKey.shiftLeft ||
                      key == LogicalKeyboardKey.shiftRight ||
                      key == LogicalKeyboardKey.altLeft ||
                      key == LogicalKeyboardKey.altRight) {
                    return KeyEventResult.handled;
                  }
                  final keyboard = HardwareKeyboard.instance;
                  updatedBindings[capturingActionId!] = DesktopShortcutBinding(
                    keyId: key.keyId,
                    meta: keyboard.isMetaPressed,
                    control: keyboard.isControlPressed,
                    shift: keyboard.isShiftPressed,
                    alt: keyboard.isAltPressed,
                  );
                  setModalState(() {
                    capturingActionId = null;
                  });
                  return KeyEventResult.handled;
                },
                child: _buildDesktopPopupSurface(
                  width: 560,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Row(
                        children: [
                          const Expanded(
                            child: Text(
                              'Keyboard Shortcuts',
                              style: TextStyle(
                                color: Color(0xFFF4F4F4),
                                fontFamily: 'Pretendard',
                                fontSize: 17,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ),
                          TextButton(
                            onPressed: () {
                              updatedBindings.clear();
                              updatedWheelSensitivity =
                                  DesktopSliderWheelSensitivity.defaults;
                              setModalState(() {
                                capturingActionId = null;
                              });
                            },
                            child: const Text('Reset Defaults'),
                          ),
                          IconButton(
                            onPressed: () => Navigator.of(dialogContext).pop(),
                            icon: const Icon(
                              Icons.close_rounded,
                              color: Color(0xFFEFEFEF),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      Text(
                        capturingActionId == null
                            ? 'Select a shortcut to remap it.'
                            : 'Press the new shortcut now.',
                        style: TextStyle(
                          color: Colors.white.withValues(alpha: 0.66),
                          fontFamily: 'Pretendard',
                          fontSize: 12.5,
                          fontWeight: FontWeight.w500,
                        ),
                      ),
                      if (_desktopKeyboardMidiEnabled) ...[
                        const SizedBox(height: 8),
                        Text(
                          'Most unmodified piano-style letter keys are reserved while computer-keyboard MIDI input is enabled.',
                          style: TextStyle(
                            color: Colors.white.withValues(alpha: 0.54),
                            fontFamily: 'Pretendard',
                            fontSize: 11.8,
                            height: 1.35,
                          ),
                        ),
                      ],
                      const SizedBox(height: 14),
                      Flexible(
                        child: SingleChildScrollView(
                          child: Column(
                            children: [
                              ..._desktopShortcutEntries.map((entry) {
                                final binding =
                                    updatedBindings[entry.key] ??
                                    _defaultDesktopShortcutBinding(entry.key);
                                final active = capturingActionId == entry.key;
                                final conflict =
                                    _desktopShortcutConflictMessage(
                                      entry.key,
                                      binding,
                                      updatedBindings,
                                    );
                                return Container(
                                  margin: const EdgeInsets.only(bottom: 10),
                                  padding: const EdgeInsets.fromLTRB(
                                    14,
                                    12,
                                    14,
                                    12,
                                  ),
                                  decoration: BoxDecoration(
                                    color: active
                                        ? Colors.white.withValues(alpha: 0.11)
                                        : Colors.white.withValues(alpha: 0.05),
                                    borderRadius: BorderRadius.circular(16),
                                    border: Border.all(
                                      color: active
                                          ? const Color(0xFF66B5FF)
                                          : conflict != null
                                          ? const Color(0xFFF57272)
                                          : Colors.white.withValues(
                                              alpha: 0.08,
                                            ),
                                    ),
                                  ),
                                  child: Column(
                                    children: [
                                      Row(
                                        children: [
                                          Expanded(
                                            child: Text(
                                              entry.value,
                                              style: const TextStyle(
                                                color: Color(0xFFF4F4F4),
                                                fontFamily: 'Pretendard',
                                                fontSize: 14,
                                                fontWeight: FontWeight.w600,
                                              ),
                                            ),
                                          ),
                                          Container(
                                            padding: const EdgeInsets.symmetric(
                                              horizontal: 12,
                                              vertical: 8,
                                            ),
                                            decoration: BoxDecoration(
                                              color: Colors.white.withValues(
                                                alpha: 0.08,
                                              ),
                                              borderRadius:
                                                  BorderRadius.circular(999),
                                            ),
                                            child: Text(
                                              active
                                                  ? 'Press keys...'
                                                  : _desktopShortcutLabel(
                                                      binding,
                                                    ),
                                              style: TextStyle(
                                                color: const Color(
                                                  0xFFF4F4F4,
                                                ).withValues(alpha: 0.86),
                                                fontFamily: 'Pretendard',
                                                fontSize: 12.5,
                                                fontWeight: FontWeight.w600,
                                              ),
                                            ),
                                          ),
                                          const SizedBox(width: 10),
                                          TextButton(
                                            onPressed: () {
                                              setModalState(() {
                                                capturingActionId = active
                                                    ? null
                                                    : entry.key;
                                              });
                                            },
                                            child: Text(
                                              active ? 'Cancel' : 'Change',
                                            ),
                                          ),
                                        ],
                                      ),
                                      if (conflict != null) ...[
                                        const SizedBox(height: 8),
                                        Align(
                                          alignment: Alignment.centerLeft,
                                          child: Text(
                                            conflict,
                                            style: const TextStyle(
                                              color: Color(0xFFF58A8A),
                                              fontFamily: 'Pretendard',
                                              fontSize: 12,
                                              fontWeight: FontWeight.w500,
                                            ),
                                          ),
                                        ),
                                      ],
                                    ],
                                  ),
                                );
                              }),
                              const SizedBox(height: 4),
                              _buildDesktopKeyboardMidiReferenceSection(
                                enabled: _desktopKeyboardMidiEnabled,
                              ),
                              const SizedBox(height: 10),
                              _buildDesktopGestureReferenceSection(
                                primaryModifier: primaryModifier,
                                optionModifier: optionModifier,
                              ),
                              const SizedBox(height: 10),
                              _buildDesktopSliderWheelSensitivitySection(
                                sensitivity: updatedWheelSensitivity,
                                primaryModifier: primaryModifier,
                                optionModifier: optionModifier,
                                onChanged: (value) {
                                  setModalState(() {
                                    updatedWheelSensitivity = value;
                                  });
                                },
                              ),
                            ],
                          ),
                        ),
                      ),
                      const SizedBox(height: 10),
                      Align(
                        alignment: Alignment.centerRight,
                        child: FilledButton(
                          onPressed: hasConflicts
                              ? null
                              : () => Navigator.of(dialogContext).pop(),
                          child: const Text('Done'),
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      );
    } finally {
      _desktopShortcutSettingsOpen = false;
    }
    if (!mounted) return;
    setState(() {
      _desktopShortcutBindings = updatedBindings;
      _desktopSliderWheelSensitivity = updatedWheelSensitivity;
      DesktopSliderWheelSensitivityStore.current = updatedWheelSensitivity;
    });
    await _persistDesktopShortcutPrefs();
    await _persistDesktopSliderWheelSensitivityPrefs();
  }

  int get _safeDawOnboardingStepIndex {
    if (_kDawTutorialSequence.isEmpty) return 0;
    if (_dawOnboardingStepIndex < 0) return 0;
    if (_dawOnboardingStepIndex >= _kDawTutorialSequence.length) {
      return _kDawTutorialSequence.length - 1;
    }
    return _dawOnboardingStepIndex;
  }

  int get _dawTutorialTargetRow {
    if (_rowCount <= 0) return 0;
    final stored = _dawTutorialRowIndex;
    if (stored != null && stored >= 0 && stored < _rowCount) {
      return stored;
    }
    return _selectedRow.clamp(0, _rowCount - 1).toInt();
  }

  _DawTutorialStepId get _currentDawOnboardingStepId =>
      _kDawTutorialSequence[_safeDawOnboardingStepIndex];

  _DawTutorialStepSpec get _currentDawOnboardingStep =>
      _buildDawTutorialStepSpec(_currentDawOnboardingStepId);

