  Future<void> _debugShowDawOnboardingStartDialog() async {
    if (!kDebugMode) return;
    final shouldStart = await _showDawOnboardingStartDialog();
    if (!mounted || !shouldStart) return;
    _startDawOnboarding();
  }

  Future<void> _maybeShowDawOnboarding() async {
    if (!mounted ||
        widget.initialAction != null ||
        _kDawTutorialSequence.isEmpty) {
      return;
    }
    final userId = _currentOnboardingUserId();
    final pendingQuickTour = await DawOnboardingPrefs.consumePendingQuickTour(
      userId,
    );
    final hasSeen = await DawOnboardingPrefs.hasSeen(userId);
    if (!mounted) return;
    if (!pendingQuickTour && hasSeen) return;
    if (pendingQuickTour) {
      _startDawOnboarding();
      return;
    }
    final shouldStart = await _showDawOnboardingStartDialog();
    if (!mounted) return;
    if (shouldStart) {
      _startDawOnboarding();
      return;
    }
    await DawOnboardingPrefs.markSeen(userId);
  }

  void _advanceDawOnboardingStep() {
    _dawOnboardingAdvanceTimer?.cancel();
    _dawOnboardingAdvanceTimer = null;
    _setDawOnboardingStep(_safeDawOnboardingStepIndex + 1);
  }

  void _scheduleDawOnboardingAdvance({
    Duration? delay,
    _DawTutorialStepId? expectedStep,
  }) {
    if (!_showDawOnboarding) return;
    final stepId = expectedStep ?? _currentDawOnboardingStepId;
    final stepDelay = delay ?? _currentDawOnboardingStep.autoAdvanceDelay;
    _dawOnboardingAdvanceTimer?.cancel();
    _dawOnboardingAdvanceTimer = Timer(stepDelay, () {
      if (!mounted || !_showDawOnboarding) return;
      if (_currentDawOnboardingStepId != stepId) return;
      _advanceDawOnboardingStep();
    });
  }

  void _handleDawOnboardingTimelineScrolled() {
    if (!_showDawOnboarding) return;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.timelineScroll) {
      _scheduleDawOnboardingAdvance();
    }
  }

  void _handleDawOnboardingTimelineZoomed() {
    if (!_showDawOnboarding) return;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.timelineZoom) {
      _scheduleDawOnboardingAdvance();
    }
  }

  void _handleDawOnboardingAddButtonOpened() {
    if (!_showDawOnboarding) return;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.addButton) {
      _scheduleDawOnboardingAdvance();
    }
  }

  void _handleTimelineRowExpansionChanged(int row, bool expanded) {
    if (row >= 0 && row < _rowExpanded.length) {
      if (expanded) {
        if (_usesTabletDesktopDawShell(context) && _allowMultipleExpandedRows) {
          _rowExpanded[row] = true;
        } else {
          for (int i = 0; i < _rowExpanded.length; i++) {
            _rowExpanded[i] = i == row;
          }
        }
      } else {
        _rowExpanded[row] = false;
      }
    }
  }

  void _handleTimelineRowTabSelected(int row, int tab) {
    if (row >= 0 && row < _rowExpandedTab.length) {
      _rowExpandedTab[row] = (tab == 1 || tab == 2) ? tab : 0;
    }
    if (row >= 0 && row < _rowCount) {
      setState(() {
        _selectedRow = row;
        _tabletRowDetailTab = tab.clamp(0, 2).toInt();
      });
    }
  }

  void _handleDawOnboardingRowExpansionChanged(int row, bool expanded) {
    _handleTimelineRowExpansionChanged(row, expanded);
    if (!_showDawOnboarding || !expanded) return;
    _dawTutorialRowIndex = row;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.rowExpand) {
      _scheduleDawOnboardingAdvance();
    }
  }

  void _handleDawOnboardingRowTabSelected(int row, int tab) {
    _handleTimelineRowTabSelected(row, tab);
    if (!_showDawOnboarding) return;
    _dawTutorialRowIndex = row;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.rowEffectsTab &&
        tab == 1) {
      _scheduleDawOnboardingAdvance();
      return;
    }
    if (_currentDawOnboardingStepId == _DawTutorialStepId.rowAutomationTab &&
        tab == 2) {
      _scheduleDawOnboardingAdvance();
    }
  }

  void _handleDawOnboardingEffectAdded(
    int row,
    int effectIndex,
    String effectName,
  ) {
    if (!_showDawOnboarding) return;
    _dawTutorialRowIndex = row;
    _dawTutorialEffectIndex = effectIndex;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.rowAddEffect) {
      _scheduleDawOnboardingAdvance(delay: const Duration(milliseconds: 1100));
    }
  }

