  void _handleDawOnboardingChatPromptSubmitted() {
    if (!_showDawOnboarding) return;
    if (_currentDawOnboardingStepId == _DawTutorialStepId.chatSend) {
      setState(() {
        _dawTutorialAwaitingChatReply = true;
        _dawTutorialChatAdvanceInFlight = false;
        _dawTutorialAssistantCountAtPromptSend = _chatTextMessageCount(
          authorId: 'assistant',
        );
      });
      _scheduleDawOnboardingAdvance(delay: const Duration(milliseconds: 700));
    }
  }

  Future<void> _handleDawOnboardingChatReplyReady() async {
    if (!_showDawOnboarding || !_dawTutorialAwaitingChatReply) return;
    if (_currentDawOnboardingStepId != _DawTutorialStepId.chatWaiting) return;
    if (_dawTutorialChatAdvanceInFlight) return;
    setState(() {
      _dawTutorialChatAdvanceInFlight = true;
    });

    final hasAssistantReply =
        _chatTextMessageCount(authorId: 'assistant') >
        _dawTutorialAssistantCountAtPromptSend;
    if (!hasAssistantReply) {
      if (!mounted) return;
      setState(() {
        _dawTutorialChatAdvanceInFlight = false;
      });
      return;
    }

    _scrollChatToLatest();
    await Future.delayed(const Duration(milliseconds: 350));

    if (!mounted || !_showDawOnboarding) return;
    if (_currentDawOnboardingStepId != _DawTutorialStepId.chatWaiting) return;
    setState(() {
      _dawTutorialAwaitingChatReply = false;
      _dawTutorialChatAdvanceInFlight = false;
    });
    _scheduleDawOnboardingAdvance(
      delay: const Duration(milliseconds: 1200),
      expectedStep: _DawTutorialStepId.chatWaiting,
    );
  }

  Map<int, _RowUiStateSnapshot> _captureRowUiStateById() {
    final snapshots = <int, _RowUiStateSnapshot>{};
    for (int i = 0; i < _rows.length; i++) {
      final id = _rows[i].rowId;
      snapshots[id] = _RowUiStateSnapshot(
        pan: i < _rowPan.length ? _rowPan[i] : 0.5,
        gain: i < _rowGain.length ? _rowGain[i] : _kGainUiUnity,
        muted: i < _rowMuted.length ? _rowMuted[i] : false,
        soloed: i < _rowSoloed.length ? _rowSoloed[i] : false,
        muteApplied: i < _rowMuteApplied.length ? _rowMuteApplied[i] : null,
        expanded: i < _rowExpanded.length ? _rowExpanded[i] : false,
        expandedTab: i < _rowExpandedTab.length ? _rowExpandedTab[i] : 0,
        volumeAutomation: i < _rowVolumeAutomation.length
            ? _rowVolumeAutomation[i].map((p) => p.copy()).toList()
            : <AutomationPoint>[AutomationPoint(x: 0.0, volume: 0.75)],
        pluginAutomation:
            (_rowPluginAutomation[i] ?? const <String, List<AutomationPoint>>{})
                .map(
                  (key, value) => MapEntry(
                    key,
                    value.map((p) => p.copy()).toList(growable: false),
                  ),
                ),
        automationClips:
            (_rowAutomationClips[i] ??
                    const <String, List<AutomationClipSnapshot>>{})
                .map(
                  (key, value) => MapEntry(
                    key,
                    value
                        .map((clip) => clip.copyWith())
                        .toList(growable: false),
                  ),
                ),
        automationTargets: Map<String, _AutomationTargetMeta>.from(
          _rowAutomationTargets[i] ?? _defaultAutomationTargetsForRow(i),
        ),
        selectedAutomationTarget: _rowSelectedAutomationTarget[i] ?? 'volume',
        gainSnapshot: i < _rowGainSnapshot.length
            ? _rowGainSnapshot[i]
            : _kGainUiUnity,
        panSnapshot: i < _rowPanSnapshot.length ? _rowPanSnapshot[i] : 0.5,
        automationSnapshot: i < _rowAutomationSnapshot.length
            ? _rowAutomationSnapshot[i].map((p) => p.copy()).toList()
            : <AutomationPoint>[],
        peakHoldDb: _rowPeakHoldDb[i],
        peakHoldLastUpdate: _rowPeakHoldLastUpdate[i],
        peakHoldFreezeUntil: _rowPeakHoldFreezeUntil[i],
      );
    }
    return snapshots;
  }

  void _syncAudioTrackRowsToCurrentRows({Map<int, int>? previousIndexById}) {
    if (_audioTracks.isEmpty) return;
    _ensureClipOperationIndexes();

    final currentIndexById = <int, int>{
      for (int index = 0; index < _rows.length; index++)
        _rows[index].rowId: index,
    };
    final rowIdsToSync = <int>{..._clipsByRowId.keys};
    if (previousIndexById != null) {
      rowIdsToSync.removeWhere(
        (rowId) => previousIndexById[rowId] == currentIndexById[rowId],
      );
    }

    var changedLayout = false;
    for (final rowId in rowIdsToSync) {
      final clips = _clipsByRowId[rowId]?.toList(growable: false);
      if (clips == null) continue;
      final currentIndex = currentIndexById[rowId];
      for (final clip in clips) {
        if (currentIndex != null) {
          changedLayout = changedLayout || clip.rowIndex != currentIndex;
          clip.rowIndex = currentIndex;
        } else if (_rowCount == 0) {
          changedLayout = changedLayout || clip.rowIndex != 0;
          clip.rowIndex = 0;
        } else {
          changedLayout = true;
          clip.rowId = _rowIdAt(0);
          clip.rowIndex = 0;
          _indexClipForOperations(clip);
        }
      }
    }
    if (changedLayout) {
      _markClipVisualMutation(layout: true);
    }
  }

  Future<void> _applyRowsToEditorState(
    List<TimelineRow> nextRows, {
    bool refreshAutomationTargets = true,
    bool setStateWhenDone = true,
    bool syncClipRows = true,
  }) async {
    final previousStateById = _captureRowUiStateById();
    final previousRowIndexById = <int, int>{
      for (int index = 0; index < _rows.length; index++)
        _rows[index].rowId: index,
    };
    _rows = _sanitizeTrackGroupsForRows(nextRows);
    _syncTrackGroupColorsFromRows(_rows);
    _syncRowLocalStateToRowCount();

    _rowPeakHoldDb.removeWhere((_, __) => true);
    _rowPeakHoldLastUpdate.removeWhere((_, __) => true);
    _rowPeakHoldFreezeUntil.removeWhere((_, __) => true);

    for (int i = 0; i < _rows.length; i++) {
      final state = previousStateById[_rows[i].rowId];
      if (state == null) continue;
      _rowPan[i] = state.pan;
      _rowGain[i] = state.gain.clamp(_kGainUiMin, _kGainUiMax);
      _rowMuted[i] = state.muted;
      _rowSoloed[i] = state.soloed;
      _rowMuteApplied[i] = state.muteApplied;
      _rowExpanded[i] = state.expanded;
      _rowExpandedTab[i] = state.expandedTab;
      _rowVolumeAutomation[i] = state.volumeAutomation
          .map((p) => p.copy())
          .toList(growable: false);
      _rowPluginAutomation[i] = state.pluginAutomation.map(
        (key, value) =>
            MapEntry(key, value.map((p) => p.copy()).toList(growable: false)),
      );
      _rowAutomationClips[i] = state.automationClips.map(
        (key, value) => MapEntry(
          key,
          value.map((clip) => clip.copyWith()).toList(growable: false),
        ),
      );
      _rowAutomationTargets[i] = Map<String, _AutomationTargetMeta>.from(
        state.automationTargets,
      );
      _rowSelectedAutomationTarget[i] = state.selectedAutomationTarget;
      if (i < _rowGainSnapshot.length) {
        _rowGainSnapshot[i] = state.gainSnapshot;
      }
      if (i < _rowPanSnapshot.length) {
        _rowPanSnapshot[i] = state.panSnapshot;
      }
      if (i < _rowAutomationSnapshot.length) {
        _rowAutomationSnapshot[i] = state.automationSnapshot
            .map((point) => point.copy())
            .toList(growable: false);
      }
      if (state.peakHoldDb != null) {
        _rowPeakHoldDb[i] = state.peakHoldDb!;
      }
      if (state.peakHoldLastUpdate != null) {
        _rowPeakHoldLastUpdate[i] = state.peakHoldLastUpdate!;
      }
      if (state.peakHoldFreezeUntil != null) {
        _rowPeakHoldFreezeUntil[i] = state.peakHoldFreezeUntil!;
      }
    }

    if (syncClipRows) {
      _syncAudioTrackRowsToCurrentRows(previousIndexById: previousRowIndexById);
    }
    await _syncTrackGroupsToEngine();
    _pruneAutomationDiscoveryCaches();

    if (refreshAutomationTargets && !_isProjectLoading) {
      await _refreshAutomationTargetsForAllRows();
    }

    if (setStateWhenDone) {
      _refreshAudioEditorView();
    }
  }

  Future<void> _reloadRowsFromEngine({
    bool refreshAutomationTargets = true,
  }) async {
    final previousRowsById = <int, TimelineRow>{
      for (final row in _rows)
        if (row.rowId >= 0) row.rowId: row,
    };
    final rawRows = await JuceAudioEngine.getRows();
    final nextRows = rawRows
        .map((m) {
          final rowId = (m['rowId'] as num?)?.toInt() ?? -1;
          final previous = previousRowsById[rowId];
          return TimelineRow(
            rowId: rowId,
            name: (m['name'] as String?) ?? previous?.name ?? '',
            iconId: (m['iconId'] as num?)?.toInt() ?? previous?.iconId ?? 0,
            kind: previous?.kind ?? TimelineRowKind.audio,
            instrumentId: previous?.instrumentId ?? '',
            instrumentName: previous?.instrumentName ?? '',
            instrumentParams: previous == null
                ? const <String, double>{}
                : Map<String, double>.from(previous.instrumentParams),
            hostedInstrumentStateBase64:
                previous?.hostedInstrumentStateBase64 ?? '',
            roleOverride: previous?.roleOverride ?? '',
            groupId: previous?.groupId ?? '',
            color: previous?.color ?? 0,
            inputDeviceName: previous?.inputDeviceName ?? '',
            inputChannelStart: previous?.inputChannelStart ?? 0,
            inputChannelCount: previous?.inputChannelCount ?? 1,
          );
        })
        .where((r) => r.rowId >= 0)
        .toList(growable: false);
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: refreshAutomationTargets,
    );
  }

  Future<void> _ensureRowExistsForClipInsertion() async {
    if (_rowCount > 0) return;
    final id = await JuceAudioEngine.addRow('Track 1', iconId: 0);
    if (id >= 0) {
      await _applyRowsToEditorState(
        <TimelineRow>[TimelineRow(rowId: id, name: 'Track 1', iconId: 0)],
        refreshAutomationTargets: !_isProjectLoading,
        syncClipRows: false,
      );
    }
  }

  Future<void> _ensureRowIndexExists(int rowIndex) async {
    if (rowIndex < 0) return;
    if (rowIndex >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return;
    }
    while (_rowCount <= rowIndex) {
      if (_rowCount >= _effectiveMaxRows) {
        _showRowLimitReachedNotice();
        return;
      }
      final next = _rowCount + 1;
      final id = await JuceAudioEngine.addRow('Track $next', iconId: 0);
      if (id < 0) break;
      await _applyRowsToEditorState(
        <TimelineRow>[
          ..._rows,
          TimelineRow(rowId: id, name: 'Track $next', iconId: 0),
        ],
        refreshAutomationTargets: !_isProjectLoading,
        syncClipRows: false,
      );
    }
  }

  Future<void> _restoreRowsFromProjectJson(
    List<Map<String, dynamic>> savedRows,
    List tracks,
  ) async {
    // Preliminary engine row reloads reconcile groups against rows that have
    // not received their persisted group IDs yet. Retain the authoritative
    // project metadata until the persisted rows are ready to be applied.
    final persistedTrackGroups = _trackGroups
        .map(_cloneTrackGroup)
        .toList(growable: false);
    const int kDefaultRows = 1;
    final bool isFreshProject = savedRows.isEmpty && tracks.isEmpty;
    int targetRowCount = savedRows.length;
    if (targetRowCount <= 0 && tracks.isNotEmpty) {
      int maxTrackRow = -1;
      for (final t in tracks) {
        final map = (t as Map).cast<String, dynamic>();
        final row = (map["rowIndex"] as num?)?.toInt() ?? 0;
        if (row > maxTrackRow) maxTrackRow = row;
      }
      targetRowCount = maxTrackRow + 1;
    }
    if (targetRowCount <= 0) {
      targetRowCount = isFreshProject
          ? kDefaultRows
          : (_rowCount > 0 ? _rowCount : 1);
    }

    final currentIds = _rows.map((r) => r.rowId).toList();
    final persistedRowIds = savedRows
        .map((row) => (row['rowId'] as num?)?.toInt() ?? -1)
        .toList(growable: false);
    final canRestoreStableRowIds =
        persistedRowIds.isNotEmpty &&
        persistedRowIds.every((rowId) => rowId > 0) &&
        persistedRowIds.toSet().length == persistedRowIds.length;

    if (canRestoreStableRowIds) {
      while (currentIds.length > 1) {
        final rowId = currentIds.removeLast();
        if (!await JuceAudioEngine.removeRow(rowId)) {
          throw StateError('project_row_identity_restore_failed');
        }
      }

      final firstPersistedId = persistedRowIds.first;
      if (currentIds.isEmpty || currentIds.first != firstPersistedId) {
        final firstRow = savedRows.first;
        final restoredId = await JuceAudioEngine.addRow(
          (firstRow['name'] ?? 'Track 1').toString(),
          iconId: (firstRow['iconId'] as num?)?.toInt() ?? 0,
          preferredRowId: firstPersistedId,
        );
        if (restoredId != firstPersistedId) {
          throw StateError('project_row_identity_restore_failed');
        }
        if (currentIds.isNotEmpty) {
          final previousId = currentIds.removeLast();
          if (!await JuceAudioEngine.removeRow(previousId)) {
            throw StateError('project_row_identity_restore_failed');
          }
        }
        currentIds.add(restoredId);
      }

      for (var index = 1; index < persistedRowIds.length; index++) {
        final row = savedRows[index];
        final restoredId = await JuceAudioEngine.addRow(
          (row['name'] ?? 'Track ${index + 1}').toString(),
          iconId: (row['iconId'] as num?)?.toInt() ?? 0,
          preferredRowId: persistedRowIds[index],
        );
        if (restoredId != persistedRowIds[index]) {
          throw StateError('project_row_identity_restore_failed');
        }
        currentIds.add(restoredId);
      }
    } else {
      while (currentIds.length < targetRowCount &&
          currentIds.length < kMaxRows) {
        final next = currentIds.length + 1;
        final id = await JuceAudioEngine.addRow('Track $next', iconId: 0);
        if (id < 0) break;
        currentIds.add(id);
      }

      while (currentIds.length > targetRowCount && currentIds.length > 1) {
        final rowId = currentIds.removeLast();
        final ok = await JuceAudioEngine.removeRow(rowId);
        if (!ok) break;
      }
    }

    await _reloadRowsFromEngine(refreshAutomationTargets: false);

    if (isFreshProject) {
      for (int i = 0; i < _rowCount; i++) {
        final rowId = _rowIdAt(i);
        if (rowId < 0) continue;
        await JuceAudioEngine.renameRow(rowId, 'Track ${i + 1}');
        await JuceAudioEngine.setRowIcon(rowId, 0);
      }
      await _reloadRowsFromEngine(refreshAutomationTargets: false);
      await _recomputeAudibleState();
      return;
    }

    for (int i = 0; i < savedRows.length && i < _rowCount; i++) {
      final row = savedRows[i];
      final name = (row["name"] as String?)?.trim() ?? "";
      final iconId = (row["iconId"] as num?)?.toInt() ?? 0;
      final rowId = _rowIdAt(i);
      if (rowId < 0) continue;
      if (name.isNotEmpty) {
        await JuceAudioEngine.renameRow(rowId, name);
      }
      await JuceAudioEngine.setRowIcon(rowId, iconId);
    }

    await _reloadRowsFromEngine(refreshAutomationTargets: false);
    final restoredRows = <TimelineRow>[];
    for (int i = 0; i < _rowCount; i++) {
      final saved = i < savedRows.length
          ? _timelineRowFromJson(savedRows[i])
          : null;
      final current = _rows[i];
      restoredRows.add(
        TimelineRow(
          rowId: current.rowId,
          name: saved?.name.isNotEmpty == true ? saved!.name : current.name,
          iconId: saved?.iconId ?? current.iconId,
          kind: saved?.kind ?? TimelineRowKind.audio,
          instrumentId: saved?.instrumentId ?? '',
          instrumentName: saved?.instrumentName ?? '',
          instrumentParams: saved == null
              ? const <String, double>{}
              : Map<String, double>.from(saved.instrumentParams),
          hostedInstrumentStateBase64: saved?.hostedInstrumentStateBase64 ?? '',
          roleOverride: saved?.roleOverride ?? '',
          groupId: saved?.groupId ?? '',
          color: saved?.color ?? 0,
          inputDeviceName: saved?.inputDeviceName ?? '',
          inputChannelStart: saved?.inputChannelStart ?? 0,
          inputChannelCount: saved?.inputChannelCount ?? 1,
        ),
      );
    }
    if (persistedTrackGroups.isNotEmpty) {
      _trackGroups
        ..clear()
        ..addAll(persistedTrackGroups);
    }
    _seedMissingTrackGroupsFromRows(restoredRows);
    await _applyRowsToEditorState(
      restoredRows,
      refreshAutomationTargets: false,
      syncClipRows: false,
    );
    for (int i = 0; i < restoredRows.length; i++) {
      final override = restoredRows[i].roleOverride;
      if (override.isNotEmpty) {
        _chatPipeline.setRoleOverride(rowIndex: i, role: override);
      }
    }
  }

