  Future<void> _shutdownAudioEngineV2Aware() {
    _androidV2ForegroundRecoveryPending = false;
    final existing = _audioEngineShutdownFuture;
    if (existing != null) return existing;
    final priorShutdown = _processAudioEngineShutdownFuture;
    final shutdown = (() async {
      if (priorShutdown != null) {
        try {
          await priorShutdown;
        } catch (_) {
          // This editor must still close its own coordinator and engine.
        }
      }
      await _performAudioEngineShutdownV2Aware();
    })();
    _audioEngineShutdownFuture = shutdown;
    _processAudioEngineShutdownFuture = shutdown;
    unawaited(
      shutdown.then<void>(
        (_) {
          if (identical(_processAudioEngineShutdownFuture, shutdown)) {
            _processAudioEngineShutdownFuture = null;
          }
        },
        onError: (Object _, StackTrace __) {
          if (identical(_processAudioEngineShutdownFuture, shutdown)) {
            _processAudioEngineShutdownFuture = null;
          }
        },
      ),
    );
    return shutdown;
  }

  Future<void> _performAudioEngineShutdownV2Aware() async {
    final unpublishedRecordingPath = _detachPendingUnpublishedRecordingPath();
    try {
      final routeRecovery = _v2AudioSessionRecoveryFuture;
      _audioRouteCoordinatorV2?.cancelPendingRecoveryForShutdown();
      if (routeRecovery != null) {
        try {
          await routeRecovery;
        } catch (_) {
          // Shutdown must still close the coordinator and engine if recovery fails.
        }
      }
      final coordinator = _audioRouteCoordinatorV2;
      _audioRouteCoordinatorV2 = null;
      if (_isBluetoothV2Session &&
          _supportsV2AudioRecording &&
          coordinator?.intent != AudioRouteIntentV2.playbackOnly) {
        await JuceAudioEngine.abortRecordingV2();
      }
      await coordinator?.dispose();
      await JuceAudioEngine.shutdown();
    } finally {
      if (unpublishedRecordingPath != null) {
        await _deleteUncommittedRecordingFile(unpublishedRecordingPath);
      }
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (defaultTargetPlatform == TargetPlatform.android) {
      if (state == AppLifecycleState.resumed) {
        debugPrint("App Resumed on Android - Re-initializing.");
        unawaited(_handleAndroidEditorResumed());
      } else if (_isEditorBackgroundState(state) ||
          (state == AppLifecycleState.inactive && !_isBluetoothV2Session)) {
        _markProjectDirty(immediate: true);
        _scheduleCloudAutoSync(reason: 'background', immediate: true);
        _flushAndRequestLocalVersionSnapshot(
          reason: ProjectVersionReason.background,
          minInterval: const Duration(minutes: 10),
        );
        final coordinator = _audioRouteCoordinatorV2;
        final v2RecordingActive =
            _isBluetoothV2Session &&
            _supportsV2AudioRecording &&
            coordinator != null &&
            (_isRecording ||
                _recordStartVisualPending ||
                coordinator.intent != AudioRouteIntentV2.playbackOnly);
        if (v2RecordingActive) {
          unawaited(_handleAndroidV2EditorBackgrounded());
        } else {
          debugPrint('App Backgrounded on Android - Pausing playback.');
          unawaited(_pausePlayback());
          setState(() {
            _isPlaying = false;
          });
        }
      }
    } else if (defaultTargetPlatform == TargetPlatform.iOS) {
      if (state == AppLifecycleState.resumed) {
        if (_isBluetoothV2Session) {
          unawaited(_resumeIOSV2AudioAfterForeground());
        } else if (_bluetoothImplementationSessionV2 != null &&
            !_isBluetoothV2Session) {
          unawaited(_refreshMicrophonePermissionAndInputs());
          unawaited(_refreshAudioRouteInfo());
        }
      } else if (_isEditorBackgroundState(state) ||
          (state == AppLifecycleState.inactive && !_isBluetoothV2Session)) {
        _markProjectDirty(immediate: true);
        _scheduleCloudAutoSync(reason: 'background', immediate: true);
        _flushAndRequestLocalVersionSnapshot(
          reason: ProjectVersionReason.background,
          minInterval: const Duration(minutes: 10),
        );
        unawaited(_pauseAudio(_safeAudioEditorStateSetter));
        setState(() {
          _isPlaying = false;
        });
        if (_isBluetoothV2Session &&
            (state == AppLifecycleState.paused ||
                state == AppLifecycleState.hidden)) {
          unawaited(_handleIOSV2EditorBackgrounded());
        }
      }
    }
  }

  bool _isEditorBackgroundState(AppLifecycleState state) =>
      state == AppLifecycleState.paused ||
      state == AppLifecycleState.hidden ||
      state == AppLifecycleState.detached;

  Future<void> _handleAndroidV2EditorBackgrounded() async {
    if (!mounted ||
        !_isBluetoothV2Session ||
        _audioRouteCoordinatorV2 == null) {
      return;
    }
    _androidV2ForegroundRecoveryPending = true;
    if (_v2AudioSessionInvalidated) return;
    _audioRouteCoordinatorV2?.beginLocalInvalidationEpisode();
    final unpublishedRecordingPath = _enterV2AudioSessionSafetyBoundary(
      notice: 'Recording stopped because Mixroom went to the background.',
    );
    final cleanup = _cleanupV2InterruptedAudio(
      unpublishedRecordingPath: unpublishedRecordingPath,
    );
    _trackV2AudioSessionRecovery(cleanup);
    await cleanup;
  }

  Future<void> _handleIOSV2EditorBackgrounded() async {
    if (!mounted ||
        !_isBluetoothV2Session ||
        _audioRouteCoordinatorV2 == null ||
        _v2AudioSessionInvalidated) {
      return;
    }
    _iosV2ForegroundRecoveryPending = true;
    _audioRouteCoordinatorV2?.beginLocalInvalidationEpisode();
    final unpublishedRecordingPath = _enterV2AudioSessionSafetyBoundary(
      notice: 'Audio is temporarily unavailable.',
    );
    final cleanup = _cleanupV2InterruptedAudio(
      unpublishedRecordingPath: unpublishedRecordingPath,
    );
    _trackV2AudioSessionRecovery(cleanup);
    await cleanup;
  }

  Future<void> _resumeIOSV2AudioAfterForeground() async {
    if (!_iosV2ForegroundRecoveryPending || !mounted) return;
    final cleanup = _v2AudioSessionRecoveryFuture;
    if (cleanup != null) await cleanup;
    // UIApplicationDidBecomeActiveNotification emits the single native
    // foreground-reconciliation event. Its coordinator callback owns reopen.
  }

  bool get _shouldDeferAndroidRouteRefresh =>
      defaultTargetPlatform == TargetPlatform.android &&
      (_isLoadingNextScreen ||
          _isProjectLoading ||
          _isLoadingAudio ||
          _androidEngineCriticalSectionDepth > 0);

  Future<T> _runWithAndroidEngineCriticalSection<T>(
    Future<T> Function() action,
  ) async {
    if (defaultTargetPlatform != TargetPlatform.android) {
      return action();
    }
    _androidEngineCriticalSectionDepth += 1;
    try {
      return await action();
    } finally {
      _androidEngineCriticalSectionDepth = math.max(
        0,
        _androidEngineCriticalSectionDepth - 1,
      );
      if (_androidEngineCriticalSectionDepth == 0) {
        unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
      }
    }
  }

  Future<void> _requestAndroidRouteRefresh({required String reason}) async {
    if (_isBluetoothV2Session) return;
    if (defaultTargetPlatform != TargetPlatform.android) {
      await JuceAudioEngine.refreshAudioRoute(reason: reason);
      return;
    }
    if (_androidRouteRefreshInFlight || _shouldDeferAndroidRouteRefresh) {
      _pendingAndroidRouteRefresh = true;
      _pendingAndroidRouteRefreshReason = reason;
      debugPrint(
        'Deferring Android audio route refresh while engine is busy: $reason',
      );
      return;
    }

    _androidRouteRefreshInFlight = true;
    try {
      await JuceAudioEngine.refreshAudioRoute(reason: reason);
    } finally {
      _androidRouteRefreshInFlight = false;
    }

    if (_pendingAndroidRouteRefresh) {
      unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
    }
  }

  Future<bool> _ensurePlaybackRouteReady({required String reason}) async {
    if (_isBluetoothV2Session) {
      if (_v2AudioSessionInvalidated) {
        if (mounted) {
          _showSmallNotice(_v2AudioSessionInvalidationNotice);
        }
        return false;
      }
      if (_v2AudioSessionRecoveryInProgress) {
        if (mounted) {
          _showSmallNotice('Audio output is changing. Please wait.');
        }
        return false;
      }
      final coordinator = _audioRouteCoordinatorV2;
      if (_usesLiveAudioRouteCoordinatorV2 &&
          coordinator != null &&
          coordinator.state != AudioRouteCoordinatorStateV2.stable) {
        if (mounted) {
          _showSmallNotice(
            coordinator.state == AudioRouteCoordinatorStateV2.failed
                ? 'Audio output is unavailable. Reopen the audio editor.'
                : 'Audio output is changing. Please wait.',
          );
        }
        return false;
      }
      final macIndependentInputRecording =
          Platform.isMacOS &&
          coordinator?.intent == AudioRouteIntentV2.recording;
      final ready =
          macIndependentInputRecording ||
          await JuceAudioEngine.validatePlaybackV2();
      if (!ready && mounted) {
        _showSmallNotice(
          Platform.isAndroid
              ? 'Audio output could not be restored. Reopen the audio editor.'
              : Platform.isIOS
              ? 'Audio output is unavailable. Check the iOS audio output.'
              : 'Audio output could not be restored. Reopen the audio editor.',
        );
      }
      if (!ready) return false;
      return JuceAudioEngine.preparePlaybackGraph(reason: reason);
    }
    var ok = false;
    try {
      ok = await JuceAudioEngine.preparePlaybackRoute(
        reason: reason,
      ).timeout(const Duration(seconds: 4));
    } on TimeoutException {
      debugPrint('preparePlaybackRoute timed out: $reason');
      return false;
    } catch (e) {
      debugPrint('preparePlaybackRoute failed [$reason]: $e');
      return false;
    }
    if (!ok && mounted) {
      debugPrint('preparePlaybackRoute failed: $reason');
    }
    return ok;
  }

  void _handleAudioRouteIntentInvalidatedV2(AudioRouteChangeEventV2 event) {
    if (!mounted || !_supportsV2AudioRecording || !_isBluetoothV2Session) {
      return;
    }
    if (_v2AudioSessionInvalidated) {
      final foregroundRecoveryEvent =
          Platform.isIOS &&
          _iosV2ForegroundRecoveryPending &&
          event.cause == 'audioInterruptionEnded';
      if (foregroundRecoveryEvent) {
        _iosV2ForegroundRecoveryPending = false;
        final cleanup = _v2AudioSessionRecoveryFuture;
        final recovery = () async {
          if (cleanup != null) await cleanup;
          await _recoverV2PlaybackAfterAudioSessionInvalidation(
            shouldAttemptSystemOutputRecovery: true,
            unpublishedRecordingPath: null,
            successNotice: 'Audio is ready. Press Play to continue.',
          );
        }();
        _trackV2AudioSessionRecovery(recovery);
      }
      return;
    }
    final interruption =
        event.cause == 'audioInterruptionBegan' ||
        event.cause == 'audioInterruptionEnded' ||
        event.cause == 'audioInterrupted';
    final shouldAttemptSystemOutputRecovery =
        (Platform.isIOS || Platform.isAndroid || Platform.isMacOS) &&
        event.cause != 'shutdown';
    final recordingWasActive =
        _isRecording ||
        _recordStartVisualPending ||
        _audioRouteCoordinatorV2?.intent != AudioRouteIntentV2.playbackOnly;
    final pendingNotice = interruption
        ? (recordingWasActive
              ? 'Audio was interrupted. Recording stopped.'
              : 'Audio is temporarily unavailable.')
        : (shouldAttemptSystemOutputRecovery
              ? 'Audio output is changing. Please wait.'
              : 'Audio output changed during recording. Reopen the audio editor to continue.');
    final unpublishedRecordingPath = _enterV2AudioSessionSafetyBoundary(
      notice: pendingNotice,
    );
    if (interruption) _showSmallNotice(pendingNotice);
    final recoverySuccessNotice = interruption
        ? 'Audio is ready. Press Play to continue.'
        : recordingWasActive
        ? 'Recording stopped because the audio device changed. Press Play to continue.'
        : 'Audio output changed. Press Play to continue.';
    final recovery = _recoverV2PlaybackAfterAudioSessionInvalidation(
      shouldAttemptSystemOutputRecovery: shouldAttemptSystemOutputRecovery,
      unpublishedRecordingPath: unpublishedRecordingPath,
      cleanupBeforeRecovery: interruption || Platform.isAndroid,
      successNotice: recoverySuccessNotice,
    );
    _trackV2AudioSessionRecovery(recovery);
  }

  String? _enterV2AudioSessionSafetyBoundary({required String notice}) {
    final pausedPosition = _isPlaying
        ? _estimateTransportClockFromSample()
        : _globalAudioClock;
    final unpublishedRecordingPath = _detachPendingUnpublishedRecordingPath();
    _v2AudioSessionInvalidationNotice = notice;
    _v2AudioSessionInvalidated = true;
    _v2AudioSessionRecoveryInProgress = true;
    _recordStartCancelRequested = true;
    _transportDesiredPlaying = false;
    ++_transportCommandSerial;
    _transportTicker?.stop();
    _stopRecordingPeakPolling(clearSamples: true);
    _stopMeterPolling();
    setState(() {
      _isPlaying = false;
      _isRecording = false;
      _recordStartVisualPending = false;
      _recordingFilePath = null;
      _syncTransportClock(pausedPosition, playing: false);
    });
    return unpublishedRecordingPath;
  }

  void _trackV2AudioSessionRecovery(Future<void> recovery) {
    _v2AudioSessionRecoveryFuture = recovery;
    unawaited(
      recovery.whenComplete(() {
        if (identical(_v2AudioSessionRecoveryFuture, recovery)) {
          _v2AudioSessionRecoveryFuture = null;
        }
      }),
    );
  }

  Future<void> _cleanupV2InterruptedAudio({
    required String? unpublishedRecordingPath,
  }) async {
    await JuceAudioEngine.abortRecordingV2(restorePlayback: false);
    if (unpublishedRecordingPath != null) {
      await _deleteUncommittedRecordingFile(unpublishedRecordingPath);
    }
  }

  Future<void> _recoverV2PlaybackAfterAudioSessionInvalidation({
    required bool shouldAttemptSystemOutputRecovery,
    required String? unpublishedRecordingPath,
    bool cleanupBeforeRecovery = false,
    required String successNotice,
  }) async {
    if (cleanupBeforeRecovery) {
      await _cleanupV2InterruptedAudio(
        unpublishedRecordingPath: unpublishedRecordingPath,
      );
      unpublishedRecordingPath = null;
    }
    if (_shouldDeferAndroidV2RecoveryUntilForeground) return;
    AudioRouteTransitionResultV2? recoveryResult;
    if (shouldAttemptSystemOutputRecovery) {
      recoveryResult = await _audioRouteCoordinatorV2
          ?.recoverPlaybackAfterIntentInvalidation();
    }
    if (_shouldDeferAndroidV2RecoveryUntilForeground) return;
    if (recoveryResult != null && recoveryResult.succeeded) {
      if (unpublishedRecordingPath != null) {
        await _deleteUncommittedRecordingFile(unpublishedRecordingPath);
      }
      JuceAudioEngine.acceptVerifiedAudioRouteTransitionV2(recoveryResult);
      if (!mounted) return;
      final recoveredJuceName =
          recoveryResult.snapshot.juce.outputDeviceName?.trim() ?? '';
      final recoveredEndpointName = recoveryResult.snapshot.outputs.isEmpty
          ? ''
          : recoveryResult.snapshot.outputs.first.name.trim();
      final recoveredOutputName = recoveredJuceName.isNotEmpty
          ? recoveredJuceName
          : recoveredEndpointName;
      setState(() {
        _v2AudioSessionInvalidated = false;
        _v2AudioSessionRecoveryInProgress = false;
        _v2AudioSessionInvalidationNotice = successNotice;
        if (Platform.isMacOS && recoveredOutputName.isNotEmpty) {
          _macOutputDeviceName = recoveredOutputName;
        }
      });
      if (Platform.isMacOS) unawaited(_loadMacV2AudioDevices());
      _showSmallNotice(_v2AudioSessionInvalidationNotice);
      return;
    }

    await JuceAudioEngine.abortRecordingV2(restorePlayback: false);
    final coordinator = _audioRouteCoordinatorV2;
    _audioRouteCoordinatorV2 = null;
    await coordinator?.dispose();
    await JuceAudioEngine.shutdown();
    if (unpublishedRecordingPath != null) {
      await _deleteUncommittedRecordingFile(unpublishedRecordingPath);
    }
    if (!mounted) return;
    setState(() {
      _v2AudioSessionRecoveryInProgress = false;
      _v2AudioSessionInvalidationNotice =
          'Audio output could not be restored. Reopen the audio editor.';
    });
    _showSmallNotice(_v2AudioSessionInvalidationNotice);
  }

  Future<void> _synchronizeIOSRouteSafetyPositionV2({
    required int commandSerial,
  }) async {
    await _pauseAudio(
      _safeAudioEditorStateSetter,
      commandSerial: commandSerial,
    );
    if (!mounted || commandSerial != _transportCommandSerial) return;
    _syncTransportClock(_globalAudioClock, playing: false);
  }

  void _handleAudioRouteCoordinatorStateV2(AudioRouteCoordinatorStateV2 state) {
    if (!mounted || state != AudioRouteCoordinatorStateV2.reconfiguring) {
      return;
    }
    final pausedPosition = _isPlaying
        ? _estimateTransportClockFromSample()
        : _globalAudioClock;
    _transportDesiredPlaying = false;
    final commandSerial = ++_transportCommandSerial;
    _transportTicker?.stop();
    setState(() {
      _isPlaying = false;
      _syncTransportClock(pausedPosition, playing: false);
    });
    _stopMeterPolling();
    if (Platform.isIOS) {
      unawaited(
        _synchronizeIOSRouteSafetyPositionV2(commandSerial: commandSerial),
      );
    }
  }

  void _handleAudioRouteTransitionV2(AudioRouteTransitionResultV2 result) {
    if (!mounted) return;
    if (!result.succeeded) {
      _showSmallNotice(
        Platform.isAndroid
            ? 'Audio output is unavailable. Choose an output in Android.'
            : Platform.isIOS
            ? 'Audio output is unavailable. Check the iOS audio output.'
            : result.diagnosticCode == 'output_selection_unavailable'
            ? L10n.translate(
                context,
                'Selected output device is not available.',
              )
            : 'Audio output is unavailable. Choose an output in macOS.',
      );
      return;
    }

    JuceAudioEngine.acceptVerifiedAudioRouteTransitionV2(result);
    final juceName = result.snapshot.juce.outputDeviceName?.trim() ?? '';
    final endpointName = result.snapshot.outputs.isEmpty
        ? ''
        : result.snapshot.outputs.first.name.trim();
    if (Platform.isMacOS) {
      final outputName = juceName.isNotEmpty ? juceName : endpointName;
      if (outputName.isNotEmpty) {
        _setStateAndRefreshProjectSettings(() {
          _macOutputDeviceName = outputName;
        });
      }
      unawaited(_loadMacV2AudioDevices());
      if (result.bluetoothCommunicationQualityReduced &&
          !_macBluetoothCommunicationQualityNoticeShown) {
        _macBluetoothCommunicationQualityNoticeShown = true;
        _showSmallNotice(
          'Bluetooth microphone selected. Playback quality is reduced. Select another microphone for stereo audio.',
        );
        return;
      }
      if (!result.bluetoothCommunicationQualityReduced) {
        _macBluetoothCommunicationQualityNoticeShown = false;
      }
    }
    if (result.status == AudioRouteTransitionStatusV2.fallback) {
      _showSmallNotice(
        'Bluetooth disconnected. Audio output changed. Press Play to continue.',
      );
      return;
    }

    if (Platform.isAndroid) {
      _showSmallNotice('Audio output changed. Press Play to continue.');
    } else if (Platform.isIOS) {
      _showSmallNotice('Audio output changed. Press Play to continue.');
    } else {
      final outputName = juceName.isNotEmpty
          ? juceName
          : (endpointName.isNotEmpty ? endpointName : 'Mac output');
      _showSmallNotice(
        'Audio output changed to $outputName. Press Play to continue.',
      );
    }
  }

  Future<void> _flushDeferredAndroidRouteRefreshIfNeeded() async {
    if (_isBluetoothV2Session) return;
    if (defaultTargetPlatform != TargetPlatform.android) return;
    if (!_pendingAndroidRouteRefresh ||
        _androidRouteRefreshInFlight ||
        _shouldDeferAndroidRouteRefresh) {
      return;
    }

    final reason = _pendingAndroidRouteRefreshReason ?? 'deferred';
    _pendingAndroidRouteRefresh = false;
    _pendingAndroidRouteRefreshReason = null;
    await _requestAndroidRouteRefresh(reason: 'deferred:$reason');
    await _refreshAudioRouteInfo(refreshNativeRoute: false);
  }

  Future<void> _handleAndroidEditorResumed() async {
    if (_isBluetoothV2Session) {
      await _resumeAndroidV2AudioAfterForeground();
    } else {
      await _requestAndroidRouteRefresh(reason: 'appResumed');
    }
    if (!mounted) return;
    await _refreshMicrophonePermissionAndInputs();
    await _refreshAudioRouteInfo(refreshNativeRoute: false);
  }

  Future<void> _resumeAndroidV2AudioAfterForeground() async {
    if (!_androidV2ForegroundRecoveryPending || !mounted) return;
    final cleanup = _v2AudioSessionRecoveryFuture;
    if (cleanup != null) await cleanup;
    if (!mounted ||
        !_androidV2ForegroundRecoveryPending ||
        WidgetsBinding.instance.lifecycleState != AppLifecycleState.resumed) {
      return;
    }
    _androidV2ForegroundRecoveryPending = false;
    final coordinator = _audioRouteCoordinatorV2;
    if (!_v2AudioSessionInvalidated || coordinator == null) return;
    coordinator.beginLocalInvalidationEpisode();
    final recovery = _recoverV2PlaybackAfterAudioSessionInvalidation(
      shouldAttemptSystemOutputRecovery: true,
      unpublishedRecordingPath: null,
      successNotice:
          'Recording stopped because Mixroom went to the background.',
    );
    _trackV2AudioSessionRecovery(recovery);
    await recovery;
  }

  bool get _shouldDeferAndroidV2RecoveryUntilForeground =>
      defaultTargetPlatform == TargetPlatform.android &&
      _androidV2ForegroundRecoveryPending;

  Uri _producerCaptureUiAccessUri() {
    final base = AppApiConfig.apiBaseUrl.trim().replaceFirst(RegExp(r'/$'), '');
    return Uri.parse('$base/v1/users/me/producer-capture-ui-access');
  }

  Future<http.Response> _fetchProducerCaptureUiAccess(String token) {
    return _producerCaptureAccessHttpClient
        .get(
          _producerCaptureUiAccessUri(),
          headers: <String, String>{
            'Authorization': 'Bearer $token',
            'Accept': 'application/json',
          },
        )
        .timeout(
          Duration(
            seconds: math.max(
              1,
              math.min(AppApiConfig.requestTimeoutSeconds, 6),
            ),
          ),
        );
  }

  Future<http.Response?> _fetchProducerCaptureUiAccessWithCandidates(
    List<String> tokenCandidates,
  ) async {
    http.Response? lastResponse;
    for (final token in tokenCandidates) {
      final response = await _fetchProducerCaptureUiAccess(token);
      if (!_isUnauthorizedStatusCode(response.statusCode)) {
        return response;
      }
      lastResponse = response;
    }
    return lastResponse;
  }

  bool _isUnauthorizedStatusCode(int statusCode) {
    return statusCode == 401 || statusCode == 403;
  }

  String _normalizedProducerCaptureUsername(String raw) {
    return raw.trim().toLowerCase();
  }

  String _fallbackProducerCaptureUsername() {
    try {
      final snapshot = context.read<AppUserService>().current;
      final fromProfile = _normalizedProducerCaptureUsername(
        snapshot?.username ?? '',
      );
      if (fromProfile.isNotEmpty) return fromProfile;
      final fromCognito = _normalizedProducerCaptureUsername(
        snapshot?.cognitoUsername ?? '',
      );
      if (fromCognito.contains('@')) return '';
      return fromCognito;
    } catch (_) {
      return '';
    }
  }

  void _applyProducerCaptureUiAllowlistAccess({
    required bool allowlisted,
    required String username,
  }) {
    final normalizedUsername = _normalizedProducerCaptureUsername(username);
    final shouldDisableUi = !allowlisted && _showProducerCaptureUi;
    final shouldDisableMode = !allowlisted && _producerDataMode;
    final changed =
        _producerCaptureUiAllowlisted != allowlisted ||
        _producerCaptureAllowlistUsername != normalizedUsername ||
        shouldDisableUi ||
        shouldDisableMode;
    if (!changed) return;

    _setStateAndRefreshProjectSettings(() {
      _producerCaptureUiAllowlisted = allowlisted;
      _producerCaptureAllowlistUsername = normalizedUsername;
      if (!allowlisted) {
        _showProducerCaptureUi = false;
        _producerDataMode = false;
        _producerUiBusy = false;
        _producerGuidedPromptAwaitingFinal = false;
        _producerCapturePanelMinimized = true;
        _producerPromptSubmitting = false;
        _producerPromptQueueIds = <String>[];
        _producerPromptQueueIndex = 0;
      }
    });
    _scheduleProjectAutosave();
    if (!allowlisted) {
      unawaited(_producerCollector.setEnabled(false));
    }
  }

  Future<void> _refreshProducerCaptureUiAllowlistAccess() async {
    final fallbackUsername = _fallbackProducerCaptureUsername();
    var resolvedUsername = fallbackUsername;
    var allowlisted = kDefaultProducerCaptureUsernameAllowlist.contains(
      fallbackUsername,
    );

    if (AppApiConfig.hasApiBaseUrl) {
      try {
        final auth = context.read<AuthService>();
        final initialCandidates = await auth.getRequestTokenCandidates();
        if (initialCandidates.isEmpty) {
          if (!mounted) return;
          _applyProducerCaptureUiAllowlistAccess(
            allowlisted: allowlisted,
            username: resolvedUsername,
          );
          return;
        }
        var response = await _fetchProducerCaptureUiAccessWithCandidates(
          initialCandidates,
        );
        if (response != null &&
            _isUnauthorizedStatusCode(response.statusCode)) {
          final refreshedCandidates = await auth.getRequestTokenCandidates(
            forceRefresh: true,
          );
          final retryCandidates = refreshedCandidates
              .where((token) => !initialCandidates.contains(token))
              .toList();
          if (retryCandidates.isNotEmpty) {
            response = await _fetchProducerCaptureUiAccessWithCandidates(
              retryCandidates,
            );
          }
        }
        if (response != null &&
            response.statusCode >= 200 &&
            response.statusCode < 300) {
          final decoded = jsonDecode(response.body);
          if (decoded is Map) {
            final usernameFromApi = _normalizedProducerCaptureUsername(
              (decoded['username'] ?? '').toString(),
            );
            if (usernameFromApi.isNotEmpty) {
              resolvedUsername = usernameFromApi;
            }
            allowlisted = decoded['enabled'] == true;
          }
        }
      } catch (error) {
        debugPrint(
          'Producer capture allowlist access fallback applied: $error',
        );
      }
    }

    if (!mounted) return;
    _applyProducerCaptureUiAllowlistAccess(
      allowlisted: allowlisted,
      username: resolvedUsername,
    );
  }

  Map<String, dynamic> _masterStateFromProjectJson(Map<String, dynamic> json) {
    final master = json["master"];
    if (master is Map) {
      return master.cast<String, dynamic>();
    }
    final legacyMasterEffects = json["masterEffects"];
    if (legacyMasterEffects is Map) {
      return <String, dynamic>{
        "effects": legacyMasterEffects.cast<String, dynamic>(),
      };
    }
    return const <String, dynamic>{
      "effects": <String, dynamic>{"effects": <dynamic>[]},
    };
  }

  Future<void> _syncNativeMasterStaticState({
    required double gain,
    required double pan,
    bool clearAutomation = false,
  }) async {
    await JuceAudioEngine.setMasterGain(gain);
    await JuceAudioEngine.setMasterPan(pan);
    if (!clearAutomation) return;
    await JuceAudioEngine.setMasterGainAutomationPoints(
      const <Map<String, dynamic>>[],
    );
    await JuceAudioEngine.setMasterPanAutomationPoints(
      const <Map<String, dynamic>>[],
    );
    await JuceAudioEngine.clearMasterEffectAutomation();
  }

  Future<void> _loadProjectIfAny() async {
    if (_loadedOnce) return;
    _loadedOnce = true;
    _isProjectLoading = true;
    var projectLoadedSuccessfully = false;

    try {
      if (PlatformCapabilities.current.isMobile) {
        await _loadMobileSampleBrowserRoots();
      } else if (!PlatformCapabilities.current.isDesktop) {
        _sampleBrowserRoots.clear();
      }
      _projectLoadIssues.clear();
      _hostedPluginRestoreEntries.clear();
      _sampleDurationCache.clear();
      _waveformCacheByPath.clear();
      _waveformFutureByPath.clear();
      _waveformPendingTracksByPath.clear();
      _waveformFailureCountByPath.clear();
      _indexedClipRowId.clear();
      _clipsByRowId.clear();
      _indexedClipEndMs.clear();
      _clipEndMsCounts.clear();
      _clipOperationIndexesInitialized = false;
      _restoredHostedInstrumentStateByClipId.clear();
      _deferredHostedInstrumentEngineClipIds.clear();
      _sampleBrowserVisible = false;
      _sampleBrowserExpanded = false;
      _sampleDragActive = false;
      _reopenSampleBrowserAfterDrag = false;
      _reopenSampleBrowserExpanded = false;
      _sampleBrowserViewState = const SampleBrowserPanelViewState();
      _tabletRightPanelCollapsed = true;
      _tabletRightPanelHandleDragging = false;
      _setMasterMeterExpandedState(false);
      _invalidateAiLibrarySnapshotCache();
      await _ensureDefaultSampleBrowserRoots();
      final loadResult = await _projectPersistence.loadProjectState(
        _projectDir,
      );
      // Project opening is never allowed to scan every third-party plug-in
      // installed on the machine. It uses the persisted catalog only; a full
      // scan is an explicit Plug-in Settings action. This keeps an unrelated
      // unhealthy VST from preventing a project from opening.
      final compatibilityOpen =
          await ProjectCompatibilityService.resolveForOpen(
            projectDir: _projectDir,
            sourceProject: loadResult.projectState,
            canHostExternalPlugins: _platformCapabilities.externalPluginHosting,
            hasPlugin: _isKnownDesktopPluginId,
          );
      final json = compatibilityOpen.projectState;
      _usingCompatibilityAudio = compatibilityOpen.usingCompatibleAudio;
      _compatibilityAudioRequired =
          !_usingCompatibilityAudio &&
          ProjectCompatibilityService.inspect(
            loadResult.projectState,
          ).needsPluginAudio;
      _compatibilityAudioCurrent =
          _compatibilityAudioRequired &&
          await ProjectCompatibilityService.isCurrent(_projectDir);
      _compatibilityAudioError = '';
      _compatibilityProjectionMetadata = json['compatibility'] is Map
          ? Map<String, dynamic>.from(json['compatibility'] as Map)
          : const <String, dynamic>{};
      _frozenPluginNamesByRow = const <int, List<String>>{};
      if (_usingCompatibilityAudio) {
        final manifest = await ProjectCompatibilityService.readManifest(
          _projectDir,
        );
        if (manifest != null) {
          _frozenPluginNamesByRow =
              ProjectCompatibilityService.frozenPluginNamesByRow(
                manifest: manifest,
                projection: json,
              );
        }
      }
      if (loadResult.warningMessage?.trim().isNotEmpty == true) {
        _projectLoadIssues.add(
          _ProjectLoadIssue(
            type: _ProjectLoadIssueType.recoveredFromBackup,
            title: 'Recovered Project Backup',
            detail: loadResult.warningMessage!.trim(),
          ),
        );
      }
      await _restoreChatHistoryFromProjectJson(json);
      _projectId = ProjectManager.ensureProjectIdInJson(json);
      _projectCreatedAtMs =
          (json["createdAt"] as num?)?.toInt() ??
          DateTime.now().millisecondsSinceEpoch;
      final projectVersion = (json["version"] as num?)?.toInt() ?? 1;
      final master = _masterStateFromProjectJson(json);
      final loadedMasterGain = _normalizeLoadedGainUi(
        (master["gain"] as num?)?.toDouble(),
        projectVersion: projectVersion,
      );
      final loadedMasterPan = ((master["pan"] as num?)?.toDouble() ?? 0.5)
          .clamp(0.0, 1.0)
          .toDouble();
      _masterGain = loadedMasterGain;
      _masterPan = loadedMasterPan;
      await _syncNativeMasterStaticState(
        gain: loadedMasterGain,
        pan: loadedMasterPan,
        clearAutomation: true,
      );
      _projectName = (json["name"] ?? "Untitled Project") as String;
      _cloudProjectId =
          (json["cloudProjectId"] ?? json["cloud_project_id"] ?? '')
              .toString()
              .trim();
      _cloudWorkspaceId =
          (json["cloudWorkspaceId"] ?? json["cloud_workspace_id"] ?? '')
              .toString()
              .trim();
      _cloudOrganizationId =
          (json["cloudOrganizationId"] ?? json["cloud_organization_id"] ?? '')
              .toString()
              .trim();
      final rawCloudDocumentRevision =
          json["cloudDocumentRevision"] ?? json["cloud_document_revision"];
      _cloudDocumentRevision = rawCloudDocumentRevision is num
          ? rawCloudDocumentRevision.toInt()
          : int.tryParse((rawCloudDocumentRevision ?? '').toString().trim());
      _cloudSourceFingerprint = (json['cloudSourceFingerprint'] ?? '')
          .toString()
          .trim();
      _cloudSyncedAt = (json["cloudSyncedAt"] ?? json["cloud_synced_at"] ?? '')
          .toString()
          .trim();
      _requiresProjectNaming = _projectRequiresNameConfirmation(json);
      _tempo =
          (((json["tempoBpm"] as num?) ?? (json["bpm"] as num?) ?? _tempo)
                  .toDouble())
              .clamp(20.0, 999.0);
      _projectKey = normalizeProjectKey((json["projectKey"] ?? '').toString());
      final rawTimeSignature = json["timeSignature"];
      final timeSignatureJson = rawTimeSignature is Map<String, dynamic>
          ? rawTimeSignature
          : rawTimeSignature is Map
          ? rawTimeSignature.cast<String, dynamic>()
          : null;
      _timeSignatureNumerator = _normalizeTimeSignatureNumerator(
        timeSignatureJson?["numerator"] ??
            json["timeSignatureNumerator"] ??
            json["beatsPerBar"],
      );
      _timeSignatureDenominator = _normalizeTimeSignatureDenominator(
        timeSignatureJson?["denominator"] ??
            json["timeSignatureDenominator"] ??
            json["beatUnit"],
      );
      _syncTempoPickerSelection();
      _tempoStretchEnabled = (json["tempoStretchEnabled"] as bool?) ?? false;
      _tempoStretchPreservePitchDefault =
          (json["tempoStretchPreservePitchDefault"] as bool?) ?? false;
      final uiSettings = (json["ui"] as Map?)?.cast<String, dynamic>();
      final savedProducerCaptureUi =
          (uiSettings?["showProducerCaptureUi"] as bool?) ?? false;
      _showProducerCaptureUi =
          _canShowProducerCaptureUiSetting && savedProducerCaptureUi;
      _desktopKeyboardMidiEnabled =
          PlatformCapabilities.current.isDesktop &&
          ((uiSettings?["desktopKeyboardMidiEnabled"] as bool?) ?? false);
      unawaited(
        JuceAudioEngine.setDesktopKeyboardMidiForwardingEnabled(
          _desktopKeyboardMidiEnabled,
        ),
      );
      _desktopSpacebarStopReturnsToStart =
          PlatformCapabilities.current.isDesktop &&
          ((uiSettings?["desktopSpacebarStopReturnsToStart"] as bool?) ??
              false);
      _allowMultipleExpandedRows =
          (uiSettings?["allowMultipleExpandedRows"] as bool?) ?? true;
      _expandRowsOnTrackSelect =
          (uiSettings?["expandRowsOnTrackSelect"] as bool?) ?? true;
      _projectCrossfadeMode = _normalizeProjectCrossfadeMode(
        (uiSettings?["crossfadeMode"] as String?) ?? 'equal_power',
      );
      _metronomeEnabled = (uiSettings?["metronomeEnabled"] as bool?) ?? false;
      _metronomeVolume =
          ((uiSettings?["metronomeVolume"] as num?)?.toDouble() ?? 0.5).clamp(
            0.0,
            1.0,
          );
      _preferredDawSampleRate = _normalizeDawSampleRate(
        uiSettings?["sampleRate"],
      );
      _preferredDawBufferSize = _normalizeDawBufferSize(
        uiSettings?["bufferSize"],
      );
      _midiInputChannelFilter = _normalizeMidiInputChannelFilter(
        uiSettings?["midiInputChannel"] ??
            uiSettings?["midiInputChannelFilter"],
      );
      _loopEnabled = (uiSettings?["loopEnabled"] as bool?) ?? false;
      _loopStartMs = (uiSettings?["loopStartMs"] as num?)?.toInt() ?? 0;
      _loopEndMs = (uiSettings?["loopEndMs"] as num?)?.toInt() ?? 0;
      await _syncMetronomeTimingToEngine();
      await JuceAudioEngine.setMetronomeEnabled(_metronomeEnabled);
      await JuceAudioEngine.setMetronomeVolume(_metronomeVolume);
      await _applyAudioEngineSettingsToNative(
        reason: 'projectLoad',
        notifyOnFailure: false,
      );

      // mark opened time
      json["lastOpenedAt"] = DateTime.now().millisecondsSinceEpoch;

      final rowsJson = ((json["rows"] as List?) ?? [])
          .whereType<Map>()
          .map((e) => e.cast<String, dynamic>())
          .toList();
      _trackGroups
        ..clear()
        ..addAll(_trackGroupsFromProjectJson(json));
      _lastNativeTrackGroupSignature = '';
      final tracks = (json["tracks"] as List?) ?? [];
      final migratedLegacyRows = _migrateLegacyInstrumentRows(rowsJson, tracks);
      json["rows"] = rowsJson;
      json["tracks"] = tracks;
      if (migratedLegacyRows) {
        json["version"] = 6;
      }
      final persistedRowIndexById = ProjectManager.persistedRowOrderIndexById(
        rowsJson,
      );
      final rowFxList = (json["rowEffects"] as List?) ?? [];
      _recordPlanLimitProjectLoadNotices(
        savedRows: rowsJson,
        savedTracks: tracks,
        rowEffects: rowFxList,
        masterState: master,
      );
      final loadedTracksForWaveforms = <AudioTrack>[];
      final ensuredRowIndexes = <int>{};
      await _restoreRowsFromProjectJson(rowsJson, tracks);

      Future<void> ensureTrackRowReady(int rowIndex) async {
        if (ensuredRowIndexes.contains(rowIndex)) return;
        await _ensureRowIndexExists(rowIndex);
        await _ensureRowExistsForClipInsertion();
        ensuredRowIndexes.add(rowIndex);
      }

      await JuceAudioEngine.beginProjectClipLoad();
      try {
        // Load all clips (audio + MIDI/instrument)
        for (final t in tracks) {
          final map = (t as Map).cast<String, dynamic>();
          final savedClipId = _normalizePersistedClipId(map['clipId']);
          final fileName = (map["fileName"] as String?)?.trim() ?? '';
          if (fileName.isEmpty) {
            debugPrint('Skipping malformed track entry without fileName: $map');
            continue;
          }
          final label = (map["label"] as String?) ?? '';
          int rowIndex = ProjectManager.resolveSavedTrackRowIndex(
            track: map,
            persistedRowIndexById: persistedRowIndexById,
          );

          final clipKind = ClipKindWire.fromWire(
            (map['clipType'] as String?) ?? 'audio',
          );
          final savedLane = rowIndex >= 0 && rowIndex < rowsJson.length
              ? _timelineRowFromJson(rowsJson[rowIndex])
              : null;
          final savedLaneInstrumentId = savedLane?.isInstrumentLane == true
              ? savedLane!.instrumentId.trim()
              : '';
          final rawInstrumentId = ((map['instrumentId'] as String?) ?? '')
              .trim();
          final instrumentId =
              clipKind == ClipKind.midi &&
                  rawInstrumentId.isEmpty &&
                  savedLaneInstrumentId.isNotEmpty
              ? savedLaneInstrumentId
              : rawInstrumentId;
          final instrumentSpec = instrumentId.isEmpty
              ? null
              : _findInstrumentSpecById(instrumentId);
          final fallbackName = (instrumentSpec?['name'] as String?) ?? '';
          final rawInstrumentName = ((map['instrumentName'] as String?) ?? '')
              .trim();
          final savedLaneInstrumentName = savedLane?.isInstrumentLane == true
              ? savedLane!.instrumentName.trim()
              : '';
          final savedLaneHostedInstrumentStateBase64 =
              savedLane?.isInstrumentLane == true
              ? savedLane!.hostedInstrumentStateBase64.trim()
              : '';
          final instrumentName = rawInstrumentName.isNotEmpty
              ? rawInstrumentName
              : savedLaneInstrumentName.isNotEmpty
              ? savedLaneInstrumentName
              : fallbackName;
          final hostedInstrumentStateBase64 =
              ((map['hostedInstrumentStateB64'] as String?) ??
                      (map['hostedInstrumentStateBase64'] as String?) ??
                      savedLaneHostedInstrumentStateBase64)
                  .trim();
          final rawParams =
              (map['instrumentParams'] as Map?)?.cast<String, dynamic>() ??
              const <String, dynamic>{};
          final instrumentParams = <String, double>{};
          for (final e in rawParams.entries) {
            if (e.value is num) {
              instrumentParams[e.key] = (e.value as num).toDouble();
            }
          }
          if (clipKind == ClipKind.midi &&
              instrumentParams.isEmpty &&
              savedLane?.isInstrumentLane == true &&
              savedLane!.instrumentParams.isNotEmpty) {
            instrumentParams.addAll(savedLane.instrumentParams);
          }
          final desktopExternalPluginHostingActive =
              PlatformCapabilities.current.isDesktop &&
              _platformCapabilities.externalPluginHosting;
          final deferHostedInstrumentStateRestore = false;
          final midiNotes = ((map['midiNotes'] as List?) ?? [])
              .whereType<Map>()
              .map((e) => MidiNote.fromJson(e.cast<String, dynamic>()))
              .toList();
          final missingDesktopPluginInstrument =
              desktopExternalPluginHostingActive &&
              clipKind == ClipKind.midi &&
              _desktopPluginCatalogLoadAttempted &&
              _instrumentIdUsesExternalPlugin(instrumentId) &&
              !_isKnownDesktopPluginId(instrumentId);
          if (missingDesktopPluginInstrument) {
            _projectLoadIssues.add(
              _ProjectLoadIssue(
                type: _ProjectLoadIssueType.missingPlugin,
                title: 'Missing Instrument Plugin',
                detail:
                    'The project references "$instrumentName", but that desktop plugin is not currently available on this Mac.',
              ),
            );
          }

          final trimStartMs = ((map["trimStartMs"] as num?)?.round() ?? 0)
              .clamp(0, 1 << 30);
          final rawTrimEndMs = (map["trimEndMs"] as num?)?.round();
          final trimStartRequested = Duration(
            milliseconds: trimStartMs.toInt(),
          );
          final trimEndRequested =
              (rawTrimEndMs != null && rawTrimEndMs > trimStartMs)
              ? Duration(milliseconds: rawTrimEndMs)
              : null;
          final offsetSec = ((map["offset"] as num?) ?? 0).toDouble();
          final crossfade = ((map["crossfade"] as num?) ?? 0).toDouble();
          final loadedGain = _normalizeLoadedGainUi(
            (map["gain"] as num?)?.toDouble(),
            projectVersion: projectVersion,
          );
          final normalizeVolume = (map["normalizeVolume"] as bool?) ?? false;
          final preNormalizeGain = _normalizeLoadedGainUi(
            (map["preNormalizeGain"] as num?)?.toDouble(),
            projectVersion: projectVersion,
          );
          final rawNormalizeGain = (map["normalizeGain"] as num?)?.toDouble();
          final hasSeparateNormalizeGain =
              rawNormalizeGain != null && rawNormalizeGain.isFinite;
          final normalizeGain = hasSeparateNormalizeGain
              ? rawNormalizeGain
                    .clamp(_kClipNormalizeGainMin, _kClipNormalizeGainMax)
                    .toDouble()
              : (normalizeVolume
                    ? (_gainUiToLinearValue(loadedGain) /
                              math.max(
                                _gainUiToLinearValue(preNormalizeGain),
                                0.000001,
                              ))
                          .clamp(_kClipNormalizeGainMin, _kClipNormalizeGainMax)
                          .toDouble()
                    : 1.0);
          final gain = (!hasSeparateNormalizeGain && normalizeVolume)
              ? preNormalizeGain
              : loadedGain;
          final pitchSemitones = ((map["pitchSemitones"] as num?) ?? 0.0)
              .toDouble();
          final isReversed = (map["isReversed"] as bool?) ?? false;
          final parsedSourceTempoBpm = ((map["sourceTempoBpm"] as num?) ?? 0.0)
              .toDouble();
          double sourceTempoBpm = parsedSourceTempoBpm;
          bool stretchToProjectTempo =
              (map["stretchToProjectTempo"] as bool?) ?? false;
          bool tempoStretchPreservePitch =
              (map["tempoStretchPreservePitch"] as bool?) ??
              _tempoStretchPreservePitchDefault;
          final tempoWarpMode = normalizeTempoWarpMode(
            map["tempoWarpMode"] as String?,
          );
          final recordingLatencyMs =
              ((map["recordingLatencyMs"] as num?) ?? 0.0).toDouble();
          final alignmentOffsetMs = ((map["alignmentOffsetMs"] as num?) ?? 0.0)
              .toDouble();
          final audioEnhancementPreset =
              (map["audioEnhancementPreset"] as String?)?.trim() ?? '';
          if (clipKind == ClipKind.midi) {
            if (sourceTempoBpm <= 0.0) {
              sourceTempoBpm = _tempo;
            }
            stretchToProjectTempo = true;
            tempoStretchPreservePitch = true;
          }

          final automationList = (map["automation"] as List?) ?? [];
          final automation = automationList
              .map(
                (e) => AutomationPointJson.fromJson(
                  (e as Map).cast<String, dynamic>(),
                ),
              )
              .toList();

          final audioFile = ProjectCompatibilityService.resolveAudioFile(
            _projectDir,
            fileName,
          );
          if (!audioFile.existsSync()) {
            if (clipKind == ClipKind.midi) {
              debugPrint(
                '[ProjectLoad] restore MIDI clip $savedClipId instrument=$instrumentId row=$rowIndex no-audio-file',
              );
              await ensureTrackRowReady(rowIndex);
              final beforeCount = _audioTracks.length;
              await _addMidiTrack(
                instrumentId: instrumentId,
                instrumentName: instrumentName,
                instrumentParams: instrumentParams.isNotEmpty
                    ? instrumentParams
                    : instrumentSpec == null
                    ? const <String, double>{}
                    : _instrumentParamsFromSpec(instrumentSpec),
                midiNotes: midiNotes,
                row: rowIndex,
                timeMs: offsetSec * 1000.0,
                trimStartRequested: trimStartRequested,
                trimEndRequested: trimEndRequested,
                label: label.isEmpty ? instrumentName : label,
                gain: gain,
                pitchSemitones: pitchSemitones,
                sourceTempoBpm: sourceTempoBpm,
                stretchToProjectTempo: stretchToProjectTempo,
                tempoStretchPreservePitch: tempoStretchPreservePitch,
                crossfade: crossfade,
                automation: automation.isNotEmpty ? automation : null,
                hostedInstrumentStateBase64: hostedInstrumentStateBase64,
                rowAlreadyEnsured: true,
                notifyUi: false,
                updateProjectDuration: false,
                startWaveform: false,
                assumeFreshEngineDefaults: true,
                deferHostedInstrumentStateRestore:
                    deferHostedInstrumentStateRestore,
                deferHostedInstrumentInstantiation:
                    deferHostedInstrumentStateRestore,
                clipId: savedClipId,
              );
              if (_audioTracks.length > beforeCount) {
                final tr = _audioTracks.last;
                tr.clipId = savedClipId;
                tr.crossfade = crossfade;
                tr.gain = gain;
                tr.normalizeVolume = normalizeVolume;
                tr.normalizeGain = normalizeGain;
                tr.preNormalizeGain = preNormalizeGain;
                tr.pitchSemitones = pitchSemitones;
                tr.isReversed = isReversed;
                tr.sourceTempoBpm = sourceTempoBpm;
                tr.stretchToProjectTempo = stretchToProjectTempo;
                tr.tempoStretchPreservePitch = tempoStretchPreservePitch;
                tr.tempoWarpMode = tempoWarpMode;
                tr.recordingLatencyMs = recordingLatencyMs;
                tr.alignmentOffsetMs = alignmentOffsetMs;
                tr.audioEnhancementPreset = audioEnhancementPreset;
                tr.hostedInstrumentStateBase64 = hostedInstrumentStateBase64;
                tr.volumeAutomation = automation.isNotEmpty
                    ? automation
                    : [
                        AutomationPoint(x: 0.0, volume: 1.0),
                        AutomationPoint(x: 1.0, volume: 1.0),
                      ];
                loadedTracksForWaveforms.add(tr);
              }
              continue;
            }
            debugPrint("Missing audio file: ${audioFile.path}");
            _projectLoadIssues.add(
              _ProjectLoadIssue(
                type: _ProjectLoadIssueType.missingAudio,
                title: 'Missing Audio File',
                detail:
                    'Mixroom could not find "$fileName" in this project folder, so that clip was left out of the current session.',
              ),
            );
            continue;
          }

          await ensureTrackRowReady(rowIndex);
          final beforeCount = _audioTracks.length;
          if (clipKind == ClipKind.midi) {
            debugPrint(
              '[ProjectLoad] restore MIDI clip $savedClipId instrument=$instrumentId row=$rowIndex',
            );
            await _addMidiTrackFromProjectFile(
              projectAudioFile: audioFile,
              label: label.isEmpty ? instrumentName : label,
              row: rowIndex,
              timeMs: offsetSec * 1000.0,
              instrumentId: instrumentId,
              instrumentName: instrumentName,
              instrumentParams: instrumentParams.isNotEmpty
                  ? instrumentParams
                  : instrumentSpec == null
                  ? const <String, double>{}
                  : _instrumentParamsFromSpec(instrumentSpec),
              midiNotes: midiNotes,
              trimStartRequested: trimStartRequested,
              trimEndRequested: trimEndRequested,
              gain: gain,
              pitchSemitones: pitchSemitones,
              sourceTempoBpm: sourceTempoBpm,
              stretchToProjectTempo: stretchToProjectTempo,
              tempoStretchPreservePitch: tempoStretchPreservePitch,
              tempoWarpMode: tempoWarpMode,
              crossfade: crossfade,
              automation: automation.isNotEmpty ? automation : null,
              hostedInstrumentStateBase64: hostedInstrumentStateBase64,
              rowAlreadyEnsured: true,
              notifyUi: false,
              updateProjectDuration: false,
              startWaveform: false,
              assumeFreshEngineDefaults: true,
              deferHostedInstrumentStateRestore:
                  deferHostedInstrumentStateRestore,
              deferHostedInstrumentInstantiation:
                  deferHostedInstrumentStateRestore,
              clipId: savedClipId,
            );
            debugPrint(
              '[ProjectLoad] restore MIDI clip $savedClipId add complete',
            );
          } else {
            debugPrint(
              '[ProjectLoad] restore audio clip $savedClipId row=$rowIndex file=$fileName',
            );
            await _addAudioTrackFromProjectFile(
              projectAudioFile: audioFile,
              label: label,
              row: rowIndex,
              timeMs: offsetSec * 1000.0,
              trimStartRequested: trimStartRequested,
              trimEndRequested: trimEndRequested,
              gain: gain,
              normalizeVolume: normalizeVolume,
              normalizeGain: normalizeGain,
              preNormalizeGain: preNormalizeGain,
              pitchSemitones: pitchSemitones,
              isReversed: isReversed,
              sourceTempoBpm: sourceTempoBpm,
              stretchToProjectTempo: stretchToProjectTempo,
              tempoStretchPreservePitch: tempoStretchPreservePitch,
              crossfade: crossfade,
              automation: automation.isNotEmpty ? automation : null,
              rowAlreadyEnsured: true,
              notifyUi: false,
              updateProjectDuration: false,
              startWaveform: false,
              assumeFreshEngineDefaults: true,
              clipId: savedClipId,
            );
            debugPrint(
              '[ProjectLoad] restore audio clip $savedClipId add complete',
            );
          }
          if (_audioTracks.length <= beforeCount) {
            debugPrint('[ProjectLoad] skipped clip $savedClipId');
            continue;
          }

          // After _addAudioTrackFromFile, the newest track is last
          // I think this code is deprecated
          final tr = _audioTracks.last;
          tr.clipId = savedClipId;
          tr.crossfade = crossfade;
          tr.gain = gain;
          tr.normalizeVolume = normalizeVolume;
          tr.normalizeGain = normalizeGain;
          tr.preNormalizeGain = preNormalizeGain;
          tr.pitchSemitones = pitchSemitones;
          tr.isReversed = isReversed;
          tr.sourceTempoBpm = sourceTempoBpm;
          tr.stretchToProjectTempo = stretchToProjectTempo;
          tr.tempoStretchPreservePitch = tempoStretchPreservePitch;
          tr.tempoWarpMode = tempoWarpMode;
          tr.recordingLatencyMs = recordingLatencyMs;
          tr.alignmentOffsetMs = alignmentOffsetMs;
          tr.audioEnhancementPreset = audioEnhancementPreset;
          tr.hostedInstrumentStateBase64 = hostedInstrumentStateBase64;
          if (clipKind == ClipKind.midi) {
            tr.clipKind = ClipKind.midi;
            tr.instrumentId = instrumentId;
            tr.instrumentName = instrumentName;
            tr.instrumentParams = Map<String, double>.from(
              instrumentParams.isNotEmpty
                  ? instrumentParams
                  : instrumentSpec == null
                  ? const <String, double>{}
                  : _instrumentParamsFromSpec(instrumentSpec),
            );
            tr.midiNotes = midiNotes.map((note) => note.copy()).toList();
          }
          tr.volumeAutomation = automation.isNotEmpty
              ? automation
              : [
                  AutomationPoint(x: 0.0, volume: 1.0),
                  AutomationPoint(x: 1.0, volume: 1.0),
                ];
          loadedTracksForWaveforms.add(tr);
          debugPrint(
            '[ProjectLoad] restored clip $savedClipId engine=${tr.engineClipId}',
          );
        }
      } finally {
        debugPrint('[ProjectLoad] end native clip load batch');
        await JuceAudioEngine.endProjectClipLoad();
        debugPrint('[ProjectLoad] ended native clip load batch');
      }

      debugPrint('[ProjectLoad] sync clip timeline and mix batch');
      await _syncDeferredClipTimelineBatchToEngine(
        Iterable<int>.generate(_audioTracks.length),
        includeMix: true,
      );
      debugPrint('[ProjectLoad] synced clip timeline and mix batch');
      debugPrint('[ProjectLoad] sync all clip fades after clip load');
      await _syncAllClipFadesToEngine();
      debugPrint('[ProjectLoad] synced all clip fades after clip load');
      debugPrint('[ProjectLoad] update duration after clip load');
      _updateOverallDurationIfNeeded();
      debugPrint('[ProjectLoad] updated duration after clip load');

      final rowStatesList = (json["rowStates"] as List?) ?? [];

      for (final rs in rowStatesList) {
        final snap = RowStateSnapshot.fromJson(
          (rs as Map).cast<String, dynamic>(),
        );
        // Row IDs are session-scoped and can be reassigned after reopen.
        // Prefer persisted row order index, and only fall back to rowId lookup.
        var r = snap.row;
        if (r < 0 || r >= _rowCount) {
          r = snap.rowId >= 0 ? _rowIndexForId(snap.rowId) : -1;
        }

        // Safety check
        if (r < 0 || r >= _rowCount) continue;

        // Restore pan & gain
        _rowPan[r] = snap.pan;
        _rowGain[r] = _normalizeLoadedGainUi(
          snap.gain,
          projectVersion: projectVersion,
        );

        // Restore automation (deep copy!)
        _rowVolumeAutomation[r] = snap.volumeAutomation
            .map((p) => p.copy())
            .toList();
        _restoreAutomationLanesForRow(
          r,
          snap.automationLanes,
          selectedTargetId: snap.selectedAutomationTargetId,
        );
        _restoreAutomationClipsForRow(r, snap.automationClips);
        if (r < _rowMuted.length) {
          _rowMuted[r] = snap.muted;
        }
        if (r < _rowSoloed.length) {
          _rowSoloed[r] = snap.soloed;
        }
        if (r < _rows.length) {
          _rows[r] = _rows[r].copyWith(
            roleOverride: snap.roleOverride,
            groupId: snap.groupId,
            inputDeviceName: snap.inputDeviceName,
            inputChannelStart: snap.inputChannelStart,
            inputChannelCount: snap.inputChannelCount,
          );
        }

        await JuceAudioEngine.setRowGain(r, _rowGain[r]);
        await JuceAudioEngine.setRowPan(r, snap.pan);
      }
      await _recomputeAudibleState();

      await _ensureLoadedAutomationDisplayRowsExist();

      // Restore FX snapshots after tracks exist
      await JuceAudioEngine.beginProjectClipLoad();
      try {
        _rowEffectSnapshotsByRowId.clear();
        for (final rf in rowFxList) {
          final snap = RowEffectsSnapshotJson.fromJson(
            (rf as Map).cast<String, dynamic>(),
          );
          if (snap.rowId >= 0) {
            _rowEffectSnapshotsByRowId[snap.rowId] = snap;
          }
          // Same reasoning as rowStates above: saved index is the stable restore
          // anchor across sessions; rowId is a best-effort fallback.
          var resolvedRow = snap.row;
          if (resolvedRow < 0 || resolvedRow >= _rowCount) {
            resolvedRow = snap.rowId >= 0 ? _rowIndexForId(snap.rowId) : -1;
          }
          if (resolvedRow < 0 || resolvedRow >= _rowCount) {
            continue;
          }
          final resolvedSnapshot = RowEffectsSnapshot(
            resolvedRow,
            snap.effects,
            rowId: snap.rowId,
          );
          debugPrint(
            '[ProjectLoad] restore row FX row=${resolvedRow + 1} count=${resolvedSnapshot.effects.length}',
          );
          _registerPendingRowEffectRestores(resolvedSnapshot);
          for (int i = 0; i < resolvedSnapshot.effects.length; i++) {
            final fx = resolvedSnapshot.effects[i];
            _updateHostedPluginRestoreStatus(
              _hostedRowEffectRestoreKey(
                rowId: resolvedSnapshot.rowId,
                row: resolvedSnapshot.row,
                effectIndex: i,
                fx: fx,
              ),
              status: _HostedPluginRestoreStatus.loading,
              detail: 'Restoring plugin from saved project state.',
            );
          }
          final restoreResult = await _restoreRowSnapshot(resolvedSnapshot);
          debugPrint(
            '[ProjectLoad] restored row FX row=${resolvedRow + 1} failures=${restoreResult.failures.length}',
          );
          _applyEffectRestoreResultToLedger(
            rowSnapshot: resolvedSnapshot,
            masterSnapshot: null,
            result: restoreResult,
          );
          _recordEffectRestoreIssues(
            scopeLabel: 'Row ${resolvedRow + 1} FX',
            result: restoreResult,
          );
        }
        if (master.isNotEmpty) {
          final masterFx = master["effects"];
          if (masterFx != null) {
            final ms = MasterEffectsSnapshotJson.fromJson(masterFx);
            _masterEffectSnapshot = ms;
            debugPrint(
              '[ProjectLoad] restore master FX count=${ms.effects.length}',
            );
            _registerPendingMasterEffectRestores(ms);
            for (int i = 0; i < ms.effects.length; i++) {
              final fx = ms.effects[i];
              _updateHostedPluginRestoreStatus(
                _hostedMasterEffectRestoreKey(effectIndex: i, fx: fx),
                status: _HostedPluginRestoreStatus.loading,
                detail: 'Restoring plugin from saved project state.',
              );
            }
            final restoreResult = await _restoreMasterSnapshot(ms);
            debugPrint(
              '[ProjectLoad] restored master FX failures=${restoreResult.failures.length}',
            );
            _applyEffectRestoreResultToLedger(
              rowSnapshot: null,
              masterSnapshot: ms,
              result: restoreResult,
            );
            _recordEffectRestoreIssues(
              scopeLabel: 'Master FX',
              result: restoreResult,
            );
          }
        }
        _syncEffectSnapshotCacheToCurrentRows();
        await _restoreDeferredHostedInstrumentLoadsDuringProjectLoad();
      } finally {
        await JuceAudioEngine.endProjectClipLoad();
      }

      await _refreshAutomationTargetsForAllRows(syncNativeWhenDone: false);

      // Prime transport state and recover any missing output route before the
      // first user-driven note audition or playback.
      _setGlobalAudioClock(Duration.zero);
      await JuceAudioEngine.setTransportSeconds(0.001);
      await JuceAudioEngine.setTransportSeconds(0.0);
      await JuceAudioEngine.setMetronomeTransportMs(0.0);
      if (Platform.isIOS || PlatformCapabilities.current.isDesktop) {
        await _ensurePlaybackRouteReady(reason: 'projectLoad');
      }
      await _syncNativeAutomationForAllRows();
      await _stabilizeAutomationTargetsAfterProjectLoad();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        for (final track in loadedTracksForWaveforms) {
          _startWaveformExtraction(track);
        }
        for (int row = 0; row < _rowCount; row++) {
          _refreshRowFx(row);
        }
      });
      unawaited(
        AnalyticsService.instance.trackScreen(
          AnalyticsScreenNames.projectEditor,
          properties: <String, Object?>{'project_id': _projectId},
        ),
      );
      unawaited(
        AnalyticsService.instance.track(
          AnalyticsEvents.projectOpened(
            projectId: _projectId,
            trackCount: ProjectManager.extractTrackCount(json),
          ),
        ),
      );
      await _restorePersistedUndoHistory(json);
      setState(() {});
      projectLoadedSuccessfully = true;
      if (mounted && _projectLoadIssues.isNotEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'Project opened with ${_projectLoadIssues.length} recovery notice${_projectLoadIssues.length == 1 ? '' : 's'}. See Project Settings for details.',
            ),
            duration: const Duration(seconds: 4),
          ),
        );
      }
      if (mounted && _usingCompatibilityAudio) {
        _queueCompatibilityAudioOpenNotice();
      }
    } catch (e) {
      debugPrint("Project load failed: $e");
    } finally {
      _isProjectLoading = false;
      if (projectLoadedSuccessfully && !_usingCompatibilityAudio) {
        _scheduleProjectAutosave(debounce: const Duration(seconds: 3));
      }
      unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
    }
  }

  void _queueCompatibilityAudioOpenNotice() {
    if (_compatibilityOpenNoticeQueued) return;
    _compatibilityOpenNoticeQueued = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_usingCompatibilityAudio) return;
      unawaited(
        showAppMessageDialog(
          context: context,
          title: 'Plugin audio included',
          message:
              'This project contains plugins not available on this device. '
              'Any edits made will create a clone of this project.\n\n'
              'Rows containing unavailable plugins have been stemmed out to audio files.',
          icon: Icons.graphic_eq_rounded,
        ),
      );
    });
  }

  String? _frozenRowDescription(int row) {
    if (!_usingCompatibilityAudio) return null;
    final names = _frozenPluginNamesByRow[row] ?? const <String>[];
    if (names.isEmpty) return null;
    final plugins = names.join(', ');
    return 'This row was stemmed to audio because this device does not have: $plugins.';
  }

  Future<void> _showFrozenRowInfo(int row) async {
    final detail = _frozenRowDescription(row);
    if (detail == null || !mounted) return;
    await showAppMessageDialog(
      context: context,
      title: 'Plugin audio',
      message: detail,
      icon: Icons.graphic_eq_rounded,
    );
  }

  Future<void> _remapCompatibilityForkAudioPaths({
    required Directory oldProjectDir,
    required Directory newProjectDir,
  }) async {
    final oldPath = p.normalize(oldProjectDir.path);
    final promoted =
        await ProjectCompatibilityService.promoteAudioForEditedCopy(
          sourceProjectDir: oldProjectDir,
          editedProjectDir: newProjectDir,
          audioFiles: <File>[
            for (final track in _audioTracks) ...<File>[
              track.file,
              track.originalFile,
            ],
          ],
        );
    for (final track in _audioTracks) {
      final paths = <File>[track.file, track.originalFile];
      for (var index = 0; index < paths.length; index++) {
        final file = paths[index];
        final normalized = p.normalize(file.path);
        final remapped =
            promoted[normalized] ??
            (p.isWithin(oldPath, normalized)
                ? File(
                    p.join(
                      newProjectDir.path,
                      p.relative(normalized, from: oldPath),
                    ),
                  )
                : file);
        if (index == 0) {
          track.file = remapped;
        } else {
          track.originalFile = remapped;
        }
      }
    }
  }

  Future<bool> _promoteCompatibilityAudioIntoCurrentProject() async {
    final promoted =
        await ProjectCompatibilityService.promoteAudioForEditedCopy(
          sourceProjectDir: _projectDir,
          editedProjectDir: _projectDir,
          audioFiles: <File>[
            for (final track in _audioTracks) ...<File>[
              track.file,
              track.originalFile,
            ],
          ],
        );
    if (promoted.isEmpty) return false;
    for (final track in _audioTracks) {
      track.file = promoted[p.normalize(track.file.path)] ?? track.file;
      track.originalFile =
          promoted[p.normalize(track.originalFile.path)] ?? track.originalFile;
    }
    return true;
  }

  Future<void> _forkCompatibilityProjectForEdits() async {
    if (!_usingCompatibilityAudio || _compatibilityForkInFlight) return;
    _compatibilityForkInFlight = true;
    try {
      final oldProjectDir = _projectDir;
      final duplicated = await ProjectManager.duplicateProject(oldProjectDir);
      final forkDir = await ProjectManager.renameProject(
        duplicated,
        _projectName,
      );
      final forkJson = await ProjectManager.readProjectJson(forkDir);
      await _remapCompatibilityForkAudioPaths(
        oldProjectDir: oldProjectDir,
        newProjectDir: forkDir,
      );
      _projectDir = forkDir;
      _projectName = (forkJson['name'] ?? p.basename(forkDir.path))
          .toString()
          .trim();
      _projectId = ProjectManager.ensureProjectIdInJson(forkJson);
      _projectCreatedAtMs =
          (forkJson['createdAt'] as num?)?.toInt() ??
          DateTime.now().millisecondsSinceEpoch;
      _cloudProjectId = '';
      _cloudWorkspaceId = '';
      _cloudOrganizationId = '';
      _cloudDocumentRevision = null;
      _cloudSyncedAt = '';
      _cloudSourceFingerprint = '';
      _cloudAutoSyncConflict = false;
      _usingCompatibilityAudio = false;
      _compatibilityProjectionMetadata = const <String, dynamic>{};
      _frozenPluginNamesByRow = const <int, List<String>>{};
      _undoManager.clear();
      ProjectManager.notifyProjectLibraryChanged();
      if (mounted) {
        setState(() {});
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'Editing ${_projectName.isEmpty ? 'a new project' : _projectName}',
            ),
          ),
        );
      }
    } finally {
      _compatibilityForkInFlight = false;
    }
  }

  /// Opening a project must never discard work because the account has changed
  /// plans. Free users can open, play, and save projects that exceed Free
  /// creation limits; the limits apply only to newly added rows and effects.
  void _recordPlanLimitProjectLoadNotices({
    required List<Map<String, dynamic>> savedRows,
    required List savedTracks,
    required List rowEffects,
    required Map<String, dynamic> masterState,
  }) {
    if (!_isFreePlan) return;

    var savedRowCount = savedRows.length;
    for (final track in savedTracks) {
      if (track is! Map) continue;
      final rowIndex = (track['rowIndex'] as num?)?.toInt() ?? -1;
      savedRowCount = math.max(savedRowCount, rowIndex + 1);
    }
    if (savedRowCount > SubscriptionLimits.freeRowsPerProject) {
      _projectLoadIssues.add(
        _ProjectLoadIssue(
          type: _ProjectLoadIssueType.planLimit,
          title: L10n.translate(context, 'Project exceeds Free track limit'),
          detail: L10n.translateWithParams(
            context,
            'All {count} tracks were restored and will be preserved when you save. Free can add up to {limit} tracks per project; upgrade to add more.',
            <String, String>{
              'count': savedRowCount.toString(),
              'limit': SubscriptionLimits.freeRowsPerProject.toString(),
            },
          ),
        ),
      );
    }

    final lockedEffects = <String>{};
    void collectEffects(Object? raw) {
      final effects = raw is List
          ? raw
          : raw is Map
          ? raw['effects']
          : null;
      if (effects is! List) return;
      for (final item in effects) {
        if (item is! Map) continue;
        final name = (item['pathOrName'] ?? item['name'] ?? item['effectId'])
            .toString()
            .trim();
        if (kMixroomBuiltInEffects.contains(name) &&
            !_canUseEffectForCurrentPlan(name)) {
          lockedEffects.add(name);
        }
      }
    }

    for (final row in rowEffects) {
      if (row is Map) collectEffects(row['effects']);
    }
    collectEffects(masterState['effects']);
    if (lockedEffects.isEmpty) return;
    final names = (lockedEffects.toList()..sort())
        .map((name) => L10n.translate(context, name))
        .join(', ');
    _projectLoadIssues.add(
      _ProjectLoadIssue(
        type: _ProjectLoadIssueType.planLimit,
        title: L10n.translate(context, 'Project includes plan-locked effects'),
        detail: L10n.translateWithParams(
          context,
          'Restored effects: {effects}. They will be preserved when you save. Free cannot add these effects to a new chain.',
          <String, String>{'effects': names},
        ),
      ),
    );
  }

  AudioTrack? _primarySelectedClipOrNull() {
    final index = _timelinePrimarySelectedClipIndex;
    if (index >= 0 && index < _audioTracks.length) {
      return _audioTracks[index];
    }
    return null;
  }

  AudioTrack? _armedMidiClipOrNull() {
    return resolveArmedMidiClip(
      tracks: _audioTracks,
      activeMidiClipEngineId: _activeMidiClipEngineId,
      primarySelectedClipIndex: _timelinePrimarySelectedClipIndex,
    );
  }

  int _activeMidiClipEditorIndex() {
    final activeIndex = _activeMidiClipIndex;
    final activeEngineId = _activeMidiClipEngineId;
    if (activeIndex != null &&
        activeIndex >= 0 &&
        activeIndex < _audioTracks.length &&
        _audioTracks[activeIndex].isMidi) {
      final clip = _audioTracks[activeIndex];
      if (activeEngineId != null &&
          activeEngineId >= 0 &&
          clip.engineClipId != activeEngineId) {
        return -1;
      }
      _activeMidiClipEngineId = _audioTracks[activeIndex].engineClipId;
      return activeIndex;
    }

    if (activeEngineId != null && activeEngineId >= 0) {
      final index = _clipIndexForEngineId(activeEngineId);
      if (index >= 0 &&
          index < _audioTracks.length &&
          _audioTracks[index].isMidi) {
        _activeMidiClipIndex = index;
        return index;
      }
    }

    return -1;
  }

  int _activePitchLabEditorIndex() {
    final activeIndex = _activePitchLabClipIndex;
    final activeEngineId = _activePitchLabClipEngineId;
    if (activeIndex != null &&
        activeIndex >= 0 &&
        activeIndex < _audioTracks.length &&
        _audioTracks[activeIndex].isMidi) {
      final clip = _audioTracks[activeIndex];
      if (activeEngineId != null &&
          activeEngineId >= 0 &&
          clip.engineClipId != activeEngineId) {
        return -1;
      }
      _activePitchLabClipEngineId = clip.engineClipId;
      return activeIndex;
    }

    if (activeEngineId != null && activeEngineId >= 0) {
      final index = _clipIndexForEngineId(activeEngineId);
      if (index >= 0 &&
          index < _audioTracks.length &&
          _audioTracks[index].isMidi) {
        _activePitchLabClipIndex = index;
        return index;
      }
    }

    return -1;
  }

  int _activePitchLabAudioSourceIndex() {
    final activeIndex = _activePitchLabSourceAudioIndex;
    final activeEngineId = _activePitchLabSourceAudioEngineId;
    if (activeIndex != null &&
        activeIndex >= 0 &&
        activeIndex < _audioTracks.length &&
        !_audioTracks[activeIndex].isMidi) {
      final clip = _audioTracks[activeIndex];
      if (activeEngineId != null &&
          activeEngineId >= 0 &&
          clip.engineClipId != activeEngineId) {
        return -1;
      }
      _activePitchLabSourceAudioEngineId = clip.engineClipId;
      return activeIndex;
    }

    if (activeEngineId != null && activeEngineId >= 0) {
      final index = _clipIndexForEngineId(activeEngineId);
      if (index >= 0 &&
          index < _audioTracks.length &&
          !_audioTracks[index].isMidi) {
        _activePitchLabSourceAudioIndex = index;
        return index;
      }
    }

    return -1;
  }

  bool _isMidiClipRecordingForEditor(int clipIndex, AudioTrack clip) {
    if (!_isMidiClipRecording || !clip.isMidi) return false;
    final recordingEngineId = _midiRecordingClipEngineId;
    if (recordingEngineId != null && recordingEngineId >= 0) {
      return clip.engineClipId == recordingEngineId;
    }
    return _midiRecordingClipIndex == clipIndex;
  }

  Future<bool> _setLiveMidiInputTargetClipIfNeeded(
    int clipId, {
    bool clearPendingEvents = true,
    bool force = false,
  }) async {
    if (!_liveMidiEventPlaybackSupported) return false;
    final safeClipId = clipId < 0 ? -1 : clipId;
    if (!force && _lastLiveMidiInputTargetClipId == safeClipId) {
      return true;
    }
    final ok = await JuceAudioEngine.setLiveMidiInputTargetClip(safeClipId);
    if (!ok && safeClipId >= 0) {
      return false;
    }
    _lastLiveMidiInputTargetClipId = safeClipId;
    if (clearPendingEvents) {
      await JuceAudioEngine.consumeLiveMidiInputEvents();
    }
    return true;
  }

  Future<void> _syncLiveMidiInputTargetClip() async {
    if (!_liveMidiEventPlaybackSupported || _isMidiClipRecording) return;
    int targetClipId = -1;
    final activeEngineId = _activeMidiClipEngineId;
    if (activeEngineId != null) {
      final activeIndex = _clipIndexForEngineId(activeEngineId);
      if (activeIndex >= 0 && activeIndex < _audioTracks.length) {
        final activeClip = _audioTracks[activeIndex];
        if (activeClip.isMidi && activeClip.engineClipId >= 0) {
          targetClipId = activeClip.engineClipId;
        }
      }
    }
    if (targetClipId < 0) {
      targetClipId = _armedMidiClipOrNull()?.engineClipId ?? -1;
    }
    await _setLiveMidiInputTargetClipIfNeeded(targetClipId);
  }

  void _handleUndoHistoryChanged() {
    final action = _undoManager.lastAction;
    if (action == null) {
      _scheduleProjectAutosave();
      return;
    }
    unawaited(_refreshAutosaveCachesForUndoAction(action));
  }

  Future<void> _refreshAutosaveCachesForUndoAction(
    EditorUndoAction action,
  ) async {
    try {
      await _refreshEffectCachesForUndoAction(action);
    } catch (e) {
      debugPrint('Autosave cache refresh failed: $e');
    }
    _scheduleProjectAutosave();
  }

  Future<void> _refreshEffectCachesForUndoAction(
    EditorUndoAction action,
  ) async {
    switch (action) {
      case final CompoundUndoAction compoundAction:
        for (final child in compoundAction.actions) {
          await _refreshEffectCachesForUndoAction(child);
        }
      case final BypassEffectAction effectAction:
        await _refreshPersistedEffectSnapshotForRow(effectAction.row);
      case final BypassEffectInstanceAction effectAction:
        await _refreshPersistedEffectSnapshotForRow(effectAction.row);
      case final InsertEffectAction effectAction:
        await _refreshPersistedEffectSnapshotForRow(effectAction.row);
      case final RemoveEffectAction effectAction:
        await _refreshPersistedEffectSnapshotForRow(effectAction.row);
      case final RemoveEffectInstanceAction effectAction:
        await _refreshPersistedEffectSnapshotForRow(effectAction.row);
      case final ReorderEffectAction effectAction:
        await _refreshPersistedEffectSnapshotForRow(effectAction.row);
      case final SetEffectParamAction effectAction:
        await _refreshPersistedEffectSnapshotForRow(effectAction.row);
      case final TrackPresetChangeAction trackPresetAction:
        await _refreshPersistedEffectSnapshotForRow(
          trackPresetAction.after.row,
        );
      case _RowEffectsAutomationSnapshotAction():
        await _refreshAllPersistedEffectSnapshots();
      case BypassMasterEffectAction():
        await _refreshPersistedMasterEffectSnapshot();
      case InsertMasterEffectAction():
        await _refreshPersistedMasterEffectSnapshot();
      case RemoveMasterEffectAction():
        await _refreshPersistedMasterEffectSnapshot();
      case ReorderMasterEffectAction():
        await _refreshPersistedMasterEffectSnapshot();
      case SetMasterEffectParamAction():
        await _refreshPersistedMasterEffectSnapshot();
      case MasterPresetChangeAction():
        await _refreshPersistedMasterEffectSnapshot();
      case _MasterEffectsSnapshotAction():
        await _refreshPersistedMasterEffectSnapshot();
      default:
        break;
    }
  }

  void _markProjectDirty({
    Duration debounce = const Duration(seconds: 1),
    bool immediate = false,
  }) {
    if (!_loadedOnce) return;
    if (_isProjectLoading) return;
    _projectAutosaveCoordinator.markDirty();
    if (immediate) {
      unawaited(_projectAutosaveCoordinator.flush());
      return;
    }
    _projectAutosaveCoordinator.schedule(debounce: debounce);
  }

  void _scheduleProjectAutosave({
    Duration debounce = const Duration(seconds: 1),
  }) {
    if (!_loadedOnce || _isProjectLoading) return;
    if (_isRecording ||
        _recordStartVisualPending ||
        _isMidiClipRecording ||
        _recordTransitionInFlight) {
      _projectAutosaveCoordinator.markDirty();
      return;
    }
    _projectAutosaveCoordinator.schedule(debounce: debounce);
  }

  Future<void> _loadCloudSyncMode() async {
    final mode = await CloudSyncPreferences.loadMode();
    _cloudSyncMode = mode;
  }

  bool get _cloudProjectsFeatureEnabled {
    try {
      return context.read<EntitlementService>().areCloudProjectsEnabled;
    } catch (_) {
      return false;
    }
  }

  bool _cloudAutoSyncTargetIsWritable() {
    final cloudProjectId = _cloudProjectId.trim();
    final cloudWorkspaceId = _cloudWorkspaceId.trim();
    if (cloudProjectId.isEmpty && cloudWorkspaceId.isEmpty) return true;
    try {
      final entitlement = context.read<EntitlementService>();
      if (cloudProjectId.isNotEmpty) {
        for (final project in entitlement.effectiveCloudProjects) {
          if (project.projectId != cloudProjectId) continue;
          return project.canWrite;
        }
      }
      if (cloudWorkspaceId.isNotEmpty) {
        for (final workspace in entitlement.effectiveWorkspaces) {
          if (workspace.workspaceId != cloudWorkspaceId) continue;
          return workspace.canWrite;
        }
      }
    } catch (_) {
      return true;
    }
    return true;
  }

  bool _canAttemptAutoCloudSync() {
    if (!_cloudProjectsFeatureEnabled) return false;
    if (_cloudSyncMode != CloudSyncMode.auto) return false;
    // The compatible projection is a local, plugin-free view of a canonical
    // desktop project. Opening or autosaving that view must never publish it
    // as a competing cloud revision and overwrite the source plugin state.
    if (_usingCompatibilityAudio) return false;
    if (!_loadedOnce || _isProjectLoading) return false;
    // Compatibility renders take a live graph snapshot. Do not start that
    // work in the middle of transport playback. The autosave remains dirty
    // and publishes after playback stops.
    if (_isPlaying) return false;
    if (_isRecording ||
        _recordStartVisualPending ||
        _isMidiClipRecording ||
        _recordTransitionInFlight) {
      return false;
    }
    if (_cloudAutoSyncConflict) return false;
    if (!_cloudAutoSyncTargetIsWritable()) return false;
    return true;
  }

  void _scheduleCloudAutoSync({
    String reason = 'autosave',
    Duration debounce = const Duration(seconds: 60),
    bool immediate = false,
  }) {
    _cloudAutoSyncDirty = true;
    // Saving while transport is running deliberately defers the expensive
    // compatibility snapshot. Keep the dirty bit first so stopping transport
    // can pick that save up instead of silently losing the auto-sync request.
    if (!_canAttemptAutoCloudSync()) return;
    if (_cloudAutoSyncInFlight) return;

    final now = DateTime.now();
    final backoffUntil = _cloudAutoSyncBackoffUntil;
    var delay = immediate ? Duration.zero : debounce;
    if (backoffUntil != null && backoffUntil.isAfter(now)) {
      final backoffDelay = backoffUntil.difference(now);
      if (backoffDelay > delay) delay = backoffDelay;
    }

    _cloudAutoSyncTimer?.cancel();
    _cloudAutoSyncTimer = Timer(delay, () {
      _cloudAutoSyncTimer = null;
      unawaited(_runCloudAutoSync(reason: reason));
    });
  }

  void _requestCloudAutoSyncNow(String reason) {
    _cloudAutoSyncDirty = true;
    if (!_canAttemptAutoCloudSync()) return;
    _cloudAutoSyncTimer?.cancel();
    _cloudAutoSyncTimer = null;
    unawaited(_runCloudAutoSync(reason: reason));
  }

  bool _isCloudAutoSyncNonRetryable(Object error) {
    final raw = error.toString().toLowerCase();
    return raw.contains('revision conflict') ||
        raw.contains('current plan') ||
        raw.contains('limit reached') ||
        raw.contains('storage limit') ||
        raw.contains('(403)');
  }

  /// Optimistic cloud writes must use the exact revision that was opened.
  /// A revision-only difference is rebased when the canonical source inside
  /// the current cloud bundle is identical to this local source.
  Future<bool> _hasCurrentCloudRevisionForAutoSync(AuthService auth) async {
    final cloudProjectId = _cloudProjectId.trim();
    if (cloudProjectId.isEmpty) return true;

    final service = CloudProjectService();
    try {
      final snapshot = await service.listProjects(auth: auth);
      CloudProjectAccessItem? remote;
      for (final project in snapshot.cloudProjects) {
        if (project.projectId == cloudProjectId) {
          remote = project;
          break;
        }
      }
      // A locally remembered cloud ID that is absent from a successful cloud
      // listing is stale. Clear it before upload so the service can create or
      // reactivate the deterministic personal project for this local project
      // ID without sending an obsolete expected_revision token.
      if (remote == null) {
        _cloudProjectId = '';
        _cloudWorkspaceId = '';
        _cloudOrganizationId = '';
        _cloudDocumentRevision = null;
        _cloudSourceFingerprint = '';
        _cloudAutoSyncConflict = false;
        final localProject = await ProjectManager.readProjectJson(_projectDir);
        ProjectManager.stripCloudSyncMetadata(localProject);
        await ProjectManager.writeProjectJson(_projectDir, localProject);
        debugPrint(
          'Cloud auto sync detached a stale local cloud link and will '
          'publish a fresh personal project.',
        );
        return true;
      }

      if (_cloudDocumentRevision != remote.documentRevision) {
        File? downloadedBundle;
        Map<String, dynamic>? localProject;
        try {
          final downloaded = await service.downloadBundle(
            auth: auth,
            project: remote,
          );
          downloadedBundle = downloaded.file;
          final remoteProject =
              await ProjectBundle.readCanonicalProjectJsonFromBundle(
                downloaded.file,
              );
          localProject = await ProjectManager.readProjectJson(_projectDir);
          if (remoteProject != null &&
              ProjectCompatibilityService.sourceFingerprint(remoteProject) ==
                  ProjectCompatibilityService.sourceFingerprint(localProject)) {
            _cloudDocumentRevision = remote.documentRevision;
            _cloudAutoSyncConflict = false;
            debugPrint(
              'Cloud auto sync rebased from revision-only change to '
              'cloud revision ${remote.documentRevision}.',
            );
            return true;
          }
        } catch (error) {
          debugPrint('Cloud revision content check skipped: $error');
        } finally {
          if (downloadedBundle != null) {
            try {
              await downloadedBundle.delete();
            } catch (_) {}
          }
        }
        // A personal project that depends on external plugins has one
        // authoritative editable source: a capable desktop. Mobile only ever
        // opens its derived audio copy, so it must not permanently strand the
        // desktop source behind a revision produced by that fallback path.
        final localSource =
            localProject ?? await ProjectManager.readProjectJson(_projectDir);
        final isPersonalProject = remote.workspaceId.trim().isEmpty;
        final localNeedsDesktopPlugins =
            _platformCapabilities.externalPluginHosting &&
            ProjectCompatibilityService.inspect(localSource).needsPluginAudio;
        if (isPersonalProject && localNeedsDesktopPlugins) {
          _cloudDocumentRevision = remote.documentRevision;
          _cloudAutoSyncConflict = false;
          debugPrint(
            'Cloud auto sync restored the authoritative desktop plugin '
            'source at cloud revision ${remote.documentRevision}.',
          );
          return true;
        }
        _cloudAutoSyncConflict = true;
        _cloudAutoSyncDirty = true;
        debugPrint(
          'Cloud auto sync paused: local revision '
          '${_cloudDocumentRevision ?? 'unknown'} is behind cloud revision '
          '${remote.documentRevision}.',
        );
        return false;
      }
      return true;
    } catch (error) {
      // Preserve the existing upload error handling for network/list errors.
      // This preflight only prevents known stale optimistic writes.
      debugPrint('Cloud revision preflight skipped: $error');
      return true;
    } finally {
      service.close();
    }
  }

  Duration _nextCloudAutoSyncBackoff() {
    final minutes = math.min(15, math.max(2, 1 << _cloudAutoSyncFailureCount));
    return Duration(minutes: minutes);
  }

  Future<void> _runCloudAutoSync({required String reason}) async {
    if (!_cloudAutoSyncDirty || !_canAttemptAutoCloudSync()) return;
    if (_cloudAutoSyncInFlight) return;

    final auth = context.read<AuthService>();
    final entitlement = context.read<EntitlementService>();
    if (!auth.isSignedIn ||
        !entitlement.areCloudProjectsEnabled ||
        !entitlement.canUseCapability(SubscriptionCapability.cloudProjects)) {
      return;
    }

    _cloudAutoSyncInFlight = true;
    _cloudAutoSyncDirty = false;
    Duration? retryDelay;
    try {
      await _projectAutosaveCoordinator.flush();
      if (!_canAttemptAutoCloudSync()) {
        _cloudAutoSyncDirty = true;
        return;
      }
      final sourceBeforePublish = await ProjectManager.readProjectJson(
        _projectDir,
      );
      final sourceFingerprintBeforePreparation =
          ProjectCompatibilityService.sourceFingerprint(sourceBeforePublish);
      if (_cloudSourceFingerprint == sourceFingerprintBeforePreparation) {
        return;
      }
      if (!await _hasCurrentCloudRevisionForAutoSync(auth)) return;
      if (!_canAttemptAutoCloudSync()) {
        _cloudAutoSyncDirty = true;
        return;
      }

      // An autosave can complete while a previous compatibility render is
      // running. Only package a revision after the source we are about to
      // upload and its frozen audio have been verified as the same revision.
      final sourceForPublish = await ProjectManager.readProjectJson(
        _projectDir,
      );
      final sourceFingerprint = ProjectCompatibilityService.sourceFingerprint(
        sourceForPublish,
      );
      final projectId = _projectId.trim().isNotEmpty
          ? _projectId.trim()
          : await ProjectManager.ensureProjectId(_projectDir);
      _projectId = projectId;

      final bundlePath = await ProjectBundle.exportMixroomBundle(
        projectDir: _projectDir,
        audioMode: BundleAudioMode.flacLossless,
        requireCurrentCompatibility: false,
      );
      final bundleFile = File(bundlePath);
      if (!await bundleFile.exists() || await bundleFile.length() <= 0) {
        return;
      }

      final service = CloudProjectService();
      try {
        var uploadWorkspaceId = _cloudWorkspaceId.trim();
        var uploadOrganizationId = _cloudOrganizationId.trim();
        final cloudProjectId = _cloudProjectId.trim().isEmpty
            ? null
            : _cloudProjectId.trim();
        if (cloudProjectId != null &&
            (uploadWorkspaceId.isEmpty || uploadOrganizationId.isEmpty)) {
          for (final project in entitlement.effectiveCloudProjects) {
            if (project.projectId != cloudProjectId) continue;
            uploadWorkspaceId = project.workspaceId.trim();
            uploadOrganizationId = project.organizationId.trim();
            break;
          }
        }
        if (cloudProjectId == null && uploadWorkspaceId.isEmpty) {
          final defaultWorkspaceId =
              await CloudSyncPreferences.loadDefaultWorkspaceId();
          if (defaultWorkspaceId.isNotEmpty) {
            for (final workspace in entitlement.effectiveWorkspaces) {
              if (workspace.workspaceId != defaultWorkspaceId) continue;
              if (workspace.status.trim().toLowerCase() != 'active') continue;
              uploadWorkspaceId = workspace.workspaceId;
              uploadOrganizationId = workspace.organizationId;
              break;
            }
          }
        }
        final result = await service.uploadBundle(
          auth: auth,
          bundleFile: bundleFile,
          projectId: projectId,
          name: _projectName,
          cloudProjectId: cloudProjectId,
          workspaceId: uploadWorkspaceId.isEmpty ? null : uploadWorkspaceId,
          organizationId: uploadOrganizationId.isEmpty
              ? null
              : uploadOrganizationId,
          expectedRevision: _cloudDocumentRevision,
        );
        final syncedAt = DateTime.now().toUtc().toIso8601String();
        _cloudProjectId = result.project.projectId;
        _cloudWorkspaceId = result.project.workspaceId.trim();
        _cloudOrganizationId = result.project.organizationId.trim();
        _cloudDocumentRevision = result.project.documentRevision;
        _cloudSyncedAt = syncedAt;
        _cloudSourceFingerprint = sourceFingerprint;
        _cloudAutoSyncFailureCount = 0;
        _cloudAutoSyncBackoffUntil = null;
        _cloudAutoSyncConflict = false;

        final json = await ProjectManager.readProjectJson(_projectDir);
        json['cloudProjectId'] = _cloudProjectId;
        if (_cloudWorkspaceId.isNotEmpty) {
          json['cloudWorkspaceId'] = _cloudWorkspaceId;
        } else {
          json.remove('cloudWorkspaceId');
        }
        if (_cloudOrganizationId.isNotEmpty) {
          json['cloudOrganizationId'] = _cloudOrganizationId;
        } else {
          json.remove('cloudOrganizationId');
        }
        json['cloudDocumentRevision'] = _cloudDocumentRevision;
        json['cloudSyncedAt'] = _cloudSyncedAt;
        json['cloudSourceFingerprint'] = _cloudSourceFingerprint;
        await ProjectManager.writeProjectJson(_projectDir, json);
        ProjectManager.notifyProjectLibraryChanged();
      } finally {
        service.close();
      }
    } catch (error) {
      _cloudAutoSyncDirty = true;
      final nonRetryable = _isCloudAutoSyncNonRetryable(error);
      if (error.toString().toLowerCase().contains('revision conflict')) {
        _cloudAutoSyncConflict = true;
      }
      if (!nonRetryable) {
        _cloudAutoSyncFailureCount = math.min(
          _cloudAutoSyncFailureCount + 1,
          4,
        );
        retryDelay = _nextCloudAutoSyncBackoff();
        _cloudAutoSyncBackoffUntil = DateTime.now().add(retryDelay);
      }
      debugPrint('Cloud auto sync skipped after $reason: $error');
    } finally {
      _cloudAutoSyncInFlight = false;
      if (retryDelay != null && _canAttemptAutoCloudSync()) {
        _cloudAutoSyncTimer?.cancel();
        _cloudAutoSyncTimer = Timer(retryDelay, () {
          _cloudAutoSyncTimer = null;
          unawaited(_runCloudAutoSync(reason: 'retry:$reason'));
        });
      } else if (_cloudAutoSyncDirty && _canAttemptAutoCloudSync()) {
        // Do not lose an edit made while the preceding upload was in flight.
        // The follow-up run re-reads the canonical source before publishing.
        _cloudAutoSyncTimer?.cancel();
        _cloudAutoSyncTimer = Timer(Duration.zero, () {
          _cloudAutoSyncTimer = null;
          unawaited(_runCloudAutoSync(reason: 'latest:$reason'));
        });
      }
    }
  }

  Future<void> _ensureCompatibilityAudioForPublish({
    ValueChanged<double>? onProgress,
  }) async {
    if (!_platformCapabilities.externalPluginHosting) return;
    final inFlight = _compatibilityRenderInFlight;
    if (inFlight != null) {
      return inFlight;
    }

    final task = () async {
      onProgress?.call(0.03);
      final source = await ProjectManager.readProjectJson(_projectDir);
      final inspected = ProjectCompatibilityService.inspect(source);
      if (!inspected.needsPluginAudio ||
          await ProjectCompatibilityService.isCurrent(_projectDir)) {
        onProgress?.call(1.0);
        return;
      }
      final prefs = await SharedPreferences.getInstance();
      const noticeKey = 'third_party_plugin_audio_notice_seen_v1';
      if (prefs.getBool(noticeKey) != true) {
        await prefs.setBool(noticeKey, true);
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(
                'Third-party plugins will be included as audio when you share, so collaborators can open this project without the same plugins.',
              ),
            ),
          );
        }
      }

      await _prepareNativeEngineStateForExport((_) {});
      onProgress?.call(0.08);
      final clipSnapshotJson = _buildNativeExportClipSnapshotJson();
      await ProjectCompatibilityService.audioDirectoryFor(
        _projectDir,
      ).create(recursive: true);
      final existingManifest = await ProjectCompatibilityService.readManifest(
        _projectDir,
      );
      final reusableArtifacts = <String, ProjectCompatibilityArtifact>{};
      if (existingManifest != null) {
        for (final dependency in inspected.dependencies) {
          for (final artifact in existingManifest.artifacts) {
            if (artifact.dependencyKey != dependency.key ||
                artifact.fingerprint !=
                    ProjectCompatibilityService.artifactFingerprint(
                      source,
                      dependency,
                    ) ||
                !await File(
                  p.join(_projectDir.path, artifact.fileName),
                ).exists()) {
              continue;
            }
            reusableArtifacts[dependency.key] = artifact;
            break;
          }
        }
      }
      final artifacts = <ProjectCompatibilityArtifact>[
        ...reusableArtifacts.values,
      ];
      final rows = (source['rows'] as List?) ?? const <Object?>[];
      final rowIndexById = <int, int>{
        for (var i = 0; i < rows.length; i++)
          if (rows[i] is Map && (rows[i] as Map)['rowId'] is num)
            ((rows[i] as Map)['rowId'] as num).toInt(): i,
      };
      final dependenciesByRow = <int, List<ProjectCompatibilityDependency>>{};
      for (final dependency in inspected.dependencies) {
        if (!reusableArtifacts.containsKey(dependency.key) &&
            (dependency.scope == ProjectCompatibilityScope.instrument ||
                dependency.scope == ProjectCompatibilityScope.row) &&
            dependency.row >= 0) {
          dependenciesByRow
              .putIfAbsent(
                dependency.row,
                () => <ProjectCompatibilityDependency>[],
              )
              .add(dependency);
        }
      }
      final pendingGroupDependencies = inspected.dependencies
          .where(
            (item) =>
                item.scope == ProjectCompatibilityScope.group &&
                !reusableArtifacts.containsKey(item.key),
          )
          .toList(growable: false);
      final pendingMasterDependencies = inspected.dependencies
          .where(
            (item) =>
                item.scope == ProjectCompatibilityScope.master &&
                !reusableArtifacts.containsKey(item.key),
          )
          .toList(growable: false);
      final renderCount = math.max(
        1,
        dependenciesByRow.length +
            pendingGroupDependencies.length +
            (pendingMasterDependencies.isEmpty ? 0 : 1),
      );
      var completedRenders = 0;

      Future<String> renderWithProgress(
        Future<String> Function() startRender,
      ) async {
        final base = completedRenders / renderCount;
        var pollingDone = false;
        final renderFuture = startRender();

        Future<void> poll() async {
          while (!pollingDone) {
            try {
              final nativeProgress = await JuceAudioEngine.getExportProgress();
              final overall =
                  (base + nativeProgress.clamp(0.0, 1.0) / renderCount)
                      .clamp(0.0, 1.0)
                      .toDouble();
              onProgress?.call(0.1 + overall * 0.82);
            } catch (_) {}
            await Future<void>.delayed(const Duration(milliseconds: 120));
          }
        }

        final poller = poll();
        try {
          return await renderFuture;
        } finally {
          pollingDone = true;
          await poller;
          completedRenders++;
          onProgress?.call(0.1 + (completedRenders / renderCount) * 0.82);
        }
      }

      Future<void> renderBoundary({
        required List<ProjectCompatibilityDependency> dependencies,
        required List<int> boundaryRows,
        required String outputName,
      }) async {
        final clipIds = _audioTracks
            .where(
              (clip) =>
                  boundaryRows.contains(clip.rowIndex) &&
                  clip.engineClipId >= 0,
            )
            .map((clip) => clip.engineClipId)
            .toSet();
        if (clipIds.isEmpty || boundaryRows.isEmpty) return;
        // The offline renderer normally starts at project zero. A frozen
        // row should instead be an ordinary audio clip beginning where its
        // earliest contributing clip begins, otherwise its visible and
        // audible placement drifts to the left in the compatible project.
        final boundaryStartSeconds = _audioTracks
            .where(
              (clip) =>
                  boundaryRows.contains(clip.rowIndex) &&
                  clip.engineClipId >= 0,
            )
            .map((clip) => math.max(0.0, clip.offset))
            .fold<double>(double.infinity, math.min);
        if (!boundaryStartSeconds.isFinite) return;
        final fileName = 'compatibility/audio/$outputName.wav';
        final output = File(p.join(_projectDir.path, fileName));
        // AudioFormatWriter overwrites an existing WAV but does not guarantee
        // truncation when the replacement is shorter. Start from a fresh file
        // so a compatibility artifact cannot retain stale audio or an invalid
        // trailing data chunk from an earlier render.
        if (await output.exists()) {
          await output.delete();
        }
        final rendered = await renderWithProgress(
          () => JuceAudioEngine.exportMix(
            output.path,
            format: 'wav',
            sampleRate: _preferredDawSampleRate,
            wavBitDepth: 32,
            wavDithering: false,
            // The Dart snapshot is the export authority for MIDI timing,
            // resolved source tempo, and the latest hosted-instrument state.
            // Omitting it can leave a newly-created offline plug-in instance
            // with stale MIDI metadata and produce a silent frozen instrument.
            clipSnapshotJson: clipSnapshotJson,
            audibleClipIds: clipIds.toList(growable: false),
            timelineStartSeconds: boundaryStartSeconds,
            bypassMasterProcessing: true,
            // Row and instrument artifacts remain routed through their source
            // group in the compatible project. Leave group gain, pan, and FX
            // out of this render so that retained group processing applies once.
            bypassGroupProcessing: dependencies.every(
              (dependency) =>
                  dependency.scope != ProjectCompatibilityScope.group,
            ),
            preserveRealtimePlayback: true,
          ),
        );
        if (rendered.isEmpty || !await output.exists()) {
          throw StateError('Could not render third-party plugin audio.');
        }
        if (await output.length() <= 44) {
          throw StateError('Third-party plugin audio render was empty.');
        }
        final fallback = <String, dynamic>{
          'fileName': fileName,
          'label': 'Frozen audio',
          'clipType': 'audio',
          'clipId': 'compatibility-$outputName',
          'rowIndex': boundaryRows.first,
          'rowId': _rowIdAt(boundaryRows.first),
          'offset': boundaryStartSeconds,
          // Mixroom's unity fader value is 2.0. The offline render already
          // includes the source clip gain, so the replacement must be unity.
          'gain': kDefaultGainUi,
          'normalizeVolume': false,
          'normalizeGain': 1.0,
          'preNormalizeGain': kDefaultGainUi,
          'trimStartMs': 0,
        };
        for (final dependency in dependencies) {
          artifacts.add(
            ProjectCompatibilityArtifact(
              dependencyKey: dependency.key,
              fileName: fileName,
              fingerprint: ProjectCompatibilityService.artifactFingerprint(
                source,
                dependency,
              ),
              trackJson: fallback,
              replacementRows: boundaryRows,
            ),
          );
        }
      }

      for (final entry in dependenciesByRow.entries) {
        await renderBoundary(
          dependencies: entry.value,
          boundaryRows: <int>[entry.key],
          outputName: 'frozen_row_${entry.key}',
        );
      }
      final groups = (source['trackGroups'] as List?) ?? const <Object?>[];
      for (final dependency in pendingGroupDependencies) {
        final group = groups.whereType<Map>().cast<Map>().firstWhere(
          (item) => (item['id'] ?? '').toString() == dependency.groupId,
          orElse: () => const <String, dynamic>{},
        );
        final groupRows = ((group['rowIds'] as List?) ?? const <Object?>[])
            .whereType<num>()
            .map((rowId) => rowIndexById[rowId.toInt()] ?? -1)
            .where((row) => row >= 0)
            .toList(growable: false);
        final safeId = dependency.groupId.replaceAll(
          RegExp(r'[^A-Za-z0-9_-]'),
          '_',
        );
        await renderBoundary(
          dependencies: <ProjectCompatibilityDependency>[dependency],
          boundaryRows: groupRows,
          outputName: 'frozen_group_$safeId',
        );
      }

      String referenceMix = '';
      final allMasterDependencies = inspected.dependencies
          .where((item) => item.scope == ProjectCompatibilityScope.master)
          .toList(growable: false);
      final masterDependencies = pendingMasterDependencies;
      if (masterDependencies.isEmpty && allMasterDependencies.isNotEmpty) {
        referenceMix =
            reusableArtifacts[allMasterDependencies.first.key]?.fileName ?? '';
      }
      if (masterDependencies.isNotEmpty) {
        referenceMix = 'compatibility/audio/original_mix_reference.wav';
        final reference = File(p.join(_projectDir.path, referenceMix));
        if (await reference.exists()) {
          await reference.delete();
        }
        final rendered = await renderWithProgress(
          () => JuceAudioEngine.exportMix(
            reference.path,
            format: 'wav',
            sampleRate: _preferredDawSampleRate,
            wavBitDepth: 32,
            wavDithering: false,
            clipSnapshotJson: clipSnapshotJson,
            preserveRealtimePlayback: true,
          ),
        );
        if (rendered.isEmpty || !await reference.exists()) {
          throw StateError('Could not render the original mix reference.');
        }
        for (final dependency in masterDependencies) {
          artifacts.add(
            ProjectCompatibilityArtifact(
              dependencyKey: dependency.key,
              fileName: referenceMix,
              fingerprint: ProjectCompatibilityService.artifactFingerprint(
                source,
                dependency,
              ),
            ),
          );
        }
      }
      if (artifacts.length != inspected.dependencies.length) {
        throw StateError('Could not render every third-party plugin path.');
      }
      await ProjectCompatibilityService.writeCompatibleCopy(
        projectDir: _projectDir,
        sourceProject: source,
        artifacts: artifacts,
        referenceMixFileName: referenceMix,
      );
      onProgress?.call(1.0);
    }();
    _compatibilityRenderInFlight = task;
    try {
      await task;
    } finally {
      if (identical(_compatibilityRenderInFlight, task)) {
        _compatibilityRenderInFlight = null;
      }
    }
  }

  Future<void> _refreshCompatibilityAudioStatus({
    Map<String, dynamic>? project,
  }) async {
    if (_usingCompatibilityAudio ||
        !_platformCapabilities.externalPluginHosting) {
      if (!mounted) return;
      _setStateAndRefreshProjectSettings(() {
        _compatibilityAudioRequired = false;
        _compatibilityAudioCurrent = false;
      });
      return;
    }
    final source = project ?? await ProjectManager.readProjectJson(_projectDir);
    final required = ProjectCompatibilityService.inspect(
      source,
    ).needsPluginAudio;
    final current =
        required && await ProjectCompatibilityService.isCurrent(_projectDir);
    if (!mounted ||
        (required == _compatibilityAudioRequired &&
            current == _compatibilityAudioCurrent)) {
      return;
    }
    _setStateAndRefreshProjectSettings(() {
      _compatibilityAudioRequired = required;
      _compatibilityAudioCurrent = current;
    });
  }

  Future<void> _prepareCompatibilityAudioManually() async {
    if (_compatibilityPreparationActive || _usingCompatibilityAudio) return;
    if (_isPlaying ||
        _isRecording ||
        _recordStartVisualPending ||
        _isMidiClipRecording ||
        _recordTransitionInFlight) {
      if (mounted) {
        showAppSnackBar(
          context,
          'Stop playback or recording before preparing a compatible version.',
          tone: AppPopupTone.warning,
        );
      }
      return;
    }

    _setStateAndRefreshProjectSettings(() {
      _compatibilityPreparationActive = true;
      _compatibilityPreparationProgress = 0.01;
      _compatibilityAudioError = '';
    });
    try {
      // Let the settings card paint its progress state before any native
      // snapshot or plug-in work begins.
      await WidgetsBinding.instance.endOfFrame;
      await _projectAutosaveCoordinator.flush();
      // Persist every hosted instrument's current state before reading the
      // canonical source and constructing the offline export snapshot. The
      // ordinary autosave path captures only the active MIDI instrument.
      await _refreshHostedInstrumentStatesForPersistence();
      _projectAutosaveCoordinator.markDirty();
      await _projectAutosaveCoordinator.flush();
      await _ensureCompatibilityAudioForPublish(
        onProgress: (progress) {
          if (!mounted) return;
          final next = progress.clamp(0.0, 1.0).toDouble();
          if (next <= _compatibilityPreparationProgress) return;
          _setStateAndRefreshProjectSettings(() {
            _compatibilityPreparationProgress = next;
          });
        },
      );
      await _refreshCompatibilityAudioStatus();
      if (!_compatibilityAudioCurrent) {
        throw StateError(
          'The project changed while its compatible version was being prepared. Try again when the edit is stable.',
        );
      }
      // A source-only cloud autosave may already have published this exact
      // project revision. Force one follow-up upload to add the newly prepared
      // portable audio without requiring another edit.
      _cloudSourceFingerprint = '';
      _requestCloudAutoSyncNow('compatible-version-ready');
      if (mounted) {
        showAppSnackBar(
          context,
          'Compatible version is ready. Future edits will not re-render it automatically.',
          tone: AppPopupTone.success,
        );
      }
    } catch (error) {
      final message = error.toString().replaceFirst('Bad state: ', '').trim();
      if (mounted) {
        _setStateAndRefreshProjectSettings(() {
          _compatibilityAudioError = message;
        });
        showAppSnackBar(
          context,
          'Could not prepare compatible version: $message',
          tone: AppPopupTone.error,
        );
      }
    } finally {
      if (mounted) {
        _setStateAndRefreshProjectSettings(() {
          _compatibilityPreparationActive = false;
          _compatibilityPreparationProgress = 0.0;
        });
      } else {
        _compatibilityPreparationActive = false;
        _compatibilityPreparationProgress = 0.0;
      }
    }
  }

  Future<void> _refreshPersistedEffectSnapshotForRow(
    int row, {
    bool forceIndividualRow = false,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    final snapshot = await captureRowSnapshot(
      row,
      rowId: _rowIdAt(row),
      forceIndividualRow: forceIndividualRow,
    );
    if (snapshot.rowId >= 0) {
      _rowEffectSnapshotsByRowId[snapshot.rowId] = snapshot;
    }
  }

  Future<void> _refreshPersistedMasterEffectSnapshot() async {
    _masterEffectSnapshot = await captureMasterSnapshot();
  }

  void _syncEffectSnapshotCacheToCurrentRows() {
    final activeRowIds = _rows
        .map((row) => row.rowId)
        .where((rowId) => rowId >= 0)
        .toSet();
    _rowEffectSnapshotsByRowId.removeWhere(
      (rowId, _) => !activeRowIds.contains(rowId),
    );
    for (int row = 0; row < _rowCount; row++) {
      final rowId = _rowIdAt(row);
      if (rowId < 0 || _rowEffectSnapshotsByRowId.containsKey(rowId)) continue;
      _rowEffectSnapshotsByRowId[rowId] = RowEffectsSnapshot(
        row,
        <EffectSnapshot>[],
        rowId: rowId,
      );
    }
  }

  void _recordEffectRestoreIssues({
    required String scopeLabel,
    required _EffectRestoreResult result,
  }) {
    if (!result.hasFailures) return;
    for (final failure in result.failures) {
      _projectLoadIssues.add(
        _ProjectLoadIssue(
          type: failure.partiallyRestored
              ? _ProjectLoadIssueType.partialPluginRestore
              : _ProjectLoadIssueType.missingPlugin,
          title: failure.partiallyRestored
              ? '$scopeLabel Restored Approximately'
              : '$scopeLabel Missing Plugin',
          detail:
              '${failure.displayName} (${failure.effectId})\n${failure.reason}',
        ),
      );
    }
  }

  String _hostedRowEffectRestoreKey({
    required int rowId,
    required int row,
    required int effectIndex,
    required EffectSnapshot fx,
  }) {
    final stableRow = rowId >= 0 ? 'rowId:$rowId' : 'row:$row';
    return 'rowFx|$stableRow|$effectIndex|${fx.effectId.trim()}';
  }

  String _hostedMasterEffectRestoreKey({
    required int effectIndex,
    required EffectSnapshot fx,
  }) {
    return 'masterFx|$effectIndex|${fx.effectId.trim()}';
  }

  String _hostedMidiInstrumentRestoreKey(AudioTrack clip) {
    final stableClip = clip.clipId.trim().isNotEmpty
        ? 'clipId:${clip.clipId.trim()}'
        : 'engine:${clip.engineClipId}';
    return 'midiInstrument|$stableClip|${clip.instrumentId.trim()}';
  }

  void _setHostedPluginRestoreEntry(_HostedPluginRestoreEntry entry) {
    void apply() {
      _hostedPluginRestoreEntries[entry.key] = entry;
    }

    if (mounted) {
      if (_isProjectLoading) {
        apply();
      } else {
        setState(apply);
        _projectSettingsStateSetter?.call(() {});
      }
    } else {
      apply();
    }
  }

  void _updateHostedPluginRestoreStatus(
    String key, {
    required _HostedPluginRestoreStatus status,
    String? detail,
  }) {
    final current = _hostedPluginRestoreEntries[key];
    if (current == null) return;
    _setHostedPluginRestoreEntry(
      current.copyWith(status: status, detail: detail),
    );
  }

  void _registerPendingRowEffectRestores(RowEffectsSnapshot snap) {
    for (int i = 0; i < snap.effects.length; i++) {
      final fx = snap.effects[i];
      _setHostedPluginRestoreEntry(
        _HostedPluginRestoreEntry(
          key: _hostedRowEffectRestoreKey(
            rowId: snap.rowId,
            row: snap.row,
            effectIndex: i,
            fx: fx,
          ),
          scope: _HostedPluginRestoreScope.rowEffect,
          status: _HostedPluginRestoreStatus.pending,
          title: 'Row ${snap.row + 1} FX: ${_effectSnapshotName(fx)}',
          detail: 'Waiting to restore this plugin from the saved project.',
          row: snap.row,
          rowId: snap.rowId,
          effectIndex: i,
          pluginId: fx.effectId,
          snapshotIndex: i,
        ),
      );
    }
  }

  void _registerPendingMasterEffectRestores(MasterEffectsSnapshot snap) {
    for (int i = 0; i < snap.effects.length; i++) {
      final fx = snap.effects[i];
      _setHostedPluginRestoreEntry(
        _HostedPluginRestoreEntry(
          key: _hostedMasterEffectRestoreKey(effectIndex: i, fx: fx),
          scope: _HostedPluginRestoreScope.masterEffect,
          status: _HostedPluginRestoreStatus.pending,
          title: 'Master FX: ${_effectSnapshotName(fx)}',
          detail: 'Waiting to restore this plugin from the saved project.',
          effectIndex: i,
          pluginId: fx.effectId,
          snapshotIndex: i,
        ),
      );
    }
  }

  void _applyEffectRestoreResultToLedger({
    required RowEffectsSnapshot? rowSnapshot,
    required MasterEffectsSnapshot? masterSnapshot,
    required _EffectRestoreResult result,
  }) {
    if (rowSnapshot != null) {
      for (int i = 0; i < rowSnapshot.effects.length; i++) {
        final fx = rowSnapshot.effects[i];
        _updateHostedPluginRestoreStatus(
          _hostedRowEffectRestoreKey(
            rowId: rowSnapshot.rowId,
            row: rowSnapshot.row,
            effectIndex: i,
            fx: fx,
          ),
          status: _HostedPluginRestoreStatus.loaded,
          detail: 'Restored successfully.',
        );
      }
      for (final failure in result.failures) {
        final index = failure.snapshotIndex;
        if (index < 0 || index >= rowSnapshot.effects.length) continue;
        final fx = rowSnapshot.effects[index];
        _updateHostedPluginRestoreStatus(
          _hostedRowEffectRestoreKey(
            rowId: rowSnapshot.rowId,
            row: rowSnapshot.row,
            effectIndex: index,
            fx: fx,
          ),
          status: failure.partiallyRestored
              ? _HostedPluginRestoreStatus.partial
              : _HostedPluginRestoreStatus.failed,
          detail: failure.reason,
        );
      }
    }

    if (masterSnapshot != null) {
      for (int i = 0; i < masterSnapshot.effects.length; i++) {
        final fx = masterSnapshot.effects[i];
        _updateHostedPluginRestoreStatus(
          _hostedMasterEffectRestoreKey(effectIndex: i, fx: fx),
          status: _HostedPluginRestoreStatus.loaded,
          detail: 'Restored successfully.',
        );
      }
      for (final failure in result.failures) {
        final index = failure.snapshotIndex;
        if (index < 0 || index >= masterSnapshot.effects.length) continue;
        final fx = masterSnapshot.effects[index];
        _updateHostedPluginRestoreStatus(
          _hostedMasterEffectRestoreKey(effectIndex: index, fx: fx),
          status: failure.partiallyRestored
              ? _HostedPluginRestoreStatus.partial
              : _HostedPluginRestoreStatus.failed,
          detail: failure.reason,
        );
      }
    }
  }

  Future<void> _retryDesktopPluginRestoreFromSavedSnapshots() async {
    if (!mounted ||
        !PlatformCapabilities.current.isDesktop ||
        !_platformCapabilities.externalPluginHosting) {
      return;
    }

    await _scanDesktopPlugins(forceRescan: true, includeHidden: true);
    if (!mounted) return;

    final preservedIssues = _projectLoadIssues
        .where((issue) {
          return issue.title != 'Master FX Missing Plugin' &&
              issue.title != 'Master FX Restored Approximately' &&
              !issue.title.startsWith('Row ') &&
              issue.type != _ProjectLoadIssueType.partialPluginRestore;
        })
        .toList(growable: false);
    final refreshedIssues = <_ProjectLoadIssue>[];
    setState(() {
      _hostedPluginRestoreEntries.clear();
    });

    final orderedRowSnapshots = _rowEffectSnapshotsByRowId.values.toList()
      ..sort((a, b) => a.row.compareTo(b.row));
    for (final snap in orderedRowSnapshots) {
      var resolvedRow = snap.row;
      if (resolvedRow < 0 || resolvedRow >= _rowCount) {
        resolvedRow = snap.rowId >= 0 ? _rowIndexForId(snap.rowId) : -1;
      }
      if (resolvedRow < 0 || resolvedRow >= _rowCount) {
        continue;
      }
      final resolvedSnapshot = RowEffectsSnapshot(
        resolvedRow,
        snap.effects,
        rowId: snap.rowId,
      );
      for (final fx in resolvedSnapshot.effects) {
        await JuceAudioEngine.clearPluginQuarantine(fx.effectId);
      }
      _registerPendingRowEffectRestores(resolvedSnapshot);
      for (int i = 0; i < resolvedSnapshot.effects.length; i++) {
        final fx = resolvedSnapshot.effects[i];
        _updateHostedPluginRestoreStatus(
          _hostedRowEffectRestoreKey(
            rowId: resolvedSnapshot.rowId,
            row: resolvedSnapshot.row,
            effectIndex: i,
            fx: fx,
          ),
          status: _HostedPluginRestoreStatus.loading,
          detail: 'Retrying restore from saved project state.',
        );
      }
      final restoreResult = await _restoreRowSnapshot(resolvedSnapshot);
      _applyEffectRestoreResultToLedger(
        rowSnapshot: resolvedSnapshot,
        masterSnapshot: null,
        result: restoreResult,
      );
      if (restoreResult.hasFailures) {
        for (final failure in restoreResult.failures) {
          refreshedIssues.add(
            _ProjectLoadIssue(
              type: failure.partiallyRestored
                  ? _ProjectLoadIssueType.partialPluginRestore
                  : _ProjectLoadIssueType.missingPlugin,
              title: failure.partiallyRestored
                  ? 'Row ${resolvedRow + 1} FX Restored Approximately'
                  : 'Row ${resolvedRow + 1} FX Missing Plugin',
              detail:
                  '${failure.displayName} (${failure.effectId})\n${failure.reason}',
            ),
          );
        }
      }
    }

    if (_masterEffectSnapshot.effects.isNotEmpty) {
      for (final fx in _masterEffectSnapshot.effects) {
        await JuceAudioEngine.clearPluginQuarantine(fx.effectId);
      }
      _registerPendingMasterEffectRestores(_masterEffectSnapshot);
      for (int i = 0; i < _masterEffectSnapshot.effects.length; i++) {
        final fx = _masterEffectSnapshot.effects[i];
        _updateHostedPluginRestoreStatus(
          _hostedMasterEffectRestoreKey(effectIndex: i, fx: fx),
          status: _HostedPluginRestoreStatus.loading,
          detail: 'Retrying restore from saved project state.',
        );
      }
      final restoreResult = await _restoreMasterSnapshot(_masterEffectSnapshot);
      _applyEffectRestoreResultToLedger(
        rowSnapshot: null,
        masterSnapshot: _masterEffectSnapshot,
        result: restoreResult,
      );
      if (restoreResult.hasFailures) {
        for (final failure in restoreResult.failures) {
          refreshedIssues.add(
            _ProjectLoadIssue(
              type: failure.partiallyRestored
                  ? _ProjectLoadIssueType.partialPluginRestore
                  : _ProjectLoadIssueType.missingPlugin,
              title: failure.partiallyRestored
                  ? 'Master FX Restored Approximately'
                  : 'Master FX Missing Plugin',
              detail:
                  '${failure.displayName} (${failure.effectId})\n${failure.reason}',
            ),
          );
        }
      }
    }

    for (final clip in List<AudioTrack>.from(_audioTracks)) {
      if (!clip.isMidi || clip.engineClipId < 0) continue;
      if (!_clipUsesExternalPluginInstrument(clip)) continue;

      final liveInstrumentId = _liveMidiEngineInstrumentId(clip.instrumentId);
      await JuceAudioEngine.clearPluginQuarantine(liveInstrumentId);
      final restoreKey = _hostedMidiInstrumentRestoreKey(clip);
      _setHostedPluginRestoreEntry(
        _HostedPluginRestoreEntry(
          key: restoreKey,
          scope: _HostedPluginRestoreScope.midiInstrument,
          status: _HostedPluginRestoreStatus.loading,
          title:
              'Instrument: ${clip.instrumentName.trim().isEmpty ? clip.instrumentId : clip.instrumentName}',
          detail: 'Retrying instrument restore from saved project state.',
          row: clip.rowIndex,
          rowId: clip.rowId,
          pluginId: liveInstrumentId,
        ),
      );
      final restored = await _refreshMidiClipEngineNow(
        clip,
        failureNotice:
            'Could not load ${clip.instrumentName.trim().isEmpty ? 'this instrument' : clip.instrumentName.trim()} for live MIDI playback.',
      );
      _updateHostedPluginRestoreStatus(
        restoreKey,
        status: restored
            ? _HostedPluginRestoreStatus.loaded
            : _HostedPluginRestoreStatus.failed,
        detail: restored
            ? 'Restored successfully.'
            : 'The instrument plugin could not be instantiated on this Mac.',
      );
      if (!restored) {
        refreshedIssues.add(
          _ProjectLoadIssue(
            type: _ProjectLoadIssueType.missingPlugin,
            title: 'Instrument Plugin Missing',
            detail:
                '${clip.instrumentName.trim().isEmpty ? clip.instrumentId : clip.instrumentName} (${clip.instrumentId})\nThe MIDI clip and saved plugin state were kept, but the live instrument could not be restored.',
          ),
        );
      }
    }

    setState(() {
      _projectLoadIssues
        ..clear()
        ..addAll(preservedIssues)
        ..addAll(refreshedIssues);
    });
    await _refreshAllPersistedEffectSnapshots();
    _scheduleProjectAutosave();

    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          refreshedIssues.isEmpty
              ? 'Desktop plugins restored from the saved project snapshots.'
              : 'Plugin restore retried. ${refreshedIssues.length} issue${refreshedIssues.length == 1 ? '' : 's'} remain.',
        ),
      ),
    );
  }

  TimelineRow? _rowForClipFromRows(
    AudioTrack clip,
    List<TimelineRow> rows, {
    Map<int, int>? rowIndexById,
  }) {
    if (clip.rowId >= 0) {
      final byIdIndex = rowIndexById?[clip.rowId];
      if (byIdIndex != null && byIdIndex >= 0 && byIdIndex < rows.length) {
        return rows[byIdIndex];
      }
    }
    final rowIndex = clip.rowIndex;
    if (rowIndex >= 0 && rowIndex < rows.length) {
      return rows[rowIndex];
    }
    return null;
  }

  Future<List<TimelineRow>> _rowsWithMidiInstrumentMetadataForSave() async {
    final rows = _rows.map(_cloneTimelineRow).toList(growable: false);
    final rowIndexById = <int, int>{
      for (int index = 0; index < rows.length; index++)
        rows[index].rowId: index,
    };
    for (int clipIndex = 0; clipIndex < _audioTracks.length; clipIndex++) {
      if (clipIndex > 0 && clipIndex % 32 == 0) {
        await Future<void>.delayed(Duration.zero);
      }
      final clip = _audioTracks[clipIndex];
      if (!clip.isMidi) continue;
      final row = _rowForClipFromRows(clip, rows, rowIndexById: rowIndexById);
      if (row == null || !row.isInstrumentLane) continue;

      final instrumentId = row.instrumentId.trim().isEmpty
          ? clip.instrumentId.trim()
          : row.instrumentId;
      if (instrumentId.trim().isEmpty) continue;

      final rowIndex = rowIndexById[row.rowId] ?? clip.rowIndex;
      if (rowIndex < 0) continue;
      rows[rowIndex] = row.copyWith(
        instrumentId: instrumentId,
        instrumentName: row.instrumentName.trim().isEmpty
            ? clip.instrumentName.trim()
            : row.instrumentName,
        instrumentParams: row.instrumentParams.isEmpty
            ? Map<String, double>.from(clip.instrumentParams)
            : Map<String, double>.from(row.instrumentParams),
        hostedInstrumentStateBase64:
            row.hostedInstrumentStateBase64.trim().isEmpty
            ? clip.hostedInstrumentStateBase64.trim()
            : row.hostedInstrumentStateBase64.trim(),
      );
    }
    return rows;
  }

  Future<Map<String, dynamic>> _buildProjectJsonSnapshot() async {
    _migrateAutomationClipsToLanePoints();
    final now = DateTime.now().millisecondsSinceEpoch;
    final rowsForSave = await _rowsWithMidiInstrumentMetadataForSave();
    final rowsJson = rowsForSave
        .map(_timelineRowToJson)
        .toList(growable: false);
    final rowIndexById = <int, int>{
      for (int index = 0; index < rowsForSave.length; index++)
        rowsForSave[index].rowId: index,
    };

    final tracksJson = <Map<String, dynamic>>[];
    final tracksForSave = List<AudioTrack>.of(_audioTracks);
    for (int trackIndex = 0; trackIndex < tracksForSave.length; trackIndex++) {
      if (trackIndex > 0 && trackIndex % 24 == 0) {
        await Future<void>.delayed(Duration.zero);
      }
      final tr = tracksForSave[trackIndex];
      final src = tr.file;
      if (!tr.isMidi && !src.existsSync()) continue;
      final fileName = ProjectCompatibilityService.persistedAudioFileName(
        projectDir: _projectDir,
        audioFile: src,
      ).trim();
      if (fileName.isEmpty) continue;
      final rowForTrack = _rowForClipFromRows(
        tr,
        rowsForSave,
        rowIndexById: rowIndexById,
      );
      final rowInstrumentId = rowForTrack?.isInstrumentLane == true
          ? rowForTrack!.instrumentId
          : '';
      final rowInstrumentName = rowForTrack?.isInstrumentLane == true
          ? rowForTrack!.instrumentName
          : '';
      final rowInstrumentParams = rowForTrack?.isInstrumentLane == true
          ? rowForTrack!.instrumentParams
          : const <String, double>{};
      final rowHostedInstrumentStateBase64 =
          rowForTrack?.isInstrumentLane == true
          ? rowForTrack!.hostedInstrumentStateBase64.trim()
          : '';
      final savedInstrumentId =
          tr.isMidi &&
              tr.instrumentId.trim().isEmpty &&
              rowInstrumentId.isNotEmpty
          ? rowInstrumentId
          : tr.instrumentId;
      final savedInstrumentName =
          tr.isMidi &&
              tr.instrumentName.trim().isEmpty &&
              rowInstrumentName.trim().isNotEmpty
          ? rowInstrumentName
          : tr.instrumentName;
      final savedInstrumentParams =
          tr.isMidi &&
              tr.instrumentParams.isEmpty &&
              rowInstrumentParams.isNotEmpty
          ? rowInstrumentParams
          : tr.instrumentParams;
      final trackJson = tr.toJson(fileName);
      trackJson["instrumentId"] = savedInstrumentId;
      trackJson["instrumentName"] = savedInstrumentName;
      trackJson["instrumentParams"] = savedInstrumentParams;
      if (tr.isMidi &&
          tr.hostedInstrumentStateBase64.trim().isEmpty &&
          rowHostedInstrumentStateBase64.isNotEmpty) {
        trackJson["hostedInstrumentStateB64"] = rowHostedInstrumentStateBase64;
      }
      if (tr.hostedInstrumentStateBase64.trim().isEmpty) {
        if (rowHostedInstrumentStateBase64.isEmpty) {
          trackJson.remove("hostedInstrumentStateB64");
        }
      }
      tracksJson.add(trackJson);
    }

    final rowStates = <Map<String, dynamic>>[];
    final rowEffects = <Map<String, dynamic>>[];
    for (int row = 0; row < _rowCount; row++) {
      final rowId = _rowIdAt(row);
      rowStates.add(
        RowStateSnapshot(
          row: row,
          rowId: rowId,
          gain: _rowGain[row],
          pan: _rowPan[row],
          muted: row < _rowMuted.length ? _rowMuted[row] : false,
          soloed: row < _rowSoloed.length ? _rowSoloed[row] : false,
          roleOverride: row < _rows.length ? _rows[row].roleOverride : '',
          groupId: row < _rows.length ? _rows[row].groupId : '',
          inputDeviceName: row < _rows.length ? _rows[row].inputDeviceName : '',
          inputChannelStart: row < _rows.length
              ? _rows[row].inputChannelStart
              : 0,
          inputChannelCount: row < _rows.length
              ? _rows[row].inputChannelCount
              : 1,
          volumeAutomation: _rowVolumeAutomation[row]
              .map((p) => p.copy())
              .toList(),
          automationLanes: _automationLanesForRowSave(row),
          automationClips: _automationClipsForRowSave(row),
          selectedAutomationTargetId: _rowSelectedAutomationTarget[row],
        ).toJson(),
      );

      final cached = rowId >= 0 ? _rowEffectSnapshotsByRowId[rowId] : null;
      rowEffects.add(
        RowEffectsSnapshot(
          row,
          cached?.effects ?? const <EffectSnapshot>[],
          rowId: rowId,
        ).toJson(),
      );
    }

    final chatMessages = _chatController.messages;
    final assistantChat = ProjectChatHistory.fromChatMessages(
      chatMessages,
      stateSessionId: chatMessages.isNotEmpty
          ? _ensureAssistantConversationSessionId()
          : _assistantConversationSessionId,
    ).toJsonValue();
    final json = <String, dynamic>{
      "version": 6,
      "name": _projectName,
      "nameConfirmed": !_requiresProjectNaming,
      "createdAt": _projectCreatedAtMs > 0
          ? _projectCreatedAtMs
          : DateTime.now().millisecondsSinceEpoch,
      "lastOpenedAt": now,
      "projectId": _projectId,
      "tempoBpm": _tempo,
      "projectKey": _projectKey,
      "timeSignature": {
        "numerator": _timeSignatureNumerator,
        "denominator": _timeSignatureDenominator,
      },
      "tempoStretchEnabled": _tempoStretchEnabled,
      "tempoStretchPreservePitchDefault": _tempoStretchPreservePitchDefault,
      "rows": rowsJson,
      "trackGroups": _trackGroups
          .map((group) => group.toJson())
          .toList(growable: false),
      "tracks": tracksJson,
      "rowStates": rowStates,
      "rowEffects": rowEffects,
      "master": {
        "gain": _masterGain,
        "pan": _masterPan,
        "effects": _masterEffectSnapshot.toJson(),
      },
      "ui": {
        "showProducerCaptureUi": _showProducerCaptureUi,
        "desktopKeyboardMidiEnabled": _desktopKeyboardMidiEnabled,
        "desktopSpacebarStopReturnsToStart": _desktopSpacebarStopReturnsToStart,
        "allowMultipleExpandedRows": _allowMultipleExpandedRows,
        "expandRowsOnTrackSelect": _expandRowsOnTrackSelect,
        "crossfadeMode": _projectCrossfadeMode,
        "metronomeEnabled": _metronomeEnabled,
        "metronomeVolume": _metronomeVolume,
        "sampleRate": _preferredDawSampleRate,
        "bufferSize": _preferredDawBufferSize,
        "midiInputChannel": _midiInputChannelFilter,
        "loopEnabled": _loopEnabled,
        "loopStartMs": _loopStartMs,
        "loopEndMs": _loopEndMs,
      },
    };
    if (_cloudProjectId.isNotEmpty) {
      json["cloudProjectId"] = _cloudProjectId;
    }
    if (_cloudWorkspaceId.isNotEmpty) {
      json["cloudWorkspaceId"] = _cloudWorkspaceId;
    }
    if (_cloudOrganizationId.isNotEmpty) {
      json["cloudOrganizationId"] = _cloudOrganizationId;
    }
    final cloudDocumentRevision = _cloudDocumentRevision;
    if (cloudDocumentRevision != null) {
      json["cloudDocumentRevision"] = cloudDocumentRevision;
    }
    if (_cloudSyncedAt.isNotEmpty) {
      json["cloudSyncedAt"] = _cloudSyncedAt;
    }
    if (_cloudSourceFingerprint.isNotEmpty) {
      json['cloudSourceFingerprint'] = _cloudSourceFingerprint;
    }
    if (assistantChat != null) {
      json["assistantChat"] = assistantChat;
    }
    if (_usingCompatibilityAudio) {
      json['compatibility'] = _compatibilityProjectionMetadata.isEmpty
          ? const <String, dynamic>{'variant': 'audio'}
          : _compatibilityProjectionMetadata;
    }
    return json;
  }

  Future<void> _performAutosaveWrite() async {
    if (_usingCompatibilityAudio) {
      await _forkCompatibilityProjectForEdits();
    }
    if (!_usingCompatibilityAudio) {
      await _promoteCompatibilityAudioIntoCurrentProject();
    }
    _syncEffectSnapshotCacheToCurrentRows();
    await _refreshHostedInstrumentStatesForPersistence(captureAll: false);
    final json = await _buildProjectJsonSnapshot();
    _attachPersistedUndoHistoryToProjectJson(json);
    if (_usingCompatibilityAudio) {
      await ProjectCompatibilityService.writeCompatibleProjection(
        projectDir: _projectDir,
        project: json,
      );
    } else {
      await _projectPersistence.saveProjectState(
        projectDir: _projectDir,
        projectState: json,
        mode: AudioProjectSaveMode.autosave,
      );
    }
    if (!_usingCompatibilityAudio) {
      await _refreshCompatibilityAudioStatus(project: json);
    }
    if (_isPlaying) {
      // _scheduleCloudAutoSync intentionally does not run while playing.
      // Retain the intent and schedule it when transport stops.
      _cloudAutoSyncDirty = true;
    } else if (!_cloudAutoSyncInFlight) {
      _scheduleCloudAutoSync(reason: 'autosave');
    }
    if (!_usingCompatibilityAudio) {
      _requestLocalVersionSnapshot(
        reason: ProjectVersionReason.autosave,
        minInterval: ProjectVersionStore.defaultPeriodicInterval,
      );
    }
    await _persistUndoHistory();
  }

  void _attachPersistedUndoHistoryToProjectJson(Map<String, dynamic> json) {
    final undo = _undoManager.persistableUndoRecords;
    final redo = _undoManager.persistableRedoRecords;
    if (undo.isEmpty && redo.isEmpty) {
      json.remove('undoHistory');
      return;
    }
    json['undoHistory'] = ProjectUndoHistorySnapshot(
      undo: undo,
      redo: redo,
    ).toJson(maxEntries: _undoManager.maxHistory);
  }

  Future<void> _restorePersistedUndoHistory(
    Map<String, dynamic> projectJson,
  ) async {
    try {
      var history = ProjectUndoHistorySnapshot.fromJsonValue(
        projectJson['undoHistory'],
      );
      if (history.isEmpty) {
        history = await _projectUndoHistoryStore.load(_projectDir);
      }
      _undoManager.restoreCommandHistory(
        undo: history.undo,
        redo: history.redo,
        actionFactory: _editorUndoActionFromPersistedRecord,
        notify: false,
      );
    } catch (error) {
      debugPrint('Project undo history restore skipped: $error');
    }
  }

  Future<void> _persistUndoHistory() async {
    try {
      await _projectUndoHistoryStore.save(
        projectDir: _projectDir,
        undo: _undoManager.persistableUndoRecords,
        redo: _undoManager.persistableRedoRecords,
        maxEntries: _undoManager.maxHistory,
      );
    } catch (error) {
      debugPrint('Project undo history save skipped: $error');
    }
  }

  EditorUndoAction? _editorUndoActionFromPersistedRecord(
    ProjectUndoSnapshotRecord record,
  ) {
    final command = record.command;
    if (command == null) return null;
    return _editorUndoActionFromPersistedCommand(
      command,
      fallbackDescription: record.description,
    );
  }

  EditorUndoAction? _editorUndoActionFromPersistedCommand(
    Map<String, dynamic> command, {
    String fallbackDescription = '',
  }) {
    final type = (command['type'] ?? '').toString();
    final clipIndex = _commandInt(command, 'clipIndex');
    final clipId = _commandClipId(command);
    switch (type) {
      case 'compound':
        final rawActions = command['actions'];
        if (rawActions is! List || rawActions.isEmpty) return null;
        final actions = <EditorUndoAction>[];
        for (final rawAction in rawActions) {
          final actionCommand = rawAction is Map<String, dynamic>
              ? rawAction
              : rawAction is Map
              ? rawAction.cast<String, dynamic>()
              : null;
          if (actionCommand == null) return null;
          final action = _editorUndoActionFromPersistedCommand(actionCommand);
          if (action == null) return null;
          actions.add(action);
        }
        return CompoundUndoAction(
          (command['description'] ?? fallbackDescription).toString(),
          actions,
          batchGraphMutations:
              _commandBool(command, 'batchGraphMutations') ?? false,
        );
      case 'clipPresenceAdd':
      case 'clipPresenceDelete':
        final rawClip = command['clip'];
        final clipPayload = rawClip is Map<String, dynamic>
            ? rawClip
            : rawClip is Map
            ? rawClip.cast<String, dynamic>()
            : null;
        if (clipPayload == null) return null;
        return _PersistedClipPresenceAction(
          descriptionText: (command['description'] ?? fallbackDescription)
              .toString()
              .trim(),
          addedByRedo: type == 'clipPresenceAdd',
          clipPayload: clipPayload,
          fallbackIndex: _commandInt(command, 'fallbackIndex') ?? -1,
          addClip: _addClipFromUndoPayload,
          removeClip: _removeClipForUndo,
        );
      case 'rowCreate':
        final createdRowId = _commandInt(command, 'createdRowId');
        final name = command['name']?.toString() ?? '';
        final position = command['position']?.toString() ?? '';
        final midi = command['midi'] == true;
        final instrumentId = command['instrumentId']?.toString() ?? '';
        if (createdRowId == null ||
            createdRowId <= 0 ||
            name.trim().isEmpty ||
            (position != 'end' && position != 'above' && position != 'below')) {
          return null;
        }
        final referenceRowId = _commandInt(command, 'referenceRowId');
        final previousSelectedRowId = _commandInt(
          command,
          'previousSelectedRowId',
        );
        return RowCreateUndoAction(
          previousSelectedRowId: previousSelectedRowId,
          initialRowId: createdRowId,
          persistedDescriptor: <String, dynamic>{
            'name': name,
            'midi': midi,
            'instrumentId': instrumentId,
            'position': position,
            'referenceRowId': referenceRowId,
          },
          createRow: (preferredRowId) => _createAiRow(
            name: name,
            midi: midi,
            instrumentId: instrumentId,
            position: position,
            referenceRowId: referenceRowId,
            preferredRowId: preferredRowId,
          ),
          deleteRow: _deleteAiCreatedRow,
          applySelection: _applyRowSelectionUndoState,
        );
      case 'clipSourceReplace':
        final rawBefore = command['beforeClip'];
        final rawAfter = command['afterClip'];
        final before = rawBefore is Map
            ? Map<String, dynamic>.from(rawBefore)
            : null;
        final after = rawAfter is Map
            ? Map<String, dynamic>.from(rawAfter)
            : null;
        if (before == null || after == null) return null;
        return ReplaceAudioClipSourceAction(
          beforePayload: before,
          afterPayload: after,
          applyPayload: _replaceAudioClipFromUndoPayload,
        );
      case 'clipGlue':
        final rawSources = command['sourceClips'];
        final rawResult = command['resultClip'];
        if (rawSources is! List || rawSources.length < 2 || rawResult is! Map) {
          return null;
        }
        final sourcePayloads = rawSources
            .whereType<Map>()
            .map((value) => Map<String, dynamic>.from(value))
            .toList(growable: false);
        if (sourcePayloads.length != rawSources.length) return null;
        return GlueAudioClipsAction(
          sourcePayloads: sourcePayloads,
          resultPayload: Map<String, dynamic>.from(rawResult),
          beforeClipOrder:
              (command['beforeClipOrder'] as List? ?? const <Object>[])
                  .map((value) => value.toString())
                  .toList(growable: false),
          beforeSelectedClipIds:
              (command['beforeSelectedClipIds'] as List? ?? const <Object>[])
                  .map((value) => value.toString())
                  .toList(growable: false),
          beforePrimaryClipId: command['beforePrimaryClipId']?.toString() ?? '',
          beforeSelectedRowId: _commandInt(command, 'beforeSelectedRowId'),
          applySnapshot: _applyAiV3GlueSnapshot,
        );
      case 'clipStemSeparation':
        final rawVocals = command['vocalsClip'];
        final rawInstrumental = command['instrumentalClip'];
        if (rawVocals is! Map || rawInstrumental is! Map) return null;
        return StemSeparationAction(
          sourceRowId: _commandInt(command, 'sourceRowId') ?? -1,
