                )
              : _handlePersistedMasterEffectUndo,
        );
      case 'masterEffectsSnapshot':
        return _MasterEffectsSnapshotAction(
          descriptionText: (command['description'] ?? fallbackDescription)
              .toString(),
          before: _commandMasterEffectsSnapshot(command['before']),
