    return _ClipStretchSnapshot(
      offsetSec: _valueDouble(map['offsetSec']) ?? 0.0,
      sourceTempoBpm: _valueDouble(map['sourceTempoBpm']) ?? 0.0,
      stretchToProjectTempo: _valueBool(map['stretchToProjectTempo']) ?? false,
      tempoStretchPreservePitch:
          _valueBool(map['tempoStretchPreservePitch']) ?? true,
      tempoWarpMode: normalizeTempoWarpMode(map['tempoWarpMode'] as String?),
      tempoStretchEnabled: _valueBool(map['tempoStretchEnabled']),
      tempoStretchPreservePitchDefault: _valueBool(
        map['tempoStretchPreservePitchDefault'],
      ),
    );
  }

  _RowLayoutSnapshot _commandRowLayoutSnapshot(Object? raw) {
    final map = raw is Map<String, dynamic>
        ? raw
        : raw is Map
        ? raw.cast<String, dynamic>()
        : const <String, dynamic>{};
    final rawRows = map['rows'];
    final rows = <TimelineRow>[];
    if (rawRows is List) {
      for (final item in rawRows) {
        final rowMap = item is Map<String, dynamic>
            ? item
            : item is Map
            ? item.cast<String, dynamic>()
            : null;
        if (rowMap == null) continue;
        rows.add(_timelineRowFromJson(rowMap));
      }
    }
    if (rows.isEmpty) {
      rows.add(TimelineRow(rowId: -1, name: 'Track 1', iconId: 0));
    }
    final groups = <TrackGroup>[];
    final rawGroups = map['trackGroups'];
    if (rawGroups is List) {
      for (final item in rawGroups) {
        final groupMap = item is Map<String, dynamic>
            ? item
            : item is Map
            ? item.cast<String, dynamic>()
            : null;
        if (groupMap == null) continue;
        final group = TrackGroupJson.fromJson(groupMap);
        if (group.id.trim().isNotEmpty) groups.add(group);
      }
    }
    return _RowLayoutSnapshot(rows: rows, trackGroups: groups);
  }

