  Future<void> _applyPersistedMidiClipState(
    AudioTrack clip,
    List<MidiNote> notes,
    String instrumentId,
    String instrumentName,
    Map<String, double> instrumentParams,
    String hostedInstrumentStateBase64,
  ) async {
    _applyMidiClipStateLocally(
      clip,
      notes: notes,
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      instrumentParams: instrumentParams,
    );
    clip.hostedInstrumentStateBase64 = hostedInstrumentStateBase64.trim();
    final refreshed = await _refreshMidiClipEngineNow(
      clip,
      failureNotice: 'Could not switch instrument for this MIDI clip.',
    );
    if (!refreshed) {
      throw StateError('v3_midi_native_sync_failed');
    }
    final clipIndex = _audioTracks.indexOf(clip);
    if (clipIndex >= 0) {
      await _syncClipTimingToEngine(clipIndex);
    }
    if (mounted) setState(() {});
  }

  Future<void> _applyPersistedClipStretchSnapshot(
    AudioTrack clip,
    _ClipStretchSnapshot snapshot,
  ) async {
    clip.offset = snapshot.offsetSec;
    clip.sourceTempoBpm = snapshot.sourceTempoBpm;
    clip.stretchToProjectTempo = snapshot.stretchToProjectTempo;
    clip.tempoStretchPreservePitch = snapshot.tempoStretchPreservePitch;
    clip.tempoWarpMode = normalizeTempoWarpMode(snapshot.tempoWarpMode);
    _tempoStretchEnabled =
        snapshot.tempoStretchEnabled ??
        _audioTracks
            .where((track) => !track.isMidi)
            .any((track) => track.stretchToProjectTempo);
    _tempoStretchPreservePitchDefault =
        snapshot.tempoStretchPreservePitchDefault ??
        _tempoStretchPreservePitchDefault;
    final clipIndex = _audioTracks.indexOf(clip);
    if (clipIndex >= 0) {
      await _syncClipTimingToEngine(clipIndex);
    }
    await _syncClipMixToEngine(clip);
    _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
    if (mounted) setState(() {});
  }

  Future<void> _addClipFromUndoPayload(Map<String, dynamic> payload) async {
    final clipId = _normalizePersistedClipId(payload['clipId']);
    if (_clipIndexForPersistentId(clipId) >= 0) return;

    final fileName = (payload['fileName'] ?? '').toString().trim();
    final file = File(
      p.join(ProjectManager.audioDir(_projectDir).path, fileName),
    );
    final kind = ClipKindWire.fromWire((payload['clipType'] ?? '').toString());
    final persistedRowId = _valueInt(payload['rowId']);
    final row = persistedRowId == null
        ? _valueInt(payload['rowIndex']) ?? -1
        : _rowIndexForId(persistedRowId);
    if (!_isValidRowIndex(row)) {
      throw StateError('clip_restore_row_missing');
    }
    final timeMs = (_valueDouble(payload['offset']) ?? 0.0) * 1000.0;
    final trimStart = Duration(
      milliseconds: _valueInt(payload['trimStartMs']) ?? 0,
    );
    final trimEnd = Duration(
      milliseconds:
          _valueInt(payload['trimEndMs']) ??
          math.max(0, _valueInt(payload['audioDurationMs']) ?? 0),
    );
    final automation = _commandAutomationPoints(payload['automation']);

    if (kind == ClipKind.midi) {
      await _addMidiTrack(
        instrumentId: (payload['instrumentId'] ?? '').toString(),
        instrumentName: (payload['instrumentName'] ?? '').toString(),
        instrumentParams: _commandDoubleMap(payload['instrumentParams']),
        midiNotes: _commandMidiNotes(payload['midiNotes']),
        row: row,
        timeMs: timeMs,
        trimStartRequested: trimStart,
        trimEndRequested: trimEnd,
        renderedFile: fileName.isEmpty ? null : file,
        label: (payload['label'] ?? '').toString(),
        gain: _valueDouble(payload['gain']),
        pitchSemitones: _valueDouble(payload['pitchSemitones']),
        sourceTempoBpm: _valueDouble(payload['sourceTempoBpm']),
        stretchToProjectTempo: _valueBool(payload['stretchToProjectTempo']),
        tempoStretchPreservePitch: _valueBool(
          payload['tempoStretchPreservePitch'],
        ),
        tempoWarpMode: payload['tempoWarpMode'] as String?,
        crossfade: _valueDouble(payload['crossfade']),
        automation: automation,
        hostedInstrumentStateBase64: (payload['hostedInstrumentStateB64'] ?? '')
            .toString(),
        clipId: clipId,
      );
      return;
    }

    if (!file.existsSync()) {
      throw StateError('Missing audio file for undo history: $fileName');
    }
    await _addAudioTrackFromProjectFile(
      projectAudioFile: file,
      label: (payload['label'] ?? '').toString(),
      row: row,
      timeMs: timeMs,
      trimStartRequested: trimStart,
      trimEndRequested: trimEnd,
      gain: _valueDouble(payload['gain']),
      normalizeVolume: _valueBool(payload['normalizeVolume']),
      normalizeGain: _valueDouble(payload['normalizeGain']),
      preNormalizeGain: _valueDouble(payload['preNormalizeGain']),
      pitchSemitones: _valueDouble(payload['pitchSemitones']),
      isReversed: _valueBool(payload['isReversed']) ?? false,
      sourceTempoBpm: _valueDouble(payload['sourceTempoBpm']),
      stretchToProjectTempo: _valueBool(payload['stretchToProjectTempo']),
      tempoStretchPreservePitch: _valueBool(
        payload['tempoStretchPreservePitch'],
      ),
      tempoWarpMode: payload['tempoWarpMode'] as String?,
      recordingLatencyMs: _valueDouble(payload['recordingLatencyMs']),
      alignmentOffsetMs: _valueDouble(payload['alignmentOffsetMs']),
      audioEnhancementPreset: (payload['audioEnhancementPreset'] ?? '')
          .toString(),
      crossfade: _valueDouble(payload['crossfade']),
      automation: automation,
      clipId: clipId,
    );
  }

  Future<void> _removeClipForUndo(String clipId, int fallbackIndex) async {
    var index = _clipIndexForPersistentId(clipId);
    if (index < 0 && _isValidClipIndex(fallbackIndex)) {
      index = fallbackIndex;
    }
    if (!_isValidClipIndex(index)) return;

    final clip = _audioTracks[index];
    clip.audioStartTimer?.cancel();
    if (_activeMidiClipEngineId == clip.engineClipId) {
      _closeMidiClipEditor();
    }
    _audioTracks.removeAt(index);
    if (clip.engineClipId >= 0) {
      await JuceAudioEngine.removeTrack(clip.engineClipId);
    }
    _updateOverallDurationIfNeeded(removedClips: <AudioTrack>[clip]);
    await _syncClipFadesForRowsToEngine({_clipRowIdForFadeSync(clip)});
    _clipFadeRowIdByEngineId.remove(clip.engineClipId);
    if (mounted) setState(() {});
  }

  void _applyPersistedRowGainState(int row, double gain) {
    if (!_isValidRowIndex(row)) return;
    setState(() => _rowGain[row] = gain);
  }

  Future<void> _setRowGainLive(int row, double gain) async {
    if (!_isValidRowIndex(row)) return;
    final group = _trackGroupForLeadRowIndex(row);
    if (group != null) {
      _applyTrackGroupGainState(group.id, gain);
      await _setTrackGroupGainNative(group.id, gain);
      return;
    }
    await JuceAudioEngine.setRowGain(row, gain.clamp(_kGainUiMin, _kGainUiMax));
  }

  Future<void> _commitRowGainFromUi(
    int row,
    double oldGain,
    double newGain, {
    String source = 'row_gain',
  }) async {
    if (!_isValidRowIndex(row)) return;
    final safeOldGain = oldGain.clamp(_kGainUiMin, _kGainUiMax).toDouble();
    final safeNewGain = newGain.clamp(_kGainUiMin, _kGainUiMax).toDouble();
    if ((safeNewGain - safeOldGain).abs() < 0.00001) return;

    final group = _trackGroupForLeadRowIndex(row);
    if (group != null) {
      await _undoManager.execute(
        SetRowGainAction(
          row: row,
          oldGain: safeOldGain,
          newGain: safeNewGain,
          applyNative: (_, gain) => _setTrackGroupGainNative(group.id, gain),
          applyToState: (_, gain) {
            _applyTrackGroupGainState(group.id, gain);
          },
        ),
      );
      _recordProducerManualEdit('${source}_group_bus', {
        'group_id': group.id,
        'row': row,
        'old_gain': safeOldGain,
        'new_gain': safeNewGain,
      });
      return;
    }

    final gainTargetId = _rowMixAutomationTargetId('gain');
    if (_hasExplicitAutomationForTarget(row, gainTargetId)) {
      final target =
          _rowAutomationTargets[row]?[gainTargetId] ??
          _fallbackAutomationTargetMeta(gainTargetId);
      final oldPoints = _pointsForAutomationTarget(
        row,
        gainTargetId,
      ).map((point) => point.copy()).toList(growable: false);
      final delta = safeNewGain - safeOldGain;
      final newPoints = oldPoints
          .map((point) {
            final currentValue = _denormalizeAutomationValue(
              point.volume,
              target,
            );
            final nextValue = (currentValue + delta)
                .clamp(target.min, target.max)
                .toDouble();
            return AutomationPoint(
              x: point.x,
              volume: _normalizeAutomationValue(
                nextValue,
                min: target.min,
                max: target.max,
                fallback: point.volume,
              ),
            );
          })
          .toList(growable: false);

      await _setAutomationTargetPointsWithUndo(
        row,
        gainTargetId,
        newPoints,
        oldPointsOverride: oldPoints,
      );

      final timeMs = _globalAudioClock.inMilliseconds.toDouble();
      final liveNormalized = _resolvedAutomationValueAtMs(
        row,
        gainTargetId,
        timeMs,
      );
      final liveGain = _denormalizeAutomationValue(
        liveNormalized,
        target,
      ).clamp(_kGainUiMin, _kGainUiMax).toDouble();
      setState(() => _rowGain[row] = liveGain);
      _recordProducerManualEdit('${source}_automation_trim', {
        'row': row,
        'old_gain': safeOldGain,
        'new_gain': safeNewGain,
        'delta': delta,
      });
      return;
    }

    await _undoManager.execute(
      SetRowGainAction(
        row: row,
        oldGain: safeOldGain,
        newGain: safeNewGain,
        applyToState: (r, g) {
          setState(() {
            _rowGain[r] = g;
          });
        },
      ),
    );
    _recordProducerManualEdit(source, {
      'row': row,
      'old_gain': safeOldGain,
      'new_gain': safeNewGain,
    });
  }

  void _applyPersistedRowPanState(int row, double pan) {
    if (!_isValidRowIndex(row)) return;
    setState(() => _rowPan[row] = pan);
  }

  Future<void> _commitRowPanFromUi(
    int row,
    double oldPan,
    double newPan, {
    String source = 'row_pan',
  }) async {
    if (!_isValidRowIndex(row)) return;
    final safeOldPan = oldPan.clamp(0.0, 1.0).toDouble();
    final safeNewPan = newPan.clamp(0.0, 1.0).toDouble();
    if ((safeNewPan - safeOldPan).abs() < 0.00001) return;

    final group = _trackGroupForLeadRowIndex(row);
    if (group != null) {
      await _undoManager.execute(
        SetRowPanAction(
          row: row,
          oldPan: safeOldPan,
          newPan: safeNewPan,
          applyNative: (_, pan) => _setTrackGroupPanNative(group.id, pan),
          applyToState: (_, pan) {
            _applyTrackGroupPanState(group.id, pan);
          },
        ),
      );
      _recordProducerManualEdit('${source}_group_bus', {
        'group_id': group.id,
        'row': row,
        'old_pan': safeOldPan,
        'new_pan': safeNewPan,
      });
      return;
    }

    await _undoManager.execute(
      SetRowPanAction(
        row: row,
        oldPan: safeOldPan,
        newPan: safeNewPan,
        applyToState: (r, p) {
          setState(() {
            _rowPan[r] = p;
          });
        },
      ),
    );
    _recordProducerManualEdit(source, {
      'row': row,
      'old_pan': safeOldPan,
      'new_pan': safeNewPan,
    });
  }

