  void _handlePersistedRowEffectParamUndo({
    required int row,
    required int effectIndex,
    required String paramId,
  }) {
    _handlePersistedRowEffectUndo(row);
    unawaited(() async {
      try {
        final params = await JuceAudioEngine.getTrackPluginParameters(
          row,
          effectIndex,
        );
        final value = _pluginParamValueById(params, paramId);
        if (value != null) {
          _updateAutomationTargetBaselineForEffectParameter(
            row: row,
            effectIndex: effectIndex,
            paramId: paramId,
            value: value,
            master: false,
          );
        }
      } catch (_) {}
    }());
  }

  void _handlePersistedMasterEffectParamUndo({
    required int effectIndex,
    required String paramId,
  }) {
    _handlePersistedMasterEffectUndo();
    unawaited(() async {
      try {
        final params = await JuceAudioEngine.getMasterPluginParameters(
          effectIndex,
        );
        final value = _pluginParamValueById(params, paramId);
        if (value != null) {
          _updateAutomationTargetBaselineForEffectParameter(
            effectIndex: effectIndex,
            paramId: paramId,
            value: value,
            master: true,
          );
        }
      } catch (_) {}
    }());
  }

  dynamic _pluginParamValueById(
    List<Map<String, dynamic>> params,
    String paramId,
  ) {
    for (final param in params) {
      final id = (param['id'] ?? param['name'] ?? '').toString();
      if (id == paramId) return param['value'];
    }
    return null;
  }

  void _requestLocalVersionSnapshot({
    required ProjectVersionReason reason,
    required Duration minInterval,
  }) {
    if (_usingCompatibilityAudio) return;
    if (_localVersionSnapshotInFlight) return;
    _localVersionSnapshotInFlight = true;
    unawaited(() async {
      try {
        if (!await ProjectVersionPreferences.isEnabled()) return;
        await _projectVersionStore.maybeCreateSnapshot(
          projectDir: _projectDir,
          reason: reason,
          minInterval: minInterval,
        );
      } catch (error) {
        debugPrint('Project version snapshot skipped: $error');
      } finally {
        _localVersionSnapshotInFlight = false;
      }
    }());
  }

  void _flushAndRequestLocalVersionSnapshot({
    required ProjectVersionReason reason,
    required Duration minInterval,
  }) {
    if (_usingCompatibilityAudio) return;
    if (_localVersionSnapshotInFlight) return;
    _localVersionSnapshotInFlight = true;
    unawaited(() async {
      try {
        if (!await ProjectVersionPreferences.isEnabled()) return;
        await _projectAutosaveCoordinator.flush();
        await _projectVersionStore.maybeCreateSnapshot(
          projectDir: _projectDir,
          reason: reason,
          minInterval: minInterval,
        );
      } catch (error) {
        debugPrint('Project version snapshot skipped: $error');
      } finally {
        _localVersionSnapshotInFlight = false;
      }
    }());
  }

  Future<void> _uploadProjectTelemetrySnapshot(
    Map<String, dynamic> json,
  ) async {
    if (!mounted) return;
    final auth = context.read<AuthService>();
    try {
      final telemetrySnapshot = _buildProjectTelemetrySnapshot(json);
      final redactedJson = Map<String, dynamic>.from(json);
      final rawTracks = json['tracks'] as List?;
      if (rawTracks != null) {
        redactedJson['tracks'] = rawTracks
            .map((track) {
              if (track is! Map) return track;
              final copy = Map<String, dynamic>.from(
                track.cast<String, dynamic>(),
              );
              copy.remove('hostedInstrumentStateB64');
              copy.remove('hostedInstrumentStateBase64');
              return copy;
            })
            .toList(growable: false);
      }
      unawaited(
        ProjectTelemetryService.instance.uploadProjectSnapshot(
          auth: auth,
          projectId: _projectId.trim(),
          projectName: _projectName,
          projectJson: redactedJson,
          projectSnapshot: telemetrySnapshot,
        ),
      );
    } catch (e) {
      debugPrint("Project telemetry snapshot failed: $e");
    }
  }

  Future<void> _normalizeProjectAudioAssetsForCheckpoint() async {
    final audioDir = ProjectManager.audioDir(_projectDir);
    if (!await audioDir.exists()) {
      await audioDir.create(recursive: true);
    }

    final assignedFileNameBySourcePath = <String, String>{};
    final usedSavedFileNamesLower = <String>{};
    final referenced = <String>{};

    for (final tr in _audioTracks) {
      final src = tr.file;
      if (!src.existsSync()) continue;

      final normalizedSourcePath = p.normalize(src.path);
      final existingAssigned =
          assignedFileNameBySourcePath[normalizedSourcePath];
      final fileName =
          existingAssigned ??
          ProjectManager.uniqueAudioFileName(
            preferredName: _displayNameForFilePath(src.path),
            usedNamesLower: usedSavedFileNamesLower,
          );
      assignedFileNameBySourcePath[normalizedSourcePath] = fileName;
      referenced.add(fileName);
      final dst = File(p.join(audioDir.path, fileName));
      if (src.path != dst.path) {
        if (await dst.exists()) {
          await dst.delete();
        }
        await src.copy(dst.path);
      }
    }

    final files = audioDir.listSync().whereType<File>();
    for (final f in files) {
      final name = p.basename(f.path);
      if (!referenced.contains(name)) {
        try {
          await f.delete();
        } catch (_) {}
      }
    }
  }

  Future<void> _refreshAllPersistedEffectSnapshots() async {
    _syncEffectSnapshotCacheToCurrentRows();
    for (int row = 0; row < _rowCount; row++) {
      await _refreshPersistedEffectSnapshotForRow(row);
    }
    await _refreshPersistedMasterEffectSnapshot();
  }

  Future<void> _saveProject({bool showSnackBar = true}) async {
    try {
      await _projectAutosaveCoordinator.flush();
      if (!_usingCompatibilityAudio) {
        await _promoteCompatibilityAudioIntoCurrentProject();
        await _normalizeProjectAudioAssetsForCheckpoint();
      }
      await _refreshAllPersistedEffectSnapshots();
      await _refreshHostedInstrumentStatesForPersistence();
      final json = await _buildProjectJsonSnapshot();
      _attachPersistedUndoHistoryToProjectJson(json);
      if (_usingCompatibilityAudio) {
        await ProjectCompatibilityService.writeCompatibleProjection(
          projectDir: _projectDir,
          project: json,
        );
      } else {
        await _projectPersistence.saveProjectState(
          projectDir: _projectDir,
          projectState: json,
          mode: AudioProjectSaveMode.checkpoint,
        );
      }
      _projectAutosaveCoordinator.clearDirty();
      await _uploadProjectTelemetrySnapshot(json);
      _requestCloudAutoSyncNow('save');
      if (!_usingCompatibilityAudio) {
        _requestLocalVersionSnapshot(
          reason: ProjectVersionReason.manualSave,
          minInterval: ProjectVersionStore.defaultSaveInterval,
        );
      }
      await _persistUndoHistory();

      if (mounted && showSnackBar) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(L10n.translate(context, 'Project saved'))),
        );
      }
    } catch (e) {
      debugPrint("Project save failed: $e");
      if (mounted && showSnackBar) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${L10n.translate(context, 'Save failed')}: $e'),
          ),
        );
      }
    }
  }

