  bool _looksLikeGeneratedUntitledProjectName(String name) {
    return RegExp(r'^Untitled Project(?: #\d+)?$').hasMatch(name.trim());
  }

  bool _projectRequiresNameConfirmation(Map<String, dynamic> json) {
    final confirmed = json['nameConfirmed'];
    if (confirmed is bool) {
      return !confirmed;
    }
    final currentName = (json['name'] as String?) ?? _projectName;
    return _looksLikeGeneratedUntitledProjectName(currentName);
  }

  void _remapProjectAudioPaths({
    required Directory oldProjectDir,
    required Directory newProjectDir,
  }) {
    final oldAudioDir = ProjectManager.audioDir(oldProjectDir).path;
    final newAudioDir = ProjectManager.audioDir(newProjectDir).path;

    for (final tr in _audioTracks) {
      final oldFilePath = tr.file.path;
      final oldOriginalPath = tr.originalFile.path;
      final fileName = p.basename(oldFilePath);
      final originalName = p.basename(oldOriginalPath);

      final shouldRemapFile =
          oldFilePath.startsWith(oldAudioDir) ||
          !File(oldFilePath).existsSync();
      final shouldRemapOriginal =
          oldOriginalPath.startsWith(oldAudioDir) ||
          !File(oldOriginalPath).existsSync();

      if (shouldRemapFile) {
        tr.file = File(p.join(newAudioDir, fileName));
      }
      if (shouldRemapOriginal) {
        tr.originalFile = File(p.join(newAudioDir, originalName));
      }
    }
  }

  Future<bool> _renameProjectAndSyncState(
    String nextName, {
    bool showSuccessSnackBar = true,
  }) async {
    final renamed = nextName.trim();
    if (renamed.isEmpty) return false;

    if (renamed == _projectName) {
      _setStateAndRefreshProjectSettings(() {
        _requiresProjectNaming = false;
      });
      _scheduleProjectAutosave();
      return true;
    }

    try {
      final oldProjectDir = _projectDir;
      final newDir = await ProjectManager.renameProject(_projectDir, renamed);
      _setStateAndRefreshProjectSettings(() {
        _projectDir = newDir;
        _projectName = p.basename(newDir.path);
        _requiresProjectNaming = false;
        _remapProjectAudioPaths(
          oldProjectDir: oldProjectDir,
          newProjectDir: newDir,
        );
      });
      _scheduleProjectAutosave();
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${L10n.translate(context, 'Rename failed')}: $e'),
          ),
        );
      }
      return false;
    }

    if (mounted && showSuccessSnackBar) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(L10n.translate(context, 'Project renamed'))),
      );
    }
    return true;
  }

  Future<bool> _ensureProjectNamedOnFirstExit() async {
    if (!_requiresProjectNaming) return true;
    final renamed = await _showProjectNameDialog(
      title: L10n.translate(context, 'Name Your Project'),
      initialName: _projectName,
      hint: L10n.translate(context, 'Project name'),
    );
    if (renamed == null) return false;
    final newName = renamed.trim();
    if (newName.isEmpty) return false;
    if (newName == _projectName) {
      setState(() => _requiresProjectNaming = false);
      return true;
    }
    return _renameProjectAndSyncState(newName, showSuccessSnackBar: false);
  }

  Future<void> _handleBackPressed() async {
    if (_isDialogOpen) return;
    _isDialogOpen = true;

    if (_isPlaying) {
      _isPlaying = false;
      await _pauseAudio(_audioEditorStateSetter ?? (fn) {});
    }

    final canExit = await _ensureProjectNamedOnFirstExit();
    if (!canExit) {
      _isDialogOpen = false;
      return;
    }

    await _saveProject(showSnackBar: false);
    _setDawPanelVisible('add_actions', false);
    _setDawPanelVisible('chat_panel', false);
    _setDawPanelVisible('chat_input', false);
    _setDawPanelVisible('sample_browser', false);
    _setDawPanelVisible('piano_roll', false);
    final activeTopPopupPanelId = _topPopupPanelId(_activeTopPopup);
    if (activeTopPopupPanelId != null) {
      _setDawPanelVisible(activeTopPopupPanelId, false);
    }

    if (mounted) {
      _pausePlayback();
      for (var track in _audioTracks) {
        track.audioStartTimer?.cancel();
      }
      await _shutdownAudioEngineV2Aware();
      Navigator.of(context).pop();
    }
  }

  void _handleBackButtonTap() {
    if (_backButtonExitInFlight) return;
    _trackUiClick(controlId: 'back_button', surface: 'top_bar');
    unawaited(_runBackButtonExitSequence());
  }

  Future<void> _runBackButtonExitSequence() async {
    _backButtonExitInFlight = true;
    if (mounted) {
      setState(() {
        _backButtonTapFeedbackActive = true;
      });
    }
    unawaited(AppHaptics.impact(AppHapticImpact.light));
    await SchedulerBinding.instance.endOfFrame;
    await Future<void>.delayed(const Duration(milliseconds: 48));
    if (mounted && _backButtonTapFeedbackActive) {
      setState(() {
        _backButtonTapFeedbackActive = false;
      });
    }
    try {
      await _handleBackPressed();
    } finally {
      _backButtonExitInFlight = false;
      if (mounted && (_backButtonTapFeedbackActive || _backButtonPressed)) {
        setState(() {
          _backButtonTapFeedbackActive = false;
          _backButtonPressed = false;
        });
      }
    }
  }

  // Helper: Format Duration as mm:ss:xx (first two digits of ms).
  String _formatDuration(Duration duration) {
    String twoDigits(int n) => n.toString().padLeft(2, '0');
    String firstTwoMsDigits(int milliseconds) {
      final msString = milliseconds.toString().padLeft(3, '0');
      return msString.substring(0, 2);
    }

    final minutes = twoDigits(duration.inMinutes.remainder(60));
    final seconds = twoDigits(duration.inSeconds.remainder(60));
    final millisecondsFirstTwo = firstTwoMsDigits(
      duration.inMilliseconds.remainder(1000),
    );

    return "$minutes:$seconds:$millisecondsFirstTwo";
  }

  void prewarmFFT() async {
    // Create a small dummy signal
    List<double> dummySignal = List.filled(1024, 0.0);
    // Fill it with some dummy data
    for (int i = 0; i < dummySignal.length; i++) {
      dummySignal[i] = sin(2 * pi * i / dummySignal.length);
    }
    // Get a padded length for the dummy signal (e.g., next power of 2)
    int paddedLength = _nextPowerOf2(dummySignal.length);
    final fft = FFT(paddedLength);
    // Perform a dummy FFT
    List<double> paddedDummy = List.filled(paddedLength, 0.0);
    paddedDummy.setAll(0, dummySignal);
    normalize(paddedDummy);
    fft.realFft(paddedDummy);
  }

  void _startMeterPolling() {
    if (!_shouldPollMetersDuringPlayback) return;
    if (_meterPolling) return;
    _meterPolling = true;

    // Defensive: re-enable native metering whenever polling starts.
    unawaited(_setNativeMeteringEnabled(true));

    _meterTimer?.cancel();
    _meterDecayTimer?.cancel();

    _meterTimer = Timer.periodic(const Duration(milliseconds: 33), (_) async {
      // prevent overlapping async ticks (super important)
      if (!_meterPolling) return; // stopped mid-flight
      if (_meterPollingBusy) return; // prevent overlap
      _meterPollingBusy = true;

      try {
        final packed = await JuceAudioEngine.getAllMeterValues();
        if (!_meterPolling || packed.isEmpty) return;

        // expected length: 5 * (1 + kNumRows)
        final stride = _meterStride;

        // ---- MASTER ----
        if (packed.length >= stride) {
          final m0 = 0;

          _meters.setMaster(
            MeterFrame(
              peakL: packed[m0 + 0].clamp(0.0, 1.0),
              peakR: packed[m0 + 1].clamp(0.0, 1.0),
              rmsL: packed[m0 + 2].clamp(0.0, 1.0),
              rmsR: packed[m0 + 3].clamp(0.0, 1.0),
              clip: packed[m0 + 4] > 0.5,
            ),
          );
        }

        // ---- ROWS ----
        // Use whichever source of truth you already have:
        // - kNumRows (your constant)
        // - or _meters.rows.length
        final rowCount = _rowCount; // or: _meters.rows.length

        for (int row = 0; row < rowCount; row++) {
          final base = stride * (1 + row);
          if (base + 4 >= packed.length) break;

          _meters.setRow(
            row,
            MeterFrame(
              peakL: packed[base + 0].clamp(0.0, 1.0),
              peakR: packed[base + 1].clamp(0.0, 1.0),
              rmsL: packed[base + 2].clamp(0.0, 1.0),
              rmsR: packed[base + 3].clamp(0.0, 1.0),
              clip: packed[base + 4] > 0.5,
            ),
          );
        }
      } catch (_) {
        // ignore transient channel errors
      } finally {
        _meterPollingBusy = false;
      }
    });
  }

  void _stopMeterPolling({bool decayToZero = true}) {
    _meterPolling = false;
    _meterTimer?.cancel();
    _meterTimer = null;

    // in case we stopped while an await was in-flight
    _meterPollingBusy = false;
    unawaited(_setNativeMeteringEnabled(false));

    if (!decayToZero) {
      _meterDecayTimer?.cancel();
      _meters.zeroAll();
      return;
    }

    _startMeterDecayToZero();
  }

  void _startMeterDecayToZero() {
    _meterDecayTimer?.cancel();

    // ~30fps-ish but cheap
    _meterDecayTimer = Timer.periodic(const Duration(milliseconds: 33), (_) {
      // if we started polling again, stop decaying
      if (_meterPolling) {
        _meterDecayTimer?.cancel();
        _meterDecayTimer = null;
        return;
      }

      _meters.decayAll(mul: 0.82); // tweak feel: 0.75 faster, 0.9 slower

      if (_meters.isAllZero) {
        _meterDecayTimer?.cancel();
        _meterDecayTimer = null;
      }
    });
  }

  bool get _shouldPollMetersDuringPlayback =>
      _isPlaying &&
      !(_showPianoRoll && _pianoRollFullscreen) &&
      !(_showPitchLab && _pitchLabFullscreen);

  bool get _tabletOverlayWindowFullscreen =>
      (_sampleBrowserVisible && _sampleBrowserExpanded) ||
      (_showCaptureDeck && _captureDeckFullscreen) ||
      (_showPianoRoll && _pianoRollFullscreen) ||
      (_showPitchLab && _pitchLabFullscreen);

  void _syncMeterPollingForVisibility() {
    if (_shouldPollMetersDuringPlayback) {
      _startMeterPolling();
    } else {
      _stopMeterPolling();
    }
  }

  Future<void> _setNativeMeteringEnabled(bool enabled) async {
    try {
      await JuceAudioEngine.setMasterMeterEnabled(enabled);
      await JuceAudioEngine.setRowMetersEnabled(enabled);
    } catch (_) {
      // Native bridge can race shutdown/teardown; ignore best-effort toggles.
    }
  }

  /// Calculate effective audio position for a given track based on video position.
  Duration _calculateEffectiveAudioPositionForTrack(
    AudioTrack track,
    Duration videoPos,
  ) {
    final offsetDuration = Duration(
      milliseconds: (track.offset * 1000).toInt(),
    );
    if (videoPos < offsetDuration) {
      return track.trimStart;
    } else {
      var effectiveAudioPos = track.trimStart + (videoPos - offsetDuration);
      if (effectiveAudioPos > track.trimEnd) {
        effectiveAudioPos = track.trimEnd;
      }
      return effectiveAudioPos;
    }
  }

  // PLAY/PAUSE TOGGLE using a global _audioStarted flag.
  Future<void> _togglePlayPause() async {
    await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    return;
  }

  Future<void> _togglePlayPauseAudio(StateSetter setLocalState) async {
    // if (_audioTracks.isEmpty) {
    //   return;
    // }

    final targetPlaying = !_isPlaying;
    _transportDesiredPlaying = targetPlaying;
    _transportCommandSerial++;
    _applyOptimisticTransportVisual(targetPlaying);
    await _drainTransportCommandQueue(setLocalState);
  }

  void _applyOptimisticTransportVisual(bool targetPlaying) {
    if (!mounted) return;
    final currentVisualClock = _isPlaying
        ? _estimateTransportClockFromSample()
        : _globalAudioClock;
    if (targetPlaying &&
        _loopEnabled &&
        _loopEndMs > _loopStartMs &&
        currentVisualClock >= Duration(milliseconds: _loopEndMs)) {
      _syncTransportClock(Duration(milliseconds: _loopStartMs), playing: false);
    } else if (targetPlaying &&
        _playheadAtOrPastTransportEnd(currentVisualClock)) {
      _syncTransportClock(_playbackStartFallbackPoint(), playing: false);
    } else if (!targetPlaying) {
      _syncTransportClock(currentVisualClock, playing: false);
    }

    if (targetPlaying) {
      _desktopPlaybackStartPoint = _globalAudioClock;
      _transportPlayStartSyncGraceUntil =
          _transportUiStopwatch.elapsed + _kTransportPlayStartSyncGrace;
      _transportEndCheckGraceUntil =
          _transportUiStopwatch.elapsed + const Duration(milliseconds: 420);
      setState(() {
        _isPlaying = true;
        _syncTransportClock(_globalAudioClock, playing: true);
      });
      if (!(_transportTicker?.isActive ?? false)) {
        _transportTicker?.start();
      }
      _syncMeterPollingForVisibility();
      return;
    }

    _transportTicker?.stop();
    setState(() {
      _isPlaying = false;
      _syncTransportClock(currentVisualClock, playing: false);
    });
    _stopMeterPolling();
    if (_cloudAutoSyncDirty) {
      _scheduleCloudAutoSync(
        reason: 'playbackStopped',
        debounce: const Duration(seconds: 15),
      );
    }
  }

  Future<void> _drainTransportCommandQueue(StateSetter setLocalState) async {
    if (_transportNativeCommandInFlight) return;
    _transportNativeCommandInFlight = true;
    try {
      while (mounted) {
        final commandSerial = _transportCommandSerial;
        final targetPlaying = _transportDesiredPlaying;
        if (targetPlaying) {
          await _resumeAudio(setLocalState, commandSerial: commandSerial);
        } else {
          await _pauseAudio(setLocalState, commandSerial: commandSerial);
        }
        if (commandSerial == _transportCommandSerial) {
          return;
        }
      }
    } finally {
      _transportNativeCommandInFlight = false;
    }
  }

  Future<void> _resumeAudio(
    StateSetter setLocalState, {
    int? commandSerial,
  }) async {
    bool commandIsCurrent() =>
        commandSerial == null || commandSerial == _transportCommandSerial;
    if (!commandIsCurrent()) return;
    if (_loopEnabled &&
        _loopEndMs > _loopStartMs &&
        _globalAudioClock >= Duration(milliseconds: _loopEndMs)) {
      final loopStart = Duration(milliseconds: _loopStartMs);
      _syncTransportClock(loopStart, playing: false);
    } else if (_playheadAtOrPastTransportEnd(_globalAudioClock)) {
      _syncTransportClock(_playbackStartFallbackPoint(), playing: false);
    }
    if (!commandIsCurrent()) return;
    _desktopPlaybackStartPoint = _globalAudioClock;
    _transportPlayStartSyncGraceUntil =
        _transportUiStopwatch.elapsed + _kTransportPlayStartSyncGrace;
    _transportEndCheckGraceUntil =
        _transportUiStopwatch.elapsed + const Duration(milliseconds: 420);
    final resumeStartPoint = _globalAudioClock;
    await JuceAudioEngine.setTransportSeconds(
      resumeStartPoint.inMilliseconds / 1000.0,
    );
    await JuceAudioEngine.setMetronomeTransportMs(
      resumeStartPoint.inMilliseconds.toDouble(),
    );
    if (!commandIsCurrent()) return;
    final routeReady = await _ensurePlaybackRouteReady(
      reason: 'transportResume',
    );
    if (!routeReady) {
      _transportDesiredPlaying = false;
      _transportTicker?.stop();
      setState(() {
        _isPlaying = false;
        _syncTransportClock(resumeStartPoint, playing: false);
      });
      _stopMeterPolling();
      return;
    }
    if (!commandIsCurrent()) return;
    var playStarted = await JuceAudioEngine.play();
    if (!playStarted &&
        Platform.isMacOS &&
        _isBluetoothV2Session &&
        commandIsCurrent() &&
        !_v2AudioSessionInvalidated &&
        !_v2AudioSessionRecoveryInProgress) {
      final recoveryResult = await _audioRouteCoordinatorV2?.transitionIntent(
        AudioRouteIntentV2.playbackOnly,
      );
      if (recoveryResult != null && recoveryResult.succeeded) {
        JuceAudioEngine.acceptVerifiedAudioRouteTransitionV2(recoveryResult);
        if (commandIsCurrent()) {
          playStarted = await JuceAudioEngine.play();
        }
      }
    }
    if (!playStarted) {
      _transportDesiredPlaying = false;
      _transportTicker?.stop();
      setState(() {
        _isPlaying = false;
        _syncTransportClock(resumeStartPoint, playing: false);
      });
      _stopMeterPolling();
      if (mounted && commandIsCurrent()) {
        _showSmallNotice('Audio output is unavailable. Please try again.');
      }
      return;
    }
    if (!commandIsCurrent()) return;
    _syncTransportClock(_globalAudioClock, playing: true);

    if (!(_transportTicker?.isActive ?? false)) {
      _transportTicker?.start();
    }

    _syncMeterPollingForVisibility();

    // Android can occasionally miss the first transport start edge.
    await Future<void>.delayed(const Duration(milliseconds: 90));
    if (!_isPlaying || !commandIsCurrent()) return;
    await _pollTransportFromJuceIfNeeded(
      force: true,
      commandSerial: commandSerial,
    );
    if (!commandIsCurrent()) return;
    if (_transportRateSecPerSec <= 0.0) {
      final retryReady = await _ensurePlaybackRouteReady(
        reason: 'transportResumeRetry',
      );
      if (retryReady) {
        await JuceAudioEngine.play();
      }
    }
  }

  Future<void> _pauseAudio(
    StateSetter setLocalState, {
    int? commandSerial,
  }) async {
    bool commandIsCurrent() =>
        commandSerial == null || commandSerial == _transportCommandSerial;
    // On pause, cancel the timer, pause each track, and importantly, reset audioStarted.
    // _audioAutomationTimer?.cancel();
    _transportTicker?.stop();

    for (var track in _audioTracks) {
      // await track.player.pause();
      // maybe below deprecated?
      track.audioStarted =
          false; // Reset flag on pause so that resume triggers play.
    }
    await JuceAudioEngine.pause();
    if (!commandIsCurrent()) return;
    await _pollTransportFromJuceIfNeeded(
      force: true,
      commandSerial: commandSerial,
    );
    if (!commandIsCurrent()) return;
    _syncTransportClock(_globalAudioClock, playing: false);

    _stopMeterPolling();
  }

  Future<void> _restartAudio(StateSetter setLocalState) async {
    // Pause all tracks and seek them to their trimStart.
    // _audioAutomationTimer?.cancel();
    _transportTicker?.stop();

    Duration newStartPoint = Duration.zero;

    // Case of loop is enabled
    if (_loopEnabled) {
      newStartPoint = Duration(milliseconds: _loopStartMs);
    }

    for (final track in _audioTracks) {
      track.audioStarted = false;
      track.audioStartTimer?.cancel();
      track.currentPosition = newStartPoint;
    }
    await JuceAudioEngine.pause();
    await JuceAudioEngine.setTransportSeconds(
      newStartPoint.inMilliseconds / 1000.0,
    );

    // Reset the global audio clock.
    setState(() {
      _syncTransportClock(newStartPoint, playing: false);
      _isPlaying = false;
    });

    _stopMeterPolling();
  }

  Future<void> _wrapPlaybackToLoopStart() async {
    if (_loopWrapInFlight) return;
    _loopWrapInFlight = true;
    try {
      await _restartAudio(_safeAudioEditorStateSetter);
      if (!mounted) return;
      await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    } finally {
      _loopWrapInFlight = false;
    }
  }

  // Pause helper
  Future<void> _pausePlayback() async {
    _transportTicker?.stop();

    // Pause all audio tracks at precise position
    for (var track in _audioTracks) {
      track.audioStartTimer
          ?.cancel(); // NEED THIS IN CASE THERE WAS A TIMER STARTED
    }
    await JuceAudioEngine.pause();
    await _pollTransportFromJuceIfNeeded(force: true);
    _syncTransportClock(_globalAudioClock, playing: false);
    _stopMeterPolling();
  }

  double _resolveClipLoopPreviewEndMs(AudioTrack clip) {
    final startMs = clip.offset * 1000.0;
    final durationMs = _clipTimelineDurationSec(clip) * 1000.0;
    return startMs + math.max(1.0, durationMs);
  }

  Future<void> _muteClipsForLoopPreview(int audibleClipIndex) async {
    final futures = <Future<void>>[];
    for (int row = 0; row < _rowCount; row++) {
      futures.add(JuceAudioEngine.muteRow(row, false));
    }
    final clipMuteUpdates = <Map<String, dynamic>>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      final engineClipId = _audioTracks[i].engineClipId;
      if (engineClipId < 0) continue;
      clipMuteUpdates.add(<String, dynamic>{
        'clip': engineClipId,
        'muted': i != audibleClipIndex,
      });
    }
    if (clipMuteUpdates.isNotEmpty) {
      futures.add(
        JuceAudioEngine.updateClipTimelineBatch(
          clipMuteUpdates,
        ).then<void>((_) {}),
      );
    }
    if (futures.isNotEmpty) {
      await Future.wait(futures);
    }
  }

  Future<void> _clearClipLoopPreviewMutes() async {
    final clipMuteUpdates = <Map<String, dynamic>>[];
    for (final clip in _audioTracks) {
      if (clip.engineClipId >= 0) {
        clipMuteUpdates.add(<String, dynamic>{
          'clip': clip.engineClipId,
          'muted': false,
        });
      }
    }
    if (clipMuteUpdates.isNotEmpty) {
      await JuceAudioEngine.updateClipTimelineBatch(clipMuteUpdates);
    }
    await _recomputeAudibleState();
  }

  void _startClipLoopPreviewTimer() {
    _clipLoopPreviewTimer?.cancel();
    _clipLoopPreviewTimer = Timer.periodic(const Duration(milliseconds: 24), (
      _,
    ) async {
      final clipIndex = _clipLoopPreviewClipIndex;
      final startMs = _clipLoopPreviewStartMs;
      final endMs = _clipLoopPreviewEndMs;
      if (clipIndex == null || startMs == null || endMs == null) return;
      if (_globalAudioClock.inMilliseconds.toDouble() < endMs - 12.0) return;
      final start = Duration(milliseconds: startMs.round());
      await JuceAudioEngine.setTransportSeconds(startMs / 1000.0);
      await JuceAudioEngine.setMetronomeTransportMs(startMs);
      _syncTransportClock(start, playing: true);
    });
  }

  Future<void> _startClipLoopPreview(int clipIndex, double startMs) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.engineClipId < 0) return;

    if (_clipLoopPreviewClipIndex == null) {
      _clipLoopPreviewRestorePlaying = _isPlaying;
      _clipLoopPreviewRestoreClock = _globalAudioClock;
    }

    final clipStartMs = clip.offset * 1000.0;
    final clipEndMs = _resolveClipLoopPreviewEndMs(clip);
    final boundedStartMs = startMs
        .clamp(clipStartMs, clipEndMs - 1.0)
        .toDouble();

    _clipLoopPreviewClipIndex = clipIndex;
    _clipLoopPreviewStartMs = boundedStartMs;
    _clipLoopPreviewEndMs = clipEndMs;

    await _stopSampleAudition();
    await _muteClipsForLoopPreview(clipIndex);
    await JuceAudioEngine.setTransportSeconds(boundedStartMs / 1000.0);
    await JuceAudioEngine.setMetronomeTransportMs(boundedStartMs);
    await _ensurePlaybackRouteReady(reason: 'clipLoopPreview');
    await JuceAudioEngine.play();
    setState(() {
      _isPlaying = true;
      _syncTransportClock(
        Duration(milliseconds: boundedStartMs.round()),
        playing: true,
      );
    });
    if (!(_transportTicker?.isActive ?? false)) {
      _transportTicker?.start();
    }
    _syncMeterPollingForVisibility();
    _startClipLoopPreviewTimer();
  }

  Future<void> _seekClipLoopPreview(int clipIndex, double startMs) async {
    if (_clipLoopPreviewClipIndex != clipIndex) {
      await _startClipLoopPreview(clipIndex, startMs);
      return;
    }
    final clip = _audioTracks[clipIndex];
    final clipStartMs = clip.offset * 1000.0;
    final clipEndMs = _resolveClipLoopPreviewEndMs(clip);
    final boundedStartMs = startMs
        .clamp(clipStartMs, clipEndMs - 1.0)
        .toDouble();
    _clipLoopPreviewStartMs = boundedStartMs;
    _clipLoopPreviewEndMs = clipEndMs;
    await JuceAudioEngine.setTransportSeconds(boundedStartMs / 1000.0);
    await JuceAudioEngine.setMetronomeTransportMs(boundedStartMs);
    _syncTransportClock(
      Duration(milliseconds: boundedStartMs.round()),
      playing: true,
    );
  }

  Future<void> _stopClipLoopPreview() async {
    if (_clipLoopPreviewClipIndex == null) return;
    _clipLoopPreviewTimer?.cancel();
    _clipLoopPreviewTimer = null;
    final restorePlaying = _clipLoopPreviewRestorePlaying;
    final restoreClock = _clipLoopPreviewRestoreClock;
    _clipLoopPreviewClipIndex = null;
    _clipLoopPreviewStartMs = null;
    _clipLoopPreviewEndMs = null;
    await JuceAudioEngine.pause();
    await _clearClipLoopPreviewMutes();
    await JuceAudioEngine.setTransportSeconds(
      restoreClock.inMilliseconds / 1000.0,
    );
    await JuceAudioEngine.setMetronomeTransportMs(
      restoreClock.inMilliseconds.toDouble(),
    );
    if (restorePlaying) {
      await _ensurePlaybackRouteReady(reason: 'clipLoopPreviewRestore');
      await JuceAudioEngine.play();
      setState(() {
        _isPlaying = true;
        _syncTransportClock(restoreClock, playing: true);
      });
      if (!(_transportTicker?.isActive ?? false)) {
        _transportTicker?.start();
      }
      _syncMeterPollingForVisibility();
    } else {
      _transportTicker?.stop();
      setState(() {
        _isPlaying = false;
        _syncTransportClock(restoreClock, playing: false);
      });
      _stopMeterPolling();
    }
  }

  Future<_AudioExportSettings?> _showAudioExportSettingsSheet() async {
    final highQualityExport = _canUseSubscriptionCapability(
      SubscriptionCapability.highQualityExport,
      fallback: widget.isProEntitled ?? true,
    );
    final normalizedCurrentSettings = _normalizeAudioExportSettings(
      _audioExportSettings,
    );
    _ExportAudioFormat selectedFormat = normalizedCurrentSettings.format;
    int selectedSampleRate = normalizedCurrentSettings.sampleRate;
    int selectedWavBitDepth = _audioExportSettings.wavBitDepth;
    bool selectedWavDithering = _audioExportSettings.wavDithering;
    int selectedMp3Bitrate = _audioExportSettings.mp3BitrateKbps;
    _ExportMp3Mode selectedMp3Mode = _audioExportSettings.mp3Mode;
    int selectedMp3VbrQuality = _audioExportSettings.mp3VbrQuality;
    _ExportChannelMode selectedChannelMode = _audioExportSettings.channelMode;
    bool selectedNormalize = _audioExportSettings.normalize;
    double selectedNormalizeTargetDb = _audioExportSettings.normalizeTargetDb;
    _ExportResampleQuality selectedResampleQuality =
        _audioExportSettings.resampleQuality;
    bool showAdvanced = false;
    final nativeWavOnly = _desktopNativeWavOnlyExport;
    if (!highQualityExport &&
        !nativeWavOnly &&
        selectedFormat != _ExportAudioFormat.mp3) {
      selectedFormat = _ExportAudioFormat.mp3;
    }
    if (nativeWavOnly) {
      selectedFormat = _ExportAudioFormat.wav;
      selectedChannelMode = _ExportChannelMode.stereo;
      selectedNormalize = false;
      selectedResampleQuality = _ExportResampleQuality.best;
    }
    if (!highQualityExport) {
      selectedSampleRate = 44100;
      selectedWavBitDepth = 16;
      selectedChannelMode = _ExportChannelMode.stereo;
      selectedNormalize = false;
      selectedResampleQuality = _ExportResampleQuality.best;
    }
    selectedSampleRate = _normalizeExportSampleRateForFormat(
      selectedFormat,
      selectedSampleRate,
