  Future<String> _convertMixWithExportSettings({
    required String inputPath,
    required _AudioExportSettings settings,
  }) async {
    final tempDir = await getTemporaryDirectory();
    final outPath =
        '${tempDir.path}/audio_export_${DateTime.now().millisecondsSinceEpoch}.${settings.fileExtension}';

    final ffmpegCmd = AudioExportPlan.buildFfmpegArgs(
      inputPath: inputPath,
      outputPath: outPath,
      format: settings.format.name,
      sampleRate: settings.sampleRate,
      wavBitDepth: settings.wavBitDepth,
      wavDithering: settings.wavDithering,
      mp3BitrateKbps: settings.mp3BitrateKbps,
      mp3Mode: settings.mp3Mode.name,
      mp3VbrQuality: settings.mp3VbrQuality,
      channelMode: settings.channelMode.name,
      normalize: settings.normalize,
      normalizeTargetDb: settings.normalizeTargetDb,
      resampleQuality: settings.resampleQuality.name,
    );

    try {
      final Session session = await FFmpegKit.execute(ffmpegCmd.join(' '));
      final returnCode = await session.getReturnCode();
      if (!ReturnCode.isSuccess(returnCode)) {
        final logs = await session.getLogs();
        final logLines = logs
            .map((log) => log.getMessage())
            .whereType<String>()
            .where((line) => line.trim().isNotEmpty)
            .toList();
        final tail = logLines.length <= 6
            ? logLines.join('\n')
            : logLines.sublist(logLines.length - 6).join('\n');

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              tail.isNotEmpty
                  ? tail
                  : '${L10n.translate(context, "Export failed")} (RC: $returnCode)',
            ),
            duration: const Duration(seconds: 8),
          ),
        );
        return "";
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${L10n.translate(context, "Export error")}: ${e.toString().split('\n').first}',
          ),
        ),
      );
      return "";
    }

    final outFile = File(outPath);
    if (!await outFile.exists() || (await outFile.length()) < 1000) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            L10n.translate(
              context,
              'Export failed: Output file missing or too small.',
            ),
          ),
        ),
      );
      return "";
    }
    return outPath;
  }

  Future<int> _resolveRawRenderSampleRate(_AudioExportSettings settings) async {
    final fallback = settings.sampleRate.clamp(8000, 192000).toInt();
    final hostSampleRate = await JuceAudioEngine.getHostSampleRate();
    final hostRateInt = hostSampleRate.round();
    if (hostRateInt >= 8000 && hostRateInt <= 192000) {
      return hostRateInt;
    }
    return fallback;
  }

  bool _canUseNativeWavExport(_AudioExportSettings settings) {
    return AudioExportPlan.canUseNativeWavExport(
      format: settings.format.name,
      channelMode: settings.channelMode.name,
      normalize: settings.normalize,
    );
  }

  Future<T> _runProgressPulse<T>({
    required ValueChanged<double> onProgress,
    required double from,
    required double to,
    required Future<T> Function() task,
    Duration tick = const Duration(milliseconds: 320),
    double step = 0.02,
  }) async {
    if (to <= from) {
      onProgress(from);
      return task();
    }

    var progress = from;
    onProgress(progress);
    final timer = Timer.periodic(tick, (_) {
      progress = math.min(progress + step, to);
      onProgress(progress);
    });

    try {
      return await task();
    } finally {
      timer.cancel();
    }
  }

  Future<String> _runNativeExportMixWithProgress({
    required String outPath,
    required String clipSnapshotJson,
    required int sampleRate,
    required int wavBitDepth,
    required bool wavDithering,
    required int mp3BitrateKbps,
    required ValueChanged<double> onProgress,
    required double from,
    required double to,
  }) async {
    final span = math.max(0.0, to - from);
    onProgress(from);
    var pollingDone = false;

    Future<void> pollNativeProgress() async {
      while (!pollingDone) {
        try {
          final nativeProgress = await JuceAudioEngine.getExportProgress();
          final mapped =
              from + span * nativeProgress.clamp(0.0, 1.0).toDouble();
          onProgress(mapped);
        } catch (_) {
          // Keep export running even if progress polling is unavailable.
        }
        await Future.delayed(const Duration(milliseconds: 120));
      }
    }

    final poller = pollNativeProgress();
    try {
      return await JuceAudioEngine.exportMix(
        outPath,
        format: 'wav',
        sampleRate: sampleRate,
        wavBitDepth: wavBitDepth,
        wavDithering: wavDithering,
        mp3BitrateKbps: mp3BitrateKbps,
        clipSnapshotJson: clipSnapshotJson,
      );
    } finally {
      pollingDone = true;
      await poller;
      try {
        final nativeProgress = await JuceAudioEngine.getExportProgress();
        final mapped = from + span * nativeProgress.clamp(0.0, 1.0).toDouble();
        onProgress(mapped);
      } catch (_) {}
    }
  }

  Future<String> _exportAudioOnly(ValueChanged<double> onProgress) async {
    if (_audioTracks.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(L10n.translate(context, 'No audio tracks selected')),
        ), // TODO: FIX THIS WORDING
      );
      return "";
    }

    var reportedProgress = 0.0;
    void reportProgress(double value) {
      final clamped = value.clamp(0.0, 1.0).toDouble();
      if (clamped <= reportedProgress) return;
      reportedProgress = clamped;
      onProgress(clamped);
    }

    reportProgress(0.02);
    final settings = _normalizeAudioExportSettings(
      _activeAudioExportSettings ?? _audioExportSettings,
    );
    reportProgress(0.06);
    await _prepareNativeEngineStateForExport(reportProgress);
    await _refreshHostedInstrumentStatesForPersistence();
    final clipSnapshotJson = _buildNativeExportClipSnapshotJson();

    return _runWithAndroidEngineCriticalSection(() async {
      if (_desktopNativeWavOnlyExport) {
        final tempDir = await getTemporaryDirectory();
        reportProgress(0.24);
        final nativeOutPath =
            '${tempDir.path}/audio_export_${DateTime.now().millisecondsSinceEpoch}.wav';

        try {
          final exportedPath = await _runNativeExportMixWithProgress(
            outPath: nativeOutPath,
            clipSnapshotJson: clipSnapshotJson,
            sampleRate: settings.sampleRate,
            wavBitDepth: settings.wavBitDepth,
            wavDithering: settings.wavDithering,
            mp3BitrateKbps: settings.mp3BitrateKbps,
            onProgress: reportProgress,
            from: 0.24,
            to: 0.88,
          );
          reportProgress(0.96);
          if (exportedPath.isEmpty) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text(L10n.translate(context, "Export failed"))),
            );
            return "";
          }
          final outFile = File(exportedPath);
          if (!await outFile.exists() || (await outFile.length()) < 1000) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  L10n.translate(
                    context,
                    'Export failed: Output file missing or too small.',
                  ),
                ),
              ),
            );
            return "";
          }
          reportProgress(1.0);
          return exportedPath;
        } catch (e) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                '${L10n.translate(context, "Export error")}: ${e.toString().split('\n').first}',
              ),
              duration: const Duration(seconds: 5),
            ),
          );
          return "";
        }
      }

      reportProgress(0.10);
      final rawRenderSampleRate = await _resolveRawRenderSampleRate(settings);
      reportProgress(0.16);
      final tempDir = await getTemporaryDirectory();
      reportProgress(0.24);

      final useNativeWavDirect =
          _canUseNativeWavExport(settings) &&
          settings.sampleRate == rawRenderSampleRate;
      if (useNativeWavDirect) {
        final nativeOutPath =
            '${tempDir.path}/audio_export_${DateTime.now().millisecondsSinceEpoch}.wav';
        try {
          final exportedPath = await _runNativeExportMixWithProgress(
            outPath: nativeOutPath,
            clipSnapshotJson: clipSnapshotJson,
            sampleRate: settings.sampleRate,
            wavBitDepth: settings.wavBitDepth,
            wavDithering: settings.wavDithering,
            mp3BitrateKbps: settings.mp3BitrateKbps,
            onProgress: reportProgress,
            from: 0.24,
            to: 0.88,
          );
          reportProgress(0.96);

          if (exportedPath.isEmpty) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text(L10n.translate(context, "Export failed"))),
            );
            return "";
          }

          final outFile = File(exportedPath);
          if (!await outFile.exists() || (await outFile.length()) < 1000) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  L10n.translate(
                    context,
                    'Export failed: Output file missing or too small.',
                  ),
                ),
              ),
            );
            return "";
          }
          reportProgress(1.0);
          return exportedPath;
        } catch (e) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                '${L10n.translate(context, "Export error")}: ${e.toString().split('\n').first}',
              ),
              duration: const Duration(seconds: 5),
            ),
          );
          return "";
        }
      }

      final rawOutPath =
          '${tempDir.path}/audio_export_raw_${DateTime.now().millisecondsSinceEpoch}.wav';

      try {
        final exportedPath = await _runNativeExportMixWithProgress(
          outPath: rawOutPath,
          clipSnapshotJson: clipSnapshotJson,
          sampleRate: rawRenderSampleRate,
          wavBitDepth: 32,
          wavDithering: false,
          mp3BitrateKbps: settings.mp3BitrateKbps,
          onProgress: reportProgress,
          from: 0.24,
          to: 0.72,
        );
        reportProgress(0.80);

        if (exportedPath.isEmpty) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text(L10n.translate(context, "Export failed"))),
          );
          return "";
        }

        final outFile = File(exportedPath);
        if (!await outFile.exists() || (await outFile.length()) < 1000) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                L10n.translate(
                  context,
                  'Export failed: Output file missing or too small.',
                ),
              ),
            ),
          );
          return "";
        }

        final convertedPath = await _runProgressPulse<String>(
          onProgress: reportProgress,
          from: 0.84,
          to: 0.97,
          task: () => _convertMixWithExportSettings(
            inputPath: exportedPath,
            settings: settings,
          ),
        );
        reportProgress(1.0);
        return convertedPath;
      } catch (e) {
        print("Full export error: $e");
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              '${L10n.translate(context, "Export error")}: ${e.toString().split('\n').first}',
            ),
            duration: Duration(seconds: 5),
          ),
        );
      }
      return "";
    });
  }

