  Future<void> _pollMidiDeviceConnections({bool seedOnly = false}) async {
    if (!_liveMidiEventPlaybackSupported || _midiDevicePollBusy) return;
    _midiDevicePollBusy = true;
    try {
      final devices = await JuceAudioEngine.getConnectedMidiInputDevices();
      final nextById = <String, String>{};
      for (final device in devices) {
        final id = (device['id'] ?? '').trim();
        if (id.isEmpty) continue;
        final name = (device['name'] ?? id).trim();
        nextById[id] = name.isEmpty ? id : name;
      }

      if (_knownMidiDevicesById.isEmpty || seedOnly) {
        _knownMidiDevicesById = nextById;
        return;
      }

      final added = <String>[];
      final removed = <String>[];

      for (final entry in nextById.entries) {
        if (!_knownMidiDevicesById.containsKey(entry.key)) {
          added.add(entry.value);
        }
      }
      for (final entry in _knownMidiDevicesById.entries) {
        if (!nextById.containsKey(entry.key)) {
          removed.add(entry.value);
        }
      }

      _knownMidiDevicesById = nextById;
      if (!mounted) return;
      if (added.isEmpty && removed.isEmpty) return;

      final parts = <String>[];
      if (added.isNotEmpty) {
        parts.add('MIDI connected: ${added.join(', ')}');
      }
      if (removed.isNotEmpty) {
        parts.add('MIDI disconnected: ${removed.join(', ')}');
      }
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(parts.join(' | '))));
    } catch (_) {
      // Ignore transient bridge errors and keep polling.
    } finally {
      _midiDevicePollBusy = false;
    }
  }

  void _startMidiDeviceConnectionPolling() {
    _midiDevicePollTimer?.cancel();
    _knownMidiDevicesById = <String, String>{};
    unawaited(_pollMidiDeviceConnections(seedOnly: true));
    _midiDevicePollTimer = Timer.periodic(const Duration(seconds: 2), (
      _,
    ) async {
      await _pollMidiDeviceConnections();
    });
  }

  void _stopMidiDeviceConnectionPolling() {
    _midiDevicePollTimer?.cancel();
    _midiDevicePollTimer = null;
    _knownMidiDevicesById = <String, String>{};
  }

  int? _activeMidiRecordingClipIndex() {
    if (_showPianoRoll) {
      final openIndex = _activeMidiClipEditorIndex();
      if (openIndex >= 0 && openIndex < _audioTracks.length) {
        if (!_audioTracks[openIndex].isMidi) return null;
        return openIndex;
      }
      final selectedClip = _primarySelectedClipOrNull();
      if (selectedClip != null && selectedClip.isMidi) {
        final selectedIndex = _timelinePrimarySelectedClipIndex;
        if (selectedIndex >= 0 && selectedIndex < _audioTracks.length) {
          return selectedIndex;
        }
      }
      final armedEngineId = _armedMidiClipOrNull()?.engineClipId;
      if (armedEngineId == null || armedEngineId < 0) return null;
      final armedIndex = _clipIndexForEngineId(armedEngineId);
      if (armedIndex < 0 || armedIndex >= _audioTracks.length) return null;
      if (!_audioTracks[armedIndex].isMidi) return null;
      return armedIndex;
    }
    final activeEngineId = _armedMidiClipOrNull()?.engineClipId;
    if (activeEngineId == null || activeEngineId < 0) return null;
    final clipIndex = _clipIndexForEngineId(activeEngineId);
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return null;
    if (!_audioTracks[clipIndex].isMidi) return null;
    return clipIndex;
  }

  int _resolvedMidiRecordingClipIndex({AudioTrack? requestedClip}) {
    if (_isMidiClipRecording) {
      final recordingEngineId = _midiRecordingClipEngineId;
      if (recordingEngineId != null && recordingEngineId >= 0) {
        final byEngineId = _clipIndexForEngineId(recordingEngineId);
        if (byEngineId >= 0 &&
            byEngineId < _audioTracks.length &&
            _audioTracks[byEngineId].isMidi) {
          _midiRecordingClipIndex = byEngineId;
          return byEngineId;
        }
      }

      final storedIndex = _midiRecordingClipIndex;
      if (storedIndex != null &&
          storedIndex >= 0 &&
          storedIndex < _audioTracks.length &&
          _audioTracks[storedIndex].isMidi) {
        _midiRecordingClipEngineId = _audioTracks[storedIndex].engineClipId;
        return storedIndex;
      }
    }

    if (requestedClip != null) {
      final identicalIndex = _audioTracks.indexWhere(
        (track) => identical(track, requestedClip),
      );
      if (identicalIndex >= 0 &&
          identicalIndex < _audioTracks.length &&
          _audioTracks[identicalIndex].isMidi) {
        _midiRecordingClipIndex = identicalIndex;
        _midiRecordingClipEngineId = _audioTracks[identicalIndex].engineClipId;
        return identicalIndex;
      }

      final requestedEngineClipId = requestedClip.engineClipId;
      if (requestedEngineClipId >= 0) {
        final requestedIndex = _clipIndexForEngineId(requestedEngineClipId);
        if (requestedIndex >= 0 &&
            requestedIndex < _audioTracks.length &&
            _audioTracks[requestedIndex].isMidi) {
          _midiRecordingClipIndex = requestedIndex;
          _midiRecordingClipEngineId = requestedEngineClipId;
          return requestedIndex;
        }
      }
    }

    final storedIndex = _midiRecordingClipIndex;
    if (storedIndex != null &&
        storedIndex >= 0 &&
        storedIndex < _audioTracks.length &&
        _audioTracks[storedIndex].isMidi) {
      _midiRecordingClipEngineId = _audioTracks[storedIndex].engineClipId;
      return storedIndex;
    }

    final recordingEngineId = _midiRecordingClipEngineId;
    if (recordingEngineId != null && recordingEngineId >= 0) {
      final byEngineId = _clipIndexForEngineId(recordingEngineId);
      if (byEngineId >= 0 &&
          byEngineId < _audioTracks.length &&
          _audioTracks[byEngineId].isMidi) {
        _midiRecordingClipIndex = byEngineId;
        return byEngineId;
      }
    }

    final openIndex = _activeMidiRecordingClipIndex();
    if (openIndex != null) {
      _midiRecordingClipIndex = openIndex;
      _midiRecordingClipEngineId = _audioTracks[openIndex].engineClipId;
      return openIndex;
    }

    return -1;
  }

  String _midiRecordHeldKey(String source, int channel, int pitch) =>
      '$source:$channel:$pitch';

  String _liveMidiRecordEventKey(String type, int channel, int pitch) =>
      '$type:$channel:$pitch';

  void _suppressNextLiveMidiRecordEvent(String type, int channel, int pitch) {
    final key = _liveMidiRecordEventKey(type, channel, pitch);
    _suppressedLiveMidiRecordEvents.update(
      key,
      (count) => count + 1,
      ifAbsent: () => 1,
    );
  }

  bool _consumeSuppressedLiveMidiRecordEvent(
    String type,
    int channel,
    int pitch,
  ) {
    final key = _liveMidiRecordEventKey(type, channel, pitch);
    final count = _suppressedLiveMidiRecordEvents[key];
    if (count == null || count <= 0) return false;
    if (count <= 1) {
      _suppressedLiveMidiRecordEvents.remove(key);
    } else {
      _suppressedLiveMidiRecordEvents[key] = count - 1;
    }
    return true;
  }

  void _sendPianoRollLiveMidiEcho({
    required AudioTrack clip,
    required bool noteOn,
    required int channel,
    required int pitch,
    required double velocity,
  }) {
    if (Platform.isAndroid && noteOn && clip.engineClipId >= 0) {
      unawaited(
        JuceAudioEngine.playPreviewMidiNote(
          clip.engineClipId,
          pitch: pitch.clamp(0, 127),
          velocity: velocity.clamp(0.0, 1.0),
          durationMs: 260,
        ),
      );
      return;
    }
    if (!_midiRecordingLiveInputArmed ||
        !_liveMidiEventPlaybackSupported ||
        clip.engineClipId < 0) {
      return;
    }
    final type = noteOn ? 'noteOn' : 'noteOff';
    _suppressNextLiveMidiRecordEvent(type, channel, pitch);
    unawaited(
      JuceAudioEngine.sendLiveMidiInputEvent(
        noteOn: noteOn,
        channel: channel,
        pitch: pitch,
        velocity: velocity,
      ).then((sent) {
        if (!sent) {
          _consumeSuppressedLiveMidiRecordEvent(type, channel, pitch);
        }
      }),
    );
  }

  double _transportSecToClipSourceBeat(AudioTrack clip, double transportSec) {
    final sourceTempo = _resolvedClipSourceTempoBpm(clip);
    if (sourceTempo <= 0.0) return 0.0;
    final safeTransportSec = transportSec.isFinite
        ? transportSec
        : _globalAudioClock.inMilliseconds.toDouble() / 1000.0;
    final timelineSec = math.max(0.0, safeTransportSec - clip.offset);
    final sourceSec =
        (timelineSec * _tempoPlaybackRatioForEngine(clip)) +
        (clip.trimStart.inMilliseconds / 1000.0);
    return math.max(0.0, sourceSec * sourceTempo / 60.0);
  }

  double _midiRecordingTransportSeconds() {
    final baseSec = _globalAudioClock.inMilliseconds.toDouble() / 1000.0;
    if (!_isMidiClipRecording || !_isPlaying) return baseSec;
    final elapsedSinceSample =
        _transportUiStopwatch.elapsed - _lastTransportSampleElapsed;
    final extrapolatedSec =
        _lastTransportSampleSeconds +
        (elapsedSinceSample.inMicroseconds / 1e6) *
            math.max(1.0, _transportRateSecPerSec);
    if (!extrapolatedSec.isFinite) return baseSec;
    return math.max(baseSec, extrapolatedSec);
  }

  bool _applyMidiRecordNoteOn(
    AudioTrack clip, {
    required String source,
    required int channel,
    required int pitch,
    required double velocity,
    required double transportSec,
    double? startBeat,
  }) {
    final beat = startBeat != null && startBeat.isFinite
        ? math.max(0.0, startBeat)
        : _transportSecToClipSourceBeat(clip, transportSec);
    final key = _midiRecordHeldKey(source, channel, pitch);
    final note = MidiNote(
      id: 'live_rec_${clip.engineClipId}_${DateTime.now().microsecondsSinceEpoch}_${_nextMidiRecordNoteToken++}',
      pitch: pitch.clamp(0, 127).toInt(),
      startBeat: beat,
      lengthBeats: 0.0625,
      velocity: velocity.clamp(0.0, 1.0),
    );
    clip.midiNotes.add(note);
    (_midiHeldNotesByKey[key] ??= <MidiNote>[]).add(note);
    _midiRecordNoteWallStartById[note.id] = _transportUiStopwatch.elapsed;
    var changed = true;
    if (_extendMidiClipForBeat(clip, note.startBeat + note.lengthBeats)) {
      changed = true;
    }
    _midiRecordHasChanges = true;
    _lastMidiRecordTransportSec = math.max(
      _lastMidiRecordTransportSec,
      transportSec,
    );
    return changed;
  }

  double _midiRecordWallHoldLengthBeats(AudioTrack clip, MidiNote note) {
    final startedAt = _midiRecordNoteWallStartById[note.id];
    if (startedAt == null) return 0.0;
    final elapsed = _transportUiStopwatch.elapsed - startedAt;
    final elapsedSec = math.max(0.0, elapsed.inMicroseconds / 1e6);
    final sourceTempo = _resolvedClipSourceTempoBpm(clip);
    if (sourceTempo <= 0.0) return 0.0;
    final sourceTempoRatio = _tempoPlaybackRatioForEngine(clip);
    return elapsedSec * sourceTempoRatio * sourceTempo / 60.0;
  }

  bool _applyMidiRecordNoteOff(
    AudioTrack clip, {
    required String source,
    required int channel,
    required int pitch,
    required double transportSec,
  }) {
    final key = _midiRecordHeldKey(source, channel, pitch);
    final stack = _midiHeldNotesByKey[key];
    if (stack == null || stack.isEmpty) {
      _lastMidiRecordTransportSec = math.max(
        _lastMidiRecordTransportSec,
        transportSec,
      );
      return false;
    }
    final note = stack.removeLast();
    if (stack.isEmpty) {
      _midiHeldNotesByKey.remove(key);
    }
    final beat = _transportSecToClipSourceBeat(clip, transportSec);
    final nextLength = math.max(
      0.03125,
      math.max(
        beat - note.startBeat,
        _midiRecordWallHoldLengthBeats(clip, note),
      ),
    );
    _midiRecordNoteWallStartById.remove(note.id);
    var changed = false;
    if ((nextLength - note.lengthBeats).abs() > 0.00001) {
      note.lengthBeats = nextLength;
      changed = true;
    }
    if (_extendMidiClipForBeat(clip, note.startBeat + note.lengthBeats)) {
      changed = true;
    }
    if (changed) {
      _midiRecordHasChanges = true;
    }
    _lastMidiRecordTransportSec = math.max(
      _lastMidiRecordTransportSec,
      transportSec,
    );
    return changed;
  }

  Future<void> _handlePianoRollKeyboardNoteDown(
    AudioTrack requestedClip,
    int pitch,
    double velocity, {
    double? startBeat,
  }) async {
    final clipIndex = _resolvedMidiRecordingClipIndex(
      requestedClip: requestedClip,
    );
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return;

    if (!_isMidiClipRecording) {
      if (!PlatformCapabilities.current.isDesktop) {
        if (clip.engineClipId >= 0) {
          await _playPianoRollPreviewForClip(clip, pitch, velocity);
        }
        return;
      }
      if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
        final key = MidiPreviewNoteKey(
          clipId: clip.engineClipId,
          channel: 1,
          pitch: pitch.clamp(0, 127).toInt(),
        );
        final result = await _pianoRollPreviewNotes.noteOn(
          key: key,
          prepare: () => _ensureLiveMidiClipReadyForPreview(clip),
          sendNoteOn: () => JuceAudioEngine.sendLiveMidiInputEvent(
            noteOn: true,
            channel: key.channel,
            pitch: key.pitch,
            velocity: velocity,
          ),
          sendNoteOff: () => _sendPianoRollPreviewNoteOff(key),
        );
        if (result == MidiPreviewNoteOnResult.delivered ||
            result == MidiPreviewNoteOnResult.cancelled) {
          return;
        }
      }
      await _previewPianoRollNote(pitch, velocity);
      return;
    }

    _sendPianoRollLiveMidiEcho(
      clip: clip,
      noteOn: true,
      channel: 1,
      pitch: pitch,
      velocity: velocity,
    );

    final transportSec = _midiRecordingTransportSeconds();
    final changed = _applyMidiRecordNoteOn(
      clip,
      source: 'piano_roll',
      channel: 1,
      pitch: pitch,
      velocity: velocity,
      transportSec: transportSec,
      startBeat: startBeat,
    );
    if (!changed) return;

    _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
    if (mounted) {
      setState(() {});
    }
  }

  Future<void> _handlePianoRollKeyboardNoteUp(
    AudioTrack requestedClip,
    int pitch,
  ) async {
    final clipIndex = _resolvedMidiRecordingClipIndex(
      requestedClip: requestedClip,
    );
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return;

    if (!_isMidiClipRecording) {
      if (!PlatformCapabilities.current.isDesktop) {
        return;
      }
      if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
        final key = MidiPreviewNoteKey(
          clipId: clip.engineClipId,
          channel: 1,
          pitch: pitch.clamp(0, 127).toInt(),
        );
        if (_closingPianoRollPreview) {
          return;
        }
        await _pianoRollPreviewNotes.noteOff(
          key: key,
          sendNoteOff: () => _sendPianoRollPreviewNoteOff(key),
        );
      }
      return;
    }

    _sendPianoRollLiveMidiEcho(
      clip: clip,
      noteOn: false,
      channel: 1,
      pitch: pitch,
      velocity: 0.0,
    );

    final transportSec = _midiRecordingTransportSeconds();
    final changed = _applyMidiRecordNoteOff(
      clip,
      source: 'piano_roll',
      channel: 1,
      pitch: pitch,
      transportSec: transportSec,
    );
    if (!changed) return;

    _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
    if (mounted) {
      setState(() {});
    }
  }

  Future<bool> _sendPianoRollPreviewNoteOff(MidiPreviewNoteKey key) async {
    final targetReady = await _setLiveMidiInputTargetClipIfNeeded(
      key.clipId,
      clearPendingEvents: false,
    );
    if (!targetReady) return false;
    return JuceAudioEngine.sendLiveMidiInputEvent(
      noteOn: false,
      channel: key.channel,
      pitch: key.pitch,
      velocity: 0.0,
    );
  }

  Future<void> _releaseAllPianoRollPreviewNotes() => _pianoRollPreviewNotes
      .releaseAll(sendNoteOff: _sendPianoRollPreviewNoteOff);

  bool _extendMidiClipForBeat(AudioTrack clip, double endBeat) {
    final sourceTempo = _resolvedClipSourceTempoBpm(clip);
    if (sourceTempo <= 0.0) return false;

    final trimStartSec = clip.trimStart.inMilliseconds / 1000.0;
    final noteEndSourceSec = math.max(0.0, endBeat) * 60.0 / sourceTempo;
    final requiredRawSec = math.max(0.001, noteEndSourceSec - trimStartSec);
    final currentRawSec =
        (clip.trimEnd - clip.trimStart).inMilliseconds / 1000.0;
    if (requiredRawSec <= currentRawSec + 0.0005) return false;

    clip.trimEnd =
        clip.trimStart +
        Duration(milliseconds: (requiredRawSec * 1000.0).ceil());
    return true;
  }

  bool _updateHeldMidiRecordNotes(
    AudioTrack clip,
    double currentBeat, {
    bool closeAll = false,
  }) {
    bool changed = false;
    final keys = _midiHeldNotesByKey.keys.toList(growable: false);
    for (final key in keys) {
      final stack = _midiHeldNotesByKey[key];
      if (stack == null || stack.isEmpty) {
        _midiHeldNotesByKey.remove(key);
        continue;
      }
      for (final note in stack) {
        final nextLength = math.max(
          0.03125,
          math.max(
            currentBeat - note.startBeat,
            _midiRecordWallHoldLengthBeats(clip, note),
          ),
        );
        if ((nextLength - note.lengthBeats).abs() > 0.00001) {
          note.lengthBeats = nextLength;
          changed = true;
        }
        if (_extendMidiClipForBeat(clip, note.startBeat + note.lengthBeats)) {
          changed = true;
        }
      }
      if (closeAll) {
        for (final note in stack) {
          _midiRecordNoteWallStartById.remove(note.id);
        }
        stack.clear();
        _midiHeldNotesByKey.remove(key);
      }
    }
    return changed;
  }

  bool _refreshHeldMidiRecordNotesFromClock({bool closeHeldNotes = false}) {
    if (!_isMidiClipRecording) return false;
    if (_midiHeldNotesByKey.isEmpty) return false;
    final clipIndex = _resolvedMidiRecordingClipIndex();
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return false;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return false;

    final transportSec = _midiRecordingTransportSeconds();
    _lastMidiRecordTransportSec = math.max(
      _lastMidiRecordTransportSec,
      transportSec,
    );
    final currentBeat = _transportSecToClipSourceBeat(clip, transportSec);
    final changed = _updateHeldMidiRecordNotes(
      clip,
      currentBeat,
      closeAll: closeHeldNotes,
    );
    if (changed) {
      _midiRecordHasChanges = true;
      _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
      if (mounted) {
        setState(() {});
      }
    }
    return changed;
  }

  Future<void> _drainMidiInputEventsForRecording({
    bool closeHeldNotes = false,
  }) async {
    if (!_isMidiClipRecording || !_midiRecordingLiveInputArmed) return;
    if (_midiInputDrainBusy) {
      if (!closeHeldNotes) return;
      for (int attempt = 0; attempt < 8 && _midiInputDrainBusy; attempt++) {
        await Future<void>.delayed(const Duration(milliseconds: 8));
      }
      if (_midiInputDrainBusy) return;
    }
    final clipIndex = _resolvedMidiRecordingClipIndex();
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return;

    _midiInputDrainBusy = true;
    try {
      final events = await JuceAudioEngine.consumeLiveMidiInputEvents();
      bool changed = false;
      double latestTransportSec = _lastMidiRecordTransportSec;

      for (final event in events) {
        final clipId = (event['clip'] as num?)?.toInt() ?? -1;
        if (clipId != clip.engineClipId) continue;

        final type = (event['type'] as String?) ?? '';
        final noteOn = type == 'noteOn';
        final noteOff = type == 'noteOff';
        if (!noteOn && !noteOff) continue;

        final pitch = (((event['pitch'] as num?)?.toInt() ?? 60).clamp(
          0,
          127,
        )).toInt();
        final channel = (((event['channel'] as num?)?.toInt() ?? 1).clamp(
          1,
          16,
        )).toInt();
        final velocity = ((event['velocity'] as num?)?.toDouble() ?? 1.0).clamp(
          0.0,
          1.0,
        );
        final transportSec =
            (event['transportSec'] as num?)?.toDouble() ??
            _midiRecordingTransportSeconds();
        latestTransportSec = math.max(latestTransportSec, transportSec);

        if (noteOn) {
          if (_consumeSuppressedLiveMidiRecordEvent('noteOn', channel, pitch)) {
            continue;
          }
          changed =
              _applyMidiRecordNoteOn(
                clip,
                source: 'external',
                channel: channel,
                pitch: pitch,
                velocity: velocity,
                transportSec: transportSec,
              ) ||
              changed;
          continue;
        }

        if (_consumeSuppressedLiveMidiRecordEvent('noteOff', channel, pitch)) {
          continue;
        }
        changed =
            _applyMidiRecordNoteOff(
              clip,
              source: 'external',
              channel: channel,
              pitch: pitch,
              transportSec: transportSec,
            ) ||
            changed;
      }

      final fallbackTransportSec =
          _globalAudioClock.inMilliseconds.toDouble() / 1000.0;
      final currentTransportSec = math.max(
        latestTransportSec,
        fallbackTransportSec,
      );
      _lastMidiRecordTransportSec = currentTransportSec;
      final currentBeat = _transportSecToClipSourceBeat(
        clip,
        currentTransportSec,
      );
      if (_updateHeldMidiRecordNotes(
        clip,
        currentBeat,
        closeAll: closeHeldNotes,
      )) {
        changed = true;
        _midiRecordHasChanges = true;
      }

      if (changed) {
        _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
        if (mounted) {
          setState(() {});
        }
      }
    } finally {
      _midiInputDrainBusy = false;
    }
  }

  Future<bool> _armLiveMidiInputTargetForRecording(
    AudioTrack clip,
    int clipIndex,
  ) async {
    if (!_liveMidiEventPlaybackSupported || clip.engineClipId < 0) {
      return false;
    }

    var targetOk = await _setLiveMidiInputTargetClipIfNeeded(
      clip.engineClipId,
      force: true,
    );
    if (targetOk) return true;

    _lastLiveMidiInputTargetClipId = -2;
    final reloaded = await _reloadMidiTrackLive(clip);
    if (reloaded) {
      await _syncClipTimingToEngine(clipIndex);
      await _syncClipMixToEngine(clip);
    }

    targetOk = await _setLiveMidiInputTargetClipIfNeeded(
      clip.engineClipId,
      force: true,
    );
    if (!targetOk) {
      debugPrint(
        'Unable to arm live MIDI input target for clip ${clip.engineClipId}; '
        'continuing with piano-roll input recording only.',
      );
    }
    return targetOk;
  }

  Future<int?> _ensureSelectedInstrumentLaneMidiRecordingClip() async {
    final row = resolveSelectedInstrumentLaneRecordingRow(
      rows: _rows,
      selectedRow: _selectedRow,
    );
    if (row == null) return null;

    final lane = _rows[row];
    final instrumentId = lane.instrumentId.trim();
    if (instrumentId.isEmpty) {
      _showSmallNotice('This instrument lane is missing its instrument.');
      return null;
    }

    final beforeCount = _audioTracks.length;
    await _undoManager.execute(
      AddMidiClipAction(
        addMidiClip:
            ({
              required String instrumentId,
              required String instrumentName,
              required Map<String, double> instrumentParams,
              required List<MidiNote> midiNotes,
              required int row,
              required double timeMs,
              Duration? trimEndRequested,
            }) => _addMidiTrack(
              instrumentId: instrumentId,
              instrumentName: instrumentName,
              instrumentParams: instrumentParams,
              midiNotes: midiNotes,
              row: row,
              timeMs: timeMs,
              trimEndRequested: trimEndRequested,
            ),
        tracks: _audioTracks,
        restoreTrack: _addClipFromUndoPayload,
        instrumentId: instrumentId,
        instrumentName: lane.instrumentName.isEmpty
            ? _instrumentNameFromId(instrumentId)
            : lane.instrumentName,
        instrumentParams: Map<String, double>.from(lane.instrumentParams),
        midiNotes: const <MidiNote>[],
        row: row,
        timeMs: _globalAudioClock.inMilliseconds.toDouble(),
        onRemove: _syncRemovedClipFadesAfterUndo,
      ),
    );
    if (_audioTracks.length <= beforeCount) return null;

    final clipIndex = _audioTracks.length - 1;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return null;
    setState(() {
      _selectedRow = row;
      _timelineSelectedClipIndices = <int>[clipIndex];
      _timelinePrimarySelectedClipIndex = clipIndex;
      _activeMidiClipEngineId = clip.engineClipId;
      _activeMidiClipIndex = clipIndex;
    });
    if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
      unawaited(_syncLiveMidiInputTargetClip());
    }
    return clipIndex;
  }

  Future<void> _startMidiClipRecording(int clipIndex) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;

    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return;

    _stopRecordingPeakPolling(clearSamples: true);
    setState(() {
      _activeMidiClipEngineId = clip.engineClipId;
      _activeMidiClipIndex = clipIndex;
      _selectedRow = clip.rowIndex.clamp(0, math.max(0, _rowCount - 1)).toInt();
      _recordingFilePath = null;
      _isRecording = true;
      _isMidiClipRecording = true;
      _midiRecordingClipEngineId = clip.engineClipId;
      _midiRecordingClipIndex = clipIndex;
      _midiRecordingLiveInputArmed = false;
    });

    if (_loopEnabled) {
      await _restartAudio(_safeAudioEditorStateSetter);
    }

    _recordingStartMs = _globalAudioClock.inMilliseconds.toDouble();
    if (!_isPlaying) {
      await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    }

    final liveTargetOk = await _armLiveMidiInputTargetForRecording(
      clip,
      clipIndex,
    );
    _midiHeldNotesByKey.clear();
    _midiRecordNoteWallStartById.clear();
    _suppressedLiveMidiRecordEvents.clear();
    _nextMidiRecordNoteToken = 0;
    _lastMidiRecordTransportSec =
        _globalAudioClock.inMilliseconds.toDouble() / 1000.0;
    _midiRecordHasChanges = false;
    _midiInputPollTimer?.cancel();
    _midiInputPollTimer = liveTargetOk
        ? Timer.periodic(const Duration(milliseconds: 40), (_) {
            unawaited(_drainMidiInputEventsForRecording());
          })
        : null;
    _midiHeldNoteRefreshTimer?.cancel();
    _midiHeldNoteRefreshTimer = Timer.periodic(
      const Duration(milliseconds: 33),
      (_) {
        _refreshHeldMidiRecordNotesFromClock();
      },
    );

    if (mounted && _isMidiClipRecording) {
      setState(() {
        _midiRecordingLiveInputArmed = liveTargetOk;
      });
    }
  }

  Future<void> _stopMidiClipRecording({bool keepPlaying = true}) async {
    _stopRecordingPeakPolling(clearSamples: true);
    _midiInputPollTimer?.cancel();
    _midiInputPollTimer = null;
    _midiHeldNoteRefreshTimer?.cancel();
    _midiHeldNoteRefreshTimer = null;

    _refreshHeldMidiRecordNotesFromClock(closeHeldNotes: true);
    await _drainMidiInputEventsForRecording(closeHeldNotes: true);

    final clipIndex = _resolvedMidiRecordingClipIndex();
    final hadMidiChanges = _midiRecordHasChanges;
    if (clipIndex >= 0 && clipIndex < _audioTracks.length) {
      final clip = _audioTracks[clipIndex];
      if (clip.isMidi && _midiRecordHasChanges) {
        clip.midiNotes.sort((a, b) {
          final timeCmp = a.startBeat.compareTo(b.startBeat);
          if (timeCmp != 0) return timeCmp;
          return a.pitch.compareTo(b.pitch);
        });
        final updatedLive = await _updateMidiClipEventsLive(clip);
        if (updatedLive) {
          await _syncClipTimingToEngine(clipIndex);
          await _syncClipMixToEngine(clip);
          _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
        } else {
          await _reloadMidiTrackLive(clip);
        }
      }
    }

    if (_liveMidiEventPlaybackSupported) {
      final previewClip = _armedMidiClipOrNull()?.engineClipId ?? -1;
      await _setLiveMidiInputTargetClipIfNeeded(previewClip, force: true);
    }

    _midiHeldNotesByKey.clear();
    _midiRecordNoteWallStartById.clear();
    _suppressedLiveMidiRecordEvents.clear();
    _midiRecordingClipEngineId = null;
    _midiRecordingClipIndex = null;
    _midiRecordingLiveInputArmed = false;
    _isMidiClipRecording = false;
    _midiRecordHasChanges = false;
    _lastMidiRecordTransportSec = 0.0;

    setState(() {
      _isRecording = false;
      _recordingFilePath = null;
    });

    if (!keepPlaying && _isPlaying) {
      await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    }
    if (hadMidiChanges) {
      _scheduleProjectAutosave();
    }
  }

  Future<void> _startRecordingJuce() async {
    if (_isBluetoothV2Session) {
      if (!_supportsV2AudioRecording) {
        _showSmallNotice(
          'Recording is unavailable for the current audio route.',
        );
        return;
      }
      if (_selectedRow < 0 ||
          _selectedRow >= _rows.length ||
          _rows[_selectedRow].kind == TimelineRowKind.instrument) {
        _showSmallNotice('Select an audio row to record.');
        return;
      }
      await _startAudioRecordingJuce();
      return;
    }
    final midiClipIndex =
        _activeMidiRecordingClipIndex() ??
        await _ensureSelectedInstrumentLaneMidiRecordingClip();
    if (midiClipIndex != null) {
      await _startMidiClipRecording(midiClipIndex);
      return;
    }
    await _startAudioRecordingJuce();
  }

  Future<void> _letRecordingVisualStatePaint() async {
    if (!mounted) return;
    try {
      await WidgetsBinding.instance.endOfFrame;
    } catch (_) {
      await Future<void>.delayed(Duration.zero);
    }
  }

  void _stopRecordingPeakPolling({required bool clearSamples}) {
    _recordingPeakTimer?.cancel();
    _recordingPeakTimer = null;
    ++_recordingPeakGeneration;
    _recordingPeakPollBusy = false;
    if (clearSamples) {
      _recordingPeaks.clear();
      _recordingPeakTimesMs.clear();
    }
  }

  void _startRecordingPeakPolling() {
    _stopRecordingPeakPolling(clearSamples: true);
    final peakGeneration = _recordingPeakGeneration;
    _recordingPeakTimer = Timer.periodic(const Duration(milliseconds: 50), (
      _,
    ) async {
      if (!_isRecording ||
          peakGeneration != _recordingPeakGeneration ||
          _recordingPeakPollBusy) {
        return;
      }

      _recordingPeakPollBusy = true;
      try {
        final peak = await JuceAudioEngine.getRecordingPeak();
        if (!mounted ||
            !_isRecording ||
            peakGeneration != _recordingPeakGeneration) {
          return;
        }
        final acceptedElapsedMs = math.max(
          0.0,
          _globalAudioClock.inMicroseconds.toDouble() / 1000.0 -
              _recordingStartMs,
        );
        final elapsedMs = _recordingPeakTimesMs.isEmpty
            ? acceptedElapsedMs
            : math.max(_recordingPeakTimesMs.last, acceptedElapsedMs);
        setState(() {
          _recordingPeaks.add(peak.clamp(0.0, 1.0).toDouble());
          _recordingPeakTimesMs.add(elapsedMs);
        });
      } finally {
        if (peakGeneration == _recordingPeakGeneration) {
          _recordingPeakPollBusy = false;
        }
      }
    });
  }

  Future<bool> _prepareAudioRecordingStartPreflight() async {
    var v2IntentOperation = AudioRouteIntentOperationV2.standard;
    if (_isBluetoothV2Session && Platform.isMacOS) {
      v2IntentOperation = AudioRouteIntentOperationV2.systemSelectedRecording;
    }
    if (_isBluetoothV2Session && Platform.isAndroid) {
      final coordinator = _audioRouteCoordinatorV2;
      if (_v2AudioSessionInvalidated ||
          coordinator == null ||
          coordinator.state != AudioRouteCoordinatorStateV2.stable ||
          coordinator.intent != AudioRouteIntentV2.playbackOnly) {
        _showSmallNotice('Audio output is changing. Please wait.');
        return false;
      }
      final source = await JuceAudioEngine.getAudioRouteSnapshotV2();
      final sourceOutput = source.outputs.length == 1
          ? source.outputs.single
          : null;
      if (source.captureConsistency != AudioRouteCaptureConsistencyV2.stable ||
          source.intent != AudioRouteIntentV2.playbackOnly ||
          source.inputs.isNotEmpty ||
          source.juce.activeInputChannels != 0 ||
          sourceOutput == null) {
        _showSmallNotice(
          'Recording is unavailable for the current Android audio route.',
        );
        return false;
      }
      switch (sourceOutput.normalizedKind) {
        case AudioRouteKindV2.builtIn:
          break;
        case AudioRouteKindV2.bluetoothMedia:
          v2IntentOperation =
              AudioRouteIntentOperationV2.systemSelectedRecording;
          break;
        default:
          _showSmallNotice(
            'Recording is unavailable for the current Android audio route.',
          );
          return false;
      }
    }
    if (!await _ensureMicrophonePermissionForRecording()) {
      return false;
    }

    if (_isBluetoothV2Session) {
      if (!_supportsV2AudioRecording || _v2AudioSessionInvalidated) {
        return false;
      }
      final coordinator = _audioRouteCoordinatorV2;
      if (coordinator == null ||
          coordinator.state != AudioRouteCoordinatorStateV2.stable ||
          coordinator.intent != AudioRouteIntentV2.playbackOnly) {
        _showSmallNotice(
          coordinator?.state == AudioRouteCoordinatorStateV2.failed
              ? 'Audio output is unavailable. Reopen the audio editor.'
              : 'Audio output is changing. Please wait.',
        );
        return false;
      }
      if (_isPlaying) {
        _transportDesiredPlaying = false;
        ++_transportCommandSerial;
        await _pausePlayback();
        if (!mounted) return false;
        setState(() {
          _isPlaying = false;
          _syncTransportClock(_globalAudioClock, playing: false);
        });
      }
      final result = await coordinator.transitionIntent(
        AudioRouteIntentV2.preparingRecording,
        operation: Platform.isIOS || Platform.isMacOS
            ? AudioRouteIntentOperationV2.systemSelectedRecording
            : v2IntentOperation,
      );
      if (_recordStartCancelRequested) return false;
      if (!result.succeeded) {
        if (mounted) {
          final macRouteRemoved =
              Platform.isMacOS &&
              result.snapshot.duplexProbe?.validationStage ==
                  'physicalRouteInvalidation';
          if (!macRouteRemoved) {
            _showSmallNotice(
              Platform.isIOS
                  ? 'Recording is unavailable for the current iOS audio route.'
                  : Platform.isMacOS
                  ? 'Recording is unavailable for the current macOS audio route.'
                  : v2IntentOperation ==
                        AudioRouteIntentOperationV2.systemSelectedRecording
                  ? 'Recording is unavailable for the current Android audio route.'
                  : result.diagnosticCode == 'bluetooth_input_forbidden'
                  ? 'Bluetooth microphones are not supported. Use the built-in device microphone.'
                  : 'Recording with the built-in device microphone is unavailable for the current output.',
            );
          }
        }
        return false;
      }
      JuceAudioEngine.acceptVerifiedAudioRouteTransitionV2(result);
      _selectedChannelStart = 0;
      _selectedChannelCount = 1;
      final verifiedInput = result.snapshot.inputs.length == 1
          ? result.snapshot.inputs.single
          : null;
      final verifiedOutput = result.snapshot.outputs.length == 1
          ? result.snapshot.outputs.single
          : null;
      final usingBluetoothDuplex =
          verifiedInput?.normalizedKind == AudioRouteKindV2.bluetoothDuplex &&
          verifiedOutput?.normalizedKind == AudioRouteKindV2.bluetoothDuplex;
      if (usingBluetoothDuplex && !_bluetoothRecordingQualityNoticeShown) {
        _bluetoothRecordingQualityNoticeShown = true;
        _showSmallNotice(
          'Bluetooth microphone in use. Playback quality is reduced while recording.',
        );
      }
      return true;
    }

    if (Platform.isAndroid || Platform.isIOS) {
      if (_inputDevices.isEmpty && !_loadingDevices) {
        await _loadInputDevicesFromJuce(scheduleRecordingPrewarm: true);
      } else if (!_inputDeviceCacheIsFresh() && !_loadingDevices) {
        unawaited(_loadInputDevicesFromJuce(scheduleRecordingPrewarm: true));
      }

      final routeKnown = _audioRouteInfoIsKnown(_audioRouteInfo);
      if (!routeKnown) {
        await _refreshAudioRouteInfo();
      } else if (!_audioRouteInfoCacheIsFresh()) {
        if (Platform.isIOS) {
          await _refreshAudioRouteInfo();
        } else {
          unawaited(_refreshAudioRouteInfo());
        }
      }

      if (!await _confirmBluetoothMicMode(_audioRouteInfo)) {
        return false;
      }
    }

    if (Platform.isMacOS) {
      if (!await _ensureMacNonBluetoothRecordingInput(
        reason: 'recordStart',
        notify: true,
      )) {
        return false;
      }

      final selectedDeviceName = (_selectedDevice ?? '').trim();
      if (selectedDeviceName.isNotEmpty) {
        final currentInputName = (await JuceAudioEngine.getCurrentDeviceName())
            .trim();
        if (currentInputName != selectedDeviceName) {
          final ok = await JuceAudioEngine.selectInputDevice(
            selectedDeviceName,
          );
          if (!ok) {
            if (mounted) {
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(
                    L10n.translate(
                      context,
                      'Selected input device is not available.',
                    ),
                  ),
                ),
              );
            }
            return false;
          }
          final channels = await JuceAudioEngine.getNumInputChannels();
          if (!mounted) return false;
          setState(() {
            _numInputChannels = channels;
            _normalizeInputChannelSelection();
          });
          _lastPreparedRecordingDevice = null;
          _lastPreparedRecordingInputOpenChannels = null;
        }
      }
    }

    // Background prewarm keeps the common path fast. Native record start still
    // validates and opens inputs, so avoid doing a second synchronous input
    // reopen here on the tap path.
    await _applyCurrentLiveMonitoringPolicy(info: _audioRouteInfo, force: true);
    return true;
  }

  Future<void> _startAudioRecordingJuce() async {
    if (_recordTransitionInFlight) return;
    _recordTransitionInFlight = true;
    _recordStartCancelRequested = false;
    try {
      _midiInputPollTimer?.cancel();
      _midiInputPollTimer = null;
      _midiHeldNotesByKey.clear();
      _midiRecordNoteWallStartById.clear();
      _suppressedLiveMidiRecordEvents.clear();

      // 1) Require a selected row
      if (_rowCount <= 0 || _selectedRow < 0 || _selectedRow >= _rowCount) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              L10n.translate(context, 'Select a track to record on first.'),
            ),
          ),
        );
        return;
      }

      if (mounted) {
        setState(() {
          _recordStartVisualPending = true;
        });
      }
      await _letRecordingVisualStatePaint();
      if (!mounted || _recordStartCancelRequested) return;

      if (_loopEnabled) {
        await _restartAudio(_safeAudioEditorStateSetter);
      }
      if (_recordStartCancelRequested) return;

      // V2 input preparation can pause for a route transition, so its take
      // starts from the settled position. Other recording paths retain their
      // established preflight timing.
      final captureStartAfterRoutePreparation =
          _isBluetoothV2Session && _supportsV2AudioRecording;
      if (!captureStartAfterRoutePreparation) {
        _recordingStartMs = _globalAudioClock.inMilliseconds.toDouble();
      }

      if (!await _prepareAudioRecordingStartPreflight()) {
        return;
      }
      if (_recordStartCancelRequested) return;
      if (captureStartAfterRoutePreparation) {
        _recordingStartMs = _globalAudioClock.inMilliseconds.toDouble();
      }

      final startPlaybackAfterRecorder =
          Platform.isIOS || _isBluetoothV2Session;

      // Legacy Android retains its established transport-first order. V2 starts
      // capture only after the prepared route is verified.
      if (!startPlaybackAfterRecorder && !_isPlaying) {
        await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
      }
      if (_recordStartCancelRequested) {
        if (_isPlaying) {
          await _pausePlayback();
          if (mounted) {
            setState(() {
              _isPlaying = false;
            });
          }
        }
        return;
      }

      // 4) Prepare file path (CHANGE → WAV)
      final audioDir = ProjectManager.audioDir(_projectDir);
      if (!await audioDir.exists()) await audioDir.create(recursive: true);
      final filePath = p.join(
        audioDir.path,
        'mixroom_rec_${DateTime.now().millisecondsSinceEpoch}.wav',
      );
      _claimPendingUnpublishedRecordingPath(filePath);

      // 5) Arm the native recorder.
      final ok = await JuceAudioEngine.startRecording(
        filePath,
        _isBluetoothV2Session ? 0 : _selectedChannelStart,
        _isBluetoothV2Session ? 1 : _selectedChannelCount,
      );

      if (!ok) {
        await _discardPendingUnpublishedRecordingFile(expectedPath: filePath);
        if (_isBluetoothV2Session && _supportsV2AudioRecording) {
          await _restoreV2PlaybackOnlyAfterRecording();
        }
        _liveInputMonitoringEffective = null;
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                L10n.translate(context, 'Failed to start recording'),
              ),
            ),
          );
        }
        return;
      }
      if (_isBluetoothV2Session && _supportsV2AudioRecording) {
        final coordinator = _audioRouteCoordinatorV2;
        final recordingResult = await coordinator?.transitionIntent(
          AudioRouteIntentV2.recording,
        );
        if (recordingResult == null || !recordingResult.succeeded) {
          await JuceAudioEngine.stopRecording();
          await _discardPendingUnpublishedRecordingFile(expectedPath: filePath);
          await _restoreV2PlaybackOnlyAfterRecording();
          if (mounted) {
            _showSmallNotice('Failed to verify the recording input.');
          }
          return;
        }
        JuceAudioEngine.acceptVerifiedAudioRouteTransitionV2(recordingResult);
      }
      if (_recordStartCancelRequested) {
        await JuceAudioEngine.stopRecording();
        await _discardPendingUnpublishedRecordingFile(expectedPath: filePath);
        _lastPreparedRecordingDevice = null;
        _lastPreparedRecordingInputOpenChannels = null;
        if (_isPlaying) {
          await _pausePlayback();
          if (mounted) {
            setState(() {
              _isPlaying = false;
            });
          }
        }
        return;
      }

      // 6) iOS starts playback after the recorder is armed so route/input state is
      // not invalidated between arm and first capture.
      if (startPlaybackAfterRecorder && !_isPlaying) {
        await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
      }
      if (startPlaybackAfterRecorder && !_isPlaying) {
        await JuceAudioEngine.stopRecording();
        await _discardPendingUnpublishedRecordingFile(expectedPath: filePath);
        if (_isBluetoothV2Session && _supportsV2AudioRecording) {
          await _restoreV2PlaybackOnlyAfterRecording();
        }
        if (mounted) {
          _showSmallNotice(
            'Recording stopped because playback could not start.',
          );
        }
        return;
      }
      if (_recordStartCancelRequested) {
        await JuceAudioEngine.stopRecording();
        await _discardPendingUnpublishedRecordingFile(expectedPath: filePath);
        _lastPreparedRecordingDevice = null;
        _lastPreparedRecordingInputOpenChannels = null;
        if (_isPlaying) {
          await _pausePlayback();
          if (mounted) {
            setState(() {
              _isPlaying = false;
            });
          }
        }
        return;
      }

      if (!mounted) {
        await JuceAudioEngine.stopRecording();
        await _discardPendingUnpublishedRecordingFile(expectedPath: filePath);
        return;
      }

      // 7) UI state (UNCHANGED)
      setState(() {
        _recordingFilePath = filePath;
        _isRecording = true;
        _recordStartVisualPending = false;
        _isMidiClipRecording = false;
        _midiRecordingClipEngineId = null;
        _midiRecordingClipIndex = null;
        _midiRecordingLiveInputArmed = false;
      });

      _startRecordingPeakPolling();
      _startRecordingRoutePolicyPolling();
    } finally {
      if (mounted && !_isRecording && _recordStartVisualPending) {
        setState(() {
          _recordStartVisualPending = false;
        });
      }
      if (mounted &&
          _isBluetoothV2Session &&
          _supportsV2AudioRecording &&
          !_isRecording &&
          !_v2AudioSessionInvalidated &&
          _audioRouteCoordinatorV2?.intent != AudioRouteIntentV2.playbackOnly) {
        await _restoreV2PlaybackOnlyAfterRecording();
      }
      if (!_isRecording) {
        await _discardPendingUnpublishedRecordingFile();
      }
      _recordStartCancelRequested = false;
      _recordTransitionInFlight = false;
    }
  }

  Future<bool> _restoreV2PlaybackOnlyAfterRecording() async {
    final coordinator = _audioRouteCoordinatorV2;
    if (coordinator == null || _v2AudioSessionInvalidated) return false;
    final result = await coordinator.transitionIntent(
      AudioRouteIntentV2.playbackOnly,
    );
    if (!result.succeeded) {
      await JuceAudioEngine.abortRecordingV2();
      return false;
    }
    JuceAudioEngine.acceptVerifiedAudioRouteTransitionV2(result);
    return true;
  }

  Future<bool> _ensureMicrophonePermissionForRecording() async {
    if (!(Platform.isAndroid || Platform.isIOS || Platform.isMacOS)) {
      return true;
    }

    if (_microphonePermissionStatus.isGranted ||
        _microphonePermissionStatus.isLimited) {
      return true;
    }

    var status = await _getMicrophonePermissionStatus();
    if (status.isGranted || status.isLimited) {
      return true;
    }

    status = await _requestMicrophonePermission();
    if (!mounted) return false;

    final granted = status.isGranted || status.isLimited;
    _setStateAndRefreshProjectSettings(() {
      _microphonePermissionStatus = status;
      _microphoneAccessBlocked = !granted;
    });

    if (granted) {
      if (!_isBluetoothV2Session) {
        unawaited(_loadInputDevicesFromJuce());
      }
      return true;
    }

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          status.isPermanentlyDenied || status.isRestricted
              ? L10n.translate(
                  context,
                  'Microphone access is blocked. Open app settings to record audio.',
                )
              : L10n.translate(
                  context,
                  'Microphone access is required to record audio.',
                ),
        ),
      ),
    );

    if (status.isPermanentlyDenied || status.isRestricted) {
      await _openAppPermissionsSettings();
    }

    return false;
  }

  Future<void> _stopRecordingJuce({bool keepPlaying = true}) async {
    if (!_isRecording) return;
    if (_isMidiClipRecording) {
      await _stopMidiClipRecording(keepPlaying: keepPlaying);
      return;
    }
    await _stopAudioRecordingJuce(keepPlaying: keepPlaying);
  }

  void _claimPendingUnpublishedRecordingPath(String path) {
    final normalized = path.trim();
    if (normalized.isEmpty) {
      throw ArgumentError.value(path, 'path', 'Recording path is empty');
    }
    final existing = _pendingUnpublishedRecordingPath;
    if (existing != null && existing != normalized) {
      throw StateError('pending_recording_path_already_owned');
    }
    _pendingUnpublishedRecordingPath = normalized;
    _recordingFilePath = normalized;
  }

  String? _detachPendingUnpublishedRecordingPath({String? expectedPath}) {
    final pending = _pendingUnpublishedRecordingPath;
    if (pending == null || (expectedPath != null && pending != expectedPath)) {
      return null;
    }
    _pendingUnpublishedRecordingPath = null;
    if (_recordingFilePath == pending) _recordingFilePath = null;
    return pending;
  }

  bool _ownsPendingUnpublishedRecordingPath(String path) =>
      _pendingUnpublishedRecordingPath == path;

  void _releasePendingRecordingForPublication(String path) {
    final detached = _detachPendingUnpublishedRecordingPath(expectedPath: path);
    if (detached == null) {
      throw StateError('pending_recording_path_not_owned');
    }
  }

  Future<void> _discardPendingUnpublishedRecordingFile({
    String? expectedPath,
  }) async {
    final path = _detachPendingUnpublishedRecordingPath(
      expectedPath: expectedPath,
    );
    if (path != null) await _deleteUncommittedRecordingFile(path);
  }

  Future<void> _deleteUncommittedRecordingFile(String path) async {
    final file = File(path);
    try {
      if (await file.exists()) await file.delete();
    } catch (_) {
      // The take was never published. Project cleanup may retry if the OS still
      // holds the just-finalized file briefly.
    }
  }

  Future<void> _stopAudioRecordingJuce({bool keepPlaying = true}) async {
    if (!_isRecording || _recordTransitionInFlight) return;
    _recordTransitionInFlight = true;
    try {
      _midiHeldNotesByKey.clear();
      _midiRecordNoteWallStartById.clear();
      _suppressedLiveMidiRecordEvents.clear();
      _midiHeldNoteRefreshTimer?.cancel();
      _midiHeldNoteRefreshTimer = null;
      final resumePlaybackAfterStop = keepPlaying && _isPlaying;
      final hadBluetoothInputRoute = _audioRouteInfo.inputIsBluetoothHeadset;
      final needsBluetoothStopRecovery =
          !_isBluetoothV2Session &&
          Platform.isAndroid &&
          hadBluetoothInputRoute;
      Future<void>? deferredBluetoothRestore;

      _stopRecordingPeakPolling(clearSamples: true);
      _stopRecordingRoutePolicyPolling();
      _liveInputMonitoringEffective = null;

      if (mounted) {
        setState(() {
          _isRecording = false;
          _isMidiClipRecording = false;
          _midiRecordingClipEngineId = null;
          _midiRecordingClipIndex = null;
          _midiRecordingLiveInputArmed = false;
        });
      }
      await _letRecordingVisualStatePaint();

      // Stop transport before native record-stop and clip insertion. This keeps
      // the record-stop transition and subsequent graph rebuild out of the live
      // playback path on both Android and iOS.
      if (_isPlaying) {
        await _pausePlayback();
        if (mounted) {
          setState(() {
            _isPlaying = false;
          });
        }
      }

      // 1) Stop JUCE recorder
      final RecordingCaptureResult captureResult;
      if (needsBluetoothStopRecovery && Platform.isAndroid) {
        captureResult =
            await JuceAudioEngine.stopRecordingWithoutPlaybackRestore();
      } else {
        captureResult = await JuceAudioEngine.stopRecording();
      }
      if (_isBluetoothV2Session && _supportsV2AudioRecording) {
        final restored = await _restoreV2PlaybackOnlyAfterRecording();
        if (!restored) {
          _v2AudioSessionInvalidated = true;
          if (mounted) {
            _showSmallNotice(
              'Recording stopped, but audio output could not be restored. Reopen the audio editor.',
            );
          }
        }
      }
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      if (needsBluetoothStopRecovery) {
        deferredBluetoothRestore = (() async {
          await Future<void>.delayed(const Duration(milliseconds: 250));
          await JuceAudioEngine.restoreBluetoothPlaybackAfterRecordingStop();
          await Future<void>.delayed(const Duration(milliseconds: 100));
          if (mounted) {
            await _refreshAudioRouteInfo(refreshNativeRoute: false);
          }
        })();
        unawaited(deferredBluetoothRestore);
      } else if (Platform.isAndroid) {
        // The native stop-record path already restores playback routing. Forcing
        // another immediate native refresh here can reopen Android's Bluetooth
        // stream again and destabilize post-record playback.
        await _refreshAudioRouteInfo(refreshNativeRoute: false);
      }

      if (!captureResult.success) {
        if (deferredBluetoothRestore != null) {
          await deferredBluetoothRestore;
        }
        await _discardPendingUnpublishedRecordingFile();
        if (mounted) {
          setState(() {
            _recordingFilePath = null;
          });
          _showSmallNotice(
            'Recording could not be saved reliably. Please try again.',
          );
        }
        return;
      }

      final recordingPath = _recordingFilePath;
      if (recordingPath == null || !File(recordingPath).existsSync()) {
        _detachPendingUnpublishedRecordingPath(expectedPath: recordingPath);
        if (mounted) {
          setState(() {
            _isRecording = false;
            _isMidiClipRecording = false;
            _midiRecordingClipEngineId = null;
            _midiRecordingClipIndex = null;
            _midiRecordingLiveInputArmed = false;
            _recordingFilePath = null;
          });

          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                L10n.translate(
                  context,
                  'Recording failed or no data captured.',
                ),
              ),
            ),
          );
        }
        return;
      }

      final int row = (_selectedRow >= 0 && _selectedRow < _rowCount)
          ? _selectedRow
          : 0;
      final double startMs = _recordingStartMs;
      final recordingLatencyMs =
          await JuceAudioEngine.getEstimatedRecordingLatencyMs();
      final compensatedStartMs = math.max(0.0, startMs - recordingLatencyMs);
      final appliedAlignmentOffsetMs = compensatedStartMs - startMs;
      if (!mounted) {
        await _discardPendingUnpublishedRecordingFile(
          expectedPath: recordingPath,
        );
        return;
      }

      if (_v2AudioSessionInvalidated ||
          !_ownsPendingUnpublishedRecordingPath(recordingPath)) {
        // A route-safety episode that overlaps Stop owns disposal of this take.
        // Never publish it after recovery, even if native finalization happened
        // to finish successfully before the invalidation was observed.
        await _discardPendingUnpublishedRecordingFile(
          expectedPath: recordingPath,
        );
        return;
      }

      // A route-safety episode during asynchronous publication owns transport
      // state. It may recover the output, but playback must remain paused until
      // the user explicitly resumes it.
      final publicationTransportSerial = _transportCommandSerial;

      // 2) Insert recorded clip (UNCHANGED)
      // Capture recovery no longer owns the finalized file once publication
      // begins. Route invalidation may run concurrently with the async clip
      // insert, but it must never delete a file that the timeline can adopt.
      _releasePendingRecordingForPublication(recordingPath);
      var recordingPublished = false;
      try {
        await _undoManager.execute(
          AddAudioTrackAction(
            addTrack:
                ({
                  required File file,
                  required int row,
                  required double timeMs,
                  Duration? trimStartRequested,
                  Duration? trimEndRequested,
                }) => _addAudioTrackFromFile(
                  file,
                  row,
                  timeMs,
                  transcodeTo48k: false,
                  showLoadingOverlay: false,
                  recordingLatencyMs: recordingLatencyMs,
                  alignmentOffsetMs: appliedAlignmentOffsetMs,
                ),
            tracks: _audioTracks,
            restoreTrack: _addClipFromUndoPayload,
            file: File(recordingPath),
            row: row,
            timeMs: compensatedStartMs,
            onRemove: _syncRemovedClipFadesAfterUndo,
          ),
        );
        recordingPublished = _audioTracks.any(
          (track) => track.file.path == recordingPath,
        );
      } catch (e) {
        debugPrint("Error adding recorded track: $e");
        recordingPublished = _audioTracks.any(
          (track) => track.file.path == recordingPath,
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                L10n.translate(context, 'Failed to add recorded track.'),
              ),
            ),
          );
        }
      }
      if (!recordingPublished) {
        await _deleteUncommittedRecordingFile(recordingPath);
      }

      // 3) Restore the intended playback state after the clip is inserted.
      if (deferredBluetoothRestore != null &&
          (resumePlaybackAfterStop || Platform.isIOS)) {
        await deferredBluetoothRestore;
      }
      if (resumePlaybackAfterStop &&
          mounted &&
          !_isPlaying &&
          publicationTransportSerial == _transportCommandSerial &&
          !_v2AudioSessionInvalidated &&
          !_v2AudioSessionRecoveryInProgress) {
        await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
      } else if (!keepPlaying && _isPlaying) {
        await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
      }
    } finally {
      _recordTransitionInFlight = false;
    }
  }

  Future<void> _addAudioTrackFromFile(
    File fromFile,
    int row,
    double timeMs, {
    Duration? trimStartRequested,
    Duration? trimEndRequested,
    bool pausePlaybackBeforeInsert = true,
    bool transcodeTo48k = true,
    bool showLoadingOverlay = true,
    String uploadMethod = 'import',
    String? clipId,
    double recordingLatencyMs = 0.0,
    double alignmentOffsetMs = 0.0,
    bool notifyUi = true,
    bool deferFadeSync = false,
  }) async {
    if (_audioTracks.length >= kNumClips) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
          ),
        ),
      );
      return;
    }

    if (pausePlaybackBeforeInsert && _isPlaying) {
      await _pausePlayback();
    }
    // A Finder drop can arrive immediately after the app regains focus, before
    // the audio device has reattached. Prime the same route used by first
    // playback before asking JUCE to install the clip, so importing audio does
    // not depend on the user pressing Play once.
    if (!_isBluetoothV2Session) {
      await JuceAudioEngine.initialise();
    }
    if (PlatformCapabilities.current.isDesktop || Platform.isIOS) {
      await _ensurePlaybackRouteReady(reason: 'audioImport');
    }
    await _ensureRowIndexExists(row);
    await _ensureRowExistsForClipInsertion();
    final safeRow = _rowCount == 0 ? 0 : row.clamp(0, _rowCount - 1);
    if (!_rowAllowsClipKind(safeRow, ClipKind.audio)) {
      _showSmallNotice('Audio clips cannot be placed on instrument lanes.');
      return;
    }
    final rowId = _rowIdAt(safeRow);
    final engineClipId = _reserveEngineClipId();
    if (engineClipId < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
          ),
        ),
      );
      return;
    }
    if (showLoadingOverlay) {
      setState(() {
        _isLoadingAudio = true;
      });
    }
    var addedTrack = false;
    try {
      final newFile = fromFile; //File(result.files.single.path!);

      final audioDir = ProjectManager.audioDir(_projectDir);
      if (!await audioDir.exists()) await audioDir.create(recursive: true);
      if (!newFile.existsSync()) return;

      final baseNameNoExt = _displayStemForFilePath(newFile.path);

      File clipSourceFile = newFile;
      if (transcodeTo48k) {
        if (uploadMethod == 'ai_library') {
          final candidatePath = _aiLibraryImportedAudioPath(newFile.path);
          final candidateFile = File(candidatePath);
          if (!candidateFile.existsSync()) {
            // AI library/sample-pack inserts should reuse one imported WAV per
            // source sample instead of cloning identical files for every hit.
            await FFmpegKit.execute(
              '-i "${newFile.path}" -ar 48000 -y "$candidatePath"',
            );
          }
          clipSourceFile = candidateFile;
        } else {
          // --- collision-safe temp name ---
          String candidatePath = p.join(audioDir.path, '$baseNameNoExt.wav');
          int suffix = 1;

          // Keep incrementing if another track already uses this temp path
          while (_audioTracks.any((t) => t.file.path == candidatePath)) {
            candidatePath = p.join(
              audioDir.path,
              '$baseNameNoExt #$suffix.wav',
            );
            suffix++;
          }

          // 1) Transcode to 48 kHz PCM WAV (fast, one-time cost for imports):
          // TODO: preserve original sample rate when native engine path is fully validated.
          await FFmpegKit.execute(
            '-i "${newFile.path}" -ar 48000 -y "$candidatePath"',
          );
          clipSourceFile = File(candidatePath);
        }
      }

      final safeTimeMs = math.max(0.0, timeMs);
      final startSec = safeTimeMs / 1000.0;
      final requestedTrimStart = trimStartRequested ?? Duration.zero;
      final requestedInFileOffsetSec =
          requestedTrimStart.inMilliseconds / 1000.0;
      final requestedLengthSec = trimEndRequested != null
          ? math.max(
              0.0,
              (trimEndRequested - requestedTrimStart).inMilliseconds / 1000.0,
            )
          : 0.0;
      final loaded = await _runWithAndroidEngineCriticalSection(() {
        return JuceAudioEngine.loadClip(
          engineClipId,
          rowId,
          clipSourceFile.path,
          startSec: startSec,
          lengthSec: requestedLengthSec,
          inFileOffsetSec: math.max(0.0, requestedInFileOffsetSec),
        );
      });
      if (!loaded) return;

      final dur = await _runWithAndroidEngineCriticalSection(
        () => _resolveClipSourceDuration(
          filePath: clipSourceFile.path,
          engineClipId: engineClipId,
        ),
      );

      // Create a new AudioTrack instance with a fixed audioDuration.
      final newTrack = await AudioTrack.create(
        file: clipSourceFile,
        originalFile: clipSourceFile, // might be unused
        audioDuration: dur, // Fixed duration for this track.
        trimStart: Duration.zero,
        trimEnd: dur,
        offset: 0.0,
        crossfade: 1.0,
        rowIndex: safeRow,
        rowId: rowId,
        engineClipId: engineClipId,
        clipId: clipId,
        label: baseNameNoExt,
        isReversed: false,
        recordingLatencyMs: recordingLatencyMs,
        alignmentOffsetMs: alignmentOffsetMs,
      );

      newTrack.offset = startSec;
      newTrack.trimStart = trimStartRequested ?? Duration.zero;
      newTrack.trimEnd = trimEndRequested ?? dur;

      await _syncClipMixToEngineOptimized(newTrack, assumeEngineDefaults: true);
      _startWaveformExtraction(newTrack);

      if (notifyUi) {
        setState(() {
          _audioTracks.add(newTrack);
          addedTrack = true;
          if (showLoadingOverlay) {
            _isLoadingAudio = false;
          }
        });
      } else {
        _audioTracks.add(newTrack);
        addedTrack = true;
      }
      _indexClipForOperations(newTrack);
      _updateOverallDurationIfNeeded(
        changedClips: <AudioTrack>[newTrack],
        notifyUi: notifyUi,
      );
      if (!deferFadeSync) {
        await _syncClipFadesForRowsToEngine({rowId});
      }
      unawaited(_flushDeferredAndroidRouteRefreshIfNeeded());
    } finally {
      _releaseReservedEngineClipId(engineClipId);
      if (showLoadingOverlay && !addedTrack && mounted && _isLoadingAudio) {
        setState(() {
          _isLoadingAudio = false;
        });
      }
    }
  }

  String _aiLibraryImportedAudioPath(String sourcePath) {
    final sourceToken = _normalizedClipPath(sourcePath);
    var hash = 0x811c9dc5;
    for (final codeUnit in sourceToken.codeUnits) {
      hash ^= codeUnit;
      hash = (hash * 0x01000193) & 0xffffffff;
    }
    final stableHash = hash.toUnsigned(32).toRadixString(16).padLeft(8, '0');
    return p.join(
      ProjectManager.audioDir(_projectDir).path,
      '${_displayStemForFilePath(sourcePath)}__$stableHash.wav',
    );
  }

  // optimized to not make unnecessary calls that normal addAudioTrack needs
  Future<void> _pasteAudioTrack(
    AudioTrack clip,
    int row,
    double timeMs, {
    Duration? trimStartRequested,
    Duration? trimEndRequested,
    String? clipId,
  }) async {
    if (_audioTracks.length >= kNumClips) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
          ),
        ),
      );
      return;
    }

    await _ensureRowIndexExists(row);
    await _ensureRowExistsForClipInsertion();
    final safeRow = _rowCount == 0 ? 0 : row.clamp(0, _rowCount - 1);
    if (!_rowAllowsClipKind(safeRow, ClipKind.audio)) {
      _showSmallNotice('Audio clips cannot be placed on instrument lanes.');
      return;
    }
    final safeTimeMs = math.max(0.0, timeMs);
    final rowId = _rowIdAt(safeRow);
    final engineClipId = _reserveEngineClipId();
    if (engineClipId < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
          ),
        ),
      );
      return;
    }
    try {
      final requestedTrimStart = trimStartRequested ?? Duration.zero;
      final requestedTrimEnd = trimEndRequested ?? clip.audioDuration;
      final requestedLengthSec = math.max(
        0.0,
        (requestedTrimEnd - requestedTrimStart).inMilliseconds / 1000.0,
      );
      final requestedInFileOffsetSec =
          requestedTrimStart.inMilliseconds / 1000.0;
      final loaded = await _runWithAndroidEngineCriticalSection(() {
        return JuceAudioEngine.loadClip(
          engineClipId,
          rowId,
          clip.file.path,
          startSec: safeTimeMs / 1000.0,
          lengthSec: requestedLengthSec,
          inFileOffsetSec: math.max(0.0, requestedInFileOffsetSec),
        );
      });
      if (!loaded) return;
      final dur = clip.audioDuration;

      // Create a new AudioTrack instance with a fixed audioDuration.
      final newTrack = await AudioTrack.create(
        file: clip.file,
        originalFile: clip.file, // might be unused
        audioDuration: dur, // Fixed duration for this track.
        trimStart: Duration.zero,
        trimEnd: dur,
        offset: 0.0,
        crossfade: 1.0,
        rowIndex: safeRow,
        rowId: rowId,
        engineClipId: engineClipId,
        clipId: clipId,
        label: clip.label,
        isReversed: clip.isReversed,
      );

      newTrack.normWaveformData = clip.normWaveformData;
      newTrack.offset = safeTimeMs / 1000.0;
      newTrack.trimStart = trimStartRequested ?? Duration.zero;
      newTrack.trimEnd = trimEndRequested ?? dur;
      newTrack.gain = clip.gain;
      newTrack.normalizeVolume = clip.normalizeVolume;
      newTrack.normalizeGain = clip.normalizeGain;
      newTrack.preNormalizeGain = clip.preNormalizeGain;
      newTrack.pitchSemitones = clip.pitchSemitones;
      newTrack.isReversed = clip.isReversed;
      newTrack.sourceTempoBpm = clip.sourceTempoBpm;
      newTrack.stretchToProjectTempo = clip.stretchToProjectTempo;
      newTrack.tempoStretchPreservePitch = clip.tempoStretchPreservePitch;
      newTrack.tempoWarpMode = clip.tempoWarpMode;
      newTrack.volumeAutomation = clip.volumeAutomation
          .map((point) => point.copy())
          .toList();

      await _syncClipEngineStateAfterLoad(newTrack);

      setState(() {
        _audioTracks.add(newTrack);
      });
      _indexClipForOperations(newTrack);
      _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[newTrack]);
      await _syncClipFadesForRowsToEngine({rowId});
    } finally {
      _releaseReservedEngineClipId(engineClipId);
    }
  }

  // used by loadProject, skips renaming logic in normal addAudioTrack
  Future<void> _addAudioTrackFromProjectFile({
    required File projectAudioFile,
    required String label,
    required int row,
    required double timeMs,
    Duration? trimStartRequested,
    Duration? trimEndRequested,
    double? gain,
    bool? normalizeVolume,
    double? normalizeGain,
    double? preNormalizeGain,
    double? pitchSemitones,
    bool isReversed = false,
    double? sourceTempoBpm,
    bool? stretchToProjectTempo,
    bool? tempoStretchPreservePitch,
    String? tempoWarpMode,
    double? recordingLatencyMs,
    double? alignmentOffsetMs,
    String? audioEnhancementPreset,
    double? crossfade,
    List<AutomationPoint>? automation,
    bool rowAlreadyEnsured = false,
    bool notifyUi = true,
    bool updateProjectDuration = true,
    bool startWaveform = true,
    bool assumeFreshEngineDefaults = false,
    String? clipId,
  }) async {
    // no FFmpeg, no temp renaming
    if (!rowAlreadyEnsured) {
      await _ensureRowIndexExists(row);
      await _ensureRowExistsForClipInsertion();
    }
    final safeRow = _rowCount == 0 ? 0 : row.clamp(0, _rowCount - 1);
    if (!_isProjectLoading && !_rowAllowsClipKind(safeRow, ClipKind.audio)) {
      _showSmallNotice('Audio clips cannot be placed on instrument lanes.');
      return;
    }
    final safeTimeMs = math.max(0.0, timeMs);
    final rowId = _rowIdAt(safeRow);
    final engineClipId = _reserveEngineClipId();
    if (engineClipId < 0) return;
    try {
      final requestedTrimStart = trimStartRequested ?? Duration.zero;
      final requestedInFileOffsetSec =
          requestedTrimStart.inMilliseconds / 1000.0;
      final requestedLengthSec = trimEndRequested != null
          ? math.max(
              0.0,
              (trimEndRequested - requestedTrimStart).inMilliseconds / 1000.0,
            )
          : 0.0;
      final loaded = await _runWithAndroidEngineCriticalSection(() {
        return JuceAudioEngine.loadClip(
          engineClipId,
          rowId,
          projectAudioFile.path,
          startSec: safeTimeMs / 1000.0,
          lengthSec: requestedLengthSec,
          inFileOffsetSec: math.max(0.0, requestedInFileOffsetSec),
        );
      });
      if (!loaded) return;

      final dur = await _runWithAndroidEngineCriticalSection(
        () => _resolveClipSourceDuration(
          filePath: projectAudioFile.path,
          engineClipId: engineClipId,
        ),
      );

      final newTrack = await AudioTrack.create(
        file: projectAudioFile, // points directly to project/audio
        originalFile: projectAudioFile, // unused
        audioDuration: dur,
        trimStart: Duration.zero,
        trimEnd: dur,
        offset: 0.0,
        crossfade: 1.0,
        rowIndex: safeRow,
        rowId: rowId,
        engineClipId: engineClipId,
        clipId: clipId,
        label: label,
        isReversed: false,
      );

      newTrack.offset = safeTimeMs / 1000.0;
      newTrack.trimStart = trimStartRequested ?? Duration.zero;
      newTrack.trimEnd = trimEndRequested ?? dur;

      if (gain != null) newTrack.gain = gain;
      if (normalizeVolume != null) newTrack.normalizeVolume = normalizeVolume;
      if (normalizeGain != null) {
        newTrack.normalizeGain = normalizeGain
            .clamp(_kClipNormalizeGainMin, _kClipNormalizeGainMax)
            .toDouble();
      }
      if (preNormalizeGain != null) {
        newTrack.preNormalizeGain = preNormalizeGain;
      }
      if (pitchSemitones != null) newTrack.pitchSemitones = pitchSemitones;
      newTrack.isReversed = isReversed;
      if (sourceTempoBpm != null) newTrack.sourceTempoBpm = sourceTempoBpm;
      if (stretchToProjectTempo != null) {
        newTrack.stretchToProjectTempo = stretchToProjectTempo;
      }
      if (tempoStretchPreservePitch != null) {
        newTrack.tempoStretchPreservePitch = tempoStretchPreservePitch;
      }
      if (tempoWarpMode != null) {
        newTrack.tempoWarpMode = normalizeTempoWarpMode(tempoWarpMode);
      }
      if (recordingLatencyMs != null) {
        newTrack.recordingLatencyMs = recordingLatencyMs;
      }
      if (alignmentOffsetMs != null) {
        newTrack.alignmentOffsetMs = alignmentOffsetMs;
      }
      if (audioEnhancementPreset != null) {
        newTrack.audioEnhancementPreset = audioEnhancementPreset.trim();
      }
      if (crossfade != null) newTrack.crossfade = crossfade;
      if (automation != null && automation.isNotEmpty) {
        newTrack.volumeAutomation = automation;
      }

      await _syncClipEngineStateAfterLoad(
        newTrack,
        assumeEngineDefaults: assumeFreshEngineDefaults,
      );

      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] add audio track model clip=${newTrack.clipId} engine=${newTrack.engineClipId} start',
        );
      }
      if (notifyUi) {
        setState(() {
          _audioTracks.add(newTrack);
        });
      } else {
        _audioTracks.add(newTrack);
      }
      _indexClipForOperations(newTrack);
      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] add audio track model clip=${newTrack.clipId} engine=${newTrack.engineClipId} done',
        );
      }
      if (!_isProjectLoading) {
        await _syncClipFadesForRowsToEngine({rowId});
      }

      if (startWaveform) {
        _startWaveformExtraction(newTrack);
      }
      if (updateProjectDuration) {
        _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[newTrack]);
      }
    } finally {
      _releaseReservedEngineClipId(engineClipId);
    }
  }

  Map<String, dynamic> _instrumentSpecById(String id) {
    final found = _findInstrumentSpecById(id);
    if (found != null) return found;
    return _defaultInstrumentSpec();
  }

  String _normalizeInstrumentToken(String value) {
    return value.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '');
  }

  Map<String, dynamic>? _findLegacySfzSpecByToken(String id) {
    final token = _normalizeInstrumentToken(id);
    if (token.isEmpty) return null;

    final pool = <Map<String, dynamic>>[
      ..._instrumentCatalog,
      ...kBundledSfzFallbackCatalog,
    ];
    Map<String, dynamic>? best;
    var bestScore = 0;

    for (final spec in pool) {
      final sfzPath = (spec['sfzAssetPath'] as String?)?.trim() ?? '';
      if (sfzPath.isEmpty) continue;
      final stemToken = _normalizeInstrumentToken(
        p.basenameWithoutExtension(sfzPath),
      );
      final nameToken = _normalizeInstrumentToken(
        (spec['name'] as String?) ?? '',
      );
      final idToken = _normalizeInstrumentToken((spec['id'] as String?) ?? '');

      var score = 0;
      if (token == idToken || token == stemToken || token == nameToken) {
        score = 6;
      } else if (stemToken.isNotEmpty &&
          (token.contains(stemToken) || stemToken.contains(token))) {
        score = 5;
      } else if (nameToken.isNotEmpty &&
          (token.contains(nameToken) || nameToken.contains(token))) {
        score = 4;
      }

      if (score > bestScore) {
        bestScore = score;
        best = spec;
      }
    }
    return best;
  }

  Map<String, dynamic>? _findInstrumentSpecById(String id) {
    final trimmed = id.trim();
    if (trimmed.isEmpty) return null;
    final lower = trimmed.toLowerCase();

    final aliasId = kLegacySfzInstrumentAliases[lower];
    if (aliasId != null && aliasId.isNotEmpty) {
      for (final spec in _instrumentCatalog) {
        if (spec['id'] == aliasId) return _platformResolvedInstrumentSpec(spec);
      }
      for (final spec in kBundledSfzFallbackCatalog) {
        if (spec['id'] == aliasId) return _platformResolvedInstrumentSpec(spec);
      }
      for (final spec in kInstrumentCatalog) {
        if (spec['id'] == aliasId) return _platformResolvedInstrumentSpec(spec);
      }
      for (final spec in _desktopHostedInstrumentCatalog) {
        if (spec['id'] == aliasId) return Map<String, dynamic>.from(spec);
      }
    }

    for (final spec in _instrumentCatalog) {
      if (spec['id'] == trimmed) return _platformResolvedInstrumentSpec(spec);
    }
    for (final spec in kBundledSfzFallbackCatalog) {
      if (spec['id'] == trimmed) return _platformResolvedInstrumentSpec(spec);
    }
    for (final spec in kInstrumentCatalog) {
      if (spec['id'] == trimmed) return _platformResolvedInstrumentSpec(spec);
    }
    for (final spec in _desktopHostedInstrumentCatalog) {
      if (spec['id'] == trimmed) return Map<String, dynamic>.from(spec);
    }

    if (lower.startsWith('sfz_asset:')) {
      final sfzPath = trimmed.substring('sfz_asset:'.length).trim();
      if (sfzPath.isNotEmpty) {
        return <String, dynamic>{
          'id': trimmed,
          'name': _prettyInstrumentNameFromSfzPreset(p.basename(sfzPath)),
          'category': 'instrument',
          'pickerCategory': 'Other',
          'sourceProject': 'External SFZ',
          'sourceLicense': 'User-provided',
          'isSampled': true,
          'sfzAssetPath': sfzPath,
          'outputGain': 0.72,
          'attackMs': 6.0,
          'decayMs': 120.0,
          'sustainLevel': 0.86,
          'releaseMs': 520.0,
          'sampleStartNorm': 0.0,
          'sampleEndNorm': 1.0,
          'reverseSample': 0.0,
          'normalizeSample': 0.0,
          'samplePlayMode': 0.0,
          'rootNote': 60.0,
          'sampleLowKey': 0.0,
          'sampleHighKey': 127.0,
          'sliceMode': 0.0,
          'sliceCount': 8.0,
          'timeStretchMode': 0.0,
          'sampleFilterCutoffHz': 20000.0,
          'granularMode': 0.0,
          'grainAttackMs': 18.0,
          'grainHoldMs': 42.0,
          'grainSpacingPct': 100.0,
          'waveSpacingPct': 100.0,
          'grainPan': 0.0,
          'grainLfoDepthPct': 0.0,
          'grainLfoSpeedHz': 0.8,
          'grainRandomPct': 0.0,
          'grainTransientMode': 0.0,
          'grainTransientHoldMs': 80.0,
          'grainLoop': 1.0,
          'grainPositionHold': 0.0,
          'grainKeyMode': 0.0,
        };
      }
    }

    if (lower.startsWith('sfz.')) {
      final legacy = _findLegacySfzSpecByToken(trimmed);
      if (legacy != null) return _platformResolvedInstrumentSpec(legacy);
    }
    return null;
  }

  String _instrumentNameFromId(String id) {
    final spec = _instrumentSpecById(id);
    return (spec['name'] as String?) ??
        (_defaultInstrumentSpec()['name'] as String? ?? 'Instrument');
  }

  Map<String, double> _instrumentParamsFromSpec(Map<String, dynamic> spec) {
    final sampled = _isSampledInstrumentSpec(spec);
    final params = <String, double>{};
    for (final entry in spec.entries) {
      final value = entry.value;
      if (value is num) {
        params[entry.key] = value.toDouble();
      }
    }
    if (_isExternalPluginInstrumentSpec(spec)) {
      return params;
    }
    if (sampled) {
      params.putIfAbsent('outputGain', () => 0.72);
      params.putIfAbsent('attackMs', () => 6.0);
      params.putIfAbsent('decayMs', () => 120.0);
      params.putIfAbsent('sustainLevel', () => 0.86);
      params.putIfAbsent('releaseMs', () => 520.0);
      params.putIfAbsent('sampleStartNorm', () => 0.0);
      params.putIfAbsent('sampleEndNorm', () => 1.0);
      params.putIfAbsent('reverseSample', () => 0.0);
      params.putIfAbsent('normalizeSample', () => 0.0);
      params.putIfAbsent('samplePlayMode', () => 0.0);
      params.putIfAbsent('rootNote', () => 60.0);
      params.putIfAbsent('sampleLowKey', () => 0.0);
      params.putIfAbsent('sampleHighKey', () => 127.0);
      params.putIfAbsent('sliceMode', () => 0.0);
      params.putIfAbsent('sliceCount', () => 8.0);
      params.putIfAbsent('timeStretchMode', () => 0.0);
      params.putIfAbsent('sampleFilterCutoffHz', () => 20000.0);
      params.putIfAbsent('stereoWidth', () => 0.0);
      params.putIfAbsent('granularMode', () => 0.0);
      params.putIfAbsent('grainAttackMs', () => 18.0);
      params.putIfAbsent('grainHoldMs', () => 42.0);
      params.putIfAbsent('grainSpacingPct', () => 100.0);
      params.putIfAbsent('waveSpacingPct', () => 100.0);
      params.putIfAbsent('grainPan', () => 0.0);
      params.putIfAbsent('grainLfoDepthPct', () => 0.0);
      params.putIfAbsent('grainLfoSpeedHz', () => 0.8);
      params.putIfAbsent('grainRandomPct', () => 0.0);
      params.putIfAbsent('grainTransientMode', () => 0.0);
      params.putIfAbsent('grainTransientHoldMs', () => 80.0);
      params.putIfAbsent('grainLoop', () => 1.0);
      params.putIfAbsent('grainPositionHold', () => 0.0);
      params.putIfAbsent('grainKeyMode', () => 0.0);
      params['drive'] = 0.0;
      params['noise'] = 0.0;
      return params;
    }
    params.putIfAbsent('oscillator', () => 1.0);
    params.putIfAbsent('cutoffHz', () => 3200.0);
    params.putIfAbsent('attackMs', () => 18.0);
    params.putIfAbsent('releaseMs', () => 180.0);
    params.putIfAbsent('drive', () => 0.08);
    return params;
  }

