  Future<File> _nextInstrumentRenderFile(String instrumentId) async {
    final audioDir = ProjectManager.audioDir(_projectDir);
    if (!await audioDir.exists()) await audioDir.create(recursive: true);
    final stem = instrumentId.replaceAll('.', '_');
    final path = p.join(
      audioDir.path,
      '${stem}_${DateTime.now().microsecondsSinceEpoch}.wav',
    );
    return File(path);
  }

  String? _sampledAliasAssetPathForInstrumentId(String instrumentId) {
    switch (instrumentId.trim().toLowerCase()) {
      case 'mixroom.drum_808_starter':
        return _resolveBundledInstrumentPathForCurrentPlatform(
          'assets/instruments/VSCO-2-CE-1.1.0/MixroomDrumStarter.sfz',
        );
      case 'mixroom.drum_house':
      case 'mixroom.drum_breakbeat':
        return _resolveBundledInstrumentPathForCurrentPlatform(
          'assets/instruments/VSCO-2-CE-1.1.0/MixroomDryDrumKit.sfz',
        );
      case 'mixroom.horn_stack':
        return _resolveBundledInstrumentPathForCurrentPlatform(
          'assets/instruments/VSCO-2-CE-1.1.0/TrumpetStac.sfz',
        );
      default:
        return null;
    }
  }

  int _remapSampledMidiPitch(String instrumentId, int pitch) {
    final normalized = instrumentId.trim().toLowerCase();
    switch (normalized) {
      case 'mixroom.drum_808_starter':
      case 'mixroom.drum_house':
      case 'mixroom.drum_breakbeat':
      case 'mixroom.drum_trap':
      case 'sfz.vsco.mixroom_drum_starter':
      case 'sfz.vsco.mixroom_dry_drum_kit':
      case 'sfz.vsco.mixroom_acoustic_drum_kit':
      case 'sfz.vsco_2_ce_1_1_0_mixroomdrumstarter':
      case 'sfz.vsco_2_ce_1_1_0_mixroomdrydrumkit':
      case 'sfz.vsco_2_ce_1_1_0_mixroomacousticdrumkit':
        switch (pitch.clamp(0, 127)) {
          case 35:
            return 36;
          case 37:
          case 39:
            return 38;
          case 41:
          case 43:
            return 45;
          case 48:
            return 47;
          case 52:
          case 53:
            return 42;
          case 55:
          case 57:
          case 59:
            return 49;
          default:
            return pitch.clamp(0, 127);
        }
      default:
        return pitch.clamp(0, 127);
    }
  }

  Future<SfzDefinition?> _sfzDefinitionForInstrument(
    String instrumentId,
  ) async {
    final spec = _instrumentSpecById(instrumentId);
    final aliasPath = _sampledAliasAssetPathForInstrumentId(instrumentId);
    if (!_isSampledInstrumentSpec(spec) && aliasPath == null) return null;
    final sfzAssetPath = aliasPath ??
        ((spec['sfzAssetPath'] as String?)?.trim() ?? '');
    if (sfzAssetPath.isEmpty) return null;
    return _sfzDefinitionLoader.load(sfzAssetPath);
  }

  Future<Set<int>> _playableMidiPitchesForInstrument(
    String instrumentId,
    Map<String, double> params,
  ) async {
    final spec = _findInstrumentSpecById(instrumentId);
    if (spec != null && _isExternalPluginInstrumentSpec(spec)) {
      return _allMidiPitches;
    }
    final aliasPath = _sampledAliasAssetPathForInstrumentId(instrumentId);
    final sampled = aliasPath != null ||
        (spec != null && _isSampledInstrumentSpec(spec));
    if (!sampled) return _allMidiPitches;

    final definition = await _sfzDefinitionForInstrument(instrumentId);
    if (definition == null) {
      final failureKey = aliasPath ??
          (spec?['sfzAssetPath'] as String?)?.trim() ??
          instrumentId.trim();
      if (_sfzRangeDetectionFailuresLogged.add(failureKey)) {
        debugPrint(
          '[PianoRollRange] Unable to parse $failureKey; enabling MIDI 0-127.',
        );
      }
      return _allMidiPitches;
    }

    final sampleLowKey =
        (params['sampleLowKey'] ?? 0.0).round().clamp(0, 127);
    final sampleHighKey = (params['sampleHighKey'] ?? 127.0)
        .round()
        .clamp(sampleLowKey, 127);
    return definition.playableInputPitches(
      remapPitch: (pitch) => _remapSampledMidiPitch(instrumentId, pitch),
      sampleLowKey: sampleLowKey,
      sampleHighKey: sampleHighKey,
    );
  }

  SfzRegion? _pickSfzRegion(
    SfzDefinition definition,
    int pitch,
    int velocity, {
    int sequenceStep = 0,
  }) {
    double random01For(SfzRegion region) {
      var seed = 0x45d9f3b;
      seed ^= pitch * 1009;
      seed ^= velocity * 9176;
      seed ^= sequenceStep * 6151;
      seed ^= region.keyCenter * 313;
      seed ^= region.loKey * 137;
      seed ^= region.hiKey * 271;
      seed = (seed ^ (seed >> 16)) & 0x7fffffff;
      return seed / 0x7fffffff;
    }

    var candidates = definition.regions
        .where((region) {
          return pitch >= region.loKey &&
              pitch <= region.hiKey &&
              velocity >= region.loVel &&
              velocity <= region.hiVel;
        })
        .toList(growable: false);

    if (candidates.isEmpty) {
      candidates = definition.regions
          .where((region) {
            return pitch >= region.loKey && pitch <= region.hiKey;
          })
          .toList(growable: false);
    }
    if (candidates.isEmpty) return null;

    final sequenced = candidates
        .where((region) {
          if (region.seqLength <= 1) return true;
          final expected = (sequenceStep % region.seqLength) + 1;
          return region.seqPosition == expected;
        })
        .toList(growable: false);
    if (sequenced.isNotEmpty) {
      candidates = sequenced;
    }

    final randomMatched = candidates
        .where((region) {
          final randomValue = random01For(region);
          return randomValue >= region.loRand && randomValue < region.hiRand;
        })
        .toList(growable: false);
    if (randomMatched.isNotEmpty) {
      candidates = randomMatched;
    }

    candidates.sort((a, b) {
      final keyA = (pitch - a.keyCenter).abs();
      final keyB = (pitch - b.keyCenter).abs();
      if (keyA != keyB) return keyA.compareTo(keyB);
      final velA = velocity < a.loVel
          ? a.loVel - velocity
          : velocity > a.hiVel
          ? velocity - a.hiVel
          : 0;
      final velB = velocity < b.loVel
          ? b.loVel - velocity
          : velocity > b.hiVel
          ? velocity - b.hiVel
          : 0;
      return velA.compareTo(velB);
    });
    return candidates.first;
  }

  int _findWavChunk(Uint8List bytes, String chunkId) {
    for (int i = 12; i + 8 <= bytes.length;) {
      final id = ascii.decode(bytes.sublist(i, i + 4), allowInvalid: true);
      final size = ByteData.sublistView(
        bytes,
        i + 4,
        i + 8,
      ).getUint32(0, Endian.little);
      if (id == chunkId) return i;
      i += 8 + size + (size.isOdd ? 1 : 0);
    }
    return -1;
  }

  _DecodedStereoPcm? _decodePcmWav(ByteData wavData) {
    final bytes = wavData.buffer.asUint8List();
    if (bytes.length < 44) return null;
    final riff = ascii.decode(bytes.sublist(0, 4), allowInvalid: true);
    final wave = ascii.decode(bytes.sublist(8, 12), allowInvalid: true);
    if (riff != 'RIFF' || wave != 'WAVE') return null;

    final fmtChunkStart = _findWavChunk(bytes, 'fmt ');
    final dataChunkStart = _findWavChunk(bytes, 'data');
    if (fmtChunkStart < 0 || dataChunkStart < 0) return null;

    final fmtSize = ByteData.sublistView(
      bytes,
      fmtChunkStart + 4,
      fmtChunkStart + 8,
    ).getUint32(0, Endian.little);
    if (fmtSize < 16) return null;
    final fmt = ByteData.sublistView(
      bytes,
      fmtChunkStart + 8,
      fmtChunkStart + 8 + fmtSize,
    );
    final audioFormat = fmt.getUint16(0, Endian.little);
    final channels = fmt.getUint16(2, Endian.little);
    final sampleRate = fmt.getUint32(4, Endian.little);
    final bitsPerSample = fmt.getUint16(14, Endian.little);
    if (channels < 1 || channels > 2) return null;
    if (audioFormat != 1) return null;
    if (bitsPerSample != 16 && bitsPerSample != 24) return null;

    final dataSize = ByteData.sublistView(
      bytes,
      dataChunkStart + 4,
      dataChunkStart + 8,
    ).getUint32(0, Endian.little);
    final dataOffset = dataChunkStart + 8;
    if (dataOffset + dataSize > bytes.length) return null;

    final bytesPerSample = bitsPerSample ~/ 8;
    final frameSize = bytesPerSample * channels;
    if (frameSize <= 0) return null;
    final frameCount = dataSize ~/ frameSize;
    if (frameCount <= 0) return null;

    final left = Float32List(frameCount);
    final right = Float32List(frameCount);

    int ptr = dataOffset;
    for (int i = 0; i < frameCount; i++) {
      double readSample() {
        if (bitsPerSample == 16) {
          final v = (bytes[ptr] | (bytes[ptr + 1] << 8));
          final signed = (v & 0x8000) != 0 ? v - 0x10000 : v;
          ptr += 2;
          return (signed / 32768.0).clamp(-1.0, 1.0).toDouble();
        }
        final v = bytes[ptr] | (bytes[ptr + 1] << 8) | (bytes[ptr + 2] << 16);
        final signed = (v & 0x800000) != 0 ? v - 0x1000000 : v;
        ptr += 3;
        return (signed / 8388608.0).clamp(-1.0, 1.0).toDouble();
      }

      final l = readSample();
      final r = channels > 1 ? readSample() : l;
      left[i] = l;
      right[i] = r;
    }

    return _DecodedStereoPcm(sampleRate: sampleRate, left: left, right: right);
  }

  String _sfzSampleCacheFileStem(String assetPath) {
    final normalized = assetPath.toLowerCase();
    final hash = normalized.codeUnits.fold<int>(
      0x811c9dc5,
      (acc, unit) => (((acc ^ unit) * 0x01000193) & 0x7fffffff),
    );
    final basename = p.posix
        .basename(assetPath)
        .replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '_');
    return '${basename}_$hash';
  }

  Future<_DecodedStereoPcm?> _decodeSfzSampleWithFfmpeg(
    String assetPath,
    ByteData sourceData,
  ) async {
    final tempDir = await getTemporaryDirectory();
    final cacheDir = Directory(p.join(tempDir.path, 'mixroom_sfz_cache'));
    if (!await cacheDir.exists()) {
      await cacheDir.create(recursive: true);
    }

    final stem = _sfzSampleCacheFileStem(assetPath);
    final inputExt = p.extension(assetPath).toLowerCase();
    final inputPath = p.join(
      cacheDir.path,
      '$stem${inputExt.isEmpty ? '.bin' : inputExt}',
    );
    final outputPath = p.join(cacheDir.path, '$stem.wav');
    final inputFile = File(inputPath);
    final outputFile = File(outputPath);

    if (!await inputFile.exists()) {
      await inputFile.writeAsBytes(
        sourceData.buffer.asUint8List(
          sourceData.offsetInBytes,
          sourceData.lengthInBytes,
        ),
        flush: true,
      );
    }

    if (!await outputFile.exists()) {
      final session = await FFmpegKit.execute(
        '-y -i "${inputFile.path}" -vn -ac 2 -ar 48000 -c:a pcm_s16le "${outputFile.path}"',
      );
      final returnCode = await session.getReturnCode();
      if (!ReturnCode.isSuccess(returnCode) || !await outputFile.exists()) {
        return null;
      }
    }

    final wavBytes = await outputFile.readAsBytes();
    return _decodePcmWav(ByteData.sublistView(wavBytes));
  }

  Future<_DecodedStereoPcm?> _decodedSfzSample(String assetPath) async {
    final cached = _sfzSampleCache.remove(assetPath);
    if (cached != null) {
      _sfzSampleCache[assetPath] = cached;
      return cached;
    }
    try {
      final data = File(assetPath).existsSync()
          ? ByteData.sublistView(await File(assetPath).readAsBytes())
          : await rootBundle.load(assetPath);
      var decoded = _decodePcmWav(data);
      decoded ??= await _decodeSfzSampleWithFfmpeg(assetPath, data);
      if (decoded == null) return null;
      _sfzSampleCache[assetPath] = decoded;
      if (_sfzSampleCache.length > _kMaxSfzSampleCacheEntries) {
        _sfzSampleCache.remove(_sfzSampleCache.keys.first);
      }
      return decoded;
    } catch (_) {
      return null;
    }
  }

  double _sfzPlaybackRate({
    required _DecodedStereoPcm sample,
    required SfzRegion region,
    required int notePitch,
    required double outputSampleRate,
  }) {
    final semitoneOffset =
        ((notePitch - region.keyCenter) * (region.pitchKeytrack / 100.0)) +
        region.pitchOffsetSemitones;
    return math.pow(2.0, semitoneOffset / 12.0).toDouble() *
        (sample.sampleRate / outputSampleRate);
  }

  int _sfzRegionFrameLimit(SfzRegion region, _DecodedStereoPcm sample) {
    final requestedEnd = region.sampleEndFrameExclusive > 0
        ? region.sampleEndFrameExclusive
        : sample.frameCount;
    return requestedEnd.clamp(region.sampleStartFrame + 1, sample.frameCount);
  }

  Future<bool> _renderInstrumentClipWithGranularizer({
    required File outFile,
    required String instrumentId,
    required List<MidiNote> notes,
    required Map<String, double> params,
    required double bpm,
    double minimumDurationMs = 1200.0,
  }) async {
    final definition = await _sfzDefinitionForInstrument(instrumentId);
    if (definition == null || definition.regions.isEmpty) return false;

    const double sampleRate = 48000.0;
    final msPerBeat = 60000.0 / bpm.clamp(1.0, 400.0);
    double endBeat = 4.0;
    for (final n in notes) {
      endBeat = math.max(endBeat, n.startBeat + n.lengthBeats);
    }

    final outputGain = (params['outputGain'] ?? 0.72).clamp(0.2, 2.0);
    final attackSec = ((params['attackMs'] ?? 4.0) / 1000.0)
        .clamp(0.0, 1.0)
        .toDouble();
    final releaseSec = ((params['releaseMs'] ?? 260.0) / 1000.0)
        .clamp(0.02, 2.4)
        .toDouble();
    final grainAttackMs = (params['grainAttackMs'] ?? 18.0)
        .clamp(0.0, 250.0)
        .toDouble();
    final grainHoldMs = (params['grainHoldMs'] ?? 42.0)
        .clamp(2.0, 500.0)
        .toDouble();
    final grainSpacingPct = (params['grainSpacingPct'] ?? 100.0)
        .clamp(1.0, 400.0)
        .toDouble();
    final waveSpacingPct = (params['waveSpacingPct'] ?? 100.0)
        .clamp(-400.0, 400.0)
        .toDouble();
    final grainPan = (params['grainPan'] ?? 0.34).clamp(-1.0, 1.0).toDouble();
    final lfoDepthPct = (params['grainLfoDepthPct'] ?? 0.0)
        .clamp(0.0, 100.0)
        .toDouble();
    final lfoSpeedHz = (params['grainLfoSpeedHz'] ?? 0.8)
        .clamp(0.0, 20.0)
        .toDouble();
    final randomPct = (params['grainRandomPct'] ?? 0.0)
        .clamp(0.0, 100.0)
        .toDouble();
    final transientHoldMs = (params['grainTransientHoldMs'] ?? 80.0)
        .clamp(2.0, 500.0)
        .toDouble();
    final transientMode = (params['grainTransientMode'] ?? 0.0).round();
    final keyMode = (params['grainKeyMode'] ?? 0.0).round();
    final loopGrains = (params['grainLoop'] ?? 1.0) >= 0.5;
    final positionHold = (params['grainPositionHold'] ?? 0.0) >= 0.5;
    final rootNote = (params['rootNote'] ?? 60.0).round().clamp(0, 127);
    final sampleLowKey = (params['sampleLowKey'] ?? 0.0).round().clamp(0, 127);
    final sampleHighKey = (params['sampleHighKey'] ?? 127.0).round().clamp(
      sampleLowKey,
      127,
    );
    final sampleStartNorm = (params['sampleStartNorm'] ?? 0.0)
        .clamp(0.0, 0.98)
        .toDouble();
    final sampleEndNorm = (params['sampleEndNorm'] ?? 1.0)
        .clamp(sampleStartNorm + 0.02, 1.0)
        .toDouble();
    final reverseSample = (params['reverseSample'] ?? 0.0) >= 0.5;
    final normalizeSample = (params['normalizeSample'] ?? 0.0) >= 0.5;
    final filterCutoff = (params['sampleFilterCutoffHz'] ?? 20000.0).clamp(
      80.0,
      20000.0,
    );

    final totalMs = math.max(
      minimumDurationMs,
      endBeat * msPerBeat + releaseSec * 1000.0 + 240.0,
    );
    final totalSamples = math.max(2048, (totalMs * sampleRate / 1000.0).ceil());
    final left = Float32List(totalSamples);
    final right = Float32List(totalSamples);

    double hash01(int seed) {
      var x = (seed * 1103515245 + 12345) & 0x7fffffff;
      x ^= (x << 13) & 0x7fffffff;
      x ^= x >> 17;
      x ^= (x << 5) & 0x7fffffff;
      return (x & 0x00ffffff) / 0x01000000;
    }

    for (int noteIndex = 0; noteIndex < notes.length; noteIndex++) {
      final note = notes[noteIndex];
      final safePitch = _remapSampledMidiPitch(instrumentId, note.pitch);
      if (safePitch < sampleLowKey || safePitch > sampleHighKey) continue;
      final safeVelocity = note.velocity.clamp(0.0, 1.0).toDouble();
      final velocityMidi = (safeVelocity * 127.0).round().clamp(0, 127);
      final region = _pickSfzRegion(
        definition,
        safePitch,
        velocityMidi,
        sequenceStep: noteIndex,
      );
      if (region == null) continue;
      final sample = await _decodedSfzSample(region.sampleAssetPath);
      if (sample == null || sample.frameCount < 4) continue;

      final baseStart = region.sampleStartFrame
          .clamp(0, math.max(0, sample.frameCount - 1))
          .toInt();
      final baseEnd = _sfzRegionFrameLimit(region, sample);
      var trimStart =
          baseStart + ((baseEnd - baseStart - 1) * sampleStartNorm).round();
      var trimEnd = baseStart + ((baseEnd - baseStart) * sampleEndNorm).round();
      trimEnd = trimEnd.clamp(trimStart + 2, baseEnd).toInt();
      final trimFrames = trimEnd - trimStart;
      if (trimFrames < 4) continue;

      final noteStart = (note.startBeat * msPerBeat * sampleRate / 1000.0)
          .round();
      final sustainSamples = math.max(
        1,
        (note.lengthBeats * msPerBeat * sampleRate / 1000.0).round(),
      );
      final renderSamples = sustainSamples + (releaseSec * sampleRate).round();
      final holdSamples = math.max(
        2,
        (grainHoldMs * sampleRate / 1000.0).round(),
      );
      final grainAttackSamples = math.min(
        holdSamples ~/ 2,
        (grainAttackMs * sampleRate / 1000.0).round(),
      );
      final grainSpacingSamples = math.max(
        1,
        (holdSamples * grainSpacingPct / 100.0).round(),
      );
      final waveSpacingFrames = holdSamples * waveSpacingPct / 100.0;
      final playbackRate = keyMode == 0
          ? math.pow(2.0, (safePitch - rootNote) / 12.0).toDouble() *
                (sample.sampleRate / sampleRate)
          : (sample.sampleRate / sampleRate);
      final startByKey = keyMode == 1
          ? ((safePitch - rootNote).clamp(0, 24) / 24.0) * trimFrames
          : keyMode >= 2
          ? ((safePitch - rootNote).clamp(0, 31) /
                    math.max(1, (params['sliceCount'] ?? 8.0).round() - 1)) *
                trimFrames
          : 0.0;
      final transientHoldFrames = transientMode >= 1
          ? (transientHoldMs * sample.sampleRate / 1000.0)
          : 0.0;
      double peak = 0.0;
      if (normalizeSample) {
        for (int i = trimStart; i < trimEnd; i++) {
          peak = math.max(peak, sample.left[i].abs());
          peak = math.max(peak, sample.right[i].abs());
        }
      }
      final normalizeGain = normalizeSample && peak > 0.001
          ? (1.0 / peak).clamp(1.0, 12.0)
          : 1.0;

      for (int grain = 0; ; grain++) {
        final grainOutStart = noteStart + grain * grainSpacingSamples;
        if (grainOutStart >= noteStart + renderSamples) break;
        final rand =
            (hash01(note.pitch * 1009 + noteStart + grain * 917) - 0.5) * 2.0;
        final randFrames = rand * trimFrames * (randomPct / 100.0) * 0.18;
        final lfoFrames =
            trimFrames *
            (lfoDepthPct / 100.0) *
            0.5 *
            math.sin(2.0 * math.pi * lfoSpeedHz * grainOutStart / sampleRate);
        final heldSource = positionHold ? 0.0 : grain * waveSpacingFrames;
        final sourceBase =
            trimStart +
            startByKey +
            transientHoldFrames +
            heldSource +
            randFrames +
            lfoFrames;
        final pan = (grainPan * (grain.isEven ? -1.0 : 1.0)).clamp(-0.95, 0.95);
        final leftGain = math.sqrt(0.5 * (1.0 - pan));
        final rightGain = math.sqrt(0.5 * (1.0 + pan));

        for (int i = 0; i < holdSamples; i++) {
          final outIndex = grainOutStart + i;
          if (outIndex < 0 || outIndex >= totalSamples) break;
          final noteAge = (outIndex - noteStart) / sampleRate;
          final holdSec = sustainSamples / sampleRate;
          final noteEnv = _fallbackEnvelopeLevel(
            ageSec: noteAge,
            holdSec: holdSec,
            attackSec: attackSec,
            decaySec: 0.08,
            sustainLevel: 0.92,
            releaseSec: releaseSec,
          ).clamp(0.0, 1.0);
          if (noteEnv <= 0.0) continue;

          final fadeIn = grainAttackSamples <= 0
              ? 1.0
              : (i / grainAttackSamples).clamp(0.0, 1.0);
          final fadeOut = grainAttackSamples <= 0
              ? 1.0
              : ((holdSamples - i) / grainAttackSamples).clamp(0.0, 1.0);
          final grainEnv = math.sin(math.pi * math.min(fadeIn, fadeOut) * 0.5);

          var pos = sourceBase + (i * playbackRate);
          if (loopGrains) {
            pos = trimStart + ((pos - trimStart) % trimFrames);
            if (pos < trimStart) pos += trimFrames;
          } else if (pos < trimStart || pos >= trimEnd - 1) {
            continue;
          }
          final readPos = reverseSample
              ? (trimEnd - 1) - (pos - trimStart)
              : pos;
          final baseIndex = readPos
              .floor()
              .clamp(trimStart, trimEnd - 1)
              .toInt();
          final nextIndex = reverseSample
              ? math.max(baseIndex - 1, trimStart)
              : math.min(baseIndex + 1, trimEnd - 1);
          final frac = (readPos - baseIndex).clamp(0.0, 1.0);
          var l =
              sample.left[baseIndex] * (1.0 - frac) +
              sample.left[nextIndex] * frac;
          var r =
              sample.right[baseIndex] * (1.0 - frac) +
              sample.right[nextIndex] * frac;
          if (filterCutoff < 19500.0) {
            final prevIndex = math.max(baseIndex - 1, trimStart);
            final nextSmoothIndex = math.min(baseIndex + 1, trimEnd - 1);
            final alpha = (filterCutoff / 20000.0).clamp(0.0, 1.0);
            final smoothL =
                (sample.left[prevIndex] + l + sample.left[nextSmoothIndex]) /
                3.0;
            final smoothR =
                (sample.right[prevIndex] + r + sample.right[nextSmoothIndex]) /
                3.0;
            l = smoothL + ((l - smoothL) * alpha);
            r = smoothR + ((r - smoothR) * alpha);
          }
          final gain =
              safeVelocity * outputGain * normalizeGain * noteEnv * grainEnv;
          left[outIndex] += (l * gain * leftGain).toDouble();
          right[outIndex] += (r * gain * rightGain).toDouble();
        }
      }
    }

    double peak = 0.0;
    for (int i = 0; i < totalSamples; i++) {
      peak = math.max(peak, left[i].abs());
      peak = math.max(peak, right[i].abs());
    }
    final normalizeGain = peak > 0.98 ? (0.98 / peak) : 1.0;
    for (int i = 0; i < totalSamples; i++) {
      left[i] = (left[i] * normalizeGain).clamp(-1.0, 1.0).toDouble();
      right[i] = (right[i] * normalizeGain).clamp(-1.0, 1.0).toDouble();
    }
    await _writeStereoPcm16Wav(
      path: outFile.path,
      sampleRate: sampleRate.toInt(),
      left: left,
      right: right,
    );
    return true;
  }

  Future<bool> _renderInstrumentClipWithSfz({
    required File outFile,
    required String instrumentId,
    required List<MidiNote> notes,
    required Map<String, double> params,
    required double bpm,
    double minimumDurationMs = 1200.0,
  }) async {
    final definition = await _sfzDefinitionForInstrument(instrumentId);
    if (definition == null || definition.regions.isEmpty) return false;

    const double sampleRate = 48000.0;
    final msPerBeat = 60000.0 / bpm.clamp(1.0, 400.0);
    double endBeat = 4.0;
    for (final n in notes) {
      endBeat = math.max(endBeat, n.startBeat + n.lengthBeats);
    }

    final outputGain = (params['outputGain'] ?? 0.72).clamp(0.2, 2.0);
    final attackOverrideSec = ((params['attackMs'] ?? -1.0) / 1000.0);
    final decaySec = (((params['decayMs'] ?? 120.0) / 1000.0).clamp(
      0.0,
      2.0,
    )).toDouble();
    final sustainLevel = (params['sustainLevel'] ?? 0.86)
        .clamp(0.05, 1.0)
        .toDouble();
    final releaseOverrideSec = ((params['releaseMs'] ?? -1.0) / 1000.0);
    final sampleStartNorm = (params['sampleStartNorm'] ?? 0.0)
        .clamp(0.0, 0.98)
        .toDouble();
    final sampleEndNorm = (params['sampleEndNorm'] ?? 1.0)
        .clamp(sampleStartNorm + 0.02, 1.0)
        .toDouble();
    final reverseSample = (params['reverseSample'] ?? 0.0) >= 0.5;
    final normalizeSample = (params['normalizeSample'] ?? 0.0) >= 0.5;
    final oneShotMode = (params['samplePlayMode'] ?? 0.0) >= 0.5;
    final rootNote = (params['rootNote'] ?? 60.0).round().clamp(0, 127);
    final sampleLowKey = (params['sampleLowKey'] ?? 0.0).round().clamp(0, 127);
    final sampleHighKey = (params['sampleHighKey'] ?? 127.0).round().clamp(
      sampleLowKey,
      127,
    );
    final sliceMode = (params['sliceMode'] ?? 0.0) >= 0.5;
    final sliceCount = (params['sliceCount'] ?? 8.0).round().clamp(2, 32);
    final stretchMode = (params['timeStretchMode'] ?? 0.0) >= 0.5;
    final filterCutoff = (params['sampleFilterCutoffHz'] ?? 20000.0).clamp(
      80.0,
      20000.0,
    );
    final tailSec = releaseOverrideSec > 0
        ? releaseOverrideSec
        : definition.defaultReleaseSec;
    var totalMs = math.max(
      minimumDurationMs,
      endBeat * msPerBeat + tailSec * 1000.0 + 180.0,
    );
    for (int noteIndex = 0; noteIndex < notes.length; noteIndex++) {
      final note = notes[noteIndex];
      final safePitch = _remapSampledMidiPitch(instrumentId, note.pitch);
      if (safePitch < sampleLowKey || safePitch > sampleHighKey) continue;
      final safeVelocity = note.velocity.clamp(0.0, 1.0);
      final velocityMidi = (safeVelocity * 127.0).round().clamp(0, 127);
      final region = _pickSfzRegion(
        definition,
        safePitch,
        velocityMidi,
        sequenceStep: noteIndex,
      );
      if (region == null || !oneShotMode) continue;
      final sample = await _decodedSfzSample(region.sampleAssetPath);
      if (sample == null || sample.frameCount < 2) continue;
      final playbackRate = _sfzPlaybackRate(
        sample: sample,
        region: region,
        notePitch: stretchMode ? rootNote : safePitch,
        outputSampleRate: sampleRate,
      );
      if (!playbackRate.isFinite || playbackRate <= 0.0) continue;
      final baseStart = region.sampleStartFrame
          .clamp(0, math.max(0, sample.frameCount - 1))
          .toInt();
      final baseEnd = _sfzRegionFrameLimit(region, sample);
      var sampleStartFrame =
          baseStart + ((baseEnd - baseStart - 1) * sampleStartNorm).round();
      var sampleEndFrameExclusive =
          baseStart + ((baseEnd - baseStart) * sampleEndNorm).round();
      sampleEndFrameExclusive = sampleEndFrameExclusive
          .clamp(sampleStartFrame + 1, baseEnd)
          .toInt();
      if (sliceMode) {
        final sliceIndex = (safePitch - rootNote).clamp(0, sliceCount - 1);
        final trimFrames = math.max(
          2,
          sampleEndFrameExclusive - sampleStartFrame,
        );
        final sliceStart =
            sampleStartFrame + (trimFrames * sliceIndex / sliceCount).floor();
        final sliceEnd =
            sampleStartFrame +
            (trimFrames * (sliceIndex + 1) / sliceCount).floor();
        sampleStartFrame = sliceStart
            .clamp(sampleStartFrame, sampleEndFrameExclusive - 1)
            .toInt();
        sampleEndFrameExclusive = sliceEnd
            .clamp(sampleStartFrame + 1, sampleEndFrameExclusive)
            .toInt();
      }
      final usableFrames = sampleEndFrameExclusive - sampleStartFrame;
      if (usableFrames < 2) continue;
      final sampleMs =
          ((usableFrames - 1) / playbackRate) * 1000.0 / sampleRate;
      totalMs = math.max(
        totalMs,
        note.startBeat * msPerBeat + sampleMs + 180.0,
      );
    }
    final totalSamples = math.max(2048, (totalMs * sampleRate / 1000.0).ceil());
    final left = Float32List(totalSamples);
    final right = Float32List(totalSamples);

    for (int noteIndex = 0; noteIndex < notes.length; noteIndex++) {
      final note = notes[noteIndex];
      final safePitch = _remapSampledMidiPitch(instrumentId, note.pitch);
      if (safePitch < sampleLowKey || safePitch > sampleHighKey) continue;
      final safeVelocity = note.velocity.clamp(0.0, 1.0);
      final velocityMidi = (safeVelocity * 127.0).round().clamp(0, 127);
      final region = _pickSfzRegion(
        definition,
        safePitch,
        velocityMidi,
        sequenceStep: noteIndex,
      );
      if (region == null) continue;
      final sample = await _decodedSfzSample(region.sampleAssetPath);
      if (sample == null || sample.frameCount < 2) continue;

      final baseStart = region.sampleStartFrame
          .clamp(0, math.max(0, sample.frameCount - 1))
          .toInt();
      final baseEnd = _sfzRegionFrameLimit(region, sample);
      var sampleStartFrame =
          baseStart + ((baseEnd - baseStart - 1) * sampleStartNorm).round();
      var sampleEndFrameExclusive =
          baseStart + ((baseEnd - baseStart) * sampleEndNorm).round();
      sampleEndFrameExclusive = sampleEndFrameExclusive
          .clamp(sampleStartFrame + 1, baseEnd)
          .toInt();
      if (sliceMode) {
        final sliceIndex = (safePitch - rootNote).clamp(0, sliceCount - 1);
        final trimFrames = math.max(
          2,
          sampleEndFrameExclusive - sampleStartFrame,
        );
        final sliceStart =
            sampleStartFrame + (trimFrames * sliceIndex / sliceCount).floor();
        final sliceEnd =
            sampleStartFrame +
            (trimFrames * (sliceIndex + 1) / sliceCount).floor();
        sampleStartFrame = sliceStart
            .clamp(sampleStartFrame, sampleEndFrameExclusive - 1)
            .toInt();
        sampleEndFrameExclusive = sliceEnd
            .clamp(sampleStartFrame + 1, sampleEndFrameExclusive)
            .toInt();
      }
      final usableFrames = sampleEndFrameExclusive - sampleStartFrame;
      if (usableFrames < 2) continue;

      final noteStart = (note.startBeat * msPerBeat * sampleRate / 1000.0)
          .round();
      final sustainSamples = math.max(
        1,
        (note.lengthBeats * msPerBeat * sampleRate / 1000.0).round(),
      );
      final attackSec = attackOverrideSec > 0
          ? attackOverrideSec
          : region.attackSec.clamp(0.0, 2.0);
      final releaseSec = releaseOverrideSec > 0
          ? releaseOverrideSec
          : region.releaseSec.clamp(0.02, 12.0);
      final releaseSamples = math.max(1, (releaseSec * sampleRate).round());
      final playbackRate = _sfzPlaybackRate(
        sample: sample,
        region: region,
        notePitch: stretchMode ? rootNote : safePitch,
        outputSampleRate: sampleRate,
      );
      if (!playbackRate.isFinite || playbackRate <= 0.0) continue;
      final sampleLimitedDurationSamples = math.max(
        1,
        ((usableFrames - 1) / playbackRate).ceil(),
      );
      final totalNoteSamples = oneShotMode
          ? sampleLimitedDurationSamples
          : sustainSamples + releaseSamples;

      double samplePos = sampleStartFrame.toDouble();
      double peak = 0.0;
      if (normalizeSample) {
        for (int i = sampleStartFrame; i < sampleEndFrameExclusive; i++) {
          peak = math.max(peak, sample.left[i].abs());
          peak = math.max(peak, sample.right[i].abs());
        }
      }
      final sampleNormalizeGain = normalizeSample && peak > 0.001
          ? (1.0 / peak).clamp(1.0, 12.0)
          : 1.0;
      final noteGain =
          safeVelocity * region.gainLinear * outputGain * sampleNormalizeGain;
      for (int i = 0; i < totalNoteSamples; i++) {
        final idx = noteStart + i;
        if (idx < 0 || idx >= totalSamples) break;
        if (samplePos >= sampleEndFrameExclusive - 1) break;

        final ageSec = i / sampleRate;
        final holdSec = sustainSamples / sampleRate;
        double env = _fallbackEnvelopeLevel(
          ageSec: ageSec,
          holdSec: holdSec,
          attackSec: attackSec,
          decaySec: decaySec,
          sustainLevel: sustainLevel,
          releaseSec: releaseSec,
        );
        env = env.clamp(0.0, 1.0);
        if (env <= 0.0) {
          samplePos += playbackRate;
          continue;
        }

        final readPos = reverseSample
            ? (sampleEndFrameExclusive - 1) -
                  (samplePos - sampleStartFrame.toDouble())
            : samplePos;
        final baseIndex = readPos
            .floor()
            .clamp(sampleStartFrame, sampleEndFrameExclusive - 1)
            .toInt();
        final frac = readPos - baseIndex;
        final nextIndex = reverseSample
            ? math.max(baseIndex - 1, sampleStartFrame)
            : math.min(baseIndex + 1, sampleEndFrameExclusive - 1);
        var l =
            sample.left[baseIndex] * (1.0 - frac) +
            sample.left[nextIndex] * frac;
        var r =
            sample.right[baseIndex] * (1.0 - frac) +
            sample.right[nextIndex] * frac;
        if (filterCutoff < 19500.0) {
          final prevIndex = math.max(baseIndex - 1, sampleStartFrame);
          final nextSmoothIndex = math.min(
            baseIndex + 1,
            sampleEndFrameExclusive - 1,
          );
          final alpha = (filterCutoff / 20000.0).clamp(0.0, 1.0);
          final smoothL =
              (sample.left[prevIndex] + l + sample.left[nextSmoothIndex]) / 3.0;
          final smoothR =
              (sample.right[prevIndex] + r + sample.right[nextSmoothIndex]) /
              3.0;
          l = smoothL + ((l - smoothL) * alpha);
          r = smoothR + ((r - smoothR) * alpha);
        }

        left[idx] += (l * env * noteGain).toDouble();
        right[idx] += (r * env * noteGain).toDouble();
        samplePos += playbackRate;
      }
    }

    double peak = 0.0;
    for (int i = 0; i < totalSamples; i++) {
      peak = math.max(peak, left[i].abs());
      peak = math.max(peak, right[i].abs());
    }
    final normalizeGain = peak > 0.98 ? (0.98 / peak) : 1.0;
    for (int i = 0; i < totalSamples; i++) {
      left[i] = (left[i] * normalizeGain).clamp(-1.0, 1.0).toDouble();
      right[i] = (right[i] * normalizeGain).clamp(-1.0, 1.0).toDouble();
    }

    await _writeStereoPcm16Wav(
      path: outFile.path,
      sampleRate: sampleRate.toInt(),
      left: left,
      right: right,
    );
    return true;
  }

  Future<bool> _renderInstrumentClipToFile({
    required File outFile,
    required String instrumentId,
    required String instrumentName,
    required List<MidiNote> notes,
    required Map<String, double> params,
  }) async {
    final normalizedParams = _normalizedInstrumentParamsForPlayback(
      instrumentId,
      params,
    );
    if (!await outFile.parent.exists()) {
      await outFile.parent.create(recursive: true);
    }

    final noteMaps = notes
        .map(
          (n) => {
            'id': n.id,
            'pitch': n.pitch,
            'startBeat': n.startBeat,
            'lengthBeats': n.lengthBeats,
            'velocity': n.velocity,
          },
        )
        .toList();

    try {
      if (_isSampledInstrumentId(instrumentId)) {
        if (_isGranularizerParams(normalizedParams)) {
          try {
            final renderedWithGranularizer =
                await _renderInstrumentClipWithGranularizer(
                  outFile: outFile,
                  instrumentId: instrumentId,
                  notes: notes,
                  params: normalizedParams,
                  bpm: _tempo,
                );
            if (renderedWithGranularizer && outFile.existsSync()) {
              return true;
            }
          } catch (e, st) {
            debugPrint('Granularizer render failed, falling back: $e\n$st');
          }
        }
        try {
          final renderedWithSfz = await _renderInstrumentClipWithSfz(
            outFile: outFile,
            instrumentId: instrumentId,
            notes: notes,
            params: normalizedParams,
            bpm: _tempo,
          );
          if (renderedWithSfz && outFile.existsSync()) {
            return true;
          }
        } catch (e, st) {
          debugPrint('SFZ render failed, falling back: $e\n$st');
        }

        if (_kAllowSampledNativeRenderFallbackForBeta && Platform.isAndroid) {
          try {
            final engineInstrumentId = _liveMidiEngineInstrumentId(
              instrumentId,
            );
            final renderedPath = await JuceAudioEngine.renderInstrumentClip(
              outPath: outFile.path,
              instrumentId: engineInstrumentId,
              instrumentName: instrumentName,
              bpm: _tempo,
              notes: noteMaps,
              params: normalizedParams,
            );
            if (renderedPath.isNotEmpty && File(renderedPath).existsSync()) {
              return true;
            }
          } catch (e, st) {
            debugPrint('Native sampled render failed, falling back: $e\n$st');
          }
        }
      } else {
        try {
          final engineInstrumentId = _liveMidiEngineInstrumentId(instrumentId);
          final renderedPath = await JuceAudioEngine.renderInstrumentClip(
            outPath: outFile.path,
            instrumentId: engineInstrumentId,
            instrumentName: instrumentName,
            bpm: _tempo,
            notes: noteMaps,
            params: normalizedParams,
          );

          if (renderedPath.isNotEmpty && File(renderedPath).existsSync()) {
            return true;
          }
        } catch (e, st) {
          debugPrint('Native synth render failed, falling back: $e\n$st');
        }
      }

      await _renderInstrumentClipWithDartSynth(
        outFile: outFile,
        instrumentId: instrumentId,
        instrumentName: instrumentName,
        notes: notes,
        params: normalizedParams,
        bpm: _tempo,
      );
      return outFile.existsSync();
    } catch (e, st) {
      debugPrint('Instrument clip render failed completely: $e\n$st');
      return false;
    }
  }

  Future<void> _renderInstrumentClipWithDartSynth({
    required File outFile,
    required String instrumentId,
    required String instrumentName,
    required List<MidiNote> notes,
    required Map<String, double> params,
    required double bpm,
    double minimumDurationMs = 1200.0,
  }) async {
    const double sampleRate = 48000.0;
    final msPerBeat = 60000.0 / bpm.clamp(1.0, 400.0);
    final preset = _fallbackPresetForInstrument(
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      params: params,
    );

    double endBeat = 4.0;
    for (final n in notes) {
      endBeat = math.max(endBeat, n.startBeat + n.lengthBeats);
    }

    final totalMs = math.max(
      minimumDurationMs,
      endBeat * msPerBeat + preset.releaseMs + 120.0,
    );
    final totalSamples = math.max(2048, (totalMs * sampleRate / 1000.0).ceil());
    final left = Float32List(totalSamples);
    final right = Float32List(totalSamples);

    final cleanedNotes = notes
        .map(
          (n) => MidiNote(
            id: n.id,
            pitch: n.pitch.clamp(0, 127).toInt(),
            startBeat: math.max(0.0, n.startBeat),
            lengthBeats: math.max(0.0625, n.lengthBeats),
            velocity: n.velocity.clamp(0.0, 1.0).toDouble(),
          ),
        )
        .toList(growable: false);

    for (final note in cleanedNotes) {
      final noteStart = (note.startBeat * msPerBeat * sampleRate / 1000.0)
          .round();
      final sustainSamples = math.max(
        1,
        (note.lengthBeats * msPerBeat * sampleRate / 1000.0).round(),
      );
      final attackSamples = math.max(
        1,
        (preset.attackMs * sampleRate / 1000.0).round(),
      );
      final decaySamples = math.max(
        1,
        (preset.decayMs * sampleRate / 1000.0).round(),
      );
      final releaseSamples = math.max(
        1,
        (preset.releaseMs * sampleRate / 1000.0).round(),
      );
      final totalNoteSamples = sustainSamples + releaseSamples;
      final freq = 440.0 * math.pow(2.0, (note.pitch - 69) / 12.0);
      final seed = note.pitch * 97 + noteStart * 7 + totalNoteSamples * 13;
      final state = _FallbackNoteState(
        phaseA: _wrapUnitPhase(((note.pitch * 19) % 100) / 100.0),
        phaseB: _wrapUnitPhase(((note.pitch * 37) % 100) / 100.0),
        seed: seed,
      );
      final pan = _clampDouble(
        math.sin(note.pitch * 0.23 + seed * 0.013) * preset.stereoWidth,
        -0.95,
        0.95,
      );
      final leftGain = math.sqrt(0.5 * (1.0 - pan));
      final rightGain = math.sqrt(0.5 * (1.0 + pan));

      for (int i = 0; i < totalNoteSamples; i++) {
        final idx = noteStart + i;
        if (idx < 0 || idx >= left.length) break;

        double env = _fallbackEnvelopeLevel(
          ageSec: i / sampleRate,
          holdSec: sustainSamples / sampleRate,
          attackSec: attackSamples / sampleRate,
          decaySec: decaySamples / sampleRate,
          sustainLevel: preset.sustainLevel,
          releaseSec: releaseSamples / sampleRate,
        );
        env = env.clamp(0.0, 1.0);
        final noteProgress = totalNoteSamples <= 1
            ? 1.0
            : (i / (totalNoteSamples - 1)).clamp(0.0, 1.0).toDouble();
        final raw = _renderFallbackRawSample(
          preset: preset,
          state: state,
          pitch: note.pitch,
          noteSampleIndex: i,
          frequencyHz: freq.toDouble(),
          noteProgress: noteProgress,
          envelope: env,
          sampleRate: sampleRate,
        );

        final drivenInput = (1.0 + preset.drive * 5.0) * raw;
        final driven = drivenInput / (1.0 + drivenInput.abs());
        final sample = driven * env * note.velocity * preset.outputGain;
        left[idx] += (sample * leftGain).toDouble();
        right[idx] += (sample * rightGain).toDouble();
      }
    }

    double peak = 0.0;
    for (int i = 0; i < left.length; i++) {
      final a = left[i].abs();
      final b = right[i].abs();
      if (a > peak) peak = a;
      if (b > peak) peak = b;
    }
    final norm = peak > 0.98 ? (0.98 / peak) : 1.0;
    for (int i = 0; i < left.length; i++) {
      left[i] = (left[i] * norm).clamp(-1.0, 1.0).toDouble();
      right[i] = (right[i] * norm).clamp(-1.0, 1.0).toDouble();
    }

    await _writeStereoPcm16Wav(
      path: outFile.path,
      sampleRate: sampleRate.toInt(),
      left: left,
      right: right,
    );
  }

  Future<void> _writeStereoPcm16Wav({
    required String path,
    required int sampleRate,
    required Float32List left,
    required Float32List right,
  }) async {
    final frameCount = math.min(left.length, right.length);
    const int channels = 2;
    const int bitsPerSample = 16;
    const int bytesPerSample = bitsPerSample ~/ 8;
    final dataSize = frameCount * channels * bytesPerSample;
    final totalSize = 44 + dataSize;
    final bytes = Uint8List(totalSize);
    final bd = ByteData.view(bytes.buffer);

    void writeAscii(int offset, String s) {
      for (int i = 0; i < s.length; i++) {
        bd.setUint8(offset + i, s.codeUnitAt(i));
      }
    }

    writeAscii(0, 'RIFF');
    bd.setUint32(4, 36 + dataSize, Endian.little);
    writeAscii(8, 'WAVE');
    writeAscii(12, 'fmt ');
    bd.setUint32(16, 16, Endian.little); // PCM chunk size
    bd.setUint16(20, 1, Endian.little); // PCM format
    bd.setUint16(22, channels, Endian.little);
    bd.setUint32(24, sampleRate, Endian.little);
    bd.setUint32(28, sampleRate * channels * bytesPerSample, Endian.little);
    bd.setUint16(32, channels * bytesPerSample, Endian.little);
    bd.setUint16(34, bitsPerSample, Endian.little);
    writeAscii(36, 'data');
    bd.setUint32(40, dataSize, Endian.little);

    int ptr = 44;
    for (int i = 0; i < frameCount; i++) {
      final l = (left[i].clamp(-1.0, 1.0) * 32767.0).round();
      final r = (right[i].clamp(-1.0, 1.0) * 32767.0).round();
      bd.setInt16(ptr, l, Endian.little);
      bd.setInt16(ptr + 2, r, Endian.little);
      ptr += 4;
    }

    await File(path).writeAsBytes(bytes, flush: true);
  }

  List<Map<String, dynamic>> _midiNotesToEnginePayload(List<MidiNote> notes) {
    return notes
        .map(
          (n) => <String, dynamic>{
            'id': n.id,
            'pitch': n.pitch,
            'startBeat': n.startBeat,
            'lengthBeats': n.lengthBeats,
            'velocity': n.velocity,
          },
        )
        .toList();
  }

  String _liveMidiEngineInstrumentId(String instrumentId) {
    final id = instrumentId.trim();
    if (id.toLowerCase().startsWith('sfz_asset:')) {
      return id;
    }
    final aliasAssetPath = _sampledAliasAssetPathForInstrumentId(id);
    if (aliasAssetPath != null && aliasAssetPath.isNotEmpty) {
      return 'sfz_asset:$aliasAssetPath';
    }
    final spec = _findInstrumentSpecById(id);
    if (spec != null && _isSampledInstrumentSpec(spec)) {
      final sfzAssetPath = (spec['sfzAssetPath'] as String?)?.trim() ?? '';
      if (sfzAssetPath.isNotEmpty) {
        return 'sfz_asset:$sfzAssetPath';
      }
    }
    return id;
  }

  Future<bool> _loadMidiClipIntoEngineLive({
    required int engineClipId,
    required int rowId,
    required String instrumentId,
    required String instrumentName,
    required List<MidiNote> midiNotes,
    required Map<String, double> instrumentParams,
    required double sourceTempoBpm,
    required double startSec,
    required double lengthSec,
    required double inFileOffsetSec,
  }) async {
    if (!_liveMidiEventPlaybackSupported) return false;
    if (engineClipId < 0 || rowId < 0) return false;
    final liveInstrumentId = _liveMidiEngineInstrumentId(instrumentId);
    if (_instrumentIdUsesExternalPlugin(liveInstrumentId) &&
        await JuceAudioEngine.isPluginQuarantined(liveInstrumentId)) {
      return false;
    }
    final normalizedParams = _normalizedInstrumentParamsForPlayback(
      instrumentId,
      instrumentParams,
    );
    final loadRequestId = ++_nextMidiClipLoadRequestId;
    final loaded = await runTimedNativeOperation<bool>(
      'MIDI instrument load $liveInstrumentId '
      'clip=$engineClipId request=$loadRequestId',
      () => _runWithAndroidEngineCriticalSection(
        () => JuceAudioEngine.loadMidiClip(
          engineClipId,
          rowId,
          instrumentId: liveInstrumentId,
          instrumentName: instrumentName,
          notes: _midiNotesToEnginePayload(midiNotes),
          params: normalizedParams,
          sourceTempoBpm: sourceTempoBpm,
          startSec: startSec,
          lengthSec: math.max(0.0, lengthSec),
          inFileOffsetSec: math.max(0.0, inFileOffsetSec),
          loadRequestId: loadRequestId,
        ),
      ),
      timeout: _kProjectPluginInstanceRestoreTimeout,
      onTimeout: () {
        // Cancellation must not extend the user-visible timeout if the native
        // message thread is the component that is stalled.
        unawaited(
          JuceAudioEngine.cancelMidiClipLoad(
            clipIndex: engineClipId,
            loadRequestId: loadRequestId,
          ),
        );
      },
    );
    return loaded ?? false;
  }

  Future<bool> _updateMidiClipEventsLive(AudioTrack clip) async {
    if (!_liveMidiEventPlaybackSupported) return false;
    if (!clip.isMidi || clip.engineClipId < 0) return false;
    final liveInstrumentId = _liveMidiEngineInstrumentId(clip.instrumentId);
    final normalizedParams = _normalizedInstrumentParamsForPlayback(
      clip.instrumentId,
      clip.instrumentParams,
    );
    return _runWithAndroidEngineCriticalSection(
      () => JuceAudioEngine.updateMidiClipEvents(
        clip.engineClipId,
        instrumentId: liveInstrumentId,
        instrumentName: clip.instrumentName,
        notes: _midiNotesToEnginePayload(clip.midiNotes),
        params: normalizedParams,
        sourceTempoBpm: _resolvedClipSourceTempoBpm(clip),
      ),
    );
  }

  bool _instrumentIdUsesExternalPlugin(String instrumentId) {
    if (PlatformCapabilities.current.isDesktop &&
        _platformCapabilities.externalPluginHosting &&
        _looksLikeDesktopHostedPluginId(instrumentId)) {
      return true;
    }
    final spec = _findInstrumentSpecById(instrumentId);
    if (spec == null) return false;
    return _isExternalPluginInstrumentSpec(spec);
  }

  bool _clipUsesExternalPluginInstrument(AudioTrack clip) {
    if (!clip.isMidi) return false;
    return _instrumentIdUsesExternalPlugin(clip.instrumentId);
  }

  bool get _hostedInstrumentStatePersistenceSupported =>
      PlatformCapabilities.current.isDesktop &&
      _platformCapabilities.externalPluginHosting &&
      _liveMidiEventPlaybackSupported;

  void _assignMidiClipInstrument(
    AudioTrack clip, {
    required String instrumentId,
    required String instrumentName,
    required Map<String, double> instrumentParams,
    bool syncLaneMetadata = true,
  }) {
    final previousLiveInstrumentId = _liveMidiEngineInstrumentId(
      clip.instrumentId,
    );
    final nextLiveInstrumentId = _liveMidiEngineInstrumentId(instrumentId);
    final preserveHostedState =
        _instrumentIdUsesExternalPlugin(clip.instrumentId) &&
        _instrumentIdUsesExternalPlugin(instrumentId) &&
        previousLiveInstrumentId == nextLiveInstrumentId;

    clip.instrumentId = instrumentId;
    clip.instrumentName = instrumentName;
    clip.instrumentParams = Map<String, double>.from(instrumentParams);
    if (!preserveHostedState) {
      clip.hostedInstrumentStateBase64 = '';
    }
    if (syncLaneMetadata) {
      _syncInstrumentLaneMetadataFromMidiClip(clip);
    }
  }

  void _syncInstrumentLaneMetadataFromMidiClip(AudioTrack clip) {
    if (!clip.isMidi) return;
    final row = clip.rowIndex;
    if (row < 0 || row >= _rows.length) return;
    final lane = _rows[row];
    if (!lane.isInstrumentLane) return;
    final nextName = clip.instrumentName.trim().isEmpty
        ? _instrumentNameFromId(clip.instrumentId)
        : clip.instrumentName.trim();
    if (lane.instrumentId == clip.instrumentId &&
        lane.instrumentName == nextName &&
        _doubleMapsEqual(lane.instrumentParams, clip.instrumentParams)) {
      return;
    }
    _rows[row] = lane.copyWith(
      name: nextName.isEmpty ? lane.name : nextName,
      iconId: 1,
      instrumentId: clip.instrumentId,
      instrumentName: nextName,
      instrumentParams: Map<String, double>.from(clip.instrumentParams),
    );
    if (lane.rowId >= 0 && nextName.isNotEmpty && lane.name != nextName) {
      unawaited(JuceAudioEngine.renameRow(lane.rowId, nextName));
    }
  }

  String _nextHostedInstrumentStateForEdit(
    AudioTrack clip, {
    required String instrumentId,
    String? currentStateBase64,
  }) {
    final currentState =
        (currentStateBase64 ?? clip.hostedInstrumentStateBase64).trim();
    if (currentState.isEmpty) return '';
    if (!_instrumentIdUsesExternalPlugin(clip.instrumentId) ||
        !_instrumentIdUsesExternalPlugin(instrumentId)) {
      return '';
    }
    return _liveMidiEngineInstrumentId(clip.instrumentId) ==
            _liveMidiEngineInstrumentId(instrumentId)
        ? currentState
        : '';
  }

  Future<String> _captureHostedInstrumentStateForClip(AudioTrack clip) async {
    if (!_hostedInstrumentStatePersistenceSupported ||
        !_clipUsesExternalPluginInstrument(clip) ||
        clip.engineClipId < 0) {
      return clip.hostedInstrumentStateBase64;
    }

    final state = await _runWithAndroidEngineCriticalSection(
      () => JuceAudioEngine.getMidiClipPluginState(clip.engineClipId),
    );
    final trimmed = state.trim();
    if (trimmed.isEmpty && clip.hostedInstrumentStateBase64.trim().isNotEmpty) {
      final existing = clip.hostedInstrumentStateBase64.trim();
      _syncHostedInstrumentStateToLane(clip, existing);
      return existing;
    }
    clip.hostedInstrumentStateBase64 = trimmed;
    _syncHostedInstrumentStateToLane(clip, trimmed);
    return clip.hostedInstrumentStateBase64;
  }

  void _syncHostedInstrumentStateToLane(AudioTrack clip, String stateBase64) {
    final trimmed = stateBase64.trim();
    if (trimmed.isEmpty || !clip.isMidi) return;
    final row = clip.rowId >= 0 ? _rowIndexForId(clip.rowId) : clip.rowIndex;
    if (row < 0 || row >= _rows.length) return;
    final lane = _rows[row];
    if (!lane.isInstrumentLane) return;
    if (!_instrumentIdUsesExternalPlugin(lane.instrumentId)) return;
    if (_liveMidiEngineInstrumentId(clip.instrumentId) !=
        _liveMidiEngineInstrumentId(lane.instrumentId)) {
      return;
    }
    if (lane.hostedInstrumentStateBase64.trim() == trimmed) return;
    _rows[row] = lane.copyWith(hostedInstrumentStateBase64: trimmed);
  }

  Future<bool> _applyHostedInstrumentStateToClip(
    AudioTrack clip,
    String stateBase64,
  ) async {
    final trimmed = stateBase64.trim();
    clip.hostedInstrumentStateBase64 = trimmed;
    _syncHostedInstrumentStateToLane(clip, trimmed);

    if (trimmed.isEmpty) {
      return true;
    }
    if (!_hostedInstrumentStatePersistenceSupported ||
        !_clipUsesExternalPluginInstrument(clip) ||
        clip.engineClipId < 0) {
      return false;
    }

    final applied = await runTimedNativeOperation<bool>(
      'MIDI instrument state ${clip.instrumentId} clip=${clip.engineClipId}',
      () => _runWithAndroidEngineCriticalSection(
        () => JuceAudioEngine.setMidiClipPluginState(
          clip.engineClipId,
          stateBase64: trimmed,
        ),
      ),
      timeout: _kProjectPluginStateRestoreTimeout,
    );
    return applied ?? false;
  }

  Future<void> _restoreHostedInstrumentStateForInteractiveUse(
    AudioTrack clip,
  ) async {
    if (_isProjectLoading ||
        !_hostedInstrumentStatePersistenceSupported ||
        !_clipUsesExternalPluginInstrument(clip) ||
        clip.engineClipId < 0) {
      return;
    }

    final stateBase64 = clip.hostedInstrumentStateBase64.trim();
    if (stateBase64.isEmpty) return;
    if (_restoredHostedInstrumentStateByClipId[clip.engineClipId] ==
        stateBase64) {
      return;
    }

    try {
      final applied = await _applyHostedInstrumentStateToClip(
        clip,
        stateBase64,
      );
      if (applied) {
        _restoredHostedInstrumentStateByClipId[clip.engineClipId] = stateBase64;
      }
    } catch (e, st) {
      debugPrint(
        'Hosted instrument state restore failed for clip '
        '${clip.engineClipId}: $e\n$st',
      );
    }
  }

  Future<void> _refreshHostedInstrumentStatesForPersistence({
    bool captureAll = true,
  }) async {
    if (!_hostedInstrumentStatePersistenceSupported) return;

    Iterable<AudioTrack> clipsToCapture = _audioTracks;
    if (!captureAll) {
      final activeClipId = _activeMidiClipEngineId;
      if (activeClipId == null || activeClipId < 0) return;
      _ensureClipOperationIndexes();
      final activeClip = _clipByEngineId[activeClipId];
      if (activeClip == null) return;
      clipsToCapture = <AudioTrack>[activeClip];
    }

    for (final clip in clipsToCapture) {
      if (!clip.isMidi) continue;
      if (!_clipUsesExternalPluginInstrument(clip) || clip.engineClipId < 0) {
        clip.hostedInstrumentStateBase64 = '';
        continue;
      }
      try {
        await _captureHostedInstrumentStateForClip(clip);
      } catch (e, st) {
        debugPrint(
          'Hosted instrument state capture failed for clip '
          '${clip.engineClipId}: $e\n$st',
        );
      }
    }

    if (!captureAll) return;

    for (int row = 0; row < _rows.length; row++) {
      final lane = _rows[row];
      if (!lane.isInstrumentLane ||
          !_instrumentIdUsesExternalPlugin(lane.instrumentId)) {
        if (lane.hostedInstrumentStateBase64.trim().isNotEmpty) {
          _rows[row] = lane.copyWith(hostedInstrumentStateBase64: '');
        }
        continue;
      }

      String stateBase64 = lane.hostedInstrumentStateBase64.trim();
      final laneClips = lane.rowId >= 0
          ? _clipsForFadeResolution(rowIds: <int>{lane.rowId})
          : _audioTracks.where((clip) => clip.rowIndex == row);
      for (final clip in laneClips) {
        if (!clip.isMidi) continue;
        if (clip.rowIndex != row && clip.rowId != lane.rowId) continue;
        if (!_clipUsesExternalPluginInstrument(clip)) continue;
        if (_liveMidiEngineInstrumentId(clip.instrumentId) !=
            _liveMidiEngineInstrumentId(lane.instrumentId)) {
          continue;
        }
        final clipState = clip.hostedInstrumentStateBase64.trim();
        if (clipState.isEmpty) continue;
        stateBase64 = clipState;
        break;
      }

      if (stateBase64 != lane.hostedInstrumentStateBase64.trim()) {
        _rows[row] = lane.copyWith(hostedInstrumentStateBase64: stateBase64);
      }
    }
  }

  Future<bool> _openMidiClipPluginEditor(AudioTrack clip) async {
    if (!PlatformCapabilities.current.isDesktop ||
        !_platformCapabilities.nativePluginEditor ||
        !_clipUsesExternalPluginInstrument(clip) ||
        clip.engineClipId < 0) {
      return false;
    }
    if (_isProjectLoading) return false;
    final pending = _midiClipEngineRefreshChains[clip.engineClipId];
    if (pending != null) {
      try {
        await pending;
      } catch (_) {}
    }
    await Future<void>.delayed(const Duration(milliseconds: 60));
    if (_isProjectLoading || !mounted || !_audioTracks.contains(clip)) {
      return false;
    }
    if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
      final liveReady = await _ensureLiveMidiClipReadyForPreview(clip);
      if (!liveReady) return false;
      if (_isProjectLoading || !mounted || !_audioTracks.contains(clip)) {
        return false;
      }
      _activeMidiClipEngineId = clip.engineClipId;
      await _setLiveMidiInputTargetClipIfNeeded(
        clip.engineClipId,
        clearPendingEvents: false,
      );
    }
    await _restoreHostedInstrumentStateForInteractiveUse(clip);
    if (_isProjectLoading || !mounted || !_audioTracks.contains(clip)) {
      return false;
    }
    for (int attempt = 0; attempt < 18; attempt++) {
      if (!mounted || _isProjectLoading || !_audioTracks.contains(clip)) {
        return false;
      }
      final opened = await _runWithAndroidEngineCriticalSection(
        () => JuceAudioEngine.openMidiClipPluginEditor(clip.engineClipId),
      );
      if (opened) {
        return true;
      }
      await Future<void>.delayed(const Duration(milliseconds: 120));
    }
    return false;
  }

  bool _canOpenMidiInstrumentUiForClipIndex(int clipIndex) {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return false;
    final clip = _audioTracks[clipIndex];
    return PlatformCapabilities.current.isDesktop &&
        _platformCapabilities.nativePluginEditor &&
        clip.isMidi &&
        _clipUsesExternalPluginInstrument(clip) &&
        clip.engineClipId >= 0;
  }

  Future<bool> _openMidiInstrumentUiForClipIndex(int clipIndex) async {
    if (!_canOpenMidiInstrumentUiForClipIndex(clipIndex)) return false;
    return _openMidiClipPluginEditor(_audioTracks[clipIndex]);
  }

  Future<void> _openMidiClipPluginEditorAfterRefresh(AudioTrack clip) async {
    if (_isProjectLoading) return;
    final pending = _midiClipEngineRefreshChains[clip.engineClipId];
    if (pending != null) {
      try {
        await pending;
      } catch (_) {}
    }
    if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
      await _setLiveMidiInputTargetClipIfNeeded(clip.engineClipId);
    }
    await Future<void>.delayed(const Duration(milliseconds: 120));
    if (!mounted || _isProjectLoading || !_audioTracks.contains(clip)) return;
    await _openMidiClipPluginEditor(clip);
  }

  Duration _estimatedMidiMaterialDuration(
    List<MidiNote> notes, {
    required double sourceTempoBpm,
    Duration minimumDuration = const Duration(milliseconds: 1),
  }) {
    final safeTempo = _clampTempo(sourceTempoBpm);
    final msPerBeat = 60000.0 / safeTempo;
    double endBeat = 0.0;
    for (final note in notes) {
      endBeat = math.max(endBeat, note.startBeat + note.lengthBeats);
    }
    final estimatedMs = math.max(
      minimumDuration.inMilliseconds.toDouble(),
      (endBeat * msPerBeat) + 120.0,
    );
    return Duration(milliseconds: estimatedMs.round());
  }

  Duration _midiTrimEndIncludingNotes(AudioTrack clip, List<MidiNote> notes) {
    if (!clip.isMidi || notes.isEmpty) return clip.trimEnd;
    final materialDuration = _estimatedMidiMaterialDuration(
      notes,
      sourceTempoBpm: _clampTempo(_tempo),
      minimumDuration: Duration.zero,
    );
    final desiredTrimEnd = clip.trimStart + materialDuration;
    if (desiredTrimEnd <= clip.trimEnd) return clip.trimEnd;
    return desiredTrimEnd;
  }

  void _setMidiClipSourceEnd(AudioTrack clip, Duration trimEnd) {
    if (!clip.isMidi) return;
    if (trimEnd <= clip.trimStart) return;
    clip.trimEnd = trimEnd;
    if (clip.audioDuration < trimEnd) {
      clip.audioDuration = trimEnd;
    }
  }

  void _applyMidiClipStateLocally(
    AudioTrack clip, {
    required List<MidiNote> notes,
    required String instrumentId,
    required String instrumentName,
    required Map<String, double> instrumentParams,
  }) {
    clip.midiNotes = notes.map((n) => n.copy()).toList(growable: false);
    _assignMidiClipInstrument(
      clip,
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      instrumentParams: instrumentParams,
    );
    clip.sourceTempoBpm = _clampTempo(_tempo);
    clip.stretchToProjectTempo = true;
    clip.tempoStretchPreservePitch = true;
    _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
  }

  void _scheduleMidiClipEngineRefresh(
    AudioTrack clip, {
    String? failureNotice,
  }) {
    if (!clip.isMidi || clip.engineClipId < 0) return;

    final clipId = clip.engineClipId;
    final token = (_midiClipEngineRefreshTokens[clipId] ?? 0) + 1;
    _midiClipEngineRefreshTokens[clipId] = token;

    final previous =
        _midiClipEngineRefreshChains[clipId] ?? Future<void>.value();

    late final Future<void> next;
    next = previous
        .catchError((_) {})
        .then((_) async {
          if (_midiClipEngineRefreshTokens[clipId] != token) return;
          if (!clip.isMidi || clip.engineClipId != clipId) return;

          final updatedLive = await _updateMidiClipEventsLive(clip);
          if (_midiClipEngineRefreshTokens[clipId] != token) return;

          if (updatedLive) {
            final clipIdx = _clipIndexForEngineId(clip.engineClipId);
            if (clipIdx >= 0) {
              await _syncClipTimingToEngine(clipIdx);
            }
            await _syncClipMixToEngine(clip);
            _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
            if (mounted) {
              setState(() {});
            }
            return;
          }

          final reloaded = await _reloadMidiTrackLive(clip);
          if (_midiClipEngineRefreshTokens[clipId] != token) return;
          if (!reloaded &&
              mounted &&
              failureNotice != null &&
              failureNotice.isNotEmpty) {
            _showSmallNotice(failureNotice);
          }
        })
        .whenComplete(() {
          if (identical(_midiClipEngineRefreshChains[clipId], next)) {
            _midiClipEngineRefreshChains.remove(clipId);
          }
        });

    _midiClipEngineRefreshChains[clipId] = next;
  }

  Future<void> _restoreDeferredHostedInstrumentLoadsDuringProjectLoad() async {
    if (_deferredHostedInstrumentEngineClipIds.isEmpty) return;
    final clipIds = Set<int>.from(_deferredHostedInstrumentEngineClipIds);
    _deferredHostedInstrumentEngineClipIds.clear();

    for (final clip in List<AudioTrack>.from(_audioTracks)) {
      if (!mounted || !_audioTracks.contains(clip)) return;
      if (!clip.isMidi || clip.engineClipId < 0) continue;
      if (!clipIds.contains(clip.engineClipId)) continue;
      if (!_clipUsesExternalPluginInstrument(clip)) continue;
      final instrumentName = clip.instrumentName.trim().isEmpty
          ? 'this instrument'
          : clip.instrumentName.trim();
      final restoreKey = _hostedMidiInstrumentRestoreKey(clip);
      _updateHostedPluginRestoreStatus(
        restoreKey,
        status: _HostedPluginRestoreStatus.loading,
        detail: 'Restoring instrument from saved project state.',
      );
      final restored = await _refreshMidiClipEngineNow(
        clip,
        failureNotice: 'Could not load $instrumentName for live MIDI playback.',
      );
      if (!mounted || !_audioTracks.contains(clip)) return;
      _updateHostedPluginRestoreStatus(
        restoreKey,
        status: restored
            ? _HostedPluginRestoreStatus.loaded
            : _HostedPluginRestoreStatus.failed,
        detail: restored
            ? 'Restored successfully.'
            : 'The instrument plugin could not be instantiated on this Mac.',
      );
      if (!restored) {
        _projectLoadIssues.add(
          _ProjectLoadIssue(
            type: _ProjectLoadIssueType.missingPlugin,
            title: 'Instrument Plugin Missing',
            detail:
                '$instrumentName (${clip.instrumentId})\nThe MIDI clip and saved plugin state were kept, but the live instrument could not be restored.',
          ),
        );
        _projectSettingsStateSetter?.call(() {});
      }
    }
  }

  Future<bool> _refreshMidiClipEngineNow(
    AudioTrack clip, {
    String? failureNotice,
  }) async {
    if (!clip.isMidi || clip.engineClipId < 0) return false;

    final clipId = clip.engineClipId;
    final token = (_midiClipEngineRefreshTokens[clipId] ?? 0) + 1;
    _midiClipEngineRefreshTokens[clipId] = token;

    final previous =
        _midiClipEngineRefreshChains[clipId] ?? Future<void>.value();
    try {
      await previous.catchError((_) {});
    } catch (_) {}

    if (!clip.isMidi || clip.engineClipId != clipId) return false;
    if (_midiClipEngineRefreshTokens[clipId] != token) return false;

    final updatedLive = await _updateMidiClipEventsLive(clip);
    if (_midiClipEngineRefreshTokens[clipId] != token) return false;

    if (updatedLive) {
      final clipIdx = _clipIndexForEngineId(clip.engineClipId);
      if (clipIdx >= 0) {
        await _syncClipTimingToEngine(clipIdx);
      }
      await _syncClipMixToEngine(clip);
      _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
      if (mounted) {
        setState(() {});
      }
      return true;
    }

    final reloaded = await _reloadMidiTrackLive(clip);
    if (_midiClipEngineRefreshTokens[clipId] != token) return false;
    if (!reloaded &&
        mounted &&
        failureNotice != null &&
        failureNotice.isNotEmpty) {
      _showSmallNotice(failureNotice);
    }
    return reloaded;
  }

  Future<void> _addMidiTrack({
    required String instrumentId,
    required String instrumentName,
    required Map<String, double> instrumentParams,
    required List<MidiNote> midiNotes,
    required int row,
    required double timeMs,
    Duration? trimStartRequested,
    Duration? trimEndRequested,
    File? renderedFile,
    String? label,
    double? gain,
    double? pitchSemitones,
    double? sourceTempoBpm,
    bool? stretchToProjectTempo,
    bool? tempoStretchPreservePitch,
    String? tempoWarpMode,
    double? crossfade,
    List<AutomationPoint>? automation,
    bool rowAlreadyEnsured = false,
    bool notifyUi = true,
    bool updateProjectDuration = true,
    bool startWaveform = true,
    bool assumeFreshEngineDefaults = false,
    bool deferHostedInstrumentStateRestore = false,
    bool deferHostedInstrumentInstantiation = false,
    String hostedInstrumentStateBase64 = '',
    String? clipId,
  }) async {
    if (_audioTracks.length >= kNumClips) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
          ),
        ),
      );
      return;
    }
    if (instrumentId.trim().isEmpty) {
      if (notifyUi && mounted) {
        _showSmallNotice('This MIDI clip is missing its instrument.');
      } else {
        _projectLoadIssues.add(
          const _ProjectLoadIssue(
            type: _ProjectLoadIssueType.missingPlugin,
            title: 'Missing MIDI Instrument',
            detail:
                'A MIDI clip in this project has no saved instrument, so it could not be restored.',
          ),
        );
      }
      return;
    }

    if (!rowAlreadyEnsured) {
      await _ensureRowIndexExists(row);
      await _ensureRowExistsForClipInsertion();
    }
    final safeRow = await _ensureInstrumentLaneForMidiClip(
      row: _rowCount == 0 ? 0 : row.clamp(0, _rowCount - 1).toInt(),
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      instrumentParams: instrumentParams,
    );
    if (safeRow < 0) return;
    final safeTimeMs = math.max(0.0, timeMs);
    final rowId = _rowIdAt(safeRow);
    final engineClipId = _allocateEngineClipId();
    if (engineClipId < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
          ),
        ),
      );
      return;
    }
    try {
      final outFile =
          renderedFile ?? await _nextInstrumentRenderFile(instrumentId);

      final requestedTrimStart = trimStartRequested ?? Duration.zero;
      final requestedInFileOffsetSec =
          requestedTrimStart.inMilliseconds / 1000.0;
      final requestedLengthSec = trimEndRequested != null
          ? math.max(
              0.0,
              (trimEndRequested - requestedTrimStart).inMilliseconds / 1000.0,
            )
          : 0.0;
      final resolvedSourceTempoBpm =
          (sourceTempoBpm != null && sourceTempoBpm > 0.0)
          ? sourceTempoBpm
          : _tempo;
      final resolvedStretchToProjectTempo = stretchToProjectTempo ?? true;
      final resolvedTempoStretchPreservePitch =
          tempoStretchPreservePitch ?? true;
      final resolvedTempoWarpMode = normalizeTempoWarpMode(tempoWarpMode);
      final startSec = safeTimeMs / 1000.0;

      final shouldDeferHostedInstrumentInstantiation =
          deferHostedInstrumentInstantiation &&
          _instrumentIdUsesExternalPlugin(instrumentId);
      if (shouldDeferHostedInstrumentInstantiation) {
        final dur = _estimatedMidiMaterialDuration(
          midiNotes,
          sourceTempoBpm: resolvedSourceTempoBpm,
          minimumDuration: const Duration(milliseconds: 1200),
        );
        final pendingTrack = await AudioTrack.create(
          file: outFile,
          originalFile: outFile,
          audioDuration: dur,
          trimStart: Duration.zero,
          trimEnd: dur,
          offset: 0.0,
          crossfade: 1.0,
          rowIndex: safeRow,
          rowId: rowId,
          engineClipId: engineClipId,
          clipId: clipId,
          label: label ?? instrumentName,
          clipKind: ClipKind.midi,
          instrumentId: instrumentId,
          instrumentName: instrumentName,
          instrumentParams: Map<String, double>.from(instrumentParams),
          midiNotes: midiNotes.map((n) => n.copy()).toList(),
          sourceTempoBpm: resolvedSourceTempoBpm,
          stretchToProjectTempo: resolvedStretchToProjectTempo,
          tempoStretchPreservePitch: resolvedTempoStretchPreservePitch,
          tempoWarpMode: resolvedTempoWarpMode,
          hostedInstrumentStateBase64: hostedInstrumentStateBase64.trim(),
        );

        pendingTrack.offset = startSec;
        pendingTrack.trimStart = trimStartRequested ?? Duration.zero;
        pendingTrack.trimEnd = trimEndRequested ?? dur;
        if (gain != null) pendingTrack.gain = gain;
        if (pitchSemitones != null) {
          pendingTrack.pitchSemitones = pitchSemitones;
        }
        pendingTrack.sourceTempoBpm = resolvedSourceTempoBpm;
        pendingTrack.stretchToProjectTempo = resolvedStretchToProjectTempo;
        pendingTrack.tempoStretchPreservePitch =
            resolvedTempoStretchPreservePitch;
        pendingTrack.tempoWarpMode = resolvedTempoWarpMode;
        if (crossfade != null) pendingTrack.crossfade = crossfade;
        if (automation != null && automation.isNotEmpty) {
          pendingTrack.volumeAutomation = automation;
        }

        if (mounted && notifyUi) {
          setState(() {
            _audioTracks.add(pendingTrack);
          });
        } else {
          _audioTracks.add(pendingTrack);
        }
        _indexClipForOperations(pendingTrack);
        _setHostedPluginRestoreEntry(
          _HostedPluginRestoreEntry(
            key: _hostedMidiInstrumentRestoreKey(pendingTrack),
            scope: _HostedPluginRestoreScope.midiInstrument,
            status: _HostedPluginRestoreStatus.pending,
            title:
                'Instrument: ${instrumentName.trim().isEmpty ? instrumentId : instrumentName}',
            detail:
                'Waiting to restore this instrument from the saved project.',
            row: safeRow,
            rowId: rowId,
            clipEngineId: engineClipId,
            pluginId: instrumentId,
          ),
        );
        _deferredHostedInstrumentEngineClipIds.add(engineClipId);
        if (updateProjectDuration) {
          _updateOverallDurationIfNeeded(
            changedClips: <AudioTrack>[pendingTrack],
          );
        }
        return;
      }
      var loadedLiveMidi = false;
      try {
        loadedLiveMidi = await _runWithAndroidEngineCriticalSection(
          () => _loadMidiClipIntoEngineLive(
            engineClipId: engineClipId,
            rowId: rowId,
            instrumentId: instrumentId,
            instrumentName: instrumentName,
            midiNotes: midiNotes,
            instrumentParams: instrumentParams,
            sourceTempoBpm: resolvedSourceTempoBpm,
            startSec: startSec,
            lengthSec: requestedLengthSec,
            inFileOffsetSec: requestedInFileOffsetSec,
          ),
        );
      } catch (e, st) {
        debugPrint('Live MIDI clip load failed: $e\n$st');
        loadedLiveMidi = false;
      }

      if (!loadedLiveMidi) {
        final fallbackFile = renderedFile;
        if (fallbackFile != null && fallbackFile.existsSync()) {
          final fallbackLoaded = await _runWithAndroidEngineCriticalSection(
            () => JuceAudioEngine.loadClip(
              engineClipId,
              rowId,
              fallbackFile.path,
              startSec: startSec,
              lengthSec: requestedLengthSec,
              inFileOffsetSec: math.max(0.0, requestedInFileOffsetSec),
            ),
          );
          if (!fallbackLoaded) return;

          _projectLoadIssues.add(
            _ProjectLoadIssue(
              type: _ProjectLoadIssueType.missingPlugin,
              title: 'Recovered Instrument As Audio',
              detail:
                  'Mixroom could not reopen "$instrumentName" for live MIDI playback, so it kept the saved rendered audio for this clip instead.',
            ),
          );

          final fallbackDuration = await _runWithAndroidEngineCriticalSection(
            () => _resolveClipSourceDuration(
              filePath: fallbackFile.path,
              engineClipId: engineClipId,
            ),
          );
          final fallbackTrack = await AudioTrack.create(
            file: fallbackFile,
            originalFile: fallbackFile,
            audioDuration: fallbackDuration,
            trimStart: Duration.zero,
            trimEnd: fallbackDuration,
            offset: 0.0,
            crossfade: 1.0,
            rowIndex: safeRow,
            rowId: rowId,
            engineClipId: engineClipId,
            clipId: clipId,
            label: label ?? instrumentName,
            clipKind: ClipKind.midi,
            instrumentId: instrumentId,
            instrumentName: instrumentName,
            instrumentParams: Map<String, double>.from(instrumentParams),
            midiNotes: midiNotes.map((n) => n.copy()).toList(),
            sourceTempoBpm: resolvedSourceTempoBpm,
            stretchToProjectTempo: resolvedStretchToProjectTempo,
            tempoStretchPreservePitch: resolvedTempoStretchPreservePitch,
            tempoWarpMode: resolvedTempoWarpMode,
            hostedInstrumentStateBase64: hostedInstrumentStateBase64.trim(),
          );
          fallbackTrack.offset = startSec;
          fallbackTrack.trimStart = trimStartRequested ?? Duration.zero;
          fallbackTrack.trimEnd = trimEndRequested ?? fallbackDuration;
          if (gain != null) fallbackTrack.gain = gain;
          if (pitchSemitones != null) {
            fallbackTrack.pitchSemitones = pitchSemitones;
          }
          if (crossfade != null) fallbackTrack.crossfade = crossfade;
          if (automation != null) {
            fallbackTrack.volumeAutomation = automation
                .map((p) => p.copy())
                .toList();
          }
          if (!assumeFreshEngineDefaults) {
            await _syncClipEngineStateAfterLoad(fallbackTrack);
          }
          if (startWaveform) _startWaveformExtraction(fallbackTrack);
          if (mounted && notifyUi) {
            setState(() {
              _audioTracks.add(fallbackTrack);
            });
          } else {
            _audioTracks.add(fallbackTrack);
          }
          _indexClipForOperations(fallbackTrack);
          if (updateProjectDuration) {
            _updateOverallDurationIfNeeded(
              changedClips: <AudioTrack>[fallbackTrack],
            );
          }
          return;
        }
        if (mounted) {
          final msg = _isSampledInstrumentId(instrumentId)
              ? 'Could not load this sampled instrument for live MIDI playback.'
              : 'Could not load this instrument for live MIDI playback.';
          ScaffoldMessenger.of(
            context,
          ).showSnackBar(SnackBar(content: Text(msg)));
        }
        return;
      }

      final dur = _estimatedMidiMaterialDuration(
        midiNotes,
        sourceTempoBpm: resolvedSourceTempoBpm,
        minimumDuration: const Duration(milliseconds: 1200),
      );

      final newTrack = await AudioTrack.create(
        file: outFile,
        originalFile: outFile,
        audioDuration: dur,
        trimStart: Duration.zero,
        trimEnd: dur,
        offset: 0.0,
        crossfade: 1.0,
        rowIndex: safeRow,
        rowId: rowId,
        engineClipId: engineClipId,
        clipId: clipId,
        label: label ?? instrumentName,
        clipKind: ClipKind.midi,
        instrumentId: instrumentId,
        instrumentName: instrumentName,
        instrumentParams: Map<String, double>.from(instrumentParams),
        midiNotes: midiNotes.map((n) => n.copy()).toList(),
        sourceTempoBpm: resolvedSourceTempoBpm,
        stretchToProjectTempo: resolvedStretchToProjectTempo,
        tempoStretchPreservePitch: resolvedTempoStretchPreservePitch,
        tempoWarpMode: resolvedTempoWarpMode,
        hostedInstrumentStateBase64: hostedInstrumentStateBase64.trim(),
      );

      newTrack.offset = startSec;
      newTrack.trimStart = trimStartRequested ?? Duration.zero;
      newTrack.trimEnd = trimEndRequested ?? dur;

      if (gain != null) newTrack.gain = gain;
      if (pitchSemitones != null) newTrack.pitchSemitones = pitchSemitones;
      newTrack.sourceTempoBpm = resolvedSourceTempoBpm;
      newTrack.stretchToProjectTempo = resolvedStretchToProjectTempo;
      newTrack.tempoStretchPreservePitch = resolvedTempoStretchPreservePitch;
      newTrack.tempoWarpMode = resolvedTempoWarpMode;
      if (crossfade != null) newTrack.crossfade = crossfade;
      if (automation != null && automation.isNotEmpty) {
        newTrack.volumeAutomation = automation;
      }

      await _syncClipEngineStateAfterLoad(
        newTrack,
        assumeEngineDefaults: assumeFreshEngineDefaults,
        deferHostedInstrumentStateRestore: deferHostedInstrumentStateRestore,
      );
      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] add MIDI track model clip=${newTrack.clipId} engine=${newTrack.engineClipId} start',
        );
      }
      if (notifyUi) {
        setState(() {
          _audioTracks.add(newTrack);
        });
      } else {
        _audioTracks.add(newTrack);
      }
      _indexClipForOperations(newTrack);
      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] add MIDI track model clip=${newTrack.clipId} engine=${newTrack.engineClipId} done',
        );
      }
      if (startWaveform) {
        _startWaveformExtraction(newTrack);
      }
      if (updateProjectDuration) {
        _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[newTrack]);
      }
    } finally {
      _releaseReservedEngineClipId(engineClipId);
    }
  }

  Future<void> _pasteMidiTrack(
    AudioTrack clip,
    int row,
    double timeMs, {
    Duration? trimStartRequested,
    Duration? trimEndRequested,
    String? clipId,
  }) async {
    if (!clip.isMidi) return;
    await _addMidiTrack(
      instrumentId: clip.instrumentId,
      instrumentName: clip.instrumentName,
      instrumentParams: Map<String, double>.from(clip.instrumentParams),
      midiNotes: _cloneMidiNotesForNewClip(clip.midiNotes),
      row: row,
      timeMs: timeMs,
      trimStartRequested: trimStartRequested,
      trimEndRequested: trimEndRequested,
      label: clip.label,
      gain: clip.gain,
      pitchSemitones: clip.pitchSemitones,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      hostedInstrumentStateBase64: clip.hostedInstrumentStateBase64,
      clipId: clipId,
    );
  }

  Future<void> _addMidiTrackFromProjectFile({
    required File projectAudioFile,
    required String label,
    required int row,
    required double timeMs,
    required String instrumentId,
    required String instrumentName,
    required Map<String, double> instrumentParams,
    required List<MidiNote> midiNotes,
    Duration? trimStartRequested,
    Duration? trimEndRequested,
    double? gain,
    double? pitchSemitones,
    double? sourceTempoBpm,
    bool? stretchToProjectTempo,
    bool? tempoStretchPreservePitch,
    String? tempoWarpMode,
    double? crossfade,
    List<AutomationPoint>? automation,
    bool rowAlreadyEnsured = false,
    bool notifyUi = true,
    bool updateProjectDuration = true,
    bool startWaveform = true,
    bool assumeFreshEngineDefaults = false,
    bool deferHostedInstrumentStateRestore = false,
    bool deferHostedInstrumentInstantiation = false,
    String hostedInstrumentStateBase64 = '',
    String? clipId,
  }) async {
    await _addMidiTrack(
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      instrumentParams: instrumentParams,
      midiNotes: midiNotes,
      row: row,
      timeMs: timeMs,
      trimStartRequested: trimStartRequested,
      trimEndRequested: trimEndRequested,
      renderedFile: projectAudioFile,
      label: label,
      gain: gain,
      pitchSemitones: pitchSemitones,
      sourceTempoBpm: sourceTempoBpm,
      stretchToProjectTempo: stretchToProjectTempo,
      tempoStretchPreservePitch: tempoStretchPreservePitch,
      tempoWarpMode: tempoWarpMode,
      crossfade: crossfade,
      automation: automation,
      rowAlreadyEnsured: rowAlreadyEnsured,
      notifyUi: notifyUi,
      updateProjectDuration: updateProjectDuration,
      startWaveform: startWaveform,
      assumeFreshEngineDefaults: assumeFreshEngineDefaults,
      deferHostedInstrumentStateRestore: deferHostedInstrumentStateRestore,
      deferHostedInstrumentInstantiation: deferHostedInstrumentInstantiation,
      hostedInstrumentStateBase64: hostedInstrumentStateBase64,
      clipId: clipId,
    );
  }

  double _rawClipDurationSec(AudioTrack clip) {
    final ms = (clip.trimEnd - clip.trimStart).inMilliseconds.toDouble();
    return math.max(0.0, ms / 1000.0);
  }

  double _resolvedClipSourceTempoBpm(AudioTrack clip) {
    if (clip.sourceTempoBpm > 0.0) {
      return _clampTempo(clip.sourceTempoBpm);
    }
    if (clip.isMidi) {
      return _clampTempo(_tempo);
    }
    return 0.0;
  }

  bool _clipFollowsProjectTempo(AudioTrack clip) {
    if (clip.isMidi) return true;
    if (!_tempoStretchEnabled) return false;
    return clip.stretchToProjectTempo;
  }

  double _clipTimelineDurationSec(AudioTrack clip) {
    final rawSec = _rawClipDurationSec(clip);
    if (rawSec <= 0.0) return 0.0;
    if (!_clipFollowsProjectTempo(clip)) return rawSec;
    final sourceTempoBpm = _resolvedClipSourceTempoBpm(clip);
    if (sourceTempoBpm <= 0.0) return rawSec;
    final clampedProjectTempo = _clampTempo(_tempo);
    final stretchMultiplier = sourceTempoBpm / clampedProjectTempo;
    return (rawSec * stretchMultiplier).clamp(0.001, 36000.0);
  }

  double _sourceTempoForCurrentClipTimeline(AudioTrack clip) {
    final rawSec = _rawClipDurationSec(clip);
    if (rawSec <= 0.0) return _clampTempo(_tempo);
    final currentTimelineSec = clip.stretchToProjectTempo
        ? _clipTimelineDurationSec(clip)
        : rawSec;
    final projectTempo = _clampTempo(_tempo);
    return ((currentTimelineSec * projectTempo) / rawSec)
        .clamp(20.0, 999.0)
        .toDouble();
  }

  double _clipTimelineDurationMs(AudioTrack clip) {
    return _clipTimelineDurationSec(clip) * 1000.0;
  }

  double _clipFullDurationMsForTrim(AudioTrack clip) {
    if (!clip.isMidi) {
      return clip.audioDuration.inMilliseconds.toDouble();
    }
    // MIDI clips should be extendable beyond rendered note material.
    return 1000.0 * 60.0 * 60.0 * 8.0;
  }

  double _clipTempoStretchPlaybackRatio(AudioTrack clip) {
    final rawSec = _rawClipDurationSec(clip);
    final timelineSec = _clipTimelineDurationSec(clip);
    if (rawSec <= 0.0 || timelineSec <= 0.0) return 1.0;
    return rawSec / timelineSec;
  }

  double _tempoPlaybackRatioForEngine(AudioTrack clip) {
    if (!_clipFollowsProjectTempo(clip)) return 1.0;
    if (_resolvedClipSourceTempoBpm(clip) <= 0.0) return 1.0;
    return _clipTempoStretchPlaybackRatio(clip).clamp(0.05, 20.0);
  }

  bool _clipPreserveTempoPitchInEngine(AudioTrack clip) {
    if (!_clipFollowsProjectTempo(clip)) return false;
    if (clip.isMidi) return true;
    return clip.tempoStretchPreservePitch;
  }

  double _effectiveClipPitchSemitones(AudioTrack clip) {
    return clip.pitchSemitones.clamp(
      _kClipPitchMinSemitones,
      _kClipPitchMaxSemitones,
    );
  }

  String _normalizeProjectCrossfadeMode(String raw) {
    switch (raw.trim().toLowerCase()) {
      case 'none':
      case 'off':
        return 'off';
      case 'cut':
        return 'cut';
      case 'fade':
      case 'x':
      case 'linear':
      case 'linear_crossfade':
      case 'linear-crossfade':
        return 'linear';
      case 'eqp':
      case 'equal_power':
      case 'equal-power':
      case 'equalpower':
      case 'crossfade':
        return 'equal_power';
      case 'xs':
      case 'x_s':
      case 'x-s':
      case 's':
      case 's_curve':
      case 's-curve':
      case 'scurve':
        return 's_curve';
      default:
        return 'equal_power';
    }
  }

  String _projectCrossfadeModeLabel(String mode) {
    switch (_normalizeProjectCrossfadeMode(mode)) {
      case 'off':
        return L10n.translate(context, 'Off');
      case 'cut':
        return L10n.translate(context, 'Cut');
      case 'linear':
        return L10n.translate(context, 'Linear Crossfade');
      case 'equal_power':
        return L10n.translate(context, 'Equal Power Crossfade');
      case 's_curve':
        return L10n.translate(context, 'S-Curve Crossfade');
      default:
        return L10n.translate(context, 'Equal Power Crossfade');
    }
  }

  IconData _projectCrossfadeModeIcon(String mode) {
    switch (_normalizeProjectCrossfadeMode(mode)) {
      case 'off':
        return Icons.do_not_disturb_on_rounded;
      case 'cut':
        return Icons.content_cut_rounded;
      case 'linear':
        return Icons.compare_arrows_rounded;
      case 'equal_power':
        return Icons.graphic_eq_rounded;
      case 's_curve':
        return Icons.timeline_rounded;
      default:
        return Icons.graphic_eq_rounded;
    }
  }

  int _projectCrossfadeCurveCode(String mode) {
    switch (_normalizeProjectCrossfadeMode(mode)) {
      case 's_curve':
        return 2;
      case 'equal_power':
        return 1;
      case 'linear':
      case 'off':
      case 'cut':
      default:
        return 0;
    }
  }

  int _clipRowIdForFadeSync(AudioTrack clip) {
    if (clip.rowId >= 0 && _rowIndexForId(clip.rowId) >= 0) {
      return clip.rowId;
    }
    if (_rowCount <= 0) return -1;
    final boundedRow = clip.rowIndex.clamp(0, _rowCount - 1).toInt();
    return _rowIdAt(boundedRow);
  }

  int _clipEndMs(AudioTrack clip) {
    return math.max(
      0,
      ((clip.offset * 1000.0) + _clipTimelineDurationMs(clip)).round(),
    );
  }

  void _incrementClipEndCount(int endMs) {
    _clipEndMsCounts[endMs] = (_clipEndMsCounts[endMs] ?? 0) + 1;
  }

  void _decrementClipEndCount(int endMs) {
    final count = _clipEndMsCounts[endMs];
    if (count == null) return;
    if (count <= 1) {
      _clipEndMsCounts.remove(endMs);
    } else {
      _clipEndMsCounts[endMs] = count - 1;
    }
  }

  void _removeClipFromOperationIndexes(
    AudioTrack clip, {
    bool markMutation = true,
  }) {
    final oldRowId = _indexedClipRowId.remove(clip);
    var removed = oldRowId != null;
    removed = _indexedClipRowIndex.remove(clip) != null || removed;
    removed = _indexedClipStartSec.remove(clip) != null || removed;
    if (oldRowId != null) {
      final rowClips = _clipsByRowId[oldRowId];
      rowClips?.remove(clip);
      if (rowClips?.isEmpty == true) {
        _clipsByRowId.remove(oldRowId);
      }
    }
    final oldEndMs = _indexedClipEndMs.remove(clip);
    if (oldEndMs != null) {
      removed = true;
      _decrementClipEndCount(oldEndMs);
    }
    if (_clipByEngineId[clip.engineClipId] == clip) {
      removed = true;
      _clipByEngineId.remove(clip.engineClipId);
    }
    if (removed && markMutation) {
      _markClipVisualMutation(topology: true);
    }
  }

  void _indexClipForOperations(AudioTrack clip, {bool markMutation = true}) {
    if (!_clipOperationIndexesInitialized) return;
    final wasIndexed = _indexedClipEndMs.containsKey(clip);
    final oldRowIndex = _indexedClipRowIndex[clip];
    final oldStartSec = _indexedClipStartSec[clip];
    final oldEndMs = _indexedClipEndMs[clip];
    _removeClipFromOperationIndexes(clip, markMutation: false);
    final rowId = _clipRowIdForFadeSync(clip);
    if (rowId >= 0) {
      (_clipsByRowId[rowId] ??= HashSet<AudioTrack>.identity()).add(clip);
      _indexedClipRowId[clip] = rowId;
    }
    _indexedClipRowIndex[clip] = clip.rowIndex;
    _indexedClipStartSec[clip] = clip.offset;
    final endMs = _clipEndMs(clip);
    _indexedClipEndMs[clip] = endMs;
    _incrementClipEndCount(endMs);
    if (clip.engineClipId >= 0) {
      _clipByEngineId[clip.engineClipId] = clip;
    }
    if (markMutation) {
      final layoutChanged =
          !wasIndexed ||
          oldRowIndex != clip.rowIndex ||
          oldStartSec != clip.offset ||
          oldEndMs != endMs;
      _markClipVisualMutation(
        layout: layoutChanged,
        layoutClip: wasIndexed && layoutChanged ? clip : null,
        topology: !wasIndexed,
      );
    }
  }

  void _rebuildClipOperationIndexes() {
    _indexedClipRowId.clear();
    _indexedClipRowIndex.clear();
    _indexedClipStartSec.clear();
    _clipsByRowId.clear();
    _indexedClipEndMs.clear();
    _clipByEngineId.clear();
    _clipEndMsCounts.clear();
    _clipOperationIndexesInitialized = true;
    for (final clip in _audioTracks) {
      _indexClipForOperations(clip, markMutation: false);
    }
    _markClipVisualMutation(topology: true);
  }

  void _ensureClipOperationIndexes() {
    if (!_clipOperationIndexesInitialized ||
        _indexedClipEndMs.length != _audioTracks.length) {
      _rebuildClipOperationIndexes();
    }
  }

  Iterable<AudioTrack> _clipsForFadeResolution({
    Set<int>? clipIndices,
    Set<int>? rowIds,
  }) sync* {
    if (clipIndices != null) {
      for (final index in clipIndices) {
        if (index >= 0 && index < _audioTracks.length) {
          yield _audioTracks[index];
        }
      }
      return;
    }
    if (rowIds == null) {
      yield* _audioTracks;
      return;
    }

    _ensureClipOperationIndexes();
    final emitted = HashSet<AudioTrack>.identity();
    for (final rowId in rowIds) {
      final rowClips = _clipsByRowId[rowId];
      if (rowClips == null) continue;
      for (final clip in rowClips) {
        if (emitted.add(clip)) yield clip;
      }
    }
  }

  Map<int, ({double fadeInSec, double fadeOutSec, int fadeCurve})>
  _resolvedClipFadesByEngineId({Set<int>? clipIndices, Set<int>? rowIds}) {
    final fades =
        <int, ({double fadeInSec, double fadeOutSec, int fadeCurve})>{};
    final candidateClips = _clipsForFadeResolution(
      clipIndices: clipIndices,
      rowIds: rowIds,
    ).toList(growable: false);

    for (final clip in candidateClips) {
      if (clip.engineClipId < 0) continue;
      fades[clip.engineClipId] = (
        fadeInSec: 0.0,
        fadeOutSec: 0.0,
        fadeCurve: 0,
      );
    }

    final mode = _normalizeProjectCrossfadeMode(_projectCrossfadeMode);
    final fadeCurve = _projectCrossfadeCurveCode(mode);
    if (mode == 'off' || mode == 'cut') return fades;

    final clipsByRow = <int, List<AudioTrack>>{};
    for (final clip in candidateClips) {
      if (clip.engineClipId < 0 || clip.isMidi) continue;
      var rowId = clip.rowId;
      if (rowId < 0) {
        if (_rowCount <= 0) continue;
        final boundedRow = clip.rowIndex.clamp(0, _rowCount - 1).toInt();
        rowId = _rowIdAt(boundedRow);
      }
      if (rowId < 0) continue;
      (clipsByRow[rowId] ??= <AudioTrack>[]).add(clip);
    }

    for (final rowClips in clipsByRow.values) {
      rowClips.sort((a, b) => a.offset.compareTo(b.offset));
      for (int i = 0; i < rowClips.length - 1; i++) {
        final left = rowClips[i];
        final right = rowClips[i + 1];
        final leftLength = _clipTimelineDurationSec(left);
        final rightLength = _clipTimelineDurationSec(right);
        final overlapSec = (left.offset + leftLength) - right.offset;
        if (overlapSec <= 0.001) continue;

        final fadeSec = math.min(overlapSec, math.min(leftLength, rightLength));
        if (fadeSec <= 0.001) continue;

        final leftCurrent =
            fades[left.engineClipId] ??
            (fadeInSec: 0.0, fadeOutSec: 0.0, fadeCurve: fadeCurve);
        fades[left.engineClipId] = (
          fadeInSec: leftCurrent.fadeInSec,
          fadeOutSec: math.max(leftCurrent.fadeOutSec, fadeSec),
          fadeCurve: fadeCurve,
        );

        final rightCurrent =
            fades[right.engineClipId] ??
            (fadeInSec: 0.0, fadeOutSec: 0.0, fadeCurve: fadeCurve);
        fades[right.engineClipId] = (
          fadeInSec: math.max(rightCurrent.fadeInSec, fadeSec),
          fadeOutSec: rightCurrent.fadeOutSec,
          fadeCurve: fadeCurve,
        );
      }
    }
    return fades;
  }

  Future<void> _syncAllClipFadesToEngine() async {
    final fades = _resolvedClipFadesByEngineId();
    if (_isProjectLoading) {
      debugPrint('[ProjectLoad] sync clip fades count=${fades.length}');
    }
    await _applyClipFadesToEngine(fades);
    _rememberClipFadeRowsForAllClips();
    if (_isProjectLoading) {
      debugPrint('[ProjectLoad] sync clip fades done');
    }
  }

  Future<void> _syncClipFadesForRowsToEngine(Set<int> rowIds) async {
    final validRowIds = rowIds.where((rowId) => rowId >= 0).toSet();
    if (validRowIds.isEmpty) return;
    final fades = _resolvedClipFadesByEngineId(rowIds: validRowIds);
    await _applyClipFadesToEngine(fades);
    _rememberClipFadeRowsForRows(validRowIds);
  }

  Future<void> _syncClipFadesAroundClipIndexToEngine(
    int clipIndex, {
    Set<int>? additionalRowIds,
  }) async {
    final rowIds = <int>{...?additionalRowIds};
    if (clipIndex >= 0 && clipIndex < _audioTracks.length) {
      final clip = _audioTracks[clipIndex];
      final previousRowId = _clipFadeRowIdByEngineId[clip.engineClipId];
      if (previousRowId != null) rowIds.add(previousRowId);
      rowIds.add(_clipRowIdForFadeSync(clip));
    }
    await _syncClipFadesForRowsToEngine(rowIds);
  }

  void _rememberClipFadeRowsForAllClips() {
    _clipFadeRowIdByEngineId.clear();
    for (final clip in _audioTracks) {
      if (clip.engineClipId < 0) continue;
      final rowId = _clipRowIdForFadeSync(clip);
      if (rowId >= 0) {
        _clipFadeRowIdByEngineId[clip.engineClipId] = rowId;
      }
    }
  }

  void _rememberClipFadeRowsForRows(Set<int> rowIds) {
    for (final clip in _clipsForFadeResolution(rowIds: rowIds)) {
      if (clip.engineClipId < 0) continue;
      final rowId = _clipRowIdForFadeSync(clip);
      _clipFadeRowIdByEngineId[clip.engineClipId] = rowId;
    }
  }

  Future<void> _applyClipFadesToEngine(
    Map<int, ({double fadeInSec, double fadeOutSec, int fadeCurve})> fades,
  ) async {
    if (fades.isEmpty) return;
    await JuceAudioEngine.updateClipFadesBatch(
      fades.entries
          .map(
            (entry) => <String, dynamic>{
              'clip': entry.key,
              'fadeInSec': entry.value.fadeInSec,
              'fadeOutSec': entry.value.fadeOutSec,
              'fadeCurve': entry.value.fadeCurve,
            },
          )
          .toList(growable: false),
    );
  }

  Future<void> _syncRemovedClipFadesAfterUndo(AudioTrack clip) async {
    _updateOverallDurationIfNeeded(removedClips: <AudioTrack>[clip]);
    await _syncClipFadesForRowsToEngine({_clipRowIdForFadeSync(clip)});
    _clipFadeRowIdByEngineId.remove(clip.engineClipId);
  }

  String _buildNativeExportClipSnapshotJson({Set<int>? audibleClipIds}) {
    final snapshots = <Map<String, dynamic>>[];
    final fadeByClipId = _resolvedClipFadesByEngineId();

    for (final clip in _audioTracks) {
      final engineClipId = clip.engineClipId;
      if (engineClipId < 0) continue;

      int resolvedRowId = clip.rowId;
      if (resolvedRowId < 0 || _rowIndexForId(resolvedRowId) < 0) {
        if (_rowCount <= 0) continue;
        final boundedRow = clip.rowIndex.clamp(0, _rowCount - 1);
        resolvedRowId = _rowIdAt(boundedRow);
      }

      // Export must follow the same source path the user is actually hearing.
      // When live MIDI clip playback is disabled or unavailable, playback runs
      // from the rendered WAV, so export should keep using that rendered audio
      // instead of reconstructing a live MIDI instrument path.
      final exportUsesLiveMidiPath =
          clip.isMidi && _liveMidiEventPlaybackSupported;
      final fades =
          fadeByClipId[engineClipId] ??
          (fadeInSec: 0.0, fadeOutSec: 0.0, fadeCurve: 0);

      final snapshot = <String, dynamic>{
        'alive': true,
        'clipId': engineClipId,
        'rowId': resolvedRowId,
        'startSec': math.max(0.0, clip.offset),
        'lengthSec': math.max(0.0, _clipTimelineDurationSec(clip)),
        'inFileOffsetSec': math.max(
          0.0,
          clip.trimStart.inMilliseconds / 1000.0,
        ),
        'pitchSemitones': _effectiveClipPitchSemitones(clip),
        'reversed': !clip.isMidi && clip.isReversed,
        'tempoRatio': _tempoPlaybackRatioForEngine(clip),
        'preservePitch': _clipPreserveTempoPitchInEngine(clip),
        'gainUi': clip.gain.clamp(0.0, 3.0),
        'extraGainLinear': _clipNormalizeGainLinear(clip),
        'panNormalized': 0.0,
        'fadeInSec': fades.fadeInSec,
        'fadeOutSec': fades.fadeOutSec,
        'fadeCurve': fades.fadeCurve,
        'muted':
            audibleClipIds != null && !audibleClipIds.contains(engineClipId),
        'isMidi': exportUsesLiveMidiPath,
        if (clip.file.path.isNotEmpty) 'sourceFilePath': clip.file.path,
      };

      if (exportUsesLiveMidiPath) {
        snapshot['midiInstrumentId'] = _liveMidiEngineInstrumentId(
          clip.instrumentId,
        );
        snapshot['midiInstrumentName'] = clip.instrumentName;
        snapshot['midiNotes'] = _midiNotesToEnginePayload(clip.midiNotes);
        snapshot['midiParams'] = _normalizedInstrumentParamsForPlayback(
          clip.instrumentId,
          clip.instrumentParams,
        );
        snapshot['midiSourceTempoBpm'] = _resolvedClipSourceTempoBpm(clip);
        if (clip.hostedInstrumentStateBase64.trim().isNotEmpty) {
          snapshot['hostedInstrumentStateB64'] = clip
              .hostedInstrumentStateBase64
              .trim();
        }
      }

      snapshots.add(snapshot);
    }

    return jsonEncode(snapshots);
  }

  String _buildGlueExportClipSnapshotJson({
    required Set<int> selectedIndices,
    required double selectionStartSec,
  }) {
    final snapshots = <Map<String, dynamic>>[];
    final fadeByClipId = _resolvedClipFadesByEngineId(
      clipIndices: selectedIndices,
    );

    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      final engineClipId = clip.engineClipId;
      if (engineClipId < 0) continue;

      int resolvedRowId = clip.rowId;
      if (resolvedRowId < 0 || _rowIndexForId(resolvedRowId) < 0) {
        if (_rowCount <= 0) continue;
        resolvedRowId = _rowIdAt(clip.rowIndex.clamp(0, _rowCount - 1).toInt());
      }

      final selected = selectedIndices.contains(i);
      final exportUsesLiveMidiPath =
          selected && clip.isMidi && _liveMidiEventPlaybackSupported;
      final fades =
          fadeByClipId[engineClipId] ??
          (fadeInSec: 0.0, fadeOutSec: 0.0, fadeCurve: 0);
      final snapshot = <String, dynamic>{
        'alive': selected,
        'clipId': engineClipId,
        'rowId': resolvedRowId,
        'startSec': selected
            ? math.max(0.0, clip.offset - selectionStartSec)
            : 0.0,
        'lengthSec': selected
            ? math.max(0.0, _clipTimelineDurationSec(clip))
            : 0.0,
        'inFileOffsetSec': selected
            ? math.max(0.0, clip.trimStart.inMilliseconds / 1000.0)
            : 0.0,
        'pitchSemitones': selected ? _effectiveClipPitchSemitones(clip) : 0.0,
        'reversed': selected && !clip.isMidi && clip.isReversed,
        'tempoRatio': selected ? _tempoPlaybackRatioForEngine(clip) : 1.0,
        'preservePitch': selected && _clipPreserveTempoPitchInEngine(clip),
        'gainUi': selected ? clip.gain.clamp(0.0, 3.0) : kDefaultGainUi,
        'extraGainLinear': selected ? _clipNormalizeGainLinear(clip) : 1.0,
        'panNormalized': 0.0,
        'fadeInSec': selected ? fades.fadeInSec : 0.0,
        'fadeOutSec': selected ? fades.fadeOutSec : 0.0,
        'fadeCurve': selected ? fades.fadeCurve : 0,
        'muted': !selected,
        'isMidi': exportUsesLiveMidiPath,
        if (selected && clip.file.path.isNotEmpty)
          'sourceFilePath': clip.file.path,
      };

      if (exportUsesLiveMidiPath) {
        snapshot['midiInstrumentId'] = _liveMidiEngineInstrumentId(
          clip.instrumentId,
        );
        snapshot['midiInstrumentName'] = clip.instrumentName;
        snapshot['midiNotes'] = _midiNotesToEnginePayload(clip.midiNotes);
        snapshot['midiParams'] = _normalizedInstrumentParamsForPlayback(
          clip.instrumentId,
          clip.instrumentParams,
        );
        snapshot['midiSourceTempoBpm'] = _resolvedClipSourceTempoBpm(clip);
        if (clip.hostedInstrumentStateBase64.trim().isNotEmpty) {
          snapshot['hostedInstrumentStateB64'] = clip
              .hostedInstrumentStateBase64
              .trim();
        }
      }

      snapshots.add(snapshot);
    }

    return jsonEncode(snapshots);
  }

  Future<void> _syncAllTempoStretchToEngine() async {
    if (_audioTracks.isEmpty) return;
    await _syncDeferredClipTimelineBatchToEngine(
      Iterable<int>.generate(_audioTracks.length),
      includeMix: true,
    );
    await _syncAllClipFadesToEngine();
    _updateOverallDurationIfNeeded(forceRebuild: true);
    if (mounted) setState(() {});
  }

  Future<void> _queueTempoEngineSync() async {
    if (_tempoSyncInFlight) {
      _tempoSyncQueued = true;
      return;
    }
    _tempoSyncInFlight = true;
    try {
      do {
        _tempoSyncQueued = false;
        await _syncMetronomeTimingToEngine();
        await _syncAllTempoStretchToEngine();
      } while (_tempoSyncQueued);
    } finally {
      _tempoSyncInFlight = false;
    }
  }

  Future<void> _syncMetronomeTimingToEngine() async {
    await JuceAudioEngine.setMetronomeBpm(_tempo);
    await JuceAudioEngine.setMetronomeTimeSignature(
      numerator: _timeSignatureNumerator,
      denominator: _timeSignatureDenominator,
    );
  }

  double _clampTempo(double bpm) => bpm.clamp(20.0, 999.0).toDouble();

  List<AutomationPoint> _cloneAutomationPoints(List<AutomationPoint> points) {
    return points.map((point) => point.copy()).toList(growable: false);
  }

  Map<int, Map<String, List<AutomationPoint>>>
  _cloneRowPluginAutomationSnapshot(
    Map<int, Map<String, List<AutomationPoint>>> source,
  ) {
    return source.map(
      (row, laneMap) => MapEntry(
        row,
        laneMap.map(
          (targetId, points) =>
              MapEntry(targetId, _cloneAutomationPoints(points)),
        ),
      ),
    );
  }

  Map<int, Map<String, List<AutomationClipSnapshot>>>
  _cloneRowAutomationClipsSnapshot(
    Map<int, Map<String, List<AutomationClipSnapshot>>> source,
  ) {
    return source.map(
      (row, laneMap) => MapEntry(
        row,
        laneMap.map(
          (targetId, clips) => MapEntry(
            targetId,
            clips.map((clip) => clip.copyWith()).toList(growable: false),
          ),
        ),
      ),
    );
  }

  _ProjectTempoSnapshot _captureProjectTempoSnapshot() {
    return _ProjectTempoSnapshot(
      tempo: _clampTempo(_tempo),
      timeSignatureNumerator: _timeSignatureNumerator,
      timeSignatureDenominator: _timeSignatureDenominator,
      clipOffsetsSec: _audioTracks
          .map((clip) => clip.offset)
          .toList(growable: false),
      clipVolumeAutomation: _audioTracks
          .map((clip) => _cloneAutomationPoints(clip.volumeAutomation))
          .toList(growable: false),
      rowVolumeAutomation: _rowVolumeAutomation
          .map(_cloneAutomationPoints)
          .toList(growable: false),
      rowPluginAutomation: _cloneRowPluginAutomationSnapshot(
        _rowPluginAutomation,
      ),
      rowAutomationClips: _cloneRowAutomationClipsSnapshot(_rowAutomationClips),
      loopEnabled: _loopEnabled,
      loopStartMs: _loopStartMs,
      loopEndMs: _loopEndMs,
    );
  }

  _TempoStretchUiModeSnapshot _captureTempoStretchUiModeSnapshot() {
    return _TempoStretchUiModeSnapshot(
      enabled: _tempoStretchEnabled,
      preservePitchDefault: _tempoStretchPreservePitchDefault,
      clipSnapshots: <int, _ClipStretchSnapshot>{
        for (int i = 0; i < _audioTracks.length; i++)
          if (!_audioTracks[i].isMidi)
            i: _ClipStretchSnapshot(
              offsetSec: _audioTracks[i].offset,
              sourceTempoBpm: _audioTracks[i].sourceTempoBpm,
              stretchToProjectTempo: _audioTracks[i].stretchToProjectTempo,
              tempoStretchPreservePitch:
                  _audioTracks[i].tempoStretchPreservePitch,
              tempoWarpMode: _audioTracks[i].tempoWarpMode,
            ),
      },
    );
  }

  Future<void> _applyProjectTempoSnapshot(
    _ProjectTempoSnapshot snapshot,
  ) async {
    _setStateAndRefreshProjectSettings(() {
      _tempo = snapshot.tempo;
      _timeSignatureNumerator = snapshot.timeSignatureNumerator;
      _timeSignatureDenominator = snapshot.timeSignatureDenominator;
      for (int i = 0; i < _audioTracks.length; i++) {
        if (i < snapshot.clipOffsetsSec.length) {
          _audioTracks[i].offset = snapshot.clipOffsetsSec[i];
        }
        if (i < snapshot.clipVolumeAutomation.length) {
          _audioTracks[i].volumeAutomation = _cloneAutomationPoints(
            snapshot.clipVolumeAutomation[i],
          );
        }
      }

      _rowVolumeAutomation
        ..clear()
        ..addAll(snapshot.rowVolumeAutomation.map(_cloneAutomationPoints));
      _rowPluginAutomation
        ..clear()
        ..addAll(
          _cloneRowPluginAutomationSnapshot(snapshot.rowPluginAutomation),
        );
      _rowAutomationClips
        ..clear()
        ..addAll(_cloneRowAutomationClipsSnapshot(snapshot.rowAutomationClips));

      _loopEnabled = snapshot.loopEnabled;
      _loopStartMs = snapshot.loopStartMs;
      _loopEndMs = snapshot.loopEndMs;
    });
    _syncTempoPickerSelection();
    await _queueTempoEngineSync();
    _updateOverallDurationIfNeeded();
    _scheduleProjectAutosave();
    if (mounted) setState(() {});
  }

  Future<void> _applyTempoStretchUiModeSnapshot(
    _TempoStretchUiModeSnapshot snapshot,
  ) async {
    _setStateAndRefreshProjectSettings(() {
      _tempoStretchEnabled = snapshot.enabled;
      _tempoStretchPreservePitchDefault = snapshot.preservePitchDefault;
      for (final entry in snapshot.clipSnapshots.entries) {
        final index = entry.key;
        if (index < 0 || index >= _audioTracks.length) continue;
        final clip = _audioTracks[index];
        if (clip.isMidi) continue;
        clip.offset = entry.value.offsetSec;
        clip.sourceTempoBpm = entry.value.sourceTempoBpm;
        clip.stretchToProjectTempo = entry.value.stretchToProjectTempo;
        clip.tempoStretchPreservePitch = entry.value.tempoStretchPreservePitch;
        clip.tempoWarpMode = normalizeTempoWarpMode(entry.value.tempoWarpMode);
      }
    });
    await _syncAllTempoStretchToEngine();
    _scheduleProjectAutosave();
  }

  static const int _kTempoPickerMinBpm = 20;
  static const int _kTempoPickerMaxBpm = 999;
  static const int _kTempoPickerMaxItem =
      _kTempoPickerMaxBpm - _kTempoPickerMinBpm;

  int _tempoPickerItemFor(double bpm) =>
      _kTempoPickerMaxBpm - _clampTempo(bpm).round();

  double _tempoPickerBpmForItem(int item) =>
      (_kTempoPickerMaxBpm - item.clamp(0, _kTempoPickerMaxItem)).toDouble();

  void _syncTempoPickerSelection({bool animate = false}) {
    final targetItem = _tempoPickerItemFor(_tempo);
    if (!_tempoPickerController.hasClients) return;
    final currentItem = _tempoPickerController.selectedItem;
    if (currentItem == targetItem) return;
    if (animate) {
      unawaited(
        _tempoPickerController.animateToItem(
          targetItem,
          duration: const Duration(milliseconds: 140),
          curve: Curves.easeOutCubic,
        ),
      );
    } else {
      _tempoPickerController.jumpToItem(targetItem);
    }
  }

  void _handleTempoPickerPointerSignal(PointerSignalEvent event) {
    if (event is! PointerScrollEvent ||
        !_usesTabletDesktopDawShell(context) ||
        !_tempoPickerController.hasClients) {
      return;
    }
    if (event.scrollDelta.dy.abs() < 0.5) return;
    GestureBinding.instance.pointerSignalResolver.register(event, (
      resolvedEvent,
    ) {
      if (resolvedEvent is! PointerScrollEvent ||
          !_tempoPickerController.hasClients) {
        return;
      }
      final direction = resolvedEvent.scrollDelta.dy < 0 ? -1 : 1;
      final currentItem = _tempoPickerController.selectedItem;
      final nextItem = (currentItem + direction)
          .clamp(0, _kTempoPickerMaxItem)
          .toInt();
      if (nextItem == currentItem) return;
      unawaited(
        _tempoPickerController.animateToItem(
          nextItem,
          duration: const Duration(milliseconds: 90),
          curve: Curves.easeOutCubic,
        ),
      );
      _setProjectTempoFromUi(_tempoPickerBpmForItem(nextItem));
    });
  }

  String _formatTempoBpm(double bpm) {
    final t = _clampTempo(bpm);
    if ((t - t.roundToDouble()).abs() < 0.0001) {
      return t.toStringAsFixed(0);
    }
    return t.toStringAsFixed(1);
  }

  static const List<List<int>> _kProjectTimeSignatureOptions = <List<int>>[
    <int>[2, 4],
    <int>[3, 4],
    <int>[4, 4],
    <int>[5, 4],
    <int>[6, 8],
    <int>[7, 8],
  ];

  int _normalizeTimeSignatureNumerator(Object? raw, {int fallback = 4}) {
    final parsed = raw is num
        ? raw.toInt()
        : int.tryParse((raw ?? '').toString().trim());
    return (parsed ?? fallback).clamp(1, 12).toInt();
  }

  int _normalizeTimeSignatureDenominator(Object? raw, {int fallback = 4}) {
    final parsed = raw is num
        ? raw.toInt()
        : int.tryParse((raw ?? '').toString().trim());
    switch (parsed ?? fallback) {
      case 2:
      case 4:
      case 8:
      case 16:
        return parsed ?? fallback;
      default:
        return 4;
    }
  }

  String _timeSignatureLabel([int? numerator, int? denominator]) {
    return '${numerator ?? _timeSignatureNumerator}/${denominator ?? _timeSignatureDenominator}';
  }

  double get _projectBarLengthQuarterBeats {
    final numerator = math.max(1, _timeSignatureNumerator);
    final denominator = math.max(1, _timeSignatureDenominator);
    return numerator * 4.0 / denominator;
  }

  List<String> get _projectKeyOptions => <String>[
    '',
    for (final root in kProjectKeyRoots)
      for (final mode in kProjectKeyModes) '$root $mode',
  ];

