  Future<void> _applyProjectTempoChange(
    double bpm, {
    bool recordUndo = false,
  }) async {
    final next = _clampTempo(bpm);
    final previous = _clampTempo(_tempo);
    if ((next - previous).abs() < 0.0001) return;
    final before = recordUndo ? _captureProjectTempoSnapshot() : null;
    _setStateAndRefreshProjectSettings(() {
      _tempo = next;
      for (final clip in _audioTracks) {
        clip.offset = remapTimelineSecondsForTempoChange(
          clip.offset,
          previousBpm: previous,
          nextBpm: next,
        );
        clip.volumeAutomation = remapAutomationPointsForTempoChange(
          clip.volumeAutomation,
          previousBpm: previous,
          nextBpm: next,
        );
      }
      for (int row = 0; row < _rowVolumeAutomation.length; row++) {
        _rowVolumeAutomation[row] = remapAutomationPointsForTempoChange(
          _rowVolumeAutomation[row],
          previousBpm: previous,
          nextBpm: next,
        );
      }
      _rowPluginAutomation.updateAll((_, laneMap) {
        return laneMap.map(
          (targetId, points) => MapEntry(
            targetId,
            remapAutomationPointsForTempoChange(
              points,
              previousBpm: previous,
              nextBpm: next,
            ),
          ),
        );
      });
      _rowAutomationClips.updateAll((_, laneMap) {
        return laneMap.map(
          (targetId, clips) => MapEntry(
            targetId,
            clips
                .map(
                  (clip) => remapAutomationClipForTempoChange(
                    clip,
                    previousBpm: previous,
                    nextBpm: next,
                  ),
                )
                .toList(growable: false),
          ),
        );
      });
      if (_loopEnabled) {
        _loopStartMs = remapTimelineMillisecondsForTempoChange(
          _loopStartMs.toDouble(),
          previousBpm: previous,
          nextBpm: next,
        ).round();
        _loopEndMs = remapTimelineMillisecondsForTempoChange(
          _loopEndMs.toDouble(),
          previousBpm: previous,
          nextBpm: next,
        ).round();
        if (_loopEndMs < _loopStartMs) {
          _loopEndMs = _loopStartMs;
        }
      }
    });
    _syncTempoPickerSelection();
    await _queueTempoEngineSync();
    _scheduleProjectAutosave();
    if (recordUndo && before != null) {
      final after = _captureProjectTempoSnapshot();
      await _undoManager.addWithoutExecute(
        _ProjectTempoChangeAction(
          before: before,
          after: after,
          applySnapshot: _applyProjectTempoSnapshot,
        ),
      );
    }
  }

  void _scheduleProjectTempoUndoCommit() {
    _tempoUndoCommitTimer?.cancel();
    _tempoUndoCommitTimer = Timer(const Duration(milliseconds: 450), () {
      unawaited(_commitPendingProjectTempoUndo());
    });
  }

  Future<void> _commitPendingProjectTempoUndo() async {
    _tempoUndoCommitTimer?.cancel();
    _tempoUndoCommitTimer = null;
    final before = _pendingTempoUndoBefore;
    _pendingTempoUndoBefore = null;
    if (before == null) return;

    final after = _captureProjectTempoSnapshot();
    if ((before.tempo - after.tempo).abs() < 0.0001 &&
        before.timeSignatureNumerator == after.timeSignatureNumerator &&
        before.timeSignatureDenominator == after.timeSignatureDenominator) {
      return;
    }
    await _undoManager.addWithoutExecute(
      _ProjectTempoChangeAction(
        before: before,
        after: after,
        applySnapshot: _applyProjectTempoSnapshot,
      ),
    );
  }

  void _setProjectTempoFromUi(double bpm) {
    final next = _clampTempo(bpm);
    if ((next - _clampTempo(_tempo)).abs() < 0.0001) return;
    _pendingTempoUndoBefore ??= _captureProjectTempoSnapshot();
    unawaited(_applyProjectTempoChange(next));
    _scheduleProjectTempoUndoCommit();
  }

  void _setProjectTimeSignatureFromUi(int numerator, int denominator) {
    final nextNumerator = _normalizeTimeSignatureNumerator(numerator);
    final nextDenominator = _normalizeTimeSignatureDenominator(denominator);
    if (nextNumerator == _timeSignatureNumerator &&
        nextDenominator == _timeSignatureDenominator) {
      return;
    }
    _pendingTempoUndoBefore ??= _captureProjectTempoSnapshot();
    _setStateAndRefreshProjectSettings(() {
      _timeSignatureNumerator = nextNumerator;
      _timeSignatureDenominator = nextDenominator;
    });
    unawaited(_syncMetronomeTimingToEngine());
    _updateOverallDurationIfNeeded();
    _scheduleProjectAutosave();
    _scheduleProjectTempoUndoCommit();
  }

  Future<void> _setTempoStretchUiMode({
    required bool enabled,
    required bool preservePitch,
  }) async {
    final follows = _audioTracks
        .where((clip) => !clip.isMidi && clip.stretchToProjectTempo)
        .toList();
    final clipModesAlreadyMatch = follows.every(
      (clip) => clip.tempoStretchPreservePitch == preservePitch,
    );
    if (_tempoStretchEnabled == enabled &&
        _tempoStretchPreservePitchDefault == preservePitch &&
        clipModesAlreadyMatch) {
      return;
    }

    final before = _captureTempoStretchUiModeSnapshot();
    _setStateAndRefreshProjectSettings(() {
      _tempoStretchEnabled = enabled;
      _tempoStretchPreservePitchDefault = preservePitch;
      for (final clip in follows) {
        clip.tempoStretchPreservePitch = preservePitch;
      }
    });

    await _syncAllTempoStretchToEngine();
    _scheduleProjectAutosave();
    final after = _captureTempoStretchUiModeSnapshot();
    await _undoManager.addWithoutExecute(
      _TempoStretchUiModeAction(
        before: before,
        after: after,
        applySnapshot: _applyTempoStretchUiModeSnapshot,
      ),
    );
  }

  Future<bool> _reloadMidiTrackLive(AudioTrack clip) async {
    if (!clip.isMidi || clip.engineClipId < 0) return false;
    if (!_liveMidiEventPlaybackSupported) return false;
    clip.sourceTempoBpm = _clampTempo(_tempo);
    clip.stretchToProjectTempo = true;
    clip.tempoStretchPreservePitch = true;

    final rowId = clip.rowId >= 0 ? clip.rowId : _rowIdAt(clip.rowIndex);
    if (rowId < 0) return false;
    final startSec = clip.offset;
    final lengthSec = _clipTimelineDurationSec(clip);
    final inFileOffsetSec = clip.trimStart.inMilliseconds.toDouble() / 1000.0;

    final reloaded = await _loadMidiClipIntoEngineLive(
      engineClipId: clip.engineClipId,
      rowId: rowId,
      instrumentId: clip.instrumentId,
      instrumentName: clip.instrumentName,
      midiNotes: clip.midiNotes,
      instrumentParams: clip.instrumentParams,
      sourceTempoBpm: _resolvedClipSourceTempoBpm(clip),
      startSec: startSec,
      lengthSec: lengthSec,
      inFileOffsetSec: inFileOffsetSec,
    );
    if (!reloaded) return false;
    await _syncClipEngineStateAfterLoad(clip);
    await _syncClipFadesForRowsToEngine({rowId});
    if (mounted) {
      setState(() {});
    }
    _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
    return true;
  }

  Future<void> _syncClipTimelineModelToEngine(
    AudioTrack clip, {
    bool skipMoveToRow = false,
  }) async {
    if (clip.engineClipId < 0) return;
    if (_rowCount == 0) return;

    final boundedRow = clip.rowIndex.clamp(0, _rowCount - 1);
    clip.rowIndex = boundedRow;
    if (clip.rowId < 0 || _rowIndexForId(clip.rowId) < 0) {
      clip.rowId = _rowIdAt(boundedRow);
    }

    final startSec = clip.offset;
    final lengthSec = _clipTimelineDurationSec(clip);
    final inFileOffsetSec = clip.trimStart.inMilliseconds / 1000.0;

    if (!skipMoveToRow) {
      await JuceAudioEngine.moveClipToRow(clip.engineClipId, clip.rowId);
    }
    await JuceAudioEngine.setClipTime(
      clip.engineClipId,
      startSec: startSec,
      lengthSec: math.max(0.0, lengthSec),
      inFileOffsetSec: math.max(0.0, inFileOffsetSec),
    );
    await JuceAudioEngine.setClipStretchOptions(
      clip.engineClipId,
      tempoRatio: _tempoPlaybackRatioForEngine(clip),
      preservePitch: _clipPreserveTempoPitchInEngine(clip),
    );
  }

  Future<void> _syncClipEngineStateAfterLoad(
    AudioTrack clip, {
    bool assumeEngineDefaults = false,
    bool deferHostedInstrumentStateRestore = false,
  }) async {
    final deferInitialPropertySync = _isProjectLoading && assumeEngineDefaults;
    if (_isProjectLoading) {
      debugPrint(
        '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} timeline start',
      );
    }
    if (!deferInitialPropertySync) {
      await _syncClipTimelineModelToEngine(clip);
      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} timeline done',
        );
        debugPrint(
          '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} mix start',
        );
      }
      await _syncClipMixToEngineOptimized(
        clip,
        assumeEngineDefaults: assumeEngineDefaults,
      );
      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} mix done',
        );
      }
    } else {
      debugPrint(
        '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} timeline and mix deferred',
      );
    }
    if (_clipUsesExternalPluginInstrument(clip) &&
        clip.hostedInstrumentStateBase64.trim().isNotEmpty) {
      if (deferHostedInstrumentStateRestore) {
        if (_isProjectLoading) {
          debugPrint(
            '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} hosted state deferred',
          );
        }
        return;
      }
      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} hosted state start',
        );
      }
      final applied = await _applyHostedInstrumentStateToClip(
        clip,
        clip.hostedInstrumentStateBase64,
      );
      if (_isProjectLoading) {
        debugPrint(
          '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} hosted state done applied=$applied',
        );
      }
      if (!applied && _isProjectLoading) {
        _projectLoadIssues.add(
          _ProjectLoadIssue(
            type: _ProjectLoadIssueType.missingPlugin,
            title: 'Plugin State Restore Failed',
            detail:
                'Mixroom reopened "${clip.instrumentName}" but could not reapply its saved plugin state exactly.',
          ),
        );
      }
    } else if (_isProjectLoading) {
      debugPrint(
        '[ProjectLoad] sync clip ${clip.clipId} engine=${clip.engineClipId} no hosted state',
      );
    }
  }

  Future<void> _syncClipTimingToEngine(
    int clipIndex, {
    bool skipMoveToRow = false,
    Set<int>? additionalFadeRowIds,
  }) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    await _syncClipTimelineModelToEngine(
      _audioTracks[clipIndex],
      skipMoveToRow: skipMoveToRow,
    );
    await _syncClipFadesAroundClipIndexToEngine(
      clipIndex,
      additionalRowIds: additionalFadeRowIds,
    );
  }

  Future<void> _syncDeferredClipTimelineBatchToEngine(
    Iterable<int> clipIndices, {
    bool includeMix = false,
  }) async {
    final updates = <Map<String, dynamic>>[];
    final seen = <int>{};
    final validClipIndices = <int>[];
    for (final clipIndex in clipIndices) {
      if (!seen.add(clipIndex)) continue;
      if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
      final clip = _audioTracks[clipIndex];
      if (clip.engineClipId < 0) continue;
      if (_rowCount == 0) continue;

      final boundedRow = clip.rowIndex.clamp(0, _rowCount - 1).toInt();
      clip.rowIndex = boundedRow;
      if (clip.rowId < 0 || _rowIndexForId(clip.rowId) < 0) {
        clip.rowId = _rowIdAt(boundedRow);
      }

      final update = <String, dynamic>{
        'clip': clip.engineClipId,
        'rowId': clip.rowId,
        'startSec': clip.offset,
        'lengthSec': math.max(0.0, _clipTimelineDurationSec(clip)),
        'inFileOffsetSec': math.max(
          0.0,
          clip.trimStart.inMilliseconds / 1000.0,
        ),
      };
      if (includeMix) {
        update.addAll(<String, dynamic>{
          'gain': clip.gain.clamp(0.0, 3.0),
          'extraGainLinear': _clipNormalizeGainLinear(clip),
          'reversed': !clip.isMidi && clip.isReversed,
          'tempoRatio': _tempoPlaybackRatioForEngine(clip),
          'preservePitch': _clipPreserveTempoPitchInEngine(clip),
          'pitchSemitones': _effectiveClipPitchSemitones(clip),
        });
      }
      updates.add(update);
      validClipIndices.add(clipIndex);
    }

    if (updates.isEmpty) return;
    final applied = await JuceAudioEngine.updateClipTimelineBatch(updates);
    if (applied >= updates.length) return;

    for (final clipIndex in validClipIndices) {
      final clip = _audioTracks[clipIndex];
      await _syncClipTimelineModelToEngine(clip);
      if (includeMix) {
        await _syncClipMixToEngine(clip);
      }
    }
  }

  double _gainUiToLinearValue(double gainUi) {
    final userGain = gainUi.clamp(_kGainUiMin, _kGainUiMax).toDouble();
    final db = userGain <= _kGainUiUnity
        ? _kGainDbMin +
              ((0.0 - _kGainDbMin) *
                  ((userGain - _kGainUiMin) / (_kGainUiUnity - _kGainUiMin))
                      .clamp(0.0, 1.0))
        : (_kGainDbMax *
              ((userGain - _kGainUiUnity) / (_kGainUiMax - _kGainUiUnity))
                  .clamp(0.0, 1.0));
    if (db <= _kGainDbMin + 0.001) return 0.0;
    return math.pow(10.0, db / 20.0).toDouble();
  }

  double _clipNormalizeGainLinear(AudioTrack clip) {
    if (!clip.normalizeVolume || clip.isMidi) return 1.0;
    return clip.normalizeGain
        .clamp(_kClipNormalizeGainMin, _kClipNormalizeGainMax)
        .toDouble();
  }

  Future<void> _syncClipMixToEngine(AudioTrack clip) async {
    if (clip.engineClipId < 0) return;
    final gain = clip.gain.clamp(0.0, 3.0);
    final normalizeGain = _clipNormalizeGainLinear(clip);
    final pitch = _effectiveClipPitchSemitones(clip);
    final tempoRatio = _tempoPlaybackRatioForEngine(clip);
    final preservePitch = _clipPreserveTempoPitchInEngine(clip);
    await JuceAudioEngine.setClipGain(clip.engineClipId, gain);
    await JuceAudioEngine.setClipExtraGainLinear(
      clip.engineClipId,
      normalizeGain,
    );
    await JuceAudioEngine.setClipReversed(
      clip.engineClipId,
      !clip.isMidi && clip.isReversed,
    );
    await JuceAudioEngine.setClipStretchOptions(
      clip.engineClipId,
      tempoRatio: tempoRatio,
      preservePitch: preservePitch,
    );
    await JuceAudioEngine.setClipPitch(clip.engineClipId, pitch);
  }

  Future<void> _syncClipMixToEngineOptimized(
    AudioTrack clip, {
    bool assumeEngineDefaults = false,
  }) async {
    if (clip.engineClipId < 0) return;
    final gain = clip.gain.clamp(0.0, 3.0);
    final normalizeGain = _clipNormalizeGainLinear(clip);
    final pitch = _effectiveClipPitchSemitones(clip);
    final tempoRatio = _tempoPlaybackRatioForEngine(clip);
    final preservePitch = _clipPreserveTempoPitchInEngine(clip);
    const double epsilon = 0.0005;

    if (!assumeEngineDefaults || (gain - kDefaultGainUi).abs() > epsilon) {
      await JuceAudioEngine.setClipGain(clip.engineClipId, gain);
    }
    if (!assumeEngineDefaults ||
        (normalizeGain - 1.0).abs() > epsilon ||
        clip.normalizeVolume) {
      await JuceAudioEngine.setClipExtraGainLinear(
        clip.engineClipId,
        normalizeGain,
      );
    }
    if (!assumeEngineDefaults || (!clip.isMidi && clip.isReversed)) {
      await JuceAudioEngine.setClipReversed(
        clip.engineClipId,
        !clip.isMidi && clip.isReversed,
      );
    }
    if (!assumeEngineDefaults ||
        (tempoRatio - 1.0).abs() > epsilon ||
        preservePitch != clip.isMidi) {
      await JuceAudioEngine.setClipStretchOptions(
        clip.engineClipId,
        tempoRatio: tempoRatio,
        preservePitch: preservePitch,
      );
    }
    if (!assumeEngineDefaults || pitch.abs() > epsilon) {
      await JuceAudioEngine.setClipPitch(clip.engineClipId, pitch);
    }
  }

  Future<void> _prepareNativeEngineStateForExport(
    ValueChanged<double> reportProgress,
  ) async {
    reportProgress(0.08);
    await _flushDeferredAndroidRouteRefreshIfNeeded();

    final pendingMidiRefreshes = _midiClipEngineRefreshChains.values.toList(
      growable: false,
    );
    if (pendingMidiRefreshes.isNotEmpty) {
      await Future.wait(
        pendingMidiRefreshes.map((future) => future.catchError((_) {})),
      );
    }

    // The native exporter now builds a dedicated offline graph from a snapshot
    // of engine state. Rebuilding/reloading clips here right before export can
    // race that snapshot and produce silent or partial renders.
    reportProgress(0.12);
    await _flushDeferredAndroidRouteRefreshIfNeeded();
    reportProgress(0.14);
  }

  Future<void> _setClipGainLive(int clipIndex, double gain) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.engineClipId < 0) return;
    final next = gain.clamp(0.0, 3.0);
    clip.gain = next;
    _markClipVisualMutation();
    await JuceAudioEngine.setClipGain(clip.engineClipId, next);
    if (mounted) setState(() {});
  }

  Future<double?> _clipSamplePeakForNormalize(AudioTrack clip) async {
    if (clip.isMidi || !clip.file.existsSync()) return null;

    final durationSec = (clip.audioDuration.inMilliseconds / 1000.0)
        .clamp(0.001, double.infinity)
        .toDouble();
    final startSec = (clip.trimStart.inMilliseconds / 1000.0)
        .clamp(0.0, durationSec)
        .toDouble();
    final endSec = (clip.trimEnd.inMilliseconds / 1000.0)
        .clamp(startSec + 0.001, durationSec)
        .toDouble();
    final trimDurationSec = (endSec - startSec)
        .clamp(0.001, durationSec)
        .toDouble();

    final args = <String>[
      '-hide_banner',
      '-nostdin',
      '-ss',
      startSec.toStringAsFixed(6),
      '-t',
      trimDurationSec.toStringAsFixed(6),
      '-i',
      clip.file.path,
      '-vn',
      '-filter:a',
      'volumedetect',
      '-f',
      'null',
      '-',
    ];
    final session = await FFmpegKit.executeWithArguments(args);
    final returnCode = await session.getReturnCode();
    final logs = await session.getLogs();
    final messages = logs
        .map((log) => log.getMessage())
        .whereType<String>()
        .toList(growable: false);
    final maxVolumePattern = RegExp(
      r'max_volume:\s*(-?inf|[-+]?\d+(?:\.\d+)?)\s*dB',
      caseSensitive: false,
    );
    for (final message in messages.reversed) {
      final match = maxVolumePattern.firstMatch(message);
      if (match == null) continue;
      final rawDb = match.group(1);
      if (rawDb == null || rawDb.toLowerCase().contains('inf')) return null;
      final db = double.tryParse(rawDb);
      if (db == null || !db.isFinite) return null;
      return math
          .pow(10.0, db / 20.0)
          .toDouble()
          .clamp(0.000001, double.infinity)
          .toDouble();
    }
    if (!ReturnCode.isSuccess(returnCode)) {
      final tail = messages.length <= 6
          ? messages.join('\n')
          : messages.sublist(messages.length - 6).join('\n');
      debugPrint(
        'Normalize volumedetect failed for ${p.basename(clip.file.path)} '
        'with code ${returnCode?.getValue()}: $tail',
      );
    }
    return null;
  }

  Future<void> _ensureClipWaveformForNormalizeVisual(AudioTrack clip) async {
    if (clip.isMidi || !clip.file.existsSync()) return;
    final durSec = (clip.audioDuration.inMilliseconds / 1000.0).clamp(
      0.001,
      double.infinity,
    );
    const int kWaveformSPS = 150;
    const int minPoints = 256;
    const int maxPoints = 20000;
    final target = (durSec * kWaveformSPS)
        .round()
        .clamp(minPoints, maxPoints)
        .toInt();
    final extracted = await _extractWaveformData(
      clip.file.path,
      durSec: durSec,
      target: target,
    );
    if (extracted != null && extracted.isNotEmpty) {
      clip.normWaveformData = extracted;
      _waveformCacheByPath[_normalizedClipPath(clip.file.path)] = extracted;
      clip.didExtractWaveform = true;
    }
  }

  Future<void> _handleToggleClipNormalize(
    int clipIndex,
    bool normalizeVolume,
  ) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi || clip.engineClipId < 0) return;

    final oldSnapshot = _ClipNormalizeSnapshot.fromClip(clip);
    final _ClipNormalizeSnapshot newSnapshot;
    if (normalizeVolume) {
      final peak = await _clipSamplePeakForNormalize(clip);
      if (peak == null || !peak.isFinite || peak <= 0.0001) {
        if (mounted) {
          _showSmallNotice(
            L10n.translate(context, 'Could not normalize this clip yet.'),
          );
          setState(() {});
        }
        return;
      }
      await _ensureClipWaveformForNormalizeVisual(clip);
      const targetPeak = 1.0;
      final normalizeGain = (targetPeak / peak)
          .clamp(_kClipNormalizeGainMin, _kClipNormalizeGainMax)
          .toDouble();
      newSnapshot = _ClipNormalizeSnapshot(
        normalizeVolume: true,
        normalizeGain: normalizeGain,
      );
    } else {
      newSnapshot = _ClipNormalizeSnapshot(
        normalizeVolume: false,
        normalizeGain: 1.0,
      );
    }

    if (oldSnapshot.approxEquals(newSnapshot)) return;

    await _undoManager.execute(
      _SetClipNormalizeAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldSnapshot: oldSnapshot,
        newSnapshot: newSnapshot,
        applyToState: (target, snapshot) {
          target.normalizeVolume = snapshot.normalizeVolume;
          target.normalizeGain = snapshot.normalizeGain;
          _markClipVisualMutation();
          if (mounted) setState(() {});
        },
      ),
    );
    _recordProducerManualEdit('clip_normalize', {
      'clip': clipIndex,
      'enabled': normalizeVolume,
      'old_normalize_gain': oldSnapshot.normalizeGain,
      'new_normalize_gain': newSnapshot.normalizeGain,
    });
  }

  Future<void> _setClipPitchLive(int clipIndex, double semitones) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.engineClipId < 0) return;
    final next = semitones.clamp(
      _kClipPitchMinSemitones,
      _kClipPitchMaxSemitones,
    );
    clip.pitchSemitones = next;
    _markClipVisualMutation();
    await JuceAudioEngine.setClipPitch(
      clip.engineClipId,
      _effectiveClipPitchSemitones(clip),
    );
    if (mounted) setState(() {});
  }

  Future<List<double>?> _extractWaveformData(
    String inputPath, {
    required double durSec,
    required int target,
  }) {
    final result = Completer<List<double>?>();
    final previous = _waveformExtractionLane;
    _waveformExtractionLane = () async {
      try {
        await previous;
      } catch (_) {
        // A failed job must not poison the lane for later clips.
      }
      try {
        result.complete(
          await _extractWaveformDataNow(
            inputPath,
            durSec: durSec,
            target: target,
          ),
        );
      } catch (error, stackTrace) {
        result.completeError(error, stackTrace);
      }
    }();
    return result.future;
  }

  Future<List<double>?> _extractWaveformDataNow(
    String inputPath, {
    required double durSec,
    required int target,
  }) async {
    const int pcmRate = 8000;
    final tmpDir = await getTemporaryDirectory();
    final rawPath =
        '${tmpDir.path}/wf_${inputPath.hashCode}_${durSec.hashCode}_$target.raw';
    final rawFile = File(rawPath);
    if (await rawFile.exists()) {
      await rawFile.delete();
    }

    final session = await FFmpegKit.executeWithArguments(<String>[
      '-hide_banner',
      '-nostdin',
      '-i',
      inputPath,
      '-ac',
      '2',
      '-ar',
      '$pcmRate',
      '-f',
      's16le',
      '-y',
      rawPath,
    ]);
    final returnCode = await session.getReturnCode();
    if (!ReturnCode.isSuccess(returnCode) || !await rawFile.exists()) {
      final logs = await session.getLogs();
      final logLines = logs
          .map((log) => log.getMessage())
          .whereType<String>()
          .where((line) => line.trim().isNotEmpty)
          .toList();
      final tail = logLines.length <= 6
          ? logLines.join('\n')
          : logLines.sublist(logLines.length - 6).join('\n');
      debugPrint(
        'Waveform FFmpeg failed for ${p.basename(inputPath)} '
        'with code ${returnCode?.getValue()}: $tail',
      );
      return null;
    }

    final bytes = await rawFile.readAsBytes();
    if (bytes.length < 2) {
      unawaited(rawFile.delete().catchError((_) => rawFile));
      return null;
    }

    const channels = 2;
    const bytesPerSample = 2;
    const bytesPerFrame = channels * bytesPerSample;
    final totalSamples = bytes.length ~/ bytesPerFrame;
    final expectedSamples = (durSec * pcmRate).round().clamp(1, 1 << 30);

    double mapExpectedToDecoded(double expectedIndex) {
      return expectedIndex * totalSamples / expectedSamples;
    }

    final out = List<double>.filled(target, 0.0, growable: false);
    for (int i = 0; i < target; i++) {
      final expStart = (i / target) * expectedSamples;
      final expEnd = ((i + 1) / target) * expectedSamples;

      int start = mapExpectedToDecoded(expStart).floor();
      int end = mapExpectedToDecoded(expEnd).floor();

      start = start.clamp(0, totalSamples);
      end = end.clamp(0, totalSamples);

      if (end <= start) continue;

      double peak = 0.0;
      for (int s = start; s < end; s++) {
        final frameBase = s * bytesPerFrame;
        for (int ch = 0; ch < channels; ch++) {
          final bi = frameBase + (ch * bytesPerSample);
          int v = bytes[bi] | (bytes[bi + 1] << 8);
          if ((v & 0x8000) != 0) v -= 0x10000;

          final f = (v / 32768.0).abs();
          if (f > peak) peak = f;
        }
      }

      out[i] = peak.clamp(0.0, 1.0);
    }
    unawaited(rawFile.delete().catchError((_) => rawFile));
    return List<double>.unmodifiable(amplifyAndCapWaveform(out));
  }

  bool _isAllZeroWaveform(List<double> waveform) {
    if (waveform.isEmpty) return true;
    return !waveform.any((value) => value.abs() > 0.0001);
  }

  void _markWaveformExtractionFailed(
    String cacheKey,
    Set<AudioTrack> tracks, [
    Object? error,
  ]) {
    _waveformFutureByPath.remove(cacheKey);
    _waveformPendingTracksByPath.remove(cacheKey);
    if (tracks.isEmpty) return;

    for (final track in tracks) {
      track.didExtractWaveform = false;
    }

    final attempts = (_waveformFailureCountByPath[cacheKey] ?? 0) + 1;
    _waveformFailureCountByPath[cacheKey] = attempts;
    final sampleName = p.basename(tracks.first.file.path);
    debugPrint(
      'Waveform extraction failed for $sampleName '
      '(attempt $attempts/$_maxWaveformExtractionAttempts): $error',
    );
    if (!mounted || attempts >= _maxWaveformExtractionAttempts) {
      return;
    }

    final retryTracks = List<AudioTrack>.of(tracks);
    unawaited(
      Future<void>.delayed(Duration(milliseconds: 300 * attempts), () {
        if (!mounted) return;
        for (final track in retryTracks) {
          if (track.isMidi || !track.file.existsSync()) continue;
          if (track.didExtractWaveform &&
              track.normWaveformData.isNotEmpty &&
              !_isAllZeroWaveform(track.normWaveformData)) {
            continue;
          }
          _startWaveformExtraction(track);
        }
      }),
    );
  }

  void _startWaveformExtraction(AudioTrack c) async {
    if (c.isMidi) {
      c.didExtractWaveform = true;
      c.normWaveformData = const <double>[];
      return;
    }

    final inputPath = c.file.path;
    final cacheKey = _normalizedClipPath(inputPath);
    try {
      final cached = _waveformCacheByPath[cacheKey];
      if (cached != null && cached.isNotEmpty) {
        if (!mounted) return;
        final waitingTracks =
            _waveformPendingTracksByPath.remove(cacheKey) ?? <AudioTrack>{};
        waitingTracks.add(c);
        _markClipVisualMutation();
        setState(() {
          for (final track in waitingTracks) {
            track.didExtractWaveform = true;
            track.normWaveformData = cached;
          }
        });
        return;
      }

      if (c.didExtractWaveform &&
          c.normWaveformData.isNotEmpty &&
          !_isAllZeroWaveform(c.normWaveformData)) {
        return;
      }

      _waveformPendingTracksByPath
          .putIfAbsent(cacheKey, () => <AudioTrack>{})
          .add(c);

      final durSec = (c.audioDuration.inMilliseconds / 1000.0).clamp(
        0.001,
        double.infinity,
      );
      const int kWaveformSPS = 150;
      const int minPoints = 256;
      const int maxPoints = 20000;
      int target = (durSec * kWaveformSPS).round();
      target = target.clamp(minPoints, maxPoints);

      final pending = _waveformFutureByPath[cacheKey];
      if (pending == null) {
        c.normWaveformData = List<double>.filled(target, 0.0, growable: false);
        if (mounted) {
          _markClipVisualMutation();
          setState(() {});
        }
      }

      final waveformFuture =
          pending ??
          (() {
            final future =
                _extractWaveformData(inputPath, durSec: durSec, target: target)
                    .then((waveform) {
                      if (waveform != null && waveform.isNotEmpty) {
                        _waveformCacheByPath[cacheKey] = waveform;
                      }
                      return waveform;
                    })
                    .whenComplete(() {
                      _waveformFutureByPath.remove(cacheKey);
                    });
            _waveformFutureByPath[cacheKey] = future;
            return future;
          })();

      final waveform = await waveformFuture;
      final waitingTracks =
          _waveformPendingTracksByPath.remove(cacheKey) ?? <AudioTrack>{c};
      if (waveform == null || waveform.isEmpty) {
        _markWaveformExtractionFailed(cacheKey, waitingTracks, 'empty result');
        return;
      }
      _waveformFailureCountByPath.remove(cacheKey);
      if (!mounted) return;
      _markClipVisualMutation();
      setState(() {
        for (final track in waitingTracks) {
          track.didExtractWaveform = true;
          track.normWaveformData = waveform;
        }
      });
    } catch (e) {
      final waitingTracks =
          _waveformPendingTracksByPath.remove(cacheKey) ?? <AudioTrack>{c};
      _markWaveformExtractionFailed(cacheKey, waitingTracks, e);
    }
  }

  Future<void> _exportAndNavigate({
    _AudioExportSettings? selectedSettingsOverride,
  }) async {
    _AudioExportSettings? selectedSettings = selectedSettingsOverride;
    if (selectedSettings == null) {
      try {
        selectedSettings = await _showAudioExportSettingsSheet();
      } catch (e) {
        debugPrint('Failed to open export dialog: $e');
        if (!mounted) {
          return;
        }
        setState(() {
          _audioExportSettings = const _AudioExportSettings(
            format: _ExportAudioFormat.wav,
            sampleRate: 44100,
            wavBitDepth: 16,
            wavDithering: true,
            mp3BitrateKbps: 192,
            mp3Mode: _ExportMp3Mode.cbr,
            mp3VbrQuality: 2,
            channelMode: _ExportChannelMode.stereo,
            normalize: false,
            normalizeTargetDb: -1.0,
            resampleQuality: _ExportResampleQuality.best,
          );
        });
        try {
          selectedSettings = await _showAudioExportSettingsSheet();
        } catch (retryError) {
          debugPrint('Retry open export dialog failed: $retryError');
          if (!mounted) return;
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                L10n.translate(context, 'Could not open export options.'),
              ),
            ),
          );
          return;
        }
      }
    }
    if (!mounted || selectedSettings == null) {
      return;
    }
    final effectiveSettings = _normalizeAudioExportSettings(selectedSettings);
    final exportFormat = effectiveSettings.fileExtension;
    final exportStopwatch = Stopwatch()..start();
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.exportStarted(
          projectId: _projectId,
          exportType: exportFormat,
          trackCount: _audioTracks.length,
        ),
      ),
    );

    final useContainedExportPanel = _usesContainedExportPanel;
    int containedExportToken = 0;
    if (useContainedExportPanel) {
      containedExportToken = _beginContainedExportProgress();
    }

    setState(() {
      _audioExportSettings = effectiveSettings;
      _activeAudioExportSettings = effectiveSettings;
      _isLoadingNextScreen = !useContainedExportPanel;
    });
    if (useContainedExportPanel) {
      await _letContainedExportProgressPaint();
      if (!mounted ||
          _containedExportCancelled ||
          containedExportToken != _containedExportRunToken) {
        return;
      }
    }
    if (_isPlaying) {
      await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    }
    final String? exportPath;
    if (useContainedExportPanel) {
      exportPath = await _exportAudioOnly((value) {
        final progress = value.clamp(0.0, 1.0).toDouble();
        if (!mounted ||
            _containedExportCancelled ||
            containedExportToken != _containedExportRunToken) {
          return;
        }
        setState(() {
          _containedExportProgress = progress;
        });
      });
      _stopContainedExportEllipsisTimer();
    } else {
      exportPath = await Navigator.push<String>(
        context,
        MaterialPageRoute(
          builder: (_) =>
              ExportProgressPage(exportFn: _exportAudioOnly, videoFile: ""),
        ),
      );
    }
    if (!mounted) {
      _activeAudioExportSettings = null;
      return;
    }

    setState(() {
      _activeAudioExportSettings = null;
      _isLoadingNextScreen = false;
    });

    if (useContainedExportPanel &&
        (_containedExportCancelled ||
            containedExportToken != _containedExportRunToken)) {
      if (exportPath != null && exportPath.isNotEmpty) {
        _deleteContainedExportFileIfSafe(exportPath);
      }
      return;
    }

    if (exportPath == null || exportPath.isEmpty) {
      if (useContainedExportPanel) {
        setState(() {
          _containedExportPanelStage = _ContainedExportPanelStage.idle;
          _containedExportProgress = 0.0;
        });
      }
      unawaited(
        AnalyticsService.instance.track(
          AnalyticsEvents.exportFailed(
            projectId: _projectId,
            errorCode: 'cancelled_or_failed',
          ),
        ),
      );
      final failStr = L10n.translate(context, 'Export canceled or failed.');
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(failStr)));
      return;
    }

    final completedExportPath = exportPath;
    int exportFileSize = 0;
    try {
      exportFileSize = await File(completedExportPath).length();
    } catch (_) {}
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.exportCompleted(
          projectId: _projectId,
          exportType: exportFormat,
          durationMs: exportStopwatch.elapsedMilliseconds,
          fileSize: exportFileSize,
        ),
      ),
    );

    final ext = p.extension(completedExportPath).replaceAll('.', '');
    final suggestedFileName = ExportSaveDialog.buildSuggestedFileName(
      baseName: _projectName,
      extension: ext,
    );
    final savedPath = await ExportSaveDialog.saveExportedFile(
      sourceFilePath: completedExportPath,
      suggestedFileName: suggestedFileName,
      desktopDialogTitle: L10n.translate(context, 'Save export'),
    );

    if (savedPath != null) {
      String? resolvedSavedDisplayName;
      String? resolvedPreviewPath;
      if (Platform.isAndroid) {
        resolvedSavedDisplayName =
            await ExportSaveDialog.resolveSavedDisplayNameFromPlatform(
              savedPath,
            );
        resolvedPreviewPath =
            await ExportSaveDialog.materializeSavedPreviewPathFromPlatform(
              savedPath,
            );

        final canAccessSavedMedia = await _ensureAndroidMediaLibraryAccess(
          rationale:
              'Mixroom needs access to audio files so the exported track can be previewed, shared, or opened from the success screen on Android.',
        );
        if (!canAccessSavedMedia) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                L10n.translate(
                  context,
                  'Media access is required to preview or open the saved export.',
                ),
              ),
            ),
          );
        }
      }

      if (!mounted) return;

      // final success_str = L10n.translate(context, 'Exported file saved!');
      // ScaffoldMessenger.of(context).showSnackBar(
      //   SnackBar(content: Text(success_str)),// at: $savedPath')),
      // );
      if (useContainedExportPanel) {
        setState(() {
          _tabletRightPanelTab = 'export';
          _tabletRightPanelCollapsed = false;
          _containedExportPanelStage = _ContainedExportPanelStage.success;
          _containedExportProgress = 1.0;
          _containedExportFilePath = completedExportPath;
          _containedExportPreviewFilePath = resolvedPreviewPath;
          _containedExportSavedFilePath = savedPath;
          _containedExportSavedFileName =
              resolvedSavedDisplayName ?? suggestedFileName;
        });
        return;
      }

      final ExportSuccessAction? action =
          await Navigator.push<ExportSuccessAction>(
            context,
            MaterialPageRoute(
              builder: (context) => ExportSuccessScreen(
                filePath: completedExportPath,
                previewFilePath: resolvedPreviewPath,
                savedFilePath: savedPath,
                savedFileName: resolvedSavedDisplayName ?? suggestedFileName,
                isVideo: false,
              ),
            ),
          );

      final shouldDeleteResolvedPreview =
          resolvedPreviewPath != null &&
          resolvedPreviewPath.isNotEmpty &&
          resolvedPreviewPath != completedExportPath &&
          resolvedPreviewPath != savedPath;
      if (shouldDeleteResolvedPreview) {
        try {
          final previewFile = File(resolvedPreviewPath);
          if (await previewFile.exists()) {
            await previewFile.delete();
          }
        } catch (_) {}
      }

      try {
        final tempExport = File(completedExportPath);
        if (await tempExport.exists()) {
          await tempExport.delete();
        }
      } catch (_) {}

      if (action == ExportSuccessAction.exitToProjects) {
        await _handleBackPressed();
        return;
      }
    } else {
      if (!mounted) return;
      if (useContainedExportPanel) {
        setState(() {
          _containedExportPanelStage = _ContainedExportPanelStage.idle;
          _containedExportProgress = 0.0;
        });
      }
      final fail_str = L10n.translate(context, 'Export canceled or failed.');
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(fail_str)));
    }
  }

  bool _isSampleAudioFile(String path) {
    final ext = p.extension(path).toLowerCase();
    return _kSampleAudioExtensions.contains(ext);
  }

  Future<bool> _insertAudioFileAtTimeline(
    String filePath, {
    int? row,
    double? timeMs,
    bool enforceKnownAudioExtension = true,
    String uploadMethod = 'import',
    bool showLoadingOverlay = true,
    bool notifyUi = true,
    bool deferFadeSync = false,
  }) async {
    if (enforceKnownAudioExtension && !_isSampleAudioFile(filePath)) {
      return false;
    }
    if (!File(filePath).existsSync()) {
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(L10n.translate(context, 'File is unavailable.')),
        ),
      );
      return false;
    }

    await _stopSampleAudition();
    final beforeClipCount = _audioTracks.length;
    try {
      await _undoManager.execute(
        AddAudioTrackAction(
          addTrack:
              ({
                required File file,
                required int row,
                required double timeMs,
                Duration? trimStartRequested,
                Duration? trimEndRequested,
              }) => _addAudioTrackFromFile(
                file,
                row,
                timeMs,
                showLoadingOverlay: showLoadingOverlay,
                uploadMethod: uploadMethod,
                notifyUi: notifyUi,
                deferFadeSync: deferFadeSync,
              ),
          tracks: _audioTracks,
          restoreTrack: _addClipFromUndoPayload,
          file: File(filePath),
          row: row ?? _selectedRow,
          timeMs: timeMs ?? _globalAudioClock.inMilliseconds.toDouble(),
          onRemove: _syncRemovedClipFadesAfterUndo,
        ),
      );
    } catch (error, stackTrace) {
      debugPrint('Failed to insert audio file at timeline: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      return false;
    }
    return _audioTracks.length > beforeClipCount;
  }

  Future<void> _pickAndInsertAudioTrack() async {
    if (!await _ensureAndroidMediaLibraryAccess()) {
      return;
    }

    if (_isPlaying) {
      await _pausePlayback();
    }
    final result = await _runFilePickerRequest<FilePickerResult?>(
      () => FilePicker.platform.pickFiles(type: FileType.any),
    );
    if (result == null ||
        result.files.isEmpty ||
        result.files.single.path == null) {
      return;
    }
    final pickedPath = result.files.single.path!;
    await _insertAudioFileAtTimeline(
      pickedPath,
      enforceKnownAudioExtension: false,
    );
  }

  Future<bool> _ensureAndroidMediaLibraryAccess({String? rationale}) async {
    if (!Platform.isAndroid) return true;

    final audioStatus = await Permission.audio.request();
    if (audioStatus.isGranted || audioStatus.isLimited) {
      return true;
    }
    PermissionStatus storageStatus = PermissionStatus.denied;
    try {
      storageStatus = await Permission.storage.request();
    } catch (_) {}
    if (storageStatus.isGranted || storageStatus.isLimited) {
      return true;
    }

    if (!mounted) return false;
    final openSettingsRequested =
        await showDialog<bool>(
          context: context,
          builder: (ctx) {
            return AlertDialog(
              title: Text(L10n.translate(ctx, 'Allow media access')),
              content: Text(
                L10n.translate(
                  ctx,
                  rationale ??
                      'Mixroom needs access to audio files to browse sample folders and import local media on Android.',
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx, false),
                  child: Text(L10n.translate(ctx, 'Not now')),
                ),
                TextButton(
                  onPressed: () => Navigator.pop(ctx, true),
                  child: Text(L10n.translate(ctx, 'Open settings')),
                ),
              ],
            );
          },
        ) ??
        false;

    if (openSettingsRequested) {
      await _openAppPermissionsSettings();
    }
    return false;
  }

  bool _hasAndroidSharedStorageSampleBrowserRoot() {
    if (!Platform.isAndroid) return false;
    return _sampleBrowserRoots.any(
      SampleBrowserRootDefaults.isAndroidSharedStoragePath,
    );
  }

  Future<bool> _ensureAndroidSampleBrowserMediaAccessIfNeeded() async {
    if (!Platform.isAndroid) return true;
    if (!_hasAndroidSharedStorageSampleBrowserRoot()) {
      return true;
    }
    return _ensureAndroidMediaLibraryAccess(
      rationale:
          'Mixroom needs access to audio files to show samples in your saved Android folders.',
    );
  }

  Future<PermissionStatus> _getMicrophonePermissionStatus() async {
    try {
      if (Platform.isAndroid || Platform.isIOS) {
        return await Permission.microphone.status;
      }
      if (Platform.isMacOS) {
        final granted = await _micRecorder.hasPermission(request: false);
        return granted ? PermissionStatus.granted : PermissionStatus.denied;
      }
    } on MissingPluginException catch (error, stackTrace) {
      debugPrint('Microphone permission status plugin unavailable: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
    } catch (error, stackTrace) {
      debugPrint('Failed to read microphone permission status: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
    }
    return PermissionStatus.granted;
  }

  Future<PermissionStatus> _requestMicrophonePermission() async {
    try {
      if (Platform.isAndroid || Platform.isIOS) {
        return await Permission.microphone.request();
      }
      if (Platform.isMacOS) {
        final granted = await _micRecorder.hasPermission();
        return granted ? PermissionStatus.granted : PermissionStatus.denied;
      }
    } on MissingPluginException catch (error, stackTrace) {
      debugPrint('Microphone permission request plugin unavailable: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
    } catch (error, stackTrace) {
      debugPrint('Failed to request microphone permission: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
    }
    return PermissionStatus.granted;
  }

  Future<void> _requestMicrophoneAccessFromSettingsPanel() async {
    final status = await _requestMicrophonePermission();
    if (!mounted) return;
    _setStateAndRefreshProjectSettings(() {
      _microphonePermissionStatus = status;
      _microphoneAccessBlocked = !(status.isGranted || status.isLimited);
    });
    if (!_microphoneAccessBlocked) {
      await _loadInputDevicesFromJuce();
      return;
    }
    if (status.isPermanentlyDenied || status.isRestricted) {
      await _openAppPermissionsSettings();
    }
  }

  Future<void> _maybePromptMicrophonePermissionOnDawEntry() async {
    if (_dawEntryMicPromptHandled) return;
    _dawEntryMicPromptHandled = true;
    if (!(Platform.isAndroid || Platform.isIOS)) return;

    final status = await _getMicrophonePermissionStatus();
    if (status.isGranted || status.isLimited) return;

    final requested = await _requestMicrophonePermission();
    if (!mounted) return;

    final granted = requested.isGranted || requested.isLimited;
    _setStateAndRefreshProjectSettings(() {
      _microphonePermissionStatus = requested;
      _microphoneAccessBlocked = !granted;
    });

    if (granted) return;

    if (requested.isPermanentlyDenied || requested.isRestricted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Microphone access is blocked. Open app settings to enable recording.',
          ),
        ),
      );
    }
  }

  Future<void> _refreshMicrophonePermissionState() async {
    final status = await _getMicrophonePermissionStatus();
    if (!mounted) return;
    _setStateAndRefreshProjectSettings(() {
      _microphonePermissionStatus = status;
      _microphoneAccessBlocked = !(status.isGranted || status.isLimited);
    });
  }

  Future<void> _refreshMicrophonePermissionAndInputs() async {
    if (!(_bluetoothImplementationSessionV2?.allowsLegacyInputLifecycle ??
        true)) {
      return;
    }
    await _refreshMicrophonePermissionState();
    if (!mounted) return;
    await _loadInputDevicesFromJuce();
  }

  Future<void> _openAppPermissionsSettings() async {
    if (Platform.isMacOS) {
      final uri = Uri.parse(
        'x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone',
      );
      if (await canLaunchUrl(uri)) {
        await launchUrl(uri);
      }
      return;
    }
    await openAppSettings();
    if (!mounted) return;
    unawaited(_refreshMicrophonePermissionAndInputs());
  }

  Future<bool> _addSampleBrowserRootFromPath(
    String directoryPath, {
    bool revealPanel = true,
    bool showDuplicateFeedback = true,
  }) async {
    final normalized = _normalizePickedDirectoryPath(directoryPath);
    if (normalized.isEmpty) {
      if (!mounted) return false;
      _showSmallNotice(
        Platform.isAndroid
            ? 'Could not open that folder. Choose a concrete subfolder instead.'
            : 'Could not open that folder.',
      );
      return false;
    }
    if (_isAndroidRootFolderPath(normalized)) {
      if (!mounted) return false;
      _showSmallNotice(
        'Phone root cannot be granted to apps on Android. Select a subfolder instead.',
      );
      return false;
    }

    if (Platform.isAndroid &&
        SampleBrowserRootDefaults.isAndroidSharedStoragePath(normalized)) {
      final granted = await _ensureAndroidMediaLibraryAccess(
        rationale:
            'Mixroom needs access to audio files to show samples in the folder you selected.',
      );
      if (!granted || !mounted) return false;
    }

    if (_sampleBrowserRoots.contains(normalized)) {
      if (mounted && showDuplicateFeedback) {
        _showSmallNotice(
          L10n.translate(context, 'Folder already loaded for this project.'),
        );
      }
      return false;
    }

    await _startSecurityScopedAccessForPath(normalized);
    final persistentAccess =
        _pendingPickedSampleBrowserAccess?.path == normalized
        ? _pendingPickedSampleBrowserAccess
        : await SampleBrowserAccess.createPersistentAccess(normalized);
    _pendingPickedSampleBrowserAccess = null;
    if (persistentAccess?.persistentToken != null) {
      _sampleBrowserPersistentTokens[normalized] =
          persistentAccess!.persistentToken!;
    }

    setState(() {
      _sampleBrowserRoots.add(normalized);
      if (revealPanel) {
        _sampleBrowserVisible = true;
      }
    });
    unawaited(_persistSampleBrowserRoots());
    if (revealPanel) {
      _setDawPanelVisible('sample_browser', true);
    }
    _invalidateAiLibrarySnapshotCache();
    return true;
  }

  Future<void> _addSampleBrowserRootFolder() async {
    final directoryPath = await _pickSampleBrowserRootDirectory();
    if (directoryPath == null) {
      return;
    }
    await _addSampleBrowserRootFromPath(directoryPath);
  }

  Future<String?> _pickSampleBrowserRootDirectory() async {
    try {
      return await _runFilePickerRequest<String?>(
        () => FilePicker.platform.getDirectoryPath(
          dialogTitle: 'Choose Sample Folder',
        ),
      );
    } on PlatformException catch (error, stackTrace) {
      debugPrint('Failed to pick sample browser folder: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      if (mounted) {
        _showSmallNotice(
          Platform.isAndroid
              ? 'Could not open the folder picker. Try choosing audio files from Import instead.'
              : 'Could not open the folder picker.',
        );
      }
      return null;
    }
  }

  bool _isAndroidRootFolderPath(String path) {
    if (!Platform.isAndroid) return false;
    final normalized = p.normalize(path);
    const rootCandidates = <String>{
      '/storage/emulated/0',
      '/sdcard',
      '/storage/self/primary',
    };
    return rootCandidates.contains(normalized);
  }

  Future<T?> _runFilePickerRequest<T>(Future<T?> Function() request) async {
    if (_filePickerInFlight) return null;
    _filePickerInFlight = true;
    try {
      // Avoid presenting a native picker during an active Flutter route transition.
      await SchedulerBinding.instance.endOfFrame;
      return await request();
    } on PlatformException catch (e) {
      if (e.code != 'multiple_request') rethrow;
      await SchedulerBinding.instance.endOfFrame;
      try {
        return await request();
      } on PlatformException catch (retryError) {
        if (retryError.code == 'multiple_request') {
          debugPrint(
            'FilePicker still reported multiple_request after retry; dropping duplicate picker call.',
          );
          return null;
        }
        rethrow;
      }
    } finally {
      _filePickerInFlight = false;
    }
  }

  bool get _usesSecurityScopedResources => Platform.isIOS || Platform.isMacOS;

  Future<void> _startSecurityScopedAccessForPath(String path) async {
    if (!_usesSecurityScopedResources) return;
    final normalized = _normalizePickedDirectoryPath(path);
    if (normalized.isEmpty) return;

    final keys = <String>{
      normalized,
      if (normalized.startsWith('/private/'))
        normalized.replaceFirst('/private', ''),
      if (normalized.startsWith('/var/')) '/private$normalized',
      'uri:${Uri.file(normalized).toString()}',
    };

    for (final key in keys) {
      if (_startedSecurityScopeKeys.contains(key)) continue;
      bool granted = false;
      try {
        if (key.startsWith('uri:')) {
          granted = await _securityScopedResource
              .startAccessingSecurityScopedResourceWithURL(key.substring(4));
        } else {
          granted = await _securityScopedResource
              .startAccessingSecurityScopedResourceWithFilePath(key);
        }
      } catch (_) {
        granted = false;
      }
      if (!granted) continue;
      _startedSecurityScopeKeys.add(key);
      _securityScopeStartCount += 1;
    }
  }

  Future<void> _startSecurityScopedAccessForFile(String filePath) async {
    if (!_usesSecurityScopedResources) return;
    final normalizedFilePath = p.normalize(filePath);
    final matchingRoots = _sampleBrowserRoots
        .where((root) {
          final normalizedRoot = p.normalize(root);
          final rootPrefix = normalizedRoot.endsWith('/')
              ? normalizedRoot
              : '$normalizedRoot/';
          return normalizedFilePath == normalizedRoot ||
              normalizedFilePath.startsWith(rootPrefix);
        })
        .toList(growable: false);
    for (final root in matchingRoots) {
      await _startSecurityScopedAccessForPath(root);
    }
  }

  void _stopAllSecurityScopedAccess() {
    if (!_usesSecurityScopedResources || _startedSecurityScopeKeys.isEmpty) {
      return;
    }
    for (final key in _startedSecurityScopeKeys) {
      try {
        if (key.startsWith('uri:')) {
          unawaited(
            _securityScopedResource.stopAccessingSecurityScopedResourceWithURL(
              key.substring(4),
            ),
          );
        } else {
          unawaited(
            _securityScopedResource
                .stopAccessingSecurityScopedResourceWithFilePath(key),
          );
        }
      } catch (_) {}
    }
    _securityScopeStartCount = 0;
    _startedSecurityScopeKeys.clear();
  }

  String _normalizePickedDirectoryPath(String rawPath) {
    final raw = rawPath.trim();
    if (raw.isEmpty) return '';

    final candidates = <String>{};

    void addCandidate(String value) {
      var path = value.trim();
      if (path.isEmpty) return;

      if (path.startsWith('file://')) {
        try {
          path = Uri.parse(path).toFilePath();
        } catch (_) {}
      }

      try {
        path = Uri.decodeFull(path);
      } catch (_) {}

      path = path.replaceAll('\\', '/');
      if (!path.startsWith('/')) return;
      path = p.normalize(path);
      candidates.add(path);

      if (path.startsWith('/private/')) {
        candidates.add(p.normalize(path.replaceFirst('/private', '')));
      } else if (path.startsWith('/var/')) {
        candidates.add(p.normalize('/private$path'));
      }
    }

    addCandidate(raw);
    try {
      final uri = Uri.parse(raw);
      if (uri.scheme == 'file') {
        addCandidate(uri.toFilePath());
      }
    } catch (_) {}

    for (final candidate in candidates) {
      if (Directory(candidate).existsSync()) return candidate;
    }

    if (candidates.isNotEmpty) {
      return candidates.first;
    }

    return '';
  }

  Future<String?> _ensureUserSampleDropFolderPath() async {
    try {
      final documentsDir = await getApplicationDocumentsDirectory();
      final dropDir = Directory(
        p.join(documentsDir.path, kUserSampleDropFolderName),
      );
      if (!await dropDir.exists()) {
        await dropDir.create(recursive: true);
      }
      return p.normalize(dropDir.path);
    } catch (error, stackTrace) {
      debugPrint('Failed to prepare user sample drop folder: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      return null;
    }
  }

  Future<String?> _ensureProjectAudioFolderPath() async {
    try {
      final audioDir = ProjectManager.audioDir(_projectDir);
      if (!await audioDir.exists()) {
        await audioDir.create(recursive: true);
      }
      return p.normalize(audioDir.path);
    } catch (error, stackTrace) {
      debugPrint('Failed to prepare project audio folder root: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      return null;
    }
  }

  List<String> _orderedSampleBrowserRootsWithDefaults({
    required List<String> bundledRoots,
    required String? projectAudioRoot,
    required String? userDropRoot,
  }) {
    return SampleBrowserRootDefaults.orderedRoots(
      bundledRoots: bundledRoots,
      projectAudioRoot: projectAudioRoot,
      userDropRoot: userDropRoot,
      userRoots: _sampleBrowserRoots,
    );
  }

  Set<String> get _fixedSampleBrowserRootFolders {
    return SampleBrowserRootDefaults.fixedRoots(
      projectAudioRoot: _sampleBrowserProjectAudioFolderPath,
      userDropRoot: _sampleBrowserUserDropFolderPath,
    );
  }

  bool _isFixedSampleBrowserRoot(String rootPath) {
    final normalizedRoot = p.normalize(rootPath);
    return _fixedSampleBrowserRootFolders.contains(normalizedRoot);
  }

  Future<void> _ensureDefaultSampleBrowserRoots() async {
    final userDropRoot = await _ensureUserSampleDropFolderPath();
    final projectAudioRoot = await _ensureProjectAudioFolderPath();

    List<String> bundledRoots = const <String>[];
    try {
      bundledRoots = await _mountBundledSamplePacks();
    } catch (error, stackTrace) {
      debugPrint('Failed to mount bundled sample packs: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
    }

    final nextRoots = _orderedSampleBrowserRootsWithDefaults(
      bundledRoots: bundledRoots,
      projectAudioRoot: projectAudioRoot,
      userDropRoot: userDropRoot,
    );
    for (final root in nextRoots) {
      await _startSecurityScopedAccessForPath(root);
    }
    final normalizedProjectAudioRoot = projectAudioRoot == null
        ? null
        : p.normalize(projectAudioRoot);
    final normalizedUserDropRoot = userDropRoot == null
        ? null
        : p.normalize(userDropRoot);
    final bundledRootSet = bundledRoots
        .map(SampleBrowserRootDefaults.normalizeRoot)
        .where((root) => root.isNotEmpty)
        .toSet();
    final rootsChanged = !_sameStringList(_sampleBrowserRoots, nextRoots);
    final projectAudioChanged =
        _sampleBrowserProjectAudioFolderPath != normalizedProjectAudioRoot;
    final userDropChanged =
        _sampleBrowserUserDropFolderPath != normalizedUserDropRoot;
    final bundledRootsChanged = !setEquals<String>(
      _sampleBrowserBundledRootFolders,
      bundledRootSet,
    );
    if (!rootsChanged &&
        !projectAudioChanged &&
        !userDropChanged &&
        !bundledRootsChanged) {
      return;
    }

    if (mounted) {
      setState(() {
        _sampleBrowserProjectAudioFolderPath = normalizedProjectAudioRoot;
        _sampleBrowserUserDropFolderPath = normalizedUserDropRoot;
        _sampleBrowserBundledRootFolders
          ..clear()
          ..addAll(bundledRootSet);
        if (rootsChanged) {
          _sampleBrowserRoots
            ..clear()
            ..addAll(nextRoots);
        }
      });
    } else {
      _sampleBrowserProjectAudioFolderPath = normalizedProjectAudioRoot;
      _sampleBrowserUserDropFolderPath = normalizedUserDropRoot;
      _sampleBrowserBundledRootFolders
        ..clear()
        ..addAll(bundledRootSet);
      if (rootsChanged) {
        _sampleBrowserRoots
          ..clear()
          ..addAll(nextRoots);
      }
    }

    if (rootsChanged || projectAudioChanged || userDropChanged) {
      unawaited(_persistSampleBrowserRoots());
    }
    if (rootsChanged || bundledRootsChanged) {
      _invalidateAiLibrarySnapshotCache();
    }
  }

  Future<void> _flushPendingDesktopFinderDrops() async {
    if (!PlatformCapabilities.current.isDesktop ||
        _pendingDesktopFinderDragEvents.isEmpty) {
      return;
    }
    final pending = List<DesktopFileDragEvent>.from(
      _pendingDesktopFinderDragEvents,
    );
    _pendingDesktopFinderDragEvents.clear();
    for (final event in pending) {
      if (event.phase != DesktopFileDragPhase.dropped) continue;
      await _handleDesktopFinderDragDrop(event);
    }
  }

  Future<void> _handleDesktopFinderDragEvent(DesktopFileDragEvent event) async {
    if (!mounted || !PlatformCapabilities.current.isDesktop) return;
    assert(() {
      debugPrint(
        '[FinderDrop] ${event.phase.name} audio=${event.hasAudio} '
        'loc=${event.location} items=${event.items.length}',
      );
      return true;
    }());
    switch (event.phase) {
      case DesktopFileDragPhase.entered:
      case DesktopFileDragPhase.updated:
        _handleDesktopFinderDragHover(event);
        return;
      case DesktopFileDragPhase.exited:
        _clearDesktopFinderDragPreview();
        return;
      case DesktopFileDragPhase.dropped:
        await _handleDesktopFinderDragDrop(event);
        return;
    }
  }

  void _handleDesktopFinderDragHover(DesktopFileDragEvent event) {
    if (!event.hasAudio || event.location == null) {
      if (!event.hasAudio) {
        _clearDesktopFinderDragPreview();
      }
      return;
    }

    final firstAudio = event.audioItems.first;
    final existing = _finderSampleDragData;
    if (existing == null || existing.filePath != firstAudio.path) {
      _finderSampleDragData = SampleDragData(
        filePath: firstAudio.path,
        label: p.basename(firstAudio.path),
      );
      unawaited(_resolveFinderSampleDragDuration(firstAudio.path));
    }

    if (!_sampleDragActive) {
      setState(() {
        _sampleDragActive = true;
      });
    }

    _timelineController.updateExternalSampleDropPreview(
      event.location!,
      data: _finderSampleDragData,
    );
  }

  Future<void> _resolveFinderSampleDragDuration(String filePath) async {
    _finderSampleDragDurationPath = filePath;
    final duration = await _resolveSampleDuration(filePath);
    if (!mounted) return;
    if (_finderSampleDragDurationPath != filePath) return;
    final current = _finderSampleDragData;
    if (current == null || current.filePath != filePath) return;
    if (duration == null || duration <= Duration.zero) return;
    if (current.duration == duration) return;
    setState(() {
      _finderSampleDragData = SampleDragData(
        filePath: current.filePath,
        label: current.label,
        duration: duration,
      );
    });
  }

  void _clearDesktopFinderDragPreview() {
    _finderSampleDragDurationPath = null;
    _finderSampleDragData = null;
    _timelineController.clearExternalSampleDropPreview();
    if (_sampleDragActive && mounted) {
      setState(() {
        _sampleDragActive = false;
      });
    } else {
      _sampleDragActive = false;
    }
  }

  Future<void> _handleDesktopFinderDragDrop(DesktopFileDragEvent event) async {
    final dragData = _finderSampleDragData;
    _clearDesktopFinderDragPreview();

    SampleDropPlacement? placement;
    if (event.location != null && event.hasAudio) {
      placement = _timelineController.placementForExternalSampleDrop(
        event.location!,
        data:
            dragData ??
            SampleDragData(
              filePath: event.audioItems.first.path,
              label: p.basename(event.audioItems.first.path),
            ),
      );
    }

    if (placement != null && !placement.allowed) {
      await _handleDesktopFinderDropBatch(event.items, skipAudio: true);
      return;
    }

    await _handleDesktopFinderDropBatch(
      event.items,
      dropRow: placement?.row,
      dropTimeMs: placement?.startMs,
    );
  }

  Future<void> _handleDesktopFinderDropBatch(
    List<DesktopFileDropItem> items, {
    int? dropRow,
    double? dropTimeMs,
    bool skipAudio = false,
  }) async {
    if (!mounted || !PlatformCapabilities.current.isDesktop || items.isEmpty) {
      return;
    }

    final audioItems = skipAudio
        ? const <DesktopFileDropItem>[]
        : items.where((item) => item.isAudio).toList(growable: false);
    final folderItems = items
        .where((item) => item.isFolder && !item.isMixroom)
        .toList(growable: false);
    final projectItems = items
        .where((item) => item.isMixroom)
        .toList(growable: false);

    var addedFolderCount = 0;
    for (final item in folderItems) {
      final added = await _addSampleBrowserRootFromPath(
        item.path,
        revealPanel: true,
        showDuplicateFeedback: false,
      );
      if (added) {
        addedFolderCount += 1;
      }
    }

    var insertedAudioCount = 0;
    var nextRow = dropRow ?? _selectedRow;
    final resolvedDropTimeMs =
        dropTimeMs ?? _globalAudioClock.inMilliseconds.toDouble();
    final batchAudioDrop = audioItems.length > 1;
    final affectedFadeRowIds = <int>{};
    if (batchAudioDrop) {
      await JuceAudioEngine.beginProjectClipLoad();
    }
    try {
      for (final item in audioItems) {
        final inserted = await _insertAudioFileAtTimeline(
          item.path,
          row: nextRow,
          timeMs: resolvedDropTimeMs,
          uploadMethod: 'finder_drop',
          showLoadingOverlay: !batchAudioDrop,
          notifyUi: !batchAudioDrop,
          deferFadeSync: batchAudioDrop,
        );
        if (inserted) {
          insertedAudioCount += 1;
          if (_audioTracks.isNotEmpty) {
            affectedFadeRowIds.add(_audioTracks.last.rowId);
          }
          nextRow += 1;
        }
      }
    } finally {
      if (batchAudioDrop) {
        await JuceAudioEngine.endProjectClipLoad();
        await _syncClipFadesForRowsToEngine(affectedFadeRowIds);
        if (mounted) setState(() {});
      }
    }

    if (insertedAudioCount > 0 && mounted) {
      _showSmallNotice(
        insertedAudioCount == 1
            ? 'Imported 1 dropped audio file.'
            : 'Imported $insertedAudioCount dropped audio files.',
      );
    } else if (addedFolderCount > 0 && mounted) {
      _showSmallNotice(
        addedFolderCount == 1
            ? 'Added 1 dropped folder to the file browser.'
            : 'Added $addedFolderCount dropped folders to the file browser.',
      );
    }

    if (projectItems.isNotEmpty && mounted) {
      _showSmallNotice('Project bundles can be imported from Home.');
    }
  }

  void _invalidateAiLibrarySnapshotCache() {
    _aiLibrarySnapshotCache = '';
    _aiLibrarySnapshotCacheKey = null;
    _aiLibrarySamplePathIndex.clear();
    _aiLibraryRolePathIndex.clear();
  }

  Future<List<String>> _collectAiLibraryAudioEntriesForRoot(
    String rootPath,
  ) async {
    final root = Directory(rootPath);
    if (!await root.exists()) return const <String>[];

    final out = <String>[];
    await for (final entity in root.list(recursive: true, followLinks: false)) {
      if (entity is! File) continue;
      if (!_isSampleAudioFile(entity.path)) continue;
      final relative = p
          .relative(entity.path, from: root.path)
          .replaceAll('\\', '/');
      if (relative.startsWith('..') || relative.trim().isEmpty) continue;
      out.add(relative);
    }
    out.sort();
    return out;
  }

  static const List<String> _kAiLibraryPreferredSampleRoles = <String>[
    'kick',
    'snare',
    'clap',
    'hat',
    'perc',
    'cymbal',
    'tom',
    'loop',
    'fx',
    'bass',
    'vocal',
    'melodic',
  ];

  String? _normalizeAiLibraryRoleAlias(String raw) {
    final normalized = raw.trim().toLowerCase();
    if (normalized.isEmpty) return null;
    const directAliases = <String, String>{
      'kick': 'kick',
      'kicks': 'kick',
      'snare': 'snare',
      'snares': 'snare',
      'clap': 'clap',
      'claps': 'clap',
      'hat': 'hat',
      'hats': 'hat',
      'hihat': 'hat',
      'hihats': 'hat',
      'perc': 'perc',
      'percussion': 'perc',
      'cymbal': 'cymbal',
      'cymbals': 'cymbal',
      'crash': 'cymbal',
      'crashes': 'cymbal',
      'ride': 'cymbal',
      'tom': 'tom',
      'toms': 'tom',
      'loop': 'loop',
      'loops': 'loop',
      'fx': 'fx',
      'effect': 'fx',
      'effects': 'fx',
      'bass': 'bass',
      'vocal': 'vocal',
      'vocals': 'vocal',
      'melodic': 'melodic',
      'melody': 'melodic',
    };
    return directAliases[normalized];
  }

  String _formatAiLibraryRoleCounts(Map<String, int> counts) {
    final orderedRoles = counts.keys.toList()
      ..sort((a, b) {
        final ai = _kAiLibraryPreferredSampleRoles.indexOf(a);
        final bi = _kAiLibraryPreferredSampleRoles.indexOf(b);
        if (ai >= 0 && bi >= 0) return ai.compareTo(bi);
        if (ai >= 0) return -1;
        if (bi >= 0) return 1;
        return a.compareTo(b);
      });
    return orderedRoles
        .where((role) => (counts[role] ?? 0) > 0)
        .map((role) => '$role:${counts[role]}')
        .join(', ');
  }

  String _formatAiLibraryFolderExamples(
    Map<String, String> examples,
    List<String> fallbackPaths,
  ) {
    final orderedRoles = examples.keys.toList()
      ..sort((a, b) {
        final ai = _kAiLibraryPreferredSampleRoles.indexOf(a);
        final bi = _kAiLibraryPreferredSampleRoles.indexOf(b);
        if (ai >= 0 && bi >= 0) return ai.compareTo(bi);
        if (ai >= 0) return -1;
        if (bi >= 0) return 1;
        return a.compareTo(b);
      });
    final parts = orderedRoles
        .take(4)
        .map((role) => '$role=${examples[role]}')
        .toList(growable: false);
    if (parts.isNotEmpty) {
      return parts.join(', ');
    }
    return fallbackPaths.take(3).join(', ');
  }

  Future<void> _autoConfigureInsertedLibraryClip(
    AudioTrack clip,
    String libraryPath, {
    bool deferEngineSync = false,
  }) async {
    final primaryRole = AssistantActionUtils.primarySampleRoleFromText(
      libraryPath,
    );
    if (primaryRole != 'loop') return;

    double? sourceTempoBpm;
    final tempoHints = AssistantActionUtils.tempoHintsFromText(libraryPath);
    if (tempoHints.isNotEmpty) {
      sourceTempoBpm = tempoHints.first.toDouble();
    } else {
      sourceTempoBpm = await _detectClipTempoBpm(clip);
    }
    if (sourceTempoBpm == null || !sourceTempoBpm.isFinite) return;

    final clipIndex = _audioTracks.indexOf(clip);
    if (clipIndex < 0) return;

    void applyTempoFollow() {
      _tempoStretchEnabled = true;
      clip.sourceTempoBpm = _clampTempo(sourceTempoBpm!);
      clip.stretchToProjectTempo = true;
      clip.tempoStretchPreservePitch = true;
    }

    if (deferEngineSync) {
      applyTempoFollow();
      _updateOverallDurationIfNeeded(
        changedClips: <AudioTrack>[clip],
        notifyUi: false,
      );
    } else {
      _setStateAndRefreshProjectSettings(applyTempoFollow);
      await _syncClipTimingToEngine(clipIndex);
      await _syncClipMixToEngine(clip);
      _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
      _scheduleProjectAutosave();
      if (mounted) setState(() {});
    }
  }

  Future<String> _buildAiLibrarySnapshot() async {
    await _ensureDefaultSampleBrowserRoots();
    final catalog = _uiInstrumentCatalog().toList(growable: false)
      ..sort(_compareInstrumentSpecsForPicker);
    final roots = _sampleBrowserRoots.map(p.normalize).toList(growable: false)
      ..sort();
    final cacheKey = jsonEncode(<String, dynamic>{
      'instrument_ids': catalog
          .map((spec) => (spec['id'] as String? ?? '').trim())
          .where((id) => id.isNotEmpty)
          .toList(growable: false),
      'sample_roots': roots,
    });
    if (_aiLibrarySnapshotCacheKey == cacheKey &&
        _aiLibrarySnapshotCache.isNotEmpty) {
      return _aiLibrarySnapshotCache;
    }

    final lines = <String>[];
    final instrumentsByCategory = <String, List<String>>{};
    for (final spec in catalog) {
      final instrumentId = (spec['id'] as String? ?? '').trim();
      if (instrumentId.isEmpty) continue;
      final category = _instrumentPickerCategory(spec).trim();
      final bucket = category.isEmpty ? 'Other' : category;
      instrumentsByCategory
          .putIfAbsent(bucket, () => <String>[])
          .add(instrumentId);
    }
    lines.add('built_in_instruments:');
    if (instrumentsByCategory.isEmpty) {
      lines.add('- none');
    } else {
      final orderedCategories = instrumentsByCategory.keys.toList()..sort();
      for (final category in orderedCategories) {
        final ids = instrumentsByCategory[category]!..sort();
        lines.add('- $category: [${ids.join(', ')}]');
      }
    }

    final sampleIndex = <String, String>{};
    final groupedDisplay = <String, List<String>>{};
    final groupedRoleCounts = <String, Map<String, int>>{};
    final groupedRoleExamples = <String, Map<String, String>>{};
    final groupedTempoHints = <String, Set<int>>{};
    final roleHints = <String, List<String>>{};
    final rolePathIndex = <String, List<String>>{};
    List<String> sortPathsForRole(String role, List<String> paths) {
      final sorted = List<String>.from(paths);
      sorted.sort((a, b) {
        final scoreA = AssistantActionUtils.sampleRolePriorityScore(a, role);
        final scoreB = AssistantActionUtils.sampleRolePriorityScore(b, role);
        final byScore = scoreB.compareTo(scoreA);
        if (byScore != 0) return byScore;
        return a.compareTo(b);
      });
      return sorted;
    }

    if (roots.isNotEmpty) {
      lines.add('library_audio_samples:');
    }
    for (final rootPath in roots) {
      final rootName = p.basename(rootPath).trim().isEmpty
          ? p.normalize(rootPath)
          : p.basename(rootPath).trim();
      final entries = await _collectAiLibraryAudioEntriesForRoot(rootPath);
      if (entries.isEmpty) continue;
      for (final relative in entries) {
        final normalizedRelative = relative.replaceAll('\\', '/');
        final directory = p.dirname(normalizedRelative).replaceAll('\\', '/');
        final fileName = p.basename(normalizedRelative);
        final logicalFolder = directory == '.' || directory.isEmpty
            ? rootName
            : '$rootName/$directory';
        final logicalPath = '$logicalFolder/$fileName';
        final actualPath = p.normalize(
          p.join(rootPath, relative.replaceAll('/', p.separator)),
        );
        sampleIndex[logicalPath] = actualPath;
        groupedDisplay
            .putIfAbsent(logicalFolder, () => <String>[])
            .add(fileName);
        final primaryRole =
            AssistantActionUtils.primarySampleRoleFromText(logicalPath) ??
            'other';
        final folderCounts = groupedRoleCounts.putIfAbsent(
          logicalFolder,
          () => <String, int>{},
        );
        folderCounts[primaryRole] = (folderCounts[primaryRole] ?? 0) + 1;
        groupedRoleExamples
            .putIfAbsent(logicalFolder, () => <String, String>{})
            .putIfAbsent(primaryRole, () => logicalPath);
        final tempoHints = AssistantActionUtils.tempoHintsFromText(logicalPath);
        if (tempoHints.isNotEmpty) {
          groupedTempoHints
              .putIfAbsent(logicalFolder, () => <int>{})
              .addAll(tempoHints);
        }
        for (final roleHint in AssistantActionUtils.sampleRoleHintsFromText(
          logicalPath,
        )) {
          final bucket = roleHints.putIfAbsent(roleHint, () => <String>[]);
          if (!bucket.contains(logicalPath)) {
            bucket.add(logicalPath);
          }
        }
      }
    }

    if (sampleIndex.isEmpty) {
      lines.add('library_audio_samples: none');
    } else {
      if (roleHints.isNotEmpty) {
        lines.add('library_role_hints:');
        const preferredRoleOrder = <String>[
          'kick',
          'snare',
          'clap',
          'hat',
          'perc',
          'cymbal',
          'tom',
          'loop',
          'fx',
          'bass',
          'vocal',
          'melodic',
        ];
        final orderedRoles = roleHints.keys.toList()
          ..sort((a, b) {
            final ai = preferredRoleOrder.indexOf(a);
            final bi = preferredRoleOrder.indexOf(b);
            if (ai >= 0 && bi >= 0) return ai.compareTo(bi);
            if (ai >= 0) return -1;
            if (bi >= 0) return 1;
            return a.compareTo(b);
          });
        for (final role in orderedRoles) {
          final paths = sortPathsForRole(role, roleHints[role]!);
          rolePathIndex[role] = paths;
          lines.add(
            '- $role: count=${paths.length} alias=role:$role examples=[${paths.take(3).join(', ')}]',
          );
        }
      }
      final groupedFolders = groupedDisplay.keys.toList()..sort();
      for (final folder in groupedFolders) {
        final files = groupedDisplay[folder]!..sort();
        final roleCounts = groupedRoleCounts[folder] ?? const <String, int>{};
        final roleCountText = _formatAiLibraryRoleCounts(roleCounts);
        final examplesText = _formatAiLibraryFolderExamples(
          groupedRoleExamples[folder] ?? const <String, String>{},
          files.map((fileName) => '$folder/$fileName').toList(growable: false),
        );
        final tempoHints = (groupedTempoHints[folder] ?? const <int>{}).toList()
          ..sort();
        final line = StringBuffer('- $folder: total=${files.length}');
        if (roleCountText.isNotEmpty) {
          line.write(' counts=[$roleCountText]');
        }
        if (tempoHints.isNotEmpty) {
          line.write(' bpm_tags=[${tempoHints.join(', ')}]');
        }
        if (examplesText.isNotEmpty) {
          line.write(' examples=[$examplesText]');
        }
        lines.add(line.toString());
      }
    }

    _aiLibrarySnapshotCacheKey = cacheKey;
    _aiLibrarySnapshotCache = lines.join('\n');
    _aiLibrarySamplePathIndex
      ..clear()
      ..addAll(sampleIndex);
    _aiLibraryRolePathIndex
      ..clear()
      ..addAll(rolePathIndex);
    return _aiLibrarySnapshotCache;
  }

  Map<String, dynamic> _buildAiClientContext() {
    final entitlement = _currentEntitlementSnapshot;
    final allowedEffects = _isFreePlan
        ? SubscriptionLimits.freeBuiltInEffects.toList(growable: false)
        : kMixroomBuiltInEffects;
    final allowedInstrumentCatalog = _instrumentCatalogForCurrentPlan(
      _uiInstrumentCatalog(),
    );
    final allowedInstruments = allowedInstrumentCatalog
        .map((spec) => (spec['id'] as String? ?? '').trim())
        .where((id) => id.isNotEmpty)
        .toList(growable: false);
    final aiCapabilities = <String>{
      ...AnalyticsService.aiCapabilities,
      'daw.transport_control',
      'daw.row_mute',
      'daw.row_solo',
      'daw.row_rename',
      'daw.row_select',
      'daw.row_delete',
      'daw.row_create',
      'daw.row_mix',
      'daw.automation_edit',
      'daw.clean_content_rows',
      if (LlmConfig.effectiveAiV3Enabled) ...<String>{
        'ai_v3.one_shot.prototype',
        'daw.stem_separate',
        'daw.audio_enhance',
        'daw.midi_compose.audio_to_midi',
      },
    }.toList(growable: false);
    final v3LibraryAssets = LlmConfig.effectiveAiV3Enabled
        ? (_aiLibrarySamplePathIndex.keys.toList()..sort())
              .map((logicalPath) {
                final roles = AssistantActionUtils.sampleRoleHintsFromText(
                  logicalPath,
                );
                final tempos = AssistantActionUtils.tempoHintsFromText(
                  logicalPath,
                );
                final digest = crypto.sha256
                    .convert(utf8.encode(logicalPath))
                    .toString()
                    .substring(0, 16);
                return <String, dynamic>{
                  'asset_id': 'sample:$digest',
                  'path': logicalPath,
                  'role': roles.isEmpty ? 'other' : roles.first,
                  if (tempos.isNotEmpty) 'bpm': tempos.first,
                };
              })
              .toList(growable: false)
        : const <Map<String, dynamic>>[];
    return <String, dynamic>{
      'ai_capabilities': aiCapabilities,
      'ai_v3_prototype_enabled': LlmConfig.effectiveAiV3Enabled,
      if (LlmConfig.normalizedContextPackingMode != 'full')
        'ai_context_packing_mode': LlmConfig.normalizedContextPackingMode,
      if (LlmConfig.normalizedToolRoutingMode != 'full')
        'ai_tool_routing_mode': LlmConfig.normalizedToolRoutingMode,
      'subscription_plan': entitlement?.planCode ?? 'free',
      'max_rows': _effectiveMaxRows,
      'current_rows': _rowCount,
      'allowed_builtin_effects': allowedEffects,
      'allowed_instrument_ids': allowedInstruments,
      if (LlmConfig.effectiveAiV3Enabled) ...<String, dynamic>{
        'ai_v3_instrument_catalog': allowedInstrumentCatalog
            .map(
              (spec) => <String, dynamic>{
                'instrument_id': (spec['id'] as String? ?? '').trim(),
                'name': (spec['name'] as String? ?? '').trim(),
              },
            )
            .where(
              (entry) =>
                  entry['instrument_id']!.isNotEmpty &&
                  entry['name']!.isNotEmpty,
            )
            .toList(growable: false),
        'ai_v3_playhead_ms': _globalAudioClock.inMilliseconds,
        'ai_v3_transport': <String, dynamic>{
          'playing': _isPlaying,
          'recording': _recordButtonVisuallyActive,
          'metronome_enabled': _metronomeEnabled,
          'loop_enabled': _loopEnabled,
          'loop_start_ms': _loopStartMs,
          'loop_end_ms': _loopEndMs,
        },
        'ai_v3_tempo_stretch_enabled': _tempoStretchEnabled,
        'ai_v3_clip_timeline_lengths_ms': <String, double>{
          for (final clip in _audioTracks)
            if (clip.clipId.trim().isNotEmpty)
              clip.clipId: _clipTimelineDurationMs(clip),
        },
        'ai_v3_clip_source_available': <String, bool>{
          for (final clip in _audioTracks)
            if (!clip.isMidi && clip.clipId.trim().isNotEmpty)
              clip.clipId:
                  clip.file.existsSync() && clip.file.lengthSync() > 44,
        },
        'ai_v3_library_assets': v3LibraryAssets,
        'ai_v3_row_automation_points': <String, dynamic>{
          for (var index = 0; index < _rowCount; index++)
            _rowIdAt(index).toString(): <String, dynamic>{
              if (index < _rowVolumeAutomation.length)
                'volume': _rowVolumeAutomation[index]
                    .map(
                      (point) => <String, dynamic>{
                        'time_ms': point.x,
                        'value': point.volume,
                      },
                    )
                    .toList(growable: false),
              for (final entry
                  in (_rowPluginAutomation[index] ??
                          const <String, List<AutomationPoint>>{})
                      .entries)
                entry.key: entry.value
                    .map(
                      (point) => <String, dynamic>{
                        'time_ms': point.x,
                        'value': point.volume,
                      },
                    )
                    .toList(growable: false),
            },
        },
        'ai_v3_row_state': List<Map<String, dynamic>>.generate(
          _rowCount,
          (index) => <String, dynamic>{
            'row_id': _rowIdAt(index),
            'muted': index < _rowMuted.length ? _rowMuted[index] : false,
            'soloed': index < _rowSoloed.length ? _rowSoloed[index] : false,
          },
        ),
      },
      'plugin_access': _isFreePlan
          ? 'free_built_in_plus_on_device_plugins'
          : 'all_plugins',
      'row_creation_policy': _isFreePlan
          ? 'Do not create or target rows above row_index 4. If an operation needs new rows, reuse an existing row at or below row_index 4.'
          : 'Rows may be created up to the app row limit.',
    };
  }

  Future<String?> _resolveAiLibrarySamplePath(String logicalPath) async {
    final normalized = logicalPath.trim();
    if (normalized.isEmpty) return null;
    final normalizedLower = normalized.toLowerCase();
    if (normalizedLower.startsWith('role:')) {
      final role = _normalizeAiLibraryRoleAlias(
        normalized.substring('role:'.length),
      );
      if (role == null) return null;
      if (_aiLibraryRolePathIndex[role]?.isEmpty ?? true) {
        await _buildAiLibrarySnapshot();
      }
      final candidates = _aiLibraryRolePathIndex[role] ?? const <String>[];
      for (final candidate in candidates) {
        final resolved = _aiLibrarySamplePathIndex[candidate];
        if (resolved != null && File(resolved).existsSync()) {
          return resolved;
        }
      }
      return null;
    }
    if (_aiLibrarySamplePathIndex.containsKey(normalized)) {
      final cached = _aiLibrarySamplePathIndex[normalized]!;
      if (File(cached).existsSync()) return cached;
    }
    try {
      await _buildAiLibrarySnapshot();
    } catch (error, stackTrace) {
      debugPrint('Failed to build AI library snapshot: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      return null;
    }
    final resolved = _aiLibrarySamplePathIndex[normalized];
    if (resolved == null || !File(resolved).existsSync()) {
      return null;
    }
    return resolved;
  }

  Future<List<String>> _mountBundledSamplePacks() async {
    if (Platform.isAndroid) {
      final mountedRoots = await JuceAudioEngine.mountBundledSamplePacks();
      return mountedRoots.map(p.normalize).toList(growable: false);
    }
    final assetGroups = await _discoverBundledSamplePackAssetGroups();
    if (assetGroups.isEmpty) return const <String>[];
    final refreshToken = await _bundledSamplePackRefreshToken();

    final supportDir = await getApplicationSupportDirectory();
    final samplePacksDir = Directory(p.join(supportDir.path, 'sample_packs'));
    if (!await samplePacksDir.exists()) {
      await samplePacksDir.create(recursive: true);
    }

    final mountedRoots = <String>[];
    final packSlugs = assetGroups.keys.toList()..sort();
    for (final packSlug in packSlugs) {
      final assetPaths = assetGroups[packSlug];
      if (assetPaths == null || assetPaths.isEmpty) continue;
      try {
        final packDir = await _extractBundledSamplePack(
          samplePacksDir: samplePacksDir,
          packSlug: packSlug,
          assetPaths: assetPaths,
          refreshToken: refreshToken,
        );
        if (packDir != null) {
          mountedRoots.add(p.normalize(packDir.path));
        }
      } catch (error, stackTrace) {
        debugPrint('Failed to extract bundled sample pack "$packSlug": $error');
        unawaited(
          CrashReportingService.instance.captureException(
            error,
            stackTrace: stackTrace,
          ),
        );
      }
    }
    return mountedRoots;
  }

  Future<Map<String, List<String>>>
  _discoverBundledSamplePackAssetGroups() async {
    final discovered = <String>{};

    try {
      final manifest = await AssetManifest.loadFromAssetBundle(rootBundle);
      discovered.addAll(
        manifest.listAssets().where(
          (path) => path.startsWith(kBundledSamplePackAssetPrefix),
        ),
      );
    } catch (_) {
      try {
        final manifestRaw = await rootBundle.loadString('AssetManifest.json');
        final decoded = jsonDecode(manifestRaw);
        if (decoded is Map) {
          discovered.addAll(
            decoded.keys.whereType<String>().where(
              (path) => path.startsWith(kBundledSamplePackAssetPrefix),
            ),
          );
        }
      } catch (_) {
        return const <String, List<String>>{};
      }
    }

    final grouped = <String, List<String>>{};
    for (final assetPath in discovered) {
      final relative = p.posix.relative(
        assetPath,
        from: kBundledSamplePackAssetPrefix.replaceAll('\\', '/'),
      );
      if (relative.isEmpty || relative.startsWith('..')) continue;
      final parts = p.posix
          .split(relative)
          .where((part) => part.isNotEmpty)
          .toList(growable: false);
      // Ignore top-level helper files like assets/sample_packs/README.md.
      if (parts.length < 2) continue;
      final packSlug = parts.first;
      grouped.putIfAbsent(packSlug, () => <String>[]).add(assetPath);
    }

    for (final entry in grouped.values) {
      entry.sort();
    }
    return grouped;
  }

  Future<Directory?> _extractBundledSamplePack({
    required Directory samplePacksDir,
    required String packSlug,
    required List<String> assetPaths,
    required String refreshToken,
  }) async {
    final displayName = _displayNameForBundledSamplePack(packSlug);
    final packDir = Directory(p.join(samplePacksDir.path, displayName));
    final manifestFile = File(
      p.join(packDir.path, kBundledSamplePackManifestFileName),
    );
    String? bundlePackManifest;
    final packManifestAssetPath =
        '$kBundledSamplePackAssetPrefix$packSlug/$kBundledSamplePackManifestFileName';
    if (assetPaths.contains(packManifestAssetPath)) {
      try {
        bundlePackManifest = await rootBundle.loadString(packManifestAssetPath);
      } catch (_) {
        bundlePackManifest = null;
      }
    }
    final assetSignature = jsonEncode(<String, dynamic>{
      'paths': assetPaths,
      'packManifest': bundlePackManifest,
      'refreshToken': refreshToken,
    });

    bool needsRefresh = true;
    if (await manifestFile.exists()) {
      try {
        final decoded =
            jsonDecode(await manifestFile.readAsString())
                as Map<String, dynamic>;
        if (decoded['assetSignature'] == assetSignature) {
          needsRefresh = false;
          for (final assetPath in assetPaths) {
            final relative = p.posix.relative(
              assetPath,
              from: '$kBundledSamplePackAssetPrefix$packSlug',
            );
            if (relative.isEmpty || relative.startsWith('..')) continue;
            final outPath = p.joinAll(<String>[
              packDir.path,
              ...p.posix.split(relative),
            ]);
            if (!File(outPath).existsSync()) {
              needsRefresh = true;
              break;
            }
          }
        }
      } catch (_) {
        needsRefresh = true;
      }
    }

    if (!needsRefresh) {
      return packDir;
    }

    if (await packDir.exists()) {
      await packDir.delete(recursive: true);
    }
    await packDir.create(recursive: true);

    for (final assetPath in assetPaths) {
      final relative = p.posix.relative(
        assetPath,
        from: '$kBundledSamplePackAssetPrefix$packSlug',
      );
      if (relative.isEmpty || relative.startsWith('..')) continue;
      final outPath = p.joinAll(<String>[
        packDir.path,
        ...p.posix.split(relative),
      ]);
      final outFile = File(outPath);
      await outFile.parent.create(recursive: true);
      final data = await rootBundle.load(assetPath);
      final bytes = data.buffer.asUint8List(
        data.offsetInBytes,
        data.lengthInBytes,
      );
      await outFile.writeAsBytes(bytes, flush: true);
    }

    await manifestFile.writeAsString(
      jsonEncode(<String, dynamic>{
        'packSlug': packSlug,
        'displayName': displayName,
        'assetSignature': assetSignature,
        'updatedAt': DateTime.now().toIso8601String(),
      }),
    );
    return packDir;
  }

  Future<String> _bundledSamplePackRefreshToken() {
    return _bundledSamplePackRefreshTokenFuture ??= () async {
      try {
        final info = await PackageInfo.fromPlatform();
        final version = info.version.trim();
        final buildNumber = info.buildNumber.trim();
        if (version.isEmpty) return buildNumber;
        if (buildNumber.isEmpty) return version;
        return '$version+$buildNumber';
      } catch (_) {
        return '';
      }
    }();
  }

  String _displayNameForBundledSamplePack(String packSlug) {
    final normalized = packSlug.trim().replaceAll('-', '_');
    final parts = normalized
        .split('_')
        .map((part) => part.trim())
        .where((part) => part.isNotEmpty)
        .toList(growable: false);
    if (parts.isEmpty) return 'Sample Pack';
    return parts
        .map((part) {
          final lower = part.toLowerCase();
          if (RegExp(r'^v\d+$').hasMatch(lower) ||
              RegExp(r'^\d+$').hasMatch(lower)) {
            return lower;
          }
          if (lower == 'cc0') return 'CC0';
          return '${lower[0].toUpperCase()}${lower.substring(1)}';
        })
        .join(' ');
  }

  void _removeSampleBrowserRoot(String rootPath) {
    if (_isFixedSampleBrowserRoot(rootPath)) {
      return;
    }
    final normalizedRoot = p.normalize(rootPath);
    final rootPrefix = normalizedRoot.endsWith('/')
        ? normalizedRoot
        : '$normalizedRoot/';
    final removedAuditionPath = _auditioningSamplePath;
    final shouldStopAudition =
        removedAuditionPath != null &&
        (p.normalize(removedAuditionPath) == normalizedRoot ||
            p.normalize(removedAuditionPath).startsWith(rootPrefix));

    void stopSecurityScope(String key) {
      if (!_usesSecurityScopedResources ||
          !_startedSecurityScopeKeys.contains(key)) {
        return;
      }
      _startedSecurityScopeKeys.remove(key);
      _securityScopeStartCount = math.max(0, _securityScopeStartCount - 1);
      try {
        if (key.startsWith('uri:')) {
          unawaited(
            _securityScopedResource.stopAccessingSecurityScopedResourceWithURL(
              key.substring(4),
            ),
          );
        } else {
          unawaited(
            _securityScopedResource
                .stopAccessingSecurityScopedResourceWithFilePath(key),
          );
        }
      } catch (_) {}
    }

    final normalizedCandidates = <String>{
      normalizedRoot,
      if (normalizedRoot.startsWith('/private/'))
        normalizedRoot.replaceFirst('/private', ''),
      if (normalizedRoot.startsWith('/var/')) '/private$normalizedRoot',
      'uri:${Uri.file(normalizedRoot).toString()}',
    };
    final persistentToken = _sampleBrowserPersistentTokens.remove(
      normalizedRoot,
    );
    if (persistentToken != null) {
      unawaited(SampleBrowserAccess.release(persistentToken));
    }

    setState(() {
      _sampleBrowserRoots.removeWhere(
        (root) => p.normalize(root) == normalizedRoot,
      );
      _sampleDurationCache.removeWhere((k, _) {
        final normalized = p.normalize(k);
        return normalized == normalizedRoot ||
            normalized.startsWith(rootPrefix);
      });
      if (_sampleBrowserRoots.isEmpty) {
        _sampleBrowserExpanded = false;
      }
    });
    unawaited(_persistSampleBrowserRoots());
    _invalidateAiLibrarySnapshotCache();

    for (final key in normalizedCandidates) {
      stopSecurityScope(key);
    }

    if (shouldStopAudition) {
      unawaited(_stopSampleAudition());
    }
  }

  Future<void> _openSampleBrowser({bool promptFolderIfEmpty = false}) async {
    await _ensureDefaultSampleBrowserRoots();
    final hasAndroidMediaAccess =
        await _ensureAndroidSampleBrowserMediaAccessIfNeeded();
    if (Platform.isAndroid && !hasAndroidMediaAccess) {
      return;
    }
    if (promptFolderIfEmpty && _sampleBrowserRoots.isEmpty) {
      await _addSampleBrowserRootFolder();
      if (_sampleBrowserRoots.isEmpty) {
        return;
      }
    }
    if (!mounted) return;
    setState(() {
      _sampleBrowserVisible = true;
      _showAddActionsPanel = false;
      _chatExpanded = false;
      _chatInputActive = false;
      _suppressSampleBrowserReopenAfterDrop = false;
      _reopenSampleBrowserAfterDrag = false;
      _reopenSampleBrowserExpanded = false;
    });
    _setDawPanelVisible('add_actions', false);
    _setDawPanelVisible('chat_panel', false);
    _setDawPanelVisible('sample_browser', true);
    _chatFocusNode.unfocus();
  }

  Future<void> _closeSampleBrowser() async {
    await _stopSampleAudition();
    if (!mounted) return;
    final preserveWindowState = _usesTabletDesktopDawShell(context);
    setState(() {
      _sampleBrowserVisible = false;
      if (!preserveWindowState) {
        _sampleBrowserExpanded = false;
      }
      _sampleDragActive = false;
      _suppressSampleBrowserReopenAfterDrop = false;
      _reopenSampleBrowserAfterDrag = false;
      _reopenSampleBrowserExpanded = false;
    });
    _setDawPanelVisible('sample_browser', false);
  }

  void _updateSampleBrowserViewState(SampleBrowserPanelViewState state) {
    _sampleBrowserViewState = state;
  }

  void _setSampleDragActive(bool active) {
    if (!mounted) return;
    bool shouldReopenAfterDelay = false;
    bool reopenExpanded = false;
    setState(() {
      _sampleDragActive = active;
      if (active && _sampleBrowserVisible && _sampleBrowserExpanded) {
        _reopenSampleBrowserAfterDrag = true;
        _reopenSampleBrowserExpanded = true;
        _sampleBrowserExpanded = false;
      }
      if (!active &&
          _reopenSampleBrowserAfterDrag &&
          !_suppressSampleBrowserReopenAfterDrop) {
        shouldReopenAfterDelay = true;
        reopenExpanded = _reopenSampleBrowserExpanded;
        _reopenSampleBrowserAfterDrag = false;
        _reopenSampleBrowserExpanded = false;
      } else if (!active && _suppressSampleBrowserReopenAfterDrop) {
        _reopenSampleBrowserAfterDrag = false;
        _reopenSampleBrowserExpanded = false;
      }
    });

    if (!shouldReopenAfterDelay) return;
    Future<void>.delayed(const Duration(milliseconds: 180), () {
      if (!mounted ||
          _sampleDragActive ||
          _sampleBrowserRoots.isEmpty ||
          _suppressSampleBrowserReopenAfterDrop) {
        return;
      }
      setState(() {
        _sampleBrowserVisible = true;
        _sampleBrowserExpanded = reopenExpanded;
      });
      _setDawPanelVisible('sample_browser', true);
    });
  }

  void _cancelSampleBrowserReopenAfterSuccessfulDrop() {
    if (!mounted) return;
    setState(() {
      _suppressSampleBrowserReopenAfterDrop = true;
      _reopenSampleBrowserAfterDrag = false;
      _reopenSampleBrowserExpanded = false;
      _sampleBrowserVisible = false;
      _sampleBrowserExpanded = false;
    });
    _setDawPanelVisible('sample_browser', false);
    Future<void>.delayed(const Duration(milliseconds: 320), () {
      if (!mounted) return;
      setState(() {
        _suppressSampleBrowserReopenAfterDrop = false;
      });
    });
  }

  void _handleSampleDragExitedBrowserPanel() {
    // Keep the drag source mounted until DragTarget accepts or cancels the
    // operation. Removing the sample-browser panel during hover disposes the
    // Draggable and can cancel an otherwise valid timeline drop.
  }

  Future<Duration?> _resolveSampleDuration(String filePath) async {
    if (_sampleDurationCache.containsKey(filePath)) {
      return _sampleDurationCache[filePath];
    }

    final override = widget.sampleDurationOverride;
    if (override != null) {
      final duration = await override(filePath);
      final resolved = duration != null && duration > Duration.zero
          ? duration
          : null;
      _sampleDurationCache[filePath] = resolved;
      return resolved;
    }

    try {
      await _startSecurityScopedAccessForFile(filePath);
      final escaped = filePath.replaceAll('"', r'\"');
      final session = await executeQuietFfprobe(
        '-v error -show_entries format=duration '
        '-of default=noprint_wrappers=1:nokey=1 "$escaped"',
      );
      final rc = await session.getReturnCode();
      if (ReturnCode.isSuccess(rc)) {
        final rawOutput = await session.getOutput();
        final firstLine = (rawOutput ?? '')
            .split('\n')
            .map((s) => s.trim())
            .firstWhere((s) => s.isNotEmpty, orElse: () => '');
        final seconds = double.tryParse(firstLine);
        if (seconds != null && seconds.isFinite && seconds > 0) {
          final duration = Duration(milliseconds: (seconds * 1000).round());
          _sampleDurationCache[filePath] = duration;
          return duration;
        }
      }
    } catch (_) {}

    _sampleDurationCache[filePath] = null;
    return null;
  }

  Future<Duration> _resolveClipSourceDuration({
    required String filePath,
    required int engineClipId,
  }) async {
    final sampled = await _resolveSampleDuration(filePath);
    if (sampled != null && sampled > Duration.zero) {
      return sampled;
    }

    // JUCE getTrackDuration() returns the active clip length, which may already
    // include trim/stretched timeline settings. Use it only as a fallback.
    final rawFallbackSeconds = await _runWithAndroidEngineCriticalSection(
      () => JuceAudioEngine.getTrackDuration(engineClipId),
    );
    final fallbackSeconds =
        (!rawFallbackSeconds.isFinite || rawFallbackSeconds < 0.0)
        ? 0.0
        : rawFallbackSeconds.clamp(0.0, 315360000.0).toDouble();
    return Duration(milliseconds: (fallbackSeconds * 1000).round());
  }

  Future<void> _stopSampleAudition() async {
    _samplePreviewRequestId += 1;
    try {
      await _samplePreviewPlayer.stop();
    } catch (_) {}
    if (!mounted) return;
    if (_auditioningSamplePath != null || _samplePreviewPlaying) {
      setState(() {
        _auditioningSamplePath = null;
        _samplePreviewPlaying = false;
      });
    }
  }

  Future<void> _auditionSampleFile(String filePath) async {
    if (!_isSampleAudioFile(filePath) || !File(filePath).existsSync()) return;
    if (_auditioningSamplePath == filePath && _samplePreviewPlayer.playing) {
      await _stopSampleAudition();
      return;
    }
    final requestId = ++_samplePreviewRequestId;

    if (_isPlaying) {
      await _pausePlayback();
      _stopMeterPolling();
      if (mounted) {
        setState(() {
          _isPlaying = false;
        });
      }
    }

    try {
      if (!mounted) return;
      setState(() {
        _auditioningSamplePath = filePath;
        _samplePreviewPlaying = true;
      });
      if (!await _ensurePlaybackRouteReady(reason: 'samplePreview')) {
        if (mounted) {
          setState(() {
            _auditioningSamplePath = null;
            _samplePreviewPlaying = false;
          });
        }
        return;
      }
      await _startSecurityScopedAccessForFile(filePath);
      await _samplePreviewPlayer.stop();
      await _samplePreviewPlayer.setFilePath(filePath);
      await _samplePreviewPlayer.seek(Duration.zero);
      await _samplePreviewPlayer.play();
    } catch (e) {
      if (!mounted) return;
      if (requestId != _samplePreviewRequestId) return;
      setState(() {
        _auditioningSamplePath = null;
        _samplePreviewPlaying = false;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${L10n.translate(context, 'Failed to preview sample')}: $e',
          ),
        ),
      );
    }
  }

  void _openAddActionsPanel({bool userInitiated = false}) {
    if (!mounted) return;
    setState(() {
      _showAddActionsPanel = true;
      _activeAddActionId = null;
      _chatExpanded = false;
