  TimelineRow _instrumentLaneRowFromSpec(Map<String, dynamic> selected) {
    final defaultSpec = _defaultInstrumentSpec();
    final instrumentId =
        (selected['id'] as String?) ?? (defaultSpec['id'] as String?) ?? '';
    final instrumentName =
        (selected['name'] as String?) ??
        (defaultSpec['name'] as String?) ??
        'Instrument';
    return TimelineRow(
      rowId: -1,
      name: instrumentName,
      iconId: 1,
      kind: TimelineRowKind.instrument,
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      instrumentParams: _instrumentParamsFromSpec(selected),
    );
  }

  Future<void> _addInstrumentClipFromPicker() async {
    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return;
    }
    var selected = await _showInstrumentPickerDialog();
    if (selected == null) return;
    if (_isPitchLabToolSpec(selected)) {
      await _openPitchLabFromCurrentSelection();
      return;
    }
    if (_isSamplerTemplateSpec(selected)) {
      selected = await _pickSamplerInstrumentSpec();
      if (selected == null) return;
    } else if (_isGranularizerTemplateSpec(selected)) {
      selected = await _pickGranularizerInstrumentSpec();
      if (selected == null) return;
    }
    final lane = _instrumentLaneRowFromSpec(selected);
    await _runRowLayoutActionWithUndo(
      description: 'Add instrument lane',
      perform: () => _addInstrumentLaneImpl(lane),
    );
  }

  Future<void> _insertInstrumentLaneFromPicker(
    int row, {
    required bool above,
  }) async {
    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return;
    }
    var selected = await _showInstrumentPickerDialog();
    if (selected == null) return;
    if (_isPitchLabToolSpec(selected)) {
      await _openPitchLabFromCurrentSelection();
      return;
    }
    if (_isSamplerTemplateSpec(selected)) {
      selected = await _pickSamplerInstrumentSpec();
      if (selected == null) return;
    } else if (_isGranularizerTemplateSpec(selected)) {
      selected = await _pickGranularizerInstrumentSpec();
      if (selected == null) return;
    }
    final lane = _instrumentLaneRowFromSpec(selected);
    await _runRowLayoutActionWithUndo(
      description: above
          ? 'Insert instrument lane above'
          : 'Insert instrument lane below',
      perform: () => _insertInstrumentLaneImpl(row, lane, above: above),
    );
  }

  Future<void> _changeInstrumentLaneFromPicker(int row) async {
    if (row < 0 || row >= _rows.length) return;
    if (!_rows[row].isInstrumentLane) return;

    var selected = await _showInstrumentPickerDialog();
    if (selected == null) return;
    if (_isPitchLabToolSpec(selected)) {
      await _openPitchLabFromCurrentSelection();
      return;
    }
    if (_isSamplerTemplateSpec(selected)) {
      selected = await _pickSamplerInstrumentSpec();
      if (selected == null) return;
    } else if (_isGranularizerTemplateSpec(selected)) {
      selected = await _pickGranularizerInstrumentSpec();
      if (selected == null) return;
    }
    await _changeInstrumentLaneToSpec(
      row,
      selected,
      preserveRowName: false,
      recordManualEdit: true,
    );
  }

  Future<void> _changeInstrumentLaneToSpec(
    int row,
    Map<String, dynamic> selected, {
    required bool preserveRowName,
    required bool recordManualEdit,
  }) async {
    if (row < 0 || row >= _rows.length) {
      throw StateError('instrument_lane_target_missing');
    }
    final currentLane = _rows[row];
    if (!currentLane.isInstrumentLane) {
      throw StateError('instrument_lane_target_invalid');
    }
    final nextLane = _instrumentLaneRowFromSpec(
      selected,
    ).copyWith(rowId: currentLane.rowId);
    final nextInstrumentName = nextLane.instrumentName.trim().isEmpty
        ? _instrumentNameFromId(nextLane.instrumentId)
        : nextLane.instrumentName.trim();
    final nextInstrumentParams = Map<String, double>.from(
      nextLane.instrumentParams,
    );
    final nextRowName = preserveRowName
        ? currentLane.name
        : (nextInstrumentName.isEmpty ? nextLane.name : nextInstrumentName);
    final preserveLaneHostedState =
        _instrumentIdUsesExternalPlugin(currentLane.instrumentId) &&
        _instrumentIdUsesExternalPlugin(nextLane.instrumentId) &&
        _liveMidiEngineInstrumentId(currentLane.instrumentId) ==
            _liveMidiEngineInstrumentId(nextLane.instrumentId);
    final nextLaneHostedState = preserveLaneHostedState
        ? currentLane.hostedInstrumentStateBase64
        : '';

    final laneChanged =
        currentLane.instrumentId != nextLane.instrumentId ||
        currentLane.instrumentName != nextInstrumentName ||
        currentLane.name != nextRowName ||
        !_doubleMapsEqual(currentLane.instrumentParams, nextInstrumentParams) ||
        currentLane.hostedInstrumentStateBase64 != nextLaneHostedState;

    final beforeLayout = await _captureRowLayoutSnapshot();
    final afterRows = beforeLayout.rows.map(_cloneTimelineRow).toList();
    if (row >= afterRows.length) return;
    afterRows[row] = afterRows[row].copyWith(
      name: nextRowName,
      iconId: 1,
      kind: TimelineRowKind.instrument,
      instrumentId: nextLane.instrumentId,
      instrumentName: nextInstrumentName,
      instrumentParams: nextInstrumentParams,
      hostedInstrumentStateBase64: nextLaneHostedState,
    );

    final actions = <EditorUndoAction>[
      if (laneChanged)
        _RowLayoutSnapshotAction(
          descriptionText: 'Change instrument lane',
          before: beforeLayout,
          after: _RowLayoutSnapshot(
            rows: afterRows,
            trackGroups: beforeLayout.trackGroups,
          ),
          applySnapshot: _applyRowLayoutSnapshot,
        ),
    ];

    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      if (!clip.isMidi || clip.rowIndex != row) continue;
      final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
      final oldParams = Map<String, double>.from(clip.instrumentParams);
      final oldInstrumentId = clip.instrumentId;
      final oldInstrumentName = clip.instrumentName;
      final oldLabel = clip.label;
      final shouldRenameLabel = shouldMidiClipLabelFollowInstrument(
        label: oldLabel,
        instrumentName: oldInstrumentName,
      );
      final oldHostedInstrumentStateBase64 =
          await _captureHostedInstrumentStateForClip(clip);
      final newHostedInstrumentStateBase64 = _nextHostedInstrumentStateForEdit(
        clip,
        instrumentId: nextLane.instrumentId,
        currentStateBase64: oldHostedInstrumentStateBase64,
      );
      final clipChanged =
          oldInstrumentId != nextLane.instrumentId ||
          oldInstrumentName != nextInstrumentName ||
          !_doubleMapsEqual(oldParams, nextInstrumentParams) ||
          oldHostedInstrumentStateBase64 != newHostedInstrumentStateBase64;
      if (!clipChanged) continue;

      actions.add(
        EditMidiClipAction(
          tracks: _audioTracks,
          originalIndex: i,
          oldNotes: oldNotes,
          newNotes: oldNotes.map((n) => n.copy()).toList(),
          oldInstrumentId: oldInstrumentId,
          oldInstrumentName: oldInstrumentName,
          oldInstrumentParams: oldParams,
          oldHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          newInstrumentId: nextLane.instrumentId,
          newInstrumentName: nextInstrumentName,
          newInstrumentParams: nextInstrumentParams,
          newHostedInstrumentStateBase64: newHostedInstrumentStateBase64,
          applyToClip:
              (
                target,
                notesToApply,
                nextInstrumentId,
                nextInstrumentName,
                nextParams,
                hostedInstrumentStateBase64,
              ) async {
                target.midiNotes = notesToApply
                    .map((note) => note.copy())
                    .toList(growable: false);
                _assignMidiClipInstrument(
                  target,
                  instrumentId: nextInstrumentId,
                  instrumentName: nextInstrumentName,
                  instrumentParams: nextParams,
                  syncLaneMetadata: false,
                );
                target.hostedInstrumentStateBase64 = hostedInstrumentStateBase64
                    .trim();
                final refreshed = await _refreshMidiClipEngineNow(
                  target,
                  failureNotice:
                      'Could not switch instrument for this MIDI clip.',
                );
                if (!refreshed) {
                  throw StateError('instrument_lane_engine_refresh_failed');
                }
                if (mounted) setState(() {});
              },
        ),
      );
      if (shouldRenameLabel && oldLabel != nextInstrumentName) {
        actions.add(
          SetClipLabelAction(
            tracks: _audioTracks,
            originalIndex: i,
            oldLabel: oldLabel,
            newLabel: nextInstrumentName,
            applyToState: (target, label) {
              target.label = label;
              if (mounted) setState(() {});
            },
          ),
        );
      }
    }

    if (actions.isEmpty) return;
    await _executeInstrumentLaneChangeActions(actions);
    if (recordManualEdit) {
      _recordProducerManualEdit('change_instrument_lane', {
        'row': row,
        'instrument_id': nextLane.instrumentId,
        'instrument_name': nextInstrumentName,
        'clip_count': actions.whereType<EditMidiClipAction>().length,
      });
    }
    _scheduleProjectAutosave();
  }

  Future<void> _executeInstrumentLaneChangeActions(
    List<EditorUndoAction> actions,
  ) async {
    final completed = <EditorUndoAction>[];
    try {
      for (final action in actions) {
        await action.redo();
        completed.add(action);
      }
      await _undoManager.addWithoutExecute(
        actions.length == 1
            ? actions.single
            : CompoundUndoAction('Change instrument lane', actions),
      );
    } catch (error, stackTrace) {
      var rollbackIncomplete = false;
      for (final action in completed.reversed) {
        try {
          await action.undo();
        } catch (_) {
          rollbackIncomplete = true;
        }
      }
      if (rollbackIncomplete) {
        Error.throwWithStackTrace(
          _EditorUndoCaptureRollbackException(error),
          stackTrace,
        );
      }
      Error.throwWithStackTrace(error, stackTrace);
    }
  }

  Future<void> _createMidiClipInInstrumentLane(int row, double timeMs) async {
    if (row < 0 || row >= _rows.length) return;
    final lane = _rows[row];
    if (!lane.isInstrumentLane) return;
    if (lane.instrumentId.trim().isEmpty) {
      _showSmallNotice('This instrument lane is missing its instrument.');
      return;
    }
    final beforeCount = _audioTracks.length;
    await _undoManager.execute(
      AddMidiClipAction(
        addMidiClip:
            ({
              required String instrumentId,
              required String instrumentName,
              required Map<String, double> instrumentParams,
              required List<MidiNote> midiNotes,
              required int row,
              required double timeMs,
              Duration? trimEndRequested,
            }) => _addMidiTrack(
              instrumentId: instrumentId,
              instrumentName: instrumentName,
              instrumentParams: instrumentParams,
              midiNotes: midiNotes,
              row: row,
              timeMs: timeMs,
              trimEndRequested: trimEndRequested,
            ),
        tracks: _audioTracks,
        restoreTrack: _addClipFromUndoPayload,
        instrumentId: lane.instrumentId,
        instrumentName: lane.instrumentName.isEmpty
            ? _instrumentNameFromId(lane.instrumentId)
            : lane.instrumentName,
        instrumentParams: Map<String, double>.from(lane.instrumentParams),
        midiNotes: const <MidiNote>[],
        row: row,
        timeMs: timeMs,
        onRemove: _syncRemovedClipFadesAfterUndo,
      ),
    );
    if (_audioTracks.length > beforeCount) {
      _openMidiClipEditor(_audioTracks.length - 1);
    }
  }

  Future<void> _handleAddActionSelection(String action) async {
    final groupingRows = action == 'group_rows'
        ? _rowsForActiveGroupingAction()
        : const <int>[];
    if (action == 'group_rows') {
      if (groupingRows.length < 2) {
        _enterRowGroupingSelectionMode();
        return;
      }
    }
    _trackUiClick(
      controlId: action,
      surface: 'add_actions',
      extra: <String, Object?>{'action_id': action},
    );
    if (mounted) {
      setState(() {
        _activeAddActionId = action;
      });
    }
    await Future<void>.delayed(const Duration(milliseconds: 65));
    _closeAddActionsPanel();
    if (action == 'audio_row') {
      await _addRow();
      return;
    }
    if (action == 'audio') {
      await _pickAndInsertAudioTrack();
      return;
    }
    if (action == 'capture_deck') {
      _openCaptureDeck();
      return;
    }
    if (action == 'sample_browser') {
      await _openSampleBrowser(
        promptFolderIfEmpty: _sampleBrowserRoots.isEmpty,
      );
      return;
    }
    if (action == 'instrument') {
      await _addInstrumentClipFromPicker();
      return;
    }
    if (action == 'group_rows') {
      await _createRowGroup(groupingRows);
      _exitRowGroupingSelectionMode();
      return;
    }
  }

  List<int> _rowsForActiveGroupingAction() {
    if (_rowGroupingSelectionMode) {
      return _validRowGroupingSelection();
    }
    if (_rowGroupingSelection.length >= 2) {
      return _validRowGroupingSelection();
    }
    return _rowsForSelectedClipGrouping();
  }

  List<int> _validRowGroupingSelection() {
    final selected =
        _rowGroupingSelection
            .where((row) => row >= 0 && row < _rowCount)
            .toSet()
            .toList()
          ..sort();
    return selected;
  }

  List<int> _rowsForSelectedClipGrouping() {
    final rows = <int>{};
    for (final index in _timelineSelectedClipIndices) {
      if (index < 0 || index >= _audioTracks.length) continue;
      final row = _audioTracks[index].rowIndex;
      if (row >= 0 && row < _rowCount) rows.add(row);
    }
    final ordered = rows.toList()..sort();
    return ordered;
  }

  void _enterRowGroupingSelectionMode() {
    if (!mounted) return;
    final seedRows = _rowsForSelectedClipGrouping();
    setState(() {
      _rowGroupingSelectionMode = true;
      _showAddActionsPanel = false;
      _rowGroupingSelection
        ..clear()
        ..addAll(seedRows);
      _activeAddActionId = null;
    });
    _setDawPanelVisible('add_actions', false);
  }

  void _exitRowGroupingSelectionMode() {
    if (!mounted) return;
    setState(() {
      _rowGroupingSelectionMode = false;
      _rowGroupingSelection.clear();
      if (_activeAddActionId == 'group_rows') {
        _activeAddActionId = null;
      }
    });
  }

  void _toggleRowGroupingSelection(int row) {
    if (row < 0 || row >= _rowCount) return;
    setState(() {
      if (_rowGroupingSelection.contains(row)) {
        _rowGroupingSelection.remove(row);
      } else {
        _rowGroupingSelection.add(row);
      }
    });
  }

