    Widget selectedAudioClipOptions() {
      final clipIndex = _tabletAudioClipOptionsIndex;
      if (!_isValidAudioClipOptionsIndex(clipIndex)) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted && _tabletAudioClipOptionsIndex != null) {
            _closeTabletAudioClipOptions();
          }
        });
        return const SizedBox.shrink();
      }
      final index = clipIndex!;
      final clip = _audioTracks[index];
      final accent = const Color(0xFF8A919D);
      final pitch = clip.pitchSemitones
          .clamp(_kClipPitchMinSemitones, _kClipPitchMaxSemitones)
          .toDouble();
      final gain = clip.gain.clamp(0.0, 3.0).toDouble();
      final pitchLabel =
          '${pitch >= 0 ? '+' : ''}${pitch.toStringAsFixed(1)}st';

      Future<void> applyPitch(double next) async {
        await _setClipPitchLive(
          index,
          next
              .clamp(_kClipPitchMinSemitones, _kClipPitchMaxSemitones)
              .toDouble(),
        );
      }

      Widget section({
        required String title,
        required Widget child,
        Widget? trailing,
      }) {
        return Container(
          width: double.infinity,
          padding: const EdgeInsets.fromLTRB(12, 11, 12, 12),
          decoration: panelCardDecoration(accent: accent),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Expanded(child: panelSectionTitle(title)),
                  if (trailing != null) trailing,
                ],
              ),
              child,
            ],
          ),
        );
      }

      return ListView(
        physics: const ClampingScrollPhysics(),
        padding: const EdgeInsets.fromLTRB(10, 0, 10, 12),
        children: [
          Container(
            padding: const EdgeInsets.fromLTRB(14, 13, 14, 14),
            decoration: panelCardDecoration(accent: accent),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Container(
                      width: 34,
                      height: 34,
                      decoration: BoxDecoration(
                        color: Colors.white.withValues(alpha: 0.10),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color: Colors.white.withValues(alpha: 0.10),
                        ),
                      ),
                      child: const Icon(
                        Icons.audio_file_rounded,
                        color: Color(0xFFF4F4F4),
                        size: 18,
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        L10n.translate(context, 'Audio Clip Options'),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          fontFamily: 'Pretendard',
                          color: Color(0xFFF4F4F4),
                          fontSize: 15,
                          fontWeight: FontWeight.w800,
                          height: 1.0,
                        ),
                      ),
                    ),
                    Material(
                      color: Colors.transparent,
                      child: InkWell(
                        borderRadius: BorderRadius.circular(12),
                        onTap: _closeTabletAudioClipOptions,
                        child: Ink(
                          width: 32,
                          height: 32,
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.08),
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(
                              color: Colors.white.withValues(alpha: 0.10),
                            ),
                          ),
                          child: const Icon(
                            Icons.close_rounded,
                            color: Color(0xFFF4F4F4),
                            size: 17,
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 12),
                TextFormField(
                  key: ValueKey(
                    'tablet_audio_clip_name_${clip.engineClipId}_${clip.label}',
                  ),
                  focusNode: _tabletAudioClipNameFocusNode,
                  initialValue: _audioClipDisplayName(clip),
                  readOnly: !_tabletAudioClipOptionsRenaming,
                  maxLength: 48,
                  onTap: () {
                    if (!_tabletAudioClipOptionsRenaming) {
                      _beginTabletAudioClipRename();
                    }
                  },
                  onChanged: (value) {
                    _tabletAudioClipOptionsNameDraft = value;
                  },
                  onFieldSubmitted: (value) {
                    unawaited(_finishTabletAudioClipRename(index, value));
                  },
                  style: const TextStyle(
                    fontFamily: 'Pretendard',
                    color: Color(0xFFF4F4F4),
                    fontSize: 13,
                    fontWeight: FontWeight.w700,
                  ),
                  decoration: InputDecoration(
                    counterText: '',
                    isDense: true,
                    labelText: L10n.translate(context, 'Clip name'),
                    labelStyle: TextStyle(
                      color: Colors.white.withValues(alpha: 0.58),
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                    ),
                    filled: true,
                    fillColor: Colors.black.withValues(alpha: 0.16),
                    contentPadding: const EdgeInsets.fromLTRB(12, 10, 8, 10),
                    suffixIcon: IconButton(
                      tooltip: L10n.translate(
                        context,
                        _tabletAudioClipOptionsRenaming
                            ? 'Finish rename'
                            : 'Rename clip',
                      ),
                      icon: Icon(
                        _tabletAudioClipOptionsRenaming
                            ? Icons.check_rounded
                            : Icons.edit_rounded,
                        size: 17,
                      ),
                      color: const Color(0xFFF4F4F4),
                      onPressed: _tabletAudioClipOptionsRenaming
                          ? () => unawaited(
                              _finishTabletAudioClipRename(
                                index,
                                _tabletAudioClipOptionsNameDraft,
                              ),
                            )
                          : _beginTabletAudioClipRename,
                    ),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(13),
                      borderSide: BorderSide(
                        color: Colors.white.withValues(alpha: 0.10),
                      ),
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(13),
                      borderSide: BorderSide(
                        color: Colors.white.withValues(alpha: 0.10),
                      ),
                    ),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(13),
                      borderSide: BorderSide(
                        color: Colors.white.withValues(alpha: 0.34),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 10),
          section(
            title: 'Tone',
            trailing: Material(
              color: Colors.transparent,
              child: InkWell(
                borderRadius: BorderRadius.circular(999),
                onTap: () => unawaited(
                  _handleToggleClipNormalize(index, !clip.normalizeVolume),
                ),
                child: Ink(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color:
                        (clip.normalizeVolume
                                ? const Color(0xFFD7DBE2)
                                : Colors.white)
                            .withValues(
                              alpha: clip.normalizeVolume ? 0.34 : 0.08,
                            ),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(
                      color: Colors.white.withValues(
                        alpha: clip.normalizeVolume ? 0.42 : 0.13,
                      ),
                    ),
                  ),
                  child: Semantics(
                    button: true,
                    toggled: clip.normalizeVolume,
                    label: L10n.translate(context, 'Normalize'),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Icon(
                          clip.normalizeVolume
                              ? Icons.toggle_on_rounded
                              : Icons.toggle_off_rounded,
                          size: 19,
                          color: const Color(0xFFF4F4F4),
                        ),
                        const SizedBox(width: 5),
                        Text(
                          L10n.translate(context, 'Normalize'),
                          style: const TextStyle(
                            fontFamily: 'Pretendard',
                            color: Color(0xFFF4F4F4),
                            fontSize: 10.5,
                            fontWeight: FontWeight.w800,
                            height: 1.0,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                PrettyGainSlider(
                  value: gain,
                  trackColor: accent,
                  inactiveTrackColor: Colors.white.withValues(alpha: 0.16),
                  thumbColor: const Color(0xFFF4F4F4),
                  onChangeStart: (_) {
                    _tabletAudioClipOptionsGainStart = gain;
                  },
                  onChanged: (value) {
                    unawaited(_setClipGainLive(index, value));
                  },
                  onChangeEnd: (_) {
                    unawaited(_commitTabletAudioClipGain(index));
                  },
                ),
                const SizedBox(height: 10),
                Row(
                  children: [
                    Text(
                      L10n.translate(context, 'Pitch'),
                      style: const TextStyle(
                        fontFamily: 'Pretendard',
                        color: Color(0xFFF4F4F4),
                        fontSize: 12,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const Spacer(),
                    Text(
                      pitchLabel,
                      style: TextStyle(
                        fontFamily: 'Pretendard',
                        color: Colors.white.withValues(alpha: 0.82),
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 4),
                Row(
                  children: [
                    clipStepButton(
                      icon: Icons.remove_rounded,
                      onTap: () {
                        _tabletAudioClipOptionsPitchStart ??= pitch;
                        unawaited(
                          applyPitch(
                            pitch - 0.5,
                          ).then((_) => _commitTabletAudioClipPitch(index)),
                        );
                      },
                    ),
                    const SizedBox(width: 7),
                    Expanded(
                      child: SliderTheme(
                        data: SliderTheme.of(context).copyWith(
                          trackHeight: 5,
                          activeTrackColor: accent,
                          inactiveTrackColor: Colors.white.withValues(
                            alpha: 0.16,
                          ),
                          thumbColor: const Color(0xFFF4F4F4),
                          overlayShape: SliderComponentShape.noOverlay,
                        ),
                        child: DesktopScrollableSlider(
                          value: pitch,
                          min: _kClipPitchMinSemitones,
                          max: _kClipPitchMaxSemitones,
                          divisions: 48,
                          onChangeStart: (_) {
                            _tabletAudioClipOptionsPitchStart = pitch;
                          },
                          onChanged: (value) {
                            unawaited(applyPitch(value));
                          },
                          onChangeEnd: (_) {
                            unawaited(_commitTabletAudioClipPitch(index));
                          },
                        ),
                      ),
                    ),
                    const SizedBox(width: 7),
                    clipStepButton(
                      icon: Icons.add_rounded,
                      onTap: () {
                        _tabletAudioClipOptionsPitchStart ??= pitch;
                        unawaited(
                          applyPitch(
                            pitch + 0.5,
                          ).then((_) => _commitTabletAudioClipPitch(index)),
                        );
                      },
                    ),
                  ],
                ),
              ],
            ),
          ),
          const SizedBox(height: 10),
          section(
            title: 'Tempo',
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  height: 40,
                  decoration: BoxDecoration(
                    color: Colors.black.withValues(alpha: 0.16),
                    borderRadius: BorderRadius.circular(13),
                    border: Border.all(
                      color: Colors.white.withValues(alpha: 0.08),
                    ),
                  ),
                  child: Row(
                    children: [
                      clipTempoModeButton(
                        label: 'Off',
                        selected: !clip.stretchToProjectTempo,
                        onTap: () =>
                            unawaited(_handleDisableClipTempoFollow(index)),
                      ),
                      clipTempoModeButton(
                        label: 'Resample',
                        selected:
                            clip.stretchToProjectTempo &&
                            !clip.tempoStretchPreservePitch,
                        onTap: () => unawaited(_handleAdjustClipToTempo(index)),
                      ),
                      clipTempoModeButton(
                        label: 'Stretch',
                        selected:
                            clip.stretchToProjectTempo &&
                            clip.tempoStretchPreservePitch,
                        onTap: () => unawaited(
                          _handleStretchClipToTempoPreservePitch(index),
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 10),
                Wrap(
                  spacing: 7,
                  runSpacing: 7,
                  children: [
                    clipPanelActionPill(
                      icon: Icons.swap_horiz_rounded,
                      label: clip.isReversed ? 'Reversed' : 'Reverse',
                      color: clip.isReversed
                          ? const Color(0xFFD7DBE2)
                          : const Color(0xFFF4F4F4),
                      onTap: () => unawaited(
                        _setAudioClipReversedFromPanel(index, !clip.isReversed),
                      ),
                    ),
                    clipPanelActionPill(
                      icon: Icons.auto_fix_high_rounded,
                      label: 'Set BPM',
                      onTap: () => unawaited(
                        _handleDetectClipTempoAndSetProjectTempo(index),
                      ),
                    ),
                    clipPanelActionPill(
                      icon: Icons.blur_linear_rounded,
                      label: 'Warp Pro',
                      color: const Color(0xFF78D9FF),
                      onTap: PlatformCapabilities.current.isDesktop
                          ? () => unawaited(_openClipWarpEditor(index))
                          : null,
                    ),
                    clipPanelActionPill(
                      icon: Icons.graphic_eq_rounded,
                      label: 'Pitch Lab',
                      color: const Color(0xFF8BE7C8),
                      onTap: () => unawaited(_openAudioPitchLabForClip(index)),
                    ),
                    clipPanelActionPill(
                      icon: Icons.library_music_outlined,
                      label: 'Split vocals',
                      onTap: () =>
                          unawaited(_handleStemSeparationForClip(index)),
                    ),
                    clipPanelActionPill(
                      icon: Icons.keyboard_alt_outlined,
                      label: 'Sampler',
                      color: const Color(0xFFD7DBE2),
                      onTap: () =>
                          unawaited(_createSamplerFromAudioClip(index)),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ],
      );
    }

    Widget selectedRowInspector() {
      if (_rowCount == 0) return const SizedBox.shrink();
      if (_tabletAudioClipOptionsIndex != null) {
        final clipOptions = selectedAudioClipOptions();
        if (clipOptions is! SizedBox) return clipOptions;
      }
      final row = _selectedRow.clamp(0, _rowCount - 1).toInt();
      final rowInfo = _rows[row];
      final group = rowInfo.groupId.trim().isEmpty
          ? null
          : _trackGroups
                .where((item) => item.id == rowInfo.groupId.trim())
                .cast<TrackGroup?>()
                .firstOrNull;
      final color = rowInfo.color == 0
          ? const Color(0xFF1194FF)
          : Color(rowInfo.color).withValues(alpha: 1.0);

      Widget rowActionsCard() {
        return Container(
          padding: const EdgeInsets.fromLTRB(14, 13, 14, 14),
          decoration: panelCardDecoration(accent: color),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              panelSectionTitle('ROW ACTIONS'),
              const SizedBox(height: 10),
              Row(
                children: [
                  Expanded(
                    child: compactPillButton(
                      label: 'Show Row',
                      icon: Icons.open_in_full_rounded,
                      onTap: () => _timelineController.ensureRowExpanded(
                        row,
                        tab: _tabletRowDetailTab,
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: compactPillButton(
                      label: 'Collapse',
                      icon: Icons.unfold_less_rounded,
                      onTap: _timelineController.collapseExpandedRows,
                    ),
                  ),
                ],
              ),
            ],
          ),
        );
      }

      return AnimatedBuilder(
        animation: _meters,
        builder: (context, _) {
          final frame = row < _meters.rows.length
              ? _meters.rows[row]
              : MeterFrame.zero;
          final peakDb = _heldPeakDbForRow(row, frame);
          return ListView(
            physics: const ClampingScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(10, 0, 10, 12),
            children: [
              Container(
                padding: const EdgeInsets.fromLTRB(14, 13, 14, 14),
                decoration: panelCardDecoration(accent: color),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Container(
                          width: 14,
                          height: 14,
                          decoration: BoxDecoration(
                            color: color,
                            shape: BoxShape.circle,
                            border: Border.all(
                              color: Colors.white.withValues(alpha: 0.40),
                            ),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            _mixerDisplayNameForRow(row),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              fontFamily: 'Pretendard',
                              color: Color(0xFFF4F4F4),
                              fontSize: 14,
                              fontWeight: FontWeight.w800,
