    Widget masterRackMeterSurface({
      required double peakDb,
      required bool expanded,
      required VoidCallback onToggle,
      bool compact = false,
    }) {
      final levelLabel = _technicalLevelLabel(peakDb);
      final levelColor = _technicalLevelColor(peakDb);
      return LayoutBuilder(
        builder: (context, constraints) {
          final narrow =
              constraints.maxWidth.isFinite && constraints.maxWidth < 250.0;
          final tight =
              constraints.maxWidth.isFinite && constraints.maxWidth < 190.0;
          final horizontalPad = narrow ? 8.0 : 12.0;
          final iconSize = tight ? 24.0 : (compact ? 26.0 : 30.0);
          final gap = narrow ? 6.0 : 8.0;
          final toggleLabel = L10n.translate(
            context,
            expanded ? 'Collapse Master Rack' : 'Expand Master Rack',
          );
          var hovered = false;
          var pressed = false;

          return StatefulBuilder(
            builder: (context, setFooterState) {
              void setHovered(bool value) {
                if (hovered == value) return;
                setFooterState(() {
                  hovered = value;
                });
              }

              void setPressed(bool value) {
                if (pressed == value) return;
                setFooterState(() {
                  pressed = value;
                });
              }

              final hoveredOrPressed = hovered || pressed;
              final surfaceAlpha = expanded
                  ? (hoveredOrPressed ? 0.32 : 0.28)
                  : (hoveredOrPressed ? 0.31 : 0.24);
              final borderColor = expanded
                  ? const Color(
                      0xFF1194FF,
                    ).withValues(alpha: hoveredOrPressed ? 0.44 : 0.34)
                  : Colors.white.withValues(
                      alpha: hoveredOrPressed ? 0.18 : 0.10,
                    );

              return Semantics(
                button: true,
                toggled: expanded,
                label: toggleLabel,
                child: MouseRegion(
                  cursor: SystemMouseCursors.click,
                  onEnter: (_) => setHovered(true),
                  onExit: (_) {
                    setHovered(false);
                    setPressed(false);
                  },
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTapDown: (_) => setPressed(true),
                    onTapUp: (_) => setPressed(false),
                    onTapCancel: () => setPressed(false),
                    onTap: onToggle,
                    onVerticalDragEnd: (_) => setPressed(false),
                    onVerticalDragCancel: () => setPressed(false),
                    onVerticalDragUpdate: (details) {
                      if (details.delta.dy < -2.0 && !expanded) {
                        onToggle();
                      } else if (details.delta.dy > 3.0 && expanded) {
                        onToggle();
                      }
                    },
                    child: AnimatedScale(
                      duration: const Duration(milliseconds: 100),
                      curve: Curves.easeOutCubic,
                      scale: pressed ? 0.992 : 1.0,
                      child: Stack(
                        clipBehavior: Clip.none,
                        children: [
                          AnimatedContainer(
                            duration: const Duration(milliseconds: 180),
                            curve: Curves.easeOutCubic,
                            padding: EdgeInsets.fromLTRB(
                              horizontalPad,
                              compact ? 18 : 20,
                              horizontalPad,
                              11,
                            ),
                            decoration: BoxDecoration(
                              color: Color.fromRGBO(95, 108, 126, surfaceAlpha),
                              borderRadius: BorderRadius.circular(16),
                              border: Border.all(color: borderColor),
                              boxShadow: <BoxShadow>[
                                BoxShadow(
                                  color: Colors.black.withValues(
                                    alpha: expanded
                                        ? 0.28
                                        : hoveredOrPressed
                                        ? 0.22
                                        : 0.18,
                                  ),
                                  blurRadius: expanded
                                      ? 18
                                      : hoveredOrPressed
                                      ? 15
                                      : 12,
                                  offset: Offset(0, hoveredOrPressed ? 7 : 6),
                                ),
                              ],
                            ),
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Row(
                                  children: [
                                    if (!tight) ...[
                                      Container(
                                        width: iconSize,
                                        height: iconSize,
                                        decoration: BoxDecoration(
                                          color: Colors.white.withValues(
                                            alpha: hoveredOrPressed
                                                ? 0.14
                                                : 0.10,
                                          ),
                                          borderRadius: BorderRadius.circular(
                                            10,
                                          ),
                                        ),
                                        child: Icon(
                                          Icons.surround_sound_outlined,
                                          size: compact ? 16 : 18,
                                          color: Colors.white.withValues(
                                            alpha: 0.90,
                                          ),
                                        ),
                                      ),
                                      SizedBox(width: gap),
                                    ],
                                    Expanded(
                                      child: Text(
                                        L10n.translate(context, 'Master'),
                                        maxLines: 1,
                                        overflow: TextOverflow.ellipsis,
                                        style: TextStyle(
                                          fontFamily: 'Pretendard',
                                          color: Colors.white.withValues(
                                            alpha: 0.92,
                                          ),
                                          fontSize: compact ? 12 : 13,
                                          fontWeight: FontWeight.w800,
                                          height: 1.0,
                                        ),
                                      ),
                                    ),
                                    SizedBox(width: gap),
                                    Container(
                                      padding: EdgeInsets.symmetric(
                                        horizontal: narrow ? 7 : 9,
                                        vertical: 3.5,
                                      ),
                                      decoration: BoxDecoration(
                                        color: levelColor.withValues(
                                          alpha: 0.17,
                                        ),
                                        borderRadius: BorderRadius.circular(
                                          999,
                                        ),
                                        border: Border.all(
                                          color: levelColor.withValues(
                                            alpha: 0.48,
                                          ),
                                        ),
                                      ),
                                      child: Text(
                                        levelLabel,
                                        maxLines: 1,
                                        overflow: TextOverflow.fade,
                                        softWrap: false,
                                        style: TextStyle(
                                          fontFamily: 'Pretendard',
                                          color: levelColor,
                                          fontSize: compact ? 10.5 : 11,
                                          fontWeight: FontWeight.w800,
                                          height: 1.0,
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 8),
                                SizedBox(
                                  width: double.infinity,
                                  height: compact ? 26 : 30,
                                  child: TrackGainStagingDbMeter(
                                    frame: _meters.master,
                                    showClipIndicator: false,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          Positioned(
                            top: -12,
                            left: 0,
                            right: 0,
                            child: Center(
                              child: Tooltip(
                                message: toggleLabel,
                                waitDuration: const Duration(milliseconds: 450),
                                child: Container(
                                  width: 36,
                                  height: 28,
                                  alignment: Alignment.center,
                                  decoration: BoxDecoration(
                                    color: expanded
                                        ? const Color(
                                            0xFFF4F4F4,
                                          ).withValues(alpha: 0.90)
                                        : const Color.fromRGBO(
                                            63,
                                            84,
                                            104,
                                            0.96,
                                          ),
                                    borderRadius: BorderRadius.circular(999),
                                    border: Border.all(
                                      color: expanded
                                          ? const Color(
                                              0xFF1194FF,
                                            ).withValues(alpha: 0.30)
                                          : Colors.white.withValues(
                                              alpha: 0.16,
                                            ),
                                    ),
                                    boxShadow: <BoxShadow>[
                                      BoxShadow(
                                        color: Colors.black.withValues(
                                          alpha: 0.24,
                                        ),
                                        blurRadius: 10,
                                        offset: const Offset(0, 4),
                                      ),
                                    ],
                                  ),
                                  child: Icon(
                                    expanded
                                        ? Icons.keyboard_arrow_down_rounded
                                        : Icons.keyboard_arrow_up_rounded,
                                    color: expanded
                                        ? const Color(0xFF15436C)
                                        : Colors.white.withValues(alpha: 0.88),
                                    size: 23,
                                  ),
                                ),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            },
          );
        },
      );
    }

    Widget masterRackControlsCard() {
      return Padding(
        padding: const EdgeInsets.fromLTRB(10, 0, 10, 10),
        child: Container(
          padding: const EdgeInsets.fromLTRB(12, 12, 12, 13),
          decoration: panelCardDecoration(
            accent: const Color(0xFF62D8FF),
            alpha: 0.70,
          ),
          child: LayoutBuilder(
            builder: (context, constraints) {
              final showStepButtons = constraints.maxWidth >= 252.0;
              return Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Builder(
                    builder: (context) {
                      Widget child = PrettyGainSlider(
                        value: _masterGain,
                        showStepButtons: showStepButtons,
                        stackedLayout: true,
                        label: L10n.translate(context, 'Master Gain'),
                        onLongPress: () => _showMasterMixAutomationSheet(
                          paramId: 'gain',
                          label: 'Master Gain',
                          haloKeys: <String>[
                            'master:gain',
                            'master:param:gain',
                          ],
                        ),
                        onChangeStart: (v) {
                          _masterGainDragStart = v;
                        },
                        onChanged: (v) {
                          setState(() => _masterGain = v);
                          JuceAudioEngine.setMasterGain(v);
                        },
                        onChangeEnd: (v) {
                          final oldGain = _masterGainDragStart ?? v;
                          final newGain = _masterGain;
                          if ((newGain - oldGain).abs() < 0.00001) {
                            _masterGainDragStart = null;
                            return;
                          }
                          _undoManager.execute(
                            SetMasterGainAction(
                              oldGain: oldGain,
                              newGain: newGain,
                              applyToState: (g) {
                                setState(() {
                                  _masterGain = g;
                                });
                              },
                            ),
                          );
                          _recordProducerManualEdit('master_gain', {
                            'old_gain': oldGain,
                            'new_gain': newGain,
                          });
                          _masterGainDragStart = null;
                        },
                      );
                      child = MultiHalo(
                        highlighter: _mixHighlighter,
                        haloKeys: const <HaloKey>[
                          HaloKey('master:gain'),
                          HaloKey('master:param:gain'),
                        ],
                        borderRadius: BorderRadius.circular(10),
                        child: child,
                      );
                      return child;
                    },
                  ),
                  const SizedBox(height: 10),
                  Builder(
                    builder: (context) {
                      Widget child = PrettyStereoSlider(
                        value: _masterPan,
                        showStepButtons: showStepButtons,
                        stackedLayout: true,
                        label: L10n.translate(context, 'Master Pan'),
                        onLongPress: () => _showMasterMixAutomationSheet(
                          paramId: 'pan',
                          label: 'Master Pan',
                          haloKeys: <String>['master:pan', 'master:param:pan'],
                        ),
                        onChangeStart: (v) {
                          _masterPanDragStart = v;
                        },
                        onChanged: (v) {
                          setState(() => _masterPan = v);
                          JuceAudioEngine.setMasterPan(v);
                        },
                        onChangeEnd: (v) {
                          final oldPan = _masterPanDragStart ?? v;
                          final newPan = _masterPan;
                          if ((newPan - oldPan).abs() < 0.00001) {
                            _masterPanDragStart = null;
                            return;
                          }
                          _undoManager.execute(
                            SetMasterPanAction(
                              oldPan: oldPan,
                              newPan: newPan,
                              applyToState: (p) {
                                setState(() {
                                  _masterPan = p;
                                });
                              },
                            ),
                          );
                          _recordProducerManualEdit('master_pan', {
                            'old_pan': oldPan,
                            'new_pan': newPan,
                          });
                          _masterPanDragStart = null;
                        },
                      );
                      child = MultiHalo(
                        highlighter: _mixHighlighter,
                        haloKeys: const <HaloKey>[
                          HaloKey('master:pan'),
                          HaloKey('master:param:pan'),
                        ],
                        borderRadius: BorderRadius.circular(10),
                        child: child,
                      );
                      return child;
                    },
                  ),
                ],
              );
            },
          ),
        ),
      );
    }

