  String _technicalLevelLabel(double peakDb) {
    if (peakDb >= -0.1) return "0.0 dBFS";
    if (!peakDb.isFinite || peakDb <= -120.0) return "-∞ dBFS";
    return "${peakDb.toStringAsFixed(1)} dBFS";
  }

  Color _technicalLevelColor(double peakDb) {
    if (!peakDb.isFinite || peakDb <= -120.0) {
      return Colors.white.withValues(alpha: 0.50);
    }
    return DbfsMeterVisuals.statusColor(peakDb);
  }

  double _heldPeakDbForRow(int row, MeterFrame frame) {
    final now = DateTime.now();
    final currentPeakDb = _ampToDbFs(math.max(frame.peakL, frame.peakR));

    final prevDb = _rowPeakHoldDb[row] ?? currentPeakDb;
    final lastUpdate = _rowPeakHoldLastUpdate[row] ?? now;
    final freezeUntil = _rowPeakHoldFreezeUntil[row] ?? now;
    final dt = (now.difference(lastUpdate).inMicroseconds / 1000000.0).clamp(
      0.0,
      0.25,
    );

    double heldDb = prevDb;
    if (!currentPeakDb.isFinite || currentPeakDb <= -120.0) {
      heldDb = double.negativeInfinity;
      _rowPeakHoldFreezeUntil[row] = now;
    } else if (currentPeakDb >= prevDb || !prevDb.isFinite) {
      heldDb = currentPeakDb;
      _rowPeakHoldFreezeUntil[row] = now.add(const Duration(milliseconds: 900));
    } else if (now.isAfter(freezeUntil)) {
      const decayDbPerSec = 11.0;
      heldDb = math.max(currentPeakDb, prevDb - (decayDbPerSec * dt));
    }
    if (heldDb <= -120.0) {
      heldDb = double.negativeInfinity;
    }

    _rowPeakHoldDb[row] = heldDb;
    _rowPeakHoldLastUpdate[row] = now;
    return heldDb;
  }

  double _ampToDbFs(double amp01) {
    return DbfsMeterVisuals.ampToDbfs(amp01);
  }

  static double _uiFromGainDb(double db) {
    final clampedDb = db.clamp(_kGainDbMin, _kGainDbMax).toDouble();
    if (clampedDb <= 0.0) {
      final t = (clampedDb - _kGainDbMin) / (0.0 - _kGainDbMin);
      return _kGainUiMin + ((_kGainUiUnity - _kGainUiMin) * t);
    }
    final t = clampedDb / _kGainDbMax;
    return _kGainUiUnity + ((_kGainUiMax - _kGainUiUnity) * t);
  }

  double _normalizeLoadedGainUi(
    double? rawGain, {
    required int projectVersion,
  }) {
    if (rawGain == null || !rawGain.isFinite) return _kGainUiUnity;
    final clamped = rawGain.clamp(_kGainUiMin, _kGainUiMax).toDouble();

    // Backward compatibility: old projects often stored unity at 1.0 UI or at
    // the previous linear-mapped unity (~2.727). Map both to the current
    // piecewise unity position.
    if (projectVersion <= 1 &&
        ((clamped - 1.0).abs() < 0.02 ||
            (clamped - _kLegacyLinearGainUiUnity).abs() < 0.02)) {
      return _kGainUiUnity;
    }
    return clamped;
  }

  Widget _buildMasterEffectsPage({
    bool addEffectTileFollowsEffectsInline = false,
  }) {
    void onMasterFxGraphChanged() {
      _refreshAudioEditorView();
    }

    return MasterEffectsPanel(
      key: ValueKey("master_effects_panel"),
      mode: _resolvedMode,
      isProEntitled: _isProEntitled,
      onUpgradeRequested: widget.onUpgradeRequested,
      getMasterEffects: () => JuceAudioEngine.getMasterEffects(),
      getMasterEffectIds: () => JuceAudioEngine.getMasterEffectIds(),
      getMasterEffectBypassState: (i) =>
          JuceAudioEngine.getMasterEffectBypassState(i),
      bypassMasterEffect: (i, bp) async {
        await _undoManager.execute(
          BypassMasterEffectAction(
            effectIndex: i,
            oldState: !bp,
            newState: bp,
            onChange: onMasterFxGraphChanged,
          ),
        );
        _recordProducerManualEdit('master_fx_bypass', {
          'index': i,
          'bypassed': bp,
        });
      }, //JuceAudioEngine.bypassMasterEffect(i, bp),
      // reorderMasterEffects: (from, to) => JuceAudioEngine.reorderMasterEffects(from, to),
      // removeMasterEffect: (i) => JuceAudioEngine.removeMasterEffect(i),
      // insertMasterEffect: (path) => JuceAudioEngine.insertMasterEffect(path),
      insertMasterEffect: (pathOrName) async {
        final action = InsertMasterEffectAction(
          pathOrName: pathOrName,
          onChange: onMasterFxGraphChanged,
        );
        await _undoManager.execute(action);
        if (!action.inserted) {
          _showSmallNotice('Could not load this effect plugin.');
          return;
        }
        _scheduleAutomationTargetsRefreshForAllRows();
        _recordProducerManualEdit('master_fx_insert', {'effect': pathOrName});
        _trackPluginInserted(pluginName: pathOrName, scope: 'master');
      },

      // need name of effects so undo action can add it back later
      removeMasterEffect: (effectIndex, name, applyingPreset) async {
        if (applyingPreset) {
          await JuceAudioEngine.removeMasterEffect(effectIndex);
          return;
        }
        await _undoManager.execute(
          RemoveMasterEffectAction(
            effectIndex: effectIndex,
            pathOrName: name,
            onChange: onMasterFxGraphChanged,
          ),
        );
        _scheduleAutomationTargetsRefreshForAllRows();
        _recordProducerManualEdit('master_fx_remove', {
          'index': effectIndex,
          'effect': name,
        });
        _trackPluginRemoved(pluginName: name, scope: 'master');
      },

      reorderMasterEffects: (from, to) async {
        await _undoManager.execute(
          ReorderMasterEffectAction(
            from: from,
            to: to,
            onChange: onMasterFxGraphChanged,
          ),
        );
        _scheduleAutomationTargetsRefreshForAllRows();
        _recordProducerManualEdit('master_fx_reorder', {
          'from': from,
          'to': to,
        });
      },
      scanPlugins: _cachedDesktopPluginsForPicker,
      onTogglePluginFavorite: _toggleDesktopPluginFavorite,
      onManagePlugins: PlatformCapabilities.current.isDesktop
          ? _showDesktopPluginManagerDialog
          : null,
      openMasterPluginEditor:
          PlatformCapabilities.current.isDesktop &&
              _platformCapabilities.nativePluginEditor
          ? (effectIndex) => JuceAudioEngine.openMasterPluginEditor(effectIndex)
          : null,
      getMasterPluginParameters: (i) =>
          JuceAudioEngine.getMasterPluginParameters(i),
      setMasterEffectParam: (i, id, v) async {
        await JuceAudioEngine.setMasterEffect(i, id, v);
        _updateAutomationTargetBaselineForEffectParameter(
          effectIndex: i,
          paramId: id,
          value: v,
          master: true,
        );
      },
      onRequestAutomateParameter: _requestMasterEffectAutomationClip,
      onMasterPluginParamCommit: (idx, paramId, oldValue, newValue) async {
        await _undoManager.execute(
          SetMasterEffectParamAction(
            effectIndex: idx,
            paramId: paramId,
            oldValue: oldValue,
            newValue: newValue,
            onChange: onMasterFxGraphChanged,
          ),
        );
        _recordProducerManualEdit('master_fx_param', {
          'index': idx,
          'param_id': paramId,
          'old_value': oldValue,
          'new_value': newValue,
        });
        unawaited(
          _trackPluginParameterCommitted(
            scope: 'master',
            effectIndex: idx,
            paramId: paramId,
            oldValue: oldValue,
            newValue: newValue,
          ),
        );
      },
      onMasterPresetCommit: (before, after) async {
        await _undoManager.execute(
          MasterPresetChangeAction(
            before: before,
            after: after,
            onChange: onMasterFxGraphChanged,
          ),
        );
        _recordProducerManualEdit('master_preset_commit', {
          'before_count': before.effects.length,
          'after_count': after.effects.length,
        });
      },
      onCopyMasterEffects: () {
        unawaited(_copyMasterEffects());
      },
      onPasteMasterEffects: () => _pasteMasterEffects(onMasterFxGraphChanged),
      onClearMasterEffects: () => _clearMasterEffects(onMasterFxGraphChanged),
      hasCopiedMasterEffects: _copiedEffects != null,
      projectBpm: _tempo,
      meters: _meters,
      getMasterCompressorMeter: (fx) =>
          JuceAudioEngine.getMasterCompressorMeter(fx),
      getMasterEqWaveform: (fx, sampleCount) =>
          JuceAudioEngine.getMasterEqWaveform(fx, sampleCount: sampleCount),
      getMasterStereoScope: (fx, pointCount) =>
          JuceAudioEngine.getMasterStereoScope(fx, pointCount: pointCount),
      highlighter: _mixHighlighter,
      registerPlaybackRefresh: (refresh) {
        _masterFxPlaybackRefresh = refresh;
      },
      registerParameterRevealer: (reveal) {
        _masterParameterRevealer = reveal;
      },
      addTileFollowsEffectsInline: addEffectTileFollowsEffectsInline,
    );
  }

  BoxDecoration _dawConnectedShellDecoration({
    required BorderRadius borderRadius,
    bool active = false,
    double inactiveAlpha = 0.16,
  }) {
    return BoxDecoration(
      borderRadius: borderRadius,
      color: Color.fromRGBO(244, 244, 244, active ? 0.20 : inactiveAlpha),
      border: Border.all(
        color: Colors.white.withValues(alpha: active ? 0.14 : 0.10),
      ),
    );
  }

  Widget _buildDawConnectedSurface({
    required Widget child,
    required BorderRadius borderRadius,
    EdgeInsetsGeometry padding = EdgeInsets.zero,
    bool active = false,
    bool showOverlay = true,
    double blur = 18,
    double inactiveAlpha = 0.16,
  }) {
    return ClipRRect(
      borderRadius: borderRadius,
      clipBehavior: Clip.antiAlias,
      child: BackdropFilter(
        filter: ImageFilter.blur(sigmaX: blur, sigmaY: blur),
        child: Container(
          padding: padding,
          decoration: _dawConnectedShellDecoration(
            borderRadius: borderRadius,
            active: active,
            inactiveAlpha: inactiveAlpha,
          ),
          child: Stack(
            children: [
              if (showOverlay)
                Positioned.fill(
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: <Color>[
                          Colors.white.withValues(alpha: active ? 0.10 : 0.07),
                          Colors.white.withValues(alpha: 0.04),
                          Colors.transparent,
                          Colors.black.withValues(alpha: 0.04),
                        ],
                        stops: const <double>[0.0, 0.22, 0.72, 1.0],
                      ),
                    ),
                  ),
                ),
              Material(type: MaterialType.transparency, child: child),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildConnectedTopPopupFrame({
    required Widget child,
    double topInset = 0,
  }) {
    return Padding(
      padding: EdgeInsets.only(top: topInset),
      child: child,
    );
  }

  Widget _buildExpandedChatHistoryOverlay() {
    if (!_chatWarm || !_chatExpanded) {
      return const SizedBox.shrink();
    }

    final overlayContext = context;
    final tabletDaw = _usesTabletDesktopDawShell(overlayContext);
    final androidOverlayPanelLift = Platform.isAndroid
        ? _kAndroidOverlayPanelLift
        : 0.0;
    const transportVisualBottomInset = 0.0;
    final keyboardLift = _chatKeyboardLiftForOverlay(overlayContext);
    final chatOverlayInsets = _desktopChatOverlayInsets(overlayContext);
    final mediaHeight = MediaQuery.sizeOf(overlayContext).height;
    final alignToChatBar = tabletDaw || PlatformCapabilities.current.isDesktop;
    final stackRenderObject = _editorContentStackKey.currentContext
        ?.findRenderObject();
    final stackSize =
        stackRenderObject is RenderBox && stackRenderObject.hasSize
        ? stackRenderObject.size
        : null;
    final rawChatBarRect = alignToChatBar
        ? _topPopupAnchorRect(_bottomChatBarAnchorKey)
        : null;
    final canUseChatBarAnchor =
        rawChatBarRect != null &&
        stackSize != null &&
        rawChatBarRect.width > 0.0 &&
        rawChatBarRect.top > 0.0;
    final anchoredChatBarRect = canUseChatBarAnchor
        ? _displayedBottomChatBarRectForOverlay(
            baseRect: rawChatBarRect,
            stackSize: stackSize,
            overlayContext: overlayContext,
          )
        : null;
    final useChatBarAnchor = anchoredChatBarRect != null && stackSize != null;
    final chatHistoryBaseBottom =
        _kChatBarStackHeight +
        (tabletDaw ? 0.0 : _kTransportBarHeight) +
        transportVisualBottomInset +
        _chatHistoryBottomGap +
        androidOverlayPanelLift;
    final anchoredChatGap = PlatformCapabilities.current.isDesktop || tabletDaw
        ? 12.0
        : 0.0;
    final anchoredAvailableHeight = useChatBarAnchor
        ? math.max(0.0, anchoredChatBarRect.top - 64.0)
        : mediaHeight - chatHistoryBaseBottom - 136.0;
    final defaultChatHistoryHeight = tabletDaw
        ? math.min(380.0, math.max(220.0, anchoredAvailableHeight)).toDouble()
        : PlatformCapabilities.current.isDesktop
        ? math
              .min(
                520.0,
                math.max(
                  _kDesktopChatHistoryMinHeight,
                  anchoredAvailableHeight,
                ),
              )
              .toDouble()
        : _kChatHistoryHeight;
    final chatHistoryMinHeight = tabletDaw
        ? 220.0
        : PlatformCapabilities.current.isDesktop
        ? _kDesktopChatHistoryMinHeight
        : _kChatHistoryHeight;
    final chatHistoryMaxHeight = tabletDaw
        ? math.min(
            520.0,
            math.max(chatHistoryMinHeight, anchoredAvailableHeight),
          )
        : PlatformCapabilities.current.isDesktop
        ? math.min(
            _kDesktopChatHistoryMaxHeight,
            math.max(chatHistoryMinHeight, anchoredAvailableHeight),
          )
        : _kChatHistoryHeight;
    final resizableChatHistory =
        tabletDaw || PlatformCapabilities.current.isDesktop;
    final chatHistoryHeight = resizableChatHistory
        ? (_desktopChatHistoryHeight ?? defaultChatHistoryHeight)
              .clamp(chatHistoryMinHeight, chatHistoryMaxHeight)
              .toDouble()
        : defaultChatHistoryHeight;
    final canClearChatHistory =
        !_isThinking && _chatController.messages.isNotEmpty;
    final canCopyChatHistory = _chatController.messages
        .whereType<TextMessage>()
        .any((message) => message.text.trim().isNotEmpty);
    final compactChatHeaderActions =
        !PlatformCapabilities.current.isDesktop && !tabletDaw;
    final chatHeaderActionGap = compactChatHeaderActions ? 5.0 : 8.0;

    return AnimatedPositioned(
      duration: const Duration(milliseconds: 190),
      curve: Curves.easeOutCubic,
      left: useChatBarAnchor
          ? anchoredChatBarRect.left
          : chatOverlayInsets.left,
      right: useChatBarAnchor
          ? math.max(0.0, stackSize.width - anchoredChatBarRect.right)
          : chatOverlayInsets.right,
      bottom: useChatBarAnchor
          ? math.max(
              0.0,
              stackSize.height - anchoredChatBarRect.top + anchoredChatGap,
            )
          : chatHistoryBaseBottom + keyboardLift,
      child: _wrapDesktopChatSurfaceKeyboardHandler(
        child: RepaintBoundary(
          child: SizedBox(
            height: chatHistoryHeight,
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 170),
              curve: Curves.easeOutCubic,
              margin: EdgeInsets.symmetric(
                horizontal: PlatformCapabilities.current.isDesktop || tabletDaw
                    ? 0.0
                    : 12.0,
              ),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(29),
                child: BackdropFilter(
                  filter: ImageFilter.blur(sigmaX: 14, sigmaY: 14),
                  child: Container(
                    decoration: BoxDecoration(
                      color: const Color.fromRGBO(
                        232,
                        232,
                        232,
                        _kChatChromeOpacity,
                      ),
                      borderRadius: BorderRadius.circular(29),
                      border: Border.all(
                        color: Colors.white.withValues(alpha: 0.12),
                      ),
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withValues(alpha: 0.22),
                          blurRadius: 18,
                          offset: const Offset(0, 10),
                        ),
                      ],
                    ),
                    child: Column(
                      children: [
                        if (resizableChatHistory)
                          GestureDetector(
                            behavior: HitTestBehavior.opaque,
                            onVerticalDragUpdate: (details) {
                              setState(() {
                                final current =
                                    _desktopChatHistoryHeight ??
                                    chatHistoryHeight;
                                _desktopChatHistoryHeight =
                                    (current - details.delta.dy)
                                        .clamp(
                                          chatHistoryMinHeight,
                                          chatHistoryMaxHeight,
                                        )
                                        .toDouble();
                              });
                            },
                            child: MouseRegion(
                              cursor: SystemMouseCursors.resizeUpDown,
                              child: SizedBox(
                                height: 14,
                                child: Center(
                                  child: Container(
                                    width: 42,
                                    height: 4,
                                    decoration: BoxDecoration(
                                      color: Colors.white.withValues(
                                        alpha: 0.42,
                                      ),
                                      borderRadius: BorderRadius.circular(999),
                                    ),
                                  ),
                                ),
                              ),
                            ),
                          ),
                        Padding(
                          padding: EdgeInsets.fromLTRB(
                            16,
                            resizableChatHistory ? 2 : 12,
                            12,
                            6,
                          ),
                          child: Row(
                            children: [
                              Expanded(
                                child: Text(
                                  L10n.translate(context, 'Project Chat'),
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    fontFamily: 'Pretendard',
                                    fontSize: 13,
                                    fontWeight: FontWeight.w700,
                                    letterSpacing: 0.3,
                                    color: Colors.white70,
                                  ),
                                ),
                              ),
                              _buildChatHeaderActionButton(
                                label: L10n.translate(context, 'Feedback'),
                                icon: Icons.feedback_outlined,
                                iconOnly: true,
                                onPressed: _feedbackSubmissionInFlight
                                    ? null
                                    : _openDawFeedbackComposer,
                              ),
                              SizedBox(width: chatHeaderActionGap),
                              _buildChatHeaderActionButton(
                                label: L10n.translate(context, 'Copy'),
                                icon: Icons.copy_rounded,
                                iconOnly: compactChatHeaderActions,
                                onPressed: canCopyChatHistory
                                    ? () {
                                        unawaited(_copyChatLogToClipboard());
                                      }
                                    : null,
                              ),
                              SizedBox(width: chatHeaderActionGap),
                              _buildChatHeaderActionButton(
                                label: L10n.translate(context, 'Clear'),
                                icon: Icons.delete_outline_rounded,
                                iconOnly: compactChatHeaderActions,
                                onPressed: canClearChatHistory
                                    ? _confirmClearChatHistory
                                    : null,
                              ),
                              SizedBox(width: chatHeaderActionGap),
                              _buildChatHeaderActionButton(
                                label: L10n.translate(context, 'Close'),
                                icon: Icons.close_rounded,
                                iconOnly: compactChatHeaderActions,
                                onPressed: _collapseChatWindow,
                              ),
                            ],
                          ),
                        ),
                        Expanded(
                          child: Stack(
                            children: [
                              Positioned.fill(
                                child: ClipRect(
                                  child: ShaderMask(
                                    blendMode: BlendMode.dstIn,
                                    shaderCallback: (Rect bounds) {
                                      final fadeStartStop = bounds.height > 0
                                          ? math.min(0.022, 4 / bounds.height)
                                          : 0.022;
                                      final fadeEndStop = bounds.height > 0
                                          ? math.min(0.08, 18 / bounds.height)
                                          : 0.08;
                                      return LinearGradient(
                                        begin: Alignment.topCenter,
                                        end: Alignment.bottomCenter,
                                        stops: <double>[
                                          0.0,
                                          fadeStartStop,
                                          fadeEndStop,
                                          1.0,
                                        ],
                                        colors: const <Color>[
                                          Colors.transparent,
                                          Color.fromRGBO(255, 255, 255, 0.45),
