  bool get _isChatTypingActive => PlatformCapabilities.current.isDesktop
      ? _chatFocusNode.hasFocus
      : (_chatFocusNode.hasFocus || _chatInputActive);

  bool _chatShouldTrackKeyboardInset(BuildContext overlayContext) {
    final keyboardVisible = MediaQuery.viewInsetsOf(overlayContext).bottom > 0;
    if (!keyboardVisible) return false;
    if (_usesTabletDesktopDawShell(overlayContext)) {
      return _chatExpanded &&
          (_chatInputActive || _chatFocusNode.hasFocus || _isThinking);
    }
    return _isChatTypingActive;
  }

  bool _tabletChatKeyboardBackdropActive(BuildContext overlayContext) {
    return mixroomUsesTabletLandscapeShell(overlayContext) &&
        MediaQuery.viewInsetsOf(overlayContext).bottom > 0.0 &&
        _chatExpanded &&
        (_chatInputActive || _chatFocusNode.hasFocus);
  }

  static const double _kTabletChatKeyboardGap = 4.0;

  double _tabletChatKeyboardLiftFromInset({required double keyboardInset}) {
    // iOS includes the prediction/suggestion bar in viewInsets.bottom.
    // The chatbar already has 10 px of app chrome below it in the bottom row,
    // so lift by the system obstruction minus that padding plus a small gap.
    const chatBarBottomChrome = 10.0;
    return math.max(
      0.0,
      keyboardInset - chatBarBottomChrome + _kTabletChatKeyboardGap,
    );
  }

  EdgeInsets _desktopChatOverlayInsets(BuildContext overlayContext) {
    final width = MediaQuery.sizeOf(overlayContext).width;
    if (_usesTabletDesktopDawShell(overlayContext)) {
      final panelReserve = _tabletReservedRightPanelWidthFor(
        width,
        collapsed: _tabletRightPanelCollapsed,
      );
      final maxContentWidth = math.min(
        TabletDawPanelLayout.bottomTabletChatMaxWidthForScreen(width),
        width - 32.0,
      );
      final centeredInset = math.max(16.0, (width - maxContentWidth) / 2.0);
      return EdgeInsets.fromLTRB(
        centeredInset,
        0,
        math.max(centeredInset, panelReserve + 12.0),
        0,
      );
    }
    if (!PlatformCapabilities.current.isDesktop) {
      return EdgeInsets.zero;
    }
    const reservedLeft = 16.0 + 372.0 + 12.0;
    const reservedRight = 16.0 + 48.0 + 10.0;
    final maxContentWidth = math.min(920.0, width - 32.0);
    if (width - reservedLeft - reservedRight >= maxContentWidth) {
      return const EdgeInsets.fromLTRB(reservedLeft, 0, reservedRight, 0);
    }
    final sideInset = math.max(12.0, (width - maxContentWidth) / 2);
    return EdgeInsets.symmetric(horizontal: sideInset);
  }

  double _chatKeyboardLiftForOverlay(BuildContext overlayContext) {
    final keyboardInset = MediaQuery.viewInsetsOf(overlayContext).bottom;
    final chatKeyboardActive = _chatShouldTrackKeyboardInset(overlayContext);
    final fixedTransportFootprint =
        _kTransportBarHeight + _androidTransportBottomInset(overlayContext);
    final tabletDaw = _usesTabletDesktopDawShell(overlayContext);
    final rawKeyboardLift = chatKeyboardActive
        ? (tabletDaw
              ? _tabletChatKeyboardLiftFromInset(keyboardInset: keyboardInset)
              : math.max(
                  0.0,
                  keyboardInset -
                      MediaQuery.paddingOf(overlayContext).bottom +
                      8.0,
                ))
        : 0.0;
    if (tabletDaw) {
      return rawKeyboardLift;
    }
    return math.max(0.0, rawKeyboardLift - fixedTransportFootprint);
  }

  double _desktopBottomPanelInset({
    required bool chatTypingActive,
    required double chatLift,
  }) {
    if (_usesTabletDesktopDawShell(context)) {
      return chatLift +
          _kChatBarStackHeight +
          _androidTabletDawBottomInset(context) +
          (_isProducerCaptureUiVisible && !chatTypingActive
              ? _kProducerBannerHeightEstimate
              : 0.0) +
          _kSamplePanelBottomGap;
    }
    if (!PlatformCapabilities.current.isDesktop) {
      return chatLift +
          _kChatBarStackHeight +
          _kTransportBarHeight +
          (_isProducerCaptureUiVisible && !chatTypingActive
              ? _kProducerBannerHeightEstimate
              : 0.0) +
          (Platform.isAndroid ? 10.0 : 0.0) +
          (Platform.isAndroid ? _kAndroidOverlayPanelLift : 0.0) +
          _kSamplePanelBottomGap;
    }
    return chatLift +
        _kChatBarStackHeight +
        (_isProducerCaptureUiVisible && !chatTypingActive
            ? _kProducerBannerHeightEstimate
            : 0.0);
  }

  Widget _buildTopCircleButtonShell({
    required Widget child,
    required VoidCallback? onTap,
    Key? key,
    String? semanticLabel,
    String? semanticIdentifier,
    bool active = false,
    double size = 52,
    bool drawShell = true,
    bool showPressFeedback = false,
    bool pressed = false,
    ValueChanged<bool>? onHighlightChanged,
  }) {
    final BorderRadius buttonRadius = BorderRadius.circular(size / 2);
    final isExportButton = semanticIdentifier == 'daw.export';
    final isBackButton = semanticIdentifier == 'daw.navigation.back';
    final effectivePressed =
        pressed || (isExportButton && _exportButtonPressed);
    final hoverShadowVisible =
        onTap != null &&
        ((isExportButton && _exportButtonHovered) ||
            (isBackButton && _backButtonHovered));
    final Widget shell = drawShell
        ? _buildDawConnectedSurface(
            borderRadius: buttonRadius,
            active: active,
            child: SizedBox(width: size, height: size, child: child),
          )
        : SizedBox(width: size, height: size, child: child);
    final Widget body = AnimatedContainer(
      duration: const Duration(milliseconds: 140),
      curve: Curves.easeOutCubic,
      width: size,
      height: size,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        boxShadow: hoverShadowVisible
            ? <BoxShadow>[
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.24),
                  blurRadius: 16,
                  spreadRadius: 2,
                  offset: const Offset(0, 5),
                ),
                BoxShadow(
                  color: Colors.white.withValues(alpha: 0.12),
                  blurRadius: 10,
                  spreadRadius: 0,
                ),
              ]
            : const <BoxShadow>[],
      ),
      child: AnimatedScale(
        duration: const Duration(milliseconds: 110),
        curve: Curves.easeOutCubic,
        scale: effectivePressed ? 0.93 : 1.0,
        child: AnimatedOpacity(
          duration: const Duration(milliseconds: 110),
          curve: Curves.easeOutCubic,
          opacity: effectivePressed ? 0.82 : 1.0,
          child: shell,
        ),
      ),
    );
    final useInkFeedback = showPressFeedback || isExportButton || isBackButton;
    return Semantics(
      identifier: semanticIdentifier,
      button: true,
      enabled: onTap != null,
      label: semanticLabel,
      child: useInkFeedback
          ? Material(
              type: MaterialType.transparency,
              child: InkWell(
                key: key,
                onTap: onTap,
                onHover: isExportButton || isBackButton
                    ? (hovered) {
                        if (!mounted) {
                          return;
                        }
                        setState(() {
                          if (isExportButton) {
                            _exportButtonHovered = hovered;
                          }
                          if (isBackButton) {
                            _backButtonHovered = hovered;
                          }
                        });
                      }
                    : null,
                onHighlightChanged: (highlighted) {
                  if (isExportButton &&
                      mounted &&
                      _exportButtonPressed != highlighted) {
                    setState(() {
                      _exportButtonPressed = highlighted;
                    });
                  }
                  onHighlightChanged?.call(highlighted);
                },
                customBorder: const CircleBorder(),
                splashColor: Colors.white.withValues(alpha: 0.18),
                highlightColor: Colors.white.withValues(alpha: 0.10),
                hoverColor: Colors.white.withValues(alpha: 0.08),
                child: SizedBox(width: size, height: size, child: body),
              ),
            )
          : GestureDetector(
              key: key,
              behavior: HitTestBehavior.opaque,
              onTap: onTap,
              child: body,
            ),
    );
  }

