  Widget _buildMixroomDropdownField<T>({
    required String label,
    required T value,
    required List<T> options,
    required ValueChanged<T?> onChanged,
    required String Function(T) textBuilder,
    double height = 50.0,
    double radius = 18.0,
    double menuMaxHeight = 360.0,
    double? menuMinWidth,
    double? menuMaxWidth,
    Color accentColor = const Color(0xFF258AE6),
  }) {
    if (options.isEmpty) {
      return Container(
        height: height,
        alignment: Alignment.centerLeft,
        padding: const EdgeInsets.symmetric(horizontal: 12),
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: 0.055),
          borderRadius: BorderRadius.circular(radius),
          border: Border.all(color: Colors.white.withValues(alpha: 0.08)),
        ),
        child: Text(
          L10n.translate(context, label),
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: TextStyle(
            fontFamily: 'Pretendard',
            color: Colors.white.withValues(alpha: 0.42),
            fontSize: 12,
            fontWeight: FontWeight.w700,
          ),
        ),
      );
    }

    final effectiveValue = options.contains(value) ? value : options.first;
    final selectedText = textBuilder(effectiveValue);
    const fieldTextStyle = TextStyle(
      fontFamily: 'Pretendard',
      color: Color(0xFFF4F4F4),
      fontSize: 12.5,
      fontWeight: FontWeight.w700,
      height: 1.0,
    );
    final menuTextStyle = fieldTextStyle.copyWith(
      color: Colors.white.withValues(alpha: 0.76),
      fontWeight: FontWeight.w600,
      height: 1.1,
    );
    final selectedMenuTextStyle = fieldTextStyle.copyWith(
      color: Colors.white.withValues(alpha: 0.94),
      fontWeight: FontWeight.w700,
      height: 1.1,
    );
    final menuPreferredHeight = math
        .min(
          menuMaxHeight,
          2.0 + (options.length * 35.0) + math.max(0, options.length - 1),
        )
        .toDouble();

    return Builder(
      builder: (anchorContext) {
        return Semantics(
          button: true,
          label: L10n.translate(context, label),
          value: selectedText,
          child: Material(
            color: Colors.transparent,
            borderRadius: BorderRadius.circular(radius),
            clipBehavior: Clip.antiAlias,
            child: InkWell(
              borderRadius: BorderRadius.circular(radius),
              onTap: () async {
                final selected = await showMixroomGlassDropdown<T>(
                  anchorContext: anchorContext,
                  verticalGap: -1.0,
                  minWidth: menuMinWidth,
                  maxWidth: menuMaxWidth,
                  preferredHeight: menuPreferredHeight,
                  radius: radius,
                  color: const Color.fromRGBO(244, 244, 244, 0.105),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 4,
                    vertical: 1,
                  ),
                  child: ConstrainedBox(
                    constraints: BoxConstraints(maxHeight: menuMaxHeight),
                    child: ListView.separated(
                      padding: EdgeInsets.zero,
                      shrinkWrap: true,
                      physics: const ClampingScrollPhysics(),
                      itemCount: options.length,
                      separatorBuilder: (_, __) => Divider(
                        height: 1,
                        thickness: 1,
                        indent: 10,
                        endIndent: 10,
                        color: Colors.white.withValues(alpha: 0.045),
                      ),
                      itemBuilder: (menuContext, index) {
                        final option = options[index];
                        final isSelected = option == effectiveValue;
                        return Material(
                          color: Colors.transparent,
                          child: InkWell(
                            borderRadius: BorderRadius.circular(13),
                            onTap: () => Navigator.of(menuContext).pop(option),
                            child: AnimatedContainer(
                              duration: const Duration(milliseconds: 110),
                              curve: Curves.easeOutCubic,
                              constraints: const BoxConstraints(minHeight: 34),
                              padding: const EdgeInsets.symmetric(
                                horizontal: 10,
                                vertical: 4,
                              ),
                              decoration: BoxDecoration(
                                color: isSelected
                                    ? const Color(
                                        0xFF258AE6,
                                      ).withValues(alpha: 0.16)
                                    : Colors.transparent,
                                borderRadius: BorderRadius.circular(13),
                                border: isSelected
                                    ? Border.all(
                                        color: const Color(
                                          0xFF258AE6,
                                        ).withValues(alpha: 0.20),
                                      )
                                    : null,
                              ),
                              child: Row(
                                children: [
                                  Expanded(
                                    child: Text(
                                      textBuilder(option),
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: isSelected
                                          ? selectedMenuTextStyle
                                          : menuTextStyle,
                                    ),
                                  ),
                                  if (isSelected) ...[
                                    const SizedBox(width: 8),
                                    Icon(
                                      Icons.check_rounded,
                                      color: accentColor,
                                      size: 17,
                                    ),
                                  ],
                                ],
                              ),
                            ),
                          ),
                        );
                      },
                    ),
                  ),
                );
                if (selected != null) {
                  onChanged(selected);
                }
              },
              child: Ink(
                height: height,
                padding: const EdgeInsets.symmetric(horizontal: 12),
                decoration: BoxDecoration(
                  color: const Color.fromRGBO(244, 244, 244, 0.10),
                  borderRadius: BorderRadius.circular(radius),
                  border: Border.all(
                    color: Colors.white.withValues(alpha: 0.13),
                  ),
                  boxShadow: <BoxShadow>[
                    BoxShadow(
                      color: Colors.black.withValues(alpha: 0.08),
                      blurRadius: 10,
                      offset: const Offset(0, 3),
                    ),
                  ],
                ),
                child: Row(
                  children: [
                    Expanded(
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            L10n.translate(context, label),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              fontFamily: 'Pretendard',
                              color: Colors.white.withValues(alpha: 0.56),
                              fontSize: 10.5,
                              fontWeight: FontWeight.w800,
                              height: 1.0,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            selectedText,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: fieldTextStyle,
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(width: 8),
                    Icon(
                      Icons.keyboard_arrow_down_rounded,
                      color: Colors.white.withValues(alpha: 0.72),
                      size: 20,
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _buildTabletRightPanelSelector({double? width}) {
    final panelWidth = _tabletExpandedRightPanelWidthFor(
      MediaQuery.sizeOf(context).width,
    );
    final compact = TabletDawPanelLayout.usesCompactRightPanelHeader(
      panelWidth,
    );
    final selectorWidth =
        width ??
        TabletDawPanelLayout.rightPanelHeaderSelectorWidth(
          panelWidth: panelWidth,
          compact: compact,
        );
    Widget segment(
      String label,
      String tabId, {
      int flex = 1,
      required BorderRadius selectedRadius,
    }) {
      final selected =
          !_tabletRightPanelCollapsed && _tabletRightPanelTab == tabId;
      final translatedLabel = L10n.translate(context, label);
      final semanticLabel = selected
          ? 'Hide $translatedLabel panel'
          : 'Show $translatedLabel panel';
      return Expanded(
        flex: flex,
        child: Semantics(
          button: true,
          selected: selected,
          label: semanticLabel,
          child: Material(
            color: Colors.transparent,
            borderRadius: selectedRadius,
            clipBehavior: Clip.antiAlias,
            child: InkWell(
              borderRadius: selectedRadius,
              hoverColor: const Color(0xFFF4F4F4).withValues(alpha: 0.13),
              highlightColor: Colors.white.withValues(alpha: 0.08),
              splashColor: Colors.white.withValues(alpha: 0.12),
              onTap: () {
                if (selected) {
                  setState(() {
                    _tabletRightPanelCollapsed = true;
                    _setMasterMeterExpandedState(false);
                  });
                  return;
                }
                _selectTabletRightPanelTab(tabId);
              },
              child: SizedBox.expand(
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 150),
                  curve: Curves.easeOutCubic,
                  margin: EdgeInsets.zero,
                  decoration: BoxDecoration(
                    color: selected
                        ? const Color(0xFFF4F4F4).withValues(alpha: 0.54)
                        : Colors.transparent,
                    borderRadius: selectedRadius,
                    border: selected
                        ? Border.all(
                            color: Colors.white.withValues(alpha: 0.26),
                          )
                        : null,
                    boxShadow: selected
                        ? <BoxShadow>[
                            BoxShadow(
                              color: Colors.black.withValues(alpha: 0.12),
                              blurRadius: 8,
                              offset: const Offset(0, 2),
                            ),
                          ]
                        : const <BoxShadow>[],
                  ),
                  alignment: Alignment.center,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 6),
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      child: Text(
                        translatedLabel,
                        maxLines: 1,
                        softWrap: false,
                        style: TextStyle(
                          fontFamily: 'Pretendard',
                          color: selected
                              ? const Color(0xFF15436C)
                              : const Color(0xFFF4F4F4).withValues(alpha: 0.78),
                          fontSize: compact ? 10.5 : 11.5,
                          fontWeight: selected
                              ? FontWeight.w900
                              : FontWeight.w700,
                          height: 1.0,
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
      );
    }

    return _buildDawConnectedSurface(
      borderRadius: BorderRadius.circular(24),
      child: SizedBox(
        width: selectorWidth,
        height: 48,
        child: Row(
          children: [
            segment(
              'Track',
              'inspector',
              selectedRadius: const BorderRadius.only(
                topLeft: Radius.circular(22),
                bottomLeft: Radius.circular(22),
              ),
            ),
            Container(
              width: 1,
              height: 32,
              color: Colors.white.withValues(alpha: 0.16),
            ),
            segment('FX', 'fx', selectedRadius: BorderRadius.zero),
            Container(
              width: 1,
              height: 32,
              color: Colors.white.withValues(alpha: 0.16),
            ),
            segment(
              'Mix',
              'mixer',
              selectedRadius: const BorderRadius.only(
                topRight: Radius.circular(22),
                bottomRight: Radius.circular(22),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildTabletProjectHeader({required double width}) {
    final title = _projectName.trim().isEmpty
        ? 'Untitled Project'
        : _projectName;
    final compact = width < 236.0;
    final macDesktop = _usesMacNativeWindowControlsInset;
    const headerHeight = 48.0;
    final actionSize = compact ? 40.0 : 48.0;
    final actionSlotWidth = actionSize;
    final settingsSize = compact ? 40.0 : 48.0;
    final gap = compact ? 6.0 : 9.0;
    final trailingInset = compact ? 0.0 : 10.0;
    final titleSurfaceWidth = math.max(
      0.0,
      width - actionSlotWidth - gap - trailingInset,
    );
    final titleInset = compact ? 8.0 : 12.0;
    final macBackPillDownNudge = macDesktop
        ? ((headerHeight - _kMacDawBackPillHeight) *
                  _kMacDawBackPillDownNudgeFraction)
              .clamp(0.0, 5.0)
              .toDouble()
        : 0.0;
    return SizedBox(
      width: width,
      height: headerHeight,
      child: Row(
        children: [
          SizedBox(
            width: actionSlotWidth,
            height: headerHeight,
            child: Align(
              alignment: Alignment.center,
              child: macDesktop
                  ? Transform.translate(
                      offset: Offset(
                        _kMacDawBackPillHorizontalNudge,
                        macBackPillDownNudge,
                      ),
                      child: _buildMacDawBackPill(
                        width: _kMacDawBackPillWidth,
                        height: _kMacDawBackPillHeight,
                        compact: true,
                      ),
                    )
                  : _buildTopCircleButtonShell(
                      key: _editorBackButtonKey,
                      semanticLabel: L10n.translate(context, 'Back'),
                      semanticIdentifier: 'daw.navigation.back',
                      onTap: _handleBackButtonTap,
                      active: false,
                      size: actionSize,
                      showPressFeedback: true,
                      pressed:
                          _backButtonPressed || _backButtonTapFeedbackActive,
                      onHighlightChanged: (pressed) {
                        if (!mounted || _backButtonPressed == pressed) return;
                        setState(() {
                          _backButtonPressed = pressed;
                        });
                      },
                      child: Center(
                        child: SvgPicture.asset(
                          kMixroomDawTopBackIconAsset,
                          width: compact ? 9 : 10,
                          height: compact ? 16 : 18,
                        ),
                      ),
                    ),
            ),
          ),
          SizedBox(width: gap),
          SizedBox(
            key: _projectNamePillKey,
            width: titleSurfaceWidth,
            height: headerHeight,
            child: _buildDawConnectedSurface(
              borderRadius: BorderRadius.circular(24),
              active: _isProjectSettingsOpen,
              child: Row(
                children: [
                  Expanded(
                    child: Padding(
                      padding: EdgeInsets.only(
                        left: titleInset,
                        right: compact ? 4.0 : 6.0,
                      ),
                      child: Text(
                        title,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          fontFamily: 'Pretendard',
                          color: const Color(0xFFF4F4F4),
                          fontSize: compact ? 10.6 : 11.6,
                          fontWeight: FontWeight.w700,
                          height: 1.0,
                        ),
                      ),
                    ),
                  ),
                  Semantics(
                    identifier: 'daw.project_settings',
                    label: L10n.translate(context, 'Project Settings'),
                    button: true,
                    child: Material(
                      color: Colors.transparent,
                      child: InkWell(
                        key: _projectSettingsButtonKey,
                        borderRadius: BorderRadius.circular(24),
                        onTap: () {
                          _trackUiClick(
                            controlId: 'project_settings_button',
                            surface: 'top_bar',
                            controlType: 'toggle',
                            value: !_isProjectSettingsOpen,
                          );
                          if (_isProjectSettingsOpen) {
                            unawaited(_closeProjectSettings());
                            return;
                          }
                          _openProjectSettings();
                        },
                        child: SizedBox(
                          width: settingsSize,
                          height: headerHeight,
                          child: Center(
                            child: SvgPicture.asset(
                              kMixroomDawTopSettingsIconAsset,
                              width: compact ? 15 : 17,
                              height: compact ? 15 : 17,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
          if (trailingInset > 0.0) SizedBox(width: trailingInset),
        ],
      ),
    );
  }

