  Future<void> _showProjectRecoveryDialog() async {
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return _buildDesktopPopupSurface(
          width: 560,
          outerPadding: const EdgeInsets.symmetric(
            horizontal: 36,
            vertical: 28,
          ),
          padding: const EdgeInsets.fromLTRB(20, 18, 20, 18),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  const Expanded(
                    child: Text(
                      'Project Recovery',
                      style: TextStyle(
                        color: Color(0xFFF4F4F4),
                        fontFamily: 'Pretendard',
                        fontSize: 18,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                  IconButton(
                    onPressed: () => Navigator.of(dialogContext).pop(),
                    icon: const Icon(
                      Icons.close_rounded,
                      color: Color(0xFFEFEFEF),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              if (_hostedPluginRestoreEntries.values
                  .where(
                    (entry) =>
                        entry.status != _HostedPluginRestoreStatus.loaded,
                  )
                  .isNotEmpty) ...[
                ..._hostedPluginRestoreEntries.values
                    .where(
                      (entry) =>
                          entry.status != _HostedPluginRestoreStatus.loaded,
                    )
                    .map((entry) {
                      final isProblem = entry.isProblem;
                      final isLoading =
                          entry.status == _HostedPluginRestoreStatus.loading;
                      return Container(
                        margin: const EdgeInsets.only(bottom: 10),
                        padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
                        decoration: BoxDecoration(
                          color:
                              (isProblem
                                      ? const Color(0xFFFFA726)
                                      : const Color(0xFF62D0FF))
                                  .withValues(alpha: 0.08),
                          borderRadius: BorderRadius.circular(16),
                          border: Border.all(
                            color:
                                (isProblem
                                        ? const Color(0xFFFFA726)
                                        : const Color(0xFF62D0FF))
                                    .withValues(alpha: 0.22),
                          ),
                        ),
                        child: Row(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Padding(
                              padding: const EdgeInsets.only(top: 2),
                              child: isLoading
                                  ? const SizedBox(
                                      width: 16,
                                      height: 16,
                                      child: CircularProgressIndicator(
                                        strokeWidth: 2,
                                        color: Color(0xFF62D0FF),
                                      ),
                                    )
                                  : Icon(
                                      isProblem
                                          ? Icons.warning_amber_rounded
                                          : Icons.schedule_rounded,
                                      color: isProblem
                                          ? const Color(0xFFFFB74D)
                                          : const Color(0xFF62D0FF),
                                      size: 18,
                                    ),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    entry.title,
                                    style: const TextStyle(
                                      color: Color(0xFFF4F4F4),
                                      fontSize: 14,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  const SizedBox(height: 5),
                                  Text(
                                    entry.detail,
                                    style: TextStyle(
                                      color: Colors.white.withValues(
                                        alpha: 0.72,
                                      ),
                                      fontSize: 12.8,
                                      height: 1.35,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      );
                    }),
                const SizedBox(height: 4),
              ],
              if (_projectLoadIssues.isEmpty &&
                  _hostedPluginRestoreEntries.values.every(
                    (entry) =>
                        entry.status == _HostedPluginRestoreStatus.loaded,
                  ))
                Text(
                  'No recovery or missing-asset notices for this session.',
                  style: TextStyle(
                    color: Colors.white.withValues(alpha: 0.62),
                    fontSize: 13.2,
                  ),
                )
              else
                ..._projectLoadIssues.map((issue) {
                  return Container(
                    margin: const EdgeInsets.only(bottom: 10),
                    padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.05),
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(
                        color: Colors.white.withValues(alpha: 0.08),
                      ),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          issue.title,
                          style: const TextStyle(
                            color: Color(0xFFF4F4F4),
                            fontSize: 14,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          issue.detail,
                          style: TextStyle(
                            color: Colors.white.withValues(alpha: 0.72),
                            fontSize: 12.8,
                            height: 1.35,
                          ),
                        ),
                      ],
                    ),
                  );
                }),
              if (PlatformCapabilities.current.isDesktop &&
                  _projectLoadIssues.any(
                    (issue) =>
                        issue.type == _ProjectLoadIssueType.missingPlugin ||
                        issue.type ==
                            _ProjectLoadIssueType.partialPluginRestore,
                  )) ...[
                const SizedBox(height: 8),
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton.icon(
                    onPressed: () async {
                      Navigator.of(dialogContext).pop();
                      await _retryDesktopPluginRestoreFromSavedSnapshots();
                    },
                    icon: const Icon(Icons.refresh_rounded),
                    label: const Text('Retry Desktop Plugin Restore'),
                  ),
                ),
              ],
            ],
          ),
        );
      },
    );
  }

