  InputDecoration _projectSettingsFieldDecoration({
    required String labelText,
    Widget? suffixIcon,
  }) {
    final border = UnderlineInputBorder(
      borderSide: BorderSide(color: Colors.white.withValues(alpha: 0.14)),
    );
    return InputDecoration(
      labelText: labelText,
      labelStyle: TextStyle(
        fontFamily: 'Pretendard',
        color: Colors.white.withValues(alpha: 0.72),
      ),
      isDense: true,
      filled: false,
      contentPadding: const EdgeInsets.symmetric(horizontal: 2, vertical: 10),
      border: border,
      enabledBorder: border,
      focusedBorder: border.copyWith(
        borderSide: const BorderSide(color: Color(0xFF1F89E3), width: 1.3),
      ),
      disabledBorder: border,
      suffixIcon: suffixIcon,
    );
  }

  Future<void> _selectInputDevice(MediaDeviceInfo device) async {
    final stream = await navigator.mediaDevices.getUserMedia({
      'audio': {'deviceId': device.deviceId},
      'video': false,
    });

    // Stop immediately — we are only probing
    for (var t in stream.getTracks()) {
      t.stop();
    }

    setState(() {
      _selectedInput = device;
    });
  }

  // iOS restricts this from happening, so give some message indicating it will have no effect, or prevent it
  Future<void> _selectOutputDevice(MediaDeviceInfo device) async {
    try {
      await Helper.selectAudioOutput(device.deviceId);
    } catch (e) {
      debugPrint("selectAudioOutput failed (falling back): $e");
    }
  }

  Future<void> _selectMacOutputDevice(String name) async {
    if (_isBluetoothV2Session) {
      final trimmed = name.trim();
      final coordinator = _audioRouteCoordinatorV2;
      if (trimmed.isEmpty) return;
      if (!_macV2OutputSelectionEnabled || coordinator == null) {
        _showSmallNotice('Audio output is changing. Please wait.');
        return;
      }
      final result = await coordinator.selectPlaybackOutput(trimmed);
      if (!mounted) return;
      if (!result.succeeded) {
        await _loadMacV2AudioDevices();
        return;
      }
      final verifiedName = result.snapshot.juce.outputDeviceName?.trim() ?? '';
      _setStateAndRefreshProjectSettings(() {
        _macOutputDeviceName = verifiedName.isEmpty ? trimmed : verifiedName;
      });
      return;
    }
    final trimmed = name.trim();
    if (trimmed.isEmpty) return;

    final ok = await JuceAudioEngine.selectOutputDevice(trimmed);
    if (!mounted) return;
    if (!ok) {
      _showSmallNotice(
        L10n.translate(context, 'Selected output device is not available.'),
      );
      await _loadInputDevicesFromJuce();
      return;
    }

    _setStateAndRefreshProjectSettings(() {
      _macOutputDeviceName = trimmed;
    });
    await _refreshAudioRouteInfo();
    await _ensurePlaybackRouteReady(reason: 'selectMacOutputDevice');
  }

  Future<void> _selectMacV2InputDevice(String? name) async {
    final coordinator = _audioRouteCoordinatorV2;
    if (!_macV2InputSelectionEnabled || coordinator == null) {
      _showSmallNotice('Audio input selection is not ready yet.');
      return;
    }
    final selection = name?.trim();
    _setStateAndRefreshProjectSettings(
      () => _macV2InputSelectionInFlight = true,
    );
    try {
      final result = await coordinator.selectRecordingInput(
        selection == null || selection.isEmpty ? null : selection,
      );
      if (!mounted) return;
      if (!result.succeeded) {
        _showSmallNotice(
          L10n.translate(context, 'Selected input device is not available.'),
        );
        await _loadMacV2AudioDevices();
        return;
      }
      _setStateAndRefreshProjectSettings(() {
        _macInputDeviceName = selection == null || selection.isEmpty
            ? null
            : selection;
      });
    } finally {
      if (mounted) {
        _setStateAndRefreshProjectSettings(
          () => _macV2InputSelectionInFlight = false,
        );
      }
    }
  }

  List<_InputChannelRouteOption> _buildInputChannelRouteOptions(
    int numInputChannels,
  ) {
    if (numInputChannels <= 0) return const <_InputChannelRouteOption>[];

    final options = <_InputChannelRouteOption>[
      for (int ch = 0; ch < numInputChannels; ch++)
        _InputChannelRouteOption(channelStart: ch, channelCount: 1),
      for (int ch = 0; ch + 1 < numInputChannels; ch += 2)
        _InputChannelRouteOption(channelStart: ch, channelCount: 2),
    ];
    return options;
  }

  _InputChannelRouteOption? _findSelectedInputChannelRouteOption(
    List<_InputChannelRouteOption> options,
  ) {
    for (final option in options) {
      if (option.channelStart == _selectedChannelStart &&
          option.channelCount == _selectedChannelCount) {
        return option;
      }
    }
    return null;
  }

  void _normalizeInputChannelSelection() {
    if (_numInputChannels <= 0) {
      _selectedChannelStart = 0;
      _selectedChannelCount = 1;
      return;
    }

    _selectedChannelStart = _selectedChannelStart.clamp(
      0,
      (_numInputChannels - 1).clamp(0, 999),
    );
    _selectedChannelCount = _selectedChannelCount.clamp(
      1,
      (_numInputChannels - _selectedChannelStart).clamp(1, 999),
    );

    final options = _buildInputChannelRouteOptions(_numInputChannels);
    final selected = _findSelectedInputChannelRouteOption(options);
    if (selected != null) return;

    final monoFallback = options.firstWhere(
      (option) =>
          option.channelCount == 1 &&
          option.channelStart == _selectedChannelStart,
      orElse: () => options.first,
    );
    _selectedChannelStart = monoFallback.channelStart;
    _selectedChannelCount = monoFallback.channelCount;
  }

  int _desiredRecordingInputOpenChannels() {
    if (_numInputChannels <= 0) {
      if (Platform.isAndroid || Platform.isIOS) {
        // Unknown route state: request a single input first to wake/arm the
        // input path, then refresh real channel metadata.
        return 1;
      }
      return 0;
    }
    final desiredInputs = _selectedChannelStart + _selectedChannelCount;
    return math.max(1, math.min(_numInputChannels, desiredInputs));
  }

  int _effectiveInputChannelCountForSettings() {
    var count = _numInputChannels;
    if (_isValidRowIndex(_selectedRow)) {
      final row = _rows[_selectedRow];
      count = math.max(count, row.inputChannelStart + row.inputChannelCount);
    }
    count = math.max(count, _selectedChannelStart + _selectedChannelCount);
    return count;
  }

  bool _shouldShowInputChannelRouteSelector() {
    return _inputDevices.isNotEmpty &&
        _effectiveInputChannelCountForSettings() > 0;
  }

  bool _recordingInputsPreparedFor({
    required String selectedDevice,
    required int desiredInputChannels,
  }) {
    return _lastPreparedRecordingDevice == selectedDevice &&
        _lastPreparedRecordingInputOpenChannels == desiredInputChannels;
  }

  bool get _recordButtonVisuallyActive =>
      _isRecording || _recordStartVisualPending;

  bool _supportsNativeBluetoothMonitorPolicy() {
    return Platform.isAndroid || Platform.isIOS || Platform.isMacOS;
  }

  bool _sameAudioRouteInfo(AudioRouteInfo a, AudioRouteInfo b) {
    return a.outputRouteKind == b.outputRouteKind &&
        a.outputRouteName == b.outputRouteName &&
        a.inputDeviceName == b.inputDeviceName &&
        a.inputIsBluetoothHeadset == b.inputIsBluetoothHeadset;
  }

  bool _inputDeviceCacheIsFresh({
    Duration maxAge = const Duration(seconds: 45),
  }) {
    if (_lastInputDevicesLoadedElapsed == Duration.zero) return false;
    return _transportUiStopwatch.elapsed - _lastInputDevicesLoadedElapsed <=
        maxAge;
  }

  bool _audioRouteInfoIsKnown(AudioRouteInfo info) {
    return info.outputRouteKind != AudioRouteKind.unknown ||
        info.outputRouteName.trim().isNotEmpty ||
        info.inputDeviceName.trim().isNotEmpty ||
        info.inputIsBluetoothHeadset;
  }

  bool _audioRouteInfoCacheIsFresh({
    Duration maxAge = const Duration(seconds: 45),
  }) {
    if (_lastAudioRouteInfoRefreshElapsed == Duration.zero) return false;
    return _transportUiStopwatch.elapsed - _lastAudioRouteInfoRefreshElapsed <=
        maxAge;
  }

  String _normalizeBluetoothRouteKeyToken(String raw) {
    return raw
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  String _bluetoothMicOptInKey([AudioRouteInfo? info]) {
    final routeInfo = info ?? _audioRouteInfo;
    final inputName = routeInfo.inputDeviceName.isNotEmpty
        ? routeInfo.inputDeviceName
        : (_selectedDevice ?? '');
    final normalized = _normalizeBluetoothRouteKeyToken(inputName);
    if (normalized.isEmpty) return 'bluetooth headset mic';
    return '$normalized::bluetooth headset mic';
  }

  bool _looksLikeBluetoothDeviceName(String name) {
    final info = _audioInputDevicePolicy.findByName(_inputDeviceInfos, name);
    if (info != null) return info.isBluetoothInput;
    final normalized = _normalizeBluetoothRouteKeyToken(name);
    if (normalized.isEmpty) return false;
    return normalized.contains('airpods') ||
        normalized.contains('bluetooth') ||
        normalized.contains('buds') ||
        normalized.contains('beats') ||
        normalized.contains('headset');
  }

  Future<void> _loadBluetoothRecordingPrefs() async {
    final prefs = await SharedPreferences.getInstance();
    if (!mounted) return;
    _setStateAndRefreshProjectSettings(() {
      _advancedBluetoothMonitorOverride =
          prefs.getBool(_kBluetoothMonitorOverridePref) ?? false;
      _allowedBluetoothMicKeys
        ..clear()
        ..addAll(
          prefs.getStringList(_kAllowedBluetoothMicKeysPref) ?? const [],
        );
    });
  }

  Future<void> _persistBluetoothMonitorOverride() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(
      _kBluetoothMonitorOverridePref,
      _advancedBluetoothMonitorOverride,
    );
  }

  Future<void> _persistBluetoothMicOptInKeys() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setStringList(
      _kAllowedBluetoothMicKeysPref,
      _allowedBluetoothMicKeys.toList()..sort(),
    );
  }

  bool _isBluetoothMicOptedIn([AudioRouteInfo? info]) {
    return _allowedBluetoothMicKeys.contains(_bluetoothMicOptInKey(info));
  }

  String? _recommendedNonBluetoothInputDevice() {
    if (Platform.isMacOS && _inputDeviceInfos.isNotEmpty) {
      return _audioInputDevicePolicy.safeFallbackName(
        devices: _inputDeviceInfos,
        selectedName: _selectedDevice,
        currentName: _audioRouteInfo.inputDeviceName,
      );
    }
    for (final device in _inputDevices) {
      if (!_looksLikeBluetoothDeviceName(device)) {
        return device;
      }
    }
    return null;
  }

  void _showBluetoothInputBlockedNotice() {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          L10n.translate(
            context,
            'Bluetooth microphones are disabled in this version. Mixroom is using the built-in/default mic instead.',
          ),
        ),
      ),
    );
  }

  Future<bool> _ensureMacNonBluetoothRecordingInput({
    required String reason,
    bool notify = false,
  }) async {
    if (!Platform.isMacOS) return true;

    final currentInputName = (await JuceAudioEngine.getCurrentDeviceName())
        .trim();
    final selectedName = (_selectedDevice ?? '').trim();
    final fallback = _inputDeviceInfos.isNotEmpty
        ? _audioInputDevicePolicy.safeFallbackName(
            devices: _inputDeviceInfos,
            selectedName: selectedName,
            currentName: currentInputName,
          )
        : _recommendedNonBluetoothInputDevice();

    final selectedIsBluetooth =
        selectedName.isNotEmpty && _looksLikeBluetoothDeviceName(selectedName);
    final currentIsBluetooth =
        currentInputName.isNotEmpty &&
        _looksLikeBluetoothDeviceName(currentInputName);
    final routeIsBluetooth = _audioRouteInfo.inputIsBluetoothHeadset;
    final needsFallback =
        fallback != null &&
        (selectedIsBluetooth ||
            currentIsBluetooth ||
            routeIsBluetooth ||
            selectedName.isEmpty);

    if (fallback == null) {
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      if (notify) {
        _showBluetoothInputBlockedNotice();
      }
      debugPrint('No non-Bluetooth native input device available: $reason');
      return false;
    }

    if (!needsFallback) return true;

    final ok = await JuceAudioEngine.selectInputDevice(fallback);
    if (!ok) {
      if (notify) {
        _showBluetoothInputBlockedNotice();
      }
      debugPrint('Failed to select non-Bluetooth native input: $fallback');
      return false;
    }

    final channels = await JuceAudioEngine.getNumInputChannels();
    if (!mounted) return false;
    _setStateAndRefreshProjectSettings(() {
      _selectedDevice = fallback;
      _numInputChannels = channels;
      _normalizeInputChannelSelection();
      if (_isValidRowIndex(_selectedRow)) {
        _rows[_selectedRow] = _rows[_selectedRow].copyWith(
          inputDeviceName: fallback,
          inputChannelStart: _selectedChannelStart,
          inputChannelCount: _selectedChannelCount,
        );
      }
    });
    _lastPreparedRecordingDevice = null;
    _lastPreparedRecordingInputOpenChannels = null;
    await _refreshAudioRouteInfo();
    if (notify) {
      _showBluetoothInputBlockedNotice();
    }
    return true;
  }

  bool _shouldEnableLiveInputMonitoring(AudioRouteInfo info) {
    if (info.isBluetoothOutput && !_advancedBluetoothMonitorOverride) {
      return false;
    }
    return true;
  }

  Future<void> _applyCurrentLiveMonitoringPolicy({
    AudioRouteInfo? info,
    bool force = false,
  }) async {
    if (_isBluetoothV2Session) return;
    if (!_supportsNativeBluetoothMonitorPolicy()) return;
    final routeInfo = info ?? _audioRouteInfo;
    final shouldEnable = _shouldEnableLiveInputMonitoring(routeInfo);
    if (!force && _liveInputMonitoringEffective == shouldEnable) {
      return;
    }
    _liveInputMonitoringEffective = shouldEnable;
    await JuceAudioEngine.setLiveInputMonitoringEnabled(shouldEnable);
  }

  Future<void> _refreshAudioRouteInfo({bool refreshNativeRoute = false}) async {
    if (_isBluetoothV2Session) return;
    if (!_supportsNativeBluetoothMonitorPolicy()) return;
    if (refreshNativeRoute) {
      await _requestAndroidRouteRefresh(reason: 'editorRouteInfo');
    }
    final info = await JuceAudioEngine.getAudioRouteInfo();
    if (!mounted) return;

    final routeLabel = info.outputRouteName.trim();
    final changed =
        !_sameAudioRouteInfo(_audioRouteInfo, info) ||
        _androidOutputRouteName != (routeLabel.isEmpty ? null : routeLabel);
    _lastAudioRouteInfoRefreshElapsed = _transportUiStopwatch.elapsed;
    if (changed) {
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      _setStateAndRefreshProjectSettings(() {
        _audioRouteInfo = info;
        if (Platform.isAndroid) {
          _androidOutputRouteName = routeLabel.isEmpty ? null : routeLabel;
        }
      });
    } else {
      _audioRouteInfo = info;
    }

    if (_isRecording && !_isMidiClipRecording) {
      await _applyCurrentLiveMonitoringPolicy(info: info);
    } else if (changed) {
      _scheduleRecordingInputPrewarm(reason: 'routeChanged');
    }
  }

  Future<void> _refreshSystemSelectedRouteInfoV2() async {
    if (!_isBluetoothV2Session || (!Platform.isAndroid && !Platform.isIOS)) {
      return;
    }
    final snapshot = await JuceAudioEngine.getAudioRouteSnapshotV2();
    if (!mounted) return;

    final output = snapshot.outputs.length == 1
        ? snapshot.outputs.single
        : null;
    final input = snapshot.inputs.length == 1 ? snapshot.inputs.single : null;
    final outputName = (output?.name ?? '').trim();
    final inputName = (input?.name ?? '').trim();
    final outputKind = switch (output?.normalizedKind) {
      AudioRouteKindV2.builtIn => AudioRouteKind.speaker,
      AudioRouteKindV2.wired => AudioRouteKind.wired,
      AudioRouteKindV2.external => AudioRouteKind.usb,
      AudioRouteKindV2.bluetooth ||
      AudioRouteKindV2.bluetoothMedia ||
      AudioRouteKindV2.bluetoothDuplex ||
      AudioRouteKindV2.bluetoothLe => AudioRouteKind.bluetoothOutput,
      _ => AudioRouteKind.unknown,
    };
    final inputIsBluetooth = switch (input?.normalizedKind) {
      AudioRouteKindV2.bluetooth ||
      AudioRouteKindV2.bluetoothDuplex ||
      AudioRouteKindV2.bluetoothLe => true,
      _ => false,
    };
    final info = AudioRouteInfo(
      outputRouteKind: outputKind,
      outputRouteName: outputName,
      inputDeviceName: inputName,
      inputIsBluetoothHeadset: inputIsBluetooth,
    );
    _setStateAndRefreshProjectSettings(() {
      _audioRouteInfo = info;
      if (Platform.isAndroid) {
        _androidOutputRouteName = outputName.isEmpty ? null : outputName;
      }
    });
  }

  Future<void> _refreshAndroidOutputRouteLabel({
    bool refreshNativeRoute = false,
  }) async {
    if (_isBluetoothV2Session) {
      await _refreshSystemSelectedRouteInfoV2();
      return;
    }
    await _refreshAudioRouteInfo(refreshNativeRoute: refreshNativeRoute);
  }

  Future<bool> _confirmBluetoothMicMode(AudioRouteInfo info) async {
    final fallbackDevice = _recommendedNonBluetoothInputDevice();
    final selectedDeviceName = (_selectedDevice ?? '').trim();
    final selectedInputLooksBluetooth =
        selectedDeviceName.isNotEmpty &&
        _looksLikeBluetoothDeviceName(selectedDeviceName);

    final shouldAutoFallbackToNonBluetoothInput =
        info.isBluetoothOutput &&
        (info.inputIsBluetoothHeadset ||
            selectedInputLooksBluetooth ||
            selectedDeviceName.isEmpty);

    if (Platform.isAndroid &&
        shouldAutoFallbackToNonBluetoothInput &&
        fallbackDevice != null) {
      final ok = await JuceAudioEngine.selectInputDevice(fallbackDevice);
      if (!ok) return false;
      final channels = await JuceAudioEngine.getNumInputChannels();
      if (!mounted) return false;
      _setStateAndRefreshProjectSettings(() {
        _selectedDevice = fallbackDevice;
        _numInputChannels = channels;
        _normalizeInputChannelSelection();
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      await _refreshAudioRouteInfo();
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Using built-in/default mic while Bluetooth output is active.',
          ),
        ),
      );
      return true;
    }

    if (Platform.isIOS && shouldAutoFallbackToNonBluetoothInput) {
      final ok = await JuceAudioEngine.preferNonBluetoothRecordingInput();
      if (!ok) return false;
      final channels = await JuceAudioEngine.getNumInputChannels();
      if (!mounted) return false;
      _setStateAndRefreshProjectSettings(() {
        _numInputChannels = channels;
        _normalizeInputChannelSelection();
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      await _refreshAudioRouteInfo();
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Using built-in/default mic while Bluetooth output is active.',
          ),
        ),
      );
      return true;
    }

    if (!info.inputIsBluetoothHeadset || _isBluetoothMicOptedIn(info)) {
      return true;
    }

    final decision = await showDialog<String>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          backgroundColor: const Color(0xFF181B24),
          title: Text(
            L10n.translate(dialogContext, 'Bluetooth headset mic'),
            style: const TextStyle(color: Colors.white),
          ),
          content: Text(
            fallbackDevice == null
                ? L10n.translate(
                    dialogContext,
                    'Bluetooth headset mic can reduce audio quality and increase latency. Continue with this mic?',
                  )
                : L10n.translate(
                    dialogContext,
                    'Bluetooth headset mic can reduce audio quality and increase latency. Use your built-in/default mic instead, or continue with this mic?',
                  ),
            style: const TextStyle(color: Colors.white70),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop('cancel'),
              child: Text(L10n.translate(dialogContext, 'Cancel')),
            ),
            if (fallbackDevice != null)
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop('fallback'),
                child: Text(L10n.translate(dialogContext, 'Use default mic')),
              ),
            FilledButton(
              onPressed: () => Navigator.of(dialogContext).pop('continue'),
              child: Text(L10n.translate(dialogContext, 'Continue')),
            ),
          ],
        );
      },
    );

    if (!mounted || decision == null || decision == 'cancel') {
      return false;
    }

    if (decision == 'fallback') {
      final fallbackDeviceName = fallbackDevice;
      if (fallbackDeviceName == null) return false;
      final ok = Platform.isIOS
          ? await JuceAudioEngine.preferNonBluetoothRecordingInput()
          : await JuceAudioEngine.selectInputDevice(fallbackDeviceName);
      if (!ok) return false;
      final channels = await JuceAudioEngine.getNumInputChannels();
      if (!mounted) return false;
      _setStateAndRefreshProjectSettings(() {
        if (!Platform.isIOS) {
          _selectedDevice = fallbackDeviceName;
        }
        _numInputChannels = channels;
        _normalizeInputChannelSelection();
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      await _refreshAudioRouteInfo();
      return !_audioRouteInfo.inputIsBluetoothHeadset ||
          _isBluetoothMicOptedIn();
    }

    _allowedBluetoothMicKeys.add(_bluetoothMicOptInKey(info));
    await _persistBluetoothMicOptInKeys();
    return true;
  }

  void _startRecordingRoutePolicyPolling() {
    _recordingRoutePolicyTimer?.cancel();
    if (_isBluetoothV2Session) return;
    if (!_supportsNativeBluetoothMonitorPolicy()) return;
    _recordingRoutePolicyTimer = Timer.periodic(const Duration(seconds: 1), (
      _,
    ) {
      if (!_isRecording || _isMidiClipRecording) {
        _recordingRoutePolicyTimer?.cancel();
        _recordingRoutePolicyTimer = null;
        return;
      }
      unawaited(_refreshAudioRouteInfo());
    });
  }

  void _stopRecordingRoutePolicyPolling() {
    _recordingRoutePolicyTimer?.cancel();
    _recordingRoutePolicyTimer = null;
  }

  int _normalizeDawSampleRate(Object? value) {
    final raw = value is num ? value.toInt() : null;
    if (raw != null && _dawSampleRateOptions.contains(raw)) return raw;
    return 44100;
  }

  int _normalizeDawBufferSize(Object? value) {
    final raw = value is num ? value.toInt() : null;
    if (raw != null && _dawBufferSizeOptions.contains(raw)) return raw;
    return 512;
  }

  int _normalizeMidiInputChannelFilter(Object? value) {
    final raw = value is num ? value.toInt() : 0;
    return raw.clamp(0, 16).toInt();
  }

  bool get _supportsDawAudioEngineDeviceSettings =>
      Platform.isMacOS || Platform.isIOS;

  Future<bool> _applyAudioEngineSettingsToNative({
    required String reason,
    bool notifyOnFailure = true,
  }) async {
    if (_audioEngineSettingsApplying) return false;

    _setStateAndRefreshProjectSettings(() {
      _audioEngineSettingsApplying = true;
    });

    try {
      await JuceAudioEngine.setMidiInputChannelFilter(_midiInputChannelFilter);

      if (_isBluetoothV2Session) {
        if (!Platform.isMacOS && !Platform.isIOS) {
          return true;
        }
        final coordinator = _audioRouteCoordinatorV2;
        if (coordinator == null) {
          // iOS deliberately starts its route coordinator after project load.
          // Retain the loaded project preference and apply it once that
          // existing startup boundary is ready.
          _v2HardwareSettingsApplicationPending = true;
          return true;
        }
        final result = await coordinator.configurePlaybackHardware(
          preferredSampleRateHz: _preferredDawSampleRate,
          preferredBufferFrames: _preferredDawBufferSize,
        );
        if (!result.succeeded) {
          if (notifyOnFailure && mounted) {
            _showSmallNotice(
              L10n.translate(context, 'Could not apply audio device settings'),
            );
          }
          return false;
        }

        JuceAudioEngine.acceptVerifiedAudioRouteTransitionV2(result);
        final outputKind = result.snapshot.outputs.length == 1
            ? result.snapshot.outputs.first.normalizedKind
            : AudioRouteKindV2.unknown;
        final bluetoothRoute =
            outputKind == AudioRouteKindV2.bluetooth ||
            outputKind == AudioRouteKindV2.bluetoothMedia ||
            outputKind == AudioRouteKindV2.bluetoothDuplex ||
            outputKind == AudioRouteKindV2.bluetoothLe;
        if (!bluetoothRoute) {
          final actualSampleRate =
              result.snapshot.juce.sampleRateHz?.round() ?? 0;
          final actualBufferSize = result.snapshot.juce.bufferFrames ?? 0;
          if ((_dawSampleRateOptions.contains(actualSampleRate) &&
                  actualSampleRate != _preferredDawSampleRate) ||
              (_dawBufferSizeOptions.contains(actualBufferSize) &&
                  actualBufferSize != _preferredDawBufferSize)) {
            _setStateAndRefreshProjectSettings(() {
              if (_dawSampleRateOptions.contains(actualSampleRate)) {
                _preferredDawSampleRate = actualSampleRate;
              }
              if (_dawBufferSizeOptions.contains(actualBufferSize)) {
                _preferredDawBufferSize = actualBufferSize;
              }
            });
          }
        }
        return true;
      }

      if (_isRecording) {
        if (notifyOnFailure && mounted) {
          _showSmallNotice(
            L10n.translate(
              context,
              'Stop recording before changing audio device settings',
            ),
          );
        }
        return false;
      }

      final applied = await JuceAudioEngine.configureAudioDevice(
        sampleRate: _preferredDawSampleRate,
        bufferSize: _preferredDawBufferSize,
        desiredInputChannels: _desiredRecordingInputOpenChannels(),
        reason: reason,
      );

      if (applied) {
        final diagnostics = await JuceAudioEngine.getEngineDiagnostics();
        final actualSampleRate = diagnostics.sampleRate.round();
        final actualBufferSize = diagnostics.bufferSize;
        if ((_dawSampleRateOptions.contains(actualSampleRate) &&
                actualSampleRate != _preferredDawSampleRate) ||
            (_dawBufferSizeOptions.contains(actualBufferSize) &&
                actualBufferSize != _preferredDawBufferSize)) {
          _setStateAndRefreshProjectSettings(() {
            if (_dawSampleRateOptions.contains(actualSampleRate)) {
              _preferredDawSampleRate = actualSampleRate;
            }
            if (_dawBufferSizeOptions.contains(actualBufferSize)) {
              _preferredDawBufferSize = actualBufferSize;
            }
          });
        }
        _lastPreparedRecordingDevice = null;
        _lastPreparedRecordingInputOpenChannels = null;
        _scheduleRecordingInputPrewarm(reason: '$reason-prewarm');
        unawaited(_refreshAudioRouteInfo());
        return true;
      }

      if (notifyOnFailure && mounted) {
        _showSmallNotice(
          L10n.translate(context, 'Could not apply audio device settings'),
        );
      }
      return false;
    } finally {
      if (mounted) {
        _setStateAndRefreshProjectSettings(() {
          _audioEngineSettingsApplying = false;
        });
      } else {
        _audioEngineSettingsApplying = false;
      }
    }
  }

  Future<bool> _prepareRecordingInputs({
    required int desiredInputChannels,
    required String selectedDevice,
    required String reason,
    bool rescheduleOnConfigChange = false,
  }) {
    if (_isBluetoothV2Session) return Future<bool>.value(false);
    _recordingInputPrewarmInFlight = true;

    late final Future<bool> future;
    future = (() async {
      var preparedForRequestedConfig = false;
      try {
        final prepared = await JuceAudioEngine.prepareRecordingInputs(
          desiredInputChannels,
          reason: reason,
        );
        if (!mounted || !prepared) return false;
        _lastPreparedRecordingDevice = selectedDevice;
        _lastPreparedRecordingInputOpenChannels = desiredInputChannels;
        preparedForRequestedConfig = true;
        return true;
      } finally {
        _recordingInputPrewarmInFlight = false;
        if (identical(_recordingInputPrewarmFuture, future)) {
          _recordingInputPrewarmFuture = null;
        }
        if (preparedForRequestedConfig && mounted) {
          final channels = await JuceAudioEngine.getNumInputChannels();
          if (channels > 0 && mounted) {
            _setStateAndRefreshProjectSettings(() {
              _numInputChannels = channels;
              _normalizeInputChannelSelection();
            });
          }
        }
        // Only chain another prewarm when the current prewarm succeeded.
        // This prevents infinite retry loops on persistent native-route errors.
        if (rescheduleOnConfigChange && mounted && preparedForRequestedConfig) {
          final currentDevice = (_selectedDevice ?? '').trim();
          final currentDesiredInputChannels =
              _desiredRecordingInputOpenChannels();
          if (currentDesiredInputChannels <= 0) {
            _lastPreparedRecordingDevice = null;
            _lastPreparedRecordingInputOpenChannels = null;
          } else if (!_recordingInputsPreparedFor(
            selectedDevice: currentDevice,
            desiredInputChannels: currentDesiredInputChannels,
          )) {
            _scheduleRecordingInputPrewarm(reason: 'configChanged');
          }
        }
      }
    })();

    _recordingInputPrewarmFuture = future;
    return future;
  }

  void _scheduleRecordingInputPrewarm({required String reason}) {
    if (_isBluetoothV2Session) return;
    if (!mounted || _isRecording) return;
    final desiredInputChannels = _desiredRecordingInputOpenChannels();
    final selectedDevice = (_selectedDevice ?? '').trim();

    if (Platform.isMacOS) {
      if (_inputDeviceInfos.isNotEmpty &&
          (selectedDevice.isEmpty ||
              _looksLikeBluetoothDeviceName(selectedDevice))) {
        _lastPreparedRecordingDevice = null;
        _lastPreparedRecordingInputOpenChannels = null;
        unawaited(_ensureMacNonBluetoothRecordingInput(reason: reason));
        return;
      }
      final fallback = _audioInputDevicePolicy.safeFallbackName(
        devices: _inputDeviceInfos,
        selectedName: selectedDevice,
        currentName: _audioRouteInfo.inputDeviceName,
      );
      if (_inputDeviceInfos.isNotEmpty && fallback == null) {
        _lastPreparedRecordingDevice = null;
        _lastPreparedRecordingInputOpenChannels = null;
        return;
      }
    }

    if (Platform.isAndroid) {
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      _recordingInputPrewarmFuture = null;
      return;
    }

    // Avoid audible route churn while playback is already active on iOS.
    if (Platform.isIOS && _isPlaying) {
      return;
    }

    if (desiredInputChannels <= 0) {
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      return;
    }
    if (selectedDevice.isEmpty && _inputDevices.isEmpty) {
      return;
    }
    if (_recordingInputPrewarmInFlight) {
      return;
    }
    if (_recordingInputsPreparedFor(
      selectedDevice: selectedDevice,
      desiredInputChannels: desiredInputChannels,
    )) {
      return;
    }

    unawaited(
      _prepareRecordingInputs(
        desiredInputChannels: desiredInputChannels,
        selectedDevice: selectedDevice,
        reason: reason,
        rescheduleOnConfigChange: true,
      ),
    );
  }

  Future<void> _loadInputDevicesFromJuce({
    bool scheduleRecordingPrewarm = false,
  }) async {
    if (_isBluetoothV2Session) {
      if (Platform.isMacOS) await _loadMacV2AudioDevices();
      return;
    }
    if (_loadingDevices) return;
    _setStateAndRefreshProjectSettings(() => _loadingDevices = true);

    try {
      final micStatus = await _getMicrophonePermissionStatus();
      final micBlocked = !(micStatus.isGranted || micStatus.isLimited);

      final devices = await JuceAudioEngine.getInputDevices();
      final deviceInfos = Platform.isMacOS
          ? await JuceAudioEngine.getInputDeviceInfos()
          : const <AudioInputDeviceInfo>[];
      final outputDevices = Platform.isMacOS
          ? await JuceAudioEngine.getOutputDevices()
          : const <String>[];
      final current = await JuceAudioEngine.getCurrentDeviceName();
      final currentOutput = await JuceAudioEngine.getCurrentOutputDeviceName();
      var channels = await JuceAudioEngine.getNumInputChannels();
      final resolvedDevices = devices.isNotEmpty
          ? devices
          : (Platform.isMacOS
                ? deviceInfos.map((info) => info.name).toList(growable: false)
                : const <String>[]);
      var selectedDeviceName = resolvedDevices.contains(current)
          ? current
          : (resolvedDevices.isNotEmpty ? resolvedDevices.first : null);
      var noSafeNativeInput = false;

      if (Platform.isMacOS && deviceInfos.isNotEmpty) {
        final fallback = _audioInputDevicePolicy.safeFallbackName(
          devices: deviceInfos,
          selectedName: selectedDeviceName,
          currentName: current,
        );
        final selectedIsBluetooth =
            selectedDeviceName != null &&
            _audioInputDevicePolicy
                    .findByName(deviceInfos, selectedDeviceName)
                    ?.isBluetoothInput ==
                true;
        final currentIsBluetooth =
            _audioInputDevicePolicy
                .findByName(deviceInfos, current)
                ?.isBluetoothInput ==
            true;
        if (fallback != null &&
            (selectedDeviceName == null ||
                selectedIsBluetooth ||
                currentIsBluetooth)) {
          final selected = await JuceAudioEngine.selectInputDevice(fallback);
          if (selected) {
            selectedDeviceName = fallback;
            channels = await JuceAudioEngine.getNumInputChannels();
          }
        } else if (fallback == null) {
          noSafeNativeInput = true;
          selectedDeviceName = resolvedDevices.isNotEmpty
              ? resolvedDevices.first
              : null;
          channels = 0;
        }
      }
      _lastInputDevicesLoadedElapsed = _transportUiStopwatch.elapsed;
      _setStateAndRefreshProjectSettings(() {
        final resolvedChannels = channels > 0
            ? channels
            : (noSafeNativeInput
                  ? 0
                  : (resolvedDevices.isNotEmpty ? _numInputChannels : 0));
        final currentOutputDeviceName = currentOutput.trim().isNotEmpty
            ? currentOutput.trim()
            : (outputDevices.isNotEmpty ? outputDevices.first : '');
        _microphonePermissionStatus = micStatus;
        _microphoneAccessBlocked = micBlocked;
        _inputDeviceInfos = deviceInfos;
        _inputDevices = resolvedDevices;
        _selectedDevice = selectedDeviceName;
        _macOutputDevices = outputDevices;
        _macOutputDeviceName = currentOutputDeviceName.isEmpty
            ? null
            : currentOutputDeviceName;
        _numInputChannels = resolvedChannels;
        _normalizeInputChannelSelection();
        _loadingDevices = false;
      });
      unawaited(_refreshAudioRouteInfo());
      if (scheduleRecordingPrewarm) {
        _scheduleRecordingInputPrewarm(reason: 'loadInputDevices');
      }
    } catch (_) {
      final micStatus = await _getMicrophonePermissionStatus();
      _setStateAndRefreshProjectSettings(() {
        _microphonePermissionStatus = micStatus;
        _microphoneAccessBlocked =
            !(micStatus.isGranted || micStatus.isLimited);
        _inputDevices = const <String>[];
        _inputDeviceInfos = const <AudioInputDeviceInfo>[];
        _macOutputDevices = const <String>[];
        _selectedDevice = null;
        _numInputChannels = 0;
        _normalizeInputChannelSelection();
        _loadingDevices = false;
        _androidOutputRouteName = null;
        _macOutputDeviceName = null;
      });
      _lastPreparedRecordingDevice = null;
      _lastPreparedRecordingInputOpenChannels = null;
      _lastInputDevicesLoadedElapsed = Duration.zero;
      _lastAudioRouteInfoRefreshElapsed = Duration.zero;
      _audioRouteInfo = AudioRouteInfo.unknown;
      if (Platform.isAndroid) {
        unawaited(
          JuceAudioEngine.prepareRecordingInputs(
            0,
            reason: 'loadInputDevices:error',
          ),
        );
      }
    }
  }

  bool get _macV2OutputSelectionEnabled {
    if (!Platform.isMacOS || !_isBluetoothV2Session) return true;
    final coordinator = _audioRouteCoordinatorV2;
    return !_loadingDevices &&
        !_macV2InputSelectionInFlight &&
        !_v2AudioSessionInvalidated &&
        !_isRecording &&
        !_recordStartVisualPending &&
        coordinator != null &&
        coordinator.intent == AudioRouteIntentV2.playbackOnly &&
        coordinator.state == AudioRouteCoordinatorStateV2.stable;
  }

  bool get _macV2InputSelectionEnabled {
    if (!Platform.isMacOS || !_isBluetoothV2Session) return false;
    final coordinator = _audioRouteCoordinatorV2;
    return !_loadingDevices &&
        !_macV2InputSelectionInFlight &&
        !_v2AudioSessionInvalidated &&
        !_isRecording &&
        !_recordStartVisualPending &&
        coordinator != null &&
        coordinator.intent == AudioRouteIntentV2.playbackOnly &&
        coordinator.state == AudioRouteCoordinatorStateV2.stable;
  }

  Future<void> _loadMacV2AudioDevices() async {
    if (!Platform.isMacOS || !_isBluetoothV2Session || _loadingDevices) return;
    _setStateAndRefreshProjectSettings(() => _loadingDevices = true);
    try {
      final inputDevices = <String>[];
      for (final info in await JuceAudioEngine.getInputDeviceInfos()) {
        final name = info.name.trim();
        if (name.isNotEmpty && !inputDevices.contains(name)) {
          inputDevices.add(name);
        }
      }
      final outputDevices = <String>[];
      for (final rawName in await JuceAudioEngine.getOutputDevices()) {
        final name = rawName.trim();
        if (name.isNotEmpty && !outputDevices.contains(name)) {
          outputDevices.add(name);
        }
      }
      final currentOutput = (await JuceAudioEngine.getCurrentOutputDeviceName())
          .trim();
      if (!mounted) return;
      _setStateAndRefreshProjectSettings(() {
        _macInputDevices = inputDevices;
        if (_macInputDeviceName != null &&
            !inputDevices.contains(_macInputDeviceName)) {
          _macInputDeviceName = null;
        }
        _macOutputDevices = outputDevices;
        _macOutputDeviceName = currentOutput.isEmpty
            ? _macOutputDeviceName
            : currentOutput;
        _loadingDevices = false;
      });
    } catch (_) {
      if (!mounted) return;
      _setStateAndRefreshProjectSettings(() => _loadingDevices = false);
    }
  }

  Widget _buildMicrophonePermissionNotice() {
    final actionLabel =
        _microphonePermissionStatus.isPermanentlyDenied ||
            _microphonePermissionStatus.isRestricted
        ? L10n.translate(context, 'Open settings')
        : L10n.translate(context, 'Allow access');
    final helperText =
        _microphonePermissionStatus.isPermanentlyDenied ||
            _microphonePermissionStatus.isRestricted
        ? L10n.translate(
            context,
            'Built-in microphone recording needs access in Settings. External audio interfaces can still be used below when available.',
          )
        : L10n.translate(
            context,
            'Built-in microphone recording needs access. External audio interfaces can still be used below when available.',
          );

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.08),
        border: Border.all(color: Colors.white.withValues(alpha: 0.14)),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            L10n.translate(context, 'Microphone access is turned off'),
            style: const TextStyle(
              color: Colors.white,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 6),
          Text(helperText, style: const TextStyle(color: Colors.white70)),
          const SizedBox(height: 10),
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton(
              onPressed:
                  _microphonePermissionStatus.isPermanentlyDenied ||
                      _microphonePermissionStatus.isRestricted
                  ? _openAppPermissionsSettings
                  : _requestMicrophoneAccessFromSettingsPanel,
              child: Text(actionLabel),
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _loadAudioDevices() async {
    final devices = await navigator.mediaDevices.enumerateDevices();

    final inputs = devices.where((d) => d.kind == 'audioinput').toList();
    final outputs = devices.where((d) => d.kind == 'audiooutput').toList();

    MediaDeviceInfo? newSelectedInput;
    MediaDeviceInfo? newSelectedOutput;

    // --- Preserve input selection if possible ---
    if (_selectedInput != null) {
      try {
        newSelectedInput = inputs.firstWhere(
          (d) => d.deviceId == _selectedInput!.deviceId,
        );
      } catch (_) {
        newSelectedInput = inputs.isNotEmpty ? inputs.first : null;
      }
    } else {
      newSelectedInput = inputs.isNotEmpty ? inputs.first : null;
    }

    // --- Preserve output selection if possible ---
    if (_selectedOutput != null) {
      try {
        newSelectedOutput = outputs.firstWhere(
          (d) => d.deviceId == _selectedOutput!.deviceId,
        );
      } catch (_) {
        newSelectedOutput = outputs.isNotEmpty ? outputs.first : null;
      }
    } else {
      newSelectedOutput = outputs.isNotEmpty ? outputs.first : null;
    }

    setState(() {
      _inputs = inputs;
      _outputs = outputs;
      _selectedInput = newSelectedInput;
      _selectedOutput = newSelectedOutput;
      _loadingDevices = false;
    });

    navigator.mediaDevices.ondevicechange = (event) {
      _loadAudioDevices(); // refresh device list
      // ScaffoldMessenger.of(context).showSnackBar(
      //   SnackBar(content: Text("Audio devices updated")),
      // );
    };
  }

  Widget _buildInputSelector() {
    if (_isBluetoothV2Session && (Platform.isAndroid || Platform.isIOS)) {
      final routeLabel = _audioRouteInfo.inputDeviceName.trim();
      final effectiveLabel = routeLabel.isEmpty
          ? L10n.translate(context, 'System Default')
          : routeLabel;
      return Semantics(
        identifier: 'daw.input_device',
        label: L10n.translate(context, 'Input Device'),
        child: InputDecorator(
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'Input Device'),
            suffixIcon: IconButton(
              tooltip: L10n.translate(context, 'Refresh audio devices'),
              icon: const Icon(Icons.refresh, color: Colors.white70),
              onPressed: () {
                unawaited(_refreshSystemSelectedRouteInfoV2());
              },
            ),
          ),
          child: Text(
            effectiveLabel,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(color: Colors.white),
          ),
        ),
      );
    }
    if (_isBluetoothV2Session && Platform.isMacOS) {
      const systemDefaultValue = '';
      final selectionEnabled = _macV2InputSelectionEnabled;
      final selectedName = _macInputDeviceName?.trim();
      final selectedValue =
          selectedName != null &&
              selectedName.isNotEmpty &&
              _macInputDevices.contains(selectedName)
          ? selectedName
          : systemDefaultValue;
      final values = <String>[systemDefaultValue, ..._macInputDevices];
      return Semantics(
        identifier: 'daw.input_device',
        label: L10n.translate(context, 'Input Device'),
        child: DropdownButtonFormField<String>(
          key: ValueKey<String>('mac-v2-input-$selectedValue'),
          initialValue: selectedValue,
          isExpanded: true,
          dropdownColor: kMixroomGlassDropdownMenuColor,
          style: const TextStyle(color: Colors.white),
          selectedItemBuilder: (context) => values
              .map(
                (value) => Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    value.isEmpty
                        ? L10n.translate(context, 'System Default')
                        : value,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(color: Colors.white),
                  ),
                ),
              )
              .toList(growable: false),
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'Input Device'),
            suffixIcon: IconButton(
              tooltip: L10n.translate(context, 'Refresh audio devices'),
              icon: const Icon(Icons.refresh, color: Colors.white70),
              onPressed: selectionEnabled
                  ? () => unawaited(_loadMacV2AudioDevices())
                  : null,
            ),
          ),
          items: values
              .map(
                (value) => DropdownMenuItem<String>(
                  value: value,
                  child: Text(
                    value.isEmpty
                        ? L10n.translate(context, 'System Default')
                        : value,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(color: Colors.white),
                  ),
                ),
              )
              .toList(growable: false),
          onChanged: selectionEnabled
              ? (value) => unawaited(
                  _selectMacV2InputDevice(
                    value == null || value.isEmpty ? null : value,
                  ),
                )
              : null,
        ),
      );
    }
    if (_loadingDevices) {
      return const Padding(
        padding: EdgeInsets.all(8),
        child: Center(child: CircularProgressIndicator(color: Colors.white)),
      );
    }

    if (_inputDevices.isEmpty) {
      if (!_microphoneAccessBlocked) {
        return Text(
          L10n.translate(context, 'No input devices available'),
          style: const TextStyle(color: Colors.white54),
        );
      }
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _buildMicrophonePermissionNotice(),
          const SizedBox(height: 12),
          Text(
            L10n.translate(context, 'No input devices available'),
            style: const TextStyle(color: Colors.white54),
          ),
        ],
      );
    }

    final selector = Semantics(
      identifier: 'daw.input_device',
      label: L10n.translate(context, 'Input Device'),
      child: DropdownButtonFormField<String>(
        key: ValueKey<String>(
          'input-device-${_selectedDevice ?? ''}-$_inputDeviceSelectorRevision',
        ),
        initialValue: _selectedDevice,
        isExpanded: true,
        dropdownColor: kMixroomGlassDropdownMenuColor,
        style: const TextStyle(color: Colors.white),
        selectedItemBuilder: (context) {
          return _inputDevices
              .map(
                (d) => Align(
                  alignment: Alignment.centerLeft,
                  child: Text(d, maxLines: 1, overflow: TextOverflow.ellipsis),
                ),
              )
              .toList(growable: false);
        },
        decoration: _projectSettingsFieldDecoration(
          labelText: L10n.translate(context, 'Input Device'),
          suffixIcon: IconButton(
            tooltip: L10n.translate(context, 'Refresh audio devices'),
            icon: const Icon(Icons.refresh, color: Colors.white70),
            onPressed: () async {
              _loadInputDevicesFromJuce(scheduleRecordingPrewarm: true);
              print("audio devices reloaded from JUCE");
            },
          ),
        ),
        items: _inputDevices
            .map(
              (d) => DropdownMenuItem(
                value: d,
                child: Text(d, maxLines: 1, overflow: TextOverflow.ellipsis),
              ),
            )
            .toList(),
        onChanged: (name) async {
          if (name == null) return;

          if (Platform.isMacOS && _looksLikeBluetoothDeviceName(name)) {
            _showBluetoothInputBlockedNotice();
            await _ensureMacNonBluetoothRecordingInput(
              reason: 'blockedBluetoothInputSelection',
              notify: false,
            );
            if (!mounted) return;
            _setStateAndRefreshProjectSettings(() {
              _inputDeviceSelectorRevision++;
            });
            return;
          }

          final ok = await JuceAudioEngine.selectInputDevice(name);
          if (!ok) return;

          final channels = await JuceAudioEngine.getNumInputChannels();

          _setStateAndRefreshProjectSettings(() {
            _selectedDevice = name;
            _numInputChannels = channels;
            _normalizeInputChannelSelection();
            if (_isValidRowIndex(_selectedRow)) {
              _rows[_selectedRow] = _rows[_selectedRow].copyWith(
                inputDeviceName: name,
                inputChannelStart: _selectedChannelStart,
                inputChannelCount: _selectedChannelCount,
              );
            }
          });
          if (_isValidRowIndex(_selectedRow)) {
            unawaited(
              JuceAudioEngine.setRowMonitorTarget(
                row: _selectedRow,
                inputDeviceName: name,
                channelStart: _selectedChannelStart,
                channelCount: _selectedChannelCount,
              ),
            );
          }
          _scheduleRecordingInputPrewarm(reason: 'selectInputDevice');
          unawaited(_refreshAndroidOutputRouteLabel());
        },
      ),
    );

    if (!_microphoneAccessBlocked) {
      return selector;
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _buildMicrophonePermissionNotice(),
        const SizedBox(height: 12),
        selector,
      ],
    );
  }

  Widget _buildInputChannelRouteSelector() {
    final options = _buildInputChannelRouteOptions(
      _effectiveInputChannelCountForSettings(),
    );
    if (options.isEmpty) return const SizedBox.shrink();

    final selected =
        _findSelectedInputChannelRouteOption(options) ?? options.first;

    return Semantics(
      identifier: 'daw.input_channel',
      label: L10n.translate(context, 'Input Channel'),
      child: DropdownButtonFormField<_InputChannelRouteOption>(
        key: ValueKey('input-channel:$_numInputChannels:${options.length}'),
        initialValue: selected,
        isExpanded: true,
        dropdownColor: kMixroomGlassDropdownMenuColor,
        style: const TextStyle(color: Colors.white),
        decoration: _projectSettingsFieldDecoration(
          labelText: L10n.translate(context, 'Input Channel'),
        ),
        items: options
            .map(
              (option) => DropdownMenuItem<_InputChannelRouteOption>(
                value: option,
                child: Text(
                  option.label,
                  style: const TextStyle(color: Colors.white),
                ),
              ),
            )
            .toList(),
        onChanged: _isRecording
            ? null
            : (option) {
                if (option == null) return;
                _setStateAndRefreshProjectSettings(() {
                  _selectedChannelStart = option.channelStart;
                  _selectedChannelCount = option.channelCount;
                  if (_isValidRowIndex(_selectedRow)) {
                    _rows[_selectedRow] = _rows[_selectedRow].copyWith(
                      inputDeviceName: _selectedDevice ?? '',
                      inputChannelStart: option.channelStart,
                      inputChannelCount: option.channelCount,
                    );
                  }
                });
                if (_isValidRowIndex(_selectedRow)) {
                  unawaited(
                    JuceAudioEngine.setRowMonitorTarget(
                      row: _selectedRow,
                      inputDeviceName: _selectedDevice ?? '',
                      channelStart: option.channelStart,
                      channelCount: option.channelCount,
                    ),
                  );
                }
                _scheduleRecordingInputPrewarm(reason: 'selectInputChannels');
              },
      ),
    );
  }

  Widget _buildDawAudioEngineSettingsControls() {
    if (!_supportsDawAudioEngineDeviceSettings) {
      return const SizedBox.shrink();
    }

    final deviceControlsDisabled = _isRecording || _audioEngineSettingsApplying;
    final midiChannelItems = <DropdownMenuItem<int>>[
      DropdownMenuItem<int>(
        value: 0,
        child: Text(
          L10n.translate(context, 'All channels'),
          style: const TextStyle(color: Colors.white),
        ),
      ),
      for (var channel = 1; channel <= 16; channel++)
        DropdownMenuItem<int>(
          value: channel,
          child: Text(
            '${L10n.translate(context, 'Channel')} $channel',
            style: const TextStyle(color: Colors.white),
          ),
        ),
    ];

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        DropdownButtonFormField<int>(
          key: ValueKey('daw-sample-rate:$_preferredDawSampleRate'),
          initialValue: _preferredDawSampleRate,
          isExpanded: true,
          dropdownColor: kMixroomGlassDropdownMenuColor,
          style: const TextStyle(color: Colors.white),
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'Sample Rate'),
          ),
          items: _dawSampleRateOptions
              .map(
                (sampleRate) => DropdownMenuItem<int>(
                  value: sampleRate,
                  child: Text(
                    sampleRate >= 1000
                        ? '${(sampleRate / 1000).toStringAsFixed(sampleRate % 1000 == 0 ? 0 : 1)} kHz'
                        : '$sampleRate Hz',
                    style: const TextStyle(color: Colors.white),
                  ),
                ),
              )
              .toList(),
          onChanged: deviceControlsDisabled
              ? null
              : (sampleRate) async {
                  if (sampleRate == null ||
                      sampleRate == _preferredDawSampleRate) {
                    return;
                  }
                  final previous = _preferredDawSampleRate;
                  _setStateAndRefreshProjectSettings(() {
                    _preferredDawSampleRate = sampleRate;
                  });
                  final applied = await _applyAudioEngineSettingsToNative(
                    reason: 'sampleRateChanged',
                  );
                  if (applied) {
                    _scheduleProjectAutosave();
                  } else if (mounted) {
                    _setStateAndRefreshProjectSettings(() {
                      _preferredDawSampleRate = previous;
                    });
                  }
                },
        ),
        const SizedBox(height: 9),
        DropdownButtonFormField<int>(
          key: ValueKey('daw-buffer-size:$_preferredDawBufferSize'),
          initialValue: _preferredDawBufferSize,
          isExpanded: true,
          dropdownColor: kMixroomGlassDropdownMenuColor,
          style: const TextStyle(color: Colors.white),
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'Sample Buffer Size'),
          ),
          items: _dawBufferSizeOptions
              .map(
                (bufferSize) => DropdownMenuItem<int>(
                  value: bufferSize,
                  child: Text(
                    '$bufferSize ${L10n.translate(context, 'samples')}',
                    style: const TextStyle(color: Colors.white),
                  ),
                ),
              )
              .toList(),
          onChanged: deviceControlsDisabled
              ? null
              : (bufferSize) async {
                  if (bufferSize == null ||
                      bufferSize == _preferredDawBufferSize) {
                    return;
                  }
                  final previous = _preferredDawBufferSize;
                  _setStateAndRefreshProjectSettings(() {
                    _preferredDawBufferSize = bufferSize;
                  });
                  final applied = await _applyAudioEngineSettingsToNative(
                    reason: 'bufferSizeChanged',
                  );
                  if (applied) {
                    _scheduleProjectAutosave();
                  } else if (mounted) {
                    _setStateAndRefreshProjectSettings(() {
                      _preferredDawBufferSize = previous;
                    });
                  }
                },
        ),
        const SizedBox(height: 9),
        DropdownButtonFormField<int>(
          key: ValueKey('daw-midi-input-channel:$_midiInputChannelFilter'),
          initialValue: _midiInputChannelFilter,
          isExpanded: true,
          dropdownColor: kMixroomGlassDropdownMenuColor,
          style: const TextStyle(color: Colors.white),
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'MIDI Input Channel'),
          ),
          items: midiChannelItems,
          onChanged: _audioEngineSettingsApplying
              ? null
              : (channel) async {
                  if (channel == null || channel == _midiInputChannelFilter) {
                    return;
                  }
                  _setStateAndRefreshProjectSettings(() {
                    _midiInputChannelFilter = _normalizeMidiInputChannelFilter(
                      channel,
                    );
                  });
                  await JuceAudioEngine.setMidiInputChannelFilter(
                    _midiInputChannelFilter,
                  );
                  _scheduleProjectAutosave();
                },
        ),
      ],
    );
  }

  Widget _buildOutputSelector() {
    if (_loadingDevices) {
      return const Padding(
        padding: EdgeInsets.all(8),
        child: Center(child: CircularProgressIndicator(color: Colors.white)),
      );
    }

    if (Platform.isAndroid) {
      final routeLabel = _androidOutputRouteName?.trim();
      final effectiveLabel = (routeLabel == null || routeLabel.isEmpty)
          ? L10n.translate(
              context,
              'System default (speaker / Bluetooth / audio interface)',
            )
          : routeLabel;
      return Semantics(
        identifier: 'daw.output_route',
        label: L10n.translate(context, 'Output Route'),
        child: InputDecorator(
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'Output Route'),
            suffixIcon: IconButton(
              tooltip: L10n.translate(context, 'Refresh output route'),
              icon: const Icon(Icons.refresh, color: Colors.white70),
              onPressed: () {
                unawaited(_refreshAndroidOutputRouteLabel());
              },
            ),
          ),
          child: Text(
            effectiveLabel,
            style: const TextStyle(color: Colors.white),
          ),
        ),
      );
    }

    if (Platform.isIOS) {
      final routeLabel = _audioRouteInfo.outputRouteName.trim();
      final effectiveLabel = routeLabel.isEmpty
          ? L10n.translate(
              context,
              'System default (speaker / Bluetooth / audio interface)',
            )
          : routeLabel;
      return Semantics(
        identifier: 'daw.output_route',
        label: L10n.translate(context, 'Output Route'),
        child: InputDecorator(
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'Output Route'),
            suffixIcon: IconButton(
              tooltip: L10n.translate(context, 'Refresh output route'),
              icon: const Icon(Icons.refresh, color: Colors.white70),
              onPressed: () {
                unawaited(
                  _isBluetoothV2Session
                      ? _refreshSystemSelectedRouteInfoV2()
                      : _refreshAudioRouteInfo(),
                );
              },
            ),
          ),
          child: Text(
            effectiveLabel,
            style: const TextStyle(color: Colors.white),
          ),
        ),
      );
    }

    if (Platform.isMacOS) {
      final outputSelectionEnabled = _macV2OutputSelectionEnabled;
      final routeLabel = _macOutputDeviceName?.trim();
      final outputValue =
          routeLabel != null &&
              routeLabel.isNotEmpty &&
              _macOutputDevices.contains(routeLabel)
          ? routeLabel
          : null;
      if (_macOutputDevices.isEmpty) {
        final effectiveLabel = (routeLabel == null || routeLabel.isEmpty)
            ? L10n.translate(
                context,
                'System default (managed by macOS audio settings)',
              )
            : routeLabel;
        return InputDecorator(
          decoration: _projectSettingsFieldDecoration(
            labelText: L10n.translate(context, 'Output Device'),
            suffixIcon: IconButton(
              tooltip: L10n.translate(context, 'Refresh output device'),
              icon: const Icon(Icons.refresh, color: Colors.white70),
              onPressed: outputSelectionEnabled
                  ? () {
                      unawaited(() async {
                        await _loadInputDevicesFromJuce();
                        await _ensurePlaybackRouteReady(
                          reason: 'macOutputRefresh',
                        );
                      }());
                    }
                  : null,
            ),
          ),
          child: Text(
            effectiveLabel,
            style: const TextStyle(color: Colors.white),
          ),
        );
      }

      return DropdownButtonFormField<String>(
        initialValue: outputValue,
        isExpanded: true,
        dropdownColor: kMixroomGlassDropdownMenuColor,
        style: const TextStyle(color: Colors.white),
        decoration: _projectSettingsFieldDecoration(
          labelText: L10n.translate(context, 'Output Device'),
          suffixIcon: IconButton(
            tooltip: L10n.translate(context, 'Refresh output device'),
            icon: const Icon(Icons.refresh, color: Colors.white70),
            onPressed: outputSelectionEnabled
                ? () {
                    unawaited(() async {
                      await _loadInputDevicesFromJuce();
                      await _ensurePlaybackRouteReady(
                        reason: 'macOutputRefresh',
                      );
                    }());
                  }
                : null,
          ),
        ),
        hint: Text(
          routeLabel == null || routeLabel.isEmpty
              ? L10n.translate(
                  context,
                  'System default (managed by macOS audio settings)',
                )
              : routeLabel,
          style: const TextStyle(color: Colors.white70),
        ),
        items: _macOutputDevices
            .map((name) {
              return DropdownMenuItem<String>(
                value: name,
                child: Text(
                  name,
                  style: const TextStyle(color: Colors.white),
                  overflow: TextOverflow.ellipsis,
                ),
              );
            })
            .toList(growable: false),
        onChanged: outputSelectionEnabled
            ? (name) {
                if (name == null) return;
                unawaited(_selectMacOutputDevice(name));
              }
            : null,
      );
    }

    // Non-Android fallback path uses WebRTC device enumeration.
    if (_outputs.isEmpty) {
      return Text(
        L10n.translate(context, 'No selectable output devices'),
        style: const TextStyle(color: Colors.white54),
      );
    }

    return DropdownButtonFormField<MediaDeviceInfo>(
      dropdownColor: kMixroomGlassDropdownMenuColor,
      initialValue: _selectedOutput,
      isExpanded: true,
      style: const TextStyle(color: Colors.white),
      decoration: _projectSettingsFieldDecoration(
        labelText: L10n.translate(context, 'Output Device'),
      ),
      items: _outputs.map((d) {
        return DropdownMenuItem(
          value: d,
          child: Text(
            d.label.isNotEmpty ? d.label : d.deviceId,
            style: const TextStyle(color: Colors.white),
          ),
        );
      }).toList(),
      onChanged: (d) {
        if (d == null) return;
        _setStateAndRefreshProjectSettings(() => _selectedOutput = d);
        _selectOutputDevice(d);
      },
    );
  }

  String _currentOutputRouteLabel() {
    if (Platform.isAndroid) {
      final label = _androidOutputRouteName?.trim();
      return label == null || label.isEmpty
          ? L10n.translate(
              context,
              'System default (speaker / Bluetooth / audio interface)',
            )
          : label;
    }
    if (Platform.isIOS) {
      final label = _audioRouteInfo.outputRouteName.trim();
      return label.isEmpty
          ? L10n.translate(
              context,
              'System default (speaker / Bluetooth / audio interface)',
            )
          : label;
    }
    if (Platform.isMacOS) {
      final label = _macOutputDeviceName?.trim();
      return label == null || label.isEmpty
          ? L10n.translate(
              context,
              'System default (managed by macOS audio settings)',
            )
          : label;
    }
    final label = _selectedOutput?.label.trim();
    return label == null || label.isEmpty
        ? L10n.translate(context, 'System default')
        : label;
  }

  bool _isBleedRiskRoute() {
    final selectedInput = (_selectedDevice ?? '').trim();
    final input =
        (selectedInput.isNotEmpty
                ? selectedInput
                : _audioRouteInfo.inputDeviceName)
            .toLowerCase();
    final output = _currentOutputRouteLabel().toLowerCase();
    final builtInOrDefaultMic =
        input.contains('built') ||
        input.contains('microphone') ||
        input.contains('mic') ||
        input.contains('default') ||
        input.isEmpty;
    final isolatedOutput =
        output.contains('bluetooth') ||
        output.contains('headphone') ||
        output.contains('headset') ||
        output.contains('earphone') ||
        output.contains('airpods') ||
        output.contains('interface') ||
        output.contains('usb');
    return builtInOrDefaultMic && !isolatedOutput;
  }

  Widget _buildAudioRoutingStatusCard() {
    final selectedInput = (_selectedDevice ?? '').trim();
    final input = selectedInput.isEmpty
        ? (_audioRouteInfo.inputDeviceName.trim().isEmpty
              ? L10n.translate(context, 'System default input')
              : _audioRouteInfo.inputDeviceName.trim())
        : selectedInput;
    final output = _currentOutputRouteLabel();
    final bleedRisk = _isBleedRiskRoute();
    final selectedRowLabel = _isValidRowIndex(_selectedRow)
        ? '${_rowDisplayName(_selectedRow)} · ${_selectedChannelCount <= 1 ? 'Input ${_selectedChannelStart + 1}' : 'Inputs ${_selectedChannelStart + 1}-${_selectedChannelStart + _selectedChannelCount}'}'
        : L10n.translate(context, 'No selected row');

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.08),
        border: Border.all(
          color: (bleedRisk ? const Color(0xFFFFC266) : Colors.white)
              .withValues(alpha: bleedRisk ? 0.36 : 0.13),
        ),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _buildRoutingStatusLine(
            icon: Icons.mic_rounded,
            label: L10n.translate(context, 'Input'),
            value: input,
          ),
          const SizedBox(height: 8),
          _buildRoutingStatusLine(
            icon: Icons.volume_up_rounded,
            label: L10n.translate(context, 'Output'),
            value: output,
          ),
          const SizedBox(height: 8),
          _buildRoutingStatusLine(
            icon: Icons.radio_button_checked_rounded,
            label: L10n.translate(context, 'Record target'),
            value: selectedRowLabel,
          ),
          const SizedBox(height: 10),
          Row(
            children: [
              Icon(
                bleedRisk
                    ? Icons.warning_amber_rounded
                    : Icons.check_circle_rounded,
                size: 18,
                color: bleedRisk
                    ? const Color(0xFFFFC266)
                    : const Color(0xFF8FE0A2),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  bleedRisk
                      ? L10n.translate(
                          context,
                          'Bleed risk: speaker playback may be captured by the recording input.',
                        )
                      : L10n.translate(
                          context,
                          'Bleed risk is low for the current route.',
                        ),
                  style: TextStyle(
                    color: bleedRisk
                        ? const Color(0xFFFFD999)
                        : Colors.white.withValues(alpha: 0.72),
                    fontSize: 12.5,
                    height: 1.25,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildRoutingStatusLine({
    required IconData icon,
