  Widget _tempoTimePill({
    required int tempo,
    required String current,
    required String total,
  }) {
    return LayoutBuilder(
      builder: (context, c) {
        final double pillWidth = c.maxWidth;
        const double sidePad = 18;
        const double gap = 14;

        // --- Adaptive font scaling ---
        final double screenWidth = MediaQuery.of(context).size.width;
        double fontScale;
        if (screenWidth >= 1000) {
          fontScale = 1.3;
        } else if (screenWidth >= 700) {
          fontScale = 1.15;
        } else if (screenWidth >= 500) {
          fontScale = 1.0;
        } else {
          fontScale = 0.9;
        }

        TextStyle bigNum = TextStyle(
          fontSize: 22 * fontScale,
          fontWeight: FontWeight.w600,
          color: Colors.white,
          height: 1.0,
          fontFeatures: const [FontFeature.tabularFigures()],
        );

        TextStyle smallNum = TextStyle(
          fontSize: 12 * fontScale,
          color: Colors.white.withOpacity(0.65),
          height: 1.0,
          fontFeatures: const [FontFeature.tabularFigures()],
        );

        TextStyle smallLabel = TextStyle(
          fontSize: 12 * fontScale,
          letterSpacing: 0.6,
          color: Colors.white.withOpacity(0.75),
          height: 1.0,
          fontFeatures: const [FontFeature.tabularFigures()],
        );

        return _Glass(
          radius: 22,
          // 🔽 slightly reduce horizontal padding so inner content has more breathing room
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
          opacity: 0.10,
          child: ConstrainedBox(
