  Future<void> _onRecordPressed() async {
    await _handleRecordPressed(keepPlayingOnStop: false);
  }

  Future<void> _onCaptureDeckRecordPressed() async {
    await _handleRecordPressed(keepPlayingOnStop: true);
  }

  Future<void> _handleRecordPressed({required bool keepPlayingOnStop}) async {
    if (_isBluetoothV2Session) {
      if (!_supportsV2AudioRecording) {
        _showSmallNotice(
          'Recording is unavailable for the current audio route.',
        );
        return;
      }
      if (_v2AudioSessionInvalidated) {
        _showSmallNotice(_v2AudioSessionInvalidationNotice);
        return;
      }
    }
    if (_recordStartVisualPending && !_isRecording) {
      _recordStartCancelRequested = true;
      if (mounted) {
        setState(() {
          _recordStartVisualPending = false;
        });
      }
      if (_isBluetoothV2Session &&
          (Platform.isIOS || Platform.isAndroid || Platform.isMacOS) &&
          _audioRouteCoordinatorV2?.state ==
              AudioRouteCoordinatorStateV2.preparingInput) {
        await JuceAudioEngine.abortRecordingV2(cancelOnly: true);
      }
      return;
    }
    if (_isRecording) {
      await _stopRecordingJuce(keepPlaying: keepPlayingOnStop);
    } else {
      await _startRecordingJuce();
    }
  }

  String _normalizeEffectText(String raw) {
    return raw
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  String? pickMixroomEffect(String effectContains) {
    final needle = _normalizeEffectText(effectContains);
    if (needle.isEmpty) return null;

    // Alias-first matching for natural language phrases
    const aliasToEffect = <String, String>{
      'gain': 'Gain',
      'reverb': 'Reverb',
      'verb': 'Reverb',
      'plate': 'Reverb',
      'room': 'Reverb',
      'hall': 'Reverb',
      'delay': 'Delay',
      'echo': 'Delay',
      'slapback': 'Delay',
      'compressor': 'Compressor',
      'comp': 'Compressor',
      'dynamic softener': 'Dynamic Softener',
      'softener': 'Dynamic Softener',
      'soothe': 'Dynamic Softener',
      'resonance suppressor': 'Dynamic Softener',
      'resonance suppression': 'Dynamic Softener',
      'resonance': 'Dynamic Softener',
      'harshness': 'Dynamic Softener',
      'limiter': 'Limiter',
      'clipper': 'Clipper',
      'de esser': 'De-Esser',
      'deesser': 'De-Esser',
      'saturator': 'Distortion',
      'saturation': 'Distortion',
      'distortion': 'Distortion',
      'drive': 'Distortion',
      'degrade': 'Degrade',
      'autotune': 'Pitch Corrector',
      'auto tune': 'Pitch Corrector',
      'pitch correct': 'Pitch Corrector',
      'pitch correction': 'Pitch Corrector',
      'pitch corrector': 'Pitch Corrector',
      'melodyne': 'Pitch Corrector',
      'pitch': 'Pitch Shift',
      'chorus': 'Chorus',
      'vibrato': 'Vibrato',
      'parametric eq': 'EQ Parametric',
      'eq parametric': 'EQ Parametric',
      '3 band eq': 'EQ 3-Band',
      'eq 3 band': 'EQ 3-Band',
      'equalizer': 'EQ Parametric',
      'eq': 'EQ Parametric',
    };
    for (final entry in aliasToEffect.entries) {
      if (needle.contains(entry.key)) {
        return entry.value;
      }
    }

    for (final name in kMixroomBuiltInEffects) {
      final candidate = _normalizeEffectText(name);
      if (candidate == needle ||
          candidate.contains(needle) ||
          needle.contains(candidate)) {
        return name;
      }
    }

    // Last-resort token overlap (handles strings like "add reverb on track 1").
    final tokens = needle
        .split(' ')
        .where(
          (t) =>
              t.isNotEmpty &&
              t != 'plugin' &&
              t != 'effect' &&
              t != 'track' &&
              t != 'row' &&
              t != 'add' &&
              t != 'remove',
        )
        .toList(growable: false);
    if (tokens.isEmpty) return null;
    String? best;
    int bestScore = 0;
    for (final name in kMixroomBuiltInEffects) {
      final candidate = _normalizeEffectText(name);
      int score = 0;
      for (final token in tokens) {
        if (candidate.contains(token)) score++;
      }
      if (score > bestScore) {
        bestScore = score;
        best = name;
      }
    }
    if (bestScore > 0) {
      return best;
    }
    return null;
  }

  Future<EditorUndoAction?> _ensureDelayBeforeReverbOnRow(
    int row, {
    bool executeWithoutAdd = true,
  }) async {
    final actions = await _ensureAiCanonicalChainOrderOnRow(
      row,
      executeWithoutAdd: executeWithoutAdd,
    );
    return actions.isEmpty ? null : actions.first;
  }

  Future<EditorUndoAction?> _ensureDelayBeforeReverbOnMaster({
    bool executeWithoutAdd = true,
  }) async {
    final actions = await _ensureAiCanonicalChainOrderOnMaster(
      executeWithoutAdd: executeWithoutAdd,
    );
    return actions.isEmpty ? null : actions.first;
  }

  int _aiEffectChainRank(String effectName) {
    final name = effectName.trim().toLowerCase();
    if (name.contains('noise') ||
        name.contains('gate') ||
        name.contains('de-ess') ||
        name.contains('pitch correct') ||
        name.contains('pitch shift')) {
      return 0;
    }
    if (name.contains('eq') || name.contains('filter')) return 1;
    if (name.contains('compress') || name.contains('expander')) return 2;
    if (name.contains('satur') ||
        name.contains('distort') ||
        name.contains('drive') ||
        name.contains('degrade')) {
      return 3;
    }
    if (name.contains('chorus') ||
        name.contains('vibrato') ||
        name.contains('mod')) {
      return 4;
    }
    if (name.contains('delay') || name.contains('echo')) return 5;
    if (name.contains('reverb')) return 6;
    if (name.contains('limit') || name.contains('clipper')) return 7;
    return 3;
  }

  List<String> _canonicalAiEffectOrder(List<String> effects) {
    final indexed = <MapEntry<int, String>>[
      for (int i = 0; i < effects.length; i++) MapEntry(i, effects[i]),
    ];
    indexed.sort((a, b) {
      final rank = _aiEffectChainRank(
        a.value,
      ).compareTo(_aiEffectChainRank(b.value));
      if (rank != 0) return rank;
      return a.key.compareTo(b.key);
    });
    return indexed.map((entry) => entry.value).toList(growable: false);
  }

  Future<List<EditorUndoAction>> _ensureAiCanonicalChainOrderOnRow(
    int row, {
    bool executeWithoutAdd = true,
    bool forceIndividualRow = false,
  }) async {
    final effects = await JuceAudioEngine.getTrackEffectsForRow(
      row,
      forceIndividualRow: forceIndividualRow,
    );
    if (effects.length < 2) return const <EditorUndoAction>[];
    final desired = _canonicalAiEffectOrder(effects);
    if (_sameStringList(effects, desired)) return const <EditorUndoAction>[];

    final current = List<String>.from(effects);
    final actions = <EditorUndoAction>[];
    for (int targetIndex = 0; targetIndex < desired.length; targetIndex++) {
      if (current[targetIndex] == desired[targetIndex]) continue;
      final from = current.indexOf(desired[targetIndex], targetIndex + 1);
      if (from < 0) continue;
      final action = ReorderEffectAction(
        row: row,
        from: from,
        to: targetIndex,
        forceIndividualRow: forceIndividualRow,
        onChange: () {
          setState(() {});
          _refreshRowFx(row);
          unawaited(_refreshAutomationTargetsForRow(row));
        },
      );
      if (executeWithoutAdd) {
        await _undoManager.executeWithoutAdd(action);
      }
      actions.add(action);
      final moved = current.removeAt(from);
      current.insert(targetIndex, moved);
    }
    return actions;
  }

  Future<List<String>> _ensureAiV3PhoneMicCleanupOrder(
    int row,
    List<String> requiredEffectIds,
  ) async {
    final effectIds = await JuceAudioEngine.getTrackEffectIdsForRow(row);
    final instanceIds = await JuceAudioEngine.getTrackEffectInstanceIdsForRow(
      row,
    );
    if (effectIds.length != instanceIds.length ||
        instanceIds.any((value) => value.trim().isEmpty)) {
      throw StateError('v3_phone_cleanup_effect_identity_missing');
    }

    final selectedIndexes = <int>[];
    final selectedInstanceIds = <String>[];
    for (final requiredEffectId in requiredEffectIds) {
      final index = List<int>.generate(effectIds.length, (value) => value)
          .firstWhere(
            (candidate) =>
                !selectedIndexes.contains(candidate) &&
                effectIds[candidate] == requiredEffectId,
            orElse: () => -1,
          );
      if (index < 0) {
        throw StateError('v3_phone_cleanup_effect_insert_failed');
      }
      selectedIndexes.add(index);
      selectedInstanceIds.add(instanceIds[index]);
    }

    final selectedSlots = List<int>.from(selectedIndexes)..sort();
    final desiredInstanceIds = List<String>.from(instanceIds);
    for (var index = 0; index < selectedSlots.length; index++) {
      desiredInstanceIds[selectedSlots[index]] = selectedInstanceIds[index];
    }

    final currentInstanceIds = List<String>.from(instanceIds);
    for (
      var targetIndex = 0;
      targetIndex < desiredInstanceIds.length;
      targetIndex++
    ) {
      final desiredInstanceId = desiredInstanceIds[targetIndex];
      if (currentInstanceIds[targetIndex] == desiredInstanceId) continue;
      final from = currentInstanceIds.indexOf(
        desiredInstanceId,
        targetIndex + 1,
      );
      if (from < 0) {
        throw StateError('v3_phone_cleanup_effect_identity_missing');
      }
      await _undoManager.execute(
        ReorderEffectAction(
          row: row,
          from: from,
          to: targetIndex,
          onChange: () {
            _refreshAudioEditorView();
            _refreshRowFx(row);
            unawaited(_refreshAutomationTargetsForRow(row));
          },
        ),
      );
      final moved = currentInstanceIds.removeAt(from);
      currentInstanceIds.insert(targetIndex, moved);
    }
    return selectedInstanceIds;
  }

  Future<List<EditorUndoAction>> _ensureAiCanonicalChainOrderOnMaster({
    bool executeWithoutAdd = true,
  }) async {
    final effects = await JuceAudioEngine.getMasterEffects();
    if (effects.length < 2) return const <EditorUndoAction>[];
    final desired = _canonicalAiEffectOrder(effects);
    if (_sameStringList(effects, desired)) return const <EditorUndoAction>[];

    final current = List<String>.from(effects);
    final actions = <EditorUndoAction>[];
    for (int targetIndex = 0; targetIndex < desired.length; targetIndex++) {
      if (current[targetIndex] == desired[targetIndex]) continue;
      final from = current.indexOf(desired[targetIndex], targetIndex + 1);
      if (from < 0) continue;
      final action = ReorderMasterEffectAction(
        from: from,
        to: targetIndex,
        onChange: () {
          setState(() {});
          unawaited(_refreshAutomationTargetsForAllRows());
        },
      );
      if (executeWithoutAdd) {
        await _undoManager.executeWithoutAdd(action);
      }
      actions.add(action);
      final moved = current.removeAt(from);
      current.insert(targetIndex, moved);
    }
    return actions;
  }

  bool _sameStringList(List<String> a, List<String> b) {
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }

  Map<String, dynamic> _toActionMap(dynamic raw) {
    return AssistantActionUtils.toActionMap(raw);
  }

  double? _toActionDouble(dynamic raw) {
    return AssistantActionUtils.toActionDouble(raw);
  }

  double _canonicalEffectParameterValue({
    required double value,
    required double? minimum,
    required double? maximum,
    required double interval,
  }) {
    if (minimum == null ||
        maximum == null ||
        !interval.isFinite ||
        interval <= 0.0) {
      return value;
    }
    final steps = ((value - minimum) / interval).round();
    return (minimum + steps * interval).clamp(minimum, maximum).toDouble();
  }

  int? _toActionInt(dynamic raw) {
    return AssistantActionUtils.toActionInt(raw);
  }

  bool _toActionBool(dynamic raw, {bool fallback = false}) {
    return AssistantActionUtils.toActionBool(raw, fallback: fallback);
  }

  Map<String, dynamic> _actionTarget(Map<String, dynamic> data) {
    return _toActionMap(data['target']);
  }

  List<String> _actionStringList(dynamic raw) {
    if (raw is! List) return const <String>[];
    return raw
        .map((e) => e.toString().trim())
        .where((s) => s.isNotEmpty)
        .toList(growable: false);
  }

  int? _parseRowIndexValue(dynamic raw, {bool preferOneBased = false}) {
    final parsed = _toActionInt(raw);
    if (parsed == null) return null;
    final direct = parsed;
    final oneBased = parsed - 1;

    bool inRange(int idx) {
      if (_rowCount <= 0) return idx >= 0;
      return idx >= 0 && idx < _rowCount;
    }

    if (preferOneBased) {
      if (parsed > 0 && inRange(oneBased)) return oneBased;
      if (inRange(direct)) return direct;
      return null;
    }
    if (inRange(direct)) return direct;
    if (parsed > 0 && inRange(oneBased)) return oneBased;
    return null;
  }

  int? _resolveActionRowIndexFromData(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
    bool includeSelectionFallback = true,
  }) {
    final target = _actionTarget(data);

    final stableRowId =
        _toActionInt(data['row_id']) ?? _toActionInt(target['row_id']);
    if (stableRowId != null) {
      final byId = _rowIndexForId(stableRowId);
      return _isValidRowIndex(byId) ? byId : null;
    }

    int? pick(List<String> keys, {bool preferOneBased = false}) {
      for (final key in keys) {
        final parsed =
            _parseRowIndexValue(data[key], preferOneBased: preferOneBased) ??
            _parseRowIndexValue(target[key], preferOneBased: preferOneBased);
        if (parsed != null) return parsed;
      }
      return null;
    }

    int? row = pick(const [
      'row_index',
      'track_index',
      'target_row_index',
    ], preferOneBased: false);
    row ??= pick(const ['row', 'target_row'], preferOneBased: false);
    row ??= pick(const [
      'row_number',
      'track_number',
      'track',
    ], preferOneBased: true);
    if (row != null) return row;

    if (fallbackClipIndex != null &&
        fallbackClipIndex >= 0 &&
        fallbackClipIndex < _audioTracks.length) {
      return _audioTracks[fallbackClipIndex].rowIndex;
    }
    if (includeSelectionFallback && _rowCount > 0) {
      return _selectedRow.clamp(0, _rowCount - 1);
    }
    return null;
  }

  int? _resolveClipIndexFromActionTarget(
    Map<String, dynamic> data, {
    bool requireAudio = false,
    bool requireMidi = false,
  }) {
    bool passesKind(AudioTrack clip) {
      if (requireAudio && clip.isMidi) return false;
      if (requireMidi && !clip.isMidi) return false;
      return true;
    }

    bool isValidIndex(int idx) =>
        idx >= 0 && idx < _audioTracks.length && passesKind(_audioTracks[idx]);

    final target = _actionTarget(data);
    final clipId = (data['clip_id'] ?? target['clip_id'])?.toString().trim();
    if (clipId != null && clipId.isNotEmpty) {
      final byId = _audioTracks.indexWhere(
        (clip) => clip.clipId == clipId && passesKind(clip),
      );
      return byId < 0 ? null : byId;
    }
    final direct =
        _toActionInt(data['clip_index']) ??
        _toActionInt(target['clip_index']) ??
        _toActionInt(data['clip']) ??
        _toActionInt(target['clip']);
    if (direct != null && isValidIndex(direct)) return direct;

    final preferSelected = _toActionBool(
      target['prefer_selected'] ?? data['prefer_selected'],
      fallback: true,
    );
    if (preferSelected && isValidIndex(_timelinePrimarySelectedClipIndex)) {
      return _timelinePrimarySelectedClipIndex;
    }

    final selected = _timelineSelectedClipIndices
        .where((i) => isValidIndex(i))
        .toList(growable: false);
    if (preferSelected && selected.length == 1) {
      return selected.first;
    }

    final rowIndex = _resolveActionRowIndexFromData(
      data,
      includeSelectionFallback: false,
    );
    final fileContains =
        (target['file_name_contains'] ?? data['file_name_contains'])
            ?.toString()
            .trim()
            .toLowerCase();
    final labelContains = (target['label_contains'] ?? data['label_contains'])
        ?.toString()
        .trim()
        .toLowerCase();

    final candidates = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      if (!passesKind(clip)) continue;
      if (rowIndex != null && clip.rowIndex != rowIndex) continue;
      if (fileContains != null &&
          fileContains.isNotEmpty &&
          !_displayNameForFilePath(
            clip.file.path,
          ).toLowerCase().contains(fileContains)) {
        continue;
      }
      if (labelContains != null &&
          labelContains.isNotEmpty &&
          !clip.label.toLowerCase().contains(labelContains)) {
        continue;
      }
      candidates.add(i);
    }

    if (candidates.length == 1) return candidates.first;
    if (candidates.length > 1) {
      final selectedIntersect = selected
          .where((i) => candidates.contains(i))
          .toList();
      if (selectedIntersect.length == 1) return selectedIntersect.first;
      return null;
    }

    if (isValidIndex(_timelinePrimarySelectedClipIndex)) {
      return _timelinePrimarySelectedClipIndex;
    }

    return null;
  }

  List<int> _resolveClipIndicesFromActionTarget(
    Map<String, dynamic> data, {
    bool requireAudio = false,
    bool requireMidi = false,
  }) {
    bool passesKind(AudioTrack clip) {
      if (requireAudio && clip.isMidi) return false;
      if (requireMidi && !clip.isMidi) return false;
      return true;
    }

    bool isValidIndex(int idx) =>
        idx >= 0 && idx < _audioTracks.length && passesKind(_audioTracks[idx]);

    final target = _actionTarget(data);
    final out = LinkedHashSet<int>();
    final rowIndex = _resolveActionRowIndexFromData(
      data,
      includeSelectionFallback: false,
    );

    void add(int? idx) {
      if (idx != null && isValidIndex(idx)) {
        out.add(idx);
      }
    }

    final directListRaw =
        (data['clip_indices'] as List?) ?? (target['clip_indices'] as List?);
    if (directListRaw != null) {
      for (final raw in directListRaw) {
        add(_toActionInt(raw));
      }
    }

    final directSingleRaw =
        data['clip_index'] ??
        target['clip_index'] ??
        data['clip'] ??
        target['clip'];
    final exactClipId = (data['clip_id'] ?? target['clip_id'])
        ?.toString()
        .trim();
    if (directSingleRaw != null &&
        (exactClipId == null || exactClipId.isEmpty)) {
      add(_toActionInt(directSingleRaw));
    }

    final scope = (target['scope'] ?? data['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    if (scope == 'selected' || scope == 'selection') {
      for (final idx in _timelineSelectedClipIndices) {
        add(idx);
      }
      add(_timelinePrimarySelectedClipIndex);
      if (out.isEmpty && _rowCount > 0) {
        final selectedRow = _selectedRow.clamp(0, _rowCount - 1).toInt();
        for (int i = 0; i < _audioTracks.length; i++) {
          final clip = _audioTracks[i];
          if (clip.rowIndex != selectedRow) continue;
          if (!passesKind(clip)) continue;
          out.add(i);
        }
      }
    } else if (scope == 'all' ||
        scope == 'all_audio' ||
        scope == 'all_selected_audio') {
      if (rowIndex != null) {
        for (int i = 0; i < _audioTracks.length; i++) {
          final clip = _audioTracks[i];
          if (clip.rowIndex != rowIndex) continue;
          if (!passesKind(clip)) continue;
          out.add(i);
        }
      } else {
        for (int i = 0; i < _audioTracks.length; i++) {
          if (isValidIndex(i)) out.add(i);
        }
      }
    }

    if (rowIndex != null && out.isEmpty && scope.isEmpty) {
      for (int i = 0; i < _audioTracks.length; i++) {
        final clip = _audioTracks[i];
        if (clip.rowIndex != rowIndex) continue;
        if (!passesKind(clip)) continue;
        out.add(i);
      }
    }

    final single = _resolveClipIndexFromActionTarget(
      data,
      requireAudio: requireAudio,
      requireMidi: requireMidi,
    );
    add(single);

    if (out.isEmpty) {
      for (final idx in _timelineSelectedClipIndices) {
        add(idx);
      }
      add(_timelinePrimarySelectedClipIndex);
    }

    final sorted = out.toList()..sort();
    return sorted;
  }

  int? _pickPreferredClipIndex(List<int> candidates) {
    if (candidates.isEmpty) return null;
    final set = candidates.toSet();
    if (set.contains(_timelinePrimarySelectedClipIndex)) {
      return _timelinePrimarySelectedClipIndex;
    }
    for (final idx in _timelineSelectedClipIndices) {
      if (set.contains(idx)) return idx;
    }
    final sorted = candidates.toList(growable: false)
      ..sort((a, b) {
        final ao = (a >= 0 && a < _audioTracks.length)
            ? _audioTracks[a].offset
            : 0.0;
        final bo = (b >= 0 && b < _audioTracks.length)
            ? _audioTracks[b].offset
            : 0.0;
        final byOffset = ao.compareTo(bo);
        if (byOffset != 0) return byOffset;
        return a.compareTo(b);
      });
    return sorted.first;
  }

  int? _resolveSingleClipIndexWithFallback(
    Map<String, dynamic> data, {
    bool requireAudio = false,
    bool requireMidi = false,
  }) {
    final direct = _resolveClipIndexFromActionTarget(
      data,
      requireAudio: requireAudio,
      requireMidi: requireMidi,
    );
    if (direct != null) return direct;
    final candidates = _resolveClipIndicesFromActionTarget(
      data,
      requireAudio: requireAudio,
      requireMidi: requireMidi,
    );
    return _pickPreferredClipIndex(candidates);
  }

  int? _resolveRowIndexFromActionTarget(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
  }) {
    final row = _resolveActionRowIndexFromData(
      data,
      fallbackClipIndex: fallbackClipIndex,
    );
    if (row == null || _rowCount <= 0) return null;
    return row.clamp(0, _rowCount - 1);
  }

  List<int> _resolveRowIndicesFromActionTarget(
    Map<String, dynamic> data, {
    bool includeSelectionFallback = true,
  }) {
    if (_rowCount <= 0) return const <int>[];
    final target = _actionTarget(data);
    final rows = LinkedHashSet<int>();

    void addRow(dynamic raw, {bool preferOneBased = false}) {
      final row = _parseRowIndexValue(raw, preferOneBased: preferOneBased);
      if (row != null && row >= 0 && row < _rowCount) {
        rows.add(row);
      }
    }

    void addRowList(dynamic raw, {bool preferOneBased = false}) {
      if (raw is List) {
        for (final item in raw) {
          addRow(item, preferOneBased: preferOneBased);
        }
      }
    }

    addRowList(data['row_indices']);
    addRowList(target['row_indices']);
    addRowList(data['track_indices']);
    addRowList(target['track_indices']);
    addRowList(data['rows']);
    addRowList(target['rows']);
    addRowList(data['tracks']);
    addRowList(target['tracks']);
    addRowList(data['row_numbers'], preferOneBased: true);
    addRowList(target['row_numbers'], preferOneBased: true);
    addRowList(data['track_numbers'], preferOneBased: true);
    addRowList(target['track_numbers'], preferOneBased: true);

    final single = _resolveActionRowIndexFromData(
      data,
      includeSelectionFallback: false,
    );
    if (single != null && single >= 0 && single < _rowCount) {
      rows.add(single);
    }

    final scope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    if (scope == 'group' || scope == 'track_group' || scope == 'track-group') {
      final groupId = _resolveRowGroupIdFromAction(data);
      if (groupId != null && groupId.isNotEmpty) {
        for (int row = 0; row < _rows.length; row++) {
          if (_rows[row].groupId.trim() == groupId) {
            rows.add(row);
          }
        }
        for (final group in _trackGroups) {
          if (group.id != groupId) continue;
          final rowIds = group.rowIds.toSet();
          for (int row = 0; row < _rows.length; row++) {
            if (rowIds.contains(_rows[row].rowId)) {
              rows.add(row);
            }
          }
        }
      }
    }
    if (scope == 'selected' || scope == 'selection') {
      for (final clipIndex in _timelineSelectedClipIndices) {
        if (clipIndex >= 0 && clipIndex < _audioTracks.length) {
          final row = _audioTracks[clipIndex].rowIndex;
          if (row >= 0 && row < _rowCount) rows.add(row);
        }
      }
      if (_timelinePrimarySelectedClipIndex >= 0 &&
          _timelinePrimarySelectedClipIndex < _audioTracks.length) {
        final row = _audioTracks[_timelinePrimarySelectedClipIndex].rowIndex;
        if (row >= 0 && row < _rowCount) rows.add(row);
      }
    }

    if (rows.isEmpty && includeSelectionFallback) {
      rows.add(_selectedRow.clamp(0, _rowCount - 1).toInt());
    }

    final out = rows.toList(growable: false)..sort();
    return out;
  }

  int _resolveInsertionRowIndexFromActionTarget(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
  }) {
    final row = _resolveActionRowIndexFromData(
      data,
      fallbackClipIndex: fallbackClipIndex,
    );
    if (row != null && row >= 0) {
      return row;
    }
    if (_rowCount > 0) {
      return _selectedRow.clamp(0, _rowCount - 1).toInt();
    }
    return 0;
  }

  bool _aiActionAllowsLayeringOnExistingRow(Map<String, dynamic> data) {
    final target = _actionTarget(data);
    final scope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    if (scope == 'selected' || scope == 'selection') return true;
    if (_toActionBool(data['prefer_selected'] ?? target['prefer_selected'])) {
      return true;
    }
    for (final raw in <dynamic>[
      data['allow_layer_existing_row'],
      target['allow_layer_existing_row'],
      data['allow_existing_row'],
      target['allow_existing_row'],
      data['place_on_existing_row'],
      target['place_on_existing_row'],
      data['target_existing_row'],
      target['target_existing_row'],
    ]) {
      if (_toActionBool(raw)) return true;
    }
    final placement =
        (data['placement_policy'] ??
                target['placement_policy'] ??
                data['placement'] ??
                target['placement'] ??
                '')
            .toString()
            .trim()
            .toLowerCase();
    return placement.contains('existing') || placement.contains('layer');
  }

  bool _aiActionRequestsCleanContentRow(Map<String, dynamic> data) {
    final target = _actionTarget(data);
    for (final raw in <dynamic>[
      data['prefer_clean_row'],
      target['prefer_clean_row'],
      data['prefer_empty_row'],
      target['prefer_empty_row'],
      data['use_empty_row'],
      target['use_empty_row'],
    ]) {
      if (_toActionBool(raw)) return true;
    }
    final placement =
        (data['placement_policy'] ??
                target['placement_policy'] ??
                data['placement'] ??
                target['placement'] ??
                '')
            .toString()
            .trim()
            .toLowerCase();
    return placement.contains('clean') ||
        placement.contains('empty') ||
        placement.contains('new_row') ||
        placement.contains('new row') ||
        placement.contains('separate');
  }

  bool _rowHasTimelineClip(int row) {
    if (row < 0 || row >= _rowCount) return false;
    _ensureClipOperationIndexes();
    final rowId = _rowIdAt(row);
    return rowId >= 0 && (_clipsByRowId[rowId]?.isNotEmpty ?? false);
  }

  int? _preferredCleanAiContentRow() {
    if (_rowCount <= 0) return 0;
    _ensureClipOperationIndexes();
    final occupiedRows = _clipsByRowId.entries
        .where((entry) => entry.value.isNotEmpty)
        .map((entry) => _rowIndexForId(entry.key))
        .where((row) => row >= 0 && row < _rowCount)
        .toSet();
    if (occupiedRows.isEmpty) {
      return _selectedRow.clamp(0, _rowCount - 1).toInt();
    }
    final bottomOccupied = occupiedRows.reduce((a, b) => a > b ? a : b);
    for (int row = bottomOccupied + 1; row < _rowCount; row++) {
      if (!occupiedRows.contains(row)) return row;
    }
    if (_rowCount < _effectiveMaxRows) return _rowCount;
    for (int row = 0; row < _rowCount; row++) {
      if (!occupiedRows.contains(row)) return row;
    }
    return null;
  }

  int _resolveAiContentInsertionRowIndexFromActionTarget(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
  }) {
    final row = _resolveInsertionRowIndexFromActionTarget(
      data,
      fallbackClipIndex: fallbackClipIndex,
    );
    if (!_aiActionRequestsCleanContentRow(data) ||
        _aiActionAllowsLayeringOnExistingRow(data) ||
        !_rowHasTimelineClip(row)) {
      return row;
    }
    return _preferredCleanAiContentRow() ?? row;
  }

  Future<int> _resolveAudioInsertionRowIndexFromActionTarget(
    Map<String, dynamic> data, {
    int? fallbackClipIndex,
  }) async {
    if (_rowCount <= 0) {
      final added = await _addRowImpl();
      if (!added || _rowCount <= 0) return 0;
      return _rowCount - 1;
    }

    final requestedRow = _resolveAiContentInsertionRowIndexFromActionTarget(
      data,
      fallbackClipIndex: fallbackClipIndex,
    );
    while (requestedRow >= _rowCount && _rowCount < _effectiveMaxRows) {
      final added = await _addRowImpl();
      if (!added || _rowCount <= 0) break;
    }
    final boundedRow = requestedRow.clamp(0, _rowCount - 1).toInt();
    if (!_rows[boundedRow].isInstrumentLane) return boundedRow;

    for (final offset in const <int>[1, -1, 2, -2, 3, -3]) {
      final candidate = boundedRow + offset;
      if (candidate < 0 || candidate >= _rowCount) continue;
      if (!_rows[candidate].isInstrumentLane) return candidate;
    }

    if (_rowCount < _effectiveMaxRows) {
      final inserted = await _insertRowBelowImpl(boundedRow);
      if (inserted) return (boundedRow + 1).clamp(0, _rowCount - 1).toInt();
    }

    for (int row = 0; row < _rowCount; row++) {
      if (!_rows[row].isInstrumentLane) return row;
    }

    return boundedRow;
  }

  bool _isKickLikeText(String raw) {
    final text = raw.trim().toLowerCase();
    if (text.isEmpty) return false;
    return text.contains('kick') ||
        text.contains('808') ||
        text.contains('bd') ||
        text.contains('bassdrum') ||
        text.contains('bass drum');
  }

  int? _resolveKickSourceClipIndexFromAction(
    Map<String, dynamic> data, {
    int? targetRow,
  }) {
    final target = _actionTarget(data);

    int? parseSourceIndex() {
      final idx = _toActionInt(
        data['source_clip_index'] ??
            target['source_clip_index'] ??
            data['kick_clip_index'] ??
            target['kick_clip_index'] ??
            data['trigger_clip_index'] ??
            target['trigger_clip_index'],
      );
      if (idx == null || idx < 0 || idx >= _audioTracks.length) return null;
      if (_audioTracks[idx].isMidi) return null;
      return idx;
    }

    int? fromIndex = parseSourceIndex();
    if (fromIndex != null) return fromIndex;

    int? sourceRow = _toActionInt(
      data['source_row_index'] ??
          target['source_row_index'] ??
          data['kick_row_index'] ??
          target['kick_row_index'],
    );
    if (sourceRow == null) {
      final sourceRole =
          (data['source_role'] ??
                  target['source_role'] ??
                  data['kick_role'] ??
                  target['kick_role'] ??
                  '')
              .toString()
              .trim()
              .toLowerCase();
      if (sourceRole == 'drums' || sourceRole == 'kick') {
        sourceRow = _selectedRow;
      }
    }

    List<int> candidatesForRow(int row) {
      if (row < 0 || row >= _rowCount) return const <int>[];
      final out = <int>[];
      for (int i = 0; i < _audioTracks.length; i++) {
        final clip = _audioTracks[i];
        if (clip.isMidi) continue;
        if (clip.rowIndex != row) continue;
        out.add(i);
      }
      return out;
    }

    if (sourceRow != null) {
      final pick = _pickPreferredClipIndex(candidatesForRow(sourceRow));
      if (pick != null) return pick;
    }

    final kickNameCandidates = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      if (clip.isMidi) continue;
      final file = _displayNameForFilePath(clip.file.path);
      if (_isKickLikeText(clip.label) || _isKickLikeText(file)) {
        kickNameCandidates.add(i);
      }
    }
    final namedKickPick = _pickPreferredClipIndex(kickNameCandidates);
    if (namedKickPick != null) return namedKickPick;

    final selectedAudioCandidates = _timelineSelectedClipIndices
        .where(
          (i) => i >= 0 && i < _audioTracks.length && !_audioTracks[i].isMidi,
        )
        .toList(growable: false);
    final selectedPick = _pickPreferredClipIndex(selectedAudioCandidates);
    if (selectedPick != null) return selectedPick;

    if (targetRow != null) {
      final rowPick = _pickPreferredClipIndex(candidatesForRow(targetRow));
      if (rowPick != null) return rowPick;
    }

    final anyAudio = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      if (!_audioTracks[i].isMidi) anyAudio.add(i);
    }
    return _pickPreferredClipIndex(anyAudio);
  }

  static const Set<String> _supportedTutorialHaloTargets = <String>{
    'tutorial:chatbar',
    'tutorial:chat_send',
    'tutorial:prompt_limits',
    'tutorial:toolbar',
    'tutorial:transport:play',
    'tutorial:transport:record',
    'tutorial:transport:restart',
    'tutorial:mute',
    'tutorial:solo',
    'tutorial:add_button',
    'tutorial:add_audio',
    'tutorial:add_instrument',
    'tutorial:export',
    'tutorial:project_settings',
    'tutorial:master_button',
    'tutorial:plugins',
    'tutorial:one_button_mix',
    'tutorial:piano_roll',
    'tutorial:timeline',
  };

  String _tutorialSlug(String raw) {
    return raw
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_|_$'), '');
  }

  String? _normalizeTutorialTargetId(String raw) {
    final normalized = AssistantActionUtils.normalizeTutorialTargetId(raw);
    if (normalized == null) return null;
    if (normalized.startsWith('row:')) {
      return normalized;
    }
    if (normalized == 'tutorial:effects_tab' ||
        normalized == 'tutorial:fx_list' ||
        normalized == 'tutorial:add_effect' ||
        normalized == 'tutorial:volume_tab') {
      if (_rowCount <= 0) return 'tutorial:timeline';
      final row = _selectedRow.clamp(0, _rowCount - 1);
      switch (normalized) {
        case 'tutorial:effects_tab':
          return 'row:$row:effects_tab';
        case 'tutorial:fx_list':
          return 'row:$row:fx_list';
        case 'tutorial:add_effect':
          return 'row:$row:add_effect';
        case 'tutorial:volume_tab':
          return 'row:$row:volume_tab';
      }
    }
    if (normalized == 'tutorial:automation_tab') {
      return 'tutorial:timeline';
    }
    if (normalized == 'tutorial:piano_roll' &&
        (!_showPianoRoll || _activeMidiClipEngineId == null)) {
      return 'tutorial:timeline';
    }
    if (_supportedTutorialHaloTargets.contains(normalized)) {
      return normalized;
    }
    if (normalized.startsWith('tutorial:')) {
      // Never no-op tutorial actions on unknown anchors; fall back to timeline.
      return 'tutorial:timeline';
    }
    return normalized;
  }

  List<String> _tutorialTargetSequenceForStep(
    Map<String, dynamic> step,
    Map<String, dynamic> rootData,
  ) {
    final out = <String>[];
    void add(String? key) {
      if (key == null) return;
      final trimmed = key.trim();
      if (trimmed.isEmpty || out.contains(trimmed)) return;
      out.add(trimmed);
    }

    final target = _toActionMap(step['target']);
    if (_rowCount <= 0) {
      final rawTarget =
          (step['target_id'] ??
                  target['target_id'] ??
                  rootData['target_id'] ??
                  _toActionMap(rootData['target'])['target_id'] ??
                  '')
              .toString();
      final fallback =
          _normalizeTutorialTargetId(rawTarget) ?? 'tutorial:timeline';
      return <String>[fallback];
    }
    final row =
        _toActionInt(
          step['row_index'] ??
              target['row_index'] ??
              rootData['row_index'] ??
              _toActionMap(rootData['target'])['row_index'],
        ) ??
        _selectedRow.clamp(0, _rowCount - 1);

    final effectName =
        (step['effect_name'] ??
                step['plugin_name'] ??
                target['effect_name'] ??
                target['plugin_name'] ??
                rootData['effect_name'] ??
                rootData['plugin_name'])
            .toString()
            .trim();
    final effectSlug = _tutorialSlug(effectName);
    final effectLower = effectName.toLowerCase();
    final effectIndex = _toActionInt(
      step['effect_index'] ??
          target['effect_index'] ??
          rootData['effect_index'] ??
          _toActionMap(rootData['target'])['effect_index'],
    );
    final paramName =
        (step['param_name'] ??
                step['param_id'] ??
                step['parameter'] ??
                target['param_name'] ??
                target['param_id'] ??
                rootData['param_name'] ??
                rootData['param_id'])
            .toString()
            .trim();
    final paramSlug = _tutorialSlug(paramName);
    final paramLower = paramName.toLowerCase();
    final addEffect = _toActionBool(
      step['show_add_effect'] ??
          step['effect_missing'] ??
          target['show_add_effect'] ??
          target['effect_missing'] ??
          rootData['show_add_effect'] ??
          rootData['effect_missing'],
      fallback: false,
    );

    final rawTarget =
        (step['target_id'] ??
                target['target_id'] ??
                rootData['target_id'] ??
                _toActionMap(rootData['target'])['target_id'] ??
                '')
            .toString();
    final normalized = _normalizeTutorialTargetId(rawTarget);

    final hasFxDrill =
        effectIndex != null || effectName.isNotEmpty || paramName.isNotEmpty;
    if (hasFxDrill || addEffect) {
      add('row:$row');
      add('row:$row:effects_tab');
      add('row:$row:fx_list');
      if (addEffect) add('row:$row:add_effect');
      if (effectIndex != null) add('row:$row:fx_index:$effectIndex');
      if (effectLower.isNotEmpty) add('row:$row:fx_contains:$effectLower');
      if (effectSlug.isNotEmpty) add('row:$row:fx_contains:$effectSlug');
      if (paramLower.isNotEmpty) add('row:$row:param:$paramLower');
      if (paramSlug.isNotEmpty) add('row:$row:param:$paramSlug');
      if (effectIndex != null && paramLower.isNotEmpty) {
        add('row:$row:fx_index:$effectIndex:param:$paramLower');
      }
      if (effectIndex != null && paramSlug.isNotEmpty) {
        add('row:$row:fx_index:$effectIndex:param:$paramSlug');
      }
      if (effectSlug.isNotEmpty && paramSlug.isNotEmpty) {
        add('row:$row:fx_contains:$effectSlug:param:$paramSlug');
      }
      if (effectLower.isNotEmpty && paramLower.isNotEmpty) {
        add('row:$row:fx_contains:$effectLower:param:$paramLower');
      }
    }

    if (normalized == 'tutorial:mute') {
      add('row:$row:mute');
    } else if (normalized == 'tutorial:solo') {
      add('row:$row:solo');
    } else if (normalized == 'tutorial:plugins') {
      add('row:$row:effects_tab');
      add('row:$row:fx_list');
    } else if (normalized == 'tutorial:timeline') {
      add('row:$row');
    }

    if (normalized != null && normalized.isNotEmpty) {
      add(normalized);
    }
    if (out.isEmpty) {
      add('tutorial:timeline');
    }
    return out;
  }

  Future<bool> _applyAssistantActions(
    List<AssistantAction> actions, {
    int? chatFlowId,
    List<Map<String, dynamic>>? v3RuntimeExpectations,
    Map<String, List<String>>? v3ExecutionSummariesByCommandId,
    Set<String>? v3RuntimeAlreadySatisfiedCommandIds,
    AiV3WorkflowRuntime? v3WorkflowRuntime,
  }) async {
    _assistantActionNoticeCaptureDepth += 1;
    final batchExecutionNotices =
        v3RuntimeExpectations == null &&
        _deferredAssistantExecutionNotices == null;
    if (batchExecutionNotices) {
      _assistantActionExecutionBatchDepth += 1;
    }
    final executionMessagesBefore = _assistantActionExecutionMessageCount;
    Future<void> applyV3MixActions(Map<String, dynamic> data) async {
      final rawMixActions = data['actions'];
      if (rawMixActions is! List || rawMixActions.isEmpty) {
        throw StateError('v3_mix_actions_missing');
      }
      final mixActions = rawMixActions
          .map((raw) {
            if (raw is! Map || raw['type'] is! String || raw['data'] is! Map) {
              throw StateError('v3_mix_action_malformed');
            }
            return MixAction(
              raw['type'].toString(),
              Map<String, dynamic>.from(raw['data'] as Map),
            );
          })
          .toList(growable: false);
      final report = await applyMixingResult(
        MixingResult(actions: mixActions, summary: '', isNoOp: false),
        emitActionSummaries: false,
        stageEffectEnsures: true,
      );
      if (report.attempted != mixActions.length ||
          report.skippedReasons.isNotEmpty) {
        throw StateError('v3_mix_actions_not_fully_applied');
      }
      final commandId = data['command_id']?.toString().trim() ?? '';
      if (commandId.isNotEmpty && report.summaries.isNotEmpty) {
        v3ExecutionSummariesByCommandId?[commandId] = List<String>.unmodifiable(
          report.summaries,
        );
      }
      if (v3RuntimeExpectations != null) {
        _addAiV3Expectations(v3RuntimeExpectations, report.appliedMutations);
      }
    }

    try {
      var hadFailure = false;
      for (var actionIndex = 0; actionIndex < actions.length; actionIndex++) {
        final action = actions[actionIndex];
        final type = action.type.trim().toLowerCase();
        var data = _toActionMap(action.data);
        String? resolvedResourceClipId;
        int? resolvedResourceRowId;
        String? resolvedResourceGroupId;
        AiV3ResourceKind? resolvedResourceKind;
        AiV3ResourceRef? resolvedResourceRef;
        AiV3RuntimeResourceBinding? resolvedResourceBinding;
        Map<String, dynamic>? splitRuntimeState;
        Map<String, dynamic>? duplicateRuntimeState;
        Map<String, dynamic>? glueRuntimeState;
        try {
          if (chatFlowId != null) {
            _throwIfChatFlowStopped(chatFlowId);
          }
          final unresolvedTarget = _actionTarget(data);
          final rawResourceRef = unresolvedTarget['resource_ref'];
          if (rawResourceRef != null) {
            final consumerType =
                data['resource_consumer_type']?.toString().trim() ?? '';
            final consumerSpec = aiV3ResourceConsumerSpecs[consumerType];
            if (consumerSpec == null ||
                consumerSpec.actionType != type ||
                consumerSpec.operation != data['operation'] ||
                v3WorkflowRuntime == null) {
              throw StateError('v3_resource_action_unsupported');
            }
            late final AiV3ResourceRef resourceRef;
            try {
              resourceRef = AiV3ResourceRef.fromJson(rawResourceRef);
            } on FormatException {
              throw StateError('v3_resource_ref_invalid');
            }
            final binding = v3WorkflowRuntime.resolveAccepted(
              resourceRef,
              acceptedKinds: consumerSpec.acceptedKinds,
            );
            resolvedResourceBinding = binding;
            resolvedResourceKind = binding.kind;
            resolvedResourceRef = resourceRef;
            if (binding.kind == AiV3ResourceKind.audioRow ||
                binding.kind == AiV3ResourceKind.midiRow) {
              final rowId = binding.stableId;
              if (rowId is! int) {
                throw StateError('v3_resource_binding_invalid');
              }
              final rowIndex = _rowIndexForId(rowId);
              final expectsMidi = binding.kind == AiV3ResourceKind.midiRow;
              if (!_isValidRowIndex(rowIndex) ||
                  _rows[rowIndex].isInstrumentLane != expectsMidi) {
                throw StateError('v3_resource_binding_unavailable');
              }
              resolvedResourceRowId = rowId;
              final resolvedRowTarget = <String, dynamic>{
                ...unresolvedTarget,
                'scope': 'row',
                'row_id': rowId,
                'row_index': rowIndex,
                if (expectsMidi &&
                    _rows[rowIndex].instrumentId.trim().isNotEmpty)
                  'instrument_id': _rows[rowIndex].instrumentId,
              }..remove('resource_ref');
              data = <String, dynamic>{
                ...data,
                'target': resolvedRowTarget,
                if (type == 'sample_insert')
                  'items': <Map<String, dynamic>>[
                    for (final raw
                        in (data['items'] as List? ?? const <Object>[]))
                      if (raw is Map)
                        <String, dynamic>{
                          ...Map<String, dynamic>.from(raw),
                          'row_index': rowIndex,
                          'target': <String, dynamic>{
                            'scope': 'row',
                            'row_id': rowId,
                            'row_index': rowIndex,
                          },
                        },
                  ],
              };
            } else if (binding.kind == AiV3ResourceKind.group) {
              final groupId = binding.stableId;
              if (groupId is! String ||
                  !_trackGroups.any((group) => group.id == groupId)) {
                throw StateError('v3_resource_binding_unavailable');
              }
              resolvedResourceGroupId = groupId;
              data = <String, dynamic>{
                ...data,
                'group_id': groupId,
                'target': <String, dynamic>{
                  'scope': 'group',
                  'group_id': groupId,
                },
              };
            } else {
              final clipId = binding.stableId;
              if (clipId is! String) {
                throw StateError('v3_resource_binding_invalid');
              }
              final clipIndex = _clipIndexForPersistentId(clipId);
              if (!_isValidClipIndex(clipIndex) ||
                  _audioTracks[clipIndex].isMidi !=
                      (binding.kind == AiV3ResourceKind.midiClip)) {
                throw StateError('v3_resource_binding_unavailable');
              }
              resolvedResourceClipId = clipId;
              data = <String, dynamic>{
                ...data,
                'target': <String, dynamic>{'scope': 'clip', 'clip_id': clipId},
              };
              if (type == 'v3_clip_convert_to_midi' ||
                  type == 'v3_clip_separate_stems') {
                final liveClip = _audioTracks[clipIndex];
                data = <String, dynamic>{
                  ...data,
                  'source_clip_id': clipId,
                  'source_row_id': liveClip.rowId,
                  'source_row_index': liveClip.rowIndex,
                  'start_ms': liveClip.offset * 1000.0,
                  'duration_ms': _clipTimelineDurationMs(liveClip).toDouble(),
                };
              }
            }
          }
          if (type == 'v3_group_edit' &&
              data['operation'] == 'create' &&
              data['member_targets'] is List) {
            if (v3WorkflowRuntime == null) {
              throw StateError('v3_resource_producer_context_missing');
            }
            final rowIds = <int>[];
            for (final rawTarget in data['member_targets'] as List) {
              final memberTarget = _toActionMap(rawTarget);
              final rawRef = memberTarget['resource_ref'];
              int? rowId;
              if (rawRef != null) {
                late final AiV3ResourceRef ref;
                try {
                  ref = AiV3ResourceRef.fromJson(rawRef);
                } on FormatException {
                  throw StateError('v3_resource_ref_invalid');
                }
                final binding = v3WorkflowRuntime.resolveAccepted(
                  ref,
                  acceptedKinds: const <AiV3ResourceKind>{
                    AiV3ResourceKind.audioRow,
                    AiV3ResourceKind.midiRow,
                  },
                );
                rowId = binding.stableId as int?;
              } else {
                rowId = _toActionInt(memberTarget['row_id']);
              }
              if (rowId == null || _rowIndexForId(rowId) < 0) {
                throw StateError('v3_resource_binding_unavailable');
              }
              rowIds.add(rowId);
            }
            if (rowIds.length < 2 || rowIds.toSet().length != rowIds.length) {
              throw StateError('v3_group_create_members_invalid');
            }
            final currentOrder = _rows.map((row) => row.rowId).toList();
            final ordered = rowIds.toList()
              ..sort(
                (left, right) => currentOrder
                    .indexOf(left)
                    .compareTo(currentOrder.indexOf(right)),
              );
            final memberSet = ordered.toSet();
            final insertionIndex = ordered
                .map(currentOrder.indexOf)
                .reduce(math.min);
            final expectedOrder =
                currentOrder
                    .where((rowId) => !memberSet.contains(rowId))
                    .toList(growable: true)
                  ..insertAll(insertionIndex, ordered);
            data = <String, dynamic>{
              ...data,
              'row_ids': ordered,
              'expected_row_order': expectedOrder,
            };
          }
          if (type == 'v3_group_edit' &&
              data['operation'] == 'remove_row' &&
              data['row_target'] is Map) {
            final rowTarget = _toActionMap(data['row_target']);
            final rawRef = rowTarget['resource_ref'];
            int? rowId;
            if (rawRef != null) {
              if (v3WorkflowRuntime == null) {
                throw StateError('v3_resource_producer_context_missing');
              }
              late final AiV3ResourceRef ref;
              try {
                ref = AiV3ResourceRef.fromJson(rawRef);
              } on FormatException {
                throw StateError('v3_resource_ref_invalid');
              }
              final binding = v3WorkflowRuntime.resolveAccepted(
                ref,
                acceptedKinds: const <AiV3ResourceKind>{
                  AiV3ResourceKind.audioRow,
                  AiV3ResourceKind.midiRow,
                },
              );
              rowId = binding.stableId as int?;
            } else {
              rowId = _toActionInt(rowTarget['row_id']);
            }
            if (rowId == null || _rowIndexForId(rowId) < 0) {
              throw StateError('v3_resource_binding_unavailable');
            }
            final groupId =
                resolvedResourceGroupId ??
                data['group_id']?.toString().trim() ??
                '';
            final group = _trackGroups
                .where((candidate) => candidate.id == groupId)
                .firstOrNull;
            if (group == null || !group.rowIds.contains(rowId)) {
              throw StateError('v3_group_membership_mismatch');
            }
            final remaining = group.rowIds
                .where((candidate) => candidate != rowId)
                .toList(growable: false);
            data = <String, dynamic>{
              ...data,
              'row_id': rowId,
              'dissolves_group': remaining.length < 2,
              'expected_member_row_ids': remaining.length < 2
                  ? const <int>[]
                  : remaining,
            };
          }
          if (type == 'clip_edit' &&
              _normalizeClipEditOperation(
                    data['operation']?.toString() ?? '',
                  ) ==
                  'cut' &&
              (data['command_id']?.toString().trim().isNotEmpty ?? false)) {
            if (v3WorkflowRuntime == null) {
              throw StateError('v3_resource_producer_context_missing');
            }
            if (resolvedResourceRef != null && v3RuntimeExpectations != null) {
              data = _withAiV3AuthoritativeResourceBounds(
                data,
                _aiV3GeneratedResourceExpectation(
                  v3RuntimeExpectations,
                  resolvedResourceRef,
                ),
              );
            }
            splitRuntimeState = _prepareAiV3SplitRuntimeState(
              data,
              inputRef: resolvedResourceRef,
            );
            splitRuntimeState['parent_row_key'] =
                resolvedResourceBinding?.parentRowKey;
          }
          if (type == 'clip_edit' &&
              _normalizeClipEditOperation(
                    data['operation']?.toString() ?? '',
                  ) ==
                  'duplicate' &&
              (data['command_id']?.toString().trim().isNotEmpty ?? false)) {
            if (v3WorkflowRuntime == null) {
              throw StateError('v3_resource_producer_context_missing');
            }
            if (resolvedResourceRef != null && v3RuntimeExpectations != null) {
              data = _withAiV3AuthoritativeResourceBounds(
                data,
                _aiV3GeneratedResourceExpectation(
                  v3RuntimeExpectations,
                  resolvedResourceRef,
                ),
              );
            }
            duplicateRuntimeState = _prepareAiV3DuplicateRuntimeState(data);
            final explicitDestinationRowId = _toActionInt(data['row_id']);
            duplicateRuntimeState['parent_row_key'] =
                explicitDestinationRowId == null
                ? resolvedResourceBinding?.parentRowKey
                : 'stable_row:$explicitDestinationRowId';
          }
          if (type == 'clip_edit' &&
              _normalizeClipEditOperation(
                    data['operation']?.toString() ?? '',
                  ) ==
                  'trim' &&
              resolvedResourceRef != null) {
            data = _prepareAiV3ReferencedTrimRuntimeData(
              data,
              expectedResource: v3RuntimeExpectations == null
                  ? null
                  : _aiV3GeneratedResourceExpectation(
                      v3RuntimeExpectations,
                      resolvedResourceRef,
                    ),
            );
          }
          if (type == 'midi_compose' &&
              data['runtime_authoritative_midi'] == true &&
              resolvedResourceRef != null) {
            if (v3RuntimeExpectations == null) {
              throw StateError('v3_resource_expectation_missing');
            }
            data = _materializeAiV3RuntimeAuthoritativeMidiAction(
              data,
              _aiV3GeneratedResourceExpectation(
                v3RuntimeExpectations,
                resolvedResourceRef,
              ),
            );
          }
          if (type == 'clip_edit' &&
              data['runtime_authoritative_audio_timing'] == true &&
              resolvedResourceRef != null) {
            if (v3RuntimeExpectations == null) {
              throw StateError('v3_resource_expectation_missing');
            }
            data = _materializeAiV3RuntimeAuthoritativeAudioTimingAction(
              data,
              _aiV3GeneratedResourceExpectation(
                v3RuntimeExpectations,
                resolvedResourceRef,
              ),
            );
          }
          if (type == 'v3_clip_glue' && data['sources'] is List) {
            if (v3WorkflowRuntime == null || v3RuntimeExpectations == null) {
              throw StateError('v3_resource_producer_context_missing');
            }
            glueRuntimeState = _prepareAiV3GlueRuntimeState(
              data,
              expectations: v3RuntimeExpectations,
              workflowRuntime: v3WorkflowRuntime,
            );
            data = Map<String, dynamic>.from(
              glueRuntimeState['materialized_data'] as Map,
            );
          }
          switch (type) {
            case 'tutorial':
              await _applyTutorialAction(data);
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'clip_edit':
              await _applyClipEditAction(data);
              if (splitRuntimeState != null) {
                if (v3RuntimeExpectations == null ||
                    v3WorkflowRuntime == null) {
                  throw StateError('v3_resource_expectation_missing');
                }
                _bindAiV3SplitOutputs(
                  splitRuntimeState,
                  expectations: v3RuntimeExpectations,
                  workflowRuntime: v3WorkflowRuntime,
                  producerActionIndex: actionIndex,
                );
              }
              if (duplicateRuntimeState != null) {
                if (v3RuntimeExpectations == null ||
                    v3WorkflowRuntime == null) {
                  throw StateError('v3_resource_expectation_missing');
                }
                _bindAiV3DuplicateOutput(
                  duplicateRuntimeState,
                  expectations: v3RuntimeExpectations,
                  workflowRuntime: v3WorkflowRuntime,
