                data,
                workflowRuntime: v3WorkflowRuntime,
              );
              if (resolvedResourceRef != null &&
                  v3RuntimeExpectations != null) {
                _markAiV3ProducerOutputTransformed(
                  v3RuntimeExpectations,
                  resolvedResourceRef,
                );
              }
              final commandId = data['command_id']?.toString().trim() ?? '';
              if (commandId.isEmpty || v3WorkflowRuntime == null) {
                if (data['command_id'] != null) {
                  throw StateError('v3_resource_producer_context_missing');
                }
              } else {
                for (final pathKey in const <String>[
                  'vocals_file',
                  'instrumental_file',
                ]) {
                  v3WorkflowRuntime.trackGeneratedArtifact(
                    stemExpectation[pathKey]?.toString() ?? '',
                  );
                }
                final outputs = <String, (AiV3ResourceKind, Object?)>{
                  'vocals_clip': (
                    AiV3ResourceKind.audioClip,
                    stemExpectation['vocals_clip_id'],
                  ),
                  'instrumental_clip': (
                    AiV3ResourceKind.audioClip,
                    stemExpectation['instrumental_clip_id'],
                  ),
                  'vocals_row': (
                    AiV3ResourceKind.audioRow,
                    stemExpectation['vocals_row_id'],
                  ),
                  'instrumental_row': (
                    AiV3ResourceKind.audioRow,
                    stemExpectation['instrumental_row_id'],
                  ),
                };
                for (final output in outputs.entries) {
                  final stableId = output.value.$2;
                  if (stableId == null) {
                    throw StateError('v3_resource_binding_missing_output');
                  }
                  v3WorkflowRuntime.bind(
                    ref: AiV3ResourceRef(
                      commandId: commandId,
                      output: output.key,
                    ),
                    kind: output.value.$1,
                    stableId: stableId,
                    parentRowRef: output.key == 'vocals_clip'
                        ? AiV3ResourceRef(
                            commandId: commandId,
                            output: 'vocals_row',
                          )
                        : output.key == 'instrumental_clip'
                        ? AiV3ResourceRef(
                            commandId: commandId,
                            output: 'instrumental_row',
                          )
                        : null,
                  );
                }
              }
              if (v3RuntimeExpectations != null) {
                if (commandId.isNotEmpty) {
                  stemExpectation['producer_command_id'] = commandId;
                  stemExpectation['producer_action_index'] = actionIndex;
                  for (final output in <String, Object?>{
                    'vocals_row': stemExpectation['vocals_row_id'],
                    'instrumental_row': stemExpectation['instrumental_row_id'],
                  }.entries) {
                    final rowId = output.value;
                    if (rowId is! int) {
                      throw StateError('v3_resource_binding_missing_output');
                    }
                    final rowIndex = _rowIndexForId(rowId);
                    if (!_isValidRowIndex(rowIndex) ||
                        _rows[rowIndex].isInstrumentLane) {
                      throw StateError('v3_resource_binding_target_mismatch');
                    }
                    _registerAiV3GeneratedRowExpectation(
                      v3RuntimeExpectations,
                      ref: AiV3ResourceRef(
                        commandId: commandId,
                        output: output.key,
                      ),
                      stableId: rowId,
                      kind: AiV3ResourceKind.audioRow,
                      name: _rows[rowIndex].name.trim(),
                      instrumentId: '',
                    );
                  }
                }
                _addAiV3Expectation(v3RuntimeExpectations, stemExpectation);
                for (final output in <String, Object?>{
                  'vocals_clip': stemExpectation['vocals_clip_id'],
                  'instrumental_clip': stemExpectation['instrumental_clip_id'],
                }.entries) {
                  final clipId = output.value;
                  if (clipId is! String || clipId.isEmpty) {
                    throw StateError('v3_resource_binding_missing_output');
                  }
                  if (commandId.isNotEmpty) {
                    final outputLengthKey = output.key == 'vocals_clip'
                        ? 'vocals_length'
                        : 'instrumental_length';
                    _registerAiV3GeneratedResourceExpectation(
                      v3RuntimeExpectations,
                      ref: AiV3ResourceRef(
                        commandId: commandId,
                        output: output.key,
                      ),
                      stableId: clipId,
                      kind: AiV3ResourceKind.audioClip,
                      start: (stemExpectation['start'] as num).toDouble(),
                      end:
                          (stemExpectation['start'] as num).toDouble() +
                          (stemExpectation[outputLengthKey] as num).toDouble(),
                      producerActionIndex: actionIndex,
                      durationFollowsTempo: false,
                      pitchSemitones: 0.0,
                    );
                  }
                }
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'v3_clip_convert_to_midi':
              final conversionExpectation =
                  await _applyAiV3ClipConvertToMidiAction(data);
              if (resolvedResourceRef != null &&
                  v3RuntimeExpectations != null) {
                _markAiV3ProducerOutputTransformed(
                  v3RuntimeExpectations,
                  resolvedResourceRef,
                );
              }
              final commandId = data['command_id']?.toString().trim() ?? '';
              if (commandId.isNotEmpty) {
                if (v3WorkflowRuntime == null ||
                    v3RuntimeExpectations == null) {
                  throw StateError('v3_resource_producer_context_missing');
                }
                final resultClipId =
                    conversionExpectation['result_clip_id']?.toString() ?? '';
                final resultIndex = _clipIndexForPersistentId(resultClipId);
                if (!_isValidClipIndex(resultIndex) ||
                    !_audioTracks[resultIndex].isMidi) {
                  throw StateError('v3_resource_binding_missing_output');
                }
                final result = _audioTracks[resultIndex];
                final rowIndex = _rowIndexForId(result.rowId);
                if (!_isValidRowIndex(rowIndex) ||
                    !_rows[rowIndex].isInstrumentLane ||
                    result.instrumentId != data['instrument_id']) {
                  throw StateError('v3_resource_binding_target_mismatch');
                }
                final rowRef = AiV3ResourceRef(
                  commandId: commandId,
                  output: 'midi_row',
                );
                final clipRef = AiV3ResourceRef(
                  commandId: commandId,
                  output: 'midi_clip',
                );
                v3WorkflowRuntime
                  ..bind(
                    ref: rowRef,
                    kind: AiV3ResourceKind.midiRow,
                    stableId: result.rowId,
                  )
                  ..bind(
                    ref: clipRef,
                    kind: AiV3ResourceKind.midiClip,
                    stableId: resultClipId,
                    parentRowRef: rowRef,
                  );
                conversionExpectation
                  ..['producer_command_id'] = commandId
                  ..['producer_action_index'] = actionIndex
                  ..['result_row_id'] = result.rowId;
                for (final expectation in v3RuntimeExpectations) {
                  if (expectation['kind'] == 'row_created') {
                    expectation
                      ..['expect_selected'] = false
                      ..['require_exact_position'] = false;
                  }
                }
                _registerAiV3GeneratedRowExpectation(
                  v3RuntimeExpectations,
                  ref: rowRef,
                  stableId: result.rowId,
                  kind: AiV3ResourceKind.midiRow,
                  name: _rows[rowIndex].name.trim(),
                  instrumentId: result.instrumentId,
                );
                _registerAiV3GeneratedResourceExpectation(
                  v3RuntimeExpectations,
                  ref: clipRef,
                  stableId: resultClipId,
                  kind: AiV3ResourceKind.midiClip,
                  start: result.offset,
                  end: result.offset + _clipTimelineDurationSec(result),
                  producerActionIndex: actionIndex,
                  durationFollowsTempo: true,
                  rowId: result.rowId,
                  midiNotes: _aiV3MidiNotePayload(result),
                );
              }
              if (v3RuntimeExpectations != null) {
                _addAiV3Expectation(
                  v3RuntimeExpectations,
                  conversionExpectation,
                );
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'effect_edit':
              await _applyEffectEditAction(data);
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'v3_effect_configure':
              final configuredExpectations =
                  await _applyAiV3EffectConfigureAction(data);
              if (v3RuntimeExpectations != null) {
                _addAiV3Expectations(
                  v3RuntimeExpectations,
                  configuredExpectations,
                );
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'v3_effect_instance_edit':
              await _applyAiV3EffectInstanceEditAction(data);
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'v3_phone_mic_cleanup':
              final cleanupExpectation = await _applyAiV3PhoneMicCleanupAction(
                data,
              );
              if (v3RuntimeExpectations != null &&
                  !v3RuntimeExpectations.any(
                    (expectation) =>
                        expectation['kind'] == 'row_deleted' &&
                        expectation['row_id'] == cleanupExpectation['row_id'],
                  )) {
                _addAiV3Expectation(v3RuntimeExpectations, cleanupExpectation);
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'v3_mix_actions':
              await applyV3MixActions(data);
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'v3_deferred_mix_goal':
              final commandId = data['command_id']?.toString().trim() ?? '';
              if (commandId.isEmpty) {
                throw StateError('v3_mix_command_id_missing');
              }
              var target = _actionTarget(data);
              final scope = target['scope']?.toString() ?? '';
              if (scope == 'group' && target['group_resource_ref'] != null) {
                if (v3WorkflowRuntime == null) {
                  throw StateError('v3_resource_producer_context_missing');
                }
                late final AiV3ResourceRef groupRef;
                try {
                  groupRef = AiV3ResourceRef.fromJson(
                    target['group_resource_ref'],
                  );
                } on FormatException {
                  throw StateError('v3_resource_ref_invalid');
                }
                final groupBinding = v3WorkflowRuntime.resolve(
                  groupRef,
                  expectedKind: AiV3ResourceKind.group,
                );
                final groupId = groupBinding.stableId;
                if (groupId is! String ||
                    !_trackGroups.any((group) => group.id == groupId)) {
                  throw StateError('v3_resource_binding_unavailable');
                }
                target = <String, dynamic>{
                  'scope': 'group',
                  'group_id': groupId,
                };
                data = <String, dynamic>{...data, 'target': target};
              }
              final reference = data['reference'];
              if (reference is Map && reference['row_id'] is int) {
                final referenceRowId = reference['row_id'] as int;
                final referenceRowIndex = _rowIndexForId(referenceRowId);
                if (!_isValidRowIndex(referenceRowIndex)) {
                  throw StateError('v3_mix_reference_id_unknown');
                }
                data = <String, dynamic>{
                  ...data,
                  'reference': <String, dynamic>{
                    ...Map<String, dynamic>.from(reference),
                    'row_index': referenceRowIndex,
                  },
                };
              }
              final project = await _buildCurrentAiProjectState();
              final allowedTargetRowIds = <int>{};
              int? requiredTargetRow;
              switch (scope) {
                case 'row':
                  final rowId = _toActionInt(target['row_id']);
                  if (rowId == null) {
                    throw StateError('v3_mix_action_target_invalid');
                  }
                  final rowIndex = _rowIndexForId(rowId);
                  if (!_isValidRowIndex(rowIndex) ||
                      _rowIdAt(rowIndex) != rowId) {
                    throw StateError('v3_mix_action_target_invalid');
                  }
                  target = <String, dynamic>{
                    ...target,
                    'row_id': rowId,
                    'row_index': rowIndex,
                  };
                  data = <String, dynamic>{...data, 'target': target};
                  final projectRow = project.rows
                      .where(
                        (row) => row.rowIndex == rowIndex && row.rowId == rowId,
                      )
                      .firstOrNull;
                  if (projectRow == null || projectRow.clips.isEmpty) {
                    throw StateError('v3_mix_audio_missing');
                  }
                  requiredTargetRow = rowIndex;
                  allowedTargetRowIds.add(rowId);
                  break;
                case 'group':
                  final groupId = target['group_id']?.toString().trim() ?? '';
                  final group = _trackGroups
                      .where((candidate) => candidate.id == groupId)
                      .firstOrNull;
                  if (group == null || group.rowIds.length < 2) {
                    throw StateError('v3_group_id_unknown');
                  }
                  allowedTargetRowIds.addAll(group.rowIds);
                  if (!project.rows.any(
                    (row) =>
                        allowedTargetRowIds.contains(row.rowId) &&
                        row.clips.isNotEmpty,
                  )) {
                    throw StateError('v3_mix_audio_missing');
                  }
                  break;
                case 'all_rows':
                  allowedTargetRowIds.addAll(
                    project.rows
                        .where((row) => row.clips.isNotEmpty)
                        .map((row) => row.rowId),
                  );
                  if (allowedTargetRowIds.isEmpty) {
                    throw StateError('v3_mix_audio_missing');
                  }
                  break;
                case 'master':
                  if (!project.rows.any((row) => row.clips.isNotEmpty)) {
                    throw StateError('v3_mix_audio_missing');
                  }
                  break;
                default:
                  throw StateError('v3_mix_action_target_invalid');
              }
              if (allowedTargetRowIds.any((rowId) => rowId < 0)) {
                throw StateError('v3_mix_audio_missing');
              }
              final materialized =
                  await AiV3MixGoalMaterializer(
                    mixModel: _mixModel,
                    magnitudePredictor: _magnitudePredictor,
                  ).materializeSingleGoal(
                    data: data,
                    project: project,
                    roleOverrides: aiV3CurrentRoleOverrides(project),
                    bypassLearnedMagnitudes: _producerDataMode,
                    requiredTargetRow: requiredTargetRow,
                    allowedTargetRowIds: scope == 'master'
                        ? null
                        : allowedTargetRowIds,
                    projectId: _projectId,
                  );
              if (materialized.isNoChange) {
                v3RuntimeAlreadySatisfiedCommandIds?.add(commandId);
              } else {
                final materializedData = <String, dynamic>{
                  'command_id': commandId,
                  'actions': materialized.actions
                      .map((action) {
                        final json = action.toJson();
                        return <String, dynamic>{
                          ...json,
                          'data': <String, dynamic>{
                            ...Map<String, dynamic>.from(json['data'] as Map),
                            'force_individual_row': true,
                          },
                        };
                      })
                      .toList(growable: false),
                  if (materialized.protectedReferenceRow != null)
                    'protected_reference_row_index':
                        materialized.protectedReferenceRow,
                };
                if (v3RuntimeExpectations != null) {
                  final simulatedRowGain = List<double>.from(_rowGain);
                  final simulatedRowPan = List<double>.from(_rowPan);
                  _captureAiV3MixExpectations(
                    v3RuntimeExpectations,
                    materializedData,
                    simulatedRowGain: simulatedRowGain,
                    simulatedRowPan: simulatedRowPan,
                    simulatedMasterMix: <String, double>{
                      'gain': _masterGain,
                      'pan': _masterPan,
                    },
                  );
                  for (final generatedRow in v3RuntimeExpectations.where(
                    (expectation) =>
                        expectation['kind'] == 'generated_row_state' &&
                        allowedTargetRowIds.contains(expectation['row_id']),
                  )) {
                    final generatedRowIndex = _rowIndexForId(
                      generatedRow['row_id'] as int,
                    );
                    if (_isValidRowIndex(generatedRowIndex)) {
                      generatedRow
                        ..['gain'] = simulatedRowGain[generatedRowIndex]
                        ..['pan'] = simulatedRowPan[generatedRowIndex];
                    }
                  }
                }
                await applyV3MixActions(materializedData);
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'v3_automation_points':
              final automationExpectation =
                  await _applyAiV3AutomationPointsAction(data);
              if (v3RuntimeExpectations != null) {
                automationExpectation['producer_action_index'] = actionIndex;
                _addAiV3Expectation(
                  v3RuntimeExpectations,
                  automationExpectation,
                );
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'automation_edit':
              await _applyAutomationEditAction(data);
              if (v3RuntimeExpectations != null) {
                final target = _actionTarget(data);
                final rowId = _toActionInt(target['row_id']);
                final row = rowId == null ? null : _rowIndexForId(rowId);
                if (row != null && _isValidRowIndex(row)) {
                  _addAiV3Expectation(v3RuntimeExpectations, <String, dynamic>{
                    'kind': 'automation_points',
                    'producer_action_index': actionIndex,
                    'row': row,
                    'row_id': rowId,
                    'automation_target_id':
                        target['automation_target_id']?.toString() ?? 'volume',
                    'points': (data['points'] as List? ?? const <Object>[])
                        .whereType<Map>()
                        .map(
                          (point) => <String, dynamic>{
                            'x': _toActionDouble(
                              point['time_ms'] ?? point['x_ms'] ?? point['x'],
                            ),
                            'value': _toActionDouble(
                              point['value'] ?? point['volume'],
                            ),
                          },
                        )
                        .toList(growable: false),
                  });
                }
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'midi_compose':
              final operation = data['operation']?.toString() ?? '';
              final producerCommandId =
                  data['command_id']?.toString().trim() ?? '';
              final beforeMidiClipIds =
                  operation == 'create_clip' &&
                      producerCommandId.isNotEmpty &&
                      v3WorkflowRuntime != null
                  ? _audioTracks
                        .where((clip) => clip.isMidi)
                        .map((clip) => clip.clipId)
                        .toSet()
                  : const <String>{};
              await _applyMidiComposeAction(data, chatFlowId: chatFlowId);
              if (beforeMidiClipIds.isNotEmpty ||
                  (operation == 'create_clip' &&
                      producerCommandId.isNotEmpty &&
                      v3WorkflowRuntime != null)) {
                final created = _audioTracks
                    .where(
                      (clip) =>
                          clip.isMidi &&
                          !beforeMidiClipIds.contains(clip.clipId),
                    )
                    .toList(growable: false);
                if (created.length != 1) {
                  throw StateError('v3_resource_binding_missing_output');
                }
                final createdClip = created.single;
                final createdClipId = createdClip.clipId;
                v3WorkflowRuntime!.bind(
                  ref: AiV3ResourceRef(
                    commandId: producerCommandId,
                    output: 'midi_clip',
                  ),
                  kind: AiV3ResourceKind.midiClip,
                  stableId: createdClipId,
                  parentRowRef: resolvedResourceKind == AiV3ResourceKind.midiRow
                      ? resolvedResourceRef
                      : null,
                );
                if (v3RuntimeExpectations != null) {
                  final expectation = v3RuntimeExpectations
                      .where(
                        (candidate) =>
                            candidate['kind'] == 'midi_clip_created' &&
                            candidate['producer_command_id'] ==
                                producerCommandId,
                      )
                      .firstOrNull;
                  if (expectation == null) {
                    throw StateError('v3_resource_expectation_missing');
                  }
                  final expectedStart = (expectation['start'] as num)
                      .toDouble();
                  final expectedLength = (expectation['length'] as num)
                      .toDouble();
                  if ((createdClip.offset - expectedStart).abs() > 0.002 ||
                      (_clipTimelineDurationSec(createdClip) - expectedLength)
                              .abs() >
                          0.003 ||
                      createdClip.rowIndex != expectation['row'] ||
                      createdClip.instrumentId !=
                          expectation['instrument_id']) {
                    throw StateError('v3_resource_binding_target_mismatch');
                  }
                  expectation['runtime_clip_id'] = createdClipId;
                  _registerAiV3GeneratedResourceExpectation(
                    v3RuntimeExpectations,
                    ref: AiV3ResourceRef(
                      commandId: producerCommandId,
                      output: 'midi_clip',
                    ),
                    stableId: createdClipId,
                    kind: AiV3ResourceKind.midiClip,
                    start: createdClip.offset,
                    end:
                        createdClip.offset +
                        _clipTimelineDurationSec(createdClip),
                    producerActionIndex: actionIndex,
                    durationFollowsTempo: true,
                    midiNotes: (expectation['notes'] as List)
                        .whereType<Map>()
                        .map((note) => Map<String, dynamic>.from(note))
                        .toList(growable: false),
                  );
                }
              }
              if ((operation == 'transpose_notes' ||
                      operation == 'replace_notes') &&
                  resolvedResourceClipId != null &&
                  resolvedResourceRef != null &&
                  resolvedResourceKind == AiV3ResourceKind.midiClip &&
                  v3RuntimeExpectations != null) {
                final expectedNotes = (data['expected_notes'] as List?)
                    ?.whereType<Map>()
                    .map((note) => Map<String, dynamic>.from(note))
                    .toList(growable: false);
                if (expectedNotes == null) {
                  throw StateError('v3_resource_midi_notes_missing');
                }
                final resourceExpectation = _aiV3GeneratedResourceExpectation(
                  v3RuntimeExpectations,
                  resolvedResourceRef,
                );
                resourceExpectation
                  ..['midi_notes'] = aiV3CanonicalMidiNotes(expectedNotes)
                  ..['midi_content_end_beats'] =
                      _toActionDouble(
                        data['expected_midi_content_end_beats'],
                      ) ??
                      _aiV3MidiContentEndBeats(expectedNotes);
                final rawFinalLength = data['final_length_beats'];
                if (rawFinalLength != null) {
                  final finalLength = (rawFinalLength as num).toDouble();
                  final start = (resourceExpectation['start'] as num)
                      .toDouble();
                  if (!finalLength.isFinite || finalLength <= 0) {
                    throw StateError('v3_resource_midi_length_invalid');
                  }
                  resourceExpectation['end'] =
                      start + finalLength * 60.0 / _tempo;
                }
                _markAiV3ProducerOutputTransformed(
                  v3RuntimeExpectations,
                  resolvedResourceRef,
                );
              }
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'stem_separate':
              await _applyStemSeparateAction(data);
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'role_override':
              await _applyRoleOverrideAction(data);
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'audio_enhance':
            case 'recording_cleanup':
              await _applyAudioEnhancementAction(data);
              if (chatFlowId != null) {
                _throwIfChatFlowStopped(chatFlowId);
              }
              break;
            case 'clarify':
              final q = (data['question'] ?? '').toString().trim();
              if (q.isNotEmpty) {
                final options = _actionStringList(data['options']);
                if (options.isEmpty) {
                  _insertAssistantChatText(q, modelAuthored: true);
                } else {
                  _insertAssistantChatText(
                    '$q\n\nOptions: ${options.join(' / ')}',
                    modelAuthored: true,
                  );
                }
              }
              break;
            default:
              break;
          }
        } on _ChatFlowCancelledException {
          rethrow;
        } catch (e, st) {
          debugPrint('Assistant action failed ($type): $e\n$st');
          hadFailure = true;
          throw _AssistantActionApplyException(
            actionType: type,
            cause: e,
            stackTrace: st,
          );
        }
      }
      return !hadFailure &&
          _assistantActionExecutionMessageCount == executionMessagesBefore;
    } finally {
      _assistantActionNoticeCaptureDepth -= 1;
      if (batchExecutionNotices) {
        _assistantActionExecutionBatchDepth -= 1;
        if (_assistantActionExecutionBatchDepth <= 0) {
          _assistantActionExecutionBatchDepth = 0;
          _flushAssistantActionExecutionBatch();
        }
      }
    }
  }

  String _normalizeRowGroupEditOperation(String raw) {
    switch (raw.trim().toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '_')) {
      case 'create':
      case 'create_group':
      case 'group':
      case 'group_rows':
        return 'create';
      case 'remove_row':
      case 'ungroup_row':
      case 'remove_from_group':
        return 'remove_row';
      case 'toggle':
      case 'toggle_collapsed':
      case 'fold':
      case 'unfold':
      case 'collapse':
      case 'expand':
        return 'toggle_collapsed';
      default:
        return raw.trim().toLowerCase();
    }
  }

  String? _resolveRowGroupIdFromAction(Map<String, dynamic> data) {
    final target = _actionTarget(data);
    final candidates =
        <String>[
              (data['group_id'] ?? '').toString(),
              (target['group_id'] ?? '').toString(),
            ]
            .map((value) => value.trim())
            .where((value) => value.isNotEmpty)
            .toList(growable: false);
    for (final candidate in candidates) {
      for (final group in _trackGroups) {
        if (group.id == candidate) return group.id;
      }
    }

    final nameCandidates =
        <String>[
              (data['group_name'] ?? '').toString(),
              (target['group_name'] ?? '').toString(),
              (data['name'] ?? '').toString(),
            ]
            .map((value) => value.trim().toLowerCase())
            .where((value) => value.isNotEmpty)
            .toList(growable: false);
    for (final candidate in nameCandidates) {
      for (final group in _trackGroups) {
        final name = group.name.trim().toLowerCase();
        if (name == candidate ||
            (name.isNotEmpty && name.contains(candidate)) ||
            (candidate.contains('group') && candidate.contains(name))) {
          return group.id;
        }
      }
    }

    final row = _resolveActionRowIndexFromData(
      data,
      includeSelectionFallback: false,
    );
    if (row != null && row >= 0 && row < _rows.length) {
      final groupId = _rows[row].groupId.trim();
      if (groupId.isNotEmpty) return groupId;
    }
    return null;
  }

  Future<void> _applyRowGroupEditAction(Map<String, dynamic> data) async {
    final operation = _normalizeRowGroupEditOperation(
      (data['operation'] ?? '').toString(),
    );
    switch (operation) {
      case 'create':
        {
          final rows = _resolveRowIndicesFromActionTarget(
            data,
            includeSelectionFallback: false,
          );
          if (rows.length < 2) {
            _insertAssistantChatText(
              'Select or specify at least two rows to group.',
            );
            return;
          }
          final name = (data['group_name'] ?? data['name'] ?? '')
              .toString()
              .trim();
          final color = _toActionInt(data['color']);
          await _createRowGroup(
            rows,
            name: name.isEmpty ? null : name,
            color: color,
          );
          _insertSystemChatText(
            '• Created ${name.isEmpty ? 'row group' : name} from ${rows.length} rows •',
          );
          return;
        }
      case 'remove_row':
        {
          final row = _resolveRowIndexFromActionTarget(data);
          if (row == null) {
            _insertAssistantChatText(
              "I couldn't resolve which row to ungroup.",
            );
            return;
          }
          await _removeRowFromGroup(row);
          _insertSystemChatText(
            '• Removed ${_rowDisplayName(row)} from its group •',
          );
          return;
        }
      case 'toggle_collapsed':
        {
          final groupId = _resolveRowGroupIdFromAction(data);
          if (groupId == null || groupId.isEmpty) {
            _insertAssistantChatText(
              "I couldn't resolve which group to fold or unfold.",
            );
            return;
          }
          await _toggleRowGroupCollapsed(groupId);
          return;
        }
      default:
        _insertAssistantChatText("I couldn't apply that row group edit.");
    }
  }

  int? _resolveRowColorFromAction(Map<String, dynamic> data) {
    final target = _actionTarget(data);
    final explicit = _toActionInt(
      data['color'] ??
          target['color'] ??
          data['argb'] ??
          target['argb'] ??
          data['value'] ??
          target['value'],
    );
    if (explicit != null) return explicit < 0 ? 0 : explicit;

    final rawName =
        (data['color_name'] ??
                target['color_name'] ??
                data['name'] ??
                target['name'] ??
                data['color'])
            ?.toString()
            .trim()
            .toLowerCase();
    if (rawName == null || rawName.isEmpty) return null;
    switch (rawName.replaceAll(RegExp(r'[^a-z0-9]+'), '_')) {
      case 'none':
      case 'clear':
      case 'default':
      case 'unset':
        return 0;
      case 'red':
      case 'pink':
      case 'coral':
        return const Color(0xFFFF6F7D).toARGB32();
      case 'orange':
      case 'amber':
        return const Color(0xFFFFA654).toARGB32();
      case 'yellow':
      case 'gold':
        return const Color(0xFFFFDD66).toARGB32();
      case 'green':
      case 'lime':
        return const Color(0xFF69E080).toARGB32();
      case 'cyan':
      case 'aqua':
      case 'teal':
        return const Color(0xFF6BD7F0).toARGB32();
      case 'blue':
        return const Color(0xFF79A8FF).toARGB32();
      case 'purple':
      case 'violet':
        return const Color(0xFFC78DFF).toARGB32();
      case 'magenta':
      case 'fuchsia':
        return const Color(0xFFFF7FE3).toARGB32();
      default:
        return null;
    }
  }

  Future<void> _applyRowColorEditAction(Map<String, dynamic> data) async {
    final operation = (data['operation'] ?? 'set')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_');
    if (operation != 'set' && operation != 'clear') {
      _insertAssistantChatText("I couldn't apply that row color edit.");
      return;
    }

    final rows = _resolveRowIndicesFromActionTarget(
      data,
      includeSelectionFallback: true,
    );
    if (rows.isEmpty) {
      _insertAssistantChatText("I couldn't resolve which row to color.");
      return;
    }

    final color = operation == 'clear' ? 0 : _resolveRowColorFromAction(data);
    if (color == null) {
      _insertAssistantChatText("I couldn't resolve which color to use.");
      return;
    }

    for (final row in rows) {
      await _setRowColor(row, color);
    }
    _insertSystemChatText(
      color == 0
          ? '• Cleared row color on ${rows.length} ${rows.length == 1 ? 'row' : 'rows'} •'
          : '• Changed row color on ${rows.length} ${rows.length == 1 ? 'row' : 'rows'} •',
    );
  }

  Future<void> _applyRowMuteAction(Map<String, dynamic> data) async {
    final operation = (data['operation'] ?? 'mute')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_');
    if (operation != 'mute' &&
        operation != 'unmute' &&
        operation != 'toggle' &&
        operation != 'set_muted') {
      _insertAssistantChatText(
        L10n.translate(context, "I couldn't apply that row mute edit."),
      );
      return;
    }
    final requestedMuted = data['muted'];
    if (operation == 'set_muted' && requestedMuted is! bool) {
      _insertAssistantChatText(
        L10n.translate(context, "I couldn't apply that row mute edit."),
      );
      return;
    }

    final rows = _resolveRowIndicesFromActionTarget(
      data,
      includeSelectionFallback: true,
    );
    if (rows.isEmpty) {
      _insertAssistantChatText("I couldn't resolve which row to mute.");
      return;
    }

    for (final row in rows) {
      final current = row < _rowMuted.length ? _rowMuted[row] : false;
      final nextMuted = operation == 'toggle'
          ? !current
          : operation == 'set_muted'
          ? requestedMuted as bool
          : operation == 'mute';
      await _setRowMutedFromUi(row, nextMuted);
    }
    final actionText = operation == 'toggle'
        ? 'Toggled mute'
        : operation == 'mute' ||
              (operation == 'set_muted' && requestedMuted == true)
        ? 'Muted'
        : 'Unmuted';
    _insertSystemChatText(
      '• $actionText ${rows.length} ${rows.length == 1 ? 'row' : 'rows'} •',
    );
  }

  Future<void> _applyRowSoloAction(Map<String, dynamic> data) async {
    final token = (data['operation'] ?? 'solo')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_');
    final operation = switch (token) {
      'set_soloed' => 'set_soloed',
      'solo' ||
      'solo_row' ||
      'solo_track' ||
      'track_solo' ||
      'row_solo' => 'solo',
      'unsolo' ||
      'un_solo' ||
      'unsolo_row' ||
      'unsolo_track' ||
      'un_solo_row' ||
      'un_solo_track' ||
      'clear_solo' => 'unsolo',
      'toggle' ||
      'toggle_solo' ||
      'toggle_row_solo' ||
      'toggle_track_solo' => 'toggle',
      _ => token,
    };
    if (operation != 'solo' &&
        operation != 'unsolo' &&
        operation != 'toggle' &&
        operation != 'set_soloed') {
      _insertAssistantChatText(
        L10n.translate(context, "I couldn't apply that row solo edit."),
      );
      return;
    }
    final requestedSoloed = data['soloed'];
    if (operation == 'set_soloed' && requestedSoloed is! bool) {
      _insertAssistantChatText(
        L10n.translate(context, "I couldn't apply that row solo edit."),
      );
      return;
    }

    final rows = _resolveRowIndicesFromActionTarget(
      data,
      includeSelectionFallback: true,
    );
    if (rows.isEmpty) {
      _insertAssistantChatText("I couldn't resolve which row to solo.");
      return;
    }

    for (final row in rows) {
      final current = row < _rowSoloed.length ? _rowSoloed[row] : false;
      final nextSoloed = operation == 'toggle'
          ? !current
          : operation == 'set_soloed'
          ? requestedSoloed as bool
          : operation == 'solo';
      await _setRowSoloedFromUi(row, nextSoloed);
    }
    final actionText = operation == 'toggle'
        ? 'Toggled solo'
        : operation == 'solo' ||
              (operation == 'set_soloed' && requestedSoloed == true)
        ? 'Soloed'
        : 'Unsoloed';
    _insertSystemChatText(
      '• $actionText ${rows.length} ${rows.length == 1 ? 'row' : 'rows'} •',
    );
  }

  Future<void> _applyRowRenameAction(Map<String, dynamic> data) async {
    final token = (data['operation'] ?? 'rename')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_');
    final operation = switch (token) {
      'rename' ||
      'rename_row' ||
      'rename_track' ||
      'track_rename' ||
      'row_rename' ||
      'set_name' ||
      'set_row_name' ||
      'set_track_name' => 'rename',
      _ => token,
    };
    if (operation != 'rename') {
      _insertAssistantChatText("I couldn't apply that row rename edit.");
      return;
    }

    final rows = _resolveRowIndicesFromActionTarget(
      data,
      includeSelectionFallback: true,
    );
    if (rows.length != 1) {
      _insertAssistantChatText("I couldn't resolve which row to rename.");
      return;
    }

    final target = _actionTarget(data);
    final rawName =
        (data['name'] ??
                data['new_name'] ??
                target['name'] ??
                target['new_name'])
            ?.toString()
            .trim() ??
        '';
    final safeName = rawName.replaceAll(RegExp(r'\s+'), ' ').trim();
    if (safeName.isEmpty) {
      _insertAssistantChatText("I couldn't resolve the new row name.");
      return;
    }

    final row = rows.single;
    final appliedName = safeName.length > 80
        ? safeName.substring(0, 80)
        : safeName;
    await _renameRow(row, appliedName);
    _insertSystemChatText('• Renamed row to $appliedName •');
