  Future<void> _applyRowSelectAction(Map<String, dynamic> data) async {
    final token = (data['operation'] ?? 'select')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_');
    final operation = switch (token) {
      'select' ||
      'select_row' ||
      'select_track' ||
      'focus' ||
      'focus_row' ||
      'focus_track' ||
      'make_active' ||
      'activate' => 'select',
      _ => token,
    };
    if (operation != 'select') {
      _insertAssistantChatText("I couldn't apply that row select edit.");
      return;
    }

    final rows = _resolveRowIndicesFromActionTarget(
      data,
      includeSelectionFallback: false,
    );
    if (rows.length != 1) {
      _insertAssistantChatText("I couldn't resolve which row to select.");
      return;
    }

    final row = rows.single.clamp(0, _rowCount - 1).toInt();
    final previousRowId = _isValidRowIndex(_selectedRow)
        ? _rowIdAt(_selectedRow)
        : null;
    final finalRowId = _rowIdAt(row);
    if (previousRowId == finalRowId) return;
    await _undoManager.execute(
      RowSelectionUndoAction(
        previousRowId: previousRowId,
        finalRowId: finalRowId,
        applySelection: _applyRowSelectionUndoState,
      ),
    );
    _insertSystemChatText('• Selected ${_rowDisplayName(row)} •');
  }

  Future<void> _applyRowSelectionUndoState(int? rowId) async {
    if (rowId == null) {
      setState(() => _selectedRow = -1);
      return;
    }
    final row = _rowIndexForId(rowId);
    if (!_isValidRowIndex(row)) {
      throw StateError('row_selection_undo_target_missing');
    }
    setState(() => _selectedRow = row);
  }

  Future<void> _applyAiV3RowRoleOverrideAction(
    Map<String, dynamic> data,
  ) async {
    final target = _actionTarget(data);
    final rowId = _toActionInt(target['row_id']);
    final row = rowId == null ? -1 : _rowIndexForId(rowId);
    if (rowId == null || !_isValidRowIndex(row)) {
      throw StateError('v3_row_role_override_target_missing');
    }
    final role = data['role']?.toString().trim() ?? '';
    if (role.isNotEmpty && !kTrackRoleOverrideValues.contains(role)) {
      throw StateError('v3_row_role_override_value_invalid');
    }
    final previousRole = _rows[row].roleOverride.trim();
    if (previousRole == role) return;
    await _undoManager.execute(
      RowRoleOverrideUndoAction(
        rowId: rowId,
        oldRole: previousRole,
        newRole: role,
        applyRole: _applyAiV3RowRoleOverrideState,
      ),
    );
    _insertSystemChatText(
      role.isEmpty
          ? '• Cleared role override for ${_rowDisplayName(row)} •'
          : '• Set ${_rowDisplayName(row)} role to $role •',
    );
  }

  Future<void> _applyAiV3RowRoleOverrideState({
    required int rowId,
    required String role,
  }) async {
    final row = _rowIndexForId(rowId);
    if (!_isValidRowIndex(row)) {
      throw StateError('v3_row_role_override_target_stale');
    }
    if (role.isNotEmpty && !kTrackRoleOverrideValues.contains(role)) {
      throw StateError('v3_row_role_override_value_invalid');
    }
    if (role.isEmpty) {
      _chatPipeline.clearRoleOverride(row);
    } else {
      final applied = _chatPipeline.setRoleOverride(rowIndex: row, role: role);
      if (!applied) {
        throw StateError('v3_row_role_override_apply_failed');
      }
    }
    _setStateAndRefreshProjectSettings(() {
      _rows[row] = _rows[row].copyWith(roleOverride: role);
    });
    _scheduleProjectAutosave();
  }

  Future<Map<String, dynamic>> _applyAiV3RowSetInstrumentAction(
    Map<String, dynamic> data,
  ) async {
    final target = _actionTarget(data);
    final rowId = _toActionInt(target['row_id']);
    final row = rowId == null ? -1 : _rowIndexForId(rowId);
    if (rowId == null || !_isValidRowIndex(row)) {
      throw StateError('v3_row_instrument_target_missing');
    }
    if (!_rows[row].isInstrumentLane) {
      throw StateError('v3_row_instrument_target_invalid');
    }
    final originalRowName = _rows[row].name;
    final instrumentId = data['instrument_id']?.toString().trim() ?? '';
    if (instrumentId.isEmpty) {
      throw StateError('v3_row_instrument_id_invalid');
    }
    final matches = _uiInstrumentCatalog()
        .where((spec) => (spec['id']?.toString().trim() ?? '') == instrumentId)
        .toList(growable: false);
    if (matches.length != 1) {
      throw StateError('v3_row_instrument_unavailable');
    }
    final destinationLane = _instrumentLaneRowFromSpec(matches.single);
    final destinationInstrumentName =
        destinationLane.instrumentName.trim().isEmpty
        ? _instrumentNameFromId(destinationLane.instrumentId)
        : destinationLane.instrumentName.trim();
    final clipsBefore = _audioTracks
        .where((clip) => clip.isMidi && clip.rowId == rowId)
        .toList(growable: false);
    final clipIds =
        clipsBefore.map((clip) => clip.clipId).toList(growable: false)..sort();
    final expectedClipLabels = <String, String>{
      for (final clip in clipsBefore)
        clip.clipId:
            shouldMidiClipLabelFollowInstrument(
              label: clip.label,
              instrumentName: clip.instrumentName,
            )
            ? destinationInstrumentName
            : clip.label,
    };
    final localizedNoticeTemplate = L10n.translate(
      context,
      'Changed {row} instrument to {instrument}',
    );
    await _changeInstrumentLaneToSpec(
      row,
      matches.single,
      preserveRowName: true,
      recordManualEdit: false,
    );
    final resolvedRow = _rowIndexForId(rowId);
    if (!_isValidRowIndex(resolvedRow)) {
      throw StateError('v3_row_instrument_target_stale');
    }
    final lane = _rows[resolvedRow];
    final instrumentName = lane.instrumentName.trim().isEmpty
        ? _instrumentNameFromId(lane.instrumentId)
        : lane.instrumentName.trim();
    final localizedNotice = localizedNoticeTemplate
        .replaceAll('{row}', _rowDisplayName(resolvedRow))
        .replaceAll('{instrument}', instrumentName);
    _insertSystemChatText('• $localizedNotice •');
    return <String, dynamic>{
      'kind': 'row_instrument',
      'row_id': rowId,
      'row_name': originalRowName,
      'instrument_id': lane.instrumentId,
      'instrument_name': lane.instrumentName,
      'instrument_params': Map<String, double>.from(lane.instrumentParams),
      'clip_ids': clipIds,
      'clip_labels': expectedClipLabels,
    };
  }

  Future<void> _applyRowDeleteAction(Map<String, dynamic> data) async {
    final token = (data['operation'] ?? 'delete')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    final operation = switch (token) {
      'delete' ||
      'remove' ||
      'delete_row' ||
      'delete_track' ||
      'remove_row' ||
      'remove_track' ||
      'trash' ||
      'trash_row' ||
      'trash_track' => 'delete',
      _ => token,
    };
    if (operation != 'delete') {
      _insertAssistantChatText("I couldn't apply that row delete edit.");
      return;
    }

    final rows = _resolveRowIndicesFromActionTarget(
      data,
      includeSelectionFallback: true,
    );
    if (rows.length != 1) {
      _insertAssistantChatText("I couldn't resolve which row to delete.");
      return;
    }

    final row = rows.single;
    if (row < 0 || row >= _rowCount) {
      _insertAssistantChatText("I couldn't resolve which row to delete.");
      return;
    }

    final name = _rowDisplayName(row);
    await _deleteRow(row);
    _insertSystemChatText('• Deleted $name •');
  }

  Future<int?> _applyRowCreateAction(Map<String, dynamic> data) async {
    final token = (data['operation'] ?? 'create')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    final operation = switch (token) {
      'create' ||
      'add' ||
      'new' ||
      'create_row' ||
      'create_track' ||
      'add_row' ||
      'add_track' ||
      'new_row' ||
      'new_track' ||
      'insert_row' ||
      'insert_track' => 'create',
      _ => token,
    };
    if (operation != 'create') {
      _insertAssistantChatText("I couldn't apply that row create edit.");
      return null;
    }

    if (_rowCount >= _effectiveMaxRows) {
      _insertAssistantChatText(
        "I couldn't create another row because the row limit is reached.",
      );
      return null;
    }

    final target = _actionTarget(data);
    final positionToken = (data['position'] ?? target['position'] ?? 'end')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    final position = switch (positionToken) {
      'above' || 'before' || 'insert_above' || 'above_target' => 'above',
      'below' ||
      'after' ||
      'under' ||
      'insert_below' ||
      'below_target' => 'below',
      'end' ||
      'bottom' ||
      'last' ||
      'append' ||
      'after_last' ||
      'at_end' => 'end',
      _ => positionToken,
    };
    if (position != 'end' && position != 'above' && position != 'below') {
      _insertAssistantChatText("I couldn't resolve where to create the row.");
      return null;
    }

    int? referenceRow;
    if (position == 'above' || position == 'below') {
      final rows = _resolveRowIndicesFromActionTarget(
        data,
        includeSelectionFallback: true,
      );
      if (rows.length != 1) {
        _insertAssistantChatText("I couldn't resolve where to create the row.");
        return null;
      }
      referenceRow = rows.single;
      if (referenceRow < 0 || referenceRow >= _rowCount) {
        _insertAssistantChatText("I couldn't resolve where to create the row.");
        return null;
      }
    }

    final rawName =
        (data['name'] ??
                data['new_name'] ??
                target['name'] ??
                target['new_name'])
            ?.toString()
            .trim() ??
        '';
    final safeName = rawName.replaceAll(RegExp(r'\s+'), ' ').trim();
    final appliedName = safeName.length > 80
        ? safeName.substring(0, 80)
        : safeName;
    if (appliedName.isEmpty) {
      _insertAssistantChatText("I couldn't resolve the new row name.");
      return null;
    }

    final laneKind = (data['lane_kind'] ?? 'audio')
        .toString()
        .trim()
        .toLowerCase();
    final midi = laneKind == 'instrument' || laneKind == 'midi';
    final instrumentId = data['instrument_id']?.toString().trim() ?? '';
    if (midi && instrumentId.isEmpty) {
      _insertAssistantChatText("I couldn't resolve the MIDI instrument.");
      return null;
    }
    final referenceRowId = referenceRow == null ? null : _rowIdAt(referenceRow);
    final previousSelectedRowId = _isValidRowIndex(_selectedRow)
        ? _rowIdAt(_selectedRow)
        : null;
    final action = RowCreateUndoAction(
      previousSelectedRowId: previousSelectedRowId,
      persistedDescriptor: <String, dynamic>{
        'name': appliedName,
        'midi': midi,
        'instrumentId': instrumentId,
        'position': position,
        'referenceRowId': referenceRowId,
      },
      createRow: (preferredRowId) => _createAiRow(
        name: appliedName,
        midi: midi,
        instrumentId: instrumentId,
        position: position,
        referenceRowId: referenceRowId,
        preferredRowId: preferredRowId,
      ),
      deleteRow: _deleteAiCreatedRow,
      applySelection: _applyRowSelectionUndoState,
    );
    await _undoManager.execute(action);
    final createdRow = _rowIndexForId(action.currentRowId);
    if (!_isValidRowIndex(createdRow)) {
      throw StateError('row_create_result_missing');
    }
    _insertSystemChatText('• Created ${_rowDisplayName(createdRow)} •');
    return action.currentRowId;
  }

  Future<int> _createAiRow({
    required String name,
    required bool midi,
    required String instrumentId,
    required String position,
    required int? referenceRowId,
    int? preferredRowId,
  }) async {
    if (_rowCount >= _effectiveMaxRows) {
      throw StateError('row_create_capacity_exceeded');
    }
    int? referenceRow;
    if (position != 'end') {
      referenceRow = referenceRowId == null
          ? null
          : _rowIndexForId(referenceRowId);
      if (referenceRow == null || !_isValidRowIndex(referenceRow)) {
        throw StateError('row_create_anchor_missing');
      }
    }
    final beforeIds = _rows.map((row) => row.rowId).toSet();
    bool created;
    if (midi) {
      final spec = _instrumentSpecById(instrumentId);
      final instrumentName = _instrumentNameFromId(instrumentId);
      final lane = TimelineRow(
        rowId: -1,
        name: name,
        iconId: 1,
        kind: TimelineRowKind.instrument,
        instrumentId: instrumentId,
        instrumentName: instrumentName,
        instrumentParams: _instrumentParamsFromSpec(spec),
      );
      created = position == 'end'
          ? await _addInstrumentLaneImpl(lane, preferredRowId: preferredRowId)
          : await _insertInstrumentLaneImpl(
              referenceRow!,
              lane,
              above: position == 'above',
              preferredRowId: preferredRowId,
            );
    } else {
      created = position == 'end'
          ? await _addRowImpl(preferredRowId: preferredRowId)
          : position == 'above'
          ? await _insertRowAboveImpl(
              referenceRow!,
              preferredRowId: preferredRowId,
            )
          : await _insertRowBelowImpl(
              referenceRow!,
              preferredRowId: preferredRowId,
            );
    }
    if (!created) throw StateError('row_create_failed');
    final createdRows = _rows.where((row) => !beforeIds.contains(row.rowId));
    if (createdRows.length != 1) throw StateError('row_create_result_invalid');
    final createdRowId = createdRows.single.rowId;
    final createdIndex = _rowIndexForId(createdRowId);
    if (!midi && !await _renameRowImpl(createdIndex, name)) {
      await _deleteAiCreatedRow(createdRowId);
      throw StateError('row_create_rename_failed');
    }
    return createdRowId;
  }

  Future<void> _deleteAiCreatedRow(int rowId) async {
    final row = _rowIndexForId(rowId);
    if (!_isValidRowIndex(row) || !await _deleteRowImpl(row)) {
      throw StateError('row_create_undo_target_missing');
    }
  }

  String _normalizeRowMixOperation(Object? raw) {
    final token = (raw ?? '')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    return switch (token) {
      'set' ||
      'set_gain' ||
      'gain' ||
      'volume' ||
      'set_volume' ||
      'track_volume' ||
      'row_volume' ||
      'fader' ||
      'set_fader' => 'set_gain',
      'adjust' ||
      'adjust_gain' ||
      'change_gain' ||
      'gain_up' ||
      'gain_down' ||
      'volume_up' ||
      'volume_down' ||
      'turn_up' ||
      'turn_down' ||
      'make_louder' ||
      'make_quieter' => 'adjust_gain',
      'pan' ||
      'set_pan' ||
      'pan_to' ||
      'center_pan' ||
      'pan_center' ||
      'pan_left' ||
      'pan_right' => 'set_pan',
      'adjust_pan' ||
      'pan_more_left' ||
      'pan_more_right' ||
      'move_left' ||
      'move_right' => 'adjust_pan',
      _ => token,
    };
  }

  double? _rowMixDoubleFrom(Map<String, dynamic> data, List<String> keys) {
    final target = _actionTarget(data);
    for (final key in keys) {
      final parsed = _toActionDouble(data[key] ?? target[key]);
      if (parsed != null && parsed.isFinite) return parsed;
    }
    return null;
  }

  String _rowMixDirection(Map<String, dynamic> data) {
    final target = _actionTarget(data);
    return (data['direction'] ?? target['direction'] ?? '')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
  }

  double? _resolveRowMixGainValue(
    Map<String, dynamic> data, {
    required double oldGain,
    required String operation,
  }) {
    final absoluteDb = _rowMixDoubleFrom(data, const [
      'gain_db',
      'db',
      'decibels',
    ]);
    final absoluteLinear = _rowMixDoubleFrom(data, const [
      'value',
      'gain',
      'linear_gain',
      'gain_linear',
    ]);
    final percent = _rowMixDoubleFrom(data, const [
      'percent',
      'gain_percent',
      'volume_percent',
    ]);
    final deltaDb = _rowMixDoubleFrom(data, const [
      'delta_db',
      'db_delta',
      'gain_delta_db',
    ]);
    final deltaLinear = _rowMixDoubleFrom(data, const [
      'delta',
      'gain_delta',
      'volume_delta',
    ]);
    final direction = _rowMixDirection(data);

    if (operation == 'set_gain') {
      if (absoluteDb != null) return rowGainDbToUi(absoluteDb);
      if (absoluteLinear != null) {
        return absoluteLinear.clamp(0.0, 3.0).toDouble();
      }
      if (percent != null) return (percent / 100.0).clamp(0.0, 3.0).toDouble();
    }

    if (operation == 'adjust_gain' ||
        direction == 'up' ||
        direction == 'down') {
      if (deltaDb != null) {
        return adjustRowGainUiByDb(oldGain, deltaDb);
      }
      if (deltaLinear != null) {
        return (oldGain + deltaLinear).clamp(0.0, 3.0).toDouble();
      }
      if (direction == 'up') {
        return adjustRowGainUiByDb(oldGain, 3.0);
      }
      if (direction == 'down') {
        return adjustRowGainUiByDb(oldGain, -3.0);
      }
    }

    if (absoluteDb != null) return rowGainDbToUi(absoluteDb);
    if (absoluteLinear != null) {
      return absoluteLinear.clamp(0.0, 3.0).toDouble();
    }
    return null;
  }

  double? _resolveRowMixPanValue(
    Map<String, dynamic> data, {
    required double oldPan01,
    required String operation,
  }) {
    final direction = _rowMixDirection(data);
    switch (direction) {
      case 'hard_left':
        return 0.0;
      case 'left':
        if (operation == 'adjust_pan') {
          final signed = ((oldPan01 * 2.0) - 1.0 - 0.25).clamp(-1.0, 1.0);
          return ((signed + 1.0) * 0.5).clamp(0.0, 1.0).toDouble();
        }
        return 0.25;
      case 'center':
      case 'centre':
        return 0.5;
      case 'right':
        if (operation == 'adjust_pan') {
          final signed = ((oldPan01 * 2.0) - 1.0 + 0.25).clamp(-1.0, 1.0);
          return ((signed + 1.0) * 0.5).clamp(0.0, 1.0).toDouble();
        }
        return 0.75;
      case 'hard_right':
        return 1.0;
    }

    final pan01 = _rowMixDoubleFrom(data, const ['pan01', 'pan_value']);
    if (pan01 != null) return pan01.clamp(0.0, 1.0).toDouble();

    final value = _rowMixDoubleFrom(data, const ['value']);
    if (value != null) return value.clamp(0.0, 1.0).toDouble();

    final signed = _rowMixDoubleFrom(data, const ['pan_signed']);
    if (signed != null) {
      return (((signed.clamp(-1.0, 1.0) + 1.0) * 0.5).clamp(
        0.0,
        1.0,
      )).toDouble();
    }

    final pan = _rowMixDoubleFrom(data, const ['pan']);
    if (pan != null) {
      if (pan < 0.0) {
        return (((pan.clamp(-1.0, 1.0) + 1.0) * 0.5).clamp(
          0.0,
          1.0,
        )).toDouble();
      }
      return pan.clamp(0.0, 1.0).toDouble();
    }

    if (operation == 'adjust_pan') {
      final delta = _rowMixDoubleFrom(data, const ['delta', 'pan_delta']);
      if (delta != null) {
        final oldSigned = (oldPan01 * 2.0) - 1.0;
        final nextSigned = (oldSigned + delta).clamp(-1.0, 1.0);
        return ((nextSigned + 1.0) * 0.5).clamp(0.0, 1.0).toDouble();
      }
    }

    return null;
  }

  Map<String, dynamic> _rowMixTargetData(Map<String, dynamic> data, int row) {
    final target = <String, dynamic>{..._actionTarget(data), 'row_index': row};
    final out = <String, dynamic>{
      'row': row,
      'row_index': row,
      'target': target,
    };
    for (final key in const ['scope', 'group_id', 'group_name']) {
      if (data.containsKey(key)) out[key] = data[key];
    }
    return out;
  }

  Future<Map<String, dynamic>?> _applyRowMixAction(
    Map<String, dynamic> data,
  ) async {
    final operation = _normalizeRowMixOperation(data['operation']);
    if (operation != 'set_gain' &&
        operation != 'adjust_gain' &&
        operation != 'set_pan' &&
        operation != 'adjust_pan') {
      _insertAssistantChatText("I couldn't apply that row mix edit.");
      return null;
    }

    final rows = _resolveRowIndicesFromActionTarget(
      data,
      includeSelectionFallback: true,
    );
    if (rows.length != 1) {
      _insertAssistantChatText("I couldn't resolve which row to mix.");
      return null;
    }
    final row = rows.single;
    if (row < 0 || row >= _rowCount) {
      _insertAssistantChatText("I couldn't resolve which row to mix.");
      return null;
    }

    final mixData = _rowMixTargetData(data, row);
    final MixAction action;
    late final Map<String, dynamic> appliedData;
    if (operation == 'set_gain' || operation == 'adjust_gain') {
      final oldGain = _rowGain[row];
      final value = _resolveRowMixGainValue(
        data,
        oldGain: oldGain,
        operation: operation,
      );
      if (value == null) {
        _insertAssistantChatText("I couldn't resolve the gain change.");
        return null;
      }
      appliedData = <String, dynamic>{
        ...data,
        'expected_row_id': _rowIdAt(row),
        'expected_gain_db': rowGainUiToDb(value),
      };
      if ((value - oldGain).abs() < 0.00001) return appliedData;
      action = MixAction('set_row_gain', {
        ...mixData,
        'force_individual_row': true,
        'mode': 'set',
        'value': value,
      });
    } else {
      final oldPan = _rowPan[row];
      final value = _resolveRowMixPanValue(
        data,
        oldPan01: oldPan,
        operation: operation,
      );
      if (value == null) {
        _insertAssistantChatText("I couldn't resolve the pan change.");
        return null;
      }
      appliedData = <String, dynamic>{
        ...data,
        'expected_row_id': _rowIdAt(row),
        'expected_pan_signed': (value * 2.0) - 1.0,
      };
      if ((value - oldPan).abs() < 0.00001) return appliedData;
      action = MixAction('set_row_pan', {
        ...mixData,
        'force_individual_row': true,
        'mode': 'set',
        'value': value,
      });
    }

    final report = await applyMixingResult(
      MixingResult(
        actions: [action],
        summary: 'Adjusted ${_rowDisplayName(row)}.',
        isNoOp: false,
      ),
    );
    if (!report.changed) {
      _insertAssistantChatText("I couldn't apply that row mix edit.");
      return null;
    }
    return appliedData;
  }

  String _normalizeTransportControlOperation(Object? raw) {
    final token = (raw ?? '')
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'^_+|_+$'), '');
    return switch (token) {
      'play' || 'start_playback' || 'resume' || 'resume_playback' => 'play',
      'pause' || 'pause_playback' => 'pause',
      'stop' || 'stop_playback' => 'stop',
      'restart' ||
      'restart_song' ||
      'go_to_start' ||
      'back_to_start' ||
      'return_to_start' => 'restart',
      'toggle' ||
      'toggle_play' ||
      'toggle_playback' ||
      'play_pause' ||
      'toggle_play_pause' => 'toggle_play_pause',
      'record' ||
      'start_record' ||
      'start_recording' ||
      'begin_recording' => 'start_recording',
      'stop_record' || 'stop_recording' => 'stop_recording',
      'toggle_record' || 'toggle_recording' => 'toggle_recording',
      'undo' || 'undo_last' || 'undo_last_action' => 'undo',
      'redo' || 'redo_last' || 'redo_last_action' => 'redo',
      'enable_metronome' ||
      'metronome_on' ||
      'turn_on_metronome' ||
      'click_on' ||
      'turn_on_click' => 'enable_metronome',
      'disable_metronome' ||
      'metronome_off' ||
      'turn_off_metronome' ||
      'click_off' ||
      'turn_off_click' => 'disable_metronome',
      'toggle_metronome' ||
      'metronome' ||
      'toggle_click' ||
      'click' => 'toggle_metronome',
      'enable_loop' || 'loop_on' || 'turn_on_loop' => 'enable_loop',
      'disable_loop' || 'loop_off' || 'turn_off_loop' => 'disable_loop',
      'toggle_loop' || 'loop' => 'toggle_loop',
      _ => token,
    };
  }

  Future<void> _applyTransportControlAction(Map<String, dynamic> data) async {
    final operation = _normalizeTransportControlOperation(data['operation']);
    switch (operation) {
      case 'play':
        if (_isRecording) {
          _insertSystemChatText('• Recording is already running •');
          return;
        }
        if (!_isPlaying) {
          await _togglePlayPause();
        }
        _insertSystemChatText('• Playback started •');
        return;
      case 'pause':
      case 'stop':
        if (_isRecording) {
          await _stopRecordingJuce(keepPlaying: false);
          _insertSystemChatText('• Recording stopped •');
          return;
        }
        if (_isPlaying) {
          await _pauseAudio(_safeAudioEditorStateSetter);
        }
        _insertSystemChatText(
          operation == 'pause' ? '• Playback paused •' : '• Playback stopped •',
        );
        return;
      case 'restart':
        if (_recordButtonVisuallyActive) {
          _insertAssistantChatText(
            'Stop recording before restarting playback.',
          );
          return;
        }
        await _restartAudio(_safeAudioEditorStateSetter);
        _insertSystemChatText('• Playback returned to the start •');
        return;
      case 'toggle_play_pause':
        if (_isRecording) {
          await _stopRecordingJuce(keepPlaying: false);
          _insertSystemChatText('• Recording stopped •');
          return;
        }
        final willPlay = !_isPlaying;
        await _togglePlayPause();
        _insertSystemChatText(
          willPlay ? '• Playback started •' : '• Playback paused •',
        );
        return;
      case 'start_recording':
        if (_recordButtonVisuallyActive) {
          _insertSystemChatText('• Recording is already running •');
          return;
        }
        await _startRecordingJuce();
        if (_recordButtonVisuallyActive) {
          _insertSystemChatText('• Recording started •');
        }
        return;
      case 'stop_recording':
        if (!_recordButtonVisuallyActive) {
          _insertSystemChatText('• Recording is not running •');
          return;
        }
        await _stopRecordingJuce(keepPlaying: false);
        _insertSystemChatText('• Recording stopped •');
        return;
      case 'toggle_recording':
        final wasRecording = _recordButtonVisuallyActive;
        await _onRecordPressed();
        if (wasRecording) {
          _insertSystemChatText('• Recording stopped •');
        } else if (_recordButtonVisuallyActive) {
          _insertSystemChatText('• Recording started •');
        }
        return;
      case 'undo':
        if (!_undoManager.canUndo && _pendingTempoUndoBefore == null) {
          _insertAssistantChatText("There's nothing to undo.");
          return;
        }
        await _performEditorUndo();
        _insertSystemChatText('• Undid the last edit •');
        return;
      case 'redo':
        if (!_undoManager.canRedo || _pendingTempoUndoBefore != null) {
          _insertAssistantChatText("There's nothing to redo.");
          return;
        }
        await _performEditorRedo();
        _insertSystemChatText('• Redid the last edit •');
        return;
      case 'enable_metronome':
        if (!_metronomeEnabled) {
          await _toggleMetronomeFromBottomBar();
        }
        _insertSystemChatText('• Metronome enabled •');
        return;
      case 'disable_metronome':
        if (_metronomeEnabled) {
          await _toggleMetronomeFromBottomBar();
        }
        _insertSystemChatText('• Metronome disabled •');
        return;
      case 'toggle_metronome':
        final next = !_metronomeEnabled;
        await _toggleMetronomeFromBottomBar();
        _insertSystemChatText(
          next ? '• Metronome enabled •' : '• Metronome disabled •',
        );
        return;
      case 'enable_loop':
        if (!_loopEnabled) {
          _toggleLoopFromBottomBar();
        }
        _insertSystemChatText('• Loop enabled •');
        return;
      case 'disable_loop':
        if (_loopEnabled) {
          _toggleLoopFromBottomBar();
        }
        _insertSystemChatText('• Loop disabled •');
        return;
      case 'toggle_loop':
        final next = !_loopEnabled;
        _toggleLoopFromBottomBar();
        _insertSystemChatText(next ? '• Loop enabled •' : '• Loop disabled •');
        return;
      default:
        _insertAssistantChatText("I couldn't apply that transport command.");
    }
  }

  _AiV3TransportSnapshot _captureAiV3TransportSnapshot() {
    final playhead = _isPlaying
        ? _estimateTransportClockFromSample()
        : _globalAudioClock;
    return _AiV3TransportSnapshot(
      playing: _isPlaying,
      playheadMs: math.max(0, playhead.inMilliseconds).toInt(),
      metronomeEnabled: _metronomeEnabled,
      loopEnabled: _loopEnabled,
      loopStartMs: _loopStartMs,
      loopEndMs: _loopEndMs,
    );
  }

  Future<_AiV3TransportSnapshot> _applyAiV3TransportAction(
    Map<String, dynamic> data,
  ) async {
    final operation = data['operation']?.toString() ?? '';
    if ((operation == 'set_playing' || operation == 'restart') &&
        _recordButtonVisuallyActive) {
      throw StateError('v3_transport_recording_active');
    }
    final before = _captureAiV3TransportSnapshot();
    final action = _AiV3TransportRollbackAction(
      before: before,
      applyAction: () => _applyAiV3TransportOperation(operation, data),
      restoreAction: _restoreAiV3TransportSnapshot,
    );
    await _undoManager.executeWithoutAdd(action);
    return _captureAiV3TransportSnapshot();
  }

  void _recordAiV3TransportExpectations(
    List<Map<String, dynamic>> expectations, {
    required String operation,
    required _AiV3TransportSnapshot state,
  }) {
    switch (operation) {
      case 'set_playing':
        _addAiV3Expectation(expectations, <String, dynamic>{
          'kind': 'transport_playing',
          'value': state.playing,
        });
        if (state.playing) {
          expectations.removeWhere(
            (expectation) =>
                expectation['kind'] == 'transport_restart_position',
          );
        }
        return;
      case 'restart':
        _addAiV3Expectation(expectations, <String, dynamic>{
          'kind': 'transport_playing',
          'value': false,
        });
        _addAiV3Expectation(expectations, <String, dynamic>{
          'kind': 'transport_restart_position',
          'value': state.playheadMs,
        });
        return;
      case 'set_metronome_enabled':
        _addAiV3Expectation(expectations, <String, dynamic>{
          'kind': 'transport_metronome',
          'value': state.metronomeEnabled,
        });
        return;
      case 'set_loop_enabled':
        _addAiV3Expectation(expectations, <String, dynamic>{
          'kind': 'transport_loop',
          'enabled': state.loopEnabled,
          'start_ms': state.loopStartMs,
          'end_ms': state.loopEndMs,
        });
        return;
    }
  }

  Future<void> _applyAiV3TransportOperation(
    String operation,
    Map<String, dynamic> data,
  ) async {
    switch (operation) {
      case 'set_playing':
        final playing = data['playing'];
        if (playing is! bool) throw StateError('v3_transport_invalid_playing');
        if (_recordButtonVisuallyActive) {
          throw StateError('v3_transport_recording_active');
        }
        await _setAiV3TransportPlaying(playing);
        return;
      case 'restart':
        if (_recordButtonVisuallyActive) {
          throw StateError('v3_transport_recording_active');
        }
        final validLoop =
            _loopEnabled && _loopEndMs > _loopStartMs && _loopStartMs >= 0;
        await _seekAiV3TransportPaused(validLoop ? _loopStartMs : 0);
        return;
      case 'set_metronome_enabled':
        final enabled = data['enabled'];
        if (enabled is! bool) {
          throw StateError('v3_transport_invalid_metronome');
        }
        if (_metronomeEnabled == enabled) return;
        setState(() => _metronomeEnabled = enabled);
        await JuceAudioEngine.setMetronomeEnabled(enabled);
        _scheduleProjectAutosave();
        return;
      case 'set_loop_enabled':
        final enabled = data['enabled'];
        if (enabled is! bool) throw StateError('v3_transport_invalid_loop');
        var startMs = _loopStartMs;
        var endMs = _loopEndMs;
        if (enabled && (startMs < 0 || endMs <= startMs)) {
          final playhead = _isPlaying
              ? _estimateTransportClockFromSample()
              : _globalAudioClock;
          startMs = math.max(0, playhead.inMilliseconds).toInt();
          endMs = startMs + _defaultBottomLoopLengthMs();
        }
        if (_loopEnabled == enabled &&
            _loopStartMs == startMs &&
            _loopEndMs == endMs) {
          return;
        }
        setState(() {
          _loopEnabled = enabled;
          _loopStartMs = startMs;
          _loopEndMs = endMs;
        });
        _scheduleProjectAutosave();
        return;
      default:
        throw StateError('v3_transport_unknown_operation');
    }
  }

  Future<void> _setAiV3TransportPlaying(bool playing) async {
    if (_isPlaying == playing) return;
    await _togglePlayPauseAudio(_safeAudioEditorStateSetter);
    if (_isPlaying != playing) {
      throw StateError('v3_transport_playback_state_mismatch');
    }
  }

  Future<void> _seekAiV3TransportPaused(int playheadMs) async {
    final targetMs = math.max(0, playheadMs).toInt();
    _transportDesiredPlaying = false;
    _transportCommandSerial++;
    _transportTicker?.stop();
    for (final track in _audioTracks) {
      track.audioStarted = false;
      track.audioStartTimer?.cancel();
      track.currentPosition = Duration(milliseconds: targetMs);
    }
    await JuceAudioEngine.pause();
    await JuceAudioEngine.setTransportSeconds(targetMs / 1000.0);
    await JuceAudioEngine.setMetronomeTransportMs(targetMs.toDouble());
    if (!mounted) throw StateError('v3_transport_editor_unmounted');
    setState(() {
      _isPlaying = false;
      _syncTransportClock(Duration(milliseconds: targetMs), playing: false);
    });
    _stopMeterPolling();
  }

  Future<void> _restoreAiV3TransportSnapshot(
    _AiV3TransportSnapshot snapshot,
  ) async {
    final metronomeChanged = _metronomeEnabled != snapshot.metronomeEnabled;
    final loopChanged =
        _loopEnabled != snapshot.loopEnabled ||
        _loopStartMs != snapshot.loopStartMs ||
        _loopEndMs != snapshot.loopEndMs;
    if (mounted) {
      setState(() {
        _metronomeEnabled = snapshot.metronomeEnabled;
        _loopEnabled = snapshot.loopEnabled;
        _loopStartMs = snapshot.loopStartMs;
        _loopEndMs = snapshot.loopEndMs;
      });
    }
    if (metronomeChanged) {
      await JuceAudioEngine.setMetronomeEnabled(snapshot.metronomeEnabled);
    }
    await _seekAiV3TransportPaused(snapshot.playheadMs);
    if (snapshot.playing) {
      await _setAiV3TransportPlaying(true);
    }
    if (metronomeChanged || loopChanged) _scheduleProjectAutosave();
  }

  String _normalizeEffectEditOperation(String raw) {
    switch (raw.trim().toLowerCase()) {
      case 'delete':
      case 'remove':
      case 'delete_effect':
      case 'remove_effect':
      case 'take_out':
        return 'remove';
      case 'add':
      case 'insert':
      case 'ensure':
      case 'ensure_effect':
      case 'add_effect':
      case 'insert_effect':
        return 'add';
      case 'disable':
      case 'bypass':
      case 'mute':
        return 'bypass';
      case 'enable':
      case 'unbypass':
      case 'unmute':
        return 'unbypass';
      case 'toggle':
      case 'toggle_bypass':
        return 'toggle_bypass';
      default:
        return raw.trim().toLowerCase();
    }
  }

  Future<List<Map<String, dynamic>>> _applyAiV3EffectConfigureAction(
    Map<String, dynamic> data,
  ) async {
    final target = _actionTarget(data);
    final row = _resolveRowIndexFromActionTarget(data);
    final effectId = data['effect_id']?.toString().trim() ?? '';
    final rawParameters = data['parameters'];
    if (row == null ||
        row < 0 ||
        row >= _rowCount ||
        effectId.isEmpty ||
        rawParameters is! Map) {
      throw StateError('v3_effect_configuration_invalid');
    }
    await _applyEffectEditAction(<String, dynamic>{
      'operation': 'add',
      'effect_name': effectId,
      'force_individual_row': true,
      'target': <String, dynamic>{...target, 'scope': 'row', 'row_index': row},
    });
    final parameters = Map<String, dynamic>.from(rawParameters);
    final presenceExpectation = <String, dynamic>{
      'kind': 'effect',
      'row': row,
      'force_individual_row': true,
      if (target['row_id'] is int) 'row_id': target['row_id'],
      'value': effectId,
    };
    if (parameters.isEmpty) {
      return <Map<String, dynamic>>[presenceExpectation];
    }
    final actions = parameters.entries
        .map((entry) {
          final value = entry.value;
          if (value is! num || !value.isFinite) {
            throw StateError('v3_effect_parameter_invalid');
          }
          return MixAction('adjust_effect_param_by_name', <String, dynamic>{
            'row': row,
            'effect_name_contains': effectId,
            'param_name': entry.key,
            'mode': 'set',
            'value_norm': value.toDouble().clamp(0.0, 1.0),
            // The legacy mixer action uses `value` when a plugin does not expose
            // min/max metadata. Supplying both forms keeps this mechanical and
            // prevents a normalized V3 command from failing on sparse metadata.
            'value': value.toDouble().clamp(0.0, 1.0),
            'skip_if_missing_effect': false,
            'force_individual_row': true,
          });
        })
        .toList(growable: false);
    final report = await applyMixingResult(
      MixingResult(
        actions: actions,
        summary: 'Configured $effectId.',
        isNoOp: false,
      ),
      emitActionSummaries: false,
    );
    if (report.skippedReasons.isNotEmpty || report.applied != actions.length) {
      throw StateError('v3_effect_parameter_apply_failed');
    }
    return <Map<String, dynamic>>[
      presenceExpectation,
      ...report.appliedMutations,
    ];
  }

  Future<void> _applyAiV3EffectInstanceEditAction(
    Map<String, dynamic> data,
  ) async {
    final row = _resolveRowIndexFromActionTarget(data);
    final target = _actionTarget(data);
    final expectedRowId = _toActionInt(target['row_id']);
    final instanceId = data['effect_instance_id']?.toString().trim() ?? '';
    final effectId = data['effect_id']?.toString().trim() ?? '';
    final operation = data['operation']?.toString().trim() ?? '';
    if (row == null ||
        row < 0 ||
        row >= _rowCount ||
        expectedRowId == null ||
        _rowIdAt(row) != expectedRowId ||
        instanceId.isEmpty ||
        effectId.isEmpty) {
      throw StateError('v3_effect_instance_target_invalid');
    }
    final instanceIds = await JuceAudioEngine.getTrackEffectInstanceIdsForRow(
      row,
      forceIndividualRow: true,
    );
    final effectIds = await JuceAudioEngine.getTrackEffectIdsForRow(
      row,
      forceIndividualRow: true,
    );
    final index = instanceIds.indexOf(instanceId);
    if (index < 0 ||
        index >= effectIds.length ||
        effectIds[index] != effectId) {
      throw StateError('v3_effect_instance_stale');
    }
    final occurrence =
        effectIds
            .take(index + 1)
            .where((candidate) => candidate == effectId)
            .length -
        1;
    void onChange() {
      _refreshAudioEditorView();
      _refreshRowFx(row);
      unawaited(_refreshAutomationTargetsForRow(row));
    }

    switch (operation) {
      case 'set_bypassed':
        final requested = data['bypassed'];
        if (requested is! bool) {
          throw StateError('v3_effect_bypass_value_invalid');
        }
        final current = await JuceAudioEngine.getRowEffectBypassState(
          row,
          index,
          forceIndividualRow: true,
        );
        if (current == requested) return;
        await _undoManager.execute(
          BypassEffectInstanceAction(
            row: row,
            effectInstanceId: instanceId,
            effectId: effectId,
            effectOccurrence: occurrence,
            oldState: current,
            newState: requested,
            forceIndividualRow: true,
            onChange: onChange,
          ),
        );
        break;
      case 'remove':
        final snapshot = await captureRowSnapshot(
          row,
          rowId: expectedRowId,
          forceIndividualRow: true,
        );
        if (index >= snapshot.effects.length ||
            snapshot.effects[index].effectId != effectId) {
          throw StateError('v3_effect_instance_snapshot_mismatch');
        }
        await _undoManager.execute(
          RemoveEffectInstanceAction(
            row: row,
            effectIndex: index,
            effectInstanceId: instanceId,
            effectOccurrence: occurrence,
            removedEffect: snapshot.effects[index],
            forceIndividualRow: true,
            onChange: () {
              _refreshAudioEditorView();
              _refreshRowFx(row);
            },
            onInstanceRestored: (oldInstanceId, newInstanceId) =>
                _remapRowEffectAutomationInstance(
                  row,
                  oldInstanceId: oldInstanceId,
                  newInstanceId: newInstanceId,
                ),
          ),
        );
        break;
      default:
        throw StateError('v3_effect_instance_operation_invalid');
    }
    await _refreshPersistedEffectSnapshotForRow(row);
  }

  Future<void> _applyAiV3PhoneMicCleanupPresets(
    Map<String, String> presetsByClipId,
  ) async {
    final resolved = <AudioTrack>[];
    for (final entry in presetsByClipId.entries) {
      final index = _clipIndexForPersistentId(entry.key);
      if (!_isValidClipIndex(index) || _audioTracks[index].isMidi) {
        throw StateError('v3_phone_cleanup_clip_state_invalid');
      }
      resolved.add(_audioTracks[index]);
    }
    for (var index = 0; index < resolved.length; index++) {
      resolved[index].audioEnhancementPreset =
          presetsByClipId[resolved[index].clipId] ?? '';
    }
    _scheduleProjectAutosave();
    if (mounted) setState(() {});
  }

  Future<Map<String, dynamic>> _applyAiV3PhoneMicCleanupAction(
    Map<String, dynamic> data,
  ) async {
    final target = _actionTarget(data);
    final rowId = _toActionInt(target['row_id']);
    final preparedRow = _toActionInt(target['row_index']);
    final row = rowId == null ? -1 : _rowIndexForId(rowId);
    final effectIds = (data['effect_ids'] as List? ?? const <Object>[])
        .map((value) => value.toString().trim())
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    final clipIds = (data['audio_clip_ids'] as List? ?? const <Object>[])
        .map((value) => value.toString().trim())
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    final preset = data['preset']?.toString().trim() ?? '';
    if (rowId == null ||
        !_isValidRowIndex(row) ||
        (preparedRow != null && preparedRow != row) ||
        !listEquals(effectIds, aiV3PhoneMicCleanupEffectIds) ||
        preset != aiV3PhoneMicCleanupPreset ||
        clipIds.isEmpty ||
        clipIds.toSet().length != clipIds.length) {
      throw StateError('v3_phone_cleanup_target_invalid');
    }
    final currentClipIds =
        _audioTracks
            .where((clip) => clip.rowId == rowId && !clip.isMidi)
            .map((clip) => clip.clipId)
            .toList(growable: false)
          ..sort();
    final expectedClipIds = List<String>.from(clipIds)..sort();
    if (!listEquals(currentClipIds, expectedClipIds)) {
      throw StateError('v3_phone_cleanup_clip_state_invalid');
    }
    for (final effectId in effectIds) {
      if (!_canUseEffectForCurrentPlan(effectId)) {
        throw StateError('v3_phone_cleanup_unavailable');
      }
    }

    void onEffectsChanged() {
      _refreshAudioEditorView();
      _refreshRowFx(row);
      unawaited(_refreshAutomationTargetsForRow(row));
    }

    for (final effectId in effectIds) {
      var nativeEffectIds = await JuceAudioEngine.getTrackEffectIdsForRow(row);
      var index = nativeEffectIds.indexOf(effectId);
      if (index < 0) {
        await _undoManager.execute(
          InsertEffectAction(
            row: row,
            pathOrName: effectId,
            onChange: onEffectsChanged,
          ),
        );
        nativeEffectIds = await JuceAudioEngine.getTrackEffectIdsForRow(row);
        index = nativeEffectIds.indexOf(effectId);
        if (index < 0) {
          throw StateError('v3_phone_cleanup_effect_insert_failed');
        }
      }
      final bypassed = await JuceAudioEngine.getRowEffectBypassState(
        row,
        index,
      );
      if (bypassed) {
        final instanceIds =
            await JuceAudioEngine.getTrackEffectInstanceIdsForRow(row);
        if (index >= instanceIds.length || instanceIds[index].trim().isEmpty) {
          throw StateError('v3_phone_cleanup_effect_identity_missing');
        }
        final occurrence =
            nativeEffectIds
                .take(index + 1)
                .where((id) => id == effectId)
                .length -
            1;
        await _undoManager.execute(
          BypassEffectInstanceAction(
            row: row,
            effectInstanceId: instanceIds[index].trim(),
            effectId: effectId,
            effectOccurrence: occurrence,
            oldState: true,
            newState: false,
            onChange: onEffectsChanged,
          ),
        );
      }
    }
    final cleanupInstanceIds = await _ensureAiV3PhoneMicCleanupOrder(
      row,
      effectIds,
    );

    final beforePresets = <String, String>{
      for (final clipId in currentClipIds)
        clipId: _audioTracks[_clipIndexForPersistentId(clipId)]
            .audioEnhancementPreset,
    };
    if (beforePresets.values.any((value) => value != preset)) {
      await _undoManager.execute(
        PhoneMicCleanupMetadataAction(
          beforePresets: beforePresets,
          preset: preset,
          applyPresets: _applyAiV3PhoneMicCleanupPresets,
        ),
      );
    }
    await _refreshPersistedEffectSnapshotForRow(row);

    final chain = await _aiV3NativeRowEffectChain(row);
    final requiredInChain = chain
        .where(
          (effect) => cleanupInstanceIds.contains(effect['effect_instance_id']),
        )
        .map((effect) => effect['effect_id'].toString())
        .toList(growable: false);
    if (!listEquals(requiredInChain, effectIds) ||
        chain.any(
          (effect) =>
              cleanupInstanceIds.contains(effect['effect_instance_id']) &&
              effect['bypassed'] == true,
        )) {
      throw StateError('v3_phone_cleanup_effect_readback_failed');
    }
    final presets = <String, String>{
      for (final clipId in currentClipIds)
        clipId: _audioTracks[_clipIndexForPersistentId(clipId)]
            .audioEnhancementPreset,
    };
    if (presets.values.any((value) => value != preset)) {
      throw StateError('v3_phone_cleanup_metadata_readback_failed');
    }
    return <String, dynamic>{
      'kind': 'phone_mic_cleanup',
      'row_id': rowId,
      'effect_chain': chain,
      'clip_presets': presets,
    };
  }

  Future<void> _remapRowEffectAutomationInstance(
    int row, {
    required String oldInstanceId,
    required String newInstanceId,
  }) async {
    if (!_isValidRowIndex(row) ||
        oldInstanceId.trim().isEmpty ||
        newInstanceId.trim().isEmpty ||
        oldInstanceId == newInstanceId) {
      return;
    }
    final oldEffectKey = 'inst:${oldInstanceId.trim()}';
    final newEffectKey = 'inst:${newInstanceId.trim()}';

    String remappedTargetId(String targetId) {
      final parsed = _parseAutomationTargetId(targetId);
      if (parsed.isMaster ||
          !parsed.isEffectParameter ||
          parsed.effectKey != oldEffectKey ||
          parsed.paramId.trim().isEmpty) {
        return targetId;
      }
      return _pluginAutomationTargetIdFromEffectKey(
        newEffectKey,
        parsed.paramId,
      );
    }

    final currentPoints = _rowPluginAutomation[row];
    if (currentPoints != null) {
      final remapped = <String, List<AutomationPoint>>{};
      for (final entry in currentPoints.entries) {
        remapped[remappedTargetId(entry.key)] = entry.value
            .map((point) => point.copy())
            .toList(growable: false);
      }
      _rowPluginAutomation[row] = remapped;
    }
    final currentClips = _rowAutomationClips[row];
    if (currentClips != null) {
      final remapped = <String, List<AutomationClipSnapshot>>{};
      for (final entry in currentClips.entries) {
        remapped[remappedTargetId(entry.key)] = _copyAutomationClipList(
          entry.value,
        );
      }
      _rowAutomationClips[row] = remapped;
    }
    final selected = _rowSelectedAutomationTarget[row];
    if (selected != null) {
      _rowSelectedAutomationTarget[row] = remappedTargetId(selected);
    }
    _lastAppliedAutomationNormalized.removeWhere(
      (key, _) => key.startsWith('$row|') && key.contains(oldInstanceId),
    );
    await _refreshAutomationTargetsForRow(row);
  }

  int? _resolveEffectIndexFromActionData(
    List<String> effects,
    Map<String, dynamic> data,
  ) {
    if (effects.isEmpty) return null;
    final target = _actionTarget(data);
    final explicitIndex = _toActionInt(
      data['effect_index'] ??
          target['effect_index'] ??
          data['plugin_index'] ??
          target['plugin_index'],
    );
    if (explicitIndex != null &&
        explicitIndex >= 0 &&
        explicitIndex < effects.length) {
      return explicitIndex;
    }

    final effectNeedles = <String>[];
    void addNeedle(dynamic raw) {
      final needle = raw?.toString().trim().toLowerCase() ?? '';
      if (needle.isEmpty || needle == 'plugin' || needle == 'effect') return;
      effectNeedles.add(needle);
    }

    addNeedle(data['effect_name']);
    addNeedle(target['effect_name']);
    addNeedle(data['plugin_name']);
    addNeedle(target['plugin_name']);
    addNeedle(data['effect_name_contains']);
    addNeedle(target['effect_name_contains']);
    addNeedle(data['plugin']);
    addNeedle(target['plugin']);
    addNeedle(data['effect']);
    addNeedle(target['effect']);
    addNeedle(data['fx']);
    addNeedle(target['fx']);
    addNeedle(data['name']);
    addNeedle(target['name']);
    addNeedle(data['kind']);
    addNeedle(target['kind']);

    for (final needle in effectNeedles) {
      final exact = <int>[];
      final fuzzy = <int>[];
      for (int i = 0; i < effects.length; i++) {
        final candidate = effects[i].trim().toLowerCase();
        if (candidate == needle) {
          exact.add(i);
        } else if (candidate.contains(needle) || needle.contains(candidate)) {
          fuzzy.add(i);
        }
      }
      if (exact.length == 1) return exact.first;
      if (exact.isEmpty && fuzzy.length == 1) return fuzzy.first;
    }

    if (effects.length == 1) return 0;
    return null;
  }

  Future<void> _applyEffectEditAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final operation = _normalizeEffectEditOperation(
      (data['operation'] ?? '').toString(),
    );
    final scope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final isMaster =
        scope == 'master' ||
        scope == 'master_bus' ||
        scope == 'master-bus' ||
        scope == 'masterbus';
    final forceIndividualRow = data['force_individual_row'] == true;
    final groupId = isMaster || forceIndividualRow
        ? null
        : _resolveRowGroupIdFromAction(data);
    final groupBusRow = groupId == null
        ? null
        : _trackGroupLeadRowIndexForId(groupId);

    final row = isMaster
        ? null
        : groupBusRow ?? _resolveRowIndexFromActionTarget(data);
    if (!isMaster && row == null) {
      _insertAssistantChatText(
        "I couldn't resolve which track plugin to edit.",
      );
      return;
    }
    final groupBusName = groupId == null
        ? null
        : _trackGroupDisplayName(groupId);
    final targetDisplayName =
        groupBusName ?? (row == null ? '' : _rowDisplayName(row));

    final effects = isMaster
        ? await JuceAudioEngine.getMasterEffects()
        : await JuceAudioEngine.getTrackEffectsForRow(
            row!,
            forceIndividualRow: forceIndividualRow,
          );
    final effectIndex = _resolveEffectIndexFromActionData(effects, data);

    if (operation == 'remove') {
      if (effectIndex == null) {
        final rowName = targetDisplayName.isEmpty
            ? 'this track'
            : targetDisplayName;
        _insertAssistantChatText(
          isMaster
              ? "I couldn't resolve which master plugin to remove."
              : "I couldn't resolve which plugin to remove on $rowName.",
        );
        return;
      }
      final effectName = effects[effectIndex];
      final onTrackChange = () {
        _refreshAudioEditorView();
        if (row != null) {
          _refreshRowFx(row);
          unawaited(_refreshAutomationTargetsForRow(row));
        } else {
          unawaited(_refreshAutomationTargetsForAllRows());
        }
      };
      final EditorUndoAction action = isMaster
          ? RemoveMasterEffectAction(
              effectIndex: effectIndex,
              pathOrName: effectName,
              onChange: onTrackChange,
            )
          : RemoveEffectAction(
              row: row!,
              effectIndex: effectIndex,
              pathOrName: effectName,
              forceIndividualRow: forceIndividualRow,
              onChange: onTrackChange,
            );
      final beforeCount = effects
          .where(
            (e) => e.trim().toLowerCase() == effectName.trim().toLowerCase(),
          )
          .length;
      await _undoManager.executeWithoutAdd(action);
      final effectsAfter = isMaster
          ? await JuceAudioEngine.getMasterEffects()
          : await JuceAudioEngine.getTrackEffectsForRow(
              row!,
              forceIndividualRow: forceIndividualRow,
            );
      final afterCount = effectsAfter
          .where(
            (e) => e.trim().toLowerCase() == effectName.trim().toLowerCase(),
          )
          .length;
      final removed = afterCount < beforeCount;
      if (!removed) {
        debugPrint(
          'effect_edit remove verification failed (master=$isMaster row=$row effect=$effectName)',
        );
        return;
      }
      if (!isMaster) {
        _mixHighlighter.trigger([
          HaloKey('row:$row'),
          HaloKey('row:$row:effects_tab'),
          HaloKey('row:$row:fx_list'),
        ]);
      }
      _insertSystemChatText(
        isMaster
            ? '• Removed $effectName from Master Bus •'
            : '• Removed $effectName from $targetDisplayName •',
      );
      return;
    }

    if (operation == 'add') {
      final effectNeedle =
          (data['effect_name'] ??
                  target['effect_name'] ??
                  data['plugin_name'] ??
                  target['plugin_name'] ??
                  data['effect_name_contains'] ??
                  target['effect_name_contains'] ??
                  data['plugin'] ??
                  target['plugin'] ??
                  data['fx'] ??
                  target['fx'] ??
                  data['name'] ??
                  target['name'] ??
                  data['kind'] ??
                  target['kind'] ??
                  data['effect'] ??
                  target['effect'])
              .toString()
              .trim()
              .toLowerCase();
      final effectName = pickMixroomEffect(effectNeedle);
      if (effectName == null) {
        _insertAssistantChatText("I couldn't resolve which plugin to add.");
        return;
      }
      if (!_canUseEffectForCurrentPlan(effectName)) {
        _insertAssistantChatText(
          '$effectName is available on Starter and higher plans.',
        );
        return;
      }
      final alreadyIndex = effects.indexWhere(
        (e) => e.trim().toLowerCase() == effectName.toLowerCase(),
      );
      if (alreadyIndex != -1) {
        final reorderActions = isMaster
            ? await _ensureAiCanonicalChainOrderOnMaster(
                executeWithoutAdd: false,
              )
            : await _ensureAiCanonicalChainOrderOnRow(
                row!,
                executeWithoutAdd: false,
                forceIndividualRow: forceIndividualRow,
              );
        if (reorderActions.isNotEmpty) {
          await _undoManager.execute(
            CompoundUndoAction('Reorder AI effect chain', reorderActions),
          );
        }
        return;
      }
      final onTrackChange = () {
        _refreshAudioEditorView();
        if (row != null) {
          _refreshRowFx(row);
          unawaited(_refreshAutomationTargetsForRow(row));
        } else {
          unawaited(_refreshAutomationTargetsForAllRows());
        }
      };
      final EditorUndoAction action = isMaster
          ? InsertMasterEffectAction(
              pathOrName: effectName,
              onChange: onTrackChange,
            )
          : InsertEffectAction(
              row: row!,
              pathOrName: effectName,
              forceIndividualRow: forceIndividualRow,
              onChange: onTrackChange,
            );
      await _undoManager.execute(action);
      final effectsAfter = isMaster
          ? await JuceAudioEngine.getMasterEffects()
          : await JuceAudioEngine.getTrackEffectsForRow(
              row!,
              forceIndividualRow: forceIndividualRow,
            );
      final inserted = effectsAfter.any(
        (e) => e.trim().toLowerCase() == effectName.trim().toLowerCase(),
      );
      if (!inserted) {
        debugPrint(
          'effect_edit add verification failed (master=$isMaster row=$row effect=$effectName)',
        );
        return;
      }
      final reorderActions = isMaster
          ? await _ensureAiCanonicalChainOrderOnMaster(executeWithoutAdd: false)
          : await _ensureAiCanonicalChainOrderOnRow(
              row!,
              executeWithoutAdd: false,
              forceIndividualRow: forceIndividualRow,
            );
      if (reorderActions.isNotEmpty) {
        for (final reorderAction in reorderActions) {
          await _undoManager.executeWithoutAdd(reorderAction);
        }
        await _undoManager.addWithoutExecute(
          CompoundUndoAction('Add $effectName', <EditorUndoAction>[
            action,
            ...reorderActions,
          ]),
        );
      } else {
        await _undoManager.addWithoutExecute(action);
      }
      if (!isMaster) {
        _mixHighlighter.trigger([
          HaloKey('row:$row'),
          HaloKey('row:$row:effects_tab'),
          HaloKey('row:$row:fx_list'),
        ]);
      }
      _insertSystemChatText(
        isMaster
            ? '• Added $effectName to Master Bus •'
            : '• Added $effectName to $targetDisplayName •',
      );
      return;
    }

    if (operation == 'bypass' ||
        operation == 'unbypass' ||
        operation == 'toggle_bypass') {
      if (effectIndex == null) {
        final rowName = targetDisplayName.isEmpty
            ? 'this track'
            : targetDisplayName;
        _insertAssistantChatText(
          isMaster
              ? "I couldn't resolve which master plugin to toggle."
              : "I couldn't resolve which plugin to toggle on $rowName.",
        );
        return;
      }
      final effectName = effects[effectIndex];
      final currentState = isMaster
          ? await JuceAudioEngine.getMasterEffectBypassState(effectIndex)
          : await JuceAudioEngine.getRowEffectBypassState(
              row!,
              effectIndex,
              forceIndividualRow: forceIndividualRow,
            );
      final nextState = switch (operation) {
        'bypass' => true,
        'unbypass' => false,
        _ => !currentState,
      };
      final onTrackChange = () {
        _refreshAudioEditorView();
        if (row != null) {
          _refreshRowFx(row);
          unawaited(_refreshAutomationTargetsForRow(row));
        } else {
          unawaited(_refreshAutomationTargetsForAllRows());
        }
      };
      final EditorUndoAction action = isMaster
          ? BypassMasterEffectAction(
              effectIndex: effectIndex,
              oldState: currentState,
              newState: nextState,
              onChange: onTrackChange,
            )
          : BypassEffectAction(
              row: row!,
              effectIndex: effectIndex,
              oldState: currentState,
              newState: nextState,
              forceIndividualRow: forceIndividualRow,
              onChange: onTrackChange,
            );
      await _undoManager.execute(action);
      if (!isMaster) {
        _mixHighlighter.trigger([
          HaloKey('row:$row'),
          HaloKey('row:$row:effects_tab'),
          HaloKey('row:$row:fx_list'),
        ]);
      }
      _insertSystemChatText(
        isMaster
            ? '• ${nextState ? 'Bypassed' : 'Enabled'} $effectName on Master Bus •'
            : '• ${nextState ? 'Bypassed' : 'Enabled'} $effectName on $targetDisplayName •',
      );
      return;
    }

    _insertAssistantChatText("I couldn't apply that plugin edit.");
  }

  Future<void> _applyTutorialAction(Map<String, dynamic> data) async {
    final rawSteps = (data['steps'] as List?) ?? const [];
    final parsed = rawSteps.map(_toActionMap).toList(growable: false);
    final steps = parsed.isEmpty
        ? <Map<String, dynamic>>[data]
        : parsed.take(12).toList(growable: false);

    for (int i = 0; i < steps.length; i++) {
      final step = steps[i];
      final sequence = _tutorialTargetSequenceForStep(step, data);
      final drilldown = _toActionBool(
        step['drilldown'] ?? data['drilldown'],
        fallback: true,
      );
      final targets = drilldown
          ? AssistantActionUtils.compactTutorialPlaybackTargets(sequence)
          : <String>[sequence.isEmpty ? 'tutorial:timeline' : sequence.last];
      if (targets.isEmpty) continue;

      final baseDurationMs =
          (_toActionInt(step['duration_ms']) ??
                  _toActionInt(data['duration_ms']) ??
                  3200)
              .clamp(1200, 18000);
      final previewDurationMs = AssistantActionUtils.tutorialPreviewDurationMs(
        baseDurationMs,
      );
      final previewPauseMs =
          (_toActionInt(step['pause_ms']) ??
                  AssistantActionUtils.tutorialPreviewPauseMs(
                    previewDurationMs,
                  ))
              .clamp(480, 1400);
      final finalDurationMs = AssistantActionUtils.tutorialFinalDurationMs(
        baseDurationMs,
      );

      for (int j = 0; j < targets.length; j++) {
        final key = targets[j];
        final isLastOverall = i == steps.length - 1 && j == targets.length - 1;
        final durationMs = isLastOverall ? finalDurationMs : previewDurationMs;
        _mixHighlighter.clear();
        _mixHighlighter.trigger([
          HaloKey(key),
        ], duration: Duration(milliseconds: durationMs));
        if (isLastOverall) continue;
        final pauseMs = previewPauseMs;
        await Future<void>.delayed(Duration(milliseconds: pauseMs));
      }
    }
  }

  String _normalizeClipEditOperation(String raw) {
    return AssistantActionUtils.normalizeClipEditOperation(raw);
  }

  String _normalizeMidiComposeOperation(String raw) {
    return AssistantActionUtils.normalizeMidiComposeOperation(raw);
  }

  MapEntry<double, double>? _estimateAutoTrimBoundsMs(
    AudioTrack clip, {
    double thresholdFloor = 0.012,
    double thresholdRatio = 0.08,
    double paddingMs = 8.0,
  }) {
    return AssistantActionUtils.estimateAutoTrimBoundsMs(
      waveform: clip.normWaveformData,
      fullMs: _clipFullDurationMsForTrim(clip),
      trimStartMs: clip.trimStart.inMilliseconds.toDouble(),
      trimEndMs: clip.trimEnd.inMilliseconds.toDouble(),
      thresholdFloor: thresholdFloor,
      thresholdRatio: thresholdRatio,
      paddingMs: paddingMs,
    );
  }

  Future<AiV3ClipBoundaryAnalysis?> _analyzeAiV3ClipBoundaries(
    AudioTrack clip,
  ) async {
    if (clip.isMidi) return null;
    if (!await _ensureAiV3ClipWaveformReady(clip)) return null;
    final bounds = _estimateAutoTrimBoundsMs(clip, paddingMs: 0.0);
    if (bounds == null ||
        !bounds.key.isFinite ||
        !bounds.value.isFinite ||
        bounds.value - bounds.key < 50.0) {
      return null;
    }
    final firstSoundOffsetMs = math.max(
      0.0,
      bounds.key - clip.trimStart.inMilliseconds.toDouble(),
    );
    return AiV3ClipBoundaryAnalysis(
      audibleStartMs: bounds.key,
      audibleEndMs: bounds.value,
      firstSoundOffsetMs: firstSoundOffsetMs.toDouble(),
    );
  }

  Future<bool> _ensureAiV3ClipWaveformReady(AudioTrack clip) async {
    if (clip.isMidi || !clip.file.existsSync()) return false;
    if (clip.normWaveformData.isNotEmpty &&
        !_isAllZeroWaveform(clip.normWaveformData)) {
      return true;
    }

    final cacheKey = _normalizedClipPath(clip.file.path);
    final cached = _waveformCacheByPath[cacheKey];
    if (cached != null && cached.isNotEmpty && !_isAllZeroWaveform(cached)) {
      clip
        ..normWaveformData = cached
        ..didExtractWaveform = true;
      return true;
    }

    try {
      final pending = _waveformFutureByPath[cacheKey];
      if (pending != null) {
        final waveform = await pending;
        if (waveform != null &&
            waveform.isNotEmpty &&
            !_isAllZeroWaveform(waveform)) {
          clip
            ..normWaveformData = waveform
            ..didExtractWaveform = true;
          return true;
        }
        return false;
      }
      await _ensureClipWaveformForNormalizeVisual(clip);
      return clip.normWaveformData.isNotEmpty &&
          !_isAllZeroWaveform(clip.normWaveformData);
    } catch (error) {
      debugPrint('V3 waveform preparation failed: $error');
      return false;
    }
  }

  ({int trimStartMs, int trimEndMs}) _canonicalAudioTrimBounds(
    AudioTrack clip, {
    required double trimStartMs,
    required double trimEndMs,
  }) {
    final fullMs = _clipFullDurationMsForTrim(clip).clamp(1.0, 1e12);
    final safeTrimStart = trimStartMs.clamp(0.0, fullMs - 50.0).toDouble();
    final safeTrimEnd = trimEndMs
        .clamp(safeTrimStart + 50.0, fullMs)
        .toDouble();
    return (trimStartMs: safeTrimStart.round(), trimEndMs: safeTrimEnd.round());
  }

  Future<void> _applyTrimActionForClip(
    int clipIndex, {
    required double newTrimStartMs,
    required double newTrimEndMs,
    double? newOffsetSec,
  }) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];

    final canonical = _canonicalAudioTrimBounds(
      clip,
      trimStartMs: newTrimStartMs,
      trimEndMs: newTrimEndMs,
    );

    await _undoManager.execute(
      TrimClipAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldTrimStart: clip.trimStart,
        oldTrimEnd: clip.trimEnd,
        oldOffset: clip.offset,
        newTrimStart: Duration(milliseconds: canonical.trimStartMs),
        newTrimEnd: Duration(milliseconds: canonical.trimEndMs),
        newOffset: newOffsetSec,
        onChange: () {
          unawaited(_syncClipTimingToEngine(clipIndex));
          _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
          if (mounted) setState(() {});
        },
      ),
    );
  }

  Future<void> _setProjectTempoFromDetectedClip(int clipIndex) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;

    final detected = await _detectClipTempoBpm(clip);
    if (detected == null || !detected.isFinite) return;
    final roundedTempo = detected.round().clamp(40, 240).toDouble();

    _setStateAndRefreshProjectSettings(() {
      clip.sourceTempoBpm = detected;
      _tempoStretchEnabled = true;
    });
    await _applyProjectTempoChange(roundedTempo);
  }

  Future<void> _applyAutoBpmAlignAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final clipIndices = _resolveClipIndicesFromActionTarget(
      data,
      requireAudio: true,
    );
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
        "I couldn't resolve which audio clips to align. Select clips and ask again.",
      );
      return;
    }

    final preservePitch = _toActionBool(data['preserve_pitch'], fallback: true);
    final setProjectTempo = _toActionBool(
      data['set_project_tempo'] ?? data['detect_set_project_tempo'],
      fallback: false,
    );
    final explicitProjectTempo = _toActionDouble(
      data['project_tempo_bpm'] ?? target['project_tempo_bpm'],
    );

    if (explicitProjectTempo != null && explicitProjectTempo.isFinite) {
      final clampedTempo = _clampTempo(explicitProjectTempo);
      if (clampedTempo != _tempo) {
        await _applyProjectTempoChange(clampedTempo);
      }
    } else if (setProjectTempo) {
      final sourceIdx =
          _toActionInt(
            data['project_tempo_source_clip_index'] ??
                target['project_tempo_source_clip_index'],
          ) ??
          (clipIndices.contains(_timelinePrimarySelectedClipIndex)
              ? _timelinePrimarySelectedClipIndex
              : clipIndices.first);
      await _setProjectTempoFromDetectedClip(sourceIdx);
    }

    for (final idx in clipIndices) {
      await _setClipTempoFollowMode(
        idx,
        preservePitch: preservePitch,
        showFeedback: false,
      );
    }
    _showSmallNotice(
      'Tempo-aligned ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.',
    );
  }

  double? _estimateFirstSoundLocalMs(
    AudioTrack clip, {
    double thresholdFloor = 0.012,
    double thresholdRatio = 0.08,
  }) {
    final estimated = _estimateAutoTrimBoundsMs(
      clip,
      thresholdFloor: thresholdFloor,
      thresholdRatio: thresholdRatio,
      paddingMs: 0.0,
    );
    if (estimated == null) return null;
    return math
        .max(0.0, estimated.key - clip.trimStart.inMilliseconds.toDouble())
        .toDouble();
  }

  double _beatDurationMsForProject() {
    return (60000.0 / _tempo.clamp(1.0, 400.0)).clamp(1.0, 60000.0).toDouble();
  }

  double _barDurationMsForProject() => _beatDurationMsForProject() * 4.0;

  double? _resolveFirstSoundAlignmentTargetMs(
    Map<String, dynamic> data, {
    required AudioTrack clip,
    required double currentFirstSoundTimelineMs,
  }) {
    final target = _actionTarget(data);
    final explicitMs =
        AssistantActionUtils.resolveMoveMusicalStartMs(
          data: data,
          target: target,
          bpm: _tempo,
        ) ??
        _toActionDouble(
          data['target_ms'] ??
              target['target_ms'] ??
              data['align_to_ms'] ??
              target['align_to_ms'] ??
              data['first_sound_target_ms'] ??
              target['first_sound_target_ms'] ??
              data['new_start_ms'] ??
              target['new_start_ms'] ??
              data['start_ms'] ??
              target['start_ms'],
        );
    if (explicitMs != null && explicitMs.isFinite) {
      return math.max(0.0, explicitMs);
    }

    final barValue = _toActionDouble(
      data['bar_index'] ??
          target['bar_index'] ??
          data['bar_number'] ??
          target['bar_number'] ??
          data['measure_index'] ??
          target['measure_index'] ??
          data['measure_number'] ??
          target['measure_number'],
    );
    if (barValue != null && barValue.isFinite) {
      final oneBasedBar = math.max(1.0, barValue);
      return (oneBasedBar - 1.0) * _barDurationMsForProject();
    }

    final beatValue = _toActionDouble(
      data['beat_index'] ??
          target['beat_index'] ??
          data['beat_number'] ??
          target['beat_number'],
    );
    if (beatValue != null && beatValue.isFinite) {
      final oneBasedBeat = math.max(1.0, beatValue);
      return (oneBasedBeat - 1.0) * _beatDurationMsForProject();
    }

    final alignTo =
        (data['align_to'] ??
                target['align_to'] ??
                data['snap_to'] ??
                target['snap_to'] ??
                data['position'] ??
                target['position'] ??
                '')
            .toString()
            .trim()
            .toLowerCase();
    if (alignTo.contains('playhead') ||
        alignTo.contains('cursor') ||
        alignTo == 'current') {
      return _globalAudioClock.inMilliseconds.toDouble();
    }
    if (alignTo.contains('project') || alignTo == 'zero') {
      return 0.0;
    }
    if (alignTo.contains('clip_start') || alignTo == 'start') {
      return clip.offset * 1000.0;
    }
    if (alignTo.contains('bar') || alignTo.contains('measure')) {
      final barMs = _barDurationMsForProject();
      return (currentFirstSoundTimelineMs / barMs).roundToDouble() * barMs;
    }

    final beatMs = _beatDurationMsForProject();
    return (currentFirstSoundTimelineMs / beatMs).roundToDouble() * beatMs;
  }

  Future<void> _applyAlignFirstSoundAction(Map<String, dynamic> data) async {
    final clipIndices = _resolveClipIndicesFromActionTarget(
      data,
      requireAudio: true,
    );
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
        "I couldn't resolve which audio clips to align. Select clips and ask again.",
      );
      return;
    }

    final thresholdFloor =
        _toActionDouble(data['threshold_floor'])?.clamp(0.001, 1.0) ?? 0.012;
    final thresholdRatio =
        _toActionDouble(data['threshold_ratio'])?.clamp(0.001, 1.0) ?? 0.08;

    var changed = 0;
    for (final clipIndex in clipIndices) {
      if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
      final clip = _audioTracks[clipIndex];
      if (clip.isMidi) continue;

      final firstLocalMs = _estimateFirstSoundLocalMs(
        clip,
        thresholdFloor: thresholdFloor.toDouble(),
        thresholdRatio: thresholdRatio.toDouble(),
      );
      if (firstLocalMs == null) continue;

      final oldStartMs = clip.offset * 1000.0;
      final currentFirstSoundMs = oldStartMs + firstLocalMs;
      final targetMs = _resolveFirstSoundAlignmentTargetMs(
        data,
        clip: clip,
        currentFirstSoundTimelineMs: currentFirstSoundMs,
      );
      if (targetMs == null || !targetMs.isFinite) continue;

      final nextStartMs = math.max(0.0, targetMs - firstLocalMs);
      if ((nextStartMs - oldStartMs).abs() < 0.5) continue;

      final oldAlignmentOffsetMs = clip.alignmentOffsetMs;
      final newAlignmentOffsetMs =
          oldAlignmentOffsetMs + (nextStartMs - oldStartMs);

      await _undoManager.execute(
        MoveClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldOffset: clip.offset,
          oldRow: clip.rowIndex,
          newOffset: nextStartMs / 1000.0,
          newRow: clip.rowIndex,
          oldAlignmentOffsetMs: oldAlignmentOffsetMs,
          newAlignmentOffsetMs: newAlignmentOffsetMs,
          onChange: () {
            clip.rowId = _rowIdAt(clip.rowIndex);
            unawaited(_syncClipTimingToEngine(clipIndex));
            _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
            if (mounted) setState(() {});
          },
        ),
      );
      changed++;
    }

    if (changed <= 0) {
      _insertAssistantChatText(
        'No clear first-sound boundary was detected for the target clip(s).',
      );
      return;
    }

    _showSmallNotice(
      'Aligned first sound on $changed clip${changed == 1 ? '' : 's'}.',
    );
  }

  double _clipTimelineStartMs(AudioTrack clip) => clip.offset * 1000.0;

  double _clipTimelineEndMs(AudioTrack clip) =>
      _clipTimelineStartMs(clip) + _clipTimelineDurationMs(clip);

  String _normalizedClipPath(String path) => p.normalize(path);

  String _decodeDisplayPathSegment(String value) {
    final trimmed = value.trim();
    if (trimmed.isEmpty || !trimmed.contains('%')) return trimmed;
    try {
      return Uri.decodeFull(trimmed);
    } catch (_) {
      return trimmed;
    }
  }

  String _displayNameForFilePath(String path) {
    final base = p.basename(path).trim();
    final rawLabel = base.isEmpty ? path.trim() : base;
    final decodedLabel = _decodeDisplayPathSegment(rawLabel);
    return decodedLabel.isEmpty ? rawLabel : decodedLabel;
  }

  String _displayStemForFilePath(String path) {
    final fileName = _displayNameForFilePath(path);
    final extension = p.extension(fileName);
    if (extension.isEmpty) return fileName;
    return fileName.substring(0, fileName.length - extension.length);
  }

  int? _findAudioClipIndexAtTimelineMs(
    double timelineMs, {
    int? rowIndex,
    String? filePath,
    int? preferEngineClipId,
  }) {
    if (!timelineMs.isFinite) return null;
    final expectedPath = filePath == null
        ? null
        : _normalizedClipPath(filePath);
    final candidates = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      final clip = _audioTracks[i];
      if (clip.isMidi) continue;
      if (rowIndex != null && clip.rowIndex != rowIndex) continue;
      if (expectedPath != null &&
          _normalizedClipPath(clip.file.path) != expectedPath) {
        continue;
      }
      final startMs = _clipTimelineStartMs(clip);
      final endMs = _clipTimelineEndMs(clip);
      if (timelineMs < startMs - 0.5 || timelineMs > endMs + 0.5) continue;
      candidates.add(i);
    }
    if (candidates.isEmpty) return null;
    if (preferEngineClipId != null && preferEngineClipId >= 0) {
      for (final idx in candidates) {
        if (_audioTracks[idx].engineClipId == preferEngineClipId) {
          return idx;
        }
      }
    }
    candidates.sort((a, b) {
      final aStart = _clipTimelineStartMs(_audioTracks[a]);
      final bStart = _clipTimelineStartMs(_audioTracks[b]);
      final aDist = (aStart - timelineMs).abs();
      final bDist = (bStart - timelineMs).abs();
      final byDist = aDist.compareTo(bDist);
      if (byDist != 0) return byDist;
      return a.compareTo(b);
    });
    return candidates.first;
  }

  List<MapEntry<double, double>> _mergeTimelineRangesMs(
    Iterable<MapEntry<double, double>> ranges, {
    double minGapMs = 45.0,
    double minLengthMs = 25.0,
    double? minMs,
    double? maxMs,
  }) {
    final normalized = <MapEntry<double, double>>[];
    for (final r in ranges) {
      double start = r.key;
      double end = r.value;
      if (!start.isFinite || !end.isFinite) continue;
      if (end < start) {
        final tmp = start;
        start = end;
        end = tmp;
      }
      if (minMs != null || maxMs != null) {
        final lo = minMs ?? double.negativeInfinity;
        final hi = maxMs ?? double.infinity;
        start = start.clamp(lo, hi).toDouble();
        end = end.clamp(lo, hi).toDouble();
      }
      if (!start.isFinite || !end.isFinite) continue;
      if (end - start < minLengthMs) continue;
      normalized.add(MapEntry(start, end));
    }
    if (normalized.isEmpty) return const <MapEntry<double, double>>[];
    normalized.sort((a, b) => a.key.compareTo(b.key));

    final merged = <MapEntry<double, double>>[];
    double currentStart = normalized.first.key;
    double currentEnd = normalized.first.value;

    for (int i = 1; i < normalized.length; i++) {
      final next = normalized[i];
      if (next.key <= currentEnd + minGapMs) {
        currentEnd = math.max(currentEnd, next.value);
      } else {
        merged.add(MapEntry(currentStart, currentEnd));
        currentStart = next.key;
        currentEnd = next.value;
      }
    }
    merged.add(MapEntry(currentStart, currentEnd));
    return merged
        .where((r) => (r.value - r.key) >= minLengthMs)
        .toList(growable: false);
  }

  double _quantile(List<double> values, double q) {
    if (values.isEmpty) return 0.0;
    final sorted = List<double>.from(values)..sort();
    final safeQ = q.clamp(0.0, 1.0).toDouble();
    final pos = safeQ * (sorted.length - 1);
    final lo = pos.floor();
    final hi = pos.ceil();
    if (lo == hi) return sorted[lo];
    final t = pos - lo;
    return sorted[lo] * (1.0 - t) + sorted[hi] * t;
  }

  Future<_ClipMono16kSegment?> _decodeTrimmedClipMono16k(
    AudioTrack clip,
  ) async {
    if (clip.isMidi) return null;
    const sampleRate = 16000;
    Float32List decoded = Float32List(0);
    try {
      decoded = await JuceAudioEngine.decodeAudioMono16k(clip.file.path);
    } catch (_) {
      return null;
    }
    if (decoded.isEmpty) return null;

    int start = (clip.trimStart.inMilliseconds * sampleRate / 1000).round();
    int end = (clip.trimEnd.inMilliseconds * sampleRate / 1000).round();
    start = start.clamp(0, decoded.length);
    end = end.clamp(start, decoded.length);
    if (end <= start + 32) return null;

    final samples = Float32List.fromList(decoded.sublist(start, end));
    if (samples.isEmpty) return null;

    final localDurationMs = samples.length * 1000.0 / sampleRate;
    final timelineDurationMs = _clipTimelineDurationMs(
      clip,
    ).clamp(1.0, 1.0e12).toDouble();
    final timelineScale = localDurationMs > 0.0
        ? timelineDurationMs / localDurationMs
        : 1.0;
    final timelineStartMs = _clipTimelineStartMs(clip);
    final timelineEndMs = timelineStartMs + localDurationMs * timelineScale;

    return _ClipMono16kSegment(
      samples: samples,
      sampleRate: sampleRate,
      timelineStartMs: timelineStartMs,
      timelineEndMs: timelineEndMs,
      timelineMsPerLocalMs: timelineScale,
    );
  }

  List<double> _frameRmsSeries(
    Float32List samples, {
    int frameSize = 320,
    int hopSize = 160,
  }) {
    if (samples.length < frameSize || hopSize <= 0) return const <double>[];
    final out = <double>[];
    for (int i = 0; i + frameSize <= samples.length; i += hopSize) {
      double sumSq = 0.0;
      for (int j = 0; j < frameSize; j++) {
        final s = samples[i + j];
        sumSq += s * s;
      }
      out.add(math.sqrt(sumSq / frameSize));
    }
    return out;
  }

  Float32List _downsampleMonoSamples(Float32List samples, {int factor = 4}) {
    if (factor <= 1 || samples.isEmpty) return Float32List.fromList(samples);
    final outLength = (samples.length / factor).floor();
    if (outLength <= 0) return Float32List(0);
    final out = Float32List(outLength);
    for (int i = 0; i < outLength; i++) {
      final start = i * factor;
      double sum = 0.0;
      for (int j = 0; j < factor; j++) {
        sum += samples[start + j];
      }
      out[i] = sum / factor;
    }
    return out;
  }

  int? _medianIntValue(List<int> values) {
    if (values.isEmpty) return null;
    final sorted = List<int>.from(values)..sort();
    return sorted[sorted.length ~/ 2];
  }

  _PitchEstimate? _estimatePitchForWindow(
    Float32List samples, {
    required int start,
    required int length,
    required int sampleRate,
    double minHz = 45.0,
    double maxHz = 1000.0,
  }) {
    if (sampleRate <= 0 || length <= 16) return null;
    final safeStart = start.clamp(0, samples.length);
    final safeEnd = math.min(samples.length, safeStart + length);
    final windowLength = safeEnd - safeStart;
    if (windowLength < 32) return null;

    double mean = 0.0;
    for (int i = safeStart; i < safeEnd; i++) {
      mean += samples[i];
    }
    mean /= windowLength;

    final minLag = math.max(2, (sampleRate / maxHz).floor());
    final maxLag = math.min(
      windowLength - 2,
      math.max(minLag + 1, (sampleRate / minHz).ceil()),
    );
    if (maxLag <= minLag) return null;

    double bestCorr = 0.0;
    int bestLag = 0;
    double? prevCorr;
    double currCorr = 0.0;

    for (int lag = minLag; lag <= maxLag; lag++) {
      double numerator = 0.0;
      double leftEnergy = 0.0;
      double rightEnergy = 0.0;
      for (int i = safeStart; i + lag < safeEnd; i++) {
        final a = samples[i] - mean;
        final b = samples[i + lag] - mean;
        numerator += a * b;
        leftEnergy += a * a;
        rightEnergy += b * b;
      }
      final denom = math.sqrt(leftEnergy * rightEnergy);
      final nextCorr = denom > 1.0e-9 ? numerator / denom : 0.0;
      if (prevCorr != null &&
          currCorr >= prevCorr &&
          currCorr >= nextCorr &&
          currCorr > bestCorr) {
        bestCorr = currCorr;
        bestLag = lag - 1;
      }
      prevCorr = currCorr;
      currCorr = nextCorr;
    }

    if (currCorr > bestCorr) {
      bestCorr = currCorr;
      bestLag = maxLag;
    }
    if (bestLag <= 0 || bestCorr < 0.38) return null;

    return _PitchEstimate(frequencyHz: sampleRate / bestLag, clarity: bestCorr);
  }

  List<MidiNote> _basicPitchEventsToMidiNotes(
    _ClipMono16kSegment segment,
    List<BasicPitchNoteEvent> events,
  ) {
    if (events.isEmpty) return const <MidiNote>[];
    final tempo = _clampTempo(_tempo);
    final msPerBeat = 60000.0 / tempo;
    final notes = <MidiNote>[];

    for (final event in events) {
      final localStartMs = event.startSeconds * 1000.0;
      final localEndMs = event.endSeconds * 1000.0;
      if (!localStartMs.isFinite ||
          !localEndMs.isFinite ||
          localEndMs <= localStartMs) {
        continue;
      }

      final timelineStartMs =
          segment.timelineStartMs + localStartMs * segment.timelineMsPerLocalMs;
      final timelineEndMs =
          segment.timelineStartMs + localEndMs * segment.timelineMsPerLocalMs;
      final startBeat = math.max(
        0.0,
        (timelineStartMs - segment.timelineStartMs) / msPerBeat,
      );
      final lengthBeats = math.max(
        0.0625,
        (timelineEndMs - timelineStartMs) / msPerBeat,
      );
      notes.add(
        MidiNote(
          id: 'ai_audio_midi_${DateTime.now().microsecondsSinceEpoch}_${notes.length}',
          pitch: event.pitchMidi.clamp(0, 127).toInt(),
          startBeat: startBeat,
          lengthBeats: lengthBeats,
          velocity: event.amplitude.clamp(0.25, 1.0),
        ),
      );
    }

    notes.sort((a, b) => a.startBeat.compareTo(b.startBeat));
    if (notes.length <= 1024) return notes;
    return notes.take(1024).map((note) => note.copy()).toList(growable: false);
  }

  List<MidiNote> _transcribeAudioClipToMidiNotesHeuristic(
    _ClipMono16kSegment segment,
  ) {
    const sourceSampleRate = 16000;
    const analysisSampleRate = 4000;
    const downsampleFactor = sourceSampleRate ~/ analysisSampleRate;
    const frameSize = 384;
    const hopSize = 128;
    final analysisSamples = _downsampleMonoSamples(
      segment.samples,
      factor: downsampleFactor,
    );
    if (analysisSamples.length < frameSize) return const <MidiNote>[];

    final rms = _frameRmsSeries(
      analysisSamples,
      frameSize: frameSize,
      hopSize: hopSize,
    );
    if (rms.isEmpty) return const <MidiNote>[];

    final noiseFloor = _quantile(rms, 0.2);
    final activeThreshold = math.max(0.006, noiseFloor * 2.25).toDouble();
    final activeRms = rms
        .where((value) => value >= activeThreshold)
        .toList(growable: false);
    if (activeRms.isEmpty) return const <MidiNote>[];
    final velocityReference = math.max(
      _quantile(activeRms, 0.85),
      activeThreshold,
    );

    final rawMidi = List<int?>.filled(rms.length, null, growable: false);
    for (int i = 0; i < rms.length; i++) {
      if (rms[i] < activeThreshold) continue;
      final estimate = _estimatePitchForWindow(
        analysisSamples,
        start: i * hopSize,
        length: frameSize,
        sampleRate: analysisSampleRate,
      );
      if (estimate == null || estimate.clarity < 0.42) continue;
      final midiValue =
          69.0 + 12.0 * (math.log(estimate.frequencyHz / 440.0) / math.ln2);
      if (!midiValue.isFinite) continue;
      rawMidi[i] = midiValue.round().clamp(0, 127).toInt();
    }

    final smoothedMidi = List<int?>.filled(
      rawMidi.length,
      null,
      growable: false,
    );
    for (int i = 0; i < rawMidi.length; i++) {
      final current = rawMidi[i];
      if (current == null) continue;
      final neighborhood = <int>[];
      for (
        int j = math.max(0, i - 1);
        j <= math.min(rawMidi.length - 1, i + 1);
        j++
      ) {
        final candidate = rawMidi[j];
        if (candidate != null) neighborhood.add(candidate);
      }
      smoothedMidi[i] = _medianIntValue(neighborhood) ?? current;
    }

    final notes = <MidiNote>[];
    final tempo = _clampTempo(_tempo);
    final msPerBeat = 60000.0 / tempo;
    int? noteStartFrame;
    int lastFrame = -1;
    final notePitches = <int>[];
    final noteLevels = <double>[];

    void flushNote() {
      if (noteStartFrame == null || lastFrame < noteStartFrame!) {
        noteStartFrame = null;
        notePitches.clear();
        noteLevels.clear();
        return;
      }

      final startSample = noteStartFrame! * hopSize;
      final endSample = math.min(
        analysisSamples.length,
        lastFrame * hopSize + frameSize,
      );
      final localStartMs = startSample * 1000.0 / analysisSampleRate;
      final localEndMs = endSample * 1000.0 / analysisSampleRate;
      final localDurationMs = localEndMs - localStartMs;
      if (localDurationMs < 85.0 || notePitches.isEmpty) {
        noteStartFrame = null;
        notePitches.clear();
        noteLevels.clear();
        return;
      }

      final medianPitch = _medianIntValue(notePitches);
      if (medianPitch == null) {
        noteStartFrame = null;
        notePitches.clear();
        noteLevels.clear();
        return;
      }

      final timelineStartMs =
          segment.timelineStartMs + localStartMs * segment.timelineMsPerLocalMs;
      final timelineEndMs =
          segment.timelineStartMs + localEndMs * segment.timelineMsPerLocalMs;
      final startBeat = math.max(
        0.0,
        (timelineStartMs - segment.timelineStartMs) / msPerBeat,
      );
      final lengthBeats = math.max(
        0.0625,
        (timelineEndMs - timelineStartMs) / msPerBeat,
      );
      final velocity =
          ((noteLevels.isEmpty
                      ? 0.72
                      : _quantile(noteLevels, 0.6) / velocityReference)
                  .clamp(0.3, 1.0))
              .toDouble();
      notes.add(
        MidiNote(
          id: 'ai_audio_midi_${DateTime.now().microsecondsSinceEpoch}_${notes.length}',
          pitch: medianPitch.clamp(0, 127).toInt(),
          startBeat: startBeat,
          lengthBeats: lengthBeats,
          velocity: velocity,
        ),
      );

      noteStartFrame = null;
      notePitches.clear();
      noteLevels.clear();
    }

    for (int i = 0; i < smoothedMidi.length; i++) {
      final pitch = smoothedMidi[i];
      if (pitch == null) {
        flushNote();
        continue;
      }
      if (noteStartFrame == null) {
        noteStartFrame = i;
        lastFrame = i;
        notePitches.add(pitch);
        noteLevels.add(rms[i]);
        continue;
      }

      final currentMedian = _medianIntValue(notePitches) ?? pitch;
      if ((pitch - currentMedian).abs() <= 1) {
        lastFrame = i;
        notePitches.add(pitch);
        noteLevels.add(rms[i]);
        continue;
      }

      flushNote();
      noteStartFrame = i;
      lastFrame = i;
      notePitches.add(pitch);
      noteLevels.add(rms[i]);
    }
    flushNote();

    if (notes.isEmpty) return const <MidiNote>[];
    notes.sort((a, b) => a.startBeat.compareTo(b.startBeat));

    final merged = <MidiNote>[];
    for (final note in notes) {
      if (merged.isNotEmpty) {
        final prev = merged.last;
        final prevEnd = prev.startBeat + prev.lengthBeats;
        if (prev.pitch == note.pitch && note.startBeat - prevEnd <= 0.125) {
          prev.lengthBeats = math.max(
            prev.lengthBeats,
            note.startBeat + note.lengthBeats - prev.startBeat,
          );
          prev.velocity = math.max(prev.velocity, note.velocity);
          continue;
        }
      }
      merged.add(note.copy());
    }

    if (merged.length <= 512) return merged;
    final trimmed = merged
        .where((note) => note.lengthBeats >= 0.08)
        .toList(growable: false);
    if (trimmed.isEmpty) {
      return merged
          .take(512)
          .map((note) => note.copy())
          .toList(growable: false);
    }
    return trimmed.take(512).map((note) => note.copy()).toList(growable: false);
  }

  Future<List<MidiNote>> _transcribeAudioClipToMidiNotes(
    AudioTrack clip,
  ) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MidiNote>[];
    try {
      final events = await BasicPitchTranscriber.instance.transcribeMono16k(
        segment.samples,
      );
      final notes = _basicPitchEventsToMidiNotes(segment, events);
      if (notes.isNotEmpty) {
        return notes;
      }
      aiDebugLog(
        'basic-pitch',
        'transcription returned no notes -> heuristic fallback',
      );
    } catch (error) {
      aiDebugLog('basic-pitch', 'transcription failed error=$error');
    }

    return _transcribeAudioClipToMidiNotesHeuristic(segment);
  }

  List<MapEntry<double, double>> _rangesFromFrameMask(
    List<bool> mask, {
    required int frameSize,
    required int hopSize,
    required int sampleRate,
    required int totalSamples,
    double minDurationMs = 80.0,
  }) {
    if (mask.isEmpty) return const <MapEntry<double, double>>[];
    final out = <MapEntry<double, double>>[];
    int startFrame = -1;

    for (int i = 0; i < mask.length; i++) {
      final active = mask[i];
      if (active && startFrame < 0) {
        startFrame = i;
      }
      final ended = startFrame >= 0 && (!active || i == mask.length - 1);
      if (!ended) continue;

      final endExclusive = (!active) ? i : i + 1;
      final startSample = startFrame * hopSize;
      final endSample = math.min(
        totalSamples,
        (endExclusive - 1) * hopSize + frameSize,
      );
      final startMs = startSample * 1000.0 / sampleRate;
      final endMs = endSample * 1000.0 / sampleRate;
      if (endMs - startMs >= minDurationMs) {
        out.add(MapEntry(startMs, endMs));
      }
      startFrame = -1;
    }

    return out;
  }

  Future<List<MapEntry<double, double>>> _detectDialogActiveSpeechRangesForClip(
    AudioTrack clip, {
    double minDurationMs = 110.0,
    double mergeGapMs = 120.0,
    double floorRms = 0.01,
    double thresholdMultiplier = 2.35,
  }) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MapEntry<double, double>>[];

    const frameSize = 320;
    const hopSize = 160;
    final rms = _frameRmsSeries(
      segment.samples,
      frameSize: frameSize,
      hopSize: hopSize,
    );
    if (rms.isEmpty) return const <MapEntry<double, double>>[];

    final noiseFloor = _quantile(rms, 0.2);
    final threshold = math
        .max(floorRms, noiseFloor * thresholdMultiplier)
        .toDouble();
    final activeMask = rms.map((v) => v >= threshold).toList(growable: false);
    final localRanges = _rangesFromFrameMask(
      activeMask,
      frameSize: frameSize,
      hopSize: hopSize,
      sampleRate: segment.sampleRate,
      totalSamples: segment.samples.length,
      minDurationMs: minDurationMs,
    );
    if (localRanges.isEmpty) return const <MapEntry<double, double>>[];

    final localDurationMs =
        segment.samples.length * 1000.0 / segment.sampleRate.toDouble();
    final mergedLocal = _mergeTimelineRangesMs(
      localRanges,
      minGapMs: mergeGapMs,
      minLengthMs: minDurationMs,
      minMs: 0.0,
      maxMs: localDurationMs,
    );
    if (mergedLocal.isEmpty) return const <MapEntry<double, double>>[];

    final timelineRanges = mergedLocal
        .map(
          (r) => MapEntry(
            segment.timelineStartMs + r.key * segment.timelineMsPerLocalMs,
            segment.timelineStartMs + r.value * segment.timelineMsPerLocalMs,
          ),
        )
        .toList(growable: false);
    return _mergeTimelineRangesMs(
      timelineRanges,
      minGapMs: mergeGapMs * segment.timelineMsPerLocalMs,
      minLengthMs: minDurationMs * segment.timelineMsPerLocalMs,
      minMs: segment.timelineStartMs,
      maxMs: segment.timelineEndMs,
    );
  }

  MapEntry<double, double>? _deriveDialogPhraseRangeAroundAnchor(
    AudioTrack clip,
    List<MapEntry<double, double>> activeRanges,
    double anchorMs, {
    double prePadMs = 35.0,
    double postPadMs = 70.0,
  }) {
    if (activeRanges.isEmpty) return null;
    final clipStart = _clipTimelineStartMs(clip);
    final clipEnd = _clipTimelineEndMs(clip);
    final probe = anchorMs.clamp(clipStart, clipEnd).toDouble();

    MapEntry<double, double>? best;
    double bestScore = double.infinity;
    for (final r in activeRanges) {
      if (probe >= r.key && probe <= r.value) {
        best = r;
        break;
      }
      final center = (r.key + r.value) * 0.5;
      final dist = (center - probe).abs();
      if (dist < bestScore) {
        bestScore = dist;
        best = r;
      }
    }
    if (best == null) return null;

    final start = (best.key - prePadMs).clamp(clipStart, clipEnd).toDouble();
    final end = (best.value + postPadMs)
        .clamp(start + 15.0, clipEnd)
        .toDouble();
    if (end - start < 20.0) return null;
    return MapEntry(start, end);
  }

  List<MapEntry<double, double>> _dialogRangesFromActionDataForClip(
    Map<String, dynamic> data,
    AudioTrack clip, {
    bool preferClipRelative = false,
  }) {
    final target = _actionTarget(data);
    final clipStartMs = _clipTimelineStartMs(clip);
    final clipEndMs = _clipTimelineEndMs(clip);

    bool resolveClipRelative(Map<String, dynamic> source) {
      final explicit = _toActionBool(
        source['clip_relative'] ??
            source['local_ms'] ??
            source['relative_to_clip'],
        fallback: false,
      );
      if (explicit) return true;
      final domain =
          (source['time_domain'] ??
                  source['range_domain'] ??
                  source['domain'] ??
                  '')
              .toString()
              .trim()
              .toLowerCase();
      if (domain == 'clip' ||
          domain == 'local' ||
          domain == 'clip_local' ||
          domain == 'clip_relative') {
        return true;
      }
      return false;
    }

    final out = <MapEntry<double, double>>[];

    void parseRange(Map<String, dynamic> src) {
      final clipRelative = resolveClipRelative(src);
      double? from = _toActionDouble(
        src['from_ms'] ?? src['start_ms'] ?? src['begin_ms'] ?? src['in_ms'],
      );
      double? to = _toActionDouble(
        src['to_ms'] ?? src['end_ms'] ?? src['out_ms'],
      );
      final length = _toActionDouble(src['length_ms'] ?? src['duration_ms']);
      final at = _toActionDouble(src['at_ms'] ?? src['time_ms']);

      if (from == null && at != null && length != null) {
        from = at;
        to = at + length;
      } else if (to == null && from != null && length != null) {
        to = from + length;
      }
      if (from == null || to == null) return;

      if (clipRelative) {
        from += clipStartMs;
        to += clipStartMs;
      }
      if (!from.isFinite || !to.isFinite) return;
      out.add(MapEntry(from, to));
    }

    final rangeLists = <List?>[
      data['ranges'] as List?,
      target['ranges'] as List?,
      data['regions'] as List?,
      target['regions'] as List?,
      data['segments'] as List?,
      target['segments'] as List?,
    ];
    for (final rawList in rangeLists) {
      if (rawList == null) continue;
      for (final raw in rawList) {
        final m = _toActionMap(raw);
        if (m.isEmpty) continue;
        parseRange(m);
      }
    }

    final topRange = <String, dynamic>{
      ...target,
      ...data,
      if (preferClipRelative) 'clip_relative': true,
    };
    parseRange(topRange);

    return _mergeTimelineRangesMs(
      out,
      minGapMs: 10.0,
      minLengthMs: 18.0,
      minMs: clipStartMs,
      maxMs: clipEndMs,
    );
  }

  Future<List<MapEntry<double, double>>> _detectDialogCoughRangesForClip(
    AudioTrack clip, {
    double thresholdStd = 2.2,
    double minDurationMs = 40.0,
    double maxDurationMs = 650.0,
    double prePadMs = 18.0,
    double postPadMs = 120.0,
    double minHighFreqRatio = 0.42,
    int maxRanges = 12,
  }) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MapEntry<double, double>>[];
    const frameSize = 256;
    const hopSize = 128;
    if (segment.samples.length < frameSize) {
      return const <MapEntry<double, double>>[];
    }

    final low = _lowPassMono(
      segment.samples,
      sampleRate: segment.sampleRate,
      cutoffHz: 900.0,
    );

    final scores = <double>[];
    final hfRatios = <double>[];
    for (int i = 0; i + frameSize <= segment.samples.length; i += hopSize) {
      double absSum = 0.0;
      double hfSum = 0.0;
      for (int j = 0; j < frameSize; j++) {
        final s = segment.samples[i + j];
        absSum += s.abs();
        hfSum += (s - low[i + j]).abs();
      }
      final energy = absSum / frameSize;
      final hfRatio = hfSum / (absSum + 1e-9);
      final score = energy * (0.35 + hfRatio);
      scores.add(score);
      hfRatios.add(hfRatio);
    }
    if (scores.length < 6) return const <MapEntry<double, double>>[];

    double mean = 0.0;
    for (final s in scores) {
      mean += s;
    }
    mean /= scores.length;

    double variance = 0.0;
    for (final s in scores) {
      final d = s - mean;
      variance += d * d;
    }
    variance /= scores.length;
    final std = math.sqrt(math.max(variance, 0.0));
    final threshold = math.max(mean + std * thresholdStd, mean * 2.6);

    final local = <MapEntry<double, double>>[];
    int startFrame = -1;
    for (int i = 0; i < scores.length; i++) {
      final hit = scores[i] >= threshold;
      if (hit && startFrame < 0) {
        startFrame = i;
      }
      final ended = startFrame >= 0 && (!hit || i == scores.length - 1);
      if (!ended) continue;

      final endExclusive = (!hit) ? i : i + 1;
      final segmentStartSample = startFrame * hopSize;
      final segmentEndSample = math.min(
        segment.samples.length,
        (endExclusive - 1) * hopSize + frameSize,
      );
      final durMs =
          (segmentEndSample - segmentStartSample) * 1000.0 / segment.sampleRate;
      if (durMs >= minDurationMs && durMs <= maxDurationMs) {
        double ratioSum = 0.0;
        int count = 0;
        for (int f = startFrame; f < endExclusive; f++) {
          ratioSum += hfRatios[f];
          count++;
        }
        final avgRatio = count > 0 ? ratioSum / count : 0.0;
        if (avgRatio >= minHighFreqRatio) {
          final startMs = segmentStartSample * 1000.0 / segment.sampleRate;
          final endMs = segmentEndSample * 1000.0 / segment.sampleRate;
          local.add(
            MapEntry(math.max(0.0, startMs - prePadMs), endMs + postPadMs),
          );
        }
      }
      startFrame = -1;
    }

    if (local.isEmpty) return const <MapEntry<double, double>>[];
    final localDurationMs =
        segment.samples.length * 1000.0 / segment.sampleRate.toDouble();
    final mergedLocal = _mergeTimelineRangesMs(
      local,
      minGapMs: 70.0,
      minLengthMs: minDurationMs,
      minMs: 0.0,
      maxMs: localDurationMs,
    );
    if (mergedLocal.isEmpty) return const <MapEntry<double, double>>[];

    final timeline = mergedLocal
        .take(maxRanges)
        .map(
          (r) => MapEntry(
            segment.timelineStartMs + r.key * segment.timelineMsPerLocalMs,
            segment.timelineStartMs + r.value * segment.timelineMsPerLocalMs,
          ),
        )
        .toList(growable: false);

    return _mergeTimelineRangesMs(
      timeline,
      minGapMs: 80.0,
      minLengthMs: minDurationMs * segment.timelineMsPerLocalMs,
      minMs: segment.timelineStartMs,
      maxMs: segment.timelineEndMs,
    );
  }

  Future<List<MapEntry<double, double>>> _detectDialogQuietRangesForClip(
    AudioTrack clip, {
    double quietRatio = 0.62,
    double minDurationMs = 180.0,
    int maxRanges = 10,
  }) async {
    final segment = await _decodeTrimmedClipMono16k(clip);
    if (segment == null) return const <MapEntry<double, double>>[];

    const frameSize = 320;
    const hopSize = 160;
    final rms = _frameRmsSeries(
      segment.samples,
      frameSize: frameSize,
      hopSize: hopSize,
    );
    if (rms.length < 6) return const <MapEntry<double, double>>[];

    final noiseFloor = _quantile(rms, 0.2);
    final activeThreshold = math.max(0.008, noiseFloor * 2.2);
    final activeMask = rms.map((v) => v >= activeThreshold).toList();
    final activeRms = <double>[];
    for (int i = 0; i < rms.length; i++) {
      if (activeMask[i]) activeRms.add(rms[i]);
    }
    if (activeRms.length < 3) return const <MapEntry<double, double>>[];

    final speechTargetRms = _quantile(activeRms, 0.68);
    final quietThreshold = math.max(
      noiseFloor * 2.0,
      speechTargetRms * quietRatio,
    );
    final quietMask = List<bool>.generate(
      rms.length,
      (i) => activeMask[i] && rms[i] < quietThreshold,
      growable: false,
    );
    final localRanges = _rangesFromFrameMask(
      quietMask,
      frameSize: frameSize,
      hopSize: hopSize,
      sampleRate: segment.sampleRate,
      totalSamples: segment.samples.length,
      minDurationMs: minDurationMs,
    );
    if (localRanges.isEmpty) return const <MapEntry<double, double>>[];

    final localDurationMs =
        segment.samples.length * 1000.0 / segment.sampleRate.toDouble();
    final mergedLocal = _mergeTimelineRangesMs(
      localRanges,
      minGapMs: 80.0,
      minLengthMs: minDurationMs,
      minMs: 0.0,
      maxMs: localDurationMs,
    );
    if (mergedLocal.isEmpty) return const <MapEntry<double, double>>[];

    final timeline = mergedLocal
        .take(maxRanges)
        .map(
          (r) => MapEntry(
            segment.timelineStartMs + r.key * segment.timelineMsPerLocalMs,
            segment.timelineStartMs + r.value * segment.timelineMsPerLocalMs,
          ),
        )
        .toList(growable: false);

    return _mergeTimelineRangesMs(
      timeline,
      minGapMs: 90.0,
      minLengthMs: minDurationMs * segment.timelineMsPerLocalMs,
      minMs: segment.timelineStartMs,
      maxMs: segment.timelineEndMs,
    );
  }

  Future<List<MapEntry<double, double>>> _detectDialogPauseRemovalRangesForClip(
    AudioTrack clip, {
    double minPauseMs = 260.0,
    double keepPauseMs = 90.0,
    int maxRanges = 14,
  }) async {
    final activeRanges = await _detectDialogActiveSpeechRangesForClip(
      clip,
      minDurationMs: 110.0,
      mergeGapMs: 120.0,
    );
    if (activeRanges.length < 2) return const <MapEntry<double, double>>[];

    final clipStart = _clipTimelineStartMs(clip);
    final clipEnd = _clipTimelineEndMs(clip);
    final out = <MapEntry<double, double>>[];

    for (int i = 1; i < activeRanges.length; i++) {
      final prev = activeRanges[i - 1];
      final next = activeRanges[i];
      final pauseStart = prev.value;
      final pauseEnd = next.key;
      final pauseLength = pauseEnd - pauseStart;
      if (pauseLength < minPauseMs) continue;

      final keep = keepPauseMs.clamp(20.0, pauseLength - 20.0).toDouble();
      if (pauseLength <= keep + 20.0) continue;

      final removeStart = (pauseStart + keep * 0.5)
          .clamp(clipStart, clipEnd)
          .toDouble();
      final removeEnd = (pauseEnd - keep * 0.5)
          .clamp(removeStart + 15.0, clipEnd)
          .toDouble();
      if (removeEnd - removeStart >= 20.0) {
        out.add(MapEntry(removeStart, removeEnd));
      }
      if (out.length >= maxRanges) break;
    }

    return _mergeTimelineRangesMs(
      out,
      minGapMs: 50.0,
      minLengthMs: 20.0,
      minMs: clipStart,
      maxMs: clipEnd,
    );
  }

  Future<int?> _isolateTimelineRangeAsClipSegment({
    required double fromMs,
    required double toMs,
    required int rowIndex,
    required String filePath,
    int? preferEngineClipId,
  }) async {
    if (!fromMs.isFinite || !toMs.isFinite) return null;
    double safeFrom = math.min(fromMs, toMs);
    double safeTo = math.max(fromMs, toMs);
    if (safeTo - safeFrom < 20.0) return null;

    final midProbeInitial = (safeFrom + safeTo) * 0.5;
    int? targetIdx = _findAudioClipIndexAtTimelineMs(
      midProbeInitial,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (targetIdx == null) return null;

    final targetClip = _audioTracks[targetIdx];
    final clipStart = _clipTimelineStartMs(targetClip);
    final clipEnd = _clipTimelineEndMs(targetClip);
    safeFrom = safeFrom.clamp(clipStart, clipEnd - 2.0).toDouble();
    safeTo = safeTo.clamp(safeFrom + 2.0, clipEnd).toDouble();
    if (safeTo - safeFrom < 20.0) return null;

    if (safeFrom > clipStart + 1.0) {
      await _handleCutClipAt(targetIdx, safeFrom);
    }

    final midProbe = (safeFrom + safeTo) * 0.5;
    int? midIdx = _findAudioClipIndexAtTimelineMs(
      midProbe,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (midIdx == null) return null;

    final midClip = _audioTracks[midIdx];
    final midStart = _clipTimelineStartMs(midClip);
    final midEnd = _clipTimelineEndMs(midClip);
    final cutEnd = safeTo.clamp(midStart + 1.0, midEnd).toDouble();
    if (cutEnd < midEnd - 1.0) {
      await _handleCutClipAt(midIdx, cutEnd);
    }

    return _findAudioClipIndexAtTimelineMs(
      midProbe,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
  }

  Future<bool> _removeTimelineRangeFromClip({
    required double fromMs,
    required double toMs,
    required int rowIndex,
    required String filePath,
    int? preferEngineClipId,
  }) async {
    final isolatedIdx = await _isolateTimelineRangeAsClipSegment(
      fromMs: fromMs,
      toMs: toMs,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (isolatedIdx == null ||
        isolatedIdx < 0 ||
        isolatedIdx >= _audioTracks.length) {
      return false;
    }
    await _handleDeleteClip(isolatedIdx);
    return true;
  }

  Future<bool> _boostTimelineRangeOnClip({
    required double fromMs,
    required double toMs,
    required int rowIndex,
    required String filePath,
    required double gainMultiplier,
    required double maxGain,
    int? preferEngineClipId,
  }) async {
    final isolatedIdx = await _isolateTimelineRangeAsClipSegment(
      fromMs: fromMs,
      toMs: toMs,
      rowIndex: rowIndex,
      filePath: filePath,
      preferEngineClipId: preferEngineClipId,
    );
    if (isolatedIdx == null ||
        isolatedIdx < 0 ||
        isolatedIdx >= _audioTracks.length) {
      return false;
    }
    final clip = _audioTracks[isolatedIdx];
    final oldGain = clip.gain;
    final nextGain = (oldGain * gainMultiplier).clamp(0.0, maxGain).toDouble();
    if ((nextGain - oldGain).abs() < 0.015) return false;

    await _undoManager.execute(
      SetClipGainAction(
        tracks: _audioTracks,
        originalIndex: isolatedIdx,
        oldGain: oldGain,
        newGain: nextGain,
        applyToState: (target, gain) {
          target.gain = gain;
          if (mounted) setState(() {});
        },
      ),
    );
    return true;
  }

  Future<int> _applyDialogRangeDeletesForClip(
    AudioTrack clip,
    List<MapEntry<double, double>> ranges, {
    int maxEdits = 12,
  }) async {
    if (ranges.isEmpty) return 0;
    final row = clip.rowIndex;
    final filePath = clip.file.path;
    final preferredEngine = clip.engineClipId >= 0 ? clip.engineClipId : null;
    final ordered = List<MapEntry<double, double>>.from(ranges)
      ..sort((a, b) => b.key.compareTo(a.key));

    int applied = 0;
    for (final range in ordered.take(maxEdits)) {
      final ok = await _removeTimelineRangeFromClip(
        fromMs: range.key,
        toMs: range.value,
        rowIndex: row,
        filePath: filePath,
        preferEngineClipId: preferredEngine,
      );
      if (ok) applied++;
    }
    return applied;
  }

  Future<int> _applyDialogLiftForClip(
    AudioTrack clip,
    List<MapEntry<double, double>> ranges, {
    required double gainMultiplier,
    required double maxGain,
    int maxEdits = 8,
  }) async {
    if (ranges.isEmpty) return 0;
    final row = clip.rowIndex;
    final filePath = clip.file.path;
    final preferredEngine = clip.engineClipId >= 0 ? clip.engineClipId : null;
    final ordered = List<MapEntry<double, double>>.from(ranges)
      ..sort((a, b) => b.key.compareTo(a.key));

    int applied = 0;
    for (final range in ordered.take(maxEdits)) {
      final ok = await _boostTimelineRangeOnClip(
        fromMs: range.key,
        toMs: range.value,
        rowIndex: row,
        filePath: filePath,
        preferEngineClipId: preferredEngine,
        gainMultiplier: gainMultiplier,
        maxGain: maxGain,
      );
      if (ok) applied++;
    }
    return applied;
  }

  Future<void> _applyDialogClipEditOperation(
    Map<String, dynamic> data, {
    required String operation,
  }) async {
    final target = _actionTarget(data);
    final clipIndices = _resolveClipIndicesFromActionTarget(
      data,
      requireAudio: true,
    );
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
        "I couldn't resolve which audio clip to edit. Select a clip and ask again.",
      );
      return;
    }

    final maxEdits =
        (_toActionInt(
                  data['max_edits'] ??
                      target['max_edits'] ??
                      data['max_events'],
                ) ??
                10)
            .clamp(1, 48);
    final anchorMs =
        (_toActionDouble(
                  data['at_ms'] ??
                      target['at_ms'] ??
                      data['time_ms'] ??
                      target['time_ms'],
                ) ??
                _globalAudioClock.inMilliseconds.toDouble())
            .toDouble();

    int deletedSegments = 0;
    int liftedSegments = 0;
    int touchedClips = 0;

    for (final clipIndex in clipIndices) {
      if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
      final clip = _audioTracks[clipIndex];
      if (clip.isMidi) continue;

      if (operation == 'dialog_cleanup') {
        final manual = _dialogRangesFromActionDataForClip(
          data,
          clip,
          preferClipRelative: true,
        );
        final detected = await _detectDialogCoughRangesForClip(
          clip,
          thresholdStd:
              (_toActionDouble(
                        data['artifact_threshold_std'] ??
                            target['artifact_threshold_std'] ??
                            data['transient_threshold_std'] ??
                            target['transient_threshold_std'],
                      ) ??
                      2.2)
                  .clamp(0.8, 4.8)
                  .toDouble(),
          minDurationMs:
              (_toActionDouble(
                        data['min_event_ms'] ?? target['min_event_ms'],
                      ) ??
                      40.0)
                  .clamp(15.0, 1200.0)
                  .toDouble(),
          maxDurationMs:
              (_toActionDouble(
                        data['max_event_ms'] ?? target['max_event_ms'],
                      ) ??
                      650.0)
                  .clamp(80.0, 2500.0)
                  .toDouble(),
          minHighFreqRatio:
              (_toActionDouble(
                        data['min_hf_ratio'] ?? target['min_hf_ratio'],
                      ) ??
                      0.42)
                  .clamp(0.2, 0.9)
                  .toDouble(),
          maxRanges: maxEdits,
        );
        final ranges = manual.isNotEmpty ? manual : detected;
        if (ranges.isEmpty) continue;
        final removed = await _applyDialogRangeDeletesForClip(
          clip,
          ranges,
          maxEdits: maxEdits,
        );
        if (removed > 0) {
          deletedSegments += removed;
          touchedClips++;
        }
        continue;
      }

      if (operation == 'dialog_remove_range') {
        var ranges = _dialogRangesFromActionDataForClip(
          data,
          clip,
          preferClipRelative: true,
        );
        if (ranges.isEmpty) {
          final clipStart = _clipTimelineStartMs(clip);
          final clipEnd = _clipTimelineEndMs(clip);
          final inClip = anchorMs >= clipStart && anchorMs <= clipEnd;
          if (!inClip && clipIndices.length > 1) {
            continue;
          }
          final active = await _detectDialogActiveSpeechRangesForClip(clip);
          final phrase = _deriveDialogPhraseRangeAroundAnchor(
            clip,
            active,
            anchorMs,
            prePadMs:
                (_toActionDouble(
                          data['phrase_pre_pad_ms'] ??
                              target['phrase_pre_pad_ms'],
                        ) ??
                        35.0)
                    .clamp(0.0, 400.0)
                    .toDouble(),
            postPadMs:
                (_toActionDouble(
                          data['phrase_post_pad_ms'] ??
                              target['phrase_post_pad_ms'],
                        ) ??
                        70.0)
                    .clamp(0.0, 500.0)
                    .toDouble(),
          );
          if (phrase != null) {
            ranges = <MapEntry<double, double>>[phrase];
          }
        }
        if (ranges.isEmpty) continue;
        final removed = await _applyDialogRangeDeletesForClip(
          clip,
          ranges,
          maxEdits: maxEdits,
        );
        if (removed > 0) {
          deletedSegments += removed;
          touchedClips++;
        }
        continue;
      }

      if (operation == 'dialog_tighten_pauses') {
        final ranges = await _detectDialogPauseRemovalRangesForClip(
          clip,
          minPauseMs:
              (_toActionDouble(
                        data['min_pause_ms'] ?? target['min_pause_ms'],
                      ) ??
                      260.0)
                  .clamp(80.0, 6000.0)
                  .toDouble(),
          keepPauseMs:
              (_toActionDouble(
                        data['keep_pause_ms'] ?? target['keep_pause_ms'],
                      ) ??
                      90.0)
                  .clamp(20.0, 1400.0)
                  .toDouble(),
          maxRanges: maxEdits,
        );
        if (ranges.isEmpty) continue;
        final removed = await _applyDialogRangeDeletesForClip(
          clip,
          ranges,
          maxEdits: maxEdits,
        );
        if (removed > 0) {
          deletedSegments += removed;
          touchedClips++;
        }
        continue;
      }

      if (operation == 'dialog_lift_quiet') {
        var ranges = _dialogRangesFromActionDataForClip(
          data,
          clip,
          preferClipRelative: true,
        );
        if (ranges.isEmpty) {
          ranges = await _detectDialogQuietRangesForClip(
            clip,
            quietRatio:
                (_toActionDouble(
                          data['quiet_ratio'] ?? target['quiet_ratio'],
                        ) ??
                        0.62)
                    .clamp(0.2, 0.95)
                    .toDouble(),
            minDurationMs:
                (_toActionDouble(
                          data['min_quiet_ms'] ?? target['min_quiet_ms'],
                        ) ??
                        180.0)
                    .clamp(40.0, 3000.0)
                    .toDouble(),
            maxRanges: maxEdits,
          );
        }
        if (ranges.isEmpty) continue;

        final boostDb =
            (_toActionDouble(
                      data['boost_db'] ??
                          target['boost_db'] ??
                          data['gain_db'] ??
                          target['gain_db'],
                    ) ??
                    4.0)
                .clamp(0.5, 12.0)
                .toDouble();
        final gainMultiplier = math.pow(10.0, boostDb / 20.0).toDouble();
        final maxGain =
            (_toActionDouble(data['max_gain'] ?? target['max_gain']) ?? 3.0)
                .clamp(0.2, 3.0)
                .toDouble();

        final lifted = await _applyDialogLiftForClip(
          clip,
          ranges,
          gainMultiplier: gainMultiplier,
          maxGain: maxGain,
          maxEdits: maxEdits,
        );
        if (lifted > 0) {
          liftedSegments += lifted;
          touchedClips++;
        }
      }
    }

    final totalEdits = deletedSegments + liftedSegments;
    if (totalEdits <= 0) {
      switch (operation) {
        case 'dialog_cleanup':
          _insertAssistantChatText(
            'No clear cough/noise events were detected in the target clip.',
          );
          break;
        case 'dialog_remove_range':
          _insertAssistantChatText(
            "I couldn't resolve a dialog segment to remove. Provide a time range or place the playhead near the sentence.",
          );
          break;
        case 'dialog_tighten_pauses':
          _insertAssistantChatText('No long pauses were found to tighten.');
          break;
        case 'dialog_lift_quiet':
          _insertAssistantChatText(
            'No quiet speech ranges were found to lift.',
          );
          break;
        default:
          break;
      }
      return;
    }

    if (operation == 'dialog_lift_quiet' && liftedSegments > 0) {
      _showSmallNotice(
        'Boosted $liftedSegments quiet segment${liftedSegments == 1 ? '' : 's'} on $touchedClips clip${touchedClips == 1 ? '' : 's'}.',
      );
      return;
    }

    _showSmallNotice(
      'Edited $deletedSegments dialog segment${deletedSegments == 1 ? '' : 's'} on $touchedClips clip${touchedClips == 1 ? '' : 's'}.',
    );
  }

  Future<void> _applyClipEditAction(Map<String, dynamic> data) async {
    final rawOperation = (data['operation'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final operation = _normalizeClipEditOperation(rawOperation);

    if (operation == 'auto_bpm_align') {
      await _applyAutoBpmAlignAction(data);
      return;
    }

    if (operation == 'align_first_sound') {
      await _applyAlignFirstSoundAction(data);
      return;
    }

    if (operation == 'auto_trim') {
      final clipIndices = _resolveClipIndicesFromActionTarget(
        data,
        requireAudio: true,
      );
      if (clipIndices.isEmpty) {
        _insertAssistantChatText(
          "I couldn't resolve which audio clips to trim. Select clips and ask again.",
        );
        return;
      }

      final thresholdFloor =
          _toActionDouble(data['threshold_floor'])?.clamp(0.001, 1.0) ?? 0.012;
      final thresholdRatio =
          _toActionDouble(data['threshold_ratio'])?.clamp(0.001, 1.0) ?? 0.08;
      final paddingMs =
          _toActionDouble(data['padding_ms'])?.clamp(0.0, 500.0) ?? 8.0;
      final preserveContentPosition = _toActionBool(
        data['preserve_content_position'],
        fallback: true,
      );

      bool anyApplied = false;
      for (final clipIndex in clipIndices) {
        if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
        final clip = _audioTracks[clipIndex];
        if (clip.isMidi) continue;

        final explicitTrimStartMs = _toActionDouble(data['trim_start_ms']);
        final explicitTrimEndMs = _toActionDouble(data['trim_end_ms']);
        final estimated = _estimateAutoTrimBoundsMs(
          clip,
          thresholdFloor: thresholdFloor.toDouble(),
          thresholdRatio: thresholdRatio.toDouble(),
          paddingMs: paddingMs.toDouble(),
        );

        final nextTrimStartMs = explicitTrimStartMs ?? estimated?.key;
        final nextTrimEndMs = explicitTrimEndMs ?? estimated?.value;
        if (nextTrimStartMs == null || nextTrimEndMs == null) continue;

        final startDeltaSec =
            (nextTrimStartMs - clip.trimStart.inMilliseconds.toDouble()) /
            1000.0;
        final nextOffset = preserveContentPosition
            ? math.max(0.0, clip.offset + startDeltaSec)
            : null;

        await _applyTrimActionForClip(
          clipIndex,
          newTrimStartMs: nextTrimStartMs,
          newTrimEndMs: nextTrimEndMs,
          newOffsetSec: nextOffset,
        );
        anyApplied = true;
      }

      if (!anyApplied) {
        _insertAssistantChatText(
          'No silence boundaries were detected for the target clip(s).',
        );
      }
      return;
    }

    if (operation == 'trim') {
      final target = _actionTarget(data);
      final clipIndices = _resolveClipIndicesFromActionTarget(
        data,
        requireAudio: true,
      );
      if (clipIndices.isEmpty) {
        _insertAssistantChatText(
          "I couldn't resolve which audio clips to trim. Select clips and ask again.",
        );
        return;
      }

      final explicitTrimStartMs = _toActionDouble(
        data['trim_start_ms'] ?? target['trim_start_ms'],
      );
      final explicitTrimEndMs = _toActionDouble(
        data['trim_end_ms'] ?? target['trim_end_ms'],
      );
      final deltaTrimStartMs = _toActionDouble(
        data['delta_trim_start_ms'] ?? target['delta_trim_start_ms'],
      );
      final deltaTrimEndMs = _toActionDouble(
        data['delta_trim_end_ms'] ?? target['delta_trim_end_ms'],
      );
      final hasExplicitTrimValues =
          explicitTrimStartMs != null ||
          explicitTrimEndMs != null ||
          deltaTrimStartMs != null ||
          deltaTrimEndMs != null;

      final sideHint =
          (data['trim_side'] ??
                  target['trim_side'] ??
                  data['side'] ??
                  target['side'] ??
                  data['edge'] ??
                  target['edge'] ??
                  '')
              .toString()
              .trim()
              .toLowerCase();
      final trimStartOnlyHint =
          sideHint.contains('start') ||
          sideHint.contains('left') ||
          sideHint == 'in' ||
          sideHint == 'head' ||
          sideHint.contains('begin');
      final trimEndOnlyHint =
          sideHint.contains('end') ||
          sideHint.contains('right') ||
          sideHint == 'out' ||
          sideHint == 'tail';

      final thresholdFloor =
          _toActionDouble(
            data['threshold_floor'] ?? target['threshold_floor'],
          )?.clamp(0.001, 1.0) ??
          0.012;
      final thresholdRatio =
          _toActionDouble(
            data['threshold_ratio'] ?? target['threshold_ratio'],
          )?.clamp(0.001, 1.0) ??
          0.08;
      final paddingMs =
          _toActionDouble(
            data['padding_ms'] ?? target['padding_ms'],
          )?.clamp(0.0, 500.0) ??
          8.0;
      final preserveContentPosition = _toActionBool(
        data['preserve_content_position'] ??
            target['preserve_content_position'],
        fallback: true,
      );
      final fallbackTrimNudgeMs =
          (_toActionDouble(
                    data['fallback_trim_ms'] ?? target['fallback_trim_ms'],
                  ) ??
                  120.0)
              .clamp(10.0, 2000.0)
              .toDouble();

      bool anyApplied = false;
      for (final clipIndex in clipIndices) {
        if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
        final clip = _audioTracks[clipIndex];
        if (clip.isMidi) continue;

        final oldTrimStartMs = clip.trimStart.inMilliseconds.toDouble();
        final oldTrimEndMs = clip.trimEnd.inMilliseconds.toDouble();
        double? nextTrimStartMs = explicitTrimStartMs;
        double? nextTrimEndMs = explicitTrimEndMs;

        if (nextTrimStartMs == null && deltaTrimStartMs != null) {
          nextTrimStartMs = oldTrimStartMs + deltaTrimStartMs;
        }
        if (nextTrimEndMs == null && deltaTrimEndMs != null) {
          nextTrimEndMs = oldTrimEndMs + deltaTrimEndMs;
        }

        if (!hasExplicitTrimValues &&
            nextTrimStartMs == null &&
            nextTrimEndMs == null) {
          final estimated = _estimateAutoTrimBoundsMs(
            clip,
            thresholdFloor: thresholdFloor.toDouble(),
            thresholdRatio: thresholdRatio.toDouble(),
            paddingMs: paddingMs.toDouble(),
          );
          if (estimated != null) {
            if (trimEndOnlyHint && !trimStartOnlyHint) {
              nextTrimEndMs = estimated.value;
            } else if (trimStartOnlyHint && !trimEndOnlyHint) {
              nextTrimStartMs = estimated.key;
            } else {
              nextTrimStartMs = estimated.key;
              nextTrimEndMs = estimated.value;
            }
          }
        }

        nextTrimStartMs ??= oldTrimStartMs;
        nextTrimEndMs ??= oldTrimEndMs;

        if (!hasExplicitTrimValues &&
            (nextTrimStartMs - oldTrimStartMs).abs() < 0.5 &&
            (nextTrimEndMs - oldTrimEndMs).abs() < 0.5) {
          if (trimEndOnlyHint && !trimStartOnlyHint) {
            nextTrimEndMs = oldTrimEndMs - fallbackTrimNudgeMs;
          } else {
            nextTrimStartMs = oldTrimStartMs + fallbackTrimNudgeMs;
          }
        }

        if ((nextTrimStartMs - oldTrimStartMs).abs() < 0.5 &&
            (nextTrimEndMs - oldTrimEndMs).abs() < 0.5) {
          continue;
        }

        final explicitNewStartMs = _toActionDouble(
          data['new_start_ms'] ??
              target['new_start_ms'] ??
              data['start_ms'] ??
              target['start_ms'],
        );
        final startDeltaSec = (nextTrimStartMs - oldTrimStartMs) / 1000.0;
        final newOffsetSec = explicitNewStartMs != null
            ? math.max(0.0, explicitNewStartMs / 1000.0)
            : (preserveContentPosition
                  ? math.max(0.0, clip.offset + startDeltaSec)
                  : null);

        await _applyTrimActionForClip(
          clipIndex,
          newTrimStartMs: nextTrimStartMs,
          newTrimEndMs: nextTrimEndMs,
          newOffsetSec: newOffsetSec,
        );
        anyApplied = true;
      }

      if (!anyApplied) {
        if (hasExplicitTrimValues) {
          _showSmallNotice('Trim made no changes.');
        } else {
          _insertAssistantChatText(
            'Could not trim the target clip(s). Try selecting the clip and asking again.',
          );
        }
      } else {
        _showSmallNotice(
          'Trimmed ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.',
        );
      }
      return;
    }

    if (operation == 'dialog_cleanup' ||
        operation == 'dialog_remove_range' ||
        operation == 'dialog_tighten_pauses' ||
        operation == 'dialog_lift_quiet') {
      await _applyDialogClipEditOperation(data, operation: operation);
      return;
    }

    int? resolveSingleClipIndex({
      bool requireAudio = false,
      bool requireMidi = false,
      String failureMessage =
          "I couldn't resolve which clip to edit. Select a clip and ask again.",
    }) {
      final idx = _resolveSingleClipIndexWithFallback(
        data,
        requireAudio: requireAudio,
        requireMidi: requireMidi,
      );
      if (idx == null) {
        _insertAssistantChatText(failureMessage);
        return null;
      }
      if (idx < 0 || idx >= _audioTracks.length) return null;
      return idx;
    }

    switch (operation) {
      case 'cut':
        {
          final target = _actionTarget(data);
          final scope = (target['scope'] ?? data['scope'] ?? '')
              .toString()
              .trim()
              .toLowerCase();
          final fromMs = _toActionDouble(data['from_ms'] ?? target['from_ms']);
          final toMs = _toActionDouble(data['to_ms'] ?? target['to_ms']);
          final rawRanges = data['ranges'] ?? target['ranges'];
          final hasExplicitRangePayload =
              (fromMs != null && toMs != null) ||
              (rawRanges is List &&
                  rawRanges.any((raw) {
                    if (raw is! Map) return false;
                    final range = Map<String, dynamic>.from(raw);
                    return _toActionDouble(range['from_ms']) != null &&
                        _toActionDouble(range['to_ms']) != null;
                  }));
          if (scope == 'all' ||
              scope == 'all_audio' ||
              scope == 'all_selected_audio' ||
              hasExplicitRangePayload) {
            _showSmallNotice('Skipped unsupported cut action.');
            break;
          }
          final clipIndex = resolveSingleClipIndex(
            failureMessage:
                "I couldn't resolve which clip to cut. Select a clip and ask again.",
          );
          if (clipIndex == null) return;
          final clip = _audioTracks[clipIndex];
          final hasMidiChopHint =
              (rawOperation.contains('note') ||
                  rawOperation.contains('chop') ||
                  rawOperation.contains('splice') ||
                  rawOperation.contains('slice')) ||
              data.containsKey('subdivision') ||
              data.containsKey('subdivision_divisor') ||
              data.containsKey('grid') ||
              data.containsKey('resolution') ||
              target.containsKey('subdivision') ||
              target.containsKey('subdivision_divisor') ||
              target.containsKey('grid') ||
              target.containsKey('resolution');
          if (clip.isMidi && hasMidiChopHint) {
            final midiActionData = <String, dynamic>{
              ...data,
              'operation': 'chop_notes',
              'target': <String, dynamic>{...target, 'clip_index': clipIndex},
            };
            await _applyMidiComposeAction(midiActionData);
            break;
          }
          final startMs = clip.offset * 1000.0;
          final endMs = startMs + _clipTimelineDurationMs(clip);
          final cutMs =
              _toActionDouble(data['cut_ms'] ?? data['time_ms']) ??
              ((startMs + endMs) / 2.0);
          await _handleCutClipAt(clipIndex, cutMs);
          _showSmallNotice('Cut clip.');
          break;
        }
      case 'glue':
        {
          final clipIndices = _resolveClipIndicesFromActionTarget(
            data,
            requireAudio: true,
          );
          if (clipIndices.length < 2) {
            _insertAssistantChatText(
              "I couldn't resolve which audio clips to glue. Select two or more clips and ask again.",
            );
            return;
          }
          await _handleGlueClips(clipIndices);
          break;
        }
      case 'move':
        {
          final target = _actionTarget(data);

          int? clampRow(int? row) {
            if (row == null || _rowCount <= 0) return null;
            return row.clamp(0, _rowCount - 1);
          }

          final explicitStartMs =
              AssistantActionUtils.resolveMoveMusicalStartMs(
                data: data,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                data['new_start_ms'] ??
                    target['new_start_ms'] ??
                    data['start_ms'] ??
                    target['start_ms'],
              );
          final explicitDeltaMs =
              AssistantActionUtils.resolveMoveMusicalDeltaMs(
                data: data,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                data['delta_ms'] ??
                    target['delta_ms'] ??
                    data['offset_ms'] ??
                    target['offset_ms'] ??
                    data['shift_ms'] ??
                    target['shift_ms'],
              );
          final explicitAlignmentOffsetMs = _toActionDouble(
            data['new_alignment_offset_ms'] ??
                target['new_alignment_offset_ms'],
          );
          final explicitDestRow = clampRow(
            _toActionInt(
              data['new_row_index'] ??
                  target['new_row_index'] ??
                  data['destination_row_index'] ??
                  target['destination_row_index'] ??
                  data['to_row_index'] ??
                  target['to_row_index'],
            ),
          );
          final explicitRowHint = clampRow(
            _toActionInt(data['row_index']) ??
                _toActionInt(target['row_index']),
          );
          final explicitRowDelta =
              _toActionInt(
                data['delta_rows'] ??
                    target['delta_rows'] ??
                    data['row_delta'] ??
                    target['row_delta'],
              ) ??
              0;
          final direction = (data['direction'] ?? target['direction'] ?? '')
              .toString()
              .trim()
              .toLowerCase();
          final snapTo =
              (data['snap_to'] ??
                      target['snap_to'] ??
                      data['position'] ??
                      target['position'] ??
                      '')
                  .toString()
                  .trim()
                  .toLowerCase();

          double moveStepMs =
              (_toActionDouble(
                        data['step_ms'] ??
                            target['step_ms'] ??
                            data['distance_ms'] ??
                            target['distance_ms'] ??
                            data['amount_ms'] ??
                            target['amount_ms'],
                      ) ??
                      0.0)
                  .abs();
          if (moveStepMs < 1.0) {
            moveStepMs = (60000.0 / _tempo.clamp(1.0, 400.0))
                .clamp(1.0, 60000.0)
                .toDouble();
          }

          int directionRowDelta = 0;
          double directionStartDeltaMs = 0.0;
          bool moveToStart =
              snapTo.contains('start') ||
              snapTo.contains('begin') ||
              snapTo == 'zero';
          switch (direction) {
            case 'left':
            case 'earlier':
            case 'back':
            case 'backward':
              directionStartDeltaMs = -moveStepMs;
              break;
            case 'right':
            case 'later':
            case 'forward':
              directionStartDeltaMs = moveStepMs;
              break;
            case 'up':
            case 'above':
              directionRowDelta = -1;
              break;
            case 'down':
            case 'below':
              directionRowDelta = 1;
              break;
            case 'start':
            case 'beginning':
            case 'zero':
              moveToStart = true;
              break;
            default:
              break;
          }

          List<int> clipIndices = _resolveClipIndicesFromActionTarget(data);
          if (clipIndices.isEmpty && moveToStart) {
            clipIndices = List<int>.generate(
              _audioTracks.length,
              (index) => index,
              growable: false,
            );
          }
          if (clipIndices.isEmpty) {
            _insertAssistantChatText(
              "I couldn't resolve which clips to move. Please ask again with a track name if you want a specific target.",
            );
            return;
          }

          final hasHorizontalInstruction =
              explicitStartMs != null ||
              explicitDeltaMs != null ||
              directionStartDeltaMs != 0.0 ||
              moveToStart;
          final hasVerticalInstruction =
              explicitDestRow != null ||
              explicitRowDelta != 0 ||
              directionRowDelta != 0;

          if (!hasHorizontalInstruction && !hasVerticalInstruction) {
            _showSmallNotice('Skipped incomplete move action.');
            break;
          }

          bool anyApplied = false;
          for (final clipIndex in clipIndices) {
            if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
            final clip = _audioTracks[clipIndex];
            final oldStartMs = clip.offset * 1000.0;
            final oldRow = clip.rowIndex;

            double nextStartMs = oldStartMs;
            if (explicitStartMs != null) {
              nextStartMs = explicitStartMs;
            } else if (explicitDeltaMs != null) {
              nextStartMs = oldStartMs + explicitDeltaMs;
            } else if (directionStartDeltaMs != 0.0) {
              nextStartMs = oldStartMs + directionStartDeltaMs;
            } else if (moveToStart) {
              nextStartMs = 0.0;
            }
            nextStartMs = math.max(0.0, nextStartMs);

            int nextRow = oldRow;
            if (explicitDestRow != null) {
              nextRow = explicitDestRow;
            } else if (directionRowDelta != 0) {
              nextRow = clampRow(oldRow + directionRowDelta) ?? oldRow;
            } else if (explicitRowDelta != 0) {
              nextRow = clampRow(oldRow + explicitRowDelta) ?? oldRow;
            } else if (clipIndices.length == 1 &&
                explicitRowHint != null &&
                explicitRowHint != oldRow) {
              // If there is a single target clip, treat row_index as destination
              // when no other row destination signal exists.
              nextRow = explicitRowHint;
            }

            final rowChanged = nextRow != oldRow;
            final startChanged = (nextStartMs - oldStartMs).abs() > 0.5;
            if (!rowChanged && !startChanged) continue;

            await _undoManager.execute(
              MoveClipAction(
                tracks: _audioTracks,
                originalIndex: clipIndex,
                oldOffset: clip.offset,
                oldRow: clip.rowIndex,
                newOffset: nextStartMs / 1000.0,
                newRow: nextRow,
                oldAlignmentOffsetMs: explicitAlignmentOffsetMs == null
                    ? null
                    : clip.alignmentOffsetMs,
                newAlignmentOffsetMs: explicitAlignmentOffsetMs,
                onChange: () {
                  clip.rowId = _rowIdAt(clip.rowIndex);
                  unawaited(_syncClipTimingToEngine(clipIndex));
                  _updateOverallDurationIfNeeded(
                    changedClips: <AudioTrack>[clip],
                  );
                },
              ),
            );
            anyApplied = true;
          }

          if (!anyApplied) {
            _showSmallNotice('Move made no changes.');
            break;
          }

          if (mounted) setState(() {});
          _showSmallNotice(
            'Moved ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.',
          );
          break;
        }
      case 'stretch':
        {
          final clipIndex = resolveSingleClipIndex();
          if (clipIndex == null) return;
          final clip = _audioTracks[clipIndex];
          final target = _actionTarget(data);
          final explicitDurationMs = _toActionDouble(
            data['timeline_duration_ms'] ??
                data['duration_ms'] ??
                target['timeline_duration_ms'] ??
                target['duration_ms'] ??
                data['new_duration_ms'] ??
                target['new_duration_ms'],
          );
          final deltaDurationMs = _toActionDouble(
            data['delta_duration_ms'] ??
                target['delta_duration_ms'] ??
                data['duration_delta_ms'] ??
                target['duration_delta_ms'],
          );
          final factor = _toActionDouble(
            data['factor'] ??
                target['factor'] ??
                data['stretch_factor'] ??
                target['stretch_factor'] ??
                data['scale'] ??
                target['scale'],
          );
          final oldDurationMs = _clipTimelineDurationMs(clip);
          final durationMs =
              explicitDurationMs ??
              ((deltaDurationMs != null)
                  ? (oldDurationMs + deltaDurationMs)
                  : ((factor != null) ? (oldDurationMs * factor) : null));
          if (durationMs == null || clip.isMidi) {
            _insertAssistantChatText(
              "I couldn't resolve the new clip length to stretch.",
            );
            return;
          }
          final newStartMs = _toActionDouble(
            data['new_start_ms'] ?? data['start_ms'],
          );
          final preservePitch = _toActionBool(
            data['preserve_pitch'],
            fallback: true,
          );
          final changed = await _applyExactClipStretch(
            clipIndex,
            durationMs,
            newStartMs: newStartMs,
            preservePitch: preservePitch,
          );
          _showSmallNotice(
            changed ? 'Stretched clip.' : 'Stretch made no changes.',
          );
          break;
        }
      case 'pitch_shift':
        {
          final target = _actionTarget(data);
          final clipIndices = _resolveClipIndicesFromActionTarget(
            data,
            requireAudio: true,
          );
          if (clipIndices.isEmpty) {
            _insertAssistantChatText(
              "I couldn't resolve which audio clips to pitch shift. Select clips and ask again.",
            );
            return;
          }

          final mode = (data['mode'] ?? target['mode'] ?? '')
              .toString()
              .trim()
              .toLowerCase();
          final explicitSetPitch = _toActionDouble(
            data['new_pitch_semitones'] ??
                target['new_pitch_semitones'] ??
                data['pitch_semitones'] ??
                target['pitch_semitones'],
          );
          final semitones = _toActionDouble(
            data['semitones'] ?? target['semitones'],
          );
          final deltaSemitones = _toActionDouble(
            data['delta_semitones'] ??
                target['delta_semitones'] ??
                data['semitone_delta'] ??
                target['semitone_delta'] ??
                data['pitch_delta'] ??
                target['pitch_delta'],
          );
          final setPitch =
              explicitSetPitch ??
              ((mode == 'set' || mode == 'absolute') ? semitones : null);
          final deltaPitch =
              deltaSemitones ??
              ((mode == 'set' || mode == 'absolute') ? null : semitones);
          if (setPitch == null && deltaPitch == null) {
            _insertAssistantChatText(
              "I couldn't resolve how many semitones to pitch shift.",
            );
            return;
          }

          var changed = 0;
          for (final clipIndex in clipIndices) {
            if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
            final clip = _audioTracks[clipIndex];
            if (clip.isMidi) continue;
            final oldPitch = clip.pitchSemitones;
            final nextPitch = (setPitch ?? (oldPitch + deltaPitch!))
                .clamp(_kClipPitchMinSemitones, _kClipPitchMaxSemitones)
                .toDouble();
            if ((nextPitch - oldPitch).abs() < 0.0005) continue;

            await _undoManager.execute(
              SetClipPitchAction(
                tracks: _audioTracks,
                originalIndex: clipIndex,
                oldPitch: oldPitch,
                newPitch: nextPitch,
                applyToState: (clip, pitch) {
                  clip.pitchSemitones = pitch;
                  if (mounted) setState(() {});
                },
              ),
            );
            changed++;
          }

          if (changed <= 0) {
            _showSmallNotice('Pitch shift made no changes.');
          } else {
            _recordProducerManualEdit('ai_clip_pitch_shift', {
              'clips': changed,
              if (setPitch != null) 'pitch_semitones': setPitch,
              if (deltaPitch != null) 'delta_semitones': deltaPitch,
            });
            _showSmallNotice(
              'Pitch shifted $changed clip${changed == 1 ? '' : 's'}.',
            );
          }
          break;
        }
      case 'tempo_follow':
        {
          final targets = _resolveClipIndicesFromActionTarget(
            data,
            requireAudio: true,
          );
          if (targets.isEmpty) {
            _insertAssistantChatText(
              "I couldn't resolve which audio clips to tempo-align.",
            );
            return;
          }
          final mode = data['mode']?.toString().trim();
          final preservePitch =
              mode == 'preserve_pitch' ||
              (mode == null &&
                  _toActionBool(data['preserve_pitch'], fallback: true));
          for (final idx in targets) {
            if (mode == 'off') {
              await _handleDisableClipTempoFollow(idx);
            } else {
              await _setClipTempoFollowMode(
                idx,
                preservePitch: preservePitch,
                showFeedback: false,
                useExistingSourceTempo: mode != null,
              );
            }
          }
          _showSmallNotice(
            'Tempo mode updated for ${targets.length} clip${targets.length == 1 ? '' : 's'}.',
          );
          break;
        }
      case 'set_source_tempo':
        {
          final targets = _resolveClipIndicesFromActionTarget(
            data,
            requireAudio: true,
          );
          final sourceTempo = _toActionDouble(data['source_tempo_bpm']);
          if (targets.isEmpty ||
              sourceTempo == null ||
              !sourceTempo.isFinite ||
              sourceTempo < 20.0 ||
              sourceTempo > 999.0) {
            throw StateError('v3_clip_source_tempo_invalid');
          }
          for (final idx in targets) {
            await _setClipSourceTempo(idx, sourceTempo);
          }
          _showSmallNotice(
            'Source tempo updated for ${targets.length} clip${targets.length == 1 ? '' : 's'}.',
          );
          break;
        }
      case 'tempo_detect_set_project':
        {
          final clipIndex = resolveSingleClipIndex(requireAudio: true);
          if (clipIndex == null) return;
          final clip = _audioTracks[clipIndex];
          if (clip.isMidi) return;
          await _setProjectTempoFromDetectedClip(clipIndex);
          final preservePitch = _toActionBool(
            data['preserve_pitch'],
            fallback: true,
          );
          await _setClipTempoFollowMode(
            clipIndex,
            preservePitch: preservePitch,
          );
          _showSmallNotice('Detected clip tempo and updated project tempo.');
          break;
        }
      case 'delete':
        {
          final clipIndices = _resolveClipIndicesFromActionTarget(data);
          if (clipIndices.isEmpty) {
            final clipIndex = resolveSingleClipIndex();
            if (clipIndex == null) return;
            await _handleDeleteClip(clipIndex);
            _showSmallNotice('Deleted clip.');
            break;
          }
          await _handleDeleteClips(clipIndices);
          _showSmallNotice(
            'Deleted ${clipIndices.length} clip${clipIndices.length == 1 ? '' : 's'}.',
          );
        }
        break;
      case 'duplicate':
        {
          var clipIndices = _resolveClipIndicesFromActionTarget(data);
          if (clipIndices.isEmpty) {
            final clipIndex = resolveSingleClipIndex();
            if (clipIndex == null) return;
            clipIndices = <int>[clipIndex];
          }
          final validClipIndices = clipIndices
              .where((i) => i >= 0 && i < _audioTracks.length)
              .toSet()
              .toList(growable: false);
          if (validClipIndices.isEmpty) {
            _insertAssistantChatText(
              "I couldn't resolve which clips to duplicate.",
            );
            return;
          }
          final sourceClips =
              validClipIndices
                  .map((i) => _audioTracks[i])
                  .toList(growable: false)
                ..sort((a, b) {
                  final byOffset = a.offset.compareTo(b.offset);
                  if (byOffset != 0) return byOffset;
                  final byRow = a.rowIndex.compareTo(b.rowIndex);
                  if (byRow != 0) return byRow;
                  return a.engineClipId.compareTo(b.engineClipId);
                });
          final anchorClip = sourceClips.first;
          final anchorStartMs = sourceClips
              .map((clip) => clip.offset * 1000.0)
              .reduce(math.min);
          final groupEndMs = sourceClips
              .map((clip) => _clipTimelineEndMs(clip))
              .reduce(math.max);
          final groupLengthMs = math
              .max(1.0, groupEndMs - anchorStartMs)
              .toDouble();
          final target = _actionTarget(data);
          final baseRow =
              _resolveRowIndexFromActionTarget(
                data,
                fallbackClipIndex: validClipIndices.first,
              ) ??
              anchorClip.rowIndex;
          final rowStep =
              _toActionInt(
                data['delta_rows'] ??
                    target['delta_rows'] ??
                    data['row_delta'] ??
                    target['row_delta'] ??
                    data['step_rows'] ??
                    target['step_rows'],
              ) ??
              0;
          final firstPasteMs =
              AssistantActionUtils.resolveMoveMusicalStartMs(
                data: data,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                data['paste_start_ms'] ??
                    target['paste_start_ms'] ??
                    data['start_ms'] ??
                    target['start_ms'],
              ) ??
              groupEndMs;
          final stepMs =
              AssistantActionUtils.resolveMoveMusicalDeltaMs(
                data: data,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                data['step_ms'] ??
                    target['step_ms'] ??
                    data['spacing_ms'] ??
                    target['spacing_ms'],
              ) ??
              groupLengthMs;
          final repeatCount = AssistantActionUtils.resolvePlacementRepeatCount(
            data: data,
            target: target,
            bpm: _tempo,
            startMs: firstPasteMs,
            stepMs: stepMs,
          );
          final duplicateCount = validClipIndices.length * repeatCount;
          if (_audioTracks.length + duplicateCount > kNumClips) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
                ),
              ),
            );
            return;
          }

          final actions = <EditorUndoAction>[];
          for (int copyIndex = 0; copyIndex < repeatCount; copyIndex++) {
            final groupStartMs = math.max(
              0.0,
              firstPasteMs + (stepMs * copyIndex),
            );
            for (final clip in sourceClips) {
              final offsetDeltaMs = (clip.offset * 1000.0) - anchorStartMs;
              final rowDelta = clip.rowIndex - anchorClip.rowIndex;
              final pasteRow = _rowCount > 0
                  ? (baseRow + rowDelta + (rowStep * copyIndex)).clamp(
                      0,
                      _rowCount - 1,
                    )
                  : math.max(0, baseRow + rowDelta + (rowStep * copyIndex));
              final pasteMs = math.max(0.0, groupStartMs + offsetDeltaMs);
              actions.add(
                _buildPasteAction(
                  clip: clip,
                  row: pasteRow,
                  timeMs: pasteMs,
                  trimStart: clip.trimStart,
                  trimEnd: clip.trimEnd,
                ),
              );
            }
          }

          if (actions.length == 1) {
            await _undoManager.execute(actions.first);
          } else {
            await _undoManager.execute(
              CompoundUndoAction(
                sourceClips.length == 1 ? 'Duplicate clip' : 'Duplicate clips',
                actions,
              ),
            );
          }
          _showSmallNotice(
            sourceClips.length == 1
                ? (repeatCount == 1
                      ? 'Duplicated clip.'
                      : 'Duplicated clip $repeatCount times.')
                : (repeatCount == 1
                      ? 'Duplicated ${sourceClips.length} clips.'
                      : 'Duplicated ${sourceClips.length} clips $repeatCount times.'),
          );
          break;
        }
      default:
        _insertAssistantChatText(
          'Unsupported clip edit operation "$operation".',
        );
        break;
    }
  }

  Future<void> _applyProjectEditAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final operation = (data['operation'] ?? '').toString().trim().toLowerCase();
    switch (operation) {
      case 'set_tempo':
        final rawTempo = _toActionDouble(
          data['tempo_bpm'] ??
              target['tempo_bpm'] ??
              data['bpm'] ??
              target['bpm'],
        );
        if (rawTempo == null || !rawTempo.isFinite || rawTempo <= 0.0) {
          _insertAssistantChatText(
            "I couldn't resolve the target project tempo.",
          );
          return;
        }
        final nextTempo = _clampTempo(rawTempo);
        final shouldStretchAudio = _toActionBool(
          data['time_stretch_audio'] ??
              target['time_stretch_audio'] ??
              data['stretch_audio'] ??
              target['stretch_audio'] ??
              data['song_speed_change'] ??
              target['song_speed_change'],
          fallback: false,
        );
        if (shouldStretchAudio) {
          final preservePitch = _toActionBool(
            data['preserve_pitch'] ?? target['preserve_pitch'],
            fallback: true,
          );
          await _enableTempoFollowForProjectAudio(
            preservePitch: preservePitch,
            deferEngineSync: (nextTempo - _tempo).abs() >= 0.0001,
          );
        }
        // Legacy chat tempo changes intentionally use the existing UI-style
        // behavior. V3 transactions capture the tempo snapshot action so a
        // later failure or Undo can restore the actual project state.
        await _applyProjectTempoChange(
          nextTempo,
          recordUndo: _undoManager.isCapturingActions,
        );
        _showSmallNotice(
          shouldStretchAudio
              ? 'Song speed set to ${nextTempo.round()} BPM.'
              : 'Project tempo set to ${nextTempo.round()} BPM.',
        );
        return;
      default:
        _insertAssistantChatText(
          'Unsupported project edit operation "$operation".',
        );
        return;
    }
  }

  Future<int> _enableTempoFollowForProjectAudio({
    required bool preservePitch,
    bool deferEngineSync = false,
  }) async {
    final before = _captureTempoStretchUiModeSnapshot();
    var changed = 0;
    _setStateAndRefreshProjectSettings(() {
      for (final clip in _audioTracks) {
        if (clip.isMidi || clip.stretchToProjectTempo) continue;
        clip.sourceTempoBpm = _sourceTempoForCurrentClipTimeline(clip);
        clip.stretchToProjectTempo = true;
        clip.tempoStretchPreservePitch = preservePitch;
        clip.tempoWarpMode = preservePitch
            ? kTempoWarpModeComplex
            : kTempoWarpModeRepitch;
        changed++;
      }
      if (changed > 0) {
        _tempoStretchEnabled = true;
      }
    });
    if (changed == 0) return 0;

    if (!deferEngineSync) {
      await _syncAllTempoStretchToEngine();
    }
    _scheduleProjectAutosave();
    final after = _captureTempoStretchUiModeSnapshot();
    await _undoManager.addWithoutExecute(
      _TempoStretchUiModeAction(
        before: before,
        after: after,
        applySnapshot: _applyTempoStretchUiModeSnapshot,
      ),
    );
    return changed;
  }

  int _estimateAiSampleInsertWorkUnits(
    String operation,
    List<Map<String, dynamic>> itemMaps,
  ) {
    var total = 0;
    for (final item in itemMaps) {
      final target = _actionTarget(item);
      if (operation == 'replace_audio_clips') {
        final targetClipIndices = _resolveClipIndicesFromActionTarget(
          item,
          requireAudio: true,
        );
        total += math.max(1, targetClipIndices.length);
        continue;
      }
      final libraryPath =
          (item['library_path'] ??
                  target['library_path'] ??
                  item['asset_path'] ??
                  target['asset_path'])
              .toString()
              .trim();
      final explicitStartMs = AssistantActionUtils.resolveMoveMusicalStartMs(
        data: item,
        target: target,
        bpm: _tempo,
      );
      final repeatCountHint =
          _toActionInt(
            item['repeat_count'] ??
                target['repeat_count'] ??
                item['copies'] ??
                target['copies'] ??
                item['count'] ??
                target['count'],
          ) ??
          1;
      final baseTimeMs =
          explicitStartMs ??
          _toActionDouble(item['start_ms'] ?? target['start_ms']) ??
          AssistantActionUtils.defaultSampleInsertStartMs(
            libraryPath,
            bpm: _tempo,
          );
      final stepMs =
          AssistantActionUtils.resolveMoveMusicalDeltaMs(
            data: item,
            target: target,
            bpm: _tempo,
          ) ??
          _toActionDouble(
            item['step_ms'] ??
                target['step_ms'] ??
                item['spacing_ms'] ??
                target['spacing_ms'],
          ) ??
          AssistantActionUtils.defaultSampleInsertStepMs(
            libraryPath,
            bpm: _tempo,
            repeatCount: repeatCountHint,
          ) ??
          0.0;
      final resolvedStartMs =
          baseTimeMs ?? _globalAudioClock.inMilliseconds.toDouble();
      total += AssistantActionUtils.resolvePlacementRepeatCount(
        data: item,
        target: target,
        bpm: _tempo,
        startMs: resolvedStartMs,
        stepMs: stepMs,
        preferSpanCoverageOverExplicitCount: true,
      );
    }
    return math.max(1, total);
  }

  Future<File> _prepareAiV3LibraryReplacementFile(String libraryPath) async {
    var sourcePath = await _resolveAiLibrarySamplePath(libraryPath);
    if (sourcePath == null &&
        _isSampleAudioFile(libraryPath) &&
        File(libraryPath).existsSync()) {
      sourcePath = libraryPath;
    }
    if (sourcePath == null) {
      throw StateError('v3_sample_replace_asset_unavailable');
    }

    final importedPath = _aiLibraryImportedAudioPath(sourcePath);
    final importedFile = File(importedPath);
    if (!importedFile.existsSync()) {
      final escapedSource = sourcePath.replaceAll('"', r'\"');
      final escapedTarget = importedPath.replaceAll('"', r'\"');
      final session = await FFmpegKit.execute(
        '-i "$escapedSource" -ar 48000 -y "$escapedTarget"',
      );
      final returnCode = await session.getReturnCode();
      if (!ReturnCode.isSuccess(returnCode) || !importedFile.existsSync()) {
        throw StateError('v3_sample_replace_import_failed');
      }
    }
    final duration = await _resolveSampleDuration(importedPath);
    if (duration == null || duration <= Duration.zero) {
      throw StateError('v3_sample_replace_audio_unreadable');
    }
    return importedFile;
  }

  Future<Map<String, dynamic>?> _applyAiV3SampleReplaceAction(
    Map<String, dynamic> data,
  ) async {
    final target = _actionTarget(data);
    final clipId = (target['clip_id'] ?? data['clip_id']).toString().trim();
    final libraryPath = (data['library_path'] ?? '').toString().trim();
    if (clipId.isEmpty || libraryPath.isEmpty) {
      throw StateError('v3_sample_replace_target_invalid');
    }
    final clipIndex = _clipIndexForPersistentId(clipId);
    if (!_isValidClipIndex(clipIndex) || _audioTracks[clipIndex].isMidi) {
      throw StateError('v3_sample_replace_target_invalid');
    }
    if (_audioTracks.length >= kNumClips) {
      throw StateError('v3_sample_replace_capacity');
    }

    final replacementFile = await _prepareAiV3LibraryReplacementFile(
      libraryPath,
    );
    final current = _audioTracks[clipIndex];
    if (_normalizedClipPath(current.file.path) ==
        _normalizedClipPath(replacementFile.path)) {
      return null;
    }

    final beforePayload = _persistedClipPayload(current);
    final oldVisibleDurationMs = math.max(
      1,
      _clipTimelineDurationMs(current).round(),
    );
    final replacementDuration = await _resolveSampleDuration(
      replacementFile.path,
    );
    if (replacementDuration == null || replacementDuration <= Duration.zero) {
      throw StateError('v3_sample_replace_audio_unreadable');
    }
    final replacementDurationMs = replacementDuration.inMilliseconds;
    final afterPayload = Map<String, dynamic>.from(beforePayload)
      ..['fileName'] = p.basename(replacementFile.path)
      ..['audioDurationMs'] = replacementDurationMs
      ..['trimStartMs'] = 0
      ..['trimEndMs'] = math.min(oldVisibleDurationMs, replacementDurationMs)
      ..['label'] = _displayStemForFilePath(libraryPath)
      ..['sourceTempoBpm'] = 0.0
      ..['stretchToProjectTempo'] = false
      ..['tempoStretchPreservePitch'] = false
      ..['tempoWarpMode'] = kTempoWarpModeComplex
      ..['recordingLatencyMs'] = 0.0
      ..['alignmentOffsetMs'] = 0.0
      ..['audioEnhancementPreset'] = '';

    final action = ReplaceAudioClipSourceAction(
      beforePayload: beforePayload,
      afterPayload: afterPayload,
      applyPayload: _replaceAudioClipFromUndoPayload,
    );
    await _undoManager.execute(action);

    final replacedIndex = _clipIndexForPersistentId(clipId);
    if (!_isValidClipIndex(replacedIndex)) {
      throw StateError('v3_sample_replace_missing_after_apply');
    }
    final replaced = _audioTracks[replacedIndex];
    if (!_aiV3ClipMatchesPersistedPayload(replaced, afterPayload)) {
      throw StateError('v3_sample_replace_exact_readback_failed');
    }
    return <String, dynamic>{
      'kind': 'sample_replaced',
      'clip_id': clipId,
      'file': replaced.file.path,
      'label': replaced.label,
      'clip_count': _audioTracks.length,
      'expected_payload': afterPayload,
    };
  }

  void _applyAiV3ReplacementResourceExpectation(
    Map<String, dynamic> resourceExpectation,
    Map<String, dynamic> replacementExpectation,
  ) {
    final rawPayload = replacementExpectation['expected_payload'];
    if (rawPayload is! Map) {
      throw StateError('v3_sample_replace_expectation_missing');
    }
    final payload = Map<String, dynamic>.from(rawPayload);
    final start = _toActionDouble(payload['offset']);
    final trimStartMs = _toActionDouble(payload['trimStartMs']);
    final trimEndMs = _toActionDouble(payload['trimEndMs']);
    if (start == null ||
        trimStartMs == null ||
        trimEndMs == null ||
        trimEndMs - trimStartMs < 50.0) {
      throw StateError('v3_sample_replace_expectation_invalid');
    }
    final rawDurationSec = (trimEndMs - trimStartMs) / 1000.0;
    resourceExpectation
      ..['start'] = start
      ..['end'] = start + rawDurationSec
      ..['file'] = replacementExpectation['file']
      ..['label'] = replacementExpectation['label']
      ..['raw_duration_sec'] = rawDurationSec
      ..['trim_start_ms'] = trimStartMs
      ..['trim_end_ms'] = trimEndMs
      ..['source_tempo_bpm'] = 0.0
      ..['tempo_follow_mode'] = 'off'
      ..['tempo_preserve_pitch'] = false
      ..['duration_follows_tempo'] = false
      ..['alignment_offset_ms'] = 0.0;
  }

  bool _aiV3ClipMatchesPersistedPayload(
    AudioTrack clip,
    Map<String, dynamic> expectedPayload,
  ) {
    final actual = _persistedClipPayload(clip);
    final expected = Map<String, dynamic>.from(expectedPayload);
    if ((actual['audioEnhancementPreset'] ?? '').toString().trim().isEmpty) {
      actual.remove('audioEnhancementPreset');
    }
    if ((expected['audioEnhancementPreset'] ?? '').toString().trim().isEmpty) {
      expected.remove('audioEnhancementPreset');
    }
    return jsonEncode(actual) == jsonEncode(expected);
  }

  Future<void> _replaceAudioClipFromUndoPayload(
    Map<String, dynamic> payload,
  ) async {
    final clipId = _normalizePersistedClipId(payload['clipId']);
    final originalIndex = _clipIndexForPersistentId(clipId);
    if (!_isValidClipIndex(originalIndex) ||
        _audioTracks[originalIndex].isMidi) {
      throw StateError('v3_sample_replace_target_invalid');
    }
    if (_audioTracks.length >= kNumClips) {
      throw StateError('v3_sample_replace_capacity');
    }

    final original = _audioTracks[originalIndex];
    final originalPayload = _persistedClipPayload(original);
    final selectedIds = _timelineSelectedClipIndices
        .where(_isValidClipIndex)
        .map((index) => _audioTracks[index].clipId)
        .toList(growable: false);
    final primaryId = _isValidClipIndex(_timelinePrimarySelectedClipIndex)
        ? _audioTracks[_timelinePrimarySelectedClipIndex].clipId
        : null;
    final temporaryId =
        '${clipId}__v3_replacement_${DateTime.now().microsecondsSinceEpoch}';
    final stagedPayload = Map<String, dynamic>.from(payload)
      ..['clipId'] = temporaryId;

    AudioTrack? staged;
    var originalRemoved = false;
    try {
      await _addClipFromUndoPayload(stagedPayload);
      final stagedIndex = _clipIndexForPersistentId(temporaryId);
      if (!_isValidClipIndex(stagedIndex)) {
        throw StateError('v3_sample_replace_stage_failed');
      }
      staged = _audioTracks[stagedIndex];

      original.audioStartTimer?.cancel();
      _audioTracks.removeAt(originalIndex);
      if (original.engineClipId >= 0) {
        await JuceAudioEngine.removeTrack(original.engineClipId);
      }
      originalRemoved = true;

      final currentStagedIndex = _audioTracks.indexOf(staged);
      if (currentStagedIndex < 0) {
        throw StateError('v3_sample_replace_stage_missing');
      }
      _audioTracks.removeAt(currentStagedIndex);
      staged.clipId = clipId;
      final insertionIndex = originalIndex
          .clamp(0, _audioTracks.length)
          .toInt();
      _audioTracks.insert(insertionIndex, staged);

      _timelineSelectedClipIndices = selectedIds
          .map(_clipIndexForPersistentId)
          .where(_isValidClipIndex)
          .toList(growable: false);
      _timelinePrimarySelectedClipIndex = primaryId == null
          ? -1
          : _clipIndexForPersistentId(primaryId);
      _tempoStretchEnabled = _audioTracks
          .where((clip) => !clip.isMidi)
          .any((clip) => clip.stretchToProjectTempo);
      await _syncAllClipFadesToEngine();
      _updateOverallDurationIfNeeded();
      _scheduleProjectAutosave();
      if (mounted) setState(() {});
    } catch (error, stackTrace) {
      if (staged != null && _audioTracks.contains(staged)) {
        _audioTracks.remove(staged);
        if (staged.engineClipId >= 0) {
          await JuceAudioEngine.removeTrack(staged.engineClipId);
        }
      }
      if (originalRemoved && _clipIndexForPersistentId(clipId) < 0) {
        await _addClipFromUndoPayload(originalPayload);
        final restoredIndex = _clipIndexForPersistentId(clipId);
        if (_isValidClipIndex(restoredIndex)) {
          final restored = _audioTracks.removeAt(restoredIndex);
          _audioTracks.insert(
            originalIndex.clamp(0, _audioTracks.length).toInt(),
            restored,
          );
        }
      }
      final restoredIndex = _clipIndexForPersistentId(clipId);
      if (!_isValidClipIndex(restoredIndex)) {
        Error.throwWithStackTrace(
          StateError('v3_sample_replace_rollback_incomplete'),
          stackTrace,
        );
      }
      _timelineSelectedClipIndices = selectedIds
          .map(_clipIndexForPersistentId)
          .where(_isValidClipIndex)
          .toList(growable: false);
      _timelinePrimarySelectedClipIndex = primaryId == null
          ? -1
          : _clipIndexForPersistentId(primaryId);
      _tempoStretchEnabled = _audioTracks
          .where((clip) => !clip.isMidi)
          .any((clip) => clip.stretchToProjectTempo);
      await _syncAllClipFadesToEngine();
      _updateOverallDurationIfNeeded();
      if (mounted) setState(() {});
      Error.throwWithStackTrace(error, stackTrace);
    }
  }

  void _restoreAiV3ClipOrder(List<String> stableOrder) {
    final orderById = <String, int>{
      for (var index = 0; index < stableOrder.length; index++)
        stableOrder[index]: index,
    };
    _audioTracks.sort((left, right) {
      final leftOrder = orderById[left.clipId] ?? stableOrder.length;
      final rightOrder = orderById[right.clipId] ?? stableOrder.length;
      return leftOrder.compareTo(rightOrder);
    });
  }

  void _restoreAiV3ClipSelection({
    required List<String> selectedClipIds,
    required String primaryClipId,
    required int? selectedRowId,
  }) {
    _timelineSelectedClipIndices = selectedClipIds
        .map(_clipIndexForPersistentId)
        .where(_isValidClipIndex)
        .toList(growable: false);
    _timelinePrimarySelectedClipIndex = primaryClipId.isEmpty
        ? -1
        : _clipIndexForPersistentId(primaryClipId);
    if (selectedRowId != null) {
      final row = _rowIndexForId(selectedRowId);
      if (_isValidRowIndex(row)) _selectedRow = row;
    }
  }

  Future<void> _applyAiV3GlueSnapshot({
    required List<Map<String, dynamic>> sourcePayloads,
    required Map<String, dynamic> resultPayload,
    required List<String> beforeClipOrder,
    required List<String> beforeSelectedClipIds,
    required String beforePrimaryClipId,
    required int? beforeSelectedRowId,
    required bool glued,
  }) async {
    final sourceIds = sourcePayloads
        .map((payload) => _normalizePersistedClipId(payload['clipId']))
        .toList(growable: false);
    final resultId = _normalizePersistedClipId(resultPayload['clipId']);
    if (sourceIds.any((id) => id.isEmpty) || resultId.isEmpty) {
      throw StateError('v3_clip_glue_snapshot_invalid');
    }

    Future<void> removeIfPresent(String clipId) async {
      final index = _clipIndexForPersistentId(clipId);
      if (_isValidClipIndex(index)) {
        await _removeClipForUndo(clipId, index);
      }
    }

    Future<void> addIfMissing(Map<String, dynamic> payload) async {
      final clipId = _normalizePersistedClipId(payload['clipId']);
      if (_clipIndexForPersistentId(clipId) < 0) {
        await _addClipFromUndoPayload(payload);
      }
      if (_clipIndexForPersistentId(clipId) < 0) {
        throw StateError('v3_clip_glue_restore_failed');
      }
    }

    if (glued) {
      if (_clipIndexForPersistentId(resultId) >= 0 ||
          sourceIds.any((id) => _clipIndexForPersistentId(id) < 0)) {
        throw StateError('v3_clip_glue_source_state_invalid');
      }
      try {
        for (final sourceId in sourceIds) {
          await removeIfPresent(sourceId);
        }
        await addIfMissing(resultPayload);
        final firstSourcePosition = beforeClipOrder
            .where(sourceIds.contains)
            .map(beforeClipOrder.indexOf)
            .fold<int>(
              beforeClipOrder.length,
              (value, index) => math.min(value, index),
            );
        final afterOrder =
            beforeClipOrder
                .where((id) => !sourceIds.contains(id))
                .toList(growable: true)
              ..insert(
                firstSourcePosition
                    .clamp(0, beforeClipOrder.length - sourceIds.length)
                    .toInt(),
                resultId,
              );
        _restoreAiV3ClipOrder(afterOrder);
        final resultIndex = _clipIndexForPersistentId(resultId);
        final resultRowId = _isValidClipIndex(resultIndex)
            ? _audioTracks[resultIndex].rowId
            : null;
        _restoreAiV3ClipSelection(
          selectedClipIds: <String>[resultId],
          primaryClipId: resultId,
          selectedRowId: resultRowId,
        );
      } catch (error, stackTrace) {
        var rollbackIncomplete = false;
        try {
          await removeIfPresent(resultId);
          for (final payload in sourcePayloads) {
            await addIfMissing(payload);
          }
          _restoreAiV3ClipOrder(beforeClipOrder);
          _restoreAiV3ClipSelection(
            selectedClipIds: beforeSelectedClipIds,
            primaryClipId: beforePrimaryClipId,
            selectedRowId: beforeSelectedRowId,
          );
        } catch (_) {
          rollbackIncomplete = true;
        }
        if (rollbackIncomplete) {
          Error.throwWithStackTrace(
            _EditorUndoCaptureRollbackException(error),
            stackTrace,
          );
        }
        Error.throwWithStackTrace(error, stackTrace);
      }
    } else {
      if (_clipIndexForPersistentId(resultId) < 0 ||
          sourceIds.any((id) => _clipIndexForPersistentId(id) >= 0)) {
        throw StateError('v3_clip_glue_result_state_invalid');
      }
      try {
        await removeIfPresent(resultId);
        for (final payload in sourcePayloads) {
          await addIfMissing(payload);
        }
        _restoreAiV3ClipOrder(beforeClipOrder);
        _restoreAiV3ClipSelection(
          selectedClipIds: beforeSelectedClipIds,
          primaryClipId: beforePrimaryClipId,
          selectedRowId: beforeSelectedRowId,
        );
      } catch (error, stackTrace) {
        var rollbackIncomplete = false;
        try {
          for (final sourceId in sourceIds) {
            await removeIfPresent(sourceId);
          }
          await addIfMissing(resultPayload);
          final resultIndex = _clipIndexForPersistentId(resultId);
          _restoreAiV3ClipSelection(
            selectedClipIds: <String>[resultId],
            primaryClipId: resultId,
            selectedRowId: _isValidClipIndex(resultIndex)
                ? _audioTracks[resultIndex].rowId
                : null,
          );
        } catch (_) {
          rollbackIncomplete = true;
        }
        if (rollbackIncomplete) {
          Error.throwWithStackTrace(
            _EditorUndoCaptureRollbackException(error),
            stackTrace,
          );
        }
        Error.throwWithStackTrace(error, stackTrace);
      }
    }

    await _syncAllClipFadesToEngine();
    _updateOverallDurationIfNeeded();
    _scheduleProjectAutosave();
    if (mounted) setState(() {});
  }

  Future<Map<String, dynamic>> _applyAiV3ClipGlueAction(
    Map<String, dynamic> data, {
    AiV3WorkflowRuntime? workflowRuntime,
  }) async {
    final target = _actionTarget(data);
    final rawIds =
        data['source_clip_ids'] ?? target['source_clip_ids'] ?? const [];
    if (rawIds is! List || rawIds.length < 2 || rawIds.length > 32) {
      throw StateError('v3_clip_glue_target_invalid');
    }
    final sourceIds = rawIds
        .map((value) => value.toString().trim())
        .toList(growable: false);
    if (sourceIds.any((id) => id.isEmpty) ||
        sourceIds.toSet().length != sourceIds.length) {
      throw StateError('v3_clip_glue_target_invalid');
    }
    final indexed = <({int index, AudioTrack clip})>[];
    for (final clipId in sourceIds) {
      final index = _clipIndexForPersistentId(clipId);
      if (!_isValidClipIndex(index) || _audioTracks[index].isMidi) {
        throw StateError('v3_clip_glue_target_invalid');
      }
      indexed.add((index: index, clip: _audioTracks[index]));
    }
    final rowIds = indexed.map((item) => item.clip.rowId).toSet();
    if (rowIds.length != 1) {
      throw StateError('v3_clip_glue_row_mismatch');
    }
    indexed.sort((left, right) => left.index.compareTo(right.index));
    final selectionStartSec = indexed
        .map((item) => item.clip.offset)
        .reduce(math.min);
    final selectionEndSec = indexed
        .map((item) => item.clip.offset + _clipTimelineDurationSec(item.clip))
        .reduce(math.max);
    final durationSec = selectionEndSec - selectionStartSec;
    if (!durationSec.isFinite || durationSec <= 0.05) {
      throw StateError('v3_clip_glue_bounds_invalid');
    }

    final expectedStartMs = _toActionDouble(data['start_ms']);
    final expectedDurationMs = _toActionDouble(data['duration_ms']);
    if (expectedStartMs == null ||
        expectedDurationMs == null ||
        (expectedStartMs - selectionStartSec * 1000.0).abs() > 2.0 ||
        (expectedDurationMs - durationSec * 1000.0).abs() > 2.0) {
      throw StateError('v3_clip_glue_stale_bounds');
    }

    final audioDir = ProjectManager.audioDir(_projectDir);
    await audioDir.create(recursive: true);
    final outputFile = File(
      p.join(
        audioDir.path,
        'glued_${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}.wav',
      ),
    );
    workflowRuntime?.trackGeneratedArtifact(outputFile.path);
    final snapshotJson = _buildGlueExportClipSnapshotJson(
      selectedIndices: indexed.map((item) => item.index).toSet(),
      selectionStartSec: selectionStartSec,
    );
    final renderedPath = await JuceAudioEngine.exportMix(
      outputFile.path,
      format: 'wav',
      sampleRate: 48000,
      wavBitDepth: 24,
      wavDithering: false,
      clipSnapshotJson: snapshotJson,
      dryClipRender: true,
    );
    final rendered = File(
      renderedPath.trim().isNotEmpty ? renderedPath.trim() : outputFile.path,
    );
    workflowRuntime?.trackGeneratedArtifact(rendered.path);
    if (!await rendered.exists() || await rendered.length() <= 44) {
      throw StateError('v3_clip_glue_render_failed');
    }
    final renderedDuration = await _resolveSampleDuration(rendered.path);
    if (renderedDuration == null || renderedDuration <= Duration.zero) {
      throw StateError('v3_clip_glue_render_unreadable');
    }
    final renderedDurationMs = renderedDuration.inMilliseconds.toDouble();
    final durationToleranceMs = math.max(100.0, expectedDurationMs * 0.01);
    if ((renderedDurationMs - expectedDurationMs).abs() > durationToleranceMs) {
      throw StateError('v3_clip_glue_render_duration_mismatch');
    }

    final beforeOrder = _audioTracks
        .map((clip) => clip.clipId)
        .toList(growable: false);
    final beforeSelectedIds = _timelineSelectedClipIndices
        .where(_isValidClipIndex)
        .map((index) => _audioTracks[index].clipId)
        .toList(growable: false);
    final beforePrimaryId = _isValidClipIndex(_timelinePrimarySelectedClipIndex)
        ? _audioTracks[_timelinePrimarySelectedClipIndex].clipId
        : '';
    final beforeSelectedRowId = _isValidRowIndex(_selectedRow)
        ? _rowIdAt(_selectedRow)
        : null;
    final sourcePayloads = indexed
        .map((item) => _persistedClipPayload(item.clip))
        .toList();
    final label = (data['label'] ?? 'Glued Clip').toString().trim();
    final resultId = 'glued_${const Uuid().v4()}';
    final resultPayload = Map<String, dynamic>.from(sourcePayloads.first)
      ..['clipId'] = resultId
      ..['fileName'] = p.basename(rendered.path)
      ..['clipType'] = ClipKind.audio.wireName
      ..['rowIndex'] = indexed.first.clip.rowIndex
      ..['rowId'] = indexed.first.clip.rowId
      ..['offset'] = selectionStartSec
      ..['audioDurationMs'] = renderedDuration.inMilliseconds
      ..['trimStartMs'] = 0
      ..['trimEndMs'] = renderedDuration.inMilliseconds
      ..['label'] = label.isEmpty ? 'Glued Clip' : label
      ..['gain'] = kDefaultGainUi
      ..['normalizeVolume'] = false
      ..['normalizeGain'] = 1.0
      ..['preNormalizeGain'] = 1.0
      ..['pitchSemitones'] = 0.0
      ..['isReversed'] = false
      ..['sourceTempoBpm'] = _tempo
      ..['stretchToProjectTempo'] = false
      ..['tempoStretchPreservePitch'] = false
      ..['tempoWarpMode'] = kTempoWarpModeComplex
      ..['recordingLatencyMs'] = 0.0
      ..['alignmentOffsetMs'] = 0.0
      ..['audioEnhancementPreset'] = ''
      ..['crossfade'] = 1.0
      ..['automation'] = const <Object>[];
    resultPayload
      ..remove('instrumentId')
      ..remove('instrumentName')
      ..remove('instrumentParams')
      ..remove('midiNotes')
      ..remove('hostedInstrumentStateB64');

    final action = GlueAudioClipsAction(
      sourcePayloads: sourcePayloads,
      resultPayload: resultPayload,
      beforeClipOrder: beforeOrder,
      beforeSelectedClipIds: beforeSelectedIds,
      beforePrimaryClipId: beforePrimaryId,
      beforeSelectedRowId: beforeSelectedRowId,
      applySnapshot: _applyAiV3GlueSnapshot,
    );
    await _undoManager.execute(action);
    return <String, dynamic>{
      'kind': 'clips_glued',
      'source_clip_ids': sourceIds,
      'result_clip_id': resultId,
      'row_id': rowIds.single,
      'start': selectionStartSec,
      'length': renderedDurationMs / 1000.0,
      'label': resultPayload['label'],
      'file': rendered.path,
      'expected_clip_count': beforeOrder.length - sourceIds.length + 1,
    };
  }

  Future<void> _applyAiV3StemSeparationSnapshot({
    required int sourceRowId,
    required Map<String, dynamic> vocalsPayload,
    required Map<String, dynamic> instrumentalPayload,
    required List<String> beforeSelectedClipIds,
    required String beforePrimaryClipId,
    required int? beforeSelectedRowId,
    required bool separated,
  }) async {
    final vocalsId = _normalizePersistedClipId(vocalsPayload['clipId']);
    final instrumentalId = _normalizePersistedClipId(
      instrumentalPayload['clipId'],
    );
    if (sourceRowId < 0 ||
        vocalsId.isEmpty ||
        instrumentalId.isEmpty ||
        vocalsId == instrumentalId) {
      throw StateError('v3_clip_stems_snapshot_invalid');
    }

    Future<void> removeGeneratedRowFor(String clipId) async {
      final clipIndex = _clipIndexForPersistentId(clipId);
      if (!_isValidClipIndex(clipIndex)) return;
      await _deleteAiCreatedRow(_audioTracks[clipIndex].rowId);
    }

    Future<void> createOutputs() async {
      final sourceRow = _rowIndexForId(sourceRowId);
      if (!_isValidRowIndex(sourceRow) ||
          _clipIndexForPersistentId(vocalsId) >= 0 ||
          _clipIndexForPersistentId(instrumentalId) >= 0) {
        throw StateError('v3_clip_stems_source_state_invalid');
      }
      int? vocalsRowId;
      int? instrumentalRowId;
      try {
        final preferredVocalsRowId = _toActionInt(
          vocalsPayload['generatedRowId'],
        );
        vocalsRowId = await _createAiRow(
          name: (vocalsPayload['label'] ?? 'Separated Vocals').toString(),
          midi: false,
          instrumentId: '',
          position: 'below',
          referenceRowId: sourceRowId,
          preferredRowId: preferredVocalsRowId,
        );
        if (preferredVocalsRowId != null &&
            vocalsRowId != preferredVocalsRowId) {
          throw StateError('v3_clip_stems_vocals_row_identity_mismatch');
        }
        final preferredInstrumentalRowId = _toActionInt(
          instrumentalPayload['generatedRowId'],
        );
        instrumentalRowId = await _createAiRow(
          name: (instrumentalPayload['label'] ?? 'Separated Instrumental')
              .toString(),
          midi: false,
          instrumentId: '',
          position: 'below',
          referenceRowId: vocalsRowId,
          preferredRowId: preferredInstrumentalRowId,
        );
        if (preferredInstrumentalRowId != null &&
            instrumentalRowId != preferredInstrumentalRowId) {
          throw StateError('v3_clip_stems_instrumental_row_identity_mismatch');
        }
        final vocalsRow = _rowIndexForId(vocalsRowId);
        final instrumentalRow = _rowIndexForId(instrumentalRowId);
        if (!_isValidRowIndex(vocalsRow) ||
            !_isValidRowIndex(instrumentalRow)) {
          throw StateError('v3_clip_stems_row_create_failed');
        }
        vocalsPayload
          ..['generatedRowId'] = vocalsRowId
          ..['rowId'] = vocalsRowId
          ..['rowIndex'] = vocalsRow;
        instrumentalPayload
          ..['generatedRowId'] = instrumentalRowId
          ..['rowId'] = instrumentalRowId
          ..['rowIndex'] = instrumentalRow;
        await _addClipFromUndoPayload(vocalsPayload);
        await _addClipFromUndoPayload(instrumentalPayload);
        if (_clipIndexForPersistentId(vocalsId) < 0 ||
            _clipIndexForPersistentId(instrumentalId) < 0) {
          throw StateError('v3_clip_stems_clip_create_failed');
        }
        _restoreAiV3ClipSelection(
          selectedClipIds: <String>[instrumentalId],
          primaryClipId: instrumentalId,
          selectedRowId: instrumentalRowId,
        );
      } catch (error, stackTrace) {
        var rollbackIncomplete = false;
        try {
          await removeGeneratedRowFor(instrumentalId);
          await removeGeneratedRowFor(vocalsId);
          if (instrumentalRowId != null &&
              _rowIndexForId(instrumentalRowId) >= 0) {
            await _deleteAiCreatedRow(instrumentalRowId);
          }
          if (vocalsRowId != null && _rowIndexForId(vocalsRowId) >= 0) {
            await _deleteAiCreatedRow(vocalsRowId);
          }
          _restoreAiV3ClipSelection(
            selectedClipIds: beforeSelectedClipIds,
            primaryClipId: beforePrimaryClipId,
            selectedRowId: beforeSelectedRowId,
          );
        } catch (_) {
          rollbackIncomplete = true;
        }
        if (rollbackIncomplete) {
          Error.throwWithStackTrace(
            _EditorUndoCaptureRollbackException(error),
            stackTrace,
          );
        }
        Error.throwWithStackTrace(error, stackTrace);
      }
    }

    Future<void> removeOutputs() async {
      if (_clipIndexForPersistentId(vocalsId) < 0 ||
          _clipIndexForPersistentId(instrumentalId) < 0) {
        throw StateError('v3_clip_stems_result_state_invalid');
      }
      try {
        await removeGeneratedRowFor(instrumentalId);
        await removeGeneratedRowFor(vocalsId);
        _restoreAiV3ClipSelection(
          selectedClipIds: beforeSelectedClipIds,
          primaryClipId: beforePrimaryClipId,
          selectedRowId: beforeSelectedRowId,
        );
      } catch (error, stackTrace) {
        try {
          await createOutputs();
        } catch (_) {
          Error.throwWithStackTrace(
            _EditorUndoCaptureRollbackException(error),
            stackTrace,
          );
        }
        Error.throwWithStackTrace(error, stackTrace);
      }
    }

    if (separated) {
      await createOutputs();
    } else {
      await removeOutputs();
    }
    await _syncAllClipFadesToEngine();
    _updateOverallDurationIfNeeded();
    _scheduleProjectAutosave();
    if (mounted) setState(() {});
  }

  Map<String, dynamic> _aiV3NeutralStemPayload({
    required AudioTrack source,
    required String clipId,
    required File file,
    required String label,
    required Duration duration,
  }) {
    final payload = _persistedClipPayload(source)
      ..['clipId'] = clipId
      ..['fileName'] = p.basename(file.path)
      ..['clipType'] = ClipKind.audio.wireName
      ..['offset'] = source.offset
      ..['audioDurationMs'] = duration.inMilliseconds
      ..['trimStartMs'] = 0
      ..['trimEndMs'] = duration.inMilliseconds
      ..['label'] = label
      ..['gain'] = kDefaultGainUi
      ..['normalizeVolume'] = false
      ..['normalizeGain'] = 1.0
      ..['preNormalizeGain'] = 1.0
      ..['pitchSemitones'] = 0.0
      ..['isReversed'] = false
      ..['sourceTempoBpm'] = _tempo
      ..['stretchToProjectTempo'] = false
      ..['tempoStretchPreservePitch'] = false
      ..['tempoWarpMode'] = kTempoWarpModeComplex
      ..['recordingLatencyMs'] = 0.0
      ..['alignmentOffsetMs'] = 0.0
      ..['audioEnhancementPreset'] = ''
      ..['crossfade'] = 1.0
      ..['automation'] = const <Object>[];
    payload
      ..remove('instrumentId')
      ..remove('instrumentName')
      ..remove('instrumentParams')
      ..remove('midiNotes')
      ..remove('hostedInstrumentStateB64');
    return payload;
  }

  Future<Map<String, dynamic>> _applyAiV3ClipSeparateStemsAction(
    Map<String, dynamic> data, {
    AiV3WorkflowRuntime? workflowRuntime,
  }) async {
    final target = _actionTarget(data);
    final clipId = (target['clip_id'] ?? data['clip_id']).toString().trim();
    final clipIndex = _clipIndexForPersistentId(clipId);
    if (!_isValidClipIndex(clipIndex) || _audioTracks[clipIndex].isMidi) {
      throw StateError('v3_clip_stems_target_invalid');
    }
    if (_rowCount + 2 > _effectiveMaxRows ||
        _audioTracks.length + 2 > kNumClips) {
      throw StateError('v3_clip_stems_capacity');
    }
    final source = _audioTracks[clipIndex];
    final sourceFile = File(source.file.path);
    if (!await sourceFile.exists() || await sourceFile.length() <= 44) {
      throw StateError('v3_clip_stems_source_unreadable');
    }
    final expectedRowId = _toActionInt(data['source_row_id']);
    final expectedStartMs = _toActionDouble(data['start_ms']);
    final expectedDurationMs = _toActionDouble(data['duration_ms']);
    final visibleDurationMs = _clipTimelineDurationMs(source).toDouble();
    if (expectedRowId != source.rowId ||
        expectedStartMs == null ||
        expectedDurationMs == null ||
        (expectedStartMs - source.offset * 1000.0).abs() > 2.0 ||
        (expectedDurationMs - visibleDurationMs).abs() > 2.0 ||
        visibleDurationMs <= 0) {
      throw StateError('v3_clip_stems_stale_source');
    }

    final audioDir = ProjectManager.audioDir(_projectDir);
    await audioDir.create(recursive: true);
    final nonce =
        '${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}';
    final dryInput = File(p.join(audioDir.path, '.stem_input_$nonce.wav'));
    final vocalsFile = File(p.join(audioDir.path, 'stem_vocals_$nonce.wav'));
    final instrumentalFile = File(
      p.join(audioDir.path, 'stem_instrumental_$nonce.wav'),
    );
    workflowRuntime
      ?..trackGeneratedArtifact(vocalsFile.path)
      ..trackGeneratedArtifact(instrumentalFile.path);
    final snapshotJson = _buildGlueExportClipSnapshotJson(
      selectedIndices: <int>{clipIndex},
      selectionStartSec: source.offset,
    );
    File? renderedInput;

    try {
      final renderedPath = await JuceAudioEngine.exportMix(
        dryInput.path,
        format: 'wav',
        sampleRate: 48000,
        wavBitDepth: 24,
        wavDithering: false,
        clipSnapshotJson: snapshotJson,
        dryClipRender: true,
      );
      final rendered = renderedInput = File(
        renderedPath.trim().isNotEmpty ? renderedPath.trim() : dryInput.path,
      );
      if (!await rendered.exists() || await rendered.length() <= 44) {
        throw StateError('v3_clip_stems_render_failed');
      }
      final decoded = _decodePcmWav(
        ByteData.sublistView(await rendered.readAsBytes()),
      );
      if (decoded == null || decoded.frameCount <= 0) {
        throw StateError('v3_clip_stems_render_unreadable');
      }
      var peak = 0.0;
      for (var index = 0; index < decoded.frameCount; index++) {
        peak = math.max(peak, decoded.left[index].abs());
        peak = math.max(peak, decoded.right[index].abs());
      }
      if (peak < 1e-5) {
        throw StateError('v3_clip_stems_source_silent');
      }
      _showSmallNotice('Separating vocals and instrumental locally...');
      final override = widget.stemSeparatorOverride;
      if (override != null) {
        await override(
          inputPath: rendered.path,
          vocalsOutputPath: vocalsFile.path,
          instrumentalOutputPath: instrumentalFile.path,
        );
      } else {
        await _spleeterStemSeparator.separateVocalsInstrumental(
          inputPath: rendered.path,
          vocalsOutputPath: vocalsFile.path,
          instrumentalOutputPath: instrumentalFile.path,
          onProgress: (progress) {
            if (progress.progress == 0 || progress.progress >= 1) {
              _showSmallNotice(progress.message);
            }
          },
        );
      }
    } catch (_) {
      for (final file in <File>[vocalsFile, instrumentalFile]) {
        if (await file.exists()) await file.delete();
      }
      rethrow;
    } finally {
      if (await dryInput.exists()) await dryInput.delete();
      final otherRenderedInput = renderedInput;
      if (otherRenderedInput != null &&
          otherRenderedInput.path != dryInput.path &&
          await otherRenderedInput.exists()) {
        await otherRenderedInput.delete();
      }
    }

    final outputDurations = <Duration>[];
    try {
      for (final file in <File>[vocalsFile, instrumentalFile]) {
        if (!await file.exists() || await file.length() <= 44) {
          throw StateError('v3_clip_stems_output_missing');
        }
        final duration = await _resolveSampleDuration(file.path);
        if (duration == null || duration <= Duration.zero) {
          throw StateError('v3_clip_stems_output_unreadable');
        }
        final toleranceMs = math.max(100.0, expectedDurationMs * 0.01);
        if ((duration.inMilliseconds - expectedDurationMs).abs() >
            toleranceMs) {
          throw StateError('v3_clip_stems_output_duration_mismatch');
        }
        outputDurations.add(duration);
      }
    } catch (_) {
      for (final file in <File>[vocalsFile, instrumentalFile]) {
        if (await file.exists()) await file.delete();
      }
      rethrow;
    }

    final sourcePayload = _persistedClipPayload(source);
    final beforeRowIds = _rows.map((row) => row.rowId).toList(growable: false);
    final beforeSelectedIds = _timelineSelectedClipIndices
        .where(_isValidClipIndex)
        .map((index) => _audioTracks[index].clipId)
        .toList(growable: false);
    final beforePrimaryId = _isValidClipIndex(_timelinePrimarySelectedClipIndex)
        ? _audioTracks[_timelinePrimarySelectedClipIndex].clipId
        : '';
    final beforeSelectedRowId = _isValidRowIndex(_selectedRow)
        ? _rowIdAt(_selectedRow)
        : null;
    final vocalsPayload = _aiV3NeutralStemPayload(
      source: source,
      clipId: 'stem_vocals_${const Uuid().v4()}',
      file: vocalsFile,
      label: (data['vocals_label'] ?? 'Separated Vocals').toString(),
      duration: outputDurations[0],
    );
    final instrumentalPayload = _aiV3NeutralStemPayload(
      source: source,
      clipId: 'stem_instrumental_${const Uuid().v4()}',
      file: instrumentalFile,
      label: (data['instrumental_label'] ?? 'Separated Instrumental')
          .toString(),
      duration: outputDurations[1],
    );
    final action = StemSeparationAction(
      sourceRowId: source.rowId,
      vocalsPayload: vocalsPayload,
      instrumentalPayload: instrumentalPayload,
      beforeSelectedClipIds: beforeSelectedIds,
      beforePrimaryClipId: beforePrimaryId,
      beforeSelectedRowId: beforeSelectedRowId,
      applySnapshot: _applyAiV3StemSeparationSnapshot,
    );
    try {
      await _undoManager.execute(action);
    } catch (_) {
      for (final file in <File>[vocalsFile, instrumentalFile]) {
        if (await file.exists()) await file.delete();
      }
      rethrow;
    }
    final vocalsIndex = _clipIndexForPersistentId(
      vocalsPayload['clipId'].toString(),
    );
    final instrumentalIndex = _clipIndexForPersistentId(
      instrumentalPayload['clipId'].toString(),
    );
    if (!_isValidClipIndex(vocalsIndex) ||
        !_isValidClipIndex(instrumentalIndex)) {
      throw StateError('v3_clip_stems_result_state_invalid');
    }
    return <String, dynamic>{
      'kind': 'stems_separated',
      'source_clip_id': clipId,
      'source_payload': sourcePayload,
      'source_row_id': source.rowId,
      'before_row_ids': beforeRowIds,
      'vocals_clip_id': vocalsPayload['clipId'],
      'instrumental_clip_id': instrumentalPayload['clipId'],
      'vocals_row_id': _audioTracks[vocalsIndex].rowId,
      'instrumental_row_id': _audioTracks[instrumentalIndex].rowId,
      'vocals_label': vocalsPayload['label'],
      'instrumental_label': instrumentalPayload['label'],
      'vocals_file': vocalsFile.path,
      'instrumental_file': instrumentalFile.path,
      'start': source.offset,
      'length': expectedDurationMs / 1000.0,
      'vocals_length': outputDurations[0].inMilliseconds / 1000.0,
      'instrumental_length': outputDurations[1].inMilliseconds / 1000.0,
      'expected_row_count': beforeRowIds.length + 2,
      'expected_clip_count': _audioTracks.length,
    };
  }

  Future<void> _applyAiV3AudioToMidiSnapshot({
    required int sourceRowId,
    required Map<String, dynamic> resultPayload,
    required List<String> beforeSelectedClipIds,
    required String beforePrimaryClipId,
    required int? beforeSelectedRowId,
    required bool converted,
  }) async {
    final resultId = _normalizePersistedClipId(resultPayload['clipId']);
    if (sourceRowId < 0 || resultId.isEmpty) {
      throw StateError('v3_audio_to_midi_snapshot_invalid');
    }

    Future<void> removeResult() async {
      final clipIndex = _clipIndexForPersistentId(resultId);
      if (!_isValidClipIndex(clipIndex)) return;
      await _deleteAiCreatedRow(_audioTracks[clipIndex].rowId);
    }

    Future<void> createResult() async {
      final sourceRow = _rowIndexForId(sourceRowId);
      if (!_isValidRowIndex(sourceRow) ||
          _clipIndexForPersistentId(resultId) >= 0) {
        throw StateError('v3_audio_to_midi_source_state_invalid');
      }
      int? resultRowId;
      try {
        final instrumentId = (resultPayload['instrumentId'] ?? '')
            .toString()
            .trim();
        if (_findInstrumentSpecById(instrumentId) == null) {
          throw StateError('v3_audio_to_midi_instrument_unavailable');
        }
        final preferredResultRowId = _toActionInt(
          resultPayload['generatedRowId'],
        );
        resultRowId = await _createAiRow(
          name: (resultPayload['label'] ?? 'Audio MIDI').toString(),
          midi: true,
          instrumentId: instrumentId,
          position: 'below',
          referenceRowId: sourceRowId,
          preferredRowId: preferredResultRowId,
        );
        if (preferredResultRowId != null &&
            resultRowId != preferredResultRowId) {
          throw StateError('v3_audio_to_midi_row_identity_mismatch');
        }
        final resultRow = _rowIndexForId(resultRowId);
        if (!_isValidRowIndex(resultRow)) {
          throw StateError('v3_audio_to_midi_row_create_failed');
        }
        resultPayload
          ..['generatedRowId'] = resultRowId
          ..['rowId'] = resultRowId
          ..['rowIndex'] = resultRow;
        await _addClipFromUndoPayload(resultPayload);
        final resultClipIndex = _clipIndexForPersistentId(resultId);
        if (resultClipIndex < 0) {
          throw StateError('v3_audio_to_midi_clip_create_failed');
        }
        final completeResultPayload = _persistedClipPayload(
          _audioTracks[resultClipIndex],
        );
        resultPayload
          ..clear()
          ..addAll(completeResultPayload)
          ..['generatedRowId'] = resultRowId;
        _restoreAiV3ClipSelection(
          selectedClipIds: <String>[resultId],
          primaryClipId: resultId,
          selectedRowId: resultRowId,
        );
      } catch (error, stackTrace) {
        var rollbackIncomplete = false;
        try {
          await removeResult();
          if (resultRowId != null && _rowIndexForId(resultRowId) >= 0) {
            await _deleteAiCreatedRow(resultRowId);
          }
          _restoreAiV3ClipSelection(
            selectedClipIds: beforeSelectedClipIds,
            primaryClipId: beforePrimaryClipId,
            selectedRowId: beforeSelectedRowId,
          );
        } catch (_) {
          rollbackIncomplete = true;
        }
        if (rollbackIncomplete) {
          Error.throwWithStackTrace(
            _EditorUndoCaptureRollbackException(error),
            stackTrace,
          );
        }
        Error.throwWithStackTrace(error, stackTrace);
      }
    }

    Future<void> removeConvertedResult() async {
      if (_clipIndexForPersistentId(resultId) < 0) {
        throw StateError('v3_audio_to_midi_result_state_invalid');
      }
      try {
        await removeResult();
        _restoreAiV3ClipSelection(
          selectedClipIds: beforeSelectedClipIds,
          primaryClipId: beforePrimaryClipId,
          selectedRowId: beforeSelectedRowId,
        );
      } catch (error, stackTrace) {
        try {
          await createResult();
        } catch (_) {
          Error.throwWithStackTrace(
            _EditorUndoCaptureRollbackException(error),
            stackTrace,
          );
        }
        Error.throwWithStackTrace(error, stackTrace);
      }
    }

    if (converted) {
      await createResult();
    } else {
      await removeConvertedResult();
    }
    await _syncAllClipFadesToEngine();
    _updateOverallDurationIfNeeded();
    _scheduleProjectAutosave();
    if (mounted) setState(() {});
  }

  Map<String, dynamic> _aiV3AudioToMidiPayload({
    required AudioTrack source,
    required String clipId,
    required String label,
    required String instrumentId,
    required List<MidiNote> notes,
    required Duration duration,
  }) {
    final instrumentSpec = _instrumentSpecById(instrumentId);
    final payload = _persistedClipPayload(source)
      ..['clipId'] = clipId
      ..['fileName'] = ''
      ..['clipType'] = ClipKind.midi.wireName
      ..['offset'] = source.offset
      ..['audioDurationMs'] = duration.inMilliseconds
      ..['trimStartMs'] = 0
      ..['trimEndMs'] = duration.inMilliseconds
      ..['label'] = label
      ..['gain'] = kDefaultGainUi
      ..['normalizeVolume'] = false
      ..['normalizeGain'] = 1.0
      ..['preNormalizeGain'] = 1.0
      ..['pitchSemitones'] = 0.0
      ..['isReversed'] = false
      ..['sourceTempoBpm'] = _tempo
      ..['stretchToProjectTempo'] = true
      ..['tempoStretchPreservePitch'] = true
      ..['tempoWarpMode'] = kTempoWarpModeComplex
      ..['recordingLatencyMs'] = 0.0
      ..['alignmentOffsetMs'] = 0.0
      ..['audioEnhancementPreset'] = ''
      ..['crossfade'] = 1.0
      ..['automation'] = const <Object>[]
      ..['instrumentId'] = instrumentId
      ..['instrumentName'] = _instrumentNameFromId(instrumentId)
      ..['instrumentParams'] = _instrumentParamsFromSpec(instrumentSpec)
      ..['midiNotes'] = notes
          .map((note) => note.toJson())
          .toList(growable: false)
      ..remove('hostedInstrumentStateB64');
    return payload;
  }

  Future<Map<String, dynamic>> _applyAiV3ClipConvertToMidiAction(
    Map<String, dynamic> data,
  ) async {
    final target = _actionTarget(data);
    final clipId = (target['clip_id'] ?? data['source_clip_id'])
        .toString()
        .trim();
    final clipIndex = _clipIndexForPersistentId(clipId);
    if (!_isValidClipIndex(clipIndex) || _audioTracks[clipIndex].isMidi) {
      throw StateError('v3_audio_to_midi_target_invalid');
    }
    if (_rowCount + 1 > _effectiveMaxRows ||
        _audioTracks.length + 1 > kNumClips) {
      throw StateError('v3_audio_to_midi_capacity');
    }
    final source = _audioTracks[clipIndex];
    final sourceFile = File(source.file.path);
    if (!await sourceFile.exists() || await sourceFile.length() <= 44) {
      throw StateError('v3_audio_to_midi_source_unreadable');
    }
    final instrumentId = (data['instrument_id'] ?? '').toString().trim();
    if (instrumentId.isEmpty || _findInstrumentSpecById(instrumentId) == null) {
      throw StateError('v3_audio_to_midi_instrument_unavailable');
    }
    final expectedRowId = _toActionInt(data['source_row_id']);
    final expectedStartMs = _toActionDouble(data['start_ms']);
    final expectedDurationMs = _toActionDouble(data['duration_ms']);
    final visibleDurationMs = _clipTimelineDurationMs(source).toDouble();
    if (expectedRowId != source.rowId ||
        expectedStartMs == null ||
        expectedDurationMs == null ||
        (expectedStartMs - source.offset * 1000.0).abs() > 2.0 ||
        (expectedDurationMs - visibleDurationMs).abs() > 2.0 ||
        visibleDurationMs <= 0) {
      throw StateError('v3_audio_to_midi_stale_source');
    }

    final audioDir = ProjectManager.audioDir(_projectDir);
    await audioDir.create(recursive: true);
    final nonce =
        '${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}';
    final dryInput = File(p.join(audioDir.path, '.audio_to_midi_$nonce.wav'));
    File? renderedInput;
    final analysisStopwatch = Stopwatch()..start();
    late final List<MidiNote> notes;
    try {
      final renderedPath = await JuceAudioEngine.exportMix(
        dryInput.path,
        format: 'wav',
        sampleRate: 48000,
        wavBitDepth: 24,
        wavDithering: false,
        clipSnapshotJson: _buildGlueExportClipSnapshotJson(
          selectedIndices: <int>{clipIndex},
          selectionStartSec: source.offset,
        ),
        dryClipRender: true,
      );
      final rendered = renderedInput = File(
        renderedPath.trim().isNotEmpty ? renderedPath.trim() : dryInput.path,
      );
      if (!await rendered.exists() || await rendered.length() <= 44) {
        throw StateError('v3_audio_to_midi_render_failed');
      }
      final mono16k = await JuceAudioEngine.decodeAudioMono16k(rendered.path);
      if (mono16k.isEmpty) {
        throw StateError('v3_audio_to_midi_render_unreadable');
      }
      var peak = 0.0;
      for (final sample in mono16k) {
        peak = math.max(peak, sample.abs());
      }
      if (peak < 1e-5) {
        throw StateError('v3_audio_to_midi_source_silent');
      }
      _showSmallNotice('Transcribing audio to MIDI locally...');
      final override = widget.basicPitchOverride;
      late final List<BasicPitchNoteEvent> events;
      try {
        events = override != null
            ? await override(mono16k: mono16k)
            : await BasicPitchTranscriber.instance.transcribeMono16k(mono16k);
      } catch (_) {
        throw StateError('v3_audio_to_midi_transcription_failed');
      }
      if (events.isEmpty) {
        throw StateError('v3_audio_to_midi_no_stable_notes');
      }
      final localDurationMs = mono16k.length * 1000.0 / 16000.0;
      final segment = _ClipMono16kSegment(
        samples: mono16k,
        sampleRate: 16000,
        timelineStartMs: 0.0,
        timelineEndMs: expectedDurationMs,
        timelineMsPerLocalMs: localDurationMs <= 0
            ? 1.0
            : expectedDurationMs / localDurationMs,
      );
      final clipLengthBeats = expectedDurationMs * _tempo / 60000.0;
      final converted = _basicPitchEventsToMidiNotes(segment, events)
          .where(
            (note) => note.startBeat >= 0 && note.startBeat < clipLengthBeats,
          )
          .take(1024)
          .map((note) {
            final copy = note.copy();
            copy.lengthBeats = math
                .min(copy.lengthBeats, clipLengthBeats - copy.startBeat)
                .toDouble();
            return copy;
          })
          .where((note) => note.lengthBeats > 0)
          .toList(growable: false);
      if (converted.isEmpty) {
        throw StateError('v3_audio_to_midi_no_stable_notes');
      }
      notes = converted;
    } finally {
      analysisStopwatch.stop();
      if (await dryInput.exists()) await dryInput.delete();
      final otherRendered = renderedInput;
      if (otherRendered != null &&
          otherRendered.path != dryInput.path &&
          await otherRendered.exists()) {
        await otherRendered.delete();
      }
    }

    final sourcePayload = _persistedClipPayload(source);
    final beforeRowIds = _rows.map((row) => row.rowId).toList(growable: false);
    final beforeSelectedIds = _timelineSelectedClipIndices
        .where(_isValidClipIndex)
        .map((index) => _audioTracks[index].clipId)
        .toList(growable: false);
    final beforePrimaryId = _isValidClipIndex(_timelinePrimarySelectedClipIndex)
        ? _audioTracks[_timelinePrimarySelectedClipIndex].clipId
        : '';
    final beforeSelectedRowId = _isValidRowIndex(_selectedRow)
        ? _rowIdAt(_selectedRow)
        : null;
    final resultPayload = _aiV3AudioToMidiPayload(
      source: source,
      clipId: 'audio_to_midi_${const Uuid().v4()}',
      label: (data['output_label'] ?? 'Audio MIDI').toString(),
      instrumentId: instrumentId,
      notes: notes,
      duration: Duration(milliseconds: expectedDurationMs.round()),
    );
    final action = AudioToMidiConversionAction(
      sourceRowId: source.rowId,
      resultPayload: resultPayload,
      beforeSelectedClipIds: beforeSelectedIds,
      beforePrimaryClipId: beforePrimaryId,
      beforeSelectedRowId: beforeSelectedRowId,
      applySnapshot: _applyAiV3AudioToMidiSnapshot,
    );
    await _undoManager.execute(action);
    return <String, dynamic>{
      'kind': 'audio_converted_to_midi',
      'source_clip_id': clipId,
      'source_payload': sourcePayload,
      'source_row_id': source.rowId,
      'before_row_ids': beforeRowIds,
      'result_clip_id': resultPayload['clipId'],
      'result_label': resultPayload['label'],
      'instrument_id': instrumentId,
      'start': source.offset,
      'length': expectedDurationMs / 1000.0,
      'notes': notes
          .map(
            (note) => <String, dynamic>{
              'pitch': note.pitch,
              'start_beat': note.startBeat,
              'length_beats': note.lengthBeats,
              'velocity': note.velocity,
            },
          )
          .toList(growable: false),
      'analysis_model': 'basic_pitch_nmp.onnx',
      'analysis_elapsed_ms': analysisStopwatch.elapsedMilliseconds,
      'expected_row_count': beforeRowIds.length + 1,
      'expected_clip_count': _audioTracks.length,
    };
  }

  Future<void> _applySampleInsertAction(Map<String, dynamic> data) async {
    final operation = (data['operation'] ?? '').toString().trim().toLowerCase();
    if (operation != 'insert_audio_clips' &&
        operation != 'insert_audio_clip' &&
        operation != 'replace_audio_clips') {
      _insertAssistantChatText(
        'Unsupported sample insert operation "$operation".',
      );
      return;
    }

    final rawItems = data['items'];
    final itemMaps = <Map<String, dynamic>>[];
    if (rawItems is List && rawItems.isNotEmpty) {
      for (final raw in rawItems) {
        final item = _toActionMap(raw);
        if (item.isNotEmpty) itemMaps.add(item);
      }
    } else {
      itemMaps.add(data);
    }

    if (itemMaps.isEmpty) {
      _insertAssistantChatText(
        "I couldn't resolve which library samples to insert.",
      );
      return;
    }

    int inserted = 0;
    int replaced = 0;
    int failed = 0;
    var processedUnits = 0;
    var batchCancelled = false;
    final insertedEngineClipIds = LinkedHashSet<int>();
    final totalUnits = _estimateAiSampleInsertWorkUnits(operation, itemMaps);
    final showBatchOverlay = totalUnits > 1;
    if (showBatchOverlay) {
      _beginAiBatchProcessingOverlay(
        totalUnits: totalUnits,
        title: 'Processing Samples',
        message: 'Adding samples to your project.',
      );
      await JuceAudioEngine.beginProjectClipLoad();
    }
    try {
      for (int i = 0; i < itemMaps.length; i++) {
        if (_cancelAiBatchProcessingRequested) break;
        final itemUnitsBefore = processedUnits;
        try {
          final item = itemMaps[i];
          final target = _actionTarget(item);
          final libraryPath =
              (item['library_path'] ??
                      target['library_path'] ??
                      item['asset_path'] ??
                      target['asset_path'])
                  .toString()
                  .trim();
          var resolvedPath = await _resolveAiLibrarySamplePath(libraryPath);
          if (resolvedPath == null) {
            final directFilePath = (item['file_path'] ?? target['file_path'])
                .toString()
                .trim();
            if (directFilePath.isNotEmpty &&
                _isSampleAudioFile(directFilePath) &&
                File(directFilePath).existsSync()) {
              resolvedPath = directFilePath;
            }
          }
          if (resolvedPath == null) {
            failed++;
            processedUnits += 1;
            if (showBatchOverlay) {
              _updateAiBatchProcessingOverlay(
                completedUnits: processedUnits,
                message: 'Skipping an unavailable sample.',
              );
            }
            continue;
          }

          if (operation == 'replace_audio_clips') {
            final targetClipIndices = _resolveClipIndicesFromActionTarget(
              item,
              requireAudio: true,
            );
            if (targetClipIndices.isEmpty) {
              failed++;
              processedUnits += 1;
              if (showBatchOverlay) {
                _updateAiBatchProcessingOverlay(
                  completedUnits: processedUnits,
                  message: 'Skipping an unresolved target.',
                );
              }
              continue;
            }
            final targetClips = targetClipIndices
                .where((idx) => idx >= 0 && idx < _audioTracks.length)
                .map((idx) => _audioTracks[idx])
                .where((clip) => !clip.isMidi)
                .toList(growable: false);
            if (targetClips.isEmpty) {
              failed++;
              continue;
            }

            final successfulTargetIndices = <int>[];
            for (final clipIndex in targetClipIndices) {
              if (_cancelAiBatchProcessingRequested) break;
              if (clipIndex < 0 || clipIndex >= _audioTracks.length) {
                failed++;
                processedUnits += 1;
                if (showBatchOverlay) {
                  _updateAiBatchProcessingOverlay(
                    completedUnits: processedUnits,
                    message: 'Skipping an invalid target.',
                  );
                }
                continue;
              }
              final clip = _audioTracks[clipIndex];
              if (clip.isMidi) {
                failed++;
                processedUnits += 1;
                if (showBatchOverlay) {
                  _updateAiBatchProcessingOverlay(
                    completedUnits: processedUnits,
                    message: 'Skipping a MIDI target.',
                  );
                }
                continue;
              }
              final inserted = await _insertAudioFileAtTimeline(
                resolvedPath,
                row: clip.rowIndex,
                timeMs: _clipTimelineStartMs(clip),
                enforceKnownAudioExtension: false,
                uploadMethod: 'ai_library',
                showLoadingOverlay: !showBatchOverlay,
                notifyUi: !showBatchOverlay,
                deferFadeSync: showBatchOverlay,
              );
              processedUnits += 1;
              if (showBatchOverlay) {
                _updateAiBatchProcessingOverlay(
                  completedUnits: processedUnits,
                  message: 'Replacing samples in your project.',
                );
              }
              if (inserted) {
                if (_audioTracks.isNotEmpty) {
                  final insertedClip = _audioTracks.last;
                  if (insertedClip.engineClipId >= 0) {
                    insertedEngineClipIds.add(insertedClip.engineClipId);
                  }
                }
                successfulTargetIndices.add(clipIndex);
              } else {
                failed++;
              }
            }
            if (successfulTargetIndices.isNotEmpty) {
              await _handleDeleteClips(successfulTargetIndices);
              replaced += successfulTargetIndices.length;
            }
            continue;
          }

          final explicitStartMs =
              AssistantActionUtils.resolveMoveMusicalStartMs(
                data: item,
                target: target,
                bpm: _tempo,
              );
          final repeatCountHint =
              _toActionInt(
                item['repeat_count'] ??
                    target['repeat_count'] ??
                    item['copies'] ??
                    target['copies'] ??
                    item['count'] ??
                    target['count'],
              ) ??
              1;
          final baseTimeMs =
              explicitStartMs ??
              _toActionDouble(item['start_ms'] ?? target['start_ms']) ??
              AssistantActionUtils.defaultSampleInsertStartMs(
                libraryPath,
                bpm: _tempo,
              );
          final baseRow = await _resolveAudioInsertionRowIndexFromActionTarget(
            item,
          );
          final rowStep =
              _toActionInt(
                item['delta_rows'] ??
                    target['delta_rows'] ??
                    item['row_delta'] ??
                    target['row_delta'] ??
                    item['step_rows'] ??
                    target['step_rows'],
              ) ??
              0;
          final stepMs =
              AssistantActionUtils.resolveMoveMusicalDeltaMs(
                data: item,
                target: target,
                bpm: _tempo,
              ) ??
              _toActionDouble(
                item['step_ms'] ??
                    target['step_ms'] ??
                    item['spacing_ms'] ??
                    target['spacing_ms'],
              ) ??
              AssistantActionUtils.defaultSampleInsertStepMs(
                libraryPath,
                bpm: _tempo,
                repeatCount: repeatCountHint,
              ) ??
              0.0;
          final resolvedStartMs =
              baseTimeMs ?? _globalAudioClock.inMilliseconds.toDouble();
          final repeatCount = AssistantActionUtils.resolvePlacementRepeatCount(
            data: item,
            target: target,
            bpm: _tempo,
            startMs: resolvedStartMs,
            stepMs: stepMs,
            preferSpanCoverageOverExplicitCount: true,
          );

          for (int copyIndex = 0; copyIndex < repeatCount; copyIndex++) {
            if (_cancelAiBatchProcessingRequested) break;
            final row = math.max(0, baseRow + (rowStep * copyIndex));
            final timeMs = math.max(
              0.0,
              resolvedStartMs + (stepMs * copyIndex),
            );
            final beforeCount = _audioTracks.length;
            final insertedClip = await _insertAudioFileAtTimeline(
              resolvedPath,
              row: row,
              timeMs: timeMs,
              enforceKnownAudioExtension: false,
              uploadMethod: 'ai_library',
              showLoadingOverlay: !showBatchOverlay,
              notifyUi: !showBatchOverlay,
              deferFadeSync: showBatchOverlay,
            );
            processedUnits += 1;
            if (showBatchOverlay) {
              _updateAiBatchProcessingOverlay(
                completedUnits: processedUnits,
                message: 'Adding samples to your project.',
              );
            }
            if (!insertedClip) {
              failed++;
              continue;
            }
            inserted++;
            if (_audioTracks.length > beforeCount) {
              final addedClip = _audioTracks.last;
              if (addedClip.engineClipId >= 0) {
                insertedEngineClipIds.add(addedClip.engineClipId);
              }
              await _autoConfigureInsertedLibraryClip(
                addedClip,
                libraryPath,
                deferEngineSync: showBatchOverlay,
              );
            }
          }
        } catch (error, stackTrace) {
          debugPrint('AI sample insert item failed: $error');
          unawaited(
            CrashReportingService.instance.captureException(
              error,
              stackTrace: stackTrace,
            ),
          );
          failed++;
          if (processedUnits == itemUnitsBefore) {
            processedUnits += 1;
          }
          if (showBatchOverlay) {
            _updateAiBatchProcessingOverlay(
              completedUnits: processedUnits,
              message: 'Skipping a sample that could not be added.',
            );
          }
        }
      }
    } finally {
      batchCancelled = _cancelAiBatchProcessingRequested;
      if (showBatchOverlay) {
        await JuceAudioEngine.endProjectClipLoad();
        final insertedClipIndices = insertedEngineClipIds
            .map(_clipIndexForEngineId)
            .where((index) => index >= 0 && index < _audioTracks.length)
            .toList(growable: false);
        await _syncDeferredClipTimelineBatchToEngine(
          insertedClipIndices,
          includeMix: true,
        );
        final affectedFadeRowIds = insertedClipIndices
            .map((index) => _clipRowIdForFadeSync(_audioTracks[index]))
            .where((rowId) => rowId >= 0)
            .toSet();
        await _syncClipFadesForRowsToEngine(affectedFadeRowIds);
      }
      if (showBatchOverlay) {
        _endAiBatchProcessingOverlay();
      }
    }

    if (insertedEngineClipIds.isNotEmpty && mounted) {
      final selectedIndices = insertedEngineClipIds
          .map(_clipIndexForEngineId)
          .where((idx) => idx >= 0 && idx < _audioTracks.length)
          .toList(growable: false);
      if (selectedIndices.isNotEmpty) {
        final primaryIndex = selectedIndices.last;
        final primaryClip = _audioTracks[primaryIndex];
        setState(() {
          _timelineSelectedClipIndices = List<int>.from(selectedIndices);
          _timelinePrimarySelectedClipIndex = primaryIndex;
          if (_rowCount > 0) {
            _selectedRow = primaryClip.rowIndex.clamp(0, _rowCount - 1).toInt();
          } else {
            _selectedRow = primaryClip.rowIndex;
          }
        });
        unawaited(_syncLiveMidiInputTargetClip());
      }
    }

    if (inserted <= 0 && replaced <= 0) {
      _insertAssistantChatText(
        operation == 'replace_audio_clips'
            ? "I couldn't resolve any library samples or target clips to replace."
            : "I couldn't resolve any library samples to insert.",
      );
      return;
    }
    if (batchCancelled) {
      if (inserted > 0 || replaced > 0) {
        _showSmallNotice(
          'Stopped after inserting $inserted sample clip${inserted == 1 ? '' : 's'} and replacing $replaced clip${replaced == 1 ? '' : 's'}.',
        );
      } else {
        _showSmallNotice('Stopped sample processing.');
      }
      return;
    }
    if (failed > 0) {
      if (replaced > 0 && inserted > 0) {
        _showSmallNotice(
          'Inserted $inserted sample clip${inserted == 1 ? '' : 's'} and replaced $replaced clip${replaced == 1 ? '' : 's'} ($failed skipped).',
        );
      } else if (replaced > 0) {
        _showSmallNotice(
          'Replaced $replaced clip${replaced == 1 ? '' : 's'} ($failed skipped).',
        );
      } else {
        _showSmallNotice(
          'Inserted $inserted sample clip${inserted == 1 ? '' : 's'} ($failed skipped).',
        );
      }
      return;
    }
    if (replaced > 0 && inserted > 0) {
      _showSmallNotice(
        'Inserted $inserted sample clip${inserted == 1 ? '' : 's'} and replaced $replaced clip${replaced == 1 ? '' : 's'}.',
      );
      return;
    }
    if (replaced > 0) {
      _showSmallNotice('Replaced $replaced clip${replaced == 1 ? '' : 's'}.');
      return;
    }
    _showSmallNotice(
      'Inserted $inserted sample clip${inserted == 1 ? '' : 's'}.',
    );
  }

