  }

  _ParsedAutomationTargetId _parseAutomationTargetId(String targetId) {
    final trimmed = targetId.trim();
    if (trimmed == 'volume') {
      return const _ParsedAutomationTargetId(
        scope: 'row',
        section: 'volume',
        isVolume: true,
        legacyEffectIndex: -1,
        effectKey: '',
        paramId: 'volume',
        mixParamId: 'volume',
      );
    }

    if (trimmed.startsWith('mix:')) {
      final paramId = _decodeAutomationIdComponent(
        trimmed.substring('mix:'.length),
      );
      return _ParsedAutomationTargetId(
        scope: 'row',
        section: 'mix',
        isVolume: false,
        legacyEffectIndex: -1,
        effectKey: '',
        paramId: paramId,
        mixParamId: paramId,
      );
    }

    if (trimmed.startsWith('master:')) {
      final paramId = _decodeAutomationIdComponent(
        trimmed.substring('master:'.length),
      );
      return _ParsedAutomationTargetId(
        scope: 'master',
        section: 'mix',
        isVolume: false,
        legacyEffectIndex: -1,
        effectKey: '',
        paramId: paramId,
        mixParamId: paramId,
      );
    }

    if (trimmed.startsWith('masterfxid:')) {
      final payload = trimmed.substring('masterfxid:'.length);
      final splitAt = payload.indexOf(':');
      if (splitAt > 0) {
        final encodedEffectKey = payload.substring(0, splitAt);
        final encodedParamId = payload.substring(splitAt + 1);
        return _ParsedAutomationTargetId(
          scope: 'master',
          section: 'effect',
          isVolume: false,
          legacyEffectIndex: -1,
          effectKey: _decodeAutomationIdComponent(encodedEffectKey),
          paramId: _decodeAutomationIdComponent(encodedParamId),
        );
      }
    }

    if (trimmed.startsWith('instrument:')) {
      final payload = trimmed.substring('instrument:'.length);
      final splitAt = payload.indexOf(':');
      if (splitAt > 0) {
        return _ParsedAutomationTargetId(
          scope: 'instrument',
          section: 'instrument',
          isVolume: false,
          legacyEffectIndex: -1,
          effectKey: _decodeAutomationIdComponent(
            payload.substring(0, splitAt),
          ),
          paramId: _decodeAutomationIdComponent(payload.substring(splitAt + 1)),
        );
      }
    }

    if (trimmed.startsWith('fxid:')) {
      final payload = trimmed.substring('fxid:'.length);
      final splitAt = payload.indexOf(':');
      if (splitAt > 0) {
        final encodedEffectKey = payload.substring(0, splitAt);
        final encodedParamId = payload.substring(splitAt + 1);
        return _ParsedAutomationTargetId(
          scope: 'row',
          section: 'effect',
          isVolume: false,
          legacyEffectIndex: -1,
          effectKey: _decodeAutomationIdComponent(encodedEffectKey),
          paramId: _decodeAutomationIdComponent(encodedParamId),
        );
      }
    }

    final parts = trimmed.split(':');
    if (parts.length >= 3 && parts.first == 'fx') {
      return _ParsedAutomationTargetId(
        scope: 'row',
        section: 'effect',
        isVolume: false,
        legacyEffectIndex: int.tryParse(parts[1]) ?? -1,
        effectKey: '',
        paramId: parts.sublist(2).join(':'),
      );
    }

    return _ParsedAutomationTargetId(
      scope: 'row',
      section: 'effect',
      isVolume: false,
      legacyEffectIndex: -1,
      effectKey: '',
      paramId: trimmed,
    );
  }

