  Map<String, _AutomationTargetMeta> _defaultAutomationTargetsForRow(int row) {
    final safeRowGain = (row >= 0 && row < _rowGain.length)
        ? (_rowGain[row] / _kGainUiMax).clamp(0.0, 1.0).toDouble()
        : (_kGainUiUnity / _kGainUiMax);
    final safeRowPan = (row >= 0 && row < _rowPan.length)
        ? _rowPan[row].clamp(0.0, 1.0).toDouble()
        : 0.5;
    return <String, _AutomationTargetMeta>{
      'volume': _volumeAutomationTargetMeta(),
      _rowMixAutomationTargetId('gain'): _rowGainAutomationTargetMeta(
        initialNormalized: safeRowGain,
      ),
      _rowMixAutomationTargetId('pan'): _rowPanAutomationTargetMeta(
        initialNormalized: safeRowPan,
      ),
      _masterMixAutomationTargetId('gain'): _masterGainAutomationTargetMeta(
        initialNormalized: (_masterGain / _kGainUiMax).clamp(0.0, 1.0),
      ),
      _masterMixAutomationTargetId('pan'): _masterPanAutomationTargetMeta(
        initialNormalized: _masterPan.clamp(0.0, 1.0),
      ),
    };
  }

  _AutomationTargetMeta _fallbackAutomationTargetMeta(String targetId) {
    if (targetId == 'volume') return _volumeAutomationTargetMeta();
    final parsed = _parseAutomationTargetId(targetId);
    final mixParam = parsed.mixParamId.trim().toLowerCase();
    if (parsed.section == 'mix') {
      if (parsed.isMaster) {
        if (mixParam == 'gain') return _masterGainAutomationTargetMeta();
        if (mixParam == 'pan') return _masterPanAutomationTargetMeta();
      } else {
        if (mixParam == 'gain') return _rowGainAutomationTargetMeta();
        if (mixParam == 'pan') return _rowPanAutomationTargetMeta();
      }
    }
    final fallbackLabel = switch (mixParam) {
      'gain' => parsed.isMaster ? 'Master Gain' : 'Track Gain',
      'pan' => parsed.isMaster ? 'Master Pan' : 'Track Pan',
      _ => parsed.paramId.isNotEmpty ? parsed.paramId : targetId,
    };
    return _AutomationTargetMeta(
      targetId: targetId,
      label: fallbackLabel,
      effectIndex: parsed.legacyEffectIndex,
      paramId: parsed.paramId,
      type: 'float',
      min: 0.0,
      max: 1.0,
      initialNormalized: targetId == 'volume' ? 0.75 : 0.5,
    );
  }

  _AutomationTargetMeta _orphanAutomationTargetMeta(
    String targetId, {
    String? label,
  }) {
    final safeLabel = (label ?? '').trim();
    final base =
        (_automationTargetMetaFromAnyRow(targetId) ??
                _fallbackAutomationTargetMeta(targetId))
            .copyWith(
              targetId: targetId,
              label: safeLabel.isEmpty ? null : safeLabel,
              isOrphan: true,
              uiVisible: false,
            );
    return base.copyWith(
      label: base.label.trim().isEmpty ? targetId : base.label.trim(),
      isOrphan: true,
      uiVisible: false,
    );
  }

  double _normalizeAutomationValue(
    double? rawValue, {
    required double min,
    required double max,
    double fallback = 0.5,
  }) {
    if (rawValue == null) return fallback.clamp(0.0, 1.0).toDouble();
    final span = max - min;
    if (!span.isFinite || span.abs() < 1e-9) {
      return fallback.clamp(0.0, 1.0).toDouble();
    }
    return ((rawValue - min) / span).clamp(0.0, 1.0).toDouble();
  }

  double _denormalizeAutomationValue(
    double normalized,
    _AutomationTargetMeta target,
  ) {
    if (target.isVolume) {
      return normalized.clamp(0.0, 1.0).toDouble();
    }
    final span = target.max - target.min;
    if (!span.isFinite || span.abs() < 1e-9) {
      return target.min;
    }
    return target.min + span * normalized.clamp(0.0, 1.0).toDouble();
  }

  double _normalizedChoiceAutomationValue(
    Map<String, dynamic> paramMap, {
    double fallback = 0.5,
  }) {
    final choiceKeys =
        paramMap.keys
            .where((key) => key.startsWith('choice_'))
            .toList(growable: false)
          ..sort((a, b) {
            final ai = int.tryParse(a.substring('choice_'.length)) ?? 0;
            final bi = int.tryParse(b.substring('choice_'.length)) ?? 0;
            return ai.compareTo(bi);
          });
    if (choiceKeys.isEmpty) {
      return fallback.clamp(0.0, 1.0).toDouble();
    }

    final rawValue = (paramMap['value'] ?? '').toString().trim();
    if (rawValue.isNotEmpty) {
      for (int i = 0; i < choiceKeys.length; i++) {
        final choice = (paramMap[choiceKeys[i]] ?? '').toString().trim();
        if (choice == rawValue) {
          if (choiceKeys.length <= 1) return 0.0;
          return (i / (choiceKeys.length - 1)).clamp(0.0, 1.0).toDouble();
        }
      }
    }

    final numericValue = _toActionDouble(paramMap['value']);
    if (numericValue != null) {
      return numericValue.clamp(0.0, 1.0).toDouble();
    }
    return fallback.clamp(0.0, 1.0).toDouble();
  }

  double _initialAutomationNormalizedFromParamMap(
    Map<String, dynamic> paramMap, {
    required double min,
    required double max,
    double fallback = 0.5,
  }) {
    final type = (paramMap['type'] ?? '').toString().trim().toLowerCase();
    switch (type) {
      case 'bool':
        final raw = paramMap['value'];
        if (raw is bool) return raw ? 1.0 : 0.0;
        final numeric = _toActionDouble(raw);
        return ((numeric ?? fallback) >= 0.5 ? 1.0 : 0.0);
      case 'choice':
        return _normalizedChoiceAutomationValue(paramMap, fallback: fallback);
      default:
        final valueNormalized = _normalizedParamMapValue(
          paramMap['valueNormalized'],
        );
        if (valueNormalized != null) return valueNormalized;
        return _normalizeAutomationValue(
          (paramMap['value'] as num?)?.toDouble(),
          min: min,
          max: max,
          fallback: fallback,
        );
    }
  }

  double? _normalizedParamMapValue(Object? raw) {
    final value = _toActionDouble(raw);
    if (value == null || !value.isFinite) return null;
    return value.clamp(0.0, 1.0).toDouble();
  }

  Map<double, String> _automationDisplayLabelsFromParamMap(
    Map<String, dynamic> paramMap,
  ) {
    final labels = <double, String>{};

    void add(Object? normalizedRaw, Object? labelRaw) {
      final normalized = _normalizedParamMapValue(normalizedRaw);
      final label = (labelRaw ?? '').toString().trim();
      if (normalized == null || label.isEmpty) return;
      labels[normalized] = label;
    }

    add(0.0, paramMap['displayMin']);
    add(0.5, paramMap['displayMid']);
    add(1.0, paramMap['displayMax']);
    add(paramMap['defaultNormalized'], paramMap['displayDefault']);
    add(paramMap['valueNormalized'], paramMap['displayValue']);
    return labels;
  }

  List<Map<String, dynamic>> _toNormalizedAutomationMaps(
    List<AutomationPoint> points,
  ) {
    return points
        .map(
          (p) => <String, dynamic>{'x': p.x, 'value': p.volume.clamp(0.0, 1.0)},
        )
        .toList(growable: false);
  }

  Set<String> _automationTargetIdsForRowSync(int row) {
    final ids = <String>{
      'volume',
      _rowMixAutomationTargetId('gain'),
      _rowMixAutomationTargetId('pan'),
    };
    ids.addAll(_rowAutomationTargets[row]?.keys ?? const <String>{});
    ids.addAll(_rowPluginAutomation[row]?.keys ?? const <String>{});
    return ids;
  }

  Set<String> _masterAutomationTargetIdsForSync() {
    final ids = <String>{
      _masterMixAutomationTargetId('gain'),
      _masterMixAutomationTargetId('pan'),
    };
    for (int row = 0; row < _rowCount; row++) {
      ids.addAll(
        (_rowAutomationTargets[row]?.keys ?? const <String>{}).where(
          _isMasterAutomationTarget,
        ),
      );
      ids.addAll(
        (_rowPluginAutomation[row]?.keys ?? const <String>{}).where(
          _isMasterAutomationTarget,
        ),
      );
    }
    return ids;
  }

  Future<void> _syncNativeRowAutomationForRow(int row) async {
    if (row < 0 || row >= _rowCount) return;

    final resolvedVolume = _resolvedAutomationPointsForTarget(row, 'volume');
    await JuceAudioEngine.setTrackAutomationPoints(
      row,
      _toMaps(resolvedVolume),
    );

    final rowGainTargetId = _rowMixAutomationTargetId('gain');
    final resolvedGain = _hasExplicitAutomationForTarget(row, rowGainTargetId)
        ? _resolvedAutomationPointsForTarget(row, rowGainTargetId)
        : const <AutomationPoint>[];
    await JuceAudioEngine.setRowGainAutomationPoints(
      row,
      _toNormalizedAutomationMaps(resolvedGain),
    );

    final rowPanTargetId = _rowMixAutomationTargetId('pan');
    final resolvedPan = _hasExplicitAutomationForTarget(row, rowPanTargetId)
        ? _resolvedAutomationPointsForTarget(row, rowPanTargetId)
        : const <AutomationPoint>[];
    await JuceAudioEngine.setRowPanAutomationPoints(
      row,
      _toNormalizedAutomationMaps(resolvedPan),
    );

    await JuceAudioEngine.clearTrackEffectAutomationForRow(row);
    final midiClipsForRow = _audioTracks.where(
      (clip) => clip.isMidi && clip.rowIndex == row && clip.engineClipId >= 0,
    );
    for (final clip in midiClipsForRow) {
      await JuceAudioEngine.clearMidiClipPluginAutomation(clip.engineClipId);
    }

    final targets =
        _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
    for (final targetId in _automationTargetIdsForRowSync(row)) {
      if (!_hasExplicitAutomationForTarget(row, targetId)) {
        continue;
      }
      final target =
          targets[targetId] ?? _fallbackAutomationTargetMeta(targetId);
      if (target.isOrphan) continue;
      final parsed = _parseAutomationTargetId(targetId);
      if (parsed.scope == 'instrument') {
        final clipIndex = _audioTracks.indexWhere(
          (clip) => clip.clipId == parsed.effectKey,
        );
        final engineClipId = clipIndex >= 0
            ? _audioTracks[clipIndex].engineClipId
            : -1;
        if (engineClipId >= 0 && parsed.paramId.trim().isNotEmpty) {
          final safePoints = _resolvedAutomationPointsForTarget(row, targetId);
          await JuceAudioEngine.setMidiClipPluginAutomationPoints(
            engineClipId,
            parsed.paramId,
            _toNormalizedAutomationMaps(safePoints),
          );
        }
        continue;
      }
      if (target.isVolume || parsed.isMaster || !parsed.isEffectParameter) {
        continue;
      }
      if (target.effectIndex < 0) continue;
      if (target.paramId.trim().isEmpty) continue;

      final safePoints = _resolvedAutomationPointsForTarget(row, targetId);
      await JuceAudioEngine.setTrackEffectAutomationPoints(
        row,
        target.effectIndex,
        target.paramId,
        target.min,
        target.max,
        _toNormalizedAutomationMaps(safePoints),
      );
    }
  }

  Future<void> _syncNativeMasterAutomation() async {
    final masterGainTargetId = _masterMixAutomationTargetId('gain');
    final masterGainPoints =
        _hasExplicitAutomationForTarget(0, masterGainTargetId)
        ? _resolvedAutomationPointsForTarget(0, masterGainTargetId)
        : const <AutomationPoint>[];
    await JuceAudioEngine.setMasterGainAutomationPoints(
      _toNormalizedAutomationMaps(masterGainPoints),
    );

    final masterPanTargetId = _masterMixAutomationTargetId('pan');
    final masterPanPoints =
        _hasExplicitAutomationForTarget(0, masterPanTargetId)
        ? _resolvedAutomationPointsForTarget(0, masterPanTargetId)
        : const <AutomationPoint>[];
    await JuceAudioEngine.setMasterPanAutomationPoints(
      _toNormalizedAutomationMaps(masterPanPoints),
    );

    await JuceAudioEngine.clearMasterEffectAutomation();

    for (final targetId in _masterAutomationTargetIdsForSync()) {
      if (!_hasExplicitAutomationForTarget(0, targetId)) continue;
      final parsed = _parseAutomationTargetId(targetId);
      if (!parsed.isMaster || !parsed.isEffectParameter) continue;
      final target =
          _automationTargetMetaFromAnyRow(targetId) ??
          _fallbackAutomationTargetMeta(targetId);
      if (target.isOrphan) continue;
      if (target.effectIndex < 0) continue;
      if (target.paramId.trim().isEmpty) continue;

      final safePoints = _resolvedAutomationPointsForTarget(0, targetId);
      await JuceAudioEngine.setMasterEffectAutomationPoints(
        target.effectIndex,
        target.paramId,
        target.min,
        target.max,
        _toNormalizedAutomationMaps(safePoints),
      );
    }
  }

  Future<void> _syncNativeAutomationForRow(
    int row, {
    bool syncMaster = true,
  }) async {
    await _syncNativeRowAutomationForRow(row);
    if (syncMaster) {
      await _syncNativeMasterAutomation();
    }
  }

  Future<void> _syncNativePluginAutomationForRow(int row) async {
    await _syncNativeAutomationForRow(row);
  }

  Future<void> _syncNativeAutomationForAllRows() async {
    _migrateAutomationClipsToLanePoints();
    for (int row = 0; row < _rowCount; row++) {
      await _syncNativeRowAutomationForRow(row);
    }
    await _syncNativeMasterAutomation();
  }

  Set<String>? _visibleAutomationParamsForEffect(String effectName) {
    final allowedNames = kExposedEffectParameterNames[effectName.trim()];
    return allowedNames?.toSet();
  }

  bool _isAutomationTargetVisibleInMenu(_AutomationTargetMeta target) {
    if (target.isVolume) return true;
    if (!target.uiVisible) return false;
    if (target.isOrphan) return false;
    return true;
  }

  Future<List<_DiscoveredAutomationTarget>> _discoverMasterAutomationTargets({
    Map<String, _AutomationTargetMeta> previousTargets =
        const <String, _AutomationTargetMeta>{},
  }) async {
    final masterEffects = await JuceAudioEngine.getMasterEffects();
    var masterEffectIds = await JuceAudioEngine.getMasterEffectIds();
    if (masterEffectIds.length != masterEffects.length) {
      masterEffectIds = List<String>.from(masterEffects);
    }
    final signature = _automationDiscoverySignature(<List<String>>[
      masterEffects,
      masterEffectIds,
    ]);
    final cached = _masterAutomationDiscoveryCache;
    if (cached != null && cached.signature == signature) {
      return _cloneDiscoveredAutomationTargets(cached.targets);
    }

    final discovered = <_DiscoveredAutomationTarget>[];
    final masterEffectDisplayLabels = buildAutomationEffectDisplayLabels(
      effectNames: masterEffects,
      fallbackIds: masterEffectIds,
    );
    final masterEffectOrdinalById = <String, int>{};
    for (
      int effectIndex = 0;
      effectIndex < masterEffects.length;
      effectIndex++
    ) {
      final effectName = masterEffects[effectIndex].trim();
      final params = exposedEffectParameters(
        effectName,
        await JuceAudioEngine.getMasterPluginParameters(effectIndex),
      );
      final visibleParams = _visibleAutomationParamsForEffect(effectName);
      final displayEffectName = effectIndex < masterEffectDisplayLabels.length
          ? masterEffectDisplayLabels[effectIndex].displayName
          : effectName;
      final rawEffectId =
          (effectIndex < masterEffectIds.length
                  ? masterEffectIds[effectIndex]
                  : effectName)
              .trim();
      final effectIdentity = rawEffectId.isNotEmpty
          ? rawEffectId
          : (effectName.isNotEmpty ? effectName : 'effect');
      final effectOrdinal = masterEffectOrdinalById.update(
        effectIdentity,
        (value) => value + 1,
        ifAbsent: () => 0,
      );
      final effectKey = _pluginAutomationEffectKey(
        effectIdentity,
        effectOrdinal,
      );
      for (final p in params) {
        final type = (p['type'] ?? '').toString().trim().toLowerCase();
        if (type != 'float' && type != 'bool' && type != 'choice') continue;

        final rawId = (p['id'] ?? p['name'] ?? '').toString().trim();
        final rawName = (p['name'] ?? rawId).toString().trim();
        if (rawId.isEmpty || rawName.isEmpty) continue;
        final isVisible =
            visibleParams == null || visibleParams.contains(rawName);

        final min = type == 'float'
            ? ((p['min'] as num?)?.toDouble() ?? 0.0)
            : 0.0;
        final max = type == 'float'
            ? ((p['max'] as num?)?.toDouble() ?? 1.0)
            : 1.0;
        final unit = (p['unit'] ?? '').toString().trim();
        final targetId = _masterAutomationTargetIdFromEffectKey(
          effectKey,
          rawId,
        );
        final label = displayEffectName.isEmpty
            ? 'Master • $rawName'
            : 'Master • $displayEffectName • $rawName';
        final previousTarget = previousTargets[targetId];
        final fallbackNormalized = (previousTarget?.initialNormalized ?? 0.5)
            .clamp(0.0, 1.0);
        final currentNormalized = _initialAutomationNormalizedFromParamMap(
          p,
          min: min,
          max: max,
          fallback: fallbackNormalized,
        );
        final defaultNormalized = _normalizedParamMapValue(
          p['defaultNormalized'],
        );
        final displayLabels = _automationDisplayLabelsFromParamMap(p);

        discovered.add(
          _DiscoveredAutomationTarget(
            meta: _AutomationTargetMeta(
              targetId: targetId,
              label: label,
              effectIndex: effectIndex,
              paramId: rawId,
              type: type,
              unit: unit,
              min: min,
              max: max,
              initialNormalized: currentNormalized,
              defaultNormalized: defaultNormalized,
              displayLabels: displayLabels,
              uiVisible: isVisible,
            ),
            scope: 'master',
            effectKey: effectKey,
          ),
        );
      }
    }
    _masterAutomationDiscoveryCache = _AutomationDiscoveryCacheEntry(
      signature: signature,
      targets: _cloneDiscoveredAutomationTargets(discovered),
    );
    return discovered;
  }

  void _scheduleAutomationTargetsRefreshForRow(int row) {
    if (row < 0 || row >= _rowCount) return;
    if (_allRowsAutomationTargetsRefreshInFlight) {
      _allRowsAutomationTargetsRefreshQueued = true;
      return;
    }
    if (_rowAutomationTargetRefreshInFlight.contains(row)) {
      _rowAutomationTargetRefreshQueued.add(row);
      return;
    }
    _rowAutomationTargetRefreshInFlight.add(row);
    unawaited(() async {
      try {
        while (true) {
          _rowAutomationTargetRefreshQueued.remove(row);
          await _refreshAutomationTargetsForRow(row);
          if (!_rowAutomationTargetRefreshQueued.remove(row)) {
            break;
          }
        }
      } finally {
        _rowAutomationTargetRefreshInFlight.remove(row);
      }
    }());
  }

  void _scheduleAutomationTargetsRefreshForAllRows() {
    if (_allRowsAutomationTargetsRefreshInFlight) {
      _allRowsAutomationTargetsRefreshQueued = true;
      return;
    }
    _allRowsAutomationTargetsRefreshInFlight = true;
    _rowAutomationTargetRefreshInFlight.clear();
    _rowAutomationTargetRefreshQueued.clear();
    unawaited(() async {
      try {
        while (true) {
          _allRowsAutomationTargetsRefreshQueued = false;
          await _refreshAutomationTargetsForAllRows();
          if (!_allRowsAutomationTargetsRefreshQueued) {
            break;
          }
        }
      } finally {
        _allRowsAutomationTargetsRefreshInFlight = false;
      }
    }());
  }

  Future<void> _refreshAutomationTargetsForRow(
    int row, {
    bool setStateWhenDone = true,
    bool syncNativeWhenDone = true,
    List<_DiscoveredAutomationTarget>? sharedMasterTargets,
  }) async {
    if (row < 0 || row >= _rowCount) return;

    final previousTargets = Map<String, _AutomationTargetMeta>.from(
      _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{},
    );
    final discovered = <String, _AutomationTargetMeta>{
      'volume': _volumeAutomationTargetMeta(),
      _rowMixAutomationTargetId('gain'): _rowGainAutomationTargetMeta(
        initialNormalized: (_rowGain[row] / _kGainUiMax).clamp(0.0, 1.0),
      ),
      _rowMixAutomationTargetId('pan'): _rowPanAutomationTargetMeta(
        initialNormalized: _rowPan[row].clamp(0.0, 1.0),
      ),
      _masterMixAutomationTargetId('gain'): _masterGainAutomationTargetMeta(
        initialNormalized: (_masterGain / _kGainUiMax).clamp(0.0, 1.0),
      ),
      _masterMixAutomationTargetId('pan'): _masterPanAutomationTargetMeta(
        initialNormalized: _masterPan.clamp(0.0, 1.0),
      ),
    };
    final discoveredByEffectKeyAndParam = <String, _AutomationTargetMeta>{};
    final discoveredByLegacyIndexAndParam = <String, _AutomationTargetMeta>{};
    final discoveredByParam = <String, List<_AutomationTargetMeta>>{};

    void recordDiscoveredTarget(
      _AutomationTargetMeta meta, {
      required String scope,
      String effectKey = '',
    }) {
      discovered[meta.targetId] = meta;
      final paramLower = meta.paramId.trim().toLowerCase();
      if (paramLower.isEmpty) return;
      if (effectKey.trim().isNotEmpty) {
        discoveredByEffectKeyAndParam['$scope\u0000${effectKey.trim()}\u0000$paramLower'] =
            meta;
      }
      if (meta.effectIndex >= 0) {
        discoveredByLegacyIndexAndParam['$scope\u0000${meta.effectIndex}\u0000$paramLower'] =
            meta;
      }
      discoveredByParam
          .putIfAbsent(
            '$scope\u0000$paramLower',
            () => <_AutomationTargetMeta>[],
          )
          .add(meta);
    }

    final rowId = _rowIdAt(row);
    final effects = await JuceAudioEngine.getTrackEffectsForRow(row);
    var effectInstanceIds =
        await JuceAudioEngine.getTrackEffectInstanceIdsForRow(row);
    if (effectInstanceIds.length != effects.length) {
      effectInstanceIds = List<String>.filled(effects.length, '');
    }
    var effectIds = await JuceAudioEngine.getTrackEffectIdsForRow(row);
    if (effectIds.length != effects.length) {
      effectIds = List<String>.from(effects);
    }
    final rowSignature = _automationDiscoverySignature(<List<String>>[
      effects,
      effectIds,
      effectInstanceIds,
    ]);
    final cachedRowDiscovery = rowId >= 0
        ? _rowAutomationDiscoveryCache[rowId]
        : null;
    if (cachedRowDiscovery != null &&
        cachedRowDiscovery.signature == rowSignature) {
      for (final entry in cachedRowDiscovery.targets) {
        recordDiscoveredTarget(
          entry.meta.copyWith(),
          scope: entry.scope,
          effectKey: entry.effectKey,
        );
      }
    } else {
      final effectDisplayLabels = buildAutomationEffectDisplayLabels(
        effectNames: effects,
        fallbackIds: effectIds,
      );
      final effectOrdinalById = <String, int>{};
      final discoveredRowTargets = <_DiscoveredAutomationTarget>[];
      for (int effectIndex = 0; effectIndex < effects.length; effectIndex++) {
        final effectName = effects[effectIndex].trim();
        final params = exposedEffectParameters(
          effectName,
          await JuceAudioEngine.getTrackPluginParameters(row, effectIndex),
        );
        final visibleParams = _visibleAutomationParamsForEffect(effectName);
        final displayEffectName = effectIndex < effectDisplayLabels.length
            ? effectDisplayLabels[effectIndex].displayName
            : effectName;
        final rawInstanceId =
            (effectIndex < effectInstanceIds.length
                    ? effectInstanceIds[effectIndex]
                    : '')
                .trim();
        final rawEffectId =
            (effectIndex < effectIds.length
                    ? effectIds[effectIndex]
                    : effectName)
                .trim();
        final effectIdentity = rawEffectId.isNotEmpty
            ? rawEffectId
            : (effectName.isNotEmpty ? effectName : 'effect');
        final effectOrdinal = effectOrdinalById.update(
          effectIdentity,
          (value) => value + 1,
          ifAbsent: () => 0,
        );
        final effectKey = rawInstanceId.isNotEmpty
            ? 'inst:$rawInstanceId'
            : _pluginAutomationEffectKey(effectIdentity, effectOrdinal);
        for (final p in params) {
          final type = (p['type'] ?? '').toString().trim().toLowerCase();
          if (type != 'float' && type != 'bool' && type != 'choice') continue;

          final rawId = (p['id'] ?? p['name'] ?? '').toString().trim();
          final rawName = (p['name'] ?? rawId).toString().trim();
          if (rawId.isEmpty || rawName.isEmpty) continue;
          final isVisible =
              visibleParams == null || visibleParams.contains(rawName);

          final min = type == 'float'
              ? ((p['min'] as num?)?.toDouble() ?? 0.0)
              : 0.0;
          final max = type == 'float'
              ? ((p['max'] as num?)?.toDouble() ?? 1.0)
              : 1.0;
          final unit = (p['unit'] ?? '').toString().trim();
          final targetId = _pluginAutomationTargetIdFromEffectKey(
            effectKey,
            rawId,
          );
          final label = displayEffectName.isEmpty
              ? rawName
              : '$displayEffectName • $rawName';
          final previousTarget = previousTargets[targetId];
          final fallbackNormalized = (previousTarget?.initialNormalized ?? 0.5)
              .clamp(0.0, 1.0);
          final currentNormalized = _initialAutomationNormalizedFromParamMap(
            p,
            min: min,
            max: max,
            fallback: fallbackNormalized,
          );
          final defaultNormalized = _normalizedParamMapValue(
            p['defaultNormalized'],
          );
          final displayLabels = _automationDisplayLabelsFromParamMap(p);

          final entry = _DiscoveredAutomationTarget(
            meta: _AutomationTargetMeta(
              targetId: targetId,
              label: label,
              effectIndex: effectIndex,
              paramId: rawId,
              type: type,
              unit: unit,
              min: min,
              max: max,
              initialNormalized: currentNormalized,
              defaultNormalized: defaultNormalized,
              displayLabels: displayLabels,
              uiVisible: isVisible,
            ),
            scope: 'row',
            effectKey: effectKey,
          );
          discoveredRowTargets.add(entry);
          recordDiscoveredTarget(
            entry.meta,
            scope: entry.scope,
            effectKey: entry.effectKey,
          );
        }
      }
      if (rowId >= 0) {
        _rowAutomationDiscoveryCache[rowId] = _AutomationDiscoveryCacheEntry(
          signature: rowSignature,
          targets: _cloneDiscoveredAutomationTargets(discoveredRowTargets),
        );
      }
    }

    final masterTargets =
        sharedMasterTargets ??
        await _discoverMasterAutomationTargets(
          previousTargets: previousTargets,
        );
    for (final entry in masterTargets) {
      recordDiscoveredTarget(
        entry.meta,
        scope: entry.scope,
        effectKey: entry.effectKey,
      );
    }

    _AutomationTargetMeta? resolveRemappedTarget(String originalTargetId) {
      if (originalTargetId == 'volume') return discovered['volume'];
      final existing = discovered[originalTargetId];
      if (existing != null) return existing;

      final previousMeta =
          previousTargets[originalTargetId] ??
          _fallbackAutomationTargetMeta(originalTargetId);
      final parsed = _parseAutomationTargetId(originalTargetId);

      // Hosted instrument parameters are not part of the row FX parameter
      // discovery pass. Their target id deliberately contains the persisted
      // clip id, so reconnect them directly to the newly assigned native clip
      // id after a project reopen. Without this, valid VST/AU instrument
      // automation is marked orphaned, hidden, and never sent back to JUCE.
      if (parsed.scope == 'instrument') {
        final clipId = parsed.effectKey.trim();
        final paramId = parsed.paramId.trim();
        final clip = _audioTracks.cast<AudioTrack?>().firstWhere(
          (candidate) =>
              candidate != null &&
              candidate.isMidi &&
              candidate.clipId == clipId &&
              candidate.engineClipId >= 0,
          orElse: () => null,
        );
        if (clip != null && paramId.isNotEmpty) {
          return previousMeta.copyWith(
            targetId: originalTargetId,
            effectIndex: clip.engineClipId,
            paramId: paramId,
            isOrphan: false,
            uiVisible: true,
          );
        }
        return null;
      }

      final normalizedParamId =
          (parsed.paramId.isNotEmpty ? parsed.paramId : previousMeta.paramId)
              .trim()
              .toLowerCase();
      if (normalizedParamId.isEmpty) return null;

      if (parsed.effectKey.isNotEmpty) {
        final byEffectKey =
            discoveredByEffectKeyAndParam['${parsed.scope}\u0000${parsed.effectKey}\u0000$normalizedParamId'];
        if (byEffectKey != null) return byEffectKey;
      }

      if (parsed.legacyEffectIndex >= 0) {
        final byLegacy =
            discoveredByLegacyIndexAndParam['${parsed.scope}\u0000${parsed.legacyEffectIndex}\u0000$normalizedParamId'];
        if (byLegacy != null) return byLegacy;
      }

      // For fxid targets, instance ids can change after restoring a project.
      // Fall back to lane metadata (effectIndex + paramId) captured at save.
      if (previousMeta.effectIndex >= 0) {
        final bySavedLaneEffectIndex =
            discoveredByLegacyIndexAndParam['${parsed.scope}\u0000${previousMeta.effectIndex}\u0000$normalizedParamId'];
        if (bySavedLaneEffectIndex != null) return bySavedLaneEffectIndex;
      }

      final candidates =
          discoveredByParam['${parsed.scope}\u0000$normalizedParamId'] ??
          const <_AutomationTargetMeta>[];
      if (candidates.isEmpty) return null;

      final previousLabelLower = previousMeta.label.trim().toLowerCase();
      if (previousLabelLower.isNotEmpty) {
        final byLabel = candidates
            .where(
              (candidate) =>
                  candidate.label.trim().toLowerCase() == previousLabelLower,
            )
            .toList(growable: false);
        if (byLabel.length == 1) {
          return byLabel.first;
        }
      }

      return null;
    }

    _AutomationTargetMeta orphanMetaForTarget(
      String targetId, {
      Iterable<AutomationClipSnapshot> clipHints =
          const <AutomationClipSnapshot>[],
    }) {
      String? labelHint;
      for (final clip in clipHints) {
        final label = clip.label.trim();
        if (label.isNotEmpty) {
          labelHint = label;
          break;
        }
      }
      return _orphanAutomationTargetMeta(targetId, label: labelHint);
    }

    final pluginByTarget = Map<String, List<AutomationPoint>>.from(
      _rowPluginAutomation[row] ?? const <String, List<AutomationPoint>>{},
    );
    final remappedPlugin = <String, List<AutomationPoint>>{};
    for (final entry in pluginByTarget.entries) {
      final originalTargetId = entry.key;
      if (originalTargetId == 'volume') continue;

      final resolvedTarget = resolveRemappedTarget(originalTargetId);
      final resolvedTargetId = resolvedTarget?.targetId ?? originalTargetId;
      final targetMeta =
          resolvedTarget ?? orphanMetaForTarget(originalTargetId);
      discovered[resolvedTargetId] = targetMeta;

      final safePoints = _sanitizeAutomationPointsForTarget(
        row,
        resolvedTargetId,
        entry.value,
      );
      final existing =
          remappedPlugin[resolvedTargetId] ?? const <AutomationPoint>[];
      remappedPlugin[resolvedTargetId] = _sanitizeAutomationPointsForTarget(
        row,
        resolvedTargetId,
        <AutomationPoint>[
          ...existing.map((p) => p.copy()),
          ...safePoints.map((p) => p.copy()),
        ],
      );
    }

    _rowPluginAutomation[row] = remappedPlugin;
    _rowAutomationClips[row] = <String, List<AutomationClipSnapshot>>{};
    _rowAutomationTargets[row] = discovered;
    final selected = _rowSelectedAutomationTarget[row];
    final selectedMeta = selected == null ? null : discovered[selected];
    if (selected == null ||
        selectedMeta == null ||
        !_isAutomationTargetVisibleInMenu(selectedMeta)) {
      final fallback = discovered.containsKey('volume')
          ? 'volume'
          : discovered.values
                .firstWhere(
                  _isAutomationTargetVisibleInMenu,
                  orElse: () => _volumeAutomationTargetMeta(),
                )
                .targetId;
      _rowSelectedAutomationTarget[row] = fallback;
    }

    if (setStateWhenDone) {
      _refreshAudioEditorView();
    }

    if (syncNativeWhenDone) {
      await _syncNativePluginAutomationForRow(row);
    }
  }

  Future<void> _refreshAutomationTargetsForAllRows({
    bool syncNativeWhenDone = true,
  }) async {
    final sharedMasterTargets = await _discoverMasterAutomationTargets();
    for (int row = 0; row < _rowCount; row++) {
      await _refreshAutomationTargetsForRow(
        row,
        setStateWhenDone: false,
        syncNativeWhenDone: false,
        sharedMasterTargets: sharedMasterTargets,
      );
      if (syncNativeWhenDone) {
        await _syncNativePluginAutomationForRow(row);
      }
    }
    _refreshAudioEditorView();
  }

  bool _hasPendingAutomationTargetRemap(int row) {
    if (row < 0 || row >= _rowCount) return false;

    bool needsRemap(String targetId) {
      if (targetId == 'volume') return false;
      final meta = _rowAutomationTargets[row]?[targetId];
      return meta == null || meta.isOrphan;
    }

    for (final targetId
        in (_rowPluginAutomation[row]?.keys ?? const <String>{})) {
      if (needsRemap(targetId)) return true;
    }
    return false;
  }

  Future<void> _stabilizeAutomationTargetsAfterProjectLoad() async {
    for (int attempt = 0; attempt < 4; attempt++) {
      final hasPending = List<int>.generate(
        _rowCount,
        (index) => index,
      ).any(_hasPendingAutomationTargetRemap);
      if (!hasPending) return;
      await Future.delayed(const Duration(milliseconds: 120));
      await _refreshAutomationTargetsForAllRows();
    }
  }

  List<Map<String, dynamic>> _automationTargetsForRowUi(int row) {
    if (row < 0 || row >= _rowCount) return const <Map<String, dynamic>>[];
    final targets =
        _rowAutomationTargets[row] ??
        <String, _AutomationTargetMeta>{
          'volume': _volumeAutomationTargetMeta(),
        };
    final values =
        targets.values
            .where(_isAutomationTargetVisibleInMenu)
            .toList(growable: false)
          ..sort((a, b) {
            if (a.isVolume && !b.isVolume) return -1;
            if (!a.isVolume && b.isVolume) return 1;
            if (a.isOrphan && !b.isOrphan) return 1;
            if (!a.isOrphan && b.isOrphan) return -1;
            return a.label.toLowerCase().compareTo(b.label.toLowerCase());
          });
    return values
        .map((target) {
          final map = target.toUiMap();
          map['hasAutomationData'] = _hasUserAutomationDataForTarget(
            row,
            target.targetId,
          );
          return map;
        })
        .toList(growable: false);
  }

  String _selectedAutomationTargetIdForRow(int row) {
    if (row < 0 || row >= _rowCount) return 'volume';
    final selected = _rowSelectedAutomationTarget[row];
    final selectedMeta = selected == null
        ? null
        : _rowAutomationTargets[row]?[selected];
    if (selectedMeta != null &&
        _isAutomationTargetVisibleInMenu(selectedMeta)) {
      return selected!;
    }
    return 'volume';
  }

  void _setSelectedAutomationTargetIdForRow(int row, String targetId) {
    if (row < 0 || row >= _rowCount) return;
    final targets =
        _rowAutomationTargets[row] ??
        <String, _AutomationTargetMeta>{
          'volume': _volumeAutomationTargetMeta(),
        };
    final selectedMeta = targets[targetId];
    if (selectedMeta == null ||
        !_isAutomationTargetVisibleInMenu(selectedMeta)) {
      targetId = 'volume';
    }
    _rowSelectedAutomationTarget[row] = targetId;
    if (mounted) setState(() {});
    _scheduleProjectAutosave();
  }

  List<AutomationPoint> _defaultAutomationPointsForTarget(
    int row,
    String targetId,
  ) {
    double normalized = targetId == 'volume' ? 0.75 : 0.5;
    final parsed = _parseAutomationTargetId(targetId);
    if (parsed.isMixParameter) {
      switch (parsed.mixParamId.trim().toLowerCase()) {
        case 'gain':
          normalized =
              (parsed.isMaster
                      ? (_masterGain / _kGainUiMax)
                      : ((row >= 0 && row < _rowCount)
                            ? (_rowGain[row] / _kGainUiMax)
                            : (_kGainUiUnity / _kGainUiMax)))
                  .clamp(0.0, 1.0)
                  .toDouble();
          break;
        case 'pan':
          normalized =
              (parsed.isMaster
                      ? _masterPan
                      : ((row >= 0 && row < _rowCount) ? _rowPan[row] : 0.5))
                  .clamp(0.0, 1.0)
                  .toDouble();
          break;
        case 'volume':
          normalized = 0.75;
          break;
        default:
          break;
      }
    }
    _AutomationTargetMeta? target;
    if (row >= 0 && row < _rowCount) {
      target = _rowAutomationTargets[row]?[targetId];
    } else {
      target = _automationTargetMetaFromAnyRow(targetId);
    }
    if (target != null) {
      normalized = target.initialNormalized.clamp(0.0, 1.0).toDouble();
    }
    return <AutomationPoint>[AutomationPoint(x: 0.0, volume: normalized)];
  }

  List<AutomationClipSnapshot> _clipsForAutomationTarget(
    int row,
    String targetId,
  ) {
    if (row < 0 || row >= _rowCount) return const <AutomationClipSnapshot>[];
    final rowMap = _rowAutomationClips[row];
    final existing = rowMap?[targetId];
    if (existing == null) return const <AutomationClipSnapshot>[];
    return existing;
  }

  List<AutomationPoint> _sanitizeAutomationClipPointsRelative(
    double lengthMs,
    List<AutomationPoint> points, {
    required double fallbackValue,
  }) {
    final safeLength = lengthMs.clamp(50.0, double.infinity).toDouble();
    final sanitized =
        points
            .map(
              (p) => AutomationPoint(
                x: (p.x.isFinite ? p.x : 0.0).clamp(0.0, safeLength).toDouble(),
                volume: (p.volume.isFinite ? p.volume : fallbackValue)
                    .clamp(0.0, 1.0)
                    .toDouble(),
              ),
            )
            .toList(growable: false)
          ..sort((a, b) => a.x.compareTo(b.x));

    if (sanitized.isEmpty) {
      final fallback = fallbackValue.clamp(0.0, 1.0).toDouble();
      return <AutomationPoint>[AutomationPoint(x: 0.0, volume: fallback)];
    }
    return sanitized;
  }

  List<AutomationClipSnapshot> _sanitizeAutomationClipsForTarget(
    int row,
    String targetId,
    List<AutomationClipSnapshot> clips,
  ) {
    final fallbackValue = targetId == 'volume' ? 0.75 : 0.5;
    final targetLabel = _automationTargetLabelFor(row, targetId);
    final seenIds = <String>{};
    int idCounter = 0;

    final out = <AutomationClipSnapshot>[];
    for (final clip in clips) {
      final safeLength = _clampAutomationLengthMs(clip.lengthMs);
      final safeStart = sanitizeAutomationTimeMs(clip.startMs);
      final safeVisualRow = clip.row
          .clamp(0, math.max(0, _rowCount - 1))
          .toInt();

      var id = clip.id.trim();
      if (id.isEmpty || seenIds.contains(id)) {
        id = 'ac_${row}_${targetId}_${idCounter}_${const Uuid().v4()}';
      }
      idCounter++;
      seenIds.add(id);

      final safePoints = _sanitizeAutomationClipPointsRelative(
        safeLength,
        clip.points,
        fallbackValue: fallbackValue,
      );

      out.add(
        clip.copyWith(
          id: id,
          row: safeVisualRow,
          targetId: targetId,
          lane: math.max(0, clip.lane).toInt(),
          label: clip.label.trim().isEmpty ? targetLabel : clip.label.trim(),
          startMs: safeStart,
          lengthMs: safeLength,
          points: safePoints,
        ),
      );
    }

    out.sort((a, b) {
      final timeCmp = a.startMs.compareTo(b.startMs);
      if (timeCmp != 0) return timeCmp;
      return a.id.compareTo(b.id);
    });
    return out;
  }

  int _defaultAutomationClipRowForSourceRow(int row) {
    if (_rowCount <= 0) return 0;
    return (row + 1).clamp(0, _rowCount - 1).toInt();
  }

  int _preferredAutomationClipRowForTarget(int row, String targetId) {
    if (!_isMasterAutomationTarget(targetId) || _rowCount <= 0) {
      return _defaultAutomationClipRowForSourceRow(row);
    }
    final occupiedRows = _audioTracks
        .map((clip) => clip.rowIndex)
        .where((rowIndex) => rowIndex >= 0 && rowIndex < _rowCount)
        .toSet();
    for (int candidate = 0; candidate < _rowCount; candidate++) {
      if (!occupiedRows.contains(candidate)) {
        return candidate;
      }
    }
    return 0;
  }

  List<AutomationPoint> _pointsForAutomationTarget(int row, String targetId) {
    if (row < 0 || row >= _rowCount) return const <AutomationPoint>[];
    if (targetId == 'volume') return _rowVolumeAutomation[row];
    final rowMap = _rowPluginAutomation[row];
    final existing = rowMap?[targetId];
    if (existing != null) return existing;
    return _defaultAutomationPointsForTarget(row, targetId);
  }

  List<AutomationPoint>? _storedAutomationPointsForTargetOrNull(
    int row,
    String targetId,
  ) {
    if (row < 0 || row >= _rowCount) return null;
    if (targetId == 'volume') return _rowVolumeAutomation[row];
    return _rowPluginAutomation[row]?[targetId];
  }

  bool _hasExplicitAutomationForTarget(int row, String targetId) {
    if (targetId == 'volume') return true;
    if (_isMasterAutomationTarget(targetId)) {
      for (int sourceRow = 0; sourceRow < _rowCount; sourceRow++) {
        final lanePoints = _rowPluginAutomation[sourceRow]?[targetId];
        if (lanePoints != null && lanePoints.isNotEmpty) {
          return true;
        }
      }
      return false;
    }
    final lanePoints = _rowPluginAutomation[row]?[targetId];
    return lanePoints != null && lanePoints.isNotEmpty;
  }

  bool _hasUserAutomationDataForTarget(int row, String targetId) {
    if (row < 0 || row >= _rowCount) return false;

    if (targetId == 'volume') {
      final points = _rowVolumeAutomation[row];
      if (points.length > 1) return true;
      if (points.isNotEmpty && (points.first.volume - 0.75).abs() > 1e-6) {
        return true;
      }
      return false;
    }

    return _hasExplicitAutomationForTarget(row, targetId);
  }

  bool _isMasterAutomationTarget(String targetId) {
    return _parseAutomationTargetId(targetId).isMaster;
  }

  _AutomationTargetMeta? _automationTargetMetaFromAnyRow(String targetId) {
    for (int row = 0; row < _rowCount; row++) {
      final meta = _rowAutomationTargets[row]?[targetId];
      if (meta != null) return meta;
    }
    return null;
  }

  List<AutomationPoint> _evaluationAutomationLanePointsForTarget(
    int row,
    String targetId,
  ) {
    if (!_isMasterAutomationTarget(targetId)) {
      return _sanitizeAutomationPointsForTarget(
        row,
        targetId,
        _pointsForAutomationTarget(row, targetId),
      );
    }

    for (int sourceRow = 0; sourceRow < _rowCount; sourceRow++) {
      final explicit = _storedAutomationPointsForTargetOrNull(
        sourceRow,
        targetId,
      );
      if (explicit == null) continue;
      return _sanitizeAutomationPointsForTarget(sourceRow, targetId, explicit);
    }

    return _sanitizeAutomationPointsForTarget(
      row,
      targetId,
      _defaultAutomationPointsForTarget(row, targetId),
    );
  }

  List<AutomationPoint> _sanitizeAutomationPointsForTarget(
    int row,
    String targetId,
    List<AutomationPoint> points,
  ) {
    final sanitized = sanitizeAutomationPointsPreservingFutureTimes(points);

    if (sanitized.isEmpty) {
      final defaults = _defaultAutomationPointsForTarget(row, targetId);
      return defaults.map((p) => p.copy()).toList(growable: false);
    }

    return sanitized;
  }

  double _evaluateAutomationClipAtRelativeMs(
    AutomationClipSnapshot clip,
    double relativeMs, {
    double fallback = 0.5,
  }) {
    final safeRel = relativeMs.clamp(0.0, clip.lengthMs).toDouble();
    return _evaluateAutomationAtMs(clip.points, safeRel, fallback: fallback);
  }

  double _resolvedAutomationValueAtMs(
    int row,
    String targetId,
    double timeMs, {
    List<AutomationPoint>? lanePointsOverride,
  }) {
    final lanePoints =
        lanePointsOverride ??
        _evaluationAutomationLanePointsForTarget(row, targetId);
    return _evaluateAutomationAtMs(
      lanePoints,
      timeMs,
      fallback: targetId == 'volume' ? 0.75 : 0.5,
    );
  }

  List<AutomationPoint> _resolvedAutomationPointsForTarget(
    int row,
    String targetId,
  ) {
    final lanePoints = _evaluationAutomationLanePointsForTarget(row, targetId);
    return lanePoints.map((p) => p.copy()).toList(growable: false);
  }

  double _evaluateAutomationAtMs(
    List<AutomationPoint> points,
    double timeMs, {
    double fallback = 0.5,
  }) {
    if (points.isEmpty) return fallback;
    if (timeMs <= points.first.x) return points.first.volume;
    if (timeMs >= points.last.x) return points.last.volume;
    for (int i = 0; i < points.length - 1; i++) {
      final a = points[i];
      final b = points[i + 1];
      if (timeMs < a.x || timeMs > b.x) continue;
      final span = (b.x - a.x).abs();
      if (span < 1e-6) return b.volume;
      final t = ((timeMs - a.x) / (b.x - a.x)).clamp(0.0, 1.0);
      return a.volume + ((b.volume - a.volume) * t);
    }
    return points.last.volume;
  }

  Future<void> _syncAutomationTargetToCurrentTime(
    int row,
    String targetId,
  ) async {
    if (targetId == 'volume') return;
    if (!_hasExplicitAutomationForTarget(row, targetId)) return;
    final target =
        _rowAutomationTargets[row]?[targetId] ??
        _automationTargetMetaFromAnyRow(targetId) ??
        _fallbackAutomationTargetMeta(targetId);
    if (target.isVolume) return;
    final parsed = _parseAutomationTargetId(targetId);
    final timeMs = _globalAudioClock.inMilliseconds.toDouble();
    final normalized = _resolvedAutomationValueAtMs(
      row,
      targetId,
      timeMs,
    ).clamp(0.0, 1.0);
    final value = _denormalizeAutomationValue(normalized, target);
    if (parsed.scope == 'instrument') {
      final clipIndex = _audioTracks.indexWhere(
        (clip) => clip.clipId == parsed.effectKey,
      );
      final engineClipId = clipIndex >= 0
          ? _audioTracks[clipIndex].engineClipId
          : -1;
      if (engineClipId >= 0) {
        await JuceAudioEngine.setMidiClipPluginParameter(
          engineClipId,
          parsed.paramId,
          normalized.toDouble(),
        );
      }
    } else if (parsed.isMaster) {
      if (parsed.isMixParameter) {
        switch (parsed.mixParamId.trim().toLowerCase()) {
          case 'gain':
            await JuceAudioEngine.setMasterGain(value);
            break;
          case 'pan':
            await JuceAudioEngine.setMasterPan(value);
            break;
          default:
            break;
        }
      } else if (parsed.isEffectParameter && target.effectIndex >= 0) {
        await JuceAudioEngine.setMasterEffect(
          target.effectIndex,
          target.paramId,
          value,
        );
        _masterFxPlaybackRefresh?.call();
      }
    } else if (parsed.isMixParameter) {
      switch (parsed.mixParamId.trim().toLowerCase()) {
        case 'gain':
          await JuceAudioEngine.setRowGain(row, value);
          break;
        case 'pan':
          await JuceAudioEngine.setRowPan(row, value);
          break;
        default:
          break;
      }
    } else if (parsed.isEffectParameter && target.effectIndex >= 0) {
      await JuceAudioEngine.setTrackEffect(
        row,
        target.effectIndex,
        target.paramId,
        value,
      );
      _refreshRowFxUiForAutomatedEffectParameter(
        row: row,
        effectIndex: target.effectIndex,
      );
    }
    _lastAppliedAutomationNormalized['$row|$targetId'] = normalized.toDouble();
  }

  Future<void> _setAutomationTargetPointsWithUndo(
    int row,
    String targetId,
    List<AutomationPoint> newPoints, {
    List<AutomationPoint>? oldPointsOverride,
    int? stableRowId,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    if (targetId == 'volume') {
      await _setRowAutomationWithUndo(row, newPoints, stableRowId: stableRowId);
      return;
    }

    final oldPoints =
        (oldPointsOverride ?? _pointsForAutomationTarget(row, targetId))
            .map((p) => p.copy())
            .toList(growable: false);
    final safePoints = _sanitizeAutomationPointsForTarget(
      row,
      targetId,
      newPoints,
    );

    await _undoManager.execute(
      SetTargetAutomationPointsAction(
        row: row,
        stableRowId: stableRowId,
        resolveRowIndex: stableRowId == null ? null : _rowIndexForId,
        targetId: targetId,
        oldPoints: oldPoints,
        newPoints: safePoints,
        applyToState: (r, laneId, points) {
          setState(() {
            final rowMap = _rowPluginAutomation.putIfAbsent(
              r,
              () => <String, List<AutomationPoint>>{},
            );
            rowMap[laneId] = points
                .map((p) => p.copy())
                .toList(growable: false);
          });
        },
        onApplied: (r, laneId, _) async {
          _lastAppliedAutomationNormalized.remove('$r|$laneId');
          await _syncNativePluginAutomationForRow(r);
          await _syncAutomationTargetToCurrentTime(r, laneId);
          _scheduleProjectAutosave();
        },
      ),
    );
  }

  bool _sameAiV3AutomationPoints(
    List<AutomationPoint> left,
    List<AutomationPoint> right, {
    double epsilon = 1e-6,
  }) {
    if (left.length != right.length) return false;
    for (int index = 0; index < left.length; index++) {
      if ((left[index].x - right[index].x).abs() > epsilon ||
          (left[index].volume - right[index].volume).abs() > epsilon) {
        return false;
      }
    }
    return true;
  }

  Future<Map<String, dynamic>> _applyAiV3AutomationPointsAction(
    Map<String, dynamic> data,
  ) async {
    final target = _actionTarget(data);
    final rowId = _toActionInt(target['row_id']);
    final row = rowId == null ? -1 : _rowIndexForId(rowId);
    final targetId =
        (target['automation_target_id'] ?? data['automation_target_id'])
            ?.toString()
            .trim();
    if (rowId == null || !_isValidRowIndex(row)) {
      throw StateError('v3_automation_row_unknown');
    }
    if (targetId == null || targetId.isEmpty) {
      throw StateError('v3_automation_target_unknown');
    }
    final targetMeta = _rowAutomationTargets[row]?[targetId];
    if (targetMeta == null ||
        targetMeta.isOrphan ||
        !targetMeta.uiVisible ||
        _isMasterAutomationTarget(targetId)) {
      throw StateError('v3_automation_target_unknown');
    }

    final operation = data['operation']?.toString();
    late final List<AutomationPoint> finalPoints;
    if (operation == 'set_points') {
      final rawPoints = data['points'];
      if (rawPoints is! List ||
          rawPoints.isEmpty ||
          rawPoints.length > aiV3MaxAutomationPoints) {
        throw StateError('v3_automation_points_invalid');
      }
      final parsed = <AutomationPoint>[];
      double? previousTimeMs;
      for (final rawPoint in rawPoints) {
        if (rawPoint is! Map) {
          throw StateError('v3_automation_points_invalid');
        }
        final timeMs = _toActionDouble(rawPoint['time_ms']);
        final value = _toActionDouble(rawPoint['value']);
        if (timeMs == null ||
            !timeMs.isFinite ||
            timeMs < 0 ||
            value == null ||
            !value.isFinite ||
            value < 0 ||
            value > 1 ||
            (previousTimeMs != null && timeMs <= previousTimeMs)) {
          throw StateError('v3_automation_points_invalid');
        }
        parsed.add(AutomationPoint(x: timeMs, volume: value));
        previousTimeMs = timeMs;
      }
      finalPoints = _sanitizeAutomationPointsForTarget(row, targetId, parsed);
    } else if (operation == 'clear') {
      if (targetId == 'volume') {
        final maxMs = math.max(
          1.0,
          _audioOnlyOverallDuration.inMilliseconds.toDouble(),
        );
        finalPoints = <AutomationPoint>[
          AutomationPoint(x: 0.0, volume: 1.0),
          AutomationPoint(x: maxMs, volume: 1.0),
        ];
      } else {
        finalPoints = _sanitizeAutomationPointsForTarget(
          row,
          targetId,
          _defaultAutomationPointsForTarget(row, targetId),
        );
      }
    } else {
      throw StateError('v3_automation_operation_unknown');
    }

    final currentPoints = _sanitizeAutomationPointsForTarget(
      row,
      targetId,
      _pointsForAutomationTarget(row, targetId),
    );
    if (!_sameAiV3AutomationPoints(currentPoints, finalPoints)) {
      await _setAutomationTargetPointsWithUndo(
        row,
        targetId,
        finalPoints,
        stableRowId: rowId,
      );
    }

    return <String, dynamic>{
      'kind': 'automation_points',
      'row': row,
      'row_id': rowId,
      'automation_target_id': targetId,
      'points': finalPoints
          .map(
            (point) => <String, dynamic>{'x': point.x, 'value': point.volume},
          )
          .toList(growable: false),
    };
  }

  List<AutomationLaneSnapshot> _automationLanesForRowSave(int row) {
    if (row < 0 || row >= _rowCount) return const <AutomationLaneSnapshot>[];
    final lanes = <AutomationLaneSnapshot>[];
    final addedTargetIds = <String>{};

    final volumePoints = _sanitizeAutomationPointsForTarget(
      row,
      'volume',
      _rowVolumeAutomation[row],
    );
    lanes.add(_volumeAutomationTargetMeta().toLaneSnapshot(volumePoints));
    addedTargetIds.add('volume');

    final rowPlugin =
        _rowPluginAutomation[row] ?? const <String, List<AutomationPoint>>{};
    final targets =
        _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
    rowPlugin.forEach((targetId, points) {
      if (targetId == 'volume') return;
      final safePoints = _sanitizeAutomationPointsForTarget(
        row,
        targetId,
        points,
      );
      if (safePoints.isEmpty) return;
      final target =
          targets[targetId] ?? _fallbackAutomationTargetMeta(targetId);
      lanes.add(target.toLaneSnapshot(safePoints));
      addedTargetIds.add(targetId);
    });

    return lanes;
  }

  void _restoreAutomationLanesForRow(
    int row,
    List<AutomationLaneSnapshot> lanes, {
    String? selectedTargetId,
  }) {
    if (row < 0 || row >= _rowCount) return;
    final rowPlugin = <String, List<AutomationPoint>>{};
    final rowTargets = <String, _AutomationTargetMeta>{
      'volume': _volumeAutomationTargetMeta(),
    };

    for (final lane in lanes) {
      final targetId = lane.targetId.trim();
      if (targetId.isEmpty) continue;
      final safePoints = _sanitizeAutomationPointsForTarget(
        row,
        targetId,
        lane.points.map((p) => p.copy()).toList(growable: false),
      );
      if (targetId == 'volume') {
        _rowVolumeAutomation[row] = safePoints;
        continue;
      }
      rowPlugin[targetId] = safePoints;
      rowTargets[targetId] = _AutomationTargetMeta.fromLaneSnapshot(lane);
    }

    _rowPluginAutomation[row] = rowPlugin;
    _rowAutomationTargets[row] = rowTargets;
    final fallbackTarget = rowTargets.containsKey('volume')
        ? 'volume'
        : (rowTargets.keys.isNotEmpty ? rowTargets.keys.first : 'volume');
    _rowSelectedAutomationTarget[row] =
        (selectedTargetId != null && rowTargets.containsKey(selectedTargetId))
        ? selectedTargetId
        : fallbackTarget;
  }

  List<AutomationClipSnapshot> _automationClipsForRowSave(int row) {
    return const <AutomationClipSnapshot>[];
  }

  List<AutomationLaneSnapshot> _pluginAutomationLanesForRowSave(int row) {
    return _automationLanesForRowSave(row)
        .where((lane) => lane.targetId != 'volume')
        .map(
          (lane) => AutomationLaneSnapshot(
            targetId: lane.targetId,
            label: lane.label,
            effectIndex: lane.effectIndex,
            paramId: lane.paramId,
            type: lane.type,
            unit: lane.unit,
            min: lane.min,
            max: lane.max,
            points: lane.points
                .map((point) => point.copy())
                .toList(growable: false),
          ),
        )
        .toList(growable: false);
  }

  List<AutomationClipSnapshot> _pluginAutomationClipsForRowSave(int row) {
    return const <AutomationClipSnapshot>[];
  }

  List<AutomationPoint> _flattenAutomationClipsIntoLanePoints({
    required int row,
    required String targetId,
    required List<AutomationPoint> lanePoints,
    required List<AutomationClipSnapshot> clips,
  }) {
    final safeClips = _sanitizeAutomationClipsForTarget(row, targetId, clips);
    if (safeClips.isEmpty) {
      return _sanitizeAutomationPointsForTarget(row, targetId, lanePoints);
    }

    final maxMs = _maxAutomationTimelineMs();
    final safeLane = _sanitizeAutomationPointsForTarget(
      row,
      targetId,
      lanePoints,
    );
    final times = <double>{0.0, maxMs};
    for (final point in safeLane) {
      times.add(point.x.clamp(0.0, maxMs).toDouble());
    }
    for (final clip in safeClips) {
      final start = clip.startMs.clamp(0.0, maxMs).toDouble();
      final end = (clip.startMs + clip.lengthMs).clamp(0.0, maxMs).toDouble();
      if (end <= start) continue;
      times
        ..add(start)
        ..add(end)
        ..add((start - 0.001).clamp(0.0, maxMs).toDouble())
        ..add((end + 0.001).clamp(0.0, maxMs).toDouble());
      for (final point in clip.points) {
        times.add((clip.startMs + point.x).clamp(start, end).toDouble());
      }
    }

    final sortedTimes = times.toList(growable: false)..sort();
    final out = <AutomationPoint>[];
    double? lastX;
    double? lastValue;
    for (final rawTime in sortedTimes) {
      final x = rawTime.clamp(0.0, maxMs).toDouble();
      if (lastX != null && (x - lastX).abs() < 1e-7) continue;
      final baseValue = _evaluateAutomationAtMs(
        safeLane,
        x,
        fallback: targetId == 'volume' ? 0.75 : 0.5,
      );
      final active = activeAutomationClipAtTime(safeClips, x);
      final value = active == null
          ? baseValue
          : _evaluateAutomationClipAtRelativeMs(
              active,
              x - active.startMs,
              fallback: baseValue,
            );
      final normalized = value.clamp(0.0, 1.0).toDouble();
      if (lastValue != null && (normalized - lastValue).abs() < 1e-7) {
        if (lastX != null && (x - lastX).abs() < 0.0005) continue;
      }
      out.add(AutomationPoint(x: x, volume: normalized));
      lastX = x;
      lastValue = normalized;
    }
    return _sanitizeAutomationPointsForTarget(row, targetId, out);
  }

  void _restoreAutomationClipsForRow(
    int row,
    List<AutomationClipSnapshot> clips,
  ) {
    if (row < 0 || row >= _rowCount) return;
    final grouped = <String, List<AutomationClipSnapshot>>{};
    for (final clip in clips) {
      final targetId = clip.targetId.trim().isEmpty ? 'volume' : clip.targetId;
      grouped
          .putIfAbsent(targetId, () => <AutomationClipSnapshot>[])
          .add(clip.copyWith(targetId: targetId));
    }

    for (final entry in grouped.entries) {
      final targetId = entry.key;
      final existingPoints = targetId == 'volume'
          ? _rowVolumeAutomation[row]
          : (_rowPluginAutomation[row]?[targetId] ??
                _defaultAutomationPointsForTarget(row, targetId));
      final flattened = _flattenAutomationClipsIntoLanePoints(
        row: row,
        targetId: targetId,
        lanePoints: existingPoints,
        clips: entry.value,
      );
      if (targetId == 'volume') {
        _rowVolumeAutomation[row] = flattened;
      } else {
        final rowPlugin = _rowPluginAutomation.putIfAbsent(
          row,
          () => <String, List<AutomationPoint>>{},
        );
        rowPlugin[targetId] = flattened;
        final rowTargets = _rowAutomationTargets.putIfAbsent(
          row,
          () => <String, _AutomationTargetMeta>{
            'volume': _volumeAutomationTargetMeta(),
          },
        );
        rowTargets.putIfAbsent(
          targetId,
          () => _fallbackAutomationTargetMeta(targetId),
        );
      }
    }
    _rowAutomationClips[row] = <String, List<AutomationClipSnapshot>>{};
  }

  void _migrateAutomationClipsToLanePoints() {
    for (int row = 0; row < _rowCount; row++) {
      final rowMap = _rowAutomationClips[row];
      if (rowMap == null || rowMap.values.every((clips) => clips.isEmpty)) {
        continue;
      }
      final allClips = <AutomationClipSnapshot>[];
      for (final clips in rowMap.values) {
        allClips.addAll(clips.map((clip) => clip.copyWith()));
      }
      _restoreAutomationClipsForRow(row, allClips);
    }
  }

  Future<_CopiedRowEffectsEntry> _captureCopiedRowEffectsEntry(int row) async {
    return _CopiedRowEffectsEntry(
      effects: await captureRowSnapshot(row, rowId: _rowIdAt(row)),
      automationLanes: _pluginAutomationLanesForRowSave(row),
      automationClips: _pluginAutomationClipsForRowSave(row),
      selectedAutomationTargetId: _selectedAutomationTargetIdForRow(row),
    );
  }

  Future<void> _applyCopiedRowEffectsEntry(
    int row,
    _CopiedRowEffectsEntry entry,
  ) async {
    if (row < 0 || row >= _rowCount) return;

    await _restoreRowSnapshot(
      RowEffectsSnapshot(row, entry.effects.effects, rowId: _rowIdAt(row)),
    );

    final preservedVolume = _rowVolumeAutomation[row]
        .map((point) => point.copy())
        .toList(growable: false);
    final lanes = <AutomationLaneSnapshot>[
      _volumeAutomationTargetMeta().toLaneSnapshot(preservedVolume),
      ...entry.automationLanes.map(
        (lane) => AutomationLaneSnapshot(
          targetId: lane.targetId,
          label: lane.label,
          effectIndex: lane.effectIndex,
          paramId: lane.paramId,
          type: lane.type,
          unit: lane.unit,
          min: lane.min,
          max: lane.max,
          points: lane.points
              .map((point) => point.copy())
              .toList(growable: false),
        ),
      ),
    ];

    setState(() {
      _restoreAutomationLanesForRow(
        row,
        lanes,
        selectedTargetId: entry.selectedAutomationTargetId,
      );
      _restoreAutomationClipsForRow(row, entry.automationClips);
    });

    await _refreshAutomationTargetsForRow(
      row,
      setStateWhenDone: false,
      syncNativeWhenDone: false,
    );
    await _syncNativeAutomationForRow(row);
    _refreshRowFx(row);
    if (mounted) setState(() {});
  }

  Future<void> _copyRowEffects(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final snapshot = await _captureCopiedRowEffectsEntry(row);
    final clipboard = _EffectsClipboardEntry(
      effects: snapshot.effects.effects
          .map(
            (fx) => EffectSnapshot(
              fx.effectId,
              fx.bypassed,
              Map<String, dynamic>.from(fx.params),
              displayName: fx.displayName,
              stateBase64: fx.stateBase64,
            ),
          )
          .toList(growable: false),
      automationLanes: snapshot.automationLanes
          .map(
            (lane) => AutomationLaneSnapshot(
              targetId: lane.targetId,
              label: lane.label,
              effectIndex: lane.effectIndex,
              paramId: lane.paramId,
              type: lane.type,
              unit: lane.unit,
              min: lane.min,
              max: lane.max,
              points: lane.points
                  .map((point) => point.copy())
                  .toList(growable: false),
            ),
          )
          .toList(growable: false),
      automationClips: snapshot.automationClips
          .map((clip) => clip.copyWith())
          .toList(growable: false),
      selectedAutomationTargetId: snapshot.selectedAutomationTargetId,
    );
    if (mounted) {
      setState(() {
        _copiedEffects = clipboard;
      });
    } else {
      _copiedEffects = clipboard;
    }
    _showSmallNotice('Copied row effects.');
  }

  Future<void> _pasteRowEffects(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final clipboard = _copiedEffects;
    if (clipboard == null) {
      _showSmallNotice('Copy effects first.');
      return;
    }

    final before = await _captureCopiedRowEffectsEntry(row);
    final after = _CopiedRowEffectsEntry(
      effects: RowEffectsSnapshot(
        row,
        clipboard.effects
            .map(
              (fx) => EffectSnapshot(
                fx.effectId,
                fx.bypassed,
                Map<String, dynamic>.from(fx.params),
                displayName: fx.displayName,
                stateBase64: fx.stateBase64,
              ),
            )
            .toList(growable: false),
        rowId: _rowIdAt(row),
      ),
      automationLanes: clipboard.automationLanes
          .map(
            (lane) => AutomationLaneSnapshot(
              targetId: lane.targetId,
              label: lane.label,
              effectIndex: lane.effectIndex,
              paramId: lane.paramId,
              type: lane.type,
              unit: lane.unit,
              min: lane.min,
              max: lane.max,
              points: lane.points
                  .map((point) => point.copy())
                  .toList(growable: false),
            ),
          )
          .toList(growable: false),
      automationClips: clipboard.automationClips
          .map((clip) => clip.copyWith())
          .toList(growable: false),
      selectedAutomationTargetId: clipboard.selectedAutomationTargetId,
    );

    await _undoManager.execute(
      _RowEffectsAutomationSnapshotAction(
        descriptionText: 'Paste track effects',
        before: before,
        after: after,
        applySnapshot: (snap) => _applyCopiedRowEffectsEntry(row, snap),
      ),
    );
    _recordProducerManualEdit('row_fx_paste', <String, Object?>{
      'row': row,
      'effect_count': after.effects.effects.length,
      'automation_lane_count': after.automationLanes.length,
      'automation_clip_count': after.automationClips.length,
    });
    _showSmallNotice('Pasted row effects.');
  }

  Future<void> _clearRowEffects(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final before = await _captureCopiedRowEffectsEntry(row);
    final hasEffects = before.effects.effects.isNotEmpty;
    final hasAutomation =
        before.automationLanes.isNotEmpty || before.automationClips.isNotEmpty;
    if (!hasEffects && !hasAutomation) {
      _showSmallNotice('This row has no effects to clear.');
      return;
    }

    await _undoManager.execute(
      _RowEffectsAutomationSnapshotAction(
        descriptionText: 'Clear track effects',
        before: before,
        after: _CopiedRowEffectsEntry(
          effects: RowEffectsSnapshot(
            row,
            const <EffectSnapshot>[],
            rowId: _rowIdAt(row),
          ),
          automationLanes: const <AutomationLaneSnapshot>[],
          automationClips: const <AutomationClipSnapshot>[],
          selectedAutomationTargetId: 'volume',
        ),
        applySnapshot: (snap) => _applyCopiedRowEffectsEntry(row, snap),
      ),
    );
    _clearTabletRowFxSelectionForRow(row);
    _recordProducerManualEdit('row_fx_clear', <String, Object?>{
      'row': row,
      'effect_count': before.effects.effects.length,
      'automation_lane_count': before.automationLanes.length,
      'automation_clip_count': before.automationClips.length,
    });
    _showSmallNotice('Cleared row effects.');
  }

