  Future<void> _setAutomationClipsForTargetWithUndo(
    int row,
    String targetId,
    List<AutomationClipSnapshot> newClips, {
    List<AutomationClipSnapshot>? oldClipsOverride,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    final oldClips = _copyAutomationClipList(
      oldClipsOverride ?? _clipsForAutomationTarget(row, targetId),
    );
    final safeClips = _sanitizeAutomationClipsForTarget(
      row,
      targetId,
      newClips,
    );
    if (safeClips.isNotEmpty) {
      await _ensureAutomationClipDisplayRowExists(row);
    }

    await _undoManager.execute(
      SetTargetAutomationClipsAction(
        row: row,
        targetId: targetId,
        oldClips: oldClips,
        newClips: safeClips,
        applyToState: (r, laneId, clips) {
          setState(() {
            final rowMap = _rowAutomationClips.putIfAbsent(
              r,
              () => <String, List<AutomationClipSnapshot>>{},
            );
            rowMap[laneId] = _copyAutomationClipList(clips);
          });
        },
        onApplied: (r, _, __) async {
          await _syncNativeAutomationForRow(r);
          _lastAppliedAutomationNormalized.remove('$r|$targetId');
          await _syncAutomationTargetToCurrentTime(r, targetId);
        },
      ),
    );
  }

  Future<void> _ensureAutomationClipDisplayRowExists(int sourceRow) async {
    if (sourceRow < 0 || sourceRow >= _rowCount) return;
    if (sourceRow + 1 < _rowCount) return;
    if (_rowCount >= _effectiveMaxRows) return;
    await _addRowImpl();
  }

  Future<void> _ensureLoadedAutomationDisplayRowsExist() async {
    if (_rowCount <= 0 || _rowCount >= _effectiveMaxRows) return;
    final lastRow = _rowCount - 1;
    final rowMap = _rowAutomationClips[lastRow];
    if (rowMap == null) return;
    final hasAutomationClips = rowMap.values.any((clips) => clips.isNotEmpty);
    if (!hasAutomationClips) return;
    await _addRowImpl();
  }

  void _triggerMasterHalos(List<String> haloKeys) {
    final mapped = haloKeys
        .map((key) => key.trim())
        .where((key) => key.isNotEmpty)
        .map(HaloKey.new)
        .toList(growable: false);
    if (mapped.isEmpty) return;
    _mixHighlighter.trigger(
      mapped,
      duration: const Duration(milliseconds: 800),
    );
  }

  String? _findAutomationTargetIdForEffectParameter({
    required int effectIndex,
    required String paramId,
    required bool master,
    int? row,
  }) {
    final normalizedParamId = paramId.trim();
    if (normalizedParamId.isEmpty) return null;

    Iterable<int> candidateRows;
    if (master) {
      candidateRows = List<int>.generate(_rowCount, (i) => i);
    } else {
      if (row == null || row < 0 || row >= _rowCount) return null;
      candidateRows = <int>[row];
    }

    for (final candidateRow in candidateRows) {
      final targets = _rowAutomationTargets[candidateRow];
      if (targets == null) continue;
      for (final entry in targets.entries) {
        if (entry.value.isOrphan) continue;
        final parsed = _parseAutomationTargetId(entry.key);
        if (parsed.isMaster != master) continue;
        if (entry.value.effectIndex != effectIndex) continue;
        if (entry.value.paramId.trim() != normalizedParamId) continue;
        return entry.key;
      }
    }
    return null;
  }

  double _normalizeAutomationTargetValue(
    _AutomationTargetMeta target,
    dynamic value,
  ) {
    final fallback = target.initialNormalized.clamp(0.0, 1.0).toDouble();
    switch (target.type.trim().toLowerCase()) {
      case 'bool':
        if (value is bool) return value ? 1.0 : 0.0;
        final numeric = _toActionDouble(value);
        if (numeric != null) {
          return numeric >= 0.5 ? 1.0 : 0.0;
        }
        return fallback;
      case 'choice':
        final numeric = _toActionDouble(value);
        if (numeric != null) {
          return numeric.clamp(0.0, 1.0).toDouble();
        }
        return fallback;
      default:
        final numeric = _toActionDouble(value);
        return _normalizeAutomationValue(
          numeric,
          min: target.min,
          max: target.max,
          fallback: fallback,
        );
    }
  }

  void _updateAutomationTargetBaselineForEffectParameter({
    required int effectIndex,
    required String paramId,
    required dynamic value,
    required bool master,
    int? row,
  }) {
    final targetId = _findAutomationTargetIdForEffectParameter(
      effectIndex: effectIndex,
      paramId: paramId,
      master: master,
      row: row,
    );
    if (targetId == null || targetId.isEmpty) return;

    final candidateRows = master
        ? List<int>.generate(_rowCount, (index) => index)
        : <int>[if (row != null) row];
    for (final candidateRow in candidateRows) {
      if (candidateRow < 0 || candidateRow >= _rowCount) continue;
      final rowTargets = _rowAutomationTargets[candidateRow];
      final target = rowTargets?[targetId];
      if (target == null) continue;
      final normalized = _normalizeAutomationTargetValue(target, value);
      rowTargets![targetId] = target.copyWith(initialNormalized: normalized);
    }
  }

  Future<void> _ensureAutomationLaneForTarget({
    required int row,
    required String targetId,
    double? initialNormalized,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    final targetMeta =
        _rowAutomationTargets[row]?[targetId] ??
        _automationTargetMetaFromAnyRow(targetId) ??
        _fallbackAutomationTargetMeta(targetId);
    final normalized = (initialNormalized ?? targetMeta.initialNormalized)
        .clamp(0.0, 1.0)
        .toDouble();

    if (targetId != 'volume' &&
        !_hasExplicitAutomationForTarget(row, targetId)) {
      await _setAutomationTargetPointsWithUndo(row, targetId, <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: normalized),
      ]);
    }
    if (!mounted) return;
    _openTimelineAutomationLaneForTarget(row: row, targetId: targetId);
  }

  Future<void> _ensureMasterAutomationLaneForTarget({
    required String targetId,
    double? initialNormalized,
  }) async {
    if (_rowCount <= 0) return;
    const row = 0;
    final targetMeta =
        _automationTargetMetaFromAnyRow(targetId) ??
        _rowAutomationTargets[row]?[targetId] ??
        _fallbackAutomationTargetMeta(targetId);
    final normalized = (initialNormalized ?? targetMeta.initialNormalized)
        .clamp(0.0, 1.0)
        .toDouble();

    if (!_hasExplicitAutomationForTarget(row, targetId)) {
      await _setAutomationTargetPointsWithUndo(row, targetId, <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: normalized),
      ]);
    }
    if (!mounted) return;
    _timelineController.showMasterAutomationLane(targetId);
  }

  void _openTimelineAutomationLaneForTarget({
    required int row,
    required String targetId,
  }) {
    if (row < 0 || row >= _rowCount) return;
    _setSelectedAutomationTargetIdForRow(row, targetId);
    _timelineController.ensureRowExpanded(row, tab: 2);
  }

  Future<void> _createAutomationClipForTarget({
    required int row,
    required String targetId,
    String? label,
    int lane = 0,
    double? startMs,
    double? lengthMs,
    double? initialNormalized,
  }) async {
    if (row < 0 || row >= _rowCount) return;
    if (_isMasterAutomationTarget(targetId)) {
      await _ensureMasterAutomationLaneForTarget(
        targetId: targetId,
        initialNormalized: initialNormalized,
      );
      _showSmallNotice('Automation lane ready.');
      return;
    }
    await _ensureAutomationLaneForTarget(
      row: row,
      targetId: targetId,
      initialNormalized: initialNormalized,
    );
    await _revealRowAutomationTargetInRightPanel(row, targetId);
    _showSmallNotice('Automation lane ready.');
  }

  Future<void> _requestMasterMixAutomationClip(String paramId) async {
    if (_rowCount <= 0) {
      _showSmallNotice('Add a row before automating parameters.');
      return;
    }
    const row = 0;
    await _refreshAutomationTargetsForRow(
      row,
      setStateWhenDone: false,
      syncNativeWhenDone: false,
    );
    final targetId = _masterMixAutomationTargetId(paramId);
    final label = switch (paramId.trim().toLowerCase()) {
      'gain' => 'Master Gain',
      'pan' => 'Master Pan',
      _ => 'Master ${paramId.trim()}',
    };
    await _createAutomationClipForTarget(
      row: row,
      targetId: targetId,
      label: label,
    );
  }

  Future<void> _requestRowEffectAutomationClip(
    int row,
    int effectIndex,
    String effectName,
    String paramId,
    String paramName,
  ) async {
    if (row < 0 || row >= _rowCount) {
      _showSmallNotice('Select a valid row before automating parameters.');
      return;
    }
    await _refreshAutomationTargetsForRow(
      row,
      setStateWhenDone: false,
      syncNativeWhenDone: false,
    );
    final targetId = _findAutomationTargetIdForEffectParameter(
      effectIndex: effectIndex,
      paramId: paramId,
      master: false,
      row: row,
    );
    if (targetId == null || targetId.isEmpty) {
      _showSmallNotice('Could not resolve that automation target.');
      return;
    }
    final targetMeta =
        _rowAutomationTargets[row]?[targetId] ??
        _automationTargetMetaFromAnyRow(targetId);
    final resolvedLabel = (targetMeta?.label ?? '').trim();
    final label = resolvedLabel.isNotEmpty
        ? resolvedLabel
        : (effectName.trim().isEmpty
              ? paramName.trim()
              : 'Row ${row + 1} • ${effectName.trim()} • ${paramName.trim()}');
    await _createAutomationClipForTarget(
      row: row,
      targetId: targetId,
      label: label.trim().isEmpty ? targetId : label,
    );
  }

  Future<void> _showHostedPluginAutomationChooser({
    required bool master,
    int row = -1,
    required int effectIndex,
  }) async {
    final effectNames = master
        ? await JuceAudioEngine.getMasterEffects()
        : await JuceAudioEngine.getTrackEffectsForRow(row);
    if (!mounted) return;
    final effectName = effectIndex >= 0 && effectIndex < effectNames.length
        ? effectNames[effectIndex]
        : 'Plugin';
    final params = exposedEffectParameters(
      effectName,
      master
          ? await JuceAudioEngine.getMasterPluginParameters(effectIndex)
          : await JuceAudioEngine.getTrackPluginParameters(row, effectIndex),
    );
    if (!mounted) return;
    if (params.isEmpty) {
      _showSmallNotice('No automatable parameters found for this plugin.');
      return;
    }
    final selected = await showDialog<Map<String, dynamic>>(
      context: context,
      builder: (dialogContext) {
        final sorted =
            params
                .map((param) => Map<String, dynamic>.from(param))
                .toList(growable: true)
              ..sort(
                (a, b) =>
                    ((a['name'] ?? a['id']) as String).toLowerCase().compareTo(
                      ((b['name'] ?? b['id']) as String).toLowerCase(),
                    ),
              );
        return _buildDesktopPopupSurface(
          width: 460,
          outerPadding: const EdgeInsets.symmetric(
            horizontal: 34,
            vertical: 30,
          ),
          padding: const EdgeInsets.fromLTRB(18, 16, 18, 18),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                master
                    ? 'Automate Master FX Parameter'
                    : 'Automate Plugin Parameter',
                style: const TextStyle(
                  color: Color(0xFFF4F4F4),
                  fontFamily: 'Pretendard',
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                effectName,
                style: TextStyle(
                  color: Colors.white.withValues(alpha: 0.66),
                  fontFamily: 'Pretendard',
                  fontSize: 12.5,
                  fontWeight: FontWeight.w500,
                ),
              ),
              const SizedBox(height: 14),
              Flexible(
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxHeight: 360),
                  child: ListView.separated(
                    shrinkWrap: true,
                    itemCount: sorted.length,
                    separatorBuilder: (_, __) =>
                        Divider(color: Colors.white.withValues(alpha: 0.08)),
                    itemBuilder: (context, index) {
                      final param = sorted[index];
                      final name = (param['name'] ?? param['id'] ?? 'Parameter')
                          .toString();
                      final id = (param['id'] ?? '').toString();
                      return ListTile(
                        contentPadding: EdgeInsets.zero,
                        title: Text(
                          name,
                          style: const TextStyle(
                            color: Color(0xFFF4F4F4),
                            fontFamily: 'Pretendard',
                            fontSize: 14,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                        subtitle: id.trim().isEmpty
                            ? null
                            : Text(
                                id,
                                style: TextStyle(
                                  color: Colors.white.withValues(alpha: 0.52),
                                  fontSize: 11.6,
                                ),
                              ),
                        onTap: () => Navigator.of(dialogContext).pop(param),
                      );
                    },
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
    if (!mounted || selected == null) return;
    final paramId = (selected['id'] ?? '').toString().trim();
    final paramName = (selected['name'] ?? selected['id'] ?? 'Parameter')
        .toString()
        .trim();
    if (paramId.isEmpty) {
      _showSmallNotice('Could not resolve that plugin parameter.');
      return;
    }
    if (master) {
      await _requestMasterEffectAutomationClip(
        effectIndex,
        effectName,
        paramId,
        paramName,
      );
    } else {
      await _requestRowEffectAutomationClip(
        row,
        effectIndex,
        effectName,
        paramId,
        paramName,
      );
    }
  }

  void _handleJuceEngineEvent(Map<String, dynamic> event) {
    final eventType = (event['event'] ?? '').toString().trim();
    switch (eventType) {
      case 'macV2InputPreferenceChanged':
        if (Platform.isMacOS && _isBluetoothV2Session && mounted) {
          _setStateAndRefreshProjectSettings(() {
            _macInputDeviceName = null;
          });
          unawaited(_loadMacV2AudioDevices());
        }
        return;
      case 'pluginEditorSpacebar':
        if (_isEditorTextEntryActive()) return;
        unawaited(_handleMacSpacebarPlayPauseShortcut());
        return;
      case 'pluginEditorClosed':
        _scheduleProjectAutosave();
        return;
      case 'pluginEditorAutomationRequest':
        final scope = (event['scope'] ?? '').toString().trim();
        final paramId = (event['paramId'] ?? '').toString().trim();
        final paramName = (event['paramName'] ?? '').toString().trim();
        if (scope == 'track_fx') {
          final row = (event['row'] as num?)?.toInt() ?? -1;
          final effectIndex = (event['effectIndex'] as num?)?.toInt() ?? -1;
          if (row >= 0 && effectIndex >= 0) {
            if (paramId.isNotEmpty && paramName.isNotEmpty) {
              unawaited(() async {
                final effectNames = await JuceAudioEngine.getTrackEffectsForRow(
                  row,
                );
                if (!mounted) return;
                final effectName =
                    effectIndex >= 0 && effectIndex < effectNames.length
                    ? effectNames[effectIndex]
                    : 'Plugin';
                await _requestRowEffectAutomationClip(
                  row,
                  effectIndex,
                  effectName,
                  paramId,
                  paramName,
                );
              }());
            } else {
              unawaited(
                _showHostedPluginAutomationChooser(
                  master: false,
                  row: row,
                  effectIndex: effectIndex,
                ),
              );
            }
          }
        } else if (scope == 'master_fx') {
          final effectIndex = (event['effectIndex'] as num?)?.toInt() ?? -1;
          if (effectIndex >= 0) {
            if (paramId.isNotEmpty && paramName.isNotEmpty) {
              unawaited(() async {
                final effectNames = await JuceAudioEngine.getMasterEffects();
                if (!mounted) return;
                final effectName =
                    effectIndex >= 0 && effectIndex < effectNames.length
                    ? effectNames[effectIndex]
                    : 'Plugin';
                await _requestMasterEffectAutomationClip(
                  effectIndex,
                  effectName,
                  paramId,
                  paramName,
                );
              }());
            } else {
              unawaited(
                _showHostedPluginAutomationChooser(
                  effectIndex: effectIndex,
                  master: true,
                ),
              );
            }
          }
        } else if (scope == 'midi_clip') {
          final engineClipId = (event['clipId'] as num?)?.toInt() ?? -1;
          final clipIndex = _clipIndexForEngineId(engineClipId);
          final clip = clipIndex >= 0 && clipIndex < _audioTracks.length
              ? _audioTracks[clipIndex]
              : null;
          final instrumentName = (clip?.instrumentName ?? '').trim();
          final clipLabel = (clip?.label ?? '').trim();
          final displayName = instrumentName.isNotEmpty
              ? instrumentName
              : (clipLabel.isNotEmpty ? clipLabel : 'Synth plugin');
          if (paramId.isEmpty || paramName.isEmpty) {
            _showSmallNotice(
              'Touch a control in $displayName before choosing Automate.',
            );
          } else {
            final row = clip?.rowIndex ?? -1;
            if (clip == null || row < 0 || row >= _rowCount) {
              _showSmallNotice('Could not resolve the synth plugin track.');
              return;
            }
            final targetId = _midiPluginAutomationTargetId(
              clip.clipId,
              paramId,
            );
            final rowTargets = _rowAutomationTargets.putIfAbsent(
              row,
              () => _defaultAutomationTargetsForRow(row),
            );
            rowTargets[targetId] = _AutomationTargetMeta(
              targetId: targetId,
              label: '$displayName • $paramName',
              effectIndex: engineClipId,
              paramId: paramId,
              type: 'float',
              min: 0.0,
              max: 1.0,
              initialNormalized: 0.5,
            );
            unawaited(() async {
              await _ensureAutomationLaneForTarget(
                row: row,
                targetId: targetId,
              );
              if (mounted) _showSmallNotice('Automation lane ready.');
            }());
          }
        }
        return;
    }
  }

  Future<void> _requestMasterEffectAutomationClip(
    int effectIndex,
    String effectName,
    String paramId,
    String paramName,
  ) async {
    if (_rowCount <= 0) {
      _showSmallNotice('Add a row before automating parameters.');
      return;
    }
    const row = 0;
    await _refreshAutomationTargetsForRow(
      row,
      setStateWhenDone: false,
      syncNativeWhenDone: false,
    );
    final targetId = _findAutomationTargetIdForEffectParameter(
      effectIndex: effectIndex,
      paramId: paramId,
      master: true,
    );
    if (targetId == null || targetId.isEmpty) {
      _showSmallNotice('Could not resolve that automation target.');
      return;
    }
    final targetMeta = _automationTargetMetaFromAnyRow(targetId);
    final resolvedLabel = (targetMeta?.label ?? '').trim();
    final label = resolvedLabel.isNotEmpty
        ? resolvedLabel
        : (effectName.trim().isEmpty
              ? paramName.trim()
              : 'Master • ${effectName.trim()} • ${paramName.trim()}');
    await _createAutomationClipForTarget(
      row: row,
      targetId: targetId,
      label: label.trim().isEmpty ? targetId : label,
    );
  }

  Future<void> _revealMasterAutomationTarget(String targetId) async {
    final parsed = _parseAutomationTargetId(targetId);
    final targetMeta =
        _automationTargetMetaFromAnyRow(targetId) ??
        _fallbackAutomationTargetMeta(targetId);
    if (_usesTabletDesktopDawShell(context)) {
      _showMasterInRightPanel();
      await WidgetsBinding.instance.endOfFrame;
      if (!mounted) return;

      if (parsed.isMixParameter) {
        switch (parsed.mixParamId.trim().toLowerCase()) {
          case 'gain':
            _triggerMasterHalos(<String>['master:gain', 'master:param:gain']);
            break;
          case 'pan':
            _triggerMasterHalos(<String>['master:pan', 'master:param:pan']);
            break;
        }
        return;
      }

      if (targetMeta.isOrphan) {
        _showSmallNotice(
          'This automation target is orphaned. Undo the plugin removal or re-add the plugin to relink it.',
        );
        return;
      }

      await WidgetsBinding.instance.endOfFrame;
      if (!mounted) return;
      final revealer = _masterParameterRevealer;
      if (revealer != null &&
          targetMeta.effectIndex >= 0 &&
          targetMeta.paramId.trim().isNotEmpty) {
        await revealer(targetMeta.effectIndex, targetMeta.paramId);
      }
      return;
    }

    setState(() {
      _setActiveTopPopup(_TopPopupType.master);
    });
    await Future<void>.delayed(const Duration(milliseconds: 40));
    if (!mounted) return;

    if (parsed.isMixParameter) {
      _masterRackContentKey.currentState?.showVolumeTab();
      switch (parsed.mixParamId.trim().toLowerCase()) {
        case 'gain':
          _triggerMasterHalos(<String>['master:gain', 'master:param:gain']);
          break;
        case 'pan':
          _triggerMasterHalos(<String>['master:pan', 'master:param:pan']);
          break;
      }
      return;
    }

    _masterRackContentKey.currentState?.showEffectsTab();
    if (targetMeta.isOrphan) {
      _showSmallNotice(
        'This automation target is orphaned. Undo the plugin removal or re-add the plugin to relink it.',
      );
      return;
    }
    await Future<void>.delayed(const Duration(milliseconds: 40));
    if (!mounted) return;
    final revealer = _masterParameterRevealer;
    if (revealer != null &&
        targetMeta.effectIndex >= 0 &&
        targetMeta.paramId.trim().isNotEmpty) {
      await revealer(targetMeta.effectIndex, targetMeta.paramId);
    }
  }

  Future<void> _revealRowAutomationTargetInRightPanel(
    int row,
    String targetId,
  ) async {
    if (row < 0 || row >= _rowCount) return;
    final targetMeta =
        _rowAutomationTargets[row]?[targetId] ??
        _automationTargetMetaFromAnyRow(targetId) ??
        _fallbackAutomationTargetMeta(targetId);
    final parsed = _parseAutomationTargetId(targetId);
    final safeRow = row.clamp(0, math.max(0, _rowCount - 1)).toInt();

    if (targetMeta.isOrphan) {
      _showSmallNotice(
        'This automation target is orphaned. Undo the plugin removal or re-add the plugin to relink it.',
      );
      return;
    }

    if (targetMeta.isVolume || parsed.isMixParameter) {
      setState(() {
        _selectedRow = safeRow;
        _tabletRowDetailTab = 0;
        _tabletRightPanelTab = 'mixer';
        _tabletRightPanelCollapsed = false;
        _tabletSelectedRowFxRow = null;
        _tabletSelectedRowFxIndex = null;
      });
      return;
    }

    if (!parsed.isEffectParameter || targetMeta.effectIndex < 0) {
      _showSmallNotice('Could not resolve that automation target.');
      return;
    }

    setState(() {
      _selectedRow = safeRow;
      _tabletRowDetailTab = 1;
      _tabletRightPanelTab = 'fx';
      _tabletRightPanelCollapsed = false;
      _tabletSelectedRowFxRow = safeRow;
      _tabletSelectedRowFxIndex = targetMeta.effectIndex;
    });

    await WidgetsBinding.instance.endOfFrame;
    await WidgetsBinding.instance.endOfFrame;
    if (!mounted ||
        _tabletSelectedRowFxRow != safeRow ||
        _tabletSelectedRowFxIndex != targetMeta.effectIndex) {
      return;
    }

    final revealer = _tabletSelectedRowFxParameterRevealer;
    if (revealer != null && targetMeta.paramId.trim().isNotEmpty) {
      await revealer(targetMeta.effectIndex, targetMeta.paramId);
      return;
    }

    _refreshRowFx(safeRow);
  }

  List<AutomationPoint> _sanitizeAutomationPoints(
    int row,
    List<AutomationPoint> points,
  ) {
    final sanitized = sanitizeAutomationPointsPreservingFutureTimes(points);

    if (sanitized.isEmpty) {
      return <AutomationPoint>[AutomationPoint(x: 0.0, volume: 1.0)];
    }

    return sanitized;
  }

  Future<void> _setRowAutomationWithUndo(
    int row,
    List<AutomationPoint> newPoints, {
    int? stableRowId,
  }) async {
    if (row < 0 || row >= _rowVolumeAutomation.length) return;
    final oldPoints = _rowVolumeAutomation[row]
        .map((p) => AutomationPoint(x: p.x, volume: p.volume))
        .toList(growable: false);
    final safePoints = _sanitizeAutomationPoints(row, newPoints);
    await _undoManager.execute(
      SetAutomationPointsAction(
        row: row,
        stableRowId: stableRowId,
        resolveRowIndex: stableRowId == null ? null : _rowIndexForId,
        oldPoints: oldPoints,
        newPoints: safePoints,
        applyToState: (r, points) {
          setState(() {
            _rowVolumeAutomation[r] = points
                .map((p) => AutomationPoint(x: p.x, volume: p.volume))
                .toList();
          });
        },
        onApplied: (r, _) async {
          await _syncNativeAutomationForRow(r);
          _scheduleProjectAutosave();
        },
      ),
    );
  }

  String? _resolveAutomationTargetIdFromAction(
    int row,
    Map<String, dynamic> data, {
    bool allowVolumeFallback = true,
  }) {
    final target = _actionTarget(data);
    final targets =
        _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
    if (targets.isEmpty) {
      return allowVolumeFallback ? 'volume' : null;
    }

    final scope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final restrictToMaster =
        scope == 'master' ||
        scope == 'master_bus' ||
        scope == 'master-bus' ||
        scope == 'masterbus';
    final restrictToRow =
        scope == 'row' ||
        scope == 'track' ||
        scope == 'channel' ||
        scope == 'group' ||
        scope == 'bus';

    bool scopeAllowsTarget(_AutomationTargetMeta meta) {
      if (meta.isOrphan) return false;
      final isMasterTarget = _parseAutomationTargetId(meta.targetId).isMaster;
      if (restrictToMaster) return isMasterTarget;
      if (restrictToRow) return !isMasterTarget;
      return true;
    }

    String? pickTargetId(dynamic raw) {
      final id = (raw ?? '').toString().trim();
      if (id.isEmpty) return null;
      if (targets.containsKey(id)) {
        final exactMeta = targets[id]!;
        if (scopeAllowsTarget(exactMeta)) return id;
        return null;
      }
      final parsed = _parseAutomationTargetId(id);
      if (parsed.isVolume || id.toLowerCase() == 'volume') {
        if (restrictToMaster) return null;
        final volumeMeta = targets['volume'];
        return volumeMeta != null && scopeAllowsTarget(volumeMeta)
            ? 'volume'
            : null;
      }
      final parsedParamLower = parsed.paramId.trim().toLowerCase();
      if (parsedParamLower.isEmpty) return null;
      final pluginTargets = targets.values.where(
        (meta) => !meta.isVolume && scopeAllowsTarget(meta),
      );
      if (parsed.effectKey.isNotEmpty) {
        final byEffectKey = pluginTargets
            .where((meta) {
              final candidateParsed = _parseAutomationTargetId(meta.targetId);
              return candidateParsed.effectKey == parsed.effectKey &&
                  meta.paramId.trim().toLowerCase() == parsedParamLower;
            })
            .toList(growable: false);
        if (byEffectKey.length == 1) {
          return byEffectKey.first.targetId;
        }
      }
      if (parsed.legacyEffectIndex >= 0) {
        final byLegacyIndex = pluginTargets
            .where(
              (meta) =>
                  meta.effectIndex == parsed.legacyEffectIndex &&
                  meta.paramId.trim().toLowerCase() == parsedParamLower,
            )
            .toList(growable: false);
        if (byLegacyIndex.length == 1) {
          return byLegacyIndex.first.targetId;
        }
      }
      return null;
    }

    bool matchesToken(String haystack, String needle) {
      final h = haystack.trim().toLowerCase();
      final n = needle.trim().toLowerCase();
      if (h.isEmpty || n.isEmpty) return false;
      return h.contains(n) || n.contains(h);
    }

    final explicit =
        pickTargetId(data['automation_target_id']) ??
        pickTargetId(target['automation_target_id']) ??
        pickTargetId(data['target_id']) ??
        pickTargetId(target['target_id']) ??
        pickTargetId(data['lane_id']) ??
        pickTargetId(target['lane_id']);
    if (explicit != null) return explicit;

    final effectIndex = _toActionInt(
      data['effect_index'] ??
          target['effect_index'] ??
          data['effect'] ??
          target['effect'],
    );
    final paramId =
        (data['param_id'] ??
                target['param_id'] ??
                data['parameter_id'] ??
                target['parameter_id'] ??
                data['param'] ??
                target['param'])
            .toString()
            .trim();
    final paramName =
        (data['param_name'] ??
                target['param_name'] ??
                data['parameter'] ??
                target['parameter'] ??
                data['name'] ??
                target['name'])
            .toString()
            .trim()
            .toLowerCase();
    final effectName =
        (data['effect_name'] ??
                target['effect_name'] ??
                data['plugin_name'] ??
                target['plugin_name'] ??
                data['plugin'] ??
                target['plugin'] ??
                data['effect'] ??
                target['effect'])
            .toString()
            .trim()
            .toLowerCase();

    if (!restrictToMaster && effectIndex != null && paramId.isNotEmpty) {
      final byDirectId = _pluginAutomationTargetId(effectIndex, paramId);
      if (targets.containsKey(byDirectId) &&
          scopeAllowsTarget(targets[byDirectId]!)) {
        return byDirectId;
      }
    }

    int? resolvedEffectIndex = effectIndex;
    if (resolvedEffectIndex == null && effectName.isNotEmpty) {
      final matchingEffectIndices = targets.values
          .where((meta) {
            if (meta.isVolume || !scopeAllowsTarget(meta)) return false;
            return matchesToken(meta.label, effectName) ||
                matchesToken(meta.paramId, effectName);
          })
          .map((meta) => meta.effectIndex)
          .where((i) => i >= 0)
          .toSet()
          .toList(growable: false);
      if (matchingEffectIndices.length == 1) {
        resolvedEffectIndex = matchingEffectIndices.first;
      }
    }

    if (resolvedEffectIndex != null) {
      final scoped = targets.values
          .where(
            (meta) =>
                !meta.isVolume &&
                scopeAllowsTarget(meta) &&
                meta.effectIndex == resolvedEffectIndex,
          )
          .toList(growable: false);
      if (scoped.isNotEmpty) {
        if (paramId.isNotEmpty) {
          final lowered = paramId.toLowerCase();
          for (final meta in scoped) {
            if (meta.paramId.toLowerCase() == lowered) return meta.targetId;
          }
        }
        if (paramName.isNotEmpty) {
          for (final meta in scoped) {
            final label = meta.label.toLowerCase();
            final pid = meta.paramId.toLowerCase();
            if (matchesToken(label, paramName) ||
                matchesToken(pid, paramName)) {
              return meta.targetId;
            }
          }
        }
        if (scoped.length == 1) return scoped.first.targetId;
      }
    }

    if (paramId.isNotEmpty) {
      final lowered = paramId.toLowerCase();
      for (final meta in targets.values) {
        if (meta.isVolume || !scopeAllowsTarget(meta)) continue;
        if (meta.paramId.toLowerCase() == lowered) return meta.targetId;
      }
    }

    if (paramName.isNotEmpty) {
      for (final meta in targets.values) {
        if (meta.isVolume || !scopeAllowsTarget(meta)) continue;
        final label = meta.label.toLowerCase();
        final pid = meta.paramId.toLowerCase();
        if (matchesToken(label, paramName) || matchesToken(pid, paramName)) {
          return meta.targetId;
        }
      }
    }

    final pluginIntent =
        effectName.isNotEmpty ||
        resolvedEffectIndex != null ||
        paramId.isNotEmpty ||
        paramName.isNotEmpty;
    if (pluginIntent && !allowVolumeFallback) {
      return null;
    }

    if (restrictToMaster) {
      return null;
    }

    return 'volume';
  }

  bool _isPluginAutomationIntent(Map<String, dynamic> data) {
    final target = _actionTarget(data);

    bool hasField(String key) {
      final value = data[key] ?? target[key];
      if (value == null) return false;
      if (value is String) return value.trim().isNotEmpty;
      if (value is num) return true;
      return true;
    }

    if (hasField('automation_target_id') ||
        hasField('target_id') ||
        hasField('lane_id') ||
        hasField('effect_index') ||
        hasField('effect_name') ||
        hasField('plugin_name') ||
        hasField('plugin') ||
        hasField('param_id') ||
        hasField('parameter_id') ||
        hasField('param_name') ||
        hasField('parameter')) {
      final explicitTargetId =
          (data['automation_target_id'] ??
                  target['automation_target_id'] ??
                  data['target_id'] ??
                  target['target_id'])
              .toString()
              .trim()
              .toLowerCase();
      if (explicitTargetId == 'volume') return false;
      return true;
    }

    final template =
        (data['template'] ??
                target['template'] ??
                data['pattern'] ??
                target['pattern'] ??
                '')
            .toString()
            .trim()
            .toLowerCase();
    if (template == 'filter_sweep' ||
        template == 'lowpass_sweep' ||
        template == 'highpass_sweep' ||
        template == 'reverb_tail') {
      return true;
    }

    return false;
  }

  double _normalizedActionValueForTarget(
    dynamic rawValue,
    _AutomationTargetMeta target, {
    String valueMode = '',
    double fallback = 0.5,
  }) {
    final raw = _toActionDouble(rawValue);
    if (raw == null) return fallback.clamp(0.0, 1.0).toDouble();
    if (target.isVolume) {
      return raw.clamp(0.0, 1.0).toDouble();
    }

    final mode = valueMode.trim().toLowerCase();
    if (mode == 'real' || mode == 'absolute' || mode == 'native') {
      return _normalizeAutomationValue(
        raw,
        min: target.min,
        max: target.max,
        fallback: fallback,
      );
    }
    if (mode == 'normalized' || mode == '0to1') {
      return raw.clamp(0.0, 1.0).toDouble();
    }

    if (raw < 0.0 || raw > 1.0) {
      return _normalizeAutomationValue(
        raw,
        min: target.min,
        max: target.max,
        fallback: fallback,
      );
    }
    return raw.clamp(0.0, 1.0).toDouble();
  }

  String _normalizeAutomationEditOperation(String raw) {
    // Legacy mapping reference: 'set' || 'replace' => 'set_points'
    switch (raw.trim().toLowerCase()) {
      case 'set':
      case 'replace':
        return 'set_points';
      case 'ramp':
      case 'curve':
      case 'add_curve':
        return 'add_ramp';
      case 'create':
      case 'add':
      case 'add_clip':
      case 'new_clip':
      case 'insert_clip':
      case 'create_clip':
        return 'create_clip';
      case 'duplicate':
      case 'clone':
      case 'clone_clip':
      case 'duplicate_clip':
        return 'duplicate_clip';
      case 'move':
      case 'move_clip':
        return 'move_clip';
      case 'remove_clip':
      case 'delete_clip':
        return 'delete_clip';
      case 'clear_clip':
      case 'remove_all_clips':
      case 'clear_clips':
        return 'clear_clips';
      case 'mute':
      case 'mute_clip':
        return 'mute_clip';
      case 'unmute':
      case 'unmute_clip':
        return 'unmute_clip';
      case 'toggle_mute':
      case 'toggle_clip_mute':
        return 'toggle_clip_mute';
      case 'replace_clip_points':
      case 'set_clip_points':
        return 'set_clip_points';
      case 'make_unique_clip':
      case 'make_unique':
        return 'make_unique_clip';
      case 'template':
      case 'apply_template':
      case 'generate_template':
        return 'apply_template';
      default:
        return raw.trim().toLowerCase();
    }
  }

  bool _automationClipListsEqual(
    List<AutomationClipSnapshot> a,
    List<AutomationClipSnapshot> b,
  ) {
    if (identical(a, b)) return true;
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      final x = a[i];
      final y = b[i];
      if (x.id != y.id ||
          x.targetId != y.targetId ||
          x.label != y.label ||
          x.patternId != y.patternId ||
          x.row != y.row ||
          x.lane != y.lane ||
          x.muted != y.muted ||
          (x.startMs - y.startMs).abs() > 1e-6 ||
          (x.lengthMs - y.lengthMs).abs() > 1e-6) {
        return false;
      }
      if (x.points.length != y.points.length) return false;
      for (int p = 0; p < x.points.length; p++) {
        final xp = x.points[p];
        final yp = y.points[p];
        if ((xp.x - yp.x).abs() > 1e-6 ||
            (xp.volume - yp.volume).abs() > 1e-6) {
          return false;
        }
      }
    }
    return true;
  }

  double _defaultAutomationClipLengthMs() {
    final msPerBeat = 60000.0 / _tempo.clamp(1.0, 400.0);
    final oneBarMs = msPerBeat * 4.0;
    final maxMs = _maxAutomationTimelineMs();
    return oneBarMs.clamp(200.0, math.max(200.0, maxMs)).toDouble();
  }

  String _newAutomationClipId(int row, String targetId) {
    return 'ac_${row}_${targetId}_${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}';
  }

  int? _resolveAutomationClipIndexFromAction(
    int row,
    String targetId,
    Map<String, dynamic> data,
  ) {
    final clips = _clipsForAutomationTarget(row, targetId);
    if (clips.isEmpty) return null;
    final target = _actionTarget(data);
    final explicitIndex = _toActionInt(
      data['clip_index'] ??
          target['clip_index'] ??
          data['automation_clip_index'] ??
          target['automation_clip_index'],
    );
    if (explicitIndex != null &&
        explicitIndex >= 0 &&
        explicitIndex < clips.length) {
      return explicitIndex;
    }

    final explicitId =
        (data['clip_id'] ??
                target['clip_id'] ??
                data['automation_clip_id'] ??
                target['automation_clip_id'] ??
                '')
            .toString()
            .trim();
    if (explicitId.isNotEmpty) {
      final idx = clips.indexWhere((clip) => clip.id == explicitId);
      if (idx >= 0) return idx;
    }

    final explicitPatternId =
        (data['pattern_id'] ??
                target['pattern_id'] ??
                data['automation_pattern_id'] ??
                target['automation_pattern_id'] ??
                '')
            .toString()
            .trim();
    if (explicitPatternId.isNotEmpty) {
      final idx = clips.indexWhere(
        (clip) => clip.patternId.trim() == explicitPatternId,
      );
      if (idx >= 0) return idx;
    }

    final atMs = _toActionDouble(
      data['at_ms'] ??
          target['at_ms'] ??
          data['time_ms'] ??
          target['time_ms'] ??
          data['start_ms'] ??
          target['start_ms'],
    );
    if (atMs != null && atMs.isFinite) {
      for (int i = 0; i < clips.length; i++) {
        final clip = clips[i];
        final endMs = clip.startMs + clip.lengthMs;
        if (atMs >= clip.startMs && atMs <= endMs) {
          return i;
        }
      }
      int nearest = 0;
      double nearestDist = (clips.first.startMs - atMs).abs();
      for (int i = 1; i < clips.length; i++) {
        final dist = (clips[i].startMs - atMs).abs();
        if (dist < nearestDist) {
          nearest = i;
          nearestDist = dist;
        }
      }
      return nearest;
    }

    return clips.length - 1;
  }

  List<AutomationPoint> _automationTemplatePointsRelative(
    String templateRaw,
    double lengthMs, {
    required double startValue,
    required double endValue,
    String direction = 'up',
  }) {
    final safeLength = lengthMs.clamp(80.0, double.infinity).toDouble();
    final start = startValue.clamp(0.0, 1.0).toDouble();
    final end = endValue.clamp(0.0, 1.0).toDouble();
    final template = templateRaw.trim().toLowerCase();
    final dirDown = direction.trim().toLowerCase() == 'down';

    if (template == 'sidechain' ||
        template == 'sidechain_pump' ||
        template == 'pump') {
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: 1.0),
        AutomationPoint(x: safeLength * 0.08, volume: 0.14),
        AutomationPoint(x: safeLength * 0.36, volume: 0.78),
        AutomationPoint(x: safeLength, volume: 1.0),
      ];
    }

    if (template == 'reverb_tail' ||
        template == 'tail' ||
        template == 'decay') {
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: 0.05),
        AutomationPoint(x: safeLength * 0.12, volume: 1.0),
        AutomationPoint(x: safeLength * 0.45, volume: 0.56),
        AutomationPoint(x: safeLength, volume: 0.12),
      ];
    }

    if (template == 'filter_sweep' ||
        template == 'sweep' ||
        template == 'lowpass_sweep' ||
        template == 'highpass_sweep') {
      final from = dirDown ? 1.0 : 0.0;
      final to = dirDown ? 0.0 : 1.0;
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: from),
        AutomationPoint(x: safeLength, volume: to),
      ];
    }

    if (template == 'auto_pan' ||
        template == 'autopan' ||
        template == 'stereo_motion' ||
        template == 'stereo_direction' ||
        template == 'pan_motion' ||
        template == 'left_right_motion') {
      final startsRight = direction.trim().toLowerCase() == 'right';
      final nearStartSide = startsRight ? 0.84 : 0.16;
      final nearOppositeSide = startsRight ? 0.16 : 0.84;
      final settleSide = startsRight ? 0.74 : 0.26;
      return <AutomationPoint>[
        AutomationPoint(x: 0.0, volume: 0.5),
        AutomationPoint(x: safeLength * 0.16, volume: nearStartSide),
        AutomationPoint(x: safeLength * 0.34, volume: 0.5),
        AutomationPoint(x: safeLength * 0.56, volume: nearOppositeSide),
        AutomationPoint(x: safeLength * 0.78, volume: settleSide),
        AutomationPoint(x: safeLength, volume: 0.5),
      ];
    }

    return <AutomationPoint>[
      AutomationPoint(x: 0.0, volume: start),
      AutomationPoint(x: safeLength, volume: end),
    ];
  }

  List<AutomationPoint> _replaceAutomationRangeWithRelativePoints({
    required int row,
    required String targetId,
    required List<AutomationPoint> existing,
    required double startMs,
    required double lengthMs,
    required List<AutomationPoint> relativePoints,
    bool replaceExisting = true,
  }) {
    final maxMs = _maxAutomationTimelineMs();
    final safeStart = startMs.clamp(0.0, maxMs).toDouble();
    final safeLength = lengthMs.clamp(1.0, math.max(1.0, maxMs - safeStart));
    final safeEnd = (safeStart + safeLength).clamp(safeStart, maxMs).toDouble();
    final sortedExisting = _sanitizeAutomationPointsForTarget(
      row,
      targetId,
      existing,
    );
    final next = <AutomationPoint>[];

    if (replaceExisting) {
      for (final point in sortedExisting) {
        if (point.x > safeStart + 1e-6 && point.x < safeEnd - 1e-6) {
          continue;
        }
        next.add(point.copy());
      }
    } else {
      next.addAll(sortedExisting.map((point) => point.copy()));
    }

    final sortedRelative = relativePoints.map((point) => point.copy()).toList()
      ..sort((a, b) => a.x.compareTo(b.x));
    for (final point in sortedRelative) {
      next.add(
        AutomationPoint(
          x: (safeStart + point.x).clamp(safeStart, safeEnd).toDouble(),
          volume: point.volume.clamp(0.0, 1.0).toDouble(),
        ),
      );
    }

    return _sanitizeAutomationPointsForTarget(row, targetId, next);
  }

  Future<void> _applyAutomationEditAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final rawOperation = (data['operation'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    var operation = _normalizeAutomationEditOperation(rawOperation);
    if (operation == 'clear') {
      final clearScope =
          (data['clear_scope'] ??
                  target['clear_scope'] ??
                  data['scope'] ??
                  target['scope'] ??
                  '')
              .toString()
              .trim()
              .toLowerCase();
      if (clearScope.contains('clip')) {
        operation = 'clear';
      }
    }
    final clipIndex = _resolveClipIndexFromActionTarget(data);
    final row = _resolveRowIndexFromActionTarget(
      data,
      fallbackClipIndex: clipIndex,
    );
    if (row == null) {
      _insertAssistantChatText(
        "I couldn't resolve which track automation to edit.",
      );
      return;
    }

    final pluginIntent = _isPluginAutomationIntent(data);
    final requestedScope = (data['scope'] ?? target['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final wantsMasterScope =
        requestedScope == 'master' ||
        requestedScope == 'master_bus' ||
        requestedScope == 'master-bus' ||
        requestedScope == 'masterbus';
    final targetId = _resolveAutomationTargetIdFromAction(
      row,
      data,
      allowVolumeFallback: !pluginIntent && !wantsMasterScope,
    );
    if (targetId == null || targetId.isEmpty) {
      final hasPluginTargets = (_rowAutomationTargets[row] ?? const {}).values
          .any((meta) => !meta.isVolume && !meta.isOrphan);
      if (pluginIntent) {
        if (!hasPluginTargets) {
          _insertAssistantChatText(
            "That track has no automatable plugin parameters yet. Add an effect first.",
          );
        } else {
          _insertAssistantChatText(
            "I couldn't resolve which plugin parameter to automate. Specify plugin + parameter (for example: effect_name + param_name).",
          );
        }
      } else if (wantsMasterScope) {
        _insertAssistantChatText(
          "I couldn't resolve which master parameter to automate. Specify master gain, master pan, or the master effect + parameter.",
        );
      } else {
        _insertAssistantChatText(
          "I couldn't resolve which automation target to edit.",
        );
      }
      return;
    }
    final targetMeta =
        _rowAutomationTargets[row]?[targetId] ??
        _fallbackAutomationTargetMeta(targetId);
    final valueMode =
        (data['value_mode'] ??
                target['value_mode'] ??
                data['value_domain'] ??
                target['value_domain'] ??
                '')
            .toString();
    final normalizedTemplate =
        (data['template'] ??
                target['template'] ??
                data['pattern'] ??
                target['pattern'] ??
                '')
            .toString()
            .trim()
            .toLowerCase();
    final defaultSpanMs = (60000.0 / _tempo.clamp(1.0, 400.0) * 4.0)
        .clamp(120.0, _automationUpperBound(120.0))
        .toDouble();

    List<AutomationPoint> clipPointsFromAction({
      required double lengthMs,
      List<AutomationPoint>? fallback,
    }) {
      final rawPoints = (data['points'] as List?) ?? const [];
      final points = <AutomationPoint>[];
      for (final raw in rawPoints) {
        final point = _toActionMap(raw);
        final x = _toActionDouble(
          point['x_ms'] ?? point['x'] ?? point['time_ms'],
        );
        final rawValue =
            point['value'] ??
            point['volume'] ??
            point['normalized_value'] ??
            point['normalized'] ??
            point['real_value'] ??
            point['native_value'];
        if (x == null || rawValue == null) continue;
        points.add(
          AutomationPoint(
            x: x,
            volume: _normalizedActionValueForTarget(
              rawValue,
              targetMeta,
              valueMode: (point['value_mode'] ?? valueMode).toString(),
              fallback: targetId == 'volume' ? 0.75 : 0.5,
            ),
          ),
        );
      }
      if (points.isNotEmpty) return points;
      if (fallback != null && fallback.isNotEmpty) {
        return fallback.map((point) => point.copy()).toList(growable: false);
      }
      final startValue = _normalizedActionValueForTarget(
        data['start_value'] ?? data['from_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 0.75 : 0.5,
      );
      final endValue = _normalizedActionValueForTarget(
        data['end_value'] ?? data['to_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: startValue,
      );
      return _automationTemplatePointsRelative(
        normalizedTemplate.isEmpty ? 'ramp' : normalizedTemplate,
        lengthMs,
        startValue: startValue,
        endValue: endValue,
        direction: (data['direction'] ?? target['direction'] ?? 'up')
            .toString(),
      );
    }

    if (operation == 'create_clip') {
      final startMs =
          (_toActionDouble(
                    data['start_ms'] ?? target['start_ms'] ?? data['at_ms'],
                  ) ??
                  _globalAudioClock.inMilliseconds.toDouble())
              .clamp(0.0, _maxAutomationTimelineMs())
              .toDouble();
      final lengthMs =
          (_toActionDouble(
                    data['length_ms'] ??
                        target['length_ms'] ??
                        data['duration_ms'],
                  ) ??
                  _defaultAutomationClipLengthMs())
              .clamp(80.0, _automationUpperBound(80.0))
              .toDouble();
      final clips = _copyAutomationClipList(
        _clipsForAutomationTarget(row, targetId),
      ).toList(growable: true);
      final requestedPatternId =
          (data['pattern_id'] ?? target['pattern_id'] ?? '').toString().trim();
      clips.add(
        AutomationClipSnapshot(
          id: _newAutomationClipId(row, targetId),
          targetId: targetId,
          label: _automationTargetLabelFor(row, targetId),
          patternId: requestedPatternId,
          row: _preferredAutomationClipRowForTarget(row, targetId),
          startMs: startMs,
          lengthMs: lengthMs,
          muted: false,
          points: clipPointsFromAction(lengthMs: lengthMs),
        ),
      );
      await _setAutomationClipsForTargetWithUndo(row, targetId, clips);
      _showSmallNotice('Created automation clip.');
      return;
    }

    if (operation == 'clear_clips') {
      await _setAutomationClipsForTargetWithUndo(
        row,
        targetId,
        const <AutomationClipSnapshot>[],
      );
      _showSmallNotice('Cleared automation clips.');
      return;
    }

    const clipOperations = <String>{
      'duplicate_clip',
      'move_clip',
      'delete_clip',
      'mute_clip',
      'unmute_clip',
      'toggle_clip_mute',
      'make_unique_clip',
      'set_clip_points',
    };
    if (clipOperations.contains(operation)) {
      final clips = _copyAutomationClipList(
        _clipsForAutomationTarget(row, targetId),
      ).toList(growable: true);
      final index = _resolveAutomationClipIndexFromAction(row, targetId, data);
      if (index == null || index < 0 || index >= clips.length) {
        _insertAssistantChatText(
          "I couldn't resolve which automation clip to edit.",
        );
        return;
      }

      final source = clips[index];
      switch (operation) {
        case 'delete_clip':
          clips.removeAt(index);
          break;
        case 'duplicate_clip':
          final copyMode =
              (data['copy_mode'] ?? target['copy_mode'] ?? 'shared')
                  .toString()
                  .trim()
                  .toLowerCase();
          var patternId = source.patternId;
          if (copyMode == 'deep') {
            patternId = '';
          } else if (patternId.isEmpty) {
            patternId = _newAutomationPatternId(row, targetId);
            clips[index] = source.copyWith(patternId: patternId);
          }
          final startMs =
              _toActionDouble(
                data['start_ms'] ??
                    target['start_ms'] ??
                    data['paste_start_ms'],
              ) ??
              source.startMs + source.lengthMs;
          clips.add(
            source.copyWith(
              id: _newAutomationClipId(row, targetId),
              startMs: startMs,
              patternId: patternId,
            ),
          );
          break;
        case 'move_clip':
          final explicitStart = _toActionDouble(
            data['start_ms'] ?? target['start_ms'] ?? data['paste_start_ms'],
          );
          final deltaMs =
              _toActionDouble(data['delta_ms'] ?? target['delta_ms']) ?? 0.0;
          final lengthMs = _toActionDouble(
            data['length_ms'] ?? target['length_ms'] ?? data['duration_ms'],
          );
          clips[index] = source.copyWith(
            startMs: math.max(0.0, explicitStart ?? source.startMs + deltaMs),
            lengthMs: lengthMs == null ? null : math.max(40.0, lengthMs),
          );
          break;
        case 'mute_clip':
          clips[index] = source.copyWith(muted: true);
          break;
        case 'unmute_clip':
          clips[index] = source.copyWith(muted: false);
          break;
        case 'toggle_clip_mute':
          clips[index] = source.copyWith(muted: !source.muted);
          break;
        case 'make_unique_clip':
          clips[index] = source.copyWith(patternId: '');
          break;
        case 'set_clip_points':
          final nextPoints = clipPointsFromAction(
            lengthMs: source.lengthMs,
            fallback: source.points,
          );
          if (source.patternId.isEmpty) {
            clips[index] = source.copyWith(points: nextPoints);
          } else {
            for (int i = 0; i < clips.length; i++) {
              if (clips[i].patternId == source.patternId) {
                clips[i] = clips[i].copyWith(points: nextPoints);
              }
            }
          }
          break;
        default:
          break;
      }

      await _setAutomationClipsForTargetWithUndo(row, targetId, clips);
      _showSmallNotice('Updated automation clip.');
      return;
    }

    final isKickSyncedSidechainTemplate =
        operation == 'apply_template' &&
        (normalizedTemplate == 'sidechain_from_kick' ||
            normalizedTemplate == 'kick_sidechain' ||
            normalizedTemplate == 'duck_to_kick' ||
            normalizedTemplate == 'kick_duck');
    if (isKickSyncedSidechainTemplate) {
      final sourceClipIndex = _resolveKickSourceClipIndexFromAction(
        data,
        targetRow: row,
      );
      if (sourceClipIndex == null ||
          sourceClipIndex < 0 ||
          sourceClipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
          "I couldn't find a kick source clip for sidechain automation.",
        );
        return;
      }
      final sourceClip = _audioTracks[sourceClipIndex];
      if (sourceClip.isMidi) {
        _insertAssistantChatText(
          'Kick-synced sidechain needs an audio source clip.',
        );
        return;
      }

      final lengthMs =
          (_toActionDouble(
                    data['length_ms'] ??
                        target['length_ms'] ??
                        data['duration_ms'] ??
                        target['duration_ms'],
                  ) ??
                  (60000.0 / _tempo.clamp(1.0, 400.0)))
              .clamp(80.0, _automationUpperBound(80.0))
              .toDouble();
      final minSpacingMs =
          (_toActionDouble(
                    data['min_spacing_ms'] ??
                        target['min_spacing_ms'] ??
                        data['event_spacing_ms'] ??
                        target['event_spacing_ms'],
                  ) ??
                  math.max(80.0, lengthMs * 0.42))
              .clamp(40.0, 4000.0)
              .toDouble();
      final thresholdStd =
          (_toActionDouble(
                    data['transient_threshold_std'] ??
                        target['transient_threshold_std'] ??
                        data['transient_sensitivity'] ??
                        target['transient_sensitivity'] ??
                        data['sensitivity'] ??
                        target['sensitivity'],
                  ) ??
                  1.25)
              .clamp(0.25, 4.0)
              .toDouble();
      final lowpassHz =
          (_toActionDouble(
                    data['kick_lowpass_hz'] ??
                        target['kick_lowpass_hz'] ??
                        data['lowpass_hz'] ??
                        target['lowpass_hz'],
                  ) ??
                  220.0)
              .clamp(80.0, 1200.0)
              .toDouble();
      final maxEvents =
          (_toActionInt(data['max_events'] ?? target['max_events']) ?? 256)
              .clamp(1, 2048);
      final offsetMs =
          (_toActionDouble(data['offset_ms'] ?? target['offset_ms']) ?? 0.0)
              .toDouble();
      final fromMs = _toActionDouble(data['from_ms'] ?? target['from_ms']);
      final toMs = _toActionDouble(data['to_ms'] ?? target['to_ms']);

      var eventMs = await _detectKickTimelineOnsetsMsForClip(
        sourceClip,
        cutoffHz: lowpassHz,
        thresholdStd: thresholdStd,
        minSpacingMs: minSpacingMs,
        maxEvents: maxEvents,
      );
      if (eventMs.isEmpty) {
        _insertAssistantChatText(
          'No kick transients were detected for automatic sidechain.',
        );
        return;
      }

      if (fromMs != null || toMs != null) {
        final startWindow = (fromMs ?? 0.0).toDouble();
        final endWindow = (toMs ?? _maxAutomationTimelineMs()).toDouble();
        eventMs = eventMs
            .where((x) => x >= startWindow && x <= endWindow)
            .toList(growable: false);
      }
      if (eventMs.isEmpty) {
        _insertAssistantChatText(
          'Kick transients were found, but none were in the requested time range.',
        );
        return;
      }

      final recoverValue = _normalizedActionValueForTarget(
        data['recover_value'] ??
            data['end_value'] ??
            data['max_value'] ??
            target['recover_value'] ??
            target['end_value'] ??
            target['max_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 1.0 : 0.8,
      );
      final duckValue = _normalizedActionValueForTarget(
        data['duck_value'] ??
            data['min_value'] ??
            data['depth'] ??
            target['duck_value'] ??
            target['min_value'] ??
            target['depth'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 0.16 : 0.2,
      );
      final attackMs =
          (_toActionDouble(data['attack_ms'] ?? target['attack_ms']) ??
                  math.min(22.0, lengthMs * 0.2))
              .clamp(2.0, math.max(2.0, lengthMs * 0.7))
              .toDouble();
      final releaseRatio =
          (_toActionDouble(data['release_ratio'] ?? target['release_ratio']) ??
                  0.38)
              .clamp(0.08, 0.95)
              .toDouble();
      final recoveryMs = (lengthMs * releaseRatio)
          .clamp(attackMs + 1.0, lengthMs)
          .toDouble();
      final midValue = (duckValue + (recoverValue - duckValue) * 0.58).clamp(
        0.0,
        1.0,
      );
      final replaceExisting = _toActionBool(
        data['replace_existing'] ?? target['replace_existing'],
        fallback: false,
      );

      final maxTimelineMs = _maxAutomationTimelineMs();
      int created = 0;
      var nextPoints = _pointsForAutomationTarget(
        row,
        targetId,
      ).map((point) => point.copy()).toList(growable: false);
      if (replaceExisting && eventMs.isNotEmpty) {
        final regionStart = ((eventMs.first + offsetMs) - lengthMs * 0.25)
            .clamp(0.0, maxTimelineMs);
        final regionEnd = ((eventMs.last + offsetMs) + lengthMs * 1.1).clamp(
          regionStart,
          maxTimelineMs,
        );
        nextPoints = nextPoints
            .where(
              (point) =>
                  point.x <= regionStart + 1e-6 || point.x >= regionEnd - 1e-6,
            )
            .map((point) => point.copy())
            .toList(growable: false);
      }
      for (final onsetMs in eventMs) {
        final startMs = (onsetMs + offsetMs).clamp(0.0, maxTimelineMs);
        if (startMs + 4.0 >= maxTimelineMs) continue;
        final clippedLength = math.min(
          lengthMs,
          math.max(40.0, maxTimelineMs - startMs),
        );
        if (clippedLength <= 40.0) continue;

        final points = <AutomationPoint>[
          AutomationPoint(x: 0.0, volume: recoverValue),
          AutomationPoint(
            x: attackMs.clamp(1.0, clippedLength),
            volume: duckValue,
          ),
          AutomationPoint(
            x: recoveryMs.clamp(attackMs + 1.0, clippedLength),
            volume: midValue.toDouble(),
          ),
          AutomationPoint(x: clippedLength, volume: recoverValue),
        ];

        nextPoints = _replaceAutomationRangeWithRelativePoints(
          row: row,
          targetId: targetId,
          existing: nextPoints,
          startMs: startMs.toDouble(),
          lengthMs: clippedLength.toDouble(),
          relativePoints: points,
          replaceExisting: false,
        );
        created++;
      }

      if (created <= 0) {
        _insertAssistantChatText(
          "I couldn't place sidechain automation in the current timeline range.",
        );
        return;
      }

      await _setAutomationTargetPointsWithUndo(row, targetId, nextPoints);
      _showSmallNotice('Added $created kick-synced sidechain moves.');
      return;
    }

    if (operation == 'apply_template') {
      final startMs =
          (_toActionDouble(
                    data['start_ms'] ?? target['start_ms'] ?? data['at_ms'],
                  ) ??
                  _globalAudioClock.inMilliseconds.toDouble())
              .clamp(0.0, _maxAutomationTimelineMs());
      final lengthMs =
          (_toActionDouble(
                    data['length_ms'] ??
                        target['length_ms'] ??
                        data['duration_ms'] ??
                        target['duration_ms'],
                  ) ??
                  _defaultAutomationClipLengthMs())
              .clamp(80.0, _automationUpperBound(80.0));
      final startValue = _normalizedActionValueForTarget(
        data['start_value'] ?? data['from_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 0.75 : 0.5,
      );
      final endValue = _normalizedActionValueForTarget(
        data['end_value'] ?? data['to_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: targetId == 'volume' ? 0.75 : 0.5,
      );
      final template = normalizedTemplate;
      final direction = (data['direction'] ?? target['direction'] ?? 'up')
          .toString();
      final rawPoints = (data['points'] as List?) ?? const [];
      final clipPoints = <AutomationPoint>[];
      for (final raw in rawPoints) {
        final m = _toActionMap(raw);
        final x = _toActionDouble(m['x_ms'] ?? m['x'] ?? m['time_ms']);
        final rawValue =
            m['value'] ??
            m['volume'] ??
            m['normalized_value'] ??
            m['normalized'] ??
            m['real_value'] ??
            m['native_value'];
        if (x == null || rawValue == null) continue;
        final pointValueMode = (m['value_mode'] ?? valueMode).toString();
        final normalized = _normalizedActionValueForTarget(
          rawValue,
          targetMeta,
          valueMode: pointValueMode,
          fallback: targetId == 'volume' ? 0.75 : 0.5,
        );
        clipPoints.add(AutomationPoint(x: x, volume: normalized));
      }
      final points = clipPoints.isNotEmpty
          ? clipPoints
          : _automationTemplatePointsRelative(
              template.isEmpty ? 'ramp' : template,
              lengthMs,
              startValue: startValue,
              endValue: endValue,
              direction: direction,
            );
      final next = _replaceAutomationRangeWithRelativePoints(
        row: row,
        targetId: targetId,
        existing: _pointsForAutomationTarget(row, targetId),
        startMs: startMs.toDouble(),
        lengthMs: lengthMs.toDouble(),
        relativePoints: points,
      );
      await _setAutomationTargetPointsWithUndo(row, targetId, next);
      _showSmallNotice('Added automation to lane.');
      return;
    }

    if (operation == 'clear') {
      if (targetId == 'volume') {
        final maxMs = math.max(
          1.0,
          _audioOnlyOverallDuration.inMilliseconds.toDouble(),
        );
        await _setRowAutomationWithUndo(row, <AutomationPoint>[
          AutomationPoint(x: 0.0, volume: 1.0),
          AutomationPoint(x: maxMs, volume: 1.0),
        ]);
      } else {
        await _setAutomationTargetPointsWithUndo(
          row,
          targetId,
          _defaultAutomationPointsForTarget(row, targetId),
        );
      }
      _showSmallNotice('Cleared automation.');
      return;
    }

    if (operation == 'add_ramp') {
      final rawFromMs =
          _toActionDouble(
            data['from_ms'] ??
                target['from_ms'] ??
                data['start_ms'] ??
                target['start_ms'],
          ) ??
          _globalAudioClock.inMilliseconds.toDouble();
      final fromMs = rawFromMs
          .clamp(0.0, _maxAutomationTimelineMs())
          .toDouble();
      final rawToMs =
          _toActionDouble(
            data['to_ms'] ??
                target['to_ms'] ??
                data['end_ms'] ??
                target['end_ms'],
          ) ??
          (fromMs + defaultSpanMs);
      final toMs = math.max(fromMs + 40.0, rawToMs);
      final direction = (data['direction'] ?? target['direction'] ?? '')
          .toString()
          .trim()
          .toLowerCase();

      final existingValue = _resolvedAutomationValueAtMs(row, targetId, fromMs);
      final parsedStartValue = _normalizedActionValueForTarget(
        data['start_value'] ?? data['from_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: existingValue,
      );
      final parsedEndValue = _normalizedActionValueForTarget(
        data['end_value'] ?? data['to_value'],
        targetMeta,
        valueMode: valueMode,
        fallback: direction == 'down'
            ? (parsedStartValue - 0.35).clamp(0.0, 1.0).toDouble()
            : direction == 'up'
            ? (parsedStartValue + 0.35).clamp(0.0, 1.0).toDouble()
            : parsedStartValue,
      );
      final next = _pointsForAutomationTarget(
        row,
        targetId,
      ).map((p) => p.copy()).toList(growable: true);
      next.add(AutomationPoint(x: fromMs, volume: parsedStartValue));
      next.add(AutomationPoint(x: toMs, volume: parsedEndValue));
      await _setAutomationTargetPointsWithUndo(row, targetId, next);
      _showSmallNotice('Added automation ramp.');
      return;
    }

    final rawPoints = (data['points'] as List?) ?? const [];
    final points = <AutomationPoint>[];
    for (final raw in rawPoints) {
      final m = _toActionMap(raw);
      final x = _toActionDouble(m['x_ms'] ?? m['x'] ?? m['time_ms']);
      final rawValue =
          m['value'] ??
          m['volume'] ??
          m['normalized_value'] ??
          m['normalized'] ??
          m['real_value'] ??
          m['native_value'];
      if (x == null || rawValue == null) continue;
      final pointValueMode = (m['value_mode'] ?? valueMode).toString();
      final normalized = _normalizedActionValueForTarget(
        rawValue,
        targetMeta,
        valueMode: pointValueMode,
        fallback: targetId == 'volume' ? 1.0 : 0.5,
      );
      points.add(AutomationPoint(x: x, volume: normalized));
    }

    if (points.isEmpty) {
      if (operation == 'set_points') {
        final fromMs =
            (_toActionDouble(
                      data['from_ms'] ??
                          target['from_ms'] ??
                          data['start_ms'] ??
                          target['start_ms'],
                    ) ??
                    _globalAudioClock.inMilliseconds.toDouble())
                .clamp(0.0, _maxAutomationTimelineMs())
                .toDouble();
        final toMs =
            (_toActionDouble(
                      data['to_ms'] ??
                          target['to_ms'] ??
                          data['end_ms'] ??
                          target['end_ms'],
                    ) ??
                    (fromMs + defaultSpanMs))
                .clamp(fromMs + 40.0, _maxAutomationTimelineMs())
                .toDouble();
        final direction = (data['direction'] ?? target['direction'] ?? '')
            .toString()
            .trim()
            .toLowerCase();
        final base = _resolvedAutomationValueAtMs(row, targetId, fromMs);
        final v0 = _normalizedActionValueForTarget(
          data['start_value'] ?? data['from_value'] ?? data['value'],
          targetMeta,
          valueMode: valueMode,
          fallback: base,
        );
        final v1 = _normalizedActionValueForTarget(
          data['end_value'] ?? data['to_value'],
          targetMeta,
          valueMode: valueMode,
          fallback: direction == 'down'
              ? (v0 - 0.35).clamp(0.0, 1.0).toDouble()
              : direction == 'up'
              ? (v0 + 0.35).clamp(0.0, 1.0).toDouble()
              : v0,
        );
        await _setAutomationTargetPointsWithUndo(
          row,
          targetId,
          <AutomationPoint>[
            AutomationPoint(x: fromMs, volume: v0),
            AutomationPoint(x: toMs, volume: v1),
          ],
        );
        _showSmallNotice('Set automation points.');
        return;
      }
      _insertAssistantChatText(
        "I need automation points to apply (time/value pairs).",
      );
      return;
    }

    await _setAutomationTargetPointsWithUndo(row, targetId, points);
    _showSmallNotice('Set automation points.');
  }

  int? _pitchClassFromToken(String token) {
    return AssistantActionUtils.pitchClassFromToken(token);
  }

  int? _midiPitchFromRaw(dynamic raw, {int fallbackOctave = 3}) {
    return AssistantActionUtils.midiPitchFromRaw(
      raw,
      fallbackOctave: fallbackOctave,
    );
  }

  int? _rootMidiFromChordToken(String token, {int octave = 2}) {
    return AssistantActionUtils.rootMidiFromChordToken(token, octave: octave);
  }

  List<String> _progressionTokensFromActionData(Map<String, dynamic> data) {
    final target = _actionTarget(data);
    final rawProgression =
        data['progression'] ??
        target['progression'] ??
        data['chords'] ??
        target['chords'] ??
        data['pattern'] ??
        target['pattern'] ??
        data['sequence'] ??
        target['sequence'] ??
        data['text'] ??
        target['text'] ??
        data['request'] ??
        target['request'];
    return AssistantActionUtils.progressionTokensFromRaw(rawProgression);
  }

  List<MidiNote> _fallbackMidiNotesFromProgression(Map<String, dynamic> data) {
    final tokens = _progressionTokensFromActionData(data);
    if (tokens.isEmpty) return const <MidiNote>[];
    final target = _actionTarget(data);
    final operation = (data['operation'] ?? '').toString().trim().toLowerCase();

    final beatsPerChord =
        _toActionDouble(
          data['beats_per_chord'] ??
              target['beats_per_chord'] ??
              data['chord_length_beats'] ??
              target['chord_length_beats'],
        ) ??
        4.0;
    final notesPerChord =
        (_toActionInt(data['notes_per_chord'] ?? target['notes_per_chord']) ??
                4)
            .clamp(1, 8)
            .toInt();
    final isBassline = operation == 'compose_bassline';
    final octave =
        (_toActionInt(data['octave'] ?? target['octave']) ??
                (isBassline ? 2 : 3))
            .clamp(-1, 8)
            .toInt();
    final velocity =
        (_toActionDouble(data['velocity'] ?? target['velocity']) ?? 0.78)
            .clamp(0.2, 1.0)
            .toDouble();

    return AssistantActionUtils.fallbackMidiNotesFromProgression(
      progressionRaw: tokens,
      beatsPerChord: beatsPerChord,
      notesPerChord: notesPerChord,
      octave: octave,
      velocity: velocity,
      mode: isBassline ? 'bass' : 'chords',
      noteIdPrefix: 'ai_prog',
    );
  }

  bool _notesContainPolyphony(List<MidiNote> notes) {
    if (notes.length < 2) return false;
    final byStart = <int, int>{};
    for (final note in notes) {
      final bucket = (note.startBeat * 1000.0).round();
      final nextCount = (byStart[bucket] ?? 0) + 1;
      if (nextCount >= 2) return true;
      byStart[bucket] = nextCount;
    }
    return false;
  }

  String _preferredAiInstrumentIdForNewMidiClip(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String operation,
    List<MidiNote> notes,
  ) {
    final explicitInstrumentId =
        (data['instrument_id'] ?? target['instrument_id'] ?? '')
            .toString()
            .trim();
    if (explicitInstrumentId.isNotEmpty) {
      return explicitInstrumentId;
    }

    if (operation == 'compose_bassline') {
      return _canUseInstrumentForCurrentPlan('mixroom.sub_bass')
          ? 'mixroom.sub_bass'
          : 'mixroom.mellow_sub';
    }

    final progressionTokens = _progressionTokensFromActionData(data);
    final requestedNotesPerChord =
        _toActionInt(data['notes_per_chord'] ?? target['notes_per_chord']) ?? 0;
    final likelyHarmony =
        progressionTokens.isNotEmpty ||
        requestedNotesPerChord > 1 ||
        _notesContainPolyphony(notes);

    if (likelyHarmony) {
      for (final candidate in const <String>[
        kPreferredPianoInstrumentId,
        'mixroom.warm_keys',
        'mixroom.velvet_ep',
        'mixroom.fm_keys',
        'mixroom.house_organ',
        'mixroom.vanilla_poly',
      ]) {
        if (_findInstrumentSpecById(candidate) != null &&
            _canUseInstrumentForCurrentPlan(candidate)) {
          return candidate;
        }
      }
    }

    for (final candidate in const <String>[
      kPreferredPianoInstrumentId,
      'mixroom.basic_synth',
      'mixroom.vanilla_poly',
      'mixroom.warm_keys',
    ]) {
      if (_findInstrumentSpecById(candidate) != null &&
          _canUseInstrumentForCurrentPlan(candidate)) {
        return candidate;
      }
    }

    return _canUseInstrumentForCurrentPlan('mixroom.sub_bass')
        ? 'mixroom.sub_bass'
        : 'mixroom.basic_synth';
  }

  String _resolveAiInstrumentIdFromActionData(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String fallbackInstrumentId,
  ) {
    final explicitInstrumentId =
        (data['instrument_id'] ?? target['instrument_id'] ?? '')
            .toString()
            .trim();
    if (explicitInstrumentId.isNotEmpty &&
        _findInstrumentSpecById(explicitInstrumentId) != null &&
        _canUseInstrumentForCurrentPlan(explicitInstrumentId)) {
      return explicitInstrumentId;
    }

    final requestedName =
        (data['instrument_name'] ?? target['instrument_name'] ?? '')
            .toString()
            .trim();
    if (requestedName.isNotEmpty) {
      final matchedSpec = _findLegacySfzSpecByToken(requestedName);
      final matchedId = (matchedSpec?['id'] as String?)?.trim() ?? '';
      if (matchedId.isNotEmpty && _canUseInstrumentForCurrentPlan(matchedId)) {
        return matchedId;
      }
    }

    if (_canUseInstrumentForCurrentPlan(fallbackInstrumentId)) {
      return fallbackInstrumentId;
    }

    for (final candidate in SubscriptionLimits.freeBuiltInInstrumentIds) {
      if (_findInstrumentSpecById(candidate) != null) return candidate;
    }
    return kPreferredPianoInstrumentId;
  }

  bool _shouldCreateFreshMidiClip(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String operation,
  ) {
    if (operation == 'create_clip') return true;
    return _toActionBool(
          data['create_new_clip'] ?? target['create_new_clip'],
        ) ||
        _toActionBool(data['prefer_new_clip'] ?? target['prefer_new_clip']);
  }

  bool _shouldPreserveExistingMidiNotes(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    String operation,
  ) {
    if (operation != 'replace_notes' && operation != 'append_notes') {
      return false;
    }
    return _toActionBool(
      data['preserve_existing_notes'] ?? target['preserve_existing_notes'],
    );
  }

  double? _resolveMidiTargetLengthBeats(
    Map<String, dynamic> data,
    Map<String, dynamic> target,
  ) {
    return AssistantActionUtils.resolveMidiTargetLengthBeatsFromAction(
      data,
      target: target,
      bpm: _tempo,
    );
  }

  List<MidiNote> _resizeMidiNotesToTargetLength(
    List<MidiNote> sourceNotes,
    double targetBeats,
  ) {
    if (sourceNotes.isEmpty || !targetBeats.isFinite || targetBeats <= 0.0) {
      return const <MidiNote>[];
    }
    final sorted = sourceNotes.map((n) => n.copy()).toList(growable: false)
      ..sort((a, b) {
        final byStart = a.startBeat.compareTo(b.startBeat);
        if (byStart != 0) return byStart;
        final byPitch = a.pitch.compareTo(b.pitch);
        if (byPitch != 0) return byPitch;
        return a.id.compareTo(b.id);
      });
    final cycleBeats = sorted
        .map((n) => n.startBeat + n.lengthBeats)
        .fold<double>(0.0, math.max);
    if (!cycleBeats.isFinite || cycleBeats <= 0.0) {
      return const <MidiNote>[];
    }

    final out = <MidiNote>[];
    final repeats = math.max(1, (targetBeats / cycleBeats).ceil());
    const epsilon = 1e-6;
    for (int repeat = 0; repeat < repeats; repeat++) {
      final beatOffset = repeat * cycleBeats;
      for (int i = 0; i < sorted.length; i++) {
        final note = sorted[i];
        final startBeat = note.startBeat + beatOffset;
        if (startBeat >= targetBeats - epsilon) continue;
        final remaining = targetBeats - startBeat;
        if (remaining <= epsilon) continue;
        out.add(
          MidiNote(
            id: 'ai_resize_${repeat}_$i',
            pitch: note.pitch,
            startBeat: startBeat,
            lengthBeats: math.min(note.lengthBeats, remaining),
            velocity: note.velocity,
          ),
        );
      }
    }
    return out;
  }

  List<MidiNote> _midiNotesFromActionData(Map<String, dynamic> data) {
    final rawNotes = (data['notes'] as List?) ?? const [];
    final out = <MidiNote>[];
    int i = 0;
    for (final raw in rawNotes) {
      final m = _toActionMap(raw);
      final startBeat = AssistantActionUtils.resolveMidiNoteStartBeat(m);
      final lengthBeats = AssistantActionUtils.resolveMidiNoteLengthBeats(m);
      final velocity =
          AssistantActionUtils.normalizeMidiVelocity(m['velocity']) ?? 0.8;
      if (startBeat == null || lengthBeats == null) continue;

      final pitches = <int>[];
      final singlePitch = _midiPitchFromRaw(
        m['pitch'] ?? m['midi'] ?? m['note'] ?? m['note_name'],
      );
      if (singlePitch != null) {
        pitches.add(singlePitch.clamp(0, 127).toInt());
      }

      final rawChordPitches = m['pitches'];
      if (rawChordPitches is List) {
        for (final rawPitch in rawChordPitches) {
          final chordPitch = _midiPitchFromRaw(rawPitch);
          if (chordPitch != null) {
            pitches.add(chordPitch.clamp(0, 127).toInt());
          }
        }
      }

      if (pitches.isEmpty) continue;

      for (final pitch in pitches) {
        out.add(
          MidiNote(
            id: 'ai_note_${DateTime.now().microsecondsSinceEpoch}_${i++}',
            pitch: pitch,
            startBeat: math.max(0.0, startBeat),
            lengthBeats: math.max(0.0625, lengthBeats),
            velocity: velocity.clamp(0.0, 1.0).toDouble(),
          ),
        );
      }
    }
    return out;
  }

  int _midiSubdivisionFromActionData(
    Map<String, dynamic> data, {
    int fallback = 16,
  }) {
    final target = _actionTarget(data);

    int? parseSubdivision(dynamic raw) {
      if (raw is num) return raw.round();
      if (raw is! String) return null;

      final text = raw.trim().toLowerCase();
      if (text.isEmpty) return null;

      int? out;
      final fraction = RegExp(r'^1\s*/\s*(\d+)$').firstMatch(text);
      if (fraction != null) {
        out = int.tryParse(fraction.group(1) ?? '');
      }
      out ??= int.tryParse(text);
      if (out == null) {
        final embedded = RegExp(r'(\d+)').firstMatch(text);
        if (embedded != null) {
          out = int.tryParse(embedded.group(1) ?? '');
        }
      }
      out ??= () {
        if (text.contains('whole')) return 1;
        if (text.contains('half')) return 2;
        if (text.contains('quarter')) return 4;
        if (text.contains('8th') || text.contains('eighth')) return 8;
        if (text.contains('16th') || text.contains('sixteenth')) return 16;
        if (text.contains('32nd') || text.contains('thirty-second')) return 32;
        if (text.contains('64th') || text.contains('sixty-fourth')) return 64;
        return null;
      }();
      if (out == null || out <= 0) return null;
      if (text.contains('triplet')) {
        out = math.max(1, ((out * 3.0) / 2.0).round());
      }
      return out;
    }

    int? resolved;
    for (final raw in <dynamic>[
      data['subdivision'],
      target['subdivision'],
      data['subdivision_divisor'],
      target['subdivision_divisor'],
      data['grid'],
      target['grid'],
      data['resolution'],
      target['resolution'],
      data['note_value'],
      target['note_value'],
    ]) {
      final parsed = parseSubdivision(raw);
      if (parsed != null) {
        resolved = parsed;
        break;
      }
    }

    if (resolved == null) {
      final stepBeats = _toActionDouble(
        data['step_beats'] ??
            target['step_beats'] ??
            data['beats_per_slice'] ??
            target['beats_per_slice'] ??
            data['slice_beats'] ??
            target['slice_beats'],
      );
      if (stepBeats != null && stepBeats.isFinite && stepBeats > 0.0) {
        resolved = (4.0 / stepBeats).round();
      }
    }

    return (resolved ?? fallback).clamp(1, 128).toInt();
  }

  List<MidiNote> _chopMidiNotesFromActionData(
    Map<String, dynamic> data,
    List<MidiNote> sourceNotes, {
    int? subdivision,
  }) {
    final target = _actionTarget(data);
    final safeSubdivision =
        subdivision ?? _midiSubdivisionFromActionData(data, fallback: 16);
    final stepBeats = _toActionDouble(
      data['step_beats'] ??
          target['step_beats'] ??
          data['beats_per_slice'] ??
          target['beats_per_slice'] ??
          data['slice_beats'] ??
          target['slice_beats'],
    );
    final sustainRatio =
        (_toActionDouble(
                  data['sustain_ratio'] ??
                      target['sustain_ratio'] ??
                      data['gate'] ??
                      target['gate'] ??
                      data['length_ratio'] ??
                      target['length_ratio'],
                ) ??
                1.0)
            .clamp(0.05, 1.0)
            .toDouble();
    final minLengthBeats =
        (_toActionDouble(
                  data['min_length_beats'] ?? target['min_length_beats'],
                ) ??
                0.03125)
            .clamp(0.0005, 4.0)
            .toDouble();
    final velocityDecayPerSlice =
        (_toActionDouble(
                  data['velocity_decay_per_slice'] ??
                      target['velocity_decay_per_slice'] ??
                      data['decay_per_slice'] ??
                      target['decay_per_slice'] ??
                      data['velocity_decay'] ??
                      target['velocity_decay'] ??
                      data['stutter_decay'] ??
                      target['stutter_decay'],
                ) ??
                0.0)
            .clamp(-1.0, 1.0)
            .toDouble();
    final velocityJitter =
        (_toActionDouble(
                  data['velocity_jitter'] ??
                      target['velocity_jitter'] ??
                      data['humanize_velocity_jitter'] ??
                      target['humanize_velocity_jitter'],
                ) ??
                0.0)
            .clamp(0.0, 1.0)
            .toDouble();
    final velocityFloor =
        (_toActionDouble(
                  data['velocity_floor'] ??
                      target['velocity_floor'] ??
                      data['min_velocity'] ??
                      target['min_velocity'],
                ) ??
                0.05)
            .clamp(0.0, 1.0)
            .toDouble();
    final fromBeat = _toActionDouble(
      data['from_beat'] ?? target['from_beat'] ?? data['start_beat'],
    );
    final toBeat = _toActionDouble(
      data['to_beat'] ?? target['to_beat'] ?? data['end_beat'],
    );

    return AssistantActionUtils.chopMidiNotes(
      notes: sourceNotes,
      subdivision: safeSubdivision,
      stepBeats: stepBeats,
      sustainRatio: sustainRatio,
      minLengthBeats: minLengthBeats,
      velocityDecayPerSlice: velocityDecayPerSlice,
      velocityJitter: velocityJitter,
      velocityFloor: velocityFloor,
      fromBeat: fromBeat,
      toBeat: toBeat,
      noteIdPrefix: 'ai_chop',
    );
  }

  Future<void> _applyMidiComposeAction(
    Map<String, dynamic> data, {
    int? chatFlowId,
  }) async {
    final operation = _normalizeMidiComposeOperation(
      (data['operation'] ?? '').toString().trim().toLowerCase(),
    );
    final target = _actionTarget(data);
    final forceCreateNewClip = _shouldCreateFreshMidiClip(
      data,
      target,
      operation,
    );

    if (operation == 'convert_audio_to_midi') {
      final sourceClipIndex = _resolveSingleClipIndexWithFallback(
        data,
        requireAudio: true,
      );
      if (sourceClipIndex == null ||
          sourceClipIndex < 0 ||
          sourceClipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
          "I couldn't resolve which audio clip to convert to MIDI.",
        );
        return;
      }
      await _convertAudioClipToMidi(sourceClipIndex, data, target, chatFlowId);
      return;
    }

    int? clipIndex;
    if (!forceCreateNewClip) {
      clipIndex = _resolveSingleClipIndexWithFallback(data, requireMidi: true);
      if (clipIndex == null) {
        final rowHint = _resolveRowIndexFromActionTarget(data);
        if (rowHint != null) {
          final midiCandidates = <int>[];
          for (int i = 0; i < _audioTracks.length; i++) {
            final clip = _audioTracks[i];
            if (!clip.isMidi) continue;
            if (clip.rowIndex != rowHint) continue;
            midiCandidates.add(i);
          }
          clipIndex = _pickPreferredClipIndex(midiCandidates);
        }
      }
    }

    if (operation == 'chop_notes') {
      if (clipIndex == null ||
          clipIndex < 0 ||
          clipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
          "I couldn't resolve which MIDI clip to chop. Select a MIDI clip and ask again.",
        );
        return;
      }
      final clip = _audioTracks[clipIndex];
      if (!clip.isMidi) {
        _insertAssistantChatText('The selected clip is not a MIDI clip.');
        return;
      }
      if (clip.midiNotes.isEmpty) {
        _insertAssistantChatText('The target MIDI clip has no notes to chop.');
        return;
      }

      final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
      final oldParams = Map<String, double>.from(clip.instrumentParams);
      final oldInstrumentId = clip.instrumentId;
      final oldInstrumentName = clip.instrumentName;
      final oldHostedInstrumentStateBase64 = clip.hostedInstrumentStateBase64;
      final subdivision = _midiSubdivisionFromActionData(data, fallback: 16);
      final decayPerSlice =
          (_toActionDouble(
                    data['velocity_decay_per_slice'] ??
                        data['decay_per_slice'] ??
                        data['velocity_decay'] ??
                        data['stutter_decay'],
                  ) ??
                  0.0)
              .toDouble();
      final nextNotes = _chopMidiNotesFromActionData(
        data,
        oldNotes,
        subdivision: subdivision,
      );

      if (_midiNotesEqual(oldNotes, nextNotes)) {
        _showSmallNotice('MIDI notes already match that chop grid.');
        return;
      }

      await _undoManager.execute(
        EditMidiClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldNotes: oldNotes,
          newNotes: nextNotes,
          oldInstrumentId: oldInstrumentId,
          oldInstrumentName: oldInstrumentName,
          oldInstrumentParams: oldParams,
          oldHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          newInstrumentId: oldInstrumentId,
          newInstrumentName: oldInstrumentName,
          newInstrumentParams: oldParams,
          newHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          applyToClip:
              (
                target,
                notesToApply,
                nextInstrumentId,
                nextInstrumentName,
                nextParams,
                hostedInstrumentStateBase64,
              ) async {
                target.midiNotes = notesToApply.map((n) => n.copy()).toList();
                _assignMidiClipInstrument(
                  target,
                  instrumentId: nextInstrumentId,
                  instrumentName: nextInstrumentName,
                  instrumentParams: nextParams,
                );
                target.hostedInstrumentStateBase64 = hostedInstrumentStateBase64
                    .trim();
                target.sourceTempoBpm = _clampTempo(_tempo);
                target.stretchToProjectTempo = true;
                target.tempoStretchPreservePitch = true;
                final updatedLive = await _updateMidiClipEventsLive(target);
                if (updatedLive) {
                  final clipIdx = _clipIndexForEngineId(target.engineClipId);
                  if (clipIdx >= 0) {
                    await _syncClipTimingToEngine(clipIdx);
                  }
                  await _syncClipMixToEngine(target);
                  _updateOverallDurationIfNeeded(
                    changedClips: <AudioTrack>[target],
                  );
                } else {
                  final reloaded = await _reloadMidiTrackLive(target);
                  if (!reloaded && mounted) {
                    _showSmallNotice('Could not update this MIDI clip.');
                  }
                }
                if (mounted) setState(() {});
              },
        ),
      );
      final withDecay = decayPerSlice.abs() > 0.0001;
      _showSmallNotice(
        withDecay
            ? 'Chopped MIDI notes to 1/$subdivision with velocity decay.'
            : 'Chopped MIDI notes to 1/$subdivision.',
      );
      return;
    }

    if (operation == 'transpose_notes') {
      if (clipIndex == null ||
          clipIndex < 0 ||
          clipIndex >= _audioTracks.length) {
        _insertAssistantChatText(
          "I couldn't resolve which MIDI clip to transpose. Select a MIDI clip and ask again.",
        );
        return;
      }
      final clip = _audioTracks[clipIndex];
      if (!clip.isMidi) {
        _insertAssistantChatText('The selected clip is not a MIDI clip.');
        return;
      }
      if (clip.midiNotes.isEmpty) {
        _insertAssistantChatText(
          'The target MIDI clip has no notes to transpose.',
        );
        return;
      }

      final semitones =
          ((_toActionDouble(data['semitones']) ?? 0.0) +
                  ((_toActionDouble(data['octaves']) ?? 0.0) * 12.0))
              .round();
      if (semitones == 0) {
        _showSmallNotice('MIDI notes already match that pitch.');
        return;
      }

      final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
      final oldParams = Map<String, double>.from(clip.instrumentParams);
      final oldInstrumentId = clip.instrumentId;
      final oldInstrumentName = clip.instrumentName;
      final oldHostedInstrumentStateBase64 = clip.hostedInstrumentStateBase64;
      final nextNotes = oldNotes
          .map(
            (n) => MidiNote(
              id: n.id,
              pitch: (n.pitch + semitones).clamp(0, 127).toInt(),
              startBeat: n.startBeat,
              lengthBeats: n.lengthBeats,
              velocity: n.velocity,
            ),
          )
          .toList(growable: false);

      await _undoManager.execute(
        EditMidiClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldNotes: oldNotes,
          newNotes: nextNotes,
          oldInstrumentId: oldInstrumentId,
          oldInstrumentName: oldInstrumentName,
          oldInstrumentParams: oldParams,
          oldHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          newInstrumentId: oldInstrumentId,
          newInstrumentName: oldInstrumentName,
          newInstrumentParams: oldParams,
          newHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          applyToClip:
              (
                target,
                notesToApply,
                nextInstrumentId,
                nextInstrumentName,
                nextParams,
                hostedInstrumentStateBase64,
              ) async {
                target.midiNotes = notesToApply.map((n) => n.copy()).toList();
                _assignMidiClipInstrument(
                  target,
                  instrumentId: nextInstrumentId,
                  instrumentName: nextInstrumentName,
                  instrumentParams: nextParams,
                );
                target.hostedInstrumentStateBase64 = hostedInstrumentStateBase64
                    .trim();
                target.sourceTempoBpm = _clampTempo(_tempo);
                target.stretchToProjectTempo = true;
                target.tempoStretchPreservePitch = true;
                final updatedLive = await _updateMidiClipEventsLive(target);
                if (updatedLive) {
                  final clipIdx = _clipIndexForEngineId(target.engineClipId);
                  if (clipIdx >= 0) {
                    await _syncClipTimingToEngine(clipIdx);
                  }
                  await _syncClipMixToEngine(target);
                  _updateOverallDurationIfNeeded(
                    changedClips: <AudioTrack>[target],
                  );
                } else {
                  final reloaded = await _reloadMidiTrackLive(target);
                  if (!reloaded && mounted) {
                    _showSmallNotice('Could not update this MIDI clip.');
                  }
                }
                if (mounted) setState(() {});
              },
        ),
      );
      final direction = semitones > 0 ? 'up' : 'down';
      final amount = semitones.abs() == 12
          ? '1 octave'
          : semitones.abs() % 12 == 0
          ? '${(semitones.abs() / 12).round()} octaves'
          : '${semitones.abs()} semitones';
      _showSmallNotice('Shifted MIDI notes $direction by $amount.');
      return;
    }

    final preserveExistingNotes = _shouldPreserveExistingMidiNotes(
      data,
      target,
      operation,
    );
    var notes = _midiNotesFromActionData(data);
    if (notes.isEmpty) {
      notes = _fallbackMidiNotesFromProgression(data);
    }
    if (notes.isEmpty &&
        clipIndex != null &&
        clipIndex >= 0 &&
        clipIndex < _audioTracks.length) {
      final sourceClip = _audioTracks[clipIndex];
      if (sourceClip.isMidi &&
          sourceClip.midiNotes.isNotEmpty &&
          AssistantActionUtils.hasStyleDrivenMidiGenerationDirectives(
            data,
            target: target,
          )) {
        notes = AssistantActionUtils.generateStyledMidiNotesFromSource(
          sourceNotes: sourceClip.midiNotes,
          data: data,
          target: target,
          noteIdPrefix: 'ai_style',
          bpm: _tempo,
        );
      }
    }
    if (notes.isEmpty &&
        clipIndex != null &&
        clipIndex >= 0 &&
        clipIndex < _audioTracks.length &&
        preserveExistingNotes) {
      final clip = _audioTracks[clipIndex];
      if (!clip.isMidi) {
        _insertAssistantChatText('The selected clip is not a MIDI clip.');
        return;
      }
      if (clip.midiNotes.isEmpty) {
        _insertAssistantChatText(
          'The target MIDI clip has no notes to extend yet.',
        );
        return;
      }
      final targetLengthBeats = _resolveMidiTargetLengthBeats(data, target);
      if (targetLengthBeats == null) {
        _insertAssistantChatText(
          'I need a target MIDI length in measures or beats for that edit.',
        );
        return;
      }
      final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
      final nextNotes = _resizeMidiNotesToTargetLength(
        oldNotes,
        targetLengthBeats,
      );
      if (nextNotes.isEmpty) {
        _insertAssistantChatText("I couldn't reshape that MIDI clip cleanly.");
        return;
      }
      if (_midiNotesEqual(oldNotes, nextNotes)) {
        _showSmallNotice('That MIDI clip is already that long.');
        return;
      }
      final oldParams = Map<String, double>.from(clip.instrumentParams);
      final oldInstrumentId = clip.instrumentId;
      final oldInstrumentName = clip.instrumentName;
      final oldHostedInstrumentStateBase64 = clip.hostedInstrumentStateBase64;
      await _undoManager.execute(
        EditMidiClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldNotes: oldNotes,
          newNotes: nextNotes,
          oldInstrumentId: oldInstrumentId,
          oldInstrumentName: oldInstrumentName,
          oldInstrumentParams: oldParams,
          oldHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          newInstrumentId: oldInstrumentId,
          newInstrumentName: oldInstrumentName,
          newInstrumentParams: oldParams,
          newHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          applyToClip:
              (
                targetClip,
                notesToApply,
                nextInstrumentId,
                nextInstrumentName,
                nextParams,
                hostedInstrumentStateBase64,
              ) async {
                targetClip.midiNotes = notesToApply
                    .map((n) => n.copy())
                    .toList();
                _assignMidiClipInstrument(
                  targetClip,
                  instrumentId: nextInstrumentId,
                  instrumentName: nextInstrumentName,
                  instrumentParams: nextParams,
                );
                targetClip.hostedInstrumentStateBase64 =
                    hostedInstrumentStateBase64.trim();
                targetClip.sourceTempoBpm = _clampTempo(_tempo);
                targetClip.stretchToProjectTempo = true;
                targetClip.tempoStretchPreservePitch = true;
                final updatedLive = await _updateMidiClipEventsLive(targetClip);
                if (updatedLive) {
                  final clipIdx = _clipIndexForEngineId(
                    targetClip.engineClipId,
                  );
                  if (clipIdx >= 0) {
                    await _syncClipTimingToEngine(clipIdx);
                  }
                  await _syncClipMixToEngine(targetClip);
                  _updateOverallDurationIfNeeded(
                    changedClips: <AudioTrack>[targetClip],
                  );
                } else {
                  final reloaded = await _reloadMidiTrackLive(targetClip);
                  if (!reloaded && mounted) {
                    _showSmallNotice('Could not update this MIDI clip.');
                  }
                }
                if (mounted) setState(() {});
              },
        ),
      );
      final roundedMeasures = targetLengthBeats / 4.0;
      final lengthLabel = roundedMeasures == roundedMeasures.roundToDouble()
          ? '${roundedMeasures.round()} bars'
          : '${targetLengthBeats.toStringAsFixed(1)} beats';
      _showSmallNotice('Extended MIDI clip to $lengthLabel.');
      return;
    }
    if (notes.isEmpty) {
      _insertAssistantChatText(
        "I need MIDI notes (or a chord progression) to write this part.",
      );
      return;
    }

    final targetLengthBeats = _resolveMidiTargetLengthBeats(data, target);
    if (targetLengthBeats != null &&
        targetLengthBeats.isFinite &&
        targetLengthBeats > 0.0 &&
        !_toActionBool(data['exact_notes'], fallback: false)) {
      final currentSpan = notes
          .map((n) => n.startBeat + n.lengthBeats)
          .fold<double>(0.0, math.max);
      if (currentSpan > 0.0 && currentSpan < targetLengthBeats - 1e-6) {
        notes = _resizeMidiNotesToTargetLength(notes, targetLengthBeats);
      }
    }

    if (clipIndex == null ||
        clipIndex < 0 ||
        clipIndex >= _audioTracks.length) {
      final preferredInstrumentId = _preferredAiInstrumentIdForNewMidiClip(
        data,
        target,
        operation,
        notes,
      );
      final row = _resolveAiContentInsertionRowIndexFromActionTarget(data);
      final instrumentId = _resolveAiInstrumentIdFromActionData(
        data,
        target,
        preferredInstrumentId,
      );
      final instrumentName =
          (data['instrument_name'] ??
                  target['instrument_name'] ??
                  _instrumentNameFromId(instrumentId))
              .toString()
              .trim();
      final startMs =
          _toActionDouble(data['start_ms'] ?? target['start_ms']) ??
          _globalAudioClock.inMilliseconds.toDouble();
      final beforeTrackCount = _audioTracks.length;
      final addMidiAction = AddMidiClipAction(
        addMidiClip:
            ({
              required String instrumentId,
              required String instrumentName,
              required Map<String, double> instrumentParams,
              required List<MidiNote> midiNotes,
              required int row,
              required double timeMs,
              Duration? trimEndRequested,
            }) => _addMidiTrack(
              instrumentId: instrumentId,
              instrumentName: instrumentName,
              instrumentParams: instrumentParams,
              midiNotes: midiNotes,
              row: row,
              timeMs: timeMs,
              trimEndRequested: trimEndRequested,
              label: data['label']?.toString(),
            ),
        tracks: _audioTracks,
        restoreTrack: _addClipFromUndoPayload,
        instrumentId: instrumentId,
        instrumentName: instrumentName.isEmpty ? instrumentId : instrumentName,
        instrumentParams: _instrumentParamsFromSpec(
          _instrumentSpecById(instrumentId),
        ),
        midiNotes: notes,
        row: row,
        timeMs: math.max(0.0, startMs),
        trimEnd: targetLengthBeats == null
            ? null
            : Duration(
                microseconds: (targetLengthBeats * 60.0 / _tempo * 1000000)
                    .round(),
              ),
        onRemove: _syncRemovedClipFadesAfterUndo,
      );
      await _undoManager.execute(addMidiAction);
      if (_audioTracks.length == beforeTrackCount) {
        _insertAssistantChatText(
          _isSampledInstrumentId(instrumentId)
              ? "I couldn't load that sampled instrument for live MIDI playback."
              : "I couldn't create that MIDI clip.",
        );
        return;
      }
      _showSmallNotice('Created MIDI clip from AI notes.');
      return;
    }

    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) {
      _insertAssistantChatText('The selected clip is not a MIDI clip.');
      return;
    }

    final append = _toActionBool(
      data['append'],
      fallback: operation.contains('append'),
    );
    final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
    final oldParams = Map<String, double>.from(clip.instrumentParams);
    final oldInstrumentId = clip.instrumentId;
    final oldInstrumentName = clip.instrumentName;
    final oldHostedInstrumentStateBase64 = clip.hostedInstrumentStateBase64;
    final preserveClipState = _toActionBool(
      data['preserve_clip_state'],
      fallback: false,
    );
    final finalLengthBeats = _toActionDouble(data['final_length_beats']);
    final hasExactFinalLength =
        finalLengthBeats != null &&
        finalLengthBeats.isFinite &&
        finalLengthBeats > 0.0;
    final oldTrimEnd = clip.trimEnd;
    final oldAudioDuration = clip.audioDuration;
    final newTrimEnd = hasExactFinalLength
        ? clip.trimStart +
              Duration(
                microseconds: (finalLengthBeats * 60.0 / _tempo * 1000000)
                    .round(),
              )
        : null;
    final newAudioDuration = newTrimEnd == null
        ? null
        : (oldAudioDuration < newTrimEnd ? newTrimEnd : oldAudioDuration);
    Map<String, dynamic> ownedState({
      required Duration trimEnd,
      required Duration audioDuration,
    }) => <String, dynamic>{
      'trim_end_us': trimEnd.inMicroseconds,
      'audio_duration_us': audioDuration.inMicroseconds,
      'source_tempo_bpm': clip.sourceTempoBpm,
      'stretch_to_project_tempo': clip.stretchToProjectTempo,
      'tempo_stretch_preserve_pitch': clip.tempoStretchPreservePitch,
      'tempo_warp_mode': clip.tempoWarpMode,
    };
    final preserveOwnedState = preserveClipState || hasExactFinalLength;
    final oldClipOwnedState = preserveOwnedState
        ? ownedState(trimEnd: oldTrimEnd, audioDuration: oldAudioDuration)
        : null;
    final newClipOwnedState = preserveOwnedState
        ? ownedState(
            trimEnd: newTrimEnd ?? oldTrimEnd,
            audioDuration: newAudioDuration ?? oldAudioDuration,
          )
        : null;

    List<MidiNote> nextNotes = notes.map((n) => n.copy()).toList();
    if (append) {
      final explicitAppendStartBeat = _toActionDouble(
        data['append_start_beat'],
      );
      double appendStartBeat = explicitAppendStartBeat ?? 0.0;
      final appendAtEnd = _toActionBool(
        data['append_at_end'],
        fallback: !preserveExistingNotes,
      );
      if (appendAtEnd && oldNotes.isNotEmpty) {
        appendStartBeat = oldNotes
            .map((n) => n.startBeat + n.lengthBeats)
            .reduce(math.max);
      } else if (explicitAppendStartBeat == null && preserveExistingNotes) {
        appendStartBeat = 0.0;
      }
      nextNotes = [
        ...oldNotes.map((n) => n.copy()),
        ...notes.map(
          (n) => MidiNote(
            id: 'ai_note_${DateTime.now().microsecondsSinceEpoch}_${n.pitch}',
            pitch: n.pitch,
            startBeat: n.startBeat + appendStartBeat,
            lengthBeats: n.lengthBeats,
            velocity: n.velocity,
          ),
        ),
      ];
    }

    await _undoManager.execute(
      EditMidiClipAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldNotes: oldNotes,
        newNotes: nextNotes,
        oldInstrumentId: oldInstrumentId,
        oldInstrumentName: oldInstrumentName,
        oldInstrumentParams: oldParams,
        oldHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
        newInstrumentId: oldInstrumentId,
        newInstrumentName: oldInstrumentName,
        newInstrumentParams: oldParams,
        newHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
        oldTrimEnd: hasExactFinalLength ? oldTrimEnd : null,
        newTrimEnd: newTrimEnd,
        oldAudioDuration: hasExactFinalLength ? oldAudioDuration : null,
        newAudioDuration: newAudioDuration,
        oldClipOwnedState: oldClipOwnedState,
        newClipOwnedState: newClipOwnedState,
        syncTiming: (target) async {
          final index = _clipIndexForPersistentId(target.clipId);
          if (!_isValidClipIndex(index)) {
            throw StateError('v3_midi_native_timing_sync_failed');
          }
          await _syncClipTimingToEngine(index);
        },
        applyToClip:
            (
              target,
              notesToApply,
              nextInstrumentId,
              nextInstrumentName,
              nextParams,
              hostedInstrumentStateBase64,
            ) async {
              target.midiNotes = notesToApply.map((n) => n.copy()).toList();
              _assignMidiClipInstrument(
                target,
                instrumentId: nextInstrumentId,
                instrumentName: nextInstrumentName,
                instrumentParams: nextParams,
              );
              target.hostedInstrumentStateBase64 = hostedInstrumentStateBase64
                  .trim();
              if (!preserveClipState) {
                target.sourceTempoBpm = _clampTempo(_tempo);
                target.stretchToProjectTempo = true;
                target.tempoStretchPreservePitch = true;
              }
              final updatedLive = await _updateMidiClipEventsLive(target);
              if (updatedLive) {
                if (!preserveClipState || hasExactFinalLength) {
                  final clipIdx = _clipIndexForEngineId(target.engineClipId);
                  if (clipIdx >= 0) {
                    await _syncClipTimingToEngine(clipIdx);
                  }
                }
                await _syncClipMixToEngine(target);
                _updateOverallDurationIfNeeded(
                  changedClips: <AudioTrack>[target],
                );
              } else {
                final reloaded = await _reloadMidiTrackLive(target);
                if (!reloaded) {
                  throw StateError('v3_midi_native_sync_failed');
                }
              }
              if (mounted) setState(() {});
            },
      ),
    );
    _showSmallNotice(append ? 'Appended MIDI notes.' : 'Updated MIDI notes.');
  }

  Future<_RowLayoutSnapshotAction?> _ensureDedicatedOutputRowBelow({
    required int sourceRow,
  }) async {
    if (sourceRow < 0) return null;
    final targetRow = sourceRow + 1;
    if (targetRow >= _effectiveMaxRows) return null;

    final hasExistingRowBelow = _rowCount > targetRow;
    final rowBelowHasAnyClip =
        hasExistingRowBelow &&
        _audioTracks.any((clip) => clip.rowIndex == targetRow);
    final rowBelowAcceptsAudio =
        hasExistingRowBelow && _rowAllowsClipKind(targetRow, ClipKind.audio);
    if (hasExistingRowBelow && !rowBelowHasAnyClip && rowBelowAcceptsAudio) {
      return null;
    }
    if (!hasExistingRowBelow && _rowCount >= _effectiveMaxRows) {
      return null;
    }

    final before = await _captureRowLayoutSnapshot();
    final inserted = await _insertRowBelowImpl(sourceRow);
    if (!inserted) return null;
    final after = await _captureRowLayoutSnapshot();
    if (after.rows.length == before.rows.length) return null;

    return _RowLayoutSnapshotAction(
      descriptionText: 'Insert output row',
      before: before,
      after: after,
      applySnapshot: _applyRowLayoutSnapshot,
    );
  }

  Future<void> _convertAudioClipToMidi(
    int sourceClipIndex,
    Map<String, dynamic> data,
    Map<String, dynamic> target,
    int? chatFlowId,
  ) async {
    final sourceClip = _audioTracks[sourceClipIndex];
    if (sourceClip.isMidi) {
      _insertAssistantChatText('Audio-to-MIDI only works on audio clips.');
      return;
    }

    final sourceRow = sourceClip.rowIndex;
    if (sourceRow < 0 || sourceRow >= _effectiveMaxRows) {
      _insertAssistantChatText(
        'I need an available row below that clip to place the MIDI result.',
      );
      return;
    }

    _showSmallNotice('Converting audio to MIDI...');
    final notes = await _transcribeAudioClipToMidiNotes(sourceClip);
    if (chatFlowId != null) {
      _throwIfChatFlowStopped(chatFlowId);
    }
    if (notes.isEmpty) {
      _insertAssistantChatText(
        "I couldn't extract stable notes from that audio clip.",
      );
      return;
    }

    final defaultInstrumentId = _preferredAiInstrumentIdForNewMidiClip(
      data,
      target,
      'convert_audio_to_midi',
      notes,
    );
    final instrumentId = _resolveAiInstrumentIdFromActionData(
      data,
      target,
      defaultInstrumentId,
    );
    final instrumentName =
        (data['instrument_name'] ??
                target['instrument_name'] ??
                _instrumentNameFromId(instrumentId))
            .toString()
            .trim();
    final clipLabel = (data['label']?.toString().trim().isNotEmpty ?? false)
        ? data['label'].toString().trim()
        : sourceClip.label.trim().isEmpty
        ? 'Audio to MIDI'
        : '${sourceClip.label} MIDI';
    final startMs = _clipTimelineStartMs(sourceClip);

    final rowLayoutAction = await _ensureDedicatedOutputRowBelow(
      sourceRow: sourceRow,
    );
    if (_rowCount <= sourceRow + 1) {
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _insertAssistantChatText(
        'I could not create a dedicated row below that clip for the MIDI result.',
      );
      return;
    }
    final targetRow = (sourceRow + 1).clamp(0, _rowCount - 1).toInt();
    final addMidiAction = AddMidiClipAction(
      addMidiClip:
          ({
            required String instrumentId,
            required String instrumentName,
            required Map<String, double> instrumentParams,
            required List<MidiNote> midiNotes,
            required int row,
            required double timeMs,
            Duration? trimEndRequested,
          }) => _addMidiTrack(
            instrumentId: instrumentId,
            instrumentName: instrumentName,
            instrumentParams: _instrumentParamsFromSpec(
              _instrumentSpecById(instrumentId),
            ),
            midiNotes: midiNotes,
            row: row,
            timeMs: timeMs,
            trimEndRequested: trimEndRequested,
            label: clipLabel,
          ),
      tracks: _audioTracks,
      restoreTrack: _addClipFromUndoPayload,
      instrumentId: instrumentId,
      instrumentName: instrumentName.isEmpty
          ? _instrumentNameFromId(instrumentId)
          : instrumentName,
      instrumentParams: _instrumentParamsFromSpec(
        _instrumentSpecById(instrumentId),
      ),
      midiNotes: notes,
      row: targetRow,
      timeMs: startMs,
      onRemove: _syncRemovedClipFadesAfterUndo,
    );

    try {
      final beforeCount = _audioTracks.length;
      await _undoManager.executeWithoutAdd(addMidiAction);
      final added = _audioTracks.length == beforeCount + 1;
      if (!added) {
        throw StateError('Failed to add audio-to-MIDI clip.');
      }

      if (rowLayoutAction != null) {
        await _undoManager.addWithoutExecute(
          CompoundUndoAction('Convert audio to MIDI', <EditorUndoAction>[
            rowLayoutAction,
            addMidiAction,
          ]),
        );
      } else {
        await _undoManager.addWithoutExecute(addMidiAction);
      }
      _showSmallNotice('Created MIDI clip below the source audio.');
    } catch (error) {
      debugPrint('Audio-to-MIDI conversion failed: $error');
      await addMidiAction.undo();
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _insertAssistantChatText(
        "I couldn't place the MIDI clip for that audio.",
      );
    }
  }

  int? _pickPitchLabTargetClipIndex({required bool midi}) {
    final candidates = <int>[];
    void add(int index) {
      if (index < 0 || index >= _audioTracks.length) return;
      final clip = _audioTracks[index];
      if (midi != clip.isMidi) return;
      if (!candidates.contains(index)) candidates.add(index);
    }

    add(_timelinePrimarySelectedClipIndex);
    for (final index in _timelineSelectedClipIndices) {
      add(index);
    }
    return _pickPreferredClipIndex(candidates);
  }

  Future<void> _openPitchLabFromCurrentSelection() async {
    final audioIndex = _pickPitchLabTargetClipIndex(midi: false);
    if (audioIndex != null) {
      await _openAudioPitchLabForClip(audioIndex);
      return;
    }

    final midiIndex = _pickPitchLabTargetClipIndex(midi: true);
    if (midiIndex != null) {
      _openPitchLabEditor(midiIndex);
      return;
    }

    _showSmallNotice(
      L10n.translate(
        context,
        'Select an audio clip first, then open Pitch Lab.',
      ),
    );
  }

  Future<void> _openAudioPitchLabForClip(int sourceClipIndex) async {
    if (sourceClipIndex < 0 || sourceClipIndex >= _audioTracks.length) return;
    final sourceClip = _audioTracks[sourceClipIndex];
    if (sourceClip.isMidi) {
      _openPitchLabEditor(sourceClipIndex);
      return;
    }

    final sourceRow = sourceClip.rowIndex;
    if (sourceRow < 0 || sourceRow >= _effectiveMaxRows) {
      _showSmallNotice(
        L10n.translate(
          context,
          'Select an audio clip on a timeline row first.',
        ),
      );
      return;
    }

    if (_pitchLabAudioAnalyzing) return;
    if (sourceClip.normWaveformData.isEmpty) {
      _startWaveformExtraction(sourceClip);
    }
    unawaited(_stopPitchLabAudioPreview(deleteFile: true));
    setState(() {
      _pitchLabAudioAnalyzing = true;
      _pitchLabAudioRendering = false;
      _pitchLabAudioPreviewRendering = false;
      _pitchLabAudioPreviewFile = null;
      _pitchLabAudioMode = true;
      _activePitchLabSourceAudioEngineId = sourceClip.engineClipId;
      _activePitchLabSourceAudioIndex = sourceClipIndex;
      _activePitchLabClipEngineId = null;
      _activePitchLabClipIndex = null;
      _showPitchLab = false;
      _showPianoRoll = false;
      _pianoRollFullscreen = false;
    });

    try {
      final notes = await _transcribeAudioClipToMidiNotes(sourceClip);
      if (!mounted) return;
      if (notes.isEmpty) {
        setState(() {
          _pitchLabAudioAnalyzing = false;
          _pitchLabAudioMode = false;
          _activePitchLabSourceAudioEngineId = null;
          _activePitchLabSourceAudioIndex = null;
          _pitchLabAudioOriginalNotes = <MidiNote>[];
          _pitchLabAudioDraftNotes = <MidiNote>[];
        });
        _showSmallNotice(
          L10n.translate(
            context,
            'Could not extract stable notes from this clip.',
          ),
        );
        return;
      }

      setState(() {
        if (_rowCount > 0) {
          _selectedRow = sourceClip.rowIndex.clamp(0, _rowCount - 1).toInt();
        }
        _pitchLabAudioAnalyzing = false;
        _pitchLabAudioMode = true;
        _activePitchLabSourceAudioEngineId = sourceClip.engineClipId;
        _activePitchLabSourceAudioIndex = sourceClipIndex;
        _pitchLabAudioOriginalNotes = notes
            .map((note) => note.copy())
            .toList(growable: false);
        _pitchLabAudioDraftNotes = notes
            .map((note) => note.copy())
            .toList(growable: false);
        _showPitchLab = true;
        _showPianoRoll = false;
        _pianoRollFullscreen = false;
      });
      _setDawPanelVisible('pitch_lab', true);
      _setDawPanelVisible('piano_roll', false);
      _syncMeterPollingForVisibility();
      _recordProducerManualEdit('open_audio_pitch_lab', {
        'source_clip_id': sourceClip.clipId,
        'note_count': notes.length,
      });
    } catch (error, stackTrace) {
      debugPrint('Audio Pitch Lab analysis failed: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      if (!mounted) return;
      setState(() {
        _pitchLabAudioAnalyzing = false;
        _pitchLabAudioMode = false;
        _activePitchLabSourceAudioEngineId = null;
        _activePitchLabSourceAudioIndex = null;
        _pitchLabAudioOriginalNotes = <MidiNote>[];
        _pitchLabAudioDraftNotes = <MidiNote>[];
      });
      _showSmallNotice(L10n.translate(context, 'Could not analyze this clip.'));
    }
  }

  double _pitchLabMsPerBeat() => 60000.0 / _clampTempo(_tempo);

  ({double startMs, double endMs}) _pitchLabNoteLocalRangeMs(MidiNote note) {
    final msPerBeat = _pitchLabMsPerBeat();
    final startMs = math.max(0.0, note.startBeat * msPerBeat);
    final endMs = math.max(
      startMs + 8.0,
      startMs + math.max(0.03125, note.lengthBeats) * msPerBeat,
    );
    return (startMs: startMs, endMs: endMs);
  }

  bool _pitchLabNoteChanged(MidiNote original, MidiNote edited) {
    final originalRange = _pitchLabNoteLocalRangeMs(original);
    final editedRange = _pitchLabNoteLocalRangeMs(edited);
    return original.pitch != edited.pitch ||
        (originalRange.startMs - editedRange.startMs).abs() > 4.0 ||
        (originalRange.endMs - editedRange.endMs).abs() > 4.0 ||
        (original.velocity - edited.velocity).abs() > 0.02;
  }

  double _pitchLabSourceActiveDurationMs(AudioTrack clip) {
    final raw = (clip.trimEnd - clip.trimStart).inMilliseconds.toDouble();
    return raw.clamp(1.0, double.infinity).toDouble();
  }

  String _pitchLabSafeRenderStem(AudioTrack clip) {
    final label = clip.label.trim().isNotEmpty
        ? clip.label.trim()
        : _displayStemForFilePath(clip.file.path);
    final safe = label
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_|_$'), '');
    return safe.isEmpty ? 'pitch_lab_render' : '${safe}_pitch_lab';
  }

  Future<File> _nextPitchLabRenderFile(AudioTrack clip) async {
    final audioDir = ProjectManager.audioDir(_projectDir);
    if (!await audioDir.exists()) {
      await audioDir.create(recursive: true);
    }
    final stem = _pitchLabSafeRenderStem(clip);
    final stamp = DateTime.now().millisecondsSinceEpoch;
    for (int i = 0; i < 1000; i++) {
      final suffix = i == 0 ? '' : '_$i';
      final file = File(p.join(audioDir.path, '${stem}_$stamp$suffix.wav'));
      if (!file.existsSync() &&
          !_audioTracks.any((track) => track.file.path == file.path)) {
        return file;
      }
    }
    return File(p.join(audioDir.path, '${stem}_${stamp}_final.wav'));
  }

  Future<({File file, Duration duration})?> _renderPitchLabAudioToProjectFile({
    required AudioTrack sourceClip,
    required List<MidiNote> originalNotes,
    required List<MidiNote> editedNotes,
  }) async {
    if (sourceClip.isMidi || !sourceClip.file.existsSync()) return null;
    if (originalNotes.isEmpty) return null;

    final editedById = <String, MidiNote>{
      for (final note in editedNotes) note.id: note,
    };
    final changedPairs = <({MidiNote original, MidiNote edited})>[];
    final changedOriginalRanges = <MapEntry<double, double>>[];

    for (final original in originalNotes) {
      final edited = editedById[original.id];
      final originalRange = _pitchLabNoteLocalRangeMs(original);
      if (edited == null) {
        changedOriginalRanges.add(
          MapEntry(originalRange.startMs, originalRange.endMs),
        );
        continue;
      }
      if (!_pitchLabNoteChanged(original, edited)) continue;
      changedPairs.add((original: original, edited: edited));
      changedOriginalRanges.add(
        MapEntry(originalRange.startMs, originalRange.endMs),
      );
    }

    if (changedPairs.isEmpty && changedOriginalRanges.isEmpty) {
      return null;
    }

    final sourceTimelineDurationMs = _clipTimelineDurationMs(
      sourceClip,
    ).clamp(1.0, 12.0 * 60.0 * 1000.0).toDouble();
    var outputDurationMs = sourceTimelineDurationMs;
    for (final pair in changedPairs) {
      final editedRange = _pitchLabNoteLocalRangeMs(pair.edited);
      outputDurationMs = math.max(outputDurationMs, editedRange.endMs + 20.0);
    }
    outputDurationMs = outputDurationMs
        .clamp(50.0, 12.0 * 60.0 * 1000.0)
        .toDouble();

    final suppressedRanges = _mergeTimelineRangesMs(
      changedOriginalRanges,
      minGapMs: 6.0,
      minLengthMs: 8.0,
      minMs: 0.0,
      maxMs: sourceTimelineDurationMs,
    );
    final outputFile = await _nextPitchLabRenderFile(sourceClip);
    final renderSegments = <Map<String, double>>[];
    for (final pair in changedPairs.take(160)) {
      final originalRange = _pitchLabNoteLocalRangeMs(pair.original);
      final editedRange = _pitchLabNoteLocalRangeMs(pair.edited);
      renderSegments.add(<String, double>{
        'originalStartMs': originalRange.startMs,
        'originalEndMs': originalRange.endMs,
        'targetStartMs': editedRange.startMs,
        'targetEndMs': editedRange.endMs,
        'semitones': (pair.edited.pitch - pair.original.pitch).toDouble(),
      });
    }

    final renderedPath = await JuceAudioEngine.renderPitchLabAudio(
      sourcePath: sourceClip.file.path,
      outPath: outputFile.path,
      trimStartMs: sourceClip.trimStart.inMilliseconds.toDouble(),
      trimEndMs: sourceClip.trimEnd.inMilliseconds.toDouble(),
      sourceTimelineDurationMs: sourceTimelineDurationMs,
      outputDurationMs: outputDurationMs,
      suppressedRanges: suppressedRanges
          .map(
            (range) => <String, double>{
              'startMs': range.key,
              'endMs': range.value,
            },
          )
          .toList(growable: false),
      segments: renderSegments,
    );
    if (renderedPath == null ||
        renderedPath.trim().isEmpty ||
        !outputFile.existsSync()) {
      debugPrint(
        'Pitch Lab native render failed for ${p.basename(sourceClip.file.path)}',
      );
      return null;
    }

    return (
      file: outputFile,
      duration: Duration(milliseconds: outputDurationMs.round()),
    );
  }

  Future<void> _applyPitchLabAudioRender(
    int sourceClipIndex,
    List<MidiNote> editedNotes,
  ) async {
    if (_pitchLabAudioRendering) return;
    if (sourceClipIndex < 0 || sourceClipIndex >= _audioTracks.length) return;
    final sourceClip = _audioTracks[sourceClipIndex];
    if (sourceClip.isMidi) return;
    if (_pitchLabAudioOriginalNotes.isEmpty) {
      _showSmallNotice(
        L10n.translate(context, 'No notes are ready to render.'),
      );
      return;
    }

    setState(() => _pitchLabAudioRendering = true);
    try {
      _showSmallNotice(L10n.translate(context, 'Rendering tuned audio...'));
      final rendered = await _renderPitchLabAudioToProjectFile(
        sourceClip: sourceClip,
        originalNotes: _pitchLabAudioOriginalNotes,
        editedNotes: editedNotes,
      );
      if (!mounted) return;
      if (rendered == null) {
        _showSmallNotice(
          L10n.translate(context, 'No pitch or timing changes to render.'),
        );
        return;
      }
      await _insertPitchLabRenderedClip(
        sourceClip: sourceClip,
        renderedFile: rendered.file,
        renderedDuration: rendered.duration,
      );
      _recordProducerManualEdit('render_audio_pitch_lab', {
        'source_clip_id': sourceClip.clipId,
        'note_count': editedNotes.length,
        'rendered_file': p.basename(rendered.file.path),
      });
      _showSmallNotice(
        L10n.translate(context, 'Rendered tuned clip below the source.'),
      );
    } catch (error, stackTrace) {
      debugPrint('Pitch Lab audio render failed: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      if (mounted) {
        _showSmallNotice(
          L10n.translate(context, 'Could not render the tuned clip.'),
        );
      }
    } finally {
      if (mounted) {
        setState(() => _pitchLabAudioRendering = false);
      }
    }
  }

  bool get _pitchLabAudioPreviewPlaying {
    final file = _pitchLabAudioPreviewFile;
    return file != null &&
        _samplePreviewPlayer.playing &&
        _auditioningSamplePath == file.path;
  }

  bool get _pitchLabAudioPreviewReady {
    final file = _pitchLabAudioPreviewFile;
    return file != null && _auditioningSamplePath == file.path;
  }

  Future<void> _pausePitchLabAudioPreview() async {
    final file = _pitchLabAudioPreviewFile;
    if (file == null || _auditioningSamplePath != file.path) return;
    await _samplePreviewPlayer.pause();
    if (mounted) {
      setState(() => _samplePreviewPlaying = false);
    } else {
      _samplePreviewPlaying = false;
    }
  }

  Future<void> _resumePitchLabAudioPreview() async {
    final file = _pitchLabAudioPreviewFile;
    if (file == null || _auditioningSamplePath != file.path) return;
    await _samplePreviewPlayer.play();
    if (mounted) {
      setState(() => _samplePreviewPlaying = true);
    } else {
      _samplePreviewPlaying = true;
    }
  }

  Future<void> _stopPitchLabAudioPreview({bool deleteFile = false}) async {
    final file = _pitchLabAudioPreviewFile;
    if (file == null) return;
    if (_auditioningSamplePath == file.path) {
      await _samplePreviewPlayer.stop();
      await _samplePreviewPlayer.seek(Duration.zero);
      if (mounted) {
        setState(() {
          _auditioningSamplePath = null;
          _samplePreviewPlaying = false;
        });
      } else {
        _auditioningSamplePath = null;
        _samplePreviewPlaying = false;
      }
    }
    if (deleteFile) {
      try {
        if (await file.exists()) {
          await file.delete();
        }
      } catch (_) {}
      if (_pitchLabAudioPreviewFile?.path == file.path) {
        _pitchLabAudioPreviewFile = null;
      }
    }
  }

  Future<void> _previewPitchLabAudioRender(
    int sourceClipIndex,
    List<MidiNote> editedNotes,
  ) async {
    if (_pitchLabAudioPreviewRendering || _pitchLabAudioRendering) return;
    if (sourceClipIndex < 0 || sourceClipIndex >= _audioTracks.length) return;
    final sourceClip = _audioTracks[sourceClipIndex];
    if (sourceClip.isMidi) return;
    if (_pitchLabAudioOriginalNotes.isEmpty) {
      _showSmallNotice(
        L10n.translate(context, 'No notes are ready to preview.'),
      );
      return;
    }

    setState(() => _pitchLabAudioPreviewRendering = true);
    try {
      await _stopPitchLabAudioPreview(deleteFile: true);
      final rendered = await _renderPitchLabAudioToProjectFile(
        sourceClip: sourceClip,
        originalNotes: _pitchLabAudioOriginalNotes,
        editedNotes: editedNotes,
      );
      if (!mounted) return;
      if (rendered == null) {
        _showSmallNotice(
          L10n.translate(context, 'No pitch or timing changes to preview.'),
        );
        return;
      }

      await _pausePlayback();
      await _samplePreviewPlayer.setFilePath(rendered.file.path);
      if (!mounted) return;
      setState(() {
        _pitchLabAudioPreviewFile = rendered.file;
        _auditioningSamplePath = rendered.file.path;
      });
      await _samplePreviewPlayer.play();
      if (mounted) {
        setState(() => _samplePreviewPlaying = true);
      }
    } catch (error, stackTrace) {
      debugPrint('Pitch Lab audio preview failed: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      if (mounted) {
        _showSmallNotice(
          L10n.translate(context, 'Could not preview the tuned clip.'),
        );
      }
    } finally {
      if (mounted) {
        setState(() => _pitchLabAudioPreviewRendering = false);
      } else {
        _pitchLabAudioPreviewRendering = false;
      }
    }
  }

  Future<void> _previewPitchLabAudioNote(
    int sourceClipIndex,
    MidiNote editedNote,
  ) async {
    if (_pitchLabAudioPreviewRendering || _pitchLabAudioRendering) return;
    if (sourceClipIndex < 0 || sourceClipIndex >= _audioTracks.length) return;
    final sourceClip = _audioTracks[sourceClipIndex];
    if (sourceClip.isMidi || !sourceClip.file.existsSync()) return;

    MidiNote originalNote = editedNote;
    for (final candidate in _pitchLabAudioOriginalNotes) {
      if (candidate.id == editedNote.id) {
        originalNote = candidate;
        break;
      }
    }

    final originalRange = _pitchLabNoteLocalRangeMs(originalNote);
    final editedRange = _pitchLabNoteLocalRangeMs(editedNote);
    final sourceTimelineDurationMs = _clipTimelineDurationMs(
      sourceClip,
    ).clamp(1.0, 12.0 * 60.0 * 1000.0).toDouble();
    final sourceStartMs = originalRange.startMs
        .clamp(0.0, sourceTimelineDurationMs)
        .toDouble();
    final sourceEndMs = originalRange.endMs
        .clamp(sourceStartMs + 8.0, sourceTimelineDurationMs)
        .toDouble();
    if (sourceEndMs <= sourceStartMs + 1.0) return;

    final noteDurationMs = (editedRange.endMs - editedRange.startMs)
        .clamp(60.0, 5000.0)
        .toDouble();
    final outputDurationMs = (noteDurationMs + 90.0)
        .clamp(90.0, 12.0 * 60.0 * 1000.0)
        .toDouble();
    final outputFile = await _nextPitchLabRenderFile(sourceClip);

    try {
      await _stopPitchLabAudioPreview(deleteFile: true);
      final renderedPath = await JuceAudioEngine.renderPitchLabAudio(
        sourcePath: sourceClip.file.path,
        outPath: outputFile.path,
        trimStartMs: sourceClip.trimStart.inMilliseconds.toDouble(),
        trimEndMs: sourceClip.trimEnd.inMilliseconds.toDouble(),
        sourceTimelineDurationMs: sourceTimelineDurationMs,
        outputDurationMs: outputDurationMs,
        suppressedRanges: <Map<String, double>>[
          <String, double>{'startMs': 0.0, 'endMs': sourceTimelineDurationMs},
        ],
        segments: <Map<String, double>>[
          <String, double>{
            'originalStartMs': sourceStartMs,
            'originalEndMs': sourceEndMs,
            'targetStartMs': 0.0,
            'targetEndMs': noteDurationMs,
            'semitones': (editedNote.pitch - originalNote.pitch).toDouble(),
          },
        ],
      );
      if (!mounted) return;
      if (renderedPath == null ||
          renderedPath.trim().isEmpty ||
          !outputFile.existsSync()) {
        return;
      }

      await _pausePlayback();
      await _samplePreviewPlayer.setFilePath(outputFile.path);
      if (!mounted) return;
      setState(() {
        _pitchLabAudioPreviewFile = outputFile;
        _auditioningSamplePath = outputFile.path;
      });
      await _samplePreviewPlayer.play();
      if (mounted) {
        setState(() => _samplePreviewPlaying = true);
      }
    } catch (error, stackTrace) {
      debugPrint('Pitch Lab note preview failed: $error');
      unawaited(
        CrashReportingService.instance.captureException(
          error,
          stackTrace: stackTrace,
        ),
      );
      try {
        if (await outputFile.exists()) {
          await outputFile.delete();
        }
      } catch (_) {}
    }
  }

  Future<void> _insertPitchLabRenderedClip({
    required AudioTrack sourceClip,
    required File renderedFile,
    required Duration renderedDuration,
  }) async {
    final sourceRow = sourceClip.rowIndex;
    if (sourceRow < 0 || sourceRow >= _effectiveMaxRows) {
      _showSmallNotice('Could not resolve a row for the rendered clip.');
      return;
    }

    final rowLayoutAction = await _ensureDedicatedOutputRowBelow(
      sourceRow: sourceRow,
    );
    if (_rowCount <= sourceRow + 1) {
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _showSmallNotice('Could not create a row for the rendered clip.');
      return;
    }

    final targetRow = (sourceRow + 1).clamp(0, _rowCount - 1).toInt();
    if (!_rowAllowsClipKind(targetRow, ClipKind.audio)) {
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _showSmallNotice('Rendered audio needs an audio lane.');
      return;
    }

    final sourceLabel = sourceClip.label.trim().isNotEmpty
        ? sourceClip.label.trim()
        : _displayStemForFilePath(sourceClip.file.path);
    final renderedLabel = '$sourceLabel Tuned';
    final startMs = _clipTimelineStartMs(sourceClip);
    final addAction = AddAudioTrackAction(
      addTrack:
          ({
            required File file,
            required int row,
            required double timeMs,
            Duration? trimStartRequested,
            Duration? trimEndRequested,
          }) => _addAudioTrackFromProjectFile(
            projectAudioFile: file,
            label: renderedLabel,
            row: row,
            timeMs: timeMs,
            trimStartRequested: trimStartRequested,
            trimEndRequested: trimEndRequested,
            gain: sourceClip.gain,
            normalizeVolume: false,
            pitchSemitones: 0.0,
            isReversed: false,
            sourceTempoBpm: _clampTempo(_tempo),
            stretchToProjectTempo: false,
            tempoStretchPreservePitch: true,
            tempoWarpMode: sourceClip.tempoWarpMode,
            crossfade: sourceClip.crossfade,
            rowAlreadyEnsured: true,
            assumeFreshEngineDefaults: true,
          ),
      tracks: _audioTracks,
      restoreTrack: _addClipFromUndoPayload,
      file: renderedFile,
      row: targetRow,
      timeMs: startMs,
      trimStart: Duration.zero,
      trimEnd: renderedDuration,
      onRemove: _syncRemovedClipFadesAfterUndo,
    );

    try {
      final beforeCount = _audioTracks.length;
      await _undoManager.executeWithoutAdd(addAction);
      final added = _audioTracks.length == beforeCount + 1;
      if (!added) {
        throw StateError('Failed to add rendered Pitch Lab clip.');
      }

      if (rowLayoutAction != null) {
        await _undoManager.addWithoutExecute(
          CompoundUndoAction('Render Pitch Lab audio', <EditorUndoAction>[
            rowLayoutAction,
            addAction,
          ]),
        );
      } else {
        await _undoManager.addWithoutExecute(addAction);
      }

      final renderedIndex = _audioTracks.length - 1;
      if (mounted) {
        setState(() {
          _timelineSelectedClipIndices = <int>[renderedIndex];
          _timelinePrimarySelectedClipIndex = renderedIndex;
          _selectedRow = targetRow;
        });
      }
    } catch (error) {
      debugPrint('Pitch Lab rendered clip insertion failed: $error');
      await addAction.undo();
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _showSmallNotice('Could not place the rendered clip on the timeline.');
    }
  }

  String _safeSamplerStem({required String label, required String identity}) {
    final safeLabel = label
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_|_$'), '');
    final base = safeLabel.isEmpty ? 'sample' : safeLabel;
    final idToken = identity
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_|_$'), '');
    return idToken.isEmpty ? 'sampler_$base' : 'sampler_${base}_$idToken';
  }

  Future<File?> _buildSamplerSfzFromSource({
    required File sourceFile,
    required String label,
    required String identity,
    Duration trimStart = Duration.zero,
    Duration? trimDuration,
  }) async {
    if (!sourceFile.existsSync()) return null;

    final audioDir = ProjectManager.audioDir(_projectDir);
    if (!await audioDir.exists()) {
      await audioDir.create(recursive: true);
    }

    final stem = _safeSamplerStem(label: label, identity: identity);
    final sampleFile = File(p.join(audioDir.path, '$stem.wav'));
    final sfzFile = File(p.join(audioDir.path, '$stem.sfz'));
    final trimStartSec = math.max(0.0, trimStart.inMilliseconds / 1000.0);
    final trimArg = trimStartSec > 0.0
        ? '-ss ${trimStartSec.toStringAsFixed(3)} '
        : '';
    final trimDurationArg = trimDuration == null
        ? ''
        : '-t ${math.max(0.05, trimDuration.inMilliseconds / 1000.0).toStringAsFixed(3)} ';

    await FFmpegKit.execute(
      '$trimArg'
      '-i "${sourceFile.path}" '
      '$trimDurationArg'
      '-ar 48000 -ac 2 -y "${sampleFile.path}"',
    );
    if (!sampleFile.existsSync()) {
      return null;
    }

    final sampleName = p.basename(sampleFile.path);
    final sfz = StringBuffer()
      ..writeln('<global> ampeg_attack=0.002 ampeg_release=0.320')
      ..writeln(
        '<region> sample=$sampleName lokey=0 hikey=127 pitch_keycenter=60 lovel=0 hivel=127 volume=0',
      );
    await sfzFile.writeAsString(sfz.toString());
    return sfzFile.existsSync() ? sfzFile : null;
  }

  Future<File?> _buildSamplerSfzForAudioClip(AudioTrack clip) async {
    if (clip.isMidi) return null;
    final label = clip.label.trim().isNotEmpty
        ? clip.label.trim()
        : _displayStemForFilePath(clip.file.path);
    return _buildSamplerSfzFromSource(
      sourceFile: clip.file,
      label: label,
      identity: clip.clipId,
      trimStart: clip.trimStart,
      trimDuration: clip.trimEnd - clip.trimStart,
    );
  }

  List<MidiNote> _samplerTriggerNotesForDurationMs(double durationMs) {
    final beatMs = 60000.0 / _clampTempo(_tempo);
    final lengthBeats = (durationMs / beatMs).clamp(0.125, 64.0).toDouble();
    return <MidiNote>[
      MidiNote(
        id: 'sampler_note_${DateTime.now().microsecondsSinceEpoch}',
        pitch: 60,
        startBeat: 0.0,
        lengthBeats: lengthBeats,
        velocity: 0.92,
      ),
    ];
  }

  List<MidiNote> _samplerTriggerNotesForClip(AudioTrack clip) {
    return _samplerTriggerNotesForDurationMs(_clipTimelineDurationMs(clip));
  }

  bool _isSamplerClip(AudioTrack clip) {
    if (!clip.isMidi) return false;
    final instrumentId = clip.instrumentId.trim().toLowerCase();
    final instrumentName = clip.instrumentName.trim().toLowerCase();
    return instrumentId.startsWith('sfz_asset:') &&
        instrumentName.endsWith('sampler');
  }

  bool _canReplaceSamplerSource(int clipIndex) {
    return clipIndex >= 0 &&
        clipIndex < _audioTracks.length &&
        _isSamplerClip(_audioTracks[clipIndex]);
  }

  bool _looksLikeDefaultSamplerTrigger(AudioTrack clip) {
    if (clip.midiNotes.length != 1) return false;
    final note = clip.midiNotes.first;
    return note.pitch == 60 &&
        note.startBeat.abs() <= 0.00001 &&
        (note.velocity - 0.92).abs() <= 0.02;
  }

  Map<String, double> _samplerParamsForSourceReplacement(AudioTrack clip) {
    return _samplerParamsForSource(base: clip.instrumentParams);
  }

  Map<String, double> _samplerParamsForSource({Map<String, double>? base}) {
    final params = <String, double>{if (base != null) ...base};
    params.putIfAbsent('attackMs', () => 2.0);
    params.putIfAbsent('decayMs', () => 120.0);
    params.putIfAbsent('sustainLevel', () => 0.86);
    params.putIfAbsent('releaseMs', () => 320.0);
    params.putIfAbsent('outputGain', () => 0.72);
    params['sampleStartNorm'] = 0.0;
    params['sampleEndNorm'] = 1.0;
    params.putIfAbsent('reverseSample', () => 0.0);
    params.putIfAbsent('normalizeSample', () => 0.0);
    params.putIfAbsent('samplePlayMode', () => 0.0);
    params.putIfAbsent('rootNote', () => 60.0);
    params.putIfAbsent('sampleLowKey', () => 0.0);
    params.putIfAbsent('sampleHighKey', () => 127.0);
    params.putIfAbsent('sliceMode', () => 0.0);
    params.putIfAbsent('sliceCount', () => 8.0);
    params.putIfAbsent('timeStretchMode', () => 0.0);
    params.putIfAbsent('sampleFilterCutoffHz', () => 20000.0);
    params['granularMode'] = 0.0;
    params['drive'] = 0.0;
    params['noise'] = 0.0;
    return params;
  }

