  Future<void> _createSamplerFromAudioClip(int sourceClipIndex) async {
    if (sourceClipIndex < 0 || sourceClipIndex >= _audioTracks.length) return;
    final sourceClip = _audioTracks[sourceClipIndex];
    if (sourceClip.isMidi) return;

    final sourceRow = sourceClip.rowIndex;
    if (sourceRow < 0 || sourceRow >= _effectiveMaxRows) {
      _showSmallNotice('Select an audio clip on a timeline row first.');
      return;
    }

    _showSmallNotice('Creating sampler...');
    final sfzFile = await _buildSamplerSfzForAudioClip(sourceClip);
    if (sfzFile == null) {
      _showSmallNotice('Could not prepare this clip for sampler playback.');
      return;
    }

    final rowLayoutAction = await _ensureDedicatedOutputRowBelow(
      sourceRow: sourceRow,
    );
    if (_rowCount <= sourceRow + 1) {
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _showSmallNotice('Could not create a row for the sampler clip.');
      return;
    }

    final instrumentId = 'sfz_asset:${sfzFile.path}';
    final sourceLabel = sourceClip.label.trim().isNotEmpty
        ? sourceClip.label.trim()
        : _displayStemForFilePath(sourceClip.file.path);
    final instrumentName = '$sourceLabel Sampler';
    final targetRow = (sourceRow + 1).clamp(0, _rowCount - 1).toInt();
    final startMs = _clipTimelineStartMs(sourceClip);
    final notes = _samplerTriggerNotesForClip(sourceClip);
    final params = <String, double>{
      'attackMs': 2.0,
      'decayMs': 120.0,
      'sustainLevel': 0.86,
      'releaseMs': 320.0,
      'outputGain': 0.72,
      'sampleStartNorm': 0.0,
      'sampleEndNorm': 1.0,
      'reverseSample': 0.0,
      'normalizeSample': 0.0,
      'samplePlayMode': 0.0,
      'rootNote': 60.0,
      'sampleLowKey': 0.0,
      'sampleHighKey': 127.0,
      'sliceMode': 0.0,
      'sliceCount': 8.0,
      'timeStretchMode': 0.0,
      'sampleFilterCutoffHz': 20000.0,
    };
    final addMidiAction = AddMidiClipAction(
      addMidiClip:
          ({
            required String instrumentId,
            required String instrumentName,
            required Map<String, double> instrumentParams,
            required List<MidiNote> midiNotes,
            required int row,
            required double timeMs,
            Duration? trimEndRequested,
          }) => _addMidiTrack(
            instrumentId: instrumentId,
            instrumentName: instrumentName,
            instrumentParams: instrumentParams,
            midiNotes: midiNotes,
            row: row,
            timeMs: timeMs,
            trimEndRequested: trimEndRequested,
            label: instrumentName,
          ),
      tracks: _audioTracks,
      restoreTrack: _addClipFromUndoPayload,
      instrumentId: instrumentId,
      instrumentName: instrumentName,
      instrumentParams: params,
      midiNotes: notes,
      row: targetRow,
      timeMs: startMs,
      onRemove: _syncRemovedClipFadesAfterUndo,
    );

    try {
      final beforeCount = _audioTracks.length;
      await _undoManager.executeWithoutAdd(addMidiAction);
      final added = _audioTracks.length == beforeCount + 1;
      if (!added) {
        throw StateError('Failed to add sampler MIDI clip.');
      }

      if (rowLayoutAction != null) {
        await _undoManager.addWithoutExecute(
          CompoundUndoAction('Create sampler', <EditorUndoAction>[
            rowLayoutAction,
            addMidiAction,
          ]),
        );
      } else {
        await _undoManager.addWithoutExecute(addMidiAction);
      }

      final samplerIndex = _audioTracks.length - 1;
      if (mounted) {
        setState(() {
          _timelineSelectedClipIndices = <int>[samplerIndex];
          _timelinePrimarySelectedClipIndex = samplerIndex;
          _selectedRow = targetRow;
        });
      }
      _openMidiClipEditor(samplerIndex);
      _recordProducerManualEdit('create_sampler_from_clip', {
        'source_clip_id': sourceClip.clipId,
        'sampler_clip_index': samplerIndex,
      });
      _showSmallNotice('Sampler ready.');
    } catch (error) {
      debugPrint('Sampler creation failed: $error');
      await addMidiAction.undo();
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      _showSmallNotice('Could not create a sampler from this clip.');
    }
  }

  Future<void> _applyStemSeparateAction(Map<String, dynamic> data) async {
    final target = _actionTarget(data);
    final clipIndices = _resolveClipIndicesFromActionTarget(
      data,
      requireAudio: true,
    );
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
        "I couldn't resolve which audio clip to separate.",
      );
      return;
    }

    final scope = (target['scope'] ?? data['scope'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final explicitMany =
        ((data['clip_indices'] as List?)?.isNotEmpty ?? false) ||
        ((target['clip_indices'] as List?)?.isNotEmpty ?? false) ||
        scope == 'all' ||
        scope == 'all_audio' ||
        scope == 'selected' ||
        scope == 'selection';

    final targets = explicitMany
        ? clipIndices
        : <int>[
            _resolveSingleClipIndexWithFallback(data, requireAudio: true) ??
                clipIndices.first,
          ];

    int success = 0;
    for (final clipIndex in targets) {
      final ok = await _performStemSeparationForClip(
        clipIndex,
        showInlineFailureNotice: !explicitMany,
      );
      if (ok) success++;
    }

    if (success <= 0) {
      if (explicitMany) {
        _showSmallNotice('Stem separation failed for target clips.');
      }
      return;
    }

    if (explicitMany && success > 1) {
      _showSmallNotice('Created stems for $success clips.');
    }
  }

  Future<void> _applyRoleOverrideAction(Map<String, dynamic> data) async {
    final operation = (data['operation'] ?? 'set')
        .toString()
        .trim()
        .toLowerCase();
    final row = _resolveRowIndexFromActionTarget(data);
    if (row == null) {
      _insertAssistantChatText(
        "I couldn't resolve which track role to update.",
      );
      return;
    }

    if (operation == 'clear' ||
        operation == 'remove' ||
        operation == 'unset' ||
        operation == 'delete') {
      final cleared = _chatPipeline.clearRoleOverride(row);
      if (row >= 0 && row < _rows.length) {
        _setStateAndRefreshProjectSettings(() {
          _rows[row] = _rows[row].copyWith(roleOverride: '');
        });
        _scheduleProjectAutosave();
      }
      if (cleared) {
        _showSmallNotice('Cleared role override for ${_rowDisplayName(row)}.');
      } else {
        _showSmallNotice('${_rowDisplayName(row)} had no role override set.');
      }
      return;
    }

    final target = _actionTarget(data);
    final role = (data['role'] ?? target['role'] ?? '').toString().trim();
    if (role.isEmpty) {
      _insertAssistantChatText(
        'I need a role value to apply (vocals, drums, bass, guitar, synth, other).',
      );
      return;
    }

    final applied = _chatPipeline.setRoleOverride(rowIndex: row, role: role);
    if (!applied) {
      _insertAssistantChatText(
        'Unsupported role "$role". Use vocals, drums, bass, guitar, synth, or other.',
      );
      return;
    }

    final roleText = role.toLowerCase().trim();
    if (row >= 0 && row < _rows.length) {
      _setStateAndRefreshProjectSettings(() {
        _rows[row] = _rows[row].copyWith(roleOverride: roleText);
      });
      _scheduleProjectAutosave();
    }
    _showSmallNotice('${_rowDisplayName(row)} role override set to $roleText.');
  }

  Future<void> _applyAudioEnhancementAction(Map<String, dynamic> data) async {
    final operation = (data['operation'] ?? 'phone_mic_cleanup')
        .toString()
        .toLowerCase();
    if (operation != 'phone_mic_cleanup' &&
        operation != 'clean_up_recording' &&
        operation != 'voice_clean' &&
        operation != 'cleanup') {
      _insertAssistantChatText(
        'Unsupported audio enhancement operation "$operation".',
      );
      return;
    }

    var clipIndices = _resolveClipIndicesFromActionTarget(
      data,
      requireAudio: true,
    );
    if (clipIndices.isEmpty && _timelinePrimarySelectedClipIndex >= 0) {
      clipIndices = <int>[_timelinePrimarySelectedClipIndex];
    }
    clipIndices = clipIndices
        .where(
          (index) =>
              index >= 0 &&
              index < _audioTracks.length &&
              !_audioTracks[index].isMidi,
        )
        .toSet()
        .toList(growable: false);
    if (clipIndices.isEmpty) {
      _insertAssistantChatText(
        'Select an audio recording first, then ask me to clean it up.',
      );
      return;
    }

    final targetRows = clipIndices
        .map((index) => _audioTracks[index].rowIndex)
        .where((row) => row >= 0 && row < _rowCount)
        .toSet()
        .toList(growable: false);
    if (targetRows.isEmpty) {
      _insertAssistantChatText("I couldn't resolve which track to clean up.");
      return;
    }

    final actions = <EditorUndoAction>[];
    const cleanupEffects = <String>[
      'EQ Parametric',
      'De-Esser',
      'Dynamic Softener',
      'Compressor',
      'Limiter',
    ];
    for (final row in targetRows) {
      for (final effectName in cleanupEffects) {
        if (!_canUseEffectForCurrentPlan(effectName)) continue;
        final current = await JuceAudioEngine.getTrackEffectsForRow(row);
        final already = current.any(
          (name) => name.trim().toLowerCase() == effectName.toLowerCase(),
        );
        if (already) continue;
        final action = InsertEffectAction(
          row: row,
          pathOrName: effectName,
          onChange: () {
            setState(() {});
            _refreshRowFx(row);
            unawaited(_refreshAutomationTargetsForRow(row));
          },
        );
        await _undoManager.executeWithoutAdd(action);
        actions.add(action);
      }
      actions.addAll(await _ensureAiCanonicalChainOrderOnRow(row));
    }

    for (final index in clipIndices) {
      _audioTracks[index].audioEnhancementPreset = 'phone_mic_cleanup_v1';
    }
    unawaited(_warmAudioEnhancementCacheForClips(clipIndices));
    if (actions.isNotEmpty) {
      await _undoManager.addWithoutExecute(
        CompoundUndoAction('Clean up recording', actions),
      );
    }
    _scheduleProjectAutosave();
    _insertSystemChatText(
      '• Cleaned up ${clipIndices.length == 1 ? _audioTracks[clipIndices.first].label : '${clipIndices.length} recordings'} •',
    );
    _showSmallNotice('Clean Up Recording applied.');
  }

  Future<void> _warmAudioEnhancementCacheForClips(List<int> clipIndices) async {
    if (clipIndices.isEmpty) return;
    final cacheDir = Directory(
      p.join(ProjectManager.audioDir(_projectDir).path, 'enhanced_cache'),
    );
    try {
      if (!await cacheDir.exists()) {
        await cacheDir.create(recursive: true);
      }
    } catch (_) {
      return;
    }

    for (final index in clipIndices) {
      if (index < 0 || index >= _audioTracks.length) continue;
      final clip = _audioTracks[index];
      if (clip.isMidi) continue;
      final sourcePath = clip.file.path;
      final sourceStem = _displayStemForFilePath(sourcePath);
      final outputPath = p.join(
        cacheDir.path,
        '${sourceStem}_${clip.clipId}_phone_mic_cleanup.wav',
      );
      final renderedPath = await JuceAudioEngine.renderEnhancedAudioCache(
        inputPath: sourcePath,
        outputPath: outputPath,
        preset: 'phone_mic_cleanup_v1',
        options: <String, dynamic>{
          'highPassHz': 80.0,
          'gate': true,
          'deEss': true,
          'compress': true,
          'limit': true,
          'normalize': true,
        },
      );
      if (renderedPath.trim().isEmpty) continue;
    }
  }

  Future<void> _handleStemSeparationForClip(int clipIndex) async {
    await _performStemSeparationForClip(clipIndex);
  }

  Future<_RowLayoutSnapshotAction?> _ensureStemOutputRowsBelow({
    required int sourceRow,
    required int stemCount,
  }) async {
    if (sourceRow < 0 || stemCount <= 0) return null;
    final before = await _captureRowLayoutSnapshot();
    var changed = false;

    // Stems must occupy dedicated audio rows directly below the source. Rows
    // can already exist there, but an instrument or occupied audio row cannot
    // accept a generated stem without corrupting the arrangement. Insert a
    // normal audio row in that position and shift existing rows downward.
    for (var offset = 1; offset <= stemCount; offset++) {
      final targetRow = sourceRow + offset;
      final hasUsableRow =
          targetRow < _rowCount &&
          _rowAllowsClipKind(targetRow, ClipKind.audio) &&
          !_audioTracks.any((track) => track.rowIndex == targetRow);
      if (hasUsableRow) continue;
      if (_rowCount >= _effectiveMaxRows ||
          !await _insertRowBelowImpl(targetRow - 1)) {
        await _applyRowLayoutSnapshot(before);
        return null;
      }
      changed = true;
    }

    if (!changed) return null;
    final after = await _captureRowLayoutSnapshot();
    return _RowLayoutSnapshotAction(
      descriptionText: 'Add rows for stem separation',
      before: before,
      after: after,
      applySnapshot: _applyRowLayoutSnapshot,
    );
  }

  Future<bool> _performStemSeparationForClip(
    int clipIndex, {
    bool showInlineFailureNotice = true,
  }) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return false;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) {
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation is only available for audio clips.');
      }
      return false;
    }
    if (_audioTracks.length + 2 > kNumClips) {
      if (showInlineFailureNotice) {
        _showSmallNotice(
          "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
        );
      }
      return false;
    }

    final sourcePath = clip.file.path;
    final source = File(sourcePath);
    if (!source.existsSync()) {
      if (showInlineFailureNotice) {
        _showSmallNotice('Selected clip file was not found.');
      }
      return false;
    }

    final audioDir = ProjectManager.audioDir(_projectDir);
    await audioDir.create(recursive: true);
    final stem = p.basenameWithoutExtension(source.path);
    final ts = DateTime.now().millisecondsSinceEpoch;
    final vocalFile = File(p.join(audioDir.path, '${stem}_vocals_$ts.wav'));
    final instrumentalFile = File(
      p.join(audioDir.path, '${stem}_instrumental_$ts.wav'),
    );

    if (showInlineFailureNotice) {
      _showSmallNotice('Splitting stems...');
    }
    try {
      await _spleeterStemSeparator.separateVocalsInstrumental(
        inputPath: source.path,
        vocalsOutputPath: vocalFile.path,
        instrumentalOutputPath: instrumentalFile.path,
      );
    } catch (e) {
      debugPrint('Spleeter stem separation failed: $e');
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation failed.');
      }
      return false;
    }

    if (!vocalFile.existsSync() || !instrumentalFile.existsSync()) {
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation failed.');
      }
      return false;
    }

    final row = clip.rowIndex;
    const stemCount = 2;
    final rowLimit = _effectiveMaxRows;
    final vocalsRow = math.min(row + 1, rowLimit - 1);
    final instrumentalRow = math.min(row + 2, rowLimit - 1);
    if (row < 0 || row >= rowLimit) {
      if (showInlineFailureNotice) {
        _showSmallNotice(
          'Stem separation needs an available track in this project.',
        );
      }
      return false;
    }

    final rowLayoutAction = instrumentalRow > row
        ? await _ensureStemOutputRowsBelow(
            sourceRow: row,
            stemCount: math.min(stemCount, instrumentalRow - row),
          )
        : null;
    final hasStemOutputRows =
        vocalsRow < _rowCount &&
        instrumentalRow < _rowCount &&
        _rowAllowsClipKind(vocalsRow, ClipKind.audio) &&
        _rowAllowsClipKind(instrumentalRow, ClipKind.audio) &&
        !_audioTracks.any((track) => track.rowIndex == vocalsRow) &&
        !_audioTracks.any((track) => track.rowIndex == instrumentalRow);
    if (!hasStemOutputRows) {
      if (showInlineFailureNotice) {
        _showSmallNotice(
          'Could not create compatible audio rows for the separated stems.',
        );
      }
      return false;
    }

    final startMs = clip.offset * 1000.0;
    final trimStart = clip.trimStart;
    final trimEnd = clip.trimEnd;

    final addVocals = AddAudioTrackAction(
      addTrack:
          ({
            required File file,
            required int row,
            required double timeMs,
            Duration? trimStartRequested,
            Duration? trimEndRequested,
          }) => _addAudioTrackFromProjectFile(
            projectAudioFile: file,
            label: clip.label.trim().isEmpty
                ? 'Vocals Stem'
                : '${clip.label} (Vocals)',
            row: row,
            timeMs: timeMs,
            trimStartRequested: trimStartRequested,
            trimEndRequested: trimEndRequested,
            gain: clip.gain,
            normalizeVolume: clip.normalizeVolume,
            normalizeGain: clip.normalizeGain,
            preNormalizeGain: clip.preNormalizeGain,
            sourceTempoBpm: clip.sourceTempoBpm,
            stretchToProjectTempo: clip.stretchToProjectTempo,
            tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
            tempoWarpMode: clip.tempoWarpMode,
          ),
      tracks: _audioTracks,
      restoreTrack: _addClipFromUndoPayload,
      file: vocalFile,
      row: vocalsRow,
      timeMs: startMs,
      trimStart: trimStart,
      trimEnd: trimEnd,
      onRemove: _syncRemovedClipFadesAfterUndo,
    );

    final addInstrumental = AddAudioTrackAction(
      addTrack:
          ({
            required File file,
            required int row,
            required double timeMs,
            Duration? trimStartRequested,
            Duration? trimEndRequested,
          }) => _addAudioTrackFromProjectFile(
            projectAudioFile: file,
            label: clip.label.trim().isEmpty
                ? 'Instrumental Stem'
                : '${clip.label} (Instrumental)',
            row: row,
            timeMs: timeMs,
            trimStartRequested: trimStartRequested,
            trimEndRequested: trimEndRequested,
            gain: clip.gain,
            normalizeVolume: clip.normalizeVolume,
            normalizeGain: clip.normalizeGain,
            preNormalizeGain: clip.preNormalizeGain,
            sourceTempoBpm: clip.sourceTempoBpm,
            stretchToProjectTempo: clip.stretchToProjectTempo,
            tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
            tempoWarpMode: clip.tempoWarpMode,
          ),
      tracks: _audioTracks,
      restoreTrack: _addClipFromUndoPayload,
      file: instrumentalFile,
      row: instrumentalRow,
      timeMs: startMs,
      trimStart: trimStart,
      trimEnd: trimEnd,
      onRemove: _syncRemovedClipFadesAfterUndo,
    );

    final actions = <EditorUndoAction>[
      if (rowLayoutAction != null) rowLayoutAction,
      addVocals,
      addInstrumental,
    ];

    var vocalsAdded = false;
    var instrumentalAdded = false;
    try {
      final beforeCount = _audioTracks.length;
      await _undoManager.executeWithoutAdd(addVocals);
      vocalsAdded = _audioTracks.length == beforeCount + 1;
      if (!vocalsAdded) {
        throw StateError('Failed to add vocal stem clip.');
      }

      await _undoManager.executeWithoutAdd(addInstrumental);
      instrumentalAdded = _audioTracks.length == beforeCount + 2;
      if (!instrumentalAdded) {
        throw StateError('Failed to add instrumental stem clip.');
      }

      if (mounted) {
        final instrumentalIndex = beforeCount + 1;
        setState(() {
          _timelineSelectedClipIndices = <int>[instrumentalIndex];
          _timelinePrimarySelectedClipIndex = instrumentalIndex;
          _selectedRow = instrumentalRow;
        });
      }

      await _undoManager.addWithoutExecute(
        CompoundUndoAction('Separate stems', actions),
      );
    } catch (e) {
      debugPrint('Failed to place separated stems on new rows: $e');
      if (instrumentalAdded) {
        await addInstrumental.undo();
      }
      if (vocalsAdded) {
        await addVocals.undo();
      }
      if (rowLayoutAction != null) {
        await rowLayoutAction.undo();
      }
      if (showInlineFailureNotice) {
        _showSmallNotice('Stem separation failed.');
      }
      return false;
    }

    if (showInlineFailureNotice) {
      _showSmallNotice('Created vocal/instrumental stems.');
    }
    return true;
  }

  Future<MixApplyReport> applyMixingResult(
    MixingResult mix, {
    bool emitActionSummaries = true,
    bool stageEffectEnsures = false,
    bool batchUndoGraphMutations = false,
  }) async {
    if (mix.isNoOp || mix.actions.isEmpty) {
      return const MixApplyReport(attempted: 0, applied: 0);
    }

    if (stageEffectEnsures) {
      final ensureActions = mix.actions
          .where(
            (action) =>
                action.type == 'ensure_effect' ||
                action.type == 'ensure_master_effect',
          )
          .toList(growable: false);
      if (ensureActions.isNotEmpty) {
        final remainingActions = mix.actions
            .where(
              (action) =>
                  action.type != 'ensure_effect' &&
                  action.type != 'ensure_master_effect',
            )
            .toList(growable: false);
        final canStageEnsures = remainingActions.every(
          (action) => const <String>{
            'noop',
            'set_row_gain',
            'set_row_pan',
            'set_master_gain',
            'set_master_pan',
            'adjust_effect_param_by_name',
            'adjust_master_effect_param_by_name',
          }.contains(action.type),
        );
        if (!canStageEnsures) {
          stageEffectEnsures = false;
        } else {
          late final MixApplyReport ensureReport;
          await JuceAudioEngine.beginGraphMutationBatch();
          try {
            ensureReport = await applyMixingResult(
              MixingResult(
                actions: ensureActions,
                summary: mix.summary,
                isNoOp: false,
                notes: mix.notes,
              ),
              emitActionSummaries: emitActionSummaries,
              batchUndoGraphMutations: true,
            );
          } finally {
            await JuceAudioEngine.endGraphMutationBatch();
          }
          if (remainingActions.isEmpty) {
            return MixApplyReport(
              attempted: mix.actions.length,
              applied: ensureReport.applied,
              summaries: ensureReport.summaries,
              skippedReasons: ensureReport.skippedReasons,
              appliedMutations: ensureReport.appliedMutations,
            );
          }
          final remainingReport = await applyMixingResult(
            MixingResult(
              actions: remainingActions,
              summary: mix.summary,
              isNoOp: false,
              notes: mix.notes,
            ),
            emitActionSummaries: emitActionSummaries,
          );
          return MixApplyReport(
            attempted: mix.actions.length,
            applied: ensureReport.applied + remainingReport.applied,
            summaries: <String>[
              ...ensureReport.summaries,
              ...remainingReport.summaries,
            ],
            skippedReasons: <String>[
              ...ensureReport.skippedReasons,
              ...remainingReport.skippedReasons,
            ],
            appliedMutations: <Map<String, dynamic>>[
              ...ensureReport.appliedMutations,
              ...remainingReport.appliedMutations,
            ],
          );
        }
      }
    }

    final List<EditorUndoAction> groupedActions = [];
    final reportSummaries = <String>[];
    final skippedReasons = <String>[];
    final appliedMutations = <Map<String, dynamic>>[];
    void emitActionSummary(String text) {
      reportSummaries.add(text);
    }

    void skipAction(String reason) {
      if (reason.trim().isEmpty) return;
      skippedReasons.add(reason.trim());
    }

    void flushActionSummaries() {
      if (!emitActionSummaries || reportSummaries.isEmpty) return;
      _insertExecutionDetailSystemText(
        source: 'mix_action_execution',
        collapsedTitle: 'Applied ${reportSummaries.length} mix changes',
        detailLines: reportSummaries,
      );
    }

    bool isGroupScopedAction(Map<String, dynamic> data) {
      final target = _toActionMap(data['target']);
      final rawScope = (data['scope'] ?? target['scope'] ?? '')
          .toString()
          .trim()
          .toLowerCase();
      return rawScope == 'group' ||
          rawScope == 'track_group' ||
          rawScope == 'track-group' ||
          data.containsKey('group_id') ||
          target.containsKey('group_id') ||
          data.containsKey('group_name') ||
          target.containsKey('group_name');
    }

    List<int> rowCandidatesFromAction(Map<String, dynamic> data) {
      if (_rowCount <= 0) return const <int>[];
      final target = _toActionMap(data['target']);
      final candidates = LinkedHashSet<int>();
      final groupCandidates = LinkedHashSet<int>();

      void add(dynamic raw, {bool preferOneBased = false}) {
        final parsed = _toActionInt(raw);
        if (parsed == null) return;
        void addIfValid(int idx) {
          if (idx >= 0 && idx < _rowCount) {
            candidates.add(idx);
          }
        }

        final oneBased = parsed - 1;
        if (preferOneBased) {
          if (parsed > 0) addIfValid(oneBased);
          addIfValid(parsed);
          return;
        }
        addIfValid(parsed);
        if (parsed > 0) {
          addIfValid(oneBased);
        }
      }

      add(data['row_index']);
      add(target['row_index']);
      add(data['track_index']);
      add(target['track_index']);
      add(data['row']);
      add(target['row']);
      add(data['target_row_index']);
      add(target['target_row_index']);
      add(data['target_row']);
      add(target['target_row']);
      add(data['row_number'], preferOneBased: true);
      add(target['row_number'], preferOneBased: true);
      add(data['track_number'], preferOneBased: true);
      add(target['track_number'], preferOneBased: true);
      add(data['track'], preferOneBased: true);
      add(target['track'], preferOneBased: true);

      final groupScoped = isGroupScopedAction(data);

      void addGroupRows(TrackGroup group) {
        final memberIds = group.rowIds.toSet();
        final groupId = group.id.trim();
        for (int row = 0; row < _rows.length; row++) {
          final item = _rows[row];
          if (memberIds.contains(item.rowId) ||
              (groupId.isNotEmpty && item.groupId == groupId)) {
            groupCandidates.add(row);
          }
        }
      }

      void addMatchingGroup(dynamic raw) {
        final token = (raw ?? '').toString().trim().toLowerCase();
        if (token.isEmpty) return;
        for (final group in _trackGroups) {
          final id = group.id.trim().toLowerCase();
          final name = group.name.trim().toLowerCase();
          if (id == token ||
              name == token ||
              (name.isNotEmpty && name.contains(token)) ||
              (name.isNotEmpty &&
                  token.contains('group') &&
                  token.contains(name))) {
            addGroupRows(group);
          }
        }
      }

      if (groupScoped) {
        addMatchingGroup(data['group_id']);
        addMatchingGroup(target['group_id']);
        addMatchingGroup(data['group_name']);
        addMatchingGroup(target['group_name']);
        for (final row in candidates) {
          if (row < 0 || row >= _rows.length) continue;
          final groupId = _rows[row].groupId.trim();
          if (groupId.isEmpty) continue;
          for (final group in _trackGroups) {
            if (group.id == groupId) {
              addGroupRows(group);
              break;
            }
          }
        }
      }

      if (groupCandidates.isNotEmpty) {
        return groupCandidates.toList(growable: false);
      }
      return candidates.toList(growable: false);
    }

    List<int> groupBusRowCandidatesFromAction(
      Map<String, dynamic> data, {
      List<int> fallbackRows = const <int>[],
    }) {
      final groupId = _resolveRowGroupIdFromAction(data);
      if (groupId != null && groupId.isNotEmpty) {
        final leadRow = _trackGroupLeadRowIndexForId(groupId);
        if (leadRow != null) return <int>[leadRow];
      }
      final candidates = fallbackRows.isEmpty
          ? rowCandidatesFromAction(data)
          : fallbackRows;
      for (final row in candidates) {
        if (row < 0 || row >= _rows.length) continue;
        final groupId = _rows[row].groupId.trim();
        if (groupId.isEmpty) continue;
        final leadRow = _trackGroupLeadRowIndexForId(groupId);
        if (leadRow != null) return <int>[leadRow];
      }
      return candidates;
    }

    TrackGroup? groupForBusRow(int row) => _trackGroupForLeadRowIndex(row);

    String targetDisplayNameForRow(int row) {
      final group = groupForBusRow(row);
      if (group == null) return _rowDisplayName(row);
      return _trackGroupDisplayName(group.id);
    }

    for (final a in mix.actions) {
      switch (a.type) {
        case 'set_row_gain':
          final rowCandidates = rowCandidatesFromAction(a.data);
          if (rowCandidates.isEmpty) {
            skipAction('No target track for gain change.');
            continue;
          }
          final rowTargets = isGroupScopedAction(a.data)
              ? groupBusRowCandidatesFromAction(
                  a.data,
                  fallbackRows: rowCandidates,
                )
              : <int>[rowCandidates.first];
          final mode = a.data['mode'] ?? 'delta';

          for (final row in rowTargets) {
            final group = a.data['force_individual_row'] == true
                ? null
                : groupForBusRow(row);
            final oldGain = group?.gain ?? _rowGain[row];
            double newGain;

            if (mode == 'set') {
              newGain = (a.data['value'] as num).toDouble().clamp(0.0, 3.0);
            } else {
              final delta = (a.data['delta'] as num).toDouble();
              newGain = (oldGain + delta).clamp(0.0, 3.0);
            }

            // _undoManager.execute(
            //   SetRowGainAction(
            //     row: row,
            //     oldGain: oldGain,
            //     newGain: newGain,
            //     applyToState: (r, g) {
            //       setState(() {
            //         _rowGain[r] = g;
            //       });
            //     },
            //   ),
            // );

            final EditorUndoAction finalAct = group == null
                ? SetRowGainAction(
                    row: row,
                    oldGain: oldGain,
                    newGain: newGain,
                    applyToState: (r, g) {
                      setState(() {
                        _rowGain[r] = g;
                      });
                    },
                  )
                : SetRowGainAction(
                    row: row,
                    oldGain: oldGain,
                    newGain: newGain,
                    applyToState: (_, g) =>
                        _applyTrackGroupGainState(group.id, g),
                    applyNative: (_, g) =>
                        _setTrackGroupGainNative(group.id, g),
                  );

            await _undoManager.executeWithoutAdd(
              finalAct,
            ); // need this so that you can make a compound undo action while preserving execute order
            groupedActions.add(finalAct);

            _mixHighlighter.trigger([
              HaloKey('row:$row'),
              HaloKey('row:$row:mixer'),
            ]);

            final summary =
                '• Adjusted Gain from ${_gainToDb(oldGain)} to ${_gainToDb(newGain)} on ${targetDisplayNameForRow(row)} •';
            emitActionSummary(summary);
          }

          continue;

        case 'set_row_pan':
          final rowCandidates = rowCandidatesFromAction(a.data);
          if (rowCandidates.isEmpty) {
            skipAction('No target track for pan change.');
            continue;
          }
          final rowTargets = isGroupScopedAction(a.data)
              ? groupBusRowCandidatesFromAction(
                  a.data,
                  fallbackRows: rowCandidates,
                )
              : <int>[rowCandidates.first];

          for (final row in rowTargets) {
            final group = a.data['force_individual_row'] == true
                ? null
                : groupForBusRow(row);
            final oldPan01 = group?.pan ?? _rowPan[row]; // 0..1

            double newPan01;

            if (a.data.containsKey('value')) {
              // ABSOLUTE SET (0..1, center = 0.5)
              newPan01 = (a.data['value'] as num).toDouble().clamp(0.0, 1.0);
            } else {
              // DELTA in signed space (-1..+1)
              final deltaSigned = (a.data['delta'] as num).toDouble();

              final oldPanSigned = (oldPan01 * 2.0) - 1.0;
              final newPanSigned = (oldPanSigned + deltaSigned).clamp(
                -1.0,
                1.0,
              );
              newPan01 = ((newPanSigned + 1.0) * 0.5).clamp(0.0, 1.0);
            }

            // _undoManager.execute(
            //   SetRowPanAction(
            //     row: row,
            //     oldPan: oldPan01,
            //     newPan: newPan01,
            //     applyToState: (r, p) {
            //       setState(() {
            //         _rowPan[r] = p;
            //       });
            //     },
            //   ),
            // );

            final EditorUndoAction finalAct = group == null
                ? SetRowPanAction(
                    row: row,
                    oldPan: oldPan01,
                    newPan: newPan01,
                    applyToState: (r, p) {
                      setState(() {
                        _rowPan[r] = p;
                      });
                    },
                  )
                : SetRowPanAction(
                    row: row,
                    oldPan: oldPan01,
                    newPan: newPan01,
                    applyToState: (_, p) =>
                        _applyTrackGroupPanState(group.id, p),
                    applyNative: (_, p) => _setTrackGroupPanNative(group.id, p),
                  );

            await _undoManager.executeWithoutAdd(
              finalAct,
            ); // need this so that you can make a compound undo action while preserving execute order
            groupedActions.add(finalAct);

            final summary =
                '• Adjusted pan from ${panToText(oldPan01)} to ${panToText(newPan01)} on ${targetDisplayNameForRow(row)} •';
            emitActionSummary(summary);
          }
          continue;

        case 'set_master_gain':
          {
            final mode = a.data['mode'] ?? 'delta';
            final oldGain = _masterGain;

            final double newGain;
            if (mode == 'set') {
              newGain = (a.data['value'] as num).toDouble().clamp(0.0, 3.0);
            } else {
              final delta = (a.data['delta'] as num?)?.toDouble() ?? 0.0;
              newGain = (oldGain + delta).clamp(0.0, 3.0);
            }

            final finalAct = SetMasterGainAction(
              oldGain: oldGain,
              newGain: newGain,
              applyToState: (g) {
                setState(() {
                  _masterGain = g;
                });
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary(
              '• Adjusted Master Gain from ${_gainToDb(oldGain)} to ${_gainToDb(newGain)} •',
            );
            continue;
          }

        case 'set_master_pan':
          {
            final oldPan01 = _masterPan;
            final mode = (a.data['mode'] as String?) ?? 'delta';

            final double newPan01;
            if (mode == 'set' || a.data.containsKey('value')) {
              newPan01 = (a.data['value'] as num).toDouble().clamp(0.0, 1.0);
            } else {
              final deltaSigned = (a.data['delta'] as num?)?.toDouble() ?? 0.0;
              final oldPanSigned = (oldPan01 * 2.0) - 1.0;
              final nextSigned = (oldPanSigned + deltaSigned).clamp(-1.0, 1.0);
              newPan01 = ((nextSigned + 1.0) * 0.5).clamp(0.0, 1.0);
            }

            final finalAct = SetMasterPanAction(
              oldPan: oldPan01,
              newPan: newPan01,
              applyToState: (p) {
                setState(() {
                  _masterPan = p;
                });
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary(
              '• Adjusted Master Pan from ${panToText(oldPan01)} to ${panToText(newPan01)} •',
            );
            continue;
          }

        case 'delete_effect':
          {
            final forceIndividualRow = a.data['force_individual_row'] == true;
            final contains = (a.data['effect_name_contains'] as String)
                .toLowerCase();
            final rowCandidates = rowCandidatesFromAction(a.data);
            if (rowCandidates.isEmpty) {
              skipAction('No target track for removing an effect.');
              continue;
            }

            if (isGroupScopedAction(a.data)) {
              final rowTargets = groupBusRowCandidatesFromAction(
                a.data,
                fallbackRows: rowCandidates,
              );
              for (final row in rowTargets) {
                final effects = await JuceAudioEngine.getTrackEffectsForRow(
                  row,
                  forceIndividualRow: forceIndividualRow,
                );
                final idx = effects.indexWhere(
                  (e) => e.toLowerCase().contains(contains),
                );
                if (idx == -1) continue;
                final effectName = effects[idx];
                final beforeCount = effects.length;
                final act = RemoveEffectAction(
                  row: row,
                  effectIndex: idx,
                  pathOrName: effectName,
                  forceIndividualRow: forceIndividualRow,
                  onChange: () {
                    setState(() {});
                    _refreshRowFx(row);
                    unawaited(_refreshAutomationTargetsForRow(row));
                  },
                );
                await _undoManager.executeWithoutAdd(act);
                final afterEffects =
                    await JuceAudioEngine.getTrackEffectsForRow(
                      row,
                      forceIndividualRow: forceIndividualRow,
                    );
                final removed =
                    afterEffects.length < beforeCount ||
                    !afterEffects.any(
                      (e) => e.toLowerCase() == effectName.toLowerCase(),
                    );
                if (!removed) continue;
                groupedActions.add(act);
                _mixHighlighter.trigger([
                  HaloKey('row:$row'),
                  HaloKey('row:$row:effects_tab'),
                  HaloKey('row:$row:fx_list'),
                  HaloKey('row:$row:fx_contains:$contains'),
                ]);
                emitActionSummary(
                  '• Removed $effectName from ${targetDisplayNameForRow(row)} •',
                );
              }
              // Absence is already the requested final state.
              continue;
            }

            int? appliedRow;
            String? removedEffectName;
            EditorUndoAction? appliedAction;
            for (final row in rowCandidates) {
              final effects = await JuceAudioEngine.getTrackEffectsForRow(
                row,
                forceIndividualRow: forceIndividualRow,
              );
              final idx = effects.indexWhere(
                (e) => e.toLowerCase().contains(contains),
              );
              if (idx == -1) continue;
              final effectName = effects[idx];
              final beforeCount = effects.length;
              final act = RemoveEffectAction(
                row: row,
                effectIndex: idx,
                pathOrName: effectName,
                forceIndividualRow: forceIndividualRow,
                onChange: () {
                  setState(() {});
                  _refreshRowFx(row);
                  unawaited(_refreshAutomationTargetsForRow(row));
                },
              );
              await _undoManager.executeWithoutAdd(act);
              final afterEffects = await JuceAudioEngine.getTrackEffectsForRow(
                row,
                forceIndividualRow: forceIndividualRow,
              );
              final removed =
                  afterEffects.length < beforeCount ||
                  !afterEffects.any(
                    (e) => e.toLowerCase() == effectName.toLowerCase(),
                  );
              if (!removed) {
                continue;
              }
              appliedRow = row;
              removedEffectName = effectName;
              appliedAction = act;
              break;
            }

            if (appliedRow == null ||
                removedEffectName == null ||
                appliedAction == null) {
              // Absence is already the requested final state.
              continue;
            }

            groupedActions.add(appliedAction);

            _mixHighlighter.trigger([
              HaloKey('row:$appliedRow'),
              HaloKey('row:$appliedRow:effects_tab'),
              HaloKey('row:$appliedRow:fx_list'),
              HaloKey('row:$appliedRow:fx_contains:$contains'),
            ]);

            emitActionSummary(
              '• Removed $removedEffectName from ${_rowDisplayName(appliedRow)} •',
            );
            continue;
          }

        case 'delete_master_effect':
          {
            final contains = (a.data['effect_name_contains'] as String)
                .toLowerCase();
            final effects = await JuceAudioEngine.getMasterEffects();
            final idx = effects.indexWhere(
              (e) => e.toLowerCase().contains(contains),
            );
            if (idx == -1) continue;

            final finalAct = RemoveMasterEffectAction(
              effectIndex: idx,
              pathOrName: effects[idx],
              onChange: () {
                setState(() {});
                unawaited(_refreshAutomationTargetsForAllRows());
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);

            emitActionSummary('• Removed ${effects[idx]} from Master Bus •');
            continue;
          }

        case 'ensure_effect':
          final forceIndividualRow = a.data['force_individual_row'] == true;
          final contains = (a.data['effect_name_contains'] as String)
              .toLowerCase();
          final rowCandidates = rowCandidatesFromAction(a.data);
          if (rowCandidates.isEmpty) {
            skipAction('No target track for adding an effect.');
            continue;
          }

          final effectName = pickMixroomEffect(contains);
          if (effectName == null) {
            skipAction('Could not resolve the requested effect.');
            continue;
          }
          if (!_canUseEffectForCurrentPlan(effectName)) {
            emitActionSummary(
              '• $effectName is available on Starter and higher plans •',
            );
            continue;
          }

          if (isGroupScopedAction(a.data)) {
            final rowTargets = groupBusRowCandidatesFromAction(
              a.data,
              fallbackRows: rowCandidates,
            );
            var appliedCount = 0;
            for (final row in rowTargets) {
              final effects = await JuceAudioEngine.getTrackEffectsForRow(
                row,
                forceIndividualRow: forceIndividualRow,
              );
              final already = effects.indexWhere(
                (e) => e.toLowerCase().contains(contains),
              );
              if (already != -1) {
                appliedCount += 1;
                groupedActions.addAll(
                  await _ensureAiCanonicalChainOrderOnRow(
                    row,
                    forceIndividualRow: forceIndividualRow,
                  ),
                );
                continue;
              }
              final beforeCount = effects.length;
              final act = InsertEffectAction(
                row: row,
                pathOrName: effectName,
                forceIndividualRow: forceIndividualRow,
                onChange: () {
                  setState(() {});
                  _refreshRowFx(row);
                  unawaited(_refreshAutomationTargetsForRow(row));
                },
              );
              await _undoManager.executeWithoutAdd(act);
              final afterEffects = await JuceAudioEngine.getTrackEffectsForRow(
                row,
                forceIndividualRow: forceIndividualRow,
              );
              final inserted =
                  afterEffects.length > beforeCount &&
                  afterEffects.any(
                    (e) =>
                        e.toLowerCase().contains(contains) ||
                        e.toLowerCase().contains(effectName.toLowerCase()),
                  );
              if (!inserted) {
                continue;
              }
              groupedActions.add(act);
              groupedActions.addAll(
                await _ensureAiCanonicalChainOrderOnRow(
                  row,
                  forceIndividualRow: forceIndividualRow,
                ),
              );
              appliedCount += 1;
              _mixHighlighter.trigger([
                HaloKey('row:$row'),
                HaloKey('row:$row:effects_tab'),
                HaloKey('row:$row:fx_list'),
                HaloKey('row:$row:fx_contains:$contains'),
              ]);
              emitActionSummary(
                '• Added $effectName to ${targetDisplayNameForRow(row)} •',
              );
            }
            if (appliedCount == 0) {
              skipAction('Could not add the requested effect to that group.');
            }
            continue;
          }

          int? appliedRow;
          EditorUndoAction? appliedAction;
          for (final row in rowCandidates) {
            final effects = await JuceAudioEngine.getTrackEffectsForRow(
              row,
              forceIndividualRow: forceIndividualRow,
            );
            final already = effects.indexWhere(
              (e) => e.toLowerCase().contains(contains),
            );
            if (already != -1) {
              appliedRow = row;
              break;
            }
            final beforeCount = effects.length;
            final act = InsertEffectAction(
              row: row,
              pathOrName: effectName,
              forceIndividualRow: forceIndividualRow,
              onChange: () {
                setState(() {});
                _refreshRowFx(row);
                unawaited(_refreshAutomationTargetsForRow(row));
              },
            );
            await _undoManager.executeWithoutAdd(act);
            final afterEffects = await JuceAudioEngine.getTrackEffectsForRow(
              row,
              forceIndividualRow: forceIndividualRow,
            );
            final inserted =
                afterEffects.length > beforeCount &&
                afterEffects.any(
                  (e) =>
                      e.toLowerCase().contains(contains) ||
                      e.toLowerCase().contains(effectName.toLowerCase()),
                );
            if (!inserted) {
              continue;
            }
            appliedRow = row;
            appliedAction = act;
            break;
          }

          if (appliedRow == null) {
            skipAction('Could not add the requested effect.');
            continue;
          }
          if (appliedAction != null) {
            groupedActions.add(appliedAction);
          }
          groupedActions.addAll(
            await _ensureAiCanonicalChainOrderOnRow(
              appliedRow,
              forceIndividualRow: forceIndividualRow,
            ),
          );

          _mixHighlighter.trigger([
            HaloKey('row:$appliedRow'),
            HaloKey('row:$appliedRow:effects_tab'),
            HaloKey('row:$appliedRow:fx_list'),
            HaloKey('row:$appliedRow:fx_contains:$contains'),
          ]);

          if (appliedAction != null) {
            final summary =
                '• Added $effectName to ${_rowDisplayName(appliedRow)} •';
            emitActionSummary(summary);
          }
          continue;

        case 'ensure_master_effect':
          {
            final contains = (a.data['effect_name_contains'] as String)
                .toLowerCase();
            final effects = await JuceAudioEngine.getMasterEffects();
            final already = effects.indexWhere(
              (e) => e.toLowerCase().contains(contains),
            );
            if (already != -1) {
              groupedActions.addAll(
                await _ensureAiCanonicalChainOrderOnMaster(),
              );
              continue;
            }

            final effectName = pickMixroomEffect(contains);
            if (effectName == null) {
              skipAction('Could not resolve the requested master effect.');
              continue;
            }
            if (!_canUseEffectForCurrentPlan(effectName)) {
              emitActionSummary(
                '• $effectName is available on Starter and higher plans •',
              );
              continue;
            }

            final finalAct = InsertMasterEffectAction(
              pathOrName: effectName,
              onChange: () {
                setState(() {});
                unawaited(_refreshAutomationTargetsForAllRows());
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);
            groupedActions.addAll(await _ensureAiCanonicalChainOrderOnMaster());

            emitActionSummary('• Added $effectName to Master Bus •');
            continue;
          }

        case 'adjust_effect_param_by_name':
          {
            final forceIndividualRow = a.data['force_individual_row'] == true;
            final rowCandidates = rowCandidatesFromAction(a.data);
            if (rowCandidates.isEmpty) {
              skipAction('No target track for plugin parameter change.');
              continue;
            }
            final rowTargets = isGroupScopedAction(a.data)
                ? groupBusRowCandidatesFromAction(
                    a.data,
                    fallbackRows: rowCandidates,
                  )
                : <int>[rowCandidates.first];
            final effectContains = (a.data['effect_name_contains'] as String)
                .toLowerCase();

            final skipIfMissing =
                (a.data['skip_if_missing_effect'] as bool?) ?? true;

            var adjustedCount = 0;
            for (final row in rowTargets) {
              final exactParamName = a.data['param_name'] as String?;
              final containsAny = (a.data['param_name_contains_any'] as List?)
                  ?.map((e) => e.toString())
                  .toList();

              final resolved = await _waitForReadyRowMixParameter(
                row: row,
                effectNameContains: effectContains,
                exactParameterName: exactParamName,
                parameterNameContainsAny: containsAny,
                forceIndividualRow: forceIndividualRow,
              );
              if (resolved == null) {
                continue;
              }

              final fxIndex = resolved.effectIndex;
              final picked = resolved.parameter;
              final paramId =
                  (picked['id'] as String?) ??
                  (picked['name'] as String); // robust
              final paramName = (picked['name'] as String?) ?? paramId;
              final current = (picked['value'] as num).toDouble();

              final double? pMin = picked['min'] is num
                  ? (picked['min'] as num).toDouble()
                  : null;
              final double? pMax = picked['max'] is num
                  ? (picked['max'] as num).toDouble()
                  : null;

              final clamp01 = (a.data['clamp_0_1'] as bool?) ?? false;

              final mode = (a.data['mode'] as String?) ?? 'delta';

              double next = current;

              if (mode == 'set') {
                if (a.data.containsKey('value_norm') &&
                    pMin != null &&
                    pMax != null) {
                  final vn = (a.data['value_norm'] as num).toDouble().clamp(
                    0.0,
                    1.0,
                  );
                  next = pMin + (pMax - pMin) * vn;
                } else {
                  next = (a.data['value'] as num).toDouble();
                }
              } else {
                // delta mode
                double delta;
                if (a.data.containsKey('delta_norm')) {
                  final dn = (a.data['delta_norm'] as num).toDouble();
                  if (pMin != null && pMax != null) {
                    delta = dn * (pMax - pMin);
                  } else {
                    delta = dn;
                  }
                } else {
                  delta = (a.data['delta'] as num).toDouble();
                }
                next = current + delta;
              }

              // -----------------------------
              // HARD SAFETY CLAMPS (action-level)
              // -----------------------------
              final double? hardMin = a.data['clamp_min'] is num
                  ? (a.data['clamp_min'] as num).toDouble()
                  : null;
              final double? hardMax = a.data['clamp_max'] is num
                  ? (a.data['clamp_max'] as num).toDouble()
                  : null;

              // Apply hard clamps FIRST (authoritative)
              if (hardMin != null || hardMax != null) {
                final lo = hardMin ?? double.negativeInfinity;
                final hi = hardMax ?? double.infinity;
                next = next.clamp(lo, hi);
              }

              // -----------------------------
              // Plugin range clamp
              // -----------------------------
              if (pMin != null && pMax != null) {
                next = next.clamp(pMin, pMax);
              } else if (clamp01) {
                next = next.clamp(0.0, 1.0);
              }
              final interval = (_toActionDouble(picked['interval']) ?? 0.0)
                  .abs();
              next = _canonicalEffectParameterValue(
                value: next,
                minimum: pMin,
                maximum: pMax,
                interval: interval,
              );

              // await _undoManager.execute(
              //   SetEffectParamAction(
              //     row: row,
              //     effectIndex: fxIndex,
              //     paramId: paramName, // if your engine needs name instead, use paramName
              //     oldValue: current,
              //     newValue: next,
              //     onChange: () {
              //       setState(() {});
              //       _refreshRowFx(row);
              //     },
              //   ),
              // );

              EditorUndoAction finalAct = SetEffectParamAction(
                row: row,
                effectIndex: fxIndex,
                effectId: resolved.effectId,
                effectInstanceId: resolved.effectInstanceId,
                effectOccurrence: resolved.effectOccurrence,
                paramId: paramId,
                oldValue: current,
                newValue: next,
                forceIndividualRow: forceIndividualRow,
                onChange: () {
                  setState(() {});
                  _refreshRowFx(row);
                },
              );

              await _undoManager.executeWithoutAdd(
                finalAct,
              ); // need this so that you can make a compound undo action while preserving execute order
              groupedActions.add(finalAct);
              final currentInstanceIds =
                  await JuceAudioEngine.getTrackEffectInstanceIdsForRow(
                    row,
                    forceIndividualRow: forceIndividualRow,
                  );
              final currentIndex = currentInstanceIds.indexOf(
                resolved.effectInstanceId!,
              );
              if (currentIndex < 0) {
                throw StateError('mix_effect_identity_missing');
              }
              final appliedParameters = exposedEffectParameters(
                resolved.effectName,
                await JuceAudioEngine.getTrackPluginParameters(
                  row,
                  currentIndex,
                  forceIndividualRow: forceIndividualRow,
                ),
              );
              final appliedParameter = appliedParameters
                  .where((parameter) => parameter['id'] == paramId)
                  .firstOrNull;
              final appliedValue = _toActionDouble(appliedParameter?['value']);
              final normalizedValue = _toActionDouble(
                appliedParameter?['valueNormalized'],
              );
              if (appliedValue == null ||
                  normalizedValue == null ||
                  (appliedValue - next).abs() >
                      math.max(0.0001, interval / 2.0 + 0.000001)) {
                throw StateError('mix_effect_parameter_apply_failed');
              }
              final normalizedInterval =
                  (_toActionDouble(appliedParameter?['intervalNormalized']) ??
                          0.0)
                      .abs();
              appliedMutations.add(<String, dynamic>{
                'kind': 'effect_parameter_value',
                'row': row,
                'master': false,
                if (forceIndividualRow) 'force_individual_row': true,
                'effect_instance_id': resolved.effectInstanceId,
                'effect_id': resolved.effectId,
                'effect_name': resolved.effectName,
                'parameter_id': paramId,
                'param_name': paramName,
                'value': next,
                'value_normalized': normalizedValue,
                'tolerance_normalized': math.max(
                  0.001,
                  normalizedInterval > 0.0
                      ? normalizedInterval / 2.0 + 0.000001
                      : 0.001,
                ),
              });
              adjustedCount += 1;

              _mixHighlighter.trigger([
                HaloKey('row:$row'),
                HaloKey('row:$row:effects_tab'),
                HaloKey('row:$row:fx_list'),
                HaloKey('row:$row:fx_index:$currentIndex'),
                HaloKey(
                  'row:$row:fx_index:$currentIndex:param:$paramId',
                ), // TODO: put paramName instead of paramId maybe
              ]);

              emitActionSummary(
                '• Adjusted $paramName from ${current.toStringAsFixed(2)} to ${next.toStringAsFixed(2)} on ${resolved.effectName} (${targetDisplayNameForRow(row)}) •',
              );
            }
            if (adjustedCount == 0 && !skipIfMissing) {
              skipAction('Could not resolve the requested plugin parameter.');
            }
            continue;
          }

        case 'adjust_master_effect_param_by_name':
          {
            final effectContains = (a.data['effect_name_contains'] as String)
                .toLowerCase();
            final skipIfMissing =
                (a.data['skip_if_missing_effect'] as bool?) ?? true;

            final exactParamName = a.data['param_name'] as String?;
            final containsAny = (a.data['param_name_contains_any'] as List?)
                ?.map((e) => e.toString())
                .toList();

            final resolved = await _waitForReadyMasterMixParameter(
              effectNameContains: effectContains,
              exactParameterName: exactParamName,
              parameterNameContainsAny: containsAny,
            );
            if (resolved == null) {
              if (!skipIfMissing) {
                skipAction(
                  'Could not resolve the requested master plugin parameter.',
                );
              }
              continue;
            }

            final fxIndex = resolved.effectIndex;
            final picked = resolved.parameter;
            final paramId =
                (picked['id'] as String?) ?? (picked['name'] as String);
            final paramName = (picked['name'] as String?) ?? paramId;
            final current = (picked['value'] as num).toDouble();

            final double? pMin = picked['min'] is num
                ? (picked['min'] as num).toDouble()
                : null;
            final double? pMax = picked['max'] is num
                ? (picked['max'] as num).toDouble()
                : null;

            final clamp01 = (a.data['clamp_0_1'] as bool?) ?? false;
            final mode = (a.data['mode'] as String?) ?? 'delta';

            double next = current;
            if (mode == 'set') {
              if (a.data.containsKey('value_norm') &&
                  pMin != null &&
                  pMax != null) {
                final vn = (a.data['value_norm'] as num).toDouble().clamp(
                  0.0,
                  1.0,
                );
                next = pMin + (pMax - pMin) * vn;
              } else {
                next = (a.data['value'] as num).toDouble();
              }
            } else {
              double delta;
              if (a.data.containsKey('delta_norm')) {
                final dn = (a.data['delta_norm'] as num).toDouble();
                if (pMin != null && pMax != null) {
                  delta = dn * (pMax - pMin);
                } else {
                  delta = dn;
                }
              } else {
                delta = (a.data['delta'] as num).toDouble();
              }
              next = current + delta;
            }

            final double? hardMin = a.data['clamp_min'] is num
                ? (a.data['clamp_min'] as num).toDouble()
                : null;
            final double? hardMax = a.data['clamp_max'] is num
                ? (a.data['clamp_max'] as num).toDouble()
                : null;

            if (hardMin != null || hardMax != null) {
              final lo = hardMin ?? double.negativeInfinity;
              final hi = hardMax ?? double.infinity;
              next = next.clamp(lo, hi);
            }

            if (pMin != null && pMax != null) {
              next = next.clamp(pMin, pMax);
            } else if (clamp01) {
              next = next.clamp(0.0, 1.0);
            }
            final interval = (_toActionDouble(picked['interval']) ?? 0.0).abs();
            next = _canonicalEffectParameterValue(
              value: next,
              minimum: pMin,
              maximum: pMax,
              interval: interval,
            );

            final finalAct = SetMasterEffectParamAction(
              effectIndex: fxIndex,
              effectId: resolved.effectId,
              paramId: paramId,
              oldValue: current,
              newValue: next,
              onChange: () {
                setState(() {});
                unawaited(_refreshAutomationTargetsForAllRows());
              },
            );

            await _undoManager.executeWithoutAdd(finalAct);
            groupedActions.add(finalAct);
            final currentEffectIds = await JuceAudioEngine.getMasterEffectIds();
            final matchingIndexes = <int>[
              for (var index = 0; index < currentEffectIds.length; index++)
                if (currentEffectIds[index] == resolved.effectId) index,
            ];
            if (matchingIndexes.length != 1) {
              throw StateError('mix_master_effect_identity_missing');
            }
            final currentIndex = matchingIndexes.single;
            final appliedParameters = exposedEffectParameters(
              resolved.effectName,
              await JuceAudioEngine.getMasterPluginParameters(currentIndex),
            );
            final appliedParameter = appliedParameters
                .where((parameter) => parameter['id'] == paramId)
                .firstOrNull;
            final appliedValue = _toActionDouble(appliedParameter?['value']);
            final normalizedValue = _toActionDouble(
              appliedParameter?['valueNormalized'],
            );
            if (appliedValue == null ||
                normalizedValue == null ||
                (appliedValue - next).abs() >
                    math.max(0.0001, interval / 2.0 + 0.000001)) {
              throw StateError('mix_master_parameter_apply_failed');
            }
            final normalizedInterval =
                (_toActionDouble(appliedParameter?['intervalNormalized']) ??
                        0.0)
                    .abs();
            appliedMutations.add(<String, dynamic>{
              'kind': 'effect_parameter_value',
              'master': true,
              'effect_index': currentIndex,
              'effect_id': resolved.effectId,
              'effect_name': resolved.effectName,
              'parameter_id': paramId,
              'param_name': paramName,
              'value': next,
              'value_normalized': normalizedValue,
              'tolerance_normalized': math.max(
                0.001,
                normalizedInterval > 0.0
                    ? normalizedInterval / 2.0 + 0.000001
                    : 0.001,
              ),
            });

            emitActionSummary(
              '• Adjusted $paramName from ${current.toStringAsFixed(2)} to ${next.toStringAsFixed(2)} on ${resolved.effectName} (Master Bus) •',
            );
            continue;
          }

        case 'hard_reset_row_fx':
          {
            final forceIndividualRow = a.data['force_individual_row'] == true;
            final rowCandidates = rowCandidatesFromAction(a.data);
            if (rowCandidates.isEmpty) {
              skipAction('No target track for resetting effects.');
              continue;
            }
            final rowTargets = isGroupScopedAction(a.data)
                ? groupBusRowCandidatesFromAction(
                    a.data,
                    fallbackRows: rowCandidates,
                  )
                : <int>[rowCandidates.first];

            // Query actual FX list
            var resetCount = 0;
            for (final row in rowTargets) {
              final effects = await JuceAudioEngine.getTrackEffectsForRow(
                row,
                forceIndividualRow: forceIndividualRow,
              );

              if (effects.isEmpty) continue;

              // IMPORTANT: delete back-to-front to keep indices valid
              for (int fxIndex = effects.length - 1; fxIndex >= 0; fxIndex--) {
                final fxName = effects[fxIndex];

                EditorUndoAction act = RemoveEffectAction(
                  row: row,
                  effectIndex: fxIndex,
                  pathOrName: fxName,
                  forceIndividualRow: forceIndividualRow,
                  onChange: () {
                    setState(() {});
                    _refreshRowFx(row);
                    unawaited(_refreshAutomationTargetsForRow(row));
                  },
                );

                await _undoManager.executeWithoutAdd(act);
                groupedActions.add(act);
              }
              resetCount += 1;

              emitActionSummary(
                '• Removed all effects on ${targetDisplayNameForRow(row)} •',
              );
            }
            if (resetCount == 0) {
              skipAction('No effects found on the target track or group.');
            }

            continue;
          }

        case 'hard_reset_master_fx':
          {
            final effects = await JuceAudioEngine.getMasterEffects();
            if (effects.isEmpty) continue;

            for (int fxIndex = effects.length - 1; fxIndex >= 0; fxIndex--) {
              final fxName = effects[fxIndex];
              final act = RemoveMasterEffectAction(
                effectIndex: fxIndex,
                pathOrName: fxName,
                onChange: () {
                  setState(() {});
                  unawaited(_refreshAutomationTargetsForAllRows());
                },
              );

              await _undoManager.executeWithoutAdd(act);
              groupedActions.add(act);
            }

            emitActionSummary('• Removed all effects on Master Bus •');
            continue;
          }

        default:
          // Unknown / noop → ignore safely
          skipAction('Unsupported mix action "${a.type}".');
          continue;
      }
    }
    if (groupedActions.isEmpty) {
      flushActionSummaries();
      return MixApplyReport(
        attempted: mix.actions.length,
        applied: 0,
        summaries: reportSummaries,
        skippedReasons: skippedReasons,
        appliedMutations: appliedMutations,
      );
    }

    await _undoManager.addWithoutExecute(
      CompoundUndoAction(
        'AI mixing adjustments',
        groupedActions,
        batchGraphMutations: batchUndoGraphMutations,
      ),
    );
    flushActionSummaries();
    return MixApplyReport(
      attempted: mix.actions.length,
      applied: groupedActions.length,
      summaries: reportSummaries,
      skippedReasons: skippedReasons,
      appliedMutations: appliedMutations,
    );
  }

  static const String _kAiRequestFailureSystemText =
      'AI request failed before any DAW change was applied. Please try again.';
  static const String _kAiApplyFailureSystemText =
      'AI returned a plan, but no DAW change was applied.';

  void _reportAiChatFailure(
    Object error,
    StackTrace stackTrace, {
    required String stage,
  }) {
    aiDebugLog('audio-editor', 'ai chat failure stage=$stage error=$error');
    unawaited(
      CrashReportingService.instance.captureException(
        error,
        stackTrace: stackTrace,
      ),
    );
  }

  Map<String, dynamic> _aiObservabilityFromMeta(Map<String, dynamic>? meta) {
    if (meta == null) return const <String, dynamic>{};
    final raw = meta['observability'];
    if (raw is Map<String, dynamic>) {
      return raw;
    }
    if (raw is Map) {
      return raw.cast<String, dynamic>();
    }
    return const <String, dynamic>{};
  }

  int? _aiObservabilityInt(Map<String, dynamic> observability, String key) {
    final value = observability[key];
    if (value is int) return value;
    if (value is num) return value.toInt();
    return null;
  }

  String? _aiObservabilityString(
    Map<String, dynamic> observability,
    String key,
  ) {
    final value = observability[key]?.toString().trim() ?? '';
    return value.isEmpty ? null : value;
  }

  bool? _aiObservabilityBool(Map<String, dynamic> observability, String key) {
    final value = observability[key];
    if (value is bool) return value;
    return null;
  }

  Map<String, dynamic> _aiMap(dynamic raw) {
    if (raw is Map<String, dynamic>) return raw;
    if (raw is Map) return raw.cast<String, dynamic>();
    return const <String, dynamic>{};
  }

  Map<String, dynamic> _aiUsageFromMeta(Map<String, dynamic>? meta) {
    if (meta == null) return const <String, dynamic>{};
    return _aiMap(meta['usage']);
  }

  Map<String, dynamic> _aiSoftErrorFromMeta(Map<String, dynamic>? meta) {
    if (meta == null) return const <String, dynamic>{};
    return _aiMap(meta['soft_error']);
  }

  int? _aiAsInt(Object? raw) {
    if (raw is int) return raw;
    if (raw is num) return raw.toInt();
    if (raw is String) return int.tryParse(raw.trim());
    return null;
  }

  double? _aiAsDouble(Object? raw) {
    if (raw is double) return raw;
    if (raw is num) return raw.toDouble();
    if (raw is String) return double.tryParse(raw.trim());
    return null;
  }

  int? _aiFirstInt(List<Object?> candidates) {
    for (final candidate in candidates) {
      final value = _aiAsInt(candidate);
      if (value != null) return value;
    }
    return null;
  }

  double? _aiFirstDouble(List<Object?> candidates) {
    for (final candidate in candidates) {
      final value = _aiAsDouble(candidate);
      if (value != null) return value;
    }
    return null;
  }

  int _aiCachedPromptTokensFromUsage(Map<String, dynamic> usage) {
    for (final key in const <String>[
      'input_tokens_details',
      'prompt_tokens_details',
    ]) {
      final details = _aiMap(usage[key]);
      final cached = _aiAsInt(details['cached_tokens']);
      if (cached != null) return cached;
    }
    return 0;
  }

  int? _aiUsagePromptTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    return _aiFirstInt(<Object?>[
      usage['input_tokens'],
      usage['prompt_tokens'],
      usage['tokens_prompt'],
      usage['prompt_token_count'],
      observability['input_tokens'],
      observability['prompt_tokens'],
      observability['tokens_prompt'],
      observability['prompt_token_count'],
    ]);
  }

  int? _aiUsageCompletionTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    return _aiFirstInt(<Object?>[
      usage['output_tokens'],
      usage['completion_tokens'],
      usage['tokens_completion'],
      usage['completion_token_count'],
      observability['output_tokens'],
      observability['completion_tokens'],
      observability['tokens_completion'],
      observability['completion_token_count'],
    ]);
  }

  int? _aiUsageTotalTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    final direct = _aiFirstInt(<Object?>[
      usage['total_tokens'],
      usage['tokens_total'],
      usage['token_count'],
      observability['total_tokens'],
      observability['tokens_total'],
      observability['token_count'],
    ]);
    if (direct != null) return direct;
    final prompt = _aiUsagePromptTokens(meta);
    final completion = _aiUsageCompletionTokens(meta);
    if (prompt != null || completion != null) {
      return (prompt ?? 0) + (completion ?? 0);
    }
    return null;
  }

  int? _aiUsageCachedPromptTokens(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    final direct = _aiFirstInt(<Object?>[
      meta?['cached_prompt_tokens'],
      usage['cached_prompt_tokens'],
      usage['prompt_cached_tokens'],
      observability['cached_prompt_tokens'],
      observability['prompt_cached_tokens'],
    ]);
    if (direct != null) return direct;
    final fromUsageDetails = _aiCachedPromptTokensFromUsage(usage);
    return fromUsageDetails > 0 ? fromUsageDetails : null;
  }

  double? _aiUsageEstimatedCostUsd(Map<String, dynamic>? meta) {
    final usage = _aiUsageFromMeta(meta);
    final observability = _aiObservabilityFromMeta(meta);
    final direct = _aiFirstDouble(<Object?>[
      usage['estimated_cost_usd'],
      usage['cost_usd'],
      usage['total_cost_usd'],
      usage['usd_cost'],
      usage['total_usd'],
      observability['estimated_cost_usd'],
      observability['cost_usd'],
      observability['total_cost_usd'],
      observability['usd_cost'],
      observability['total_usd'],
    ]);
    if (direct != null) return direct;

    final promptCost = _aiFirstDouble(<Object?>[
      usage['input_cost_usd'],
      usage['prompt_cost_usd'],
      observability['input_cost_usd'],
      observability['prompt_cost_usd'],
    ]);
    final completionCost = _aiFirstDouble(<Object?>[
      usage['output_cost_usd'],
      usage['completion_cost_usd'],
      observability['output_cost_usd'],
      observability['completion_cost_usd'],
    ]);
    if (promptCost != null || completionCost != null) {
      return (promptCost ?? 0) + (completionCost ?? 0);
    }
    return null;
  }

  String? _aiSoftErrorCodeFromMeta(Map<String, dynamic>? meta) {
    final softError = _aiSoftErrorFromMeta(meta);
    final code = (softError['code'] ?? '').toString().trim();
    return code.isEmpty ? null : code;
  }

  Future<void> _trackAiResponseOutcome({
    required String promptTraceId,
    required String aiFeature,
    required String projectId,
    Map<String, dynamic>? meta,
    String? fallbackErrorCode,
  }) async {
    final observability = _aiObservabilityFromMeta(meta);
    final runtimeConfigFingerprint = _aiObservabilityString(
      observability,
      'runtime_config_fingerprint',
    );
    final hasSystemPromptOverride = _aiObservabilityBool(
      observability,
      'has_system_prompt_override',
    );
    final modelName = _aiObservabilityString(observability, 'effective_model');
    final latencyMs = _aiFirstInt(<Object?>[
      observability['provider_roundtrip_ms'],
      observability['openai_api_ms'],
      observability['proxy_roundtrip_ms'],
    ]);
    final softErrorCode = _aiSoftErrorCodeFromMeta(meta);
    final errorCode = softErrorCode ?? fallbackErrorCode;
    if ((errorCode ?? '').trim().isNotEmpty) {
      await AnalyticsService.instance.track(
        AnalyticsEvents.aiResponseFailed(
          projectId: projectId,
          aiFeature: aiFeature,
          errorCode: errorCode!,
          promptTraceId: promptTraceId,
          runtimeConfigFingerprint: runtimeConfigFingerprint,
          hasSystemPromptOverride: hasSystemPromptOverride,
        ),
      );
      return;
    }

    await AnalyticsService.instance.track(
      AnalyticsEvents.aiResponseCompleted(
        projectId: projectId,
        aiFeature: aiFeature,
        modelName: modelName,
        promptTraceId: promptTraceId,
        runtimeConfigFingerprint: runtimeConfigFingerprint,
        hasSystemPromptOverride: hasSystemPromptOverride,
        latencyMs: latencyMs,
        tokensPrompt: _aiUsagePromptTokens(meta),
        tokensCompletion: _aiUsageCompletionTokens(meta),
        tokensTotal: _aiUsageTotalTokens(meta),
        cachedPromptTokens: _aiUsageCachedPromptTokens(meta),
        estimatedCostUsd: _aiUsageEstimatedCostUsd(meta),
      ),
    );
  }

