  void _logAiPromptCycleSummary({
    required String promptTraceId,
    required String toolName,
    required String? modelName,
    required String status,
    required Map<String, dynamic> observability,
    required int promptCycleTotalMs,
    int? applyMixMs,
  }) {
    if (!kAiDebugLogs || !kAiDebugVerbose) return;
    final parts = <String>[
      'trace=$promptTraceId',
      'status=$status',
      if (toolName.trim().isNotEmpty) 'tool=$toolName',
      if ((modelName ?? '').trim().isNotEmpty) 'model=$modelName',
      'total=${promptCycleTotalMs}ms',
      if (_aiObservabilityInt(observability, 'project_stats_ms') != null)
        'project=${_aiObservabilityInt(observability, 'project_stats_ms')}ms',
      if (_aiObservabilityInt(observability, 'proxy_roundtrip_ms') != null)
        'proxy=${_aiObservabilityInt(observability, 'proxy_roundtrip_ms')}ms',
      if (_aiObservabilityInt(observability, 'openai_api_ms') != null)
        'openai=${_aiObservabilityInt(observability, 'openai_api_ms')}ms',
      if (_aiObservabilityInt(observability, 'mix_plan_ms') != null)
        'mixPlan=${_aiObservabilityInt(observability, 'mix_plan_ms')}ms',
      if (_aiObservabilityInt(observability, 'mix_model_heuristic_ms') != null)
        'heuristic=${_aiObservabilityInt(observability, 'mix_model_heuristic_ms')}ms',
      if (_aiObservabilityInt(observability, 'mix_model_onnx_ms') != null)
        'onnx=${_aiObservabilityInt(observability, 'mix_model_onnx_ms')}ms',
      if (applyMixMs != null) 'apply=${applyMixMs}ms',
    ];
    aiDebugLog('prompt-cycle', parts.join(' '));
  }

  void _logAiPromptDebugPretty({
    required String promptTraceId,
    required String toolName,
    required Map<String, dynamic>? meta,
    required int promptCycleTotalMs,
    int? applyMixMs,
  }) {
    if (!kAiDebugLogs) return;

    final observability = _aiObservabilityFromMeta(meta);
    final steps =
        (meta?['mix_debug_steps'] as List?)
            ?.whereType<Map>()
            .map((e) => Map<String, dynamic>.from(e))
            .toList(growable: false) ??
        const <Map<String, dynamic>>[];

    String fmtMs(String key) {
      final value = _aiObservabilityInt(observability, key);
      return value == null ? '-' : '${value}ms';
    }

    String fmtStr(String key) {
      return _aiObservabilityString(observability, key) ?? '-';
    }

    String fmtNum(dynamic value, {int digits = 3}) {
      if (value is num) {
        return value.toStringAsFixed(digits);
      }
      return '-';
    }

    Map<String, dynamic> mapOrEmpty(dynamic raw) {
      if (raw is Map<String, dynamic>) return raw;
      if (raw is Map) return raw.cast<String, dynamic>();
      return const <String, dynamic>{};
    }

    List<Map<String, dynamic>> listOfMaps(dynamic raw) {
      if (raw is! List) return const <Map<String, dynamic>>[];
      return raw
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList(growable: false);
    }

    String formatDataDelta(
      Map<String, dynamic> beforeData,
      Map<String, dynamic> afterData,
    ) {
      final keys = <String>{...beforeData.keys, ...afterData.keys}.toList()
        ..sort();
      final diffs = <String>[];
      for (final key in keys) {
        final beforeValue = beforeData[key];
        final afterValue = afterData[key];
        if (beforeValue == afterValue) continue;

        final beforeText = beforeValue?.toString() ?? 'null';
        final afterText = afterValue?.toString() ?? 'null';
        if (beforeText == afterText) continue;

        diffs.add('$key:$beforeText->$afterText');
      }
      if (diffs.isEmpty) return 'no_data_delta';
      if (!kAiDebugVerbose && diffs.length > 5) {
        return '${diffs.take(5).join(', ')}, ...';
      }
      return diffs.join(', ');
    }

    String formatMagnitudeEntry(Map<String, dynamic> entry) {
      final actionIndex = entry['action_index'];
      final actionType =
          (entry['action_type']?.toString().trim().isNotEmpty ?? false)
          ? entry['action_type'].toString().trim()
          : 'unknown_action';
      final decision = entry['decision']?.toString().trim() ?? '-';
      final dropped = entry['dropped'] == true;

      final beforeAction = mapOrEmpty(entry['before']);
      final afterAction = mapOrEmpty(entry['after']);
      final beforeType =
          beforeAction['type']?.toString().trim().isNotEmpty == true
          ? beforeAction['type'].toString().trim()
          : actionType;
      final afterType =
          afterAction['type']?.toString().trim().isNotEmpty == true
          ? afterAction['type'].toString().trim()
          : actionType;
      final typeText = beforeType == afterType
          ? beforeType
          : '$beforeType->$afterType';

      final beforeData = mapOrEmpty(beforeAction['data']);
      final afterData = mapOrEmpty(afterAction['data']);
      final dataDelta = formatDataDelta(beforeData, afterData);

      final prefix = '[a$actionIndex]';
      final applyScore = fmtNum(entry['apply_score']);
      final rawMagnitude = fmtNum(entry['raw_magnitude']);
      final finalScale = dropped ? '-' : fmtNum(entry['final_scale']);
      if (dropped) {
        return '$prefix DROP $typeText apply=$applyScore raw=$rawMagnitude '
            'decision=$decision before=${aiDebugShortMap(beforeData, maxEntries: 6, maxValueLen: 44)}';
      }
      return '$prefix $typeText apply=$applyScore raw=$rawMagnitude '
          'final=$finalScale decision=$decision delta={$dataDelta}';
    }

    bool isMagnitudeEntryChanged(Map<String, dynamic> entry) {
      if (entry['dropped'] == true) return true;
      final beforeAction = mapOrEmpty(entry['before']);
      final afterAction = mapOrEmpty(entry['after']);
      final beforeType = beforeAction['type']?.toString() ?? '';
      final afterType = afterAction['type']?.toString() ?? '';
      if (beforeType != afterType) return true;
      final beforeData = mapOrEmpty(beforeAction['data']);
      final afterData = mapOrEmpty(afterAction['data']);
      return formatDataDelta(beforeData, afterData) != 'no_data_delta';
    }

    String formatGoalCompact(Map<String, dynamic> goal) {
      final parts = <String>[
        'scope=${goal['scope'] ?? 'auto'}',
        if (goal['row_index'] != null) 'row=${goal['row_index']}',
        if ((goal['role']?.toString().trim() ?? '').isNotEmpty)
          'role=${goal['role']}',
        if (goal['intensity'] is num)
          'intensity=${(goal['intensity'] as num).toStringAsFixed(2)}',
      ];
      final intents =
          (goal['intents'] as List?)
              ?.whereType<Map>()
              .map((rawIntent) {
                final intent = Map<String, dynamic>.from(rawIntent);
                final bits = <String>[intent['kind']?.toString() ?? 'unknown'];
                final direction = intent['direction']?.toString();
                final descriptor = intent['descriptor']?.toString();
                if ((direction ?? '').trim().isNotEmpty)
                  bits.add(direction!.trim());
                if ((descriptor ?? '').trim().isNotEmpty) {
                  bits.add(descriptor!.trim());
                }
                if (intent['confidence'] is num) {
                  bits.add((intent['confidence'] as num).toStringAsFixed(2));
                }
                return bits.join('/');
              })
              .join(', ') ??
          '';
      if (intents.isNotEmpty) {
        parts.add('intents=$intents');
      }
      return parts.join(' ');
    }

    String formatStepLine(int index, Map<String, dynamic> step) {
      final goal = step['goal'] is Map
          ? Map<String, dynamic>.from(step['goal'] as Map)
          : const <String, dynamic>{};
      final heuristicCount =
          ((step['heuristic_actions'] as List?) ?? const []).length;
      final refinedCount =
          ((step['refined_actions'] as List?) ?? const []).length;
      final fallback = step['fallback_reason']?.toString().trim() ?? '';
      final fallbackPart = fallback.isEmpty ? '' : ' fallback=$fallback';
      return '  ${index + 1}. ${formatGoalCompact(goal)} '
          '[heuristic=$heuristicCount refined=$refinedCount$fallbackPart]';
    }

    final b = StringBuffer()
      ..writeln('AI Prompt Cycle')
      ..writeln('trace: $promptTraceId')
      ..writeln('tool: ${toolName.isEmpty ? '-' : toolName}')
      ..writeln(
        'route: ${fmtStr('llm_route')}  prompt: ${fmtStr('prompt_source')}',
      )
      ..writeln(
        'timings: total=${promptCycleTotalMs}ms project=${fmtMs('project_stats_ms')} '
        'proxy=${fmtMs('proxy_roundtrip_ms')} openai=${fmtMs('openai_api_ms')} '
        'mixPlan=${fmtMs('mix_plan_ms')} heuristic=${fmtMs('mix_model_heuristic_ms')} '
        'onnx=${fmtMs('mix_model_onnx_ms')} apply=${applyMixMs == null ? '-' : '${applyMixMs}ms'}',
      )
      ..writeln(
        'models: llm=${fmtStr('effective_model')} '
        'source=${fmtStr('mix_magnitude_model_source')} '
        'bundle=${fmtStr('mix_magnitude_model_bundle_version')} '
        'apply=${fmtStr('mix_apply_model_version')} '
        'regressor=${fmtStr('mix_magnitude_regressor_version')}',
      );

    final fallbackReasons =
        meta?['learned_magnitude_fallback_reasons'] as List? ?? const [];
    b.writeln(
      'magnitude: enabled=${meta?['learned_magnitude_enabled']} '
      'ready=${meta?['learned_magnitude_ready']} '
      'bypassed=${meta?['learned_magnitude_bypassed']} '
      'fallback=${meta?['learned_magnitude_fallback_used']} '
      'reasons=${fallbackReasons.isEmpty ? '-' : fallbackReasons.join(",")}',
    );

    if (steps.isEmpty) {
      b.writeln('steps: none');
    } else {
      final maxVisibleSteps = kAiDebugVerbose ? 4 : 2;
      final visibleCount = math.min(steps.length, maxVisibleSteps);
      b.writeln('steps: ${steps.length}');
      for (int i = 0; i < visibleCount; i++) {
        final step = steps[i];
        b.writeln(formatStepLine(i, step));
        final magnitudeEntries = listOfMaps(step['magnitude_debug']);
        if (magnitudeEntries.isNotEmpty) {
          final droppedCount = magnitudeEntries
              .where((entry) => entry['dropped'] == true)
              .length;
          final changedCount = magnitudeEntries
              .where(isMagnitudeEntryChanged)
              .length;
          b.writeln(
            '     onnx_deltas=${magnitudeEntries.length} '
            'changed=$changedCount dropped=$droppedCount',
          );
          if (kAiDebugVerbose) {
            final visibleDeltas = magnitudeEntries.length;
            for (int j = 0; j < visibleDeltas; j++) {
              b.writeln('       ${formatMagnitudeEntry(magnitudeEntries[j])}');
            }
          } else {
            final topEntries = magnitudeEntries.take(2).toList(growable: false);
            for (final entry in topEntries) {
              b.writeln('       ${formatMagnitudeEntry(entry)}');
            }
            if (magnitudeEntries.length > topEntries.length) {
              b.writeln(
                '       ... +${magnitudeEntries.length - topEntries.length} more action delta(s)',
              );
            }
          }
        }
      }
      if (steps.length > visibleCount) {
        b.writeln('  ... +${steps.length - visibleCount} more step(s)');
      }
    }

    aiDebugBlock('prompt-debug', 'AI prompt cycle', b.toString());
  }

  Map<String, dynamic>? _pickParam(
    List<Map<String, dynamic>> params, {
    String? exactName,
    List<String>? containsAny,
  }) {
    final lowerExact = exactName?.toLowerCase();

    Map<String, dynamic>? best;
    int bestScore = -1;

    for (final p in params) {
      final name = (p['name']?.toString() ?? '');
      final n = name.toLowerCase();

      int score = 0;
      if (lowerExact != null && n == lowerExact) score += 100;
      if (containsAny != null &&
          containsAny.any((s) => n.contains(s.toLowerCase())))
        score += 50;
      if (score > bestScore) {
        bestScore = score;
        best = p;
      }
    }

    return bestScore > 0 ? best : null;
  }

  Future<_ResolvedMixEffectParameter?> _waitForReadyRowMixParameter({
    required int row,
    required String effectNameContains,
    String? exactParameterName,
    List<String>? parameterNameContainsAny,
    bool forceIndividualRow = false,
  }) async {
    final deadline = DateTime.now().add(_kAiMixEffectReadyTimeout);
    do {
      try {
        final values = await Future.wait<dynamic>(<Future<dynamic>>[
          JuceAudioEngine.getTrackEffectsForRow(
            row,
            forceIndividualRow: forceIndividualRow,
          ),
          JuceAudioEngine.getTrackEffectIdsForRow(
            row,
            forceIndividualRow: forceIndividualRow,
          ),
          JuceAudioEngine.getTrackEffectInstanceIdsForRow(
            row,
            forceIndividualRow: forceIndividualRow,
          ),
        ]).timeout(_kAiMixEffectProbeTimeout);
        final effects = (values[0] as List).cast<String>();
        final effectIds = (values[1] as List).cast<String>();
        final instanceIds = (values[2] as List).cast<String>();
        final effectIndex = effects.indexWhere(
          (name) => name.toLowerCase().contains(effectNameContains),
        );
        if (effectIndex >= 0 &&
            effectIndex < effectIds.length &&
            effectIndex < instanceIds.length &&
            effectIds[effectIndex].trim().isNotEmpty &&
            instanceIds[effectIndex].trim().isNotEmpty) {
          final rawParameters = await JuceAudioEngine.getTrackPluginParameters(
            row,
            effectIndex,
            forceIndividualRow: forceIndividualRow,
          ).timeout(_kAiMixEffectProbeTimeout);
          final parameters = exposedEffectParameters(
            effects[effectIndex],
            rawParameters,
          );
          final parameter = _pickParam(
            parameters,
            exactName: exactParameterName,
            containsAny: parameterNameContainsAny,
          );
          if (parameter != null) {
            return _ResolvedMixEffectParameter(
              effectIndex: effectIndex,
              effectId: effectIds[effectIndex],
              effectName: effects[effectIndex],
              effectInstanceId: instanceIds[effectIndex],
              effectOccurrence: effectIds
                  .take(effectIndex)
                  .where((id) => id == effectIds[effectIndex])
                  .length,
              parameter: parameter,
            );
          }
        }
      } on TimeoutException {
        throw StateError('mix_effect_readiness_timeout');
      }
      if (DateTime.now().isBefore(deadline)) {
        await Future<void>.delayed(_kAiMixEffectProbeInterval);
      }
    } while (DateTime.now().isBefore(deadline));
    return null;
  }

  Future<_ResolvedMixEffectParameter?> _waitForReadyMasterMixParameter({
    required String effectNameContains,
    String? exactParameterName,
    List<String>? parameterNameContainsAny,
  }) async {
    final deadline = DateTime.now().add(_kAiMixEffectReadyTimeout);
    do {
      try {
        final values = await Future.wait<dynamic>(<Future<dynamic>>[
          JuceAudioEngine.getMasterEffects(),
          JuceAudioEngine.getMasterEffectIds(),
        ]).timeout(_kAiMixEffectProbeTimeout);
        final effects = (values[0] as List).cast<String>();
        final effectIds = (values[1] as List).cast<String>();
        final effectIndex = effects.indexWhere(
          (name) => name.toLowerCase().contains(effectNameContains),
        );
        if (effectIndex >= 0 &&
            effectIndex < effectIds.length &&
            effectIds[effectIndex].trim().isNotEmpty) {
          final rawParameters = await JuceAudioEngine.getMasterPluginParameters(
            effectIndex,
          ).timeout(_kAiMixEffectProbeTimeout);
          final parameters = exposedEffectParameters(
            effects[effectIndex],
            rawParameters,
          );
          final parameter = _pickParam(
            parameters,
            exactName: exactParameterName,
            containsAny: parameterNameContainsAny,
          );
          if (parameter != null) {
            return _ResolvedMixEffectParameter(
              effectIndex: effectIndex,
              effectId: effectIds[effectIndex],
              effectName: effects[effectIndex],
              parameter: parameter,
            );
          }
        }
      } on TimeoutException {
        throw StateError('mix_master_effect_readiness_timeout');
      }
      if (DateTime.now().isBefore(deadline)) {
        await Future<void>.delayed(_kAiMixEffectProbeInterval);
      }
    } while (DateTime.now().isBefore(deadline));
    return null;
  }

  Future<ProjectState> _buildCurrentAiProjectState() async {
    final maxRows = math.max(_rowCount, 1);

    final rowGain = List<double>.generate(
      maxRows,
      (i) => i < _rowGain.length ? _rowGain[i] : _kGainUiUnity,
    );
    final rowPan = List<double>.generate(
      maxRows,
      (i) => i < _rowPan.length ? _rowPan[i] : 0.5,
    );
    final rowAutomation = List<List<AutomationPoint>>.generate(maxRows, (i) {
      if (i < _rowVolumeAutomation.length) {
        return _rowVolumeAutomation[i]
            .map((p) => AutomationPoint(x: p.x, volume: p.volume))
            .toList();
      }
      return [AutomationPoint(x: 0.0, volume: 1.0)];
    });

    final builder = ProjectStateBuilder(
      classifier: _classifier,
      maxRows: maxRows,
    );
    final aiTrackGroups = await _trackGroupsForAiProjectState();
    return builder.build(
      audioTracks: _audioTracks,
      bpmFallback: _tempo,
      projectKey: _projectKey,
      rowGain: rowGain,
      rowPan: rowPan,
      rowAutomation: rowAutomation,
      masterGain0to3: _masterGain,
      masterPan0to1: _masterPan,
      timelineRows: _visibleAiRows(),
      trackGroups: aiTrackGroups,
    );
  }

  Future<Map<String, dynamic>> _buildProducerSnapshot() async {
    final projectState = await _buildCurrentAiProjectState();

    final masterEffects = await JuceAudioEngine.getMasterEffects();
    final masterFx = <Map<String, dynamic>>[];
    for (int i = 0; i < masterEffects.length; i++) {
      final params = exposedEffectParameters(
        masterEffects[i],
        await JuceAudioEngine.getMasterPluginParameters(i),
      );
      final bypassed = await JuceAudioEngine.getMasterEffectBypassState(i);
      masterFx.add({
        'index': i,
        'name': masterEffects[i],
        'bypassed': bypassed,
        'params': params,
      });
    }

    return {
      'captured_at': DateTime.now().toUtc().toIso8601String(),
      'tempo_bpm': _tempo,
      'project_state': projectState.toJson(),
      'master': {'gain': _masterGain, 'pan': _masterPan, 'effects': masterFx},
    };
  }

  void _recordProducerManualEdit(String kind, Map<String, dynamic> payload) {
    if (!_producerDataMode) return;
    unawaited(
      _producerCollector.recordManualEdit(
        kind: kind,
        payload: {...payload, 'at': DateTime.now().toUtc().toIso8601String()},
        projectId: _projectId,
        projectName: _projectName,
        projectDir: _projectDir,
      ),
    );
  }

  int _beginChatFlow() {
    final flowId = ++_chatFlowSequence;
    if (mounted) {
      setState(() {
        _activeChatFlowId = flowId;
        _isThinking = true;
      });
    } else {
      _activeChatFlowId = flowId;
      _isThinking = true;
    }
    if (!_chatScrollHintEnabled) {
      _scrollChatToLatest();
    }
    return flowId;
  }

  bool _isChatFlowActive(int flowId) => _activeChatFlowId == flowId;

  void _throwIfChatFlowStopped(int flowId) {
    if (!_isChatFlowActive(flowId)) {
      throw const _ChatFlowCancelledException();
    }
  }

  void _endChatFlow(int flowId) {
    if (_activeChatFlowId != flowId) return;
    if (mounted) {
      setState(() {
        _activeChatFlowId = null;
        _isThinking = false;
      });
      _scrollChatToLatest();
    } else {
      _activeChatFlowId = null;
      _isThinking = false;
    }
  }

  void _stopActiveChatFlow() {
    if (_activeChatFlowId == null) return;
    _chatFocusNode.unfocus();
    if (mounted) {
      setState(() {
        _activeChatFlowId = null;
        _isThinking = false;
        _chatInputActive = false;
      });
    } else {
      _activeChatFlowId = null;
      _isThinking = false;
      _chatInputActive = false;
    }
  }

  void _resolveAiV3Clarification(String? clarificationId) {
    if (!_aiV3ClarificationSession.resolve(clarificationId)) return;
    if (mounted) {
      setState(() {});
    }
  }

  Widget _buildSystemChatMessage(TextMessage message) {
    final metadata = message.metadata;
    final detailLines = _chatExecutionDetailLines(metadata);
    if (detailLines.isEmpty) {
      return GestureDetector(
        behavior: HitTestBehavior.opaque,
        onSecondaryTapDown: (_) {
          unawaited(_copyChatMessageToClipboard(message));
        },
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 10),
          child: Center(
            child: Text(
              message.text,
              textAlign: TextAlign.center,
              style: const TextStyle(
                fontFamily: 'Pretendard',
                fontSize: 13,
                fontWeight: FontWeight.w600,
                letterSpacing: 0.4,
                color: Colors.white70,
              ),
            ),
          ),
        ),
      );
    }

    final collapsedByDefault = metadata?['collapsed_by_default'] == true;
    final isExpanded =
        !collapsedByDefault ||
        _expandedChatDetailMessageIds.contains(message.id);
    final title = _plainSystemDetailText(
      '${metadata?['collapsed_title'] ?? message.text}',
    );

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 6),
      child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 560),
          child: DecoratedBox(
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.07),
              borderRadius: BorderRadius.circular(14),
              border: Border.all(color: Colors.white.withValues(alpha: 0.10)),
            ),
            child: Material(
              type: MaterialType.transparency,
              child: InkWell(
                borderRadius: BorderRadius.circular(14),
                onTap: () {
                  setState(() {
                    if (_expandedChatDetailMessageIds.contains(message.id)) {
                      _expandedChatDetailMessageIds.remove(message.id);
                    } else {
                      _expandedChatDetailMessageIds.add(message.id);
                    }
                  });
                },
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(10, 8, 12, 8),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            isExpanded
                                ? Icons.keyboard_arrow_down_rounded
                                : Icons.keyboard_arrow_right_rounded,
                            size: 18,
                            color: Colors.white70,
                          ),
                          const SizedBox(width: 4),
                          Flexible(
                            child: Text(
                              title.isEmpty
                                  ? 'Applied ${detailLines.length} changes'
                                  : title,
                              style: const TextStyle(
                                fontFamily: 'Pretendard',
                                fontSize: 13,
                                fontWeight: FontWeight.w700,
                                height: 1.2,
                                letterSpacing: 0.1,
                                color: Color(0xC7FFFFFF),
                              ),
                            ),
                          ),
                        ],
                      ),
                      if (isExpanded) ...[
                        const SizedBox(height: 7),
                        for (final line in detailLines)
                          Padding(
                            padding: const EdgeInsets.only(left: 22, bottom: 5),
                            child: Text(
                              line,
                              style: TextStyle(
                                fontFamily: 'Pretendard',
                                fontSize: 12,
                                fontWeight: FontWeight.w600,
                                height: 1.25,
                                color: Colors.white.withValues(alpha: 0.72),
                              ),
                            ),
                          ),
                      ],
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  List<String> _chatExecutionDetailLines(Map<String, dynamic>? metadata) {
    final raw = metadata?['detail_lines'];
    if (raw is! Iterable) return const <String>[];
    return raw
        .map((line) => _plainSystemDetailText('$line'))
        .where((line) => line.isNotEmpty)
        .toList(growable: false);
  }

  void _insertUserChatText(String text) {
    _insertChatTextMessage(authorId: 'user', text: text);
  }

  void _insertAssistantChatText(
    String text, {
    bool modelAuthored = false,
    Map<String, dynamic>? metadata,
  }) {
    if (!modelAuthored && _assistantActionNoticeCaptureDepth > 0) {
      _insertAssistantActionExecutionSystemText(text);
      return;
    }
    _insertChatTextMessage(
      authorId: 'assistant',
      text: text,
      metadata: metadata,
    );
  }

  void _insertSystemChatText(
    String text, {
    Map<String, dynamic>? metadata,
    bool persist = true,
  }) {
    final deferredNotices = _deferredAssistantExecutionNotices;
    if (_assistantActionNoticeCaptureDepth > 0 && deferredNotices != null) {
      final normalized = text.trim();
      if (normalized.isNotEmpty && !deferredNotices.contains(normalized)) {
        deferredNotices.add(normalized);
      }
      return;
    }
    _insertChatTextMessage(
      authorId: 'system',
      text: text,
      metadata: metadata,
      persist: persist,
    );
  }

  String _centeredSystemChatText(String text) {
    final trimmed = text.trim();
    if (trimmed.isEmpty) return '';
    return trimmed.startsWith('•') && trimmed.endsWith('•')
        ? trimmed
        : '• $trimmed •';
  }

  String _plainSystemDetailText(String text) {
    var trimmed = text.trim();
    if (trimmed.startsWith('•')) {
      trimmed = trimmed.substring(1).trimLeft();
    }
    if (trimmed.endsWith('•')) {
      trimmed = trimmed.substring(0, trimmed.length - 1).trimRight();
    }
    return trimmed;
  }

  static const int _kChatExecutionDetailCollapseThreshold = 3;

  void _insertExecutionDetailSystemText({
    required String source,
    required String collapsedTitle,
    required List<String> detailLines,
  }) {
    final lines = detailLines
        .map(_plainSystemDetailText)
        .where((line) => line.isNotEmpty)
        .toList(growable: false);
    if (lines.isEmpty) return;
    if (lines.length < _kChatExecutionDetailCollapseThreshold) {
      for (final line in lines) {
        _insertSystemChatText(
          _centeredSystemChatText(line),
          metadata: <String, dynamic>{'source': source},
        );
      }
      return;
    }

    final title = collapsedTitle.trim().isEmpty
        ? 'Applied ${lines.length} changes'
        : collapsedTitle.trim();
    _insertSystemChatText(
      _centeredSystemChatText(title),
      metadata: <String, dynamic>{
        'source': source,
        'detail_lines': lines,
        'collapsed_title': title,
        'collapsed_by_default': true,
      },
    );
  }

  void _flushAssistantActionExecutionBatch() {
    if (_assistantActionExecutionBatch.isEmpty) return;
    final lines = List<String>.from(_assistantActionExecutionBatch);
    _assistantActionExecutionBatch.clear();
    _insertExecutionDetailSystemText(
      source: 'daw_assistant_action_execution',
      collapsedTitle: 'Applied ${lines.length} DAW actions',
      detailLines: lines,
    );
  }

  void _insertAssistantActionNoticeSystemText(String text) {
    if (_assistantActionNoticeCaptureDepth <= 0) return;
    final displayText = _centeredSystemChatText(text);
    if (displayText.isEmpty) return;
    final deferredNotices = _deferredAssistantActionNotices;
    if (deferredNotices != null) {
      final normalized = text.trim();
      if (normalized.isNotEmpty && !deferredNotices.contains(normalized)) {
        deferredNotices.add(normalized);
      }
      return;
    }
    _insertSystemChatText(
      displayText,
      metadata: const <String, dynamic>{
        'source': 'daw_assistant_action_notice',
      },
    );
  }

  void _insertAssistantActionExecutionSystemText(String text) {
    final displayText = _centeredSystemChatText(text);
    if (displayText.isEmpty) return;
    _assistantActionExecutionMessageCount += 1;
    if (_deferredAssistantExecutionNotices == null &&
        _assistantActionExecutionBatchDepth > 0) {
      _assistantActionExecutionBatch.add(displayText);
      return;
    }
    _insertSystemChatText(
      displayText,
      metadata: const <String, dynamic>{
        'source': 'daw_assistant_action_execution',
      },
    );
  }

  void _insertAiFailureSystemText(String text) {
    final displayText = _centeredSystemChatText(text);
    if (displayText.isEmpty) return;
    _insertSystemChatText(
      displayText,
      metadata: const <String, dynamic>{'source': 'ai_chat_failure'},
    );
  }

  void _insertChatTextMessage({
    required String authorId,
    required String text,
    DateTime? createdAt,
    Map<String, dynamic>? metadata,
    bool persist = true,
  }) {
    if (!mounted || _chatMutationDisposed) return;
    final trimmed = text.trim();
    if (trimmed.isEmpty) return;
    final cappedText = _truncateChatMessageText(trimmed);
    if (cappedText.isEmpty) return;

    final existingMessages = <Message>[
      ..._chatController.messages,
      ..._pendingChatInsertions,
    ];
    if (existingMessages.isNotEmpty) {
      final lastMessage = existingMessages.last;
      if (lastMessage is TextMessage &&
          lastMessage.authorId == authorId &&
          lastMessage.text.trim() == cappedText) {
        return;
      }
    }

    _pendingChatInsertions.add(
      TextMessage(
        id: const Uuid().v4(),
        authorId: authorId,
        createdAt: (createdAt ?? DateTime.now()).toUtc(),
        text: cappedText,
        metadata: metadata,
      ),
    );

    _scheduleChatInsertionFlush();
    if (!persist) return;
    _scheduleChatHistoryPersist();
    if (authorId == 'user' || authorId == 'assistant' || authorId == 'system') {
      _scrollChatToLatest();
    }
  }

  String _truncateChatMessageText(String text) {
    final maxCharacters =
        kDefaultProjectChatHistoryLimits.maxStoredMessageCharacters;
    if (maxCharacters <= 0) return '';
    if (text.length <= maxCharacters) return text;
    if (maxCharacters == 1) return text.substring(0, 1);
    return '${text.substring(0, maxCharacters - 1)}…';
  }

  int _chatTextMessageCount({String? authorId}) {
    int count = 0;
    for (final message in _chatController.messages) {
      if (message is! TextMessage) continue;
      if (authorId != null && message.authorId != authorId) continue;
      count++;
    }
    return count;
  }

  String _completedAssistantReplyText(String message) {
    return message.trim();
  }

  Future<void> _presentPipelineReply(
    ChatPipelineResult reply, {
    int? chatFlowId,
  }) async {
    if (reply.hasAiV3Handoff) {
      await _presentAiV3Handoff(reply.aiV3Handoff!, chatFlowId: chatFlowId);
      return;
    }
    // Ordering note for source-coverage tests:
    // _insertAssistantChatText(reply.message);
    // await _applyAssistantActions(reply.assistantActions);
    final assistantMessagesBefore = _chatTextMessageCount(
      authorId: 'assistant',
    );

    var actionsApplied = true;
    if (reply.hasAssistantActions) {
      actionsApplied = await _applyAssistantActions(
        reply.assistantActions,
        chatFlowId: chatFlowId,
      );
    }

    final assistantMessagesAfter = _chatTextMessageCount(authorId: 'assistant');
    final shouldInsertPrimaryReply =
        actionsApplied &&
        reply.message.trim().isNotEmpty &&
        (!reply.hasAssistantActions ||
            assistantMessagesAfter == assistantMessagesBefore);
    if (shouldInsertPrimaryReply) {
      if (chatFlowId != null) {
        _throwIfChatFlowStopped(chatFlowId);
      }
      _insertAssistantChatText(
        _completedAssistantReplyText(reply.message),
        modelAuthored: true,
      );
    }
    if (LlmConfig.aiLiveEvaluationEnabled) {
      await _performAutosaveWrite();
    }
  }

