                Map<String, dynamic>.from(expectation['source_payload'] as Map),
              )) {
            return false;
          }
          final vocalsMatches = _audioTracks
              .where((clip) => clip.clipId == expectation['vocals_clip_id'])
              .toList(growable: false);
          final instrumentalMatches = _audioTracks
              .where(
                (clip) => clip.clipId == expectation['instrumental_clip_id'],
              )
              .toList(growable: false);
          final vocalsExpected = generatedResource(
            expectation['vocals_clip_id'].toString(),
          );
          final instrumentalExpected = generatedResource(
            expectation['instrumental_clip_id'].toString(),
          );
          final vocalsPresent =
              expectation['vocals_row_deleted'] != true &&
              vocalsExpected?['present'] != false;
          final instrumentalPresent =
              expectation['instrumental_row_deleted'] != true &&
              instrumentalExpected?['present'] != false;
          if (vocalsMatches.length != (vocalsPresent ? 1 : 0) ||
              instrumentalMatches.length != (instrumentalPresent ? 1 : 0)) {
            return false;
          }
          final vocals = vocalsMatches.firstOrNull;
          final instrumental = instrumentalMatches.firstOrNull;
          final vocalsTransformed =
              expectation['vocals_clip_transformed'] == true;
          final instrumentalTransformed =
              expectation['instrumental_clip_transformed'] == true;
          final sourceRow = _rowIndexForId(
            (expectation['source_row_id'] as num).toInt(),
          );
          final beforeRowIds =
              (expectation['before_row_ids'] as List? ?? const <Object>[])
                  .map((value) => (value as num).toInt())
                  .toList(growable: false);
          final survivingRowIds = _rows
              .map((row) => row.rowId)
              .where(beforeRowIds.contains)
              .toList(growable: false);
          final vocalsFile = File(expectation['vocals_file'].toString());
          final instrumentalFile = File(
            expectation['instrumental_file'].toString(),
          );
          bool neutral(AudioTrack clip, {required bool timingTransformed}) {
            final expectsTempoFollow =
                expectation['outputs_follow_tempo'] == true;
            return !clip.isMidi &&
                clip.gain == kDefaultGainUi &&
                !clip.normalizeVolume &&
                (clip.normalizeGain - 1.0).abs() <= epsilon &&
                !clip.isReversed &&
                (timingTransformed ||
                    (clip.stretchToProjectTempo == expectsTempoFollow &&
                        (!expectsTempoFollow ||
                            clip.tempoStretchPreservePitch ==
                                (expectation['outputs_preserve_pitch'] ==
                                    true)))) &&
                clip.volumeAutomation.every(
                  (point) => (point.volume - 1.0).abs() <= epsilon,
                );
          }
          if (!_isValidRowIndex(sourceRow) ||
              (vocals != null &&
                  (vocals.rowId != expectation['vocals_row_id'] ||
                      vocals.label != expectation['vocals_label'] ||
                      (!vocalsTransformed &&
                          (_clipTimelineDurationSec(vocals) -
                                      (expectation['vocals_length'] as num)
                                          .toDouble())
                                  .abs() >
                              0.1) ||
                      !neutral(
                        vocals,
                        timingTransformed: vocalsTransformed,
                      ))) ||
              (instrumental != null &&
                  (instrumental.rowId != expectation['instrumental_row_id'] ||
                      instrumental.label != expectation['instrumental_label'] ||
                      (!instrumentalTransformed &&
                          (_clipTimelineDurationSec(instrumental) -
                                      (expectation['instrumental_length']
                                              as num)
                                          .toDouble())
                                  .abs() >
                              0.1) ||
                      !neutral(
                        instrumental,
                        timingTransformed: instrumentalTransformed,
                      ))) ||
              (vocals != null &&
                  instrumental != null &&
                  vocals.rowId == instrumental.rowId) ||
              survivingRowIds.length != beforeRowIds.length ||
              !listEquals(survivingRowIds, beforeRowIds) ||
              !await vocalsFile.exists() ||
              await vocalsFile.length() <= 44 ||
              !await instrumentalFile.exists() ||
              await instrumentalFile.length() <= 44) {
            return false;
          }
          break;
        case 'audio_converted_to_midi':
          final resultDeleted = expectation['result_clip_deleted'] == true;
          final resultTransformed = expectation['resource_transformed'] == true;
          final sourceMatches = _audioTracks
              .where((clip) => clip.clipId == expectation['source_clip_id'])
              .toList(growable: false);
          final resultMatches = _audioTracks
              .where((clip) => clip.clipId == expectation['result_clip_id'])
              .toList(growable: false);
          if (sourceMatches.length != 1 ||
              resultMatches.length != (resultDeleted ? 0 : 1) ||
              !_aiV3ClipMatchesPersistedPayload(
                sourceMatches.single,
                Map<String, dynamic>.from(expectation['source_payload'] as Map),
              )) {
            return false;
          }
          final sourceRow = _rowIndexForId(
            (expectation['source_row_id'] as num).toInt(),
          );
          final beforeRowIds =
              (expectation['before_row_ids'] as List? ?? const <Object>[])
                  .map((value) => (value as num).toInt())
                  .toList(growable: false);
          final survivingRowIds = _rows
              .map((row) => row.rowId)
              .where(beforeRowIds.contains)
              .toList(growable: false);
          if (!_isValidRowIndex(sourceRow) ||
              survivingRowIds.length != beforeRowIds.length ||
              !listEquals(survivingRowIds, beforeRowIds)) {
            return false;
          }
          if (resultDeleted) break;
          final result = resultMatches.single;
          final actualNotes = result.midiNotes
              .map(
                (note) => <String, dynamic>{
                  'pitch': note.pitch,
                  'start_beat': note.startBeat,
                  'length_beats': note.lengthBeats,
                  'velocity': note.velocity,
                },
              )
              .toList(growable: false);
          if (!result.isMidi ||
              result.rowIndex != sourceRow + 1 ||
              result.label != expectation['result_label'] ||
              result.instrumentId != expectation['instrument_id'] ||
              (!resultTransformed &&
                  ((result.offset - (expectation['start'] as num).toDouble())
                              .abs() >
                          0.002 ||
                      (_clipTimelineDurationSec(result) -
                                  (expectation['length'] as num).toDouble())
                              .abs() >
                          0.002 ||
                      jsonEncode(actualNotes) !=
                          jsonEncode(expectation['notes'])))) {
            return false;
          }
          break;
        case 'samples_created':
          final before = (expectation['before_clip_ids'] as List)
              .map((id) => '$id')
              .toSet();
          final runtimeClipId =
              expectation['runtime_clip_id']?.toString() ?? '';
          final generated = generatedResource(runtimeClipId);
          if (runtimeClipId.isNotEmpty && generated != null) {
            final matchingIdentity = _audioTracks
                .where(
                  (clip) =>
                      clip.clipId == runtimeClipId &&
                      !before.contains(clip.clipId) &&
                      !clip.isMidi,
                )
                .toList(growable: false);
            if (generated['present'] == false) {
              if (matchingIdentity.isNotEmpty) return false;
            } else if (matchingIdentity.length != 1) {
              return false;
            } else {
              final clip = matchingIdentity.single;
              final expectedRowId = _toActionInt(generated['row_id']);
              final expectedFile = generated['file']?.toString();
              if ((expectedRowId != null && clip.rowId != expectedRowId) ||
                  (expectedFile != null && clip.file.path != expectedFile)) {
                return false;
              }
            }
            break;
          }
          final unmatched = _audioTracks
              .where((clip) => !before.contains(clip.clipId) && !clip.isMidi)
              .toList(growable: true);
          for (final raw in expectation['items'] as List) {
            final item = Map<String, dynamic>.from(raw as Map);
            if (generated != null && generated['present'] == false) {
              if (_audioTracks.any((clip) => clip.clipId == runtimeClipId)) {
                return false;
              }
              continue;
            }
            final index = unmatched.indexWhere(
              (clip) =>
                  (runtimeClipId.isEmpty || clip.clipId == runtimeClipId) &&
                  clip.rowIndex == item['row'] &&
                  clip.file.path == item['file'],
            );
            if (index < 0) return false;
            unmatched.removeAt(index);
          }
          break;
        case 'generated_resource_state':
          final clipId = expectation['clip_id']?.toString() ?? '';
          final matches = _audioTracks
              .where((clip) => clip.clipId == clipId)
              .toList(growable: false);
          if (expectation['present'] == false) {
            if (matches.isNotEmpty) return false;
            break;
          }
          if (matches.length != 1) return false;
          final clip = matches.single;
          final expectedMidi =
              expectation['resource_kind'] == AiV3ResourceKind.midiClip.name;
          final expectedRowId = _toActionInt(expectation['row_id']);
          if (clip.isMidi != expectedMidi ||
              (expectedRowId != null && clip.rowId != expectedRowId) ||
              (clip.offset - (expectation['start'] as num).toDouble()).abs() >
                  0.002) {
            return false;
          }
          final expectedEnd = _toActionDouble(expectation['end']);
          if (expectedEnd != null &&
              (clip.offset + _clipTimelineDurationSec(clip) - expectedEnd)
                      .abs() >
                  0.003) {
            return false;
          }
          final expectedPitch = _toActionDouble(expectation['pitch_semitones']);
          if (expectedPitch != null &&
              (clip.pitchSemitones - expectedPitch).abs() > epsilon) {
            return false;
          }
          if (!expectedMidi) {
            final expectedFile = expectation['file']?.toString();
            final expectedLabel = expectation['label']?.toString();
            final expectedAlignmentOffset = _toActionDouble(
              expectation['alignment_offset_ms'],
            );
            final expectedRawDuration = _toActionDouble(
              expectation['raw_duration_sec'],
            );
            final expectedSourceTempo = _toActionDouble(
              expectation['source_tempo_bpm'],
            );
            final expectedMode = expectation['tempo_follow_mode']?.toString();
            final expectedPreservePitch = expectation['tempo_preserve_pitch'];
            if ((expectedFile != null &&
                    _normalizedClipPath(clip.file.path) !=
                        _normalizedClipPath(expectedFile)) ||
                (expectedLabel != null && clip.label != expectedLabel) ||
                (expectedAlignmentOffset != null &&
                    (clip.alignmentOffsetMs - expectedAlignmentOffset).abs() >
                        0.5) ||
                (expectedRawDuration != null &&
                    (_rawClipDurationSec(clip) - expectedRawDuration).abs() >
                        0.002) ||
                (expectedSourceTempo != null &&
                    (clip.sourceTempoBpm - expectedSourceTempo).abs() >
                        0.0001) ||
                (expectedMode != null &&
                    _aiV3AudioTempoFollowMode(clip) != expectedMode) ||
                (expectedPreservePitch is bool &&
                    clip.tempoStretchPreservePitch != expectedPreservePitch)) {
              return false;
            }
          }
          final expectedTrimStart = _toActionDouble(
            expectation['trim_start_ms'],
          );
          final expectedTrimEnd = _toActionDouble(expectation['trim_end_ms']);
          if ((expectedTrimStart != null &&
                  (clip.trimStart.inMilliseconds - expectedTrimStart).abs() >
                      1.0) ||
              (expectedTrimEnd != null &&
                  (clip.trimEnd.inMilliseconds - expectedTrimEnd).abs() >
                      1.0)) {
            return false;
          }
          final expectedNotes = expectation['midi_notes'];
          if (expectedNotes is List) {
            final actualNotes = _aiV3MidiNotePayload(clip);
            final canonicalExpected = aiV3CanonicalMidiNotes(
              expectedNotes.cast<Map>().map(
                (note) => Map<String, dynamic>.from(note),
              ),
            );
            if (jsonEncode(actualNotes) != jsonEncode(canonicalExpected)) {
              return false;
            }
            final expectedContentEnd = _toActionDouble(
              expectation['midi_content_end_beats'],
            );
            if (expectedContentEnd != null &&
                (_aiV3MidiContentEndBeats(actualNotes) - expectedContentEnd)
                        .abs() >
                    0.000001) {
              return false;
            }
          }
          break;
        case 'clip_absent':
          if (_audioTracks.any((clip) => clip.clipId == expectation['clip_id']))
            return false;
          break;
        case 'midi_notes':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          if (index < 0) return false;
          final actual = _aiV3MidiNotePayload(_audioTracks[index]);
          final expected = aiV3CanonicalMidiNotes(
            (expectation['value'] as List).cast<Map>().map(
              (note) => Map<String, dynamic>.from(note),
            ),
          );
          if (jsonEncode(actual) != jsonEncode(expected)) return false;
          break;
        case 'effect':
          final effects = await JuceAudioEngine.getTrackEffectsForRow(
            _aiV3ExpectationRow(expectation),
            forceIndividualRow: expectation['force_individual_row'] == true,
          );
          final needle = expectation['value'].toString().toLowerCase();
          if (!effects.any((effect) => effect.toLowerCase() == needle)) {
            return false;
          }
          break;
        case 'automation_points':
          final row = expectation['row_id'] is int
              ? _rowIndexForId(expectation['row_id'] as int)
              : expectation['row'] as int;
          final targetId =
              expectation['automation_target_id']?.toString() ?? 'volume';
          final points = _isValidRowIndex(row)
              ? _sanitizeAutomationPointsForTarget(
                  row,
                  targetId,
                  _pointsForAutomationTarget(row, targetId),
                )
              : const <AutomationPoint>[];
          final expected = expectation['points'] as List;
          if (points.length != expected.length) return false;
          for (var index = 0; index < expected.length; index++) {
            final item = Map<String, dynamic>.from(expected[index] as Map);
            if ((points[index].x - (item['x'] as num).toDouble()).abs() >
                    0.002 ||
                (points[index].volume - (item['value'] as num).toDouble())
                        .abs() >
                    epsilon) {
              return false;
            }
          }
          break;
      }
    }
    return true;
  }

  List<AudioTrack> _aiV3MatchingCreatedClips(Map<String, dynamic> expectation) {
    final before = (expectation['before_clip_ids'] as List? ?? const <Object>[])
        .map((value) => value.toString())
        .toSet();
    final expectedRow = expectation['row'] as int;
    final expectedStart = expectation['start'] as double;
    final expectedLength = expectation['length'] as double;
    final expectedMidi = expectation['is_midi'] as bool;
    final expectedFile = expectation['file'].toString();
    final expectedLabel = expectation['label'].toString();
    final expectedInstrument = expectation['instrument_id']?.toString() ?? '';
    final expectedMidiNotes = expectation['midi_notes'];
    final runtimeClipId = expectation['runtime_clip_id']?.toString() ?? '';
    final resourceTransformed = expectation['resource_transformed'] == true;
    return _audioTracks
        .where((clip) {
          if (before.contains(clip.clipId) ||
              (runtimeClipId.isNotEmpty && clip.clipId != runtimeClipId) ||
              clip.rowIndex != expectedRow ||
              clip.isMidi != expectedMidi ||
              clip.label != expectedLabel ||
              (!resourceTransformed &&
                  (clip.offset - expectedStart).abs() > 0.002)) {
            return false;
          }
          if (expectedMidi) {
            if (clip.instrumentId != expectedInstrument) return false;
            if (!resourceTransformed) {
              final actualNotes = clip.midiNotes
                  .map(
                    (note) => <String, dynamic>{
                      'pitch': note.pitch,
                      'start_beat': note.startBeat,
                      'length_beats': note.lengthBeats,
                      'velocity': note.velocity,
                    },
                  )
                  .toList(growable: false);
              if (jsonEncode(actualNotes) != jsonEncode(expectedMidiNotes)) {
                return false;
              }
            }
          } else if (clip.file.path != expectedFile) {
            return false;
          }
          return resourceTransformed ||
              (_clipTimelineDurationMs(clip) / 1000.0 - expectedLength).abs() <=
                  0.002;
        })
        .toList(growable: false);
  }

  Future<List<Map<String, dynamic>>> _observeAiV3Expectations(
    List<Map<String, dynamic>> expectations,
  ) async {
    final observed = <Map<String, dynamic>>[];
    for (final expectation in expectations) {
      final kind = expectation['kind']?.toString() ?? '';
      final item = <String, dynamic>{'kind': kind};
      switch (kind) {
        case 'bundle':
          item.addAll(<String, dynamic>{
            'state_digest': _freshAiV3StateFingerprint(),
            'row_count': _rowCount,
            'clip_count': _audioTracks.length,
          });
          break;
        case 'tempo':
          item['value'] = _tempo;
          break;
        case 'transport_playing':
          item['value'] = _isPlaying;
          break;
        case 'transport_metronome':
          item['value'] = _metronomeEnabled;
          break;
        case 'transport_loop':
          item['value'] = <String, dynamic>{
            'enabled': _loopEnabled,
            'start_ms': _loopStartMs,
            'end_ms': _loopEndMs,
          };
          break;
        case 'transport_restart_position':
          item['value'] = _globalAudioClock.inMilliseconds;
          break;
        case 'row_mute':
          final row = expectation['row_id'] is int
              ? _rowIndexForId(expectation['row_id'] as int)
              : expectation['row'] as int;
          item['value'] = _isValidRowIndex(row) && row < _rowMuted.length
              ? _rowMuted[row]
              : null;
          break;
        case 'row_selection':
          item['value'] = _isValidRowIndex(_selectedRow)
              ? _rowIdAt(_selectedRow)
              : null;
          break;
        case 'row_created':
          final runtimeRowId = expectation['runtime_row_id'];
          final createdIndex = runtimeRowId is int
              ? _rowIndexForId(runtimeRowId)
              : -1;
          final created = _isValidRowIndex(createdIndex)
              ? _rows[createdIndex]
              : null;
          item['value'] = created != null
              ? <String, dynamic>{
                  'row_id': created.rowId,
                  'name': created.name,
                  'lane_kind': created.kind.wireName,
                  'instrument_id': created.instrumentId,
                  'position': createdIndex,
                  'selected':
                      _isValidRowIndex(_selectedRow) &&
                      _rowIdAt(_selectedRow) == created.rowId,
                }
              : null;
          break;
        case 'row_deleted':
          item['value'] = <String, dynamic>{
            'target_absent': _rowIndexForId(expectation['row_id'] as int) < 0,
            'surviving_row_ids': _rows
                .map((row) => row.rowId)
                .toList(growable: false),
          };
          break;
        case 'group_created':
        case 'group_row_removed':
        case 'group_collapsed':
        case 'group_absent':
          final groupId = expectation['group_id'].toString();
          final group = _trackGroups
              .where((candidate) => candidate.id == groupId)
              .firstOrNull;
          item['value'] = group == null
              ? null
              : <String, dynamic>{
                  'group_id': group.id,
                  'name': group.name,
                  'member_row_ids': List<int>.from(group.rowIds),
                  'collapsed': group.collapsed,
                };
          break;
        case 'row_color':
          final row = _rowIndexForId(expectation['row_id'] as int);
          item['value'] = _isValidRowIndex(row) ? _rows[row].color : null;
          break;
        case 'row_solo':
          final row = expectation['row_id'] is int
              ? _rowIndexForId(expectation['row_id'] as int)
              : expectation['row'] as int;
          item['value'] = _isValidRowIndex(row) && row < _rowSoloed.length
              ? _rowSoloed[row]
              : null;
          break;
        case 'row_name':
          final row = expectation['row_id'] is int
              ? _rowIndexForId(expectation['row_id'] as int)
              : expectation['row'] as int;
          item['value'] = _isValidRowIndex(row) && row < _rows.length
              ? _rows[row].name
              : null;
          break;
        case 'row_role_override':
          final row = _rowIndexForId(expectation['row_id'] as int);
          item['value'] = _isValidRowIndex(row)
              ? _rows[row].roleOverride.trim()
              : null;
          break;
        case 'row_instrument':
          final rowId = expectation['row_id'] as int;
          final row = _rowIndexForId(rowId);
          item['value'] = !_isValidRowIndex(row)
              ? null
              : <String, dynamic>{
                  'row_name': _rows[row].name,
                  'instrument_id': _rows[row].instrumentId,
                  'instrument_name': _rows[row].instrumentName,
                  'instrument_params': _rows[row].instrumentParams,
                  'clips': <Map<String, dynamic>>[
                    for (final clip in _audioTracks)
                      if (clip.isMidi && clip.rowId == rowId)
                        <String, dynamic>{
                          'clip_id': clip.clipId,
                          'instrument_id': clip.instrumentId,
                          'instrument_name': clip.instrumentName,
                          'instrument_params': clip.instrumentParams,
                          'label': clip.label,
                        },
                  ],
                };
          break;
        case 'row_pan':
          final row = expectation['row_id'] is int
              ? _rowIndexForId(expectation['row_id'] as int)
              : expectation['row'] as int;
          item['value'] = _isValidRowIndex(row) && row < _rowPan.length
              ? _rowPan[row]
              : null;
          break;
        case 'row_gain':
          final row = expectation['row_id'] is int
              ? _rowIndexForId(expectation['row_id'] as int)
              : expectation['row'] as int;
          item['value'] = _isValidRowIndex(row) && row < _rowGain.length
              ? _rowGain[row]
              : null;
          break;
        case 'master_gain':
          item['value'] = _masterGain;
          break;
        case 'master_pan':
          item['value'] = _masterPan;
          break;
        case 'mix_reference_unchanged':
          item['value'] = _aiV3RowMixSnapshot(expectation['row'] as int);
          break;
        case 'mix_effect_presence':
        case 'mix_effects_empty':
        case 'mix_effect_parameter_resolved':
        case 'effect_parameter_value':
          final effects = expectation['master'] == true
              ? _aiV3MasterEffectsJson()
              : expectation['force_individual_row'] == true
              ? await _aiV3NativeRowEffectChain(
                  _aiV3ExpectationRow(expectation),
                )
              : _aiV3RowEffectsJson(_aiV3ExpectationRow(expectation));
          final requiresObservedEffect =
              kind == 'mix_effect_parameter_resolved' ||
              (kind == 'mix_effect_presence' && expectation['present'] == true);
          if (requiresObservedEffect && effects.isEmpty) {
            throw StateError('v3_effect_observation_missing');
          }
          item['value'] = effects;
          break;
        case 'effect_chain_exact':
          item['value'] = await _aiV3NativeRowEffectChain(
            _aiV3ExpectationRow(expectation),
          );
          break;
        case 'phone_mic_cleanup':
          final row = _rowIndexForId(expectation['row_id'] as int);
          item['value'] = !_isValidRowIndex(row)
              ? null
              : <String, dynamic>{
                  'effect_chain': await _aiV3NativeRowEffectChain(row),
                  'clip_presets': <String, String>{
                    for (final clipId
                        in (expectation['clip_presets'] as Map).keys.map(
                          (value) => value.toString(),
                        ))
                      if (_clipIndexForPersistentId(clipId) >= 0)
                        clipId: _audioTracks[_clipIndexForPersistentId(clipId)]
                            .audioEnhancementPreset,
                  },
                };
          break;
        case 'clip_start':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0 ? null : _audioTracks[index].offset;
          break;
        case 'clip_bounds':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0
              ? null
              : <String, dynamic>{
                  'start': _audioTracks[index].offset,
                  'end':
                      _audioTracks[index].offset +
                      _clipTimelineDurationMs(_audioTracks[index]) / 1000.0,
                };
          break;
        case 'clip_trim':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0
              ? null
              : <String, dynamic>{
                  'trim_start_ms': _audioTracks[index].trimStart.inMilliseconds,
                  'trim_end_ms': _audioTracks[index].trimEnd.inMilliseconds,
                };
          break;
        case 'clip_alignment_offset':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0
              ? null
              : _audioTracks[index].alignmentOffsetMs;
          break;
        case 'clip_pitch':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0 ? null : _audioTracks[index].pitchSemitones;
          break;
        case 'clip_stretch':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0
              ? null
              : <String, dynamic>{
                  'length':
                      _clipTimelineDurationMs(_audioTracks[index]) / 1000.0,
                  'stretch_enabled':
                      _tempoStretchEnabled &&
                      _audioTracks[index].stretchToProjectTempo,
                  'preserve_pitch':
                      _audioTracks[index].tempoStretchPreservePitch,
                  'warp_mode': normalizeTempoWarpMode(
                    _audioTracks[index].tempoWarpMode,
                  ),
                };
          break;
        case 'clip_source_tempo':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0
              ? null
              : <String, dynamic>{
                  'source_tempo_bpm': _audioTracks[index].sourceTempoBpm,
                };
          break;
        case 'clip_tempo_follow':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0
              ? null
              : <String, dynamic>{
                  'project_stretch_enabled': _tempoStretchEnabled,
                  'clip_follows_tempo':
                      _audioTracks[index].stretchToProjectTempo,
                  'preserve_pitch':
                      _audioTracks[index].tempoStretchPreservePitch,
                  'warp_mode': normalizeTempoWarpMode(
                    _audioTracks[index].tempoWarpMode,
                  ),
                  'length':
                      _clipTimelineDurationMs(_audioTracks[index]) / 1000.0,
                };
          break;
        case 'clip_bounds_unchanged':
          item['value'] = <Map<String, dynamic>>[
            for (final raw in expectation['value'] as List)
              if (raw is Map)
                (() {
                  final clipId = raw['clip_id']?.toString() ?? '';
                  final index = _audioTracks.indexWhere(
                    (clip) => clip.clipId == clipId,
                  );
                  return <String, dynamic>{
                    'clip_id': clipId,
                    if (index >= 0) ...<String, dynamic>{
                      'start': _audioTracks[index].offset,
                      'end':
                          _audioTracks[index].offset +
                          _clipTimelineDurationMs(_audioTracks[index]) / 1000.0,
                    },
                  };
                })(),
          ];
          break;
        case 'other_clip_tempo_state_unchanged':
          item['value'] = <Map<String, dynamic>>[
            for (final raw in expectation['value'] as List)
              if (raw is Map)
                (() {
                  final clipId = raw['clip_id']?.toString() ?? '';
                  final index = _audioTracks.indexWhere(
                    (clip) => clip.clipId == clipId,
                  );
                  return <String, dynamic>{
                    'clip_id': clipId,
                    if (index >= 0) ...<String, dynamic>{
                      'source_tempo_bpm': _audioTracks[index].sourceTempoBpm,
                      'follows_tempo':
                          _audioTracks[index].stretchToProjectTempo,
                      'preserve_pitch':
                          _audioTracks[index].tempoStretchPreservePitch,
                      'warp_mode': normalizeTempoWarpMode(
                        _audioTracks[index].tempoWarpMode,
                      ),
                    },
                  };
                })(),
          ];
          break;
        case 'clip_created':
          item['value'] = _aiV3MatchingCreatedClips(
            expectation,
          ).map((clip) => clip.clipId).toList(growable: false);
          break;
        case 'midi_clip_created':
          final before = (expectation['before_clip_ids'] as List)
              .map((id) => '$id')
              .toSet();
          item['value'] = _audioTracks
              .where((clip) => !before.contains(clip.clipId) && clip.isMidi)
              .map(
                (clip) => <String, dynamic>{
                  'clip_id': clip.clipId,
                  'row': clip.rowIndex,
                  'start': clip.offset,
                  'length': _clipTimelineDurationMs(clip) / 1000.0,
                  'instrument_id': clip.instrumentId,
                  'notes': clip.midiNotes
                      .map((note) => note.toJson())
                      .toList(growable: false),
                },
              )
              .toList(growable: false);
          break;
        case 'sample_replaced':
          final matches = _audioTracks
              .where((clip) => clip.clipId == expectation['clip_id'])
              .toList(growable: false);
          item['value'] = matches.length != 1
              ? null
              : <String, dynamic>{
                  'clip_id': matches.single.clipId,
                  'file': matches.single.file.path,
                  'row_id': matches.single.rowId,
                  'start': matches.single.offset,
                  'length_ms': _clipTimelineDurationMs(matches.single),
                  'label': matches.single.label,
                  'gain': matches.single.gain,
                  'normalize_volume': matches.single.normalizeVolume,
                  'normalize_gain': matches.single.normalizeGain,
                  'pre_normalize_gain': matches.single.preNormalizeGain,
                  'pitch_semitones': matches.single.pitchSemitones,
                  'reversed': matches.single.isReversed,
                  'crossfade': matches.single.crossfade,
                  'source_tempo_bpm': matches.single.sourceTempoBpm,
                  'stretch_to_project_tempo':
                      matches.single.stretchToProjectTempo,
                  'alignment_offset_ms': matches.single.alignmentOffsetMs,
                  'recording_latency_ms': matches.single.recordingLatencyMs,
                  'audio_enhancement_preset':
                      matches.single.audioEnhancementPreset,
                  'automation': matches.single.volumeAutomation
                      .map(
                        (point) => <String, dynamic>{
                          'x': point.x,
                          'volume': point.volume,
                        },
                      )
                      .toList(growable: false),
                };
          break;
        case 'clips_glued':
          final resultId = expectation['result_clip_id']?.toString() ?? '';
          final matches = _audioTracks
              .where((clip) => clip.clipId == resultId)
              .toList(growable: false);
          item['value'] = matches.length != 1
              ? null
              : <String, dynamic>{
                  'source_clip_ids': expectation['source_clip_ids'],
                  'result_clip_id': resultId,
                  'row_id': matches.single.rowId,
                  'start': matches.single.offset,
                  'length': _clipTimelineDurationMs(matches.single) / 1000.0,
                  'label': matches.single.label,
                  'file': matches.single.file.path,
                  'gain': matches.single.gain,
                  'pitch_semitones': matches.single.pitchSemitones,
                  'reversed': matches.single.isReversed,
                  'stretch_to_project_tempo':
                      matches.single.stretchToProjectTempo,
                  'selected':
                      _timelinePrimarySelectedClipIndex >= 0 &&
                      _timelinePrimarySelectedClipIndex < _audioTracks.length &&
                      _audioTracks[_timelinePrimarySelectedClipIndex].clipId ==
                          resultId,
                };
          break;
        case 'stems_separated':
          final vocalsId = expectation['vocals_clip_id']?.toString() ?? '';
          final instrumentalId =
              expectation['instrumental_clip_id']?.toString() ?? '';
          final vocalsIndex = _clipIndexForPersistentId(vocalsId);
          final instrumentalIndex = _clipIndexForPersistentId(instrumentalId);
          item['value'] =
              !_isValidClipIndex(vocalsIndex) ||
                  !_isValidClipIndex(instrumentalIndex)
              ? null
              : <String, dynamic>{
                  'source_clip_id': expectation['source_clip_id'],
                  'vocals_clip_id': vocalsId,
                  'instrumental_clip_id': instrumentalId,
                  'vocals_row_id': _audioTracks[vocalsIndex].rowId,
                  'instrumental_row_id': _audioTracks[instrumentalIndex].rowId,
                  'start': _audioTracks[vocalsIndex].offset,
                  'vocals_length': _clipTimelineDurationSec(
                    _audioTracks[vocalsIndex],
                  ),
                  'instrumental_length': _clipTimelineDurationSec(
                    _audioTracks[instrumentalIndex],
                  ),
                  'selected':
                      _timelinePrimarySelectedClipIndex == instrumentalIndex,
                };
          break;
        case 'audio_converted_to_midi':
          final resultId = expectation['result_clip_id']?.toString() ?? '';
          final resultIndex = _clipIndexForPersistentId(resultId);
          item['value'] = !_isValidClipIndex(resultIndex)
              ? null
              : <String, dynamic>{
                  'source_clip_id': expectation['source_clip_id'],
                  'result_clip_id': resultId,
                  'result_row_id': _audioTracks[resultIndex].rowId,
                  'instrument_id': _audioTracks[resultIndex].instrumentId,
                  'start': _audioTracks[resultIndex].offset,
                  'length': _clipTimelineDurationSec(_audioTracks[resultIndex]),
                  'note_count': _audioTracks[resultIndex].midiNotes.length,
                  'analysis_model': expectation['analysis_model'],
                  'analysis_elapsed_ms': expectation['analysis_elapsed_ms'],
                  'selected': _timelinePrimarySelectedClipIndex == resultIndex,
                };
          break;
        case 'samples_created':
          final before = (expectation['before_clip_ids'] as List)
              .map((id) => '$id')
              .toSet();
          item['value'] = _audioTracks
              .where((clip) => !before.contains(clip.clipId) && !clip.isMidi)
              .map(
                (clip) => <String, dynamic>{
                  'clip_id': clip.clipId,
                  'row': clip.rowIndex,
                  'start': clip.offset,
                  'file': clip.file.path,
                },
              )
              .toList(growable: false);
          break;
        case 'generated_resource_state':
          final clipId = expectation['clip_id']?.toString() ?? '';
          final index = _clipIndexForPersistentId(clipId);
          item['value'] = !_isValidClipIndex(index)
              ? <String, dynamic>{'present': false}
              : <String, dynamic>{
                  'present': true,
                  'clip_id': clipId,
                  'resource_kind': _audioTracks[index].isMidi
                      ? AiV3ResourceKind.midiClip.name
                      : AiV3ResourceKind.audioClip.name,
                  'start': _audioTracks[index].offset,
                  'end':
                      _audioTracks[index].offset +
                      _clipTimelineDurationSec(_audioTracks[index]),
                  'pitch_semitones': _audioTracks[index].pitchSemitones,
                  if (!_audioTracks[index].isMidi) ...<String, dynamic>{
                    'raw_duration_sec': _rawClipDurationSec(
                      _audioTracks[index],
                    ),
                    'source_tempo_bpm': _audioTracks[index].sourceTempoBpm,
                    'tempo_follow_mode': _aiV3AudioTempoFollowMode(
                      _audioTracks[index],
                    ),
                    'tempo_preserve_pitch':
                        _audioTracks[index].tempoStretchPreservePitch,
                  },
                  if (_audioTracks[index].isMidi)
                    'midi_notes': _audioTracks[index].midiNotes
                        .map(
                          (note) => <String, dynamic>{
                            'pitch': note.pitch,
                            'start_beat': note.startBeat,
                            'length_beats': note.lengthBeats,
                            'velocity': note.velocity,
                          },
                        )
                        .toList(growable: false),
                  if (_audioTracks[index].isMidi)
                    'midi_content_end_beats': _aiV3MidiContentEndBeats(
                      _aiV3MidiNotePayload(_audioTracks[index]),
                    ),
                };
          break;
        case 'clip_absent':
          item['value'] = !_audioTracks.any(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          break;
        case 'midi_notes':
          final index = _audioTracks.indexWhere(
            (clip) => clip.clipId == expectation['clip_id'],
          );
          item['value'] = index < 0
              ? null
              : _audioTracks[index].midiNotes
                    .map(
                      (note) => <String, dynamic>{
                        'id': note.id,
                        'pitch': note.pitch,
                        'start_beat': note.startBeat,
                        'length_beats': note.lengthBeats,
                        'velocity': note.velocity,
                      },
                    )
                    .toList(growable: false);
          break;
        case 'effect':
          final row = _aiV3ExpectationRow(expectation);
          if (row < 0 || row >= _rowCount) {
            item['value'] = null;
            break;
          }
          final forceIndividualRow =
              expectation['force_individual_row'] == true;
          final effects = await JuceAudioEngine.getTrackEffectsForRow(
            row,
            forceIndividualRow: forceIndividualRow,
          );
          final needle = expectation['value'].toString().toLowerCase();
          final effectIndex = effects.indexWhere(
            (effect) => effect.toLowerCase() == needle,
          );
          item['effects'] = effects;
          item['value'] = effectIndex < 0
              ? null
              : await JuceAudioEngine.getTrackPluginParameters(
                  row,
                  effectIndex,
                  forceIndividualRow: forceIndividualRow,
                );
          break;
        case 'automation_points':
          final row = expectation['row_id'] is int
              ? _rowIndexForId(expectation['row_id'] as int)
              : expectation['row'] as int;
          final targetId =
              expectation['automation_target_id']?.toString() ?? 'volume';
          item['value'] = _isValidRowIndex(row)
              ? _sanitizeAutomationPointsForTarget(
                      row,
                      targetId,
                      _pointsForAutomationTarget(row, targetId),
                    )
                    .map(
                      (point) => <String, dynamic>{
                        'x': point.x,
                        'value': point.volume,
                      },
                    )
                    .toList(growable: false)
              : null;
          break;
      }
      observed.add(item);
    }
    return observed;
  }

  String _freshAiV3StateFingerprint() {
    Object? stableValue(Object? value) {
      if (value is Map) {
        final entries = value.entries.toList()
          ..sort(
            (left, right) =>
                left.key.toString().compareTo(right.key.toString()),
          );
        return <String, dynamic>{
          for (final entry in entries)
            entry.key.toString(): stableValue(entry.value),
        };
      }
      if (value is Iterable) {
        return value.map(stableValue).toList(growable: false);
      }
      if (value == null || value is num || value is bool || value is String) {
        return value;
      }
      return value.toString();
    }

    Map<String, dynamic> effect(EffectSnapshot value) => <String, dynamic>{
      'effect_id': value.effectId,
      'display_name': value.displayName,
      'bypassed': value.bypassed,
      'params': stableValue(value.params),
    };

    final state = <String, dynamic>{
      'project': <String, dynamic>{
        'tempo': _tempo,
        'key': _projectKey,
        'beats_per_bar': _timeSignatureNumerator,
        'beat_unit': _timeSignatureDenominator,
        'master_gain': _masterGain,
        'master_pan': _masterPan,
        'row_count': _rowCount,
      },
      'rows': List<Map<String, dynamic>>.generate(
        _rowCount,
        (index) => <String, dynamic>{
          'row_index': index,
          'row_id': index < _rows.length ? _rows[index].rowId : null,
          'name': index < _rows.length ? _rows[index].name : null,
          'kind': index < _rows.length ? _rows[index].kind.wireName : null,
          'instrument_id': index < _rows.length
              ? _rows[index].instrumentId
              : null,
          'instrument_params': index < _rows.length
              ? stableValue(_rows[index].instrumentParams)
              : null,
          'role_override': index < _rows.length
              ? _rows[index].roleOverride
              : null,
          'color': index < _rows.length ? _rows[index].color : null,
          'gain': index < _rowGain.length ? _rowGain[index] : null,
          'pan': index < _rowPan.length ? _rowPan[index] : null,
          'muted': index < _rowMuted.length ? _rowMuted[index] : null,
          'soloed': index < _rowSoloed.length ? _rowSoloed[index] : null,
          'group_id': index < _rows.length ? _rows[index].groupId : null,
          'automation': index < _rowVolumeAutomation.length
              ? _rowVolumeAutomation[index]
                    .map(
                      (point) => <String, dynamic>{
                        'x': point.x,
                        'value': point.volume,
                      },
                    )
                    .toList(growable: false)
              : const <Map<String, dynamic>>[],
          'effects': index < _rows.length
              ? (_rowEffectSnapshotsByRowId[_rows[index].rowId]?.effects ??
                        const <EffectSnapshot>[])
                    .map(effect)
                    .toList(growable: false)
              : const <Map<String, dynamic>>[],
        },
      ),
      'clips': _audioTracks
          .asMap()
          .entries
          .map(
            (entry) => <String, dynamic>{
              'clip_index': entry.key,
              'clip_id': entry.value.clipId,
              'engine_clip_id': entry.value.engineClipId,
              'row_index': entry.value.rowIndex,
              'row_id': entry.value.rowId,
              'kind': entry.value.clipKind.wireName,
              'offset': entry.value.offset,
              'trim_start_ms': entry.value.trimStart.inMilliseconds,
              'trim_end_ms': entry.value.trimEnd.inMilliseconds,
              'gain': entry.value.gain,
              'pitch_semitones': entry.value.pitchSemitones,
              'reversed': entry.value.isReversed,
              'stretch_to_tempo': entry.value.stretchToProjectTempo,
              'instrument_id': entry.value.instrumentId,
              'instrument_params': stableValue(entry.value.instrumentParams),
              'midi_notes': entry.value.midiNotes
                  .map((note) => note.toJson())
                  .toList(growable: false),
            },
          )
          .toList(growable: false),
      'groups': _trackGroups
          .map(
            (group) => <String, dynamic>{
              'id': group.id,
              'name': group.name,
              'color': group.color,
              'row_ids': List<int>.from(group.rowIds),
              'gain': group.gain,
              'pan': group.pan,
              'muted': group.muted,
              'soloed': group.soloed,
              'collapsed': group.collapsed,
              'effects': group.effects.map(effect).toList(growable: false),
            },
          )
          .toList(growable: false),
      'master_effects': _masterEffectSnapshot.effects
          .map(effect)
          .toList(growable: false),
      'automation_clips': stableValue(_aiValidationAutomationClips()),
      'selection': <String, dynamic>{
        'selected_row_index': _selectedRow,
        'selected_clip_indices': List<int>.from(_timelineSelectedClipIndices),
        'primary_selected_clip_index': _timelinePrimarySelectedClipIndex,
      },
    };
    return crypto.sha256.convert(utf8.encode(jsonEncode(state))).toString();
  }

  void _scrollChatToLatest({bool jump = false}) {
    if (_chatScrollHintEnabled) {
      _setChatScrollHintEnabled(false);
    }
    final request = ++_chatScrollRequest;
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted ||
          _chatMutationDisposed ||
          !_chatExpanded ||
          request != _chatScrollRequest) {
        return;
      }
      final controller = _chatController;
      if (controller is! ScrollToMessageMixin) return;
      final total = controller.messages.length;
      if (total <= 0) return;
      try {
        await (controller as ScrollToMessageMixin).scrollToIndex(
          total - 1,
          duration: jump ? Duration.zero : const Duration(milliseconds: 180),
          curve: Curves.easeOutCubic,
          alignment: 1.0,
        );
        if (!mounted ||
            _chatMutationDisposed ||
            !_chatExpanded ||
            request != _chatScrollRequest ||
            !_chatListScrollController.hasClients) {
          return;
        }
        final position = _chatListScrollController.position;
        if (!position.hasContentDimensions) return;
        final target = position.maxScrollExtent;
        if ((target - position.pixels).abs() <= 1) return;
        if (jump) {
          _chatListScrollController.jumpTo(target);
        } else {
          await _chatListScrollController.animateTo(
            target,
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOutCubic,
          );
        }
      } catch (_) {
        // Ignore interrupted scroll animations during rapid chat updates.
      }
    });
  }

  Widget _buildThinkingPlaceholderBubble() => const _ChatThinkingBubble();

  void _showCopiedChatMessageFeedback(String messageId) {
    _copiedChatMessageTimer?.cancel();
    _copiedChatMessageTimer = null;
    if (mounted) {
      setState(() {
        _copiedChatMessageId = messageId;
      });
    } else {
      _copiedChatMessageId = messageId;
    }
    _copiedChatMessageTimer = Timer(const Duration(milliseconds: 1400), () {
      if (!mounted) {
        _copiedChatMessageId = null;
        return;
      }
      setState(() {
        _copiedChatMessageId = null;
      });
    });
  }

  Future<void> _copyChatLogToClipboard() async {
    final lines = <String>[];
    for (final message in _chatController.messages) {
      if (message is! TextMessage) continue;
      final text = message.text.trim();
      if (text.isEmpty) continue;
      final author = switch (message.authorId) {
        'user' => 'You',
        'system' => 'System',
        _ => 'MixAssistant',
      };
      lines.add('$author: $text');
    }
    if (lines.isEmpty) return;
    await Clipboard.setData(ClipboardData(text: lines.join('\n\n')));
    await AppHaptics.impact(AppHapticImpact.light);
    _showSmallNotice(L10n.translate(context, 'Copied chat log.'));
  }

  Future<void> _copyChatMessageToClipboard(TextMessage message) async {
    final text = message.text.trim();
    if (text.isEmpty) return;
    await Clipboard.setData(ClipboardData(text: text));
    await AppHaptics.impact(AppHapticImpact.light);
    _showCopiedChatMessageFeedback(message.id);
  }

  void _scheduleChatHistoryPrune() {
    if (_chatHistoryPruneScheduled || _chatHistoryPruneInFlight) return;
    _chatHistoryPruneScheduled = true;
    Future<void>.microtask(() async {
      _chatHistoryPruneScheduled = false;
      if (_chatHistoryPruneInFlight) return;
      _chatHistoryPruneInFlight = true;
      try {
        await _pruneChatHistoryInMemory();
      } finally {
        _chatHistoryPruneInFlight = false;
      }
      if (_chatHistoryNeedsPruning()) {
        _scheduleChatHistoryPrune();
      }
    });
  }

  void _scheduleChatInsertionFlush() {
    if (_chatInsertionFlushScheduled) return;
    _chatInsertionFlushScheduled = true;
    Future<void>.microtask(() {
      _chatInsertionFlushScheduled = false;
      if (!mounted || _chatMutationDisposed || _pendingChatInsertions.isEmpty) {
        return;
      }
      final messages = List<Message>.from(_pendingChatInsertions);
      _pendingChatInsertions.clear();
      unawaited(
        _enqueueChatMutation(() async {
          final controller = _chatController;
          if (controller is InMemoryChatController) {
            await controller.insertAllMessages(messages, animated: false);
          } else {
            await controller.insertAllMessages(messages);
          }
        }).whenComplete(_scheduleChatHistoryPrune),
      );
    });
  }

  Future<void> _enqueueChatMutation(Future<void> Function() operation) {
    final Future<void> result = _chatMutationQueue.then<void>((_) async {
      if (!mounted || _chatMutationDisposed) return;
      await operation();
    });
    _chatMutationQueue = result.catchError((Object error, StackTrace stack) {
      debugPrint('Chat mutation failed: $error');
      return Future<void>.value();
    });
    return result;
  }

  Future<void> _setChatMessages(
    List<Message> messages, {
    bool animated = true,
  }) {
    _pendingChatInsertions.clear();
    return _enqueueChatMutation(() async {
      final controller = _chatController;
      if (controller is InMemoryChatController) {
        await controller.setMessages(messages, animated: animated);
      } else {
        await controller.setMessages(messages);
      }
    });
  }

  Future<void> _removeChatMessage(Message message, {bool animated = true}) {
    return _enqueueChatMutation(() async {
      final controller = _chatController;
      if (controller is InMemoryChatController) {
        await controller.removeMessage(message, animated: animated);
      } else {
        await controller.removeMessage(message);
      }
    });
  }

  bool _chatHistoryNeedsPruning() {
    final limits = kDefaultProjectChatHistoryLimits;
    final messages = _chatController.messages;
    final maxStoredMessages = limits.maxStoredMessages;
    if (maxStoredMessages != null && messages.length > maxStoredMessages) {
      return true;
    }
    int totalChars = 0;
    for (final message in messages) {
      if (message is TextMessage) {
        totalChars += message.text.length;
        if (totalChars > limits.maxStoredCharacters) {
          return true;
        }
      }
    }
    return false;
  }

  Future<void> _pruneChatHistoryInMemory() async {
    bool changed = false;
    while (_chatHistoryNeedsPruning()) {
      final messages = _chatController.messages;
      if (messages.isEmpty) break;
      await _removeChatMessage(messages.first, animated: false);
      changed = true;
    }
    if (changed && mounted) {
      setState(() {});
    }
  }

  Future<void> _restoreChatHistoryFromProjectJson(
    Map<String, dynamic> json,
  ) async {
    _aiV3ClarificationSession.clear();
    final history = ProjectChatHistory.fromJson(
      json['assistantChat'] ?? json['chatHistory'],
    );
    _assistantConversationSessionId = history.stateSessionId.trim();
    await _setChatMessages(
      history.toChatMessages().cast<Message>(),
      animated: false,
    );
    _chatPipeline.replaceConversation(history.toConversation());
  }

  void _scheduleChatHistoryPersist({bool immediate = false}) {
    if (immediate) {
      _markProjectDirty(immediate: true);
      return;
    }

    _scheduleProjectAutosave(debounce: const Duration(milliseconds: 700));
  }

  Future<void> _persistChatHistoryOnly() async {
    _markProjectDirty(immediate: true);
  }

  Future<void> _clearChatHistory() async {
    _aiV3ClarificationSession.clear();
    await _setChatMessages(const <Message>[], animated: false);
    _chatPipeline.clearConversation();
    _rotateAssistantConversationSessionId();
    await _persistChatHistoryOnly();
    if (mounted) setState(() {});
  }

  void _applyPromptRateLimitStatus(
    AiPromptRateLimitStatus? status, {
    bool markLoadingComplete = true,
  }) {
    _promptRateLimitRefreshTimer?.cancel();
    _promptRateLimitRefreshTimer = null;
    if (!mounted) {
      _promptRateLimitStatus = status;
      if (markLoadingComplete) {
        _promptRateLimitLoading = false;
      }
      return;
    }

    setState(() {
      _promptRateLimitStatus = status;
      if (markLoadingComplete) {
        _promptRateLimitLoading = false;
      }
    });

    if (status == null || status.canSubmit) return;
    final resetAt = status.blockedResetAt?.toLocal();
    if (resetAt == null) return;
    final wait = resetAt.difference(DateTime.now()).inMilliseconds + 1200;
    final delay = Duration(milliseconds: wait.clamp(1000, 2147483647));
    _promptRateLimitRefreshTimer = Timer(delay, () {
      unawaited(_refreshPromptRateLimitStatus(silent: true));
    });
  }

  void _updatePromptRateLimitStatusFromMeta(Map<String, dynamic>? meta) {
    final raw = meta?['prompt_rate_limit'];
    if (raw is! Map) return;
    _applyPromptRateLimitStatus(
      AiPromptRateLimitStatus.fromJson(raw.cast<String, dynamic>()),
    );
  }

  void _maybeShowPromptRateLimitDialogFromMeta(Map<String, dynamic>? meta) {
    if (meta?['prompt_rate_limit_hit'] != true) return;
    final raw = meta?['prompt_rate_limit'];
    if (raw is! Map) return;
    final status = AiPromptRateLimitStatus.fromJson(
      raw.cast<String, dynamic>(),
    );
    if (status.canSubmit) return;
    unawaited(
      Future<void>.delayed(const Duration(milliseconds: 120), () async {
        if (!mounted) return;
        await _showPromptRateLimitDialog();
      }),
    );
  }

  Future<void> _refreshPromptRateLimitStatus({bool silent = false}) async {
    if (!silent && mounted) {
      setState(() => _promptRateLimitLoading = true);
    } else if (!silent) {
      _promptRateLimitLoading = true;
    }

    try {
      final status = await _chatPipeline.llm.fetchPromptRateLimitStatus();
      _applyPromptRateLimitStatus(status);
    } catch (_) {
      _applyPromptRateLimitStatus(null);
    }
  }

  String _formatPromptWaitDuration(DateTime? resetsAt) {
    if (resetsAt == null) return 'unknown';
    final remaining = resetsAt.toLocal().difference(DateTime.now());
    if (remaining.inSeconds <= 0) return 'less than a minute';
    if (remaining.inDays >= 1) {
      final hours = remaining.inHours.remainder(24);
      return hours > 0
          ? '${remaining.inDays}d ${hours}h'
          : '${remaining.inDays}d';
    }
    if (remaining.inHours >= 1) {
      final minutes = remaining.inMinutes.remainder(60);
      return minutes > 0
          ? '${remaining.inHours}h ${minutes}m'
          : '${remaining.inHours}h';
    }
    return '${remaining.inMinutes.clamp(1, 59)}m';
  }

  String _formatPromptResetAt(BuildContext context, DateTime? resetsAt) {
    if (resetsAt == null) return L10n.translate(context, 'Unknown');
    final local = resetsAt.toLocal();
    final locale = Localizations.maybeLocaleOf(context)?.toLanguageTag();
    final time = intl.DateFormat.jm(locale).format(local);
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final targetDay = DateTime(local.year, local.month, local.day);
    final dayDelta = targetDay.difference(today).inDays;
    if (dayDelta == 0) {
      return '${L10n.translate(context, 'today at')} $time';
    }
    if (dayDelta == 1) {
      return '${L10n.translate(context, 'tomorrow at')} $time';
    }
    final date = intl.DateFormat('EEE, MMM d', locale).format(local);
    final at = L10n.translate(context, 'at').trim();
    return at.isEmpty ? '$date $time' : '$date $at $time';
  }

  String _formatPromptResetShort(
    DateTime? resetsAt, {
    bool preferDateWhenFar = false,
  }) {
    if (resetsAt == null) return '--';
    final local = resetsAt.toLocal();
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final targetDay = DateTime(local.year, local.month, local.day);
    final dayDelta = targetDay.difference(today).inDays;
    if (preferDateWhenFar && dayDelta >= 1) {
      final month = local.month.toString().padLeft(2, '0');
      final day = local.day.toString().padLeft(2, '0');
      return '$month/$day';
    }
    final isPm = local.hour >= 12;
    final hour12 = local.hour % 12 == 0 ? 12 : local.hour % 12;
    final minute = local.minute.toString().padLeft(2, '0');
    return '$hour12:$minute ${isPm ? 'PM' : 'AM'}';
  }

