  Future<void> _loadAiModels() async {
    if (defaultTargetPlatform != TargetPlatform.android &&
        defaultTargetPlatform != TargetPlatform.iOS) {
      await _classifier.load();
    }
    await _magnitudePredictor.load();
  }

  String _aiAutomationClipSnapshot() {
    return _legacyAiAutomationClipSnapshot();
  }

  Map<int, List<Map<String, dynamic>>> _aiValidationAutomationTargets() {
    final result = <int, List<Map<String, dynamic>>>{};
    for (int row = 0; row < _rowCount; row++) {
      final targetIds =
          _automationTargetIdsForRowSync(row)
              .where((targetId) => !_parseAutomationTargetId(targetId).isMaster)
              .toList()
            ..sort();
      final targets =
          _rowAutomationTargets[row] ?? const <String, _AutomationTargetMeta>{};
      result[row] = targetIds
          .map(
            (targetId) =>
                (targets[targetId] ?? _fallbackAutomationTargetMeta(targetId))
                    .toUiMap(),
          )
          .where((target) => target['isOrphan'] != true)
          .toList(growable: false);
    }
    return result;
  }

  List<Map<String, dynamic>> _aiValidationMasterAutomationTargets() {
    final targetIds = _masterAutomationTargetIdsForSync().toList()..sort();
    return targetIds
        .map((targetId) {
          final target =
              _automationTargetMetaFromAnyRow(targetId) ??
              _fallbackAutomationTargetMeta(targetId);
          return target.toUiMap();
        })
        .where((target) => target['isOrphan'] != true)
        .toList(growable: false);
  }

  List<Map<String, dynamic>> _aiValidationAutomationClips() {
    final result = <Map<String, dynamic>>[];
    final rows = _rowAutomationClips.keys.toList()..sort();
    for (final row in rows) {
      final laneMap = _rowAutomationClips[row];
      if (laneMap == null) continue;
      final targetIds = laneMap.keys.toList()..sort();
      for (final targetId in targetIds) {
        final parsedTarget = _parseAutomationTargetId(targetId);
        final clips =
            _copyAutomationClipList(
              laneMap[targetId] ?? const <AutomationClipSnapshot>[],
            )..sort((left, right) {
              final byStart = left.startMs.compareTo(right.startMs);
              return byStart != 0 ? byStart : left.id.compareTo(right.id);
            });
        for (final clip in clips) {
          result.add(<String, dynamic>{
            'scope': parsedTarget.isMaster ? 'master' : 'row',
            'row_index': row,
            'target_id': targetId,
            'clip_id': clip.id,
            if (clip.patternId.trim().isNotEmpty)
              'pattern_id': clip.patternId.trim(),
            'start_ms': clip.startMs,
            'length_ms': clip.lengthMs,
            'lane': clip.lane,
            'muted': clip.muted,
          });
        }
      }
    }
    return result;
  }

  String _legacyAiAutomationClipSnapshot() {
    const int maxTargetsPerScope = 4;
    const int maxEntriesForFocusedTarget = 10;
    const int maxEntriesPerOtherTarget = 4;

    String summarizeLane(
      int row,
      String targetId,
      List<AutomationClipSnapshot> clips, {
      required bool focused,
    }) {
      final label = _automationTargetLabelFor(row, targetId);
      final sorted = _copyAutomationClipList(clips)
        ..sort((a, b) {
          final byStart = a.startMs.compareTo(b.startMs);
          if (byStart != 0) return byStart;
          return a.id.compareTo(b.id);
        });
      final linkedGroups = <String, List<AutomationClipSnapshot>>{};
      final uniqueClips = <AutomationClipSnapshot>[];
      for (final clip in sorted) {
        final patternId = clip.patternId.trim();
        if (patternId.isEmpty) {
          uniqueClips.add(clip);
        } else {
          linkedGroups
              .putIfAbsent(patternId, () => <AutomationClipSnapshot>[])
              .add(clip);
        }
      }

      final entries = <({double startMs, String text})>[];
      for (final entry in linkedGroups.entries) {
        final group = entry.value;
        group.sort((a, b) => a.startMs.compareTo(b.startMs));
        final first = group.first;
        final last = group.last;
        final clipIds = group.take(3).map((clip) => clip.id).join(',');
        final hiddenIds = group.length - math.min(group.length, 3);
        final idSuffix = hiddenIds > 0 ? ',+$hiddenIds more' : '';
        final laneSet = group.map((clip) => clip.lane).toSet().toList()..sort();
        final laneSummary = laneSet.length == 1
            ? '${laneSet.first}'
            : '${laneSet.first}-${laneSet.last}';
        entries.add((
          startMs: first.startMs,
          text:
              'linked{pattern_id=${entry.key},count=${group.length},start_ms=${first.startMs.round()},'
              'end_ms=${(last.startMs + last.lengthMs).round()},lanes=$laneSummary,clip_ids=$clipIds$idSuffix}',
        ));
      }
      for (final clip in uniqueClips) {
        final mutedToken = clip.muted ? ',muted=true' : '';
        entries.add((
          startMs: clip.startMs,
          text:
              'unique{clip_id=${clip.id},start_ms=${clip.startMs.round()},length_ms=${clip.lengthMs.round()},'
              'lane=${clip.lane}$mutedToken}',
        ));
      }
      entries.sort((a, b) => a.startMs.compareTo(b.startMs));

      final maxEntries = focused
          ? maxEntriesForFocusedTarget
          : maxEntriesPerOtherTarget;
      final visible = entries
          .take(maxEntries)
          .map((entry) => entry.text)
          .toList();
      final hidden = entries.length - visible.length;
      if (hidden > 0) {
        visible.add('(+$hidden more entries)');
      }

      return '$label[$targetId]{clips=${clips.length},linked_groups=${linkedGroups.length},'
          'unique_clips=${uniqueClips.length}}=${visible.join(';')}';
    }

    List<String> summarizeRowTargets(
      int row, {
      required bool includeMasterTargets,
      String prioritizedTargetId = '',
    }) {
      final rowMap =
          _rowAutomationClips[row] ??
          const <String, List<AutomationClipSnapshot>>{};
      final targetIds =
          rowMap.keys.where((targetId) {
            final isMasterTarget = _parseAutomationTargetId(targetId).isMaster;
            if (includeMasterTargets != isMasterTarget) return false;
            final clips = rowMap[targetId] ?? const <AutomationClipSnapshot>[];
            return clips.isNotEmpty;
          }).toList()..sort((a, b) {
            if (a == prioritizedTargetId && b != prioritizedTargetId) return -1;
            if (b == prioritizedTargetId && a != prioritizedTargetId) return 1;
            final aCount =
                (rowMap[a] ?? const <AutomationClipSnapshot>[]).length;
            final bCount =
                (rowMap[b] ?? const <AutomationClipSnapshot>[]).length;
            final byCount = bCount.compareTo(aCount);
            if (byCount != 0) return byCount;
            return a.compareTo(b);
          });
      final out = <String>[];
      final visibleTargets = targetIds
          .take(maxTargetsPerScope)
          .toList(growable: false);
      for (final targetId in visibleTargets) {
        final clips = _copyAutomationClipList(
          rowMap[targetId] ?? const <AutomationClipSnapshot>[],
        );
        out.add(
          summarizeLane(
            row,
            targetId,
            clips,
            focused: targetId == prioritizedTargetId,
          ),
        );
      }
      final hiddenTargets = targetIds.length - visibleTargets.length;
      if (hiddenTargets > 0) {
        out.add('(+$hiddenTargets more automation targets)');
      }
      return out;
    }

    final lines = <String>[];
    final selectedRow = _selectedRow;
    if (selectedRow >= 0 && selectedRow < _rowCount) {
      final selectedTargetId = _selectedAutomationTargetIdForRow(selectedRow);
      final selected = summarizeRowTargets(
        selectedRow,
        includeMasterTargets: false,
        prioritizedTargetId: selectedTargetId,
      );
      if (selected.isNotEmpty) {
        lines.add('selected_row_automation_clips=${selected.join(' | ')}');
      }
    }

    final master = summarizeRowTargets(0, includeMasterTargets: true);
    if (master.isNotEmpty) {
      lines.add('master_automation_clips=${master.join(' | ')}');
    }

    return lines.join('\n');
  }

  Future<void> runOneButtonMix() async {
    // optional: show system “Mixing…” message
    _insertSystemChatText(
      L10n.translate(context, 'Mixing…'),
      metadata: {'typing': true},
      persist: false,
    );

    final selectedProfile =
        OneButtonMixProfiles.byId(_selectedOneButtonMixProfileId);
    final prompt = OneButtonMixProfiles.buildPrompt(selectedProfile.id);
    const aiFeature = 'one_button_mix';
    final promptTraceId = const Uuid().v4();
    final promptCycleStopwatch = Stopwatch()..start();
    int? applyMixMs;
    final magnitudeObservability = _magnitudePredictor.observabilityContext;
    unawaited(
      AnalyticsService.instance.track(
        AnalyticsEvents.aiPromptSubmitted(
          projectId: _projectId,
          aiFeature: aiFeature,
          promptTraceId: promptTraceId,
          mixMagnitudeModelSource:
              magnitudeObservability['mix_magnitude_model_source']?.toString(),
          mixMagnitudeModelBundleVersion:
              magnitudeObservability['mix_magnitude_model_bundle_version']
                  ?.toString(),
          mixApplyModelVersion:
              magnitudeObservability['mix_apply_model_version']?.toString(),
          mixMagnitudeRegressorVersion:
              magnitudeObservability['mix_magnitude_regressor_version']
                  ?.toString(),
        ),
      ),
    );

    Map<String, dynamic>? producerPreSnapshot;
    if (_producerDataMode) {
      producerPreSnapshot = await _buildProducerSnapshot();
      _producerGuidedPromptAwaitingFinal = false;
      if (_producerCollector.hasPendingPromptCycle) {
        await _finalizeProducerPromptCycle(
          disposition: 'next_ai_step',
          insertMessage: false,
          finalSnapshot: producerPreSnapshot,
        );
      }
    }

    late final ChatPipelineResult reply;
    try {
      await _ensureAiModelsLoaded();
      final librarySnapshot = await _buildAiLibrarySnapshot();
      final aiTrackGroups = await _trackGroupsForAiProjectState();
      reply = await _chatPipeline.handleUserText(
        text: prompt,
        audioTracks: _audioTracks,
        bpmFallback: _tempo,
        projectKey: _projectKey,
        rowNames: _visibleAiRowNames(),
        timelineRows: _visibleAiRows(),
        trackGroups: aiTrackGroups,
        librarySnapshot: librarySnapshot,
        clientContext: _buildAiClientContext(),
        rowGain: _rowGain,
        rowPan: _rowPan,
        rowAutomation: _rowVolumeAutomation,
        masterGain0to3: _masterGain,
        masterPan0to1: _masterPan,
        selectedClipIndices: _timelineSelectedClipIndices,
        primarySelectedClipIndex: _timelinePrimarySelectedClipIndex,
        selectedRowIndex: _selectedRow,
        automationClipSnapshot: _aiAutomationClipSnapshot(),
        beatsPerBar: _timeSignatureNumerator,
        beatUnit: _timeSignatureDenominator,
        validationAutomationTargets: _aiValidationAutomationTargets(),
        validationMasterAutomationTargets:
            _aiValidationMasterAutomationTargets(),
        validationAutomationClips: _aiValidationAutomationClips(),
        promptTraceId: promptTraceId,
        projectId: _projectId,
        aiFeature: aiFeature,
        conversationSessionId: _ensureAssistantConversationSessionId(),
        clientStateDigest: _freshAiV3StateFingerprint(),
        autoApplyProposals: true, // <-- key
        bypassLearnedMagnitudes: _producerDataMode,
        oneButtonMixProfileId: selectedProfile.id,
      );
    } catch (error, stackTrace) {
      _reportAiChatFailure(error, stackTrace, stage: 'one_button_pipeline');
      promptCycleStopwatch.stop();
      unawaited(
        _trackAiResponseOutcome(
          promptTraceId: promptTraceId,
          aiFeature: aiFeature,
          projectId: _projectId,
          fallbackErrorCode: 'one_button_pipeline',
        ),
      );
      unawaited(
        _trackAiPromptCycleFailed(
          promptTraceId: promptTraceId,
          aiFeature: aiFeature,
          projectId: _projectId,
          errorCode: 'one_button_pipeline',
          promptCycleTotalMs: promptCycleStopwatch.elapsedMilliseconds,
        ),
      );
      _insertAiFailureSystemText(_kAiRequestFailureSystemText);
      return;
    }

    final toolName = reply.meta?['tool']?.toString().trim() ?? '';
    if (toolName.isEmpty) {
      // Server-side analytics are authoritative for AI request outcomes.
    } else {
      _trackAiToolUsage(
        toolName: toolName,
        aiFeature: aiFeature,
        promptTraceId: promptTraceId,
        actionTypes:
            reply.mixing?.actions
                .map((action) => action.type)
                .toList(growable: false) ??
            reply.assistantActions
                .map((action) => action.type)
                .toList(growable: false),
      );
    }

    _updatePromptRateLimitStatusFromMeta(reply.meta);
    _maybeShowPromptRateLimitDialogFromMeta(reply.meta);
    unawaited(
      _trackAiResponseOutcome(
        promptTraceId: promptTraceId,
        aiFeature: aiFeature,
        projectId: _projectId,
        meta: reply.meta,
      ),
    );

    final replyMix = reply.mixing;
    final replyHasMix =
        replyMix != null && !(replyMix.isNoOp || replyMix.actions.isEmpty);

    try {
      if (replyMix != null && !replyMix.isNoOp && replyMix.actions.isNotEmpty) {
        final mix = replyMix;
        final applyMixStopwatch = Stopwatch()..start();
        final applyReport = await applyMixingResult(
          mix,
          emitActionSummaries: true,
        );
        applyMixStopwatch.stop();
        applyMixMs = applyMixStopwatch.elapsedMilliseconds;
        if (applyReport.applied <= 0) {
          promptCycleStopwatch.stop();
          unawaited(
            _trackAiPromptCycleFailed(
              promptTraceId: promptTraceId,
              aiFeature: aiFeature,
              projectId: _projectId,
              errorCode: 'one_button_apply_no_changes',
              meta: reply.meta,
              toolName: toolName,
              applyMixMs: applyMixMs,
              promptCycleTotalMs: promptCycleStopwatch.elapsedMilliseconds,
            ),
          );
          _insertAiFailureSystemText(_kAiApplyFailureSystemText);
          return;
        }
        _showAiMixCompletionFeedback(applyReport);
        _chatPipeline.recordAppliedMix(
          mix,
          visibleAssistantText: reply.message,
        );

        if (_producerDataMode && producerPreSnapshot != null) {
          final producerPostSnapshot = await _buildProducerSnapshot();
          await _producerCollector.recordAiStep(
            prompt: prompt,
            preSnapshot: producerPreSnapshot,
            postSnapshot: producerPostSnapshot,
            resolvedActions: mix.actions.map((a) => a.toJson()).toList(),
            llmPayload: reply.meta,
            projectId: _projectId,
            projectName: _projectName,
            projectDir: _projectDir,
          );
        }
      }

      await _presentPipelineReply(reply);
    } catch (error, stackTrace) {
      _reportAiChatFailure(error, stackTrace, stage: 'one_button_apply');
      promptCycleStopwatch.stop();
      unawaited(
        _trackAiPromptCycleFailed(
          promptTraceId: promptTraceId,
          aiFeature: aiFeature,
          projectId: _projectId,
          errorCode: 'one_button_apply',
          meta: reply.meta,
          toolName: toolName,
          applyMixMs: applyMixMs,
          promptCycleTotalMs: promptCycleStopwatch.elapsedMilliseconds,
        ),
      );
      _insertAiFailureSystemText(
        replyHasMix ? _kAiApplyFailureSystemText : _kAiRequestFailureSystemText,
      );
      return;
    }

    promptCycleStopwatch.stop();
    _logAiPromptDebugPretty(
      promptTraceId: promptTraceId,
      toolName: toolName,
      meta: reply.meta,
      applyMixMs: applyMixMs,
      promptCycleTotalMs: promptCycleStopwatch.elapsedMilliseconds,
    );
    unawaited(
      _trackAiPromptCycleCompleted(
        promptTraceId: promptTraceId,
        aiFeature: aiFeature,
        projectId: _projectId,
        meta: reply.meta,
        toolName: toolName,
        applyMixMs: applyMixMs,
        promptCycleTotalMs: promptCycleStopwatch.elapsedMilliseconds,
      ),
    );

    // show a snackbar/modal if you want:
    // ScaffoldMessenger.of(context).showSnackBar(...)
  }

