  double _androidTransportBottomInset(BuildContext context) {
    if (!Platform.isAndroid) return 0.0;
    final bottomPadding = MediaQuery.paddingOf(context).bottom;
    final viewPadding = MediaQuery.viewPaddingOf(context).bottom;
    final navInset = math.max(bottomPadding, viewPadding);
    final baseInset = navInset <= 0.0
        ? 15.0
        : (navInset + 11.0).clamp(15.0, 25.0).toDouble();
    return baseInset + 2.0;
  }

  double _androidTabletDawBottomInset(BuildContext context) {
    if (!Platform.isAndroid || !_usesTabletDesktopDawShell(context)) {
      return 0.0;
    }
    final navInset = math.max(
      math.max(
        MediaQuery.paddingOf(context).bottom,
        MediaQuery.viewPaddingOf(context).bottom,
      ),
      MediaQuery.systemGestureInsetsOf(context).bottom,
    );
    if (navInset <= 0.0) return 0.0;
    return (navInset + 8.0).clamp(0.0, 88.0).toDouble();
  }

