  List<double> _buildOnsetEnvelopeFromSamples(
    Float32List samples, {
    int frameSize = 1024,
    int hopSize = 128,
  }) {
    return MixroomTempoDetection.buildOnsetEnvelopeFromSamples(
      samples,
      frameSize: frameSize,
      hopSize: hopSize,
    );
  }

  double? _detectTempoFromOnsetEnvelope(
    List<double> onsetEnv,
    double envSampleRateHz, {
    double? durationSec,
  }) {
    return MixroomTempoDetection.detectTempoFromOnsetEnvelope(
      onsetEnv,
      envSampleRateHz,
      durationSec: durationSec,
    );
  }

  Float32List _lowPassMono(
    Float32List input, {
    int sampleRate = 16000,
    double cutoffHz = 220.0,
  }) {
    if (input.isEmpty) return input;
    final clampedCutoff = cutoffHz.clamp(20.0, sampleRate * 0.45).toDouble();
    final alpha = math.exp(-2.0 * math.pi * clampedCutoff / sampleRate);
    final out = Float32List(input.length);
    double y = 0.0;
    for (int i = 0; i < input.length; i++) {
      y = (1.0 - alpha) * input[i] + alpha * y;
      out[i] = y.toDouble();
    }
    return out;
  }

  List<double> _detectTransientTimesMsFromOnsetEnvelope(
    List<double> onsetEnv, {
    required double envSampleRateHz,
    double thresholdStd = 1.25,
    double minSpacingMs = 110.0,
    int maxEvents = 256,
  }) {
    if (onsetEnv.length < 8 || envSampleRateHz <= 0.0) return const <double>[];
    final n = onsetEnv.length;

    double mean = 0.0;
    for (final v in onsetEnv) {
      mean += v;
    }
    mean /= n;

    double variance = 0.0;
    for (final v in onsetEnv) {
      final d = v - mean;
      variance += d * d;
    }
    variance /= n;
    final std = math.sqrt(math.max(variance, 0.0));
    final threshold = math.max(
      mean + std * thresholdStd,
      mean * 1.65 + 0.000015,
    );

    final minFrames = math.max(
      1,
      (minSpacingMs * envSampleRateHz / 1000.0).round(),
    );
    int lastAccepted = -minFrames * 2;
    final out = <double>[];

    for (int i = 1; i < n - 1; i++) {
      final v = onsetEnv[i];
      if (v < threshold) continue;
      if (v <= onsetEnv[i - 1] || v < onsetEnv[i + 1]) continue;
      if (i - lastAccepted < minFrames) {
        if (out.isNotEmpty && v > onsetEnv[lastAccepted]) {
          out.removeLast();
          out.add((i * 1000.0) / envSampleRateHz);
          lastAccepted = i;
        }
        continue;
      }
      out.add((i * 1000.0) / envSampleRateHz);
      lastAccepted = i;
      if (out.length >= maxEvents) break;
    }
    return out;
  }

  Future<List<double>> _detectKickTimelineOnsetsMsForClip(
    AudioTrack clip, {
    double cutoffHz = 220.0,
    double thresholdStd = 1.25,
    double minSpacingMs = 110.0,
    int maxEvents = 256,
  }) async {
    if (clip.isMidi) return const <double>[];

    const int sampleRate = 16000;
    Float32List decoded = Float32List(0);
    try {
      decoded = await JuceAudioEngine.decodeAudioMono16k(clip.file.path);
    } catch (_) {
      return const <double>[];
    }
    if (decoded.isEmpty) return const <double>[];

    int start = (clip.trimStart.inMilliseconds * sampleRate / 1000).round();
    int end = (clip.trimEnd.inMilliseconds * sampleRate / 1000).round();
    start = start.clamp(0, decoded.length);
    end = end.clamp(start, decoded.length);
    if (end <= start) return const <double>[];
    final segment = Float32List.sublistView(decoded, start, end);
    final lowPassed = _lowPassMono(
      segment,
      sampleRate: sampleRate,
      cutoffHz: cutoffHz,
    );

    const int frameSize = 1024;
    const int hopSize = 256;
    final env = _buildOnsetEnvelopeFromSamples(
      lowPassed,
      frameSize: frameSize,
      hopSize: hopSize,
    );
    if (env.isEmpty) return const <double>[];
    final envHz = sampleRate / hopSize;
    final localMs = _detectTransientTimesMsFromOnsetEnvelope(
      env,
      envSampleRateHz: envHz,
      thresholdStd: thresholdStd,
      minSpacingMs: minSpacingMs,
      maxEvents: maxEvents,
    );
    if (localMs.isEmpty) return const <double>[];

    final clipStartMs = clip.offset * 1000.0;
    final maxTimelineMs = _maxAutomationTimelineMs();
    return localMs
        .map((ms) => (clipStartMs + ms).clamp(0.0, maxTimelineMs).toDouble())
        .toList(growable: false);
  }

  double? _detectTempoFromClipWaveform(AudioTrack clip) {
    final waveform = clip.normWaveformData;
    if (waveform.length < 64 || clip.audioDuration.inMilliseconds <= 0) {
      return null;
    }
    final totalMs = clip.audioDuration.inMilliseconds.toDouble();
    final start = ((clip.trimStart.inMilliseconds / totalMs) * waveform.length)
        .floor()
        .clamp(0, waveform.length)
        .toInt();
    final end = ((clip.trimEnd.inMilliseconds / totalMs) * waveform.length)
        .ceil()
        .clamp(start, waveform.length)
        .toInt();
    final subset = end > start && end - start >= 64
        ? waveform.sublist(start, end)
        : waveform;
    final envelopeHz = waveform.length / (totalMs / 1000.0);
    return _detectTempoFromOnsetEnvelope(
      subset,
      envelopeHz,
      durationSec: subset.length / envelopeHz,
    );
  }

  Future<double?> _detectClipTempoBpm(
    AudioTrack clip, {
    int maxAnalysisSamples = 480000,
  }) async {
    if (clip.isMidi) return null;

    const int sampleRate = 16000;
    Float32List decoded = Float32List(0);
    try {
      decoded = await JuceAudioEngine.decodeAudioMono16kForAnalysis(
        clip.file.path,
        maxOutputSamples: maxAnalysisSamples,
      );
    } catch (_) {
      decoded = Float32List(0);
    }

    if (decoded.isNotEmpty) {
      int start = (clip.trimStart.inMilliseconds * sampleRate / 1000).round();
      int end = (clip.trimEnd.inMilliseconds * sampleRate / 1000).round();
      start = start.clamp(0, decoded.length);
      end = end.clamp(start, decoded.length);
      Float32List segment = decoded;
      if (end > start && end - start >= sampleRate ~/ 2) {
        segment = Float32List.sublistView(decoded, start, end);
      }
      const int tempoHopSize = 128;
      final env = _buildOnsetEnvelopeFromSamples(
        segment,
        hopSize: tempoHopSize,
      );
      if (env.isNotEmpty) {
        final bpm = _detectTempoFromOnsetEnvelope(
          env,
          sampleRate / tempoHopSize,
          durationSec: segment.length / sampleRate,
        );
        if (bpm != null) return bpm;
      }
    }

    return _detectTempoFromClipWaveform(clip);
  }

  Future<void> _setClipTempoFollowMode(
    int clipIndex, {
    required bool preservePitch,
    bool showFeedback = true,
    bool useExistingSourceTempo = false,
  }) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;

    final before = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      tempoStretchEnabled: _tempoStretchEnabled,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    final nextSourceTempoBpm = useExistingSourceTempo && clip.sourceTempoBpm > 0
        ? clip.sourceTempoBpm
        : _sourceTempoForCurrentClipTimeline(clip);

    final after = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: nextSourceTempoBpm,
      stretchToProjectTempo: true,
      tempoStretchPreservePitch: preservePitch,
      tempoWarpMode: preservePitch
          ? kTempoWarpModeComplex
          : kTempoWarpModeRepitch,
      tempoStretchEnabled: true,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    if (before.approxEquals(after)) return;

    await _undoManager.execute(
      _StretchClipResizeAction(
        descriptionText: 'Change clip tempo mode',
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldSnapshot: before,
        newSnapshot: after,
        applySnapshot: (target, snapshot) async {
          target.offset = snapshot.offsetSec;
          target.sourceTempoBpm = snapshot.sourceTempoBpm;
          target.stretchToProjectTempo = snapshot.stretchToProjectTempo;
          target.tempoStretchPreservePitch = snapshot.tempoStretchPreservePitch;
          target.tempoWarpMode = normalizeTempoWarpMode(snapshot.tempoWarpMode);
          _tempoStretchEnabled =
              snapshot.tempoStretchEnabled ??
              _audioTracks
                  .where((t) => !t.isMidi)
                  .any((t) => t.stretchToProjectTempo);
          _tempoStretchPreservePitchDefault =
              snapshot.tempoStretchPreservePitchDefault ??
              _tempoStretchPreservePitchDefault;
          final targetIndex = _audioTracks.indexOf(target);
          if (targetIndex >= 0) {
            await _syncClipTimingToEngine(targetIndex);
          }
          await _syncClipMixToEngine(target);
          _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[target]);
          _scheduleProjectAutosave();
          if (mounted) setState(() {});
        },
      ),
    );

    if (!mounted || !showFeedback) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          preservePitch
              ? 'Clip now follows tempo and preserves pitch.'
              : 'Clip now follows tempo with resample mode.',
        ),
      ),
    );
  }

  Future<void> _handleDisableClipTempoFollow(int clipIndex) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;
    if (!clip.stretchToProjectTempo) return;

    final before = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      tempoStretchEnabled: _tempoStretchEnabled,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    final hasOtherAudioTempoFollow = _audioTracks
        .where((track) => !track.isMidi && !identical(track, clip))
        .any((track) => track.stretchToProjectTempo);
    final after = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: false,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      tempoStretchEnabled: hasOtherAudioTempoFollow
          ? _tempoStretchEnabled
          : false,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    await _undoManager.execute(
      _StretchClipResizeAction(
        descriptionText: 'Change clip tempo mode',
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldSnapshot: before,
        newSnapshot: after,
        applySnapshot: (target, snapshot) async {
          target.offset = snapshot.offsetSec;
          target.sourceTempoBpm = snapshot.sourceTempoBpm;
          target.stretchToProjectTempo = snapshot.stretchToProjectTempo;
          target.tempoStretchPreservePitch = snapshot.tempoStretchPreservePitch;
          target.tempoWarpMode = normalizeTempoWarpMode(snapshot.tempoWarpMode);
          _tempoStretchEnabled =
              snapshot.tempoStretchEnabled ??
              _audioTracks
                  .where((t) => !t.isMidi)
                  .any((t) => t.stretchToProjectTempo);
          _tempoStretchPreservePitchDefault =
              snapshot.tempoStretchPreservePitchDefault ??
              _tempoStretchPreservePitchDefault;
          final targetIndex = _audioTracks.indexOf(target);
          if (targetIndex >= 0) {
            await _syncClipTimingToEngine(targetIndex);
          }
          await _syncClipMixToEngine(target);
          _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[target]);
          _scheduleProjectAutosave();
          if (mounted) setState(() {});
        },
      ),
    );

    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(L10n.translate(context, 'Clip tempo mode turned off.')),
      ),
    );
  }

  Future<void> _handleStretchClipToTempoPreservePitch(int clipIndex) async {
    await _setClipTempoFollowMode(clipIndex, preservePitch: true);
  }

  Future<void> _handleAdjustClipToTempo(int clipIndex) async {
    await _setClipTempoFollowMode(clipIndex, preservePitch: false);
  }

  Future<void> _setClipSourceTempo(int clipIndex, double sourceTempoBpm) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi ||
        !sourceTempoBpm.isFinite ||
        sourceTempoBpm < 20.0 ||
        sourceTempoBpm > 999.0) {
      return;
    }
    final before = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      tempoStretchEnabled: _tempoStretchEnabled,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    final after = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      tempoStretchEnabled: _tempoStretchEnabled,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    if (before.approxEquals(after)) return;
    await _undoManager.execute(
      _StretchClipResizeAction(
        descriptionText: 'Set clip source tempo',
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldSnapshot: before,
        newSnapshot: after,
        applySnapshot: _applyPersistedClipStretchSnapshot,
      ),
    );
  }

  Future<bool> _applyExactClipStretch(
    int clipIndex,
    double newTimelineDurationMs, {
    required bool preservePitch,
    double? newStartMs,
  }) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return false;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return false;
    final rawSec = _rawClipDurationSec(clip);
    if (rawSec <= 0 || !newTimelineDurationMs.isFinite) return false;
    final targetTimelineSec = newTimelineDurationMs / 1000.0;
    final projectTempo = _clampTempo(_tempo);
    final nextSourceTempo = targetTimelineSec * projectTempo / rawSec;
    final playbackRatio = rawSec / targetTimelineSec;
    if (targetTimelineSec < 0.05 ||
        targetTimelineSec > 36000.0 ||
        nextSourceTempo < 20.0 ||
        nextSourceTempo > 999.0 ||
        playbackRatio < 0.05 ||
        playbackRatio > 20.0) {
      return false;
    }
    final before = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      tempoStretchEnabled: _tempoStretchEnabled,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    final after = _ClipStretchSnapshot(
      offsetSec: newStartMs == null
          ? clip.offset
          : math.max(0.0, newStartMs / 1000.0),
      sourceTempoBpm: nextSourceTempo,
      stretchToProjectTempo: true,
      tempoStretchPreservePitch: preservePitch,
      tempoWarpMode: preservePitch
          ? kTempoWarpModeComplex
          : kTempoWarpModeRepitch,
      tempoStretchEnabled: true,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    if (before.approxEquals(after)) return false;
    await _undoManager.execute(
      _StretchClipResizeAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldSnapshot: before,
        newSnapshot: after,
        applySnapshot: _applyPersistedClipStretchSnapshot,
      ),
    );
    return true;
  }

  void _handleStretchClipResize(
    int clipIndex,
    double newTimelineDurationMs, {
    double? newStartMs,
  }) {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;
    _pendingStretchUndoByClip.putIfAbsent(
      clipIndex,
      () => _ClipStretchSnapshot(
        offsetSec: clip.offset,
        sourceTempoBpm: clip.sourceTempoBpm,
        stretchToProjectTempo: clip.stretchToProjectTempo,
        tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
        tempoWarpMode: clip.tempoWarpMode,
      ),
    );

    final rawSec = _rawClipDurationSec(clip);
    if (rawSec <= 0.0) return;

    final targetTimelineSec = (newTimelineDurationMs / 1000.0).clamp(
      0.05,
      36000.0,
    );
    final projectTempo = _clampTempo(_tempo);
    final nextSourceTempo = ((targetTimelineSec * projectTempo) / rawSec).clamp(
      20.0,
      999.0,
    );

    if (!mounted) return;
    setState(() {
      _tempoStretchEnabled = true;
      clip.stretchToProjectTempo = true;
      clip.sourceTempoBpm = nextSourceTempo;
      if (newStartMs != null) {
        clip.offset = math.max(0.0, newStartMs / 1000.0);
      }
    });
    _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
  }

  Future<void> _handleStretchClipResizeCommit(int clipIndex) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;
    final before = _pendingStretchUndoByClip.remove(clipIndex);
    final after = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
    );

    if (before == null || before.approxEquals(after)) {
      await _syncClipTimingToEngine(clipIndex);
      await _syncClipMixToEngine(clip);
      _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
      if (mounted) setState(() {});
      return;
    }

    await _undoManager.execute(
      _StretchClipResizeAction(
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldSnapshot: before,
        newSnapshot: after,
        applySnapshot: (target, snapshot) async {
          target.offset = snapshot.offsetSec;
          target.sourceTempoBpm = snapshot.sourceTempoBpm;
          target.stretchToProjectTempo = snapshot.stretchToProjectTempo;
          target.tempoStretchPreservePitch = snapshot.tempoStretchPreservePitch;
          target.tempoWarpMode = normalizeTempoWarpMode(snapshot.tempoWarpMode);
          _tempoStretchEnabled = _audioTracks
              .where((t) => !t.isMidi)
              .any((t) => t.stretchToProjectTempo);
          final targetIndex = _audioTracks.indexOf(target);
          if (targetIndex >= 0) {
            await _syncClipTimingToEngine(targetIndex);
          }
          await _syncClipMixToEngine(target);
          _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[target]);
          if (mounted) setState(() {});
        },
      ),
    );
  }

  Future<void> _handleDetectClipTempoAndSetProjectTempo(int clipIndex) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;

    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(L10n.translate(context, 'Detecting clip tempo...')),
        ),
      );
    }

    final detected = await _detectClipTempoBpm(clip);
    final initialBpm = _clampTempo(
      detected ??
          (clip.sourceTempoBpm > 0.0
              ? clip.sourceTempoBpm
              : _clampTempo(_tempo)),
    );
    final controller = TextEditingController(
      text: initialBpm.toStringAsFixed(initialBpm % 1.0 == 0.0 ? 0 : 1),
    );
    bool applyProjectTempo = false;
    double? chosenBpm;

    if (mounted) {
      final action = await showDialog<String>(
        context: context,
        barrierColor: Colors.black.withValues(alpha: 0.58),
        builder: (ctx) {
          String? errorText;
          void submit(StateSetter setInnerState, bool setProjectTempo) {
            final parsed = double.tryParse(
              controller.text.trim().replaceAll(',', '.'),
            );
            if (parsed == null || !parsed.isFinite) {
              setInnerState(() {
                errorText = L10n.translate(ctx, 'Enter a valid BPM.');
              });
              return;
            }
            if (parsed < 40.0 || parsed > 240.0) {
              setInnerState(() {
                errorText = L10n.translate(
                  ctx,
                  'BPM must be between 40 and 240.',
                );
              });
              return;
            }
            chosenBpm = _clampTempo(parsed);
            Navigator.of(ctx).pop(setProjectTempo ? 'project' : 'clip');
          }

          return StatefulBuilder(
            builder: (ctx, setInnerState) => MixroomShellDialog(
              radius: 26,
              insetPadding: const EdgeInsets.symmetric(horizontal: 18),
              color: const Color.fromRGBO(26, 38, 56, 0.94),
              child: DefaultTextStyle.merge(
                style: const TextStyle(fontFamily: 'Pretendard'),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Container(
                          width: 42,
                          height: 42,
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.08),
                            borderRadius: BorderRadius.circular(14),
                            border: Border.all(
                              color: Colors.white.withValues(alpha: 0.10),
                            ),
                          ),
                          alignment: Alignment.center,
                          child: const Icon(
                            Icons.speed_rounded,
                            color: Color(0xFFF4F4F4),
                            size: 20,
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(
                            L10n.translate(ctx, 'Set Clip BPM'),
                            style: const TextStyle(
                              color: Color(0xFFF4F4F4),
                              fontSize: 18,
                              fontWeight: FontWeight.w700,
                              height: 1.15,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 14),
                    Text(
                      detected == null
                          ? L10n.translate(
                              ctx,
                              'Tempo detection could not lock. Enter the source BPM manually.',
                            )
                          : '${L10n.translate(ctx, 'Detected')} ${detected.toStringAsFixed(1)} BPM. ${L10n.translate(ctx, 'Edit it if it is wrong.')}',
                      style: TextStyle(
                        color: Colors.white.withValues(alpha: 0.82),
                        fontSize: 13.5,
                        fontWeight: FontWeight.w500,
                        height: 1.35,
                      ),
                    ),
                    const SizedBox(height: 14),
                    TextField(
                      controller: controller,
                      autofocus: true,
                      keyboardType: const TextInputType.numberWithOptions(
                        decimal: true,
                      ),
                      inputFormatters: [
                        FilteringTextInputFormatter.allow(RegExp(r'[0-9\.,]')),
                      ],
                      style: const TextStyle(
                        color: Color(0xFFF4F4F4),
                        fontSize: 28,
                        fontWeight: FontWeight.w800,
                        letterSpacing: 0,
                      ),
                      decoration: InputDecoration(
                        suffixText: 'BPM',
                        suffixStyle: TextStyle(
                          color: Colors.white.withValues(alpha: 0.52),
                          fontSize: 13,
                          fontWeight: FontWeight.w700,
                        ),
                        errorText: errorText,
                        filled: true,
                        fillColor: Colors.white.withValues(alpha: 0.07),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(14),
                          borderSide: BorderSide(
                            color: Colors.white.withValues(alpha: 0.10),
                          ),
                        ),
                        enabledBorder: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(14),
                          borderSide: BorderSide(
                            color: Colors.white.withValues(alpha: 0.10),
                          ),
                        ),
                        focusedBorder: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(14),
                          borderSide: BorderSide(
                            color: Colors.white.withValues(alpha: 0.34),
                          ),
                        ),
                      ),
                      onSubmitted: (_) => submit(setInnerState, true),
                    ),
                    const SizedBox(height: 10),
                    Text(
                      '${L10n.translate(ctx, 'Stretch uses this as the clip source BPM.')} ${L10n.translate(ctx, 'Project is currently')} ${_formatTempoBpm(_tempo)} BPM.',
                      style: TextStyle(
                        color: Colors.white.withValues(alpha: 0.62),
                        fontSize: 12,
                        fontWeight: FontWeight.w500,
                        height: 1.32,
                      ),
                    ),
                    const SizedBox(height: 18),
                    Row(
                      children: [
                        Expanded(
                          child: MixroomShellDialogButton(
                            label: L10n.translate(ctx, 'Cancel'),
                            onPressed: () => Navigator.of(ctx).pop(),
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: MixroomShellDialogButton(
                            label: L10n.translate(ctx, 'Stretch Clip'),
                            onPressed: () => submit(setInnerState, false),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    SizedBox(
                      width: double.infinity,
                      child: MixroomShellDialogButton(
                        label: L10n.translate(ctx, 'Set Project BPM + Stretch'),
                        accent: true,
                        onPressed: () => submit(setInnerState, true),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      );
      applyProjectTempo = action == 'project';
    }
    // showDialog completes as soon as the route starts popping, but the
    // outgoing route can still rebuild TextField during its close animation.
    unawaited(
      Future<void>.delayed(const Duration(milliseconds: 500), () {
        controller.dispose();
      }),
    );
    final manualBpm = chosenBpm;
    if (manualBpm == null) return;

    _setStateAndRefreshProjectSettings(() {
      clip.sourceTempoBpm = manualBpm;
      clip.stretchToProjectTempo = true;
      clip.tempoStretchPreservePitch = _tempoStretchPreservePitchDefault;
      _tempoStretchEnabled = true;
    });

    if (applyProjectTempo) {
      final nextTempo = _clampTempo(manualBpm);
      if ((nextTempo - _clampTempo(_tempo)).abs() < 0.0001) {
        await _syncClipTimingToEngine(clipIndex);
        await _syncClipMixToEngine(clip);
        _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
      } else {
        await _applyProjectTempoChange(nextTempo, recordUndo: true);
      }
    } else {
      await _syncClipTimingToEngine(clipIndex);
      await _syncClipMixToEngine(clip);
      _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
    }

    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          applyProjectTempo
              ? '${L10n.translate(context, 'Clip source set to')} ${manualBpm.toStringAsFixed(1)} BPM. ${L10n.translate(context, 'Project BPM updated.')}'
              : '${L10n.translate(context, 'Clip source set to')} ${manualBpm.toStringAsFixed(1)} BPM.',
        ),
      ),
    );
  }

  Future<void> _openClipWarpEditor(int clipIndex) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (clip.isMidi) return;

    final rawSec = _rawClipDurationSec(clip);
    if (rawSec <= 0.0) return;

    final initialBpm = _resolvedClipSourceTempoBpm(clip) > 0.0
        ? _resolvedClipSourceTempoBpm(clip)
        : _clampTempo(_tempo);
    final bpmController = TextEditingController(
      text: _formatTempoBpm(initialBpm),
    );

    var chosenWarpEnabled = clip.stretchToProjectTempo;
    var chosenPreservePitch = clip.tempoStretchPreservePitch;
    var chosenBpm = initialBpm;
    var chosenMode = switch (normalizeTempoWarpMode(clip.tempoWarpMode)) {
      kTempoWarpModeBeats => 'Beats',
      kTempoWarpModeRepitch => 'Repitch',
      _ => 'Complex',
    };
    if (clip.stretchToProjectTempo && !clip.tempoStretchPreservePitch) {
      chosenMode = 'Repitch';
    }

    final action = await showDialog<String>(
      context: context,
      barrierColor: Colors.black.withValues(alpha: 0.62),
      builder: (ctx) {
        String? errorText;

        void setBpmFromBars(StateSetter setInnerState, int bars) {
          final beats = math.max(1.0, bars * _projectBarLengthQuarterBeats);
          final next = _clampTempo((beats * 60.0) / rawSec);
          setInnerState(() {
            chosenWarpEnabled = true;
            chosenPreservePitch = true;
            chosenMode = bars <= 1 ? 'Beats' : 'Complex';
            chosenBpm = next;
            bpmController.text = _formatTempoBpm(next);
            errorText = null;
          });
        }

        void submit(StateSetter setInnerState) {
          if (!chosenWarpEnabled) {
            Navigator.of(ctx).pop('apply');
            return;
          }
          final parsed = double.tryParse(
            bpmController.text.trim().replaceAll(',', '.'),
          );
          if (parsed == null || !parsed.isFinite) {
            setInnerState(() {
              errorText = L10n.translate(ctx, 'Enter a valid BPM.');
            });
            return;
          }
          if (parsed < 20.0 || parsed > 999.0) {
            setInnerState(() {
              errorText = L10n.translate(
                ctx,
                'BPM must be between 20 and 999.',
              );
            });
            return;
          }
          chosenBpm = _clampTempo(parsed);
          chosenPreservePitch = chosenMode != 'Repitch';
          Navigator.of(ctx).pop('apply');
        }

        Widget modeButton(
          StateSetter setInnerState,
          String label,
          IconData icon,
        ) {
          final selected = chosenMode == label;
          return Expanded(
            child: Tooltip(
              message: label,
              child: InkWell(
                borderRadius: BorderRadius.circular(10),
                onTap: () {
                  setInnerState(() {
                    chosenMode = label;
                    chosenWarpEnabled = true;
                    chosenPreservePitch = label != 'Repitch';
                  });
                },
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 120),
                  height: 40,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: selected
                        ? const Color(0xFF78D9FF).withValues(alpha: 0.20)
                        : Colors.white.withValues(alpha: 0.055),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: selected
                          ? const Color(0xFF78D9FF).withValues(alpha: 0.42)
                          : Colors.white.withValues(alpha: 0.09),
                    ),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(
                        icon,
                        size: 15,
                        color: selected
                            ? const Color(0xFF78D9FF)
                            : Colors.white70,
                      ),
                      const SizedBox(width: 5),
                      Flexible(
                        child: Text(
