                      Row(
                        children: [
                          Expanded(
                            child: MixroomShellDialogButton(
                              label: L10n.translate(ctx, 'Cancel'),
                              onPressed: () => Navigator.of(ctx).pop(),
                            ),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: MixroomShellDialogButton(
                              label: chosenWarpEnabled
                                  ? 'Apply Warp'
                                  : 'Turn Off',
                              accent: true,
                              onPressed: () => submit(setInnerState),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );

    unawaited(
      Future<void>.delayed(const Duration(milliseconds: 500), () {
        bpmController.dispose();
      }),
    );
    if (action != 'apply') return;

    final before = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: clip.sourceTempoBpm,
      stretchToProjectTempo: clip.stretchToProjectTempo,
      tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
      tempoWarpMode: clip.tempoWarpMode,
      tempoStretchEnabled: _tempoStretchEnabled,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    final hasOtherAudioTempoFollow = _audioTracks
        .where((track) => !track.isMidi && !identical(track, clip))
        .any((track) => track.stretchToProjectTempo);
    final after = _ClipStretchSnapshot(
      offsetSec: clip.offset,
      sourceTempoBpm: _clampTempo(chosenBpm),
      stretchToProjectTempo: chosenWarpEnabled,
      tempoStretchPreservePitch: chosenWarpEnabled && chosenPreservePitch,
      tempoWarpMode: normalizeTempoWarpMode(chosenMode),
      tempoStretchEnabled: chosenWarpEnabled || hasOtherAudioTempoFollow,
      tempoStretchPreservePitchDefault: _tempoStretchPreservePitchDefault,
    );
    if (before.approxEquals(after)) return;

    await _undoManager.execute(
      _StretchClipResizeAction(
        descriptionText: 'Apply clip warp',
        tracks: _audioTracks,
        originalIndex: clipIndex,
        oldSnapshot: before,
        newSnapshot: after,
        applySnapshot: (target, snapshot) async {
          target.offset = snapshot.offsetSec;
          target.sourceTempoBpm = snapshot.sourceTempoBpm;
          target.stretchToProjectTempo = snapshot.stretchToProjectTempo;
          target.tempoStretchPreservePitch = snapshot.tempoStretchPreservePitch;
          target.tempoWarpMode = normalizeTempoWarpMode(snapshot.tempoWarpMode);
          _tempoStretchEnabled =
              snapshot.tempoStretchEnabled ??
              _audioTracks
                  .where((t) => !t.isMidi)
                  .any((t) => t.stretchToProjectTempo);
          _tempoStretchPreservePitchDefault =
              snapshot.tempoStretchPreservePitchDefault ??
              _tempoStretchPreservePitchDefault;
          final targetIndex = _audioTracks.indexOf(target);
          if (targetIndex >= 0) {
            await _syncClipTimingToEngine(targetIndex);
          }
          await _syncClipMixToEngine(target);
          _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[target]);
          _scheduleProjectAutosave();
          if (mounted) setState(() {});
        },
      ),
    );

    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          chosenWarpEnabled
              ? 'Warp applied: $chosenMode at ${_formatTempoBpm(chosenBpm)} BPM.'
              : 'Warp turned off.',
        ),
      ),
    );
  }

  void _clearCopiedClip() {
    if (_copiedClip == null &&
        (_copiedClipGroup == null || _copiedClipGroup!.isEmpty)) {
      return;
    }
    setState(() {
      _copiedClip = null;
      _copiedClipGroup = null;
      _copiedTrimStart = Duration.zero;
      _copiedTrimEnd = Duration.zero;
    });
  }

  bool _canPasteCopiedClipAtRow(int row) {
    if (row < 0 || row >= _rows.length) return false;
    final group = _copiedClipGroup;
    if (group != null && group.isNotEmpty) {
      for (final entry in group) {
        final targetRow = row + entry.rowDelta;
        if (targetRow < 0 || targetRow >= _rows.length) return false;
        if (!_rowAllowsClipKind(targetRow, entry.clip.clipKind)) {
          return false;
        }
        if (entry.clip.isMidi &&
            !_instrumentLaneCanAcceptClip(targetRow, entry.clip)) {
          return false;
        }
      }
      return true;
    }
    final clip = _copiedClip;
    if (clip == null) return false;
    if (!_rowAllowsClipKind(row, clip.clipKind)) return false;
    return !clip.isMidi || _instrumentLaneCanAcceptClip(row, clip);
  }

  bool _instrumentLaneCanAcceptClip(int row, AudioTrack clip) {
    if (row < 0 || row >= _rows.length || !clip.isMidi) return false;
    final lane = _rows[row];
    if (!lane.isInstrumentLane) return false;
    final laneInstrumentId = lane.instrumentId.trim();
    final clipInstrumentId = clip.instrumentId.trim();
    return laneInstrumentId.isEmpty ||
        clipInstrumentId.isEmpty ||
        laneInstrumentId == clipInstrumentId;
  }

  void _handleCopyClip(int clipIndex) {
    _handleCopyClips(<int>[clipIndex]);
  }

  void _handleCopyClips(List<int> clipIndices) {
    final valid = clipIndices
        .where((i) => i >= 0 && i < _audioTracks.length)
        .toSet()
        .toList();
    if (valid.isEmpty) return;

    valid.sort((a, b) {
      final da = _audioTracks[a].offset;
      final db = _audioTracks[b].offset;
      final cmpOffset = da.compareTo(db);
      if (cmpOffset != 0) return cmpOffset;
      final cmpRow = _audioTracks[a].rowIndex.compareTo(
        _audioTracks[b].rowIndex,
      );
      if (cmpRow != 0) return cmpRow;
      return a.compareTo(b);
    });

    final anchor = _audioTracks[valid.first];
    final anchorStartMs = anchor.offset * 1000.0;
    final anchorRow = anchor.rowIndex;
    final group = valid
        .map(
          (index) => _CopiedClipGroupEntry(
            clip: _audioTracks[index],
            trimStart: _audioTracks[index].trimStart,
            trimEnd: _audioTracks[index].trimEnd,
            offsetDeltaMs: _audioTracks[index].offset * 1000.0 - anchorStartMs,
            rowDelta: _audioTracks[index].rowIndex - anchorRow,
          ),
        )
        .toList(growable: false);

    setState(() {
      _copiedClip = anchor;
      _copiedTrimStart = anchor.trimStart;
      _copiedTrimEnd = anchor.trimEnd;
      _copiedClipGroup = group.length > 1 ? group : null;
    });
  }

  EditorUndoAction _buildPasteAction({
    required AudioTrack clip,
    required int row,
    required double timeMs,
    required Duration trimStart,
    required Duration trimEnd,
  }) {
    if (clip.isMidi) {
      return PasteMidiClipAction(
        pasteMidiClip:
            ({
              required AudioTrack clip,
              required int row,
              required double timeMs,
              Duration? trimStartRequested,
              Duration? trimEndRequested,
            }) => _pasteMidiTrack(
              clip,
              row,
              timeMs,
              trimStartRequested: trimStartRequested,
              trimEndRequested: trimEndRequested,
            ),
        tracks: _audioTracks,
        restoreTrack: _addClipFromUndoPayload,
        clip: clip,
        row: row,
        timeMs: timeMs,
        trimStart: trimStart,
        trimEnd: trimEnd,
        onRemove: _syncRemovedClipFadesAfterUndo,
      );
    }

    return PasteAudioClipAction(
      pasteClip:
          ({
            required AudioTrack clip,
            required int row,
            required double timeMs,
            Duration? trimStartRequested,
            Duration? trimEndRequested,
          }) => _pasteAudioTrack(
            clip,
            row,
            timeMs,
            trimStartRequested: trimStartRequested,
            trimEndRequested: trimEndRequested,
          ),
      tracks: _audioTracks,
      restoreTrack: _addClipFromUndoPayload,
      clip: clip,
      row: row,
      timeMs: timeMs,
      trimStart: trimStart,
      trimEnd: trimEnd,
      onRemove: _syncRemovedClipFadesAfterUndo,
    );
  }

  DeleteClipAction _buildDeleteClipAction(AudioTrack clip) {
    return DeleteClipAction(
      tracks: _audioTracks,
      clip: clip,
      addTrack:
          ({
            required AudioTrack clip,
            required int row,
            required double timeMs,
            required Duration trimStartRequested,
            required Duration trimEndRequested,
          }) => clip.isMidi
          ? _addMidiTrack(
              instrumentId: clip.instrumentId,
              instrumentName: clip.instrumentName,
              instrumentParams: Map<String, double>.from(clip.instrumentParams),
              midiNotes: clip.midiNotes.map((n) => n.copy()).toList(),
              row: row,
              timeMs: timeMs,
              trimStartRequested: trimStartRequested,
              trimEndRequested: trimEndRequested,
              renderedFile: clip.file,
              label: clip.label,
              gain: clip.gain,
              pitchSemitones: clip.pitchSemitones,
              sourceTempoBpm: clip.sourceTempoBpm,
              stretchToProjectTempo: clip.stretchToProjectTempo,
              tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
              tempoWarpMode: clip.tempoWarpMode,
              crossfade: clip.crossfade,
              automation: clip.volumeAutomation.map((p) => p.copy()).toList(),
              hostedInstrumentStateBase64: clip.hostedInstrumentStateBase64,
              clipId: clip.clipId,
            )
          : _addAudioTrackFromProjectFile(
              projectAudioFile: clip.file,
              label: clip.label,
              row: row,
              timeMs: timeMs,
              trimStartRequested: trimStartRequested,
              trimEndRequested: trimEndRequested,
              gain: clip.gain,
              normalizeVolume: clip.normalizeVolume,
              normalizeGain: clip.normalizeGain,
              preNormalizeGain: clip.preNormalizeGain,
              pitchSemitones: clip.pitchSemitones,
              sourceTempoBpm: clip.sourceTempoBpm,
              stretchToProjectTempo: clip.stretchToProjectTempo,
              tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
              tempoWarpMode: clip.tempoWarpMode,
              crossfade: clip.crossfade,
              automation: clip.volumeAutomation.map((p) => p.copy()).toList(),
              clipId: clip.clipId,
            ),
      onChange: (changedClip, {required removed}) {
        if (removed) {
          _updateOverallDurationIfNeeded(
            removedClips: <AudioTrack>[changedClip],
          );
        } else {
          _updateOverallDurationIfNeeded(forceRebuild: true);
        }
        unawaited(
          _syncClipFadesForRowsToEngine({_clipRowIdForFadeSync(changedClip)}),
        );
        if (removed) {
          _clipFadeRowIdByEngineId.remove(changedClip.engineClipId);
        }
      },
    );
  }

  Future<void> _handleMoveClips(List<TimelineClipMoveRequest> moves) async {
    final actions = <EditorUndoAction>[];
    final movesByIndex = <int, TimelineClipMoveRequest>{};
    final affectedFadeRowIds = <int>{};
    for (final move in moves) {
      final clipIndex = move.clipIndex;
      if (clipIndex < 0 || clipIndex >= _audioTracks.length) continue;
      final clip = _audioTracks[clipIndex];
      final nextRow = move.newRowIndex
          .clamp(0, math.max(0, _rowCount - 1))
          .toInt();
      if (!_rowAllowsClipKind(nextRow, clip.clipKind)) {
        _showSmallNotice(
          clip.isMidi
              ? 'MIDI clips belong on instrument lanes.'
              : 'Audio clips cannot be placed on instrument lanes.',
        );
        return;
      }
      final nextOffset = math.max(0.0, move.newStartMs) / 1000.0;
      final rowChanged = nextRow != clip.rowIndex;
      final offsetChanged = (nextOffset - clip.offset).abs() > 0.0005;
      if (!rowChanged && !offsetChanged) continue;
      final oldRowId = _clipRowIdForFadeSync(clip);
      final nextRowId = _rowIdAt(nextRow);
      affectedFadeRowIds
        ..add(oldRowId)
        ..add(nextRowId);
      final actionFadeRowIds = <int>{oldRowId, nextRowId};
      movesByIndex[clipIndex] = move;
      actions.add(
        MoveClipAction(
          tracks: _audioTracks,
          originalIndex: clipIndex,
          oldOffset: clip.offset,
          oldRow: clip.rowIndex,
          newOffset: nextOffset,
          newRow: nextRow,
          onChange: () {
            clip.rowId = _rowIdAt(clip.rowIndex);
            if (_deferClipTimelineEngineSync) {
              _deferredClipTimelineSyncIndices.add(clipIndex);
              _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
              return;
            }
            unawaited(
              _syncClipTimingToEngine(
                clipIndex,
                additionalFadeRowIds: actionFadeRowIds,
              ),
            );
            _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
          },
        ),
      );
    }
    actions.addAll(_buildCutOverlapTrimActions(movesByIndex));
    if (actions.isEmpty) return;
    _deferredClipTimelineSyncIndices.clear();
    _deferClipTimelineEngineSync = true;
    try {
      if (actions.length == 1) {
        await _undoManager.execute(actions.first);
      } else {
        final description =
            _normalizeProjectCrossfadeMode(_projectCrossfadeMode) == 'cut'
            ? 'Move clips with cut'
            : 'Move clips';
        await _undoManager.execute(CompoundUndoAction(description, actions));
      }
    } finally {
      _deferClipTimelineEngineSync = false;
    }
    await _syncDeferredClipTimelineBatchToEngine(
      _deferredClipTimelineSyncIndices,
    );
    _deferredClipTimelineSyncIndices.clear();
    await _syncClipFadesForRowsToEngine(affectedFadeRowIds);
    // Clip moves change rendered-plugin timing. Persist the final model only
    // after the native timeline batch has accepted the same move, so the
    // compatibility render and cloud bundle cannot retain the old position.
    _scheduleProjectAutosave();
    if (!mounted) return;
    setState(() {});
  }

  double _timelineTrimDeltaToSourceMs(AudioTrack clip, double timelineDeltaMs) {
    final timelineMs = _clipTimelineDurationMs(clip);
    final rawMs = _rawClipDurationSec(clip) * 1000.0;
    if (timelineMs <= 0.0 || rawMs <= 0.0) return timelineDeltaMs;
    return timelineDeltaMs * (rawMs / timelineMs);
  }

  List<EditorUndoAction> _buildCutOverlapTrimActions(
    Map<int, TimelineClipMoveRequest> movesByIndex,
  ) {
    if (movesByIndex.isEmpty ||
        _normalizeProjectCrossfadeMode(_projectCrossfadeMode) != 'cut') {
      return const <EditorUndoAction>[];
    }

    const double overlapEpsilonMs = 0.5;
    const double minVisibleTimelineMs = 20.0;
    final movedIndices = movesByIndex.keys.toSet();
    final actions = <EditorUndoAction>[];
    final orderedMoves = movesByIndex.entries.toList()
      ..sort((a, b) {
        final aStart = math.max(0.0, a.value.newStartMs);
        final bStart = math.max(0.0, b.value.newStartMs);
        return aStart.compareTo(bStart);
      });

    for (
      int targetIndex = 0;
      targetIndex < _audioTracks.length;
      targetIndex++
    ) {
      if (movedIndices.contains(targetIndex)) continue;
      final target = _audioTracks[targetIndex];
      var targetStartMs = target.offset * 1000.0;
      var targetEndMs = targetStartMs + _clipTimelineDurationMs(target);
      if (targetEndMs <= targetStartMs + minVisibleTimelineMs) continue;

      var nextTrimStartMs = target.trimStart.inMilliseconds.toDouble();
      var nextTrimEndMs = target.trimEnd.inMilliseconds.toDouble();
      var nextOffsetSec = target.offset;
      var changed = false;

      for (final entry in orderedMoves) {
        final movedIndex = entry.key;
        if (movedIndex < 0 || movedIndex >= _audioTracks.length) continue;
        final moved = _audioTracks[movedIndex];
        final movedRow = entry.value.newRowIndex
            .clamp(0, math.max(0, _rowCount - 1))
            .toInt();
        if (movedRow != target.rowIndex) continue;
        final movedStartMs = math.max(0.0, entry.value.newStartMs);
        final movedEndMs = movedStartMs + _clipTimelineDurationMs(moved);
        if (movedEndMs <= movedStartMs) continue;

        final overlapStartMs = math.max(targetStartMs, movedStartMs);
        final overlapEndMs = math.min(targetEndMs, movedEndMs);
        if (overlapEndMs <= overlapStartMs + overlapEpsilonMs) continue;

        final remainingLeftMs = (overlapStartMs - targetStartMs).clamp(
          0.0,
          double.infinity,
        );
        final remainingRightMs = (targetEndMs - overlapEndMs).clamp(
          0.0,
          double.infinity,
        );
        final trimStartSide =
            overlapStartMs <= targetStartMs + overlapEpsilonMs ||
            (overlapEndMs < targetEndMs - overlapEpsilonMs &&
                remainingRightMs > remainingLeftMs);

        if (trimStartSide) {
          final nextStartMs = overlapEndMs;
          final newVisibleMs = targetEndMs - nextStartMs;
          if (newVisibleMs < minVisibleTimelineMs) continue;
          final sourceDeltaMs = _timelineTrimDeltaToSourceMs(
            target,
            nextStartMs - targetStartMs,
          );
          final candidateTrimStartMs = nextTrimStartMs + sourceDeltaMs;
          if (candidateTrimStartMs >= nextTrimEndMs - 1.0) continue;
          nextTrimStartMs = candidateTrimStartMs;
          nextOffsetSec = nextStartMs / 1000.0;
          targetStartMs = nextStartMs;
          changed = true;
        } else {
          final nextEndMs = overlapStartMs;
          final newVisibleMs = nextEndMs - targetStartMs;
          if (newVisibleMs < minVisibleTimelineMs) continue;
          final sourceDeltaMs = _timelineTrimDeltaToSourceMs(
            target,
            targetEndMs - nextEndMs,
          );
          final candidateTrimEndMs = nextTrimEndMs - sourceDeltaMs;
          if (candidateTrimEndMs <= nextTrimStartMs + 1.0) continue;
          nextTrimEndMs = candidateTrimEndMs;
          targetEndMs = nextEndMs;
          changed = true;
        }
      }

      if (!changed) continue;
      actions.add(
        TrimClipAction(
          tracks: _audioTracks,
          originalIndex: targetIndex,
          oldTrimStart: target.trimStart,
          oldTrimEnd: target.trimEnd,
          oldOffset: target.offset,
          newTrimStart: Duration(milliseconds: nextTrimStartMs.round()),
          newTrimEnd: Duration(milliseconds: nextTrimEndMs.round()),
          newOffset: nextOffsetSec,
          onChange: () {
            if (_deferClipTimelineEngineSync) {
              _deferredClipTimelineSyncIndices.add(targetIndex);
              _updateOverallDurationIfNeeded(
                changedClips: <AudioTrack>[target],
              );
              return;
            }
            unawaited(_syncClipTimingToEngine(targetIndex));
            _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[target]);
          },
        ),
      );
    }

    return actions;
  }

  Future<void> _handleDeleteClip(int clipIndex) async {
    await _handleDeleteClips(<int>[clipIndex]);
  }

  Future<void> _handleDeleteClips(List<int> clipIndices) async {
    final validDescending =
        clipIndices
            .where((i) => i >= 0 && i < _audioTracks.length)
            .toSet()
            .toList()
          ..sort((a, b) => b.compareTo(a));
    if (validDescending.isEmpty) return;

    final actions = <EditorUndoAction>[];
    final deletedClips = <AudioTrack>[];
    bool deletedActiveMidi = false;
    bool deletedActivePitchLab = false;
    bool deletedActivePitchLabAudio = false;
    for (final index in validDescending) {
      if (index < 0 || index >= _audioTracks.length) continue;
      final clip = _audioTracks[index];
      deletedClips.add(clip);
      if (_activeMidiClipEngineId != null &&
          clip.engineClipId == _activeMidiClipEngineId) {
        deletedActiveMidi = true;
      }
      if (_activePitchLabClipEngineId != null &&
          clip.engineClipId == _activePitchLabClipEngineId) {
        deletedActivePitchLab = true;
      }
      if (_activePitchLabSourceAudioEngineId != null &&
          clip.engineClipId == _activePitchLabSourceAudioEngineId) {
        deletedActivePitchLabAudio = true;
      }
      actions.add(_buildDeleteClipAction(clip));
    }
    if (actions.isEmpty) return;

    if (actions.length == 1) {
      await _undoManager.execute(actions.first);
    } else {
      final affectedRowIds = deletedClips
          .map(_clipRowIdForFadeSync)
          .where((rowId) => rowId >= 0)
          .toSet();
      final deleteActions = actions.cast<DeleteClipAction>();
      await _undoManager.execute(
        DeleteClipsAction(
          actions: deleteActions,
          beginRestoreBatch: () async {
            await JuceAudioEngine.beginGraphMutationBatch();
          },
          endRestoreBatch: () async {
            await JuceAudioEngine.endGraphMutationBatch();
          },
          onChange: (changedClips, {required removed}) async {
            if (removed) {
              for (final clip in changedClips) {
                _clipFadeRowIdByEngineId.remove(clip.engineClipId);
              }
              _updateOverallDurationIfNeeded(removedClips: changedClips);
            } else {
              _updateOverallDurationIfNeeded(forceRebuild: true);
            }
            await _syncClipFadesForRowsToEngine(affectedRowIds);
          },
        ),
      );
    }

    if (deletedActiveMidi) {
      _closeMidiClipEditor();
    }
    if (deletedActivePitchLab || deletedActivePitchLabAudio) {
      _closePitchLabEditor();
    }

    Future.delayed(const Duration(milliseconds: 50), () {
      if (!mounted) return;
      setState(() {});
    });
  }

  void _openCaptureDeck() {
    if (_showCaptureDeck) return;
    setState(() {
      _showCaptureDeck = true;
      _sampleBrowserVisible = false;
      _showPianoRoll = false;
      _showPitchLab = false;
      _pitchLabFullscreen = false;
      _activePitchLabClipEngineId = null;
      _activePitchLabClipIndex = null;
      _pitchLabAudioMode = false;
      _activePitchLabSourceAudioEngineId = null;
      _activePitchLabSourceAudioIndex = null;
      _pitchLabAudioOriginalNotes = <MidiNote>[];
      _pitchLabAudioDraftNotes = <MidiNote>[];
      _pitchLabAudioAnalyzing = false;
      _pitchLabAudioRendering = false;
    });
    _syncMeterPollingForVisibility();
  }

  void _closeCaptureDeck() {
    if (!_showCaptureDeck) return;
    setState(() {
      _showCaptureDeck = false;
      _captureDeckFullscreen = false;
    });
    _syncMeterPollingForVisibility();
  }

  List<int> _captureDeckSelectedClipIndices() {
    final selected = _timelineSelectedClipIndices
        .where((idx) => idx >= 0 && idx < _audioTracks.length)
        .toSet()
        .toList();
    if (selected.isEmpty &&
        _timelinePrimarySelectedClipIndex >= 0 &&
        _timelinePrimarySelectedClipIndex < _audioTracks.length) {
      selected.add(_timelinePrimarySelectedClipIndex);
    }
    selected.sort((a, b) {
      final aClip = _audioTracks[a];
      final bClip = _audioTracks[b];
      final rowCompare = aClip.rowIndex.compareTo(bClip.rowIndex);
      if (rowCompare != 0) return rowCompare;
      return aClip.offset.compareTo(bClip.offset);
    });
    return selected;
  }

  String _captureDeckSelectedClipLabel() {
    final selected = _captureDeckSelectedClipIndices();
    if (selected.isEmpty) return 'No clip selected';
    if (selected.length > 1) return '${selected.length} clips selected';
    final label = _audioTracks[selected.single].label.trim();
    return label.isEmpty ? 'Selected clip' : label;
  }

  String _captureDeckSelectedRowName() {
    if (_rowCount <= 0) return 'No track';
    final row = _selectedRow.clamp(0, _rowCount - 1).toInt();
    final name = _rows[row].name.trim();
    return name.isEmpty ? 'Track ${row + 1}' : name;
  }

  bool _captureDeckCanBounceSelection() {
    return _captureDeckSelectedClipIndices().isNotEmpty;
  }

  bool _captureDeckCanCleanUpRecording() {
    return _captureDeckSelectedClipIndices().any(
      (index) =>
          index >= 0 &&
          index < _audioTracks.length &&
          !_audioTracks[index].isMidi,
    );
  }

  bool _captureDeckCanFreezeRow() {
    if (_rowCount <= 0) return false;
    final row = _selectedRow.clamp(0, _rowCount - 1).toInt();
    return _rowHasTimelineClip(row);
  }

  Future<int> _createCaptureTargetRow({
    required String name,
    int? afterRow,
  }) async {
    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return -1;
    }

    int targetRow;
    if (afterRow != null && afterRow >= 0 && afterRow < _rowCount) {
      final inserted = await _insertRowBelowImpl(afterRow);
      if (!inserted) return -1;
      targetRow = afterRow + 1;
    } else {
      final added = await _addRowImpl();
      if (!added) return -1;
      targetRow = _rowCount - 1;
    }

    if (targetRow >= 0 && targetRow < _rowCount) {
      final rowId = _rowIdAt(targetRow);
      final safeName = name.trim().isEmpty ? 'Capture' : name.trim();
      await JuceAudioEngine.renameRow(rowId, safeName);
      setState(() {
        _rows[targetRow].name = safeName;
        _selectedRow = targetRow;
      });
    }
    return targetRow;
  }

  Future<File?> _renderClipSetForCapture({
    required Set<int> selectedIndices,
    required double selectionStartSec,
    required String fileStem,
    required bool includeRowAndMasterFx,
  }) async {
    final audioDir = ProjectManager.audioDir(_projectDir);
    await audioDir.create(recursive: true);
    final outFile = File(
      p.join(
        audioDir.path,
        '${fileStem}_${DateTime.now().microsecondsSinceEpoch}.wav',
      ),
    );
    await _prepareNativeEngineStateForExport((_) {});
    final renderedPath = await JuceAudioEngine.exportMix(
      outFile.path,
      format: 'wav',
      sampleRate: 48000,
      wavBitDepth: 24,
      wavDithering: false,
      clipSnapshotJson: _buildGlueExportClipSnapshotJson(
        selectedIndices: selectedIndices,
        selectionStartSec: selectionStartSec,
      ),
      dryClipRender: !includeRowAndMasterFx,
    );
    final rendered = File(
      renderedPath.trim().isNotEmpty ? renderedPath : outFile.path,
    );
    if (!await rendered.exists()) return null;
    if (await rendered.length() <= 44) return null;
    return rendered;
  }

  Future<void> _handleBounceSelectedToTimeline() async {
    if (_captureDeckBusy || _isRecording) return;
    final selected = _captureDeckSelectedClipIndices();
    if (selected.isEmpty) {
      _showSmallNotice('Select a clip to bounce.');
      return;
    }

    setState(() => _captureDeckBusy = true);
    try {
      final clips = selected.map((idx) => _audioTracks[idx]).toList();
      final startSec = clips.map((clip) => clip.offset).reduce(math.min);
      final endSec = clips
          .map((clip) => clip.offset + _clipTimelineDurationSec(clip))
          .reduce(math.max);
      final durationSec = math.max(0.0, endSec - startSec);
      if (durationSec <= 0.05) {
        _showSmallNotice('Selection is too short to bounce.');
        return;
      }

      _showSmallNotice('Bouncing selection...');
      final rendered = await _renderClipSetForCapture(
        selectedIndices: selected.toSet(),
        selectionStartSec: startSec,
        fileStem: 'bounce_selection',
        includeRowAndMasterFx: true,
      );
      if (rendered == null) {
        _showSmallNotice('Could not bounce the selection.');
        return;
      }
      final targetRow = await _createCaptureTargetRow(name: 'Bounce');
      if (targetRow < 0) return;
      await _addAudioTrackFromProjectFile(
        projectAudioFile: rendered,
        label: 'Bounced Selection',
        row: targetRow,
        timeMs: startSec * 1000.0,
        trimStartRequested: Duration.zero,
        trimEndRequested: Duration(milliseconds: (durationSec * 1000).round()),
        gain: kDefaultGainUi,
        sourceTempoBpm: _tempo,
        stretchToProjectTempo: false,
        tempoStretchPreservePitch: false,
      );
      _scheduleProjectAutosave();
      _showSmallNotice('Bounced selection to a new audio track.');
    } finally {
      if (mounted) setState(() => _captureDeckBusy = false);
    }
  }

  Future<void> _handleCleanUpSelectedRecording() async {
    if (_captureDeckBusy || _isRecording) return;
    final selected = _captureDeckSelectedClipIndices()
        .where(
          (index) =>
              index >= 0 &&
              index < _audioTracks.length &&
              !_audioTracks[index].isMidi,
        )
        .toList(growable: false);
    if (selected.isEmpty) {
      _showSmallNotice('Select an audio recording to clean up.');
      return;
    }

    setState(() => _captureDeckBusy = true);
    try {
      await _applyAudioEnhancementAction({
        'operation': 'phone_mic_cleanup',
        'target': {'clip_indices': selected},
      });
    } finally {
      if (mounted) setState(() => _captureDeckBusy = false);
    }
  }

  Future<void> _handleFreezeSelectedRowToAudio() async {
    if (_captureDeckBusy || _isRecording) return;
    if (_rowCount <= 0) return;
    final row = _selectedRow.clamp(0, _rowCount - 1).toInt();
    final rowClipIndices = <int>[];
    for (int i = 0; i < _audioTracks.length; i++) {
      if (_audioTracks[i].rowIndex == row) rowClipIndices.add(i);
    }
    if (rowClipIndices.isEmpty) {
      _showSmallNotice('Selected row has no clips to freeze.');
      return;
    }

    setState(() => _captureDeckBusy = true);
    try {
      final clips = rowClipIndices.map((idx) => _audioTracks[idx]).toList();
      final startSec = clips.map((clip) => clip.offset).reduce(math.min);
      final endSec = clips
          .map((clip) => clip.offset + _clipTimelineDurationSec(clip))
          .reduce(math.max);
      final durationSec = math.max(0.0, endSec - startSec);
      if (durationSec <= 0.05) {
        _showSmallNotice('Row is too short to freeze.');
        return;
      }

      _showSmallNotice('Freezing row...');
      final rendered = await _renderClipSetForCapture(
        selectedIndices: rowClipIndices.toSet(),
        selectionStartSec: startSec,
        fileStem: 'freeze_row',
        includeRowAndMasterFx: true,
      );
      if (rendered == null) {
        _showSmallNotice('Could not freeze this row.');
        return;
      }
      final sourceName = _rows[row].name.trim().isEmpty
          ? 'Track ${row + 1}'
          : _rows[row].name.trim();
      final targetRow = await _createCaptureTargetRow(
        name: '$sourceName Freeze',
        afterRow: row,
      );
      if (targetRow < 0) return;
      await _addAudioTrackFromProjectFile(
        projectAudioFile: rendered,
        label: '$sourceName Freeze',
        row: targetRow,
        timeMs: startSec * 1000.0,
        trimStartRequested: Duration.zero,
        trimEndRequested: Duration(milliseconds: (durationSec * 1000).round()),
        gain: kDefaultGainUi,
        sourceTempoBpm: _tempo,
        stretchToProjectTempo: false,
        tempoStretchPreservePitch: false,
      );
      if (row >= 0 && row < _rowMuted.length) {
        setState(() => _rowMuted[row] = true);
        await _recomputeAudibleState();
      }
      _scheduleProjectAutosave();
      _showSmallNotice('Frozen row rendered to audio.');
    } finally {
      if (mounted) setState(() => _captureDeckBusy = false);
    }
  }

  Future<void> _handleCaptureMixToTimeline() async {
    if (_captureDeckBusy || _isRecording) return;
    if (_audioTracks.isEmpty) {
      _showSmallNotice('Nothing to capture yet.');
      return;
    }

    setState(() => _captureDeckBusy = true);
    try {
      _showSmallNotice('Capturing mix...');
      final audioDir = ProjectManager.audioDir(_projectDir);
      await audioDir.create(recursive: true);
      final outFile = File(
        p.join(
          audioDir.path,
          'capture_mix_${DateTime.now().microsecondsSinceEpoch}.wav',
        ),
      );
      await _prepareNativeEngineStateForExport((_) {});
      final renderedPath = await JuceAudioEngine.exportMix(
        outFile.path,
        format: 'wav',
        sampleRate: 48000,
        wavBitDepth: 24,
        wavDithering: false,
        clipSnapshotJson: _buildNativeExportClipSnapshotJson(),
      );
      final rendered = File(
        renderedPath.trim().isNotEmpty ? renderedPath : outFile.path,
      );
      if (!await rendered.exists() || await rendered.length() <= 44) {
        _showSmallNotice('Could not capture the mix.');
        return;
      }
      final targetRow = await _createCaptureTargetRow(name: 'Mix Capture');
      if (targetRow < 0) return;
      await _addAudioTrackFromProjectFile(
        projectAudioFile: rendered,
        label: 'Mix Capture',
        row: targetRow,
        timeMs: 0.0,
        gain: kDefaultGainUi,
        sourceTempoBpm: _tempo,
        stretchToProjectTempo: false,
        tempoStretchPreservePitch: false,
      );
      _scheduleProjectAutosave();
      _showSmallNotice('Captured mix to a new audio track.');
    } finally {
      if (mounted) setState(() => _captureDeckBusy = false);
    }
  }

  Future<void> _handleGlueClips(List<int> clipIndices) async {
    final valid =
        clipIndices
            .where((i) => i >= 0 && i < _audioTracks.length)
            .toSet()
            .toList()
          ..sort((a, b) {
            final aClip = _audioTracks[a];
            final bClip = _audioTracks[b];
            final rowCompare = aClip.rowIndex.compareTo(bClip.rowIndex);
            if (rowCompare != 0) return rowCompare;
            return aClip.offset.compareTo(bClip.offset);
          });
    if (valid.length < 2) return;

    final selectedClips = valid.map((i) => _audioTracks[i]).toList();
    final row = selectedClips.first.rowIndex;
    if (selectedClips.any((clip) => clip.rowIndex != row)) {
      _showSmallNotice('Glue clips on one row at a time.');
      return;
    }

    final selectionStartSec = selectedClips
        .map((clip) => clip.offset)
        .reduce(math.min);
    final selectionEndSec = selectedClips
        .map((clip) => clip.offset + _clipTimelineDurationSec(clip))
        .reduce(math.max);
    final durationSec = selectionEndSec - selectionStartSec;
    if (!durationSec.isFinite || durationSec <= 0.05) return;

    final audioDir = ProjectManager.audioDir(_projectDir);
    await audioDir.create(recursive: true);
    final outFile = File(
      p.join(
        audioDir.path,
        'glued_${DateTime.now().microsecondsSinceEpoch}.wav',
      ),
    );
    final selectedSet = valid.toSet();
    final snapshotJson = _buildGlueExportClipSnapshotJson(
      selectedIndices: selectedSet,
      selectionStartSec: selectionStartSec,
    );

    _showSmallNotice('Gluing selected clips...');
    final renderedPath = await JuceAudioEngine.exportMix(
      outFile.path,
      format: 'wav',
      sampleRate: 48000,
      wavBitDepth: 24,
      wavDithering: false,
      clipSnapshotJson: snapshotJson,
      dryClipRender: true,
    );
    final rendered = File(
      renderedPath.isNotEmpty ? renderedPath : outFile.path,
    );
    if (!await rendered.exists()) {
      _showSmallNotice('Could not glue these clips.');
      return;
    }
    final renderedBytes = await rendered.length();
    if (renderedBytes <= 44) {
      _showSmallNotice('Glue render was empty.');
      return;
    }

    final deleteActions = valid.reversed
        .map((index) => _buildDeleteClipAction(_audioTracks[index]))
        .toList(growable: false);
    final addAction = AddAudioTrackAction(
      addTrack:
          ({
            required File file,
            required int row,
            required double timeMs,
            Duration? trimStartRequested,
            Duration? trimEndRequested,
          }) => _addAudioTrackFromProjectFile(
            projectAudioFile: file,
            label: 'Glued Clip',
            row: row,
            timeMs: timeMs,
            trimStartRequested: trimStartRequested,
            trimEndRequested: trimEndRequested,
            gain: kDefaultGainUi,
            sourceTempoBpm: _tempo,
            stretchToProjectTempo: false,
            tempoStretchPreservePitch: false,
          ),
      tracks: _audioTracks,
      restoreTrack: _addClipFromUndoPayload,
      file: rendered,
      row: row,
      timeMs: selectionStartSec * 1000.0,
      trimStart: Duration.zero,
      trimEnd: Duration(milliseconds: (durationSec * 1000.0).round()),
      onRemove: _syncRemovedClipFadesAfterUndo,
    );

    await _undoManager.execute(
      CompoundUndoAction('Glue clips', <EditorUndoAction>[
        ...deleteActions,
        addAction,
      ]),
    );
    _updateOverallDurationIfNeeded();
    if (!mounted) return;
    setState(() {});
  }

  Future<void> _handleCutClipAt(int clipIndex, double cutTimeMs) async {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    final startMs = clip.offset * 1000.0;
    final timelineDurationMs = _clipTimelineDurationMs(clip);
    final endMs = startMs + timelineDurationMs;
    if (timelineDurationMs <= 1.0) return;
    if (cutTimeMs <= startMs + 1.0 || cutTimeMs >= endMs - 1.0) return;

    final rawSpanMs = (clip.trimEnd - clip.trimStart).inMilliseconds.toDouble();
    if (rawSpanMs <= 1.0) return;
    final ratio = ((cutTimeMs - startMs) / timelineDurationMs).clamp(0.0, 1.0);
    final cutTrimMs =
        clip.trimStart.inMilliseconds.toDouble() + rawSpanMs * ratio;
    final leftTrimEnd = Duration(milliseconds: cutTrimMs.round());
    final minTrimGap = const Duration(milliseconds: 50);
    if ((leftTrimEnd - clip.trimStart) < minTrimGap) return;
    if ((clip.trimEnd - leftTrimEnd) < minTrimGap) return;

    final oldTrimStart = clip.trimStart;
    final oldTrimEnd = clip.trimEnd;
    final oldOffset = clip.offset;
    final trimLeftAction = TrimClipAction(
      tracks: _audioTracks,
      originalIndex: clipIndex,
      oldTrimStart: oldTrimStart,
      oldTrimEnd: oldTrimEnd,
      oldOffset: oldOffset,
      newTrimStart: oldTrimStart,
      newTrimEnd: leftTrimEnd,
      newOffset: null,
      onChange: () {
        unawaited(_syncClipTimingToEngine(clipIndex));
        _updateOverallDurationIfNeeded(changedClips: <AudioTrack>[clip]);
      },
    );
    final pasteRightAction = _buildPasteAction(
      clip: clip,
      row: clip.rowIndex,
      timeMs: cutTimeMs,
      trimStart: leftTrimEnd,
      trimEnd: oldTrimEnd,
    );
    await _undoManager.execute(
      CompoundUndoAction('Cut clip', <EditorUndoAction>[
        trimLeftAction,
        pasteRightAction,
      ]),
    );
  }

  Future<bool> _handlePasteClipAt(int row, double timeMs) {
    return _enqueueClipPaste(() async {
      final beforeCount = _audioTracks.length;
      final safePasteTimeMs = math.max(0.0, timeMs);
      if (!_canPasteCopiedClipAtRow(row)) {
        _showSmallNotice('Copied clip does not match this lane.');
        return false;
      }
      final group = _copiedClipGroup;
      if (group != null && group.isNotEmpty) {
        if (_audioTracks.length + group.length > kNumClips) {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
                ),
              ),
            );
          }
          return false;
        }
        final actions = <EditorUndoAction>[];
        for (final entry in group) {
          final targetRow = row + entry.rowDelta;
          final targetTime = math.max(
            0.0,
            safePasteTimeMs + entry.offsetDeltaMs,
          );
          actions.add(
            _buildPasteAction(
              clip: entry.clip,
              row: targetRow,
              timeMs: targetTime,
              trimStart: entry.trimStart,
              trimEnd: entry.trimEnd,
            ),
          );
        }
        if (actions.isNotEmpty) {
          await _undoManager.execute(
            CompoundUndoAction('Paste clips', actions),
          );
        }
        final changed = _audioTracks.length > beforeCount;
        if (changed) {
          _focusInsertedClipsAfterPaste(
            _audioTracks.sublist(beforeCount).toList(growable: false),
          );
        }
        return changed;
      }

      if (_copiedClip == null) return false;
      if (_audioTracks.length >= kNumClips) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
              ),
            ),
          );
        }
        return false;
      }

      await _undoManager.execute(
        _buildPasteAction(
          clip: _copiedClip!,
          row: row,
          timeMs: safePasteTimeMs,
          trimStart: _copiedTrimStart,
          trimEnd: _copiedTrimEnd,
        ),
      );
      final changed = _audioTracks.length > beforeCount;
      if (changed) {
        _focusInsertedClipsAfterPaste(
          _audioTracks.sublist(beforeCount).toList(growable: false),
        );
      }
      return changed;
    });
  }

  Future<bool> _handleStepDuplicateClips(
    List<int> clipIndices,
    double pasteStartMs,
  ) {
    return _enqueueClipPaste(() async {
      final valid = clipIndices
          .where((i) => i >= 0 && i < _audioTracks.length)
          .toSet()
          .toList();
      if (valid.isEmpty) return false;

      valid.sort((a, b) {
        final startCompare = _audioTracks[a].offset.compareTo(
          _audioTracks[b].offset,
        );
        if (startCompare != 0) return startCompare;
        final rowCompare = _audioTracks[a].rowIndex.compareTo(
          _audioTracks[b].rowIndex,
        );
        if (rowCompare != 0) return rowCompare;
        return a.compareTo(b);
      });

      if (_audioTracks.length + valid.length > kNumClips) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                "Max number of audio clips reached ($kNumClips). Unable to add more clips.",
              ),
            ),
          );
        }
        return false;
      }

      final anchorStartMs = _audioTracks[valid.first].offset * 1000.0;
      final safePasteStartMs = math.max(0.0, pasteStartMs);
      final actions = <EditorUndoAction>[];
      for (final index in valid) {
        final clip = _audioTracks[index];
        if (!_rowAllowsClipKind(clip.rowIndex, clip.clipKind)) {
          return false;
        }
        actions.add(
          _buildPasteAction(
            clip: clip,
            row: clip.rowIndex,
            timeMs: math.max(
              0.0,
              safePasteStartMs + ((clip.offset * 1000.0) - anchorStartMs),
            ),
            trimStart: clip.trimStart,
            trimEnd: clip.trimEnd,
          ),
        );
      }

      if (actions.isEmpty) return false;
      final beforeCount = _audioTracks.length;
      if (actions.length == 1) {
        await _undoManager.execute(actions.first);
      } else {
        await _undoManager.execute(
          CompoundUndoAction('Step duplicate clips', actions),
        );
      }

      final changed = _audioTracks.length > beforeCount;
      if (changed) {
        _focusInsertedClipsAfterPaste(
          _audioTracks.sublist(beforeCount).toList(growable: false),
        );
      }
      return changed;
    });
  }

  int _clipIndexForEngineId(int engineClipId) {
    if (engineClipId < 0) return -1;
    return _audioTracks.indexWhere((t) => t.engineClipId == engineClipId);
  }

  List<MidiNote> _cloneMidiNotesForNewClip(List<MidiNote> notes) {
    return notes
        .map(
          (note) => MidiNote(
            id: 'midi_${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}',
            pitch: note.pitch,
            startBeat: note.startBeat,
            lengthBeats: note.lengthBeats,
            velocity: note.velocity,
          ),
        )
        .toList(growable: false);
  }

  void _focusInsertedClipsAfterPaste(List<AudioTrack> insertedTracks) {
    if (insertedTracks.isEmpty || !mounted) return;

    final insertedIndices = insertedTracks
        .map((track) {
          if (track.engineClipId >= 0) {
            return _clipIndexForEngineId(track.engineClipId);
          }
          return _audioTracks.indexOf(track);
        })
        .where((index) => index >= 0 && index < _audioTracks.length)
        .toList(growable: false);
    if (insertedIndices.isEmpty) return;

    var primaryIndex = insertedIndices.last;
    for (int i = insertedIndices.length - 1; i >= 0; i--) {
      final candidate = _audioTracks[insertedIndices[i]];
      if (candidate.isMidi) {
        primaryIndex = insertedIndices[i];
        break;
      }
    }

    final primaryClip = _audioTracks[primaryIndex];
    setState(() {
      _timelineSelectedClipIndices = insertedIndices;
      _timelinePrimarySelectedClipIndex = primaryIndex;
      if (_rowCount > 0) {
        _selectedRow = primaryClip.rowIndex.clamp(0, _rowCount - 1).toInt();
      }
      if (primaryClip.isMidi && primaryClip.engineClipId >= 0) {
        _activeMidiClipEngineId = primaryClip.engineClipId;
        _activeMidiClipIndex = primaryIndex;
      }
    });

    if (_showPianoRoll) {
      _retargetOpenMidiClipEditorToSelection(primaryIndex);
    }
    if (_showPitchLab) {
      _retargetOpenPitchLabEditorToSelection(primaryIndex);
    }
    if (_liveMidiEventPlaybackSupported && !_isMidiClipRecording) {
      unawaited(_syncLiveMidiInputTargetClip());
    }
  }

  void _retargetOpenMidiClipEditorToSelection(int clipIndex) {
    if (!_showPianoRoll || _isMidiClipRecording) return;
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return;
    if (_activeMidiClipIndex == clipIndex &&
        _activeMidiClipEngineId == clip.engineClipId) {
      return;
    }
    setState(() {
      if (_rowCount > 0) {
        _selectedRow = clip.rowIndex.clamp(0, _rowCount - 1).toInt();
      }
      _activeMidiClipEngineId = clip.engineClipId;
      _activeMidiClipIndex = clipIndex;
    });
  }

  void _openMidiClipEditor(int clipIndex) {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return;
    setState(() {
      if (_rowCount > 0) {
        _selectedRow = clip.rowIndex.clamp(0, _rowCount - 1).toInt();
      }
      _activeMidiClipEngineId = clip.engineClipId;
      _activeMidiClipIndex = clipIndex;
      _showPianoRoll = true;
    });
    _setDawPanelVisible('piano_roll', true);
    _syncMeterPollingForVisibility();
    if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
      // Prime the output route before the first audition. Processor readiness
      // remains in the awaited key-preview path, avoiding concurrent reloads.
      unawaited(_prepareLiveMidiPreviewRoute());
      unawaited(_syncLiveMidiInputTargetClip());
    }
  }

  void _closeMidiClipEditor() {
    _closingPianoRollPreview = true;
    final desktopRelease = _releaseAllDesktopMidiNotes();
    final pianoRollRelease = _releaseAllPianoRollPreviewNotes();
    setState(() {
      _showPianoRoll = false;
      _pianoRollFullscreen = false;
      _activeMidiClipEngineId = null;
      _activeMidiClipIndex = null;
    });
    _setDawPanelVisible('piano_roll', false);
    _syncMeterPollingForVisibility();
    unawaited(() async {
      try {
        await Future.wait(<Future<void>>[desktopRelease, pianoRollRelease]);
        if (_liveMidiEventPlaybackSupported && !_isMidiClipRecording) {
          await _syncLiveMidiInputTargetClip();
        }
      } finally {
        _closingPianoRollPreview = false;
      }
    }());
  }

  void _openPitchLabEditor(int clipIndex) {
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (!clip.isMidi) return;
    unawaited(_stopPitchLabAudioPreview(deleteFile: true));
    setState(() {
      if (_rowCount > 0) {
        _selectedRow = clip.rowIndex.clamp(0, _rowCount - 1).toInt();
      }
      _activePitchLabClipEngineId = clip.engineClipId;
      _activePitchLabClipIndex = clipIndex;
      _activeMidiClipEngineId = clip.engineClipId;
      _activeMidiClipIndex = clipIndex;
      _pitchLabAudioMode = false;
      _activePitchLabSourceAudioEngineId = null;
      _activePitchLabSourceAudioIndex = null;
      _pitchLabAudioOriginalNotes = <MidiNote>[];
      _pitchLabAudioDraftNotes = <MidiNote>[];
      _pitchLabAudioAnalyzing = false;
      _pitchLabAudioRendering = false;
      _pitchLabAudioPreviewRendering = false;
      _pitchLabAudioPreviewFile = null;
      _showPitchLab = true;
      _showPianoRoll = false;
      _pianoRollFullscreen = false;
    });
    _setDawPanelVisible('pitch_lab', true);
    _setDawPanelVisible('piano_roll', false);
    _syncMeterPollingForVisibility();
    if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
      unawaited(_syncLiveMidiInputTargetClip());
    }
  }

  void _closePitchLabEditor() {
    unawaited(_releaseAllDesktopMidiNotes());
    unawaited(_stopPitchLabAudioPreview(deleteFile: true));
    setState(() {
      _showPitchLab = false;
      _pitchLabFullscreen = false;
      _activePitchLabClipEngineId = null;
      _activePitchLabClipIndex = null;
      _pitchLabAudioMode = false;
      _activePitchLabSourceAudioEngineId = null;
      _activePitchLabSourceAudioIndex = null;
      _pitchLabAudioOriginalNotes = <MidiNote>[];
      _pitchLabAudioDraftNotes = <MidiNote>[];
      _pitchLabAudioAnalyzing = false;
      _pitchLabAudioRendering = false;
      _pitchLabAudioPreviewRendering = false;
      _pitchLabAudioPreviewFile = null;
    });
    _setDawPanelVisible('pitch_lab', false);
    _syncMeterPollingForVisibility();
    if (_liveMidiEventPlaybackSupported && !_isMidiClipRecording) {
      unawaited(_syncLiveMidiInputTargetClip());
    }
  }

  void _retargetOpenPitchLabEditorToSelection(int clipIndex) {
    if (!_showPitchLab || _isMidiClipRecording) return;
    if (clipIndex < 0 || clipIndex >= _audioTracks.length) return;
    final clip = _audioTracks[clipIndex];
    if (_pitchLabAudioMode) {
      if (clip.isMidi) return;
      if (_activePitchLabSourceAudioIndex == clipIndex &&
          _activePitchLabSourceAudioEngineId == clip.engineClipId) {
        return;
      }
      unawaited(_openAudioPitchLabForClip(clipIndex));
      return;
    }
    if (!clip.isMidi) return;
    if (_activePitchLabClipIndex == clipIndex &&
        _activePitchLabClipEngineId == clip.engineClipId) {
      return;
    }
    setState(() {
      if (_rowCount > 0) {
        _selectedRow = clip.rowIndex.clamp(0, _rowCount - 1).toInt();
      }
      _activePitchLabClipEngineId = clip.engineClipId;
      _activePitchLabClipIndex = clipIndex;
      _activeMidiClipEngineId = clip.engineClipId;
      _activeMidiClipIndex = clipIndex;
    });
  }

  Future<void> _commitMidiClipFromPitchLab({
    required List<MidiNote> notes,
    required Map<String, double> instrumentParams,
    required String instrumentId,
    required String instrumentName,
  }) async {
    if (_activePitchLabClipEngineId == null) return;
    _activeMidiClipEngineId = _activePitchLabClipEngineId;
    _activeMidiClipIndex = _activePitchLabClipIndex;
    await _commitMidiClipFromPianoRoll(
      notes: notes,
      instrumentParams: instrumentParams,
      instrumentId: instrumentId,
      instrumentName: instrumentName,
    );
  }

  Future<bool> _prepareLiveMidiPreviewRoute() async {
    if (!_liveMidiEventPlaybackSupported) return false;
    if (kIsWeb) return true;
    if (!midiPreviewNeedsPlaybackReadiness(
      defaultTargetPlatform,
      isBluetoothV2Session: _isBluetoothV2Session,
    )) {
      return true;
    }
    final pending = _liveMidiPreviewRoutePrepareFuture;
    if (pending != null) return await pending;

    final next = _ensurePlaybackRouteReady(reason: 'midiPreview');
    _liveMidiPreviewRoutePrepareFuture = next;
    try {
      return await next;
    } finally {
      if (identical(_liveMidiPreviewRoutePrepareFuture, next)) {
        _liveMidiPreviewRoutePrepareFuture = null;
      }
    }
  }

  Future<bool> _ensureLiveMidiClipReadyForPreview(AudioTrack clip) async {
    if (!_liveMidiEventPlaybackSupported || !clip.isMidi) return false;
    if (clip.engineClipId < 0) return false;

    final pending = _midiClipEngineRefreshChains[clip.engineClipId];
    if (pending != null) {
      try {
        await pending;
      } catch (_) {}
    }
    if (!mounted || !_audioTracks.contains(clip)) return false;
    if (!clip.isMidi || clip.engineClipId < 0) return false;

    return ensureMidiPreviewReady(
      prepareRoute: _prepareLiveMidiPreviewRoute,
      updateProcessor: () => _updateMidiClipEventsLive(clip),
      reloadProcessor: () => _reloadMidiTrackLive(clip),
      assignLiveTarget: () => _setLiveMidiInputTargetClipIfNeeded(
        clip.engineClipId,
        clearPendingEvents: false,
        force: true,
      ),
      isStillValid: () => mounted && _audioTracks.contains(clip),
    );
  }

  Future<bool> _playPianoRollPreviewForClip(
    AudioTrack clip,
    int pitch,
    double velocity,
  ) async {
    if (!await _ensureLiveMidiClipReadyForPreview(clip)) return false;
    final safePitch = pitch.clamp(0, 127);
    final safeVelocity = velocity.clamp(0.0, 1.0);
    final played = await JuceAudioEngine.playPreviewMidiNote(
      clip.engineClipId,
      pitch: safePitch,
      velocity: safeVelocity,
      durationMs: 220,
    );
    if (played) return true;

    if (!await _reloadMidiTrackLive(clip) ||
        !mounted ||
        !_audioTracks.contains(clip)) {
      return false;
    }
    final targetReady = await _setLiveMidiInputTargetClipIfNeeded(
      clip.engineClipId,
      clearPendingEvents: false,
      force: true,
    );
    if (!targetReady) return false;
    return JuceAudioEngine.playPreviewMidiNote(
      clip.engineClipId,
      pitch: safePitch,
      velocity: safeVelocity,
      durationMs: 220,
    );
  }

  Future<void> _previewPianoRollNote(int pitch, double velocity) async {
    if (_activeMidiClipEngineId == null) return;
    final idx = _clipIndexForEngineId(_activeMidiClipEngineId!);
    if (idx < 0 || idx >= _audioTracks.length) return;
    final clip = _audioTracks[idx];
    if (!clip.isMidi) return;
    if (_isMidiClipRecording) {
      return;
    }

    if (_liveMidiEventPlaybackSupported && clip.engineClipId >= 0) {
      await _playPianoRollPreviewForClip(clip, pitch, velocity);
    }
  }

  bool _midiNotesEqual(List<MidiNote> a, List<MidiNote> b) {
    if (identical(a, b)) return true;
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      final x = a[i];
      final y = b[i];
      if (x.pitch != y.pitch) return false;
      if ((x.startBeat - y.startBeat).abs() > 0.00001) return false;
      if ((x.lengthBeats - y.lengthBeats).abs() > 0.00001) return false;
      if ((x.velocity - y.velocity).abs() > 0.00001) return false;
    }
    return true;
  }

  bool _doubleMapsEqual(Map<String, double> a, Map<String, double> b) {
    if (a.length != b.length) return false;
    for (final e in a.entries) {
      final v = b[e.key];
      if (v == null) return false;
      if ((e.value - v).abs() > 0.00001) return false;
    }
    return true;
  }

  Future<void> _commitMidiClipFromPianoRoll({
    required List<MidiNote> notes,
    required Map<String, double> instrumentParams,
    required String instrumentId,
    required String instrumentName,
  }) async {
    if (_activeMidiClipEngineId == null) return;
    final index = _clipIndexForEngineId(_activeMidiClipEngineId!);
    if (index < 0 || index >= _audioTracks.length) return;
    final clip = _audioTracks[index];
    if (!clip.isMidi) return;
    if (_isMidiClipRecording) {
      return;
    }

    final oldNotes = clip.midiNotes.map((n) => n.copy()).toList();
    final newNotes = notes.map((n) => n.copy()).toList();
    final oldParams = Map<String, double>.from(clip.instrumentParams);
    final newParams = Map<String, double>.from(instrumentParams);
    final oldInstrumentId = clip.instrumentId;
    final oldInstrumentName = clip.instrumentName;
    final oldHostedInstrumentStateBase64 = clip.hostedInstrumentStateBase64;
    final oldTrimEnd = clip.trimEnd;
    final oldAudioDuration = clip.audioDuration;
    final newTrimEnd = _midiTrimEndIncludingNotes(clip, newNotes);
    final newHostedInstrumentStateBase64 = _nextHostedInstrumentStateForEdit(
      clip,
      instrumentId: instrumentId,
      currentStateBase64: oldHostedInstrumentStateBase64,
    );

    final notesChanged = !_midiNotesEqual(oldNotes, newNotes);
    final paramsChanged = !_doubleMapsEqual(oldParams, newParams);
    final instrumentChanged =
        oldInstrumentId != instrumentId || oldInstrumentName != instrumentName;
    if (!notesChanged && !paramsChanged && !instrumentChanged) {
      return;
    }

    await _undoManager.execute(
      EditMidiClipAction(
        tracks: _audioTracks,
        originalIndex: index,
        oldNotes: oldNotes,
        newNotes: newNotes,
        oldInstrumentId: oldInstrumentId,
        oldInstrumentName: oldInstrumentName,
        oldInstrumentParams: oldParams,
        oldHostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
        newInstrumentId: instrumentId,
        newInstrumentName: instrumentName,
        newInstrumentParams: newParams,
        newHostedInstrumentStateBase64: newHostedInstrumentStateBase64,
        applyToClip:
            (
              target,
              notesToApply,
              nextInstrumentId,
              nextInstrumentName,
              nextParams,
              hostedInstrumentStateBase64,
            ) {
              final applyingRedo =
                  nextInstrumentId == instrumentId &&
                  nextInstrumentName == instrumentName &&
                  _midiNotesEqual(notesToApply, newNotes);
              final applyingInstrumentChange =
                  target.instrumentId != nextInstrumentId ||
                  target.instrumentName != nextInstrumentName ||
                  !_doubleMapsEqual(target.instrumentParams, nextParams);
              _applyMidiClipStateLocally(
                target,
                notes: notesToApply,
                instrumentId: nextInstrumentId,
                instrumentName: nextInstrumentName,
                instrumentParams: nextParams,
              );
              if (applyingRedo) {
                _setMidiClipSourceEnd(target, newTrimEnd);
              } else {
                target.trimEnd = oldTrimEnd;
                target.audioDuration = oldAudioDuration;
              }
              _updateOverallDurationIfNeeded(
                changedClips: <AudioTrack>[target],
              );
              target.hostedInstrumentStateBase64 = hostedInstrumentStateBase64
                  .trim();
              Future<void> refresh;
              if (applyingInstrumentChange) {
                refresh = _refreshMidiClipEngineNow(
                  target,
                  failureNotice:
                      'Could not switch instrument for this MIDI clip.',
                ).then<void>((_) {});
              } else {
                _scheduleMidiClipEngineRefresh(target);
                refresh = Future<void>.value();
              }
              if (mounted) {
                setState(() {});
              }
              return refresh;
            },
      ),
    );
  }

  Future<void> _recomputeAudibleState() async {
    final soloActive = _rowSoloed.any((s) => s);
    final futures = <Future<void>>[];

    for (int row = 0; row < _rowCount; row++) {
      bool shouldMute;

      if (soloActive) {
        // SOLO MODE: mute everything that is NOT soloed
        shouldMute = !_rowSoloed[row];
      } else {
        // NORMAL MODE: respect mute buttons
        shouldMute = _rowMuted[row];
      }

      if (row < _rowMuteApplied.length && _rowMuteApplied[row] == shouldMute) {
        continue;
      }
      if (row < _rowMuteApplied.length) {
        _rowMuteApplied[row] = shouldMute;
      }
      futures.add(JuceAudioEngine.muteRow(row, shouldMute));
    }

    if (futures.isNotEmpty) {
      await Future.wait(futures);
    }
  }

  Future<_RowLayoutSnapshot> _captureRowLayoutSnapshot() async {
    final rows = _rows.map(_cloneTimelineRow).toList();
    final trackGroups = _trackGroups.map(_cloneTrackGroup).toList();
    return _RowLayoutSnapshot(rows: rows, trackGroups: trackGroups);
  }

  Future<void> _applyRowLayoutSnapshot(_RowLayoutSnapshot snap) async {
    var targetCount = snap.rows.length;
    if (targetCount <= 0) targetCount = 1;

    final currentIds = _rows.map((r) => r.rowId).toList();

    while (currentIds.length < targetCount) {
      final next = currentIds.length + 1;
      final id = await JuceAudioEngine.addRow('Track $next', iconId: 0);
      if (id < 0) break;
      currentIds.add(id);
    }

    while (currentIds.length > targetCount && currentIds.length > 1) {
      final rowId = currentIds.removeLast();
      final ok = await JuceAudioEngine.removeRow(rowId);
      if (!ok) break;
    }

    // Reorder JUCE rows to match snapshot row identity (moves FX/meters with rows).
    final reorderCount = math.min(currentIds.length, snap.rows.length);
    for (int i = 0; i < reorderCount; i++) {
      final desiredId = snap.rows[i].rowId;
      final from = currentIds.indexOf(desiredId);
      if (from < 0 || from == i) continue;
      final ok = await JuceAudioEngine.moveRowOrder(from, i);
      if (!ok) continue;
      final moved = currentIds.removeAt(from);
      currentIds.insert(i, moved);
    }

    final applyCount = math.min(snap.rows.length, currentIds.length);
    for (int i = 0; i < applyCount; i++) {
      final rowId = currentIds[i];
      if (rowId < 0) continue;
      final row = snap.rows[i];
      await JuceAudioEngine.renameRow(rowId, row.name);
      await JuceAudioEngine.setRowIcon(rowId, row.iconId);
    }

    await _reloadRowsFromEngine(refreshAutomationTargets: false);
    final restoredRows = <TimelineRow>[];
    for (int i = 0; i < _rowCount; i++) {
      final snapRow = i < snap.rows.length ? snap.rows[i] : null;
      final current = _rows[i];
      restoredRows.add(
        snapRow == null
            ? current
            : snapRow.copyWith(
                rowId: current.rowId,
                name: snapRow.name,
                iconId: snapRow.iconId,
              ),
      );
    }
    _trackGroups
      ..clear()
      ..addAll(snap.trackGroups.map(_cloneTrackGroup));
    await _applyRowsToEditorState(
      restoredRows,
      refreshAutomationTargets: false,
      syncClipRows: false,
    );

    await _recomputeAudibleState();
    _updateOverallDurationIfNeeded();
    _refreshAudioEditorView();
  }

  Future<void> _runRowLayoutActionWithUndo({
    required String description,
    required Future<bool> Function() perform,
  }) async {
    final before = await _captureRowLayoutSnapshot();
    final changed = await perform();
    if (!changed) return;
    final after = await _captureRowLayoutSnapshot();
    await _undoManager.addWithoutExecute(
      _RowLayoutSnapshotAction(
        descriptionText: description,
        before: before,
        after: after,
        applySnapshot: _applyRowLayoutSnapshot,
      ),
    );
  }

  Future<bool> _addRowImpl({int? preferredRowId}) async {
    if (_rowCount >= _effectiveMaxRows) return false;
    final nextIndex = _rowCount + 1;
    final rowId = await JuceAudioEngine.addRow(
      'Track $nextIndex',
      iconId: 0,
      preferredRowId: preferredRowId,
    );
    if (rowId >= 0) {
      await _applyRowsToEditorState(
        <TimelineRow>[
          ..._rows,
          TimelineRow(rowId: rowId, name: 'Track $nextIndex', iconId: 0),
        ],
        refreshAutomationTargets: false,
        syncClipRows: false,
      );
      if (_rowSoloed.any((s) => s)) {
        final idx = _rowIndexForId(rowId);
        if (idx >= 0) {
          _rowMuteApplied[idx] = true;
          await JuceAudioEngine.muteRow(idx, true);
        }
      }
      return true;
    }
    return false;
  }

  Future<void> _addRow() async {
    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return;
    }
    await _runRowLayoutActionWithUndo(
      description: 'Add row',
      perform: _addRowImpl,
    );
  }

  Future<bool> _addInstrumentLaneImpl(
    TimelineRow instrumentRow, {
    int? preferredRowId,
  }) async {
    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return false;
    }
    final rowId = await JuceAudioEngine.addRow(
      instrumentRow.name,
      iconId: instrumentRow.iconId,
      preferredRowId: preferredRowId,
    );
    if (rowId < 0) return false;
    await _applyRowsToEditorState(
      <TimelineRow>[..._rows, instrumentRow.copyWith(rowId: rowId)],
      refreshAutomationTargets: false,
      syncClipRows: false,
    );
    return true;
  }

  Future<bool> _insertInstrumentLaneImpl(
    int row,
    TimelineRow instrumentRow, {
    required bool above,
    int? preferredRowId,
  }) async {
    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return false;
    }
    if (row < 0 || row >= _rowCount) return false;
    final refRowId = _rowIdAt(row);
    final rowId = above
        ? await JuceAudioEngine.insertRowAbove(
            refRowId,
            instrumentRow.name,
            iconId: instrumentRow.iconId,
            preferredRowId: preferredRowId,
          )
        : await JuceAudioEngine.insertRowBelow(
            refRowId,
            instrumentRow.name,
            iconId: instrumentRow.iconId,
            preferredRowId: preferredRowId,
          );
    if (rowId < 0) return false;
    final nextRows = List<TimelineRow>.from(_rows)
      ..insert(above ? row : row + 1, instrumentRow.copyWith(rowId: rowId));
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: false,
      syncClipRows: true,
    );
    return true;
  }

  Future<bool> _insertRowAboveImpl(int row, {int? preferredRowId}) async {
    if (_rowCount >= _effectiveMaxRows) return false;
    if (row < 0 || row >= _rowCount) return false;
    final refRowId = _rowIdAt(row);
    final rowId = await JuceAudioEngine.insertRowAbove(
      refRowId,
      'Track ${_rowCount + 1}',
      iconId: 0,
      preferredRowId: preferredRowId,
    );
    if (rowId < 0) return false;
    final nextRows = List<TimelineRow>.from(_rows)
      ..insert(
        row,
        TimelineRow(rowId: rowId, name: 'Track ${_rowCount + 1}', iconId: 0),
      );
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: false,
      syncClipRows: true,
    );
    if (_rowSoloed.any((s) => s)) {
      final idx = _rowIndexForId(rowId);
      if (idx >= 0) {
        _rowMuteApplied[idx] = true;
        await JuceAudioEngine.muteRow(idx, true);
      }
    }
    return true;
  }

  Future<void> _insertRowAbove(int row) async {
    if (_rowCount >= _effectiveMaxRows) {
      _showRowLimitReachedNotice();
      return;
    }
    await _runRowLayoutActionWithUndo(
      description: 'Insert row above',
      perform: () => _insertRowAboveImpl(row),
    );
  }

  Future<bool> _insertRowBelowImpl(int row, {int? preferredRowId}) async {
