  void _showSmallNotice(String message) {
    if (!mounted) return;
    _insertAssistantActionNoticeSystemText(message);
    final localizedMessage = _localizedNoticeMessage(message);
    final messenger = ScaffoldMessenger.of(context);
    messenger.hideCurrentSnackBar();
    messenger.showSnackBar(
      SnackBar(
        behavior: SnackBarBehavior.floating,
        duration: const Duration(seconds: 2),
        backgroundColor: Colors.transparent,
        elevation: 0,
        padding: EdgeInsets.zero,
        showCloseIcon: false,
        content: ClipRRect(
          borderRadius: BorderRadius.circular(16),
          child: BackdropFilter(
            filter: ImageFilter.blur(sigmaX: 80, sigmaY: 80),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
              decoration: BoxDecoration(
                color: const Color.fromRGBO(70, 80, 95, 0.97),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: Colors.white.withValues(alpha: 0.14)),
              ),
              child: Text(
                localizedMessage,
                style: const TextStyle(
                  fontFamily: 'Pretendard',
                  fontSize: 13.5,
                  fontWeight: FontWeight.w500,
                  height: 1.2,
                  color: Color(0xFFF4F4F4),
                  letterSpacing: -0.05,
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  String _localizedNoticeMessage(String message) {
    final exact = L10n.translate(context, message);
    if (exact != message) return exact;

    final projectTempoMatch = RegExp(
      r'^Project tempo set to ([0-9]+) BPM\.$',
    ).firstMatch(message);
    if (projectTempoMatch != null) {
      return '${L10n.translate(context, 'Project tempo set to')} ${projectTempoMatch.group(1)} BPM.';
    }

    final sidechainMatch = RegExp(
      r'^Created ([0-9]+) kick-synced sidechain clips\.$',
    ).firstMatch(message);
    if (sidechainMatch != null) {
      return '${L10n.translate(context, 'Created')} ${sidechainMatch.group(1)} ${L10n.translate(context, 'kick-synced sidechain clips.')}';
    }

    final stemsMatch = RegExp(
      r'^Created stems for ([0-9]+) clips\.$',
    ).firstMatch(message);
    if (stemsMatch != null) {
      return '${L10n.translate(context, 'Created stems for')} ${stemsMatch.group(1)} ${L10n.translate(context, 'clips.')}';
    }

    final shiftedMidiMatch = RegExp(
      r'^Shifted MIDI notes (up|down) by (.+)\.$',
    ).firstMatch(message);
    if (shiftedMidiMatch != null) {
      return '${L10n.translate(context, 'Shifted MIDI notes')} ${L10n.translate(context, shiftedMidiMatch.group(1)!)} ${L10n.translate(context, 'by')} ${shiftedMidiMatch.group(2)}.';
    }

    final extendedMidiMatch = RegExp(
      r'^Extended MIDI clip to (.+)\.$',
    ).firstMatch(message);
    if (extendedMidiMatch != null) {
      return '${L10n.translate(context, 'Extended MIDI clip to')} ${extendedMidiMatch.group(1)}.';
    }

    return message;
  }

  Future<void> _clearRowContent(int row) async {
    if (row < 0 || row >= _rowCount) return;
    final rowId = _rowIdAt(row);

    final removedEngineClipIds = <int>[];
    final removedClips = <AudioTrack>[];
    // Remove clips on this row (descending so indices stay valid for removal).
    for (int i = _audioTracks.length - 1; i >= 0; i--) {
      final clip = _audioTracks[i];
      final matchesRowId = rowId >= 0 && clip.rowId == rowId;
      final matchesRowIndex = clip.rowIndex == row;
      if (matchesRowId || matchesRowIndex) {
        clip.audioStartTimer?.cancel();
        _audioTracks.removeAt(i);
        removedClips.add(clip);
        if (clip.engineClipId >= 0) {
          removedEngineClipIds.add(clip.engineClipId);
          _clipFadeRowIdByEngineId.remove(clip.engineClipId);
        }
      }
    }
    await JuceAudioEngine.unloadClips(removedEngineClipIds);
    _updateOverallDurationIfNeeded(removedClips: removedClips);

    // Clear row FX chain.
    final fx = await JuceAudioEngine.getTrackEffectsForRow(row);
    for (int i = fx.length - 1; i >= 0; i--) {
      await JuceAudioEngine.removeTrackEffect(row, i);
    }

    // Reset row controls.
    _rowMuted[row] = false;
    _rowSoloed[row] = false;
    _rowGain[row] = _kGainUiUnity;
    _rowPan[row] = 0.5;
    _rowVolumeAutomation[row] = [AutomationPoint(x: 0.0, volume: 0.75)];
    _rowPluginAutomation[row] = <String, List<AutomationPoint>>{};
    _rowAutomationClips[row] = <String, List<AutomationClipSnapshot>>{};
    _rowSelectedAutomationTarget[row] = 'volume';

    await JuceAudioEngine.setRowGain(row, _kGainUiUnity);
    await JuceAudioEngine.setRowPan(row, 0.5);
    await _syncNativeAutomationForRow(row);
    await _recomputeAudibleState();
  }

  _DeletedRowUiState _captureDeletedRowUiState(int row) {
    return _DeletedRowUiState(
      muted: row < _rowMuted.length ? _rowMuted[row] : false,
      soloed: row < _rowSoloed.length ? _rowSoloed[row] : false,
      muteApplied: row < _rowMuteApplied.length ? _rowMuteApplied[row] : null,
      expanded: row < _rowExpanded.length ? _rowExpanded[row] : false,
      expandedTab: row < _rowExpandedTab.length ? _rowExpandedTab[row] : 0,
      gainSnapshot: row < _rowGainSnapshot.length
          ? _rowGainSnapshot[row]
          : _kGainUiUnity,
      panSnapshot: row < _rowPanSnapshot.length ? _rowPanSnapshot[row] : 0.5,
      automationSnapshot: row < _rowAutomationSnapshot.length
          ? _rowAutomationSnapshot[row]
                .map((point) => point.copy())
                .toList(growable: false)
          : const <AutomationPoint>[],
      peakHoldDb: _rowPeakHoldDb[row],
      peakHoldLastUpdate: _rowPeakHoldLastUpdate[row],
      peakHoldFreezeUntil: _rowPeakHoldFreezeUntil[row],
    );
  }

  Future<_DeletedRowSnapshot?> _captureDeletedRowSnapshot(int row) async {
    if (row < 0 || row >= _rowCount) return null;
    final rowInfo = _rows[row];
    final rowId = rowInfo.rowId;
    final deletedClips = rowId >= 0
        ? _clipsForFadeResolution(rowIds: <int>{rowId}).toList(growable: false)
        : _audioTracks
              .where((clip) => clip.rowIndex == row)
              .toList(growable: false);

    final containsActiveMidiClip =
        _activeMidiClipEngineId != null &&
        deletedClips.any(
          (clip) => clip.engineClipId == _activeMidiClipEngineId,
        );
    final previousSelectedRowId = _isValidRowIndex(_selectedRow)
        ? _rowIdAt(_selectedRow)
        : null;
    final nextSelectedRowId = previousSelectedRowId == rowId
        ? (row + 1 < _rowCount
              ? _rowIdAt(row + 1)
              : row > 0
              ? _rowIdAt(row - 1)
              : null)
        : previousSelectedRowId;

    return _DeletedRowSnapshot(
      originalIndex: row,
      row: _cloneTimelineRow(rowInfo),
      wasOnlyRow: _rowCount <= 1,
      uiState: _captureDeletedRowUiState(row),
      rowState: RowStateSnapshot(
        row: row,
        rowId: rowId,
        gain: row < _rowGain.length ? _rowGain[row] : _kGainUiUnity,
        pan: row < _rowPan.length ? _rowPan[row] : 0.5,
        volumeAutomation: row < _rowVolumeAutomation.length
            ? _rowVolumeAutomation[row]
                  .map((point) => point.copy())
                  .toList(growable: false)
            : <AutomationPoint>[AutomationPoint(x: 0.0, volume: 0.75)],
        automationLanes: _automationLanesForRowSave(row),
        automationClips: _automationClipsForRowSave(row),
        selectedAutomationTargetId: row < _rowSelectedAutomationTarget.length
            ? _rowSelectedAutomationTarget[row]
            : 'volume',
      ),
      rowEffects: await captureRowSnapshot(row, rowId: rowId),
      clips: deletedClips,
      closesMidiEditor: containsActiveMidiClip,
      previousSelectedRowId: previousSelectedRowId,
      nextSelectedRowId: nextSelectedRowId,
      trackGroups: _trackGroups.map(_cloneTrackGroup).toList(growable: false),
    );
  }

  Future<void> _restoreDeletedRowClips(int row, List<AudioTrack> clips) async {
    for (final clip in clips) {
      if (clip.isMidi) {
        await _addMidiTrack(
          instrumentId: clip.instrumentId,
          instrumentName: clip.instrumentName,
          instrumentParams: Map<String, double>.from(clip.instrumentParams),
          midiNotes: clip.midiNotes.map((note) => note.copy()).toList(),
          row: row,
          timeMs: clip.offset * 1000.0,
          trimStartRequested: clip.trimStart,
          trimEndRequested: clip.trimEnd,
          renderedFile: clip.file,
          label: clip.label,
          gain: clip.gain,
          pitchSemitones: clip.pitchSemitones,
          sourceTempoBpm: clip.sourceTempoBpm,
          stretchToProjectTempo: clip.stretchToProjectTempo,
          tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
          tempoWarpMode: clip.tempoWarpMode,
          crossfade: clip.crossfade,
          automation: clip.volumeAutomation.map((p) => p.copy()).toList(),
          hostedInstrumentStateBase64: clip.hostedInstrumentStateBase64,
          clipId: clip.clipId,
          rowAlreadyEnsured: true,
          notifyUi: false,
          updateProjectDuration: false,
          assumeFreshEngineDefaults: true,
        );
        continue;
      }

      await _addAudioTrackFromProjectFile(
        projectAudioFile: clip.file,
        label: clip.label,
        row: row,
        timeMs: clip.offset * 1000.0,
        trimStartRequested: clip.trimStart,
        trimEndRequested: clip.trimEnd,
        gain: clip.gain,
        normalizeVolume: clip.normalizeVolume,
        normalizeGain: clip.normalizeGain,
        preNormalizeGain: clip.preNormalizeGain,
        pitchSemitones: clip.pitchSemitones,
        isReversed: clip.isReversed,
        sourceTempoBpm: clip.sourceTempoBpm,
        stretchToProjectTempo: clip.stretchToProjectTempo,
        tempoStretchPreservePitch: clip.tempoStretchPreservePitch,
        tempoWarpMode: clip.tempoWarpMode,
        crossfade: clip.crossfade,
        automation: clip.volumeAutomation.map((p) => p.copy()).toList(),
        clipId: clip.clipId,
        rowAlreadyEnsured: true,
        notifyUi: false,
        updateProjectDuration: false,
        assumeFreshEngineDefaults: true,
      );
    }
  }

  Future<void> _restoreDeletedRowState(
    int row,
    RowStateSnapshot rowState,
    _DeletedRowUiState uiState,
  ) async {
    if (row < 0 || row >= _rowCount) return;

    _rowGain[row] = rowState.gain.clamp(_kGainUiMin, _kGainUiMax).toDouble();
    _rowPan[row] = rowState.pan;
    _rowMuted[row] = uiState.muted;
    _rowSoloed[row] = uiState.soloed;
    _rowMuteApplied[row] = uiState.muteApplied;
    _rowExpanded[row] = uiState.expanded;
    _rowExpandedTab[row] = uiState.expandedTab;
    _restoreAutomationLanesForRow(
      row,
      rowState.automationLanes,
      selectedTargetId: rowState.selectedAutomationTargetId,
    );
    _restoreAutomationClipsForRow(row, rowState.automationClips);
    if (row < _rowGainSnapshot.length) {
      _rowGainSnapshot[row] = uiState.gainSnapshot;
    }
    if (row < _rowPanSnapshot.length) {
      _rowPanSnapshot[row] = uiState.panSnapshot;
    }
    if (row < _rowAutomationSnapshot.length) {
      _rowAutomationSnapshot[row] = uiState.automationSnapshot
          .map((point) => point.copy())
          .toList(growable: false);
    }
    if (uiState.peakHoldDb != null) {
      _rowPeakHoldDb[row] = uiState.peakHoldDb!;
    } else {
      _rowPeakHoldDb.remove(row);
    }
    if (uiState.peakHoldLastUpdate != null) {
      _rowPeakHoldLastUpdate[row] = uiState.peakHoldLastUpdate!;
    } else {
      _rowPeakHoldLastUpdate.remove(row);
    }
    if (uiState.peakHoldFreezeUntil != null) {
      _rowPeakHoldFreezeUntil[row] = uiState.peakHoldFreezeUntil!;
    } else {
      _rowPeakHoldFreezeUntil.remove(row);
    }

    await JuceAudioEngine.setRowGain(row, _rowGain[row]);
    await JuceAudioEngine.setRowPan(row, _rowPan[row]);
    await _refreshAutomationTargetsForRow(
      row,
      setStateWhenDone: false,
      syncNativeWhenDone: false,
    );
    await _syncNativeAutomationForRow(row);
  }

  Future<int> _restoreDeletedRowFromSnapshot(
    _DeletedRowSnapshot snapshot,
  ) async {
    var restoredRowIndex = snapshot.originalIndex;
    var restoredRowId = snapshot.row.rowId;

    if (snapshot.wasOnlyRow) {
      if (_rowCount == 0) {
        restoredRowId = await JuceAudioEngine.addRow(
          snapshot.row.name,
          iconId: snapshot.row.iconId,
          preferredRowId: snapshot.row.rowId,
        );
        if (restoredRowId < 0) return snapshot.row.rowId;
        _restoreDeletedRowGroups(snapshot, restoredRowId);
        await _applyRowsToEditorState(
          _applyCurrentTrackGroupMembership(<TimelineRow>[
            snapshot.row.copyWith(rowId: restoredRowId),
          ]),
          refreshAutomationTargets: false,
          syncClipRows: false,
        );
      } else {
        restoredRowIndex = 0;
        restoredRowId = _rowIdAt(restoredRowIndex);
        await JuceAudioEngine.renameRow(restoredRowId, snapshot.row.name);
        await JuceAudioEngine.setRowIcon(restoredRowId, snapshot.row.iconId);
        _restoreDeletedRowGroups(snapshot, restoredRowId);
        await _applyRowsToEditorState(
          _applyCurrentTrackGroupMembership(<TimelineRow>[
            snapshot.row.copyWith(rowId: restoredRowId),
          ]),
          refreshAutomationTargets: false,
          syncClipRows: false,
        );
      }
    } else {
      final desiredIndex = snapshot.originalIndex.clamp(0, _rowCount);
      if (_rowCount == 0) {
        restoredRowId = await JuceAudioEngine.addRow(
          snapshot.row.name,
          iconId: snapshot.row.iconId,
          preferredRowId: snapshot.row.rowId,
        );
        restoredRowIndex = 0;
      } else if (desiredIndex >= _rowCount) {
        restoredRowId = await JuceAudioEngine.insertRowBelow(
          _rowIdAt(_rowCount - 1),
          snapshot.row.name,
          iconId: snapshot.row.iconId,
          preferredRowId: snapshot.row.rowId,
        );
        restoredRowIndex = _rowCount;
      } else {
        restoredRowId = await JuceAudioEngine.insertRowAbove(
          _rowIdAt(desiredIndex),
          snapshot.row.name,
          iconId: snapshot.row.iconId,
          preferredRowId: snapshot.row.rowId,
        );
        restoredRowIndex = desiredIndex;
      }
      if (restoredRowId != snapshot.row.rowId) {
        throw StateError('row_restore_identity_mismatch');
      }

      await JuceAudioEngine.renameRow(restoredRowId, snapshot.row.name);
      await JuceAudioEngine.setRowIcon(restoredRowId, snapshot.row.iconId);
      _restoreDeletedRowGroups(snapshot, restoredRowId);

      final nextRows = List<TimelineRow>.from(_rows)
        ..insert(restoredRowIndex, snapshot.row.copyWith(rowId: restoredRowId));
      await _applyRowsToEditorState(
        _applyCurrentTrackGroupMembership(nextRows),
        refreshAutomationTargets: false,
        syncClipRows: true,
      );
    }

    await _restoreDeletedRowClips(restoredRowIndex, snapshot.clips);
    await _restoreRowSnapshot(
      RowEffectsSnapshot(
        restoredRowIndex,
        snapshot.rowEffects.effects,
        rowId: restoredRowId,
      ),
    );
    await _restoreDeletedRowState(
      restoredRowIndex,
      snapshot.rowState,
      snapshot.uiState,
    );
    await _recomputeAudibleState();
    _updateOverallDurationIfNeeded();
    _refreshRowFx(restoredRowIndex);
    _refreshAudioEditorView();
    return restoredRowId;
  }

  void _restoreDeletedRowGroups(
    _DeletedRowSnapshot snapshot,
    int restoredRowId,
  ) {
    _trackGroups
      ..clear()
      ..addAll(
        snapshot.trackGroups.map((group) {
          return TrackGroup(
            id: group.id,
            name: group.name,
            color: group.color,
            rowIds: group.rowIds
                .map((id) => id == snapshot.row.rowId ? restoredRowId : id)
                .toList(growable: false),
            gain: group.gain,
            pan: group.pan,
            muted: group.muted,
            soloed: group.soloed,
            collapsed: group.collapsed,
            effects: group.effects,
          );
        }),
      );
  }

  List<TimelineRow> _applyCurrentTrackGroupMembership(List<TimelineRow> rows) {
    final groupIdByRowId = <int, String>{
      for (final group in _trackGroups)
        for (final rowId in group.rowIds) rowId: group.id,
    };
    return rows
        .map((row) => row.copyWith(groupId: groupIdByRowId[row.rowId] ?? ''))
        .toList(growable: false);
  }

  Future<void> _restoreDeletedRowClipPayloads(
    int row,
    List<Map<String, dynamic>> clipPayloads,
  ) async {
    for (final payload in clipPayloads) {
      final adjusted = Map<String, dynamic>.from(payload);
      adjusted['rowIndex'] = row;
      await _addClipFromUndoPayload(adjusted);
    }
  }

  Future<int> _restoreDeletedRowFromPersistedSnapshot(
    Map<String, dynamic> snapshot,
  ) async {
    final originalIndex = _valueInt(snapshot['originalIndex']) ?? 0;
    final rowMap = snapshot['row'] is Map<String, dynamic>
        ? snapshot['row'] as Map<String, dynamic>
        : snapshot['row'] is Map
        ? (snapshot['row'] as Map).cast<String, dynamic>()
        : const <String, dynamic>{};
    final rowName = (rowMap['name'] ?? 'Track ${originalIndex + 1}')
        .toString()
        .trim();
    final rowIconId = _valueInt(rowMap['iconId']) ?? 0;
    final rowSnapshot = _timelineRowFromJson(<String, dynamic>{
      ...rowMap,
      'name': rowName,
      'iconId': rowIconId,
    });
    final wasOnlyRow = _valueBool(snapshot['wasOnlyRow']) ?? false;
    final uiState = _commandDeletedRowUiState(snapshot['uiState']);
    final rowState = snapshot['rowState'] is Map<String, dynamic>
        ? RowStateSnapshot.fromJson(snapshot['rowState'])
        : snapshot['rowState'] is Map
        ? RowStateSnapshot.fromJson(
            (snapshot['rowState'] as Map).cast<String, dynamic>(),
          )
        : RowStateSnapshot(
            row: originalIndex,
            rowId: -1,
            gain: _kGainUiUnity,
            pan: 0.5,
            volumeAutomation: <AutomationPoint>[
              AutomationPoint(x: 0.0, volume: 0.75),
            ],
          );
    final rowEffects = _commandRowEffectsSnapshot(snapshot['rowEffects']);
    final clipPayloads = _commandClipPayloads(snapshot['clips']);

    var restoredRowIndex = originalIndex;
    final originalRowId = _valueInt(rowMap['rowId']) ?? -1;
    final preferredRowId = originalRowId > 0 ? originalRowId : null;
    var restoredRowId = originalRowId;

    if (wasOnlyRow) {
      if (_rowCount == 0) {
        restoredRowId = await JuceAudioEngine.addRow(
          rowName,
          iconId: rowIconId,
          preferredRowId: preferredRowId,
        );
        if (restoredRowId < 0) return _valueInt(rowMap['rowId']) ?? -1;
      } else {
        restoredRowIndex = 0;
        restoredRowId = _rowIdAt(0);
        await JuceAudioEngine.renameRow(restoredRowId, rowName);
        await JuceAudioEngine.setRowIcon(restoredRowId, rowIconId);
      }
      await _applyRowsToEditorState(
        <TimelineRow>[rowSnapshot.copyWith(rowId: restoredRowId)],
        refreshAutomationTargets: false,
        syncClipRows: false,
      );
    } else {
      final desiredIndex = originalIndex.clamp(0, _rowCount);
      if (_rowCount == 0) {
        restoredRowId = await JuceAudioEngine.addRow(
          rowName,
          iconId: rowIconId,
          preferredRowId: preferredRowId,
        );
        restoredRowIndex = 0;
      } else if (desiredIndex >= _rowCount) {
        restoredRowId = await JuceAudioEngine.insertRowBelow(
          _rowIdAt(_rowCount - 1),
          rowName,
          iconId: rowIconId,
          preferredRowId: preferredRowId,
        );
        restoredRowIndex = _rowCount;
      } else {
        restoredRowId = await JuceAudioEngine.insertRowAbove(
          _rowIdAt(desiredIndex),
          rowName,
          iconId: rowIconId,
          preferredRowId: preferredRowId,
        );
        restoredRowIndex = desiredIndex;
      }
      if (preferredRowId != null && restoredRowId != preferredRowId) {
        throw StateError('row_restore_identity_mismatch');
      }
      if (restoredRowId < 0) {
        throw StateError('row_restore_failed');
      }

      final nextRows = List<TimelineRow>.from(_rows)
        ..insert(restoredRowIndex, rowSnapshot.copyWith(rowId: restoredRowId));
      await _applyRowsToEditorState(
        nextRows,
        refreshAutomationTargets: false,
        syncClipRows: true,
      );
    }

    await _restoreDeletedRowClipPayloads(restoredRowIndex, clipPayloads);
    await _restoreRowSnapshot(
      RowEffectsSnapshot(
        restoredRowIndex,
        rowEffects.effects,
        rowId: restoredRowId,
      ),
    );
    await _restoreDeletedRowState(restoredRowIndex, rowState, uiState);
    await _recomputeAudibleState();
    _updateOverallDurationIfNeeded();
    _refreshRowFx(restoredRowIndex);
    _refreshAudioEditorView();
    return restoredRowId;
  }

  Future<void> _deletePersistedRowForUndo(
    int currentRowId,
    int fallbackIndex,
    bool closesMidiEditor,
  ) async {
    var targetRow = _rowIndexForId(currentRowId);
    if (targetRow < 0 && _rowCount > 0) {
      targetRow = fallbackIndex.clamp(0, _rowCount - 1).toInt();
    }
    if (targetRow < 0 || targetRow >= _rowCount) return;
    await _deleteRowImpl(targetRow);
    if (closesMidiEditor) {
      _closeMidiClipEditor();
    }
  }

  Future<bool> _deleteRowImpl(int row) async {
    if (row < 0 || row >= _rowCount) return false;
    if (_rowCount == 1) {
      await _clearRowContent(row);
      final rowId = _rowIdAt(row);
      if (rowId >= 0) {
        await JuceAudioEngine.renameRow(rowId, 'Track 1');
        await JuceAudioEngine.setRowIcon(rowId, 0);
        await _applyRowsToEditorState(
          <TimelineRow>[
            TimelineRow(
              rowId: rowId,
              name: 'Track 1',
              iconId: 0,
              kind: TimelineRowKind.audio,
            ),
          ],
          refreshAutomationTargets: false,
          syncClipRows: false,
        );
        await _recomputeAudibleState();
      }
      return true;
    }
    final deletingRowId = _rowIdAt(row);
    if (deletingRowId < 0) return false;

    final removedClips = _clipsForFadeResolution(
      rowIds: <int>{deletingRowId},
    ).toList(growable: false);

    final ok = await JuceAudioEngine.removeRow(deletingRowId);
    if (!ok) return false;

    for (final clip in removedClips) {
      clip.audioStartTimer?.cancel();
      _clipFadeRowIdByEngineId.remove(clip.engineClipId);
    }
    _audioTracks.removeWhere((clip) => clip.rowId == deletingRowId);
    _updateOverallDurationIfNeeded(removedClips: removedClips);

    final nextRows = List<TimelineRow>.from(_rows)..removeAt(row);
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: false,
      syncClipRows: true,
    );
    await _recomputeAudibleState();
    return true;
  }

  Future<void> _deleteRow(int row) async {
    final snapshot = await _captureDeletedRowSnapshot(row);
    if (snapshot == null) return;
    await _undoManager.execute(
      _DeleteRowAction(
        initialRowId: snapshot.row.rowId,
        fallbackIndex: snapshot.originalIndex,
        snapshot: snapshot,
        deleteRow: (currentRowId) async {
          var targetRow = _rowIndexForId(currentRowId);
          if (targetRow < 0 || targetRow >= _rowCount) {
            targetRow = snapshot.originalIndex.clamp(0, _rowCount - 1);
          }
          if (targetRow < 0 || targetRow >= _rowCount) return;
          await _deleteRowImpl(targetRow);
          if (snapshot.closesMidiEditor) {
            _closeMidiClipEditor();
          }
        },
        restoreRow: () => _restoreDeletedRowFromSnapshot(snapshot),
        previousSelectedRowId: snapshot.previousSelectedRowId,
        nextSelectedRowId: snapshot.nextSelectedRowId,
        applySelection: _applyRowSelectionUndoState,
      ),
    );
  }

