  Future<_AiV3GroupLayoutState> _captureAiV3GroupLayoutState() async {
    final selectedRowId = _isValidRowIndex(_selectedRow)
        ? _rowIdAt(_selectedRow)
        : null;
    return _AiV3GroupLayoutState(
      layout: await _captureRowLayoutSnapshot(),
      selectedRowId: selectedRowId,
    );
  }

  _AiV3GroupLayoutState _deriveAiV3GroupLayoutState(
    _AiV3GroupLayoutState before,
    Map<String, dynamic> data,
  ) {
    final operation = data['operation']?.toString().trim() ?? '';
    final sourceRows = before.layout.rows.map(_cloneTimelineRow).toList();
    final sourceGroups = before.layout.trackGroups
        .map(_cloneTrackGroup)
        .toList();
    final rowIds = sourceRows.map((row) => row.rowId).toSet();

    if (operation == 'create') {
      final groupId = data['group_id']?.toString().trim() ?? '';
      final name = data['name']?.toString().trim() ?? '';
      final rawMembers = data['row_ids'];
      if (groupId.isEmpty ||
          name.isEmpty ||
          sourceGroups.any((group) => group.id == groupId) ||
          rawMembers is! List) {
        throw StateError('v3_group_create_state_invalid');
      }
      final members = rawMembers.whereType<int>().toList(growable: false);
      if (members.length < 2 ||
          members.length != rawMembers.length ||
          members.toSet().length != members.length ||
          members.any((rowId) => !rowIds.contains(rowId))) {
        throw StateError('v3_group_create_members_invalid');
      }
      final currentOrder = sourceRows.map((row) => row.rowId).toList();
      final orderedMembers = members.toList(growable: false)
        ..sort(
          (left, right) =>
              currentOrder.indexOf(left).compareTo(currentOrder.indexOf(right)),
        );
      final memberSet = orderedMembers.toSet();
      final retainedGroups = <TrackGroup>[];
      for (final group in sourceGroups) {
        final remaining = group.rowIds
            .where((rowId) => !memberSet.contains(rowId))
            .toList(growable: false);
        if (remaining.length < 2) continue;
        retainedGroups.add(
          TrackGroup(
            id: group.id,
            name: group.name,
            color: group.color,
            rowIds: remaining,
            gain: group.gain,
            pan: group.pan,
            muted: group.muted,
            soloed: group.soloed,
            collapsed: group.collapsed,
            effects: group.effects,
          ),
        );
      }
      final memberColor = orderedMembers
          .map(
            (rowId) => sourceRows.firstWhere((row) => row.rowId == rowId).color,
          )
          .firstWhere((color) => color != 0, orElse: () => 0);
      retainedGroups.add(
        TrackGroup(
          id: groupId,
          name: name,
          color: memberColor,
          rowIds: orderedMembers,
        ),
      );
      final groupIdByRow = <int, String>{
        for (final group in retainedGroups)
          for (final rowId in group.rowIds) rowId: group.id,
      };
      final insertionIndex = orderedMembers
          .map(currentOrder.indexOf)
          .reduce((left, right) => math.min(left, right));
      final reordered =
          sourceRows
              .where((row) => !memberSet.contains(row.rowId))
              .toList(growable: true)
            ..insertAll(
              insertionIndex,
              orderedMembers.map(
                (rowId) => sourceRows.firstWhere((row) => row.rowId == rowId),
              ),
            );
      return _AiV3GroupLayoutState(
        layout: _RowLayoutSnapshot(
          rows: reordered
              .map(
                (row) => row.copyWith(groupId: groupIdByRow[row.rowId] ?? ''),
              )
              .toList(growable: false),
          trackGroups: retainedGroups,
        ),
        selectedRowId: before.selectedRowId,
      );
    }

    final groupId = data['group_id']?.toString().trim() ?? '';
    final groupIndex = sourceGroups.indexWhere((group) => group.id == groupId);
    if (groupId.isEmpty || groupIndex < 0) {
      throw StateError('v3_group_id_unknown');
    }
    final group = sourceGroups[groupIndex];
    if (operation == 'remove_row') {
      final rowId = _toActionInt(data['row_id']);
      if (rowId == null || !group.rowIds.contains(rowId)) {
        throw StateError('v3_group_membership_mismatch');
      }
      final remaining = group.rowIds
          .where((candidate) => candidate != rowId)
          .toList(growable: false);
      final nextGroups = sourceGroups.map(_cloneTrackGroup).toList();
      if (remaining.length < 2) {
        nextGroups.removeAt(groupIndex);
      } else {
        nextGroups[groupIndex] = TrackGroup(
          id: group.id,
          name: group.name,
          color: group.color,
          rowIds: remaining,
          gain: group.gain,
          pan: group.pan,
          muted: group.muted,
          soloed: group.soloed,
          collapsed: group.collapsed,
          effects: group.effects,
        );
      }
      final retainedMemberIds = remaining.length < 2
          ? group.rowIds.toSet()
          : <int>{rowId};
      return _AiV3GroupLayoutState(
        layout: _RowLayoutSnapshot(
          rows: sourceRows
              .map(
                (row) => retainedMemberIds.contains(row.rowId)
                    ? row.copyWith(groupId: '')
                    : row,
              )
              .toList(growable: false),
          trackGroups: nextGroups,
        ),
        selectedRowId: before.selectedRowId,
      );
    }
    if (operation == 'set_collapsed') {
      final collapsed = data['collapsed'];
      if (collapsed is! bool) {
        throw StateError('v3_group_collapsed_invalid');
      }
      final nextGroups = sourceGroups.map(_cloneTrackGroup).toList();
      nextGroups[groupIndex] = TrackGroup(
        id: group.id,
        name: group.name,
        color: group.color,
        rowIds: group.rowIds,
        gain: group.gain,
        pan: group.pan,
        muted: group.muted,
        soloed: group.soloed,
        collapsed: collapsed,
        effects: group.effects,
      );
      return _AiV3GroupLayoutState(
        layout: _RowLayoutSnapshot(rows: sourceRows, trackGroups: nextGroups),
        selectedRowId: before.selectedRowId,
      );
    }
    throw StateError('v3_group_operation_invalid');
  }

  Future<void> _applyAiV3GroupLayoutState(_AiV3GroupLayoutState state) async {
    final currentIds = _rows.map((row) => row.rowId).toSet();
    final targetIds = state.layout.rows.map((row) => row.rowId).toSet();
    if (currentIds.length != targetIds.length ||
        !currentIds.containsAll(targetIds)) {
      throw StateError('v3_group_row_set_stale');
    }
    if (!await _applyEngineRowOrder(state.layout.rows)) {
      throw StateError('v3_group_row_reorder_failed');
    }
    _trackGroups
      ..clear()
      ..addAll(state.layout.trackGroups.map(_cloneTrackGroup));
    await _applyRowsToEditorState(
      state.layout.rows.map(_cloneTimelineRow).toList(growable: false),
      refreshAutomationTargets: false,
      syncClipRows: true,
    );
    await _applyRowSelectionUndoState(state.selectedRowId);
    final actualOrder = _rows.map((row) => row.rowId).toList(growable: false);
    final expectedOrder = state.layout.rows
        .map((row) => row.rowId)
        .toList(growable: false);
    final actualGroups = _trackGroups
        .map((group) => group.toJson())
        .toList(growable: false);
    final expectedGroups = state.layout.trackGroups
        .map((group) => group.toJson())
        .toList(growable: false);
    if (!listEquals(actualOrder, expectedOrder) ||
        jsonEncode(actualGroups) != jsonEncode(expectedGroups)) {
      throw StateError('v3_group_state_apply_mismatch');
    }
    _updateOverallDurationIfNeeded();
    _refreshAudioEditorView();
  }

  Future<void> _applyAiV3GroupEditAction(Map<String, dynamic> data) async {
    final before = await _captureAiV3GroupLayoutState();
    final after = _deriveAiV3GroupLayoutState(before, data);
    await _undoManager.execute(
      _AiV3GroupLayoutAction(
        before: before,
        after: after,
        applyState: _applyAiV3GroupLayoutState,
      ),
    );
  }

  Future<bool> _createRowGroupImpl(
    List<int> rows, {
    String? name,
    int? color,
  }) async {
    final orderedRows =
        rows.where((row) => row >= 0 && row < _rowCount).toSet().toList()
          ..sort();
    if (orderedRows.length < 2) return false;

    final groupedRowIdList = orderedRows.map(_rowIdAt).toList(growable: false);
    final groupedRowIds = groupedRowIdList.toSet();
    final groupedRowsPacked = List<TimelineRow>.from(_rows);
    final insertIndex = orderedRows.first;
    for (int i = 0; i < groupedRowIdList.length; i++) {
      final rowId = groupedRowIdList[i];
      final fromIndex = groupedRowsPacked.indexWhere(
        (candidate) => candidate.rowId == rowId,
      );
      final toIndex = insertIndex + i;
      if (fromIndex < 0 || fromIndex == toIndex) continue;
      final movedInEngine = await JuceAudioEngine.moveRowOrder(
        fromIndex,
        toIndex,
      );
      if (!movedInEngine) {
        return false;
      }
      final movedRow = groupedRowsPacked.removeAt(fromIndex);
      groupedRowsPacked.insert(toIndex, movedRow);
    }

    final groupId =
        'group_${DateTime.now().microsecondsSinceEpoch}_${const Uuid().v4()}';
    final nextRows = groupedRowsPacked
        .map(
          (row) => groupedRowIds.contains(row.rowId)
              ? row.copyWith(groupId: groupId)
              : _cloneTimelineRow(row),
        )
        .toList(growable: false);
    final existingGroups = _trackGroups
        .map((group) {
          final rowIds = group.rowIds
              .where((rowId) => !groupedRowIds.contains(rowId))
              .toList(growable: false);
          if (rowIds.length < 2) return null;
          return TrackGroup(
            id: group.id,
            name: group.name,
            color: group.color,
            rowIds: rowIds,
            gain: group.gain,
            pan: group.pan,
            muted: group.muted,
            soloed: group.soloed,
            collapsed: group.collapsed,
            effects: group.effects,
          );
        })
        .whereType<TrackGroup>()
        .toList(growable: true);
    final normalizedName = (name ?? '').trim();
    final groupColor = color != null && color > 0
        ? color
        : orderedRows
              .map((row) => _rows[row].color)
              .firstWhere((color) => color != 0, orElse: () => 0);
    existingGroups.add(
      TrackGroup(
        id: groupId,
        name: normalizedName.isEmpty
            ? 'Group ${_trackGroups.length + 1}'
            : normalizedName,
        color: groupColor,
        rowIds: groupedRowIdList,
      ),
    );

    _trackGroups
      ..clear()
      ..addAll(existingGroups);
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: false,
      syncClipRows: true,
    );
    return true;
  }

  Future<void> _createRowGroup(
    List<int> rows, {
    String? name,
    int? color,
  }) async {
    await _runRowLayoutActionWithUndo(
      description: 'Create row group',
      perform: () => _createRowGroupImpl(rows, name: name, color: color),
    );
  }

  Future<bool> _removeRowFromGroupImpl(int row) async {
    if (row < 0 || row >= _rowCount) return false;
    final rowId = _rowIdAt(row);
    final currentGroupId = _rows[row].groupId.trim();
    if (currentGroupId.isEmpty) return false;
    final nextRows = _rows
        .map(
          (item) => item.rowId == rowId
              ? item.copyWith(groupId: '')
              : _cloneTimelineRow(item),
        )
        .toList(growable: false);
    final nextGroups = _trackGroups
        .map((group) {
          if (group.id != currentGroupId) return _cloneTrackGroup(group);
          final rowIds = group.rowIds
              .where((candidateId) => candidateId != rowId)
              .toList(growable: false);
          if (rowIds.isEmpty) return null;
          return TrackGroup(
            id: group.id,
            name: group.name,
            color: group.color,
            rowIds: rowIds,
            gain: group.gain,
            pan: group.pan,
            muted: group.muted,
            soloed: group.soloed,
            collapsed: group.collapsed,
            effects: group.effects,
          );
        })
        .whereType<TrackGroup>()
        .toList(growable: false);
    _trackGroups
      ..clear()
      ..addAll(nextGroups);
    await _applyRowsToEditorState(
      nextRows,
      refreshAutomationTargets: false,
      syncClipRows: false,
    );
    return true;
  }

