                                ),
                              if (_showTempoRollDown)
                                Positioned(
                                  top: topBarReservedHeight,
                                  left: 0,
                                  right: 0,
                                  bottom:
                                      _kChatBarStackHeight +
                                      _kTransportBarHeight +
                                      (_isProducerCaptureUiVisible
                                          ? _kProducerBannerHeightEstimate
                                          : 0.0),
                                  child: Listener(
                                    behavior: HitTestBehavior.translucent,
                                    onPointerDown:
                                        _onTopPopupTapAwayPointerDown,
                                    onPointerMove:
                                        _onTopPopupTapAwayPointerMove,
                                    onPointerCancel:
                                        _onTopPopupTapAwayPointerCancel,
                                    onPointerUp: (event) {
                                      if (!_consumeTopPopupTapAwayPointerUp(
                                        event,
                                      )) {
                                        return;
                                      }
                                      if (_isGlobalPointInsideKeyRect(
                                        _tempoRollDownPanelKey,
                                        event.position,
                                      )) {
                                        return;
                                      }
                                      _closeTopPopup(_TopPopupType.tempo);
                                    },
                                    child: const SizedBox.expand(),
                                  ),
                                ),
                              if (_isProjectSettingsOpen)
                                Positioned(
                                  top: topBarReservedHeight,
                                  left: 0,
                                  right: 0,
                                  bottom:
                                      _kChatBarStackHeight +
                                      _kTransportBarHeight +
                                      (_isProducerCaptureUiVisible
                                          ? _kProducerBannerHeightEstimate
                                          : 0.0),
                                  child: Listener(
                                    behavior: HitTestBehavior.translucent,
                                    onPointerDown:
                                        _onTopPopupTapAwayPointerDown,
                                    onPointerMove:
                                        _onTopPopupTapAwayPointerMove,
                                    onPointerCancel:
                                        _onTopPopupTapAwayPointerCancel,
                                    onPointerUp: (event) {
                                      if (!_consumeTopPopupTapAwayPointerUp(
                                        event,
                                      )) {
                                        return;
                                      }
                                      if (_isGlobalPointInsideKeyRect(
                                        _projectSettingsDialogKey,
                                        event.position,
                                      )) {
                                        return;
                                      }
                                      unawaited(_closeProjectSettings());
                                    },
                                    child: const SizedBox.expand(),
                                  ),
                                ),
                              _buildTempoRollDownPanel(),
                              // tap-away closing
                              if (_showMasterRack)
                                Positioned(
                                  top: topBarReservedHeight,
                                  left: 0,
                                  right: 0,
                                  bottom:
                                      _kChatBarStackHeight +
                                      _kTransportBarHeight +
                                      (_isProducerCaptureUiVisible
                                          ? _kProducerBannerHeightEstimate
                                          : 0.0),
                                  child: Listener(
                                    behavior: HitTestBehavior.translucent,
                                    onPointerDown:
                                        _onTopPopupTapAwayPointerDown,
                                    onPointerMove:
                                        _onTopPopupTapAwayPointerMove,
                                    onPointerCancel:
                                        _onTopPopupTapAwayPointerCancel,
                                    onPointerUp: (event) {
                                      if (!_isMasterPopupOpen) return;
                                      if (!_consumeTopPopupTapAwayPointerUp(
                                        event,
                                      )) {
                                        return;
                                      }
                                      if (_isGlobalPointInsideKeyRect(
                                        _masterRackKey,
                                        event.position,
                                      )) {
                                        return;
                                      }
                                      _closeTopPopup(_TopPopupType.master);
                                    },
                                    child: const SizedBox.expand(),
                                  ),
                                ),
                              _buildMasterPopup(),
                              Positioned(
                                top: 0,
                                left: 0,
                                right: tabletRightPanelReservedWidth,
                                child: ValueListenableBuilder<Duration>(
                                  valueListenable: _transportClock,
                                  builder: (_, clock, __) =>
                                      _buildTopBar(clock, editorLayoutSpec),
                                ),
                              ),
                              _buildTimelineHorizontalScrollbarOverlay(
                                topBarReservedHeight: topBarReservedHeight,
                                rightInset: tabletRightPanelReservedWidth,
                              ),
                              _buildProjectSettingsPopup(),
                              _buildExpandedChatHistoryOverlay(),
                            ],
                          );
                        },
                      ),
                    ),
                    // floatingActionButton: Padding(
                    //   padding: const EdgeInsets.only(bottom: 0.0, right: 0.0), // above bottom nav
                    //   child: FloatingActionButton(
                    //     onPressed: () => _showAddMediaOptions(),
                    //     backgroundColor: const Color.fromARGB(255, 212, 212, 212),
                    //     child: const Icon(Icons.add, color: Colors.black),
                    //     shape: const CircleBorder(),
                    //     elevation: 4,
                    //   ),
                    // ),
                  ),
                ),
                Positioned(
                  left: 0,
                  right: usesTabletDawLayout ? tabletBottomDockRightInset : 0,
                  bottom: tabletDawBottomInset,
                  child: Material(
                    type: MaterialType.transparency,
                    child: RepaintBoundary(
                      child: _buildBottomChatAndTransport(
                        includeChatBar: true,
                        includeProducerCapture: showProducerCapture,
                        includeTransport: true,
                        chatBarKeyboardOffset: keyboardLift,
                      ),
                    ),
                  ),
                ),
                _buildFloatingTabletDesktopChatBarOverlay(),
                _buildHoistedFloatingEditorWindows(
                  overlayContext: context,
                  usesTabletDawLayout: usesTabletDawLayout,
                  keyboardLift: keyboardLift,
                ),
                if (_v3ExecutionInProgress)
                  const Positioned.fill(
                    child: ModalBarrier(
                      dismissible: false,
                      color: Colors.transparent,
                    ),
                  ),
                if (_isSyncing)
                  Positioned.fill(
                    child: Container(
                      color: Colors.black.withOpacity(0.75),
                      child: Center(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            const DotsLoader(),
                            const SizedBox(height: 16),
                            SizedBox(
                              width: 250,
                              child: LinearProgressIndicator(
                                value: _syncProgress,
                                backgroundColor: Colors.white30,
                                valueColor: AlwaysStoppedAnimation<Color>(
                                  Colors.lightBlueAccent,
                                ),
                              ),
                            ),
                            const SizedBox(height: 8),
                            Text(
                              '${(_syncProgress * 100).toStringAsFixed(1)}%',
                              style: const TextStyle(color: Colors.white70),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                if ((_isLoadingAudio || _isLoadingNextScreen) &&
                    !_showAiBatchProcessingOverlay)
                  Positioned.fill(
                    child: Container(
                      color: Colors.black.withOpacity(0.5),
                      child: const Center(child: CircularProgressIndicator()),
                    ),
                  ),
                _buildProgressIndicator(),
                _buildAiBatchProcessingOverlay(),
                if (_chatExpanded && !_v3ExecutionInProgress)
                  Positioned(
                    left: usesTabletDawLayout ? tabletSidePanelWidth : 0,
                    right: usesTabletDawLayout
                        ? tabletRightPanelReservedWidth
                        : 0,
                    top: 0,
                    bottom: chatTapAwayBottomInset,
                    child: GestureDetector(
                      behavior: HitTestBehavior.translucent,
                      onTapDown: (_) => _collapseChatWindow(),
                    ),
                  ),
                if (_showDawOnboarding) _buildDawOnboardingOverlay(),
              ],
            ),
          ),
        );
      },
    );
  }

  Alignment _dawOnboardingCardAlignment(_DawTutorialCardPlacement placement) {
    switch (placement) {
      case _DawTutorialCardPlacement.topLeft:
        return Alignment.topLeft;
      case _DawTutorialCardPlacement.topCenter:
        return Alignment.topCenter;
      case _DawTutorialCardPlacement.topRight:
        return Alignment.topRight;
      case _DawTutorialCardPlacement.centerLeft:
        return Alignment.centerLeft;
      case _DawTutorialCardPlacement.centerRight:
        return Alignment.centerRight;
      case _DawTutorialCardPlacement.bottomLeft:
        return Alignment.bottomLeft;
      case _DawTutorialCardPlacement.bottomCenter:
        return Alignment.bottomCenter;
      case _DawTutorialCardPlacement.bottomRight:
        return Alignment.bottomRight;
    }
  }

  EdgeInsets _dawOnboardingCardPadding(_DawTutorialCardPlacement placement) {
    switch (placement) {
      case _DawTutorialCardPlacement.topLeft:
      case _DawTutorialCardPlacement.topCenter:
      case _DawTutorialCardPlacement.topRight:
        return const EdgeInsets.fromLTRB(16, 76, 16, 16);
      case _DawTutorialCardPlacement.centerLeft:
      case _DawTutorialCardPlacement.centerRight:
        return const EdgeInsets.fromLTRB(16, 110, 16, 150);
      case _DawTutorialCardPlacement.bottomLeft:
      case _DawTutorialCardPlacement.bottomCenter:
      case _DawTutorialCardPlacement.bottomRight:
        return const EdgeInsets.fromLTRB(16, 90, 16, 156);
    }
  }

  bool _useTabletDesktopDawOnboardingLayout() {
    return mixroomUsesTabletLandscapeShell(context) ||
        PlatformCapabilities.current.isDesktop;
  }

  Alignment _effectiveDawOnboardingCardAlignment(_DawTutorialStepSpec step) {
    if (step.id == _DawTutorialStepId.rowAutomationTab &&
        _useTabletDesktopDawOnboardingLayout()) {
      return Alignment.centerLeft;
    }
    if (step.id == _DawTutorialStepId.rowExpand &&
        _useTabletDesktopDawOnboardingLayout()) {
      return Alignment.topLeft;
    }
    if (step.id == _DawTutorialStepId.rowEffectsTab &&
        _useTabletDesktopDawOnboardingLayout()) {
      return Alignment.topLeft;
    }
    if (step.id == _DawTutorialStepId.masterOpen &&
        _useTabletDesktopDawOnboardingLayout()) {
      return Alignment.bottomRight;
    }
    if (step.id == _DawTutorialStepId.chatOpen &&
        _useTabletDesktopDawOnboardingLayout()) {
      return Alignment.bottomCenter;
    }
    return _dawOnboardingCardAlignment(step.placement);
  }

  EdgeInsets _effectiveDawOnboardingCardPadding(_DawTutorialStepSpec step) {
    if (step.id == _DawTutorialStepId.rowAutomationTab &&
        _useTabletDesktopDawOnboardingLayout()) {
      return const EdgeInsets.fromLTRB(178, 120, 16, 140);
    }
    if (step.id == _DawTutorialStepId.rowExpand &&
        _useTabletDesktopDawOnboardingLayout()) {
      return const EdgeInsets.fromLTRB(178, 148, 16, 16);
    }
    if (step.id == _DawTutorialStepId.rowEffectsTab &&
        _useTabletDesktopDawOnboardingLayout()) {
      return const EdgeInsets.fromLTRB(178, 206, 16, 16);
    }
    if (step.id == _DawTutorialStepId.masterOpen &&
        _useTabletDesktopDawOnboardingLayout()) {
      return const EdgeInsets.fromLTRB(16, 90, 18, 132);
    }
    if (step.id == _DawTutorialStepId.chatOpen &&
        _useTabletDesktopDawOnboardingLayout()) {
      return const EdgeInsets.fromLTRB(16, 90, 16, 92);
    }
    return step.cardPadding ?? _dawOnboardingCardPadding(step.placement);
  }

  double? _effectiveDawOnboardingCardMaxWidth(_DawTutorialStepSpec step) {
    if (step.id == _DawTutorialStepId.rowAutomationTab &&
        _useTabletDesktopDawOnboardingLayout()) {
      return 248;
    }
    if (step.id == _DawTutorialStepId.rowExpand &&
        _useTabletDesktopDawOnboardingLayout()) {
      return 236;
    }
    if (step.id == _DawTutorialStepId.rowEffectsTab &&
        _useTabletDesktopDawOnboardingLayout()) {
      return 236;
    }
    if (step.id == _DawTutorialStepId.chatOpen &&
        _useTabletDesktopDawOnboardingLayout()) {
      return 320;
    }
    return step.cardMaxWidth;
  }

  Widget _buildDawOnboardingOverlay() {
    final theme = Theme.of(context);
    final step = _currentDawOnboardingStep;
    final stepNumber = _safeDawOnboardingStepIndex + 1;
    final stepCount = _kDawTutorialSequence.length;
    final showPrimaryButton = step.mode != _DawTutorialAdvanceMode.interaction;
    final forceShowPrimaryButtonForStep =
        step.id == _DawTutorialStepId.chatSend;
    void onPrimaryPressed() {
      if (step.mode == _DawTutorialAdvanceMode.done) {
        unawaited(_finishDawOnboarding());
        return;
      }
      if (step.id == _DawTutorialStepId.chatSend &&
          !_dawTutorialAwaitingChatReply) {
        _setDawOnboardingStep(_safeDawOnboardingStepIndex + 2);
        return;
      }
      _advanceDawOnboardingStep();
    }

    final cardAlignment = _effectiveDawOnboardingCardAlignment(step);
    final cardPadding = _effectiveDawOnboardingCardPadding(step);
    final cardMaxWidth = _effectiveDawOnboardingCardMaxWidth(step);
    return Positioned.fill(
      child: Stack(
        children: [
          IgnorePointer(
            child: Container(color: Colors.black.withValues(alpha: 0.18)),
          ),
          SafeArea(
            child: LayoutBuilder(
              builder: (context, constraints) {
                final availableWidth =
                    constraints.maxWidth - cardPadding.horizontal;
                final availableHeight =
                    constraints.maxHeight - cardPadding.vertical;
                if (availableWidth <= 0 || availableHeight <= 0) {
                  return const SizedBox.shrink();
                }
                final maxWidth = math.min(
                  cardMaxWidth ?? 360.0,
                  availableWidth,
                );
                final skipButton = Tooltip(
                  message: _dawTutorialText('skip'),
                  child: TextButton(
                    onPressed: () {
                      unawaited(_finishDawOnboarding());
                    },
                    style: TextButton.styleFrom(
                      foregroundColor: Colors.white,
                      backgroundColor: Colors.white.withValues(alpha: 0.06),
                      padding: const EdgeInsets.all(4),
                      minimumSize: const Size(28, 28),
                      maximumSize: const Size(28, 28),
                      tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                      visualDensity: VisualDensity.compact,
                      shape: const CircleBorder(
                        side: BorderSide(color: Colors.white12),
                      ),
                    ),
                    child: const Icon(Icons.close_rounded, size: 14),
                  ),
                );

                return AnimatedAlign(
                  duration: const Duration(milliseconds: 150),
                  curve: Curves.easeOutCubic,
                  alignment: cardAlignment,
                  child: AnimatedPadding(
                    duration: const Duration(milliseconds: 150),
                    curve: Curves.easeOutCubic,
                    padding: cardPadding,
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 150),
                      curve: Curves.easeOutCubic,
                      constraints: BoxConstraints(
                        maxWidth: maxWidth,
                        maxHeight: availableHeight,
                      ),
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(24),
                        child: BackdropFilter(
                          filter: ImageFilter.blur(sigmaX: 18, sigmaY: 18),
                          child: Container(
                            decoration: BoxDecoration(
                              gradient: LinearGradient(
                                begin: Alignment.topLeft,
                                end: Alignment.bottomRight,
                                colors: <Color>[
                                  const Color(
                                    0xFF10203A,
                                  ).withValues(alpha: 0.96),
                                  const Color(
                                    0xFF0B1527,
                                  ).withValues(alpha: 0.96),
                                ],
                              ),
                              borderRadius: BorderRadius.circular(24),
                              border: Border.all(
                                color: Colors.white.withValues(alpha: 0.08),
                              ),
                              boxShadow: <BoxShadow>[
                                BoxShadow(
                                  color: Colors.black.withValues(alpha: 0.22),
                                  blurRadius: 22,
                                  offset: const Offset(0, 12),
                                ),
                              ],
                            ),
                            padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),
                            child: SingleChildScrollView(
                              physics: const ClampingScrollPhysics(),
                              child: AnimatedSize(
                                duration: const Duration(milliseconds: 150),
                                curve: Curves.easeOutCubic,
                                alignment: Alignment.topCenter,
                                child: AnimatedSwitcher(
                                  duration: const Duration(milliseconds: 120),
                                  switchInCurve: Curves.easeOut,
                                  switchOutCurve: Curves.easeIn,
                                  transitionBuilder: (child, animation) {
                                    final fade = CurvedAnimation(
                                      parent: animation,
                                      curve: Curves.easeOut,
                                    );
                                    final slide = Tween<Offset>(
                                      begin: const Offset(0, 0.02),
                                      end: Offset.zero,
                                    ).animate(fade);
                                    return FadeTransition(
                                      opacity: fade,
                                      child: SlideTransition(
                                        position: slide,
                                        child: child,
                                      ),
                                    );
                                  },
                                  child: Column(
                                    key: ValueKey<_DawTutorialStepId>(step.id),
                                    mainAxisSize: MainAxisSize.min,
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Row(
                                        children: [
                                          Expanded(
                                            child: ConstrainedBox(
                                              constraints: const BoxConstraints(
                                                maxWidth: 160,
                                              ),
                                              child: FittedBox(
                                                fit: BoxFit.scaleDown,
                                                alignment: Alignment.centerLeft,
                                                child: Container(
                                                  padding:
                                                      const EdgeInsets.symmetric(
                                                        horizontal: 10,
                                                        vertical: 6,
                                                      ),
                                                  decoration: BoxDecoration(
                                                    color: step.accent
                                                        .withValues(
                                                          alpha: 0.18,
                                                        ),
                                                    borderRadius:
                                                        BorderRadius.circular(
                                                          999,
                                                        ),
                                                  ),
                                                  child: Text(
                                                    _dawTutorialText(
                                                      'step_badge',
                                                      params: <String, String>{
                                                        'current': stepNumber
                                                            .toString(),
                                                        'total': stepCount
                                                            .toString(),
                                                      },
                                                    ),
                                                    style: theme
                                                        .textTheme
                                                        .labelMedium
                                                        ?.copyWith(
                                                          color: step.accent,
                                                          fontWeight:
                                                              FontWeight.w800,
                                                        ),
                                                    maxLines: 1,
                                                    overflow:
                                                        TextOverflow.ellipsis,
                                                  ),
                                                ),
                                              ),
                                            ),
                                          ),
                                          const SizedBox(width: 8),
                                          Flexible(flex: 0, child: skipButton),
                                        ],
                                      ),
                                      const SizedBox(height: 10),
                                      Text(
                                        step.title,
                                        softWrap: true,
                                        maxLines: 2,
                                        overflow: TextOverflow.ellipsis,
                                        style: theme.textTheme.titleLarge
                                            ?.copyWith(
                                              color: Colors.white,
                                              fontWeight: FontWeight.w800,
                                              height: 1.1,
                                            ),
                                      ),
                                      const SizedBox(height: 8),
                                      Text(
                                        step.body,
                                        softWrap: true,
                                        style: theme.textTheme.bodyMedium
                                            ?.copyWith(
                                              color: Colors.white.withValues(
                                                alpha: 0.82,
                                              ),
                                              height: 1.38,
                                            ),
                                      ),
                                      if (step.helperText != null) ...[
                                        const SizedBox(height: 12),
                                        Container(
                                          width: double.infinity,
                                          padding: const EdgeInsets.symmetric(
                                            horizontal: 12,
                                            vertical: 10,
                                          ),
                                          decoration: BoxDecoration(
                                            color: Colors.white.withValues(
                                              alpha: 0.06,
                                            ),
                                            borderRadius: BorderRadius.circular(
                                              14,
                                            ),
                                            border: Border.all(
                                              color: Colors.white.withValues(
                                                alpha: 0.08,
                                              ),
                                            ),
                                          ),
                                          child: Row(
                                            children: [
                                              if (step.id ==
                                                  _DawTutorialStepId
                                                      .chatWaiting)
                                                Padding(
                                                  padding:
                                                      const EdgeInsets.only(
                                                        right: 10,
                                                      ),
                                                  child: SizedBox(
                                                    width: 14,
                                                    height: 14,
                                                    child: CircularProgressIndicator(
                                                      strokeWidth: 2,
                                                      valueColor:
                                                          AlwaysStoppedAnimation<
                                                            Color
                                                          >(step.accent),
                                                    ),
                                                  ),
                                                ),
                                              Expanded(
                                                child: Text(
                                                  step.helperText!,
                                                  softWrap: true,
                                                  maxLines: 3,
                                                  overflow:
                                                      TextOverflow.ellipsis,
                                                  style: theme
                                                      .textTheme
                                                      .bodySmall
                                                      ?.copyWith(
                                                        color: Colors.white
                                                            .withValues(
                                                              alpha: 0.78,
                                                            ),
                                                        fontWeight:
                                                            FontWeight.w600,
                                                      ),
                                                ),
                                              ),
                                              if (forceShowPrimaryButtonForStep)
                                                Padding(
                                                  padding:
                                                      const EdgeInsets.only(
                                                        left: 8,
                                                      ),
                                                  child: FilledButton(
                                                    onPressed: onPrimaryPressed,
                                                    style: FilledButton.styleFrom(
                                                      backgroundColor:
                                                          step.accent,
                                                      foregroundColor:
                                                          const Color(
                                                            0xFF081220,
                                                          ),
                                                      padding:
                                                          const EdgeInsets.symmetric(
                                                            horizontal: 12,
                                                            vertical: 8,
                                                          ),
                                                      minimumSize: const Size(
                                                        0,
                                                        32,
                                                      ),
                                                      tapTargetSize:
                                                          MaterialTapTargetSize
                                                              .shrinkWrap,
                                                      shape: RoundedRectangleBorder(
                                                        borderRadius:
                                                            BorderRadius.circular(
                                                              10,
                                                            ),
                                                      ),
                                                    ),
                                                    child: Text(
                                                      _dawTutorialText('next'),
                                                      style: const TextStyle(
                                                        fontWeight:
                                                            FontWeight.w800,
                                                      ),
                                                    ),
                                                  ),
                                                ),
                                            ],
                                          ),
                                        ),
                                      ],
                                      if (showPrimaryButton &&
                                          !forceShowPrimaryButtonForStep) ...[
                                        const SizedBox(height: 16),
                                        Align(
                                          alignment: Alignment.centerRight,
                                          child: FilledButton(
                                            onPressed: onPrimaryPressed,
                                            style: FilledButton.styleFrom(
                                              backgroundColor: step.accent,
                                              foregroundColor: const Color(
                                                0xFF081220,
                                              ),
                                              padding:
                                                  const EdgeInsets.symmetric(
                                                    horizontal: 18,
                                                    vertical: 11,
                                                  ),
                                              shape: RoundedRectangleBorder(
                                                borderRadius:
                                                    BorderRadius.circular(14),
                                              ),
                                            ),
                                            child: Text(
                                              step.ctaLabel ??
                                                  (step.mode ==
                                                          _DawTutorialAdvanceMode
                                                              .done
                                                      ? _dawTutorialText('done')
                                                      : _dawTutorialText(
                                                          'next',
                                                        )),
                                              style: const TextStyle(
                                                fontWeight: FontWeight.w800,
                                              ),
                                            ),
                                          ),
                                        ),
                                      ],
                                    ],
                                  ),
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

class _TimelineHorizontalScrollbarEndCap extends StatelessWidget {
  const _TimelineHorizontalScrollbarEndCap({
    required this.active,
    required this.resizing,
  });

  final bool active;
  final bool resizing;

  @override
  Widget build(BuildContext context) {
    final accent = resizing ? const Color(0xFFFFC66D) : const Color(0xFF7FC9E5);
    final colorAlpha = active
        ? 0.76
        : resizing
        ? 0.46
        : 0.28;
    final glowAlpha = active
        ? 0.46
        : resizing
        ? 0.24
        : 0.0;
    return AnimatedContainer(
      duration: const Duration(milliseconds: 110),
      width: active ? 8 : (resizing ? 6 : 5),
      height: active ? 14 : (resizing ? 12 : 9),
      margin: const EdgeInsets.symmetric(horizontal: 3),
      decoration: BoxDecoration(
        color: resizing
            ? accent.withValues(alpha: colorAlpha)
            : const Color(0xFF15436C).withValues(alpha: colorAlpha),
        borderRadius: BorderRadius.circular(99),
        border: active || resizing
            ? Border.all(
                color: Colors.white.withValues(alpha: active ? 0.56 : 0.34),
                width: 0.6,
              )
            : null,
        boxShadow: active || resizing
            ? <BoxShadow>[
                BoxShadow(
                  color: accent.withValues(alpha: glowAlpha),
                  blurRadius: active ? 10 : 7,
                  spreadRadius: active ? 1.4 : 0.8,
                ),
              ]
            : const <BoxShadow>[],
      ),
    );
  }
}

class _TabletDesktopTopControlButtonShell extends StatefulWidget {
  const _TabletDesktopTopControlButtonShell({
    super.key,
    required this.width,
    required this.height,
    required this.semanticLabel,
    required this.active,
    required this.embedded,
    required this.onTap,
    required this.child,
  });

  final double width;
  final double height;
  final String semanticLabel;
  final bool active;
  final bool embedded;
  final VoidCallback onTap;
  final Widget child;

  @override
  State<_TabletDesktopTopControlButtonShell> createState() =>
      _TabletDesktopTopControlButtonShellState();
}

class _TabletDesktopTopControlButtonShellState
    extends State<_TabletDesktopTopControlButtonShell> {
  bool _hovered = false;
  bool _pressed = false;

  void _setHovered(bool value) {
    if (_hovered == value) return;
    setState(() {
      _hovered = value;
    });
  }

  void _setPressed(bool value) {
    if (_pressed == value) return;
    setState(() {
      _pressed = value;
    });
  }

  @override
  Widget build(BuildContext context) {
    final radius = widget.embedded
        ? BorderRadius.zero
        : BorderRadius.circular(12);
    final hoverActive = _hovered;
    final pressed = _pressed;
    final fillColor = widget.active
        ? const Color(0xFFF4F4F4).withValues(alpha: 0.86)
        : hoverActive
        ? Colors.white.withValues(alpha: widget.embedded ? 0.07 : 0.06)
        : Colors.transparent;
    final shadowVisible = widget.active;

    return Semantics(
      label: widget.semanticLabel,
      button: true,
      selected: widget.active,
      child: MouseRegion(
        cursor: SystemMouseCursors.click,
        onEnter: (_) => _setHovered(true),
        onExit: (_) {
          _setHovered(false);
          _setPressed(false);
        },
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTapDown: (_) => _setPressed(true),
          onTapUp: (_) => _setPressed(false),
          onTapCancel: () => _setPressed(false),
          onTap: widget.onTap,
          child: AnimatedScale(
            duration: const Duration(milliseconds: 100),
            curve: Curves.easeOutCubic,
            scale: pressed ? 0.996 : 1.0,
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 140),
              curve: Curves.easeOutCubic,
              width: widget.width,
              height: widget.height,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: fillColor,
                borderRadius: radius,
                boxShadow: shadowVisible
                    ? <BoxShadow>[
                        BoxShadow(
                          color: Colors.black.withValues(
                            alpha: widget.active ? 0.16 : 0.10,
                          ),
                          blurRadius: widget.active ? 10 : 7,
                          spreadRadius: widget.active ? 1 : 0,
                          offset: Offset(0, widget.active ? 2 : 1),
                        ),
                      ]
                    : const <BoxShadow>[],
              ),
              child: AnimatedOpacity(
                duration: const Duration(milliseconds: 100),
                curve: Curves.easeOutCubic,
                opacity: 1.0,
                child: widget.child,
              ),
            ),
          ),
        ),
      ),
    );
  }
}

