// EXPORT SUCCESS SCREEN

enum ExportSuccessAction { backToDaw, exitToProjects }

class ExportSuccessScreen extends StatelessWidget {
  static const MethodChannel _savedExportsChannel = MethodChannel(
    'mixroom/saved_exports',
  );
  final String filePath;
  final String? previewFilePath;
  final String? savedFilePath;
  final String? savedFileName;
  final bool isVideo;

  const ExportSuccessScreen({
    super.key,
    required this.filePath,
    this.previewFilePath,
    required this.isVideo,
    this.savedFilePath,
    this.savedFileName,
  });

  String? _savedNameFromPathHint() {
    final saved = savedFilePath?.trim();
    if (saved == null || saved.isEmpty) return null;

    final normalized = _normalizedCandidatePath(saved);
    if (!_isUriLikePath(normalized)) {
      final decoded = Uri.decodeFull(normalized);
      final base = p.basename(decoded).trim();
      if (base.isNotEmpty &&
          base != '.' &&
          base != p.basename(filePath).trim()) {
        return base;
      }
    }

    final documentId = _extractAndroidDocumentId(saved);
    if (documentId != null && documentId.contains('/')) {
      final leaf = documentId.split('/').last.trim();
      if (leaf.isNotEmpty && leaf != p.basename(filePath).trim()) {
        return leaf;
      }
    }
    return null;
  }

  String _resolvedFileName() {
    final explicit = savedFileName?.trim();
    if (explicit != null && explicit.isNotEmpty) {
      return explicit;
    }

    final hintedFromPath = _savedNameFromPathHint();
    if (hintedFromPath != null && hintedFromPath.isNotEmpty) {
      return hintedFromPath;
    }

    final savedLocalPath = _resolveSavedLocalPath();
    if (savedLocalPath != null && savedLocalPath.isNotEmpty) {
      final base = p.basename(savedLocalPath).trim();
      if (base.isNotEmpty &&
          base != '.' &&
          base != p.basename(filePath).trim()) {
        return base;
      }
    }

    final saved = savedFilePath?.trim();
    if (saved != null && saved.isNotEmpty) {
      final normalized = _normalizedCandidatePath(saved);
      if (_isUriLikePath(normalized)) {
        final uri = Uri.tryParse(normalized);
        if (uri != null && uri.pathSegments.isNotEmpty) {
          final segment = uri.pathSegments.last.trim();
          if (segment.isNotEmpty) return segment;
        }
      } else {
        final base = p.basename(normalized).trim();
        if (base.isNotEmpty && base != '.') return base;
      }
    }

    if (explicit != null && explicit.isNotEmpty) {
      return explicit;
    }

    return p.basename(filePath);
  }

  String _openSavedLabel(BuildContext context) {
    if (!kIsWeb && (Platform.isIOS || Platform.isAndroid)) {
      return L10n.translate(context, 'Open in Files');
    }
    if (!kIsWeb && Platform.isMacOS) {
      return L10n.translate(context, 'Open in Finder');
    }
    if (!kIsWeb && Platform.isWindows) {
      return L10n.translate(context, 'Show in File Explorer');
    }
    if (!kIsWeb && Platform.isLinux) {
      return L10n.translate(context, 'Show in Files');
    }
    return L10n.translate(context, 'Open saved file');
  }

  bool _isUriLikePath(String path) {
    final trimmed = path.trim();
    if (trimmed.isEmpty) return false;
    return trimmed.contains('://');
  }

  String _normalizedCandidatePath(String path) {
    final trimmed = path.trim();
    if (trimmed.isEmpty) return trimmed;
    if (!_isUriLikePath(trimmed)) return trimmed;

    final uri = Uri.tryParse(trimmed);
    if (uri == null) return trimmed;
    if (uri.scheme == 'file') {
      return uri.toFilePath();
    }
    return trimmed;
  }

  String? _extractAndroidDocumentId(String rawPath) {
    var value = rawPath.trim();
    if (value.isEmpty) return null;

    try {
      value = Uri.decodeFull(value);
    } catch (_) {}

    final uri = Uri.tryParse(value);
    final path = uri?.path ?? value;

    String? extractFrom(String input) {
      final markerIndex = input.indexOf('/document/');
      if (markerIndex >= 0) {
        return input.substring(markerIndex + '/document/'.length);
      }
      if (input.startsWith('document/')) {
        return input.substring('document/'.length);
      }
      return null;
    }

    var documentId = extractFrom(path);
    if (documentId == null) {
      documentId = extractFrom(value);
    }
    if (documentId == null || documentId.trim().isEmpty) {
      return null;
    }

    try {
      documentId = Uri.decodeComponent(documentId);
    } catch (_) {}
    return documentId;
  }

  String? _androidDocumentPathToAbsolute(String rawPath) {
    if (kIsWeb || !Platform.isAndroid) return null;
    final documentId = _extractAndroidDocumentId(rawPath);
    if (documentId == null || documentId.isEmpty) return null;

    if (documentId.startsWith('raw:')) {
      final raw = documentId.substring(4);
      if (raw.startsWith('/')) return p.normalize(raw);
      return null;
    }
    if (documentId.startsWith('primary:')) {
      final rel = documentId.substring('primary:'.length);
      return p.normalize('/storage/emulated/0/$rel');
    }
    if (documentId.startsWith('home:')) {
      final rel = documentId.substring('home:'.length);
      return p.normalize('/storage/emulated/0/Documents/$rel');
    }
    if (documentId.startsWith('downloads:')) {
      final rel = documentId.substring('downloads:'.length);
      if (rel.isEmpty || RegExp(r'^\d+$').hasMatch(rel)) return null;
      return p.normalize('/storage/emulated/0/Download/$rel');
    }
    return null;
  }

  String? _resolveSavedLocalPath() {
    final saved = savedFilePath?.trim();
    if (saved == null || saved.isEmpty) return null;

    final normalized = _normalizedCandidatePath(saved);
    if (!_isUriLikePath(normalized) && File(normalized).existsSync()) {
      return normalized;
    }

    final androidAbsolute = _androidDocumentPathToAbsolute(saved);
    if (androidAbsolute != null && File(androidAbsolute).existsSync()) {
      return androidAbsolute;
    }

    return null;
  }

  List<Uri> _uriCandidatesForPath(String path) {
    final normalized = _normalizedCandidatePath(path);
    if (normalized.isEmpty) return const <Uri>[];

    final out = <Uri>[];
    final seen = <String>{};

    void add(Uri? uri) {
      if (uri == null) return;
      final key = uri.toString();
      if (!seen.add(key)) return;
      out.add(uri);
    }

    if (_isUriLikePath(normalized)) {
      add(Uri.tryParse(normalized));
      return out;
    }

    if (!kIsWeb && Platform.isAndroid) {
      if (normalized.startsWith('/document/') ||
          normalized.startsWith('/tree/')) {
        const authorities = <String>[
          'com.android.externalstorage.documents',
          'com.android.providers.downloads.documents',
          'com.android.providers.media.documents',
        ];
        final pathValue = normalized.startsWith('/')
            ? normalized
            : '/$normalized';
        for (final authority in authorities) {
          add(Uri(scheme: 'content', host: authority, path: pathValue));
        }
      }
    }

    if (!kIsWeb && Platform.isIOS && normalized.startsWith('/')) {
      add(Uri.file(normalized));
    }

    return out;
  }

  bool _requiresNativeSavedExportOpen(String path) {
    if (kIsWeb) return false;
    final normalized = _normalizedCandidatePath(path);
    if (Platform.isAndroid) {
      if (_isUriLikePath(normalized)) return true;
      return normalized.startsWith('/document/') ||
          normalized.startsWith('/tree/');
    }
    if (Platform.isIOS) {
      return _isUriLikePath(normalized) || normalized.startsWith('/');
    }
    return false;
  }

  Future<bool> _openSavedExportViaNative(String path) async {
    if (!_requiresNativeSavedExportOpen(path)) return false;
    try {
      final opened = await _savedExportsChannel.invokeMethod<bool>(
        'openSavedExport',
        <String, dynamic>{'path': path},
      );
      return opened == true;
    } catch (_) {
      return false;
    }
  }

  bool get _canRevealSavedExportInDesktopFileManager {
    if (kIsWeb) return false;
    return Platform.isMacOS || Platform.isWindows || Platform.isLinux;
  }

  Future<bool> _revealSavedExportInDesktopFileManager(String path) async {
    if (!_canRevealSavedExportInDesktopFileManager) return false;
    final normalized = _normalizedCandidatePath(path);
    if (normalized.trim().isEmpty || _isUriLikePath(normalized)) return false;

    final isFile = File(normalized).existsSync();
    final isDirectory = Directory(normalized).existsSync();
    if (!isFile && !isDirectory) return false;

    try {
      if (Platform.isMacOS) {
        final args = isDirectory
            ? <String>[normalized]
            : <String>['-R', normalized];
        final result = await Process.run('open', args);
        return result.exitCode == 0;
      }

      if (Platform.isWindows) {
        final args = isDirectory
            ? <String>[normalized]
            : <String>['/select,', normalized];
        final result = await Process.run('explorer.exe', args);
        return result.exitCode == 0;
      }

      if (Platform.isLinux) {
        final folder = isDirectory ? normalized : File(normalized).parent.path;
        if (folder.trim().isEmpty || !Directory(folder).existsSync()) {
          return false;
        }
        final result = await Process.run('xdg-open', <String>[folder]);
        return result.exitCode == 0;
      }
    } catch (_) {
      return false;
    }

    return false;
  }

  String _resolvedActionPath() {
    final savedLocal = _resolveSavedLocalPath();
    if (savedLocal != null && savedLocal.isNotEmpty) {
      return savedLocal;
    }

    final normalizedFilePath = _normalizedCandidatePath(filePath);
    if (!_isUriLikePath(normalizedFilePath) &&
        File(normalizedFilePath).existsSync()) {
      return normalizedFilePath;
    }

    return normalizedFilePath;
  }

  String _resolvedPreviewPath() {
    final preview = previewFilePath?.trim();
    if (preview != null &&
        preview.isNotEmpty &&
        !_isUriLikePath(preview) &&
        File(preview).existsSync()) {
      return preview;
    }

    final normalizedFilePath = _normalizedCandidatePath(filePath);
    final savedLocal = _resolveSavedLocalPath();
    if (savedLocal != null && savedLocal.isNotEmpty) {
      return savedLocal;
    }

    if (!_isUriLikePath(normalizedFilePath) &&
        File(normalizedFilePath).existsSync()) {
      return normalizedFilePath;
    }

    return normalizedFilePath;
  }

  Future<void> _shareFile(BuildContext context) async {
    try {
      if (!kIsWeb && (Platform.isAndroid || Platform.isIOS)) {
        final saved = savedFilePath?.trim();
        if (saved != null && saved.isNotEmpty) {
          final shared = await ExportSaveDialog.shareSavedExportFromPlatform(
            saved,
          );
          if (shared) {
            return;
          }
        }
      }

      var sharePath = _resolvedActionPath();
      if (_isUriLikePath(sharePath) || !File(sharePath).existsSync()) {
        final fallback = _normalizedCandidatePath(filePath);
        if (!_isUriLikePath(fallback) && File(fallback).existsSync()) {
          sharePath = fallback;
        }
      }
      if (_isUriLikePath(sharePath) || !File(sharePath).existsSync()) {
        throw Exception('No readable export file path for sharing.');
      }
      await Share.shareXFiles([XFile(sharePath, name: _resolvedFileName())]);
    } catch (e) {
      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(L10n.translate(context, 'Failed to share.'))),
      );
    }
  }

  Future<void> _openSavedFile(BuildContext context) async {
    if (!kIsWeb && Platform.isAndroid) {
      final saved = savedFilePath?.trim();
      final target = (saved != null && saved.isNotEmpty)
          ? saved
          : _normalizedCandidatePath(filePath);
      if (target.trim().isNotEmpty && await _openSavedExportViaNative(target)) {
        return;
      }

      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            L10n.translate(context, 'Could not open the saved export.'),
          ),
        ),
      );
      return;
    }

    if (_canRevealSavedExportInDesktopFileManager) {
      final saved = savedFilePath?.trim();
      final savedLocalPath = _resolveSavedLocalPath();
      final candidates = <String>[
        if (saved != null && saved.isNotEmpty) _normalizedCandidatePath(saved),
        if (savedLocalPath != null && savedLocalPath.isNotEmpty) savedLocalPath,
        _normalizedCandidatePath(filePath),
      ];

      final attempted = <String>{};
      for (final candidate in candidates) {
        if (candidate.trim().isEmpty || !attempted.add(candidate)) continue;
        if (await _revealSavedExportInDesktopFileManager(candidate)) {
          return;
        }
      }

      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            L10n.translate(context, 'Could not show the saved export.'),
          ),
        ),
      );
      return;
    }

    final saved = savedFilePath?.trim();
    final savedLocalPath = _resolveSavedLocalPath();
    final candidates = <String>[
      if (saved != null && saved.isNotEmpty) _normalizedCandidatePath(saved),
      if (savedLocalPath != null && savedLocalPath.isNotEmpty) savedLocalPath,
      _normalizedCandidatePath(filePath),
    ];

    final attempted = <String>{};
    for (final candidate in candidates) {
      if (candidate.trim().isEmpty || !attempted.add(candidate)) continue;
      try {
        if (await _openSavedExportViaNative(candidate)) {
          return;
        }

        if (!kIsWeb &&
            Platform.isAndroid &&
            _requiresNativeSavedExportOpen(candidate)) {
          continue;
        }

        final uriCandidates = _uriCandidatesForPath(candidate);
        for (final uri in uriCandidates) {
          final launched = await launchUrl(
            uri,
            mode: LaunchMode.externalApplication,
          );
          if (launched) return;
        }

        if (_isUriLikePath(candidate)) continue;
        if (!File(candidate).existsSync()) continue;
        final result = await OpenFile.open(candidate);
        if (result.type == ResultType.done) {
          return;
        }
      } catch (_) {
        // Try the next candidate before surfacing a failure.
      }
    }

    if (!context.mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          L10n.translate(context, 'Could not open the saved export.'),
        ),
      ),
    );
  }

  Future<void> _openSocialMedia(String deepLink, String fallbackUrl) async {
    try {
      if (await canLaunchUrl(Uri.parse(deepLink))) {
        await launchUrl(Uri.parse(deepLink));
      } else {
        await launchUrl(Uri.parse(fallbackUrl));
      }
    } catch (e) {
      debugPrint('Error launching social media.'); // $e');
    }
  }

  void _showUploadComingSoon(BuildContext context) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(L10n.translate(context, 'Platform upload coming soon')),
      ),
    );
  }

  Future<Map<String, String>?> showUploadDialog(BuildContext context) {
    final titleController = TextEditingController(text: 'My Mixroom Video');
    final descController = TextEditingController(
      text: 'Made with Mixroom 🎸🎬',
    );

    return showDialog<Map<String, String>>(
      context: context,
      builder: (context) {
        return AlertDialog(
          title: Text(L10n.translate(context, 'Upload to YouTube')),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                controller: titleController,
                decoration: InputDecoration(
                  labelText: L10n.translate(context, 'Title'),
                ),
              ),
              TextField(
                controller: descController,
                decoration: InputDecoration(
                  labelText: L10n.translate(context, 'Description'),
                ),
                maxLines: 2,
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: Text(L10n.translate(context, 'Cancel')),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: Theme.of(context).colorScheme.primary,
                foregroundColor: const Color.fromARGB(
                  255,
                  255,
                  255,
                  255,
                ), // or onPrimary
              ),
              onPressed: () {
                Navigator.pop(context, {
                  'title': titleController.text,
                  'description': descController.text,
                });
              },
              child: Text(L10n.translate(context, 'Upload')),
            ),
          ],
        );
      },
    );
  }

  Future<File> extractFirstFrame(File videoFile) async {
    final tempDir = await getTemporaryDirectory();
    final outPath = '${tempDir.path}/frame.jpg';

    final cmd = '-i "${videoFile.path}" -frames:v 1 "$outPath"';
    await FFmpegKit.execute(cmd);

    final frame = File(outPath);
    if (!await frame.exists()) throw Exception('Failed to extract frame');
    return frame;
  }

  Future<File> generateThumbnailWithQR(String videoId) async {
    final url = 'https://youtube.com/watch?v=$videoId';

    // 1. Generate QR Code
    final qrValidationResult = QrValidator.validate(
      data: url,
      version: QrVersions.auto,
      errorCorrectionLevel: QrErrorCorrectLevel.H,
    );
    final qrCode = qrValidationResult.qrCode!;
    final painter = QrPainter.withQr(
      qr: qrCode,
      color: const Color(0xFF000000),
      emptyColor: const Color(0xFFFFFFFF),
      gapless: true,
    );
    final qrImageData = await painter.toImageData(
      300,
      format: ImageByteFormat.png,
    );

    final qrBytes = qrImageData!.buffer.asUint8List();

    // 2. Get YouTube default thumbnail
    // final thumbRes = await http.get(Uri.parse('https://img.youtube.com/vi/$videoId/maxresdefault.jpg'));
    // final thumbnail = img.decodeImage(thumbRes.bodyBytes);
    final frameFile = await extractFirstFrame(File(filePath));
    final thumbnail = img.decodeImage(await frameFile.readAsBytes());
    final qr = img.decodeImage(qrBytes);

    if (thumbnail == null || qr == null)
      throw Exception("Failed to process images");

    // 3. Overlay QR on top-left
    final qrSize = (thumbnail.width * 0.25).toInt(); // ~25% width
    final qrResized = img.copyResize(qr, width: qrSize);
    img.compositeImage(thumbnail, qrResized, dstX: 10, dstY: 10);

    // 4. Save to temp file
    final tempDir = await getTemporaryDirectory();
    final outFile = File('${tempDir.path}/yt_thumb_with_qr.jpg');
    await outFile.writeAsBytes(img.encodePng(thumbnail));
    return outFile;
  }

  void showQRPopup(BuildContext context, File qrImage) {
    showDialog(
      context: context,
      builder: (_) {
        return AlertDialog(
          title: Text(L10n.translate(context, 'Video Uploaded')),
