class _DeletedRowUiState {
  final bool muted;
  final bool soloed;
  final bool? muteApplied;
  final bool expanded;
  final int expandedTab;
  final double gainSnapshot;
  final double panSnapshot;
  final List<AutomationPoint> automationSnapshot;
