class _AiV3TransportRollbackAction extends EditorUndoAction {
  _AiV3TransportRollbackAction({
    required this.before,
    required Future<void> Function() applyAction,
    required Future<void> Function(_AiV3TransportSnapshot) restoreAction,
  }) : _applyAction = applyAction,
       _restoreAction = restoreAction;

  final _AiV3TransportSnapshot before;
  final Future<void> Function() _applyAction;
  final Future<void> Function(_AiV3TransportSnapshot) _restoreAction;

  @override
  String get description => 'Apply V3 transport state';

  @override
  Future<void> redo() async {
    try {
      await _applyAction();
    } catch (error, stackTrace) {
      try {
        await _restoreAction(before);
      } catch (_) {
        Error.throwWithStackTrace(
          _EditorUndoCaptureRollbackException(error),
          stackTrace,
        );
      }
      Error.throwWithStackTrace(error, stackTrace);
    }
  }

  @override
  Future<void> undo() => _restoreAction(before);
}

class _EditorUndoCaptureRollbackException
    implements Exception, AiV3RollbackIncompleteFailure {
  const _EditorUndoCaptureRollbackException(this.originalError);

  final Object originalError;

  @override
  String toString() => 'undo_capture_rollback_incomplete';
}

const int _kMaxPersistedUndoCommandJsonBytes = 256 * 1024;

Map<String, dynamic> _persistedClipPayload(AudioTrack clip) {
  final payload = clip.toJson(p.basename(clip.file.path));
  payload['audioDurationMs'] = clip.audioDuration.inMilliseconds;
  if (clip.hostedInstrumentStateBase64.trim().isEmpty) {
    payload.remove('hostedInstrumentStateB64');
  }
  return payload;
}

String _persistedClipIdFor(List<AudioTrack> tracks, int index) {
  if (index < 0 || index >= tracks.length) return '';
  return tracks[index].clipId;
}

class _EditorUndoStackEntry {
  _EditorUndoStackEntry({required this.action, required this.snapshot});

  final EditorUndoAction action;
  final ProjectUndoSnapshotRecord? snapshot;
}

class EditorUndoManager extends ChangeNotifier {
  final int maxHistory;
  final List<_EditorUndoStackEntry> _undo = [];
  final List<_EditorUndoStackEntry> _redo = [];
  final Object _captureZoneKey = Object();
  List<EditorUndoAction>? _capturedActions;
  Object? _captureOwnerToken;
  EditorUndoAction? _lastAction;

  EditorUndoManager({this.maxHistory = 5});

  bool get canUndo => _capturedActions == null && _undo.isNotEmpty;
  bool get canRedo => _capturedActions == null && _redo.isNotEmpty;
  bool get isCapturingActions => _capturedActions != null;
  EditorUndoAction? get lastAction => _lastAction;
  List<ProjectUndoSnapshotRecord> get undoSnapshotRecords =>
      List.unmodifiable(_snapshotRecords(_undo));
  List<ProjectUndoSnapshotRecord> get redoSnapshotRecords =>
      List.unmodifiable(_snapshotRecords(_redo));
  List<ProjectUndoSnapshotRecord> get undoHistoryNewestFirst =>
      List.unmodifiable(_snapshotRecords(_undo.reversed));
  List<ProjectUndoSnapshotRecord> get redoHistoryNewestFirst =>
      List.unmodifiable(_snapshotRecords(_redo.reversed));
  List<ProjectUndoSnapshotRecord> get persistableUndoRecords =>
      List.unmodifiable(_persistableTail(_undo));
  List<ProjectUndoSnapshotRecord> get persistableRedoRecords =>
      List.unmodifiable(_persistableTail(_redo));

  int? undoStepCountForRecord(ProjectUndoSnapshotRecord record) {
    if (_capturedActions != null) return null;
    return _stepCountForRecord(_undo, record);
  }

  int? redoStepCountForRecord(ProjectUndoSnapshotRecord record) {
    if (_capturedActions != null) return null;
    return _stepCountForRecord(_redo, record);
  }

  Future<void> execute(EditorUndoAction action) async {
    _requireActiveCaptureOwner();
    await action.redo();
    if (_capturedActions != null) {
      _captureAction(action);
      return;
    }
    _undo.add(
      _EditorUndoStackEntry(action: action, snapshot: _recordForAction(action)),
    );
    if (_undo.length > maxHistory) {
      _undo.removeAt(0);
    }
    _redo.clear();
    _lastAction = action;
    notifyListeners();
  }

  // yes it is redundant, but works for the edge case of:
  // execute an AI action where you want a compound undo history
  // but you need to execute in sequence before you add, because they depend on each other
  Future<void> executeWithoutAdd(EditorUndoAction action) async {
    _requireActiveCaptureOwner();
    await action.redo();
    if (_capturedActions != null) {
      _captureAction(action);
    }
  }

  // same comment here as above
  Future<void> addWithoutExecute(EditorUndoAction action) async {
    _requireActiveCaptureOwner();
    if (_capturedActions != null) {
      _captureAction(action);
      return;
    }
    _undo.add(
      _EditorUndoStackEntry(action: action, snapshot: _recordForAction(action)),
    );
    if (_undo.length > maxHistory) {
      _undo.removeAt(0);
    }
    _redo.clear();
    _lastAction = action;
    notifyListeners();
  }

  /// Runs existing editor behavior without creating a history entry. Every
  /// undoable action it performs is captured so an AI bundle can commit one
  /// compound action only after all requested steps have succeeded.
  Future<List<EditorUndoAction>> captureActions(
    Future<void> Function() perform,
  ) async {
    if (_capturedActions != null) {
      throw StateError('undo_action_capture_already_active');
    }
    final captured = <EditorUndoAction>[];
    final ownerToken = Object();
    _capturedActions = captured;
    _captureOwnerToken = ownerToken;
    try {
      await runZoned(
        perform,
        zoneValues: <Object, Object>{_captureZoneKey: ownerToken},
      );
      return List<EditorUndoAction>.unmodifiable(captured);
    } catch (error, stackTrace) {
      var rollbackIncomplete = false;
      try {
        await _undoEditorActionsInReverse(captured);
      } catch (_) {
        rollbackIncomplete = true;
      }
      if (rollbackIncomplete) {
        Error.throwWithStackTrace(
          _EditorUndoCaptureRollbackException(error),
          stackTrace,
        );
      }
      rethrow;
    } finally {
      _capturedActions = null;
      _captureOwnerToken = null;
    }
  }

  void _requireActiveCaptureOwner() {
    if (_capturedActions == null) return;
    if (identical(Zone.current[_captureZoneKey], _captureOwnerToken)) return;
    throw StateError('undo_action_capture_external_mutation');
  }

  void _captureAction(EditorUndoAction action) {
    final captured = _capturedActions;
    if (captured == null) return;
    if (action is CompoundUndoAction) {
      captured.removeWhere((item) => action.actions.contains(item));
    } else {
      captured.remove(action);
    }
    captured.add(action);
  }

  Future<EditorUndoAction?> undo() async {
    if (_capturedActions != null) return null;
    if (_undo.isEmpty) return null;
    final entry = _undo.removeLast();
    final a = entry.action;
    await a.undo();
    _redo.add(entry);
    _lastAction = a;
    notifyListeners();
    return a;
  }

  Future<EditorUndoAction?> redo() async {
    if (_capturedActions != null) return null;
    if (_redo.isEmpty) return null;
    final entry = _redo.removeLast();
    final a = entry.action;
    await a.redo();
    _undo.add(entry);
    _lastAction = a;
    notifyListeners();
    return a;
  }

  Future<void> undoSteps(int count) async {
    if (_capturedActions != null) return;
    for (var i = 0; i < count && _undo.isNotEmpty; i++) {
      await undo();
    }
  }

  Future<void> redoSteps(int count) async {
    if (_capturedActions != null) return;
    for (var i = 0; i < count && _redo.isNotEmpty; i++) {
      await redo();
    }
  }

  Future<EditorUndoAction?> undoToRecord(
    ProjectUndoSnapshotRecord record,
  ) async {
    if (_capturedActions != null) return null;
    final index = _indexForRecord(_undo, record);
    if (index < 0) return null;
    return _stepUndoToIndex(index);
  }

  Future<EditorUndoAction?> redoToRecord(
    ProjectUndoSnapshotRecord record,
  ) async {
    if (_capturedActions != null) return null;
    final index = _indexForRecord(_redo, record);
    if (index < 0) return null;
    return _stepRedoToIndex(index);
  }

  Future<EditorUndoAction?> _stepUndoToIndex(int index) async {
    final stepCount = _undo.length - index;
    EditorUndoAction? last;
    for (var i = 0; i < stepCount && _undo.isNotEmpty; i++) {
      last = await undo();
    }
    return last;
  }

  Future<EditorUndoAction?> _stepRedoToIndex(int index) async {
    final stepCount = _redo.length - index;
    EditorUndoAction? last;
    for (var i = 0; i < stepCount && _redo.isNotEmpty; i++) {
      last = await redo();
    }
    return last;
  }

  void restoreCommandHistory({
    required List<ProjectUndoSnapshotRecord> undo,
    required List<ProjectUndoSnapshotRecord> redo,
    required EditorUndoAction? Function(ProjectUndoSnapshotRecord record)
    actionFactory,
    bool notify = true,
  }) {
    _undo
      ..clear()
      ..addAll(_restoreCommandEntries(undo, actionFactory));
    _redo
      ..clear()
      ..addAll(_restoreCommandEntries(redo, actionFactory));
    _lastAction = null;
    if (notify) notifyListeners();
  }

  void clear() {
    if (_undo.isEmpty && _redo.isEmpty) return;
    _undo.clear();
    _redo.clear();
    notifyListeners();
  }

  ProjectUndoSnapshotRecord _recordForAction(EditorUndoAction action) {
    var command = action.toPersistedUndoCommand();
    if (command != null) {
      final sizeBytes = utf8.encode(jsonEncode(command)).length;
      if (sizeBytes > _kMaxPersistedUndoCommandJsonBytes) {
        command = null;
      }
    }
    return ProjectUndoSnapshotRecord(
      id: 'undo_${DateTime.now().microsecondsSinceEpoch}',
      description: action.description,
      timestampMs: DateTime.now().millisecondsSinceEpoch,
      before: const <String, dynamic>{},
      after: const <String, dynamic>{},
      command: command,
    );
  }

  List<ProjectUndoSnapshotRecord> _snapshotRecords(
    Iterable<_EditorUndoStackEntry> entries,
  ) {
    final records = <ProjectUndoSnapshotRecord>[];
    for (final entry in entries) {
      final snapshot = entry.snapshot;
      if (snapshot != null) records.add(snapshot);
    }
    return records;
  }

  int? _stepCountForRecord(
    List<_EditorUndoStackEntry> entries,
    ProjectUndoSnapshotRecord record,
  ) {
    var steps = 0;
    for (final entry in entries.reversed) {
      steps += 1;
      if (entry.snapshot?.id == record.id) return steps;
    }
    return null;
  }

  int _indexForRecord(
    List<_EditorUndoStackEntry> entries,
    ProjectUndoSnapshotRecord record,
  ) {
    return entries.indexWhere((entry) => entry.snapshot?.id == record.id);
  }

  static List<_EditorUndoStackEntry> _restoreCommandEntries(
    List<ProjectUndoSnapshotRecord> records,
    EditorUndoAction? Function(ProjectUndoSnapshotRecord record) actionFactory,
  ) {
    final entries = <_EditorUndoStackEntry>[];
    for (final record in records) {
      if (record.command == null) continue;
      final action = actionFactory(record);
      if (action == null) continue;
      entries.add(_EditorUndoStackEntry(action: action, snapshot: record));
    }
    return entries;
  }

  static List<ProjectUndoSnapshotRecord> _persistableTail(
    List<_EditorUndoStackEntry> entries,
  ) {
    final records = <ProjectUndoSnapshotRecord>[];
    for (final entry in entries.reversed) {
      final snapshot = entry.snapshot;
      if (snapshot?.command == null) break;
      records.add(snapshot!);
    }
    return records.reversed.toList(growable: false);
  }
}

class _RowLayoutSnapshotAction extends EditorUndoAction {
  final String descriptionText;
  final _RowLayoutSnapshot before;
  final _RowLayoutSnapshot after;
  final Future<void> Function(_RowLayoutSnapshot snap) applySnapshot;

  _RowLayoutSnapshotAction({
    required this.descriptionText,
    required this.before,
    required this.after,
    required this.applySnapshot,
  });

  @override
  String get description => descriptionText;

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': 'rowLayout',
    'description': descriptionText,
    'before': before.toJson(),
    'after': after.toJson(),
  };

  @override
  Future<void> redo() => applySnapshot(after);

  @override
  Future<void> undo() => applySnapshot(before);
}

class _AiV3GroupLayoutAction extends EditorUndoAction {
  _AiV3GroupLayoutAction({
    required this.before,
    required this.after,
    required this.applyState,
  });

  final _AiV3GroupLayoutState before;
  final _AiV3GroupLayoutState after;
  final Future<void> Function(_AiV3GroupLayoutState state) applyState;

  @override
  String get description => 'Edit row group';

  Future<void> _applyWithRollback(
    _AiV3GroupLayoutState target,
    _AiV3GroupLayoutState rollback,
  ) async {
    try {
      await applyState(target);
    } catch (error, stackTrace) {
      try {
        await applyState(rollback);
      } catch (_) {
        Error.throwWithStackTrace(
          _EditorUndoCaptureRollbackException(error),
          stackTrace,
        );
      }
      Error.throwWithStackTrace(error, stackTrace);
    }
  }

  @override
  Future<void> redo() => _applyWithRollback(after, before);

  @override
  Future<void> undo() => _applyWithRollback(before, after);
}

class _DeleteRowAction extends EditorUndoAction {
  int _currentRowId;
  final int fallbackIndex;
  final _DeletedRowSnapshot? snapshot;
  final Future<void> Function(int currentRowId) deleteRow;
  final Future<int> Function() restoreRow;
  final int? previousSelectedRowId;
  final int? nextSelectedRowId;
  final Future<void> Function(int? rowId)? applySelection;

  _DeleteRowAction({
    required int initialRowId,
    this.fallbackIndex = 0,
    this.snapshot,
    required this.deleteRow,
    required this.restoreRow,
    this.previousSelectedRowId,
    this.nextSelectedRowId,
    this.applySelection,
  }) : _currentRowId = initialRowId;

  @override
  String get description => 'Delete row';

  @override
  Map<String, dynamic>? toPersistedUndoCommand() {
    final snap = snapshot;
    if (snap == null) return null;
    return <String, dynamic>{
      'type': 'deleteRow',
      'currentRowId': _currentRowId,
      'fallbackIndex': fallbackIndex,
      'snapshot': snap.toJson(),
    };
  }

  @override
  Future<void> redo() async {
    await deleteRow(_currentRowId);
    await applySelection?.call(nextSelectedRowId);
  }

  @override
  Future<void> undo() async {
    _currentRowId = await restoreRow();
    final selected = previousSelectedRowId == snapshot?.row.rowId
        ? _currentRowId
        : previousSelectedRowId;
    await applySelection?.call(selected);
  }
}

class _PersistedDeleteRowAction extends EditorUndoAction {
  int currentRowId;
  final int fallbackIndex;
  final Map<String, dynamic> snapshot;
  final Future<void> Function(
    int currentRowId,
    int fallbackIndex,
    bool closesMidiEditor,
  )
  deleteRow;
  final Future<int> Function(Map<String, dynamic> snapshot) restoreRow;

  _PersistedDeleteRowAction({
    required this.currentRowId,
    required this.fallbackIndex,
    required Map<String, dynamic> snapshot,
    required this.deleteRow,
    required this.restoreRow,
  }) : snapshot = Map<String, dynamic>.from(snapshot);

  @override
  String get description => 'Delete row';

  bool get closesMidiEditor {
    final value = snapshot['closesMidiEditor'];
    if (value is bool) return value;
    return (value ?? '').toString().trim().toLowerCase() == 'true';
  }

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': 'deleteRow',
    'currentRowId': currentRowId,
    'fallbackIndex': fallbackIndex,
    'snapshot': snapshot,
  };

  @override
  Future<void> redo() {
    return deleteRow(currentRowId, fallbackIndex, closesMidiEditor);
  }

  @override
  Future<void> undo() async {
    currentRowId = await restoreRow(snapshot);
  }
}

