class EditMidiClipAction extends EditorUndoAction {
  final List<AudioTrack> tracks;
  final int originalIndex;
  final String clipId;

  final List<MidiNote> oldNotes;
  final List<MidiNote> newNotes;
  final String oldInstrumentId;
  final String oldInstrumentName;
  final Map<String, double> oldInstrumentParams;
  final String oldHostedInstrumentStateBase64;
  final String newInstrumentId;
  final String newInstrumentName;
  final Map<String, double> newInstrumentParams;
  final String newHostedInstrumentStateBase64;
  final Duration? oldTrimEnd;
  final Duration? newTrimEnd;
  final Duration? oldAudioDuration;
  final Duration? newAudioDuration;
  final Map<String, dynamic>? oldClipOwnedState;
  final Map<String, dynamic>? newClipOwnedState;
  final Future<void> Function(AudioTrack clip)? syncTiming;
  final Future<void> Function(
    AudioTrack clip,
    List<MidiNote> notes,
    String instrumentId,
    String instrumentName,
    Map<String, double> instrumentParams,
    String hostedInstrumentStateBase64,
  )
  applyToClip;

  EditMidiClipAction({
    required this.tracks,
    required this.originalIndex,
    String? clipId,
    required this.oldNotes,
    required this.newNotes,
    required this.oldInstrumentId,
    required this.oldInstrumentName,
    required this.oldInstrumentParams,
    this.oldHostedInstrumentStateBase64 = '',
    required this.newInstrumentId,
    required this.newInstrumentName,
    required this.newInstrumentParams,
    this.newHostedInstrumentStateBase64 = '',
    this.oldTrimEnd,
    this.newTrimEnd,
    this.oldAudioDuration,
    this.newAudioDuration,
    this.oldClipOwnedState,
    this.newClipOwnedState,
    this.syncTiming,
    required this.applyToClip,
  }) : clipId = (clipId ?? _persistedClipIdFor(tracks, originalIndex)).trim();

  @override
  String get description => 'Edit MIDI clip';

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': 'midiEdit',
    'clipIndex': originalIndex,
    'clipId': clipId,
    'oldNotes': oldNotes.map((note) => note.toJson()).toList(),
    'newNotes': newNotes.map((note) => note.toJson()).toList(),
    'oldInstrumentId': oldInstrumentId,
    'oldInstrumentName': oldInstrumentName,
    'oldInstrumentParams': oldInstrumentParams,
    if (oldHostedInstrumentStateBase64.trim().isNotEmpty)
      'oldHostedInstrumentStateB64': oldHostedInstrumentStateBase64.trim(),
    'newInstrumentId': newInstrumentId,
    'newInstrumentName': newInstrumentName,
    'newInstrumentParams': newInstrumentParams,
    if (newHostedInstrumentStateBase64.trim().isNotEmpty)
      'newHostedInstrumentStateB64': newHostedInstrumentStateBase64.trim(),
    if (oldTrimEnd != null) 'oldTrimEndMs': oldTrimEnd!.inMilliseconds,
    if (newTrimEnd != null) 'newTrimEndMs': newTrimEnd!.inMilliseconds,
    if (oldAudioDuration != null)
      'oldAudioDurationMs': oldAudioDuration!.inMilliseconds,
    if (newAudioDuration != null)
      'newAudioDurationMs': newAudioDuration!.inMilliseconds,
    if (oldClipOwnedState != null) 'oldClipOwnedState': oldClipOwnedState,
    if (newClipOwnedState != null) 'newClipOwnedState': newClipOwnedState,
  };

  void _applyOwnedState(AudioTrack clip, Map<String, dynamic>? state) {
    if (state == null) return;
    final trimEndUs = state['trim_end_us'];
    final audioDurationUs = state['audio_duration_us'];
    final sourceTempo = state['source_tempo_bpm'];
    final followsTempo = state['stretch_to_project_tempo'];
    final preservePitch = state['tempo_stretch_preserve_pitch'];
    final warpMode = state['tempo_warp_mode'];
    if (trimEndUs is int) {
      clip.trimEnd = Duration(microseconds: trimEndUs);
    }
    if (audioDurationUs is int) {
      clip.audioDuration = Duration(microseconds: audioDurationUs);
    }
    if (sourceTempo is num) {
      clip.sourceTempoBpm = sourceTempo.toDouble();
    }
    if (followsTempo is bool) {
      clip.stretchToProjectTempo = followsTempo;
    }
    if (preservePitch is bool) {
      clip.tempoStretchPreservePitch = preservePitch;
    }
    if (warpMode is String && warpMode.trim().isNotEmpty) {
      clip.tempoWarpMode = warpMode;
    }
  }

  Future<void> _apply({
    required AudioTrack clip,
    required List<MidiNote> notes,
    required String instrumentId,
    required String instrumentName,
    required Map<String, double> instrumentParams,
    required String hostedInstrumentStateBase64,
    required Duration? trimEnd,
    required Duration? audioDuration,
    required Map<String, dynamic>? clipOwnedState,
  }) async {
    if (trimEnd != null) clip.trimEnd = trimEnd;
    if (audioDuration != null) clip.audioDuration = audioDuration;
    await applyToClip(
      clip,
      notes.map((n) => n.copy()).toList(),
      instrumentId,
      instrumentName,
      Map<String, double>.from(instrumentParams),
      hostedInstrumentStateBase64,
    );
    _applyOwnedState(clip, clipOwnedState);
    final sync = syncTiming;
    if (sync != null && clipOwnedState != null) {
      await sync(clip);
    }
  }

  @override
  Future<void> redo() async {
    final clip = _resolveClip(tracks, originalIndex, clipId: clipId);
    if (clip == null) return;
    try {
      await _apply(
        clip: clip,
        notes: newNotes,
        instrumentId: newInstrumentId,
        instrumentName: newInstrumentName,
        instrumentParams: newInstrumentParams,
        hostedInstrumentStateBase64: newHostedInstrumentStateBase64,
        trimEnd: newTrimEnd,
        audioDuration: newAudioDuration,
        clipOwnedState: newClipOwnedState,
      );
    } catch (error, stackTrace) {
      try {
        await _apply(
          clip: clip,
          notes: oldNotes,
          instrumentId: oldInstrumentId,
          instrumentName: oldInstrumentName,
          instrumentParams: oldInstrumentParams,
          hostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
          trimEnd: oldTrimEnd,
          audioDuration: oldAudioDuration,
          clipOwnedState: oldClipOwnedState,
        );
      } catch (_) {
        Error.throwWithStackTrace(
          _EditorUndoCaptureRollbackException(error),
          stackTrace,
        );
      }
      Error.throwWithStackTrace(error, stackTrace);
    }
  }

  @override
  Future<void> undo() async {
    final clip = _resolveClip(tracks, originalIndex, clipId: clipId);
    if (clip == null) return;
    try {
      await _apply(
        clip: clip,
        notes: oldNotes,
        instrumentId: oldInstrumentId,
        instrumentName: oldInstrumentName,
        instrumentParams: oldInstrumentParams,
        hostedInstrumentStateBase64: oldHostedInstrumentStateBase64,
        trimEnd: oldTrimEnd,
        audioDuration: oldAudioDuration,
        clipOwnedState: oldClipOwnedState,
      );
    } catch (error, stackTrace) {
      try {
        await _apply(
          clip: clip,
          notes: newNotes,
          instrumentId: newInstrumentId,
          instrumentName: newInstrumentName,
          instrumentParams: newInstrumentParams,
          hostedInstrumentStateBase64: newHostedInstrumentStateBase64,
          trimEnd: newTrimEnd,
          audioDuration: newAudioDuration,
          clipOwnedState: newClipOwnedState,
        );
      } catch (_) {
        Error.throwWithStackTrace(
          _EditorUndoCaptureRollbackException(error),
          stackTrace,
        );
      }
      Error.throwWithStackTrace(error, stackTrace);
    }
  }
}

class DeleteClipAction extends EditorUndoAction {
  final List<AudioTrack> tracks;
  final AudioTrack clip;
  late final int originalIndex;

  final Future<void> Function({
    required AudioTrack clip,
    required int row,
    required double timeMs,
    required Duration trimStartRequested,
    required Duration trimEndRequested,
  })
  addTrack;

  final void Function(AudioTrack clip, {required bool removed}) onChange;

  // snapshot
  // can deprecate all fields except clip, since all of them derive from clip anyways
  late final File file;
  late final int row;
  late final double timeMs;
  late final Duration trimStart;
  late final Duration trimEnd;

  DeleteClipAction({
    required this.tracks,
    required this.clip,
    required this.addTrack,
    required this.onChange,
  }) {
    originalIndex = tracks.indexOf(clip);
    file = clip.file;
    row = clip.rowIndex;
    timeMs = clip.offset * 1000.0;
    trimStart = clip.trimStart;
    trimEnd = clip.trimEnd;
  }

  @override
  String get description =>
      clip.isMidi ? 'Delete instrument clip' : 'Delete audio clip';

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': 'clipPresenceDelete',
    'description': description,
    'fallbackIndex': originalIndex,
    'clip': _persistedClipPayload(clip),
  };

  @override
  Future<void> redo() async {
    int idx = tracks.indexOf(clip);
    if (idx < 0 && clip.engineClipId >= 0) {
      idx = tracks.indexWhere((t) => t.engineClipId == clip.engineClipId);
    }
    if (idx < 0) return;
    final existing = tracks[idx];

    existing.audioStartTimer?.cancel();
    tracks.removeAt(idx);
    if (existing.engineClipId >= 0) {
      await JuceAudioEngine.removeTrack(existing.engineClipId);
    }

    onChange(existing, removed: true);
  }

  @override
  Future<void> undo() async {
    await addTrack(
      clip: clip,
      row: row,
      timeMs: timeMs,
      trimStartRequested: trimStart,
      trimEndRequested: trimEnd,
    );
    onChange(clip, removed: false);
  }
}

class DeleteClipsAction extends EditorUndoAction {
  DeleteClipsAction({
    required this.actions,
    required this.beginRestoreBatch,
    required this.endRestoreBatch,
    required this.onChange,
  });

  final List<DeleteClipAction> actions;
  final Future<void> Function() beginRestoreBatch;
  final Future<void> Function() endRestoreBatch;
  final Future<void> Function(List<AudioTrack> clips, {required bool removed})
  onChange;

  @override
  String get description => 'Delete clips';

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': 'compound',
    'description': description,
    'actions': actions
        .map((action) => action.toPersistedUndoCommand())
        .whereType<Map<String, dynamic>>()
        .toList(growable: false),
  };

  @override
  Future<void> redo() async {
    final removed = <AudioTrack>[];
    final engineClipIds = <int>[];
    for (final action in actions) {
      var index = action.tracks.indexOf(action.clip);
      if (index < 0 && action.clip.engineClipId >= 0) {
        index = action.tracks.indexWhere(
          (clip) => clip.engineClipId == action.clip.engineClipId,
        );
      }
      if (index < 0) continue;

      final clip = action.tracks.removeAt(index);
      clip.audioStartTimer?.cancel();
      removed.add(clip);
      if (clip.engineClipId >= 0) {
        engineClipIds.add(clip.engineClipId);
      }
    }
    await JuceAudioEngine.unloadClips(engineClipIds);
    await onChange(removed, removed: true);
  }

  @override
  Future<void> undo() async {
    await beginRestoreBatch();
    try {
      for (final action in actions.reversed) {
        await action.addTrack(
          clip: action.clip,
          row: action.row,
          timeMs: action.timeMs,
          trimStartRequested: action.trimStart,
          trimEndRequested: action.trimEnd,
        );
      }
    } finally {
      await endRestoreBatch();
    }
    await onChange(
      actions.map((action) => action.clip).toList(growable: false),
      removed: false,
    );
  }
}

class _PersistedClipPresenceAction extends EditorUndoAction {
  final String descriptionText;
  final bool addedByRedo;
  final Map<String, dynamic> clipPayload;
  final int fallbackIndex;
  final Future<void> Function(Map<String, dynamic> payload) addClip;
  final Future<void> Function(String clipId, int fallbackIndex) removeClip;

  _PersistedClipPresenceAction({
    required String descriptionText,
    required this.addedByRedo,
    required Map<String, dynamic> clipPayload,
    required this.fallbackIndex,
    required this.addClip,
    required this.removeClip,
  }) : descriptionText = descriptionText.trim().isEmpty
           ? (addedByRedo ? 'Add audio clip' : 'Delete audio clip')
           : descriptionText.trim(),
       clipPayload = Map<String, dynamic>.from(clipPayload);

  String get clipId => (clipPayload['clipId'] ?? '').toString().trim();

  @override
  String get description => descriptionText;

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': addedByRedo ? 'clipPresenceAdd' : 'clipPresenceDelete',
    'description': descriptionText,
    'fallbackIndex': fallbackIndex,
    'clip': clipPayload,
  };

  @override
  Future<void> redo() {
    return addedByRedo
        ? addClip(clipPayload)
        : removeClip(clipId, fallbackIndex);
  }

  @override
  Future<void> undo() {
    return addedByRedo
        ? removeClip(clipId, fallbackIndex)
        : addClip(clipPayload);
  }
}

