class _ProjectTempoSnapshot {
  final double tempo;
  final int timeSignatureNumerator;
  final int timeSignatureDenominator;
  final List<double> clipOffsetsSec;
  final List<List<AutomationPoint>> clipVolumeAutomation;
  final List<List<AutomationPoint>> rowVolumeAutomation;
  final Map<int, Map<String, List<AutomationPoint>>> rowPluginAutomation;
  final Map<int, Map<String, List<AutomationClipSnapshot>>> rowAutomationClips;
  final bool loopEnabled;
  final int loopStartMs;
  final int loopEndMs;

  const _ProjectTempoSnapshot({
    required this.tempo,
    required this.timeSignatureNumerator,
    required this.timeSignatureDenominator,
    required this.clipOffsetsSec,
    required this.clipVolumeAutomation,
    required this.rowVolumeAutomation,
    required this.rowPluginAutomation,
    required this.rowAutomationClips,
    required this.loopEnabled,
    required this.loopStartMs,
    required this.loopEndMs,
  });

  Map<String, dynamic> toJson() => <String, dynamic>{
    'tempo': tempo,
    'timeSignatureNumerator': timeSignatureNumerator,
    'timeSignatureDenominator': timeSignatureDenominator,
    'clipOffsetsSec': clipOffsetsSec,
    'clipVolumeAutomation': clipVolumeAutomation
        .map((points) => points.map((point) => point.toJson()).toList())
        .toList(growable: false),
    'rowVolumeAutomation': rowVolumeAutomation
        .map((points) => points.map((point) => point.toJson()).toList())
        .toList(growable: false),
    'rowPluginAutomation': rowPluginAutomation.map(
      (row, laneMap) => MapEntry(
        row.toString(),
        laneMap.map(
          (targetId, points) => MapEntry(
            targetId,
            points.map((point) => point.toJson()).toList(),
          ),
        ),
      ),
    ),
    'rowAutomationClips': rowAutomationClips.map(
      (row, laneMap) => MapEntry(
        row.toString(),
        laneMap.map(
          (targetId, clips) =>
              MapEntry(targetId, clips.map((clip) => clip.toJson()).toList()),
        ),
      ),
    ),
    'loopEnabled': loopEnabled,
    'loopStartMs': loopStartMs,
    'loopEndMs': loopEndMs,
  };
}

