// ----------------------------------------------------------------
// SNAPSHOT HISTORY
// ----------------------------------------------------------------

Future<RowEffectsSnapshot> captureRowSnapshot(
  int row, {
  int rowId = -1,
  bool forceIndividualRow = false,
}) async {
  var effectIds = await JuceAudioEngine.getTrackEffectIdsForRow(
    row,
    forceIndividualRow: forceIndividualRow,
  );
  final effects = await JuceAudioEngine.getTrackEffectsForRow(
    row,
    forceIndividualRow: forceIndividualRow,
  );
  if (effectIds.length != effects.length) {
    effectIds = List<String>.from(effects);
  }
  final snapshots = <EffectSnapshot>[];

  final count = effects.length;
  for (int i = 0; i < count; i++) {
    final params = await JuceAudioEngine.getTrackPluginParameters(
      row,
      i,
      forceIndividualRow: forceIndividualRow,
    );
    final isBypassed = await JuceAudioEngine.getRowEffectBypassState(
      row,
      i,
      forceIndividualRow: forceIndividualRow,
    );
    final effectName = i < effects.length ? effects[i] : effectIds[i];
    final stateBase64 = await JuceAudioEngine.getTrackEffectState(
      row,
      i,
      forceIndividualRow: forceIndividualRow,
    );
    snapshots.add(
      EffectSnapshot(
        effectIds[i],
        isBypassed,
        _effectSnapshotParamValues(effectName, params),
        displayName: effectName,
        stateBase64: _effectSnapshotState(effectName, stateBase64),
      ),
    );
  }

  return RowEffectsSnapshot(row, snapshots, rowId: rowId);
}

class _EffectRestoreFailure {
  const _EffectRestoreFailure({
    required this.effectId,
    required this.displayName,
    required this.reason,
    this.snapshotIndex = -1,
    this.partiallyRestored = false,
  });

  final String effectId;
  final String displayName;
  final String reason;
  final int snapshotIndex;
  final bool partiallyRestored;
}

class _EffectRestoreResult {
  const _EffectRestoreResult(this.failures);

  final List<_EffectRestoreFailure> failures;

  bool get hasFailures => failures.isNotEmpty;
}

const Duration _kProjectPluginInstanceRestoreTimeout = Duration(seconds: 18);
const Duration _kProjectPluginStateRestoreTimeout = Duration(seconds: 12);

Future<void> _waitUntilAsync(
  Future<bool> Function() predicate, {
  int maxAttempts = 30,
  Duration step = const Duration(milliseconds: 100),
}) async {
  for (int i = 0; i < maxAttempts; i++) {
    if (await predicate()) return;
    await Future.delayed(step);
  }
}

Set<String> _pluginParameterKeys(List<Map<String, dynamic>> params) {
  final keys = <String>{};
  for (final param in params) {
    final id = (param['id'] ?? '').toString().trim();
    final name = (param['name'] ?? '').toString().trim();
    if (id.isNotEmpty) keys.add(id);
    if (name.isNotEmpty) keys.add(name);
  }
  return keys;
}

String _effectSnapshotName(EffectSnapshot fx) {
  final displayName = fx.displayName.trim();
  return displayName.isNotEmpty ? displayName : fx.effectId.trim();
}

Map<String, dynamic> _effectSnapshotParamValues(
  String effectName,
  List<Map<String, dynamic>> params,
) {
  return exposedEffectParameterValues(effectName, params);
}

String _effectSnapshotState(String effectName, String stateBase64) {
  return hasCanonicalExposedEffectParameters(effectName) ? '' : stateBase64;
}

bool _shouldRestoreEffectStateChunk(EffectSnapshot fx) {
  return fx.stateBase64.trim().isNotEmpty &&
      !hasCanonicalExposedEffectParameters(_effectSnapshotName(fx));
}

Map<String, dynamic> _restorableEffectSnapshotParams(EffectSnapshot fx) {
  return exposedEffectParameterValueMap(_effectSnapshotName(fx), fx.params);
}

Future<void> _waitForTrackEffectParameters(
  int row,
  int effectIndex,
  Map<String, dynamic> expectedParams,
) async {
  if (expectedParams.isEmpty) return;
  await _waitUntilAsync(
    () async {
      final params = await JuceAudioEngine.getTrackPluginParameters(
        row,
        effectIndex,
      );
      if (params.isEmpty) return false;
      final availableKeys = _pluginParameterKeys(params);
      return expectedParams.keys.every((key) => availableKeys.contains(key));
    },
    maxAttempts: 20,
    step: const Duration(milliseconds: 80),
  );
}

Future<void> _waitForTrackEffectCount(int row, int expectedCount) async {
  await _waitUntilAsync(
    () async {
      final effects = await JuceAudioEngine.getTrackEffectsForRow(row);
      return effects.length == expectedCount;
    },
    maxAttempts: 20,
    step: const Duration(milliseconds: 80),
  );
}

Future<void> _waitForMasterEffectParameters(
  int effectIndex,
  Map<String, dynamic> expectedParams,
) async {
  if (expectedParams.isEmpty) return;
  await _waitUntilAsync(
    () async {
      final params = await JuceAudioEngine.getMasterPluginParameters(
        effectIndex,
      );
      if (params.isEmpty) return false;
      final availableKeys = _pluginParameterKeys(params);
      return expectedParams.keys.every((key) => availableKeys.contains(key));
    },
    maxAttempts: 20,
    step: const Duration(milliseconds: 80),
  );
}

Future<_EffectRestoreResult> _restoreRowSnapshot(
  RowEffectsSnapshot snap,
) async {
  final failures = <_EffectRestoreFailure>[];
  await JuceAudioEngine.beginGraphMutationBatch();
  try {
    // remove all
    final current = await JuceAudioEngine.getTrackEffectsForRow(snap.row);
    for (int i = current.length - 1; i >= 0; i--) {
      await JuceAudioEngine.removeTrackEffect(snap.row, i);
    }
    if (current.isNotEmpty) {
      await _waitForTrackEffectCount(snap.row, 0);
    }

    var insertedCount = 0;

    // reinsert + restore params
    for (
      int snapshotIndex = 0;
      snapshotIndex < snap.effects.length;
      snapshotIndex++
    ) {
      final fx = snap.effects[snapshotIndex];
      if (await JuceAudioEngine.isPluginQuarantined(fx.effectId)) {
        failures.add(
          _EffectRestoreFailure(
            effectId: fx.effectId,
            displayName: fx.displayName.trim().isEmpty
                ? fx.effectId
                : fx.displayName.trim(),
            reason:
                'Plugin is quarantined after a previous crash during load. Use Retry to attempt loading it again.',
            snapshotIndex: snapshotIndex,
          ),
        );
        continue;
      }
      final insertAccepted =
          await runTimedNativeOperation<bool>(
            'Row ${snap.row + 1} FX insert ${_effectSnapshotName(fx)}',
            () => JuceAudioEngine.insertTrackEffect(snap.row, fx.effectId),
            timeout: _kProjectPluginInstanceRestoreTimeout,
          ) ??
          false;
      bool inserted = false;
      final insertedIndex = insertedCount;
      if (insertAccepted) {
        await _waitUntilAsync(
          () async {
            final names = await JuceAudioEngine.getTrackEffectsForRow(snap.row);
            inserted = names.length > insertedIndex;
            return inserted;
          },
          maxAttempts: 8,
          step: const Duration(milliseconds: 80),
        );
      }
      if (!inserted) {
        failures.add(
          _EffectRestoreFailure(
            effectId: fx.effectId,
            displayName: fx.displayName.trim().isEmpty
                ? fx.effectId
                : fx.displayName.trim(),
            reason: 'The plugin could not be instantiated on this Mac.',
            snapshotIndex: snapshotIndex,
          ),
        );
        continue;
      }
      insertedCount += 1;
      final expectsState = _shouldRestoreEffectStateChunk(fx);
      var stateApplied = false;
      if (expectsState) {
        stateApplied =
            await runTimedNativeOperation<bool>(
              'Row ${snap.row + 1} FX state ${_effectSnapshotName(fx)}',
              () => JuceAudioEngine.setTrackEffectState(
                snap.row,
                insertedIndex,
                stateBase64: fx.stateBase64,
              ),
              timeout: _kProjectPluginStateRestoreTimeout,
            ) ??
            false;
      }
      final fallbackParams = _restorableEffectSnapshotParams(fx);
      if (!stateApplied && fallbackParams.isNotEmpty) {
        await _waitForTrackEffectParameters(
          snap.row,
          insertedIndex,
          fallbackParams,
        );
        for (final e in fallbackParams.entries) {
          await JuceAudioEngine.setTrackEffect(
            snap.row,
            insertedIndex,
            e.key,
            e.value,
          );
        }
      }
      if (expectsState && !stateApplied) {
        failures.add(
          _EffectRestoreFailure(
            effectId: fx.effectId,
            displayName: fx.displayName.trim().isEmpty
                ? fx.effectId
                : fx.displayName.trim(),
            reason:
                'The plugin loaded, but Mixroom could only restore exposed parameters instead of the full saved plugin chunk.',
            snapshotIndex: snapshotIndex,
            partiallyRestored: true,
          ),
        );
      }
      if (fx.bypassed) {
        await JuceAudioEngine.bypassRowEffect(snap.row, insertedIndex, true);
      }
    }
  } finally {
    await JuceAudioEngine.endGraphMutationBatch();
  }
  return _EffectRestoreResult(failures);
}

Future<MasterEffectsSnapshot> captureMasterSnapshot() async {
  var effectIds = await JuceAudioEngine.getMasterEffectIds();
  final effects = await JuceAudioEngine.getMasterEffects();
  if (effectIds.length != effects.length) {
    effectIds = List<String>.from(effects);
  }
  final snapshots = <EffectSnapshot>[];

  final count = effects.length;
  for (int i = 0; i < count; i++) {
    final params = await JuceAudioEngine.getMasterPluginParameters(i);
    final isBypassed = await JuceAudioEngine.getMasterEffectBypassState(i);
    final effectName = i < effects.length ? effects[i] : effectIds[i];
    final stateBase64 = await JuceAudioEngine.getMasterEffectState(i);
    snapshots.add(
      EffectSnapshot(
        effectIds[i],
        isBypassed,
        _effectSnapshotParamValues(effectName, params),
        displayName: effectName,
        stateBase64: _effectSnapshotState(effectName, stateBase64),
      ),
    );
  }

  return MasterEffectsSnapshot(snapshots);
}

Future<_EffectRestoreResult> _restoreMasterSnapshot(
  MasterEffectsSnapshot snap,
) async {
  final failures = <_EffectRestoreFailure>[];
  await JuceAudioEngine.beginGraphMutationBatch();
  try {
    // remove all
    final current = await JuceAudioEngine.getMasterEffects();
    for (int i = current.length - 1; i >= 0; i--) {
      await JuceAudioEngine.removeMasterEffect(i);
    }

    var insertedCount = 0;

    // reinsert + restore params
    for (
      int snapshotIndex = 0;
      snapshotIndex < snap.effects.length;
      snapshotIndex++
    ) {
      final fx = snap.effects[snapshotIndex];
      if (await JuceAudioEngine.isPluginQuarantined(fx.effectId)) {
        failures.add(
          _EffectRestoreFailure(
            effectId: fx.effectId,
            displayName: fx.displayName.trim().isEmpty
                ? fx.effectId
                : fx.displayName.trim(),
            reason:
                'Plugin is quarantined after a previous crash during load. Use Retry to attempt loading it again.',
            snapshotIndex: snapshotIndex,
          ),
        );
        continue;
      }
      final insertAccepted =
          await runTimedNativeOperation<bool>(
            'Master FX insert ${_effectSnapshotName(fx)}',
            () => JuceAudioEngine.insertMasterEffect(fx.effectId),
            timeout: _kProjectPluginInstanceRestoreTimeout,
          ) ??
          false;
      bool inserted = false;
      final insertedIndex = insertedCount;
      if (insertAccepted) {
        await _waitUntilAsync(
          () async {
            final names = await JuceAudioEngine.getMasterEffects();
            inserted = names.length > insertedIndex;
            return inserted;
          },
          maxAttempts: 8,
          step: const Duration(milliseconds: 80),
        );
      }
      if (!inserted) {
        failures.add(
          _EffectRestoreFailure(
            effectId: fx.effectId,
            displayName: fx.displayName.trim().isEmpty
                ? fx.effectId
                : fx.displayName.trim(),
            reason: 'The plugin could not be instantiated on this Mac.',
            snapshotIndex: snapshotIndex,
          ),
        );
        continue;
      }
      insertedCount += 1;
      final expectsState = _shouldRestoreEffectStateChunk(fx);
      var stateApplied = false;
      if (expectsState) {
        stateApplied =
            await runTimedNativeOperation<bool>(
              'Master FX state ${_effectSnapshotName(fx)}',
              () => JuceAudioEngine.setMasterEffectState(
                insertedIndex,
                stateBase64: fx.stateBase64,
              ),
              timeout: _kProjectPluginStateRestoreTimeout,
            ) ??
            false;
      }
      final fallbackParams = _restorableEffectSnapshotParams(fx);
      if (!stateApplied && fallbackParams.isNotEmpty) {
        await _waitForMasterEffectParameters(insertedIndex, fallbackParams);
        for (final e in fallbackParams.entries) {
          await JuceAudioEngine.setMasterEffect(insertedIndex, e.key, e.value);
        }
      }
      if (expectsState && !stateApplied) {
        failures.add(
          _EffectRestoreFailure(
            effectId: fx.effectId,
            displayName: fx.displayName.trim().isEmpty
                ? fx.effectId
                : fx.displayName.trim(),
            reason:
                'The plugin loaded, but Mixroom could only restore exposed parameters instead of the full saved plugin chunk.',
            snapshotIndex: snapshotIndex,
            partiallyRestored: true,
          ),
        );
      }
      if (fx.bypassed) {
        await JuceAudioEngine.bypassMasterEffect(insertedIndex, true);
      }
    }
  } finally {
    await JuceAudioEngine.endGraphMutationBatch();
  }
  return _EffectRestoreResult(failures);
}

class TrackPresetChangeAction extends EditorUndoAction {
  final RowEffectsSnapshot before;
  final RowEffectsSnapshot after;
  final VoidCallback onChange;

  TrackPresetChangeAction({
    required this.before,
    required this.after,
    required this.onChange,
  });

  @override
  String get description => 'Load track preset';

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': 'trackPreset',
    'before': before.toJson(),
    'after': after.toJson(),
  };

  @override
  Future<void> redo() async {
    await _restoreRowSnapshot(after);
    onChange();
  }

  @override
  Future<void> undo() async {
    await _restoreRowSnapshot(before);
    onChange();
  }
}

class MasterPresetChangeAction extends EditorUndoAction {
  final MasterEffectsSnapshot before;
  final MasterEffectsSnapshot after;
  final VoidCallback onChange;

  MasterPresetChangeAction({
    required this.before,
