    await _restoreMasterSnapshot(before);
    onChange();
  }
}

class _MasterEffectsSnapshotAction extends EditorUndoAction {
  final String descriptionText;
  final MasterEffectsSnapshot before;
  final MasterEffectsSnapshot after;
  final Future<void> Function(MasterEffectsSnapshot snap) applySnapshot;
  final VoidCallback onChange;

  _MasterEffectsSnapshotAction({
    required this.descriptionText,
    required this.before,
    required this.after,
    required this.applySnapshot,
    required this.onChange,
  });

  @override
  String get description => descriptionText;

  @override
  Map<String, dynamic> toPersistedUndoCommand() => <String, dynamic>{
    'type': 'masterEffectsSnapshot',
    'description': descriptionText,
    'before': before.toJson(),
    'after': after.toJson(),
  };

  @override
  Future<void> redo() async {
    await applySnapshot(after);
    onChange();
  }

  @override
  Future<void> undo() async {
    await applySnapshot(before);
    onChange();
  }
}

AudioTrack? _resolveClip(
  List<AudioTrack> tracks,
  int index, {
  String clipId = '',
}) {
  final id = clipId.trim();
  if (id.isNotEmpty) {
    for (final track in tracks) {
      if (track.clipId == id) return track;
    }
  }
  if (index < 0 || index >= tracks.length) return null;
  return tracks[index];
}

Widget _chatHelpButton({
  required BuildContext context,
  required VoidCallback onTap,
  bool busy = false,
}) {
  final child = Container(
    width: 28,
    height: 28,
    decoration: BoxDecoration(
      color: Colors.white.withValues(alpha: 0.10),
      shape: BoxShape.circle,
      border: Border.all(color: Colors.white.withValues(alpha: 0.12)),
    ),
    alignment: Alignment.center,
    child: busy
        ? const SizedBox(
            width: 14,
            height: 14,
            child: CircularProgressIndicator(
              strokeWidth: 1.8,
              valueColor: AlwaysStoppedAnimation<Color>(Colors.white70),
            ),
          )
        : const Icon(
            Icons.question_mark_rounded,
            size: 16,
            color: Colors.white,
          ),
  );
  if (busy) {
    return SizedBox(width: 28, height: 28, child: child);
  }
  return Tooltip(
    message: L10n.translate(context, 'chat_help_tooltip'),
    child: SizedBox(
      width: 28,
      height: 28,
      child: Material(
        color: Colors.transparent,
        shape: const CircleBorder(),
        child: InkResponse(
          onTap: onTap,
          containedInkWell: true,
          customBorder: const CircleBorder(),
          radius: 20,
          splashColor: Colors.white.withValues(alpha: 0.14),
          highlightColor: Colors.white.withValues(alpha: 0.08),
          child: child,
        ),
      ),
    ),
  );
}

class _ChatBar extends StatefulWidget {
  final bool expanded;
  final bool hasText;
  final bool isThinking;
  final TextEditingController controller;
  final FocusNode focusNode;
  final Gradient barGradient;
  final bool readOnly;
  final MixChangeHighlighter? tutorialHighlighter;
  final AiPromptRateLimitStatus? promptRateLimitStatus;
  final bool promptRateLimitLoading;
  final bool showPromptRateLimitBadge;
  final VoidCallback onShowPromptRateLimits;
  final VoidCallback onShowCapabilities;
  final VoidCallback onTapBar;
  final VoidCallback onSubmit;
  final VoidCallback onStop;

  const _ChatBar({
    super.key,
    required this.expanded,
    required this.hasText,
    required this.isThinking,
    required this.controller,
    required this.focusNode,
    this.barGradient = _AudioEditorScreenState2._kChatBarGradient,
    this.readOnly = false,
    this.tutorialHighlighter,
    required this.promptRateLimitStatus,
    required this.promptRateLimitLoading,
    required this.showPromptRateLimitBadge,
    required this.onShowPromptRateLimits,
    required this.onShowCapabilities,
    required this.onTapBar,
    required this.onSubmit,
    required this.onStop,
  });

  @override
  State<_ChatBar> createState() => _ChatBarState();
}

class _ChatBarState extends State<_ChatBar> {
  bool _pressed = false;

  void _setPressed(bool pressed) {
    if (_pressed == pressed) return;
    setState(() {
      _pressed = pressed;
    });
  }

  String _badgeLabel(BuildContext context) {
    return L10n.translate(context, 'Usage');
  }

  String _badgeTooltip(BuildContext context) {
    final status = widget.promptRateLimitStatus;
    if (status == null) {
      return L10n.translate(context, 'Show prompt limits');
    }
    final daily = status.daily;
    final weekly = status.weekly;
    final extraPromptBank = status.extraPromptBank;
    final extraBankCopy = extraPromptBank.available
        ? ' ${L10n.translate(context, 'Extra bank')}: ${L10n.translate(context, 'used first')}.'
        : '';
    if (status.canSubmit) {
      return '${L10n.translate(context, 'Daily')} ${daily.remainingPercent}% ${L10n.translate(context, 'left')}, '
          '${L10n.translate(context, 'Weekly')} ${weekly.remainingPercent}% ${L10n.translate(context, 'left')}.$extraBankCopy';
    }
    return '${L10n.translate(context, 'Prompt limit reached. Tap to see reset time.')}$extraBankCopy';
  }

  Widget _buildPromptLimitBadge(BuildContext context) {
    Widget badge;
    if (widget.promptRateLimitLoading && widget.promptRateLimitStatus == null) {
      badge = Container(
        width: 26,
        height: 26,
        decoration: BoxDecoration(
          color: const Color.fromRGBO(92, 122, 150, 0.38),
          borderRadius: BorderRadius.circular(999),
          border: Border.all(color: Colors.white.withValues(alpha: 0.12)),
        ),
        alignment: Alignment.center,
        child: const SizedBox(
          width: 13,
          height: 13,
          child: CircularProgressIndicator(
            strokeWidth: 1.8,
            valueColor: AlwaysStoppedAnimation<Color>(Colors.white70),
          ),
        ),
      );
    } else {
      final status = widget.promptRateLimitStatus;
      final backgroundColor = status == null
          ? const Color.fromRGBO(98, 128, 156, 0.38)
          : status.canSubmit
          ? const Color.fromRGBO(104, 134, 160, 0.40)
          : const Color.fromRGBO(152, 116, 110, 0.44);

      badge = Semantics(
        button: true,
        label: _badgeTooltip(context),
        child: Tooltip(
          message: _badgeTooltip(context),
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: widget.onShowPromptRateLimits,
            child: ExcludeSemantics(
              child: Container(
                height: 34,
                constraints: const BoxConstraints(minWidth: 66),
                padding: const EdgeInsets.symmetric(horizontal: 10),
                decoration: BoxDecoration(
                  color: backgroundColor,
                  borderRadius: BorderRadius.circular(999),
                  border: Border.all(
                    color: Colors.white.withValues(alpha: 0.12),
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withValues(alpha: 0.07),
                      blurRadius: 6,
                      offset: const Offset(0, 2),
                    ),
                  ],
                ),
                alignment: Alignment.center,
                child: Text(
                  _badgeLabel(context),
                  style: const TextStyle(
                    fontFamily: 'Pretendard',
                    fontSize: 12,
                    fontWeight: FontWeight.w500,
                    color: Colors.white,
                    height: 1.0,
                  ),
                ),
              ),
            ),
          ),
        ),
      );
    }

    if (widget.tutorialHighlighter != null) {
      badge = Halo(
        highlighter: widget.tutorialHighlighter!,
        haloKey: const HaloKey('tutorial:prompt_limits'),
        borderRadius: BorderRadius.circular(999),
        child: badge,
      );
    }
    return badge;
  }

  @override
  Widget build(BuildContext context) {
    final barHeight = _AudioEditorScreenState2._kChatBarFixedHeight;
    final typeHint = L10n.translate(context, 'Type...');
    const collapsedTextStyle = TextStyle(
      fontFamily: 'Pretendard',
      fontSize: 15,
      fontWeight: FontWeight.w400,
      height: 1.16,
      letterSpacing: -0.15,
      color: Color(0xFFF4F4F4),
    );
    const inputTextStyle = TextStyle(
      fontFamily: 'Pretendard',
      fontSize: 15,
      fontWeight: FontWeight.w400,
      height: 1.16,
      letterSpacing: -0.15,
      color: Color(0xFFF4F4F4),
    );
    const hintTextStyle = TextStyle(
      fontFamily: 'Pretendard',
      fontSize: 15,
      fontWeight: FontWeight.w400,
      height: 1.16,
      letterSpacing: -0.15,
      color: Color(0xB8F4F4F4),
