}

class _TabletMetronomeIcon extends StatelessWidget {
  const _TabletMetronomeIcon({required this.color, required this.size});

  final Color color;
  final double size;

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: Size.square(size),
      painter: _TabletMetronomeIconPainter(color),
    );
  }
}

class _TabletMetronomeIconPainter extends CustomPainter {
  const _TabletMetronomeIconPainter(this.color);

  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final stroke = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = math.max(1.5, size.width * 0.075)
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    final fill = Paint()
      ..color = color.withValues(alpha: 0.18)
      ..style = PaintingStyle.fill;

    final body = Path()
      ..moveTo(size.width * 0.34, size.height * 0.88)
      ..lineTo(size.width * 0.66, size.height * 0.88)
      ..lineTo(size.width * 0.57, size.height * 0.23)
      ..quadraticBezierTo(
        size.width * 0.50,
        size.height * 0.13,
        size.width * 0.43,
        size.height * 0.23,
      )
      ..close();
    canvas.drawPath(body, fill);
    canvas.drawPath(body, stroke);

    canvas.drawLine(
      Offset(size.width * 0.50, size.height * 0.24),
      Offset(size.width * 0.39, size.height * 0.73),
      stroke,
    );
    canvas.drawCircle(
      Offset(size.width * 0.39, size.height * 0.73),
      size.width * 0.07,
      Paint()..color = color,
    );
    canvas.drawLine(
      Offset(size.width * 0.40, size.height * 0.88),
      Offset(size.width * 0.60, size.height * 0.88),
      stroke,
    );
  }

  @override
  bool shouldRepaint(covariant _TabletMetronomeIconPainter oldDelegate) {
    return oldDelegate.color != color;
  }
}

class _TopBarMasterVisualizer extends StatefulWidget {
  final MeterBus meters;

  const _TopBarMasterVisualizer({required this.meters});

  @override
  State<_TopBarMasterVisualizer> createState() =>
      _TopBarMasterVisualizerState();
}

class _TopBarMasterVisualizerState extends State<_TopBarMasterVisualizer> {
  static const int _waveformSampleCount = 2048;
  static const Duration _pollInterval = Duration(milliseconds: 33);
  static const Duration _modeMenuPressDelay = Duration(milliseconds: 240);
  List<double> _waveformSamples = const <double>[];
  List<double> _spectrumDb = const <double>[];
  double _sampleRate = 44100.0;
  double _level = 0.0;
  MeterFrame _meterFrame = MeterFrame.zero;
  bool _clipped = false;
  TopBarVisualizerMode _mode = TopBarVisualizerMode.spectrum;
  Timer? _pollTimer;
  Timer? _modeMenuPressTimer;
  bool _pollInFlight = false;
  bool _modeMenuPressTriggered = false;

  @override
  void initState() {
    super.initState();
    widget.meters.addListener(_handleMetersChanged);
    _syncFromCurrentMeterFrame();
    _startSpectrumPolling();
    unawaited(_refreshSampleRate());
  }

  @override
  void didUpdateWidget(covariant _TopBarMasterVisualizer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.meters, widget.meters)) {
      oldWidget.meters.removeListener(_handleMetersChanged);
      widget.meters.addListener(_handleMetersChanged);
      _syncFromCurrentMeterFrame(forceSetState: true);
    }
  }

  @override
  void dispose() {
    _pollTimer?.cancel();
    _modeMenuPressTimer?.cancel();
    widget.meters.removeListener(_handleMetersChanged);
    super.dispose();
  }

  Future<void> _refreshSampleRate() async {
    final sampleRate = await JuceAudioEngine.getHostSampleRate();
    if (!mounted) return;
    if ((sampleRate - _sampleRate).abs() < 1.0) return;
    setState(() {
      _sampleRate = sampleRate;
    });
  }

  void _startSpectrumPolling() {
    _pollTimer?.cancel();
    _pollTimer = Timer.periodic(_pollInterval, (_) {
      unawaited(_pollSpectrum());
    });
    unawaited(_pollSpectrum());
  }

  Future<void> _pollSpectrum() async {
    if (!mounted || _pollInFlight) return;
    _pollInFlight = true;
    try {
      final waveform = await JuceAudioEngine.getRecentMasterWaveform(
        sampleCount: _waveformSampleCount,
      );
      if (!mounted) return;
      final waveformSamples = List<double>.from(waveform, growable: false);
      final nextSpectrum = _TopBarSpectrumAnalyzer.computeSpectrumDb(waveform);
      final smoothedSpectrum = _TopBarSpectrumAnalyzer.smoothSpectrum(
        current: _spectrumDb,
        next: nextSpectrum,
      );
      if (!listEquals(smoothedSpectrum, _spectrumDb) ||
          !listEquals(waveformSamples, _waveformSamples)) {
        setState(() {
          _waveformSamples = waveformSamples;
          _spectrumDb = smoothedSpectrum;
        });
      }
    } finally {
      _pollInFlight = false;
    }
  }

  void _syncFromCurrentMeterFrame({bool forceSetState = false}) {
    final frame = widget.meters.master;
    final nextLevel = math
        .max(
          math.max(frame.rmsL, frame.rmsR),
          math.max(frame.peakL, frame.peakR),
        )
        .clamp(0.0, 1.0);
    if (!forceSetState &&
        (nextLevel - _level).abs() < 0.01 &&
        frame == _meterFrame &&
        frame.clip == _clipped) {
      return;
    }
    setState(() {
      _level = nextLevel;
      _meterFrame = frame;
      _clipped = frame.clip;
    });
  }

  void _handleMetersChanged() => _syncFromCurrentMeterFrame();

  void _cycleMode() {
    setState(() {
      _mode = _mode.next;
    });
  }

  void _startModeMenuPressTimer(BuildContext anchorContext) {
    _modeMenuPressTimer?.cancel();
    _modeMenuPressTriggered = false;
    _modeMenuPressTimer = Timer(_modeMenuPressDelay, () {
      if (!mounted) return;
      _modeMenuPressTriggered = true;
      unawaited(_showModeMenu(anchorContext));
    });
  }

  void _cancelModeMenuPressTimer() {
    _modeMenuPressTimer?.cancel();
    _modeMenuPressTimer = null;
  }

  void _handleVisualizerTap() {
    if (_modeMenuPressTriggered) {
      _modeMenuPressTriggered = false;
      return;
    }
    _cycleMode();
  }

  void _handleVisualizerSecondaryTap(BuildContext anchorContext) {
    if (!PlatformCapabilities.current.isDesktop) return;
    _cancelModeMenuPressTimer();
    _modeMenuPressTriggered = false;
    unawaited(_showModeMenu(anchorContext));
  }

  IconData _modeIcon(TopBarVisualizerMode mode) {
    return switch (mode) {
      TopBarVisualizerMode.spectrum => Icons.multiline_chart_rounded,
      TopBarVisualizerMode.bars => Icons.bar_chart_rounded,
      TopBarVisualizerMode.meter => Icons.speed_rounded,
      TopBarVisualizerMode.scope => Icons.blur_circular_rounded,
      TopBarVisualizerMode.waveform => Icons.show_chart_rounded,
    };
  }

  String _modeLabel(BuildContext context, TopBarVisualizerMode mode) {
    return L10n.translate(context, mode.label);
  }

  Future<void> _showModeMenu(BuildContext anchorContext) async {
    unawaited(HapticFeedback.selectionClick());
    final selected = await showMixroomGlassDropdown<TopBarVisualizerMode>(
      anchorContext: anchorContext,
      minWidth: 234,
      maxWidth: 292,
      preferredHeight: 262,
      radius: 18,
      color: kMixroomGlassDropdownMenuColor,
      padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxHeight: 262),
        child: ListView.separated(
          padding: EdgeInsets.zero,
          shrinkWrap: true,
          physics: const ClampingScrollPhysics(),
          itemCount: TopBarVisualizerMode.values.length,
          separatorBuilder: (_, __) => Divider(
            height: 1,
            thickness: 1,
            color: Colors.white.withValues(alpha: 0.06),
          ),
          itemBuilder: (menuContext, index) {
            final option = TopBarVisualizerMode.values[index];
            final isSelected = option == _mode;
            final optionLabel = _modeLabel(anchorContext, option);
            final foreground = isSelected
                ? const Color(0xFFF4F4F4)
                : Colors.white.withValues(alpha: 0.78);
            return Material(
              color: Colors.transparent,
              child: InkWell(
                borderRadius: BorderRadius.circular(14),
                onTap: () => Navigator.of(menuContext).pop(option),
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 110),
                  curve: Curves.easeOutCubic,
                  constraints: const BoxConstraints(minHeight: 46),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 9,
                  ),
                  decoration: BoxDecoration(
                    color: isSelected
                        ? const Color(0xFFF4F4F4).withValues(alpha: 0.14)
                        : Colors.transparent,
                    borderRadius: BorderRadius.circular(14),
                    border: isSelected
                        ? Border.all(
                            color: Colors.white.withValues(alpha: 0.14),
                          )
                        : null,
                  ),
                  child: Row(
                    children: [
                      Container(
                        width: 30,
                        height: 30,
                        alignment: Alignment.center,
                        decoration: BoxDecoration(
                          color: isSelected
                              ? const Color(0xFF62D8FF).withValues(alpha: 0.16)
                              : Colors.white.withValues(alpha: 0.06),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(
                            color: isSelected
                                ? const Color(
                                    0xFF62D8FF,
                                  ).withValues(alpha: 0.28)
                                : Colors.white.withValues(alpha: 0.08),
                          ),
                        ),
                        child: Icon(
                          _modeIcon(option),
                          size: 17,
                          color: isSelected
                              ? const Color(0xFF62D8FF)
                              : Colors.white.withValues(alpha: 0.62),
                        ),
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          optionLabel,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            fontFamily: 'Pretendard',
                            color: foreground,
                            fontSize: 13,
                            fontWeight: isSelected
                                ? FontWeight.w900
                                : FontWeight.w700,
                            height: 1.0,
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      AnimatedOpacity(
                        opacity: isSelected ? 1 : 0,
                        duration: const Duration(milliseconds: 110),
                        child: const Icon(
                          Icons.check_rounded,
                          color: Color(0xFF62D8FF),
                          size: 18,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        ),
      ),
    );
    if (!mounted || selected == null || selected == _mode) return;
    setState(() {
      _mode = selected;
    });
  }

  @override
  Widget build(BuildContext context) {
    final label = L10n.translate(context, 'Master output analyzer');
    final currentModeLabel = _modeLabel(context, _mode);
    final nextModeLabel = _modeLabel(context, _mode.next);
    final switchToLabel = L10n.translate(context, 'Switch to');
    final holdToChooseAnalyzerLabel = L10n.translate(
      context,
      'Hold to choose analyzer.',
    );
    final hint = '$switchToLabel $nextModeLabel. $holdToChooseAnalyzerLabel';
    return Semantics(
      button: true,
      label: label,
      value: currentModeLabel,
      hint: hint,
      onTap: _cycleMode,
      onLongPress: () => unawaited(_showModeMenu(context)),
      child: Tooltip(
        message: '$currentModeLabel • $switchToLabel $nextModeLabel',
        child: Builder(
          builder: (anchorContext) {
            return MouseRegion(
              cursor: SystemMouseCursors.click,
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: _handleVisualizerTap,
                onSecondaryTap: () =>
                    _handleVisualizerSecondaryTap(anchorContext),
                onTapDown: (_) => _startModeMenuPressTimer(anchorContext),
                onTapUp: (_) => _cancelModeMenuPressTimer(),
                onTapCancel: _cancelModeMenuPressTimer,
                child: RepaintBoundary(
                  child: CustomPaint(
                    painter: _TopBarMasterVisualizerPainter(
                      waveformSamples: _waveformSamples,
                      spectrumDb: _spectrumDb,
                      analyzerSampleRate: _sampleRate,
                      level: _level,
                      meterFrame: _meterFrame,
                      clipped: _clipped,
                      mode: _mode,
                    ),
                  ),
                ),
              ),
            );
          },
        ),
      ),
    );
  }
}

class _TopBarMasterVisualizerPainter extends CustomPainter {
  final List<double> waveformSamples;
  final List<double> spectrumDb;
  final double analyzerSampleRate;
  final double level;
  final MeterFrame meterFrame;
  final bool clipped;
  final TopBarVisualizerMode mode;

  const _TopBarMasterVisualizerPainter({
    required this.waveformSamples,
    required this.spectrumDb,
    required this.analyzerSampleRate,
    required this.level,
    required this.meterFrame,
    required this.clipped,
    required this.mode,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final rect = Offset.zero & size;
    final rrect = BorderRadius.circular(14).toRRect(rect);

    final bgPaint = Paint()
      ..shader = const LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: <Color>[
          Color(0xFF101820),
          Color(0xFF152231),
          Color(0xFF081017),
        ],
        stops: <double>[0.0, 0.54, 1.0],
      ).createShader(rect);
    canvas.drawRRect(rrect, bgPaint);

    final innerGlow = Paint()
      ..shader = RadialGradient(
        center: const Alignment(0.66, -0.72),
        radius: 1.18,
        colors: <Color>[
          const Color(0xFF48C7FF).withValues(alpha: 0.18 + (0.07 * level)),
          Colors.transparent,
        ],
      ).createShader(rect);
    canvas.drawRRect(rrect, innerGlow);

    final plotRect = Rect.fromLTWH(
      8,
      6,
      size.width - 16,
      math.max(26, size.height - 12),
    );

    canvas.save();
    canvas.clipRRect(rrect);
    final gridPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.055)
      ..strokeWidth = 1;

    for (final fraction in const <double>[0.25, 0.50, 0.75]) {
      final y = plotRect.top + (plotRect.height * fraction);
      canvas.drawLine(
        Offset(plotRect.left, y),
        Offset(plotRect.right, y),
        gridPaint,
      );
    }

    if (mode == TopBarVisualizerMode.spectrum ||
        mode == TopBarVisualizerMode.bars) {
      for (final hz in _TopBarSpectrumAnalyzer.bandMarkerHz) {
        final x = _TopBarSpectrumAnalyzer.frequencyToX(
          hz: hz,
          rect: plotRect,
          sampleRate: analyzerSampleRate,
        );
        canvas.drawLine(
          Offset(x, plotRect.top),
          Offset(x, plotRect.bottom),
          gridPaint,
        );
      }
    }

    final baselinePaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.10)
      ..strokeWidth = 1.1;
    canvas.drawLine(
      Offset(plotRect.left, plotRect.bottom - 0.5),
      Offset(plotRect.right, plotRect.bottom - 0.5),
      baselinePaint,
    );

    switch (mode) {
      case TopBarVisualizerMode.spectrum:
        _paintSpectrum(canvas, plotRect);
        break;
      case TopBarVisualizerMode.bars:
        _paintBars(canvas, plotRect);
        break;
      case TopBarVisualizerMode.meter:
        _paintMeter(canvas, plotRect);
        break;
      case TopBarVisualizerMode.scope:
        _paintScope(canvas, plotRect);
        break;
      case TopBarVisualizerMode.waveform:
        _paintWaveform(canvas, plotRect);
        break;
    }

    canvas.restore();

    final borderPaint = Paint()
      ..color = const Color(0xFFC5EBFF).withValues(alpha: 0.16)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;
    canvas.drawRRect(rrect, borderPaint);
  }

  void _paintSpectrum(Canvas canvas, Rect drawRect) {
    final spectrumPath = Path();
    final sampleColumns = math.max(96, drawRect.width.floor());
    for (int i = 0; i < sampleColumns; i++) {
      final t = sampleColumns <= 1 ? 0.0 : i / (sampleColumns - 1);
      final hz = _TopBarSpectrumAnalyzer.normalizedToFrequency(
        t,
        analyzerSampleRate,
      );
      final db = _TopBarSpectrumAnalyzer.sampleSpectrumDbAtHz(
        spectrumDb: spectrumDb,
        hz: hz,
        sampleRate: analyzerSampleRate,
      );
      final x = drawRect.left + (drawRect.width * t);
      final y = _TopBarSpectrumAnalyzer.dbToY(db, drawRect);
      if (i == 0) {
        spectrumPath.moveTo(x, y);
      } else {
        spectrumPath.lineTo(x, y);
      }
    }

    final fillPath = Path.from(spectrumPath)
      ..lineTo(drawRect.right, drawRect.bottom)
      ..lineTo(drawRect.left, drawRect.bottom)
      ..close();

    const accent = Color(0xFF62D8FF);
    final glowPaint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: <Color>[
          accent.withValues(alpha: clipped ? 0.28 : 0.21),
          accent.withValues(alpha: 0.045),
          Colors.transparent,
        ],
      ).createShader(drawRect);
    canvas.drawPath(fillPath, glowPaint);

    final haloPaint = Paint()
      ..color = accent.withValues(alpha: 0.24)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 4.0
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4);
    canvas.drawPath(spectrumPath, haloPaint);

    final linePaint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.centerLeft,
        end: Alignment.centerRight,
        colors: <Color>[
          accent.withValues(alpha: 0.80 + (0.10 * level)),
          const Color(0xFFFFFFFF).withValues(alpha: 0.90),
        ],
      ).createShader(drawRect)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.45
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    canvas.drawPath(spectrumPath, linePaint);
  }

  void _paintBars(Canvas canvas, Rect drawRect) {
    const accent = Color(0xFF62D8FF);
    const barCount = 56;
    final barWidth = drawRect.width / ((barCount * 1.34) - 0.34);
    final gap = barWidth * 0.34;
    final barPaint = Paint();
    for (int i = 0; i < barCount; i++) {
      final t = barCount <= 1 ? 0.0 : i / (barCount - 1);
      final hz = _TopBarSpectrumAnalyzer.normalizedToFrequency(
        t,
        analyzerSampleRate,
      );
      final db = _TopBarSpectrumAnalyzer.sampleSpectrumDbAtHz(
        spectrumDb: spectrumDb,
        hz: hz,
        sampleRate: analyzerSampleRate,
      );
      final amplitude = _TopBarSpectrumAnalyzer.dbToUnit(db);
      final x = drawRect.left + (i * (barWidth + gap));
      final height = math.max(
        1.8,
        (drawRect.height - 1.4) * math.pow(amplitude, 0.84),
      );
      final barRect = RRect.fromRectAndRadius(
        Rect.fromLTWH(x, drawRect.bottom - height, barWidth, height),
        Radius.circular(math.min(2.2, barWidth * 0.46)),
      );
      barPaint.shader = LinearGradient(
        begin: Alignment.bottomCenter,
        end: Alignment.topCenter,
        colors: [
          accent.withValues(alpha: 0.14 + (0.10 * level)),
          accent.withValues(alpha: 0.42 + (0.20 * amplitude)),
          Colors.white.withValues(alpha: 0.86),
        ],
      ).createShader(barRect.outerRect);
      canvas.drawRRect(barRect, barPaint);
    }
  }

  void _paintMeter(Canvas canvas, Rect drawRect) {
    const laneGap = 2.0;
    final laneHeight = (drawRect.height * 0.18).clamp(5.0, 7.5).toDouble();
    final meterHeight = (laneHeight * 2.0) + laneGap;
    final meterTop = drawRect.top + ((drawRect.height - meterHeight) / 2.0);
    final laneArea = Rect.fromLTWH(
      drawRect.left,
      meterTop,
      drawRect.width,
      meterHeight,
    );
    final laneBackground = Paint()
      ..color = const Color(0xFF071018).withValues(alpha: 0.70);
    final peakPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.88)
      ..strokeWidth = 1.0;
    final tickPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.075)
      ..strokeWidth = 1;

    for (final db in const <double>[-48, -30, -15, -6, 0]) {
      final x =
          laneArea.left + (laneArea.width * DbfsMeterVisuals.dbfsToUnit(db));
      canvas.drawLine(
        Offset(x, laneArea.top),
        Offset(x, laneArea.bottom),
        tickPaint,
      );
    }

    void drawLane({
      required double top,
      required double rms,
      required double peak,
    }) {
      final laneRect = RRect.fromRectAndRadius(
        Rect.fromLTWH(laneArea.left, top, laneArea.width, laneHeight),
        const Radius.circular(2.6),
      );
      canvas.drawRRect(laneRect, laneBackground);

      final rmsWidth = laneArea.width * DbfsMeterVisuals.ampToUnit(rms);
      final peakWidth = laneArea.width * DbfsMeterVisuals.ampToUnit(peak);
      if (rmsWidth > 0.0) {
        final rmsRect = Rect.fromLTWH(
          laneRect.outerRect.left,
          laneRect.outerRect.top,
          rmsWidth,
          laneRect.outerRect.height,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(rmsRect, const Radius.circular(2.6)),
          Paint()
            ..shader = DbfsMeterVisuals.horizontalGradient(
              opacity: 0.94,
            ).createShader(laneRect.outerRect),
        );
      }
      if (peakWidth > rmsWidth) {
        final peakRect = Rect.fromLTWH(
          laneRect.outerRect.left + rmsWidth,
          laneRect.outerRect.top,
          peakWidth - rmsWidth,
          laneRect.outerRect.height,
        );
        canvas.drawRect(
          peakRect,
          Paint()
            ..shader = DbfsMeterVisuals.horizontalGradient(
              opacity: 0.34,
            ).createShader(laneRect.outerRect),
        );
      }
      if (peakWidth > 0.6) {
        final peakX = (laneArea.left + peakWidth)
            .clamp(laneArea.left, laneArea.right)
            .toDouble();
        canvas.drawLine(
          Offset(peakX, laneRect.outerRect.top),
          Offset(peakX, laneRect.outerRect.bottom),
          peakPaint,
        );
      }
    }

    drawLane(top: laneArea.top, rms: meterFrame.rmsL, peak: meterFrame.peakL);
    drawLane(
      top: laneArea.top + laneHeight + laneGap,
      rms: meterFrame.rmsR,
      peak: meterFrame.peakR,
    );
  }

  double _waveformAutoGain(List<double> samples) {
    if (samples.isEmpty) return 1.0;
    var maxAbs = 0.0;
    for (final sample in samples) {
      final absValue = sample.abs();
      if (absValue > maxAbs) maxAbs = absValue;
    }
    if (maxAbs < 0.0001) return 1.0;
    return (0.82 / maxAbs).clamp(1.0, 8.0).toDouble();
  }

  void _paintScope(Canvas canvas, Rect drawRect) {
    final center = drawRect.center;
    final axisPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.055)
      ..strokeWidth = 1;
    canvas.drawLine(
      Offset(drawRect.left, center.dy),
      Offset(drawRect.right, center.dy),
      axisPaint,
    );
    canvas.drawLine(
      Offset(center.dx, drawRect.top),
      Offset(center.dx, drawRect.bottom),
      axisPaint,
    );

    final samples = waveformSamples;
    final path = Path();
    final points = math.min(420, samples.length);
    if (points < 8) {
      final idleRect = Rect.fromCenter(
        center: center,
        width: drawRect.width * (0.18 + (level * 0.28)),
        height: drawRect.height * (0.18 + (level * 0.34)),
      );
      path.addOval(idleRect);
    } else {
      final step = math.max(1, (samples.length / points).floor());
      final gain = _waveformAutoGain(samples);
      final panSkew =
          ((meterFrame.peakR + meterFrame.rmsR) -
                  (meterFrame.peakL + meterFrame.rmsL))
              .clamp(-1.0, 1.0)
              .toDouble();
      final spread = (0.34 + (level * 0.42) + (panSkew.abs() * 0.20)).clamp(
        0.26,
        0.84,
      );
      final radiusX = drawRect.width * 0.45;
      final radiusY = drawRect.height * 0.46;
      var moved = false;
      for (int i = 0; i < points; i++) {
        final sampleIndex = math.min(samples.length - 1, i * step);
        final prevIndex = math.max(0, sampleIndex - step);
        final sample = (samples[sampleIndex] * gain)
            .clamp(-1.0, 1.0)
            .toDouble();
        final prev = (samples[prevIndex] * gain).clamp(-1.0, 1.0).toDouble();
        final delta = ((sample - prev) * 2.2).clamp(-1.0, 1.0).toDouble();
        final shimmer = math.sin((i / points) * math.pi * 2.0) * 0.06;
        final left =
            (sample * (1.0 - (panSkew * 0.28))) + ((delta + shimmer) * spread);
        final right =
            (sample * (1.0 + (panSkew * 0.28))) - ((delta - shimmer) * spread);
        final mid = ((left + right) * 0.5).clamp(-1.0, 1.0).toDouble();
        final side = ((left - right) * 0.5).clamp(-1.0, 1.0).toDouble();
        final x = center.dx + (side * radiusX);
        final y = center.dy - (mid * radiusY);
        if (!moved) {
          path.moveTo(x, y);
          moved = true;
        } else {
          path.lineTo(x, y);
        }
      }
    }

    const accent = Color(0xFF62D8FF);
    final glowPaint = Paint()
      ..color = accent.withValues(alpha: 0.22 + (0.12 * level))
      ..style = PaintingStyle.stroke
      ..strokeWidth = 7.0
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 5);
    canvas.drawPath(path, glowPaint);

    final tracePaint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: <Color>[
          accent.withValues(alpha: 0.72),
          Colors.white.withValues(alpha: 0.90),
          const Color(0xFF9EEBFF).withValues(alpha: 0.76),
        ],
      ).createShader(drawRect)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.35
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    canvas.drawPath(path, tracePaint);
  }

  void _paintWaveform(Canvas canvas, Rect drawRect) {
    final centerY = drawRect.center.dy;
    final samples = waveformSamples;
    final path = Path();
    final fillPath = Path();
    final points = math.min(
      math.max(96, drawRect.width.floor()),
      samples.length,
    );
    if (points < 8) {
      canvas.drawLine(
        Offset(drawRect.left, centerY),
        Offset(drawRect.right, centerY),
        Paint()
          ..color = const Color(0xFF62D8FF).withValues(alpha: 0.34)
          ..strokeWidth = 1.2
          ..strokeCap = StrokeCap.round,
      );
      return;
    }

    final gain = _waveformAutoGain(samples);
    final step = math.max(1, (samples.length / points).floor());
    var moved = false;
    for (int i = 0; i < points; i++) {
      final sampleIndex = math.min(samples.length - 1, i * step);
      final sample = (samples[sampleIndex] * gain).clamp(-1.0, 1.0).toDouble();
      final t = points <= 1 ? 0.0 : i / (points - 1);
      final x = drawRect.left + (drawRect.width * t);
      final y = centerY - (sample * drawRect.height * 0.43);
      if (!moved) {
        path.moveTo(x, y);
        fillPath.moveTo(x, centerY);
        fillPath.lineTo(x, y);
        moved = true;
      } else {
        path.lineTo(x, y);
        fillPath.lineTo(x, y);
      }
    }
    fillPath
      ..lineTo(drawRect.right, centerY)
      ..close();

    const accent = Color(0xFF62D8FF);
    canvas.drawLine(
      Offset(drawRect.left, centerY),
      Offset(drawRect.right, centerY),
      Paint()
        ..color = Colors.white.withValues(alpha: 0.07)
        ..strokeWidth = 1,
    );
    canvas.drawPath(
      fillPath,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            accent.withValues(alpha: 0.18 + (level * 0.10)),
            accent.withValues(alpha: 0.03),
            Colors.transparent,
          ],
        ).createShader(drawRect),
    );
    canvas.drawPath(
      path,
      Paint()
        ..color = accent.withValues(alpha: 0.24)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 5
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4),
    );
    canvas.drawPath(
      path,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: <Color>[
            accent.withValues(alpha: 0.78),
            Colors.white.withValues(alpha: 0.90),
            accent.withValues(alpha: 0.78),
          ],
        ).createShader(drawRect)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.45
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );
  }

  @override
  bool shouldRepaint(covariant _TopBarMasterVisualizerPainter oldDelegate) {
    late final List<double> oldWaveformSamples;
    late final List<double> oldSpectrumDb;
    try {
      oldWaveformSamples = oldDelegate.waveformSamples;
      oldSpectrumDb = oldDelegate.spectrumDb;
    } catch (_) {
      return true;
    }
    return !listEquals(oldWaveformSamples, waveformSamples) ||
        !listEquals(oldSpectrumDb, spectrumDb) ||
        oldDelegate.analyzerSampleRate != analyzerSampleRate ||
        oldDelegate.level != level ||
        oldDelegate.meterFrame != meterFrame ||
        oldDelegate.clipped != clipped ||
        oldDelegate.mode != mode;
  }
}

class _TopBarSpectrumAnalyzer {
  static const double _minDb = -90.0;
  static const double _maxDb = 0.0;
  static const double _minHz = 30.0;
  static const double _maxHz = 18000.0;
  static const List<double> bandMarkerHz = <double>[
    80.0,
    300.0,
    1200.0,
    5000.0,
    12000.0,
  ];
  static final Map<int, FFT> _fftCache = <int, FFT>{};

  static FFT _fftForSize(int size) =>
      _fftCache.putIfAbsent(size, () => FFT(size));

  static int _nextPowerOfTwo(int v) {
    var n = 1;
    while (n < v) {
      n <<= 1;
    }
    return n;
  }

  static double _log10(num x) => math.log(x) / math.ln10;

  static List<double> computeSpectrumDb(List<double> samples) {
    if (samples.length < 64) return const <double>[];

    var fftSize = _nextPowerOfTwo(samples.length);
    fftSize = fftSize.clamp(256, 2048);

    final input = List<double>.filled(fftSize, 0.0, growable: false);
    final copyLen = math.min(fftSize, samples.length);
    final readOffset = samples.length - copyLen;
    for (int i = 0; i < copyLen; i++) {
      final window =
          0.5 - 0.5 * math.cos((2.0 * math.pi * i) / (copyLen - 1).toDouble());
      input[i] = samples[readOffset + i] * window;
    }

    final fft = _fftForSize(fftSize);
    final freqDomain = fft.realFft(input);
    if (freqDomain.length <= 1) return const <double>[];

    final out = List<double>.filled(freqDomain.length, _minDb, growable: false);
    for (int i = 1; i < freqDomain.length; i++) {
      final c = freqDomain[i];
      final mag = math.sqrt(c.x * c.x + c.y * c.y) / (fftSize * 0.5);
      out[i] = (20.0 * _log10(mag + 1.0e-12)).clamp(_minDb, 6.0);
    }

    for (int i = 1; i < out.length - 1; i++) {
      out[i] = ((out[i - 1] * 0.2) + (out[i] * 0.6) + (out[i + 1] * 0.2)).clamp(
        _minDb,
        6.0,
      );
    }

    return out;
  }

  static List<double> smoothSpectrum({
    required List<double> current,
    required List<double> next,
  }) {
    if (next.isEmpty) {
      if (current.isEmpty) return const <double>[];
      return current
          .map((value) => math.max(_minDb, (value * 0.82) + (_minDb * 0.18)))
          .toList(growable: false);
    }
    if (current.isEmpty || current.length != next.length) {
      return List<double>.from(next, growable: false);
    }
    final out = List<double>.filled(next.length, _minDb, growable: false);
    for (int i = 0; i < next.length; i++) {
      final rise = next[i] > current[i];
      final alpha = rise ? 0.42 : 0.18;
      out[i] = current[i] + ((next[i] - current[i]) * alpha);
    }
    return out;
  }

  static double normalizedToFrequency(double t, double sampleRate) {
    final maxHz = _displayMaxHz(sampleRate);
    final minLog = math.log(_minHz);
    final maxLog = math.log(maxHz);
    return math.exp(minLog + ((maxLog - minLog) * t));
  }

  static double frequencyToX({
    required double hz,
    required Rect rect,
    required double sampleRate,
  }) {
    final maxHz = _displayMaxHz(sampleRate);
    final clampedHz = hz.clamp(_minHz, maxHz);
    final minLog = math.log(_minHz);
    final maxLog = math.log(maxHz);
    final t = (math.log(clampedHz) - minLog) / (maxLog - minLog);
    return rect.left + (rect.width * t.clamp(0.0, 1.0));
  }

  static double sampleSpectrumDbAtHz({
    required List<double> spectrumDb,
    required double hz,
    required double sampleRate,
  }) {
    if (spectrumDb.length < 2 || hz <= 0.0 || sampleRate <= 1000.0) {
      return _minDb;
    }
    final fftSize = (spectrumDb.length - 1) * 2;
    final nyquist = sampleRate * 0.5;
    final binHz = fftSize > 0 ? sampleRate / fftSize : 0.0;
    if (binHz <= 0.0 || hz > nyquist) return _minDb;
    final maxUsableIdx = math.max(1, spectrumDb.length - 4);
    final idx = (hz / binHz).clamp(1.0, maxUsableIdx.toDouble()).toDouble();
    if (idx <= 1.0) return spectrumDb[1];

    final radius = hz >= 8000.0
        ? 5
        : hz >= 4000.0
        ? 3
        : 2;
    final center = idx.round().clamp(1, maxUsableIdx);
    final start = math.max(1, center - radius);
    final end = math.min(maxUsableIdx, center + radius);
    var magSum = 0.0;
    var weightSum = 0.0;
    for (int i = start; i <= end; i++) {
      final distance = (i - idx).abs();
      final weight = math.max(0.15, 1.0 - (distance / (radius + 1.0)));
      final db = spectrumDb[i].clamp(_minDb, 6.0).toDouble();
      magSum += math.pow(10.0, db / 20.0) * weight;
      weightSum += weight;
    }
    if (weightSum <= 0.0 || magSum <= 0.0) return _minDb;
    return (20.0 * _log10(magSum / weightSum)).clamp(_minDb, 6.0).toDouble();
  }

  static double _displayMaxHz(double sampleRate) {
    final nyquist = sampleRate > 1000.0 ? sampleRate * 0.5 : 22050.0;
    return math.min(_maxHz, math.max(12000.0, nyquist * 0.82)).toDouble();
  }

  static double dbToY(double db, Rect rect) {
    final normalized = ((db.clamp(_minDb, _maxDb) - _minDb) / (_maxDb - _minDb))
        .clamp(0.0, 1.0);
    final eased = math.pow(normalized, 0.78).toDouble();
    return rect.bottom - (rect.height * eased);
  }

  static double dbToUnit(double db) {
    return ((db.clamp(_minDb, _maxDb) - _minDb) / (_maxDb - _minDb)).clamp(
      0.0,
      1.0,
    );
  }
}

class TrackGainStagingDbMeter extends StatelessWidget {
  final MeterFrame frame;
  final bool showClipIndicator;

  const TrackGainStagingDbMeter({
    super.key,
    required this.frame,
    this.showClipIndicator = true,
  });

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final width = constraints.maxWidth.isFinite
            ? constraints.maxWidth
            : 1.0;
        final height = constraints.maxHeight.isFinite
            ? constraints.maxHeight
            : 20.0;
        return CustomPaint(
          size: Size(width, height),
          painter: _TrackGainStagingDbMeterPainter(
            frame,
            showClipIndicator: showClipIndicator,
          ),
        );
      },
    );
  }
}

class _TrackGainStagingDbMeterPainter extends CustomPainter {
  final MeterFrame f;
  final bool showClipIndicator;
  _TrackGainStagingDbMeterPainter(this.f, {required this.showClipIndicator});

  @override
  void paint(Canvas c, Size s) {
    const pad = 2.0;
    const laneGap = 2.0;
    const labelStripH = 8.0;

    final bg = Paint()..color = const Color(0xFF353E4A);
    final border = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1
      ..color = Colors.white.withValues(alpha: 0.12);

    final meterRect = Offset.zero & s;
    c.drawRect(meterRect, bg);
    c.drawRect(meterRect, border);

    final innerWidth = math.max(0.0, s.width - (pad * 2));
    final meterBottomY = math.max(pad, s.height - pad - labelStripH);
    final innerHeight = math.max(0.0, meterBottomY - pad);
    final laneHeight = math.max(0.0, (innerHeight - laneGap) / 2);

    final laneBgPaint = Paint()
      ..color = const Color.fromRGBO(244, 244, 244, 0.14);
    final tickPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.08)
      ..strokeWidth = 1;
    final peakPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.95)
      ..strokeWidth = 1.2;
    final clipPaint = Paint()..color = const Color(0xFFFF6464);

    final dbTicks = [-48.0, -36.0, -24.0, -15.0, -10.0, -6.0, -3.0, 0.0];
    for (final db in dbTicks) {
      final x = pad + (DbfsMeterVisuals.dbfsToUnit(db) * innerWidth);
      c.drawLine(Offset(x, pad), Offset(x, meterBottomY), tickPaint);
    }

    void drawLane({
      required double top,
      required double rms,
      required double peak,
    }) {
      final laneRect = Rect.fromLTWH(pad, top, innerWidth, laneHeight);
      c.drawRect(laneRect, laneBgPaint);

      final rmsUnit = DbfsMeterVisuals.ampToUnit(rms);
      final peakUnit = DbfsMeterVisuals.ampToUnit(peak);
      final rmsWidth = innerWidth * rmsUnit;
      final peakWidth = innerWidth * peakUnit;

      if (rmsWidth > 0.0) {
        final rmsRect = Rect.fromLTWH(pad, top, rmsWidth, laneHeight);
        c.drawRect(
          rmsRect,
          Paint()
            ..shader = DbfsMeterVisuals.horizontalGradient(
              opacity: 0.95,
            ).createShader(laneRect),
        );
      }

      if (peakWidth > rmsWidth) {
        final transientRect = Rect.fromLTWH(
          pad + rmsWidth,
          top,
          peakWidth - rmsWidth,
          laneHeight,
        );
        c.drawRect(
          transientRect,
          Paint()
            ..shader = DbfsMeterVisuals.horizontalGradient(
              opacity: 0.34,
            ).createShader(laneRect),
        );
      }

      if (peakWidth > 0.5) {
        final peakX = (pad + peakWidth).clamp(pad, pad + innerWidth).toDouble();
        c.drawLine(
          Offset(peakX, top),
          Offset(peakX, top + laneHeight),
          peakPaint,
        );
      }
    }

    drawLane(top: pad, rms: f.rmsL, peak: f.peakL);
    drawLane(top: pad + laneHeight + laneGap, rms: f.rmsR, peak: f.peakR);

    final labelTicks = [-48.0, -30.0, -15.0, -6.0, 0.0];
    for (final db in labelTicks) {
      final x = pad + (innerWidth * DbfsMeterVisuals.dbfsToUnit(db));
      final text = db.toStringAsFixed(0);
      final tp = TextPainter(
        text: TextSpan(
          text: text,
          style: TextStyle(
            color: Colors.white.withValues(alpha: 0.42),
            fontSize: 6.6,
            fontWeight: FontWeight.w500,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      final drawX = (x - tp.width / 2).clamp(pad, s.width - pad - tp.width);
      tp.paint(c, Offset(drawX, meterBottomY + 0.5));
    }

    if (showClipIndicator && f.clip) {
      c.drawCircle(Offset(s.width - 5, 5), 2.1, clipPaint);
    }
  }

  @override
  bool shouldRepaint(covariant _TrackGainStagingDbMeterPainter oldDelegate) {
    return oldDelegate.f != f ||
        oldDelegate.showClipIndicator != showClipIndicator;
  }
}

class _TabletRightPanelEdgeHandleTabPainter extends CustomPainter {
  const _TabletRightPanelEdgeHandleTabPainter({required this.active});

  final bool active;

  Path _tabPath(Size size) {
    final w = size.width;
    final h = size.height;
    final right = w - 0.7;
    final top = 2.5;
    final bottom = h - 2.5;
    const left = 1.6;

    return Path()
      ..moveTo(right, top)
      ..lineTo(right, bottom)
      ..lineTo(left + 10.0, bottom - 7.0)
      ..quadraticBezierTo(left + 3.0, bottom - 11.5, left + 2.2, bottom - 20.0)
      ..lineTo(left + 2.2, top + 20.0)
      ..quadraticBezierTo(left + 3.0, top + 11.5, left + 10.0, top + 7.0)
      ..close();
  }

  @override
  void paint(Canvas canvas, Size size) {
    final path = _tabPath(size);
    canvas.drawShadow(
      path,
      Colors.black.withValues(alpha: active ? 0.30 : 0.20),
      active ? 5.0 : 3.0,
      true,
    );

    final fillPaint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.centerLeft,
        end: Alignment.centerRight,
        colors: active
            ? const <Color>[
                Color(0xFF59626A),
                Color(0xFF53606B),
                Color(0xFF485865),
              ]
            : const <Color>[
                Color(0xFF515E68),
                Color(0xFF4A5864),
                Color(0xFF43525E),
              ],
      ).createShader(Offset.zero & size);
    canvas.drawPath(path, fillPaint);

    if (active) {
      canvas.drawPath(
        path,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 4.0
          ..color = const Color(0xFFFFA83D).withValues(alpha: 0.18)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 5),
      );
    }

    final edgePaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = active ? 1.15 : 0.8
      ..color = active
          ? const Color(0xFFFFB45B).withValues(alpha: 0.58)
          : Colors.white.withValues(alpha: 0.16);
    canvas.drawPath(path, edgePaint);

    final innerHighlight = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.75
      ..color = Colors.white.withValues(alpha: active ? 0.18 : 0.11);
    final insetPath = Path()
      ..moveTo(size.width - 3.4, 5.0)
      ..lineTo(size.width - 3.4, size.height - 5.0);
    canvas.drawPath(insetPath, innerHighlight);
  }

  @override
  bool shouldRepaint(
    covariant _TabletRightPanelEdgeHandleTabPainter oldDelegate,
  ) {
    return oldDelegate.active != active;
  }
}

class _TabletRightPanelEdgeHandleMarkPainter extends CustomPainter {
  const _TabletRightPanelEdgeHandleMarkPainter({required this.active});

  final bool active;

  @override
  void paint(Canvas canvas, Size size) {
    final gripColor = active
        ? const Color(0xFFFFC06A)
        : Colors.white.withValues(alpha: 0.52);
    final center = size.center(Offset.zero);
    final paint = Paint()
      ..color = gripColor
      ..strokeWidth = active ? 1.65 : 1.35
      ..strokeCap = StrokeCap.round;
    final top = center.dy - 13.0;
    final bottom = center.dy + 13.0;
    for (final dx in <double>[-4.6, 0.0, 4.6]) {
      canvas.drawLine(
        Offset(center.dx + dx, top),
        Offset(center.dx + dx, bottom),
        paint,
      );
    }
  }

  @override
  bool shouldRepaint(
    covariant _TabletRightPanelEdgeHandleMarkPainter oldDelegate,
  ) {
    return oldDelegate.active != active;
  }
}

class MiniStereoMeterHorizontal extends StatelessWidget {
  final MeterFrame frame;
  final double width;
  final double height;

  const MiniStereoMeterHorizontal({
    super.key,
    required this.frame,
    this.width = 120,
    this.height = 18,
  });

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: Size(width, height),
      painter: _MiniStereoMeterHorizontalPainter(frame),
    );
  }
}

class _MiniStereoMeterHorizontalPainter extends CustomPainter {
  final MeterFrame f;
  _MiniStereoMeterHorizontalPainter(this.f);

  @override
  void paint(Canvas c, Size s) {
    // ===== Background slot =====
    final bg = Paint()
      ..color = const Color(0xFF1A2230); // richer dark blue-gray

    final border = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1
      ..color = Colors.white.withValues(alpha: 0.10);

    // NO rounding: clean rectangle
    final rect = Offset.zero & s;
    c.drawRect(rect, bg);
    c.drawRect(rect, border);

    // ===== Tick lines (scale feel) =====
    final tick = Paint()
      ..color = Colors.white.withValues(alpha: 0.06)
      ..strokeWidth = 1;

    for (final db in const [-36.0, -24.0, -15.0, -10.0, -6.0, -3.0]) {
      final x = s.width * DbfsMeterVisuals.dbfsToUnit(db);
      c.drawLine(Offset(x, 1), Offset(x, s.height - 1), tick);
    }

    // ===== Meter paints =====
    final peakPaint = Paint()
      ..color = Colors.white.withValues(alpha: 0.88)
      ..strokeWidth = 1.15;

    // Split into two lanes
    const laneGap = 1.0;
    final laneH = (s.height - laneGap) / 2.0;

    Rect laneRect(int laneIdx) {
      final top = laneIdx == 0 ? 0.0 : laneH + laneGap;
      return Rect.fromLTWH(0, top, s.width, laneH);
    }

    // ===== Left lane (Top) =====
    final topLane = laneRect(0);
    c.drawRect(topLane, Paint()..color = Colors.white.withValues(alpha: 0.04));

    final lRmsW = s.width * DbfsMeterVisuals.ampToUnit(f.rmsL);
    final lPeakW = s.width * DbfsMeterVisuals.ampToUnit(f.peakL);

    if (lRmsW > 0.0) {
      c.drawRect(
        Rect.fromLTWH(topLane.left, topLane.top, lRmsW, topLane.height),
        Paint()
          ..shader = DbfsMeterVisuals.horizontalGradient(
            opacity: 0.94,
          ).createShader(topLane),
      );
    }
    if (lPeakW > lRmsW) {
      c.drawRect(
        Rect.fromLTWH(
          topLane.left + lRmsW,
          topLane.top,
          lPeakW - lRmsW,
          topLane.height,
        ),
        Paint()
          ..shader = DbfsMeterVisuals.horizontalGradient(
            opacity: 0.34,
          ).createShader(topLane),
      );
    }
    if (lPeakW > 0.5) {
      final lPeakX = lPeakW.clamp(0.0, s.width).toDouble();
      c.drawLine(
        Offset(lPeakX, topLane.top),
        Offset(lPeakX, topLane.bottom),
        peakPaint,
      );
    }

    // ===== Right lane (Bottom) =====
    final botLane = laneRect(1);
    c.drawRect(botLane, Paint()..color = Colors.white.withValues(alpha: 0.04));

    final rRmsW = s.width * DbfsMeterVisuals.ampToUnit(f.rmsR);
    final rPeakW = s.width * DbfsMeterVisuals.ampToUnit(f.peakR);

    if (rRmsW > 0.0) {
      c.drawRect(
        Rect.fromLTWH(botLane.left, botLane.top, rRmsW, botLane.height),
        Paint()
          ..shader = DbfsMeterVisuals.horizontalGradient(
            opacity: 0.94,
          ).createShader(botLane),
      );
    }
    if (rPeakW > rRmsW) {
      c.drawRect(
        Rect.fromLTWH(
          botLane.left + rRmsW,
          botLane.top,
          rPeakW - rRmsW,
          botLane.height,
        ),
        Paint()
          ..shader = DbfsMeterVisuals.horizontalGradient(
            opacity: 0.34,
          ).createShader(botLane),
      );
    }
    if (rPeakW > 0.5) {
      final rPeakX = rPeakW.clamp(0.0, s.width).toDouble();
      c.drawLine(
        Offset(rPeakX, botLane.top),
        Offset(rPeakX, botLane.bottom),
        peakPaint,
      );
    }

    // ===== Clip indicator (optional) =====
    // if (f.clip) {
    //   final clipPaint = Paint()..color = const Color(0xFFFF4A4A);

    //   // Small square light (pro look)
    //   c.drawRect(
    //     Rect.fromLTWH(s.width - 6, 2, 4, 4),
    //     clipPaint,
    //   );
    // }
  }

  @override
  bool shouldRepaint(covariant _MiniStereoMeterHorizontalPainter old) {
    return old.f != f;
  }
}
